  const stableSourceSpecificId = String(record?.incidentId || record?.incident_id || raw?.incidentId || raw?.incident_id || record?.id || raw?.uuid || record?.key || "").trim();
  const incidentId = String(sourceReportId || existingCanonicalIncidentId || stableSourceSpecificId || (explicitCrossingReportOwnership && crossingId ? `rail-${crossingId}` : "") || record?.key || "").trim();
  const activeState = typeof getIncidentLifecycleState === "function" && explicitCrossingReportOwnership ? getIncidentLifecycleState(record) : (record?.active === false ? "inactive" : String(record?.lifecycleState || record?.status || record?.state || "active").toLowerCase());
  const clearedState = /cleared|recently_cleared|hazard_cleared|expired|inactive|removed/.test(String(activeState).toLowerCase()) || record?.expired === true || String(record?.type || record?.report_type || "").toLowerCase() === "hazard_cleared";
