function gridlyRenderEvidenceExperience(storyInput) {
  const root = document.querySelector("[data-gridly-evidence-experience]");
  const list = document.querySelector("[data-gridly-evidence-list]");
  if (!root || !list) return false;
  const model = gridlyBuildEvidenceExperienceModel(storyInput);
  list.replaceChildren();
  model.sections.forEach(function (section) {
    const item = document.createElement("section");
    item.className = "gridly-evidence-item";
    item.dataset.gridlyEvidenceCategory = section.category;
    const title = document.createElement("h4");
    title.textContent = section.title;
    const line = document.createElement("p");
    line.textContent = section.line;
    const meta = document.createElement("small");
    meta.textContent = section.meta;
    item.append(title, line, meta);
    list.appendChild(item);
  });
  const confidence = document.createElement("section");
  confidence.className = "gridly-evidence-item gridly-evidence-confidence";
  confidence.dataset.gridlyEvidenceCategory = "confidence";
  const title = document.createElement("h4");
  title.textContent = "Confidence";
  const level = document.createElement("p");
  level.textContent = model.confidence.level;
  const detail = document.createElement("small");
  detail.textContent = model.confidence.detail;
  confidence.append(title, level, detail);
  list.appendChild(confidence);
  return true;
}

function gridlyEvidenceExperienceFindTerms(model, terms) {
  const text = [model?.title, ...(model?.sections || []).flatMap((section) => [section.title, section.line, section.meta]), model?.confidence?.level, model?.confidence?.detail].filter(Boolean).join(" ");
  return terms.filter((term) => new RegExp(`\\b${term.replace(/[.*+?^${}()|[\\]\\]/g, "\\$&")}\\b`, "i").test(text));
}

