function gridlyTravelBriefCleanLine(value) {
  return gridlyEvidenceExperienceSafeText(value)
    .replace(/\b(?:DriveTexas|TxDOT|provider|connector|normalized|payload|classification|API)\b/gi, "")
    .replace(/\s{2,}/g, " ")
    .replace(/\s+([.,])/g, "$1")
    .trim();
}

function gridlyTravelBriefRecordLine(record, fallback) {
  const candidates = [record?.consumerSummary, record?.headline, record?.title, record?.summary, record?.description, record?.event, record?.type].filter(Boolean);
  const base = gridlyTravelBriefCleanLine(candidates[0] || fallback || "");
  const route = gridlyTravelBriefCleanLine(record?.routeName || record?.route || record?.road || record?.highway || "");
  const location = gridlyTravelBriefCleanLine(record?.locationName || record?.location || record?.near || record?.crossingName || record?.address || "");
  let line = base;
  if (route && line && !line.toLowerCase().includes(route.toLowerCase())) line = `${base} on ${route}`;
  if (location && line && !line.toLowerCase().includes(location.toLowerCase())) line = `${line} near ${location}`;
  return gridlyTravelBriefCleanLine(line || fallback || "");
}

function gridlyTravelBriefCommunityCondition(record = {}) {
  const text = gridlyTravelBriefCleanLine([
    record.consumerSummary,
    record.headline,
    record.title,
    record.summary,
    record.description,
    record.event,
    record.type,
    record.reportType,
    record.hazardType,
    record.category
  ].filter(Boolean).join(" ")).toLowerCase();
  if (/train|rail|crossing/.test(text) && /block|blocked|blocking|stopped|delay|delayed|waiting/.test(text)) return "crossing-delay";
  if (/flood|high water|water over|standing water/.test(text)) return "flooding";
  if (/crash|wreck|collision|accident/.test(text)) return "crash";
  if (/closure|closed/.test(text)) return "road-closure";
  if (/debris|object|obstruction|hazard/.test(text)) return "road-hazard";
  if (/construction|work zone|road work|roadwork/.test(text)) return "construction";
  return "community-report";
}

function gridlyTravelBriefCommunityLocality(record = {}) {
  const locality = [
    record.locality,
    record.town,
    record.city,
    record.placeName,
    record.awarenessArea,
    record.raw?.locality,
    record.raw?.town,
    record.raw?.city,
    record.raw?.placeName,
    record.raw?.awarenessArea
  ].map((value) => gridlyTravelBriefCleanLine(value || "")).find(Boolean) || "";
  if (!locality || /county$/i.test(locality) || /\b(?:nearby|unknown|current location)\b/i.test(locality)) return "";
  return locality.replace(/,?\s*Texas$/i, "");
}

// LP227: KBYG owns community-level presentation.  Governance has already
// selected the records passed here; this selector must not reinterpret county
// membership or borrow the incident-location formatter used by Alerts/map.
function gridlySelectKbygCommunityPresentationContext(records = [], awarenessContext = {}) {
  const cleanCommunity = (value) => {
    const label = gridlyTravelBriefCleanLine(value || "").replace(/,?\s*Texas$/i, "");
    return !label || /county$/i.test(label) || /^(?:nearby|unknown|current location|area)$/i.test(label) ? "" : label;
  };
  const selectedArea = awarenessContext?.selectedAwarenessArea || {};
  const selectedCommunity = awarenessContext?.countyWide === false && awarenessContext?.filterMode !== "county"
    ? cleanCommunity(awarenessContext?.label || awarenessContext?.localityLabel || selectedArea?.label || selectedArea?.storageValue)
    : "";
  if (selectedCommunity) return Object.freeze({ label: selectedCommunity, type: "COMMUNITY", source: "selected_canonical_community" });

  const evidenceCommunity = (Array.isArray(records) ? records : []).map((record) => cleanCommunity(
    record?.canonicalCommunity || record?.communityName || record?.locality || record?.town || record?.city || record?.placeName || record?.awarenessArea
      || record?.raw?.canonicalCommunity || record?.raw?.communityName || record?.raw?.locality || record?.raw?.town || record?.raw?.city || record?.raw?.placeName || record?.raw?.awarenessArea
  )).find(Boolean) || "";
  if (evidenceCommunity) return Object.freeze({ label: evidenceCommunity, type: "COMMUNITY", source: "governed_evidence_community" });

  const county = gridlyTravelBriefCleanLine(awarenessContext?.countyName || "");
  if (county && !/^(?:nearby|unknown|area)$/i.test(county)) return Object.freeze({ label: county, type: "COUNTY", source: "governed_county_fallback" });
  return Object.freeze({ label: "", type: "GENERIC", source: "generic_area_fallback" });
}

function gridlyFormatKbygCommunityCopy(records = [], presentationContext = {}) {
  const count = (Array.isArray(records) ? records : []).filter(Boolean).length;
  if (!count) return "No community travel conditions reported.";
  const subject = count === 1 ? "A community report is" : `${count} community reports are`;
  return presentationContext?.label ? `${subject} active in ${presentationContext.label}.` : `${subject} active nearby.`;
}

const GRIDLY_TRAVEL_BRIEF_COMMUNITY_CONDITION_COPY = Object.freeze({
  "flooding": Object.freeze({ singular: "Flooding", plural: "Flooding", mixed: "flooding" }),
  "crossing-delay": Object.freeze({ singular: "Crossing delay", plural: "Crossing delays", mixed: "crossing delays" }),
  "road-hazard": Object.freeze({ singular: "Road hazard", plural: "Road hazards", mixed: "road hazards" }),
  "road-closure": Object.freeze({ singular: "Road closure", plural: "Road closures", mixed: "road closures" }),
  "crash": Object.freeze({ singular: "Crash", plural: "Crashes", mixed: "crashes" }),
  "construction": Object.freeze({ singular: "Construction", plural: "Construction", mixed: "construction" }),
  "community-report": Object.freeze({ singular: "Community report", plural: "Community reports", mixed: "community reports" })
});

function gridlyTravelBriefCommunityConditionCopy(conditionKey) {
  return GRIDLY_TRAVEL_BRIEF_COMMUNITY_CONDITION_COPY[conditionKey] || GRIDLY_TRAVEL_BRIEF_COMMUNITY_CONDITION_COPY["community-report"];
}

function gridlyTravelBriefCommunityLine(record = {}) {
  const condition = gridlyTravelBriefCommunityCondition(record);
  const copy = gridlyTravelBriefCommunityConditionCopy(condition);
  const identity = typeof getGridlyIncidentLocationPresentation === "function" ? getGridlyIncidentLocationPresentation(record) : null;
  if (identity?.fullLabel) return `${copy.singular} at ${identity.fullLabel}.`;
  const locality = gridlyTravelBriefCommunityLocality(record);
  return gridlyTravelBriefCommunityConditionLine(condition, copy, locality);
}

function gridlyTravelBriefCommunityConditionLine(condition, copy, locality = "") {
  if (condition === "flooding") return locality ? `${copy.singular} affecting roads in ${locality}.` : "Flooding affecting nearby roads.";
  if (condition === "crossing-delay") return locality ? `${copy.plural} reported in ${locality}.` : "Crossing delays reported nearby.";
  if (condition === "road-closure") return locality ? `${copy.singular} affecting roads in ${locality}.` : "Road closure affecting nearby roads.";
  if (condition === "road-hazard") return locality ? `${copy.singular} affecting roads in ${locality}.` : "Road hazard affecting nearby roads.";
  if (condition === "crash") return locality ? `${copy.singular} affecting travel in ${locality}.` : "Crash affecting nearby travel.";
  if (condition === "construction") return locality ? `${copy.singular} affecting roads in ${locality}.` : "Construction affecting nearby roads.";
  return locality ? `Community activity affecting travel in ${locality}.` : "Community activity affecting nearby travel.";
}


function gridlyTravelBriefCommunityGroupLine(group) {
  const copy = gridlyTravelBriefCommunityConditionCopy(group.condition);
  const localities = [...new Set(group.records.map((record) => gridlyTravelBriefCommunityLocality(record)).filter(Boolean))];
  if (group.records.length === 1) return gridlyTravelBriefCommunityLine(group.records[0]);
  if (group.records.length === 2) {
    if (localities.length === 1) return gridlyTravelBriefCommunityConditionLine(group.condition, copy, localities[0]);
    return gridlyTravelBriefCommunityConditionLine(group.condition, copy);
  }
  if (localities.length === 1) return gridlyTravelBriefCommunityConditionLine(group.condition, copy, localities[0]);
  return gridlyTravelBriefCommunityConditionLine(group.condition, copy);
}

function gridlyTravelBriefCommunityLines(records = [], awarenessContext = {}) {
  const active = Array.isArray(records) ? records.filter(Boolean) : [];
  if (!active.length) return ["No community travel conditions reported."];
  const context = gridlySelectKbygCommunityPresentationContext(active, awarenessContext);
  return [gridlyFormatKbygCommunityCopy(active, context)];
}

function gridlyTravelBriefCommunityJoinedConditionLines(groups) {
  return groups.slice(0, 3).map((group) => {
    const copy = gridlyTravelBriefCommunityConditionCopy(group.condition);
    return gridlyTravelBriefCommunityConditionLine(group.condition, copy);
  }).filter(Boolean);
}

function gridlyTravelBriefRoadwayConditionLabel(line = "") {
  const text = String(line || "");
  if (/construction|work zone|road work|roadwork/i.test(text)) return "Construction";
  if (/lane|restriction/i.test(text)) return "lane closure";
  if (/closure|closed/i.test(text)) return "road closure";
  if (/crash|wreck|collision|accident/i.test(text)) return "crash";
  if (/flood|high water/i.test(text)) return "flooding";
  return "roadway condition";
}

function gridlyTravelBriefRoadwayLineRoute(record = {}, line = "") {
  const route = gridlyTravelBriefCleanLine(record?.routeName || record?.route || record?.road || record?.highway || "");
  if (route) return route;
  const match = String(line || "").match(/\bon\s+([A-Z]{1,4}[-\s]?\d+[A-Z]?|I[-\s]?\d+[A-Z]?|US[-\s]?\d+[A-Z]?|FM[-\s]?\d+[A-Z]?|SH[-\s]?\d+[A-Z]?|TX[-\s]?\d+[A-Z]?)/i);
  return match ? gridlyTravelBriefCleanLine(match[1].toUpperCase().replace(/([A-Z]+)\s+(\d)/, "$1 $2")) : "";
}

function gridlyTravelBriefConsolidateRoadwayLines(entries = []) {
  const groups = [];
  entries.forEach((entry) => {
    const route = gridlyTravelBriefRoadwayLineRoute(entry.record, entry.line);
    if (!route) {
      groups.push({ route: "", entries: [entry] });
      return;
    }
    let group = groups.find((candidate) => candidate.route && candidate.route.toLowerCase() === route.toLowerCase());
    if (!group) {
      group = { route, entries: [] };
      groups.push(group);
    }
    group.entries.push(entry);
  });

  return groups.map((group) => {
    if (!group.route || group.entries.length === 1) return group.entries[0].line;
    const conditionLabels = [...new Set(group.entries.map((entry) => gridlyTravelBriefRoadwayConditionLabel(entry.line)).filter(Boolean))];
    if (conditionLabels.length >= 2 && conditionLabels.length <= 3) {
      const last = conditionLabels.pop();
      return `${conditionLabels.join(", ")} and ${last} on ${group.route}`;
    }
    return `${group.entries.length} roadway conditions on ${group.route}`;
  });
}

function gridlyAwarenessSourceLabel(sourceKind) {
  if (sourceKind === "official-roadways") return "Official Source · DriveTexas";
  if (sourceKind === "community") return "Community reports from nearby drivers";
  if (sourceKind === "weather") return "Weather context";
  return "Gridly awareness";
}

function gridlyTravelBriefDriveTexasLines(records = [], completeness = gridlyGetAwarenessEvidenceCompleteness(), sourceEnvelope = gridlyStoryTransportationSourceStatusEnvelope()) {
  const impacted = (Array.isArray(records) ? records : [])
    .map((record) => ({ record, impact: gridlyStoryTransportationImpact(record) }))
    .filter((entry) => entry.impact);
  if (!impacted.length) {
    if (sourceEnvelope && sourceEnvelope.healthyEmpty !== true) return sourceEnvelope.consumerDisclosure ? [sourceEnvelope.consumerDisclosure] : [];
    return completeness.canStateNoOfficialRoadwayAdvisories ? ["No official roadway advisories nearby."] : [];
  }
  const lines = impacted.map(({ record, impact }) => {
    const line = gridlyTravelBriefRecordLine(record, impact?.detail || "Roadway advisory may affect travel.");
    if (/construction|work zone/i.test(line)) return { record, line: line.replace(/construction(?: activity)? may affect nearby roads\.?/i, "Construction may affect travel.") };
    if (/lane|restriction/i.test(line)) return { record, line: line.replace(/roadway restrictions may affect local travel\.?/i, "Lane closure may affect travel.") };
    return { record, line };
  }).filter((entry) => entry.line);
  const consolidated = gridlyTravelBriefConsolidateRoadwayLines(lines).slice(0, sourceEnvelope?.retained ? 1 : 2);
  if (sourceEnvelope?.retained && sourceEnvelope.consumerDisclosure) consolidated.push(sourceEnvelope.consumerDisclosure);
  return consolidated;
}

function gridlyTravelBriefWeatherLines(weather, completeness = gridlyGetAwarenessEvidenceCompleteness()) {
  const impact = gridlyStoryWeatherMeaningfulImpact(weather);
  if (!impact) return completeness.canStateNoWeatherImpact ? ["No travel-impacting weather."] : [];
  const alert = gridlyTravelBriefCleanLine(weather?.alertTitle || weather?.event || weather?.headline || weather?.title || "");
  const lines = [];
  if (alert && gridlyBriefInteractionLooksLikeWeatherAlert(alert)) lines.push(alert);
  lines.push(gridlyTravelBriefCleanLine(impact.detail || impact.situation || "Weather may affect travel."));
  return [...new Set(lines.filter(Boolean))].slice(0, 2);
}

function gridlyTravelBriefSettledFreshnessCopy(prefix, minutes) {
  const safePrefix = /checked/i.test(prefix || "") ? "Checked" : "Updated";
  if (Number.isFinite(minutes)) {
    const rounded = Math.max(0, Math.round(minutes));
    if (rounded <= 1) return `${safePrefix} just now`;
    return `${safePrefix} ${rounded} minutes ago`;
  }
  return `${safePrefix} just now`;
}

function gridlyTravelBriefFreshnessLine(records = [], driveTexasRecords = []) {
  const domFreshness = gridlyTravelBriefCleanLine(typeof gridlyBriefInteractionText === "function" ? gridlyBriefInteractionText("#lastUpdated") : "").replace(/^Reports:\s*/i, "");
  const domMinutes = domFreshness.match(/(\d+)\s*(?:m|min|minute|minutes)\s*ago/i);
  if (/updated/i.test(domFreshness) && domMinutes) return gridlyTravelBriefSettledFreshnessCopy("Updated", Number(domMinutes[1]));
  if (/updated\s+just now|just now/i.test(domFreshness) && !/checking/i.test(domFreshness)) return gridlyTravelBriefSettledFreshnessCopy(/checked/i.test(domFreshness) ? "Checked" : "Updated");
  const timestamps = records.concat(driveTexasRecords).map((record) => Date.parse(record?.updatedAt || record?.updated_at || record?.lastUpdated || record?.last_updated || record?.createdAt || record?.created_at || record?.submittedAt || record?.startTime || record?.start_time || "")).filter(Number.isFinite);
  if (timestamps.length) {
    const minutes = Math.max(0, Math.round((Date.now() - Math.max(...timestamps)) / 60000));
    return gridlyTravelBriefSettledFreshnessCopy("Updated", minutes);
  }
  return gridlyTravelBriefSettledFreshnessCopy("Checked");
}

function gridlyTravelBriefSectionHasActiveIncident(section) {
  const lines = Array.isArray(section?.lines) ? section.lines.map((line) => gridlyTravelBriefCleanLine(line)).filter(Boolean) : [];
  const text = lines.join(" ");
  if (!text || /no community travel conditions reported|no official roadway advisories nearby|no travel-impacting weather/i.test(text)) return false;
  return /active|reported|blocked|delayed|closed|closure|crash|flood|debris|hazard|construction|traffic|advisory|concern|impact/i.test(text);
}

function gridlyTravelBriefIncidentActionApplicability(model) {
  const sections = Array.isArray(model?.sections) ? model.sections : [];
  const community = sections.find((section) => section?.key === "community");
  const communityActive = gridlyTravelBriefSectionHasActiveIncident(community);
  return Object.freeze({
    confirm: communityActive,
    markCleared: communityActive
  });
}

function gridlyTravelBriefDecisionReason(story = {}, evidence = {}) {
  if (evidence.community?.count > 0 && evidence.rail?.count > 0) return "Community reports indicate a blocked or delayed crossing.";
  if (evidence.community?.count > 0) return evidence.community.count > 1 ? "Multiple community reports are active nearby." : "A community report is active nearby.";
  if (evidence.transportation) return "Official roadway information shows a nearby travel concern.";
  if (evidence.weather) return evidence.weather.detail || "Weather is affecting nearby travel.";
  return "No active concerns are reported in the available local intelligence.";
}

// LP064 is a presentation adapter only. It translates evidence already selected by
// each decision surface; it does not fetch, score, classify, or retain intelligence.
const GRIDLY_UNIFIED_EVIDENCE_ORDER = Object.freeze([
  "community", "official-roadways", "weather", "rail-crossing", "confidence", "freshness"
]);

const GRIDLY_UNIFIED_EVIDENCE_LABELS = Object.freeze({
  community: "Community",
  "official-roadways": "Official Roadways",
  weather: "Weather",
  "rail-crossing": "Rail / Crossing",
  confidence: "Confidence",
  freshness: "Freshness"
});

function gridlyUnifiedEvidenceCountLine(count, singular, plural) {
  const value = Math.max(0, Number(count || 0));
  if (value === 1) return singular;
  return plural.replace("{count}", String(value));
}

function buildGridlyUnifiedEvidencePresentation(input = {}) {
  const quiet = Boolean(input.quiet);
  const completeness = input.completeness || (typeof gridlyGetAwarenessEvidenceCompleteness === "function" ? gridlyGetAwarenessEvidenceCompleteness({ communityReportCount: input.communityCount }) : null);
  const items = [];
  const add = (category, text, strength = "supporting") => {
    const consumerText = gridlyTravelBriefCleanLine(text);
    if (!consumerText || /^(?:unknown|n\/a)$/i.test(consumerText)) return;
    items.push(Object.freeze({ category, label: GRIDLY_UNIFIED_EVIDENCE_LABELS[category], text: consumerText, strength }));
  };
  const communityCount = Math.max(0, Number(input.communityCount || 0));
  const officialCount = Math.max(0, Number(input.officialCount || 0));
  const weatherActive = Boolean(input.weatherActive);
  const railCount = Math.max(0, Number(input.railCount || 0));
  if (communityCount) add("community", "Community reports support this.", communityCount > 1 ? "strong" : "supporting");
  else if ((quiet || input.explainQuietCommunity) && completeness?.canStateCommunityQuiet) add("community", "No nearby community travel issues are being reported.", "quiet");
  if (officialCount) add("official-roadways", "Official roadway information supports this.", officialCount > 1 ? "strong" : "supporting");
  else if ((quiet || input.explainQuietOfficial) && completeness?.canStateNoOfficialRoadwayAdvisories) add("official-roadways", "No official roadway concerns are showing nearby.", "quiet");
  if (weatherActive) add("weather", "Weather conditions support this.", "supporting");
  else if ((quiet || input.explainQuietWeather) && completeness?.canStateNoWeatherImpact) add("weather", "No travel-impacting weather is showing nearby.", "quiet");
  if (railCount) add("rail-crossing", "Crossing reports support this.", railCount > 1 ? "strong" : "supporting");
  else if (quiet || input.explainQuietRail) add("rail-crossing", "No active crossing delays are being reported nearby.", "quiet");
  add("confidence", input.confidence || (quiet ? "Quiet conditions." : "Developing conditions."), quiet ? "quiet" : "supporting");
  add("freshness", input.freshness || "Checked just now.", "currentness");
  const orderedItems = GRIDLY_UNIFIED_EVIDENCE_ORDER.flatMap((category) => items.filter((item) => item.category === category));
  return Object.freeze({
    pattern: "LP064 Unified Evidence Pattern",
    title: "Why Gridly says this",
    state: quiet ? "quiet" : "active",
    items: Object.freeze(orderedItems),
    order: GRIDLY_UNIFIED_EVIDENCE_ORDER,
    presentationOnly: true
  });
}

function renderGridlyUnifiedEvidence(container, presentation, options = {}) {
  if (!container || !presentation) return false;
  let details = container.matches?.("details.gridly-unified-evidence") ? container : container.querySelector?.("details.gridly-unified-evidence");
  if (!details) {
    details = document.createElement("details");
    details.className = "gridly-unified-evidence";
    container.appendChild(details);
  }
  details.dataset.gridlyEvidenceSurface = options.surface || "decision";
  details.dataset.gridlyEvidencePattern = presentation.pattern;
  details.dataset.gridlyEvidenceState = presentation.state;
  details.replaceChildren();
  const summary = document.createElement("summary");
  summary.textContent = presentation.title;
  details.appendChild(summary);
  const list = document.createElement("dl");
  list.className = "gridly-unified-evidence-list";
  presentation.items.forEach((item) => {
    const group = document.createElement("div");
    group.className = "gridly-unified-evidence-item";
    group.dataset.gridlyEvidenceCategory = item.category;
    const term = document.createElement("dt");
    term.textContent = item.label;
    const description = document.createElement("dd");
    description.textContent = item.text;
    group.append(term, description);
    list.appendChild(group);
  });
  details.appendChild(list);
  return true;
}

function gridlyTravelBriefUnifiedEvidence({ story, records, driveTexasRecords, weather, sourceEnvelope = gridlyStoryTransportationSourceStatusEnvelope() }) {
  const railCount = records.filter((record) => /rail|train|crossing/i.test([record?.type, record?.category, record?.title, record?.description].join(" "))).length;
  const communityCount = Math.max(0, records.length - railCount);
  const weatherImpact = gridlyStoryWeatherMeaningfulImpact(weather);
  const quiet = communityCount === 0 && driveTexasRecords.length === 0 && !weatherImpact && railCount === 0 && (!sourceEnvelope || sourceEnvelope.healthyEmpty === true);
  return buildGridlyUnifiedEvidencePresentation({
    quiet, communityCount, officialCount: driveTexasRecords.length, weatherActive: Boolean(weatherImpact),
    weatherText: weatherImpact?.detail || "Weather conditions support this travel concern.", railCount,
    confidence: gridlyTravelBriefConfidenceLine(story),
    freshness: `${gridlyTravelBriefFreshnessLine(records, driveTexasRecords)}.`
  });
}

function gridlyTravelBriefConfidenceLine(story = {}) {
  const confidence = gridlyTravelBriefCleanLine(story?.confidence || "");
  if (/several recent signals/i.test(confidence)) return "Strong supporting evidence.";
  if (/some recent evidence/i.test(confidence)) return "Multiple recent signals.";
  if (/early signs/i.test(confidence)) return "Developing conditions.";
  return "Quiet conditions.";
}

function gridlyBuildTravelBriefDecisionSection({ story, records, driveTexasRecords }) {
  const evidence = story?.evidence || {};
  const interpretation = gridlyTravelBriefCleanLine(story?.recommendation || (records.length || driveTexasRecords.length ? "Check before leaving." : "Stay aware while traveling."));
  const reason = gridlyTravelBriefDecisionReason(story, evidence);
  const confidence = gridlyTravelBriefConfidenceLine(story);
  const freshness = gridlyTravelBriefFreshnessLine(records, driveTexasRecords);
  return Object.freeze({
    key: "driver-decision",
    title: "Before You Go",
    sourceLine: "",
    pattern: "LP061 Driver Decision Pattern",
    lines: Object.freeze([interpretation, reason, confidence, freshness])
  });
}

function gridlyBuildTravelBriefModel(storyInput) {
  const records = gridlyStoryActiveRecords();
  const governedKbygEvidenceIds = gridlyGetGovernedActiveAwarenessRows().map((row) => row.evidenceId);
  const driveTexasSourceEnvelope = gridlyStoryTransportationSourceStatusEnvelope();
  const driveTexasRecords = gridlyStoryTransportationConnectorRecords();
  const weather = gridlyBriefInteractionWeatherModel();
  const kbygPresentationContext = typeof getGridlyCanonicalAwarenessPresentationContext === "function" ? getGridlyCanonicalAwarenessPresentationContext() : {};
  // A caller may have built storyInput before the governed snapshot arrived.
  // Once KBYG authority is active, rebuild from that final record collection so
  // stale quiet copy cannot overwrite the expanded portrait consumer.
  const story = storyInput?.evidence && !governedKbygEvidenceIds.length ? storyInput : (typeof buildGridlyAwarenessStory === "function" ? buildGridlyAwarenessStory({ records, transportationRecords: driveTexasRecords, weather }) : null);
  return Object.freeze({
    version: "LP061",
    title: "Current Conditions",
    driverDecisionPattern: true,
    sections: Object.freeze([
      gridlyBuildTravelBriefDecisionSection({ story, records, driveTexasRecords }),
      Object.freeze({ key: "community", title: "Community", sourceLine: gridlyAwarenessSourceLabel("community"), lines: Object.freeze(gridlyTravelBriefCommunityLines(records, kbygPresentationContext)) }),
      Object.freeze({ key: "drivetexas", title: "Official Roadways", sourceLine: gridlyAwarenessSourceLabel("official-roadways"), lines: Object.freeze(gridlyTravelBriefDriveTexasLines(driveTexasRecords, gridlyGetAwarenessEvidenceCompleteness(), driveTexasSourceEnvelope)) }),
      Object.freeze({ key: "weather", title: "Weather", sourceLine: gridlyAwarenessSourceLabel("weather"), lines: Object.freeze(gridlyTravelBriefWeatherLines(weather)) })
    ]),
    unifiedEvidence: gridlyTravelBriefUnifiedEvidence({ story, records, driveTexasRecords, weather, sourceEnvelope: driveTexasSourceEnvelope }),
    officialRoadwaySourceStatus: driveTexasSourceEnvelope,
    governedKbygEvidenceIds: Object.freeze(governedKbygEvidenceIds.slice()),
    kbygPresentationContext: gridlySelectKbygCommunityPresentationContext(records, kbygPresentationContext),
    cardinality: story?.cardinality || null,
    storyConnected: Boolean(story?.evidence)
  });
}

function gridlyLp227KbygCommunityContextAcceptance(options = {}) {
  const projection = options.projection || (typeof gridlyGetGovernedConsumerProjection === "function" ? gridlyGetGovernedConsumerProjection() : null);
  const rows = Array.isArray(options.records) ? options.records.map((record) => ({ record })) : (projection?.surfaces?.kbygCommunity || []);
  const records = rows.map((row) => row?.record || row).filter(Boolean);
  const canonical = options.awarenessContext || (typeof getGridlyCanonicalAwarenessPresentationContext === "function" ? getGridlyCanonicalAwarenessPresentationContext() : {});
  const context = gridlySelectKbygCommunityPresentationContext(records, canonical);
  const kbygCommunityCopy = gridlyFormatKbygCommunityCopy(records, context);
  const incidentRecord = records[0] || {};
  const alertProjection = typeof gridlyProjectAlertIncidentLocation === "function" ? gridlyProjectAlertIncidentLocation(incidentRecord) : incidentRecord;
  const incidentSpecificLocation = String(options.incidentSpecificLocation || alertProjection?.selectedLocationValue || alertProjection?.resolvedLocation || alertProjection?.__gridlyPresentationLocationLabel || "").trim();
  const alertsIncidentLocation = String(options.alertsIncidentLocation || (typeof document !== "undefined" ? document.querySelector?.("[data-gridly-alert-location]")?.dataset?.gridlyAlertLocation : "") || incidentSpecificLocation).trim();
  const activeCounty = String(options.activeCounty || (typeof gridlyGetActiveCountyId === "function" ? gridlyGetActiveCountyId() : canonical?.countyId || "")).trim();
  const selectedArea = canonical?.selectedAwarenessArea || {};
  const selectedMembership = String(options.selectedMembership || selectedArea?.selectedMembership || selectedArea?.countyId || activeCounty).trim();
  const canonicalCommunity = context.source === "selected_canonical_community" ? context.label : String(canonical?.label || "").trim();
  const incidentSpecificLocationExcludedFromKbyg = !incidentSpecificLocation || !kbygCommunityCopy.toLowerCase().includes(incidentSpecificLocation.toLowerCase());
  const communityContextPass = Boolean(context.type === "COMMUNITY" && canonicalCommunity && context.label === canonicalCommunity && kbygCommunityCopy.includes(canonicalCommunity));
  const surfaceSeparationPass = Boolean(incidentSpecificLocationExcludedFromKbyg && (!incidentSpecificLocation || alertsIncidentLocation === incidentSpecificLocation));
  const governancePreservedPass = Boolean(!selectedMembership || !activeCounty || selectedMembership === activeCounty);
  const report = Object.freeze({
    canonicalCommunity, selectedMembership, activeCounty,
    governedKbygEvidenceCount: rows.length,
    kbygPresentationContext: context.label || "nearby",
    kbygPresentationContextType: context.type,
    kbygCommunityCopy,
    countyFallbackAvailable: Boolean(canonical?.countyName),
    incidentSpecificLocation,
    incidentSpecificLocationExcludedFromKbyg,
    alertsIncidentLocation,
    communityContextPass,
    surfaceSeparationPass,
    governancePreservedPass,
    overallPass: Boolean(communityContextPass && surfaceSeparationPass && governancePreservedPass)
  });
  if (options.log !== false && typeof console !== "undefined") {
    console.group("=== LP227 KBYG COMMUNITY CONTEXT ACCEPTANCE ===");
    Object.entries(report).forEach(([key, value]) => console.log(`${key}:`, value));
    console.groupEnd();
  }
  return report;
}

if (typeof window !== "undefined") window.gridlyLp227KbygCommunityContextAcceptance = gridlyLp227KbygCommunityContextAcceptance;

function gridlyAwarenessCardinalityLanguageAudit(options = {}) {
  const compactModel = options.compactModel || (typeof buildGridlyCommunityPulseModel === "function" ? buildGridlyCommunityPulseModel({ auditOnly: true }) : {});
  const compactDecision = options.compactDecision || buildGridlyCommunityPulseDecisionPresentation(compactModel);
  const travelModel = options.travelModel || gridlyBuildTravelBriefModel(options.story);
  const travelDecision = (travelModel?.sections || []).find((section) => section.key === "driver-decision");
  const compactIds = Array.isArray(compactModel?.activeAwareness?.governedKbygEvidenceIds)
    ? [...new Set(compactModel.activeAwareness.governedKbygEvidenceIds.filter(Boolean))]
    : [];
  const travelCardinality = options.story?.cardinality || travelModel?.cardinality || null;
  const travelIds = Array.isArray(travelCardinality?.sourceIds) ? travelCardinality.sourceIds.slice() : (travelModel?.governedKbygEvidenceIds || []).slice();
  const compactCount = compactIds.length;
  const travelCount = Number(travelCardinality?.authoritativeConditionCount ?? travelIds.length) || 0;
  const grammaticalNumber = (count) => count === 0 ? "quiet" : (count === 1 ? "singular" : "plural");
  const compactText = [compactDecision?.headline, compactDecision?.subline].filter(Boolean).join(" ");
  const travelBriefText = (travelDecision?.lines || []).filter(Boolean).join(" ");
  const compactNumber = grammaticalNumber(compactCount);
  const travelNumber = grammaticalNumber(travelCount);
  const parityApplicable = compactIds.length === travelIds.length && compactIds.every((id) => travelIds.includes(id));
  return Object.freeze({
    milestone: "LP222",
    compact: Object.freeze({ semanticScope: "governed-kbyg-community-current-conditions", authoritativeConditionCount: compactCount, sourceIds: Object.freeze(compactIds), grammaticalNumber: compactNumber, text: compactText }),
    travelBrief: Object.freeze({ semanticScope: travelCardinality?.semanticScope || "travel-brief-current-relevant-conditions", authoritativeConditionCount: travelCount, sourceIds: Object.freeze(travelIds), grammaticalNumber: travelNumber, text: travelBriefText }),
    parityApplicable,
    parity: parityApplicable ? compactNumber === travelNumber : null,
    presentationOnly: true
  });
}

function gridlyRenderTravelBrief(storyInput) {
  const list = document.querySelector("[data-gridly-travel-brief-list]");
  if (!list) return false;
  const model = gridlyBuildTravelBriefModel(storyInput);
  list.replaceChildren();
  model.sections.forEach(function (section) {
    const item = document.createElement("section");
    item.className = "gridly-travel-brief-item";
    item.dataset.gridlyTravelBriefSection = section.key;
    const title = document.createElement("h4");
    title.textContent = section.title;
    const source = document.createElement("small");
    source.className = "gridly-travel-brief-source";
    source.textContent = section.sourceLine || (section.key === "driver-decision" ? "" : gridlyAwarenessSourceLabel(section.key));
    const body = document.createElement("div");
    body.className = "gridly-travel-brief-lines";
    const lineRoles = ["interpretation", "reason", "confidence", "freshness"];
    section.lines.forEach(function (line, index) {
      const p = document.createElement("p");
      p.textContent = line;
      if (section.key === "driver-decision") p.dataset.gridlyDecisionRole = lineRoles[index] || `line-${index + 1}`;
      body.appendChild(p);
    });
    item.append(title);
    if (source.textContent) item.appendChild(source);
    item.appendChild(body);
    list.appendChild(item);
  });
  renderGridlyUnifiedEvidence(list, model.unifiedEvidence, { surface: "travel-brief" });
  return true;
}

