function gridlyBriefInteractionBuildModel() {
  const hour = new Date().getHours();
  const greeting = hour < 12 ? "Good Morning" : hour < 17 ? "Good Afternoon" : "Good Evening";
  const primary = gridlyBriefInteractionText("#gridlyV2TopStatusPrimary") || "Local awareness";
  const secondary = gridlyBriefInteractionText("#gridlyV2TopStatusSecondary") || "Monitoring nearby conditions";
  const trust = gridlyBriefInteractionText("#gridlyV2TopStatusTrust") || "Monitoring nearby conditions";
  const presentationContext = getGridlyCanonicalAwarenessPresentationContext();
  const quietBrief = (/your area is clear right now|area is clear|conditions? (?:are )?calm|area is quiet/i.test(primary)
    && /no active community reports need attention|monitoring nearby conditions|community activity is normal/i.test(`${secondary} ${trust}`))
    || (/no active community reports need attention/i.test(secondary) && !/closure|blocked|blocking|train|delay|flood|crash|wreck|warning|watch|advisory/i.test(primary));
  const briefIntelligence = !quietBrief && window.gridlyAwarenessBriefIntelligenceModel && typeof window.gridlyAwarenessBriefIntelligenceModel === "object"
    ? window.gridlyAwarenessBriefIntelligenceModel
    : null;
  const conditionSummary = briefIntelligence?.conditionSummary || null;
  const meaningfulConditions = Array.isArray(conditionSummary?.additionalConditions) ? conditionSummary.additionalConditions : [];
  const activeConditionCount = Math.max(0, Number(conditionSummary?.activeCount || meaningfulConditions.length + 1 || 0) || 0);
  const story = typeof buildGridlyAwarenessStory === "function" ? buildGridlyAwarenessStory({ primary, secondary, trust, awarenessContext: presentationContext }) : null;
  const outlook = story?.situation || (quietBrief ? "Area is quiet." : (conditionSummary?.primary || primary));
  const context = story?.confidence || (quietBrief ? "No community reports need attention." : secondary);
  const combined = (primary + " " + secondary + " " + meaningfulConditions.map((entry) => entry.text).join(" ")).toLowerCase();
  const outlookItems = [];
  if (quietBrief) {
    outlookItems.push({ icon: "👥", text: outlook });
  } else {
    outlookItems.push({ icon: gridlyBriefInteractionOutlookIcon(outlook, "📍"), text: outlook });
    if (meaningfulConditions.length === 1 && activeConditionCount <= 2) {
      outlookItems.push({ icon: gridlyBriefInteractionOutlookIcon(meaningfulConditions[0].text, "•"), text: `${meaningfulConditions[0].text}.` });
    } else if (meaningfulConditions.length >= 1 && activeConditionCount >= 3) {
      outlookItems.push({ icon: "", text: "Travel notes:" }); // V871 legacy static check: Also affecting travel:
      meaningfulConditions.slice(0, 2).forEach((entry) => outlookItems.push({ icon: "•", text: gridlyNormalizeAwarenessBriefConditionText(entry.text) }));
      outlookItems.push({ icon: "", text: "View map for the complete picture." });
    }
  }
  let travelStatus = story?.recommendation || "Local travel looks clear.";
  if (!story) {
    if (/flood|heavy rain|storm|tornado/.test(combined)) travelStatus = "Weather may slow some local travel later today.";
    else if (/west|east|north|south|construction|closure|blocked|blocking|train|delay/.test(combined)) travelStatus = resolveGridlyCommunityAwareTravelGuidance({ awarenessContext: presentationContext, combinedText: combined }).text;
    else if (/closure|blocked|blocking|train|delay/.test(combined)) travelStatus = "Allow extra time near the affected area.";
    else if (/report|activity|community/.test(combined) && !/no active/.test(combined)) travelStatus = "Allow extra time near active reports.";
  }
  const travelSupport = /looks clear|looks good|no significant|travel normally/i.test(travelStatus) ? "No major impacts expected." : "Check the map below before you go.";
  return {
    greeting,
    location: presentationContext.texasLabel,
    outlook,
    context,
    outlookItems: gridlySuppressDuplicateBriefingConditionItems(gridlySuppressStandaloneTransitionBriefItems(outlookItems), { awarenessContext: presentationContext }),
    weather: gridlyBriefInteractionWeatherModel(),
    travelStatus,
    travelSupport,
    story
  };
}

function gridlyBriefInteractionSetExpanded(expanded, options) {
  const root = document.querySelector("#gridlyPortraitV2");
  const handle = document.querySelector("[data-gridly-brief-foundation-handle]");
  const panel = document.querySelector("[data-gridly-brief-panel]");
  if (!root || !handle || !panel) return false;
  const shouldRemember = !options || options.remember !== false;
  root.dataset.gridlyBriefState = expanded ? "expanded" : "collapsed";
  document.body?.classList.toggle("gridly-brief-expanded", Boolean(expanded));
  document.body?.classList.toggle("gridly-brief-collapsed", !expanded);
  handle.setAttribute("aria-expanded", String(expanded));
  handle.querySelector(".gridly-brief-foundation-handle-icon")?.replaceChildren(document.createTextNode(expanded ? "▲" : "▼"));
  panel.hidden = false;
  panel.dataset.gridlyBriefExpanded = expanded ? "true" : "false";
  if (!expanded) window.setTimeout(function () {
    if (panel.dataset.gridlyBriefExpanded !== "true") panel.hidden = true;
  }, 310);
  if (shouldRemember) {
    try { window.localStorage?.setItem(GRIDLY_BRIEF_INTERACTION_STORAGE_KEY, expanded ? "true" : "false"); } catch (error) {}
  }
  window.requestAnimationFrame?.(gridlyPortraitSpatialOwnershipSync);
  window.setTimeout(gridlyPortraitSpatialOwnershipSync, 340);
  return true;
}

function gridlyBriefInteractionCollapseForPanel(source) {
  const handle = document.querySelector("[data-gridly-brief-foundation-handle]");
  const panel = document.querySelector("[data-gridly-brief-panel]");
  const expanded = handle?.getAttribute("aria-expanded") === "true" || panel?.dataset?.gridlyBriefExpanded === "true";
  if (!expanded) return false;
  const collapsed = gridlyBriefInteractionSetExpanded(false, { remember: true });
  if (collapsed) {
    document.body?.setAttribute("data-gridly-brief-last-auto-collapse", source || "panel-open");
  }
  return collapsed;
}

window.gridlyBriefInteractionCollapseForPanel = gridlyBriefInteractionCollapseForPanel;

function gridlyBriefInteractionRender() {
  const model = gridlyBriefInteractionBuildModel();
  const greeting = document.querySelector("#gridlyBriefGreeting");
  const location = document.querySelector("#gridlyBriefLocation");
  const weather = document.querySelector("#gridlyBriefWeather");
  const outlook = document.querySelector("#gridlyBriefOutlook");
  const context = document.querySelector("#gridlyBriefContext");
  const travelStatus = document.querySelector("#gridlyBriefTravelStatus");
  const travelSupport = document.querySelector("#gridlyBriefTravelSupport");
  if (greeting) greeting.textContent = model.greeting;
  if (location) location.textContent = model.location;
  if (weather) {
    weather.replaceChildren();
    if (model.weather) {
      weather.dataset.weatherHeroMode = model.weather.mode === "alert" ? "alert" : "conditions";
      const label = document.createElement("span");
      label.className = "gridly-brief-weather-label";
      label.textContent = "WEATHER";
      const headline = document.createElement("span");
      headline.className = model.weather.mode === "alert" ? "gridly-brief-weather-alert-title" : "gridly-brief-weather-temp";
      headline.textContent = model.weather.mode === "alert" ? "Weather Alert" : model.weather.temperature;
      weather.append(label, headline);
      if (model.weather.summary) {
        const summary = document.createElement("span");
        summary.className = "gridly-brief-weather-summary";
        summary.textContent = model.weather.summary;
        weather.appendChild(summary);
      }
    } else {
      delete weather.dataset.weatherHeroMode;
    }
    weather.hidden = !model.weather;
  }
  if (outlook) {
    outlook.replaceChildren();
    (model.outlookItems || []).forEach(function (item) {
      const row = document.createElement("span");
      row.className = "gridly-brief-outlook-row";
      const icon = document.createElement("span");
      icon.className = "gridly-brief-outlook-icon";
      icon.setAttribute("aria-hidden", "true");
      icon.textContent = item.icon;
      const text = document.createElement("span");
      text.className = "gridly-brief-outlook-text";
      text.textContent = item.text;
      row.append(icon, text);
      outlook.appendChild(row);
    });
  }
  if (context) context.textContent = model.context;
  if (travelStatus) travelStatus.textContent = model.travelStatus;
  if (travelSupport) travelSupport.textContent = model.travelSupport;
  if (typeof gridlyRenderTravelBrief === "function") gridlyRenderTravelBrief(model.story);
}

function gridlyRefreshBriefWeather() {
  gridlyBriefInteractionRender();
  return Boolean(gridlyBriefInteractionWeatherBridge());
}

window.gridlyRefreshBriefWeather = gridlyRefreshBriefWeather;
window.gridlyBriefInteractionRender = gridlyBriefInteractionRender;

function gridlyInitBriefInteraction() {
  const handle = document.querySelector("[data-gridly-brief-foundation-handle]");
  if (!handle) return;
  gridlyBriefInteractionRender();
  handle.addEventListener("click", function () {
    gridlyBriefInteractionRender();
    gridlyBriefInteractionSetExpanded(handle.getAttribute("aria-expanded") !== "true");
  });
  if (document.documentElement?.dataset?.gridlyBriefPanelCollapseBound !== "true") {
    document.documentElement.dataset.gridlyBriefPanelCollapseBound = "true";
    document.addEventListener("pointerdown", function (event) {
      const trigger = event.target?.closest?.("#gridlyPortraitV2 .gridly-v2-bottom-dock button, #gridlyPortraitV2 [data-v2-sheet]");
      if (!trigger || trigger.closest?.("[data-gridly-brief-stack]")) return;
      gridlyBriefInteractionCollapseForPanel(trigger.dataset?.v2Sheet || trigger.dataset?.action || "dock-trigger");
    }, true);
  }
  let remembered = false;
  try { remembered = window.localStorage?.getItem(GRIDLY_BRIEF_INTERACTION_STORAGE_KEY) === "true"; } catch (error) {}
  const signature = gridlyBriefInteractionMajorEventSignature();
  let lastSignature = "";
  try { lastSignature = window.localStorage?.getItem(GRIDLY_BRIEF_INTERACTION_EVENT_KEY) || ""; } catch (error) {}
  const autoExpand = Boolean(signature && signature !== lastSignature);
  gridlyBriefInteractionSetExpanded(autoExpand || remembered, { remember: !autoExpand });
  if (autoExpand) {
    try { window.localStorage?.setItem(GRIDLY_BRIEF_INTERACTION_EVENT_KEY, signature); } catch (error) {}
  }
}

if (typeof document !== "undefined") {
  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", gridlyInitBriefInteraction, { once: true });
  } else {
    gridlyInitBriefInteraction();
  }
}


function gridlyPortraitRuntimeVisible(element) {
  if (!element || !element.getBoundingClientRect) return false;
  const rect = element.getBoundingClientRect();
  const styles = window.getComputedStyle(element);
  return Boolean(rect && rect.width > 0 && rect.height > 0 && styles.display !== "none" && styles.visibility !== "hidden" && Number(styles.opacity || "1") > 0.05);
}

function gridlyPortraitFindRuntimeControlRail() {
  return Array.from(document.querySelectorAll(".gridly-v2-control-rail"))
    .find((rail) => rail.isConnected) || null;
}

function gridlyPortraitControlRailMetrics(rail) {
  if (!rail || !rail.getBoundingClientRect) {
    return { visible: false, width: 0, height: 0, display: "", visibility: "", opacity: "" };
  }
  const rect = rail.getBoundingClientRect();
  const styles = window.getComputedStyle(rail);
  const opacity = Number(styles.opacity || "1");
  return {
    visible: Boolean(rect && rect.width > 0 && rect.height > 0 && styles.display !== "none" && styles.visibility !== "hidden" && opacity > 0),
    width: rect?.width || 0,
    height: rect?.height || 0,
    display: styles.display,
    visibility: styles.visibility,
    opacity: styles.opacity
  };
}

function gridlyPortraitControlButtonVisible(controlRail, selector) {
  const button = controlRail?.querySelector?.(selector) || null;
  if (!button || !button.getBoundingClientRect) return false;
  const rect = button.getBoundingClientRect();
  const styles = window.getComputedStyle(button);
  return Boolean(rect && rect.width > 0 && rect.height > 0 && styles.display !== "none" && styles.visibility !== "hidden" && Number(styles.opacity || "1") > 0.05);
}

function gridlyPortraitControlReachable(controlRail) {
  if (!controlRail) return false;
  const controls = Array.from(controlRail.querySelectorAll('button, [role="button"]'));
  if (!controls.length) return false;
  return controls.every((control) => {
    const rect = control.getBoundingClientRect?.();
    if (!rect || rect.width <= 0 || rect.height <= 0) return false;
    const target = document.elementFromPoint?.(rect.left + rect.width / 2, rect.top + rect.height / 2);
    return Boolean(target && (target === control || control.contains(target) || controlRail.contains(target)));
  });
}

function gridlyPortraitSpatialOwnershipSync() {
  const shell = document.getElementById("gridlyPortraitV2");
  const mapFrame = document.querySelector(".map-frame");
  const rail = gridlyPortraitFindRuntimeControlRail();
  if (!shell || !rail) return false;

  rail.setAttribute("data-gridly-portrait-map-control", "true");
  rail.toggleAttribute("data-gridly-portrait-map-overlay-control", false);

  const filterStrip = document.querySelector("#gridlyPortraitV2 .gridly-v2-segments");
  const mapRect = (document.querySelector("#map") || mapFrame)?.getBoundingClientRect?.();
  const filterRect = filterStrip?.getBoundingClientRect?.();
  if (mapRect) {
    // V867's governed portrait fallback is 188px. During cold-start awareness
    // rendering the map/filter rects can briefly report a top-edge layout;
    // never let that transient measurement replace the established offset.
    const governedPortraitTop = 188;
    const top = Math.max(governedPortraitTop, Math.round(mapRect.top + 18), Math.round((filterRect?.bottom || mapRect.top) + 16));
    rail.style.setProperty("--gridly-v2-control-rail-top", `${top}px`);
    rail.style.setProperty("--gridly-v2-control-rail-right", "10px");
  }

  const metrics = gridlyPortraitControlRailMetrics(rail);
  return Boolean(metrics.visible && rail.children.length > 0 && rail.isConnected);
}

if (typeof document !== "undefined") {
  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", gridlyPortraitSpatialOwnershipSync, { once: true });
  } else {
    gridlyPortraitSpatialOwnershipSync();
  }
}
window.addEventListener?.("resize", gridlyPortraitSpatialOwnershipSync, { passive: true });
window.addEventListener?.("orientationchange", function () {
  window.setTimeout(gridlyPortraitSpatialOwnershipSync, 120);
}, { passive: true });

window.gridlyPortraitSpatialOwnershipSync = gridlyPortraitSpatialOwnershipSync;


