function gridlyGetCountyRuntimeSources(countyId = gridlyGetActiveCountyId()) {
  const normalizedCountyId = gridlyNormalizeCountyId(countyId);
  return GRIDLY_COUNTY_RUNTIME_SOURCE_REGISTRY[normalizedCountyId] || GRIDLY_COUNTY_RUNTIME_SOURCE_REGISTRY[GRIDLY_DEFAULT_COUNTY_ID];
}

function gridlyGetActiveCountyRuntimeSources() {
  return gridlyGetCountyRuntimeSources(gridlyGetActiveCountyId());
}

function gridlyCountyRuntimeSourceAvailable(sourceName, countyId = gridlyGetActiveCountyId()) {
  const sources = gridlyGetCountyRuntimeSources(countyId);
  if (!sources) return false;
  if (sourceName === "roads") {
    const manifestEntry = typeof gridlyGetRoadwayRuntimeManifestEntry === "function" ? gridlyGetRoadwayRuntimeManifestEntry(countyId) : null;
    const manifestRoadSourceAvailable = Boolean((manifestEntry?.status === "local_runtime" || manifestEntry?.status === "external_runtime") && gridlyValidateRoadwayRuntimeAssetUrl(manifestEntry?.url, { allowLocalhostHttp: true }));
    return Boolean((sources.availability?.roads === "available" && sources.roadSourceLoadable === true) || manifestRoadSourceAvailable);
  }
  return sources?.availability?.[sourceName] === "available";
}

function gridlyNormalizeCountyId(value) {
  const candidate = String(value || "").trim().toLowerCase();
  const countyConfig = GRIDLY_COUNTY_REGISTRY[candidate];
  return countyConfig && countyConfig.operational === true ? candidate : GRIDLY_DEFAULT_COUNTY_ID;
}

function gridlyIsKnownCountyId(value) {
  const candidate = String(value || "").trim().toLowerCase();
  return Object.prototype.hasOwnProperty.call(GRIDLY_COUNTY_REGISTRY, candidate);
}

function gridlyIsCountyOperational(value) {
  const candidate = String(value || "").trim().toLowerCase();
  return GRIDLY_COUNTY_REGISTRY[candidate]?.operational === true;
}

function gridlyGetCountyRuntimeStatus(value) {
  const candidate = String(value || "").trim().toLowerCase();
  const countyConfig = GRIDLY_COUNTY_REGISTRY[candidate];
  if (!countyConfig) return Object.freeze({ known: false, operational: false, stage: "unknown", productionEnabled: false, selectable: false, validationOnly: false, productionActivationBlocked: false, reauthorizationRequired: false });
  return Object.freeze({
    known: true,
    countyId: countyConfig.id,
    operational: countyConfig.operational === true,
    stage: countyConfig.stage || GRIDLY_COUNTY_STAGE_DISABLED,
    productionEnabled: countyConfig.productionEnabled === true,
    selectable: countyConfig.selectable === true,
    validationOnly: countyConfig.validationOnly === true || countyConfig.stage === GRIDLY_COUNTY_STAGE_VALIDATION_ONLY,
    productionActivationBlocked: countyConfig.productionActivationBlocked === true,
    reauthorizationRequired: countyConfig.reauthorizationRequired === true || countyConfig.productionReauthorizationRequired === true || countyConfig.activationHold?.reauthorizationRequired === true
  });
}

function gridlyIsValidationOnlyCountySelectorOption(option, status = gridlyGetCountyRuntimeStatus(option?.value)) {
  return Boolean(
    option?.dataset?.gridlyValidationOnly === "true"
    && status.known === true
    && status.validationOnly === true
    && status.selectable === true
    && status.productionEnabled === false
    && status.productionActivationBlocked === true
    && status.reauthorizationRequired === true
  );
}

function gridlyValidateCountyContainment(row, expectedCountyId = gridlyGetActiveCountyId()) {
  const expected = gridlyNormalizeCountyId(expectedCountyId);
  const rawCountyId = row?.county_id || row?.countyId;
  const candidate = rawCountyId ? String(rawCountyId).trim().toLowerCase() : (expected === GRIDLY_DEFAULT_COUNTY_ID ? GRIDLY_DEFAULT_COUNTY_ID : "");
  const candidateStatus = gridlyGetCountyRuntimeStatus(candidate);
  const allowed = candidate === expected && candidateStatus.known === true && candidateStatus.operational === true;
  return Object.freeze({
    allowed,
    expectedCountyId: expected,
    candidateCountyId: candidate,
    candidateKnown: candidateStatus.known,
    candidateOperational: candidateStatus.operational,
    crossCountyBlocked: !allowed,
    montgomeryStagedBlocked: candidate === "montgomery-tx" && candidateStatus.operational === false
  });
}

function gridlyGetActiveCountyId(preResolvedAwarenessArea) {
  if (preResolvedAwarenessArea?.countyId) return gridlyNormalizeCountyId(preResolvedAwarenessArea.countyId);
  if (typeof window !== "undefined" && window.GRIDLY_ACTIVE_COUNTY_ID) {
    return gridlyNormalizeCountyId(window.GRIDLY_ACTIVE_COUNTY_ID);
  }
  if (typeof getGridlySelectedAwarenessArea === "function") {
    try {
      if (typeof gridlyRecordSelectedAwarenessInstrumentedCallSite === "function") gridlyRecordSelectedAwarenessInstrumentedCallSite("gridlyGetActiveCountyId", "js/app.js:gridlyGetActiveCountyId");
      const selectedAwarenessArea = getGridlySelectedAwarenessArea();
      if (selectedAwarenessArea?.countyId) return gridlyNormalizeCountyId(selectedAwarenessArea.countyId);
    } catch (_error) {
      // Selected awareness state may not be initialized during early bootstrap.
    }
  }
  return GRIDLY_DEFAULT_COUNTY_ID;
}

// LP188.12 owner-approved, non-visible validation identity. Values are projected
// exclusively from the same runtime county and package registries used by Gridly.
function gridlyPublishValidationIdentity() {
  if (typeof document === "undefined") return;
  const countyId = gridlyGetActiveCountyId();
  const county = GRIDLY_COUNTY_REGISTRY[countyId];
  const fips = gridlyExtractCountyGeoid(county);
  const pkg = typeof window !== "undefined" && window.gridlyPackageRegistry?.getCommunityPackage
    ? window.gridlyPackageRegistry.getCommunityPackage(countyId)
    : null;
  const root = document.documentElement;
  if (fips) root.setAttribute("data-gridly-active-county-fips", fips);
  else root.removeAttribute("data-gridly-active-county-fips");
  if (pkg) root.setAttribute("data-gridly-package-identity", JSON.stringify({ id: pkg.id, version: pkg.version, status: pkg.status, validationState: pkg.validationState }));
  else root.removeAttribute("data-gridly-package-identity");
}

function gridlyGetActiveCountyConfig() {
  return GRIDLY_COUNTY_REGISTRY[gridlyGetActiveCountyId()] || GRIDLY_COUNTY_REGISTRY[GRIDLY_DEFAULT_COUNTY_ID];
}

function gridlyBuildCountyStorageKey(baseKey, countyId = gridlyGetActiveCountyId()) {
  const safeBaseKey = String(baseKey || "").trim();
  const safeCountyId = gridlyNormalizeCountyId(countyId);
  return safeBaseKey ? `${safeBaseKey}:${safeCountyId}` : safeCountyId;
}

function gridlyGetCountyScopedReportMetadata(countyId = gridlyGetActiveCountyId()) {
  const requestedCountyId = String(countyId || "").trim().toLowerCase();
  const countyConfig = (gridlyIsKnownCountyId(requestedCountyId) ? GRIDLY_COUNTY_REGISTRY[requestedCountyId] : null)
    || GRIDLY_COUNTY_REGISTRY[gridlyNormalizeCountyId(countyId)]
    || GRIDLY_COUNTY_REGISTRY[GRIDLY_DEFAULT_COUNTY_ID];
  return {
    county_id: countyConfig.id,
    state: countyConfig.state
  };
}

function gridlyGetAvailableCountyAwarenessBounds() {
  const legacy = typeof GRIDLY_COUNTY_AWARENESS_BOUNDS_BY_ID !== "undefined" ? GRIDLY_COUNTY_AWARENESS_BOUNDS_BY_ID : Object.freeze({});
  const authoritative = typeof window !== "undefined"
    ? window.gridlyLp0361cRuntimeCountyGeometryPackageLoader?.getCountyBoundsById?.()
    : null;
  return authoritative || legacy;
}

function gridlyCoordinateInsideCountyBounds(lat, lng, countyId = GRIDLY_DEFAULT_COUNTY_ID) {
  const numericLat = Number(lat);
  const numericLng = Number(lng);
  const awarenessBoundsById = gridlyGetAvailableCountyAwarenessBounds();
  const metadata = typeof gridlyGetCountyBoundsMetadata === "function"
    ? gridlyGetCountyBoundsMetadata(countyId)
    : { rawBounds: awarenessBoundsById[gridlyNormalizeCountyId(countyId)] || null };
  const bounds = metadata?.rawBounds || null;
  if (!Number.isFinite(numericLat) || !Number.isFinite(numericLng) || !bounds) return false;
  return numericLat >= Number(bounds.south)
    && numericLat <= Number(bounds.north)
    && numericLng >= Number(bounds.west)
    && numericLng <= Number(bounds.east);
}

function gridlyAuthoritativePointOnSegment(point, start, end) {
  const cross = (point[1] - start[1]) * (end[0] - start[0]) - (point[0] - start[0]) * (end[1] - start[1]);
  return Math.abs(cross) <= 1e-10
    && point[0] >= Math.min(start[0], end[0]) - 1e-10 && point[0] <= Math.max(start[0], end[0]) + 1e-10
    && point[1] >= Math.min(start[1], end[1]) - 1e-10 && point[1] <= Math.max(start[1], end[1]) + 1e-10;
}

function gridlyAuthoritativePointInRing(point, ring) {
  if (!Array.isArray(ring) || ring.length < 4) return "outside";
  let inside = false;
  for (let index = 0, previous = ring.length - 1; index < ring.length; previous = index, index += 1) {
    const current = ring[index], prior = ring[previous];
    if (gridlyAuthoritativePointOnSegment(point, prior, current)) return "boundary";
    if (((current[1] > point[1]) !== (prior[1] > point[1])) && point[0] < (prior[0] - current[0]) * (point[1] - current[1]) / (prior[1] - current[1]) + current[0]) inside = !inside;
  }
  return inside ? "inside" : "outside";
}

function gridlyAuthoritativePointInGeometry(lat, lng, geometry) {
  if (!geometry || !Array.isArray(geometry.coordinates)) return "outside";
  const point = [Number(lng), Number(lat)], polygons = geometry.type === "Polygon" ? [geometry.coordinates] : geometry.type === "MultiPolygon" ? geometry.coordinates : [];
  let inside = false;
  for (const polygon of polygons) {
    const outer = gridlyAuthoritativePointInRing(point, polygon[0]);
    if (outer === "boundary") return "boundary";
    if (outer !== "inside") continue;
    let excluded = false;
    for (const hole of polygon.slice(1)) {
      const position = gridlyAuthoritativePointInRing(point, hole);
      if (position === "boundary") return "boundary";
      if (position === "inside") excluded = true;
    }
    if (!excluded) inside = true;
  }
  return inside ? "inside" : "outside";
}

function gridlyResolveCountyIdForCoordinate(lat, lng) {
  const numericLat = Number(lat);
  const numericLng = Number(lng);
  if (!Number.isFinite(numericLat) || !Number.isFinite(numericLng)) {
    return Object.freeze({
      countyId: null,
      state: null,
      coordinateCountyResolutionAvailable: Object.keys(gridlyGetAvailableCountyAwarenessBounds()).length > 0,
      coordinateInsideSupportedCounty: false,
      matchedBoundsSource: null
    });
  }
  const boundsMatches = Object.values(GRIDLY_COUNTY_REGISTRY)
    .filter((config) => config?.operational === true && gridlyCoordinateInsideCountyBounds(numericLat, numericLng, config.id));
  const geometryRecords = typeof window !== "undefined" ? window.gridlyLp0361cRuntimeCountyGeometryPackageLoader?.getCandidateGeometries(boundsMatches.map((config) => config.id)) : null;
  const polygonMatches = Array.isArray(geometryRecords) ? geometryRecords.filter((record) => ["inside", "boundary"].includes(gridlyAuthoritativePointInGeometry(numericLat, numericLng, record.geometry))) : [];
  polygonMatches.sort((left, right) => String(left.countyId).localeCompare(String(right.countyId)));
  const selected = polygonMatches.length ? GRIDLY_COUNTY_REGISTRY[polygonMatches[0].countyId] : null;
  return Object.freeze({
    countyId: selected?.id || null,
    state: selected?.state || null,
    coordinateCountyResolutionAvailable: Object.keys(gridlyGetAvailableCountyAwarenessBounds()).length > 0,
    coordinateInsideSupportedCounty: Boolean(selected),
    matchedBoundsSource: selected ? (gridlyGetAvailableCountyAwarenessBounds()[selected.id]?.source || null) : null,
    authoritativeGeometryAvailable: Array.isArray(geometryRecords) && geometryRecords.length === boundsMatches.length,
    ambiguousCountyResolution: polygonMatches.length > 1,
    boundaryPolicy: "inclusive-deterministic-lowest-county-id"
  });
}

let gridlyCountyModeContextResolution = Object.freeze({
  countyResolutionSource: null,
  resolvedCountyId: null,
  persistedAwarenessCountyId: null,
  stalePersistedContextIgnored: false
});

function gridlyGetPersistedAwarenessCountyId() {
  const selected = typeof getGridlySelectedAwarenessArea === "function" ? getGridlySelectedAwarenessArea() : null;
  return selected?.countyId ? gridlyNormalizeCountyId(selected.countyId) : null;
}

// County mode owns a presentation decision, not a Home preference decision.
// Explicit county-wide identity wins; otherwise the current governed PLACE or
// local presentation coordinate is resolved through authoritative containment.
function gridlyResolveCountyModeActiveContext() {
  const presentation = gridlyActiveGeographicPresentation;
  const persistedAwarenessCountyId = gridlyGetPersistedAwarenessCountyId();
  let resolvedCountyId = null;
  let countyResolutionSource = null;
  if (presentation?.semanticLevel === "COUNTYWIDE" && presentation.explicitCountyId) {
    resolvedCountyId = gridlyNormalizeCountyId(presentation.explicitCountyId);
    countyResolutionSource = "active-countywide-identity";
  } else {
    const lat = Number(presentation?.lat);
    const lng = Number(presentation?.lng);
    if (Number.isFinite(lat) && Number.isFinite(lng)) {
      resolvedCountyId = gridlyResolveCountyIdForCoordinate(lat, lng)?.countyId || null;
      countyResolutionSource = presentation?.semanticLevel === "PLACE"
        ? "active-presentation-coordinate"
        : "current-coordinate-containment";
    }
  }
  // A map-only context is the final current-context candidate. Persisted state
  // is intentionally not a fallback when a governed presentation exists.
  if (!resolvedCountyId && !presentation) {
    const center = map?.getCenter?.();
    resolvedCountyId = center ? gridlyResolveCountyIdForCoordinate(center.lat, center.lng)?.countyId || null : null;
    if (resolvedCountyId) countyResolutionSource = "current-coordinate-containment";
  }
  if (!resolvedCountyId) {
    resolvedCountyId = gridlyGetActiveCountyId();
    countyResolutionSource = "current-active-county-fallback";
  }
  gridlyCountyModeContextResolution = Object.freeze({
    countyResolutionSource,
    resolvedCountyId,
    persistedAwarenessCountyId,
    stalePersistedContextIgnored: Boolean(persistedAwarenessCountyId && persistedAwarenessCountyId !== resolvedCountyId)
  });
  return gridlyCountyModeContextResolution;
}

function gridlyGetCoordinateScopedReportMetadata(lat, lng) {
  const resolution = gridlyResolveCountyIdForCoordinate(lat, lng);
  if (!resolution.countyId) return null;
  return gridlyGetCountyScopedReportMetadata(resolution.countyId);
}

function gridlyGetActiveSanJacintoSubmissionOverrideCountyId() {
  const activeCountyId = gridlyGetActiveCountyId();
  if (activeCountyId !== "san-jacinto-tx") return "";
  const selectedAwarenessArea = typeof getGridlySelectedAwarenessArea === "function" ? getGridlySelectedAwarenessArea() : null;
  const selectedLabel = String(selectedAwarenessArea?.label || selectedAwarenessArea?.storageValue || "").trim().toLowerCase();
  const sanJacintoActiveAreas = new Set([
    "san jacinto county",
    "coldspring",
    "shepherd",
    "point blank",
    "oakhurst"
  ]);
  return sanJacintoActiveAreas.has(selectedLabel) ? "san-jacinto-tx" : "";
}

function gridlyGetReportSubmissionCountyScopedMetadata(lat, lng) {
  const sanJacintoOverrideCountyId = gridlyGetActiveSanJacintoSubmissionOverrideCountyId();
  if (sanJacintoOverrideCountyId) return gridlyGetCountyScopedReportMetadata(sanJacintoOverrideCountyId);
  return gridlyGetCoordinateScopedReportMetadata(lat, lng);
}

function gridlyGetCountyReportingIdentity(countyId) {
  const normalized = gridlyNormalizeCountyId(countyId);
  const county = GRIDLY_COUNTY_REGISTRY[normalized];
  const countyFips = county ? gridlyExtractCountyGeoid(county) : "";
  if (!county || !/^48\d{3}$/.test(String(countyFips || ""))) return null;
  return Object.freeze({ countyId: normalized, countyFips: String(countyFips), countyName: county.name });
}

function gridlyGetReportSubmissionCommunityMetadata(countyId, lat, lng) {
  const county = GRIDLY_COUNTY_REGISTRY[gridlyNormalizeCountyId(countyId)];
  const candidates = Array.isArray(county?.consumerAwarenessAreas) ? county.consumerAwarenessAreas : [];
  const ranked = candidates.map((community) => {
    const target = gridlyPlacePresentationTargets?.[community.placeGeoid];
    const targetLat = Number(target?.lat ?? community?.focus?.lat);
    const targetLng = Number(target?.lon ?? target?.lng ?? community?.focus?.lng);
    const distance = Number.isFinite(targetLat) && Number.isFinite(targetLng) ? haversineDistance(lat, lng, targetLat, targetLng) : Infinity;
    return { community, distance };
  }).filter((candidate) => Number.isFinite(candidate.distance)).sort((left, right) => left.distance - right.distance);
  const nearest = ranked[0]?.community;
  return nearest ? { communityName: nearest.displayName || null, communityKey: nearest.placeGeoid || null, placeGeoid: nearest.placeGeoid || null } : {};
}

function gridlyGetCountyDisplayContext(record = {}, options = {}) {
  const rawCountyId = options.countyId || options.activeCountyId || record?.county_id || record?.countyId || record?.raw?.county_id || record?.raw?.countyId || record?.source?.county_id || record?.source?.countyId || gridlyGetActiveCountyId();
  const candidateCountyId = String(rawCountyId || "").trim().toLowerCase();
  const explicitCountyContextAllowed = gridlyIsKnownCountyId(candidateCountyId) && (options.allowActivationHeldCountyContext === true || Boolean(record?.county_id || record?.countyId || record?.raw?.county_id || record?.raw?.countyId || record?.source?.county_id || record?.source?.countyId));
  const countyId = gridlyIsKnownCountyId(candidateCountyId) && (gridlyIsCountyOperational(candidateCountyId) || explicitCountyContextAllowed)
    ? candidateCountyId
    : gridlyGetActiveCountyId();
  const countyConfig = GRIDLY_COUNTY_REGISTRY[countyId] || GRIDLY_COUNTY_REGISTRY[GRIDLY_DEFAULT_COUNTY_ID];
  let awarenessArea = options.awarenessArea || options.selectedAwarenessArea || null;
  if (!awarenessArea && typeof getGridlySelectedAwarenessArea === "function") {
    awarenessArea = getGridlySelectedAwarenessArea();
  }
  const awarenessCountyId = awarenessArea?.countyId ? gridlyNormalizeCountyId(awarenessArea.countyId) : "";
  const awarenessLabel = awarenessArea && (!awarenessCountyId || awarenessCountyId === countyId)
    ? String(awarenessArea.label || awarenessArea.storageValue || "").trim()
    : "";
  const usableAwarenessLabel = awarenessLabel && !/^other$/i.test(awarenessLabel) ? awarenessLabel : "";
  return {
    countyId,
    countyName: countyConfig?.name || LOCATION_DEFAULTS?.county || "this county",
    defaultCity: countyConfig?.defaultCity || "",
    awarenessLabel: usableAwarenessLabel,
    fallbackAreaLabel: usableAwarenessLabel || countyConfig?.defaultCity || countyConfig?.name || "this area"
  };
}

function gridlyResolveCountyAwareFallbackLocation(record = {}, options = {}) {
  const context = gridlyGetCountyDisplayContext(record, options);
  return context.fallbackAreaLabel || "this area";
}


function gridlyClassifyRoadEvaluationContextBuildCaller(callerName = "unknown") {
  const name = String(callerName || "unknown");
  if (name === "buildGridlyRoadEvaluationOperationContext") return "operation_scoped_builds";
  if (name === "collectNearbyRoadCandidates") return "candidate_validation_fallback_builds";
  if (name === "gridlyIsInvalidCountyAwareRoadLabel") return "invalid_label_fallback_builds";
  if (name === "gridlyDirectionalRoadNameFromFeature" || name === "gridlyBuildLocalDirectionalRoadCandidates") return "directional_feature_fallback_builds";
  if (name === "resolveNearbyRoadPair" || name === "resolveNearestRoadName" || name === "resolveNearbyKnownLocation") return "nearest_road_fallback_builds";
  return "explicit_legacy_fallback_builds";
}

function gridlyRecordRoadEvaluationContextBuild(options = {}) {
  if (typeof gridlySelectedAwarenessAreaResolutionCache === "undefined") return;
  const cache = gridlySelectedAwarenessAreaResolutionCache;
  cache.roadEvaluationContextBuildCount = Number(cache.roadEvaluationContextBuildCount || 0) + 1;
  const buildNumber = Number(cache.roadEvaluationContextBuildCount || 0);
  let caller = { name: "unknown", source: "unavailable" };
  try {
    const stackLines = String(new Error().stack || "").split("\n").map((line) => line.trim()).filter(Boolean);
    const directFrame = stackLines.find((line) => !line.includes("gridlyRecordRoadEvaluationContextBuild") && !line.includes("buildGridlyRoadEvaluationContext") && !line.includes("Error"));
    caller = gridlyNormalizeLp016SelectedAreaCallerFrame(directFrame || "");
  } catch (_error) {}
  const callerName = caller.name || "unknown";
  const callSite = `${callerName} @ ${caller.source || "unavailable"}`;
  const bucket = gridlyClassifyRoadEvaluationContextBuildCaller(callerName);
  cache.roadContextBuildsByCaller[callerName] = Number(cache.roadContextBuildsByCaller[callerName] || 0) + 1;
  cache.roadContextBuildsByCallSite[callSite] = Number(cache.roadContextBuildsByCallSite[callSite] || 0) + 1;
  cache.roadContextBuildsByCaller[bucket] = Number(cache.roadContextBuildsByCaller[bucket] || 0) + 1;
  const isOperationScoped = bucket === "operation_scoped_builds" || options.operationScoped === true;
  if (!isOperationScoped) {
    cache.roadEvaluationFallbackContextBuildCount = Number(cache.roadEvaluationFallbackContextBuildCount || 0) + 1;
    const isExpectedLegacyFallback = options.expectedLegacyFallback === true;
    if (!isExpectedLegacyFallback) {
      cache.roadEvaluationUnexpectedFallbackCount = Number(cache.roadEvaluationUnexpectedFallbackCount || 0) + 1;
      cache.roadEvaluationUnexpectedFallbackCallSites[callSite] = Number(cache.roadEvaluationUnexpectedFallbackCallSites[callSite] || 0) + 1;
      if (callerName === "gridlyIsInvalidCountyAwareRoadLabel") cache.invalidRoadLabelUnexpectedRebuildCount = Number(cache.invalidRoadLabelUnexpectedRebuildCount || 0) + 1;
    }
  }
  const shouldSample = buildNumber <= 50 || buildNumber % 250 === 0;
  if (shouldSample && Number(cache.roadContextBuildSampleCount || 0) < 500) {
    cache.roadContextBuildSamples.push(Object.freeze({ buildNumber, caller: callerName, callSite, bucket }));
    cache.roadContextBuildSampleCount = Number(cache.roadContextBuildSampleCount || 0) + 1;
  }
  cache.samplingCoveredThroughRoadContextBuild = Math.max(Number(cache.samplingCoveredThroughRoadContextBuild || 0), buildNumber);
}

function buildGridlyRoadEvaluationContext(options = {}) {
  gridlyRecordRoadEvaluationContextBuild(options);
  const selectedAwarenessArea = options.selectedAwarenessArea !== undefined
    ? options.selectedAwarenessArea
    : (typeof getGridlySelectedAwarenessArea === "function" ? (gridlySelectedAwarenessAreaResolutionCache.selectedAreaLookupWithinRoadContextCount = Number(gridlySelectedAwarenessAreaResolutionCache.selectedAreaLookupWithinRoadContextCount || 0) + 1, getGridlySelectedAwarenessArea()) : null);
  const activeCountyId = gridlyNormalizeCountyId(options.activeCountyId || (typeof gridlyGetActiveCountyId === "function" ? (gridlySelectedAwarenessAreaResolutionCache.activeCountyLookupWithinRoadContextCount = Number(gridlySelectedAwarenessAreaResolutionCache.activeCountyLookupWithinRoadContextCount || 0) + 1, gridlyGetActiveCountyId(selectedAwarenessArea)) : ((typeof window !== "undefined" && window.GRIDLY_ACTIVE_COUNTY_ID) || selectedAwarenessArea?.countyId || GRIDLY_DEFAULT_COUNTY_ID)));
  const countyDisplayContext = options.countyDisplayContext || (typeof gridlyGetCountyDisplayContext === "function" ? (gridlySelectedAwarenessAreaResolutionCache.countyDisplayLookupWithinRoadContextCount = Number(gridlySelectedAwarenessAreaResolutionCache.countyDisplayLookupWithinRoadContextCount || 0) + 1, gridlyGetCountyDisplayContext({}, { selectedAwarenessArea, activeCountyId, countyId: activeCountyId })) : null);
  const awarenessLookupSource = options.awarenessLookupSource || selectedAwarenessArea?.label || selectedAwarenessArea?.storageValue || "";
  const normalizedAwarenessAreaLookup = options.normalizedAwarenessAreaLookup !== undefined
    ? String(options.normalizedAwarenessAreaLookup || "")
    : (typeof normalizeGridlyAwarenessAreaLookupText === "function" ? normalizeGridlyAwarenessAreaLookupText(awarenessLookupSource) : String(awarenessLookupSource || "").toLowerCase().replace(/[^a-z0-9]+/g, " ").trim());
  const activeCountyName = String(GRIDLY_COUNTY_REGISTRY[activeCountyId]?.name || "").trim().toLowerCase();
  return Object.freeze({
    activeCountyId,
    activeCountyName,
    countyDisplayContext,
    selectedAwarenessArea: selectedAwarenessArea || null,
    normalizedAwarenessAreaLookup,
    invalidCountyAwareRoadLabelPattern: /^(?:local road impact(?: into| in)? liberty|impact into liberty|impact in liberty|local road impact|local roadway|local road|unknown road|unknown roadway|this road|this area|location pending)$/i
  });
}

function gridlyGetInvalidRoadLabelCaller() {
  try {
    const stackLines = String(new Error().stack || "").split("\n").map((line) => line.trim()).filter(Boolean);
    const directFrame = stackLines.find((line) => !line.includes("gridlyGetInvalidRoadLabelCaller") && !line.includes("gridlyRecordInvalidRoadLabelContextAudit") && !line.includes("gridlyIsInvalidCountyAwareRoadLabel") && !line.includes("Error"));
    return gridlyNormalizeLp016SelectedAreaCallerFrame(directFrame || "");
  } catch (_error) {
    return { name: "unknown", source: "unavailable" };
  }
}

function gridlyIsValidRoadEvaluationContext(context = null) {
  return Boolean(
    context &&
    typeof context === "object" &&
    (
      context.invalidCountyAwareRoadLabelPattern instanceof RegExp ||
      context.activeCountyId ||
      context.activeCountyName ||
      context.countyDisplayContext ||
      context.selectedAwarenessArea !== undefined ||
      context.normalizedAwarenessAreaLookup !== undefined
    )
  );
}

function gridlyResolveSuppliedRoadEvaluationContext(candidate = null) {
  if (gridlyIsValidRoadEvaluationContext(candidate)) return { context: candidate, rejectedReason: "" };
  if (candidate && typeof candidate === "object") {
    const nested = candidate.roadEvaluationContext || candidate.evaluationContext || candidate.context || null;
    if (gridlyIsValidRoadEvaluationContext(nested)) return { context: nested, rejectedReason: "nested_context_unwrapped" };
    return { context: null, rejectedReason: "invalid_context_shape" };
  }
  if (candidate === undefined) return { context: null, rejectedReason: "missing_argument" };
  if (candidate === null) return { context: null, rejectedReason: "null_context" };
  return { context: null, rejectedReason: "non_object_context" };
}

function gridlyRecordInvalidRoadLabelContextAudit({ caller, callSite, event, rejectedReason = "" } = {}) {
  if (typeof gridlySelectedAwarenessAreaResolutionCache === "undefined") return;
  const cache = gridlySelectedAwarenessAreaResolutionCache;
  const callerName = caller?.name || "unknown";
  const callerKey = callSite || `${callerName} @ ${caller?.source || "unavailable"}`;
  if (event === "received") cache.invalidRoadLabelReceivedContextCount = Number(cache.invalidRoadLabelReceivedContextCount || 0) + 1;
  if (event === "missing") cache.invalidRoadLabelMissingContextCount = Number(cache.invalidRoadLabelMissingContextCount || 0) + 1;
  if (event === "rebuilt") cache.invalidRoadLabelRebuiltContextCount = Number(cache.invalidRoadLabelRebuiltContextCount || 0) + 1;
  if (event === "unexpected_rebuild") cache.invalidRoadLabelUnexpectedRebuildCount = Number(cache.invalidRoadLabelUnexpectedRebuildCount || 0) + 1;
  if (event === "legacy_fallback") cache.invalidRoadLabelLegacyFallbackCount = Number(cache.invalidRoadLabelLegacyFallbackCount || 0) + 1;
  if (event === "ignored") cache.invalidRoadLabelIgnoredContextCount = Number(cache.invalidRoadLabelIgnoredContextCount || 0) + 1;
  if (rejectedReason) cache.invalidRoadLabelContextRejectedReason[rejectedReason] = Number(cache.invalidRoadLabelContextRejectedReason[rejectedReason] || 0) + 1;
  cache.invalidRoadLabelCallerBreakdown[callerKey] = Number(cache.invalidRoadLabelCallerBreakdown[callerKey] || 0) + 1;
  if (event === "rebuilt" || event === "unexpected_rebuild") cache.invalidRoadLabelRebuildCallerBreakdown[callerKey] = Number(cache.invalidRoadLabelRebuildCallerBreakdown[callerKey] || 0) + 1;
  if (Number(cache.invalidRoadLabelContextSampleCount || 0) < 500) {
    cache.invalidRoadLabelContextSamples.push(Object.freeze({ event, caller: callerName, callSite: callerKey, rejectedReason }));
    cache.invalidRoadLabelContextSampleCount = Number(cache.invalidRoadLabelContextSampleCount || 0) + 1;
  }
}

function gridlyGetLegacyInvalidRoadLabelFallbackContext() {
  if (gridlyGetLegacyInvalidRoadLabelFallbackContext.cachedContext) return { context: gridlyGetLegacyInvalidRoadLabelFallbackContext.cachedContext, rebuilt: false };
  gridlyGetLegacyInvalidRoadLabelFallbackContext.cachedContext = buildGridlyRoadEvaluationContext({ expectedLegacyFallback: true });
  return { context: gridlyGetLegacyInvalidRoadLabelFallbackContext.cachedContext, rebuilt: true };
}

function gridlyIsInvalidCountyAwareRoadLabel(value = "", roadEvaluationContext = null) {
  const text = normalizeGridlyUserFacingRoadText(value).toLowerCase();
  if (!text) return true;
  const caller = gridlyGetInvalidRoadLabelCaller();
  const callSite = `${caller.name || "unknown"} @ ${caller.source || "unavailable"}`;
  // Legacy compatibility previously used: roadEvaluationContext || buildGridlyRoadEvaluationContext().
  const supplied = gridlyResolveSuppliedRoadEvaluationContext(roadEvaluationContext);
  let context = supplied.context;
  if (context) {
    gridlyRecordInvalidRoadLabelContextAudit({ caller, callSite, event: "received", rejectedReason: supplied.rejectedReason });
  } else {
    gridlyRecordInvalidRoadLabelContextAudit({ caller, callSite, event: "missing", rejectedReason: supplied.rejectedReason });
    gridlyRecordInvalidRoadLabelContextAudit({ caller, callSite, event: "legacy_fallback", rejectedReason: supplied.rejectedReason });
    const fallback = gridlyGetLegacyInvalidRoadLabelFallbackContext();
    context = fallback.context;
    if (fallback.rebuilt) gridlyRecordInvalidRoadLabelContextAudit({ caller, callSite, event: "rebuilt", rejectedReason: supplied.rejectedReason });
  }
  const activeCountyName = String(context?.activeCountyName || GRIDLY_COUNTY_REGISTRY[context?.activeCountyId || gridlyGetActiveCountyId()]?.name || "").trim().toLowerCase();
  if (activeCountyName && text === activeCountyName) return true;
  const invalidPattern = context?.invalidCountyAwareRoadLabelPattern || /^(?:local road impact(?: into| in)? liberty|impact into liberty|impact in liberty|local road impact|local roadway|local road|unknown road|unknown roadway|this road|this area|location pending)$/i;
  return invalidPattern.test(text);
}

function gridlyBuildCountyAwareLocationPhrase(prefix = "near", record = {}, options = {}) {
  const context = gridlyGetCountyDisplayContext(record, options);
  const fallback = context.fallbackAreaLabel || context.defaultCity || context.countyName || "this area";
  if (/^in$/i.test(prefix) && /county$/i.test(fallback)) return `in ${fallback}`;
  return `${prefix} ${fallback}`;
}

function gridlyIsSanJacintoRoadClosureRecord(record = {}, options = {}) {
  const context = gridlyGetCountyDisplayContext(record, options);
  if (context.countyId !== "san-jacinto-tx") return false;
  const categoryText = [
    record?.report_type, record?.reportType, record?.type, record?.category, record?.eventType,
    record?.condition, record?.title, record?.headline, record?.resolvedCategory, record?.topCategory,
    record?.raw?.report_type, record?.raw?.type, record?.raw?.category, record?.raw?.condition,
    record?.source?.report_type, record?.source?.type, record?.source?.category, record?.source?.condition
  ].map((value) => String(value || "")).join(" ");
  return /\broad[_\s-]*(?:closed|closure)\b|\broad\s+closed\b/i.test(categoryText);
}

function gridlyHasAcceptedSpecificRoadLabel(record = {}) {
  const candidates = [
    record?.roadName, record?.primaryRoad, record?.resolvedRoadName, record?.nearestRoad, record?.nearestRoadName,
    record?.routeNameDisplay, record?.routeName, record?.road, record?.route, record?.corridor, record?.highway,
    record?.raw?.roadName, record?.raw?.primaryRoad, record?.raw?.resolvedRoadName, record?.raw?.nearestRoad, record?.raw?.nearestRoadName, record?.raw?.routeName, record?.raw?.road, record?.raw?.route,
    record?.source?.roadName, record?.source?.primaryRoad, record?.source?.resolvedRoadName, record?.source?.nearestRoad, record?.source?.nearestRoadName, record?.source?.routeName, record?.source?.road, record?.source?.route
  ];
  return candidates.some((value) => {
    const text = normalizeGridlyUserFacingRoadText(value || "");
    return text && !gridlyIsInvalidCountyAwareRoadLabel(text) && !/^(?:Coldspring|San Jacinto County)$/i.test(text);
  });
}

function gridlyNormalizeSanJacintoRoadClosureFallbackText(text = "", record = {}, options = {}) {
  const displayText = normalizeGridlyUserFacingRoadText(text);
  if (!displayText) return "";
  if (!gridlyIsSanJacintoRoadClosureRecord(record, options)) return displayText;
  if (gridlyHasAcceptedSpecificRoadLabel(record)) return displayText;
  if (/^Road Closed\s+(?:near\s+Coldspring|on\s+San Jacinto County)\b/i.test(displayText)) {
    return displayText.replace(/^Road Closed\s+(?:near\s+Coldspring|on\s+San Jacinto County)\b/i, "Road Closed reported nearby");
  }
  return displayText;
}

function normalizeGridlyCountyAwareDisplayText(value = "", record = {}, options = {}) {
  let text = normalizeGridlyUserFacingRoadText(value);
  if (!text) return "";
  const context = gridlyGetCountyDisplayContext(record, options);
  if (context.countyId === GRIDLY_DEFAULT_COUNTY_ID) return text;
  const fallback = context.fallbackAreaLabel || "this area";
  text = text
    .replace(/^Road Closed Reported$/i, `Road closed near ${fallback}`)
    .replace(/^Reported\s+on\s+(.+ County)$/i, (_match, countyName) => `Reported in ${countyName}`)
    .replace(/^(.+?)\s+on\s+(.+ County)$/i, (_match, title, countyName) => `${title} ${gridlyBuildCountyAwareLocationPhrase("near", record, options) || `near ${countyName}`}`)
    .replace(/^(.+?)\s+on\s+Local Road Impact(?: Into Liberty| in Liberty)?$/i, (_match, title) => `${title} ${gridlyBuildCountyAwareLocationPhrase("near", record, options)}`)
    .replace(/^Reported\s+on\s+Local Road Impact(?: Into Liberty| in Liberty)?$/i, `Reported ${gridlyBuildCountyAwareLocationPhrase("in", record, options)}`)
    .replace(/^Reported\s+(?:near|at)\s+Local Road Impact(?: Into Liberty| in Liberty)?$/i, `Reported ${gridlyBuildCountyAwareLocationPhrase("near", record, options)}`)
    .replace(/\bLocal Road Impact Into Liberty\b/gi, fallback)
    .replace(/\bLocal Road Impact in Liberty\b/gi, fallback)
    .replace(/\bLocal Road Impact\b/gi, fallback)
    .replace(/\bUnknown Road(?:way)?\b/gi, fallback)
    .replace(/\bLocal Road(?:way)?\b/gi, fallback)
    .replace(/\bImpact Into Liberty\b/gi, fallback)
    .replace(/\bInto Liberty\b/gi, `in ${fallback}`)
    .replace(/\bLiberty County\b/gi, context.countyName)
    .replace(/\bLiberty\b/gi, fallback);
  return gridlyNormalizeSanJacintoRoadClosureFallbackText(text, record, options);
}

function gridlyExtractStructuredMetadata(record = {}) {
  const detailCandidates = [record?.detail, record?.description, record?.subtitle, record?.raw?.detail, record?.raw?.description, record?.source?.detail, record?.source?.description];
  const detail = detailCandidates.map((value) => String(value || "")).find((value) => value.includes(OTHER_HAZARD_STRUCTURED_METADATA_PREFIX)) || "";
  const markerIndex = detail.indexOf(OTHER_HAZARD_STRUCTURED_METADATA_PREFIX);
  if (markerIndex < 0) return {};
  const rawJson = detail.slice(markerIndex + OTHER_HAZARD_STRUCTURED_METADATA_PREFIX.length).trim();
  const jsonMatch = rawJson.match(/^\{[^}]*\}/);
  if (!jsonMatch) return {};
  try {
    const parsed = JSON.parse(jsonMatch[0]);
    return parsed && typeof parsed === "object" ? parsed : {};
  } catch (error) {
    return {};
  }
}

function gridlyGetReportCountyId(row, fallbackActiveCountyId = gridlyGetActiveCountyId()) {
  const structured = gridlyExtractStructuredMetadata(row);
  const rawCountyId = row?.county_id || row?.countyId || structured.county_id || structured.countyId;
  if (!rawCountyId) {
    const coordinateCountyId = gridlyResolveCountyIdForCoordinate(row?.lat ?? row?.latitude, row?.lng ?? row?.lon ?? row?.longitude)?.countyId || "";
    if (coordinateCountyId) return coordinateCountyId;
    const normalizedFallbackCountyId = gridlyNormalizeCountyId(fallbackActiveCountyId);
    return normalizedFallbackCountyId === GRIDLY_DEFAULT_COUNTY_ID ? GRIDLY_DEFAULT_COUNTY_ID : "";
  }
  const candidate = String(rawCountyId).trim().toLowerCase();
  return gridlyIsKnownCountyId(candidate) && gridlyIsCountyOperational(candidate) ? candidate : candidate;
}

function gridlyReportMatchesActiveCounty(row, activeCountyId = gridlyGetActiveCountyId()) {
  const rawCountyId = row?.county_id || row?.countyId || row?.raw?.county_id || row?.raw?.countyId;
  const normalizedReportCountyId = rawCountyId
    ? String(rawCountyId || "").trim().toLowerCase()
    : String(gridlyGetReportCountyId(row, activeCountyId) || "").trim().toLowerCase();
  if (!normalizedReportCountyId) return activeCountyId === GRIDLY_DEFAULT_COUNTY_ID;
  return normalizedReportCountyId === activeCountyId && gridlyIsKnownCountyId(normalizedReportCountyId) && gridlyIsCountyOperational(normalizedReportCountyId);
}

