const gridlyPwaInstallReadinessState = {
  beforeInstallPromptEvent: null,
  installPromptSupportReady: false,
  serviceWorkerRegistration: null,
  serviceWorkerRegistered: false,
  serviceWorkerRegistrationError: null,
  installPromptOutcome: null,
  installPromptUserChoice: null,
  installPromptLastError: null,
  userInitiatedPromptCount: 0,
  autoPromptPrevented: true,
  updateAvailable: false,
  updateNotificationShown: false,
  updatePromptDismissed: false,
  updateReloadRequested: false,
  updateReloadSuppressedForActiveSubmission: false,
  updateWaitingWorker: null,
  serviceWorkerVersion: null,
  serviceWorkerCacheName: null
};


function gridlyIsActiveSubmissionInProgress() {
  if (typeof document === "undefined") return false;
  return Boolean(document.querySelector('[data-gridly-report-submitting="true"], [aria-busy="true"][data-gridly-report-form]'));
}

function gridlyEnsurePwaUpdateNotice() {
  if (typeof document === "undefined") return null;
  let notice = document.querySelector("[data-gridly-pwa-update-notice]");
  if (notice) return notice;
  notice = document.createElement("section");
  notice.setAttribute("data-gridly-pwa-update-notice", "true");
  notice.setAttribute("role", "status");
  notice.setAttribute("aria-live", "polite");
  notice.hidden = true;
  notice.className = "gridly-pwa-update-notice";
  notice.innerHTML = '<div><strong>A new version of Gridly is available.</strong><br><span>Update now for the latest improvements.</span></div><div class="gridly-pwa-update-actions"><button type="button" data-gridly-pwa-update-later>Later</button><button type="button" data-gridly-pwa-update-now>Update Now</button></div>';
  document.body?.appendChild(notice);
  notice.querySelector("[data-gridly-pwa-update-later]")?.addEventListener("click", () => {
    gridlyPwaInstallReadinessState.updatePromptDismissed = true;
    notice.hidden = true;
  });
  notice.querySelector("[data-gridly-pwa-update-now]")?.addEventListener("click", () => gridlyApplyPwaUpdateWhenSafe());
  return notice;
}

function gridlyShowPwaUpdateAvailable(worker = null) {
  gridlyPwaInstallReadinessState.updateAvailable = true;
  gridlyPwaInstallReadinessState.updateWaitingWorker = worker || gridlyPwaInstallReadinessState.updateWaitingWorker || null;
  if (gridlyPwaInstallReadinessState.updatePromptDismissed) return;
  const notice = gridlyEnsurePwaUpdateNotice();
  if (notice) {
    notice.hidden = false;
    gridlyPwaInstallReadinessState.updateNotificationShown = true;
  }
}

function gridlyApplyPwaUpdateWhenSafe() {
  if (gridlyIsActiveSubmissionInProgress()) {
    gridlyPwaInstallReadinessState.updateReloadSuppressedForActiveSubmission = true;
    return false;
  }
  gridlyPwaInstallReadinessState.updateReloadRequested = true;
  const worker = gridlyPwaInstallReadinessState.updateWaitingWorker;
  worker?.postMessage?.({ type: "GRIDLY_SKIP_WAITING" });
  if (typeof window !== "undefined" && window.location?.reload) window.location.reload();
  return true;
}

function gridlyTrackPwaRegistrationUpdates(registration) {
  if (!registration) return;
  if (registration.waiting) gridlyShowPwaUpdateAvailable(registration.waiting);
  registration.addEventListener?.("updatefound", () => {
    const installingWorker = registration.installing;
    installingWorker?.addEventListener?.("statechange", () => {
      if (installingWorker.state === "installed" && navigator.serviceWorker?.controller) {
        gridlyShowPwaUpdateAvailable(installingWorker);
      }
    });
  });
}

function gridlyRequestServiceWorkerVersion(registration) {
  const worker = registration?.active || navigator.serviceWorker?.controller;
  if (!worker) return;
  const handleMessage = (event) => {
    if (event.data?.type !== "GRIDLY_SW_VERSION") return;
    gridlyPwaInstallReadinessState.serviceWorkerVersion = event.data.version || null;
    gridlyPwaInstallReadinessState.serviceWorkerCacheName = event.data.cacheName || null;
    navigator.serviceWorker?.removeEventListener?.("message", handleMessage);
  };
  navigator.serviceWorker?.addEventListener?.("message", handleMessage);
  worker.postMessage?.({ type: "GRIDLY_GET_SW_VERSION" });
}

function gridlyIsStandaloneMode() {
  if (typeof window === "undefined") return false;
  const navigatorStandalone = window.navigator && window.navigator.standalone === true;
  const displayModeStandalone = typeof window.matchMedia === "function"
    && window.matchMedia("(display-mode: standalone)").matches;
  return Boolean(navigatorStandalone || displayModeStandalone);
}

function gridlyIsLikelyIosSafari() {
  if (typeof window === "undefined" || typeof navigator === "undefined") return false;
  const userAgent = String(navigator.userAgent || "");
  const vendor = String(navigator.vendor || "");
  const platform = String(navigator.platform || "");
  const hasTouchMac = platform === "MacIntel" && Number(navigator.maxTouchPoints || 0) > 1;
  const isiOS = /iPad|iPhone|iPod/i.test(userAgent) || hasTouchMac;
  const isSafari = /Safari/i.test(userAgent) && /Apple/i.test(vendor) && !/CriOS|FxiOS|EdgiOS|OPiOS|DuckDuckGo/i.test(userAgent);
  return Boolean(isiOS && isSafari);
}

function gridlyGetPwaInstallUxElements() {
  if (typeof document === "undefined") return { cards: [], buttons: [], statuses: [] };
  return {
    cards: Array.from(document.querySelectorAll("[data-gridly-pwa-install-card]")),
    buttons: Array.from(document.querySelectorAll("[data-gridly-pwa-install-button]")),
    statuses: Array.from(document.querySelectorAll("[data-gridly-pwa-install-status]"))
  };
}

function gridlyGetPwaInstallUxState() {
  const pwaReadinessAvailable = typeof window !== "undefined" && typeof window.gridlyPwaReadinessAudit === "function";
  const installStateAvailable = typeof window !== "undefined" && Boolean(window.gridlyPwaInstallReadinessState);
  const standaloneDetected = gridlyIsStandaloneMode();
  const beforeInstallPromptCaptured = Boolean(gridlyPwaInstallReadinessState.beforeInstallPromptEvent);
  const iosInstructionSupported = gridlyIsLikelyIosSafari();
  const shouldShow = Boolean(pwaReadinessAvailable && installStateAvailable && !standaloneDetected && (beforeInstallPromptCaptured || iosInstructionSupported));
  const canPrompt = Boolean(shouldShow && beforeInstallPromptCaptured);
  return {
    pwaReadinessAvailable,
    installStateAvailable,
    standaloneDetected,
    beforeInstallPromptCaptured,
    iosInstructionSupported,
    shouldShow,
    canPrompt
  };
}

function gridlyRenderPwaInstallUx() {
  if (typeof document === "undefined") return;
  const state = gridlyGetPwaInstallUxState();
  const { cards, buttons, statuses } = gridlyGetPwaInstallUxElements();
  cards.forEach((card) => {
    card.hidden = !state.shouldShow && !state.standaloneDetected;
    card.dataset.gridlyPwaInstallVisible = state.shouldShow ? "true" : "false";
    card.dataset.gridlyPwaInstallMode = state.standaloneDetected ? "standalone" : (state.beforeInstallPromptCaptured ? "prompt" : (state.iosInstructionSupported ? "ios" : "unsupported"));
  });
  buttons.forEach((button) => {
    const showPromptButton = state.shouldShow && state.canPrompt;
    button.hidden = !showPromptButton;
    button.disabled = !showPromptButton;
    button.textContent = state.standaloneDetected ? "Installed" : "Install";
    button.setAttribute("aria-disabled", button.disabled ? "true" : "false");
  });
  statuses.forEach((status) => {
    if (state.standaloneDetected) {
      status.textContent = "Installed";
    } else if (state.iosInstructionSupported && !state.beforeInstallPromptCaptured) {
      status.textContent = "Tap Share, then Add to Home Screen.";
    } else if (gridlyPwaInstallReadinessState.installPromptOutcome === "dismissed") {
      status.textContent = "You can install Gridly later from this screen.";
    } else if (gridlyPwaInstallReadinessState.installPromptOutcome) {
      status.textContent = `Install prompt ${gridlyPwaInstallReadinessState.installPromptOutcome}.`;
    } else {
      status.textContent = state.canPrompt ? "Install opens only after you tap the button." : "Install is unavailable in this browser.";
    }
  });
}

async function gridlyHandlePwaInstallButtonClick(event) {
  event?.preventDefault?.();
  const state = gridlyGetPwaInstallUxState();
  if (!state.canPrompt || !gridlyPwaInstallReadinessState.beforeInstallPromptEvent) {
    gridlyRenderPwaInstallUx();
    return null;
  }
  const promptEvent = gridlyPwaInstallReadinessState.beforeInstallPromptEvent;
  gridlyPwaInstallReadinessState.userInitiatedPromptCount += 1;
  gridlyPwaInstallReadinessState.installPromptLastError = null;
  try {
    const promptResult = promptEvent.prompt();
    if (promptResult && typeof promptResult.then === "function") await promptResult;
    const choice = promptEvent.userChoice && typeof promptEvent.userChoice.then === "function" ? await promptEvent.userChoice : null;
    gridlyPwaInstallReadinessState.installPromptUserChoice = choice || null;
    gridlyPwaInstallReadinessState.installPromptOutcome = choice?.outcome || "prompted";
  } catch (error) {
    gridlyPwaInstallReadinessState.installPromptLastError = error ? String(error.message || error) : "Install prompt failed";
    gridlyPwaInstallReadinessState.installPromptOutcome = "error";
  } finally {
    gridlyPwaInstallReadinessState.beforeInstallPromptEvent = null;
    gridlyPwaInstallReadinessState.installPromptSupportReady = false;
    gridlyRenderPwaInstallUx();
  }
  return gridlyPwaInstallReadinessState.installPromptOutcome;
}

function gridlyBindPwaInstallUx(root = document) {
  if (!root?.querySelectorAll) return;
  root.querySelectorAll("[data-gridly-pwa-install-button]").forEach((button) => {
    if (button.dataset.v2Action) return;
    if (button.dataset.gridlyPwaInstallBound === "1") return;
    button.dataset.gridlyPwaInstallBound = "1";
    button.addEventListener("click", gridlyHandlePwaInstallButtonClick);
  });
  gridlyRenderPwaInstallUx();
}

function gridlyPwaInstallUxAudit() {
  const state = gridlyGetPwaInstallUxState();
  const { cards, buttons } = gridlyGetPwaInstallUxElements();
  const visible = (element) => {
    if (!element || element.hidden) return false;
    if (typeof window === "undefined" || typeof window.getComputedStyle !== "function") return true;
    const style = window.getComputedStyle(element);
    return Boolean(style.display !== "none" && style.visibility !== "hidden" && Number(style.opacity || 1) !== 0);
  };
  const installButtonVisible = buttons.some(visible);
  return {
    available: true,
    pwaReadinessAvailable: state.pwaReadinessAvailable,
    installStateAvailable: state.installStateAvailable,
    installButtonFound: buttons.length > 0,
    installButtonVisible,
    installButtonDisabled: buttons.some((button) => button.disabled || button.getAttribute("aria-disabled") === "true"),
    standaloneDetected: state.standaloneDetected,
    beforeInstallPromptCaptured: state.beforeInstallPromptCaptured,
    iosInstructionSupported: state.iosInstructionSupported,
    autoPromptPrevented: gridlyPwaInstallReadinessState.autoPromptPrevented === true,
    safeUserInitiatedPromptOnly: gridlyPwaInstallReadinessState.autoPromptPrevented === true && gridlyPwaInstallReadinessState.userInitiatedPromptCount >= 0,
    noWorkflowChanges: true,
    safeForCapacitorPhase: true,
    installCardsFound: cards.length,
    installCardVisible: cards.some(visible),
    promptOutcome: gridlyPwaInstallReadinessState.installPromptOutcome || null
  };
}

function gridlyReadMetaContent(selector) {
  if (typeof document === "undefined") return "";
  const element = document.querySelector(selector);
  return element ? String(element.getAttribute("content") || "").trim() : "";
}

function gridlyReadLinkHref(selector) {
  if (typeof document === "undefined") return "";
  const element = document.querySelector(selector);
  return element ? String(element.getAttribute("href") || "").trim() : "";
}

function gridlyIsGithubPagesCompatiblePath(path) {
  return Boolean(path) && !path.startsWith("/") && !path.startsWith("http://") && !path.startsWith("https://");
}

function gridlyGetPwaReadinessAudit() {
  const manifestHref = gridlyReadLinkHref('link[rel="manifest"]');
  const themeColor = gridlyReadMetaContent('meta[name="theme-color"]');
  const appleCapable = gridlyReadMetaContent('meta[name="apple-mobile-web-app-capable"]');
  const mobileCapable = gridlyReadMetaContent('meta[name="mobile-web-app-capable"]');
  const icon192 = gridlyReadLinkHref('link[rel="icon"][sizes="192x192"]');
  const icon512 = gridlyReadLinkHref('link[rel="icon"][sizes="512x512"]');
  const manifestDetected = Boolean(manifestHref);
  const serviceWorkerDetected = typeof navigator !== "undefined" && "serviceWorker" in navigator;
  const themeColorPresent = Boolean(themeColor);
  const appleMetaPresent = appleCapable.toLowerCase() === "yes";
  const mobileMetaPresent = mobileCapable.toLowerCase() === "yes";
  const iconSetDetected = Boolean(icon192 && icon512);
  const githubPagesCompatible = gridlyIsGithubPagesCompatiblePath(manifestHref)
    && gridlyIsGithubPagesCompatiblePath("./service-worker.js")
    && gridlyIsGithubPagesCompatiblePath("./assets/icon-192.png")
    && gridlyIsGithubPagesCompatiblePath("./assets/icon-512.png");
  const safeForCapacitorPhase = Boolean(
    manifestDetected
    && serviceWorkerDetected
    && themeColorPresent
    && appleMetaPresent
    && mobileMetaPresent
    && iconSetDetected
    && githubPagesCompatible
  );

  return {
    available: true,
    manifestDetected,
    serviceWorkerDetected,
    serviceWorkerRegistered: Boolean(gridlyPwaInstallReadinessState.serviceWorkerRegistered),
    installPromptSupportReady: Boolean(gridlyPwaInstallReadinessState.installPromptSupportReady),
    themeColorPresent,
    appleMetaPresent,
    mobileMetaPresent,
    iconSetDetected,
    standaloneSupported: typeof window !== "undefined" && typeof window.matchMedia === "function",
    githubPagesCompatible,
    safeForCapacitorPhase
  };
}

if (typeof window !== "undefined") {
  window.gridlyPwaInstallReadinessState = gridlyPwaInstallReadinessState;
  window.gridlyIsStandaloneMode = gridlyIsStandaloneMode;
  window.gridlyPwaReadinessAudit = gridlyGetPwaReadinessAudit;
  window.gridlyPwaInstallUxAudit = gridlyPwaInstallUxAudit;
  window.gridlyApplyPwaUpdateWhenSafe = gridlyApplyPwaUpdateWhenSafe;

  window.addEventListener("beforeinstallprompt", (event) => {
    event.preventDefault();
    gridlyPwaInstallReadinessState.beforeInstallPromptEvent = event;
    gridlyPwaInstallReadinessState.installPromptSupportReady = true;
    gridlyPwaInstallReadinessState.autoPromptPrevented = true;
    gridlyRenderPwaInstallUx();
  });

  window.addEventListener("appinstalled", () => {
    gridlyPwaInstallReadinessState.beforeInstallPromptEvent = null;
    gridlyPwaInstallReadinessState.installPromptSupportReady = false;
    gridlyPwaInstallReadinessState.installPromptOutcome = "installed";
    gridlyRenderPwaInstallUx();
  });

  window.addEventListener("DOMContentLoaded", () => {
    gridlyBindPwaInstallUx(document);
  });

  window.addEventListener("load", () => {
    if (!("serviceWorker" in navigator)) return;
    navigator.serviceWorker.register("./service-worker.js", { scope: "./" })
      .then((registration) => {
        gridlyPwaInstallReadinessState.serviceWorkerRegistration = registration;
        gridlyPwaInstallReadinessState.serviceWorkerRegistered = true;
        gridlyPwaInstallReadinessState.serviceWorkerRegistrationError = null;
        gridlyTrackPwaRegistrationUpdates(registration);
        gridlyRequestServiceWorkerVersion(registration);
      })
      .catch((error) => {
        gridlyPwaInstallReadinessState.serviceWorkerRegistration = null;
        gridlyPwaInstallReadinessState.serviceWorkerRegistered = false;
        gridlyPwaInstallReadinessState.serviceWorkerRegistrationError = error ? String(error.message || error) : "Service worker registration failed";
      });
  });
}

const gridlyBackgroundLoopAuditState = {
  topPanelWriteCount: 0,
  topPanelOwnerCheckCount: 0,
  portraitRefreshCount: 0,
  dailyHabitUpdateCount: 0,
  repeatedSameValueWrites: 0,
  sameValueWriteSuppressionApplied: false,
  topPanelWrites: [],
  topPanelOwnerChecks: [],
  portraitRefreshes: [],
  dailyHabitUpdates: [],
  dedupedWrites: [],
  activeIntervals: new Map(),
  activeTimeouts: new Map(),
  activeAnimationFrames: new Map(),
  nextTimerAuditId: 1
};

const GRIDLY_BACKGROUND_LOOP_CALLERS = {
  updateDailyHabitStatus: [
    "loadCrossings() after curated crossings load",
    "refreshReportHazardViews() refresh cycle"
  ],
  refreshPortraitV2LocalizedIntelligence: [
    "applyGridlyAlertLocationSync() after alert location sync",
    "refreshReportHazardViews() refresh cycle"
  ],
  topPanelBindingWriteHelpers: [
    "updateDailyHabitStatus() via logTopPanelWrite()/safeText()",
    "refreshPortraitV2LocalizedIntelligence() via logTopPanelWrite()/textContent"
  ],
  topStripOwnerDiagnosticLogging: [
    "updateDailyHabitStatus()",
    "refreshPortraitV2LocalizedIntelligence()"
  ]
};

function trimGridlyBackgroundAuditList(list, maxLength = 60) {
  while (list.length > maxLength) list.shift();
}

function getGridlyBackgroundAuditStack() {
  try {
    return String(new Error().stack || "")
      .split("\n")
      .slice(2, 7)
      .map((line) => line.trim())
      .filter(Boolean);
  } catch (error) {
    return [];
  }
}

function recordGridlyBackgroundFunctionCall(functionName) {
  const entry = {
    at: Date.now(),
    functionName,
    stack: getGridlyBackgroundAuditStack()
  };
  if (functionName === "refreshPortraitV2LocalizedIntelligence") {
    gridlyBackgroundLoopAuditState.portraitRefreshCount += 1;
    gridlyBackgroundLoopAuditState.portraitRefreshes.push(entry);
    trimGridlyBackgroundAuditList(gridlyBackgroundLoopAuditState.portraitRefreshes);
  } else if (functionName === "updateDailyHabitStatus") {
    gridlyBackgroundLoopAuditState.dailyHabitUpdateCount += 1;
    gridlyBackgroundLoopAuditState.dailyHabitUpdates.push(entry);
    trimGridlyBackgroundAuditList(gridlyBackgroundLoopAuditState.dailyHabitUpdates);
  }
}

function isGridlyExplicitDebugModeEnabled() {
  if (typeof window === "undefined") return false;
  if (window.GRIDLY_DEBUG === true || window.GRIDLY_PERFORMANCE_DEBUG === true) return true;
  try {
    return window.localStorage?.getItem?.("gridlyDebugMode") === "true"
      || window.localStorage?.getItem?.("gridlyPerformanceDebug") === "true";
  } catch (error) {
    return false;
  }
}

function isGridlyTopPanelDebugEnabled() {
  return typeof window !== "undefined" && window.GRIDLY_DEBUG_TOP_PANEL === true;
}

function recordGridlyTopPanelDedupe(sourceFunction, targetElement, value) {
  gridlyBackgroundLoopAuditState.repeatedSameValueWrites += 1;
  gridlyBackgroundLoopAuditState.sameValueWriteSuppressionApplied = true;
  gridlyBackgroundLoopAuditState.dedupedWrites.push({
    at: Date.now(),
    sourceFunction: String(sourceFunction || "unknown"),
    targetElement: normalizeGridlyHeaderOwnershipTarget(targetElement),
    value: typeof value === "string" ? value : (value == null ? "" : String(value))
  });
  trimGridlyBackgroundAuditList(gridlyBackgroundLoopAuditState.dedupedWrites);
}

function setGridlyTopPanelTextIfChanged(elementOrId, value, sourceFunction, targetElement = elementOrId) {
  const element = typeof elementOrId === "string" ? document.getElementById(elementOrId) : elementOrId;
  if (!element) return false;
  const serializedValue = normalizeGridlyCountyAwareDisplayText(typeof value === "string" ? value : (value == null ? "" : String(value)));
  const normalizedTarget = normalizeGridlyHeaderOwnershipTarget(targetElement);
  if (typeof canGridlyCommunityPulseWriteTopStatus === "function" && !canGridlyCommunityPulseWriteTopStatus(sourceFunction, normalizedTarget, serializedValue, { setter: "setGridlyTopPanelTextIfChanged" })) return false;
  if (element.textContent === serializedValue) {
    recordGridlyTopPanelDedupe(sourceFunction, normalizedTarget, serializedValue);
    return false;
  }
  element.textContent = serializedValue;
  recordGridlyTopPanelWriteApplied(sourceFunction, normalizedTarget, serializedValue);
  return true;
}

function safeTopPanelText(id, value, sourceFunction) {
  if (shouldSuppressGridlyDashboardSectionPassiveTextUpdate(id)) return 0;
  let appliedWrites = 0;
  if (!els[id]) els[id] = document.getElementById(id);
  if (setGridlyTopPanelTextIfChanged(els[id], value, sourceFunction, id)) appliedWrites += 1;
  document.querySelectorAll(`[data-bind-text="${id}"]`).forEach((node, index) => {
    if (setGridlyTopPanelTextIfChanged(node, value, sourceFunction, `${id}:data-bind:${index}`)) appliedWrites += 1;
  });
  return appliedWrites;
}

function toGridlyTimerAuditRecord(record) {
  return {
    id: record.auditId,
    nativeId: String(record.nativeId),
    delay: record.delay,
    createdAt: record.createdAt,
    ageMs: Date.now() - record.createdAt,
    stack: record.stack
  };
}

function resetGridlyBackgroundTimerTrackingRecords() {
  gridlyBackgroundLoopAuditState.activeIntervals.clear();
  gridlyBackgroundLoopAuditState.activeTimeouts.clear();
  gridlyBackgroundLoopAuditState.activeAnimationFrames.clear();
}

function installGridlyBackgroundTimerTracking() {
  if (typeof window === "undefined") return null;
  if (window.__gridlyBackgroundLoopTrackingInstalled && window.__gridlyBackgroundLoopTrackingRestore) {
    return window.__gridlyBackgroundLoopTrackingRestore;
  }
  const nativeApis = {
    setInterval: window.setInterval,
    clearInterval: window.clearInterval,
    setTimeout: window.setTimeout,
    clearTimeout: window.clearTimeout,
    requestAnimationFrame: window.requestAnimationFrame,
    cancelAnimationFrame: window.cancelAnimationFrame
  };
  const nativeSetInterval = nativeApis.setInterval.bind(window);
  const nativeClearInterval = nativeApis.clearInterval.bind(window);
  const nativeSetTimeout = nativeApis.setTimeout.bind(window);
  const nativeClearTimeout = nativeApis.clearTimeout.bind(window);
  const nativeRequestAnimationFrame = nativeApis.requestAnimationFrame ? nativeApis.requestAnimationFrame.bind(window) : null;
  const nativeCancelAnimationFrame = nativeApis.cancelAnimationFrame ? nativeApis.cancelAnimationFrame.bind(window) : null;

  window.__gridlyBackgroundLoopTrackingInstalled = true;
  resetGridlyBackgroundTimerTrackingRecords();

  const restoreGridlyBackgroundTimerTracking = () => {
    if (!window.__gridlyBackgroundLoopTrackingInstalled) return;
    window.setInterval = nativeApis.setInterval;
    window.clearInterval = nativeApis.clearInterval;
    window.setTimeout = nativeApis.setTimeout;
    window.clearTimeout = nativeApis.clearTimeout;
    if (nativeApis.requestAnimationFrame) window.requestAnimationFrame = nativeApis.requestAnimationFrame;
    if (nativeApis.cancelAnimationFrame) window.cancelAnimationFrame = nativeApis.cancelAnimationFrame;
    resetGridlyBackgroundTimerTrackingRecords();
    window.__gridlyBackgroundLoopTrackingInstalled = false;
    window.__gridlyBackgroundLoopTrackingRestore = null;
  };
  window.__gridlyBackgroundLoopTrackingRestore = restoreGridlyBackgroundTimerTracking;

  window.setInterval = (handler, delay, ...args) => {
    const auditId = gridlyBackgroundLoopAuditState.nextTimerAuditId++;
    const nativeId = nativeSetInterval(handler, delay, ...args);
    gridlyBackgroundLoopAuditState.activeIntervals.set(nativeId, {
      auditId,
      nativeId,
      delay: Number(delay) || 0,
      createdAt: Date.now(),
      stack: getGridlyBackgroundAuditStack()
    });
    return nativeId;
  };
  window.clearInterval = (nativeId) => {
    gridlyBackgroundLoopAuditState.activeIntervals.delete(nativeId);
    return nativeClearInterval(nativeId);
  };
  window.setTimeout = (handler, delay, ...args) => {
    const auditId = gridlyBackgroundLoopAuditState.nextTimerAuditId++;
    let nativeId;
    const wrappedHandler = (...handlerArgs) => {
      gridlyBackgroundLoopAuditState.activeTimeouts.delete(nativeId);
      return typeof handler === "function" ? handler(...handlerArgs) : Function(String(handler || ""))();
    };
    nativeId = nativeSetTimeout(wrappedHandler, delay, ...args);
    gridlyBackgroundLoopAuditState.activeTimeouts.set(nativeId, {
      auditId,
      nativeId,
      delay: Number(delay) || 0,
      createdAt: Date.now(),
      stack: getGridlyBackgroundAuditStack()
    });
    return nativeId;
  };
  window.clearTimeout = (nativeId) => {
    gridlyBackgroundLoopAuditState.activeTimeouts.delete(nativeId);
    return nativeClearTimeout(nativeId);
  };
  if (nativeRequestAnimationFrame && nativeCancelAnimationFrame) {
    window.requestAnimationFrame = (handler) => {
      const auditId = gridlyBackgroundLoopAuditState.nextTimerAuditId++;
      let nativeId;
      const wrappedHandler = (timestamp) => {
        gridlyBackgroundLoopAuditState.activeAnimationFrames.delete(nativeId);
        return handler(timestamp);
      };
      nativeId = nativeRequestAnimationFrame(wrappedHandler);
      gridlyBackgroundLoopAuditState.activeAnimationFrames.set(nativeId, {
        auditId,
        nativeId,
        delay: 0,
        createdAt: Date.now(),
        stack: getGridlyBackgroundAuditStack()
      });
      return nativeId;
    };
    window.cancelAnimationFrame = (nativeId) => {
      gridlyBackgroundLoopAuditState.activeAnimationFrames.delete(nativeId);
      return nativeCancelAnimationFrame(nativeId);
    };
  }
  return restoreGridlyBackgroundTimerTracking;
}

function withGridlyBackgroundTimerTracking(callback) {
  const restore = installGridlyBackgroundTimerTracking();
  try {
    const result = callback?.();
    if (result && typeof result.finally === "function") return result.finally(() => restore?.());
    restore?.();
    return result;
  } catch (error) {
    restore?.();
    throw error;
  }
}

function getGridlyBackgroundSuspectedLoops() {
  const repeatedByKey = new Map();
  for (const entry of gridlyBackgroundLoopAuditState.dedupedWrites) {
    const key = `${entry.sourceFunction}:${entry.targetElement}:${entry.value}`;
    repeatedByKey.set(key, (repeatedByKey.get(key) || 0) + 1);
  }
  return [...repeatedByKey.entries()]
    .filter(([, count]) => count >= 2)
    .map(([key, count]) => {
      const [sourceFunction, targetElement, ...valueParts] = key.split(":");
      return {
        sourceFunction,
        targetElement,
        repeatedSameValueWrites: count,
        value: valueParts.join(":")
      };
    });
}

function gridlyBackgroundLoopAudit() {
  const suspectedLoops = getGridlyBackgroundSuspectedLoops();
  const activeIntervals = [...gridlyBackgroundLoopAuditState.activeIntervals.values()].map(toGridlyTimerAuditRecord);
  const activeTimeouts = [...gridlyBackgroundLoopAuditState.activeTimeouts.values()].map(toGridlyTimerAuditRecord);
  const activeAnimationFrames = [...gridlyBackgroundLoopAuditState.activeAnimationFrames.values()].map(toGridlyTimerAuditRecord);
  return {
    topPanelWriteCount: gridlyBackgroundLoopAuditState.topPanelWriteCount,
    repeatedTopPanelWriteCount: gridlyBackgroundLoopAuditState.repeatedSameValueWrites,
    sameValueWriteSuppressionApplied: Boolean(gridlyBackgroundLoopAuditState.sameValueWriteSuppressionApplied),
    recentSuppressedTopPanelWrites: [...gridlyBackgroundLoopAuditState.dedupedWrites],
    recentAppliedTopPanelWrites: [...gridlyBackgroundLoopAuditState.topPanelWrites],
    topPanelOwnerCheckCount: gridlyBackgroundLoopAuditState.topPanelOwnerCheckCount,
    portraitRefreshCount: gridlyBackgroundLoopAuditState.portraitRefreshCount,
    dailyHabitUpdateCount: gridlyBackgroundLoopAuditState.dailyHabitUpdateCount,
    repeatedSameValueWrites: gridlyBackgroundLoopAuditState.repeatedSameValueWrites,
    activeIntervals,
    activeTimeouts,
    activeAnimationFrames,
    suspectedLoops,
    recommendation: suspectedLoops.length
      ? "Repeated top-panel writes are being deduped. Inspect suspectedLoops stacks and activeIntervals for refresh sources before adding new refresh timers."
      : "No repeated same-value top-panel write loop detected in the captured audit window.",
    callers: GRIDLY_BACKGROUND_LOOP_CALLERS
  };
}

if (typeof window !== "undefined") {
  window.gridlyBackgroundLoopAudit = gridlyBackgroundLoopAudit;
  window.withGridlyBackgroundTimerTracking = withGridlyBackgroundTimerTracking;
}

