const ROAD_HAZARD_TYPE_OPTIONS = [
  { value: "flooding", label: "Flooding" },
  { value: "crash", label: "Crash / Wreck" },
  { value: "disabled_vehicle", label: "Disabled Vehicle" },
  { value: "debris", label: "Debris in Road" },
  { value: "road_closed", label: "Road Closed" },
  { value: "construction", label: "Construction" },
  { value: "traffic_backup", label: "Traffic Backup / Heavy Delay" },
  { value: "other_hazard", label: "Other Hazard" }
];

const OTHER_HAZARD_SUBTYPE_OPTIONS = Object.freeze([
  { value: "livestock_on_road", label: "Livestock on Road", narrativeLabel: "Livestock" },
  { value: "traffic_signal_issue", label: "Traffic Signal Issue", narrativeLabel: "Traffic signal issue" },
  { value: "downed_power_line", label: "Downed Power Line", narrativeLabel: "Downed power line" },
  { value: "emergency_response_activity", label: "Emergency Response Activity", narrativeLabel: "Emergency response activity" },
  { value: "other", label: "Other", narrativeLabel: "Hazard" }
]);

const OTHER_HAZARD_SUBTYPE_VALUES = new Set(OTHER_HAZARD_SUBTYPE_OPTIONS.map((option) => option.value));
const OTHER_HAZARD_STRUCTURED_METADATA_PREFIX = "gridly_structured=";

function normalizeOtherHazardSubtype(value = "") {
  const normalized = String(value || "").trim().toLowerCase();
  return OTHER_HAZARD_SUBTYPE_VALUES.has(normalized) ? normalized : "";
}

function getOtherHazardSubtypeOption(value = "") {
  const normalized = normalizeOtherHazardSubtype(value);
  return OTHER_HAZARD_SUBTYPE_OPTIONS.find((option) => option.value === normalized) || null;
}

function getOtherHazardSubtypeLabel(value = "") {
  return getOtherHazardSubtypeOption(value)?.label || "Other Hazard";
}

function buildOtherHazardStructuredMetadata(subtype = "") {
  const normalizedSubtype = normalizeOtherHazardSubtype(subtype);
  return normalizedSubtype ? { category: "other_hazard", subtype: normalizedSubtype } : { category: "other_hazard" };
}

function appendGridlyStructuredMetadata(detail = "", metadata = {}) {
  const cleanMetadata = Object.entries(metadata || {}).reduce((clean, [key, value]) => {
    if (!key || value === undefined || value === null || value === "") return clean;
    clean[key] = value;
    return clean;
  }, {});
  if (!Object.keys(cleanMetadata).length) return detail;
  const text = String(detail || "").trim();
  const markerIndex = text.indexOf(OTHER_HAZARD_STRUCTURED_METADATA_PREFIX);
  if (markerIndex < 0) return `${text} ${OTHER_HAZARD_STRUCTURED_METADATA_PREFIX}${JSON.stringify(cleanMetadata)}`.trim();
  const beforeMarker = text.slice(0, markerIndex).trim();
  const rawJson = text.slice(markerIndex + OTHER_HAZARD_STRUCTURED_METADATA_PREFIX.length).trim();
  const jsonMatch = rawJson.match(/^\{[^}]*\}/);
  if (!jsonMatch) return `${beforeMarker} ${OTHER_HAZARD_STRUCTURED_METADATA_PREFIX}${JSON.stringify(cleanMetadata)}`.trim();
  try {
    const parsed = JSON.parse(jsonMatch[0]);
    return `${beforeMarker} ${OTHER_HAZARD_STRUCTURED_METADATA_PREFIX}${JSON.stringify({ ...(parsed && typeof parsed === "object" ? parsed : {}), ...cleanMetadata })}`.trim();
  } catch (error) {
    return `${beforeMarker} ${OTHER_HAZARD_STRUCTURED_METADATA_PREFIX}${JSON.stringify(cleanMetadata)}`.trim();
  }
}

function appendOtherHazardStructuredMetadata(detail = "", subtype = "") {
  const normalizedSubtype = normalizeOtherHazardSubtype(subtype);
  if (!normalizedSubtype) return detail;
  return appendGridlyStructuredMetadata(detail, buildOtherHazardStructuredMetadata(normalizedSubtype));
}

function extractOtherHazardStructuredMetadata(record = {}) {
  const directSubtype = normalizeOtherHazardSubtype(record?.subtype || record?.hazardSubtype || record?.otherHazardSubtype);
  if (directSubtype) return buildOtherHazardStructuredMetadata(directSubtype);
  const nestedCandidates = [record?.raw, record?.source, record?.incident, record?.latestReport].filter((candidate) => candidate && typeof candidate === "object");
  for (const candidate of nestedCandidates) {
    const nestedSubtype = normalizeOtherHazardSubtype(candidate?.subtype || candidate?.hazardSubtype || candidate?.otherHazardSubtype);
    if (nestedSubtype) return buildOtherHazardStructuredMetadata(nestedSubtype);
  }
  const detailCandidates = [record?.detail, record?.description, record?.subtitle, record?.raw?.detail, record?.raw?.description, record?.source?.detail, record?.source?.description];
  const detail = detailCandidates.map((value) => String(value || "")).find((value) => value.includes(OTHER_HAZARD_STRUCTURED_METADATA_PREFIX)) || String(record?.detail || record?.description || "");
  const markerIndex = detail.indexOf(OTHER_HAZARD_STRUCTURED_METADATA_PREFIX);
  if (markerIndex < 0) return { category: "other_hazard" };
  const rawJson = detail.slice(markerIndex + OTHER_HAZARD_STRUCTURED_METADATA_PREFIX.length).trim();
  const jsonMatch = rawJson.match(/^\{[^}]*\}/);
  if (!jsonMatch) return { category: "other_hazard" };
  try {
    const parsed = JSON.parse(jsonMatch[0]);
    const parsedSubtype = normalizeOtherHazardSubtype(parsed?.subtype);
    return {
      ...(parsed && typeof parsed === "object" ? parsed : {}),
      ...(parsedSubtype ? buildOtherHazardStructuredMetadata(parsedSubtype) : { category: parsed?.category || "other_hazard" }),
      ...(parsed?.county_id ? { county_id: String(parsed.county_id).trim().toLowerCase() } : {}),
      ...(parsed?.countyId ? { countyId: String(parsed.countyId).trim().toLowerCase() } : {})
    };
  } catch (error) {
    return { category: "other_hazard" };
  }
}

function resolveOtherHazardSubtypeFromRecord(record = {}) {
  const category = String(record?.category || record?.report_type || record?.reportType || record?.type || record?.raw?.category || record?.raw?.report_type || record?.raw?.type || record?.source?.category || record?.source?.report_type || record?.source?.type || "").trim().toLowerCase();
  const normalizedCategory = category ? getHazardCategory(category) : "other_hazard";
  if (normalizedCategory !== "other_hazard" && category !== "other_hazard") return "";
  return normalizeOtherHazardSubtype(extractOtherHazardStructuredMetadata(record).subtype);
}

let lastOtherHazardRenderedSubtype = "";
let lastOtherHazardRenderedSubtypeLabel = "";
let lastOtherHazardRenderedAlertTitle = "";
let lastOtherHazardNarrativeAuditState = null;

function isOtherHazardGenericRoadLabel(value = "") {
  const text = String(value || "").replace(/\s+/g, " ").trim();
  if (!text) return true;
  return /^(?:this road|local roadway|local road|local road impact(?: into liberty| in liberty)?|impact into liberty|road|roadway|street|unknown|location pending|liberty county|county)$/i.test(text);
}

function normalizeOtherHazardNarrativeRoadName(value = "") {
  const raw = String(value || "").replace(/\s+/g, " ").trim();
  if (!raw || isOtherHazardGenericRoadLabel(raw)) return "";
  const standardizedReference = typeof gridlyV230NormalizeRoadReference === "function" ? gridlyV230NormalizeRoadReference(raw) : "";
  if (standardizedReference) return standardizedReference;
  if (typeof normalizeRoadDisplayCase === "function") return normalizeRoadDisplayCase(raw);
  if (typeof normalizeRoadwayReference === "function") return normalizeRoadwayReference(raw);
  if (typeof normalizeCorridorBaseLabel === "function") return normalizeCorridorBaseLabel(raw);
  return raw;
}

function resolveOtherHazardNarrativeRoadName(report = {}, explicitRoadName = "") {
  const coordinate = typeof normalizeCoordinatePair === "function"
    ? normalizeCoordinatePair(report?.lat ?? report?.latitude ?? report?.rawLat ?? report?.source?.lat ?? report?.source?.latitude ?? report?.raw?.lat ?? report?.raw?.latitude, report?.lng ?? report?.lon ?? report?.longitude ?? report?.rawLng ?? report?.source?.lng ?? report?.source?.lon ?? report?.source?.longitude ?? report?.raw?.lng ?? report?.raw?.lon ?? report?.raw?.longitude)
    : null;
  const resolvedFromCoordinate = coordinate && typeof resolveNearestRoadName === "function"
    ? resolveNearestRoadName(coordinate.lat, coordinate.lng)
    : "";
  const candidates = [
    explicitRoadName,
    report?.resolvedRoadName,
    report?.lastResolvedRoadName,
    report?.selectedRoadName,
    report?.roadName,
    report?.road_name,
    report?.street_name,
    report?.nearest_road,
    report?.snapped_road_name,
    report?.primaryRoad,
    report?.corridor,
    report?.titleRoad,
    report?.raw?.resolvedRoadName,
    report?.raw?.selectedRoadName,
    report?.raw?.roadName,
    report?.raw?.road_name,
    report?.raw?.street_name,
    report?.raw?.nearest_road,
    report?.source?.resolvedRoadName,
    report?.source?.selectedRoadName,
    report?.source?.roadName,
    report?.source?.road_name,
    report?.source?.street_name,
    report?.source?.nearest_road,
    resolvedFromCoordinate
  ];
  for (const candidate of candidates) {
    const normalized = normalizeOtherHazardNarrativeRoadName(candidate);
    if (normalized && !isOtherHazardGenericRoadLabel(normalized)) {
      return {
        roadName: normalized,
        roadResolutionAvailable: true,
        normalizationApplied: typeof normalizeRoadDisplayCase === "function" || typeof normalizeRoadwayReference === "function" || typeof normalizeCorridorBaseLabel === "function",
        source: candidate === resolvedFromCoordinate ? "coordinate_resolver" : "record"
      };
    }
  }
  return {
    roadName: "",
    roadResolutionAvailable: false,
    normalizationApplied: false,
    source: "fallback"
  };
}

function normalizeOtherHazardAwarenessAreaCandidate(value = "") {
  return String(value || "").replace(/\s+/g, " ").trim();
}

function isOtherHazardRoadLikeAwarenessAreaCandidate(value = "") {
  const text = normalizeOtherHazardAwarenessAreaCandidate(value);
  if (!text) return false;
  const normalizedReference = typeof gridlyV230NormalizeRoadReference === "function"
    ? gridlyV230NormalizeRoadReference(text)
    : "";
  const normalizedText = normalizeOtherHazardAwarenessAreaCandidate(
    typeof normalizeGridlyRoadDisplayName === "function" ? normalizeGridlyRoadDisplayName(text) : text
  );
  const roadOnlyPatterns = [
    /^(?:farm[-\s]+to[-\s]+market(?:\s+road)?|farm\s+road|fm)\s*[- ]?\d+[a-z]?$/i,
    /^(?:county\s+road|cr)\s*[- ]?\d+[a-z]?$/i,
    /^(?:u\.?s\.?\s+highway|united\s+states\s+highway|us)\s*[- ]?\d+[a-z]?$/i,
    /^(?:state\s+highway|texas\s+highway|texas\s+state\s+highway|tx|sh)\s*[- ]?\d+[a-z]?$/i,
    /^(?:interstate|ih|i)\s*[- ]?\d+[a-z]?$/i
  ];
  if (roadOnlyPatterns.some((pattern) => pattern.test(text) || pattern.test(normalizedText))) return true;
  return Boolean(normalizedReference && normalizeOtherHazardAwarenessAreaCandidate(normalizedReference).toLowerCase() === normalizedText.toLowerCase());
}

function getOtherHazardAwarenessAreaRejectionReason(value = "", resolvedRoadName = "") {
  const text = normalizeOtherHazardAwarenessAreaCandidate(value);
  if (!text) return "empty";
  const roadNorm = normalizeOtherHazardAwarenessAreaCandidate(resolvedRoadName).toLowerCase();
  if (roadNorm && text.toLowerCase() === roadNorm) return "matches_resolved_road";
  if (/^(?:liberty county|county|this road|local roadway|local road|location pending)$/i.test(text)) return "generic_area";
  if (isOtherHazardRoadLikeAwarenessAreaCandidate(text)) return "road_like_label";
  return "";
}

function resolveOtherHazardNarrativeArea(report = {}, explicitCommunityName = "", resolvedRoadName = "") {
  const coordinate = typeof normalizeCoordinatePair === "function"
    ? normalizeCoordinatePair(report?.lat ?? report?.latitude ?? report?.rawLat ?? report?.source?.lat ?? report?.source?.latitude ?? report?.raw?.lat ?? report?.raw?.latitude, report?.lng ?? report?.lon ?? report?.longitude ?? report?.rawLng ?? report?.source?.lng ?? report?.source?.lon ?? report?.source?.longitude ?? report?.raw?.lng ?? report?.raw?.lon ?? report?.raw?.longitude)
    : null;
  const nearbyKnownLocation = coordinate && typeof resolveNearbyKnownLocation === "function"
    ? resolveNearbyKnownLocation(coordinate.lat, coordinate.lng)
    : "";
  const candidates = [
    explicitCommunityName,
    report?.awarenessArea,
    report?.communityName,
    report?.town,
    report?.city,
    report?.municipality,
    report?.area,
    report?.location_name,
    report?.locationName,
    report?.raw?.awarenessArea,
    report?.raw?.communityName,
    report?.raw?.town,
    report?.raw?.city,
    report?.raw?.area,
    report?.source?.awarenessArea,
    report?.source?.communityName,
    report?.source?.town,
    report?.source?.city,
    report?.source?.area,
    nearbyKnownLocation
  ];
  const resolution = {
    awarenessArea: "",
    rejectedAwarenessAreaCandidate: "",
    awarenessAreaRejectedReason: "",
    finalAwarenessArea: "",
    areaQualityPass: true
  };
  for (const candidate of candidates) {
    const value = normalizeOtherHazardAwarenessAreaCandidate(candidate);
    const rejectionReason = getOtherHazardAwarenessAreaRejectionReason(value, resolvedRoadName);
    if (!value) continue;
    if (rejectionReason) {
      if (!resolution.rejectedAwarenessAreaCandidate) {
        resolution.rejectedAwarenessAreaCandidate = value;
        resolution.awarenessAreaRejectedReason = rejectionReason;
      }
      continue;
    }
    resolution.awarenessArea = value;
    resolution.finalAwarenessArea = value;
    resolution.areaQualityPass = !isOtherHazardRoadLikeAwarenessAreaCandidate(value);
    return resolution;
  }
  resolution.areaQualityPass = true;
  return resolution;
}

function buildOtherHazardNarrativeModel(report = {}, roadName = "", communityName = "") {
  const metadata = extractOtherHazardStructuredMetadata(report);
  const subtypeOption = getOtherHazardSubtypeOption(metadata.subtype);
  const subtype = subtypeOption?.value || metadata.subtype || "other";
  const subtypeLabel = subtypeOption?.narrativeLabel || "Hazard";
  const roadResolution = resolveOtherHazardNarrativeRoadName(report, roadName);
  const resolvedRoadName = roadResolution.roadName;
  const areaResolution = resolvedRoadName
    ? resolveOtherHazardNarrativeArea(report, communityName, resolvedRoadName)
    : {
      awarenessArea: "",
      rejectedAwarenessAreaCandidate: "",
      awarenessAreaRejectedReason: "",
      finalAwarenessArea: "",
      areaQualityPass: true
    };
  const awarenessArea = areaResolution.finalAwarenessArea || areaResolution.awarenessArea || "";
  const fallbackLevel = resolvedRoadName && awarenessArea ? 1 : (resolvedRoadName ? 2 : 3);
  const narrative = fallbackLevel === 1
    ? `${subtypeLabel} reported on ${resolvedRoadName} in ${awarenessArea}`
    : (fallbackLevel === 2 ? `${subtypeLabel} reported on ${resolvedRoadName}` : `${subtypeLabel} reported on this road`);
  const narrativeAreaMatch = narrative.match(/\breported\s+on\s+.+?\s+in\s+(.+)$/i);
  const narrativeAreaRoadLike = Boolean(narrativeAreaMatch?.[1] && isOtherHazardRoadLikeAwarenessAreaCandidate(narrativeAreaMatch[1]));
  const wordingQualityPass = Boolean(narrative && !narrativeAreaRoadLike && !/\bon\s+this\s+road\s+on\b/i.test(narrative) && !/\bon\s+road\s+on\b/i.test(narrative) && !/on\s+This\s+Road/.test(narrative) && !/\bLivestock on Road on\b/i.test(narrative));
  return {
    subtype,
    subtypeLabel,
    resolvedRoadName,
    awarenessArea,
    rejectedAwarenessAreaCandidate: areaResolution.rejectedAwarenessAreaCandidate || "",
    awarenessAreaRejectedReason: areaResolution.awarenessAreaRejectedReason || "",
    finalAwarenessArea: awarenessArea,
    areaQualityPass: Boolean(areaResolution.areaQualityPass && !narrativeAreaRoadLike),
    narrative,
    fallbackLevel,
    roadResolutionAvailable: roadResolution.roadResolutionAvailable,
    normalizationApplied: roadResolution.normalizationApplied,
    wordingQualityPass
  };
}

function recordOtherHazardRenderedAlert(record = {}, title = "") {
  const subtype = resolveOtherHazardSubtypeFromRecord(record);
  if (!subtype) return;
  lastOtherHazardRenderedSubtype = subtype;
  lastOtherHazardRenderedSubtypeLabel = getOtherHazardSubtypeOption(subtype)?.narrativeLabel || getOtherHazardSubtypeLabel(subtype);
  lastOtherHazardRenderedAlertTitle = String(title || "").trim();
  const model = buildOtherHazardNarrativeModel({ ...record, subtype });
  const renderedNarrative = lastOtherHazardRenderedAlertTitle || model.narrative;
  const renderedAreaMatch = renderedNarrative.match(/\breported\s+on\s+.+?\s+in\s+(.+)$/i);
  const renderedAreaRoadLike = Boolean(renderedAreaMatch?.[1] && isOtherHazardRoadLikeAwarenessAreaCandidate(renderedAreaMatch[1]));
  lastOtherHazardNarrativeAuditState = {
    ...model,
    narrative: renderedNarrative,
    areaQualityPass: Boolean(model.areaQualityPass && !renderedAreaRoadLike),
    wordingQualityPass: Boolean(renderedNarrative && model.wordingQualityPass && !renderedAreaRoadLike && !/\bon\s+This\s+Road\b/.test(renderedNarrative))
  };
}

function buildOtherHazardSubtypeNarrative(report = {}, roadName = "", communityName = "") {
  return buildOtherHazardNarrativeModel(report, roadName, communityName).narrative;
}

function gridlyOtherHazardSubtypeAudit() {
  const sample = buildOtherHazardStructuredMetadata("livestock_on_road");
  const fallback = extractOtherHazardStructuredMetadata({ report_type: "other_hazard", detail: "Shared report: road hazard may affect travel." });
  return {
    auditVersion: "GRIDLY_V235_OTHER_HAZARD_STRUCTURED_SUBTYPES",
    subtypeSupportEnabled: true,
    supportedSubtypes: OTHER_HAZARD_SUBTYPE_OPTIONS.map((option) => ({
      value: option.value,
      label: option.label
    })),
    backwardCompatibilityMaintained: fallback.category === "other_hazard" && !fallback.subtype,
    narrativeSupportAvailable: buildOtherHazardSubtypeNarrative({ category: sample.category, subtype: sample.subtype }, "FM 770", "Hull") === "Livestock reported on FM 770 in Hull",
    findings: [
      "Other Hazard keeps category=other_hazard and can add a structured subtype without free text.",
      "Reports without subtype continue to normalize and render as standard Other Hazard.",
      "Subtype narratives are generated from structured values and supplied road/community context."
    ]
  };
}

function gridlyOtherHazardNarrativeAudit() {
  const activeRecords = [
    ...(Array.isArray(activeHazards) ? activeHazards : []),
    ...(Array.isArray(activeReports) ? activeReports : []),
    ...(typeof getActiveUnifiedIncidents === "function" ? getActiveUnifiedIncidents() : []),
    ...(typeof getUnifiedIncidents === "function" ? getUnifiedIncidents() : [])
  ];
  const liveOtherHazard = activeRecords.find((record) => resolveOtherHazardSubtypeFromRecord(record));
  const model = liveOtherHazard
    ? buildOtherHazardNarrativeModel(liveOtherHazard)
    : (lastOtherHazardNarrativeAuditState || buildOtherHazardNarrativeModel({ category: "other_hazard", subtype: "livestock_on_road", resolvedRoadName: "FM 1410", awarenessArea: "Hull" }));
  return {
    subtype: model.subtype,
    subtypeLabel: model.subtypeLabel,
    resolvedRoadName: model.resolvedRoadName,
    awarenessArea: model.awarenessArea,
    rejectedAwarenessAreaCandidate: model.rejectedAwarenessAreaCandidate || "",
    awarenessAreaRejectedReason: model.awarenessAreaRejectedReason || "",
    finalAwarenessArea: model.finalAwarenessArea || model.awarenessArea || "",
    areaQualityPass: Boolean(model.areaQualityPass),
    narrative: model.narrative,
    fallbackLevel: model.fallbackLevel,
    roadResolutionAvailable: model.roadResolutionAvailable,
    normalizationApplied: model.normalizationApplied,
    wordingQualityPass: Boolean(model.wordingQualityPass && model.areaQualityPass && !/\bon\s+This\s+Road\b/.test(model.narrative))
  };
}

