function getGridlyDriveTexasEventText(event = {}) {
  if (typeof event === "string") return event;
  return [event.title, event.eventType, event.type, event.condition, event.description, event.status, event.category].filter(Boolean).join(" ");
}

function classifyDriveTexasEvent(event = {}) {
  const eventText = getGridlyDriveTexasEventText(event);
  const lowerText = eventText.toLowerCase();
  const floodCause = /flood|high\s*water|water\s*over\s*road/.test(lowerText);
  const closureCause = /road\s*closed|full\s*closure|closed/.test(lowerText);
  if (floodCause && closureCause) {
    return { normalizedGridlyType: "road_closed", confidence: "high", trustLabel: "Official Source", lifecycleClass: "flood_closure", floodRelated: true, travelConfidenceImpact: "Severe", reason: "Official-style event combines closure and flood/high-water language; preserve closure semantics and flood relationship." };
  }
  const mapping = GRIDLY_DRIVETEXAS_SHADOW_MAPPINGS.find((candidate) => candidate.match.test(eventText));
  if (mapping) {
    const { match: _match, ...result } = mapping;
    return { ...result };
  }
  return { normalizedGridlyType: "other_official", confidence: "low", trustLabel: "Official Source", lifecycleClass: "review_required", floodRelated: false, travelConfidenceImpact: "None", reason: "No recommended V326 mapping matched; keep as official evidence for future taxonomy review." };
}


