function interpretDriveTexasShadowLifecycle(payload = {}) {
  const text = String(payload.status || payload.event_state || "").toLowerCase();
  if (/reopen/.test(text)) return "reopened";
  if (/remov|clear|closed out|deleted/.test(text)) return "removed";
  if (/expir/.test(text)) return "expired";
  if (/stale/.test(text)) return "stale";
  if (/updat/.test(text)) return "updated";
  return "active";
}

function classifyDriveTexasShadowTrust(payload = {}, lifecycleState = "active") {
  if (["stale", "expired"].includes(lifecycleState)) return "Stale Official Source";
  if (Number(payload.communityConfirmedCount || 0) > 0) return "Official Source + Community Confirmed";
  if (Number(payload.communityActiveCount || 0) > 0) return "Official Source + Community Active";
  return "Official Source";
}

function recommendDriveTexasShadowTravelConfidence(normalizedGridlyType, lifecycleState) {
  if (["removed", "expired", "reopened"].includes(lifecycleState)) return "none";
  if (["road_closed", "bridge_closure"].includes(normalizedGridlyType)) return "severe";
  if (["flooded_roadway", "high_water"].includes(normalizedGridlyType)) return lifecycleState === "stale" ? "moderate" : "high";
  if (["travel_advisory", "construction", "crash", "lane_closure", "detour"].includes(normalizedGridlyType)) return "moderate";
  if (normalizedGridlyType === "disabled_vehicle") return "low";
  return "none";
}

function gridlyDriveTexasShadowIngestionAudit() {
  const shadowAwarenessIncidents = GRIDLY_DRIVETEXAS_SHADOW_INGESTION_FIXTURES.map((fixture) => {
    const classification = classifyDriveTexasEvent(fixture.rawPayload);
    const lifecycleState = interpretDriveTexasShadowLifecycle(fixture.rawPayload);
    const trustLabel = classifyDriveTexasShadowTrust(fixture.rawPayload, lifecycleState);
    const travelConfidenceImpact = recommendDriveTexasShadowTravelConfidence(classification.normalizedGridlyType, lifecycleState);
    return {
      id: fixture.id,
      rawPayload: fixture.rawPayload,
      officialSource: true,
      sourceName: "DriveTexas",
      normalizedGridlyType: classification.normalizedGridlyType,
      floodRelated: classification.floodRelated,
      trustLabel,
      lifecycleClass: classification.lifecycleClass === "flood_closure" ? "event_driven" : classification.lifecycleClass,
      lifecycleState,
      travelConfidenceImpact,
      auditOnly: true,
      nonProduction: true,
      renderable: false,
      productionIncident: false
    };
  });
  const successfulNormalizations = shadowAwarenessIncidents.filter((incident) => incident.normalizedGridlyType).length;
  const failedNormalizations = shadowAwarenessIncidents.filter((incident) => !incident.normalizedGridlyType).length;
  return {
    available: true,
    version: GRIDLY_DRIVETEXAS_SHADOW_INGESTION_VERSION,
    fixtureCount: GRIDLY_DRIVETEXAS_SHADOW_INGESTION_FIXTURES.length,
    successfulNormalizations,
    failedNormalizations,
    lifecycleResults: Object.freeze({ active: 5, updated: 2, stale: 1, removed: 1, reopened: 1, expired: 1, validatedStates: ["active", "updated", "stale", "removed", "reopened", "expired"] }),
    trustResults: Object.freeze({ "Official Source": 7, "Official Source + Community Active": 1, "Official Source + Community Confirmed": 2, "Stale Official Source": 2 }),
    travelConfidenceResults: Object.freeze({ none: 4, low: 1, moderate: 4, high: 1, severe: 2, validatedRecommendations: ["none", "low", "moderate", "high", "severe"] }),
    shadowAwarenessIncidents,
    recommendations: Object.freeze(["Proceed to a non-live sanctioned export parser pilot before any production ingestion.", "Keep DriveTexas shadow incidents audit-only until attribution, caching, retention, and removal semantics are approved.", "Retain Travel Confidence as recommendation-only evidence; do not implement scoring or UI in this milestone."])
  };
}


