function readDriveTexasExportField(record = {}, names = []) {
  const source = record?.properties && typeof record.properties === "object" ? { ...record, ...record.properties } : record;
  const key = names.find((name) => source[name] !== undefined && source[name] !== null && String(source[name]).trim() !== "");
  return key ? source[key] : null;
}

function parseDriveTexasExportGeometry(record = {}) {
  const source = record?.properties && typeof record.properties === "object" ? { ...record, ...record.properties } : record;
  const geometry = record.geometry || source.geometry || null;
  if (geometry?.type && Array.isArray(geometry.coordinates)) return { geometry, quality: "explicit_geometry", minimumAwarenessReady: true };
  const rawLat = readDriveTexasExportField(source, ["latitude", "lat", "y"]);
  const rawLon = readDriveTexasExportField(source, ["longitude", "lon", "lng", "x"]);
  const lat = Number(rawLat);
  const lon = Number(rawLon);
  if (rawLat !== null && rawLon !== null && Number.isFinite(lat) && Number.isFinite(lon)) return { geometry: { type: "Point", coordinates: [lon, lat] }, quality: "coordinate_pair", minimumAwarenessReady: true };
  const startLat = Number(source.startLatitude); const startLon = Number(source.startLongitude); const endLat = Number(source.endLatitude); const endLon = Number(source.endLongitude);
  if ([startLat, startLon, endLat, endLon].every(Number.isFinite)) return { geometry: { type: "LineString", coordinates: [[startLon, startLat], [endLon, endLat]] }, quality: "derived_segment", minimumAwarenessReady: true };
  return { geometry: null, quality: "road_county_only", minimumAwarenessReady: Boolean(readDriveTexasExportField(source, ["route_name", "roadway", "roadName"]) && readDriveTexasExportField(source, ["county", "countyName"])) };
}

function parseDriveTexasStaticExportRecord(record = {}) {
  const geometryResult = parseDriveTexasExportGeometry(record);
  const parsed = {
    sourceId: readDriveTexasExportField(record, ["GLOBALID", "globalId", "id", "objectid", "OBJECTID"]),
    title: readDriveTexasExportField(record, ["title", "headline", "name"]),
    description: readDriveTexasExportField(record, ["description", "details", "desc"]),
    roadway: readDriveTexasExportField(record, ["route_name", "roadway", "roadName", "road", "route"]),
    county: readDriveTexasExportField(record, ["county", "countyName"]),
    district: readDriveTexasExportField(record, ["district", "txdotDistrict"]),
    eventType: readDriveTexasExportField(record, ["event_type", "condition", "category", "type"]),
    status: readDriveTexasExportField(record, ["status", "event_state", "state"]),
    updatedAt: readDriveTexasExportField(record, ["last_updated", "updated", "updateTime", "modified"]),
    geometry: geometryResult.geometry,
    geometryQuality: geometryResult.quality,
    minimumGeometryReady: geometryResult.minimumAwarenessReady,
    communityActiveCount: Number(readDriveTexasExportField(record, ["communityActiveCount"]) || 0),
    communityConfirmedCount: Number(readDriveTexasExportField(record, ["communityConfirmedCount"]) || 0)
  };
  const required = ["sourceId", "eventType", "status", "updatedAt"];
  const recommended = ["title", "description", "roadway", "county", "district"];
  const missingRequired = required.filter((field) => !parsed[field]);
  const missingRecommended = recommended.filter((field) => !parsed[field]);
  return { parsed, parseSuccessful: missingRequired.length === 0, missingRequired, missingRecommended, unsupportedFields: [], geometryResult };
}

function gridlyDriveTexasStaticExportParserAudit(samples = GRIDLY_DRIVETEXAS_STATIC_EXPORT_SAMPLES) {
  const results = samples.map((sample) => {
    const parsedResult = parseDriveTexasStaticExportRecord(sample.record || sample);
    const classification = classifyDriveTexasEvent(parsedResult.parsed);
    const lifecycleState = interpretDriveTexasShadowLifecycle(parsedResult.parsed);
    const trustLabel = classifyDriveTexasShadowTrust(parsedResult.parsed, lifecycleState);
    return { exportShape: sample.exportShape || "record", ...parsedResult, normalizedGridlyType: classification.normalizedGridlyType, lifecycleState, trustLabel };
  });
  const counts = (items) => items.reduce((acc, item) => ({ ...acc, [item]: (acc[item] || 0) + 1 }), {});
  return {
    available: true,
    version: GRIDLY_DRIVETEXAS_STATIC_EXPORT_PARSER_VERSION,
    sampleRecordCount: results.length,
    parsedSuccessfully: results.filter((item) => item.parseSuccessful).length,
    parseFailures: results.filter((item) => !item.parseSuccessful).map((item) => ({ exportShape: item.exportShape, missingRequired: item.missingRequired })),
    schemaFindings: { required: ["sourceId", "eventType", "status", "updatedAt"], optional: ["title", "description", "roadway", "county", "district", "geometry", "communityActiveCount", "communityConfirmedCount"], missing: counts(results.flatMap((item) => item.missingRecommended)), unsupported: [], reliability: "Representative static structures preserve required parser fields; title/description/geometry vary by export shape." },
    normalizationResults: counts(results.map((item) => item.normalizedGridlyType)),
    lifecycleResults: counts(results.map((item) => item.lifecycleState)),
    trustResults: counts(results.map((item) => item.trustLabel)),
    geometryResults: { explicitGeometry: results.filter((item) => item.geometryResult.quality === "explicit_geometry").length, coordinatePair: results.filter((item) => item.geometryResult.quality === "coordinate_pair").length, derivedSegment: results.filter((item) => item.geometryResult.quality === "derived_segment").length, roadCountyOnly: results.filter((item) => item.geometryResult.quality === "road_county_only").length, minimumAwarenessReady: results.filter((item) => item.geometryResult.minimumAwarenessReady).length, minimumRequirement: "Prefer official Point or LineString geometry; accept lat/lon pairs or start/end segment coordinates for future awareness review; road+county-only records remain area-level and not marker-ready." },
    recommendations: ["Proceed to a sanctioned non-live export bundle pilot before any production ingestion.", "Keep parser output audit-only and routed only into the V330 shadow contract.", "Require stable source id, event type, lifecycle status, update timestamp, roadway/county context, and marker-grade geometry before any future awareness display.", "Document export-specific field aliases before considering recurring imports."],
    records: results
  };
}



