function getDriveTexasReplayStableId(parsed = {}) {
  return parsed.sourceId ? `drivetexas:${String(parsed.sourceId).toLowerCase()}` : null;
}

function gridlyDriveTexasExportBundleReplayAudit() {
  const seenStableIds = new Map();
  const rows = [];
  let recordsProcessed = 0;
  GRIDLY_DRIVETEXAS_EXPORT_BUNDLE_REPLAY_FIXTURE.forEach((snapshot) => {
    snapshot.records.forEach((record) => {
      recordsProcessed += 1;
      const parsedResult = parseDriveTexasStaticExportRecord(record);
      const parsed = parsedResult.parsed;
      const classification = classifyDriveTexasEvent(parsed);
      const lifecycleStatus = interpretDriveTexasShadowLifecycle(parsed);
      const trustLabel = classifyDriveTexasShadowTrust(parsed, lifecycleStatus);
      const normalizedStableId = getDriveTexasReplayStableId(parsed);
      const previous = seenStableIds.get(parsed.sourceId);
      const identityStable = Boolean(normalizedStableId) && (!previous || previous === normalizedStableId);
      if (parsed.sourceId && !seenStableIds.has(parsed.sourceId)) seenStableIds.set(parsed.sourceId, normalizedStableId);
      const geometryReady = ["explicit_geometry", "coordinate_pair", "derived_segment"].includes(parsed.geometryQuality);
      const markerReady = geometryReady && !["removed", "reopened", "expired"].includes(lifecycleStatus) && classification.normalizedGridlyType !== "detour";
      const detourLanguage = /detour|alternate route/i.test([parsed.title, parsed.description, parsed.eventType].filter(Boolean).join(" "));
      const awarenessOnlyReasons = [];
      if (!geometryReady) awarenessOnlyReasons.push("road/county-only location is not exact marker-ready geometry");
      if (detourLanguage) awarenessOnlyReasons.push("detour/alternate-route language retained as awareness context only");
      if (["removed", "reopened", "expired"].includes(lifecycleStatus)) awarenessOnlyReasons.push("lifecycle state is not active marker-ready evidence");
      const v330Compatible = parsedResult.parseSuccessful && Boolean(classification.normalizedGridlyType) && trustLabel.startsWith("Official Source") && parsed.communityActiveCount >= 0 && parsed.communityConfirmedCount >= 0;
      rows.push({
        snapshotId: snapshot.snapshotId,
        snapshotTime: snapshot.snapshotTime,
        officialId: parsed.sourceId,
        normalizedStableId,
        canonicalType: classification.normalizedGridlyType,
        lifecycleStatus,
        trustLabel,
        geometryReadiness: parsed.geometryQuality,
        markerReady,
        awarenessOnlyReason: awarenessOnlyReasons.join("; ") || null,
        identityStabilityResult: identityStable ? "stable" : "unstable",
        v330CompatibilityResult: v330Compatible ? "compatible" : "issue",
        officialSourceSeparatedFromCommunityReports: parsed.communityActiveCount === 0 && parsed.communityConfirmedCount === 0,
        detourTreatedAsRouting: false,
        productionIncident: false,
        renderable: false
      });
    });
  });
  const normalizedCount = rows.filter((row) => row.canonicalType).length;
  const failedNormalizationCount = rows.length - normalizedCount;
  const identityInstabilityCount = rows.filter((row) => row.identityStabilityResult !== "stable").length;
  const v330CompatibilityIssueCount = rows.filter((row) => row.v330CompatibilityResult !== "compatible").length;
  const lifecycleTransitionCount = rows.filter((row, index) => index > 0 && rows.slice(0, index).some((prior) => prior.officialId === row.officialId && prior.lifecycleStatus !== row.lifecycleStatus)).length;
  return {
    available: true,
    policyVersion: GRIDLY_DRIVETEXAS_EXPORT_BUNDLE_REPLAY_VERSION,
    productionBehaviorChanged: false,
    liveIngestionUsed: false,
    externalNetworkUsed: false,
    uiChanged: false,
    mapChanged: false,
    routingChanged: false,
    snapshotsReplayed: GRIDLY_DRIVETEXAS_EXPORT_BUNDLE_REPLAY_FIXTURE.length,
    recordsProcessed,
    normalizedCount,
    failedNormalizationCount,
    stableIdentityCount: rows.length - identityInstabilityCount,
    identityInstabilityCount,
    lifecycleTransitionCount,
    removedEventCount: rows.filter((row) => row.lifecycleStatus === "removed").length,
    reopenedEventCount: rows.filter((row) => row.lifecycleStatus === "reopened").length,
    markerReadyCount: rows.filter((row) => row.markerReady).length,
    awarenessOnlyCount: rows.filter((row) => !row.markerReady).length,
    v330CompatibleCount: rows.length - v330CompatibilityIssueCount,
    v330CompatibilityIssueCount,
    detourTreatedAsRouting: false,
    safeForNextOfficialSourceMilestone: failedNormalizationCount === 0 && identityInstabilityCount === 0 && v330CompatibilityIssueCount === 0,
    rows,
    notes: [
      "Audit-only static sanctioned export bundle replay; no live DriveTexas ingestion or network calls.",
      "Detour and alternate-route language is preserved only as awareness context and never converted into routing instructions.",
      "Road/county-only records are minimum awareness evidence but are not exact marker-ready records.",
      "Official DriveTexas source records remain separate from community reports and are not production incidents."
    ]
  };
}


const GRIDLY_DRIVETEXAS_READINESS_GATE_VERSION = "V333";

function classifyDriveTexasReadinessLocation(row = {}) {
  if (["explicit_geometry", "coordinate_pair", "derived_segment"].includes(row.geometryReadiness)) {
    if (["removed", "reopened", "expired"].includes(row.lifecycleStatus) || row.canonicalType === "detour") return "awareness_only";
    return "marker_ready";
  }
  if (row.geometryReadiness === "road_county_only") return "awareness_only";
  return "unsupported";
}

function gridlyDriveTexasReadinessGateAudit() {
  const replay = gridlyDriveTexasExportBundleReplayAudit();
  const parser = gridlyDriveTexasStaticExportParserAudit();
  const normalizer = gridlyDriveTexasShadowNormalizerAudit();
  const rows = replay.rows.map((row) => ({ ...row, locationClass: classifyDriveTexasReadinessLocation(row) }));
  const markerReadySupported = rows.filter((row) => row.locationClass === "marker_ready").length;
  const awarenessOnlySupported = rows.filter((row) => row.locationClass === "awareness_only").length;
  const unsupportedLocationRecords = rows.filter((row) => row.locationClass === "unsupported").length;
  const identityBlockers = [];
  const geometryBlockers = unsupportedLocationRecords ? ["Some records lack enough location information for even awareness-only treatment."] : [];
  const lifecycleBlockers = [];
  const trustBlockers = [];
  const productionBlockers = [
    "No approved live DriveTexas acquisition path, credentials policy, rate-limit policy, attribution policy, retention policy, or caching policy is implemented.",
    "Static-export and replay contracts are fixture/sanctioned-sample validated only; API-based acquisition still requires sanctioned contract verification.",
    "Marker-grade geometry must remain gated so road/county-only and broad advisory records do not become exact map markers.",
    "Lifecycle removal, stale, and reopen semantics require validation against sanctioned recurring exports before production ingestion.",
    "Official-source events must remain separated from community reports until a production source-evidence model is approved.",
    "Audit logging, replay archives, and operational runbooks are not yet productionized."
  ];
  const readyForShadowIngestionPlanning = identityBlockers.length === 0 && lifecycleBlockers.length === 0 && trustBlockers.length === 0 && unsupportedLocationRecords === 0 && replay.safeForNextOfficialSourceMilestone;
  return {
    available: true,
    policyVersion: GRIDLY_DRIVETEXAS_READINESS_GATE_VERSION,
    productionBehaviorChanged: false,
    liveIngestionImplemented: false,
    networkAccessImplemented: false,
    uiChanged: false,
    mapChanged: false,
    routingChanged: false,
    acquisitionReadiness: "Static exports and sanctioned feed-export bundles are ready for non-production shadow-ingestion planning; API-based acquisition is contract-ready conceptually but not implementation-ready until approved access, attribution, caching, rate limits, and replay/audit retention are documented.",
    identityReadiness: "Stable identity confidence is high for records carrying official source ids; lifecycle/update/reopen confidence is sufficient for planning because V326-V332 fixtures preserve source id, status, update timestamp, and replay transitions, but production still requires sanctioned recurring export validation.",
    geometryReadiness: "Geometry-rich records and exact coordinates are marker-ready in future planning; road/county-only and broad advisory records remain awareness-only; no unsupported records were present in the replay fixture.",
    lifecycleReadiness: "The active, updated, removed, reopened, and stale model is sufficient for shadow-ingestion planning, with production approval blocked until real removal cadence, stale thresholds, and reopen identity behavior are validated against sanctioned recurring exports.",
    trustReadiness: "The existing trust states are sufficient for planning: Official Source, Official Source + Community Active, Official Source + Community Confirmed, and Stale Official Source. Removed/reopened/expired remain lifecycle states, not new user-facing trust labels for this gate.",
    markerReadySupported,
    awarenessOnlySupported,
    unsupportedLocationRecords,
    identityBlockers,
    geometryBlockers,
    lifecycleBlockers,
    trustBlockers,
    productionBlockers,
    readyForShadowIngestionPlanning,
    readyForProductionIngestion: false,
    findings: [
      "Shadow-ingestion planning is safe when limited to sanctioned, non-live, audit-only acquisition planning.",
      "Production ingestion is not approved in V333.",
      "Additional architecture work is required before production ingestion, especially acquisition governance, attribution/caching/retention policy, operational audit logging, and recurring export validation.",
      "Official-source events remain separate from community reports; community evidence may annotate confidence but does not overwrite official lifecycle state.",
      "Detour and alternate-route language remains awareness-only and is not routing guidance.",
      "Gridly remains Awareness Platform First and Route Intelligence Second; this gate does not make Gridly a routing platform.",
      `Reviewed ${replay.recordsProcessed} replay records: ${markerReadySupported} marker-ready, ${awarenessOnlySupported} awareness-only, ${unsupportedLocationRecords} unsupported.`,
      `Parser sample success: ${parser.parsedSuccessfully}/${parser.sampleRecordCount}; normalizer fixture mappings: ${normalizer.successfulMappings}/${normalizer.fixtureCount}.`
    ],
    recommendations: [
      "Recommendation A: Ready for Shadow Ingestion Planning, provided the next milestone remains audit-only and sanctioned-source-only.",
      "Do not approve production ingestion during V333.",
      "Plan a sanctioned shadow-ingestion design that specifies acquisition mode, allowed storage, attribution, cache/retention windows, replay archive format, and failure/audit reporting.",
      "Keep marker readiness separate from awareness-only records and require marker-grade geometry before any future map display.",
      "Validate recurring export/API lifecycle semantics before any production write path or user-facing behavior."
    ],
    notes: [
      "Readiness review only; no live ingestion, network access, polling, scheduled jobs, Supabase writes, UI, map, routing, alerts, or notification behavior were added.",
      "Static exports, feed exports, and API-based acquisition are evaluated as architecture readiness categories only.",
      "Replay, parser, lifecycle, trust, and vocabulary findings are inherited from V326 through V332."
    ],
    reviewedMilestones: ["V323", "V324", "V325", "V326", "V327", "V328", "V329", "V330", "V331", "V332"],
    rows
  };
}


