    lifecycleRecommendations: { flood_closure: "Activate on official closure; stale after 2-4 hours in active weather; expire on official reopen/end/removal reconciliation.", flood: "Activate on official flood/high-water status; stale after 1-2 hours; expire on official clear/end/removal reconciliation.", closure: "Activate while official closure is current; stale after 6-12 hours unless scheduled; expire on official reopen or end time.", planned_work: "Activate at start time; stale after 24 hours; expire at official end/removal reconciliation.", short_lived: "Activate while current; stale after 30-90 minutes; expire aggressively after removal/end time.", advisory: "Activate while official advisory is current; stale after 2-6 hours; expire on end/removal.", lane_restriction: "Activate during official lane restriction; stale after 24-48 hours; expire at end/removal.", detour: "Attach to parent closure or work-zone lifecycle; do not route users." },
    trustRecommendations: ["Official Source", "Official Source + Community Confirmed", "Official Source + Community Active", "Stale Official Source"],
    travelConfidenceRecommendations: { None: ["other_official when unmapped or informational only"], Low: ["disabled_vehicle"], Moderate: ["travel_advisory", "construction", "crash", "lane_closure", "detour"], High: ["flooded_roadway", "high_water"], Severe: ["road_closed", "bridge_closure", "flood_closure"] },
    lifecycleSimulation: GRIDLY_DRIVETEXAS_LIFECYCLE_SIMULATION.lifecycleSimulation,
