const GRIDLY_ROAD_DISPLAY_UNNORMALIZED_PATTERN = /\b(?:farm[-\s]+to[-\s]+market(?:\s+road)?|farm\s+road|county\s+road|state\s+highway|texas\s+highway|u\.?s\.?\s+highway|us\s+highway|interstate)\s*[- ]?\d+[a-z]?\b/i;

function normalizeGridlyRoadDisplayName(roadName = "") {
  const raw = String(roadName || "").replace(/\s+/g, " ").trim();
  if (!raw) return "";
  const compact = raw
    .replace(/\bwestbound\b|\beastbound\b|\bnorthbound\b|\bsouthbound\b/gi, "")
    .replace(/\s+/g, " ")
    .trim();
  const patterns = [
    { re: /^(?:farm[-\s]+to[-\s]+market(?:\s+road)?|farm\s+road|fm)\s*[- ]?(\d+[a-z]?)$/i, format: (n) => `FM ${n.toUpperCase().replace(/^0+(?=\d)/, "")}` },
    { re: /^(?:county\s+road|cr)\s*[- ]?(\d+[a-z]?)$/i, format: (n) => `CR ${n.toUpperCase().replace(/^0+(?=\d)/, "")}` },
    { re: /^(?:state\s+highway|texas\s+highway|texas\s+state\s+highway|tx)\s*[- ]?(\d+[a-z]?)$/i, format: (n) => `TX ${n.toUpperCase().replace(/^0+(?=\d)/, "")}` },
    { re: /^(?:u\.?s\.?\s+highway|united\s+states\s+highway|us)\s*[- ]?(\d+[a-z]?)$/i, format: (n) => `US ${n.toUpperCase().replace(/^0+(?=\d)/, "")}` },
    { re: /^(?:interstate|ih|i)\s*[- ]?(\d+[a-z]?)$/i, format: (n) => `I-${n.toUpperCase().replace(/^0+(?=\d)/, "")}` }
  ];
  for (const pattern of patterns) {
    const match = compact.match(pattern.re);
    if (match?.[1]) return pattern.format(match[1]);
  }
  return raw;
}

const GRIDLY_ROUTE_PANEL_ENCODING_ARTIFACT_GUARD_VERSION = "V890R.1-route-panel-encoding-artifact-guard";
const GRIDLY_DISPLAY_ENCODING_ARTIFACT_PATTERNS = Object.freeze([
  "\u00c2", "\u00c3", "\ufffd", "\u00e2\u20ac\u00a2", "\u00e2\u20ac\u2122", "\u00e2\u20ac\u0153", "\u00e2\u20ac\ufffd", "\u00e2\u20ac\u201c", "\u00e2\u20ac\u201d"
]);

function cleanupGridlyDisplayEncodingArtifacts(value = "") {
  if (value == null) return "";
  return String(value)
    .replace(/\u00e2\u20ac\u00a2/g, "•")
    .replace(/\u00e2\u20ac\u2122/g, "’")
    .replace(/\u00e2\u20ac\u02dc/g, "‘")
    .replace(/\u00e2\u20ac\u0153/g, "“")
    .replace(/\u00e2\u20ac\ufffd/g, "”")
    .replace(/\u00e2\u20ac\u009d/g, "”")
    .replace(/\u00e2\u20ac\u201c/g, "–")
    .replace(/\u00e2\u20ac\u201d/g, "—")
    .replace(/\u00c2\s*/g, "")
    .replace(/\u00c3\s*/g, "")
    .replace(/\ufffd+/g, "")
    .replace(/[ 	]{2,}/g, " ")
    .trim();
}

function gridlyTextContainsKnownEncodingArtifact(value = "") {
  const text = String(value || "");
  return GRIDLY_DISPLAY_ENCODING_ARTIFACT_PATTERNS.some((pattern) => text.includes(pattern));
}

function normalizeGridlyUserFacingRoadText(value = "") {
  if (value == null) return "";
  if (typeof value === "object") {
    const structured = value.structuredDisplayLocation || value.locationContext || value.location || {};
    const objectDisplayText = value.consumerDisplayLocation
      || value.displayLocation
      || value.canonicalDisplayLocation
      || value.canonicalLocationPhrase
      || value.nearbyLocationPhrase
      || value.authoritativeLocationLabel
      || value.strongestLocationLabel
      || structured.consumerDisplayLocation
      || structured.displayLocation
      || structured.canonicalDisplayLocation
      || structured.canonicalLocationPhrase
      || structured.phrasing
      || structured.primary
      || structured.primaryRoad
      || structured.label
      || structured.name
      || value.displayText
      || value.summary
      || value.headline
      || value.title
      || value.label
      || value.name
      || value.text
      || value.description
      || "";
    return normalizeGridlyUserFacingRoadText(objectDisplayText);
  }
  let text = cleanupGridlyDisplayEncodingArtifacts(value);
  const replacements = [
    { re: /\b(?:farm[-\s]+to[-\s]+market(?:\s+road)?|farm\s+road|fm)\s*[- ]?(\d+[a-z]?)\b/gi, format: (n) => `FM ${n.toUpperCase().replace(/^0+(?=\d)/, "")}` },
    { re: /\b(?:county\s+road|cr)\s*[- ]?(\d+[a-z]?)\b/gi, format: (n) => `CR ${n.toUpperCase().replace(/^0+(?=\d)/, "")}` },
    { re: /\b(?:state\s+highway|texas\s+highway|texas\s+state\s+highway|tx)\s*[- ]?(\d+[a-z]?)\b/gi, format: (n) => `TX ${n.toUpperCase().replace(/^0+(?=\d)/, "")}` },
    { re: /\b(?:u\.?s\.?\s+highway|united\s+states\s+highway|us)\s*[- ]?(\d+[a-z]?)\b/gi, format: (n) => `US ${n.toUpperCase().replace(/^0+(?=\d)/, "")}` },
    { re: /\b(?:interstate|ih|i)\s*[- ]?(\d+[a-z]?)\b/gi, format: (n) => `I-${n.toUpperCase().replace(/^0+(?=\d)/, "")}` }
  ];
  replacements.forEach((rule) => {
    text = text.replace(rule.re, (_match, number) => rule.format(number));
  });
  return text.replace(/\s+/g, " ").trim();
}

function findGridlyRoadDisplayInconsistencies(text = "") {
  const source = String(text || "");
  const findings = [];
  const matcher = new RegExp(GRIDLY_ROAD_DISPLAY_UNNORMALIZED_PATTERN.source, "ig");
  let match;
  while ((match = matcher.exec(source)) && findings.length < 20) {
    findings.push({ text: match[0], normalized: normalizeGridlyRoadDisplayName(match[0]), index: match.index });
  }
  return findings;
}

function gridlyRoadNameStandardizationAudit() {
  const sampleConversions = GRIDLY_ROAD_DISPLAY_STANDARDIZATION_SAMPLES.map(([input, expected]) => {
    const output = normalizeGridlyRoadDisplayName(input);
    return { input, output, expected, matched: output === expected };
  });
  const userFacingSurfacesChecked = [];
  const nestedAlertCardsChecked = [];
  const findings = [];
  const nestedAlertInconsistencyFindings = [];
  if (typeof document !== "undefined" && document?.querySelectorAll) {
    GRIDLY_ROAD_DISPLAY_SURFACE_SELECTORS.forEach((selector) => {
      const nodes = Array.from(document.querySelectorAll(selector));
      userFacingSurfacesChecked.push({ selector, found: nodes.length });
      nodes.forEach((node, index) => {
        const text = String(node?.textContent || "").trim();
        findGridlyRoadDisplayInconsistencies(text).forEach((finding) => {
          findings.push({ surface: selector, nodeIndex: index, ...finding });
        });
      });
    });

    const seenNestedAlertCards = new Set();
    GRIDLY_ROAD_DISPLAY_NESTED_ALERT_CARD_SELECTORS.forEach((selector) => {
      const nodes = Array.from(document.querySelectorAll(selector));
      nestedAlertCardsChecked.push({ selector, found: nodes.length });
      nodes.forEach((node, index) => {
        if (!node || seenNestedAlertCards.has(node)) return;
        seenNestedAlertCards.add(node);
        const text = String(node?.textContent || "").replace(/\s+/g, " ").trim();
        findGridlyRoadDisplayInconsistencies(text).forEach((finding) => {
          const nestedFinding = {
            type: "nested_alert_card_raw_road_name",
            surface: selector,
            nodeIndex: index,
            ...finding
          };
          nestedAlertInconsistencyFindings.push(nestedFinding);
          findings.push(nestedFinding);
        });
      });
    });
  } else {
    userFacingSurfacesChecked.push({ selector: "document", found: 0, note: "DOM unavailable in this environment" });
    nestedAlertCardsChecked.push({ selector: "document", found: 0, note: "DOM unavailable in this environment" });
  }
  const failedSamples = sampleConversions.filter((sample) => !sample.matched);
  const remainingRawRoadNames = [...new Set(findings.map((finding) => finding.text).filter(Boolean))];
  return {
    auditVersion: GRIDLY_ROAD_NAME_STANDARDIZATION_AUDIT_VERSION,
    normalizationRulesLoaded: failedSamples.length === 0,
    sampleConversions,
    userFacingSurfacesChecked,
    nestedAlertCardsChecked,
    nestedAlertInconsistencies: nestedAlertInconsistencyFindings.length,
    remainingRawRoadNames,
    inconsistenciesFound: findings.length + failedSamples.length,
    findings: [
      ...failedSamples.map((sample) => ({ type: "sample_mismatch", ...sample })),
      ...findings
    ]
  };
}

if (typeof window !== "undefined") {
  window.normalizeGridlyRoadDisplayName = normalizeGridlyRoadDisplayName;
  window.normalizeGridlyUserFacingRoadText = normalizeGridlyUserFacingRoadText;
  window.gridlyRoadNameStandardizationAudit = gridlyRoadNameStandardizationAudit;
}

function pickFirstNonEmptyText(values = []) {
  for (const value of values) {
    const text = safeDisplayText(value, "");
    if (text) return text;
  }
  return "";
}

function safeDisplayText(value, fallback = "") {
  const rawFallback = typeof fallback === "string"
    ? fallback
    : (typeof fallback === "number" || typeof fallback === "boolean" ? String(fallback) : "");
  const safeFallback = rawFallback.replace(/\s+/g, " ").trim().toLowerCase() === "[object object]" ? "" : rawFallback;
  if (value == null) return normalizeGridlyUserFacingRoadText(safeFallback);
  if (typeof value === "string") {
    const text = normalizeGridlyUserFacingRoadText(value.replace(/\s+/g, " ").trim());
    return text && text.toLowerCase() !== "[object object]" ? text : normalizeGridlyUserFacingRoadText(safeFallback);
  }
  if (typeof value === "number" || typeof value === "boolean") return String(value);
  if (Array.isArray(value)) {
    const joined = value.map((entry) => safeDisplayText(entry, "")).filter(Boolean).join(" ");
    return joined || normalizeGridlyUserFacingRoadText(safeFallback);
  }
  if (typeof value === "object") {
    const candidate =
      value.displayText ||
      value.summary ||
      value.headline ||
      value.title ||
      value.label ||
      value.name ||
      value.text ||
      value.description;
    return safeDisplayText(candidate, safeFallback);
  }
  return normalizeGridlyUserFacingRoadText(safeFallback);
}

function gridlyHistoricalClosePathDurationBucket(durationMinutes) {
  const minutes = Number(durationMinutes);
  if (!Number.isFinite(minutes) || minutes < 0) return null;
  if (minutes < 15) return "0-15 min";
  if (minutes < 60) return "15-60 min";
  if (minutes < 240) return "1-4 hr";
  if (minutes < 720) return "4-12 hr";
  if (minutes < 1440) return "12-24 hr";
  return "24+ hr";
}

function gridlyHistoricalClosePathSimulation(options = {}) {
  const nowMs = Number.isFinite(Number(options?.nowMs)) ? Number(options.nowMs) : Date.now();
  const nowIso = new Date(nowMs).toISOString();
  const minutesAgoIso = (minutes) => new Date(nowMs - (Number(minutes) * 60000)).toISOString();

  const simulatedCloseEvents = [
    {
      caseId: "A",
      incidentId: "sim-hazard-driver-clear",
      hazardType: "road_hazard",
      roadName: "US 90",
      crossingName: "",
      createdAt: minutesAgoIso(20),
      clearedAt: nowIso,
      expectedCloseState: "CLEARED_BY_DRIVER",
      closeState: "CLEARED_BY_DRIVER",
      closeReason: "Driver reported the hazard cleared in the simulation.",
      confirmationCount: 1,
      source: "driver_clear_simulation",
      locationKey: "road_hazard|us-90"
    },
    {
      caseId: "B",
      incidentId: "sim-hazard-community-clear",
      hazardType: "debris",
      roadName: "FM 1960",
      crossingName: "",
      createdAt: minutesAgoIso(120),
      clearedAt: nowIso,
      expectedCloseState: "CLEARED_BY_COMMUNITY",
      closeState: "CLEARED_BY_COMMUNITY",
      closeReason: "Multiple community confirmations reported clear in the simulation.",
      confirmationCount: 3,
      source: "community_clear_simulation",
      locationKey: "debris|fm-1960"
    },
    {
      caseId: "C",
      incidentId: "sim-crossing-quick-clear",
      hazardType: "rail_crossing_blocked",
      roadName: "Main Street",
      crossingName: "Main Street Crossing",
      createdAt: minutesAgoIso(10),
      clearedAt: nowIso,
      expectedCloseState: "CLEARED_BY_DRIVER",
      closeState: "CLEARED_BY_DRIVER",
      closeReason: "Blocked crossing was reported clear quickly in the simulation.",
      confirmationCount: 1,
      source: "driver_crossing_clear_simulation",
      locationKey: "main-street-crossing"
    },
    {
      caseId: "D",
      incidentId: "sim-trusted-source-closure",
      hazardType: "road_closure",
      roadName: "SH 146",
      crossingName: "",
      createdAt: minutesAgoIso(360),
      clearedAt: nowIso,
      expectedCloseState: "CLEARED_BY_TRUSTED_SOURCE",
      closeState: "CLEARED_BY_TRUSTED_SOURCE",
      closeReason: "Trusted-source closure resolved in the simulation.",
      confirmationCount: 1,
      source: "trusted_source_simulation",
      locationKey: "road_closure|sh-146"
    },
    {
      caseId: "E",
      incidentId: "sim-expired-unconfirmed",
      hazardType: "unconfirmed_hazard",
      roadName: "CR 2145",
      crossingName: "",
      createdAt: minutesAgoIso(1800),
      clearedAt: nowIso,
      expectedCloseState: "EXPIRED_UNCONFIRMED",
      closeState: "EXPIRED_UNCONFIRMED",
      closeReason: "Old unconfirmed hazard reached the simulated expiration state; clearedAt is a simulated terminal timestamp, not a live clear write.",
      confirmationCount: 0,
      source: "expiration_policy_simulation",
      locationKey: "unconfirmed_hazard|cr-2145"
    },
    {
      caseId: "F",
      incidentId: "sim-missing-cleared-at",
      hazardType: "road_hazard",
      roadName: "FM 1010",
      crossingName: "",
      createdAt: minutesAgoIso(60),
      clearedAt: null,
      expectedCloseState: "ACTIVE",
      closeState: "ACTIVE",
      closeReason: "Malformed simulated record is missing clearedAt and remains duration-ineligible.",
      confirmationCount: 1,
      source: "malformed_record_simulation",
      locationKey: "road_hazard|fm-1010"
    },
    {
      caseId: "G",
      incidentId: "sim-missing-created-at",
      hazardType: "debris",
      roadName: "Loop 494",
      crossingName: "",
      createdAt: null,
      clearedAt: nowIso,
      expectedCloseState: "ACTIVE",
      closeState: "ACTIVE",
      closeReason: "Malformed simulated record is missing createdAt and remains duration-ineligible.",
      confirmationCount: 1,
      source: "malformed_record_simulation",
      locationKey: "debris|loop-494"
    }
  ];

  const expectations = {
    A: { expectedCloseState: "CLEARED_BY_DRIVER", expectedDurationBucket: "15-60 min" },
    B: { expectedCloseState: "CLEARED_BY_COMMUNITY", expectedDurationBucket: "1-4 hr" },
    C: { expectedCloseState: "CLEARED_BY_DRIVER", expectedDurationBucket: "0-15 min" },
    D: { expectedCloseState: "CLEARED_BY_TRUSTED_SOURCE", expectedDurationBucket: "4-12 hr" },
    E: { expectedCloseState: "EXPIRED_UNCONFIRMED", expectedDurationBucket: "24+ hr" },
    F: { expectedCloseState: "ACTIVE", expectedDurationBucket: null },
    G: { expectedCloseState: "ACTIVE", expectedDurationBucket: null }
  };

  const durationCalculations = simulatedCloseEvents.map((event) => {
    const durationMinutes = gridlyMinutesBetween(event.createdAt, event.clearedAt);
    const durationEligible = durationMinutes !== null && Number.isFinite(Number(durationMinutes));
    return {
      caseId: event.caseId,
      incidentId: event.incidentId,
      createdAt: event.createdAt,
      clearedAt: event.clearedAt,
      durationMinutes,
      durationBucket: durationEligible ? gridlyHistoricalClosePathDurationBucket(durationMinutes) : null,
      durationEligible,
      calculationOnly: true,
      storageWritePerformed: false,
      runtimeActivationPerformed: false
    };
  });

  const calculationByCase = durationCalculations.reduce((acc, calculation) => {
    acc[calculation.caseId] = calculation;
    return acc;
  }, {});

  const simulatedHistoricalRecords = simulatedCloseEvents.flatMap((event) => {
    const calculation = calculationByCase[event.caseId];
    if (!calculation?.durationEligible) return [];
    return [{
      incidentId: event.incidentId,
      hazardType: event.hazardType,
      roadName: event.roadName,
      crossingName: event.crossingName,
      createdAt: event.createdAt,
      clearedAt: event.clearedAt,
      durationMinutes: calculation.durationMinutes,
      durationBucket: calculation.durationBucket,
      confirmationCount: event.confirmationCount,
      source: event.source,
      closeState: event.closeState,
      closeReason: event.closeReason,
      locationKey: event.locationKey
    }];
  });

  const historicalRecordCases = simulatedHistoricalRecords.reduce((acc, record) => {
    const sourceEvent = simulatedCloseEvents.find((event) => event.incidentId === record.incidentId);
    if (sourceEvent?.caseId) acc[sourceEvent.caseId] = true;
    return acc;
  }, {});

  const validationResults = simulatedCloseEvents.map((event) => {
    const expected = expectations[event.caseId] || {};
    const calculation = calculationByCase[event.caseId] || {};
    const actualDurationBucket = calculation.durationBucket || null;
    const actualCloseState = event.closeState;
    const durationEligible = Boolean(calculation.durationEligible);
    const historicalRecordCreated = Boolean(historicalRecordCases[event.caseId]);
    return {
      caseId: event.caseId,
      expectedCloseState: expected.expectedCloseState || event.expectedCloseState,
      actualCloseState,
      expectedDurationBucket: expected.expectedDurationBucket || null,
      actualDurationBucket,
      durationMinutes: calculation.durationMinutes !== null && Number.isFinite(Number(calculation.durationMinutes)) ? calculation.durationMinutes : null,
      durationEligible,
      historicalRecordCreated,
      matched: actualCloseState === (expected.expectedCloseState || event.expectedCloseState)
        && actualDurationBucket === (expected.expectedDurationBucket || null)
        && historicalRecordCreated === durationEligible,
      destructiveActionTaken: false
    };
  });

  const allMatched = validationResults.every((result) => result.matched && result.destructiveActionTaken === false);
  const futureActivationReview = {
    activationBenefits: [
      "Proves createdAt plus clearedAt can produce deterministic durationMinutes and duration buckets.",
      "Shows the historical record shape can preserve source, confirmation, location, and close provenance.",
      "Provides a safe fixture for future side-by-side write audits before any live close-path activation."
    ],
    activationRisks: [
      "Live activation could still mis-match a clear report to the wrong active incident without stronger identity checks.",
      "Expired-unconfirmed terminal timestamps must remain distinct from true clear timestamps in analytics.",
      "Sparse driver clear reports may bias duration averages until real coverage is measured."
    ],
    telemetryImpact: "None in this simulation; no counters, telemetry schema, beacon, or storage writes are touched.",
    analyticsImpact: "None in this simulation; duration and bucket outputs are returned only as in-memory simulated objects.",
    betaReadinessAssessment: allMatched
      ? "Simulation-ready: close-path duration math and record shaping validate against all expected simulated cases, but runtime activation still requires a separate side-by-side write audit."
      : "Not ready: one or more simulated close-path validations failed and must be corrected before any activation review.",
    safestNextStep: "Keep the helper read-only and use it as an audit fixture for the next side-by-side historical write review; do not activate live writes, storage, analytics, telemetry, alerts, or map changes from this simulation."
  };

  const recommendations = {
    simulationOnly: true,
    storageWritesPerformed: false,
    runtimeActivationPerformed: false,
    protectedSystemsChanged: false,
    allValidationCasesMatched: allMatched,
    futureActivationReview
  };

  return {
    simulatedCloseEvents,
    simulatedHistoricalRecords,
    durationCalculations,
    validationResults,
    recommendations
  };
}


function gridlyHistoricalCloseWriteAuditIso(value) {
  const ms = new Date(value || 0).getTime();
  return Number.isFinite(ms) && ms > 0 ? new Date(ms).toISOString() : null;
}

function gridlyHistoricalCloseWriteAuditCreatedAt(record = {}, type = "hazard") {
  if (type === "crossing" || record?.crossingId || record?.crossing_id) {
    return gridlyHistoricalCloseWriteAuditIso(record.blockedAt || record.createdAt || record.created_at || record.submittedAt || record.reportedAt || record.timestamp || record.updatedAt || record.updated_at);
  }
  return gridlyHistoricalCloseWriteAuditIso(record.createdAt || record.created_at || record.submittedAt || record.reportedAt || record.timestamp || record.updatedAt || record.updated_at || record.blockedAt);
}

function gridlyHistoricalCloseWriteAuditClearedAt(record = {}) {
  return gridlyHistoricalCloseWriteAuditIso(record.clearedAt || record.cleared_at || record.resolvedAt || record.resolved_at || record.closedAt || record.closed_at);
}

function gridlyHistoricalCloseWriteAuditRoadName(record = {}, type = "hazard") {
  if (type === "crossing" || record?.crossingId || record?.crossing_id) {
    const crossingId = record?.crossingId || record?.crossing_id || "";
    const metadata = gridlyGetCrossingHistoryMetadata(crossingId, record);
    return gridlyNormalizeAnalyticsRoadLabel(record?.roadName || record?.road || metadata.roadName) || metadata.roadName || "Unknown road";
  }
  const road = gridlyHistoricalAuditRoad(record) || gridlyGetHazardHistoryMetadata(record).roadName || record?.road || "Unknown road";
  return gridlyNormalizeAnalyticsRoadLabel(road) || road || "Unknown road";
}

function gridlyHistoricalCloseWriteAuditCrossingName(record = {}, type = "hazard") {
  if (!(type === "crossing" || record?.crossingId || record?.crossing_id)) return "";
  const metadata = gridlyGetCrossingHistoryMetadata(record?.crossingId || record?.crossing_id || "", record);
  return String(record?.crossingName || record?.crossing || metadata.crossingName || "").trim();
}

function gridlyHistoricalCloseWriteAuditHazardType(record = {}, type = "hazard") {
  if (type === "crossing" || record?.crossingId || record?.crossing_id) return "rail_crossing_blocked";
  return gridlyNormalizeHazardType(record) || gridlyHistoricalAuditHazardType(record) || "unknown";
}

function gridlyHistoricalCloseWriteAuditIncidentId(record = {}, type = "hazard", fallback = "candidate") {
  if (type === "crossing" || record?.crossingId || record?.crossing_id) {
    return String(record?.incidentId || record?.id || record?.reportId || record?.crossingId || record?.crossing_id || fallback).trim();
  }
  return String(record?.incidentId || record?.id || record?.reportId || record?.crossingId || record?.crossing_id || (typeof getHazardClusterKey === "function" ? getHazardClusterKey(record) : fallback)).trim();
}

function gridlyHistoricalCloseWriteAuditSource(record = {}, sourceKind = "unknown") {
  return String(record?.source || record?.provider || record?.reportSource || record?.submittedBy || sourceKind || "unknown").trim() || "unknown";
}

function gridlyHistoricalCloseWriteAuditLocationKey(record = {}, type = "hazard") {
  if (type === "crossing" || record?.crossingId || record?.crossing_id) {
    return String(record?.crossingId || record?.crossing_id || gridlyHistoricalCloseWriteAuditCrossingName(record, "crossing") || gridlyHistoricalCloseWriteAuditRoadName(record, "crossing") || "").trim().toLowerCase();
  }
  return [gridlyHistoricalCloseWriteAuditHazardType(record, type), gridlyHistoricalCloseWriteAuditRoadName(record, type)]
    .filter(Boolean)
    .join("|")
    .toLowerCase();
}

function gridlyHistoricalCloseWriteAuditCurrentState(record = {}, sourceKind = "activeHazards") {
  const explicitState = String(record?.lifecycleState || record?.lifecycle || record?.status || record?.state || "").trim();
  if (explicitState) return explicitState;
  const type = String(record?.type || record?.report_type || record?.eventType || "").trim();
  if (isClearedReportType(type) || gridlyHistoricalCloseWriteAuditClearedAt(record)) return "cleared";
  if (sourceKind === "historicalCrossingEvents" || sourceKind === "historicalHazardEvents") return "open_history_record";
  if (sourceKind === "activeReports" && typeof getIncidentLifecycleState === "function") return getIncidentLifecycleState(record) || "active";
  if (sourceKind === "activeHazards" && typeof gridlyIsActiveHazardRecord === "function") return gridlyIsActiveHazardRecord(record) ? "active" : "inactive_or_expired";
  return "active";
}

function gridlyHistoricalCloseWriteAuditCloseReason(record = {}, sourceKind = "unknown", currentState = "active") {
  if (gridlyHistoricalCloseWriteAuditClearedAt(record)) return "Existing cleared timestamp would be preserved as close provenance.";
  if (sourceKind === "historicalCrossingEvents" || sourceKind === "historicalHazardEvents") return "Open historical event would receive a close timestamp during a future close transition.";
  if (String(currentState).toLowerCase().includes("expired")) return "Expired or inactive record would only be eligible if a future close policy explicitly selected it.";
  return "Active record would receive a close timestamp only after a future explicit close transition.";
}

function gridlyHistoricalCloseWriteAuditCandidateFromRecord(record = {}, sourceKind = "activeHazards", index = 0, nowIso = new Date().toISOString()) {
  const type = sourceKind === "activeReports" || sourceKind === "historicalCrossingEvents" || record?.crossingId || record?.crossing_id ? "crossing" : "hazard";
  const createdAt = gridlyHistoricalCloseWriteAuditCreatedAt(record, type);
  const currentState = gridlyHistoricalCloseWriteAuditCurrentState(record, sourceKind);
  const closeReason = gridlyHistoricalCloseWriteAuditCloseReason(record, sourceKind, currentState);
  const candidateId = `${sourceKind}:${gridlyHistoricalCloseWriteAuditIncidentId(record, type, `${type}-${index}`) || `${type}-${index}`}`;
  return {
    candidateId,
    type,
    sourceKind,
    recordIndex: index,
    incidentId: gridlyHistoricalCloseWriteAuditIncidentId(record, type, `${type}-${index}`),
    roadName: gridlyHistoricalCloseWriteAuditRoadName(record, type),
    crossingName: gridlyHistoricalCloseWriteAuditCrossingName(record, type),
    createdAt,
    currentState,
    closeEligibilityReason: closeReason,
    hypotheticalClearedAt: nowIso,
    sourceRecord: record
  };
}

function gridlyHistoricalCloseWriteAuditCandidateEligible(record = {}, sourceKind = "activeHazards") {
  const typeText = String(record?.type || record?.report_type || record?.eventType || "").toLowerCase();
  if (isClearedReportType(typeText) || gridlyHistoricalCloseWriteAuditClearedAt(record)) return false;
  if (sourceKind === "historicalCrossingEvents" || sourceKind === "historicalHazardEvents") return true;
  if (sourceKind === "activeReports") return typeof getIncidentLifecycleState === "function" ? getIncidentLifecycleState(record) === "active" : true;
  if (sourceKind === "activeHazards") return typeof gridlyIsActiveHazardRecord === "function" ? gridlyIsActiveHazardRecord(record) : true;
  gridlyAlertsOpenAuditFinish({ opened: false, path: "unavailable" });
  return false;
}

function gridlyHistoricalCloseWriteAuditProposedRecord(candidate = {}) {
  const record = candidate.sourceRecord || {};
  const createdAt = candidate.createdAt || null;
  const clearedAt = candidate.hypotheticalClearedAt || null;
  const durationMinutes = gridlyMinutesBetween(createdAt, clearedAt);
  const durationEligible = Number.isFinite(Number(durationMinutes));
  const confirmationCount = candidate.type === "crossing"
    ? gridlyCountCrossingConfirmations(record.crossingId || record.crossing_id || candidate.incidentId, activeReports)
    : gridlyHazardLifecycleConfirmationCount(record, candidate.sourceKind === "activeReports" ? "activeReports" : "activeHazards", activeHazards, activeReports);
  return {
    incidentId: candidate.incidentId,
    hazardType: gridlyHistoricalCloseWriteAuditHazardType(record, candidate.type),
    roadName: candidate.roadName,
    crossingName: candidate.crossingName,
    createdAt,
    clearedAt,
    durationMinutes: durationEligible ? durationMinutes : null,
    durationBucket: durationEligible ? gridlyHistoricalClosePathDurationBucket(durationMinutes) : null,
    confirmationCount: Number.isFinite(Number(confirmationCount)) ? Number(confirmationCount) : 0,
    source: gridlyHistoricalCloseWriteAuditSource(record, candidate.sourceKind),
    closeState: "PENDING_FUTURE_CLOSE_TRANSITION",
    closeReason: candidate.closeEligibilityReason,
    locationKey: gridlyHistoricalCloseWriteAuditLocationKey(record, candidate.type),
    auditOnly: true,
    storageWritePerformed: false,
    runtimeActivationPerformed: false
  };
}

function gridlyHistoricalCloseWriteAuditComparison(candidate = {}, proposed = {}) {
  const record = candidate.sourceRecord || {};
  const currentFields = {
    incidentId: gridlyHistoricalCloseWriteAuditIncidentId(record, candidate.type, candidate.incidentId),
    hazardType: gridlyHistoricalCloseWriteAuditHazardType(record, candidate.type),
    roadName: candidate.roadName,
    crossingName: candidate.crossingName,
    createdAt: candidate.createdAt,
    clearedAt: gridlyHistoricalCloseWriteAuditClearedAt(record),
    durationMinutes: Number.isFinite(Number(record?.durationMinutes)) ? Number(record.durationMinutes) : null,
    confirmationCount: Number.isFinite(Number(record?.confirmationCount ?? record?.confirmations ?? record?.confirmation_count)) ? Number(record?.confirmationCount ?? record?.confirmations ?? record?.confirmation_count) : null,
    source: gridlyHistoricalCloseWriteAuditSource(record, candidate.sourceKind),
    closeState: record?.closeState || record?.lifecycleState || record?.status || null,
    closeReason: record?.closeReason || null,
    locationKey: gridlyHistoricalCloseWriteAuditLocationKey(record, candidate.type)
  };
  const required = ["incidentId", "hazardType", "roadName", "createdAt", "clearedAt", "durationMinutes", "durationBucket", "confirmationCount", "source", "closeState", "closeReason", "locationKey"];
  const missingFields = required.filter((field) => proposed[field] === null || proposed[field] === undefined || proposed[field] === "");
  const durationEligible = Number.isFinite(Number(proposed.durationMinutes));
  return {
    candidateId: candidate.candidateId,
    currentFields,
    proposedFields: proposed,
    missingFields,
    durationEligible,
    readiness: missingFields.length === 0 && durationEligible ? "READY_FOR_FUTURE_CLOSE_WRITE_SHAPE" : (durationEligible ? "PARTIAL_MISSING_OPTIONAL_OR_PROVENANCE_FIELDS" : "NOT_READY_MISSING_DURATION_INPUTS")
  };
}

function gridlyHistoricalCloseWriteAudit(options = {}) {
  const nowMs = Number.isFinite(Number(options?.nowMs)) ? Number(options.nowMs) : Date.now();
  const nowIso = new Date(nowMs).toISOString();
  const storageSnapshot = gridlyReadHistoricalIntelligenceStorageSnapshot();
  const historicalState = storageSnapshot.state || gridlyCreateEmptyEventHistoryState();
  const historicalCrossingEvents = Array.isArray(historicalState.crossingEvents) ? historicalState.crossingEvents : [];
  const historicalHazardEvents = Array.isArray(historicalState.hazardEvents) ? historicalState.hazardEvents : [];
  const candidateSources = [
    { sourceKind: "activeHazards", records: Array.isArray(activeHazards) ? activeHazards : [] },
    { sourceKind: "activeReports", records: Array.isArray(activeReports) ? activeReports : [] },
    { sourceKind: "historicalHazardEvents", records: historicalHazardEvents },
    { sourceKind: "historicalCrossingEvents", records: historicalCrossingEvents }
  ];
  const candidateRecords = candidateSources.flatMap((source) => source.records
    .map((record, index) => ({ record, index }))
    .filter(({ record }) => gridlyHistoricalCloseWriteAuditCandidateEligible(record, source.sourceKind))
    .map(({ record, index }) => gridlyHistoricalCloseWriteAuditCandidateFromRecord(record, source.sourceKind, index, nowIso)));
  const proposedHistoricalWrites = candidateRecords.map((candidate) => gridlyHistoricalCloseWriteAuditProposedRecord(candidate));
  const writeComparisons = candidateRecords.map((candidate, index) => gridlyHistoricalCloseWriteAuditComparison(candidate, proposedHistoricalWrites[index]));
  const canPopulate = (field) => writeComparisons.filter((comparison) => comparison.proposedFields[field] !== null && comparison.proposedFields[field] !== undefined && comparison.proposedFields[field] !== "").length;
  const validationResults = {
    candidateCount: candidateRecords.length,
    proposedWriteCount: proposedHistoricalWrites.length,
    historicalRecordsInspected: historicalCrossingEvents.length + historicalHazardEvents.length,
    activeHazardsInspected: Array.isArray(activeHazards) ? activeHazards.length : 0,
    activeReportsInspected: Array.isArray(activeReports) ? activeReports.length : 0,
    canPopulateCounts: {
      createdAt: canPopulate("createdAt"),
      clearedAt: canPopulate("clearedAt"),
      durationMinutes: canPopulate("durationMinutes"),
      closeState: canPopulate("closeState"),
      closeReason: canPopulate("closeReason"),
      locationKey: canPopulate("locationKey")
    },
    durationEligibleCount: writeComparisons.filter((comparison) => comparison.durationEligible).length,
    missingCreatedAtCount: writeComparisons.filter((comparison) => comparison.missingFields.includes("createdAt")).length,
    missingLocationKeyCount: writeComparisons.filter((comparison) => comparison.missingFields.includes("locationKey")).length,
    allCandidatesDurationEligible: writeComparisons.length > 0 && writeComparisons.every((comparison) => comparison.durationEligible),
    storageWritePerformed: false,
    runtimeActivationPerformed: false,
    destructiveActionTaken: false
  };
  const recommendations = {
    currentWriteReadiness: writeComparisons.length > 0 && writeComparisons.every((comparison) => comparison.missingFields.length === 0) ? "READY_SHAPE_ONLY" : "PARTIAL_AUDIT_ONLY",
    durationWriteReadiness: validationResults.candidateCount > 0 && validationResults.durationEligibleCount === validationResults.candidateCount ? "READY_WHEN_CLOSE_TIMESTAMP_EXISTS" : "BLOCKED_BY_MISSING_CREATED_AT_OR_CLOSE_TIMESTAMP",
    closeStateReadiness: validationResults.canPopulateCounts.closeState === validationResults.candidateCount ? "AUDIT_PLACEHOLDER_AVAILABLE" : "NEEDS_REAL_CLOSE_STATE_MAPPING_BEFORE_ACTIVATION",
    activationBenefits: [
      "Would turn explicit close transitions into deterministic durationMinutes and durationBucket values.",
      "Would preserve side-by-side provenance for road, crossing, source, confirmation, close state, and location key.",
      "Would let future historical intelligence reason over cleared events instead of open-ended active records."
    ],
    activationRisks: [
      "A real close path still needs exact matching between a clear signal and the intended active record.",
      "Placeholder closeState values in this audit are not sufficient for analytics activation.",
      "Historical storage writes should remain disabled until close reason and identity matching are product-approved."
    ],
    safestNextStep: "Keep this helper audit-only; next add a non-writing close-state mapping fixture with explicit identity matching before enabling any storage, analytics, telemetry, UI, or lifecycle activation.",
    auditOnly: true,
    storageWritesPerformed: false,
    runtimeActivationPerformed: false
  };
  return {
    candidateRecords: candidateRecords.map(({ sourceRecord, ...candidate }) => candidate),
    proposedHistoricalWrites,
    writeComparisons,
    validationResults,
    recommendations
  };
}

if (typeof window !== "undefined") {
  window.safeDisplayText = safeDisplayText;
}

function gridlyCollectIncidentText(incident = {}) {
  if (!incident || typeof incident !== "object") return "";
  return [
    incident.type, incident.report_type, incident.reportKind, incident.title, incident.description,
    incident.notes, incident.category, incident.source, incident.status, incident.condition,
    incident.crossingStatus, incident.crossing_status
  ].map((value) => String(value || "").toLowerCase()).join(" ");
}

function isGridlyRailShapedObject(input = {}) {
  if (!input || typeof input !== "object") return false;
  const hasLatLng = Number.isFinite(Number(input?.lat)) && Number.isFinite(Number(input?.lng));
  const hasCrossingIdentity = Boolean(input?.crossingId || input?.crossingName || input?.crossingNumber);
  const hasRailroad = Boolean(String(input?.railroad || "").trim());
  const hasStaticCrossingShape = hasLatLng && hasRailroad && Boolean(input?.name || input?.originalName);
  const reportKindText = String(input?.reportKind || input?.type || input?.status || "").toLowerCase();
  const hasRailReportKind = /rail|crossing|train|blocked/.test(reportKindText);
  return hasCrossingIdentity || hasStaticCrossingShape || (hasLatLng && hasRailroad) || hasRailReportKind;
}

function normalizeGridlyIncidentCategory(input) {
  if (input && typeof input === "object") {
    const explicitCategory = [input.type, input.report_type, input.reportType, input.hazardType, input.category, input.hazardCategory]
      .map((value) => String(value || "").trim().toLowerCase().replace(/[\s-]+/g, "_"))
      .find(Boolean);
    if (explicitCategory === "rail_issue") return "rail_issue";
    if (explicitCategory === "traffic_backup") return "traffic_backup";
    if (explicitCategory === "disabled_vehicle") return "disabled_vehicle";
    if (explicitCategory !== "rail_blockage_delay" && HAZARD_TYPES[explicitCategory]) return explicitCategory;
  }
  if (isGridlyRailShapedObject(input)) return "rail";
  const raw = typeof input === "object" && input
    ? [
      input.condition,
      input.conditionType,
      input.title,
      input.description,
      input.detail,
      input.category,
      input.eventType,
      input.externalSource,
      input.provider,
      input.source
    ].map((value) => String(value || "")).join(" ")
    : String(input || "");
  const trimmedRaw = String(raw || "").trim();
  if (!trimmedRaw) return "unknown";
  const value = trimmedRaw.toLowerCase().replace(/[_-]+/g, " ").replace(/\s+/g, " ").trim();
  const compact = value.replace(/\s+/g, "");
  const txdotLike = /txdot|drivetexas|drive texas/.test(value);

  if (/rail issue|crossing malfunction|gate issue|signal issue|rail infrastructure/.test(value) && !/train blocking|blocked crossing|crossing blocked/.test(value)) return "rail_issue";
  if (/blocked crossing|crossing blocked|train blocking|active rail report|fra crossing|crossing id|crossing number/.test(value)) return "rail";
  if (/\brail\b/.test(value) && /crossing|train|blocked|fra/.test(value)) return "rail";
  if (/standing water/.test(value)) return txdotLike ? "txdot_flooding" : "standing_water";
  if (/fallen tree|down(ed)? tree|tree in road/.test(value)) return "fallen_tree";
  if (/signal outage|traffic signal|signal out/.test(value)) return "signal_outage";
  if (/utility work|power line|downed line/.test(value)) return "utility_work";
  if (/emergency response impact|crash response|fire blocking road|ambulance delay/.test(value)) return "emergency_response_impact";
  if (/traffic backup|heavy traffic|traffic delay|severe delay|major congestion|unexpected backup/.test(value)) return "traffic_backup";
  if (/wreck|crash|collision/.test(value)) return "crash";
  if (/flood|high water|impassable/.test(value)) return txdotLike ? "txdot_flooding" : "flooding";
  if (/ice|black ice/.test(value)) return "ice";
  if (/debris|obstruction/.test(value)) return "debris";
  if (/construction/.test(value)) return txdotLike ? "txdot_construction" : "construction";
  if (/disabled vehicle|stalled|vehicle disabled/.test(value)) return "disabled_vehicle";
  if (/damage|washout|road damage/.test(value)) return txdotLike ? "txdot_damage" : "unknown";
  if (/closure|closed|road closed/.test(value)) return txdotLike ? "txdot_closure" : "road_closed";
  if (/road hazard/.test(value)) return "unknown";
  if (/other/.test(value) && txdotLike) return "txdot_other";
  const underscoredValue = value.replace(/\s+/g, "_");
  if (compact in HAZARD_CATEGORY_MAP || underscoredValue in HAZARD_CATEGORY_MAP) {
    const mapped = HAZARD_CATEGORY_MAP[compact] || HAZARD_CATEGORY_MAP[underscoredValue];
    if (mapped === "rail_blockage_delay") return "rail";
    if (mapped === "rail_issue") return "rail_issue";
    if (mapped === "traffic_backup") return "traffic_backup";
    if (mapped === "other_hazard") return "unknown";
    if (GRIDLY_NORMALIZED_INCIDENT_CATEGORIES.has(mapped)) return mapped;
  }
  return txdotLike ? "txdot_other" : "unknown";
}


function normalizeGridlyTxdotVisualCategory(category = "unknown", incident = {}) {
  const normalized = String(category || "").toLowerCase().trim();
  if (["txdot_construction", "txdot_closure", "txdot_flooding", "txdot_damage", "txdot_other"].includes(normalized)) {
    return normalized;
  }

  const value = [
    normalized,
    incident?.condition,
    incident?.conditionType,
    incident?.title,
    incident?.description,
    incident?.detail,
    incident?.category,
    incident?.eventType,
    incident?.externalSource,
    incident?.provider,
    incident?.source
  ].map((item) => String(item || "").toLowerCase()).join(" ").replace(/[_-]+/g, " ").replace(/\s+/g, " ").trim();

  if (/construction|utility work|road work|maintenance/.test(value)) return "txdot_construction";
  if (/road closed|closure|\bclosed\b/.test(value)) return "txdot_closure";
  if (/flooding|high water|\bice\b|weather|standing water|impassable/.test(value)) return "txdot_flooding";
  if (/damage|debris|pothole|road damage|washout|obstruction/.test(value)) return "txdot_damage";
  if (/crash|signal outage|disabled vehicle|stalled|unknown|other/.test(value)) return "txdot_other";

  return "txdot_other";
}

function normalizeGridlyCommunityVisualCategory(category = "unknown") {
  const normalized = String(category || "").toLowerCase().trim();
  const allowedCommunityCategories = new Set([
    "flooding",
    "ice",
    "debris",
    "crash",
    "construction",
    "road_closed",
    "disabled_vehicle",
    "traffic_backup",
    "standing_water",
    "fallen_tree",
    "signal_outage",
    "utility_work",
    "emergency_response_impact",
    "unknown"
  ]);
  if (allowedCommunityCategories.has(normalized)) return normalized;
  if (!normalized.startsWith("txdot_")) return "unknown";
  if (normalized === "txdot_flooding") return "flooding";
  if (normalized === "txdot_construction") return "construction";
  if (normalized === "txdot_closure") return "road_closed";
  if (normalized === "txdot_damage") return "debris";
  if (normalized === "txdot_other") return "unknown";
  return "unknown";
}

function getGridlyIncidentSeverity(incident = {}, category = "unknown") {
  const text = gridlyCollectIncidentText(incident);
  const isMinor = /minor|small|fender bender/.test(text);
  const severeFlooding = /severe flooding|flooded road|impassable|swift water/.test(text);
  const routeImpact = Boolean(incident?.routeImpact) || /blocking road|blocked road|all lanes|closure|detour|route impact/.test(text);
  const blockedRail = /blocked crossing|train blocking|stopped train|closed crossing|\bblocked\b|\bclosed\b|\bstopped\b/.test(text);
  const clearRail = /clear crossing|crossing clear|\bclear\b|\bopen\b|no blockage/.test(text);
  const staticRail = isGridlyRailShapedObject(incident) && !incident?.crossingId && !incident?.reportKind && !incident?.title && !incident?.description && !incident?.status;

  if (routeImpact) return "critical";
  if (category === "road_closed" || category === "txdot_closure") return "critical";
  if (severeFlooding) return "critical";
  if (category === "rail" && routeImpact) return "critical";
  if (category === "rail" && blockedRail) return "high";
  if (category === "rail" && (staticRail || clearRail)) return "low";
  if (category === "rail") return "moderate";
  if (category === "crash") return isMinor ? "moderate" : "high";
  if (category === "flooding" || category === "txdot_flooding") return "high";
  if (category === "ice") return "high";
  if (category === "construction" || category === "txdot_construction") return "moderate";
  if (category === "traffic_backup") return "moderate";
  if (category === "disabled_vehicle") return "moderate";
  if (category === "debris") return isMinor ? "low" : "moderate";
  if (category === "standing_water" || category === "fallen_tree" || category === "signal_outage" || category === "utility_work" || category === "emergency_response_impact") return "moderate";
  return "low";
}

function getGridlyZoomBehavior(category = "unknown", severity = "low", incident = {}) {
  const text = gridlyCollectIncidentText(incident);
  const routeImpact = Boolean(incident?.routeImpact) || /route impact|blocking road|closure|detour|all lanes/.test(text);
  const railClear = /clear crossing|crossing clear|\bclear\b|\bopen\b/.test(text)
    || (isGridlyRailShapedObject(incident) && !/blocked|train blocking|stopped|closed/.test(text));
  if (category === "rail" && (routeImpact || severity === "critical")) return "far";
  if (category === "rail" && (/blocked crossing|train blocking|stopped train|closed crossing|\bblocked\b|\bclosed\b|\bstopped\b/.test(text) || severity === "high")) return "mid";
  if (category === "rail" && railClear) return "near";
  if (severity === "critical" && routeImpact) return "far";
  if (severity === "high" || severity === "moderate") return "mid";
  return "near";
}


