window.gridlyAwarenessPhraseAudit = function gridlyAwarenessPhraseAudit(options = {}) {
  try {
    const rawAwarenessMode = String(options?.awarenessMode || (typeof getGridlyAwarenessMode === "function" ? getGridlyAwarenessMode(options) : "community")).toLowerCase();
    const awarenessMode = ["route", "community", "hybrid"].includes(rawAwarenessMode) ? rawAwarenessMode : "community";
    const markerPane = typeof document !== "undefined" ? document.querySelector("#map .leaflet-marker-pane") : null;
    const selectedDomNodes = getGridlyDomBridgeAuditTargets(markerPane);
    const phraseSamples = selectedDomNodes
      .map((node, index) => extractGridlyDomBridgePhraseEntry(node, index, "dom-awareness-phrase"))
      .map((entry) => {
        const extractedPhrases = [
          entry.extractedShortPhrase || entry.synthesizedShortPhrase || "",
          entry.extractedConfidencePhrase || entry.confidenceLabel || "",
          entry.consequence || "",
          entry.confidence || "",
          entry.extractedFreshnessPhrase || entry.freshness || ""
        ].filter(Boolean);
        const awarenessPhrase = extractedPhrases[0] || "";
        return {
          id: entry.id,
          awarenessMode,
          awarenessPhrase,
          shortPhrase: entry.extractedShortPhrase || entry.synthesizedShortPhrase || awarenessPhrase,
          confidencePhrase: entry.extractedConfidencePhrase || entry.confidenceLabel || "",
          consequencePhrase: entry.consequence || "",
          confidenceLevel: entry.confidence || "unknown",
          freshnessLevel: entry.extractedFreshnessPhrase || entry.freshness || "unknown",
          routeImpact: Boolean(entry.routeImpact),
          routeRelevant: Boolean(entry.routeImpact),
          phraseSources: {
            intelligence: entry.intelligence || entry.synthesizedShortPhrase || "",
            confidenceLabel: entry.confidenceLabel || "",
            routeImpact: entry.routeImpact ? "true" : "",
            consequence: entry.consequence || "",
            confidence: entry.confidence || "",
            freshness: entry.freshness || ""
          }
        };
      })
      .filter((sample) => Boolean(
        sample.shortPhrase
        || sample.confidencePhrase
        || sample.consequencePhrase
        || (sample.confidenceLevel && sample.confidenceLevel !== "unknown")
        || (sample.freshnessLevel && sample.freshnessLevel !== "unknown")
        || sample.routeImpact
      ));
    return {
      awarenessMode,
      evaluatedCount: phraseSamples.length,
      routePhraseCount: phraseSamples.filter((sample) => sample.awarenessMode === "route").length,
      communityPhraseCount: phraseSamples.filter((sample) => sample.awarenessMode === "community").length,
      hybridPhraseCount: phraseSamples.filter((sample) => sample.awarenessMode === "hybrid").length,
      selectedDomCount: selectedDomNodes.length,
      extractedDomPhraseCount: phraseSamples.length,
      finalSourceUsed: selectedDomNodes.length ? "dom_bridge" : "dom_bridge_empty",
      finalUsedExtractedSamples: true,
      topPhraseSamples: phraseSamples.slice(0, 8),
      notes: [
        "Awareness phrase audit uses the shared DOM bridge intelligence extractor; no visual/UI rendering changes.",
        "Existing intelligence and route intelligence phrase audits are preserved separately."
      ]
    };
  } catch (error) {
    return {
      awarenessMode: "unknown",
      evaluatedCount: 0,
      routePhraseCount: 0,
      communityPhraseCount: 0,
      hybridPhraseCount: 0,
      selectedDomCount: 0,
      extractedDomPhraseCount: 0,
      finalSourceUsed: "dom_bridge",
      finalUsedExtractedSamples: true,
      topPhraseSamples: [],
      notes: [`Awareness phrase audit fallback: ${error?.message || "unknown error"}`]
    };
  }
};

window.gridlyRouteFreshnessConsequenceAudit = function gridlyRouteFreshnessConsequenceAudit() {
  try {
    const incidents = Array.isArray(getUnifiedIncidents?.()) ? getUnifiedIncidents() : (Array.isArray(activeHazards) ? activeHazards : []);
    const levelRank = { low: 1, moderate: 2, high: 3, critical: 4 };
    const evaluated = incidents.map((incident) => {
      const base = evaluateGridlyRouteConsequence(incident, { freshnessOptions: { nowMs: Date.now() } });
      const raw = evaluateGridlyRouteConsequence(incident, { freshnessOptions: { nowMs: Date.now() - 60000 } });
      return { incident, base, raw };
    });
    const routeRelevant = evaluated.filter((entry) => Boolean(entry.base?.routeRelevant));
    const sourceRouteRelevantCount = routeRelevant.length;
    const markerPane = typeof document !== "undefined" ? document.querySelector("#map .leaflet-marker-pane") : null;
    const domBridgeNodes = markerPane
      ? Array.from(new Set(Array.from(markerPane.querySelectorAll("[data-gridly-route-impact=\"true\"], .gridly-marker-rail-route-impact, .gridly-marker-priority-route-impact, [data-gridly-consequence]"))))
      : [];
    const consequenceLevels = ["low", "moderate", "high", "critical"];
    const domBridgeSamples = domBridgeNodes.map((node) => {
      const freshness = String(node?.dataset?.gridlyFreshness || "").toLowerCase();
      const consequenceDataset = String(node?.dataset?.gridlyConsequence || "").toLowerCase();
      const consequenceClass = consequenceLevels.find((level) => node.classList?.contains(`gridly-consequence-${level}`)) || "";
      const consequence = consequenceDataset || consequenceClass || "low";
      const visualStyle = String(node?.dataset?.visualStyle || "").toLowerCase();
      const routeImpactDataset = String(node?.dataset?.gridlyRouteImpact || "").toLowerCase();
      const isRouteImpactClass = node.classList?.contains("gridly-marker-rail-route-impact") || node.classList?.contains("gridly-marker-priority-route-impact");
      const isRouteImpactStyle = visualStyle === "rail_route_impact";
      const routeRelevantDom = routeImpactDataset === "true" || isRouteImpactClass || isRouteImpactStyle;
      return {
        id: String(node?.dataset?.incidentId || node?.dataset?.id || "").trim(),
        freshnessLevel: freshness || "unknown",
        consequenceLevel: consequence,
        visualStyle: visualStyle || "",
        routeImpact: routeImpactDataset === "true",
        routeRelevant: routeRelevantDom
      };
    });
    const domRouteRelevant = domBridgeSamples.filter((sample) => Boolean(sample.routeRelevant));
    const domBridgeFreshnessCounts = { fresh: 0, recent: 0, aging: 0, stale: 0, unknown: 0 };
    const domBridgeConsequenceCounts = { low: 0, moderate: 0, high: 0, critical: 0 };
    domRouteRelevant.forEach((sample) => {
      const freshnessLevel = String(sample.freshnessLevel || "unknown").toLowerCase();
      if (domBridgeFreshnessCounts[freshnessLevel] === undefined) domBridgeFreshnessCounts[freshnessLevel] = 0;
      domBridgeFreshnessCounts[freshnessLevel] += 1;
      const consequenceLevel = String(sample.consequenceLevel || "low").toLowerCase();
      if (domBridgeConsequenceCounts[consequenceLevel] === undefined) domBridgeConsequenceCounts[consequenceLevel] = 0;
      domBridgeConsequenceCounts[consequenceLevel] += 1;
    });
    const unknownFreshnessCount = routeRelevant.filter(({ base }) => String(base?.freshnessLevel || "").toLowerCase() === "unknown").length;
    const missingTimestampRouteRelevantCount = routeRelevant.filter(({ incident }) => Boolean(evaluateGridlyIncidentFreshness(incident)?.missingTimestamp)).length;
    const timestampSourceCounts = routeRelevant.reduce((acc, { incident }) => {
      const src = String(evaluateGridlyIncidentFreshness(incident)?.timestampSourceUsed || "missing");
      acc[src] = (acc[src] || 0) + 1;
      return acc;
    }, {});
    let downgradedConsequenceCount = 0;
    let upgradedConsequenceCount = 0;
    routeRelevant.forEach(({ base, raw }) => {
      const a = levelRank[String(base?.consequenceLevel || "low")] || 1;
      const b = levelRank[String(raw?.consequenceLevel || "low")] || 1;
      if (a < b) downgradedConsequenceCount += 1;
      if (a > b) upgradedConsequenceCount += 1;
    });
    const topWeightedSamples = routeRelevant
      .sort((a, b) => Number(b.base?.consequenceScore || 0) - Number(a.base?.consequenceScore || 0))
      .slice(0, 8)
      .map(({ incident, base }) => ({ id: incident?.id || incident?.crossingId || "", type: incident?.type || incident?.report_type || "unknown", freshnessLevel: base?.freshnessLevel || "recent", confidenceWeight: Number(base?.confidenceWeight || 1), consequenceLevel: base?.consequenceLevel || "low", consequenceScore: Number(base?.consequenceScore || 0), consequenceReason: base?.consequenceReason || "" }));
    const levelOrder = ["critical", "high", "moderate", "low"];
    const sourceHighestFreshnessWeightedConsequence = levelOrder.find((level) => topWeightedSamples.some((sample) => sample.consequenceLevel === level)) || "low";
    const domHighestFreshnessWeightedConsequence = levelOrder.find((level) => Number(domBridgeConsequenceCounts[level] || 0) > 0) || "low";
    const routeFreshnessSourceUsed = sourceRouteRelevantCount > 0 ? "source_incidents" : (domRouteRelevant.length > 0 ? "dom_bridge" : "none");
    const useDomBridgeForRouteRelevant = sourceRouteRelevantCount === 0 && domRouteRelevant.length > 0;
    const highestFreshnessWeightedConsequence = useDomBridgeForRouteRelevant ? domHighestFreshnessWeightedConsequence : sourceHighestFreshnessWeightedConsequence;
    return {
      routeRelevantCount: useDomBridgeForRouteRelevant ? domRouteRelevant.length : sourceRouteRelevantCount,
      freshnessAdjustedCount: routeRelevant.filter(({ base }) => base?.freshnessLevel === "aging" || base?.freshnessLevel === "stale" || base?.freshnessLevel === "fresh").length,
      domBridgeRouteRelevantCount: domRouteRelevant.length,
      domBridgeFreshnessCounts,
      domBridgeConsequenceCounts,
      domBridgeAdjustedCount: domRouteRelevant.filter((sample) => ["fresh", "aging", "stale"].includes(String(sample.freshnessLevel || "unknown").toLowerCase())).length,
      domBridgeSamples: domRouteRelevant.slice(0, 8),
      routeFreshnessSourceUsed,
      downgradedConsequenceCount,
      upgradedConsequenceCount,
      highestFreshnessWeightedConsequence,
      unknownFreshnessCount,
      missingTimestampRouteRelevantCount,
      timestampSourceCounts,
      topWeightedSamples,
      notes: ["Consequence freshness audit is read-only and preserves current route-impact bridge behavior."]
    };
  } catch (error) {
    return { routeRelevantCount: 0, freshnessAdjustedCount: 0, domBridgeRouteRelevantCount: 0, domBridgeFreshnessCounts: { fresh: 0, recent: 0, aging: 0, stale: 0, unknown: 0 }, domBridgeConsequenceCounts: { low: 0, moderate: 0, high: 0, critical: 0 }, domBridgeAdjustedCount: 0, domBridgeSamples: [], routeFreshnessSourceUsed: "none", downgradedConsequenceCount: 0, upgradedConsequenceCount: 0, highestFreshnessWeightedConsequence: "low", topWeightedSamples: [], notes: [`Route freshness consequence audit fallback: ${error?.message || "unknown error"}`] };
  }
};

window.gridlyApplyRailRouteImpactDomBridge = function gridlyApplyRailRouteImpactDomBridge() {
  const summary = {
    activeRoutePresent: false,
    domBridgeAvailable: typeof window.gridlyRailMarkerSourceTrace === "function" && typeof doesGridlyIncidentImpactActiveRoute === "function",
    evaluatedRailDomCount: 0,
    impactedSampleCount: 0,
    matchedDomCount: 0,
    unmatchedImpactedCount: 0,
    unmatchedImpactedSamples: [],
    matchStrategyCounts: {
      direct_reference: 0,
      marker_dom_index: 0,
      crossing_id_or_number: 0,
      rounded_lat_lng_key: 0,
      class_style_fallback: 0
    },
    escalatedDomCount: 0,
    deEscalatedDomCount: 0,
    skippedDomCount: 0,
    escalatedSamples: [],
    appliedElementTagCounts: {},
    appliedElementClassSamples: [],
    appliedDatasetSamples: [],
    canonicalTargetStrategyCounts: {
      self: 0,
      marker_wrapper: 0,
      marker_icon: 0
    },
    notes: ["temporary_visual_escalation_only"],
    warning: "temporary_dom_visual_bridge"
  };
  if (!summary.domBridgeAvailable || typeof document === "undefined") {
    return summary;
  }
  const routeLatLngs = typeof getRoutePolylineLatLngs === "function" ? getRoutePolylineLatLngs() : [];
  summary.activeRoutePresent = Array.isArray(routeLatLngs) && routeLatLngs.length >= 2;
  if (!summary.activeRoutePresent) {
    summary.notes.push("no_active_route_detected");
  }
  const trace = window.gridlyRailMarkerSourceTrace();
  const railSamples = Array.isArray(trace?.railDomSamples) ? trace.railDomSamples : [];
  summary.evaluatedRailDomCount = railSamples.length;
  const markerPane = document.querySelector("#map .leaflet-marker-pane");
  const railNodes = markerPane
    ? Array.from(markerPane.querySelectorAll(".gridly-marker-rail-clear, .gridly-marker-rail-blocked, .gridly-marker-rail-route-impact, [data-visual-style=\"rail_clear\"], [data-visual-style=\"rail_blocked\"], [data-visual-style=\"rail_route_impact\"], [class*='rail']"))
    : [];
  const uniqueRailNodes = Array.from(new Set(railNodes));
  const keyForSample = (sample = {}) => {
    if (typeof sample?.roundedLatLngKey === "string" && sample.roundedLatLngKey) return sample.roundedLatLngKey;
    const lat = Number(sample?.coordinates?.lat);
    const lng = Number(sample?.coordinates?.lng);
    return Number.isFinite(lat) && Number.isFinite(lng) ? `${lat.toFixed(6)},${lng.toFixed(6)}` : "";
  };
  const keyForNode = (el) => {
    const lat = Number(el?.dataset?.lat ?? el?.dataset?.latitude);
    const lng = Number(el?.dataset?.lng ?? el?.dataset?.lon ?? el?.dataset?.longitude);
    return Number.isFinite(lat) && Number.isFinite(lng) ? `${lat.toFixed(6)},${lng.toFixed(6)}` : "";
  };
  const crossingTokensForSample = (sample = {}) => [
    sample?.crossingId,
    sample?.crossingNumber,
    sample?.crossingDetected?.id,
    sample?.crossingDetected?.number,
    sample?.dataset?.crossingId,
    sample?.dataset?.crossingNumber,
    sample?.dataAttributes?.["data-crossing-id"],
    sample?.dataAttributes?.["data-crossing-number"]
  ].map((value) => String(value || "").trim()).filter(Boolean);
  const crossingTokensForNode = (el) => [
    el?.dataset?.crossingId,
    el?.dataset?.crossingNumber,
    el?.dataset?.incidentId,
    el?.getAttribute?.("data-crossing-id"),
    el?.getAttribute?.("data-crossing-number")
  ].map((value) => String(value || "").trim()).filter(Boolean);
  const classStyleTokenForSample = (sample = {}) => `${String(sample?.detectedVisualStyle || sample?.visualStyleDetected || "").trim()}|${String(sample?.className || "").trim()}`;
  const classStyleTokenForNode = (el) => `${String(el?.dataset?.visualStyle || "").trim()}|${String(el?.className || "").trim()}`;
  const removeLowPriorityRailClasses = (el) => {
    el.classList.remove("gridly-marker-rail-clear", "gridly-marker-rail-blocked", "gridly-marker-priority-passive");
  };
  const getCanonicalVisibleMarkerTarget = (el) => {
    if (!el || typeof el.closest !== "function") return { target: el, strategy: "self" };
    const markerWrapper = el.closest(".leaflet-marker-icon");
    if (markerWrapper) return { target: markerWrapper, strategy: "marker_icon" };
    const markerShell = el.closest(".gridly-hazard-marker, .gridly-marker");
    if (markerShell) return { target: markerShell, strategy: "marker_wrapper" };
    return { target: el, strategy: "self" };
  };
  const consequenceLevels = ["low", "moderate", "high", "critical"];
  const clearConsequenceClasses = (el) => {
    consequenceLevels.forEach((level) => el.classList.remove(`gridly-consequence-${level}`));
  };
  const deriveBridgeConsequenceLevel = (sample = {}) => {
    const candidate = { lat: sample?.coordinates?.lat, lng: sample?.coordinates?.lng, routeImpact: true, status: sample?.crossingDetected?.status || sample?.dataset?.status || "blocked" };
    const evalResult = evaluateGridlyRouteConsequence(candidate, { category: "rail", markerStyle: "rail_route_impact", routeImpact: true });
    const level = String(evalResult?.consequenceLevel || "high").toLowerCase();
    return consequenceLevels.includes(level) ? level : "high";
  };
  const applyEscalation = (el, sample = {}) => {
    const canonical = getCanonicalVisibleMarkerTarget(el);
    const targetEl = canonical.target || el;
    summary.canonicalTargetStrategyCounts[canonical.strategy] = Number(summary.canonicalTargetStrategyCounts[canonical.strategy] || 0) + 1;
    removeLowPriorityRailClasses(targetEl);
    targetEl.classList.add("gridly-marker-rail-route-impact", "gridly-marker-priority-route-impact");
    targetEl.dataset.visualStyle = "rail_route_impact";
    targetEl.dataset.gridlyMarkerPriority = "route-impact";
    targetEl.dataset.gridlyRouteImpact = "true";
    const consequenceLevel = deriveBridgeConsequenceLevel(sample);
    clearConsequenceClasses(targetEl);
    targetEl.classList.add(`gridly-consequence-${consequenceLevel}`);
    targetEl.dataset.gridlyConsequence = consequenceLevel;
    const intelligencePhrase = "Active route disruption";
    const confidenceLabel = "Community report with stronger confidence";
    targetEl.dataset.gridlyIntelligence = intelligencePhrase;
    targetEl.dataset.gridlyConfidenceLabel = confidenceLabel;
    targetEl.dataset.gridlyConfidence = "medium";
    const tagKey = String(targetEl.tagName || "unknown").toUpperCase();
    summary.appliedElementTagCounts[tagKey] = Number(summary.appliedElementTagCounts[tagKey] || 0) + 1;
    if (summary.appliedElementClassSamples.length < 8) summary.appliedElementClassSamples.push(String(targetEl.className || ""));
    if (summary.appliedDatasetSamples.length < 8) {
      summary.appliedDatasetSamples.push({
        visualStyle: String(targetEl.dataset?.visualStyle || ""),
        gridlyRouteImpact: String(targetEl.dataset?.gridlyRouteImpact || ""),
        gridlyConsequence: String(targetEl.dataset?.gridlyConsequence || ""),
        gridlyMarkerPriority: String(targetEl.dataset?.gridlyMarkerPriority || ""),
        gridlyIntelligence: String(targetEl.dataset?.gridlyIntelligence || ""),
        gridlyConfidenceLabel: String(targetEl.dataset?.gridlyConfidenceLabel || "")
      });
    }
    if (summary.escalatedSamples.length < 8) {
      summary.escalatedSamples.push({
        crossingId: sample?.crossingDetected?.id || "",
        crossingName: sample?.crossingDetected?.name || "",
        lat: Number(sample?.coordinates?.lat),
        lng: Number(sample?.coordinates?.lng)
      });
    }
  };
  const clearEscalation = (el) => {
    const canonical = getCanonicalVisibleMarkerTarget(el);
    const targetEl = canonical.target || el;
    const wasEscalated = targetEl.classList.contains("gridly-marker-rail-route-impact")
      || targetEl.classList.contains("gridly-marker-priority-route-impact")
      || String(targetEl.dataset?.visualStyle || "") === "rail_route_impact"
      || String(targetEl.dataset?.gridlyRouteImpact || "") === "true";
    targetEl.classList.remove("gridly-marker-rail-route-impact", "gridly-marker-priority-route-impact");
    delete targetEl.dataset.gridlyRouteImpact;
    clearConsequenceClasses(targetEl);
    delete targetEl.dataset.gridlyConsequence;
    delete targetEl.dataset.gridlyIntelligence;
    delete targetEl.dataset.gridlyConfidenceLabel;
    delete targetEl.dataset.gridlyConfidence;
    if (String(targetEl.dataset?.visualStyle || "") === "rail_route_impact") {
      targetEl.dataset.visualStyle = "rail_blocked";
    }
    if (String(targetEl.dataset?.gridlyMarkerPriority || "") === "route-impact") {
      targetEl.dataset.gridlyMarkerPriority = "passive";
    }
    if (wasEscalated) summary.deEscalatedDomCount += 1;
  };
  const unmatchedNodePool = [...uniqueRailNodes];
  const consumeNode = (node, strategy) => {
    if (!node) return null;
    const idx = unmatchedNodePool.indexOf(node);
    if (idx >= 0) unmatchedNodePool.splice(idx, 1);
    if (strategy && summary.matchStrategyCounts[strategy] !== undefined) {
      summary.matchStrategyCounts[strategy] += 1;
    }
    return node;
  };
  const findAndConsume = (predicate, strategy) => consumeNode(unmatchedNodePool.find(predicate), strategy);
  railSamples.forEach((sample, sampleIndex) => {
    const candidate = { lat: sample?.coordinates?.lat, lng: sample?.coordinates?.lng, source: "rail_dom_trace", markerStyle: sample?.detectedVisualStyle || sample?.visualStyleDetected || "rail_clear" };
    const impacted = summary.activeRoutePresent && doesGridlyIncidentImpactActiveRoute(candidate);
    if (!impacted) return;
    summary.impactedSampleCount += 1;
    let matchedNode = null;
    if (sample?.__gridlyDomElement && unmatchedNodePool.includes(sample.__gridlyDomElement)) {
      matchedNode = consumeNode(sample.__gridlyDomElement, "direct_reference");
    }
    if (!matchedNode) {
      const domIndex = Number(sample?.markerDomIndex ?? sample?.sampleIndex ?? sampleIndex);
      if (Number.isInteger(domIndex) && domIndex >= 0) matchedNode = consumeNode(uniqueRailNodes[domIndex], "marker_dom_index");
    }
    if (!matchedNode) {
      const sampleCrossingTokens = new Set(crossingTokensForSample(sample));
      if (sampleCrossingTokens.size > 0) {
        matchedNode = findAndConsume((node) => crossingTokensForNode(node).some((token) => sampleCrossingTokens.has(token)), "crossing_id_or_number");
      }
    }
    if (!matchedNode) {
      const roundedLatLngKey = keyForSample(sample);
      if (roundedLatLngKey) matchedNode = findAndConsume((node) => keyForNode(node) === roundedLatLngKey, "rounded_lat_lng_key");
    }
    if (!matchedNode) {
      const classStyleToken = classStyleTokenForSample(sample);
      matchedNode = findAndConsume((node) => classStyleTokenForNode(node) === classStyleToken, "class_style_fallback");
    }
    if (!matchedNode) {
      summary.unmatchedImpactedCount += 1;
      if (summary.unmatchedImpactedSamples.length < 8) summary.unmatchedImpactedSamples.push(sample);
      return;
    }
    applyEscalation(matchedNode, sample);
    summary.matchedDomCount += 1;
    summary.escalatedDomCount += 1;
  });
  unmatchedNodePool.forEach((el) => {
    clearEscalation(el);
    summary.skippedDomCount += 1;
  });
  window.__gridlyRailRouteImpactDomBridgeLastAudit = summary;
  summary.notes.push("no_source_object_mutation");
  summary.notes.push("no_new_markers_created");
  return summary;
};

window.gridlyRailRouteImpactDomBridgeAudit = function gridlyRailRouteImpactDomBridgeAudit() {
  const last = window.__gridlyRailRouteImpactDomBridgeLastAudit;
  if (last && typeof last === "object") return { ...last, domBridgeAvailable: true, warning: "temporary_dom_visual_bridge" };
  return {
    activeRoutePresent: false,
    domBridgeAvailable: typeof window.gridlyApplyRailRouteImpactDomBridge === "function",
    evaluatedRailDomCount: 0,
    escalatedDomCount: 0,
    deEscalatedDomCount: 0,
    skippedDomCount: 0,
    escalatedSamples: [],
    notes: ["bridge_not_run_yet"],
    warning: "temporary_dom_visual_bridge"
  };
};


window.gridlyRouteConsequenceBridgeAudit = function gridlyRouteConsequenceBridgeAudit() {
  try {
    const markerPane = typeof document !== "undefined" ? document.querySelector("#map .leaflet-marker-pane") : null;
    const routeImpactSelector = "[data-gridly-route-impact=\"true\"], .gridly-marker-rail-route-impact, .gridly-marker-priority-route-impact";
    const consequenceSelector = "[data-gridly-consequence]";
    const bridgeNodes = markerPane ? Array.from(markerPane.querySelectorAll(`${routeImpactSelector}, ${consequenceSelector}`)) : [];
    const uniqueBridgeNodes = Array.from(new Set(bridgeNodes));
    const levels = ["low", "moderate", "high", "critical"];
    const counts = { low: 0, moderate: 0, high: 0, critical: 0 };
    let withConsequence = 0;
    const missing = [];
    uniqueBridgeNodes.forEach((node) => {
      const datasetLevel = String(node.dataset?.gridlyConsequence || "").toLowerCase();
      const classLevel = levels.find((level) => node.classList?.contains(`gridly-consequence-${level}`)) || "";
      const level = datasetLevel || classLevel;
      if (!level) {
        if (missing.length < 12) missing.push(String(node.dataset?.incidentId || node.dataset?.crossingId || node.dataset?.id || "unknown"));
        return;
      }
      withConsequence += 1;
      counts[level] = Number(counts[level] || 0) + 1;
    });
    const highestBridgeConsequence = ["critical", "high", "moderate", "low"].find((level) => counts[level] > 0) || "low";
    return {
      evaluatedBridgeMarkers: uniqueBridgeNodes.length,
      bridgeMarkersWithConsequence: withConsequence,
      bridgeConsequenceCounts: counts,
      highestBridgeConsequence,
      routeImpactBridgeMarkerCount: uniqueBridgeNodes.length,
      missingConsequenceMarkers: missing,
      notes: ["Temporary bridge diagnostic for route-impact rail DOM metadata alignment.", "No route recalculation or source mutation performed."],
      warning: "temporary_dom_consequence_bridge"
    };
  } catch (error) {
    return { evaluatedBridgeMarkers: 0, bridgeMarkersWithConsequence: 0, bridgeConsequenceCounts: { low: 0, moderate: 0, high: 0, critical: 0 }, highestBridgeConsequence: "low", routeImpactBridgeMarkerCount: 0, missingConsequenceMarkers: [], notes: [`Route consequence bridge audit fallback: ${error?.message || "unknown error"}`], warning: "temporary_dom_consequence_bridge" };
  }
};

