function gridlyBuildOperationalCountyWideAwarenessArea(countyId, config) {
  const bounds = GRIDLY_COUNTY_AWARENESS_BOUNDS_BY_ID[countyId] || null;
  const lat = bounds ? (Number(bounds.south) + Number(bounds.north)) / 2 : 30.2;
  const lng = bounds ? (Number(bounds.west) + Number(bounds.east)) / 2 : -94.9;
  return {
    key: countyId.replace(/-tx$/, "-county"),
    label: config.name,
    storageValue: config.name,
    countyId,
    lat,
    lng,
    radiusMiles: null,
    startupZoom: 10,
    countyWide: true,
    source: "V819 operational county registry selector bridge"
  };
}

