const GRIDLY_SAN_JACINTO_TOWN_CROSSING_COUNT_AUDIT_VISIBLE_MARKER_NOTE = "Visible markers may be 0 at startup zoom 13 because inactive San Jacinto crossing infrastructure markers require zoom 14; this audit uses the loaded normalized crossing inventory, not rendered marker count.";

function gridlyNormalizeCrossingAuditCoordinate(crossing = {}) {
  const lat = Number(crossing?.lat ?? crossing?.latitude);
  const lng = Number(crossing?.lng ?? crossing?.lon ?? crossing?.longitude);
  if (!Number.isFinite(lat) || !Number.isFinite(lng)) return null;
  return { lat, lng };
}

function gridlySanJacintoTownCrossingCountAudit(options = {}) {
  const sampleSize = Math.max(1, Number(options.sampleSize || 5));
  const inventory = Array.isArray(crossings) ? crossings : [];
  const validCrossings = inventory
    .map((crossing) => ({ crossing, coords: gridlyNormalizeCrossingAuditCoordinate(crossing) }))
    .filter((entry) => entry.coords);
  const townAreas = GRIDLY_SAN_JACINTO_TOWN_CROSSING_COUNT_AUDIT_KEYS
    .map((key) => GRIDLY_AWARENESS_AREA_BY_KEY[key])
    .filter((area) => area && area.countyId === "san-jacinto-tx" && Number.isFinite(Number(area.radiusMiles)));
  const towns = townAreas.map((area) => {
    const center = { lat: Number(area.lat), lng: Number(area.lng) };
    const withDistances = validCrossings
      .map(({ crossing, coords }) => ({ crossing, coords, distanceMiles: getDistanceMiles(center.lat, center.lng, coords.lat, coords.lng) }))
      .filter((entry) => Number.isFinite(entry.distanceMiles))
      .sort((a, b) => a.distanceMiles - b.distanceMiles);
    return {
      town: area.label,
      countyId: area.countyId,
      townCenter: center,
      radiusMiles: Number(area.radiusMiles),
      crossingCountWithinRadius: withDistances.filter((entry) => entry.distanceMiles <= Number(area.radiusMiles)).length,
      nearestCrossings: withDistances.slice(0, sampleSize).map(({ crossing, coords, distanceMiles }) => ({
        id: String(crossing?.id || crossing?.crossingId || crossing?.crossing_id || ""),
        lat: coords.lat,
        lng: coords.lng,
        distanceMiles: Number(distanceMiles.toFixed(2)),
        displayName: crossing?.displayName || crossing?.name || crossing?.originalName || "",
        roadName: crossing?.primaryRoad || crossing?.roadName || crossing?.road || crossing?.props?.roadwayname || crossing?.props?.street || crossing?.props?.highwayname || ""
      }))
    };
  });
  const crossingsOutsideAllTownRadii = validCrossings.filter(({ coords }) => {
    return !townAreas.some((area) => {
      const distanceMiles = getDistanceMiles(Number(area.lat), Number(area.lng), coords.lat, coords.lng);
      return Number.isFinite(distanceMiles) && distanceMiles <= Number(area.radiusMiles);
    });
  }).length;

  return {
    audit: "V670 San Jacinto town crossing count inventory audit",
    sourceOfTruth: "loaded normalized crossing inventory records",
    renderedMarkerCountUsed: false,
    totalSanJacintoCrossingInventoryCount: inventory.length,
    totalValidCoordinateCount: validCrossings.length,
    crossingsOutsideAllTownRadii,
    towns,
    note: GRIDLY_SAN_JACINTO_TOWN_CROSSING_COUNT_AUDIT_VISIBLE_MARKER_NOTE
  };
}


function gridlyNormalizeConsumerCrossingText(value) {
  return String(value || "").trim();
}

