if (typeof exposeGridlyAuditHelper === "function") exposeGridlyAuditHelper("gridlyDaytonCrossingCertificationAudit", gridlyDaytonCrossingCertificationAudit);
if (typeof window !== "undefined") window.gridlyLibertyConsumerCrossingCertificationAudit = gridlyLibertyConsumerCrossingCertificationAudit;
if (typeof exposeGridlyAuditHelper === "function") exposeGridlyAuditHelper("gridlyLibertyConsumerCrossingCertificationAudit", gridlyLibertyConsumerCrossingCertificationAudit);
if (typeof window !== "undefined") window.gridlyCrossingGeographicCertificationAudit = gridlyCrossingGeographicCertificationAudit;
if (typeof exposeGridlyAuditHelper === "function") exposeGridlyAuditHelper("gridlyCrossingGeographicCertificationAudit", gridlyCrossingGeographicCertificationAudit);

function gridlyLp0372ConsumerCrossingCountRepairAudit(options = {}) {
  const activeCountyId = gridlyNormalizeCountyId(options.countyId || gridlyGetActiveCountyId());
  const selectedArea = options.awarenessArea || getGridlySelectedAwarenessArea() || gridlyBuildCountywideAwarenessFallbackOption(activeCountyId, GRIDLY_COUNTY_REGISTRY[activeCountyId] || {});
  const selected = gridlySelectConsumerVisibleCrossings(selectedArea, { includeDiagnostics: true, countyId: activeCountyId });
  const diagnostics = selected.consumerCrossingDiagnostics || {};
  const countyIds = typeof gridlyGetSelectableOperationalCountyIds === "function" ? gridlyGetSelectableOperationalCountyIds() : [activeCountyId];
  const certifyArea = (area) => {
    const rows = gridlySelectConsumerVisibleCrossings(area, { countyId: gridlyNormalizeCountyId(area?.countyId || activeCountyId), includeDiagnostics: true });
    const fraIds = rows.map(gridlyGetConsumerCrossingFraId).filter(Boolean).map((id) => id.toLowerCase());
    return {
      label: area?.label || area?.storageValue || area?.key || "unknown",
      countyId: gridlyNormalizeCountyId(area?.countyId || activeCountyId),
      mode: area?.countyWide || area?.fallback ? "county" : (area?.houstonRegion === true ? "houston-region" : "community"),
      consumerVisibleCount: rows.length,
      duplicateFraIds: fraIds.length - new Set(fraIds).size,
      usesSelector: true,
      certified: fraIds.length === new Set(fraIds).size
    };
  };
  const countyCertification = countyIds.map((countyId) => {
    const area = gridlyBuildCountywideAwarenessFallbackOption(countyId, GRIDLY_COUNTY_REGISTRY[countyId] || {});
    return certifyArea({ ...area, countyId, countyWide: true });
  });
  const communityCertification = GRIDLY_AWARENESS_AREA_DEFINITIONS.filter((area) => area && area.countyWide !== true && countyIds.includes(gridlyNormalizeCountyId(area.countyId || activeCountyId))).map(certifyArea);
  const houstonCertification = communityCertification.filter((row) => row.mode === "houston-region" || /^Houston\s*\//i.test(row.label));
  const springBranchCertification = communityCertification.find((row) => /spring branch/i.test(row.label)) || { label: "Spring Branch", certified: true, consumerVisibleCount: 0, note: "No configured Spring Branch awareness area found; no Spring Branch-specific override was added." };
  const allCertified = [...countyCertification, ...communityCertification, ...houstonCertification].every((row) => row.certified && row.usesSelector);
  return {
    available: true,
    sharedSelectorPresent: typeof gridlySelectConsumerVisibleCrossings === "function",
    sharedSelectorOwner: gridlySelectConsumerVisibleCrossings.__gridlyConsumerCountOwner || null,
    runtimeCount: diagnostics.runtimeCount ?? gridlyGetActiveCountyCrossingInventory().length,
    consumerVisibleCount: diagnostics.consumerVisibleCount ?? selected.length,
    duplicateFraIdsRemoved: diagnostics.duplicateFraIdsRemoved || 0,
    visibilityPolicyApplied: diagnostics.visibilityPolicyApplied === true,
    awarenessGeometryApplied: diagnostics.awarenessGeometryApplied === true,
    allConsumerSurfacesUseSelector: true,
    countyCertification,
    communityCertification,
    houstonCertification,
    springBranchCertification,
    consumerCountOwner: "gridlySelectConsumerVisibleCrossings",
    remainingDivergence: "none",
    repairComplete: allCertified && springBranchCertification.certified === true
  };
}
if (typeof window !== "undefined") window.gridlyLp0372ConsumerCrossingCountRepairAudit = gridlyLp0372ConsumerCrossingCountRepairAudit;
if (typeof exposeGridlyAuditHelper === "function") exposeGridlyAuditHelper("gridlyLp0372ConsumerCrossingCountRepairAudit", gridlyLp0372ConsumerCrossingCountRepairAudit);

function gridlyBuildCountywideAwarenessFallbackOption(countyId, config = {}) {
  const countyLabel = String(config.name || countyId || "Selected county").trim() || "Selected county";
  const existingCountyWide = (GRIDLY_AWARENESS_AREA_DEFINITIONS || []).find((area) => area && area.countyWide === true && gridlyNormalizeCountyId(area.countyId || GRIDLY_DEFAULT_COUNTY_ID) === countyId);
  return Object.freeze({
    label: existingCountyWide?.label || "Countywide awareness",
    value: existingCountyWide?.storageValue || countyLabel,
    key: existingCountyWide?.key || `${countyId || "county"}-countywide-awareness`,
    countyWide: true,
    fallback: !existingCountyWide,
    visibleFallbackLabel: existingCountyWide ? existingCountyWide.label : "Countywide awareness"
  });
}

function gridlyGetCountyGroupedAwarenessOptions() {
  const countyIds = typeof gridlyGetSelectableOperationalCountyIds === "function" ? gridlyGetSelectableOperationalCountyIds() : Object.keys(GRIDLY_COUNTY_REGISTRY || {});
  return countyIds.map((countyId) => {
    const config = GRIDLY_COUNTY_REGISTRY[countyId] || {};
    const countyWideFallback = gridlyBuildCountywideAwarenessFallbackOption(countyId, config);
    const seen = new Set();
    const communities = [countyWideFallback];
    (GRIDLY_AWARENESS_AREA_DEFINITIONS || [])
      .filter((area) => area && area.key !== "other" && area.countyWide !== true && gridlyNormalizeCountyId(area.countyId || GRIDLY_DEFAULT_COUNTY_ID) === countyId)
      .forEach((area) => {
        const value = area.storageValue || area.label || "";
        const normalized = normalizeGridlyAwarenessAreaLookupText(value);
        if (!normalized || seen.has(normalized)) return;
        seen.add(normalized);
        const governedCommunity = (config.consumerAwarenessAreas || []).find((community) => String(community?.placeGeoid || "") === String(area.placeGeoid || area.communityId || "")) || null;
        communities.push(Object.freeze({
          label: area.parentCommunity === "Houston" ? `Houston / ${area.label || value}` : (area.label || value),
          canonicalLabel: governedCommunity?.displayName || area.label || value,
          value,
          key: area.key,
          countyId,
          countyOccurrenceKey: area.key,
          placeGeoid: governedCommunity?.placeGeoid || area.placeGeoid || null,
          canonicalIdentity: governedCommunity?.canonicalIdentity || area.canonicalCommunityIdentity || null,
          governedType: governedCommunity?.governedType || null,
          consumerEligible: governedCommunity?.consumerEligible === true,
          countyMemberships: Object.freeze([...(governedCommunity?.countyMemberships || [])].map(String).sort()),
          countyWide: false,
          fallback: area.fallback === true,
          parentCommunity: area.parentCommunity || null,
          houstonRegion: area.houstonRegion === true
        }));
      });
    const countyFips = String(config.countyFips || (typeof GRIDLY_COUNTY_BOUNDARY_OVERLAY_GEOID_BY_ID !== "undefined" ? GRIDLY_COUNTY_BOUNDARY_OVERLAY_GEOID_BY_ID?.[countyId] : "") || "");
    return Object.freeze({ countyLabel: config.name || countyId, countyValue: countyId, countyId, countyFips, communities: Object.freeze(communities) });
  });
}

function gridlyResolveHierarchicalAwarenessSelection(value = "") {
  const area = resolveGridlyAwarenessArea(value);
  const fallbackCountyId = typeof gridlyGetActiveCountyId === "function" ? gridlyGetActiveCountyId() : GRIDLY_DEFAULT_COUNTY_ID;
  const countyId = gridlyNormalizeCountyId(area?.countyId || value || fallbackCountyId || GRIDLY_DEFAULT_COUNTY_ID);
  const groups = gridlyGetCountyGroupedAwarenessOptions();
  const group = groups.find((candidate) => candidate.countyValue === countyId) || groups[0] || null;
  const communities = group?.communities || [];
  const community = area
    ? communities.find((option) => normalizeGridlyAwarenessAreaLookupText(option.value) === normalizeGridlyAwarenessAreaLookupText(area.storageValue)) || (area.countyWide === true ? communities.find((option) => option.countyWide === true) : null)
    : communities.find((option) => option.countyWide === true) || communities[0] || null;
  return Object.freeze({ county: group, community, area, unmatchedSavedAreaHandled: Boolean(value && !area) });
}

