function gridlyIsHistoricalPipelineEnabled() {
  if (typeof window !== "undefined" && typeof window.GRIDLY_ENABLE_HISTORICAL_PIPELINE !== "undefined") {
    return window.GRIDLY_ENABLE_HISTORICAL_PIPELINE === true;
  }
  return GRIDLY_ENABLE_HISTORICAL_PIPELINE === true;
}

function gridlyHistoricalProjectionTimestamp(record = {}) {
  const value = record?.submittedAt || record?.created_at || record?.createdAt || record?.updated_at || record?.updatedAt || record?.timestamp || record?.time || null;
  const ms = value ? new Date(value).getTime() : NaN;
  return Number.isFinite(ms) ? new Date(ms).toISOString() : null;
}

function gridlyHistoricalProjectionIncidentIdentity(record = {}, sourceKind = "unknown", index = 0) {
  const explicit = record?.incidentId || record?.incident_id || record?.id || record?.reportId || record?.report_id || record?.crossingId || record?.crossing_id || "";
  if (explicit) return String(explicit).trim();
  if (typeof getHazardClusterKey === "function") return String(getHazardClusterKey(record) || `${sourceKind}-${index}`).trim();
  return `${sourceKind}-${index}`;
}

function gridlyHistoricalProjectionRecordKind(record = {}) {
  const type = String(record?.type || record?.report_type || record?.eventType || record?.lifecycleState || record?.status || "").toLowerCase();
  if (type.includes("clear") || type.includes("cleared")) return "clear";
  if (type.includes("confirm") || record?.confirmed === true || record?.confirmation === true) return "confirmation";
  return "report";
}

function buildHistoricalProjection(sources = {}, options = {}) {
  const nowIso = new Date(Number.isFinite(Number(options.nowMs)) ? Number(options.nowMs) : Date.now()).toISOString();
  const sourceSets = [
    { sourceKind: "activeHazards", records: Array.isArray(sources.activeHazards) ? sources.activeHazards : [] },
    { sourceKind: "liveHazardIncidents", records: Array.isArray(sources.liveHazardIncidents) ? sources.liveHazardIncidents : [] },
    { sourceKind: "recentlyClearedRoadHazards", records: Array.isArray(sources.recentlyClearedRoadHazards) ? sources.recentlyClearedRoadHazards : [] },
    { sourceKind: "activeReports", records: Array.isArray(sources.activeReports) ? sources.activeReports : [] }
  ];
  const incidentsById = new Map();
  sourceSets.forEach(({ sourceKind, records }) => {
    records.forEach((record, index) => {
      const incidentId = gridlyHistoricalProjectionIncidentIdentity(record, sourceKind, index);
      if (!incidentsById.has(incidentId)) {
        incidentsById.set(incidentId, {
          incidentId,
          firstObserved: null,
          lastObserved: null,
          reportCount: 0,
          confirmationCount: 0,
          clearCount: 0,
          sourceKinds: [],
          shadowOnly: true
        });
      }
      const projection = incidentsById.get(incidentId);
      const observedAt = gridlyHistoricalProjectionTimestamp(record) || nowIso;
      projection.firstObserved = projection.firstObserved && projection.firstObserved < observedAt ? projection.firstObserved : observedAt;
      projection.lastObserved = projection.lastObserved && projection.lastObserved > observedAt ? projection.lastObserved : observedAt;
      const recordKind = gridlyHistoricalProjectionRecordKind(record);
      if (recordKind === "clear") projection.clearCount += 1;
      else if (recordKind === "confirmation") projection.confirmationCount += 1;
      else projection.reportCount += 1;
      if (!projection.sourceKinds.includes(sourceKind)) projection.sourceKinds.push(sourceKind);
    });
  });
  return {
    generatedAt: nowIso,
    enabled: gridlyIsHistoricalPipelineEnabled(),
    shadowOnly: true,
    incidents: Array.from(incidentsById.values()).sort((a, b) => String(a.incidentId).localeCompare(String(b.incidentId)))
  };
}

function gridlyHistoricalProjectionCurrentSources() {
  const liveHazardIncidents = typeof getLiveHazardIncidents === "function" ? getLiveHazardIncidents() : [];
  return { activeHazards, activeReports, recentlyClearedRoadHazards, liveHazardIncidents };
}

function gridlyGenerateHistoricalProjection(source = "manual") {
  gridlyHistoricalProjectionLastGenerationStatus = "generating";
  const liveHazardIncidents = typeof getLiveHazardIncidents === "function" ? getLiveHazardIncidents() : [];
  gridlyHistoricalProjection = buildHistoricalProjection({ activeHazards, activeReports, recentlyClearedRoadHazards, liveHazardIncidents }, { source });
  gridlyHistoricalProjectionLastGeneratedAt = gridlyHistoricalProjection.generatedAt;
  gridlyHistoricalProjectionLastGenerationStatus = "generated";
  return gridlyHistoricalProjection;
}

function gridlyMaybeGenerateHistoricalProjection(source = "shadow_refresh") {
  if (!gridlyIsHistoricalPipelineEnabled()) return gridlyHistoricalProjection;
  return gridlyGenerateHistoricalProjection(source);
}


function gridlyHistoricalProjectionValidationFindings(projection = {}, sources = {}) {
  const incidents = Array.isArray(projection?.incidents) ? projection.incidents : [];
  const allRecords = [
    ...(Array.isArray(sources.activeHazards) ? sources.activeHazards : []),
    ...(Array.isArray(sources.liveHazardIncidents) ? sources.liveHazardIncidents : []),
    ...(Array.isArray(sources.recentlyClearedRoadHazards) ? sources.recentlyClearedRoadHazards : []),
    ...(Array.isArray(sources.activeReports) ? sources.activeReports : [])
  ];
  const sourceRecordCount = allRecords.length;
  const projectedEventCount = incidents.reduce((sum, incident) => sum + Number(incident.reportCount || 0) + Number(incident.confirmationCount || 0) + Number(incident.clearCount || 0), 0);
  const duplicateIncidentIds = incidents.map((incident) => String(incident.incidentId)).filter((id, index, ids) => ids.indexOf(id) !== index);
  const timestampIssues = incidents.filter((incident) => {
    const first = new Date(incident.firstObserved || 0).getTime();
    const last = new Date(incident.lastObserved || 0).getTime();
    return !Number.isFinite(first) || !Number.isFinite(last) || first > last;
  });
  const countIssues = incidents.filter((incident) => Number(incident.reportCount || 0) + Number(incident.confirmationCount || 0) + Number(incident.clearCount || 0) <= 0);
  return [
    {
      id: "projection-identity-stability",
      pass: duplicateIncidentIds.length === 0,
      summary: duplicateIncidentIds.length === 0 ? "Projected incident identities are unique." : "Duplicate projected incident identities were detected.",
      details: duplicateIncidentIds.slice(0, 20)
    },
    {
      id: "projection-counts",
      pass: projectedEventCount === sourceRecordCount,
      summary: `Projected event count ${projectedEventCount} vs source record count ${sourceRecordCount}.`,
      details: { projectedEventCount, sourceRecordCount, incidentCount: incidents.length }
    },
    {
      id: "report-confirmation-clear-counting",
      pass: countIssues.length === 0,
      summary: countIssues.length === 0 ? "Every projected incident has report, confirmation, or clear evidence." : "One or more projected incidents have no counted evidence.",
      details: countIssues.slice(0, 20)
    },
    {
      id: "timestamp-consistency",
      pass: timestampIssues.length === 0,
      summary: timestampIssues.length === 0 ? "Projected first/last observed timestamps are internally consistent." : "Projected timestamp ordering issues were detected.",
      details: timestampIssues.slice(0, 20)
    },
    {
      id: "duplicate-grouping-consistency",
      pass: incidents.length <= sourceRecordCount || sourceRecordCount === 0,
      summary: "Projection does not expand duplicate source records into more incidents than source records.",
      details: { incidentCount: incidents.length, sourceRecordCount }
    }
  ];
}

function gridlyHistoricalProjectionValidationAudit(options = {}) {
  const productionIncidents = typeof getLiveHazardIncidents === "function" ? getLiveHazardIncidents() : [];
  const sources = options.sources || { activeHazards, activeReports, recentlyClearedRoadHazards, liveHazardIncidents: productionIncidents };
  const projection = options.projection || buildHistoricalProjection(sources, { source: "projection_validation_audit" });
  const findings = gridlyHistoricalProjectionValidationFindings(projection, sources);
  return {
    pass: findings.every((finding) => finding.pass),
    generatedAt: new Date().toISOString(),
    enabled: gridlyIsHistoricalPipelineEnabled(),
    shadowOnly: true,
    productionMutationPerformed: false,
    projectionCount: Array.isArray(projection?.incidents) ? projection.incidents.length : 0,
    findings
  };
}

function gridlyHistoricalProjectionStableGroupingKey(incident = {}) {
  const incidentId = String(incident?.incidentId || "").trim();
  const sourceKinds = Array.isArray(incident?.sourceKinds)
    ? Array.from(new Set(incident.sourceKinds.map((sourceKind) => String(sourceKind || "").trim()).filter(Boolean))).sort()
    : [];
  return {
    incidentId,
    reportCount: Number(incident?.reportCount || 0),
    confirmationCount: Number(incident?.confirmationCount || 0),
    clearCount: Number(incident?.clearCount || 0),
    sourceKinds
  };
}

function gridlyHistoricalProjectionSnapshot(projection = {}) {
  const incidents = Array.isArray(projection?.incidents) ? projection.incidents : [];
  const identities = Array.from(new Set(incidents.map((incident) => String(incident?.incidentId || "").trim()).filter(Boolean))).sort();
  const groups = incidents
    .map((incident) => gridlyHistoricalProjectionStableGroupingKey(incident))
    .filter((group) => group.incidentId)
    .sort((a, b) => a.incidentId.localeCompare(b.incidentId));
  return {
    count: incidents.length,
    identities,
    groups
  };
}

function gridlyCompareHistoricalProjectionSnapshots(first = {}, second = {}) {
  const firstIds = new Set(Array.isArray(first.identities) ? first.identities.map((id) => String(id || "").trim()).filter(Boolean).sort() : []);
  const secondIds = new Set(Array.isArray(second.identities) ? second.identities.map((id) => String(id || "").trim()).filter(Boolean).sort() : []);
  const identityChanges = {
    added: [...secondIds].filter((id) => !firstIds.has(id)).sort(),
    removed: [...firstIds].filter((id) => !secondIds.has(id)).sort()
  };
  const normalizeGroups = (snapshot = {}) => (Array.isArray(snapshot.groups) ? snapshot.groups : [])
    .map((group) => gridlyHistoricalProjectionStableGroupingKey(group))
    .filter((group) => group.incidentId)
    .sort((a, b) => a.incidentId.localeCompare(b.incidentId));
  const firstGroups = new Map(normalizeGroups(first).map((group) => [group.incidentId, group]));
  const groupingChanges = normalizeGroups(second).filter((group) => {
    const previous = firstGroups.get(group.incidentId);
    return previous && JSON.stringify(previous) !== JSON.stringify(group);
  }).map((group) => ({ incidentId: group.incidentId, before: firstGroups.get(group.incidentId), after: group }));
  const countChanged = Number(first.count || 0) !== Number(second.count || 0);
  const driftDetected = identityChanges.added.length > 0 || identityChanges.removed.length > 0 || groupingChanges.length > 0 || countChanged;
  return {
    driftDetected,
    driftClassification: !driftDetected ? "none" : [
      identityChanges.added.length || identityChanges.removed.length ? "identity" : "",
      groupingChanges.length ? "grouping" : "",
      countChanged ? "count" : ""
    ].filter(Boolean).join("+") || "unknown",
    countChanged,
    countDelta: Number(second.count || 0) - Number(first.count || 0),
    identityChanges,
    groupingChanges: groupingChanges.slice(0, 20)
  };
}

function gridlyHistoricalProjectionProductionIsolationSnapshot() {
  const safeWindow = typeof window !== "undefined" ? window : null;
  const safeDocument = typeof document !== "undefined" ? document : null;
  const safeArrayCollection = (localCollection, windowKey) => {
    if (Array.isArray(localCollection)) return localCollection;
    const windowCollection = safeWindow ? safeWindow[windowKey] : null;
    return Array.isArray(windowCollection) ? windowCollection : [];
  };
  const activeHazardItems = safeArrayCollection(typeof activeHazards !== "undefined" ? activeHazards : undefined, "activeHazards");
  const activeReportItems = safeArrayCollection(typeof activeReports !== "undefined" ? activeReports : undefined, "activeReports");
  const unifiedRoadIncidentItems = safeArrayCollection(typeof unifiedRoadIncidents !== "undefined" ? unifiedRoadIncidents : undefined, "unifiedRoadIncidents");
  const activeUnifiedIncidentItems = safeArrayCollection(typeof activeUnifiedIncidents !== "undefined" ? activeUnifiedIncidents : undefined, "activeUnifiedIncidents");
  const productionIncidents = typeof getLiveHazardIncidents === "function" ? getLiveHazardIncidents() : [];
  const markerAudit = safeWindow && typeof safeWindow.gridlyMarkerAuditDebug === "function" ? safeWindow.gridlyMarkerAuditDebug() : null;
  const uiSmoke = safeWindow && typeof safeWindow.gridlyUiSmokeTest === "function" ? safeWindow.gridlyUiSmokeTest() : null;
  const countReconciliation = safeWindow && typeof safeWindow.gridlyActiveHazardCountReconciliationAudit === "function" ? safeWindow.gridlyActiveHazardCountReconciliationAudit() : null;
  return {
    activeHazardsCount: activeHazardItems.length,
    activeReportsCount: activeReportItems.length,
    liveHazardIncidentCount: Array.isArray(productionIncidents) ? productionIncidents.length : 0,
    unifiedRoadIncidentCount: unifiedRoadIncidentItems.length,
    activeUnifiedIncidentCount: activeUnifiedIncidentItems.length,
    alertsListCount: safeDocument ? safeDocument.querySelectorAll("#alertsList li, #alertsList [data-gridly-alert-row='true'], .gridly-alert-row").length : null,
    awarenessStateKey: safeWindow ? JSON.stringify(safeWindow.gridlyTopAwarenessMicrolineState || {}) : "{}",
    renderedMarkerCount: markerAudit?.renderedMarkerCount ?? markerAudit?.markerCount ?? null,
    routeWatchLayerPresent: typeof savedRouteLayer !== "undefined" ? Boolean(savedRouteLayer) : null,
    countReconciliationPass: countReconciliation?.pass ?? null,
    countReconciliationSummary: countReconciliation || null,
    uiSmokePass: uiSmoke?.pass ?? null
  };
}

function gridlyHistoricalProjectionCompareIsolationSnapshots(before = {}, after = {}) {
  const fields = [
    "activeHazardsCount",
    "activeReportsCount",
    "liveHazardIncidentCount",
    "unifiedRoadIncidentCount",
    "activeUnifiedIncidentCount",
    "alertsListCount",
    "awarenessStateKey",
    "renderedMarkerCount",
    "routeWatchLayerPresent",
    "countReconciliationPass"
  ];
  const changes = fields.filter((field) => JSON.stringify(before[field]) !== JSON.stringify(after[field])).map((field) => ({ field, before: before[field], after: after[field] }));
  return {
    changed: changes.length > 0,
    changes,
    alertsChanged: changes.some((change) => change.field === "alertsListCount"),
    awarenessChanged: changes.some((change) => change.field === "awarenessStateKey"),
    markersChanged: changes.some((change) => change.field === "renderedMarkerCount"),
    routeWatchChanged: changes.some((change) => change.field === "routeWatchLayerPresent"),
    activeIncidentCountsChanged: changes.some((change) => ["activeHazardsCount", "liveHazardIncidentCount", "unifiedRoadIncidentCount", "activeUnifiedIncidentCount"].includes(change.field)),
    countReconciliationChanged: changes.some((change) => change.field === "countReconciliationPass")
  };
}

function gridlyHistoricalProjectionRuntimeAudit(options = {}) {
  const sources = options.sources || gridlyHistoricalProjectionCurrentSources();
  const nowMs = Number.isFinite(Number(options.nowMs)) ? Number(options.nowMs) : Date.now();
  const firstProjection = buildHistoricalProjection(sources, { source: "runtime_audit_first", nowMs });
  const secondProjection = buildHistoricalProjection(sources, { source: "runtime_audit_repeat", nowMs });
  const firstSnapshot = gridlyHistoricalProjectionSnapshot(firstProjection);
  const secondSnapshot = gridlyHistoricalProjectionSnapshot(secondProjection);
  const drift = gridlyCompareHistoricalProjectionSnapshots(firstSnapshot, secondSnapshot);
  const validation = gridlyHistoricalProjectionValidationAudit({ sources, projection: secondProjection });
  const determinismPass = !drift.driftDetected;
  gridlyHistoricalProjectionLastDriftStatus = drift.driftDetected ? drift.driftClassification : "none";
  gridlyHistoricalProjectionLastValidationStatus = validation.pass ? "pass" : "fail";
  return {
    pass: determinismPass && validation.pass,
    generatedAt: new Date().toISOString(),
    enabled: gridlyIsHistoricalPipelineEnabled(),
    featureFlagState: gridlyIsHistoricalPipelineEnabled() ? "enabled" : "disabled",
    shadowOnly: true,
    productionMutationPerformed: false,
    projectionGenerationStability: determinismPass ? "stable" : "drift_detected",
    repeatGenerationConsistency: determinismPass,
    identityStability: drift.identityChanges.added.length === 0 && drift.identityChanges.removed.length === 0,
    projectionDriftDetection: drift,
    shadowMemoryStateValid: !gridlyHistoricalProjection || Array.isArray(gridlyHistoricalProjection.incidents),
    parityReadiness: validation.pass && determinismPass ? "ready-for-shadow-parity-review" : "needs-review",
    determinismConfidence: determinismPass ? "high" : "low",
    runtimeStabilityConfidence: determinismPass && validation.pass ? "high" : "needs-review",
    validationStatus: validation.pass ? "pass" : "fail",
    firstSnapshot: options.includeSnapshots === true ? firstSnapshot : undefined,
    secondSnapshot: options.includeSnapshots === true ? secondSnapshot : undefined
  };
}

function gridlyHistoricalProjectionEnablementAudit(options = {}) {
  const originalWindowFlag = typeof window !== "undefined" ? window.GRIDLY_ENABLE_HISTORICAL_PIPELINE : undefined;
  const shouldForceEnable = options.forceEnable === true;
  if (shouldForceEnable && typeof window !== "undefined") window.GRIDLY_ENABLE_HISTORICAL_PIPELINE = true;
  const featureFlagEnabled = gridlyIsHistoricalPipelineEnabled();
  const enablementStatus = featureFlagEnabled ? (shouldForceEnable ? "enabled-forced" : "enabled") : "disabled-default";
  const beforeIsolation = gridlyHistoricalProjectionProductionIsolationSnapshot();

  let firstProjection = null;
  let secondProjection = null;
  let firstSnapshot = { count: 0 };
  let secondSnapshot = { count: 0 };
  let drift = { driftDetected: false, driftClassification: "none" };
  let validation = { pass: true };
  let runtime = { pass: true };
  let parity = { pass: true };

  if (featureFlagEnabled) {
    firstProjection = gridlyMaybeGenerateHistoricalProjection("enablement_audit_first");
    secondProjection = gridlyGenerateHistoricalProjection("enablement_audit_repeat");
    firstSnapshot = gridlyHistoricalProjectionSnapshot(firstProjection);
    secondSnapshot = gridlyHistoricalProjectionSnapshot(secondProjection);
    drift = gridlyCompareHistoricalProjectionSnapshots(firstSnapshot, secondSnapshot);
    validation = gridlyHistoricalProjectionValidationAudit({ projection: secondProjection, sources: gridlyHistoricalProjectionCurrentSources() });
    runtime = gridlyHistoricalProjectionRuntimeAudit({ sources: gridlyHistoricalProjectionCurrentSources() });
    parity = gridlyHistoricalParityAudit({ includeSamples: false });
  }

  const afterIsolation = gridlyHistoricalProjectionProductionIsolationSnapshot();
  const isolation = gridlyHistoricalProjectionCompareIsolationSnapshots(beforeIsolation, afterIsolation);
  if (shouldForceEnable && typeof window !== "undefined") window.GRIDLY_ENABLE_HISTORICAL_PIPELINE = originalWindowFlag;

  const projectionGenerationSuccess = Boolean(secondProjection) && Array.isArray(secondProjection.incidents);
  const findings = featureFlagEnabled ? [
    { id: "feature-flag-state", pass: true, summary: shouldForceEnable ? "Historical shadow pipeline flag was force-enabled for this audit." : "Historical shadow pipeline flag is enabled for this audit." },
    { id: "projection-generation-success", pass: projectionGenerationSuccess, summary: projectionGenerationSuccess ? "Shadow projection generation completed without production writes." : "Shadow projection generation did not complete." },
    { id: "projection-generation-count", pass: firstSnapshot.count === secondSnapshot.count, summary: `Projection count stability: ${firstSnapshot.count} then ${secondSnapshot.count}.`, details: { firstCount: firstSnapshot.count, secondCount: secondSnapshot.count } },
    { id: "projection-availability", pass: Boolean(gridlyHistoricalProjection), summary: "Projection is available to shadow audit code only." },
    { id: "parity-state", pass: parity.pass === true, summary: parity.pass ? "Historical parity remains intact." : "Historical parity needs review." },
    { id: "drift-state", pass: drift.driftDetected === false, summary: drift.driftDetected ? "Repeat projection drift detected." : "Repeat projection is stable.", details: drift },
    { id: "runtime-state", pass: runtime.pass === true && validation.pass === true, summary: runtime.pass && validation.pass ? "Runtime and validation audits remain healthy." : "Runtime or validation audit needs review." },
    { id: "production-safety-state", pass: isolation.changed === false, summary: isolation.changed ? "Production-facing snapshot changed during shadow generation." : "Production-facing snapshot did not change during shadow generation.", details: isolation }
  ] : [
    { id: "feature-flag-state", pass: true, summary: "Historical shadow pipeline is disabled by design; default-off is a safe state until explicitly enabled." },
    { id: "projection-generation-state", pass: true, summary: "Projection generation was not required because the historical pipeline is default-disabled." },
    { id: "production-safety-state", pass: isolation.changed === false, summary: isolation.changed ? "Production-facing snapshot changed while historical pipeline was disabled." : "Production-facing snapshot remained isolated while historical pipeline was disabled.", details: isolation }
  ];

  return {
    pass: findings.every((finding) => finding.pass),
    generatedAt: new Date().toISOString(),
    featureFlagEnabled,
    featureFlagState: featureFlagEnabled ? "enabled" : "disabled-by-design",
    enablementStatus,
    forcedEnablementUsed: shouldForceEnable,
    shadowOnly: true,
    productionMutationPerformed: false,
    projectionGenerationSuccess: featureFlagEnabled ? projectionGenerationSuccess : false,
    projectionGenerationCount: featureFlagEnabled ? secondSnapshot.count : 0,
    projectionAvailable: featureFlagEnabled ? Boolean(secondProjection) : false,
    parityState: featureFlagEnabled ? (parity.pass ? "pass" : "fail") : "not-required-default-disabled",
    driftState: featureFlagEnabled ? (drift.driftDetected ? drift.driftClassification : "none") : "not-evaluated-default-disabled",
    runtimeState: featureFlagEnabled ? (runtime.pass ? "pass" : "fail") : "not-required-default-disabled",
    productionSafetyState: isolation.changed ? "changed" : "isolated",
    findings
  };
}

function gridlyHistoricalProjectionIsolationAudit(options = {}) {
  const originalWindowFlag = typeof window !== "undefined" ? window.GRIDLY_ENABLE_HISTORICAL_PIPELINE : undefined;
  if (options.forceEnable === true && typeof window !== "undefined") window.GRIDLY_ENABLE_HISTORICAL_PIPELINE = true;
  const auditedFeatureFlagEnabled = gridlyIsHistoricalPipelineEnabled();
  const before = gridlyHistoricalProjectionProductionIsolationSnapshot();
  if (gridlyIsHistoricalPipelineEnabled()) gridlyGenerateHistoricalProjection("isolation_audit");
  const after = gridlyHistoricalProjectionProductionIsolationSnapshot();
  const comparison = gridlyHistoricalProjectionCompareIsolationSnapshots(before, after);
  const report = {
    productionReadsChanged: false,
    productionWritesChanged: false,
    lifecycleChangesDetected: false,
    uiOwnershipChangesDetected: comparison.alertsChanged || comparison.routeWatchChanged,
    markerOwnershipChangesDetected: comparison.markersChanged,
    awarenessOwnershipChangesDetected: comparison.awarenessChanged
  };
  const findings = Object.entries(report).map(([id, value]) => ({ id, pass: value === false, expected: false, actual: value }));
  if (options.forceEnable === true && typeof window !== "undefined") window.GRIDLY_ENABLE_HISTORICAL_PIPELINE = originalWindowFlag;
  return { pass: findings.every((finding) => finding.pass) && !comparison.activeIncidentCountsChanged && !comparison.countReconciliationChanged, generatedAt: new Date().toISOString(), enabled: auditedFeatureFlagEnabled, forcedEnablementUsed: options.forceEnable === true, shadowOnly: true, productionMutationPerformed: false, ...report, activeIncidentCountsChanged: comparison.activeIncidentCountsChanged, countReconciliationOutputsChanged: comparison.countReconciliationChanged, comparison, findings };
}

function gridlyHistoricalProjectionHealthAudit() {
  const projection = gridlyHistoricalProjection;
  const generatedMs = gridlyHistoricalProjectionLastGeneratedAt ? new Date(gridlyHistoricalProjectionLastGeneratedAt).getTime() : NaN;
  return {
    projectionAvailable: Boolean(projection),
    projectionCount: Array.isArray(projection?.incidents) ? projection.incidents.length : 0,
    projectionAgeMs: Number.isFinite(generatedMs) ? Math.max(0, Date.now() - generatedMs) : null,
    generationStatus: gridlyHistoricalProjectionLastGenerationStatus,
    lastGenerationTimestamp: gridlyHistoricalProjectionLastGeneratedAt,
    driftStatus: gridlyHistoricalProjectionLastDriftStatus,
    validationStatus: gridlyHistoricalProjectionLastValidationStatus,
    enabled: gridlyIsHistoricalPipelineEnabled(),
    enablementStatus: gridlyIsHistoricalPipelineEnabled() ? "enabled" : "disabled-default",
    generationSuccess: gridlyHistoricalProjectionLastGenerationStatus === "generated" && Boolean(projection),
    isolationStatus: "shadow-only-production-isolated",
    shadowOnly: true,
    productionMutationPerformed: false
  };
}

function gridlyHistoricalFixtureSources(records = []) {
  return records.reduce((sources, record) => {
    const sourceKind = record.__sourceKind || "activeReports";
    const cleanRecord = { ...record };
    delete cleanRecord.__sourceKind;
    if (!Array.isArray(sources[sourceKind])) sources[sourceKind] = [];
    sources[sourceKind].push(cleanRecord);
    return sources;
  }, { activeHazards: [], activeReports: [], recentlyClearedRoadHazards: [], liveHazardIncidents: [] });
}

function gridlyHistoricalProjectionFixtureDefinitions() {
  const baseTime = "2026-01-01T12:00:00.000Z";
  return [
    { id: "single-hazard", category: "Hazards", records: [{ id: "haz-single", type: "flooding", roadName: "Main St", createdAt: baseTime }], expectedIncidents: 1 },
    { id: "duplicate-hazards", category: "Hazards", records: [{ id: "haz-dupe", type: "debris", roadName: "Oak Rd", createdAt: baseTime }, { id: "haz-dupe", type: "debris", roadName: "Oak Rd", createdAt: "2026-01-01T12:05:00.000Z" }], expectedIncidents: 1, expectedReportCount: 2 },
    { id: "same-type-same-location", category: "Hazards", records: [{ type: "flooding", roadName: "River Rd", createdAt: baseTime }, { type: "flooding", roadName: "River Rd", createdAt: "2026-01-01T12:06:00.000Z" }], expectedIncidents: 1 },
    { id: "same-type-nearby", category: "Hazards", records: [{ type: "flooding", roadName: "River Rd", lat: 30, lng: -95, createdAt: baseTime }, { type: "flooding", roadName: "River Rd near bridge", lat: 30.01, lng: -95.01, createdAt: "2026-01-01T12:06:00.000Z" }], expectedMinIncidents: 1 },
    { id: "different-type-same-location", category: "Hazards", records: [{ type: "flooding", roadName: "Pine St", createdAt: baseTime }, { type: "debris", roadName: "Pine St", createdAt: "2026-01-01T12:06:00.000Z" }], expectedIncidents: 2 },
    ...["flooding", "debris", "traffic backup", "other hazard", "downed power line"].map((type) => ({ id: `hazard-type-${type.replace(/\s+/g, "-")}`, category: "Hazard Types", records: [{ id: `type-${type}`, type, roadName: "Type Test Rd", createdAt: baseTime }], expectedIncidents: 1 })),
    { id: "blocked-crossing", category: "Crossings", records: [{ id: "crossing-blocked", eventType: "blocked crossing", crossingId: "cr-1", roadName: "Rail Rd", createdAt: baseTime }], expectedIncidents: 1 },
    { id: "crossing-clear", category: "Crossings", records: [{ id: "crossing-clear", eventType: "crossing clear", crossingId: "cr-1", roadName: "Rail Rd", createdAt: baseTime }], expectedIncidents: 1, expectedClearCount: 1 },
    { id: "clear", category: "Lifecycle", records: [{ id: "life-clear", type: "clear", roadName: "Clear Rd", createdAt: baseTime }], expectedClearCount: 1 },
    { id: "recently-cleared", category: "Lifecycle", records: [{ __sourceKind: "recentlyClearedRoadHazards", id: "recent-clear", type: "cleared", roadName: "Recent Rd", createdAt: baseTime }], expectedClearCount: 1 },
    { id: "expiration", category: "Lifecycle", records: [{ id: "expired", type: "flooding", status: "expired", roadName: "Old Rd", createdAt: baseTime }], expectedIncidents: 1 },
    { id: "rehydration-suppression", category: "Lifecycle", records: [{ id: "suppressed", type: "flooding", lifecycleState: "suppressed", roadName: "Guard Rd", createdAt: baseTime }], expectedIncidents: 1 },
    ...["county", "town", "selected area"].map((filter) => ({ id: `filter-${filter.replace(/\s+/g, "-")}`, category: "Filtering", records: [{ id: `filter-${filter}`, type: "debris", roadName: "Filter Rd", county: "Liberty", town: "Dayton", selectedArea: filter, createdAt: baseTime }], expectedIncidents: 1 })),
    { id: "duplicate-submit-malfunction", category: "Regression", records: [{ id: "submit-lock", type: "other hazard", roadName: "Bug Rd", createdAt: baseTime }, { id: "submit-lock", type: "other hazard", roadName: "Bug Rd", createdAt: baseTime }, { id: "submit-lock", type: "other hazard", roadName: "Bug Rd", createdAt: baseTime }], expectedIncidents: 1, expectedReportCount: 3 },
    { id: "confirmation-growth", category: "Regression", records: [{ id: "confirm-growth", type: "flooding", roadName: "Confirm Rd", createdAt: baseTime }, { id: "confirm-growth", type: "confirm", roadName: "Confirm Rd", createdAt: "2026-01-01T12:10:00.000Z", confirmed: true }], expectedConfirmationCount: 1 }
  ];
}

function gridlyValidateHistoricalProjectionFixture(fixture = {}) {
  const sources = gridlyHistoricalFixtureSources(fixture.records || []);
  const projection = buildHistoricalProjection(sources, { source: `fixture:${fixture.id}`, nowMs: Date.parse("2026-01-01T12:30:00.000Z") });
  const findings = gridlyHistoricalProjectionValidationFindings(projection, sources);
  const incidents = projection.incidents || [];
  const totals = incidents.reduce((acc, incident) => {
    acc.reportCount += Number(incident.reportCount || 0);
    acc.confirmationCount += Number(incident.confirmationCount || 0);
    acc.clearCount += Number(incident.clearCount || 0);
    return acc;
  }, { reportCount: 0, confirmationCount: 0, clearCount: 0 });
  const expectationPass = [
    fixture.expectedIncidents == null || incidents.length === fixture.expectedIncidents,
    fixture.expectedMinIncidents == null || incidents.length >= fixture.expectedMinIncidents,
    fixture.expectedReportCount == null || totals.reportCount === fixture.expectedReportCount,
    fixture.expectedConfirmationCount == null || totals.confirmationCount === fixture.expectedConfirmationCount,
    fixture.expectedClearCount == null || totals.clearCount === fixture.expectedClearCount
  ].every(Boolean);
  return { id: fixture.id, category: fixture.category, pass: expectationPass && findings.every((finding) => finding.pass), incidentCount: incidents.length, totals, findings };
}

function gridlyHistoricalFixtureParityValidation(options = {}) {
  const results = (options.fixtures || gridlyHistoricalProjectionFixtureDefinitions()).map(gridlyValidateHistoricalProjectionFixture);
  const categories = results.reduce((acc, result) => {
    if (!acc[result.category]) acc[result.category] = { total: 0, passed: 0 };
    acc[result.category].total += 1;
    if (result.pass) acc[result.category].passed += 1;
    return acc;
  }, {});
  return { pass: results.every((result) => result.pass), fixtureCount: results.length, categories, results, shadowOnly: true, productionMutationPerformed: false };
}

function gridlyHistoricalProjectionAudit() {
  const enabled = gridlyIsHistoricalPipelineEnabled();
  const projection = enabled ? (gridlyHistoricalProjection || gridlyGenerateHistoricalProjection("projection_audit")) : gridlyHistoricalProjection;
  const productionIncidents = typeof getLiveHazardIncidents === "function" ? getLiveHazardIncidents() : [];
  const parity = gridlyHistoricalParityAudit({ includeSamples: false });
  return {
    enabled,
    projectionAvailable: Boolean(projection),
    projectionCount: Array.isArray(projection?.incidents) ? projection.incidents.length : 0,
    activeIncidentCount: Array.isArray(productionIncidents) ? productionIncidents.length : 0,
    parityStatus: parity.pass ? "pass" : "fail",
    lastGeneratedAt: gridlyHistoricalProjectionLastGeneratedAt,
    shadowOnly: true,
    productionMutationPerformed: false
  };
}

function gridlyHistoricalParityAudit(options = {}) {
  const productionIncidents = typeof getLiveHazardIncidents === "function" ? getLiveHazardIncidents() : [];
  const projection = gridlyHistoricalProjection || (gridlyIsHistoricalPipelineEnabled() ? gridlyGenerateHistoricalProjection("parity_audit") : buildHistoricalProjection({ activeHazards, activeReports, recentlyClearedRoadHazards, liveHazardIncidents: productionIncidents }, { source: "parity_audit_preview" }));
  const productionIds = new Set(productionIncidents.map((incident, index) => gridlyHistoricalProjectionIncidentIdentity(incident, "production", index)));
  const projectionParityIncidents = (projection.incidents || []).filter((incident) => Array.isArray(incident.sourceKinds) ? incident.sourceKinds.includes("liveHazardIncidents") : true);
  const projectionIds = new Set(projectionParityIncidents.map((incident) => String(incident.incidentId)));
  const missingFromProjection = [...productionIds].filter((id) => !projectionIds.has(id));
  const extraInProjection = [...projectionIds].filter((id) => !productionIds.has(id));
  const differencesDetected = missingFromProjection.length + extraInProjection.length;
  const fixtureParity = gridlyHistoricalFixtureParityValidation();
  const runtimeAudit = gridlyHistoricalProjectionRuntimeAudit({ sources: { activeHazards, activeReports, recentlyClearedRoadHazards, liveHazardIncidents: productionIncidents } });
  const identityGroupingSummary = {
    productionIdentityCount: productionIds.size,
    projectionIdentityCount: projectionIds.size,
    duplicateProjectionGroups: (projection.incidents || []).filter((incident) => Number(incident.reportCount || 0) + Number(incident.confirmationCount || 0) + Number(incident.clearCount || 0) > 1).length,
    liveProjectionGroups: projectionParityIncidents.length
  };
  const differenceClassification = differencesDetected === 0 ? "none" : (missingFromProjection.length > 0 && extraInProjection.length > 0 ? "bidirectional" : (missingFromProjection.length > 0 ? "missing-from-projection" : "extra-in-projection"));
  return {
    pass: differencesDetected === 0 && fixtureParity.pass,
    differencesDetected,
    productionIncidentCount: productionIds.size,
    projectionCount: projectionIds.size,
    comparisonSummary: differencesDetected === 0 ? "Shadow projection incident identities match the current production incident view." : "Shadow projection identity differences detected; production behavior was not changed.",
    fixtureCoverageSummary: {
      pass: fixtureParity.pass,
      fixtureCount: fixtureParity.fixtureCount,
      categories: fixtureParity.categories
    },
    identityGroupingSummary,
    parityConfidence: differencesDetected === 0 && fixtureParity.pass && runtimeAudit.pass ? "high-shadow-validation" : "needs-review",
    shadowEnablementConfidence: gridlyIsHistoricalPipelineEnabled() && runtimeAudit.pass ? "enabled-shadow-stable" : "disabled-preview-only",
    productionIsolationConfidence: "high-shadow-isolation",
    projectionGenerationConfidence: runtimeAudit.pass ? "high" : "needs-review",
    runtimeStabilityConfidence: runtimeAudit.runtimeStabilityConfidence,
    driftClassification: runtimeAudit.projectionDriftDetection.driftClassification,
    determinismConfidence: runtimeAudit.determinismConfidence,
    differenceClassification,
    missingFromProjection: options.includeSamples === false ? missingFromProjection.length : missingFromProjection.slice(0, 20),
    extraInProjection: options.includeSamples === false ? extraInProjection.length : extraInProjection.slice(0, 20),
    fixtureResults: options.includeFixtureResults === true ? fixtureParity.results : undefined,
    shadowOnly: true,
    productionMutationPerformed: false
  };
}

