function gridlyReadHistoricalIntelligenceStorageSnapshot() {
  const fallback = gridlyCreateEmptyEventHistoryState();
  const raw = gridlySafeLocalStorageGet(GRIDLY_EVENT_HISTORY_STORAGE_KEY);
  if (!raw) {
    return {
      key: GRIDLY_EVENT_HISTORY_STORAGE_KEY,
      found: false,
      parseOk: true,
      state: fallback,
      storageReadError: null
    };
  }

  try {
    const parsed = JSON.parse(raw);
    return {
      key: GRIDLY_EVENT_HISTORY_STORAGE_KEY,
      found: true,
      parseOk: true,
      state: {
        ...fallback,
        ...(parsed && typeof parsed === "object" ? parsed : {}),
        crossingEvents: Array.isArray(parsed?.crossingEvents) ? parsed.crossingEvents : [],
        hazardEvents: Array.isArray(parsed?.hazardEvents) ? parsed.hazardEvents : [],
        operationalTelemetry: {
          ...fallback.operationalTelemetry,
          ...(parsed?.operationalTelemetry && typeof parsed.operationalTelemetry === "object" ? parsed.operationalTelemetry : {})
        }
      },
      storageReadError: null
    };
  } catch (error) {
    return {
      key: GRIDLY_EVENT_HISTORY_STORAGE_KEY,
      found: true,
      parseOk: false,
      state: fallback,
      storageReadError: error?.message || "invalid_event_history_storage"
    };
  }
}

function gridlyListHistoricalIntelligenceStorageKeys() {
  const matches = [];
  try {
    if (typeof localStorage === "undefined") return matches;
    for (let index = 0; index < localStorage.length; index += 1) {
      const key = localStorage.key(index);
      if (!key || !/gridly|history|historical|analytics|archive|event/i.test(key)) continue;
      const value = localStorage.getItem(key);
      matches.push({
        key,
        bytes: String(value || "").length,
        primaryHistoricalSource: key === GRIDLY_EVENT_HISTORY_STORAGE_KEY
      });
    }
  } catch (error) {
    matches.push({ key: "localStorage", readError: error?.message || "storage_key_scan_failed" });
  }
  return matches.sort((a, b) => Number(b.primaryHistoricalSource) - Number(a.primaryHistoricalSource) || String(a.key).localeCompare(String(b.key)));
}

function gridlyHistoricalAuditTimestamp(record = {}) {
  return record?.createdAt || record?.blockedAt || record?.submittedAt || record?.created_at || record?.reportedAt || record?.timestamp || null;
}

function gridlyHistoricalAuditDuration(record = {}) {
  const explicit = Number(record?.durationMinutes ?? record?.duration ?? record?.duration_min ?? record?.durationMins);
  if (Number.isFinite(explicit)) return Math.round(explicit);
  return gridlyMinutesBetween(gridlyHistoricalAuditTimestamp(record), record?.clearedAt || record?.cleared_at || null);
}

function gridlyHistoricalAuditRoad(record = {}) {
  const road = String(record?.roadName || record?.road || record?.resolvedRoadName || record?.primaryRoad || record?.routeName || "").trim();
  if (!road || road.toLowerCase() === "unknown road") return "";
  return road;
}

function gridlyHistoricalAuditCrossing(record = {}) {
  return String(record?.crossingName || record?.crossing || record?.crossing_id || record?.crossingId || "").trim();
}

function gridlyHistoricalAuditHazardType(record = {}) {
  return String(record?.hazardType || record?.type || record?.report_type || "").trim();
}

function gridlyHistoricalAuditLocationKey(record = {}, kind = "event") {
  if (kind === "crossing") return String(record?.crossingId || record?.crossing_id || gridlyHistoricalAuditCrossing(record) || "").trim().toLowerCase();
  return [gridlyHistoricalAuditHazardType(record), gridlyHistoricalAuditRoad(record)].filter(Boolean).join("|").toLowerCase();
}

function gridlyHistoricalAuditCountGroups(records = [], keyBuilder = () => "") {
  const counts = records.reduce((acc, record) => {
    const key = keyBuilder(record);
    if (!key) return acc;
    acc[key] = (acc[key] || 0) + 1;
    return acc;
  }, {});
  return {
    unique: Object.keys(counts).length,
    repeated: Object.values(counts).filter((count) => count >= 2).length,
    maxCount: Math.max(0, ...Object.values(counts))
  };
}

function gridlyHistoricalAuditReadiness({ ready, limited }) {
  if (ready) return "READY";
  if (limited) return "LIMITED";
  return "NOT_READY";
}

function gridlyBuildHistoricalIntelligenceReadiness(combinedEvents = [], crossingEvents = [], hazardEvents = []) {
  const repeatedHazards = gridlyHistoricalAuditCountGroups(hazardEvents, (event) => gridlyHistoricalAuditLocationKey(event, "hazard"));
  const floodEvents = hazardEvents.filter((event) => /flood|high_water|high water|water/.test(gridlyHistoricalAuditHazardType(event).toLowerCase()));
  const repeatedFloods = gridlyHistoricalAuditCountGroups(floodEvents, (event) => gridlyHistoricalAuditRoad(event).toLowerCase());
  const repeatedCrossings = gridlyHistoricalAuditCountGroups(crossingEvents, (event) => gridlyHistoricalAuditLocationKey(event, "crossing"));
  const constructionEvents = hazardEvents.filter((event) => /construction|roadwork|work_zone|work zone|lane_closure|closure/.test(gridlyHistoricalAuditHazardType(event).toLowerCase()));
  const repeatedConstruction = gridlyHistoricalAuditCountGroups(constructionEvents, (event) => gridlyHistoricalAuditRoad(event).toLowerCase());
  const trafficBackupEvents = hazardEvents.filter((event) => /traffic[_\s-]*backup|heavy[_\s-]*traffic|traffic[_\s-]*delay|congestion|heavy[_\s-]*delay/.test(gridlyHistoricalAuditHazardType(event).toLowerCase()));
  const repeatedTrafficBackups = gridlyHistoricalAuditCountGroups(trafficBackupEvents, (event) => gridlyHistoricalAuditRoad(event).toLowerCase());
  const durationEvents = combinedEvents.filter((event) => Boolean(gridlyHistoricalAuditRoad(event.record)) && Number.isFinite(Number(gridlyHistoricalAuditDuration(event.record))));
  const delayedCorridors = gridlyHistoricalAuditCountGroups(durationEvents.map((event) => event.record), (event) => gridlyHistoricalAuditRoad(event).toLowerCase());
  const confirmedEvents = combinedEvents.filter((event) => Number(event.record?.confirmationCount ?? event.record?.confirmations ?? event.record?.confirmation_count) >= 2);
  const confirmedHotspots = gridlyHistoricalAuditCountGroups(confirmedEvents, (event) => {
    const record = event.record || {};
    return gridlyHistoricalAuditRoad(record).toLowerCase() || gridlyHistoricalAuditLocationKey(record, event.kind);
  });
  const timestampedEvents = combinedEvents.filter((event) => Number.isFinite(new Date(gridlyHistoricalAuditTimestamp(event.record) || 0).getTime()) && new Date(gridlyHistoricalAuditTimestamp(event.record) || 0).getTime() > 0);
  const dayKeys = new Set(timestampedEvents.map((event) => new Date(gridlyHistoricalAuditTimestamp(event.record)).toISOString().slice(0, 10)));
  const hourBuckets = new Set(timestampedEvents.map((event) => Math.floor(new Date(gridlyHistoricalAuditTimestamp(event.record)).getUTCHours() / 4)));
  const timestamps = timestampedEvents.map((event) => new Date(gridlyHistoricalAuditTimestamp(event.record)).getTime()).sort((a, b) => a - b);
  const spanDays = timestamps.length > 1 ? Math.round((timestamps[timestamps.length - 1] - timestamps[0]) / 86400000) : 0;

  const categories = [
    {
      category: "RECURRING_HAZARDS",
      readiness: gridlyHistoricalAuditReadiness({ ready: hazardEvents.length >= 20 && repeatedHazards.repeated >= 3, limited: hazardEvents.length >= 3 && repeatedHazards.repeated >= 1 }),
      availableEventCount: hazardEvents.length,
      blockers: [
        hazardEvents.length < 20 ? "Needs more hazard history before broad recurring-hazard summaries are safe." : "",
        repeatedHazards.repeated < 3 ? "Needs more repeated same-type/same-road hazard clusters." : ""
      ].filter(Boolean)
    },
    {
      category: "FREQUENT_FLOOD_LOCATIONS",
      readiness: gridlyHistoricalAuditReadiness({ ready: floodEvents.length >= 10 && repeatedFloods.repeated >= 2, limited: floodEvents.length >= 2 && repeatedFloods.repeated >= 1 }),
      availableEventCount: floodEvents.length,
      blockers: [
        floodEvents.length < 10 ? "Needs more real flood or high-water events." : "",
        repeatedFloods.repeated < 2 ? "Needs repeated flood events on the same road/location." : ""
      ].filter(Boolean)
    },
    {
      category: "MOST_BLOCKED_CROSSINGS",
      readiness: gridlyHistoricalAuditReadiness({ ready: crossingEvents.length >= 20 && repeatedCrossings.repeated >= 3, limited: crossingEvents.length >= 3 && repeatedCrossings.repeated >= 1 }),
      availableEventCount: crossingEvents.length,
      blockers: [
        crossingEvents.length < 20 ? "Needs more crossing history." : "",
        repeatedCrossings.repeated < 3 ? "Needs repeated blockage records for multiple specific crossings." : ""
      ].filter(Boolean)
    },
    {
      category: "REPEAT_CONSTRUCTION_ZONES",
      readiness: gridlyHistoricalAuditReadiness({ ready: constructionEvents.length >= 8 && repeatedConstruction.repeated >= 2, limited: constructionEvents.length >= 2 && repeatedConstruction.repeated >= 1 }),
      availableEventCount: constructionEvents.length,
      blockers: [
        constructionEvents.length < 8 ? "Needs more construction/work-zone history." : "",
        repeatedConstruction.repeated < 2 ? "Needs repeated construction records by road/zone." : ""
      ].filter(Boolean)
    },
    {
      category: "TRAFFIC_BACKUP_CORRIDORS",
      readiness: gridlyHistoricalAuditReadiness({ ready: trafficBackupEvents.length >= 8 && repeatedTrafficBackups.repeated >= 2, limited: trafficBackupEvents.length >= 2 && repeatedTrafficBackups.repeated >= 1 }),
      availableEventCount: trafficBackupEvents.length,
      blockers: [
        trafficBackupEvents.length < 8 ? "Needs more traffic backup/heavy-delay history." : "",
        repeatedTrafficBackups.repeated < 2 ? "Needs repeated traffic backup records on the same corridors." : ""
      ].filter(Boolean)
    },
    {
      category: "HIGH_DELAY_CORRIDORS",
      readiness: gridlyHistoricalAuditReadiness({ ready: durationEvents.length >= 20 && delayedCorridors.repeated >= 3, limited: durationEvents.length >= 5 && delayedCorridors.repeated >= 1 }),
      availableEventCount: durationEvents.length,
      blockers: [
        durationEvents.length < 20 ? "Needs more closed events with usable durations and roads." : "",
        delayedCorridors.repeated < 3 ? "Needs repeated duration evidence on the same corridors." : ""
      ].filter(Boolean)
    },
    {
      category: "COMMUNITY_CONFIRMED_HOTSPOTS",
      readiness: gridlyHistoricalAuditReadiness({ ready: confirmedEvents.length >= 15 && confirmedHotspots.repeated >= 3, limited: confirmedEvents.length >= 3 && confirmedHotspots.repeated >= 1 }),
      availableEventCount: confirmedEvents.length,
      blockers: [
        confirmedEvents.length < 15 ? "Needs more records with two or more confirmations." : "",
        confirmedHotspots.repeated < 3 ? "Needs repeated confirmed records at the same locations." : ""
      ].filter(Boolean)
    },
    {
      category: "TIME_OF_DAY_PATTERNS",
      readiness: gridlyHistoricalAuditReadiness({ ready: timestampedEvents.length >= 30 && dayKeys.size >= 7 && hourBuckets.size >= 2, limited: timestampedEvents.length >= 10 && dayKeys.size >= 2 }),
      availableEventCount: timestampedEvents.length,
      blockers: [
        timestampedEvents.length < 30 ? "Needs more timestamped historical events." : "",
        dayKeys.size < 7 ? "Needs events across more distinct days." : "",
        hourBuckets.size < 2 ? "Needs enough variety to compare dayparts." : ""
      ].filter(Boolean)
    },
    {
      category: "SEASONAL_PATTERNS",
      readiness: gridlyHistoricalAuditReadiness({ ready: timestampedEvents.length >= 30 && spanDays >= 90, limited: timestampedEvents.length >= 10 && spanDays >= 30 }),
      availableEventCount: timestampedEvents.length,
      blockers: [
        timestampedEvents.length < 30 ? "Needs more timestamped historical events." : "",
        spanDays < 90 ? "Needs a longer historical time span before seasonal claims are safe." : ""
      ].filter(Boolean)
    }
  ];

  return { categories, diagnostics: { repeatedHazards, repeatedFloods, repeatedCrossings, repeatedConstruction, repeatedTrafficBackups, delayedCorridors, confirmedHotspots, distinctDays: dayKeys.size, daypartBuckets: hourBuckets.size, spanDays } };
}


function gridlyHistoricalClearTimeField(record = {}) {
  if (record?.clearedAt) return { field: "clearedAt", value: record.clearedAt };
  if (record?.cleared_at) return { field: "cleared_at", value: record.cleared_at };
  return { field: "", value: null };
}

function gridlyHistoricalCreatedTimeField(record = {}, kind = "event") {
  const fields = kind === "crossing"
    ? ["blockedAt", "createdAt", "submittedAt", "created_at", "reportedAt", "timestamp"]
    : ["createdAt", "submittedAt", "created_at", "reportedAt", "timestamp", "blockedAt"];
  for (const field of fields) {
    if (record?.[field]) return { field, value: record[field] };
  }
  return { field: "", value: null };
}

function gridlyHistoricalHasUsableIso(value) {
  const ms = new Date(value || 0).getTime();
  return Number.isFinite(ms) && ms > 0;
}

function gridlyHistoricalClearTimeCoverage(records = [], kind = "event") {
  const totalRecords = records.length;
  const created = records.filter((record) => gridlyHistoricalHasUsableIso(gridlyHistoricalCreatedTimeField(record, kind).value));
  const cleared = records.filter((record) => gridlyHistoricalHasUsableIso(gridlyHistoricalClearTimeField(record).value));
  const duration = records.filter((record) => Number.isFinite(Number(gridlyHistoricalAuditDuration(record))));
  const confirmed = records.filter((record) => Number.isFinite(Number(record?.confirmationCount ?? record?.confirmations ?? record?.confirmation_count)));
  return {
    totalRecords,
    createdAtCoverage: { count: created.length, missing: totalRecords - created.length, percent: totalRecords ? Math.round((created.length / totalRecords) * 100) : 0 },
    clearedAtCoverage: { count: cleared.length, missing: totalRecords - cleared.length, percent: totalRecords ? Math.round((cleared.length / totalRecords) * 100) : 0 },
    durationCoverage: { count: duration.length, missing: totalRecords - duration.length, percent: totalRecords ? Math.round((duration.length / totalRecords) * 100) : 0 },
    confirmationCoverage: { count: confirmed.length, missing: totalRecords - confirmed.length, percent: totalRecords ? Math.round((confirmed.length / totalRecords) * 100) : 0 }
  };
}

function gridlyHistoricalClearTimeSample(event = {}) {
  const record = event.record || {};
  const created = gridlyHistoricalCreatedTimeField(record, event.kind);
  const cleared = gridlyHistoricalClearTimeField(record);
  return {
    kind: event.kind,
    index: event.index,
    id: event.kind === "crossing" ? String(record.crossingId || record.crossing_id || "") : String(record.incidentId || record.id || record.crossingId || record.crossing_id || ""),
    roadName: gridlyHistoricalAuditRoad(record) || null,
    createdAt: created.value,
    createdAtSourceField: created.field || null,
    clearedAt: cleared.value,
    clearedAtSourceField: cleared.field || null,
    durationMinutes: Number.isFinite(Number(gridlyHistoricalAuditDuration(record))) ? Number(gridlyHistoricalAuditDuration(record)) : null,
    confirmationCount: Number.isFinite(Number(record.confirmationCount ?? record.confirmations ?? record.confirmation_count)) ? Number(record.confirmationCount ?? record.confirmations ?? record.confirmation_count) : null
  };
}

function gridlyHistoricalClearTimeAudit() {
  const storageSnapshot = gridlyReadHistoricalIntelligenceStorageSnapshot();
  const historicalState = storageSnapshot.state || gridlyCreateEmptyEventHistoryState();
  const crossingEvents = Array.isArray(historicalState.crossingEvents) ? historicalState.crossingEvents : [];
  const hazardEvents = Array.isArray(historicalState.hazardEvents) ? historicalState.hazardEvents : [];
  const combinedEvents = [
    ...crossingEvents.map((record, index) => ({ kind: "crossing", record, index })),
    ...hazardEvents.map((record, index) => ({ kind: "hazard", record, index }))
  ];
  const recordsWithCreatedAt = combinedEvents.filter((event) => gridlyHistoricalHasUsableIso(gridlyHistoricalCreatedTimeField(event.record, event.kind).value));
  const recordsWithClearedAt = combinedEvents.filter((event) => gridlyHistoricalHasUsableIso(gridlyHistoricalClearTimeField(event.record).value));
  const durationEligibleRecords = combinedEvents.filter((event) => {
    const created = gridlyHistoricalCreatedTimeField(event.record, event.kind).value;
    const cleared = gridlyHistoricalClearTimeField(event.record).value;
    return gridlyHistoricalHasUsableIso(created) && gridlyHistoricalHasUsableIso(cleared) && Number.isFinite(Number(gridlyMinutesBetween(created, cleared)));
  });
  const createdNoClear = combinedEvents.filter((event) => gridlyHistoricalHasUsableIso(gridlyHistoricalCreatedTimeField(event.record, event.kind).value) && !gridlyHistoricalHasUsableIso(gridlyHistoricalClearTimeField(event.record).value));
  const clearedNoDuration = combinedEvents.filter((event) => gridlyHistoricalHasUsableIso(gridlyHistoricalClearTimeField(event.record).value) && !Number.isFinite(Number(gridlyHistoricalAuditDuration(event.record))));
  const durationWithoutClear = combinedEvents.filter((event) => !gridlyHistoricalHasUsableIso(gridlyHistoricalClearTimeField(event.record).value) && Number.isFinite(Number(gridlyHistoricalAuditDuration(event.record))));
  const alternateClearOnly = combinedEvents.filter((event) => !event.record?.clearedAt && event.record?.cleared_at);
  const historyWritePaths = [
    {
      path: "gridlyCaptureCrossingHistoryEvent(report)",
      writesTo: "crossingEvents",
      trigger: "Crossing report submission, crossing clear submission, or batch capture from live reports.",
      createdAtSource: "gridlyBuildCrossingEvent() stores report.submittedAt || report.created_at || now as blockedAt.",
      clearedAtSource: "Only clear report types set target.clearedAt to report.submittedAt || report.created_at || now.",
      durationSource: "Only the clear branch sets durationMinutes with gridlyMinutesBetween(target.blockedAt, target.clearedAt)."
    },
    {
      path: "gridlyCaptureHazardHistoryEvent(report)",
      writesTo: "hazardEvents",
      trigger: "Hazard report submission, hazard clear submission, or batch capture from live reports.",
      createdAtSource: "gridlyBuildHazardEvent() stores report.submittedAt || report.created_at || now as createdAt.",
      clearedAtSource: "Only clear report types set target.clearedAt to report.submittedAt || report.created_at || now.",
      durationSource: "Only the clear branch sets durationMinutes with gridlyMinutesBetween(target.createdAt, target.clearedAt)."
    },
    {
      path: "gridlyCaptureHistoryFromReports(reports)",
      writesTo: "crossingEvents and hazardEvents through deferred capture helpers",
      trigger: "loadSharedReports() passes currently unexpired live reports after normalization.",
      createdAtSource: "Inherited from each normalized live report's created_at/submittedAt.",
      clearedAtSource: "Only present if the fetched report itself is a clear report or matches an existing open history event.",
      durationSource: "Inherited from the capture helper clear branch; active non-clear reports remain open."
    },
    {
      path: "gridlyReadEventHistoryState() normalization repair",
      writesTo: "gridlyEventHistoryV1 when duplicate/road-name cleanup changes stored history",
      trigger: "Read-time cleanup only after localStorage parse.",
      createdAtSource: "Preserves existing event timestamps.",
      clearedAtSource: "May preserve a duplicate event's clearedAt, but does not create new clear timestamps.",
      durationSource: "May preserve a duplicate event's durationMinutes, but does not calculate new durations."
    },
    {
      path: "gridlyClearTestData()",
      writesTo: "gridlyEventHistoryV1 reset to an empty history state",
      trigger: "Manual test cleanup with explicit confirmation.",
      createdAtSource: "None; deletes local history.",
      clearedAtSource: "None; bypasses clear conversion because it replaces the history state.",
      durationSource: "None; bypasses duration calculation because it replaces the history state."
    }
  ];
  const missingSources = [
    createdNoClear.length ? "Stored records are mostly open event captures: creation/blocked timestamps are written on report creation, while clear timestamps are only written by explicit clear report paths." : "Current records do not show a created-without-clear gap.",
    durationWithoutClear.length ? "Some records have duration without a clear timestamp; verify legacy conversion before trusting durations." : "No records currently prove duration was calculated while clear timestamps were discarded.",
    clearedNoDuration.length ? "Some cleared records lack durationMinutes, so duration calculation should be audited before activation." : "No cleared records currently show a missing-duration calculation gap.",
    "loadSharedReports() only selects unexpired reports; older clear rows can be absent from the batch path, leaving earlier created/open history records without a clear event.",
    "gridlyClearTestData() can erase local event history without first converting active records into cleared history."
  ];
  const gapAnalysis = {
    reportsNeverEnteringClearedState: {
      count: createdNoClear.length,
      examples: createdNoClear.slice(0, 5).map(gridlyHistoricalClearTimeSample),
      finding: createdNoClear.length ? "Current history contains creation timestamps but no clear timestamps, so these records still look open to duration analytics." : "No current examples."
    },
    clearEventsNotWrittenToHistory: {
      count: Math.max(0, (Number(historicalState?.operationalTelemetry?.reportsCreated) || 0) - (Number(historicalState?.operationalTelemetry?.reportsCleared) || 0)),
      examples: createdNoClear.slice(0, 5).map(gridlyHistoricalClearTimeSample),
      finding: "Evidence is indirect: clear timestamps are only added by clear report branches, and current created/open records have not been matched by those branches."
    },
    durationCalculationNeverTriggered: {
      count: createdNoClear.filter((event) => !Number.isFinite(Number(gridlyHistoricalAuditDuration(event.record)))).length,
      examples: createdNoClear.filter((event) => !Number.isFinite(Number(gridlyHistoricalAuditDuration(event.record)))).slice(0, 5).map(gridlyHistoricalClearTimeSample),
      finding: "Duration calculation is gated behind clear timestamps, so open records never become duration eligible."
    },
    clearTimestampsDiscarded: {
      count: alternateClearOnly.length + durationWithoutClear.length,
      examples: [...alternateClearOnly, ...durationWithoutClear].slice(0, 5).map(gridlyHistoricalClearTimeSample),
      finding: alternateClearOnly.length || durationWithoutClear.length ? "Potential legacy field mismatch or discarded clear timestamp evidence exists." : "No current stored records show clear timestamps being discarded after they were captured."
    },
    historicalConversionPathMissingFields: {
      count: createdNoClear.length,
      examples: createdNoClear.slice(0, 5).map(gridlyHistoricalClearTimeSample),
      finding: "The creation conversion path intentionally initializes clearedAt and durationMinutes as null; it depends on a later clear report to complete the record."
    },
    cleanupPathBypassingClearLogic: {
      count: 1,
      examples: [{ path: "gridlyClearTestData()", effect: "writes an empty gridlyEventHistoryV1 state instead of clearing active events" }],
      finding: "A manual cleanup path exists that bypasses clear-time and duration logic by resetting the local history store."
    },
    manualTestCleanupDeletingActiveRecordsBeforeClearHistoryIsWritten: {
      count: 1,
      examples: [{ path: "gridlyClearTestData()", requiredConfirmation: "CLEAR_TEST_DATA" }],
      finding: "This is possible when the cleanup helper is used before clear reports are submitted; current storage alone cannot prove how often it happened."
    }
  };
  const recordTypeAnalysis = {
    crossingHistory: gridlyHistoricalClearTimeCoverage(crossingEvents, "crossing"),
    hazardHistory: gridlyHistoricalClearTimeCoverage(hazardEvents, "hazard")
  };
  const currentClearTimeReadiness = recordsWithClearedAt.length === combinedEvents.length && combinedEvents.length > 0 ? "READY" : (recordsWithClearedAt.length > 0 ? "LIMITED" : "NOT_READY");
  const currentDurationReadiness = durationEligibleRecords.length >= 10 ? "LIMITED" : (durationEligibleRecords.length > 0 ? "LIMITED_SAMPLE_ONLY" : "NOT_READY");
  const futureReadiness = {
    currentDurationReadiness,
    currentClearTimeReadiness,
    canCalculateAverageDurations: durationEligibleRecords.length >= 10,
    canCalculateRecurringBlockageLength: crossingEvents.filter((record) => gridlyHistoricalHasUsableIso(gridlyHistoricalClearTimeField(record).value) && Number.isFinite(Number(gridlyHistoricalAuditDuration(record)))).length >= 10,
    canCalculateHazardPersistence: hazardEvents.filter((record) => gridlyHistoricalHasUsableIso(gridlyHistoricalClearTimeField(record).value) && Number.isFinite(Number(gridlyHistoricalAuditDuration(record)))).length >= 10,
    safestNextStep: "Keep this audit read-only; next, add a separate reviewed lifecycle/history-close design that writes clear timestamps and durations before any active record is removed or cleanup path resets history."
  };

  return {
    totalHistoricalRecords: combinedEvents.length,
    recordsWithCreatedAt: recordsWithCreatedAt.length,
    recordsWithClearedAt: recordsWithClearedAt.length,
    recordsMissingCreatedAt: combinedEvents.length - recordsWithCreatedAt.length,
    recordsMissingClearedAt: combinedEvents.length - recordsWithClearedAt.length,
    durationEligibleRecords: durationEligibleRecords.length,
    sampleRecords: combinedEvents.slice(0, 10).map(gridlyHistoricalClearTimeSample),
    recommendations: [
      "Do not activate duration intelligence until clearedAt coverage is representative and durationEligibleRecords is non-zero across both crossing and hazard history.",
      "Treat existing created-without-cleared records as open/incomplete, not as duration samples.",
      "Design the future fix around the clear transition: persist clearedAt and durationMinutes before active records expire, are filtered out, or are manually cleaned up."
    ],
    historyWritePaths,
    createdAtSources: historyWritePaths.map((path) => ({ path: path.path, source: path.createdAtSource })),
    clearedAtSources: historyWritePaths.map((path) => ({ path: path.path, source: path.clearedAtSource })),
    durationSources: historyWritePaths.map((path) => ({ path: path.path, source: path.durationSource })),
    missingSources,
    historyWritePathAnalysis: {
      historyWritePaths,
      createdAtSources: historyWritePaths.map((path) => ({ path: path.path, source: path.createdAtSource })),
      clearedAtSources: historyWritePaths.map((path) => ({ path: path.path, source: path.clearedAtSource })),
      durationSources: historyWritePaths.map((path) => ({ path: path.path, source: path.durationSource })),
      missingSources
    },
    recordTypeAnalysis,
    crossingHistory: recordTypeAnalysis.crossingHistory,
    hazardHistory: recordTypeAnalysis.hazardHistory,
    gapAnalysis,
    futureReadiness,
    currentDurationReadiness: futureReadiness.currentDurationReadiness,
    currentClearTimeReadiness: futureReadiness.currentClearTimeReadiness,
    canCalculateAverageDurations: futureReadiness.canCalculateAverageDurations,
    canCalculateRecurringBlockageLength: futureReadiness.canCalculateRecurringBlockageLength,
    canCalculateHazardPersistence: futureReadiness.canCalculateHazardPersistence,
    safestNextStep: futureReadiness.safestNextStep,
    auditOnly: true,
    writesPerformed: false,
    storage: {
      key: GRIDLY_EVENT_HISTORY_STORAGE_KEY,
      found: storageSnapshot.found,
      parseOk: storageSnapshot.parseOk,
      storageReadError: storageSnapshot.storageReadError || null,
      operationalTelemetry: historicalState.operationalTelemetry || null
    }
  };
}

function gridlyHistoricalIntelligenceAudit() {
  const storageSnapshot = gridlyReadHistoricalIntelligenceStorageSnapshot();
  const historicalState = storageSnapshot.state || gridlyCreateEmptyEventHistoryState();
  const crossingEvents = Array.isArray(historicalState.crossingEvents) ? historicalState.crossingEvents : [];
  const hazardEvents = Array.isArray(historicalState.hazardEvents) ? historicalState.hazardEvents : [];
  const combinedEvents = [
    ...crossingEvents.map((record, index) => ({ kind: "crossing", record, index })),
    ...hazardEvents.map((record, index) => ({ kind: "hazard", record, index }))
  ];
  const closedEvents = combinedEvents.filter((event) => Boolean(event.record?.clearedAt || event.record?.cleared_at || Number.isFinite(Number(gridlyHistoricalAuditDuration(event.record)))));
  const openEvents = combinedEvents.filter((event) => !event.record?.clearedAt && !event.record?.cleared_at && !Number.isFinite(Number(gridlyHistoricalAuditDuration(event.record))));
  const timestamped = combinedEvents
    .map((event) => gridlyHistoricalAuditTimestamp(event.record))
    .filter((value) => Number.isFinite(new Date(value || 0).getTime()) && new Date(value || 0).getTime() > 0)
    .sort((a, b) => new Date(a).getTime() - new Date(b).getTime());
  const activeLifecycleClassifications = [
    ...gridlyDiagnosticArray(activeHazards).map((record, index) => gridlyClassifyHazardLifecycleFrameworkRecord({ record, sourceKind: "activeHazards", index, sourceHazards: gridlyDiagnosticArray(activeHazards), sourceReports: gridlyDiagnosticArray(activeReports) })),
    ...gridlyDiagnosticArray(activeReports).map((record, index) => gridlyClassifyHazardLifecycleFrameworkRecord({ record, sourceKind: "activeReports", index, sourceHazards: gridlyDiagnosticArray(activeHazards), sourceReports: gridlyDiagnosticArray(activeReports) }))
  ];
  const lifecycleHistoricalCandidates = activeLifecycleClassifications.filter((item) => item.historicalEligible);
  const readinessModel = gridlyBuildHistoricalIntelligenceReadiness(combinedEvents, crossingEvents, hazardEvents);
  const readyCategories = readinessModel.categories.filter((item) => item.readiness === "READY").map((item) => item.category);
  const limitedCategories = readinessModel.categories.filter((item) => item.readiness === "LIMITED").map((item) => item.category);
  const notReadyCategories = readinessModel.categories.filter((item) => item.readiness === "NOT_READY").map((item) => item.category);
  const totalHistoricalEvents = combinedEvents.length;
  const gapAnalysis = combinedEvents.reduce((acc, event) => {
    const record = event.record || {};
    if (!gridlyHistoricalAuditRoad(record)) acc.missingRoadNames += 1;
    if (!Number.isFinite(Number(gridlyHistoricalAuditDuration(record)))) acc.missingDurations += 1;
    if (!Number.isFinite(Number(record.confirmationCount ?? record.confirmations ?? record.confirmation_count))) acc.missingConfirmations += 1;
    if (!record.clearedAt && !record.cleared_at) acc.missingClearTimes += 1;
    if (event.kind === "crossing" && !String(record.crossingId || record.crossing_id || "").trim()) acc.missingCrossingIds += 1;
    if (event.kind === "hazard" && !gridlyHistoricalAuditHazardType(record)) acc.missingHazardTypes += 1;
    return acc;
  }, {
    missingRoadNames: 0,
    missingDurations: 0,
    missingConfirmations: 0,
    missingClearTimes: 0,
    missingCrossingIds: 0,
    missingHazardTypes: 0,
    insufficientHistoricalVolume: totalHistoricalEvents < 30 ? 30 - totalHistoricalEvents : 0
  });
  const sampleHistoricalRecords = combinedEvents.slice(0, 10).map((event) => {
    const record = event.record || {};
    return {
      type: event.kind === "crossing" ? (record.eventType || gridlyNormalizeCrossingEventType(record)) : gridlyHistoricalAuditHazardType(record),
      road: gridlyHistoricalAuditRoad(record),
      crossing: event.kind === "crossing" ? gridlyHistoricalAuditCrossing(record) : "",
      createdAt: gridlyHistoricalAuditTimestamp(record),
      clearedAt: record.clearedAt || record.cleared_at || null,
      duration: gridlyHistoricalAuditDuration(record),
      confirmationCount: Number.isFinite(Number(record.confirmationCount ?? record.confirmations ?? record.confirmation_count)) ? Number(record.confirmationCount ?? record.confirmations ?? record.confirmation_count) : null
    };
  });
  const sampleLifecycleHistoricalCandidates = lifecycleHistoricalCandidates.slice(0, 10).map((item) => ({
    category: item.category,
    ageHours: item.ageHours,
    lifecycleState: item.lifecycleState,
    trustLabel: item.trustLabel,
    historicalEligible: item.historicalEligible
  }));
  const eventCounts = {
    totalHistoricalEvents,
    crossingEvents: crossingEvents.length,
    hazardEvents: hazardEvents.length,
    openEvents: openEvents.length,
    closedEvents: closedEvents.length,
    earliestEvent: timestamped[0] || null,
    latestEvent: timestamped[timestamped.length - 1] || null,
    lifecycleHistoricalCandidates: lifecycleHistoricalCandidates.length
  };
  const historicalSources = [
    {
      source: "gridlyEventHistoryV1",
      storageKey: GRIDLY_EVENT_HISTORY_STORAGE_KEY,
      found: storageSnapshot.found,
      parseOk: storageSnapshot.parseOk,
      storageReadError: storageSnapshot.storageReadError,
      crossingEvents: crossingEvents.length,
      hazardEvents: hazardEvents.length,
      writesPerformed: false
    },
    {
      source: "crossing history",
      storageKey: GRIDLY_EVENT_HISTORY_STORAGE_KEY,
      found: crossingEvents.length > 0,
      eventCount: crossingEvents.length,
      writesPerformed: false
    },
    {
      source: "hazard history",
      storageKey: GRIDLY_EVENT_HISTORY_STORAGE_KEY,
      found: hazardEvents.length > 0,
      eventCount: hazardEvents.length,
      writesPerformed: false
    },
    {
      source: "historical analytics storage / existing event archives",
      localStorageKeys: gridlyListHistoricalIntelligenceStorageKeys(),
      writesPerformed: false
    }
  ];
  const intelligenceReadiness = {
    overallReadiness: readyCategories.length >= 3 ? "READY" : (readyCategories.length + limitedCategories.length > 0 ? "LIMITED" : "NOT_READY"),
    answer: readyCategories.length >= 3
      ? "Gridly appears to have enough real historical volume for limited community-intelligence pilots, but activation still needs a separate safety/UI/analytics review."
      : (readyCategories.length + limitedCategories.length > 0
        ? "Gridly has some useful real history, but it is only limited and should not yet produce broad community intelligence."
        : "Gridly does not currently have enough real historical data to produce meaningful community intelligence."),
    categories: readinessModel.categories,
    diagnostics: readinessModel.diagnostics
  };
  const findingAudit = gridlyBuildHistoricalIntelligenceFindings();
  const recommendations = {
    gapAnalysis,
    futureReadiness: {
      currentHistoricalVolume: totalHistoricalEvents,
      estimatedTrendReadiness: intelligenceReadiness.overallReadiness,
      strongestCategories: [...readyCategories, ...limitedCategories].slice(0, 4),
      weakestCategories: notReadyCategories,
      safestNextStep: totalHistoricalEvents >= 30
        ? "Continue read-only validation with representative real records; require a separate activation task before generating or displaying trends."
        : "Keep collecting real closed/open historical events with road names, crossing IDs, clear times, durations, hazard types, and confirmation counts before activating intelligence."
    },
    auditOnly: true,
    activationPerformed: false,
    protectedSystemsChanged: false
  };

  const roadClearedTrace = gridlyBuildRoadClearedLifecycleTrace();

  return {
    ...roadClearedTrace,
    historicalSources,
    eventCounts,
    intelligenceReadiness,
    sampleHistoricalRecords,
    sampleLifecycleHistoricalCandidates,
    rawFindingCount: Number(findingAudit.rawFindingCount || 0),
    dedupedFindingCount: Number(findingAudit.dedupedFindingCount || 0),
    groupedFindingCount: Number(findingAudit.groupedFindingCount || 0),
    suppressedFindingCount: Number(findingAudit.suppressedFindingCount || 0),
    strongestFinding: findingAudit.strongestFinding || null,
    rankedFindings: findingAudit.rankedFindings || [],
    dedupedRankedFindings: findingAudit.dedupedRankedFindings || [],
    suppressedFindingsSample: findingAudit.suppressedFindingsSample || [],
    groupingReasons: findingAudit.groupingReasons || [],
    noPreviewLanguage: true,
    recommendations
  };
}


function gridlyHistoricalClosePathFramework() {
  const closeStates = [
    {
      state: "ACTIVE",
      purpose: "Represents a live report that has a createdAt timestamp but has not entered any reviewed close path.",
      requiredInputs: ["incidentId or stable record id", "hazardType or crossing/event type", "createdAt", "locationKey", "source"],
      historicalOutcome: "Remain excluded from duration intelligence because clearedAt and durationMinutes are not available."
    },
    {
      state: "CLEARED_BY_DRIVER",
      purpose: "Documents a direct driver clear report for the same incident, road segment, crossing, or location key.",
      requiredInputs: ["incidentId/locationKey match", "createdAt", "driver clear submittedAt used as clearedAt", "clearedBy/source metadata"],
      historicalOutcome: "Eligible to become a closed historical record after audit validation confirms the clear report matches the active record."
    },
    {
      state: "CLEARED_BY_COMMUNITY",
      purpose: "Documents multiple independent community clear confirmations for the same active condition.",
      requiredInputs: ["incidentId/locationKey match", "createdAt", "clear confirmation count", "latest qualifying clear timestamp as clearedAt", "confirmation source summary"],
      historicalOutcome: "Eligible for historical storage with community confidence context, while preserving that the clear signal was community-derived."
    },
    {
      state: "CLEARED_BY_TRUSTED_SOURCE",
      purpose: "Documents a clear signal from a trusted, reviewed, official, or system-owned source.",
      requiredInputs: ["incidentId/locationKey match", "createdAt", "trusted-source clear timestamp as clearedAt", "trusted source identity/category"],
      historicalOutcome: "Highest-confidence close candidate for duration analytics once side-by-side write audits prove field quality."
    },
    {
      state: "EXPIRED_UNCONFIRMED",
      purpose: "Represents a future non-destructive expiration candidate when an active record ages out without a clear signal.",
      requiredInputs: ["incidentId/locationKey", "createdAt", "age threshold", "absence of recent confirmation", "expiration reason"],
      historicalOutcome: "Should not produce durationMinutes unless a reviewed policy explicitly treats expiration time as a separate non-clear terminal timestamp."
    },
    {
      state: "HISTORICAL",
      purpose: "Represents a closed record preserved for audit, duration, recurrence, and future community intelligence review.",
      requiredInputs: ["incidentId", "createdAt", "clearedAt for duration-eligible records", "durationMinutes", "hazardType/event type", "location fields", "source and confirmation metadata"],
      historicalOutcome: "Available for read-only duration and trend audits after the close path is activated in a separate implementation task."
    }
  ];

  const closeTriggers = [
    {
      trigger: "User reports clear",
      recommendedState: "CLEARED_BY_DRIVER",
      recommendationOnly: true,
      recommendedInputs: ["active incident match", "clear report timestamp", "reporter/source category", "locationKey"],
      notes: "Use only after a future write path validates that the clear report is tied to the active record being closed."
    },
    {
      trigger: "Multiple users report clear",
      recommendedState: "CLEARED_BY_COMMUNITY",
      recommendationOnly: true,
      recommendedInputs: ["active incident match", "minimum independent clear confirmations", "latest or policy-selected clear timestamp", "confirmationCount"],
      notes: "Require deduplication and anti-spam review before this can close a live record."
    },
    {
      trigger: "Trusted source indicates clear",
      recommendedState: "CLEARED_BY_TRUSTED_SOURCE",
      recommendationOnly: true,
      recommendedInputs: ["trusted source identity", "active incident match", "trusted clear timestamp", "source confidence"],
      notes: "Safest future close trigger, but still needs audit-only validation before runtime writes."
    },
    {
      trigger: "Future expiration path",
      recommendedState: "EXPIRED_UNCONFIRMED",
      recommendationOnly: true,
      recommendedInputs: ["createdAt", "age threshold", "confirmation freshness", "expiration reason"],
      notes: "Expiration is not equivalent to clearedAt; keep it separate from duration analytics unless a future policy explicitly defines it."
    },
    {
      trigger: "Manual moderation action",
      recommendedState: "CLEARED_BY_TRUSTED_SOURCE",
      recommendationOnly: true,
      recommendedInputs: ["moderator action timestamp", "reason", "active incident match", "moderation source"],
      notes: "Preserve moderation provenance so historical records remain auditable."
    }
  ];

  const closeRules = {
    frameworkOnly: true,
    activationPerformed: false,
    runtimeWritesPerformed: false,
    requiredCloseTimestamp: "clearedAt must be written by an explicit close transition, not inferred from createdAt.",
    matchingPrinciples: [
      "Prefer incidentId when available.",
      "Fall back to locationKey plus hazardType/crossing identity only after audit validation.",
      "Do not close unrelated records that merely share a road name.",
      "Preserve source provenance for every close path."
    ],
    nonDestructiveRequirement: "A future close path should persist the historical record before any active-list cleanup removes or hides the live record.",
    explicitNonGoals: [
      "No Supabase writes in this framework.",
      "No active hazard mutation in this framework.",
      "No map, marker, alert, header, route, refresh, analytics, or telemetry behavior changes.",
      "No duration or community-intelligence activation."
    ]
  };

  const durationRules = {
    fields: {
      createdAt: "Required ISO timestamp captured when the report first becomes active or historically stored.",
      clearedAt: "Required ISO timestamp captured only by a reviewed close transition.",
      durationMinutes: "Computed in a future write path as the non-negative minute difference between createdAt and clearedAt.",
      durationHours: "Derived display/audit value equal to durationMinutes / 60, rounded only for presentation.",
      durationBuckets: ["0-15 min", "15-60 min", "1-4 hr", "4-12 hr", "12-24 hr", "24+ hr"]
    },
    eligibility: [
      "createdAt and clearedAt must both be valid timestamps.",
      "clearedAt must be greater than or equal to createdAt.",
      "durationMinutes must be finite and non-negative.",
      "EXPIRED_UNCONFIRMED records are excluded from clear-time duration analytics unless separately modeled."
    ],
    bucketDefinitions: [
      { bucket: "0-15 min", minInclusive: 0, maxExclusive: 15 },
      { bucket: "15-60 min", minInclusive: 15, maxExclusive: 60 },
      { bucket: "1-4 hr", minInclusive: 60, maxExclusive: 240 },
      { bucket: "4-12 hr", minInclusive: 240, maxExclusive: 720 },
      { bucket: "12-24 hr", minInclusive: 720, maxExclusive: 1440 },
      { bucket: "24+ hr", minInclusive: 1440, maxExclusive: null }
    ],
    activationState: "framework_only"
  };

  const historicalTransitionRules = {
    whenRecordBecomesHistorical: [
      "After a future close trigger selects a terminal close state and writes clearedAt, durationMinutes, and close provenance.",
      "After a future audited expiration path marks EXPIRED_UNCONFIRMED without treating it as a cleared duration sample.",
      "After side-by-side history write audits confirm no active runtime behavior changes and no historical field loss."
    ],
    fieldsToPreserve: [
      "incidentId",
      "hazardType",
      "roadName",
      "crossingName",
      "createdAt",
      "clearedAt",
      "durationMinutes",
      "confirmationCount",
      "source",
      "locationKey",
      "closeState",
      "closeTrigger",
      "clearedBy",
      "latitude",
      "longitude"
    ],
    transitionGuardrails: [
      "Do not overwrite createdAt during close.",
      "Do not synthesize clearedAt from page refresh time or cleanup time.",
      "Write historical data before removing an active record from live collections.",
      "Keep expired-unconfirmed records distinguishable from cleared records.",
      "Keep transition auditing read-only until a separate runtime write-path task is approved."
    ],
    activationState: "not_active"
  };

  const communityIntelligenceReadiness = {
    supportsAverageDurations: true,
    supportsRecurringBlockageLength: true,
    supportsHazardPersistence: true,
    supportsFutureCommunityIntelligence: true,
    readinessBenefits: [
      "A formal close path would make clearedAt coverage measurable instead of absent.",
      "DurationMinutes would allow average blockage and persistence audits without guessing from active record age.",
      "Historical records could preserve source and confirmation context for safer future trend labels."
    ],
    activationRisks: [
      "Premature activation could misclassify open records as cleared.",
      "Expiration timestamps could be mistaken for true clear times if not modeled separately.",
      "Sparse or biased clear reporting could produce misleading duration averages.",
      "Runtime writes need schema, telemetry, analytics, and rollback review before use."
    ],
    guardrails: [
      "Keep this framework recommendation-only.",
      "Require audit-only validation before writing clearedAt.",
      "Require side-by-side history write audit before mutating runtime data.",
      "Separate cleared, trusted-cleared, community-cleared, and expired-unconfirmed outcomes.",
      "Do not activate community intelligence until duration coverage is representative."
    ]
  };

  const recommendations = {
    safestSequence: [
      "1. Close-path framework",
      "2. Audit-only validation",
      "3. Side-by-side history write audit",
      "4. Runtime write path",
      "5. Duration analytics",
      "6. Community intelligence activation"
    ],
    immediateNextStep: "Validate this returned framework against real historical clear-time audit outputs without writing storage or changing UI/runtime behavior.",
    protectedSystemsUnchanged: [
      "Portrait V2",
      "Header ownership",
      "Alert ownership/rendering",
      "Route Watch and OSRM routing",
      "Supabase",
      "TxDOT and rail crossings",
      "Settings",
      "Analytics and telemetry schemas",
      "Map and marker ownership",
      "Refresh loops and lifecycle behavior",
      "Trust progression and community intelligence activation"
    ],
    communityIntelligenceReadiness
  };

  return {
    closeStates,
    closeTriggers,
    closeRules,
    durationRules,
    historicalTransitionRules,
    recommendations
  };
}

