window.gridlyCaptureCommuteBaselineSample = function gridlyCaptureCommuteBaselineSampleAudit() {
  return gridlyCaptureCommuteBaselineSampleImpl();
};

function gridlyGetLocationPermissionDiagnostic() {
  if (typeof navigator === "undefined") return "navigator_unavailable";
  if (typeof navigator.geolocation === "undefined") return "geolocation_unavailable";
  if (gridlyCachedGeolocationPermissionStatus) return gridlyCachedGeolocationPermissionStatus;
  if (navigator.permissions?.query) return "permissions_api_available_async_status_not_queried";
  return "geolocation_available_permission_unknown";
}

function gridlyIsUsableLocationCoordinate(candidate = {}) {
  const lat = Number(candidate?.lat ?? candidate?.latitude);
  const lng = Number(candidate?.lng ?? candidate?.lon ?? candidate?.longitude);
  return Number.isFinite(lat) && Number.isFinite(lng) && Math.abs(lat) <= 90 && Math.abs(lng) <= 180;
}

function gridlyGetUsableLocationReadiness() {
  const candidates = [
    typeof userLocation !== "undefined" ? userLocation : null,
    typeof window !== "undefined" ? window.gridlyUserLocation : null,
    typeof window !== "undefined" ? window.__gridlyUserLocation : null,
    typeof window !== "undefined" ? window.gridlyCurrentLocation : null,
    typeof window !== "undefined" ? window.__gridlyCurrentLocation : null
  ];
  return candidates.some((candidate) => gridlyIsUsableLocationCoordinate(candidate));
}

function gridlyPrimeGeolocationPermissionStatus() {
  try {
    if (typeof navigator === "undefined" || typeof navigator.geolocation === "undefined") return false;
    if (!navigator.permissions?.query || gridlyGeolocationPermissionQueryInFlight) return false;
    gridlyGeolocationPermissionQueryInFlight = true;
    navigator.permissions.query({ name: "geolocation" }).then((status) => {
      gridlyCachedGeolocationPermissionStatus = status?.state || null;
      if (status && "onchange" in status) {
        status.onchange = () => {
          gridlyCachedGeolocationPermissionStatus = status.state || null;
        };
      }
    }).catch(() => {
      gridlyCachedGeolocationPermissionStatus = null;
    }).finally(() => {
      gridlyGeolocationPermissionQueryInFlight = false;
    });
    return true;
  } catch (_error) {
    gridlyGeolocationPermissionQueryInFlight = false;
    return false;
  }
}

window.gridlyHazardLifecycleBlueprint = function gridlyHazardLifecycleBlueprint() {
  const hazardRecords = gridlyDiagnosticArray(activeHazards).filter((hazard) => hazard && typeof hazard === "object");
  const activeHazardRecords = hazardRecords.filter((hazard) => gridlyIsActiveHazardRecord(hazard));
  const confirmedHazards = activeHazardRecords.filter((hazard) => gridlyIsConfirmedHazardRecord(hazard));
  const hazardTypeCounts = activeHazardRecords.reduce((counts, hazard) => {
    const type = gridlyNormalizeHazardType(hazard);
    counts[type] = (counts[type] || 0) + 1;
    return counts;
  }, {});

  return {
    blueprintVersion: GRIDLY_USER_TRUST_BLUEPRINT_VERSION,
    activeHazardCount: activeHazardRecords.length,
    confirmedHazardCount: confirmedHazards.length,
    unverifiedHazardCount: Math.max(0, activeHazardRecords.length - confirmedHazards.length),
    hazardTypeCounts,
    lifecycleClassifierAvailable: typeof gridlyClassifyHazardLifecycle === "function",
    lifecycleAuditAvailable: typeof window.gridlyHazardLifecycleAudit === "function",
    recommendedLifecycleRules: {
      unverified: [
        { age: "0-30m", lifecycleState: "new", recommendedAction: "keep_active" },
        { age: "30-60m", lifecycleState: "active", recommendedAction: "keep_active" },
        { age: "60-120m", lifecycleState: "aging", recommendedAction: "request_confirmation" },
        { age: "120m+", lifecycleState: "expired_candidate", recommendedAction: "expired_candidate" }
      ],
      confirmed: [
        { age: "0-2h", lifecycleState: "active", recommendedAction: "keep_active" },
        { age: "2-6h", lifecycleState: "verified", recommendedAction: "keep_active" },
        { age: "6-12h", lifecycleState: "aging", recommendedAction: "reduce_confidence" },
        { age: "12h+", lifecycleState: "expired_candidate", recommendedAction: "expired_candidate" }
      ],
      construction: [
        { age: "0-24h", lifecycleState: "active", recommendedAction: "keep_active" },
        { age: "24-72h", lifecycleState: "aging", recommendedAction: "reduce_confidence" },
        { age: "72h+", lifecycleState: "expired_candidate", recommendedAction: "expired_candidate" }
      ],
      flooding: [
        { age: "0-6h", lifecycleState: "active", recommendedAction: "keep_active" },
        { age: "6-24h", lifecycleState: "aging", recommendedAction: "request_confirmation" },
        { age: "24h+", lifecycleState: "expired_candidate", recommendedAction: "expired_candidate", marker: "extended_retention_candidate" }
      ],
      railBlockage: [
        { age: "0-30m", lifecycleState: "active", recommendedAction: "keep_active" },
        { age: "30-60m", lifecycleState: "aging", recommendedAction: "request_confirmation" },
        { age: "60m+", lifecycleState: "expired_candidate", recommendedAction: "expired_candidate", marker: "event_driven_candidate" }
      ]
    },
    notes: ["Lifecycle classifier is read-only; no Supabase deletes, cleanup, hard purge, map removal, or alert-panel removal are applied."]
  };
};

window.gridlyHazardLifecycleAudit = function gridlyHazardLifecycleAudit(options = {}) {
  const sourceHazards = Array.isArray(options?.hazards)
    ? options.hazards
    : (Array.isArray(activeHazards) ? activeHazards : []);
  const sourceReports = Array.isArray(options?.reports)
    ? options.reports
    : (Array.isArray(activeReports) ? activeReports : []);
  const sourceRecords = [
    ...sourceHazards.map((record) => ({ record, sourceKind: "activeHazards" })),
    ...sourceReports.map((record) => ({ record, sourceKind: "activeReports" }))
  ]
    .filter(({ record }) => record && typeof record === "object")
    .filter(({ record }) => gridlyIsActiveHazardRecord(record) || gridlyIsRoadClearedHazardRecord(record));
  const classifications = sourceRecords.map(({ record, sourceKind }, index) => ({
    id: record?.id || record?.reportId || record?.crossingId || `${record?.type || record?.report_type || "hazard"}-${index}`,
    sourceKind,
    rawType: record?.type || record?.report_type || record?.category || "unknown",
    ...gridlyClassifyHazardLifecycle(record, options)
  }));
  const byType = classifications.reduce((acc, entry) => {
    const type = entry.lifecycleType || "unknown";
    if (!acc[type]) acc[type] = { total: 0, active: 0, verified: 0, aging: 0, expired_candidate: 0, historical: 0, request_confirmation: 0 };
    acc[type].total += 1;
    const stageKey = String(entry.lifecycleStage || "").toLowerCase();
    if (acc[type][stageKey] !== undefined) acc[type][stageKey] += 1;
    if (entry.lifecycleRecommendedAction === "request_confirmation") acc[type].request_confirmation += 1;
    return acc;
  }, {});
  const stageCount = (stage) => classifications.filter((entry) => String(entry.lifecycleStage || "").toLowerCase() === String(stage || "").toLowerCase()).length;
  const requestConfirmationCount = classifications.filter((entry) => entry.lifecycleRecommendedAction === "request_confirmation").length;
  const roadClearedTrace = gridlyBuildRoadClearedLifecycleTrace({ hazards: sourceHazards, reports: sourceReports });
  return {
    ...roadClearedTrace,
    totalClassified: classifications.length,
    activeCount: stageCount("active") + stageCount("new") + stageCount("verified"),
    agingCount: stageCount("aging"),
    expiredCandidateCount: stageCount("expired_candidate"),
    historicalCount: stageCount("historical"),
    requestConfirmationCount,
    byType,
    sampleClassifications: classifications.slice(0, 10),
    lifecycleRulesApplied: window.gridlyHazardLifecycleBlueprint?.().recommendedLifecycleRules || {},
    destructiveActionsTaken: false
  };
};

function gridlyGetTravelTimeImpactReadiness(routeGeometry = gridlyGetRouteGeometryDiagnostics()) {
  const counts = gridlyCommuteIntelligenceAuditState?.counts || {};
  const hasRouteImpactSnapshot = Object.prototype.hasOwnProperty.call(counts, "routeIncidentCount");
  const hasCorridorSnapshot = Object.prototype.hasOwnProperty.call(counts, "corridorCount");
  const activeRouteImpactCount = Math.max(0, Number(counts.routeIncidentCount || 0));
  const activeCorridorImpactCount = Math.max(0, Number(counts.corridorCount || 0));
  return {
    activeRouteImpactCount,
    activeCorridorImpactCount,
    routeImpactReady: Boolean(routeGeometry.routeGeometryAvailable && hasRouteImpactSnapshot && hasCorridorSnapshot),
    routeImpactUnavailableReasons: [
      !routeGeometry.routeGeometryAvailable ? "route_geometry_unavailable" : "",
      !hasRouteImpactSnapshot ? "route_impact_snapshot_unavailable" : "",
      !hasCorridorSnapshot ? "corridor_impact_snapshot_unavailable" : ""
    ].filter(Boolean),
    routeImpactSource: "gridlyCommuteIntelligenceAuditState.counts"
  };
}

function gridlyResolveCurrentCommuteRouteStatus(routeImpactCount = 0, corridorImpactCount = 0) {
  const safeRouteImpactCount = Math.max(0, Number(routeImpactCount || 0));
  const safeCorridorImpactCount = Math.max(0, Number(corridorImpactCount || 0));
  if (safeRouteImpactCount >= 2 || safeCorridorImpactCount >= 2) return "impacted";
  if (safeRouteImpactCount > 0 || safeCorridorImpactCount > 0) return "minor_impacts";
  return "normal";
}

function gridlyBuildCurrentCommuteSnapshot() {
  const places = gridlyGetSavedPlacesReadiness();
  const routeGeometry = gridlyGetRouteGeometryDiagnostics();
  const routeConfigured = Boolean(places.routablePlaceCount >= 2 && (places.hasHome || places.hasWork));
  const routeMetrics = gridlyGetTravelTimeRouteMetrics(routeGeometry);
  const impactReadiness = gridlyGetTravelTimeImpactReadiness(routeGeometry);
  const routeImpactCount = impactReadiness.activeRouteImpactCount;
  const corridorImpactCount = impactReadiness.activeCorridorImpactCount;

  return {
    routeConfigured,
    routeMetricsAvailable: Boolean(routeMetrics.routeMetricsAvailable),

    distanceMiles: Number.isFinite(Number(routeMetrics.routeDistanceMiles)) ? Number(routeMetrics.routeDistanceMiles) : null,
    currentDurationMinutes: Number.isFinite(Number(routeMetrics.routeDurationMinutes)) ? Number(routeMetrics.routeDurationMinutes) : null,

    routePointCount: Number.isFinite(Number(routeMetrics.routePointCount)) ? Number(routeMetrics.routePointCount) : 0,
    routeGeneratedAt: routeMetrics.routeGeneratedAt || null,

    routeStatus: gridlyResolveCurrentCommuteRouteStatus(routeImpactCount, corridorImpactCount),

    routeImpactCount,
    corridorImpactCount
  };
}

window.gridlyCurrentCommuteSnapshot = function gridlyCurrentCommuteSnapshot() {
  return gridlyBuildCurrentCommuteSnapshot();
};

function gridlyBuildCommuteDeltaSnapshot() {
  const places = gridlyGetSavedPlacesReadiness();
  const normalBaseline = typeof window.gridlyNormalCommuteBaseline === "function"
    ? window.gridlyNormalCommuteBaseline()
    : gridlyBuildNormalCommuteBaseline();
  const currentCommuteSnapshot = typeof window.gridlyCurrentCommuteSnapshot === "function"
    ? window.gridlyCurrentCommuteSnapshot()
    : gridlyBuildCurrentCommuteSnapshot();
  const routeKey = normalBaseline.routeKey || gridlyBuildCommuteBaselineRouteKey(places) || "fallback_route";
  const currentDurationMinutes = Number.isFinite(Number(currentCommuteSnapshot?.currentDurationMinutes)) && Number(currentCommuteSnapshot.currentDurationMinutes) > 0
    ? Number(currentCommuteSnapshot.currentDurationMinutes)
    : null;
  const normalCommuteMinutes = Number.isFinite(Number(normalBaseline.normalCommuteMinutes)) && Number(normalBaseline.normalCommuteMinutes) > 0
    ? Number(normalBaseline.normalCommuteMinutes)
    : null;
  const baselineConfidence = normalBaseline.baselineConfidence || "none";
  const baselineStatus = normalBaseline.baselineStatus || "unavailable";
  const currentCommuteAvailable = Boolean(
    currentCommuteSnapshot?.routeConfigured
    && currentCommuteSnapshot?.routeMetricsAvailable
    && currentDurationMinutes !== null
  );
  const normalCommuteAvailable = Boolean(
    normalCommuteMinutes !== null
    && Number(normalBaseline.sampleCount || 0) > 0
  );
  const deltaAvailable = Boolean(currentCommuteAvailable && normalCommuteAvailable);
  const deltaMinutes = deltaAvailable ? currentDurationMinutes - normalCommuteMinutes : null;
  const deltaDirection = !deltaAvailable
    ? "unavailable"
    : (deltaMinutes >= 3 ? "slower" : (deltaMinutes <= -3 ? "faster" : "about_normal"));
  const deltaStatus = !deltaAvailable
    ? "unavailable"
    : (deltaDirection === "slower" ? "slower_than_normal" : (deltaDirection === "faster" ? "faster_than_normal" : "normal"));
  const deltaReasons = [
    !currentCommuteAvailable ? "current commute snapshot unavailable" : "",
    !normalCommuteAvailable ? "normal commute baseline unavailable" : "",
    baselineConfidence === "low" ? "low confidence baseline" : ""
  ].filter(Boolean);

  return {
    routeKey,
    currentDurationMinutes,
    normalCommuteMinutes,
    deltaMinutes,
    deltaDirection,
    deltaStatus,
    baselineConfidence,
    baselineStatus,
    deltaAvailable,
    deltaReason: deltaReasons.length ? deltaReasons.join("; ") : "available",
    destructiveActionsTaken: false
  };
}

window.gridlyCommuteDeltaSnapshot = function gridlyCommuteDeltaSnapshot() {
  return gridlyBuildCommuteDeltaSnapshot();
};

function gridlyFormatCommuteDisplayMinutes(value) {
  if (!Number.isFinite(Number(value))) return null;
  const rounded = Math.round(Number(value));
  return rounded > 0 ? rounded : null;
}

function gridlyBuildCommuteDisplayCopy() {
  const commuteDeltaSnapshot = typeof window.gridlyCommuteDeltaSnapshot === "function"
    ? window.gridlyCommuteDeltaSnapshot()
    : gridlyBuildCommuteDeltaSnapshot();
  const currentDurationMinutes = gridlyFormatCommuteDisplayMinutes(commuteDeltaSnapshot.currentDurationMinutes);
  const normalCommuteMinutes = gridlyFormatCommuteDisplayMinutes(commuteDeltaSnapshot.normalCommuteMinutes);
  const deltaMinutes = Number.isFinite(Number(commuteDeltaSnapshot.deltaMinutes))
    ? Math.round(Number(commuteDeltaSnapshot.deltaMinutes))
    : null;
  const deltaDirection = commuteDeltaSnapshot.deltaDirection || "unavailable";
  const baselineConfidence = commuteDeltaSnapshot.baselineConfidence || "none";
  const absoluteDeltaMinutes = Number.isFinite(Number(deltaMinutes)) ? Math.abs(deltaMinutes) : null;

  let headline = currentDurationMinutes !== null
    ? `Current route: ${currentDurationMinutes} min`
    : "Current route unavailable";
  let subline = "Commute comparison unavailable";
  let detailLine = "Normal commute history is needed before comparing this route";

  if (deltaDirection === "about_normal") {
    subline = "About normal for this route";
    detailLine = "No significant travel difference detected";
  } else if (deltaDirection === "slower") {
    subline = `About ${absoluteDeltaMinutes} min slower than normal`;
    detailLine = "Travel conditions may be affecting this route";
  } else if (deltaDirection === "faster") {
    subline = `About ${absoluteDeltaMinutes} min faster than normal`;
    detailLine = "Travel conditions are lighter than normal";
  }

  const confidenceLine = baselineConfidence === "high"
    ? "Based on established commute history"
    : (baselineConfidence === "medium" ? "Based on recent commute history" : "Still learning this route");

  return {
    headline,
    subline,
    detailLine,
    confidenceLine,
    currentDurationMinutes,
    normalCommuteMinutes,
    deltaMinutes,
    deltaDirection,
    baselineConfidence
  };
}

window.gridlyCommuteDisplayCopy = function gridlyCommuteDisplayCopy() {
  return gridlyBuildCommuteDisplayCopy();
};


let gridlyRouteWatchDisplayAuditState = {
  commuteDisplayCopyAvailable: false,
  displayTargetFound: false,
  displayApplied: false,
  displayText: "",
  fallbackUsed: true,
  displayReason: "not_rendered"
};

function gridlyGetRouteWatchCommuteDisplayCopy() {
  const commuteDisplayCopy = typeof window.gridlyCommuteDisplayCopy === "function"
    ? window.gridlyCommuteDisplayCopy()
    : null;
  const displayLines = commuteDisplayCopy
    ? [
        commuteDisplayCopy.headline,
        commuteDisplayCopy.subline,
        commuteDisplayCopy.detailLine,
        commuteDisplayCopy.confidenceLine
      ].map((line) => String(line || "").trim())
    : [];
  const completeDisplayCopy = displayLines.length === 4 && displayLines.every(Boolean);
  const commuteDeltaSnapshot = typeof window.gridlyCommuteDeltaSnapshot === "function"
    ? window.gridlyCommuteDeltaSnapshot()
    : null;
  const commuteDisplayCopyAvailable = Boolean(
    completeDisplayCopy
    && commuteDeltaSnapshot?.deltaAvailable
    && Number.isFinite(Number(commuteDisplayCopy?.currentDurationMinutes))
    && Number(commuteDisplayCopy.currentDurationMinutes) > 0
  );

  return {
    commuteDisplayCopy,
    commuteDisplayCopyAvailable,
    displayLines,
    displayText: commuteDisplayCopyAvailable ? displayLines.join("\n") : "",
    displayReason: commuteDisplayCopyAvailable
      ? "commute_display_copy_available"
      : (completeDisplayCopy ? "commute_delta_unavailable" : "commute_display_copy_unavailable")
  };
}

function gridlyBuildRouteWatchDisplayAudit(update = {}) {
  gridlyRouteWatchDisplayAuditState = {
    ...gridlyRouteWatchDisplayAuditState,
    ...update,
    fallbackUsed: !Boolean(update.displayApplied ?? gridlyRouteWatchDisplayAuditState.displayApplied)
  };
  return { ...gridlyRouteWatchDisplayAuditState };
}

function gridlyRenderRouteWatchDisplayCopy(container = null) {
  const target = container || document.querySelector(".desktop-route-watch-strip .route-watch-metrics");
  const display = gridlyGetRouteWatchCommuteDisplayCopy();
  const baseAudit = {
    commuteDisplayCopyAvailable: display.commuteDisplayCopyAvailable,
    displayTargetFound: Boolean(target),
    displayApplied: false,
    displayText: display.displayText,
    displayReason: display.displayReason
  };

  if (!target) {
    return gridlyBuildRouteWatchDisplayAudit({ ...baseAudit, fallbackUsed: true, displayReason: "display_target_not_found" });
  }
  if (!display.commuteDisplayCopyAvailable) {
    target.querySelector('[data-route-watch-display="commute-intelligence"]')?.remove();
    return gridlyBuildRouteWatchDisplayAudit({ ...baseAudit, fallbackUsed: true });
  }

  const [headline, subline, detailLine, confidenceLine] = display.displayLines;
  const markup = `
    <span data-route-watch-display="commute-intelligence" class="route-watch-commute-display">
      <b>${sanitizeText(headline)}</b>
      <em>${sanitizeText(subline)}</em>
      <em>${sanitizeText(detailLine)}</em>
      <em>${sanitizeText(confidenceLine)}</em>
    </span>
  `;
  const existing = target.querySelector('[data-route-watch-display="commute-intelligence"]');
  if (existing) {
    existing.outerHTML = markup;
  } else {
    target.insertAdjacentHTML("beforeend", markup);
  }

  return gridlyBuildRouteWatchDisplayAudit({
    ...baseAudit,
    displayApplied: true,
    fallbackUsed: false,
    displayReason: "route_watch_display_applied"
  });
}

window.gridlyRouteWatchDisplayAudit = function gridlyRouteWatchDisplayAudit() {
  const target = typeof document !== "undefined"
    ? document.querySelector(".desktop-route-watch-strip .route-watch-metrics")
    : null;
  const renderedDisplay = target?.querySelector('[data-route-watch-display="commute-intelligence"]') || null;
  const display = gridlyGetRouteWatchCommuteDisplayCopy();
  return gridlyBuildRouteWatchDisplayAudit({
    commuteDisplayCopyAvailable: display.commuteDisplayCopyAvailable,
    displayTargetFound: Boolean(target),
    displayApplied: Boolean(renderedDisplay && display.commuteDisplayCopyAvailable),
    displayText: renderedDisplay ? String(renderedDisplay.textContent || "").replace(/\s+/g, " ").trim() : display.displayText,
    fallbackUsed: !Boolean(renderedDisplay && display.commuteDisplayCopyAvailable),
    displayReason: renderedDisplay && display.commuteDisplayCopyAvailable
      ? "route_watch_display_applied"
      : (target ? display.displayReason : "display_target_not_found")
  });
};

function gridlyRouteWatchDisplayBlockerAudit(options = {}) {
  const skipBetaReadiness = Boolean(options?.skipBetaReadiness);
  const target = typeof window !== "undefined" ? window : globalThis;
  const hasDocument = typeof document !== "undefined";
  const findings = [];
  const emptyResult = (extra = {}) => ({
    available: true,
    version: "V264.1",
    betaBlockerPresent: false,
    blockerType: "unknown",
    userVisibleIssueDetected: false,
    auditFalsePositiveDetected: false,
    displaySurfaceFound: false,
    displaySurfaceVisible: false,
    displaySurfaceFunctional: false,
    routeWatchAccessible: false,
    routeWatchMonitoringVisible: false,
    routeWatchReadinessVisible: false,
    routeWatchOwnershipValid: false,
    routeWatchDisplayApplied: false,
    recommendedAction: "Display Patch Needed",
    consumerFriendlyPass: false,
    findings,
    ...extra
  });

  if (!hasDocument) {
    findings.push("Document is unavailable, so the Route Watch display blocker cannot be classified from the runtime DOM.");
    return emptyResult({ betaBlockerPresent: true });
  }

  const runAuditSafely = (fn, ...args) => {
    if (typeof fn !== "function") return null;
    try {
      return fn(...args);
    } catch (error) {
      findings.push(`Supporting audit ${fn.name || "anonymous"} failed during V264.1 review: ${String(error?.message || error || "unknown error")}`);
      return null;
    }
  };
  const text = (node) => String(node?.textContent || "").replace(/\s+/g, " ").trim();
  const visible = (node) => {
    if (!node) return false;
    try {
      if (node.hidden || node.hasAttribute?.("hidden") || node.hasAttribute?.("inert")) return false;
      const style = typeof getComputedStyle === "function" ? getComputedStyle(node) : null;
      if (style && (style.display === "none" || style.visibility === "hidden" || style.opacity === "0")) return false;
      const rect = typeof node.getBoundingClientRect === "function" ? node.getBoundingClientRect() : null;
      if (rect && rect.width === 0 && rect.height === 0 && node.offsetParent === null) return false;
      return true;
    } catch (_error) {
      return true;
    }
  };
  const id = (name) => document.getElementById(name);
  const routeWatchSurface = document.querySelector(".desktop-route-watch-strip");
  const metricsSurface = routeWatchSurface?.querySelector?.(".route-watch-metrics") || document.querySelector(".desktop-route-watch-strip .route-watch-metrics");
  const statusLine = routeWatchSurface?.querySelector?.(".route-watch-status-line") || null;
  const ownershipSummary = routeWatchSurface?.querySelector?.(".route-ownership-summary") || null;
  const routeWatchDisplayAudit = runAuditSafely(target?.gridlyRouteWatchDisplayAudit);
  const betaAudit = skipBetaReadiness ? null : runAuditSafely(target?.gridlyBetaReadinessReviewAudit);
  const routeOwnershipAudit = runAuditSafely(target?.gridlyRouteOwnershipAudit);
  const routeOriginAudit = runAuditSafely(target?.gridlyRouteOriginAudit);

  const betaBlockers = Array.isArray(betaAudit?.betaBlockers) ? betaAudit.betaBlockers : [];
  const betaRouteDisplayBlockerReported = betaBlockers.some((blocker) => /Route Watch display audit reports display was not applied/i.test(String(blocker || "")));
  const displaySurfaceFound = Boolean(routeWatchSurface && metricsSurface);
  const displaySurfaceVisible = Boolean(visible(routeWatchSurface) && visible(metricsSurface));
  const metricsText = text(metricsSurface);
  const statusText = text(id("desktopRouteStatus"));
  const hintText = text(id("routeWatchSetupHint"));
  const livePillText = text(id("routeWatchLivePill"));
  const routeWatchAccessible = Boolean(
    id("routeWatchStartBtn")
    && id("routeWatchStartSelect")
    && id("routeWatchDestinationSelect")
    && id("showFullRouteBtn")
    && id("stopRouteWatchBtn")
  );
  const routeWatchMonitoringVisible = Boolean(
    id("routeWatchLivePill")
    && id("routeOwnershipMonitoring")
    && /monitoring|route watch status|reports near route|reports|guidance/i.test(metricsText)
  );
  const routeWatchReadinessVisible = Boolean(
    id("routeWatchSetupHint")
    && /start route watch|choose|select|set home|destination|monitoring off|monitoring on|preview/i.test(`${hintText} ${statusText} ${livePillText}`)
  );
  const displaySurfaceFunctional = Boolean(
    displaySurfaceFound
    && routeWatchAccessible
    && routeWatchMonitoringVisible
    && routeWatchReadinessVisible
    && statusLine
    && ownershipSummary
    && /freshness|reports|route watch status|travel guidance|recommendation|monitoring/i.test(metricsText)
  );
  const routeWatchOwnershipValid = Boolean(
    ownershipSummary
    && id("routeOwnershipOrigin")
    && id("routeOwnershipDestination")
    && id("routeOwnershipMonitoring")
    && (!routeOwnershipAudit || (routeOwnershipAudit?.routeExitOwnershipPass !== false && routeOwnershipAudit?.consumerFriendlyPass !== false && routeOwnershipAudit?.protectedSystemsPass !== false))
    && (!routeOriginAudit || (routeOriginAudit?.originOwnershipMatch !== false && routeOriginAudit?.consumerFriendlyPass !== false && routeOriginAudit?.protectedSystemsPass !== false))
  );
  const oldDisplayApplied = Boolean(routeWatchDisplayAudit?.displayApplied);
  const oldDisplayExplicitlyNotApplied = routeWatchDisplayAudit?.displayApplied === false;
  const routeWatchDisplayApplied = Boolean(displaySurfaceFunctional);
  const auditFalsePositiveDetected = Boolean(oldDisplayExplicitlyNotApplied && displaySurfaceFunctional && routeWatchAccessible);
  const displayNotDetected = Boolean(oldDisplayExplicitlyNotApplied && displaySurfaceFound && displaySurfaceFunctional && !oldDisplayApplied);
  const userVisibleIssueDetected = Boolean(!routeWatchAccessible || !displaySurfaceFound || !displaySurfaceVisible || !displaySurfaceFunctional || !routeWatchOwnershipValid);
  const consumerFriendlyPass = Boolean(
    routeWatchAccessible
    && displaySurfaceFound
    && displaySurfaceVisible
    && displaySurfaceFunctional
    && routeWatchMonitoringVisible
    && routeWatchReadinessVisible
    && routeWatchOwnershipValid
    && !userVisibleIssueDetected
  );

  let blockerType = "unknown";
  let recommendedAction = "Display Patch Needed";
  if (userVisibleIssueDetected) {
    blockerType = "real_display_issue";
    recommendedAction = "Display Patch Needed";
  } else if (auditFalsePositiveDetected) {
    blockerType = betaRouteDisplayBlockerReported ? "audit_false_positive" : "display_not_detected";
    recommendedAction = "Audit Update Needed";
  } else if (displayNotDetected) {
    blockerType = "display_not_detected";
    recommendedAction = "Audit Update Needed";
  } else if (consumerFriendlyPass) {
    blockerType = "audit_false_positive";
    recommendedAction = "Audit Update Needed";
  }

  if (displaySurfaceFound) findings.push("Route Watch display surface is present: the desktop strip and route-watch metrics container exist.");
  else findings.push("Route Watch display surface is missing from the runtime DOM.");
  if (displaySurfaceVisible) findings.push("Route Watch display surface is visible in the current runtime DOM snapshot.");
  else findings.push("Route Watch display surface is not visible in the current runtime DOM snapshot.");
  if (routeWatchAccessible) findings.push("Route Watch controls remain accessible: start, saved-place selectors, show full route, and stop controls are present.");
  else findings.push("One or more Route Watch controls are missing.");
  if (routeWatchReadinessVisible) findings.push("Route Watch readiness is visible through setup/status copy before monitoring starts.");
  else findings.push("Route Watch readiness copy was not detected.");
  if (routeWatchMonitoringVisible) findings.push("Route Watch monitoring state is visible through the live pill, ownership status, and metrics copy.");
  else findings.push("Route Watch monitoring state was not detected in visible copy.");
  if (auditFalsePositiveDetected) findings.push(`Existing display audit returned displayApplied: false because ${routeWatchDisplayAudit?.displayReason || "no commute-intelligence add-on was rendered"}, but the consumer Route Watch display is present and functional.`);
  if (betaRouteDisplayBlockerReported) findings.push("Beta Readiness is still using the narrow Route Watch displayApplied flag as a blocker condition.");
  if (consumerFriendlyPass) findings.push("A normal beta tester can access Route Watch, see readiness, and monitor route state without running audits.");
  if (!consumerFriendlyPass) findings.push("A normal beta tester could encounter a user-visible Route Watch display issue in this runtime snapshot.");

  return {
    available: true,
    version: "V264.1",
    betaBlockerPresent: Boolean(userVisibleIssueDetected),
    blockerType,
    userVisibleIssueDetected,
    auditFalsePositiveDetected,
    displaySurfaceFound,
    displaySurfaceVisible,
    displaySurfaceFunctional,
    routeWatchAccessible,
    routeWatchMonitoringVisible,
    routeWatchReadinessVisible,
    routeWatchOwnershipValid,
    routeWatchDisplayApplied,
    recommendedAction,
    consumerFriendlyPass,
    findings
  };
}

window.gridlyRouteWatchDisplayBlockerAudit = gridlyRouteWatchDisplayBlockerAudit;
if (typeof exposeGridlyAuditHelper === "function") {
  exposeGridlyAuditHelper("gridlyRouteWatchDisplayBlockerAudit", gridlyRouteWatchDisplayBlockerAudit);
}

function gridlyBetaRouteBlockerClassificationAudit(options = {}) {
  const skipBetaReadiness = Boolean(options?.skipBetaReadiness);
  const target = typeof window !== "undefined" ? window : globalThis;
  const hasDocument = typeof document !== "undefined";
  const findings = [];
  const routeStateClassifications = [];
  const runAuditSafely = (name, ...args) => {
    const fn = target?.[name];
    if (typeof fn !== "function") {
      return { available: false, failing: false, result: null, error: "helper_unavailable" };
    }
    try {
      const result = fn(...args);
      return {
        available: Boolean(result && result.available !== false),
        failing: Boolean(result?.available === false),
        result,
        error: ""
      };
    } catch (error) {
      findings.push(`Supporting audit ${name} threw during V264.2 classification: ${String(error?.message || error || "unknown error")}`);
      return { available: true, failing: true, result: null, error: String(error?.message || error || "unknown error") };
    }
  };
  const visible = (node) => {
    if (!node || !hasDocument) return false;
    try {
      if (node.hidden || node.hasAttribute?.("hidden") || node.hasAttribute?.("inert")) return false;
      const style = typeof getComputedStyle === "function" ? getComputedStyle(node) : null;
      if (style && (style.display === "none" || style.visibility === "hidden" || style.opacity === "0")) return false;
      const rect = typeof node.getBoundingClientRect === "function" ? node.getBoundingClientRect() : null;
      if (rect && rect.width === 0 && rect.height === 0 && node.offsetParent === null) return false;
      return true;
    } catch (_error) {
      return true;
    }
  };
  const id = (name) => hasDocument ? document.getElementById(name) : null;
  const selectorPresent = (selector) => hasDocument && Boolean(document.querySelector(selector));
  const text = (node) => String(node?.textContent || "").replace(/\s+/g, " ").trim();
  const betaAudit = skipBetaReadiness ? { available: false, failing: false, result: null, error: "skipped_for_nested_classification" } : runAuditSafely("gridlyBetaReadinessReviewAudit");
  const routeOriginAudit = runAuditSafely("gridlyRouteOriginAudit");
  const routeWatchDisplayAudit = runAuditSafely("gridlyRouteWatchDisplayAudit");
  const routeWatchDisplayBlockerAudit = runAuditSafely("gridlyRouteWatchDisplayBlockerAudit", { skipBetaReadiness: true });
  const routeOwnershipAudit = runAuditSafely("gridlyRouteOwnershipAudit");
  const destinationSearchAudit = runAuditSafely("gridlyDestinationSearchShellAudit");
  const destinationOriginAudit = runAuditSafely("gridlyDestinationCurrentLocationOriginAudit");
  const currentLocationAudit = runAuditSafely("gridlyAppLocationReadinessAudit");

  const currentBetaBlockers = Array.isArray(betaAudit.result?.betaBlockers) ? [...betaAudit.result.betaBlockers] : [];
  const routeRelatedCurrentBetaBlockers = currentBetaBlockers.filter((blocker) => /route|destination|saved place|current location/i.test(String(blocker || "")));
  const routeGeometryAudit = typeof getGridlyActiveRouteCoordinatesForAudit === "function"
    ? getGridlyActiveRouteCoordinatesForAudit()
    : (typeof gridlyGetRouteGeometryDiagnostics === "function" ? gridlyGetRouteGeometryDiagnostics() : null);
  const activeRoutePresent = Boolean(routeGeometryAudit?.activeRoutePresent || routeGeometryAudit?.routeGeometryAvailable || routeGeometryAudit?.currentRouteAvailable);
  const routeWatchActive = Boolean(target?.__gridlyRouteWatchActive || (typeof routeWatchActivated !== "undefined" && routeWatchActivated));
  const routeWatchSurface = hasDocument ? document.querySelector(".desktop-route-watch-strip") : null;
  const metricsSurface = routeWatchSurface?.querySelector?.(".route-watch-metrics") || (hasDocument ? document.querySelector(".desktop-route-watch-strip .route-watch-metrics") : null);
  const routeWatchDisplayAvailable = Boolean(routeWatchSurface && metricsSurface);
  const routeWatchDisplayVisible = Boolean(visible(routeWatchSurface) && visible(metricsSurface));
  const routeWatchAccessible = Boolean(
    id("routeWatchStartBtn")
    && id("routeWatchStartSelect")
    && id("routeWatchDestinationSelect")
    && id("showFullRouteBtn")
    && id("stopRouteWatchBtn")
  );
  const metricsText = text(metricsSurface);
  const routeWatchReadinessVisible = Boolean(
    id("routeWatchSetupHint")
    && /start route watch|choose|select|set home|destination|monitoring off|monitoring on|preview/i.test(`${text(id("routeWatchSetupHint"))} ${text(id("desktopRouteStatus"))} ${text(id("routeWatchLivePill"))}`)
  );
  const routeWatchMonitoringVisible = Boolean(
    id("routeWatchLivePill")
    && id("routeOwnershipMonitoring")
    && /monitoring|route watch status|reports near route|reports|guidance/i.test(metricsText)
  );
  const routeWatchDisplayFunctional = Boolean(
    routeWatchDisplayAvailable
    && routeWatchAccessible
    && routeWatchReadinessVisible
    && routeWatchMonitoringVisible
    && (routeWatchDisplayVisible || routeWatchDisplayBlockerAudit.result?.displaySurfaceFunctional === true)
    && /freshness|reports|route watch status|travel guidance|recommendation|monitoring/i.test(metricsText)
  );
  const routeOriginAuditAvailable = Boolean(routeOriginAudit.available);
  const routeOriginAuditFailing = Boolean(
    routeOriginAudit.available
    && (
      routeOriginAudit.failing
      || routeOriginAudit.result?.originOwnershipMatch === false
      || routeOriginAudit.result?.consumerFriendlyPass === false
      || routeOriginAudit.result?.protectedSystemsPass === false
    )
  );
  const routeOriginAuditUnavailable = !routeOriginAuditAvailable;
  const destinationSearchAvailable = Boolean(
    id("gridlySearchShell")
    && id("gridlyAddressSearchInput")
    && (typeof target?.gridlyDestinationSearchShellAudit === "function" || typeof openGridlyDestinationSearchSurface === "function" || typeof showGridlySearchShell === "function")
    && (!destinationSearchAudit.result || (destinationSearchAudit.result?.shellExists !== false && destinationSearchAudit.result?.inputExists !== false))
  );
  const routeDetailsAvailable = Boolean(id("showFullRouteBtn") || selectorPresent("[data-route-details], #routeDetailsPanel, #fullRouteSheet"));
  const managePlacesAvailable = Boolean(id("settingsManageSavedPlacesBtn") && id("settingsSavedPlacesList"));
  const savedPlacesRouteSelectorsAvailable = Boolean(id("routeWatchStartSelect") && id("routeWatchDestinationSelect"));
  const currentLocationRouteAvailable = Boolean(
    selectorPresent("[data-v2-control='use-location'], #mobileUseLocationBtn, #manageSourceLocationBtn")
    && (!currentLocationAudit.result || currentLocationAudit.result?.manualLocationButtonStillAvailable !== false)
    && (!currentLocationAudit.result || currentLocationAudit.result?.fallbackStillAvailable !== false)
    && (!destinationOriginAudit.result || destinationOriginAudit.result?.consumerFriendlyPass !== false)
  );
  const routeOwnershipFailing = Boolean(
    routeOwnershipAudit.available
    && (
      routeOwnershipAudit.failing
      || routeOwnershipAudit.result?.routeExitOwnershipPass === false
      || routeOwnershipAudit.result?.consumerFriendlyPass === false
      || routeOwnershipAudit.result?.protectedSystemsPass === false
    )
  );

  if (!activeRoutePresent) routeStateClassifications.push("no_active_route");
  if (!routeWatchActive) routeStateClassifications.push("idle_state");
  if (routeWatchDisplayAvailable && !routeWatchDisplayVisible) routeStateClassifications.push("closed_state");
  if (routeOriginAuditUnavailable) routeStateClassifications.push("audit_unavailable");
  if (routeOriginAuditFailing || routeOwnershipFailing) routeStateClassifications.push("audit_failure");

  const displayBlockerType = String(routeWatchDisplayBlockerAudit.result?.blockerType || "");
  const displayAuditReportsIssue = Boolean(
    routeWatchDisplayBlockerAudit.result?.userVisibleIssueDetected
    || routeWatchDisplayBlockerAudit.result?.betaBlockerPresent
    || /real_display_issue/i.test(displayBlockerType)
  );
  const displayOnlyAuditConflict = Boolean(
    displayAuditReportsIssue
    && routeWatchDisplayBlockerAudit.result?.auditFalsePositiveDetected
    && routeWatchDisplayBlockerAudit.result?.routeWatchAccessible
    && routeWatchDisplayBlockerAudit.result?.routeWatchReadinessVisible
    && routeWatchDisplayBlockerAudit.result?.routeWatchMonitoringVisible
    && (routeWatchDisplayBlockerAudit.result?.routeWatchDisplayApplied || routeWatchDisplayFunctional)
  );
  const routeDisplayAppliedFalseDueToCommuteDeltaUnavailable = Boolean(
    routeWatchDisplayAudit.result?.displayApplied === false
    && /commute_delta_unavailable/i.test(String(routeWatchDisplayAudit.result?.displayReason || routeWatchDisplayAudit.result?.reason || routeWatchDisplayAudit.result?.fallbackReason || ""))
  );
  const routeWatchFalsePositiveDetected = Boolean(
    displayOnlyAuditConflict
    || (routeWatchDisplayAudit.result?.displayApplied === false && routeWatchDisplayFunctional && routeWatchAccessible)
    || (routeDisplayAppliedFalseDueToCommuteDeltaUnavailable && routeWatchAccessible)
  );
  const routeWatchDisplayNonBlocking = Boolean(
    !routeWatchDisplayAvailable
    || !routeWatchDisplayVisible
    || routeWatchDisplayFunctional
    || routeDisplayAppliedFalseDueToCommuteDeltaUnavailable
  );
  const routeOriginFailureBlocksBeta = Boolean(activeRoutePresent && routeOriginAuditFailing);
  const actualUserVisibleRouteIssueDetected = Boolean(
    !destinationSearchAvailable
    || !routeDetailsAvailable
    || !routeWatchAccessible
    || !managePlacesAvailable
    || !savedPlacesRouteSelectorsAvailable
    || !currentLocationRouteAvailable
    || (routeWatchDisplayAvailable && routeWatchDisplayVisible && !routeWatchDisplayFunctional && !routeDisplayAppliedFalseDueToCommuteDeltaUnavailable)
    || routeOriginFailureBlocksBeta
    || routeOwnershipFailing
  );
  if (actualUserVisibleRouteIssueDetected) routeStateClassifications.push("user_visible_failure");

  const idleStateMisclassified = Boolean(!routeWatchActive && routeRelatedCurrentBetaBlockers.length && !actualUserVisibleRouteIssueDetected);
  const closedStateMisclassified = Boolean(routeWatchDisplayAvailable && !routeWatchDisplayVisible && routeRelatedCurrentBetaBlockers.length && !actualUserVisibleRouteIssueDetected);
  const noRouteStateMisclassified = Boolean(!activeRoutePresent && routeRelatedCurrentBetaBlockers.length && !actualUserVisibleRouteIssueDetected);
  const unavailableAuditMisclassified = Boolean(routeOriginAuditUnavailable && routeRelatedCurrentBetaBlockers.some((blocker) => /Route origin audit is unavailable or failing/i.test(String(blocker || ""))) && !routeOriginAuditFailing);

  const recommendedBetaBlockers = [];
  if (!destinationSearchAvailable) recommendedBetaBlockers.push("Destination Search helper or shell/input is missing.");
  if (!routeDetailsAvailable) recommendedBetaBlockers.push("Route Details access is missing.");
  if (!routeWatchAccessible) recommendedBetaBlockers.push("Route Watch controls are missing.");
  if (routeWatchDisplayAvailable && routeWatchDisplayVisible && !routeWatchDisplayFunctional && !routeDisplayAppliedFalseDueToCommuteDeltaUnavailable) recommendedBetaBlockers.push("Route Watch display has a user-visible functional issue.");
  if (!managePlacesAvailable) recommendedBetaBlockers.push("Manage Places access is missing.");
  if (!savedPlacesRouteSelectorsAvailable) recommendedBetaBlockers.push("Saved Places route selectors are missing.");
  if (!currentLocationRouteAvailable) recommendedBetaBlockers.push("Current Location route origin controls are missing or failing.");
  if (routeOriginFailureBlocksBeta) recommendedBetaBlockers.push("Route origin audit is failing.");
  if (routeOwnershipFailing) recommendedBetaBlockers.push("Route ownership audit is failing.");
  const uniqueRecommendedBetaBlockers = Array.from(new Set(recommendedBetaBlockers));
  const blockerClassificationAccurate = Boolean(
    !routeWatchFalsePositiveDetected
    && !idleStateMisclassified
    && !closedStateMisclassified
    && !noRouteStateMisclassified
    && !unavailableAuditMisclassified
  );
  const consumerFriendlyPass = Boolean(
    destinationSearchAvailable
    && routeDetailsAvailable
    && routeWatchAccessible
    && routeWatchDisplayNonBlocking
    && managePlacesAvailable
    && savedPlacesRouteSelectorsAvailable
    && currentLocationRouteAvailable
    && !actualUserVisibleRouteIssueDetected
  );

  findings.push(activeRoutePresent ? "Active route coordinates or a current route state are present." : "No active route is present; this is classified as no_active_route and should not fail Route Readiness by itself.");
  findings.push(routeWatchActive ? "Route Watch is active; monitoring state should be evaluated as active monitoring." : "Route Watch is idle/off; idle_state is separate from a failed Route Watch display.");
  findings.push(routeWatchDisplayAvailable ? "Route Watch display surface exists in the DOM." : "Route Watch display surface is unavailable in the DOM.");
  findings.push(routeWatchDisplayVisible ? "Route Watch display surface is visible in the current DOM snapshot." : "Route Watch display surface is closed or hidden in the current DOM snapshot; closed_state is not automatically a beta blocker.");
  findings.push(routeWatchDisplayFunctional ? "Route Watch display is functionally available: controls, readiness copy, monitoring copy, and metrics are present." : "Route Watch display functionality was not fully proven from this snapshot.");
  findings.push(routeOriginAuditAvailable ? "Route origin audit helper is available." : "Route origin audit helper is unavailable; audit_unavailable is separate from audit_failure.");
  if (routeDisplayAppliedFalseDueToCommuteDeltaUnavailable) findings.push("Route Watch display audit returned displayApplied false because commute_delta_unavailable; V264.3 classifies that as non-blocking without a user-visible route failure.");
  if (!actualUserVisibleRouteIssueDetected) findings.push("No actual user-visible route issue was detected; idle/no-route/closed states are diagnostic classifications only.");
  if (routeOriginFailureBlocksBeta) findings.push("Route origin audit is available but failing its ownership/consumer/protected-system checks while an active route exists.");
  else if (!activeRoutePresent && routeOriginAuditFailing) findings.push("Route origin audit is failing in a no-active-route state; V264.5 classifies this as route_origin_not_required rather than a beta blocker.");
  if (routeWatchFalsePositiveDetected) findings.push("Route Watch display blocker classification conflict detected: the display is accessible/functional while a supporting audit classifies it as a real display issue.");
  if (unavailableAuditMisclassified) findings.push("Current Beta Readiness combines route origin audit_unavailable with audit_failure in one blocker string; V264.2 recommends separating them.");
  findings.push(consumerFriendlyPass ? "Consumer pass: a normal beta tester should be able to create a route, access Route Details, access Route Watch, and manage places without a route-related failure." : "Consumer pass is not proven because one or more route creation/details/watch/manage-place checks failed.");

  let recommendedAction = "No route blocker patch recommended; keep route-related beta blockers at zero for idle/no-route/closed/audit-unavailable states.";
  if (uniqueRecommendedBetaBlockers.length) {
    recommendedAction = "Patch only the listed user-visible route failures or failing route audits; do not patch Route Watch UI for idle, closed, no-route, or unavailable-audit states.";
  } else if (routeWatchFalsePositiveDetected || unavailableAuditMisclassified) {
    recommendedAction = "Audit classification update recommended: split idle_state, closed_state, no_active_route, audit_unavailable, audit_failure, and user_visible_failure before changing Beta Readiness blockers.";
  }

  return {
    available: true,
    version: "V264.5",
    activeRoutePresent,
    routeOriginAuditAvailable,
    routeOriginAuditFailing,
    routeOriginFailureBlocksBeta,
    routeOriginNotRequiredInCurrentState: Boolean(!activeRoutePresent),
    routeWatchDisplayAvailable,
    routeWatchDisplayVisible,
    routeWatchDisplayFunctional,
    blockerClassificationAccurate,
    routeWatchFalsePositiveDetected,
    idleStateMisclassified,
    closedStateMisclassified,
    noRouteStateMisclassified,
    actualUserVisibleRouteIssueDetected,
    nonUserFacingRouteStatesIgnored: Boolean(!actualUserVisibleRouteIssueDetected && routeStateClassifications.some((classification) => /no_active_route|idle_state|closed_state|audit_unavailable/.test(classification))),
    routeDisplayAppliedFalseDueToCommuteDeltaUnavailable,
    recommendedBetaBlockerCount: uniqueRecommendedBetaBlockers.length,
    currentBetaBlockers,
    recommendedBetaBlockers: uniqueRecommendedBetaBlockers,
    recommendedAction,
    consumerFriendlyPass,
    findings,
    classifications: Array.from(new Set(routeStateClassifications)),
    diagnostics: {
      routeWatchActive,
      routeWatchAccessible,
      routeWatchReadinessVisible,
      routeWatchMonitoringVisible,
      routeWatchDisplayNonBlocking,
      routeOriginAuditUnavailable,
      unavailableAuditMisclassified,
      destinationSearchAvailable,
      routeDetailsAvailable,
      managePlacesAvailable,
      savedPlacesRouteSelectorsAvailable,
      currentLocationRouteAvailable,
      routeOwnershipAuditAvailable: Boolean(routeOwnershipAudit.available),
      routeOwnershipAuditFailing: routeOwnershipFailing,
      routeWatchDisplayAuditDisplayApplied: Boolean(routeWatchDisplayAudit.result?.displayApplied),
      routeWatchDisplayAuditDisplayReason: String(routeWatchDisplayAudit.result?.displayReason || routeWatchDisplayAudit.result?.reason || "unknown"),
      routeDisplayAppliedFalseDueToCommuteDeltaUnavailable,
      routeWatchDisplayBlockerType: displayBlockerType || "unknown",
      routeWatchDisplayBlockerUserVisibleIssue: Boolean(routeWatchDisplayBlockerAudit.result?.userVisibleIssueDetected)
    }
  };
}

window.gridlyBetaRouteBlockerClassificationAudit = gridlyBetaRouteBlockerClassificationAudit;
if (typeof exposeGridlyAuditHelper === "function") {
  exposeGridlyAuditHelper("gridlyBetaRouteBlockerClassificationAudit", gridlyBetaRouteBlockerClassificationAudit);
}

function gridlyRouteOriginFailureTriageAudit() {
  const target = typeof window !== "undefined" ? window : globalThis;
  const hasDocument = typeof document !== "undefined";
  const findings = [];
  const runAuditSafely = (name, ...args) => {
    const fn = target?.[name];
    if (typeof fn !== "function") {
      return { available: false, result: null, error: "helper_unavailable" };
    }
    try {
      const result = fn(...args);
      return { available: Boolean(result && result.available !== false), result, error: "" };
    } catch (error) {
      const message = String(error?.message || error || "unknown error");
      findings.push(`Supporting audit ${name} threw during V264.4 route-origin triage: ${message}`);
      return { available: true, result: null, error: message };
    }
  };
  const text = (id) => hasDocument ? String(document.getElementById(id)?.textContent || "").replace(/\s+/g, " ").trim() : "";
  const present = (id) => hasDocument && Boolean(document.getElementById(id));
  const routeGeometryAudit = typeof getGridlyActiveRouteCoordinatesForAudit === "function"
    ? getGridlyActiveRouteCoordinatesForAudit()
    : (typeof gridlyGetRouteGeometryDiagnostics === "function" ? gridlyGetRouteGeometryDiagnostics() : null);
  const preview = typeof getGridlyDestinationRoutePreviewState === "function"
    ? getGridlyDestinationRoutePreviewState()
    : (target?.GridlyDestinationRoutePreview || null);
  const ownership = typeof updateGridlyRouteOwnershipSurface === "function"
    ? updateGridlyRouteOwnershipSurface()
    : null;
  const activeRoutePresent = Boolean(
    routeGeometryAudit?.activeRoutePresent
    || routeGeometryAudit?.routeGeometryAvailable
    || routeGeometryAudit?.currentRouteAvailable
    || preview?.activeRoutePresent
    || preview?.routeGeometryAvailable
    || preview?.layerExists
    || ownership?.hasRoute
  );

  const routeOriginAudit = runAuditSafely("gridlyRouteOriginAudit");
  const betaAudit = runAuditSafely("gridlyBetaReadinessReviewAudit");
  const destinationSearchAudit = runAuditSafely("gridlyDestinationSearchShellAudit");
  const currentLocationAudit = runAuditSafely("gridlyAppLocationReadinessAudit");
  const destinationOriginAudit = runAuditSafely("gridlyDestinationCurrentLocationOriginAudit");
  const routeOriginAuditAvailable = Boolean(routeOriginAudit.available);
  const routeOriginAuditPass = Boolean(
    routeOriginAuditAvailable
    && routeOriginAudit.result
    && routeOriginAudit.result?.originOwnershipMatch !== false
    && routeOriginAudit.result?.consumerFriendlyPass !== false
    && routeOriginAudit.result?.protectedSystemsPass !== false
  );
  const betaBlockers = Array.isArray(betaAudit.result?.betaBlockers) ? betaAudit.result.betaBlockers : [];
  const routeOriginBetaBlockerReported = betaBlockers.some((blocker) => /route origin/i.test(String(blocker || "")));
  const routeOriginRequiredInCurrentState = Boolean(activeRoutePresent);
  const routeOriginMissingBecauseNoRoute = Boolean(!activeRoutePresent && !routeOriginAuditPass);
  const routeOriginMissingBecauseFailure = Boolean(activeRoutePresent && !routeOriginAuditPass);
  const routeOriginMissingBecauseAuditExpectation = Boolean(!activeRoutePresent && (routeOriginBetaBlockerReported || routeOriginMissingBecauseNoRoute));
  const routeOriginReason = activeRoutePresent
    ? (routeOriginAuditPass ? "route_origin_available_for_active_route" : "active_route_origin_audit_failed")
    : (routeOriginAuditAvailable ? "no_active_route_origin_not_required" : "no_active_route_origin_audit_unavailable");

  const destinationSearchReady = Boolean(
    present("gridlySearchShell")
    && present("gridlyAddressSearchInput")
    && (!destinationSearchAudit.result || (destinationSearchAudit.result?.shellExists !== false && destinationSearchAudit.result?.inputExists !== false))
  );
  const currentLocationOriginReady = Boolean(
    (!currentLocationAudit.result || currentLocationAudit.result?.manualLocationButtonStillAvailable !== false)
    && (!currentLocationAudit.result || currentLocationAudit.result?.fallbackStillAvailable !== false)
    && (!destinationOriginAudit.result || destinationOriginAudit.result?.consumerFriendlyPass !== false)
  );
  const routeDetailsReady = Boolean(present("showFullRouteBtn") || present("gridlyDestinationImpactPane"));
  const walmartRouteRecoveryLikely = Boolean(
    destinationSearchReady
    && currentLocationOriginReady
    && routeDetailsReady
    && (routeOriginAuditPass || !activeRoutePresent)
  );
  const actualUserVisibleIssueDetected = Boolean(routeOriginMissingBecauseFailure);
  const betaBlockerJustified = Boolean(actualUserVisibleIssueDetected);

  let blockerClassification = "unknown";
  if (!activeRoutePresent) {
    blockerClassification = routeOriginBetaBlockerReported || routeOriginMissingBecauseAuditExpectation
      ? "audit_expectation_mismatch"
      : "no_active_route";
  } else if (actualUserVisibleIssueDetected) {
    blockerClassification = "route_origin_failure";
  }

  let recommendedAction = "Further Runtime Validation Needed";
  if (blockerClassification === "audit_expectation_mismatch") recommendedAction = "Audit Classification Update Needed";
  else if (blockerClassification === "no_active_route") recommendedAction = "No Patch Needed";
  else if (blockerClassification === "route_origin_failure" || blockerClassification === "user_visible_failure") recommendedAction = "Route Origin Patch Needed";
  else if (activeRoutePresent && routeOriginAuditPass) recommendedAction = "No Patch Needed";

  const consumerFriendlyPass = Boolean(activeRoutePresent && routeOriginAuditPass && walmartRouteRecoveryLikely && !actualUserVisibleIssueDetected);

  findings.push(activeRoutePresent ? "Active route state is present; Route Origin is required and should match the visible route ownership surface." : "No active route is present; Route Origin is not required until a route exists.");
  findings.push(routeOriginAuditAvailable ? "Route Origin audit helper is available for active-route validation." : "Route Origin audit helper is unavailable in this runtime snapshot.");
  findings.push(routeOriginAuditPass ? "Route Origin audit passes in the current runtime state." : "Route Origin audit does not pass in the current runtime state.");
  if (routeOriginMissingBecauseNoRoute) findings.push("Route Origin is missing/failing because the current runtime has no active route, not because a visible route origin failed.");
  if (routeOriginMissingBecauseFailure) findings.push("Route Origin is missing/failing while an active route exists; this should be treated as a genuine route-origin failure.");
  if (routeOriginMissingBecauseAuditExpectation) findings.push("The blocker is caused by expecting Route Origin in a no-active-route state; this is an audit expectation mismatch.");
  findings.push(walmartRouteRecoveryLikely ? "Destination Search, Current Location origin support, and Route Details controls appear available for a tester to validate Current Location → Walmart recovery." : "Current Location → Walmart recovery is not fully proven from this snapshot; runtime validation is needed.");
  findings.push(actualUserVisibleIssueDetected ? "A normal beta tester could notice a Route Origin problem because an active route lacks valid origin behavior." : "No user-visible Route Origin issue is detected in the current no-active-route/idle snapshot.");
  findings.push("Tester validation: create Current Location → Walmart, then rerun this audit and gridlyRouteOriginAudit() to compare active-route behavior against the no-route baseline.");

  return {
    available: true,
    version: "V264.5",

    activeRoutePresent,

    routeOriginNotRequiredInCurrentState: Boolean(!activeRoutePresent),

    routeOriginAuditAvailable,

    routeOriginAuditPass,

    routeOriginReason,

    routeOriginRequiredInCurrentState,

    routeOriginMissingBecauseNoRoute,

    routeOriginMissingBecauseFailure,

    routeOriginMissingBecauseAuditExpectation,

    actualUserVisibleIssueDetected,

    betaBlockerJustified,

    blockerClassification,

    recommendedAction,

    consumerFriendlyPass,

    findings,
    diagnostics: {
      routeOriginBetaBlockerReported,
      destinationSearchReady,
      currentLocationOriginReady,
      routeDetailsReady,
      walmartRouteRecoveryLikely,
      betaBlockers,
      routeOwnershipOriginText: text("routeOwnershipOrigin"),
      routeOwnershipDestinationText: text("routeOwnershipDestination"),
      routeOwnershipMonitoringText: text("routeOwnershipMonitoring"),
      desktopRouteStatusText: text("desktopRouteStatus"),
      routeWatchSetupHintText: text("routeWatchSetupHint"),
      routeOriginAuditResult: routeOriginAudit.result || null,
      routeGeometryAudit: routeGeometryAudit || null
    }
  };
}

