window.gridlyTravelTimeAudit = function gridlyTravelTimeAudit() {
  const places = gridlyGetSavedPlacesReadiness();
  const routeGeometry = gridlyGetRouteGeometryDiagnostics();
  const routeWatchConfigured = Boolean(places.routablePlaceCount >= 2 && (places.hasHome || places.hasWork));
  const routeMetrics = gridlyGetTravelTimeRouteMetrics(routeGeometry);
  const routeDistanceMiles = routeMetrics.routeDistanceMiles;
  const routeDistanceAvailable = Number.isFinite(Number(routeDistanceMiles)) && Number(routeDistanceMiles) > 0;
  const currentRouteDurationMinutes = routeMetrics.routeDurationMinutes;
  const routeDurationAvailable = Number.isFinite(Number(currentRouteDurationMinutes)) && Number(currentRouteDurationMinutes) > 0;
  const routeMetricsAvailable = Boolean(routeMetrics.routeMetricsAvailable);
  const missingRequirements = [
    !routeWatchConfigured ? "route_watch_not_configured" : "",
    !places.hasHome ? "home_not_configured" : "",
    !places.hasWork ? "work_not_configured" : "",
    !routeGeometry.routeGeometryAvailable ? "route_geometry_unavailable" : "",
    !routeMetricsAvailable ? "route_metrics_unavailable" : "",
    !routeDistanceAvailable ? "route_distance_unavailable" : "",
    !routeDurationAvailable ? "current_route_duration_unavailable" : ""
  ].filter(Boolean);
  const estimatedTravelTimeReady = Boolean(routeWatchConfigured && routeGeometry.routeGeometryAvailable && routeDurationAvailable);
  const baselineReady = Boolean(places.hasHome && places.hasWork && routeWatchConfigured && routeGeometry.routeGeometryAvailable && routeDistanceAvailable && routeDurationAvailable);
  const impactReadiness = gridlyGetTravelTimeImpactReadiness(routeGeometry);
  const currentCommuteSnapshot = window.gridlyCurrentCommuteSnapshot?.() || null;
  const currentCommuteSnapshotAvailable = Boolean(currentCommuteSnapshot?.routeConfigured && currentCommuteSnapshot?.routeMetricsAvailable);

  return {
    routeWatchConfigured,
    homeConfigured: places.hasHome,
    workConfigured: places.hasWork,
    routeGeometryAvailable: routeGeometry.routeGeometryAvailable,
    routeMetricsAvailable,
    routeMetricsSource: routeMetrics.routeMetricsSource,
    routeGeneratedAt: routeMetrics.routeGeneratedAt,
    routePointCount: routeMetrics.routePointCount,
    routeDistanceAvailable,
    routeDistanceMiles,
    routeDurationAvailable,
    currentRouteDurationMinutes,
    baselineReady,
    missingRequirements,
    estimatedTravelTimeReady,
    currentCommuteSnapshotAvailable,
    currentCommuteSnapshot,
    activeRouteImpactCount: impactReadiness.activeRouteImpactCount,
    activeCorridorImpactCount: impactReadiness.activeCorridorImpactCount,
    routeImpactReady: impactReadiness.routeImpactReady,
    unavailableReasons: {
      routeWatchConfigured: routeWatchConfigured ? null : (places.routablePlaceCount < 2 ? "fewer_than_two_routable_places" : "home_or_work_required"),
      homeConfigured: places.hasHome ? null : "saved_home_missing",
      workConfigured: places.hasWork ? null : "saved_work_missing",
      routeGeometryAvailable: routeGeometry.routeGeometryAvailable ? null : "active_route_polyline_missing",
      routeMetricsAvailable: routeMetricsAvailable ? null : "route_metrics_not_available_from_active_or_persisted_route",
      routeDistanceAvailable: routeDistanceAvailable ? null : "osrm_distance_not_available_for_current_route",
      routeDurationAvailable: routeDurationAvailable ? null : "osrm_duration_not_available_for_current_route",
      routeImpactReady: impactReadiness.routeImpactReady ? null : impactReadiness.routeImpactUnavailableReasons.join(",")
    },
    notes: ["Diagnostic-only foundation; no historical commute prediction, machine learning, schedulers, polling, or route recomputation are used."]
  };
};


function gridlyBuildCommuteBaselineBlueprint() {
  const places = gridlyGetSavedPlacesReadiness();
  const routeGeometry = gridlyGetRouteGeometryDiagnostics();
  const routeConfigured = Boolean(places.hasHome && places.hasWork && places.routablePlaceCount >= 2);
  const routeMetrics = gridlyGetTravelTimeRouteMetrics(routeGeometry);
  const routeMetricsAvailable = Boolean(routeMetrics.routeMetricsAvailable);
  const currentCommuteSnapshot = typeof window.gridlyCurrentCommuteSnapshot === "function"
    ? window.gridlyCurrentCommuteSnapshot()
    : null;
  const currentCommuteSnapshotAvailable = Boolean(
    currentCommuteSnapshot?.routeConfigured
    && currentCommuteSnapshot?.routeMetricsAvailable
  );
  const baselineCollectionReady = Boolean(
    places.hasHome
    && places.hasWork
    && routeConfigured
    && routeMetricsAvailable
    && currentCommuteSnapshotAvailable
  );
  const baselineStorageAudit = typeof window.gridlyCommuteBaselineStorageAudit === "function"
    ? window.gridlyCommuteBaselineStorageAudit()
    : { baselineStorageReady: false, sampleCount: 0, latestSample: null };
  const normalBaseline = typeof window.gridlyNormalCommuteBaseline === "function"
    ? window.gridlyNormalCommuteBaseline()
    : gridlyBuildNormalCommuteBaseline();
  const baselineStorageReady = Boolean(baselineStorageAudit.baselineStorageReady);
  const normalCommuteBaselineAvailable = Boolean(normalBaseline.normalCommuteMinutes > 0 && normalBaseline.sampleCount > 0);
  const baselineSampleCount = Math.max(0, Number(normalBaseline.sampleCount || 0));
  const latestBaselineSampleAt = normalBaseline.latestSampleAt || baselineStorageAudit.latestSample?.capturedAt || null;
  const normalCommuteMinutes = normalBaseline.normalCommuteMinutes;
  const baselineStatus = normalBaseline.baselineStatus || "unavailable";
  const baselineConfidence = normalBaseline.baselineConfidence || "none";
  const commuteDeltaSnapshot = typeof window.gridlyCommuteDeltaSnapshot === "function"
    ? window.gridlyCommuteDeltaSnapshot()
    : gridlyBuildCommuteDeltaSnapshot();
  const commuteDeltaAvailable = Boolean(commuteDeltaSnapshot.deltaAvailable);
  const commuteDeltaMinutes = Number.isFinite(Number(commuteDeltaSnapshot.deltaMinutes)) ? Number(commuteDeltaSnapshot.deltaMinutes) : null;
  const commuteDeltaStatus = commuteDeltaSnapshot.deltaStatus || "unavailable";
  const deltaComputationReady = Boolean(
    currentCommuteSnapshotAvailable
    && normalCommuteBaselineAvailable
    && normalCommuteMinutes > 0
  );
  const missingRequirements = [
    !places.hasHome ? "home_not_configured" : "",
    !places.hasWork ? "work_not_configured" : "",
    !routeConfigured ? "route_watch_not_configured_for_home_and_work" : "",
    !routeMetricsAvailable ? "route_metrics_unavailable" : "",
    !currentCommuteSnapshotAvailable ? "current_commute_snapshot_unavailable" : "",
    !baselineStorageReady ? "baseline_storage_empty_or_unavailable" : "",
    !normalCommuteBaselineAvailable ? "normal_commute_baseline_unavailable" : "",
    !deltaComputationReady ? "normal_commute_delta_inputs_unavailable" : ""
  ].filter(Boolean);

  return {
    routeConfigured,
    routeMetricsAvailable,
    currentCommuteSnapshotAvailable,
    baselineCollectionReady,
    baselineStorageReady,
    baselineSampleCount,
    latestBaselineSampleAt,
    normalCommuteBaselineAvailable,
    normalCommuteMinutes,
    baselineStatus,
    baselineConfidence,
    deltaComputationReady,
    commuteDeltaAvailable,
    commuteDeltaMinutes,
    commuteDeltaStatus,
    missingRequirements,
    recommendedFutureModel: {
      normalCommute: "rolling baseline duration",
      currentCommute: "latest route duration",
      delta: "difference between current and baseline duration"
    }
  };
}

window.gridlyCommuteBaselineBlueprint = function gridlyCommuteBaselineBlueprint() {
  return gridlyBuildCommuteBaselineBlueprint();
};

