const gridlyV737StaleFirstPaintAuditState = {
  cycleId: 0,
  cycleStartedAt: 0,
  firstPaints: {},
  ownershipTransitions: [],
  replacements: [],
  staleFirstPaintDetected: false,
  lastDetermination: "not_observed",
  lastRefreshBudgetImpactMs: 0
};

function getGridlyV737AuditNow() {
  return typeof performance !== "undefined" && typeof performance.now === "function" ? performance.now() : Date.now();
}

function getGridlyV737OwnershipSnapshot(extra = {}) {
  const activeCounty = typeof gridlyGetActiveCountyId === "function" ? gridlyGetActiveCountyId() : "";
  const selectedArea = typeof getGridlySelectedAwarenessArea === "function" ? getGridlySelectedAwarenessArea() : null;
  return {
    activeCounty,
    activeCountyName: safeDisplayText(typeof gridlyGetActiveCountyConfig === "function" ? gridlyGetActiveCountyConfig()?.name : "", ""),
    awarenessArea: safeDisplayText(selectedArea?.label || selectedArea?.storageValue || "", ""),
    awarenessAreaCountyId: selectedArea?.countyId ? gridlyNormalizeCountyId(selectedArea.countyId) : "",
    ...extra
  };
}

function recordGridlyV737OwnershipTransition(surface = "", payload = {}) {
  if (!surface) return null;
  const now = getGridlyV737AuditNow();
  const entry = {
    surface,
    at: Date.now(),
    offsetMs: Number((now - (gridlyV737StaleFirstPaintAuditState.cycleStartedAt || now)).toFixed(2)),
    ...getGridlyV737OwnershipSnapshot(payload)
  };
  gridlyV737StaleFirstPaintAuditState.ownershipTransitions.push(entry);
  gridlyV737StaleFirstPaintAuditState.ownershipTransitions = gridlyV737StaleFirstPaintAuditState.ownershipTransitions.slice(-40);
  return entry;
}

function recordGridlyV737FirstPaint(surface = "", payload = {}) {
  if (!surface) return null;
  if (!gridlyV737StaleFirstPaintAuditState.cycleStartedAt) {
    gridlyV737StaleFirstPaintAuditState.cycleStartedAt = getGridlyV737AuditNow();
  }
  const now = getGridlyV737AuditNow();
  const text = safeDisplayText(payload.text || payload.primary || payload.headline || payload.title || "", "");
  const existing = gridlyV737StaleFirstPaintAuditState.firstPaints[surface] || null;
  const entry = {
    surface,
    text,
    secondary: safeDisplayText(payload.secondary || payload.subline || payload.status || "", ""),
    source: safeDisplayText(payload.source || payload.owner || "", "unknown"),
    authoritative: Boolean(payload.authoritative),
    at: Date.now(),
    offsetMs: Number((now - gridlyV737StaleFirstPaintAuditState.cycleStartedAt).toFixed(2)),
    ...getGridlyV737OwnershipSnapshot(payload.ownership || {})
  };
  if (!existing) {
    gridlyV737StaleFirstPaintAuditState.firstPaints[surface] = entry;
  } else if ((existing.text || existing.secondary) && (existing.text !== entry.text || existing.secondary !== entry.secondary)) {
    const replacement = { surface, from: existing, to: entry, trigger: payload.trigger || entry.source, replacementTimingMs: entry.offsetMs };
    gridlyV737StaleFirstPaintAuditState.replacements.push(replacement);
    gridlyV737StaleFirstPaintAuditState.replacements = gridlyV737StaleFirstPaintAuditState.replacements.slice(-20);
    if (existing.authoritative === false && entry.authoritative === true) {
      gridlyV737StaleFirstPaintAuditState.staleFirstPaintDetected = true;
      gridlyV737StaleFirstPaintAuditState.lastDetermination = "stale_first_paint_replaced_by_authoritative_content";
      gridlyV737StaleFirstPaintAuditState.lastRefreshBudgetImpactMs = Number(Math.max(0, entry.offsetMs - existing.offsetMs).toFixed(2));
    }
  }
  return entry;
}


const GRIDLY_STALE_FIRST_PAINT_NEUTRAL_COPY = Object.freeze({
  primary: "Monitoring nearby conditions",
  secondary: "Checking current conditions",
  trustLine: "Monitoring nearby conditions"
});

const gridlyStaleFirstPaintGuardAuditState = {
  available: true,
  pass: true,
  canonicalAwarenessArea: "",
  renderedHeadline: "",
  renderedBriefLocation: "",
  staleAreaDetected: false,
  staleEventDetected: false,
  staleRouteTextDetected: false,
  neutralLoadingStateUsed: false,
  finalContextMatchesCanonical: true,
  lastDecision: "not_observed"
};

function normalizeGridlyStaleFirstPaintText(value = "") {
  return String(value || "").toLowerCase().replace(/[^a-z0-9]+/g, " ").replace(/\s+/g, " ").trim();
}

function gridlyTextMentionsAwarenessArea(text = "", areaName = "") {
  const area = safeDisplayText(areaName, "");
  if (!area) return false;
  return new RegExp(`\\b${area.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")}\\b`, "i").test(String(text || ""));
}

function gridlyStaleFirstPaintKnownAreaLeak(text = "", canonicalArea = "") {
  const normalizedCanonical = normalizeGridlyStaleFirstPaintText(canonicalArea);
  const knownAreas = (typeof GRIDLY_AWARENESS_AREA_DEFINITIONS !== "undefined" ? GRIDLY_AWARENESS_AREA_DEFINITIONS : [])
    .map((area) => safeDisplayText(area?.label || area?.storageValue, ""))
    .filter(Boolean);
  return knownAreas.some((area) => normalizeGridlyStaleFirstPaintText(area) !== normalizedCanonical && gridlyTextMentionsAwarenessArea(text, area));
}

function gridlyStaleFirstPaintExtractModelText(model = {}) {
  return [
    model?.awarenessPrimary,
    model?.awarenessSecondary,
    model?.awarenessBrief?.primary,
    model?.awarenessBrief?.secondary,
    model?.awarenessBrief?.selectedHeadline,
    model?.pulseModel?.renderedPulseHeadline,
    model?.pulseModel?.renderedPulseSubline,
    model?.communityAwarenessSummary?.panelTitle,
    model?.communityAwarenessSummary?.status,
    model?.communityAwarenessSummary?.subline
  ].map((value) => safeDisplayText(value, "")).filter(Boolean).join(" · ");
}

function gridlyStaleFirstPaintActiveEventText(model = {}) {
  const activeAwareness = model?.pulseModel?.activeAwareness || model?.activeAwareness || {};
  const samples = Array.isArray(activeAwareness?.activeAwarenessSamples) ? activeAwareness.activeAwarenessSamples : [];
  const record = activeAwareness?.topAwarenessSelectedLocationIntelligence?.item
    || activeAwareness?.topAwarenessSelectedLocationIntelligence
    || activeAwareness?.selectedIncident
    || samples[0]
    || activeAwareness;
  return [
    record?.headline,
    record?.title,
    record?.summary,
    record?.description,
    record?.localizedSummary,
    record?.roadName,
    record?.resolvedLocationLabel,
    activeAwareness?.headline,
    activeAwareness?.resolvedLocationLabel
  ].map((value) => safeDisplayText(value, "")).filter(Boolean).join(" · ");
}

function gridlyStaleFirstPaintRouteTextIsAllowed(renderedText = "", activeEventText = "") {
  const renderedHasUs90 = /\b(?:US\s*90|U\.S\.\s*90|Highway\s*90)\b/i.test(renderedText);
  if (!renderedHasUs90) return true;
  return /\b(?:US\s*90|U\.S\.\s*90|Highway\s*90)\b/i.test(activeEventText);
}

function guardGridlyStaleFirstPaintTextModel(textModel = {}) {
  const canonical = typeof getGridlyCanonicalAwarenessPresentationContext === "function" ? getGridlyCanonicalAwarenessPresentationContext() : null;
  const canonicalArea = safeDisplayText(canonical?.displayName || canonical?.label, "");
  const renderedHeadline = safeDisplayText(textModel?.awarenessPrimary || textModel?.awarenessBrief?.primary, "");
  const renderedBriefLocation = safeDisplayText(textModel?.awarenessSecondary || textModel?.awarenessBrief?.secondary, "");
  const renderedText = gridlyStaleFirstPaintExtractModelText(textModel);
  const activeEventText = gridlyStaleFirstPaintActiveEventText(textModel);
  const quiet = String(textModel?.awarenessBrief?.state || "quiet") === "quiet";
  const staleAreaDetected = Boolean(canonicalArea && gridlyStaleFirstPaintKnownAreaLeak(renderedText, canonicalArea));
  const activeTextMentionsCanonical = !activeEventText || gridlyTextMentionsAwarenessArea(activeEventText, canonicalArea) || /\bTX\s*321\b/i.test(activeEventText);
  const renderedTextMentionsCanonical = gridlyTextMentionsAwarenessArea(renderedText, canonicalArea) || /\bTX\s*321\b/i.test(renderedText);
  const staleEventDetected = Boolean(!quiet && canonicalArea && !renderedTextMentionsCanonical && !activeTextMentionsCanonical);
  const staleRouteTextDetected = !gridlyStaleFirstPaintRouteTextIsAllowed(renderedText, activeEventText);
  const shouldNeutralize = staleAreaDetected || staleEventDetected || staleRouteTextDetected;
  const guarded = shouldNeutralize
    ? {
      ...textModel,
      awarenessPrimary: GRIDLY_STALE_FIRST_PAINT_NEUTRAL_COPY.primary,
      awarenessSecondary: GRIDLY_STALE_FIRST_PAINT_NEUTRAL_COPY.secondary,
      awarenessBrief: {
        ...(textModel.awarenessBrief || {}),
        state: "quiet",
        primary: GRIDLY_STALE_FIRST_PAINT_NEUTRAL_COPY.primary,
        secondary: GRIDLY_STALE_FIRST_PAINT_NEUTRAL_COPY.secondary,
        selectedHeadline: GRIDLY_STALE_FIRST_PAINT_NEUTRAL_COPY.primary,
        selectedSource: "stale_first_paint_guard_neutral_loading",
        trustLine: GRIDLY_STALE_FIRST_PAINT_NEUTRAL_COPY.trustLine,
        staleFirstPaintGuardApplied: true
      }
    }
    : textModel;
  const finalRenderedText = shouldNeutralize ? `${GRIDLY_STALE_FIRST_PAINT_NEUTRAL_COPY.primary} ${GRIDLY_STALE_FIRST_PAINT_NEUTRAL_COPY.secondary}` : renderedText;
  Object.assign(gridlyStaleFirstPaintGuardAuditState, {
    available: true,
    pass: !(staleAreaDetected || staleEventDetected || staleRouteTextDetected) || shouldNeutralize,
    canonicalAwarenessArea: canonicalArea,
    renderedHeadline: shouldNeutralize ? GRIDLY_STALE_FIRST_PAINT_NEUTRAL_COPY.primary : renderedHeadline,
    renderedBriefLocation: shouldNeutralize ? GRIDLY_STALE_FIRST_PAINT_NEUTRAL_COPY.secondary : renderedBriefLocation,
    staleAreaDetected,
    staleEventDetected,
    staleRouteTextDetected,
    neutralLoadingStateUsed: shouldNeutralize,
    finalContextMatchesCanonical: shouldNeutralize || !canonicalArea || quiet || gridlyTextMentionsAwarenessArea(finalRenderedText, canonicalArea) || /\bTX\s*321\b/i.test(finalRenderedText),
    lastDecision: shouldNeutralize ? "neutral_loading_state_used" : "canonical_context_allowed"
  });
  return guarded;
}

function gridlyStaleFirstPaintGuardAudit() {
  return { ...gridlyStaleFirstPaintGuardAuditState };
}

