  const markerLayerDestroyed = Boolean(gridlyCrossingRenderLifecycleAuditState.markerLayerDestroyed);
  const markerLayerRebuilt = Boolean(gridlyCrossingRenderLifecycleAuditState.markerLayerRebuilt);
  const popupIndirectRenderDetected = Boolean(!renderTriggeredByPopupOpen && (renderTriggeredBySafeZone || renderTriggeredByMoveEnd) && Number(gridlyCrossingRenderLifecycleAuditState.popupOpenedCount || 0) > 0);
  const popupAutopanRenderDetected = /popup-autopan|autoPan|autopan/i.test(renderReasonText);
  const popupInvalidateSizeRenderDetected = /invalidateSize|popup-invalidate/i.test(renderReasonText);
  const intentionalViewportRenderDetected = Boolean(gridlyCrossingRenderLifecycleAuditState.realViewportChangeAllowedDuringPopupOpen || /intentional-user-pan|intentional-user-zoom/.test(renderReasonText));
  const falseViewportRenderBlocked = Number(gridlyV921RCrossingConsistencyState?.falseViewportRendersBlocked || 0) + Number(gridlyCrossingRenderLifecycleAuditState.popupMapMoveOrZoomRenderBlockedDuringPopupOpen || 0);
