  const popupSuppressedViewportRenders = suppressedCalls.filter((call) => /map-move-or-zoom|move|zoom|viewport|popup/i.test(`${call.reason || ""} ${call.caller || ""}`)).length;
  const selectionStateChangeSuppressedFullRender = Number(gridlyCrossingRenderLifecycleAuditState.selectionStateChangeSuppressedFullRender || 0);
  const selectedMarkerUpdatedInPlace = Number(gridlyCrossingRenderLifecycleAuditState.selectedMarkerUpdatedInPlace || 0);
