  const combinedStateChangeRenderBlockedDuringPopupOpen = Boolean(gridlyCrossingRenderLifecycleAuditState.combinedStateChangeRenderBlockedDuringPopupOpen);
  const combinedStateChangeReasonBlocked = gridlyCrossingRenderLifecycleAuditState.combinedStateChangeReasonBlocked || "";
  const realViewportChangeAllowedDuringPopupOpen = Boolean(gridlyCrossingRenderLifecycleAuditState.realViewportChangeAllowedDuringPopupOpen);
  const popupMoveRenderBlockedDuringPopupOpen = Number(gridlyCrossingRenderLifecycleAuditState.popupMoveRenderBlockedDuringPopupOpen || 0);
  const popupMoveEndRenderBlockedDuringPopupOpen = Number(gridlyCrossingRenderLifecycleAuditState.popupMoveEndRenderBlockedDuringPopupOpen || 0);
  const popupMapMoveOrZoomRenderBlockedDuringPopupOpen = Number(gridlyCrossingRenderLifecycleAuditState.popupMapMoveOrZoomRenderBlockedDuringPopupOpen || 0);
  const crossingLayerClearBlockedReason = gridlyCrossingRenderLifecycleAuditState.crossingLayerClearBlockedReason || "";
  const popupOpenedCount = Number(gridlyCrossingRenderLifecycleAuditState.popupOpenedCount || 0);
