function gridlyRenderPipelineAttributionAudit() {
  const crossingCalls = gridlyV921RenderPipelineState.crossingCalls;
  const total = crossingCalls.length || 1;
  const rebuilds = crossingCalls.filter((call) => call.renderMode === "full-rebuild" || call.layerCleared).length;
  const partial = crossingCalls.filter((call) => call.renderMode === "diff-and-frame-schedule").length;
  const skipped = crossingCalls.filter((call) => call.signatureEqual || call.skippedBeforeModelWork || call.skippedAfterModelWork).length;
  const created = gridlyV921RenderPipelineState.markerReuse.created;
  const reused = gridlyV921RenderPipelineState.markerReuse.reused;
  const phases = crossingCalls.flatMap((call) => Object.entries(call.phases || {}).map(([name, duration]) => ({ pipeline: "crossings", name, duration })));
  return {
    available: true, version: GRIDLY_V921_VERSION,
    renderPipelines: ["crossings", "alerts", "community-pulse", "panel-open"],
    measuredPhases: phases,
    worstFunctions: phases.sort((a, b) => b.duration - a.duration).slice(0, 8),
    worstLoops: crossingCalls.map((call) => ({ functionName: "renderCrossingMarkersFromList", itemCount: call.visibleRecordCount, duration: call.duration, markersCreated: call.markersCreated })).sort((a, b) => b.duration - a.duration).slice(0, 5),
    renderReasonCounts: { ...gridlyV921RenderPipelineState.reasonCounts },
    signatureSkipRate: Number((skipped / total).toFixed(3)), rebuildRate: Number((rebuilds / total).toFixed(3)), partialUpdateRate: Number((partial / total).toFixed(3)),
    markerReuseRate: Number((reused / Math.max(1, reused + created)).toFixed(3)),
    popupConstructionCounts: { built: gridlyCrossingRenderLifecycleAuditState.popupContentSetCount, deferred: gridlyV921RenderPipelineState.markerReuse.popupContentDeferred },
    staleBatchCancellations: gridlyV921RenderPipelineState.frameScheduling.cancelledGenerations.length,
    recommendations: gridlyV921RenderPipelineState.recommendations, safeForPatch: gridlyV921RenderPipelineState.safeForPatch
  };
}
