function getGridlyRenderedCrossingMarkerCountyIds() {
  const countyIds = new Set();
  if (crossingMarkers instanceof Map) {
    crossingMarkers.forEach((marker) => {
      const markerCountyId = marker?.options?.gridlyCountyId || marker?.options?.gridlyCrossingCountyId || null;
      if (markerCountyId) countyIds.add(String(markerCountyId));
    });
  }
  if (crossingLayer && typeof crossingLayer.getLayers === "function") {
    crossingLayer.getLayers().forEach((layer) => {
      const markerCountyId = layer?.options?.gridlyCountyId || layer?.options?.gridlyCrossingCountyId || null;
      if (markerCountyId) countyIds.add(String(markerCountyId));
    });
  }
  return Array.from(countyIds).sort();
}

function pushAuditCall(bucket, reason, extra = {}) {
  const timestamp = Date.now();
  bucket.count += 1;
  bucket.lastCalls.push({ timestamp, iso: new Date(timestamp).toISOString(), reason, ...extra });
  if (bucket.lastCalls.length > NETWORK_AUDIT_LOG_LIMIT) bucket.lastCalls.splice(0, bucket.lastCalls.length - NETWORK_AUDIT_LOG_LIMIT);
  return timestamp;
}

