        const communityCount = Math.max(0, Number(alert?.__gridlyCommunityReportEvidenceCount || evidenceCount || 0));
        const officialRows = evidenceRows.filter(rowLooksOfficialRoadway);
        const weatherRows = evidenceRows.filter(rowLooksWeather);
