function verifyGridlyPortraitAwarenessSurfaceSync({ textModel = {}, awarenessAreaName = "" } = {}) {
  const domState = readGridlyPortraitAwarenessSurfaceDomState();
  const expectedPrimary = safeDisplayText(textModel?.awarenessPrimary, "");
  const expectedSecondary = safeDisplayText(textModel?.awarenessSecondary, "");
  const expectedArea = safeDisplayText(awarenessAreaName || textModel?.communityAwarenessSummary?.awarenessAreaName, "");
  const topSynced = Boolean(expectedPrimary && domState.topPrimary === expectedPrimary && (!expectedSecondary || domState.topSecondary === expectedSecondary));
  const panelSynced = Boolean(
    domState.panelVisible
    && domState.panelOwner === "location-awareness"
    && (!expectedArea || domState.panelAreaName === expectedArea)
    && domState.panelTitle
    && (!expectedPrimary || domState.panelTitle === expectedPrimary || domState.panelTitle === expectedArea || domState.panelTitle === `${expectedArea} Context`)
  );
  return { topSynced, panelSynced, domState, expectedPrimary, expectedSecondary, expectedArea };
}

function gridlyLp0552RefreshOpenHistoricalSheetForAwarenessChange(reason = "awareness-area-change") {
  if (typeof document === "undefined") return { available: false, refreshed: false, reason: "document_unavailable" };
  const sheet = document.getElementById("gridlyPortraitV2Sheet");
  const body = document.getElementById("gridlyPortraitV2SheetBody");
  const title = document.getElementById("gridlyPortraitV2SheetTitle");
  if (!sheet || !body || sheet.dataset?.activeSheet !== "history" || sheet.hidden) return { available: true, refreshed: false, reason: "history_sheet_not_open" };
  const template = typeof sheetTemplates !== "undefined" ? sheetTemplates.history : null;
  if (!template || typeof template.html !== "function") return { available: true, refreshed: false, reason: "history_template_unavailable" };
  const priorText = safeDisplayText(body.textContent || "", "");
  const priorSubject = safeDisplayText(body.querySelector?.("[data-gridly-history-consumer-subject]")?.textContent || "", "");
  title.textContent = template.title || "Historical Intelligence";
  body.innerHTML = template.html() || "";
  gridlyBindPwaInstallUx?.(body);
  bindV2SheetActions?.();
  const nextSubject = safeDisplayText(body.querySelector?.("[data-gridly-history-consumer-subject]")?.textContent || "", "");
  sheet.dataset.gridlyHistoryRefreshReason = reason;
  sheet.dataset.gridlyHistoryLastRefreshAt = new Date().toISOString();
  return { available: true, refreshed: true, behavior: "rerender", reason, priorSubject, nextSubject, stalePriorSubjectRemoved: !priorSubject || priorSubject === nextSubject || !safeDisplayText(body.textContent || "", "").includes(priorSubject), priorTextChanged: priorText !== safeDisplayText(body.textContent || "", "") };
}

function syncGridlyAwarenessAreaSurfacesImmediately(reason = "awareness-area-change", options = {}) {
  const syncStartedAt = typeof performance !== "undefined" && typeof performance.now === "function" ? performance.now() : Date.now();
  const summary = typeof buildGridlyCommunityAwarenessIntelligenceSummary === "function"
    ? buildGridlyCommunityAwarenessIntelligenceSummary(options?.summaryOptions || {})
    : null;
  const authoritativeSummary = typeof window.gridlyPublishCanonicalAreaTransitionSummary === "function"
    ? window.gridlyPublishCanonicalAreaTransitionSummary(summary, reason)
    : summary;
  const awarenessAreaName = safeDisplayText(summary?.awarenessAreaName, gridlyGetActiveCountyConfig()?.name || "selected county");
  const scopedPulseOptions = {
    ...(options?.pulseOptions || {}),
    ...(options?.summaryOptions || {}),
    activeReports: Array.isArray(authoritativeSummary?.activeReportsInArea) ? authoritativeSummary.activeReportsInArea : options?.pulseOptions?.activeReports,
    activeHazards: Array.isArray(authoritativeSummary?.activeHazardsInArea) ? authoritativeSummary.activeHazardsInArea : options?.pulseOptions?.activeHazards,
    communityAwarenessSummary: authoritativeSummary,
    communityActivityCount: (Array.isArray(authoritativeSummary?.activeReportsInArea) ? authoritativeSummary.activeReportsInArea.length : 0) + (Array.isArray(authoritativeSummary?.activeHazardsInArea) ? authoritativeSummary.activeHazardsInArea.length : 0),
    communityActivitySource: "awareness_area_immediate_sync.area_scoped_active_items",
    reason
  };

  if (typeof syncMobileDestinationCommandCard === "function") {
    syncMobileDestinationCommandCard();
  }

  const communityPulseState = typeof refreshGridlyCommunityPulseSharedModel === "function"
    ? refreshGridlyCommunityPulseSharedModel({ ...scopedPulseOptions, topAwarenessMicrolineReadOnly: true })
    : (typeof renderGridlyCommunityPulse === "function" ? renderGridlyCommunityPulse(scopedPulseOptions) : null);

  let portraitRefreshResult = null;
  if (typeof refreshPortraitV2LocalizedIntelligence === "function" && options?.refreshPortrait !== false) {
    portraitRefreshResult = refreshPortraitV2LocalizedIntelligence({
      pulseModel: communityPulseState,
      communityAwarenessSummary: authoritativeSummary
    });
  }
  if (typeof renderUnifiedIncidents === "function" && options?.refreshMapMarkers !== false) {
    renderUnifiedIncidents(`awareness-area-sync:${reason}`);
  }
  const historicalSheetRefreshResult = gridlyLp0552RefreshOpenHistoricalSheetForAwarenessChange(reason);

  const surfaceSync = verifyGridlyPortraitAwarenessSurfaceSync({
    textModel: portraitRefreshResult?.textModel,
    awarenessAreaName
  });

  gridlyAwarenessAreaImmediateSyncState = {
    lastReason: reason,
    lastSyncedAt: new Date().toISOString(),
    awarenessAreaName,
    topAwarenessSynced: Boolean(surfaceSync.topSynced),
    panelSynced: Boolean(surfaceSync.panelSynced),
    communityPulseSynced: Boolean(communityPulseState && isGridlyCachedAwarenessSummaryForCurrentArea(communityPulseState.communityAwarenessSummary || summary || {})),
    durationMs: Number((((typeof performance !== "undefined" && typeof performance.now === "function") ? performance.now() : Date.now()) - syncStartedAt).toFixed(2)),
    crossingsInArea: Array.isArray(summary?.crossingsInArea) ? summary.crossingsInArea.length : 0,
    activeHazardsInArea: Array.isArray(summary?.activeHazardsInArea) ? summary.activeHazardsInArea.length : 0,
    activeReportsInArea: Array.isArray(summary?.activeReportsInArea) ? summary.activeReportsInArea.length : 0,
    pulseVisible: Boolean(communityPulseState?.pulseVisible),
    historicalSheetRefreshResult,
    surfaceDomState: surfaceSync.domState,
    expectedTopAwarenessPrimary: surfaceSync.expectedPrimary,
    expectedTopAwarenessSecondary: surfaceSync.expectedSecondary
  };

  if (typeof recordGridlyActiveLocationLifecycleEvent === "function") {
    recordGridlyActiveLocationLifecycleEvent("syncGridlyAwarenessAreaSurfacesImmediately", {
      reason,
      awarenessAreaName,
      topAwarenessSynced: Boolean(surfaceSync.topSynced),
      panelSynced: Boolean(surfaceSync.panelSynced),
      communityPulseSynced: Boolean(gridlyAwarenessAreaImmediateSyncState.communityPulseSynced),
      durationMs: gridlyAwarenessAreaImmediateSyncState.durationMs
    });
  }

  return {
    summary,
    communityPulseState,
    portraitRefreshResult,
    syncState: { ...gridlyAwarenessAreaImmediateSyncState }
  };
}

window.gridlyAwarenessAreaImmediateSyncDebug = function gridlyAwarenessAreaImmediateSyncDebug() {
  return { ...gridlyAwarenessAreaImmediateSyncState };
};

function syncMobileDestinationCommandCard(options = {}) {
  const cardRenderStartedAt = getGridlyDestinationPerfNow();
  const selectedLabel = getSelectedDestinationLabel();
  const preview = typeof getGridlyDestinationRoutePreviewState === "function" ? getGridlyDestinationRoutePreviewState() : (window.GridlyDestinationRoutePreview || {});
  const destinationPreviewActive = Boolean(selectedLabel || preview?.active || preview?.destination);
  const routeIsMonitoring = Boolean((routeWatchActivated || window.__gridlyRouteWatchActive) && !destinationPreviewActive);
  const previewMeta = selectedLabel ? getGridlyDestinationPreviewMetaText() : "";
  const ownership = typeof resolveGridlyRouteOwnershipSurface === "function" ? resolveGridlyRouteOwnershipSurface() : null;
  const relationLine = selectedLabel
    ? (preview?.routeRelationLineText || getGridlyRouteRelationLineText(ownership?.originLabel || "Map Center", selectedLabel))
    : "";
  const destinationSupportText = selectedLabel
    ? (preview?.sameSavedPlaceRouteGuardActive
      ? (preview.sameSavedPlaceRouteGuardMessage || "Choose a different destination")
      : `${relationLine} · ${ownership?.monitoringLabel || (routeIsMonitoring ? "Monitoring Active" : "Preview Only")}${previewMeta ? ` · ${previewMeta}` : ""}`)
    : "";
  const routeImpactText = routeIsMonitoring && selectedLabel ? getGridlyDestinationRouteImpactCardText() : "";
  const routeMonitoringSupportText = routeIsMonitoring
    ? [
        "Route Watch Active",
        destinationSupportText || "Monitoring saved destination",
        routeImpactText
      ].filter((line) => String(line || "").trim()).join("\n")
    : destinationSupportText;
  const awarenessSummary = getGridlyMobileAwarenessPanelSummary(options?.communityAwarenessSummary ? { summary: options.communityAwarenessSummary } : {});
  const visibilityState = getGridlyMobileCommandCardVisibilityState(awarenessSummary);
  const popupInteractionActive = visibilityState.popupInteractionActive;
  const awarenessPanelMode = Boolean(visibilityState.awarenessPanelMode);
  const cardVisible = Boolean(visibilityState.visible);
  const card = document.getElementById("mobileDestinationCommandTitle")?.closest?.(".mobile-destination-command");
  if (card) {
    card.hidden = !cardVisible;
    card.setAttribute("aria-hidden", cardVisible ? "false" : "true");
    card.classList.toggle("is-command-card-suppressed", !cardVisible);
    if (!cardVisible) {
      card.classList.remove("visible", "active", "is-awareness-panel", "awareness", "owner-awareness", "gridly-awareness-owner", "is-destination-panel");
    }
  }
  card?.classList.toggle("is-awareness-panel", Boolean(cardVisible && awarenessPanelMode));
  card?.classList.toggle("awareness", Boolean(cardVisible && awarenessPanelMode));
  card?.classList.toggle("owner-awareness", Boolean(cardVisible && awarenessPanelMode));
  card?.classList.toggle("gridly-awareness-owner", Boolean(cardVisible && awarenessPanelMode));
  card?.classList.toggle("is-destination-panel", Boolean(cardVisible && !awarenessPanelMode));
  document.body?.classList.toggle("gridly-mobile-awareness-panel-present", Boolean(cardVisible && awarenessPanelMode));
  window.__gridlyMobileCommandCardVisibilityState = { ...visibilityState, visible: cardVisible };
  window.__gridlySyncAwarenessPanelDockContract?.();

  if (!cardVisible) {
    document.getElementById("mobileAwarenessPanelCrossings")?.toggleAttribute("hidden", true);
    document.getElementById("mobileAwarenessPanelIssues")?.toggleAttribute("hidden", true);
    safeText("mobileDestinationCommandImpact", "");
  } else if (awarenessPanelMode) {
    safeText("mobileAwarenessPanelKicker", getGridlyLocationAwarenessCardKicker(awarenessSummary.areaName || awarenessSummary.awarenessAreaName));
    safeText("mobileDestinationCommandTitle", awarenessSummary.panelTitle);
    safeText("mobileDestinationCommandMeta", awarenessSummary.status);
    safeText("mobileAwarenessPanelCrossings", awarenessSummary.crossingsLine);
    safeText("mobileAwarenessPanelIssues", "");
    document.getElementById("mobileAwarenessPanelCrossings")?.toggleAttribute("hidden", !String(awarenessSummary.crossingsLine || "").trim());
    document.getElementById("mobileAwarenessPanelIssues")?.toggleAttribute("hidden", true);
    safeText("mobileDestinationCommandImpact", "");
    safeText("mobileDestinationCommandBtn", "Search");
  } else {
    const impactText = selectedLabel ? getGridlyDestinationRouteImpactCardText() : "";
    safeText("mobileAwarenessPanelKicker", "Route");
    safeText("mobileDestinationCommandTitle", selectedLabel ? getGridlyRouteContextTitle(selectedLabel) : (routeIsMonitoring ? getGridlyRouteContextTitle("") : "Destination"));
    safeText(
      "mobileDestinationCommandMeta",
      selectedLabel
        ? (routeMonitoringSupportText || "Calculating route…")
        : routeIsMonitoring
          ? "Selected: Saved destination"
          : "Choose where you're going"
    );
    safeText("mobileAwarenessPanelCrossings", "");
    safeText("mobileAwarenessPanelIssues", "");
    document.getElementById("mobileAwarenessPanelCrossings")?.toggleAttribute("hidden", true);
    document.getElementById("mobileAwarenessPanelIssues")?.toggleAttribute("hidden", true);
    safeText("mobileDestinationCommandImpact", impactText);
    safeText("mobileDestinationCommandBtn", selectedLabel ? "Change" : "Choose Route");
  }

  const impactLine = document.getElementById("mobileDestinationCommandImpact");
  if (impactLine) {
    const hasImpactText = Boolean(String(impactLine.textContent || "").trim());
    impactLine.setAttribute("aria-disabled", hasImpactText ? "false" : "true");
    impactLine.title = hasImpactText ? "Open route awareness details" : "";
  }
  syncGridlyVisibleRouteExitControls();
  bindGridlyVisibleRouteExitControls();
  if (GRIDLY_DESTINATION_IMPACT_PANE_STATE.paneOpen) renderGridlyDestinationImpactPane();
  setGridlyDestinationPerformanceTiming("renderMs", getGridlyDestinationPerfNow() - cardRenderStartedAt);
}

function clearGridlyDestinationRoutePreview(options = {}) {
  if (options?.preservePerformanceAudit !== true) resetGridlyDestinationPerformanceAudit("idle");
  else invalidateGridlyDestinationRouteIntelligenceCache();
  const preview = getGridlyDestinationRoutePreviewState();
  preview.requestId = Number(preview.requestId || 0) + 1;
  preview.active = false;
  preview.status = "idle";
  preview.source = null;
  preview.destination = null;
  preview.distanceMeters = null;
  preview.distanceMiles = null;
  preview.etaMinutes = null;
  preview.durationSeconds = null;
  preview.geometry = [];
  preview.error = "";
  preview.autoLocationAttempted = false;
  preview.autoLocationSucceeded = false;
  preview.autoLocationFallbackUsed = false;
  preview.autoLocationFallbackReason = "";
  preview.sameSavedPlaceRouteGuardActive = false;
  preview.sameSavedPlaceRouteGuardMessage = "";
  preview.routeRelationLineText = "";
  try {
    destinationRoutePreviewLayer?.clearLayers?.();
  } catch (error) {
    if (options?.silent !== true) console.warn("Failed to clear destination route preview:", error);
  }
  preview.routeLayer = null;
  window.GridlyDestinationRoutePreview = preview;
  if (options?.syncCard !== false) syncMobileDestinationCommandCard();
  return true;
}

function formatGridlyRouteOriginLabel(label = "", source = "") {
  const rawLabel = String(label || "").trim();
  const normalizedSource = String(source || "").toLowerCase();
  const normalizedLabel = rawLabel.toLowerCase();
  if (["gps", "current_location", "current-location"].includes(normalizedSource) || normalizedLabel === "current location") return "Current Location";
  if (normalizedSource === "home" || normalizedLabel === "home") return "Home";
  if (normalizedSource === "work" || normalizedLabel === "work") return "Work";
  if (normalizedSource === "map_center" || normalizedLabel === "map center") return "Map Center";
  return rawLabel || "Saved Place";
}

function gridlyRouteOriginCoordinatesMatchDestination(originCoords, destinationCoords) {
  const origin = normalizeCoordinatePair(originCoords?.lat, originCoords?.lng);
  const destination = normalizeCoordinatePair(destinationCoords?.lat, destinationCoords?.lng);
  if (!origin || !destination) return false;
  return Math.abs(origin.lat - destination.lat) < 0.000001 && Math.abs(origin.lng - destination.lng) < 0.000001;
}

const GRIDLY_SAVED_PLACE_ROUTE_GUARD_DISTANCE_MILES = 0.03;

function isGridlySavedPlaceDestination(destination = null) {
  return Boolean(destination && (destination.provider === "saved_place" || destination.raw?.savedPlace === true || String(destination.source || "") === "saved_place"));
}

function getGridlySavedPlaceTypeFromDestination(destination = null) {
  return String(destination?.savedPlaceType || destination?.raw?.savedPlaceType || destination?.providerId || destination?.id || "").toLowerCase();
}

function gridlyRouteOriginNearlyMatchesDestination(originCoords, destinationCoords, maxMiles = GRIDLY_SAVED_PLACE_ROUTE_GUARD_DISTANCE_MILES) {
  const distanceMiles = getGridlyCoordinateDistanceMiles(originCoords, destinationCoords);
  return distanceMiles !== null && distanceMiles <= maxMiles;
}

function getGridlyRouteRelationLineText(originLabel = "", destinationLabel = "") {
  const origin = gridlyFriendlyPlaceLabel(originLabel, "Map Center");
  const destination = gridlyFriendlyPlaceLabel(destinationLabel, "Destination");
  return `${origin} → ${destination}`;
}

function syncGridlyDestinationPreviewRouteCard(origin = null, destination = null, options = {}) {
  if (!origin || !destination) return false;
  const originLabel = formatGridlyRouteOriginLabel(origin.label, origin.source);
  const destinationLabel = gridlyFriendlyPlaceLabel(
    destination.label || destination.title || destination.displayName || destination.address || destination.name,
    "Destination"
  );
  const relationLine = getGridlyRouteRelationLineText(originLabel, destinationLabel);
  safeText("desktopRouteHome", originLabel);
  safeText("desktopRouteWork", destinationLabel);
  safeText("routeCardLabel", relationLine);
  safeText("desktopRouteStatus", `Route created · Previewing ${originLabel} → ${destinationLabel}. Start Route Watch to monitor this route.`);
  if (options?.syncSetupHint === true || !(routeWatchActivated || window.__gridlyRouteWatchActive)) {
    safeText("routeWatchSetupHint", `Route created · Previewing ${originLabel} → ${destinationLabel}. Start Route Watch to monitor this route.`);
  }
  return relationLine;
}

function getGridlySavedPlaceRouteGuard(destination = null, origin = null) {
  if (!isGridlySavedPlaceDestination(destination) || !origin) {
    return { active: false, reason: "", message: "", originMatchesDestination: false };
  }
  const destinationLabel = gridlyFriendlyPlaceLabel(destination?.label || destination?.title || destination?.displayName || "Saved place", "Saved place");
  const destinationType = getGridlySavedPlaceTypeFromDestination(destination);
  const originSource = String(origin?.source || "").toLowerCase();
  const sameNamedSavedPlace = Boolean(destinationType && ["home", "work"].includes(destinationType) && originSource === destinationType);
  const nearSameCoordinates = gridlyRouteOriginNearlyMatchesDestination(origin, destination);
  if (!sameNamedSavedPlace && !nearSameCoordinates) {
    return { active: false, reason: "", message: "", originMatchesDestination: false };
  }
  const message = sameNamedSavedPlace || ["home", "work"].includes(destinationType)
    ? `You’re already at ${destinationLabel}`
    : "Choose a different destination";
  return {
    active: true,
    reason: sameNamedSavedPlace ? "same_saved_place" : "near_identical_coordinates",
    message,
    originMatchesDestination: true
  };
}

function getGridlySelectedRouteStartOriginCandidate() {
  const startId = els?.routeWatchStartSelect?.value || "";
  if (!startId || typeof getSavedPlaces !== "function") return null;
  const startPlace = getSavedPlaces().find((place) => place.id === startId) || null;
  const coords = normalizeCoordinatePair(startPlace?.lat, startPlace?.lng);
  if (!startPlace || !coords) return null;
  const source = startPlace.id === "home" || startPlace.id === "work" ? startPlace.id : "saved_place";
  return { ...coords, label: formatGridlyRouteOriginLabel(startPlace.label || startPlace.name || "Saved Place", source), source };
}

function getGridlyCurrentLocationStateCoordinate() {
  const candidates = [
    typeof userLocation !== "undefined" ? userLocation : null,
    typeof window !== "undefined" ? window.gridlyUserLocation : null,
    typeof window !== "undefined" ? window.__gridlyUserLocation : null,
    typeof window !== "undefined" ? window.gridlyCurrentLocation : null,
    typeof window !== "undefined" ? window.__gridlyCurrentLocation : null
  ];
  for (const candidate of candidates) {
    const coords = normalizeCoordinatePair(
      candidate?.lat ?? candidate?.latitude ?? candidate?.coords?.latitude,
      candidate?.lng ?? candidate?.lon ?? candidate?.longitude ?? candidate?.coords?.longitude
    );
    if (coords) return coords;
  }
  return null;
}

function getGridlyVisibleUserLocationDotCoordinate() {
  if (!userMarker || !map) return null;
  try {
    if (typeof map.hasLayer === "function" && !map.hasLayer(userMarker)) return null;
    const markerLatLng = typeof userMarker.getLatLng === "function" ? userMarker.getLatLng() : null;
    return normalizeCoordinatePair(markerLatLng?.lat, markerLatLng?.lng);
  } catch (_error) {
    return null;
  }
}

function getGridlyCurrentLocationRouteCoordinate() {
  return getGridlyVisibleUserLocationDotCoordinate() || getGridlyCurrentLocationStateCoordinate();
}

const GRIDLY_DESTINATION_AUTO_LOCATION_TIMEOUT_MS = 6000;
const GRIDLY_DESTINATION_AUTO_LOCATION_GEO_OPTIONS = Object.freeze({
  enableHighAccuracy: true,
  maximumAge: 60000
});
const GRIDLY_APP_LOCATION_READINESS_VERSION = "V257.9";
const GRIDLY_STARTUP_LOCATION_TIMING_AUDIT_VERSION = "V257.9A";
const GRIDLY_APP_LOCATION_STARTUP_PROMPT_SESSION_KEY = "gridlyAppLocationReadinessStartupPromptAttemptedV257_9";
let gridlyDestinationAutoLocationPromptAttempted = false;
let gridlyDestinationAutoLocationRequestInFlight = null;
let gridlyAppLocationReadinessRequestInFlight = null;
const gridlyAppLocationReadinessState = {
  startupLocationAttempted: false,
  startupLocationSucceeded: false,
  lastLocationRefreshReason: "",
  lastLocationFailureReason: "",
  lastStartupAttemptedAt: null,
  lastStartupSucceededAt: null,
  startupTimeoutMs: GRIDLY_DESTINATION_AUTO_LOCATION_TIMEOUT_MS,
  locationRequestStartedAt: null,
  locationRequestEndedAt: null,
  acquisitionDurationMs: 0,
  timedOut: false,
  enableHighAccuracy: GRIDLY_DESTINATION_AUTO_LOCATION_GEO_OPTIONS.enableHighAccuracy,
  maximumAge: GRIDLY_DESTINATION_AUTO_LOCATION_GEO_OPTIONS.maximumAge,
  lastSuccessfulLocationAt: null,
  lastSuccessfulAcquisitionDurationMs: 0,
  browserReportedErrorCode: "",
  browserReportedErrorMessage: "",
  startupAutoGeolocationDeferred: false
};
const gridlyDestinationCurrentLocationOriginState = {
  attemptedForDestinationSearch: false,
  succeededForDestinationSearch: false,
  failureReason: "",
  permissionState: "",
  coordinate: null,
  lastAttemptedAt: null,
  lastSucceededAt: null,
  fallbackUsed: false,
  fallbackSource: "",
  fallbackReason: ""
};

const gridlyDestinationLocationRecoveryState = {
  version: "V257.8A",
  fallbackRouteActive: false,
  fallbackOriginSource: "",
  destinationLabel: "",
  currentLocationArrivedAfterFallback: false,
  autoRefreshTriggered: false,
  routeRebuiltFromCurrentLocation: false,
  finalOriginSource: "",
  pendingRefresh: false,
  lastAutoRefreshReason: "",
  lastFallbackCreatedAt: null,
  lastCurrentLocationArrivedAt: null,
  lastAutoRefreshTriggeredAt: null,
  lastRouteRebuiltAt: null
};

async function getGridlyDestinationAutoLocationPermissionState() {
  if (typeof navigator === "undefined") return "navigator_unavailable";
  if (typeof navigator.geolocation === "undefined") return "geolocation_unavailable";
  if (gridlyCachedGeolocationPermissionStatus) return gridlyCachedGeolocationPermissionStatus;
  try {
    if (navigator.permissions?.query) {
      const status = await navigator.permissions.query({ name: "geolocation" });
      gridlyCachedGeolocationPermissionStatus = status?.state || null;
      return gridlyCachedGeolocationPermissionStatus || "unknown";
    }
  } catch (_error) {
    gridlyCachedGeolocationPermissionStatus = null;
  }
  return "unknown";
}

function getGridlyDestinationAutoLocationErrorReason(error) {
  const code = Number(error?.code);
  if (code === 1) return "permission_denied";
  if (code === 2) return "position_unavailable";
  if (code === 3) return "timeout";
  return String(error?.message || "location_unavailable").toLowerCase().replace(/[^a-z0-9_]+/g, "_") || "location_unavailable";
}

function gridlyAppLocationReadinessSessionPromptAttempted() {
  try {
    return window.sessionStorage?.getItem(GRIDLY_APP_LOCATION_STARTUP_PROMPT_SESSION_KEY) === "true";
  } catch (_error) {
    return false;
  }
}

function markGridlyAppLocationReadinessSessionPromptAttempted() {
  try {
    window.sessionStorage?.setItem(GRIDLY_APP_LOCATION_STARTUP_PROMPT_SESSION_KEY, "true");
  } catch (_error) {
    // Session storage is optional; the in-memory prompt guard still prevents repeated prompts this load.
  }
}

function formatGridlyStartupLocationTimingAuditTimestamp(value) {
  const timestamp = Number(value);
  if (!Number.isFinite(timestamp) || timestamp <= 0) return "";
  try {
    return new Date(timestamp).toISOString();
  } catch (_error) {
    return "";
  }
}

function syncGridlyAppLocationReadinessSuccess(coords, reason = "startup_location_refresh") {
  const normalizedCoords = normalizeCoordinatePair(coords?.lat, coords?.lng) || getGridlyCurrentLocationRouteCoordinate();
  gridlyAppLocationReadinessState.startupLocationSucceeded = Boolean(normalizedCoords);
  gridlyAppLocationReadinessState.lastLocationRefreshReason = reason;
  gridlyAppLocationReadinessState.lastLocationFailureReason = "";
  if (normalizedCoords) {
    const succeededAt = Date.now();
    gridlyAppLocationReadinessState.lastStartupSucceededAt = succeededAt;
    gridlyAppLocationReadinessState.lastSuccessfulLocationAt = succeededAt;
    gridlyDestinationCurrentLocationOriginState.permissionState = gridlyDestinationCurrentLocationOriginState.permissionState || gridlyCachedGeolocationPermissionStatus || "granted";
    gridlyDestinationCurrentLocationOriginState.succeededForDestinationSearch = true;
    gridlyDestinationCurrentLocationOriginState.failureReason = "";
    gridlyDestinationCurrentLocationOriginState.coordinate = { ...normalizedCoords };
    gridlyDestinationCurrentLocationOriginState.lastSucceededAt = Date.now();
  }
  return normalizedCoords;
}

async function requestGridlyAppLocationReadinessRefresh(reason = "startup_location_readiness") {
  const isStartupLocationReadinessRequest = String(reason || "") === "startup_location_readiness";
  if (isStartupLocationReadinessRequest) {
    gridlyAppLocationReadinessState.startupAutoGeolocationDeferred = true;
    gridlyGeoAuditState.startupAutoGeolocationDeferred = true;
  }
  const existingCoords = getGridlyCurrentLocationRouteCoordinate();
  if (existingCoords) {
    gridlyAppLocationReadinessState.startupLocationAttempted = true;
    gridlyAppLocationReadinessState.lastStartupAttemptedAt = Date.now();
    syncGridlyAppLocationReadinessSuccess(existingCoords, "existing_current_location");
    return { attempted: false, succeeded: true, fallbackReason: "", coords: existingCoords, permissionState: gridlyDestinationCurrentLocationOriginState.permissionState || gridlyCachedGeolocationPermissionStatus || "" };
  }
  if (gridlyAppLocationReadinessRequestInFlight) return gridlyAppLocationReadinessRequestInFlight;

  gridlyAppLocationReadinessRequestInFlight = (async () => {
    gridlyAppLocationReadinessState.startupLocationAttempted = true;
    gridlyAppLocationReadinessState.startupLocationSucceeded = false;
    gridlyAppLocationReadinessState.lastLocationRefreshReason = reason;
    gridlyAppLocationReadinessState.lastLocationFailureReason = "";
    gridlyAppLocationReadinessState.lastStartupAttemptedAt = Date.now();

    const permissionState = await getGridlyDestinationAutoLocationPermissionState();
    gridlyDestinationCurrentLocationOriginState.permissionState = permissionState || "unknown";
    if (["navigator_unavailable", "geolocation_unavailable"].includes(permissionState)) {
      gridlyAppLocationReadinessState.lastLocationFailureReason = permissionState;
      gridlyDestinationCurrentLocationOriginState.failureReason = permissionState;
      return { attempted: true, succeeded: false, fallbackReason: permissionState, permissionState };
    }
    if (permissionState === "denied") {
      gridlyAppLocationReadinessState.lastLocationFailureReason = "permission_denied";
      gridlyDestinationCurrentLocationOriginState.failureReason = "permission_denied";
      return { attempted: true, succeeded: false, fallbackReason: "permission_denied", permissionState };
    }
    if (isStartupLocationReadinessRequest) {
      const fallbackReason = "startup_auto_geolocation_deferred";
      gridlyAppLocationReadinessState.startupAutoGeolocationDeferred = true;
      gridlyGeoAuditState.startupAutoGeolocationDeferred = true;
      gridlyAppLocationReadinessState.lastLocationFailureReason = fallbackReason;
      gridlyDestinationCurrentLocationOriginState.failureReason = fallbackReason;
      recordGridlyGeolocationRequest("app_location_readiness_startup_deferred", { startupBlocked: true, startupDeferred: true });
      return { attempted: false, succeeded: false, fallbackReason, permissionState, startupAutoGeolocationDeferred: true };
    }

    if (permissionState !== "granted" && (gridlyDestinationAutoLocationPromptAttempted || gridlyAppLocationReadinessSessionPromptAttempted())) {
      const fallbackReason = "startup_prompt_already_attempted";
      gridlyAppLocationReadinessState.lastLocationFailureReason = fallbackReason;
      gridlyDestinationCurrentLocationOriginState.failureReason = fallbackReason;
      return { attempted: true, succeeded: false, fallbackReason, permissionState };
    }

    if (permissionState !== "granted") {
      markGridlyAppLocationReadinessSessionPromptAttempted();
    }

    const result = await requestGridlyDestinationAutoCurrentLocation({
      timeoutMs: GRIDLY_DESTINATION_AUTO_LOCATION_TIMEOUT_MS,
      allowPromptRetry: false,
      reason
    });
    if (result?.succeeded && result?.coords) {
      const coords = syncGridlyAppLocationReadinessSuccess(result.coords, reason);
      if (coords) return { ...result, coords, permissionState: "granted" };
    }
    const fallbackReason = result?.fallbackReason || gridlyDestinationCurrentLocationOriginState.failureReason || "location_unavailable";
    gridlyAppLocationReadinessState.lastLocationFailureReason = fallbackReason;
    return { ...(result || {}), attempted: true, succeeded: false, fallbackReason, permissionState };
  })().finally(() => {
    gridlyAppLocationReadinessRequestInFlight = null;
  });

  return gridlyAppLocationReadinessRequestInFlight;
}

function startGridlyAppLocationReadinessRefresh() {
  if (typeof window === "undefined") return false;
  window.setTimeout?.(() => {
    requestGridlyAppLocationReadinessRefresh("startup_location_readiness").catch(() => {
      gridlyAppLocationReadinessState.lastLocationFailureReason = "startup_location_refresh_failed";
    });
  }, 0);
  return true;
}

if (typeof document !== "undefined") {
  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", startGridlyAppLocationReadinessRefresh, { once: true });
  } else {
    startGridlyAppLocationReadinessRefresh();
  }
}

async function requestGridlyDestinationAutoCurrentLocation(options = {}) {
  const isStartupLocationReadinessRequest = String(options?.reason || "") === "startup_location_readiness";
  if (isStartupLocationReadinessRequest && options?.allowStartupAutoGeolocation !== true) {
    const permissionState = await getGridlyDestinationAutoLocationPermissionState();
    const fallbackReason = "startup_auto_geolocation_deferred";
    gridlyAppLocationReadinessState.startupAutoGeolocationDeferred = true;
    gridlyGeoAuditState.startupAutoGeolocationDeferred = true;
    gridlyDestinationCurrentLocationOriginState.permissionState = permissionState || "unknown";
    gridlyDestinationCurrentLocationOriginState.failureReason = fallbackReason;
    recordGridlyGeolocationRequest("destination_route_auto_current_location_startup_deferred", { startupBlocked: true, startupDeferred: true });
    return { attempted: false, succeeded: false, fallbackReason, permissionState, startupAutoGeolocationDeferred: true };
  }
  const existingCoords = getGridlyCurrentLocationRouteCoordinate();
  if (existingCoords) {
    gridlyDestinationCurrentLocationOriginState.succeededForDestinationSearch = true;
    gridlyDestinationCurrentLocationOriginState.failureReason = "";
    gridlyDestinationCurrentLocationOriginState.coordinate = existingCoords;
    gridlyDestinationCurrentLocationOriginState.lastSucceededAt = Date.now();
    return { attempted: false, succeeded: true, fallbackReason: "", coords: existingCoords };
  }

  if (gridlyDestinationAutoLocationRequestInFlight) return gridlyDestinationAutoLocationRequestInFlight;

  gridlyDestinationAutoLocationRequestInFlight = (async () => {
    const permissionState = await getGridlyDestinationAutoLocationPermissionState();
    gridlyDestinationCurrentLocationOriginState.permissionState = permissionState || "unknown";
    gridlyDestinationCurrentLocationOriginState.attemptedForDestinationSearch = true;
    gridlyDestinationCurrentLocationOriginState.succeededForDestinationSearch = false;
    gridlyDestinationCurrentLocationOriginState.failureReason = "";
    gridlyDestinationCurrentLocationOriginState.coordinate = null;
    gridlyDestinationCurrentLocationOriginState.lastAttemptedAt = Date.now();
    if (["navigator_unavailable", "geolocation_unavailable"].includes(permissionState)) {
      gridlyDestinationCurrentLocationOriginState.failureReason = permissionState;
      return { attempted: true, succeeded: false, fallbackReason: permissionState };
    }
    if (permissionState === "denied") {
      gridlyDestinationCurrentLocationOriginState.failureReason = "permission_denied";
      return { attempted: true, succeeded: false, fallbackReason: "permission_denied" };
    }
    if (permissionState !== "granted" && gridlyDestinationAutoLocationPromptAttempted && options?.allowPromptRetry !== true) {
      gridlyDestinationCurrentLocationOriginState.failureReason = "auto_location_prompt_already_attempted";
      return { attempted: true, succeeded: false, fallbackReason: "auto_location_prompt_already_attempted" };
    }

    gridlyDestinationAutoLocationPromptAttempted = permissionState !== "granted" || gridlyDestinationAutoLocationPromptAttempted;
    recordGridlyGeolocationRequest("destination_route_auto_current_location");

    return new Promise((resolve) => {
      let settled = false;
      const finish = (result) => {
        if (settled) return;
        settled = true;
        resolve(result);
      };
      const timeoutMs = Number(options?.timeoutMs || GRIDLY_DESTINATION_AUTO_LOCATION_TIMEOUT_MS);
      const locationRequestStartedAt = Date.now();
      const geolocationOptions = {
        enableHighAccuracy: GRIDLY_DESTINATION_AUTO_LOCATION_GEO_OPTIONS.enableHighAccuracy,
        timeout: timeoutMs,
        maximumAge: GRIDLY_DESTINATION_AUTO_LOCATION_GEO_OPTIONS.maximumAge
      };
      if (isStartupLocationReadinessRequest) {
        gridlyAppLocationReadinessState.startupTimeoutMs = timeoutMs;
        gridlyAppLocationReadinessState.locationRequestStartedAt = locationRequestStartedAt;
        gridlyAppLocationReadinessState.locationRequestEndedAt = null;
        gridlyAppLocationReadinessState.acquisitionDurationMs = 0;
        gridlyAppLocationReadinessState.timedOut = false;
        gridlyAppLocationReadinessState.enableHighAccuracy = geolocationOptions.enableHighAccuracy;
        gridlyAppLocationReadinessState.maximumAge = geolocationOptions.maximumAge;
        gridlyAppLocationReadinessState.browserReportedErrorCode = "";
        gridlyAppLocationReadinessState.browserReportedErrorMessage = "";
      }
      const timeoutId = window.setTimeout?.(() => {
        if (isStartupLocationReadinessRequest) {
          const timeoutEndedAt = Date.now();
          gridlyAppLocationReadinessState.locationRequestEndedAt = timeoutEndedAt;
          gridlyAppLocationReadinessState.acquisitionDurationMs = Math.max(0, timeoutEndedAt - locationRequestStartedAt);
          gridlyAppLocationReadinessState.timedOut = true;
        }
        gridlyDestinationCurrentLocationOriginState.failureReason = "timeout";
        finish({ attempted: true, succeeded: false, fallbackReason: "timeout" });
      }, timeoutMs + 250);

      navigator.geolocation.getCurrentPosition(
        (position) => {
          const locationRequestEndedAt = Date.now();
          const acquisitionDurationMs = Math.max(0, locationRequestEndedAt - locationRequestStartedAt);
          gridlyAppLocationReadinessState.lastSuccessfulLocationAt = locationRequestEndedAt;
          gridlyAppLocationReadinessState.lastSuccessfulAcquisitionDurationMs = acquisitionDurationMs;
          if (isStartupLocationReadinessRequest) {
            gridlyAppLocationReadinessState.locationRequestEndedAt = locationRequestEndedAt;
            gridlyAppLocationReadinessState.acquisitionDurationMs = acquisitionDurationMs;
            if (!settled) gridlyAppLocationReadinessState.timedOut = false;
          }
          if (settled) return;
          if (timeoutId) window.clearTimeout?.(timeoutId);
          const coords = getValidGridlyUserLocationCoordinates(position);
          if (!coords) {
            gridlyDestinationCurrentLocationOriginState.failureReason = "invalid_coordinates";
            finish({ attempted: true, succeeded: false, fallbackReason: "invalid_coordinates" });
            return;
          }
          gridlyCachedGeolocationPermissionStatus = "granted";
          gridlyDestinationCurrentLocationOriginState.permissionState = "granted";
          gridlyDestinationCurrentLocationOriginState.succeededForDestinationSearch = true;
          gridlyDestinationCurrentLocationOriginState.failureReason = "";
          gridlyDestinationCurrentLocationOriginState.coordinate = coords;
          gridlyDestinationCurrentLocationOriginState.lastSucceededAt = Date.now();
          setGridlyUserLocation({ ...coords, suppressRouteOriginRefresh: true });
          updateNearestContext();
          finish({ attempted: true, succeeded: true, fallbackReason: "", coords });
        },
        (error) => {
          const locationRequestEndedAt = Date.now();
          const acquisitionDurationMs = Math.max(0, locationRequestEndedAt - locationRequestStartedAt);
          const browserReportedErrorCode = error?.code ?? "";
          const browserReportedErrorMessage = String(error?.message || "");
          if (isStartupLocationReadinessRequest) {
            gridlyAppLocationReadinessState.locationRequestEndedAt = locationRequestEndedAt;
            gridlyAppLocationReadinessState.acquisitionDurationMs = acquisitionDurationMs;
            gridlyAppLocationReadinessState.browserReportedErrorCode = browserReportedErrorCode === "" ? "" : String(browserReportedErrorCode);
            gridlyAppLocationReadinessState.browserReportedErrorMessage = browserReportedErrorMessage;
            gridlyAppLocationReadinessState.timedOut = Number(error?.code) === 3 || gridlyAppLocationReadinessState.timedOut;
          }
          if (settled) return;
          if (timeoutId) window.clearTimeout?.(timeoutId);
          const fallbackReason = getGridlyDestinationAutoLocationErrorReason(error);
          if (fallbackReason === "permission_denied") gridlyCachedGeolocationPermissionStatus = "denied";
          gridlyDestinationCurrentLocationOriginState.permissionState = gridlyCachedGeolocationPermissionStatus || gridlyDestinationCurrentLocationOriginState.permissionState || "unknown";
          gridlyDestinationCurrentLocationOriginState.failureReason = fallbackReason;
          finish({ attempted: true, succeeded: false, fallbackReason });
        },
        geolocationOptions
      );
    });
  })().finally(() => {
    gridlyDestinationAutoLocationRequestInFlight = null;
  });

  return gridlyDestinationAutoLocationRequestInFlight;
}

function getGridlyCoordinateDistanceMiles(a, b) {
  const first = normalizeCoordinatePair(a?.lat, a?.lng);
  const second = normalizeCoordinatePair(b?.lat, b?.lng);
  if (!first || !second) return null;
  if (typeof getDistanceMiles === "function") return getDistanceMiles(first.lat, first.lng, second.lat, second.lng);
  return null;
}

function getGridlyRouteGeometryCoordinateAt(preview = getGridlyDestinationRoutePreviewState(), index = 0) {
  if (!Array.isArray(preview?.geometry) || !preview.geometry.length) return null;
  const normalizedIndex = index < 0 ? preview.geometry.length + index : index;
  const point = preview.geometry[normalizedIndex];
  if (!point) return null;
  if (typeof normalizeGridlyDestinationRoutePoint === "function") return normalizeGridlyDestinationRoutePoint(point);
  if (Array.isArray(point)) return normalizeCoordinatePair(point[0], point[1]);
  return normalizeCoordinatePair(point?.lat ?? point?.latitude, point?.lng ?? point?.lon ?? point?.longitude);
}

function getGridlyFirstRouteGeometryCoordinate(preview = getGridlyDestinationRoutePreviewState()) {
  return getGridlyRouteGeometryCoordinateAt(preview, 0);
}

function getGridlyLastRouteGeometryCoordinate(preview = getGridlyDestinationRoutePreviewState()) {
  return getGridlyRouteGeometryCoordinateAt(preview, -1);
}

function gridlyCoordinatesNearlyMatch(a, b, maxMiles = 0.15) {
  const distanceMiles = getGridlyCoordinateDistanceMiles(a, b);
  return distanceMiles !== null && distanceMiles <= maxMiles;
}

function getGridlyDestinationLocationRecoveryDestinationLabel(destination = null, preview = null) {
  return gridlyFriendlyPlaceLabel(
    destination?.label
      || destination?.title
      || destination?.displayName
      || destination?.address
      || destination?.name
      || preview?.destination?.label
      || "Destination",
    "Destination"
  );
}

function isGridlyDestinationFallbackOrigin(origin = null) {
  const originSource = String(origin?.source || "").toLowerCase();
  return Boolean(originSource && originSource !== "current_location");
}

function getGridlyDestinationLocationRecoveryContext() {
  const preview = typeof getGridlyDestinationRoutePreviewState === "function" ? getGridlyDestinationRoutePreviewState() : (window.GridlyDestinationRoutePreview || {});
  const searchState = typeof ensureGridlySearchState === "function" ? ensureGridlySearchState() : null;
  const selectedDestination = typeof normalizeGridlySearchResult === "function"
    ? normalizeGridlySearchResult(searchState?.selectedDestination)
    : searchState?.selectedDestination;
  const destination = selectedDestination || preview?.destination || null;
  const destinationSearchActive = Boolean(selectedDestination || preview?.destination || preview?.active);
  const origin = preview?.source || null;
  const fallbackOriginSource = isGridlyDestinationFallbackOrigin(origin) ? String(origin.source || "") : "";
  const fallbackRouteActive = Boolean(
    destinationSearchActive
    && preview?.active
    && fallbackOriginSource
    && (origin?.fallbackUsed || preview?.autoLocationFallbackUsed || gridlyDestinationCurrentLocationOriginState.fallbackUsed || origin?.routeOriginPipeline === "v257_4_fallback")
  );
  return {
    preview,
    searchState,
    selectedDestination,
    destination,
    destinationSearchActive,
    origin,
    fallbackRouteActive,
    fallbackOriginSource,
    destinationLabel: getGridlyDestinationLocationRecoveryDestinationLabel(destination, preview)
  };
}

function recordGridlyDestinationLocationRecoveryPreviewState(origin = null, destination = null, preview = null, options = {}) {
  const destinationLabel = getGridlyDestinationLocationRecoveryDestinationLabel(destination, preview);
  const originSource = String(origin?.source || "");
  const fallbackActive = Boolean(origin && isGridlyDestinationFallbackOrigin(origin) && (origin.fallbackUsed || origin.routeOriginPipeline === "v257_4_fallback" || preview?.autoLocationFallbackUsed));
  gridlyDestinationLocationRecoveryState.destinationLabel = destinationLabel;
  gridlyDestinationLocationRecoveryState.finalOriginSource = originSource;

  if (fallbackActive) {
    gridlyDestinationLocationRecoveryState.fallbackRouteActive = true;
    gridlyDestinationLocationRecoveryState.fallbackOriginSource = originSource;
    gridlyDestinationLocationRecoveryState.routeRebuiltFromCurrentLocation = false;
    gridlyDestinationLocationRecoveryState.lastFallbackCreatedAt = Date.now();
    return;
  }

  if (originSource === "current_location") {
    gridlyDestinationLocationRecoveryState.fallbackRouteActive = false;
    if (gridlyDestinationLocationRecoveryState.autoRefreshTriggered || options?.originRefresh === true) {
      gridlyDestinationLocationRecoveryState.routeRebuiltFromCurrentLocation = true;
      gridlyDestinationLocationRecoveryState.lastRouteRebuiltAt = Date.now();
    }
  }
}

function maybeTriggerGridlyDestinationLocationRecovery(reason = "current_location_updated") {
  if (typeof buildGridlyDestinationRoutePreview !== "function") return false;
  const currentLocationCoordinate = getGridlyCurrentLocationRouteCoordinate() || gridlyDestinationCurrentLocationOriginState.coordinate || null;
  if (!currentLocationCoordinate) return false;

  const context = getGridlyDestinationLocationRecoveryContext();
  if (!context.destinationSearchActive || !context.fallbackRouteActive || !context.destination) return false;
  if (gridlyDestinationLocationRecoveryState.pendingRefresh) return false;

  gridlyDestinationLocationRecoveryState.currentLocationArrivedAfterFallback = true;
  gridlyDestinationLocationRecoveryState.autoRefreshTriggered = true;
  gridlyDestinationLocationRecoveryState.pendingRefresh = true;
  gridlyDestinationLocationRecoveryState.lastAutoRefreshReason = reason;
  gridlyDestinationLocationRecoveryState.lastCurrentLocationArrivedAt = Date.now();
  gridlyDestinationLocationRecoveryState.lastAutoRefreshTriggeredAt = Date.now();
  gridlyDestinationLocationRecoveryState.destinationLabel = context.destinationLabel;
  gridlyDestinationLocationRecoveryState.fallbackOriginSource = context.fallbackOriginSource;

  window.setTimeout?.(async () => {
    try {
      const refreshedPreview = await buildGridlyDestinationRoutePreview({ reason, originRefresh: true, locationRecovery: true });
      const refreshedOriginSource = String(refreshedPreview?.source?.source || "");
      gridlyDestinationLocationRecoveryState.finalOriginSource = refreshedOriginSource;
      gridlyDestinationLocationRecoveryState.routeRebuiltFromCurrentLocation = refreshedOriginSource === "current_location";
      if (gridlyDestinationLocationRecoveryState.routeRebuiltFromCurrentLocation) {
        gridlyDestinationLocationRecoveryState.fallbackRouteActive = false;
        gridlyDestinationLocationRecoveryState.lastRouteRebuiltAt = Date.now();
      }
    } finally {
      gridlyDestinationLocationRecoveryState.pendingRefresh = false;
    }
  }, 0);

  return true;
}

function scheduleGridlyDestinationRoutePreviewOriginRefresh(reason = "current_location_updated") {
  if (typeof buildGridlyDestinationRoutePreview !== "function") return false;
  const preview = typeof getGridlyDestinationRoutePreviewState === "function" ? getGridlyDestinationRoutePreviewState() : (window.GridlyDestinationRoutePreview || {});
  const searchState = typeof ensureGridlySearchState === "function" ? ensureGridlySearchState() : null;
  const selectedDestination = typeof normalizeGridlySearchResult === "function"
    ? normalizeGridlySearchResult(searchState?.selectedDestination)
    : searchState?.selectedDestination;
  if (!preview?.active && !selectedDestination) return false;
  if (maybeTriggerGridlyDestinationLocationRecovery(reason)) return true;
  window.__gridlyDestinationRouteOriginRefreshReason = reason;
  window.setTimeout?.(() => buildGridlyDestinationRoutePreview({ reason, originRefresh: true }), 0);
  return true;
}

function getGridlyDestinationRouteOrigin(options = {}) {
  const destinationCoords = normalizeCoordinatePair(options?.destination?.lat, options?.destination?.lng);
  const skippedSources = [];
  const savedState = typeof getSavedPlacesState === "function" ? getSavedPlacesState() : {};
  const savedHome = savedState?.home || null;
  const savedWork = savedState?.work || null;
  const includeRouteWatchStart = options?.includeRouteWatchStart === true || options?.routeOwnership === "route_watch";
  const selectedStart = includeRouteWatchStart ? getGridlySelectedRouteStartOriginCandidate() : null;
  const mapCenter = typeof map?.getCenter === "function" ? map.getCenter() : null;
  const centerCoords = normalizeCoordinatePair(mapCenter?.lat ?? defaultCenter[0], mapCenter?.lng ?? defaultCenter[1]);
  const destinationSavedPlaceType = String(
    options?.destination?.savedPlaceType
      || options?.destination?.raw?.savedPlaceType
      || options?.destination?.providerId
      || options?.destination?.id
      || ""
  ).toLowerCase();
  const savedPlaceDestinationSelected = ["home", "work"].includes(destinationSavedPlaceType)
    || options?.destination?.provider === "saved_place"
    || options?.destination?.raw?.savedPlace === true;
  const savedHomeCandidate = { coords: normalizeCoordinatePair(savedHome?.lat, savedHome?.lng), label: savedHome?.label || savedHome?.name || "Home", source: "home", routeOriginOwner: "destination_search", routeOriginPipeline: "v257_4_fallback", fallbackReason: "Current Location is unavailable; using Home." };
  const savedWorkCandidate = { coords: normalizeCoordinatePair(savedWork?.lat, savedWork?.lng), label: savedWork?.label || savedWork?.name || "Work", source: "work", routeOriginOwner: "destination_search", routeOriginPipeline: "v257_4_fallback", fallbackReason: "Current Location is unavailable; using Work." };
  const mapCenterCandidate = { coords: centerCoords, label: "Map Center", source: "map_center", routeOriginOwner: "destination_search", routeOriginPipeline: "v257_4_fallback", fallbackReason: "Current Location is unavailable; using Map Center." };
  const savedFallbackCandidates = savedPlaceDestinationSelected
    ? [mapCenterCandidate, savedHomeCandidate, savedWorkCandidate]
    : [savedHomeCandidate, savedWorkCandidate, mapCenterCandidate];

  const currentLocationRouteCoords = getGridlyCurrentLocationRouteCoordinate();
  const candidates = [
    { coords: currentLocationRouteCoords, label: "Current Location", source: "current_location", routeOriginOwner: "destination_search", routeOriginPipeline: "current_location", fallbackReason: "Current Location is available." },
    selectedStart ? { coords: selectedStart, label: selectedStart.label, source: selectedStart.source, routeOriginOwner: "route_watch", routeOriginPipeline: "route_watch_start", routeWatchOrigin: true, fallbackReason: "Current Location is unavailable; using your selected Route Watch start place." } : null,
    ...savedFallbackCandidates
  ].filter(Boolean);

  for (const candidate of candidates) {
    const coords = normalizeCoordinatePair(candidate.coords?.lat, candidate.coords?.lng);
    if (!coords) continue;
    const normalizedCandidate = {
      ...coords,
      label: formatGridlyRouteOriginLabel(candidate.label, candidate.source),
      source: candidate.source,
      routeOriginOwner: candidate.routeOriginOwner || "destination_search",
      routeOriginPipeline: candidate.routeOriginPipeline || (candidate.source === "current_location" ? "current_location" : "v257_4_fallback"),
      routeWatchOrigin: candidate.routeWatchOrigin === true,
      fallbackUsed: candidate.source !== "current_location",
      fallbackReason: candidate.source === "current_location" ? "" : candidate.fallbackReason
    };
    if (destinationCoords && gridlyRouteOriginCoordinatesMatchDestination(normalizedCandidate, destinationCoords) && options?.allowSameDestination !== true) {
      skippedSources.push(normalizedCandidate.label);
      continue;
    }
    if (skippedSources.length) {
      normalizedCandidate.fallbackUsed = normalizedCandidate.source !== "current_location";
      normalizedCandidate.fallbackReason = `${normalizedCandidate.fallbackReason || "Using another available route origin."} Skipped ${skippedSources.join(", ")} because it matches the destination.`;
    }
    return normalizedCandidate;
  }
  return null;
}

function drawGridlyDestinationRoutePreviewLine(latLngs = []) {
  const leaflet = window.L;
  if (!map || !Array.isArray(latLngs) || latLngs.length < 2 || typeof leaflet?.polyline !== "function") return null;
  if (!destinationRoutePreviewLayer && typeof leaflet?.layerGroup === "function") destinationRoutePreviewLayer = leaflet.layerGroup().addTo(map);
  if (!destinationRoutePreviewLayer) return null;
  destinationRoutePreviewLayer.clearLayers();
  const halo = leaflet.polyline(latLngs, {
    pane: "routePane",
    color: "#e8fbff",
    weight: 18,
    opacity: 0.12,
    lineCap: "round",
    lineJoin: "round",
    interactive: false,
    className: "gridly-route-signature-halo gridly-destination-route-hero-halo"
  });
  const shoulder = leaflet.polyline(latLngs, {
    pane: "routePane",
    color: "#0b5f92",
    weight: 11,
    opacity: 0.46,
    lineCap: "round",
    lineJoin: "round",
    interactive: false,
    className: "gridly-route-signature-shoulder gridly-destination-route-hero-shoulder"
  });
  const core = leaflet.polyline(latLngs, {
    pane: "routePane",
    color: "#8ff1ff",
    weight: 6,
    opacity: 0.9,
    lineCap: "round",
    lineJoin: "round",
    interactive: false,
    className: "gridly-route-signature-core gridly-destination-route-hero-core"
  });
  destinationRoutePreviewLayer.addLayer(halo);
  destinationRoutePreviewLayer.addLayer(shoulder);
  destinationRoutePreviewLayer.addLayer(core);
  return destinationRoutePreviewLayer;
}

async function buildGridlyDestinationRoutePreview(options = {}) {
  const state = ensureGridlySearchState();
  const destination = normalizeGridlySearchResult(state?.selectedDestination);
  clearGridlyDestinationRoutePreview({ silent: true, syncCard: false, preservePerformanceAudit: true });
  const flowStartedAt = Number.isFinite(Number(gridlyDestinationPerformanceAuditState.destinationFlowStartedAt))
    ? Number(gridlyDestinationPerformanceAuditState.destinationFlowStartedAt)
    : getGridlyDestinationPerfNow();
  const routePreviewStartedAt = getGridlyDestinationPerfNow();
  gridlyDestinationPerformanceAuditState.routePreviewRequestStartedAt = routePreviewStartedAt;
  gridlyDestinationPerformanceAuditState.routePreviewRequestEndedAt = null;
  gridlyDestinationPerformanceAuditState.routePreviewStatus = "preparing";
  gridlyDestinationPerformanceAuditState.lastUpdatedAt = Date.now();
  const preview = getGridlyDestinationRoutePreviewState();
  const requestId = Number(preview.requestId || 0) + 1;
  preview.requestId = requestId;
  preview.destination = destination ? {
    label: destination.title || destination.displayName || destination.address || "Destination",
    lat: destination.lat,
    lng: destination.lng,
    id: destination.id || null
  } : null;

  if (!destination || !Number.isFinite(destination.lat) || !Number.isFinite(destination.lng)) {
    preview.status = destination ? "unavailable" : "idle";
    preview.error = destination ? "invalid_destination" : "";
    window.GridlyDestinationRoutePreview = preview;
    gridlyDestinationPerformanceAuditState.routePreviewStatus = preview.status;
    gridlyDestinationPerformanceAuditState.routePreviewRequestEndedAt = getGridlyDestinationPerfNow();
    setGridlyDestinationPerformanceTiming("totalDestinationRouteMs", gridlyDestinationPerformanceAuditState.routePreviewRequestEndedAt - flowStartedAt);
    addGridlyDestinationPerformanceNote(preview.error || "destination route preview did not start");
    syncMobileDestinationCommandCard();
    return preview;
  }

  gridlyDestinationCurrentLocationOriginState.fallbackUsed = false;
  gridlyDestinationCurrentLocationOriginState.fallbackSource = "";
  gridlyDestinationCurrentLocationOriginState.fallbackReason = "";
  let autoLocationResult = { attempted: false, succeeded: false, fallbackReason: "" };
  if (!getGridlyCurrentLocationRouteCoordinate()) {
    autoLocationResult = await requestGridlyDestinationAutoCurrentLocation({ timeoutMs: GRIDLY_DESTINATION_AUTO_LOCATION_TIMEOUT_MS, allowPromptRetry: false });
    const latestAfterLocationAttempt = getGridlyDestinationRoutePreviewState();
    if (latestAfterLocationAttempt.requestId !== requestId) {
      addGridlyDestinationPerformanceNote("stale destination route preview ignored after auto location attempt");
      return latestAfterLocationAttempt;
    }
  }

  preview.autoLocationAttempted = Boolean(autoLocationResult.attempted);
  preview.autoLocationSucceeded = Boolean(autoLocationResult.succeeded && getGridlyCurrentLocationRouteCoordinate());
  preview.autoLocationFallbackUsed = Boolean(autoLocationResult.attempted && !preview.autoLocationSucceeded);
  preview.autoLocationFallbackReason = preview.autoLocationFallbackUsed ? (autoLocationResult.fallbackReason || "location_unavailable") : "";

  const origin = getGridlyDestinationRouteOrigin({ destination, allowSameDestination: isGridlySavedPlaceDestination(destination) });
  if (origin && preview.autoLocationAttempted && origin.source !== "current_location") {
    preview.autoLocationFallbackUsed = true;
    preview.autoLocationFallbackReason = preview.autoLocationFallbackReason || origin.fallbackReason || `using_${origin.source || "fallback_origin"}`;
  }
  if (origin && origin.source === "current_location") {
    preview.autoLocationSucceeded = Boolean(preview.autoLocationAttempted || autoLocationResult.succeeded);
    preview.autoLocationFallbackUsed = false;
    preview.autoLocationFallbackReason = "";
  }
  gridlyDestinationCurrentLocationOriginState.fallbackUsed = Boolean(origin && origin.source !== "current_location");
  gridlyDestinationCurrentLocationOriginState.fallbackSource = gridlyDestinationCurrentLocationOriginState.fallbackUsed ? String(origin?.source || "") : "";
  gridlyDestinationCurrentLocationOriginState.fallbackReason = gridlyDestinationCurrentLocationOriginState.fallbackUsed
    ? (preview.autoLocationFallbackReason || origin?.fallbackReason || autoLocationResult.fallbackReason || "current_location_unavailable")
    : "";
  recordGridlyDestinationLocationRecoveryPreviewState(origin, destination, preview, options);

  if (!origin) {
    preview.status = "unavailable";
    preview.error = "origin_unavailable";
    window.GridlyDestinationRoutePreview = preview;
    gridlyDestinationPerformanceAuditState.routePreviewStatus = preview.status;
    gridlyDestinationPerformanceAuditState.routePreviewRequestEndedAt = getGridlyDestinationPerfNow();
    setGridlyDestinationPerformanceTiming("totalDestinationRouteMs", gridlyDestinationPerformanceAuditState.routePreviewRequestEndedAt - flowStartedAt);
    addGridlyDestinationPerformanceNote(preview.error || "destination route origin unavailable");
    syncMobileDestinationCommandCard();
    return preview;
  }

  const destinationLabel = destination.title || destination.displayName || destination.address || "Destination";
  preview.routeRelationLineText = getGridlyRouteRelationLineText(origin.label, destinationLabel);
  syncGridlyDestinationPreviewRouteCard(origin, { ...destination, label: destinationLabel });
  const samePlaceGuard = getGridlySavedPlaceRouteGuard(destination, origin);
  if (samePlaceGuard.active) {
    destinationRoutePreviewLayer?.clearLayers?.();
    preview.active = true;
    preview.status = "guarded";
    preview.source = origin;
    preview.geometry = [];
    preview.distanceMeters = null;
    preview.distanceMiles = null;
    preview.durationSeconds = null;
    preview.etaMinutes = null;
    preview.error = samePlaceGuard.reason;
    preview.routeLayer = null;
    preview.sameSavedPlaceRouteGuardActive = true;
    preview.sameSavedPlaceRouteGuardMessage = samePlaceGuard.message;
    window.GridlyDestinationRoutePreview = preview;
    gridlyDestinationPerformanceAuditState.routePreviewStatus = preview.status;
    gridlyDestinationPerformanceAuditState.routePreviewRequestEndedAt = getGridlyDestinationPerfNow();
    setGridlyDestinationPerformanceTiming("totalDestinationRouteMs", gridlyDestinationPerformanceAuditState.routePreviewRequestEndedAt - flowStartedAt);
    addGridlyDestinationPerformanceNote(samePlaceGuard.reason);
    setConfirmation(samePlaceGuard.message, "error");
    syncMobileDestinationCommandCard();
    return preview;
  }

  preview.sameSavedPlaceRouteGuardActive = false;
  preview.sameSavedPlaceRouteGuardMessage = "";
  preview.active = true;
  preview.status = "loading";
  gridlyDestinationPerformanceAuditState.routePreviewStatus = "loading";
  preview.source = origin;
  preview.error = "";
  window.GridlyDestinationRoutePreview = preview;
  syncMobileDestinationCommandCard();
  applyGridlyDestinationVisibilityOffset(destination, { reason: "destination-preview-loading" });

  const routeRequestStartedAt = getGridlyDestinationPerfNow();
  const routeData = await fetchRoadRoutePreviewData([origin.lat, origin.lng], [destination.lat, destination.lng], { auditSource: "destination_route_preview" });
  setGridlyDestinationPerformanceTiming("routeRequestMs", getGridlyDestinationPerfNow() - routeRequestStartedAt);
  const latestPreview = getGridlyDestinationRoutePreviewState();
  if (latestPreview.requestId !== requestId) {
    addGridlyDestinationPerformanceNote("stale destination route preview request ignored");
    return latestPreview;
  }

  if (!routeData?.geometry?.length || routeData.geometry.length < 2) {
    destinationRoutePreviewLayer?.clearLayers?.();
    latestPreview.active = true;
    latestPreview.status = "unavailable";
    latestPreview.geometry = [];
    latestPreview.distanceMeters = null;
    latestPreview.distanceMiles = null;
    latestPreview.durationSeconds = null;
    latestPreview.etaMinutes = null;
    latestPreview.error = "route_unavailable";
    latestPreview.routeLayer = null;
    window.GridlyDestinationRoutePreview = latestPreview;
    gridlyDestinationPerformanceAuditState.routePreviewStatus = latestPreview.status;
    gridlyDestinationPerformanceAuditState.routePreviewRequestEndedAt = getGridlyDestinationPerfNow();
    setGridlyDestinationPerformanceTiming("totalDestinationRouteMs", gridlyDestinationPerformanceAuditState.routePreviewRequestEndedAt - flowStartedAt);
    addGridlyDestinationPerformanceNote(latestPreview.error || "route preview unavailable");
    syncMobileDestinationCommandCard();
    return latestPreview;
  }

  const renderStartedAt = getGridlyDestinationPerfNow();
  const renderedLayer = drawGridlyDestinationRoutePreviewLine(routeData.geometry);
  setGridlyDestinationPerformanceTiming("renderMs", getGridlyDestinationPerfNow() - renderStartedAt);
  latestPreview.active = true;
  latestPreview.status = renderedLayer ? "ready" : "unavailable";
  latestPreview.routeLayer = renderedLayer;
  latestPreview.geometry = routeData.geometry;
  latestPreview.distanceMeters = routeData.distanceMeters;
  latestPreview.distanceMiles = routeData.distanceMiles;
  latestPreview.durationSeconds = routeData.durationSeconds;
  latestPreview.etaMinutes = routeData.etaMinutes;
  latestPreview.routeProvider = routeData.provider || "osrm";
  latestPreview.error = renderedLayer ? "" : "render_unavailable";
  recordGridlyDestinationLocationRecoveryPreviewState(latestPreview.source, destination, latestPreview, options);
  gridlyDestinationPerformanceAuditState.routePreviewStatus = latestPreview.status;
  gridlyDestinationPerformanceAuditState.routeGeometryPointCount = Array.isArray(latestPreview.geometry) ? latestPreview.geometry.length : 0;
  if (!renderedLayer) addGridlyDestinationPerformanceNote(latestPreview.error);
  window.GridlyDestinationRoutePreview = latestPreview;
  if (latestPreview.status === "ready") primeGridlyDestinationRouteImpactCache();
  syncMobileDestinationCommandCard();
  gridlyDestinationPerformanceAuditState.routePreviewRequestEndedAt = getGridlyDestinationPerfNow();
  setGridlyDestinationPerformanceTiming("totalDestinationRouteMs", gridlyDestinationPerformanceAuditState.routePreviewRequestEndedAt - flowStartedAt);
  return latestPreview;
}

window.gridlyDestinationRoutePreviewDebug = function gridlyDestinationRoutePreviewDebug() {
  const preview = getGridlyDestinationRoutePreviewState();
  return {
    active: Boolean(preview.active),
    status: preview.status,
    source: preview.source,
    destination: preview.destination,
    distanceMiles: preview.distanceMiles,
    etaMinutes: preview.etaMinutes,
    geometryPointCount: Array.isArray(preview.geometry) ? preview.geometry.length : 0,
    layerOwnsRenderedRoute: Boolean(destinationRoutePreviewLayer && preview.routeLayer === destinationRoutePreviewLayer),
    routeWatchLayerUntouched: Boolean(savedRouteLayer && destinationRoutePreviewLayer !== savedRouteLayer),
    routeProvider: preview.routeProvider,
    error: preview.error
  };
};

function gridlyCountRouteLayerVertices(layer) {
  const countLatLngs = (value) => {
    if (!Array.isArray(value)) return 0;
    return value.reduce((count, item) => {
      if (Array.isArray(item)) return count + countLatLngs(item);
      const lat = Number(item?.lat ?? item?.[0]);
      const lng = Number(item?.lng ?? item?.[1]);
      return count + (Number.isFinite(lat) && Number.isFinite(lng) ? 1 : 0);
    }, 0);
  };
  if (!layer) return 0;
  try {
    if (typeof layer.getLatLngs === "function") return countLatLngs(layer.getLatLngs());
    if (typeof layer.getLayers === "function") {
      return layer.getLayers().reduce((count, childLayer) => count + gridlyCountRouteLayerVertices(childLayer), 0);
    }
  } catch (_error) {
    return 0;
  }
  return 0;
}

function gridlyBuildDestinationVsRouteWatchGeometryObservationAudit() {
  const preview = getGridlyDestinationRoutePreviewState();
  const destinationGeometryCount = Array.isArray(preview.geometry) ? preview.geometry.length : 0;
  const destinationLayerVertexCount = gridlyCountRouteLayerVertices(destinationRoutePreviewLayer);
  const destinationRouteVertexCount = Math.max(destinationGeometryCount, destinationLayerVertexCount);
  const routeWatchRouteLatLngs = typeof getRoutePolylineLatLngs === "function" ? getRoutePolylineLatLngs() : [];
  const routeWatchLayerVertexCount = gridlyCountRouteLayerVertices(window.__gridlyRoutePreviewLayer);
  const routeWatchGroupVertexCount = gridlyCountRouteLayerVertices(routePreviewCorridorLayer);
  const routeWatchSnapshot = typeof getGridlyAuditRouteRenderSnapshot === "function" ? getGridlyAuditRouteRenderSnapshot() : {};
  const routeWatchActive = Boolean(routeWatchActivated || window.__gridlyRouteWatchActive);
  const routeWatchVertexCount = Math.max(
    Array.isArray(routeWatchRouteLatLngs) ? routeWatchRouteLatLngs.length : 0,
    routeWatchLayerVertexCount,
    routeWatchGroupVertexCount,
    Number(routeWatchSnapshot?.routeGeometryPointCount || 0),
    Number(routePreviewPolylinePointCount || 0),
    Number(lastRouteGeometryPointCount || 0)
  );
  const v296Audit = typeof window.gridlyRouteWatchGeometryRuntimeShadowAudit === "function"
    ? window.gridlyRouteWatchGeometryRuntimeShadowAudit()
    : null;
  const v296Candidates = Array.isArray(v296Audit?.candidates) ? v296Audit.candidates : [];
  const destinationLabel = String(preview.destination?.label || preview.destination?.name || preview.destination?.displayName || "");
  const destinationRouteObservedByV296 = v296Candidates.some((candidate) => /destination|search|preview|walmart/i.test(String(candidate?.routeIdentifier || candidate?.routeName || "")));
  const routeWatchObservedByV296 = Boolean(v296Audit && Number(v296Audit.evaluatedCandidates || 0) > 0 && !destinationRouteObservedByV296);
  const destinationRouteHasGeometry = destinationRouteVertexCount >= 2;
  const routeWatchHasGeometry = routeWatchVertexCount >= 2;
  const v296Available = typeof window.gridlyRecordRouteWatchGeometryRuntimeShadowCandidate === "function"
    && typeof window.gridlyRouteWatchGeometryRuntimeShadowAudit === "function";
  const activeRouteContext = typeof getActiveRouteContext === "function" ? getActiveRouteContext() : null;
  const destinationRouteActive = Boolean(preview.active || preview.status === "ready");
  const routeOwnershipState = activeRouteContext?.routeContextAvailable
    ? gridlyRouteWatchOwnershipFromActiveContext(activeRouteContext)
    : routeWatchActive
      ? "route_watch_monitored_route"
      : destinationRouteActive
        ? "searched_destination_route"
        : "no_active_route";
  const observationGapDetected = Boolean(destinationRouteHasGeometry && !routeWatchActive && !destinationRouteObservedByV296);
  const observationGapReason = observationGapDetected
    ? "searched_destination_route_is_separate_from_saved_route_watch_observation"
    : routeWatchHasGeometry && routeWatchActive && !routeWatchObservedByV296
      ? "saved_route_watch_geometry_present_but_no_v296_relevance_candidates_have_run_yet"
      : "no_runtime_observation_gap_detected";
  return {
    available: true,
    auditOnly: true,
    productionBehaviorChanged: false,
    safeForProductionWiring: false,
    routeWatchPathDetected: Boolean(typeof startInlineRouteWatch === "function" && typeof renderRoutePreviewLine === "function" && typeof getRouteHazardAssessment === "function" && typeof isIncidentRouteRelevant === "function"),
    destinationRoutePathDetected: Boolean(typeof buildGridlyDestinationRoutePreview === "function" && typeof drawGridlyDestinationRoutePreviewLine === "function" && destinationRoutePreviewLayer !== savedRouteLayer),
    sharedGeometryHelpersDetected: Boolean(typeof fetchRoadRoutePreviewData === "function" && typeof getGridlyAuditRouteRenderSnapshot === "function"),
    sharedRelevanceHelpersDetected: false,
    destinationRouteHasGeometry,
    destinationRouteVertexCount,
    routeWatchActive,
    destinationRouteActive,
    activeRouteContext,
    sharedOwnershipSource: "getActiveRouteContext",
    routeOwnershipState,
    routeWatchHasGeometry,
    routeWatchVertexCount,
    destinationRouteObservedByV296,
    routeWatchObservedByV296,
    observationGapDetected,
    observationGapReason,
    recommendedObservationArchitecture: "Keep Route Watch and destination route observation separate in V298; optionally extend audit-only V296-style observation to destination routes with a distinct recorder and schema, but do not wire production scoring or merge user-facing behavior.",
    checks: {
      searchedDestinationRoute: {
        active: Boolean(preview.active),
        ready: preview.status === "ready",
        status: preview.status,
        walmartStyleDestinationDetected: /walmart/i.test(destinationLabel),
        destinationLabel,
        routeProvider: preview.routeProvider || "",
        hasGeometry: destinationRouteHasGeometry,
        vertexCount: destinationRouteVertexCount,
        layerPresent: Boolean(destinationRoutePreviewLayer),
        layerOwnsRenderedRoute: Boolean(destinationRoutePreviewLayer && preview.routeLayer === destinationRoutePreviewLayer)
      },
      savedHomeWorkRouteWatchRoute: {
        active: routeWatchActive,
        selectedRouteId: window.__gridlySelectedRouteId || "",
        originLabel: activeRouteOriginLabel || "",
        destinationLabel: activeRouteDestinationLabel || "",
        homeToWorkSelectorState: /home/i.test(String(activeRouteOriginLabel || "")) && /work/i.test(String(activeRouteDestinationLabel || "")),
        hasGeometry: routeWatchHasGeometry,
        vertexCount: routeWatchVertexCount
      },
      activeRoutePreviewLayerState: {
        routeWatchLayerPresent: Boolean(window.__gridlyRoutePreviewLayer || routePreviewCorridorLayer),
        routeWatchLayerVertexCount: Math.max(routeWatchLayerVertexCount, routeWatchGroupVertexCount),
        destinationLayerPresent: Boolean(destinationRoutePreviewLayer),
        destinationLayerVertexCount,
        layersAreSeparate: Boolean(destinationRoutePreviewLayer && destinationRoutePreviewLayer !== savedRouteLayer && destinationRoutePreviewLayer !== window.__gridlyRoutePreviewLayer)
      },
      osrmSuccessFallbackState: {
        routeWatchOsrmSuccess: Boolean(osrmRouteSuccess),
        routeWatchGeometrySource: routeGeometrySource || "fallback",
        destinationProvider: preview.routeProvider || "",
        destinationOsrmSuccess: Boolean(preview.status === "ready" && preview.routeProvider === "osrm" && destinationRouteHasGeometry)
      },
      routePolylineAvailability: {
        routeWatchPolylineAvailable: routeWatchHasGeometry,
        routeWatchPolylineVertexCount: routeWatchVertexCount,
        destinationPolylineAvailable: destinationRouteHasGeometry,
        destinationPolylineVertexCount: destinationRouteVertexCount
      },
      v296ObservationScope: {
        helperAvailable: v296Available,
        evaluatedCandidates: Number(v296Audit?.evaluatedCandidates || 0),
        observesRouteWatchRelevancePath: routeWatchObservedByV296 || v296Available,
        observesDestinationPreviewPath: destinationRouteObservedByV296,
        onlyObservesOnePath: Boolean(v296Available && !destinationRouteObservedByV296)
      }
    }
  };
}

function gridlyClassifyActiveRouteContextDestinationType(destination = {}, fallbackLabel = "") {
  const text = `${destination?.type || ""} ${destination?.id || ""} ${destination?.slot || ""} ${destination?.label || ""} ${destination?.name || ""} ${destination?.title || ""} ${fallbackLabel || ""}`.toLowerCase();
  if (/\bhome\b/.test(text)) return "home";
  if (/\bwork\b/.test(text)) return "work";
  if (/saved|favorite|place/.test(text)) return "saved_place";
  if (text.trim()) return "searched_destination";
  return "none";
}

function gridlyBuildActiveRouteContextModel() {
  return {
    routeContextAvailable: "boolean; true only when an observable active or recently cleared route context can be described",
    routeContextType: [...GRIDLY_ACTIVE_ROUTE_CONTEXT_TYPES],
    routeSource: ["none", "search_destination", "saved_destination", "home_destination", "work_destination", "route_watch", "cleared"],
    destinationType: ["none", "searched_destination", "saved_place", "home", "work"],
    destinationLabel: "string; display label only, never a write target",
    hasGeometry: "boolean; geometry is observable context only",
    geometrySource: ["none", "destination_route_preview", "route_watch_preview", "shared_route_helper", "cleared"],
    vertexCount: "number; read-only count of observable vertices",
    routePreviewAvailable: "boolean; read-only route preview/layer availability",
    monitoringActive: "boolean; Route Watch monitoring state remains separate from route creation",
    relevanceObserved: "boolean; whether relevance/audit paths have observed the context",
    routeWatchEligible: "boolean; descriptive only, does not promote or activate Route Watch",
    ownershipNotes: "string[]; explains detected ownership boundaries and drift"
  };
}

const GRIDLY_ACTIVE_ROUTE_CONTEXT_TYPES = Object.freeze(["no_active_route", "searched_destination_route", "saved_destination_route", "home_destination_route", "work_destination_route", "route_watch_monitored_route", "cleared_route"]);

function gridlyBuildCurrentDetectedActiveRouteContext() {
  const preview = window.GridlyDestinationRoutePreview && typeof window.GridlyDestinationRoutePreview === "object" ? window.GridlyDestinationRoutePreview : {};
  const searchState = window.GridlySearchState && typeof window.GridlySearchState === "object" ? window.GridlySearchState : {};
  const selectedDestination = preview?.destination || searchState?.selectedDestination || activeDestinationPlace || {};
  const routeWatchActive = Boolean(routeWatchActivated || window.__gridlyRouteWatchActive);
  const destinationGeometryCount = Array.isArray(preview?.geometry) ? preview.geometry.length : 0;
  const destinationLayerVertexCount = typeof gridlyCountRouteLayerVertices === "function" ? gridlyCountRouteLayerVertices(destinationRoutePreviewLayer) : 0;
  const destinationVertexCount = Math.max(destinationGeometryCount, destinationLayerVertexCount);
  const routeWatchRouteLatLngs = typeof getRoutePolylineLatLngs === "function" ? getRoutePolylineLatLngs() : [];
  const routeWatchLayerVertexCount = typeof gridlyCountRouteLayerVertices === "function" ? Math.max(gridlyCountRouteLayerVertices(window.__gridlyRoutePreviewLayer), gridlyCountRouteLayerVertices(routePreviewCorridorLayer)) : 0;
  const routeWatchVertexCount = Math.max(Array.isArray(routeWatchRouteLatLngs) ? routeWatchRouteLatLngs.length : 0, routeWatchLayerVertexCount, Number(routePreviewPolylinePointCount || 0), Number(lastRouteGeometryPointCount || 0));
  const destinationPreviewActive = Boolean(preview?.active || preview?.status === "ready" || destinationVertexCount >= 2 || selectedDestination?.label || selectedDestination?.title || selectedDestination?.name);
  const destinationLabel = String(preview?.destination?.label || preview?.destination?.name || preview?.destination?.title || selectedDestination?.label || selectedDestination?.name || selectedDestination?.title || activeRouteDestinationLabel || "").trim();
  const destinationType = gridlyClassifyActiveRouteContextDestinationType(selectedDestination, destinationLabel);
  let routeContextType = "no_active_route";
  let routeSource = "none";
  if (routeWatchActive) {
    routeContextType = "route_watch_monitored_route";
    routeSource = activeRouteSource === "destination_preview" ? "destination_preview" : "route_watch";
  } else if (destinationPreviewActive) {
    if (destinationType === "home") {
      routeContextType = "home_destination_route";
      routeSource = "home_destination";
    } else if (destinationType === "work") {
      routeContextType = "work_destination_route";
      routeSource = "work_destination";
    } else if (destinationType === "saved_place") {
      routeContextType = "saved_destination_route";
      routeSource = "saved_destination";
    } else {
      routeContextType = "searched_destination_route";
      routeSource = "search_destination";
    }
  } else if (lastRenderedRouteKey || routePreviewRendered || routePreviewLayerExists || preview?.status === "cleared") {
    routeContextType = "cleared_route";
    routeSource = "cleared";
  }
  const hasDestinationGeometry = destinationVertexCount >= 2;
  const hasRouteWatchGeometry = routeWatchVertexCount >= 2;
  const hasGeometry = routeWatchActive ? hasRouteWatchGeometry : hasDestinationGeometry;
  const vertexCount = routeWatchActive ? routeWatchVertexCount : destinationVertexCount;
  const activeRouteGeometry = routeWatchActive && Array.isArray(routeWatchRouteLatLngs) && routeWatchRouteLatLngs.length >= 2
    ? routeWatchRouteLatLngs.map((point) => ({ lat: Number(point.lat), lng: Number(point.lng) })).filter((point) => Number.isFinite(point.lat) && Number.isFinite(point.lng))
    : Array.isArray(preview?.geometry)
      ? preview.geometry.map((point) => ({ lat: Number(point.lat ?? point.latitude), lng: Number(point.lng ?? point.lon ?? point.longitude) })).filter((point) => Number.isFinite(point.lat) && Number.isFinite(point.lng))
      : [];
  window.__gridlyActiveRouteContextGeometry = activeRouteGeometry;
  return {
    routeContextAvailable: routeContextType !== "no_active_route",
    routeContextType,
    routeSource,
    destinationType,
    destinationLabel: destinationLabel || (routeWatchActive ? activeRouteDestinationLabel || "Route Watch destination" : ""),
    hasGeometry,
    geometrySource: routeWatchActive && hasRouteWatchGeometry
      ? (activeRouteSource === "destination_preview" ? "destination_route_preview" : "route_watch_preview")
      : hasDestinationGeometry ? "destination_route_preview" : routeContextType === "cleared_route" ? "cleared" : "none",
    vertexCount,
    routeGeometry: Object.freeze(activeRouteGeometry.map((point) => Object.freeze({ lat: point.lat, lng: point.lng }))),
    routePreviewAvailable: Boolean(preview?.active || preview?.status === "ready" || routePreviewRendered || destinationVertexCount >= 2 || routeWatchVertexCount >= 2),
    monitoringActive: routeWatchActive,
    relevanceObserved: Boolean(window.gridlyRouteWatchGeometryRuntimeShadowAudit?.().evaluatedCandidates),
    routeWatchEligible: Boolean(destinationType === "home" || destinationType === "work" || destinationType === "saved_place" || routeWatchActive),
    ownershipNotes: [
      "Active route context is read-only and descriptive.",
      activeRouteSource === "destination_preview"
        ? "Destination preview owns the exact geometry monitored by Route Watch."
        : "Local Route Watch geometry remains owned by the saved-place preview.",
      "Route Watch monitoring remains separate from route creation and destination preview.",
      "Audit observation may read geometry counts without changing recommendations, relevance, routing, UI, or storage."
    ]
  };
}

function getActiveRouteContext() {
  const detectedContext = gridlyBuildCurrentDetectedActiveRouteContext();
  const normalizedContext = {
    available: true,
    readOnly: true,
    productionBehaviorChanged: false,

    routeContextAvailable: Boolean(detectedContext.routeContextAvailable),
    routeContextType: GRIDLY_ACTIVE_ROUTE_CONTEXT_TYPES.includes(detectedContext.routeContextType) ? detectedContext.routeContextType : "no_active_route",
    routeSource: String(detectedContext.routeSource || "none"),
    destinationType: String(detectedContext.destinationType || "none"),
    destinationLabel: String(detectedContext.destinationLabel || ""),

    hasGeometry: Boolean(detectedContext.hasGeometry),
    geometrySource: String(detectedContext.geometrySource || "none"),
    vertexCount: Number.isFinite(Number(detectedContext.vertexCount)) ? Number(detectedContext.vertexCount) : 0,
    routeGeometry: Object.freeze(Array.isArray(detectedContext.routeGeometry) ? detectedContext.routeGeometry.map((point) => Object.freeze({ lat: Number(point.lat), lng: Number(point.lng) })).filter((point) => Number.isFinite(point.lat) && Number.isFinite(point.lng)) : []),

    routePreviewAvailable: Boolean(detectedContext.routePreviewAvailable),
    monitoringActive: Boolean(detectedContext.monitoringActive),
    relevanceObserved: Boolean(detectedContext.relevanceObserved),
    routeWatchEligible: Boolean(detectedContext.routeWatchEligible),

    ownershipNotes: Object.freeze(Array.isArray(detectedContext.ownershipNotes) ? [...detectedContext.ownershipNotes] : []),
    safeForProductionWiring: false
  };
  return Object.freeze(normalizedContext);
}

