function gridlyBuildRouteWatchFunctionalReadinessAudit() {
  const safeNumber = (value, fallback = 0) => {
    const number = Number(value);
    return Number.isFinite(number) ? number : fallback;
  };
  const layerOnMap = (layer) => {
    try {
      return Boolean(map && layer && typeof map.hasLayer === "function" && map.hasLayer(layer));
    } catch (_error) {
      return false;
    }
  };
  const routeWatchRouteLatLngs = typeof getRoutePolylineLatLngs === "function" ? getRoutePolylineLatLngs() : [];
  const routeWatchLayerVertexCount = gridlyCountRouteLayerVertices(window.__gridlyRoutePreviewLayer);
  const routeWatchGroupVertexCount = gridlyCountRouteLayerVertices(routePreviewCorridorLayer);
  const routeWatchSnapshot = typeof getGridlyAuditRouteRenderSnapshot === "function" ? getGridlyAuditRouteRenderSnapshot() : {};
  const routeWatchPolylineVertexCount = Math.max(
    Array.isArray(routeWatchRouteLatLngs) ? routeWatchRouteLatLngs.length : 0,
    routeWatchLayerVertexCount,
    routeWatchGroupVertexCount,
    safeNumber(routeWatchSnapshot?.routeGeometryPointCount),
    safeNumber(routePreviewPolylinePointCount),
    safeNumber(lastRouteGeometryPointCount)
  );
  const places = typeof getSavedPlaces === "function" ? getSavedPlaces() : [];
  const selectedStartId = els?.routeWatchStartSelect?.value || lastRouteWatchSelection?.startId || "";
  const selectedDestinationId = els?.routeWatchDestinationSelect?.value || lastRouteWatchSelection?.destinationId || "";
  const selectedStart = places.find((place) => place.id === selectedStartId) || null;
  const selectedDestination = places.find((place) => place.id === selectedDestinationId) || null;
  const startCoordinates = normalizeCoordinatePair(selectedStart?.lat, selectedStart?.lng)
    || normalizeCoordinatePair(lastRouteAttempt?.startCoords?.lat, lastRouteAttempt?.startCoords?.lng)
    || null;
  const destinationCoordinates = normalizeCoordinatePair(selectedDestination?.lat, selectedDestination?.lng)
    || normalizeCoordinatePair(lastRouteAttempt?.destinationCoords?.lat, lastRouteAttempt?.destinationCoords?.lng)
    || null;
  const activeRouteContext = typeof getActiveRouteContext === "function" ? getActiveRouteContext() : null;
  const routeWatchActive = Boolean(activeRouteContext?.monitoringActive || routeWatchActivated || window.__gridlyRouteWatchActive);
  const routePreviewLayerOnMap = Boolean(layerOnMap(window.__gridlyRoutePreviewLayer) || layerOnMap(routePreviewCorridorLayer));
  const routePreviewLayerExistsAudit = Boolean(window.__gridlyRoutePreviewLayer || routePreviewCorridorLayer || routePreviewLayerExists);
  const routePreviewRenderedAudit = Boolean(routePreviewRendered || routeWatchPolylineVertexCount >= 2 || routePreviewLayerOnMap);
  const routeWatchGeometryReady = Boolean(routeWatchPolylineVertexCount >= 2 && routePreviewLayerExistsAudit && routePreviewRenderedAudit);
  const fallbackRouteUsed = String(routeGeometrySource || "").toLowerCase() === "fallback" || Boolean(!osrmRouteSuccess && routeWatchPolylineVertexCount >= 2);
  const osrmFailureReason = osrmRouteSuccess ? "" : (lastRouteError || lastRoutePreviewError || lastRouteEarlyReturnReason || routePreviewReason || "osrm_route_not_successful");
  const routeRelevanceNested = gridlyCommuteIntelligenceAuditState?.routeRelevanceNestedSections || {};
  const routeRelevanceExecuted = Boolean(
    safeNumber(routeRelevanceNested.isIncidentRouteRelevant_loop) > 0
    || safeNumber(routeRelevanceNested.getRoutePolylineLatLngs) > 0
    || safeNumber(routeRelevanceNested.getRouteHazardAssessment) > 0
  );
  const v296Audit = typeof window.gridlyRouteWatchGeometryRuntimeShadowAudit === "function"
    ? window.gridlyRouteWatchGeometryRuntimeShadowAudit()
    : null;
  const v296Candidates = Array.isArray(v296Audit?.candidates) ? v296Audit.candidates : [];
  const preview = getGridlyDestinationRoutePreviewState();
  const destinationGeometryCount = Array.isArray(preview.geometry) ? preview.geometry.length : 0;
  const destinationLayerVertexCount = gridlyCountRouteLayerVertices(destinationRoutePreviewLayer);
  const destinationRouteVertexCount = Math.max(destinationGeometryCount, destinationLayerVertexCount, safeNumber(gridlyDestinationPerformanceAuditState.routeGeometryPointCount));
  const searchedDestination = preview.destination || normalizeGridlySearchResult(ensureGridlySearchState()?.selectedDestination) || null;
  const searchedDestinationCoordinates = normalizeCoordinatePair(searchedDestination?.lat, searchedDestination?.lng);
  const destinationRoutePreviewRequested = Boolean(preview.active || preview.status && preview.status !== "idle" || gridlyDestinationPerformanceAuditState.routePreviewRequestStartedAt);
  const destinationRouteLayerExists = Boolean(destinationRoutePreviewLayer || preview.routeLayer);
  const destinationRouteLayerOnMap = Boolean(layerOnMap(destinationRoutePreviewLayer) || layerOnMap(preview.routeLayer));
  const destinationRoutePreviewRendered = Boolean(preview.status === "ready" && destinationRouteVertexCount >= 2 && destinationRouteLayerExists);
  const destinationRouteGeometryReady = Boolean(destinationRouteVertexCount >= 2 && destinationRoutePreviewRendered);
  const destinationRouteTreatedAsRouteWatch = Boolean(
    routeWatchActive
    && searchedDestinationCoordinates
    && destinationCoordinates
    && Math.abs(Number(searchedDestinationCoordinates.lat) - Number(destinationCoordinates.lat)) < 0.00001
    && Math.abs(Number(searchedDestinationCoordinates.lng) - Number(destinationCoordinates.lng)) < 0.00001
  );
  const destinationRouteIntentionallySeparate = Boolean(
    typeof buildGridlyDestinationRoutePreview === "function"
    && typeof startInlineRouteWatch === "function"
    && destinationRoutePreviewLayer
    && destinationRoutePreviewLayer !== savedRouteLayer
    && destinationRoutePreviewLayer !== window.__gridlyRoutePreviewLayer
  );
  const destinationRouteFunctional = Boolean(destinationRoutePreviewRequested && searchedDestinationCoordinates && destinationRouteGeometryReady);
  const routeWatchFunctional = Boolean(routeWatchActive && startCoordinates && destinationCoordinates && routeWatchGeometryReady);
  const routeWatchOsrmAttempted = Boolean(osrmRequestStarted || routeRequestTriggered || lastRouteRequest || lastOsrmRequestUrl || lastRouteAttempt?.osrmCallStarted);
  const routePreviewRequested = Boolean(routeRequestTriggered || lastRouteRequest || lastRouteAttempt || routePreviewReason !== "Route preview has not been requested.");
  const destinationOnlyRouteActive = Boolean(destinationRouteFunctional && destinationRouteIntentionallySeparate && !routeWatchActive);
  const savedSelectionsValid = Boolean(startCoordinates && destinationCoordinates);
  const savedRouteMissingDestination = Boolean(startCoordinates && !destinationCoordinates);
  const routeCleared = Boolean(!routeWatchActive && !destinationRoutePreviewRequested && routePreviewReason === "Route cleared.");
  const activeRouteOwnershipState = activeRouteContext?.routeContextAvailable
    ? gridlyRouteWatchOwnershipFromActiveContext(activeRouteContext)
    : routeWatchActive
      ? "route_watch_monitored_route"
      : destinationOnlyRouteActive
        ? "searched_destination_route"
        : routeCleared
          ? "route_cleared"
          : savedRouteMissingDestination
            ? "missing_destination"
            : "no_active_route";
  const observedCandidateCount = safeNumber(v296Audit?.evaluatedCandidates || v296Candidates.length);
  const routeWatchObservedByV296 = v296Candidates.length > 0
    ? v296Candidates.some((candidate) => {
        const ownership = String(candidate?.routeOwnership || candidate?.routeSource || "saved_route_watch_route");
        const identifier = String(candidate?.routeIdentifier || candidate?.routeName || "");
        return ownership !== "searched_destination_route" && !/destination|search|preview|walmart/i.test(identifier);
      })
    : observedCandidateCount > 0 && !destinationRouteObservedByV296;
  const observationReady = Boolean(routeWatchFunctional && routeWatchPolylineVertexCount > 0 && routeWatchObservedByV296);

  let blockingReason = "none";
  let recommendedNextAction = "proceed_to_runtime_observation";
  if (destinationOnlyRouteActive) {
    blockingReason = "searched_destination_route_is_separate_from_saved_route_watch";
    recommendedNextAction = "separate_destination_observation";
  } else if (!routeWatchActive && savedRouteMissingDestination) {
    blockingReason = "missing_saved_route_watch_destination";
    recommendedNextAction = "select_saved_route_watch_destination";
  } else if (!routeWatchActive && savedSelectionsValid && routePreviewRequested) {
    blockingReason = "saved_route_watch_activation_attempt_did_not_remain_active";
    recommendedNextAction = "fix_route_watch_activation";
  } else if (!routeWatchActive) {
    blockingReason = routeCleared ? "route_cleared" : "no_active_saved_route_watch";
    recommendedNextAction = savedSelectionsValid ? "start_saved_route_watch" : "select_saved_route_watch_start_and_destination";
  } else if (routeWatchOsrmAttempted && !osrmRouteSuccess && routeWatchPolylineVertexCount < 2) {
    blockingReason = osrmFailureReason || "osrm_route_generation_failed";
    recommendedNextAction = "fix_osrm_route_generation";
  } else if (routeWatchActive && routeWatchPolylineVertexCount < 2) {
    blockingReason = "route_watch_geometry_not_retained";
    recommendedNextAction = "fix_route_geometry_retention";
  } else if (!routePreviewLayerExistsAudit || !routePreviewLayerOnMap || !routePreviewRenderedAudit) {
    blockingReason = "route_preview_not_rendered_or_not_on_map";
    recommendedNextAction = "fix_route_preview_rendering";
  } else if (destinationRouteGeometryReady && !destinationRouteTreatedAsRouteWatch && destinationRouteIntentionallySeparate && !routeWatchObservedByV296) {
    blockingReason = "destination_route_geometry_is_separate_from_route_watch_observation";
    recommendedNextAction = "separate_destination_observation";
  } else if (!routeWatchObservedByV296) {
    blockingReason = "runtime_route_relevance_observation_not_yet_executed";
    recommendedNextAction = "proceed_to_runtime_observation";
  }

  return {
    available: true,
    auditOnly: true,
    productionBehaviorChanged: false,
    conservativeRule: "Do not recommend more geometry scoring work unless route geometry is present and Route Watch is functional.",
    activeRouteContext,
    sharedOwnershipSource: "getActiveRouteContext",
    savedRouteWatchPath: {
      selectedStart: selectedStart ? { id: selectedStart.id || "", name: selectedStart.name || "" } : { id: selectedStartId, name: lastRouteAttempt?.selectedStart || "" },
      selectedDestination: selectedDestination ? { id: selectedDestination.id || "", name: selectedDestination.name || "" } : { id: selectedDestinationId, name: lastRouteAttempt?.selectedDestination || "" },
      startCoordinatesPresent: Boolean(startCoordinates),
      destinationCoordinatesPresent: Boolean(destinationCoordinates),
      routeWatchActive,
      activeRouteOwnershipState,
      savedSelectionsValid,
      routeCleared,
      routePreviewRequested,
      osrmRequestAttempted: routeWatchOsrmAttempted,
      osrmRouteSuccess: Boolean(osrmRouteSuccess),
      osrmFailureReason,
      fallbackRouteUsed,
      routeGeometrySource: routeGeometrySource || "fallback",
      routePolylineVertexCount: routeWatchPolylineVertexCount,
      routePreviewLayerExists: routePreviewLayerExistsAudit,
      routePreviewLayerOnMap,
      routePreviewRendered: routePreviewRenderedAudit,
      activeRouteSource,
      monitoredRouteDuration: monitoredRouteDurationSeconds,
      routeRelevanceExecuted,
      v296RuntimeShadowObservedCandidates: observedCandidateCount,
      lastRouteAttempt: lastRouteAttempt ? { ...lastRouteAttempt } : null
    },
    searchedDestinationRoutePath: {
      lastSearchedDestination: searchedDestination ? {
        label: searchedDestination.label || searchedDestination.name || searchedDestination.displayName || searchedDestination.title || "Destination",
        id: searchedDestination.id || null
      } : null,
      searchedDestinationCoordinatesPresent: Boolean(searchedDestinationCoordinates),
      destinationRoutePreviewRequested,
      destinationRouteGeometrySource: preview.routeProvider || (destinationRouteVertexCount >= 2 ? "unknown" : "none"),
      destinationRouteVertexCount,
      destinationRoutePreviewLayerExists: destinationRouteLayerExists,
      destinationRoutePreviewRendered,
      destinationRouteTreatedAsRouteWatch,
      destinationRouteIntentionallySeparate,
      destinationOnlyRouteActive,
      destinationRouteStatus: preview.status || "idle",
      destinationRouteError: preview.error || ""
    },
    routeWatchFunctional,
    routeWatchGeometryReady,
    v300Recommendation: observationReady ? "proceed_to_geometry_runtime_observation" : recommendedNextAction,
    destinationRouteFunctional,
    destinationRouteGeometryReady,
    observationReady,
    blockingReason,
    recommendedNextAction
  };
}

function gridlyBuildRouteWatchDestinationOwnershipAudit() {
  const preview = getGridlyDestinationRoutePreviewState();
  const savedPlacesState = typeof getSavedPlacesState === "function"
    ? getSavedPlacesState()
    : (typeof normalizeSavedPlaces === "function" ? normalizeSavedPlaces() : { home: null, work: null, custom: [], favorites: [] });
  const routableSavedPlaces = typeof getSavedPlaces === "function" ? getSavedPlaces() : [];
  const destinationRouteAudit = gridlyBuildDestinationVsRouteWatchGeometryObservationAudit();
  const readinessAudit = gridlyBuildRouteWatchFunctionalReadinessAudit();
  const destinationRouteActive = Boolean(readinessAudit.searchedDestinationRoutePath?.destinationRoutePreviewRequested || preview.active || preview.status === "ready");
  const routeWatchActive = Boolean(routeWatchActivated || window.__gridlyRouteWatchActive);
  const destinationSearchOwnsRouting = Boolean(typeof buildGridlyDestinationRoutePreview === "function" && typeof drawGridlyDestinationRoutePreviewLine === "function");
  const routeWatchOwnsMonitoring = Boolean(typeof startInlineRouteWatch === "function" && typeof getRouteHazardAssessment === "function" && typeof isIncidentRouteRelevant === "function");
  const separateRoutePreviewLayers = Boolean(
    destinationRoutePreviewLayer
    && destinationRoutePreviewLayer !== savedRouteLayer
    && destinationRoutePreviewLayer !== window.__gridlyRoutePreviewLayer
  );
  const sharedGeometryProvider = Boolean(typeof fetchRoadRoutePreviewData === "function");
  const ownershipOverlapDetected = Boolean(destinationSearchOwnsRouting && routeWatchOwnsMonitoring && sharedGeometryProvider);
  const ownershipDriftDetected = Boolean(ownershipOverlapDetected && separateRoutePreviewLayers);
  const classifySelection = (label, place = null, options = {}) => ({
    label,
    configured: options.searched ? true : Boolean(place && isConfiguredPlace(place)),
    userFacingWorkflow: "Search Destination selection starts destination routing and can lead into Route Watch monitoring.",
    createsRouteWatchRoute: Boolean(routeWatchActive && (options.savedPlace || options.homeWorkSelector)),
    createsDestinationRoute: Boolean(destinationRouteActive || options.searched),
    createsBoth: Boolean((routeWatchActive && (options.savedPlace || options.homeWorkSelector)) && (destinationRouteActive || options.searched)),
    createsNeither: false,
    technicalClassification: (routeWatchActive && (options.savedPlace || options.homeWorkSelector))
      ? "saved_route_watch_route"
      : "searched_destination_route"
  });

  const productOwnershipModel = "one_destination_based_route_watch_experience";
  const technicalOwnershipModel = {
    destinationRouteOwnership: "Destination Search owns route request/preview for Home, Work, saved places, and searched destinations.",
    routeWatchOwnership: "Route Watch owns activation state, saved-place selector monitoring, route relevance, and monitoring copy.",
    routePreviewOwnership: separateRoutePreviewLayers
      ? "Fragmented: Destination Search and Route Watch keep separate preview layers while sharing route geometry fetch capability."
      : "Shared route preview ownership was not proven in this snapshot.",
    geometryOwnership: sharedGeometryProvider
      ? "Shared OSRM/fetchRoadRoutePreviewData provider with separate destination and Route Watch retention/rendering paths."
      : "Geometry provider ownership unavailable in this snapshot.",
    relevanceOwnership: "Route Watch owns incident relevance/monitoring; destination preview does not own production relevance scoring.",
    routeMonitoringOwnership: "Route Watch owns monitoring after a route is active.",
    savedPlaceOwnership: "Saved Places owns Home, Work, custom, and favorite place persistence; Destination Search surfaces them as routable destinations."
  };

  return {
    available: true,
    auditOnly: true,
    productionBehaviorChanged: false,

    productOwnershipModel,
    technicalOwnershipModel,

    destinationSearchOwnsRouting,
    routeWatchOwnsMonitoring,
    ownershipOverlapDetected,
    ownershipDriftDetected,

    homeDestinationClassification: classifySelection("Home", savedPlacesState.home, { savedPlace: true, homeWorkSelector: true }),
    workDestinationClassification: classifySelection("Work", savedPlacesState.work, { savedPlace: true, homeWorkSelector: true }),
    savedPlaceClassification: classifySelection("Marshall's / Walmart saved place", routableSavedPlaces.find((place) => !/home|work/i.test(String(place.id || ""))) || null, { savedPlace: true }),
    searchedDestinationClassification: classifySelection("Marshall's / Walmart searched destination", null, { searched: true }),

    geometryOwnership: technicalOwnershipModel.geometryOwnership,
    routePreviewOwnership: technicalOwnershipModel.routePreviewOwnership,
    relevanceOwnership: technicalOwnershipModel.relevanceOwnership,

    specificAnswers: {
      homeFromSearchDestinationCreates: routeWatchActive ? "both" : "destination_route",
      workFromSearchDestinationCreates: routeWatchActive ? "both" : "destination_route",
      marshallsFromSearchDestinationCreates: routeWatchActive && destinationRouteActive ? "both" : "destination_route",
      walmartFromSearchDestinationCreates: routeWatchActive && destinationRouteActive ? "both" : "destination_route",
      routeWatchHasSeparateActivationFlow: true,
      userPerceivesDistinction: false,
      codePerceivesDistinction: ownershipDriftDetected
    },

    userExperienceConclusion: "The current product experience treats Home, Work, saved places, searched destinations, route preview, and Route Watch as one destination-based routing workflow.",
    technicalConclusion: "Implementation still preserves separate destination-route and saved Route Watch ownership paths for preview layers, activation state, monitoring, and relevance observation.",

    recommendedOwnershipModel: ownershipDriftDetected
      ? "V301 Route Watch Ownership Refactor: align technical ownership around destination-based Route Watch while keeping geometry scoring audit-only."
      : "V301 Geometry Observation Alignment: extend audit-only observation if runtime confirms a single destination-based Route Watch path.",

    supportingAuditState: {
      destinationRouteAudit,
      readinessAudit
    },

    safeForProductionWiring: false
  };
}


function gridlyBuildRouteWatchOwnershipRefactorAudit() {
  const currentOwnershipModel = "fragmented_destination_route_and_route_watch_ownership";
  const futureOwnershipModel = "unified_destination_based_route_watch_ownership";
  const ownershipDomains = [
    { domain: "destination selection", currentOwner: "Search Destination plus Saved Places selectors", desiredOwner: "Destination Intent", migrationRisk: "medium" },
    { domain: "destination search", currentOwner: "Search Destination", desiredOwner: "Destination Intent", migrationRisk: "low" },
    { domain: "Home", currentOwner: "Saved Places persistence plus Search Destination surfacing plus Route Watch saved selector", desiredOwner: "Destination Intent with Saved Places as storage", migrationRisk: "medium" },
    { domain: "Work", currentOwner: "Saved Places persistence plus Search Destination surfacing plus Route Watch saved selector", desiredOwner: "Destination Intent with Saved Places as storage", migrationRisk: "medium" },
    { domain: "saved places", currentOwner: "Saved Places persistence and Search Destination routing inputs", desiredOwner: "Destination Inputs owned by Destination Intent", migrationRisk: "medium" },
    { domain: "searched destinations", currentOwner: "Search Destination", desiredOwner: "Destination Intent", migrationRisk: "low" },
    { domain: "route preview generation", currentOwner: "Search Destination preview path and Route Watch saved-route path", desiredOwner: "Route Generation", migrationRisk: "high" },
    { domain: "route geometry retention", currentOwner: "Destination preview state, saved route state, and audit-only geometry shadow state", desiredOwner: "Route Geometry Observation", migrationRisk: "high" },
    { domain: "route monitoring", currentOwner: "Route Watch activation and monitoring state", desiredOwner: "Route Watch Monitoring", migrationRisk: "medium" },
    { domain: "route relevance", currentOwner: "Route Watch relevance helpers", desiredOwner: "Route Intelligence", migrationRisk: "medium" },
    { domain: "route intelligence", currentOwner: "Route relevance and destination intelligence are adjacent but separate", desiredOwner: "Route Intelligence", migrationRisk: "medium" },
    { domain: "route recommendations", currentOwner: "Destination and route-watch surfaces can independently communicate route state", desiredOwner: "Awareness Surfaces reading Route Intelligence", migrationRisk: "medium" },
    { domain: "alternate routes", currentOwner: "Route generation/preview exploration without unified Route Watch ownership", desiredOwner: "Route Generation with Route Intelligence observation", migrationRisk: "medium" },
    { domain: "Route Watch UI ownership", currentOwner: "Route Watch surfaces and display/blocker audits", desiredOwner: "Awareness Surfaces reflecting destination route state", migrationRisk: "medium" },
    { domain: "Route Watch activation ownership", currentOwner: "Route Watch activation flow separate from destination selection", desiredOwner: "Route Watch Monitoring begins from generated destination route state", migrationRisk: "high" }
  ];
  const duplicatedOwnership = [
    { area: "route preview generation", owners: ["Search Destination", "Route Watch"], risk: "high" },
    { area: "Home/Work route intent", owners: ["Saved Places", "Search Destination", "Route Watch activation"], risk: "medium" }
  ];
  const fragmentedOwnership = [
    { area: "route geometry lifecycle", fragments: ["fetch", "preview render", "Route Watch retention", "shadow observation"], risk: "high" },
    { area: "route state communication", fragments: ["destination panel", "Route Watch UI", "awareness surfaces"], risk: "medium" }
  ];
  const orphanOwnership = [
    { area: "destination route geometry as Route Watch observation", reason: "Generated destination geometry is not yet the authoritative Route Watch geometry owner.", risk: "high" },
    { area: "searched destination monitoring handoff", reason: "Search Destination can create route intent before Route Watch monitoring owns it.", risk: "medium" }
  ];
  const migrationRisk = {
    overall: "medium_high",
    lowRisk: ownershipDomains.filter((domain) => domain.migrationRisk === "low").length,
    mediumRisk: ownershipDomains.filter((domain) => domain.migrationRisk === "medium").length,
    highRisk: ownershipDomains.filter((domain) => domain.migrationRisk === "high").length,
    reason: "Planning is safe, but implementation would touch route activation, geometry retention, and monitoring ownership boundaries."
  };
  const recommendedRefactorSequence = [
    { phase: 1, name: "Ownership alignment", implementation: false, goal: "Name Destination Intent as the product owner and document Route Generation, Route Watch Monitoring, Route Intelligence, and Awareness Surfaces as downstream owners." },
    { phase: 2, name: "Observation alignment", implementation: false, goal: "Align audits so destination-created route state can be observed without changing production routing." },
    { phase: 3, name: "Monitoring alignment", implementation: false, goal: "Design the handoff from generated destination route to Route Watch monitoring." },
    { phase: 4, name: "Geometry observation alignment", implementation: false, goal: "Design audit-only geometry observation that follows the destination route lifecycle." },
    { phase: 5, name: "Future production consideration", implementation: false, goal: "Only after evidence and approval, consider production wiring separately." }
  ];

  return {
    available: true,
    auditOnly: true,
    productionBehaviorChanged: false,

    currentOwnershipModel,
    futureOwnershipModel,

    ownershipDomains,
    ownershipDriftCount: duplicatedOwnership.length + fragmentedOwnership.length + orphanOwnership.length,

    duplicatedOwnership,
    fragmentedOwnership,
    orphanOwnership,

    migrationRisk,

    productModelAligned: true,
    technicalModelAligned: false,

    recommendedRefactorSequence,

    safeForProductionWiring: false
  };
}

