    geographicEvaluationState: hasCanonicalPlaceIdentity && !canonicalFocus ? "CANONICAL_FOCUS_UNAVAILABLE" : "AVAILABLE",
    countyWide: area.countyWide === true,
    fallback: area.fallback === true
