function resyncGridlyActiveCountyVisibleSurfaces(reason = "active-county-resync") {
  const activeCountyId = gridlyGetActiveCountyId();
  const filterActiveCountyRecords = (records) => {
    return (Array.isArray(records) ? records : []).filter((record) => gridlyReportMatchesActiveCounty(record, activeCountyId));
  };
  activeReports = filterActiveCountyRecords(activeReports);
  activeHazards = filterActiveCountyRecords(activeHazards);
  recentlyClearedRoadHazards = filterActiveCountyRecords(recentlyClearedRoadHazards);
  gridlyRefreshCycleCache = createGridlyRefreshCycleCache();

  if (unifiedIncidentLayer && typeof unifiedIncidentLayer.clearLayers === "function") {
    unifiedIncidentLayer.clearLayers();
  }

  const syncReason = `${reason}:${activeCountyId}`;
  try {
    refreshReportHazardViews(syncReason);
  } finally {
    gridlyRefreshCycleCache = null;
  }
  if (typeof renderAlerts === "function") renderAlerts();
  if (typeof updateMobileAlertsMirror === "function") updateMobileAlertsMirror();
  if (typeof syncGridlyAwarenessAreaSurfacesImmediately === "function") {
    syncGridlyAwarenessAreaSurfacesImmediately(syncReason, { refreshMapMarkers: true });
  }
  if (typeof loadSharedReports === "function") {
    loadSharedReports(`active_county_surface_resync:${activeCountyId}`).catch((error) => {
      console.warn("Gridly active county surface resync refresh failed:", error);
    });
  }
}

function gridlyGetCountyBoundsMetadata(countyId = GRIDLY_DEFAULT_COUNTY_ID) {
  const requested = String(countyId || "").trim().toLowerCase();
  const normalized = gridlyNormalizeCountyId(requested || GRIDLY_DEFAULT_COUNTY_ID);
  const availableBounds = gridlyGetAvailableCountyAwarenessBounds();
  const raw = availableBounds[normalized] || null;
  const knownRequestedMissingBounds = requested && gridlyIsKnownCountyId(requested) && !availableBounds[requested];
  return {
    requestedCountyId: requested || GRIDLY_DEFAULT_COUNTY_ID,
    countyId: knownRequestedMissingBounds ? requested : normalized,
    rawBounds: knownRequestedMissingBounds ? null : raw,
    source: knownRequestedMissingBounds ? null : (raw?.source || null),
    fallbackUsed: Boolean(requested && requested !== normalized),
    libertyFallbackDetected: Boolean(requested && requested !== "liberty-tx" && normalized === "liberty-tx"),
    missingBoundary: Boolean(knownRequestedMissingBounds || !raw)
  };
}

function gridlyGetCountyBounds(countyId = GRIDLY_DEFAULT_COUNTY_ID) {
  if (typeof L === "undefined" || !L.latLngBounds) return null;
  const metadata = gridlyGetCountyBoundsMetadata(countyId);
  const raw = metadata.rawBounds;
  // The original awareness-bounds table only covers the early activated
  // counties. Statewide PLACE activation loads authoritative county geometry
  // during startup, so use that governed geometry for later counties.
  if (!raw) return typeof gridlyGetAuthoritativeCountyGeometryFocusBounds === "function"
    ? gridlyGetAuthoritativeCountyGeometryFocusBounds(metadata.countyId)
    : null;
  // Legacy test sentinel only: const raw = normalized === "montgomery-tx" ? MONTGOMERY_COUNTY_AWARENESS_BOUNDS : LIBERTY_COUNTY_AWARENESS_BOUNDS;
  const bounds = L.latLngBounds([raw.south, raw.west], [raw.north, raw.east]);
  return bounds.isValid() ? bounds : null;
}

