function gridlyMilesToMeters(miles) {
  const value = Number(miles);
  return Number.isFinite(value) && value > 0 ? value * 1609.344 : 0;
}

function getGridlyAwarenessIdentityArea() {
  const area = typeof getGridlySelectedAwarenessArea === "function" ? getGridlySelectedAwarenessArea() : null;
  return area || GRIDLY_AWARENESS_AREA_BY_KEY?.["liberty-county"] || null;
}

function getGridlyAwarenessIdentityBoundaryStyle() {
  const area = getGridlyAwarenessIdentityArea();
  const countyMode = Boolean(area?.countyWide || area?.fallback || activeGeoFilter === "county");
  const standardMap = activeBaseLayerName === "Standard" || currentMapStyle === "Standard";
  return {
    pane: "awarenessIdentityPane",
    color: standardMap ? "#374151" : (countyMode ? "#8ee6ff" : "#94dff3"),
    weight: countyMode ? 1.5 : 1.25,
    opacity: countyMode ? 0.42 : 0.34,
    fill: false,
    dashArray: countyMode ? "" : "10 12",
    lineCap: "round",
    lineJoin: "round",
    interactive: false,
    className: `gridly-county-awareness-boundary${countyMode ? " gridly-county-awareness-boundary-emphasis" : ""}`
  };
}

function getGridlyAwarenessIdentitySnapshot(extra = {}) {
  const center = map?.getCenter?.();
  return {
    selectedAwarenessArea: extra.selectedAwarenessArea ?? gridlyAwarenessMapIdentityState.selectedAwarenessArea,
    countyBoundaryLoaded: extra.countyBoundaryLoaded ?? Boolean(gridlyAwarenessMapIdentityState.countyBoundaryLoaded),
    countyBoundaryVisible: extra.countyBoundaryVisible ?? Boolean(gridlyAwarenessMapIdentityState.countyBoundaryVisible),
    radiusHaloVisible: extra.radiusHaloVisible ?? Boolean(gridlyAwarenessMapIdentityState.radiusHaloVisible),
    labelVisible: extra.labelVisible ?? Boolean(gridlyAwarenessMapIdentityState.labelVisible),
    labelPlacement: extra.labelPlacement ?? gridlyAwarenessMapIdentityState.labelPlacement ?? null,
    currentFilter: extra.currentFilter ?? activeGeoFilter ?? null,
    mapZoomCenter: map ? {
      zoom: map.getZoom?.() ?? null,
      center: center ? { lat: Number(center.lat.toFixed(6)), lng: Number(center.lng.toFixed(6)) } : null
    } : null,
    warnings: Array.isArray(extra.warnings) ? extra.warnings : (gridlyAwarenessMapIdentityState.warnings || []),
    errors: Array.isArray(extra.errors) ? extra.errors : (gridlyAwarenessMapIdentityState.errors || [])
  };
}

function setGridlyAwarenessMapIdentityState(patch = {}) {
  gridlyAwarenessMapIdentityState = getGridlyAwarenessIdentitySnapshot(patch);
  return gridlyAwarenessMapIdentityState;
}

function getGridlyAwarenessIdentityLabelPlacement(area = {}, labelText = "Awareness") {
  const rawLat = Number(area?.lat);
  const rawLng = Number(area?.lng);
  if (!map || typeof L === "undefined" || !Number.isFinite(rawLat) || !Number.isFinite(rawLng)) {
    return { latLng: [rawLat, rawLng], iconAnchor: [0, 0], adjusted: false, reason: "map_or_coordinates_unavailable" };
  }

  const countyMode = Boolean(area?.countyWide || area?.fallback);
  const baseLatLng = countyMode ? L.latLng(rawLat, rawLng) : L.latLng(rawLat + 0.006, rawLng);
  const size = map.getSize?.();
  if (!size || !Number.isFinite(size.x) || !Number.isFinite(size.y)) {
    return { latLng: [baseLatLng.lat, baseLatLng.lng], iconAnchor: [0, 0], adjusted: false, reason: "map_size_unavailable" };
  }

  const insets = getGridlyVisibleMapChromeInsets(map);
  const labelWidth = Math.min(230, Math.max(132, String(labelText || "Awareness").length * 7.2 + 28));
  const labelHeight = 32;
  const margin = 10;
  const minX = Math.max(margin, Number(insets.left || 0) + margin);
  const maxX = Math.max(minX, Number(size.x) - Number(insets.right || 0) - labelWidth - margin);
  const minY = Math.max(margin, Number(insets.top || 0) + margin);
  const maxY = Math.max(minY, Number(size.y) - Number(insets.bottom || 0) - labelHeight - margin);
  const basePoint = map.latLngToContainerPoint(baseLatLng);
  const clampedPoint = L.point(
    Math.min(Math.max(basePoint.x, minX), maxX),
    Math.min(Math.max(basePoint.y, minY), maxY)
  );
  const adjusted = Math.abs(clampedPoint.x - basePoint.x) > 1 || Math.abs(clampedPoint.y - basePoint.y) > 1;
  const adjustedLatLng = map.containerPointToLatLng(clampedPoint);

  return {
    latLng: [Number(adjustedLatLng.lat), Number(adjustedLatLng.lng)],
    iconAnchor: [0, 0],
    adjusted,
    reason: adjusted ? "viewport_clamped_to_visible_map_area" : "anchor_visible",
    estimatedLabelWidth: Math.round(labelWidth),
    containerPoint: { x: Math.round(clampedPoint.x), y: Math.round(clampedPoint.y) },
    baseContainerPoint: { x: Math.round(basePoint.x), y: Math.round(basePoint.y) },
    safeBounds: { minX: Math.round(minX), maxX: Math.round(maxX), minY: Math.round(minY), maxY: Math.round(maxY) }
  };
}

function renderGridlyAwarenessMapIdentity(reason = "unknown") {
  const warnings = [];
  const errors = [];
  if (!map || typeof L === "undefined") {
    warnings.push("Map or Leaflet is not initialized yet.");
    return setGridlyAwarenessMapIdentityState({ warnings, errors });
  }
  if (!gridlyAwarenessIdentityLayer) {
    warnings.push("Awareness identity layer is not initialized yet.");
    return setGridlyAwarenessMapIdentityState({ warnings, errors });
  }

  const area = getGridlyAwarenessIdentityArea();
  if (!area) {
    errors.push("No selected awareness area could be resolved.");
    gridlyAwarenessIdentityLayer.clearLayers();
    return setGridlyAwarenessMapIdentityState({ warnings, errors });
  }

  gridlyAwarenessIdentityLayer.clearLayers();
  gridlyCountyBoundaryLayer = null;
  gridlyAwarenessRadiusLayer = null;
  gridlyAwarenessIdentityLabelLayer = null;

  if (gridlyCountyBoundaryGeoJson && L.geoJSON) {
    gridlyCountyBoundaryLayer = L.geoJSON(gridlyCountyBoundaryGeoJson, {
      style: getGridlyAwarenessIdentityBoundaryStyle,
      interactive: false
    }).addTo(gridlyAwarenessIdentityLayer);
  } else {
    warnings.push("Liberty County boundary data is not loaded; using bounds-only awareness orientation until it loads.");
  }

  const countyMode = Boolean(area.countyWide || area.fallback);
  const labelText = `${area.label || GRIDLY_COUNTY_WIDE_AWARENESS_LABEL} Awareness`;
  const labelPlacement = getGridlyAwarenessIdentityLabelPlacement(area, labelText);

  if (!countyMode && Number.isFinite(Number(area.lat)) && Number.isFinite(Number(area.lng))) {
    const radiusMeters = gridlyMilesToMeters(area.radiusMiles || DEFAULT_NEARBY_RADIUS_MILES);
    if (radiusMeters > 0 && L.circle) {
      gridlyAwarenessRadiusLayer = L.circle([Number(area.lat), Number(area.lng)], {
        pane: "awarenessIdentityPane",
        radius: radiusMeters,
        color: "#7ce7ff",
        weight: 1.5,
        opacity: 0.5,
        fillColor: "#7ce7ff",
        fillOpacity: 0.045,
        dashArray: "8 10",
        interactive: false,
        className: "gridly-awareness-area-halo"
      }).addTo(gridlyAwarenessIdentityLayer);
    } else {
      warnings.push(`Awareness radius is unavailable for ${area.label}.`);
    }
  }

  const awarenessPanelOwnsIdentity = true;
  if (awarenessPanelOwnsIdentity) {
    warnings.push("Awareness map label suppressed because the Awareness Area panel owns area identity.");
  } else if (L.marker && L.divIcon && Number.isFinite(Number(labelPlacement.latLng?.[0])) && Number.isFinite(Number(labelPlacement.latLng?.[1]))) {
    gridlyAwarenessIdentityLabelLayer = L.marker(labelPlacement.latLng, {
      pane: "awarenessLabelPane",
      interactive: false,
      keyboard: false,
      icon: L.divIcon({
        className: "gridly-awareness-identity-label",
        html: `<span>${safeDisplayText(labelText, "Awareness")}</span>`,
        iconSize: null,
        iconAnchor: labelPlacement.iconAnchor || [0, 0]
      })
    }).addTo(gridlyAwarenessIdentityLayer);
  } else {
    warnings.push(`Awareness label is unavailable for ${area.label}.`);
  }

  return setGridlyAwarenessMapIdentityState({
    selectedAwarenessArea: getGridlyAwarenessAreaDebugOption(area),
    countyBoundaryLoaded: Boolean(gridlyCountyBoundaryGeoJson),
    countyBoundaryVisible: Boolean(gridlyCountyBoundaryLayer && map.hasLayer(gridlyAwarenessIdentityLayer)),
    radiusHaloVisible: Boolean(gridlyAwarenessRadiusLayer && map.hasLayer(gridlyAwarenessIdentityLayer)),
    labelVisible: Boolean(gridlyAwarenessIdentityLabelLayer && map.hasLayer(gridlyAwarenessIdentityLayer)),
    labelPlacement,
    currentFilter: activeGeoFilter || null,
    warnings: warnings.concat(reason ? [`Last render reason: ${reason}`] : []),
    errors
  });
}

async function loadGridlyActiveCountyBoundaryIdentity(reason = "county-boundary-load") {
  if (!gridlyAwarenessIdentityLayer) return renderGridlyAwarenessMapIdentity("boundary-layer-not-ready");
  const activeCountyConfig = gridlyGetActiveCountyConfig();
  const activeCountyBoundaryUrl = gridlyGetActiveCountyRuntimeSources().boundarySource || LIBERTY_COUNTY_BOUNDARY_URL;
  try {
    const response = await fetch(activeCountyBoundaryUrl, { cache: "no-store" });
    if (!response.ok) throw new Error(`${activeCountyConfig.name} boundary returned ${response.status}`);
    const geojson = await response.json();
    const features = Array.isArray(geojson?.features) ? geojson.features : [];
    if (!features.length) throw new Error(`${activeCountyConfig.name} boundary GeoJSON has no features.`);
    gridlyCountyBoundaryGeoJson = geojson;
  } catch (error) {
    gridlyCountyBoundaryGeoJson = null;
    gridlyAwarenessMapIdentityState.errors = [`Unable to load ${activeCountyConfig.name} boundary: ${error?.message || error || "unknown_error"}`];
  }
  return renderGridlyAwarenessMapIdentity(reason);
}

async function loadGridlyLibertyCountyBoundary() {
  return loadGridlyActiveCountyBoundaryIdentity("county-boundary-load");
}

function getGridlyCountyBoundaryOverlaySupportedCountyIds() {
  return GRIDLY_COUNTY_BOUNDARY_OVERLAY_COUNTY_IDS.filter((countyId) => Boolean(GRIDLY_COUNTY_REGISTRY[countyId]));
}

function normalizeGridlyCountyBoundaryOverlayName(value = "") {
  return String(value || "").trim().toLowerCase().replace(/\s+county$/, "").replace(/[^a-z0-9]+/g, "");
}

function getGridlyCountyBoundaryOverlayFeatureGeoid(feature = {}) {
  return String(feature?.properties?.geoid || feature?.properties?.GEOID || feature?.properties?.GEOID20 || "").trim();
}

function getGridlyCountyBoundaryOverlayFeatureName(feature = {}) {
  return String(feature?.properties?.name || feature?.properties?.NAME || feature?.properties?.county || feature?.properties?.COUNTY || "").trim();
}

function getGridlyCountyBoundaryOverlayCountyGeoid(countyId = GRIDLY_DEFAULT_COUNTY_ID) {
  return GRIDLY_COUNTY_BOUNDARY_OVERLAY_GEOID_BY_ID[gridlyNormalizeCountyId(countyId)] || null;
}

function findGridlyCountyBoundaryOverlayFeatureForCounty(features = [], countyId = GRIDLY_DEFAULT_COUNTY_ID) {
  const normalizedCountyId = gridlyNormalizeCountyId(countyId);
  const expectedGeoid = getGridlyCountyBoundaryOverlayCountyGeoid(normalizedCountyId);
  if (expectedGeoid) {
    const geoidMatch = features.find((feature) => getGridlyCountyBoundaryOverlayFeatureGeoid(feature) === expectedGeoid);
    if (geoidMatch) return geoidMatch;
  }
  const expectedName = normalizeGridlyCountyBoundaryOverlayName(GRIDLY_COUNTY_REGISTRY[normalizedCountyId]?.name || normalizedCountyId);
  return features.find((feature) => normalizeGridlyCountyBoundaryOverlayName(getGridlyCountyBoundaryOverlayFeatureName(feature)) === expectedName) || null;
}

function getGridlyCountyBoundaryOverlayStyle(countyId = GRIDLY_DEFAULT_COUNTY_ID) {
  const normalized = gridlyNormalizeCountyId(countyId);
  const active = normalized === gridlyGetActiveCountyId();
  const standardMap = activeBaseLayerName === "Standard" || currentMapStyle === "Standard";
  const darkOrSatellite = activeBaseLayerName === "Dark" || currentMapStyle === "Dark" || activeBaseLayerName === "Satellite" || currentMapStyle === "Satellite";
  const activeCountyFillEnabled = active;
  const activeCountyFillOpacity = active ? (standardMap ? 0.012 : 0.018) : 0;
  const passiveCountyOpacity = 0;
  const passiveCountyWeight = 0;
  return {
    pane: "countyBoundaryOverlayPane",
    color: active ? (standardMap ? "#374151" : "#cbd5e1") : (darkOrSatellite ? "#94a3b8" : "#6b7280"),
    weight: active ? 3 : passiveCountyWeight,
    opacity: active ? (standardMap ? 0.9 : 0.94) : passiveCountyOpacity,
    fill: activeCountyFillEnabled,
    fillColor: active ? (standardMap ? "#111827" : "#f8fafc") : "transparent",
    fillOpacity: active ? (standardMap ? 0.035 : 0.045) : activeCountyFillOpacity,
    dashArray: active ? "" : "3 12",
    lineCap: "round",
    lineJoin: "round",
    interactive: false,
    className: `gridly-county-boundary-overlay${active ? " gridly-county-boundary-overlay-active" : " gridly-county-boundary-overlay-passive"}`
  };
}

function countGridlyCountyBoundaryOverlayCoordinates(geojson) {
  let coordinateCount = 0;
  const walk = (value) => {
    if (!Array.isArray(value)) return;
    if (value.length >= 2 && typeof value[0] === "number" && typeof value[1] === "number") { coordinateCount += 1; return; }
    value.forEach(walk);
  };
  (geojson?.features || []).forEach((feature) => walk(feature?.geometry?.coordinates));
  return coordinateCount;
}

function getGridlyCountyBoundaryOverlayQuality(geojson, sourceType = "unknown") {
  const coordinateCount = countGridlyCountyBoundaryOverlayCoordinates(geojson);
  const sourceFeatureCoordinateCount = (geojson?.features || []).reduce((total, feature) => total + countGridlyCountyBoundaryOverlayCoordinates({ type: "FeatureCollection", features: [feature] }), 0);
  const tooCoarse = coordinateCount > 0 && coordinateCount < GRIDLY_COUNTY_BOUNDARY_OVERLAY_MIN_ACTIVE_COORDINATE_COUNT;
  return {
    sourceType,
    coordinateCount,
    sourceFeatureCoordinateCount,
    minimumRecommendedCoordinateCount: GRIDLY_COUNTY_BOUNDARY_OVERLAY_MIN_ACTIVE_COORDINATE_COUNT,
    tooCoarse,
    pass: coordinateCount >= GRIDLY_COUNTY_BOUNDARY_OVERLAY_MIN_ACTIVE_COORDINATE_COUNT
  };
}

function getGridlyCountyBoundaryOverlayBbox(geojson) {
  const coords = [];
  const walk = (value) => {
    if (!Array.isArray(value)) return;
    if (value.length >= 2 && typeof value[0] === "number" && typeof value[1] === "number") { coords.push(value); return; }
    value.forEach(walk);
  };
  (geojson?.features || []).forEach((feature) => walk(feature?.geometry?.coordinates));
  if (!coords.length) return null;
  const lngs = coords.map((coord) => coord[0]);
  const lats = coords.map((coord) => coord[1]);
  return { west: Math.min(...lngs), south: Math.min(...lats), east: Math.max(...lngs), north: Math.max(...lats) };
}

function renderGridlyCountyBoundaryOverlay(reason = "unknown") {
  if (!map || typeof L === "undefined" || !gridlyCountyBoundaryOverlayLayer) return gridlyCountyBoundaryOverlayAudit({ reason, renderAttempted: false });
  gridlyCountyBoundaryOverlayLayer.clearLayers();
  gridlyCountyBoundaryOverlayLayersById = {};
  // This layer is presentation state owned exclusively by County mode.  In
  // particular, a county bounds camera is never treated as a boundary.
  if (activeGeoFilter !== "county") return gridlyCountyBoundaryOverlayAudit({ reason, renderAttempted: true, hiddenForFilter: true });
  const activeCountyId = gridlyGetActiveCountyId();
  const activeCountyGeoid = getGridlyCountyBoundaryOverlayCountyGeoid(activeCountyId);
  const activeGeojsonRaw = gridlyCountyBoundaryOverlayGeoJsonById[activeCountyId] || null;
  const activeFeatures = Array.isArray(activeGeojsonRaw?.features)
    ? activeGeojsonRaw.features.filter((feature) => !activeCountyGeoid || getGridlyCountyBoundaryOverlayFeatureGeoid(feature) === activeCountyGeoid)
    : [];
  const activeGeojson = activeGeojsonRaw && typeof activeGeojsonRaw === "object" ? { ...activeGeojsonRaw, type: "FeatureCollection", features: activeFeatures } : null;
  gridlyCountyBoundaryGeoJson = activeGeojson;
  if (activeGeojson && activeFeatures.length && L.geoJSON) {
    const layer = L.geoJSON(activeGeojson, { style: () => getGridlyCountyBoundaryOverlayStyle(activeCountyId), interactive: false });
    layer.addTo(gridlyCountyBoundaryOverlayLayer);
    gridlyCountyBoundaryOverlayLayersById[activeCountyId] = layer;
  }
  return gridlyCountyBoundaryOverlayAudit({ reason, renderAttempted: true });
}

function gridlyGetCountyBoundaryRenderSnapshot() {
  const countyId = gridlyGetActiveCountyId();
  const county = GRIDLY_COUNTY_REGISTRY[countyId] || {};
  const geojson = gridlyCountyBoundaryOverlayGeoJsonById[countyId] || null;
  const feature = geojson?.features?.[0] || null;
  const polygonLayer = gridlyCountyBoundaryOverlayLayersById[countyId] || null;
  const polygonLayerCreated = Boolean(polygonLayer);
  const polygonLayerAdded = Boolean(polygonLayer && gridlyCountyBoundaryOverlayLayer);
  const polygonCurrentlyOnMap = Boolean(activeGeoFilter === "county" && polygonLayerAdded && (!map?.hasLayer || map.hasLayer(gridlyCountyBoundaryOverlayLayer)));
  const bounds = getGridlyCountyBoundaryOverlayBbox(geojson);
  const source = gridlyCountyBoundaryOverlaySourceMetadataById[countyId] || {};
  const geometryFound = Boolean(feature?.geometry);
  const stages = [
    ["geometryFound", geometryFound],
    ["polygonLayerCreated", polygonLayerCreated],
    ["polygonLayerAdded", polygonLayerAdded],
    ["polygonCurrentlyOnMap", polygonCurrentlyOnMap]
  ];
  const presentation = gridlyActiveGeographicPresentation || {};
  const resolution = gridlyCountyModeContextResolution || {};
  return Object.freeze({
    countyId,
    countyFips: getGridlyCountyBoundaryOverlayFeatureGeoid(feature) || gridlyExtractCountyGeoid(county),
    countyName: getGridlyCountyBoundaryOverlayFeatureName(feature) || county.name || null,
    geometryType: feature?.geometry?.type || null,
    geometrySource: source.sourcePath || null,
    geometryFound,
    polygonLayerCreated,
    polygonLayerAdded,
    polygonCurrentlyOnMap,
    overlayState: polygonCurrentlyOnMap ? "active" : "inactive-removed",
    fitBoundsSource: activeGeoFilter === "county" && polygonLayerCreated ? "authoritative-county-polygon-layer" : null,
    bounds,
    activeGeoFilter: activeGeoFilter || null,
    activePlaceGeoid: presentation.placeGeoid || null,
    activePlaceLabel: presentation.placeLabel || null,
    activePresentationLat: Number.isFinite(Number(presentation.lat)) ? Number(presentation.lat) : null,
    activePresentationLng: Number.isFinite(Number(presentation.lng)) ? Number(presentation.lng) : null,
    countyResolutionSource: resolution.countyResolutionSource || null,
    resolvedCountyId: resolution.resolvedCountyId || null,
    persistedAwarenessCountyId: resolution.persistedAwarenessCountyId || null,
    stalePersistedContextIgnored: resolution.stalePersistedContextIgnored === true,
    firstFailedStage: activeGeoFilter !== "county" ? "county-overlay-inactive" : (stages.find((entry) => !entry[1])?.[0] || null)
  });
}

if (typeof window !== "undefined") {
  window.gridlyGetCountyBoundaryRenderSnapshot = gridlyGetCountyBoundaryRenderSnapshot;
  if (typeof exposeGridlyAuditHelper === "function") exposeGridlyAuditHelper("gridlyGetCountyBoundaryRenderSnapshot", gridlyGetCountyBoundaryRenderSnapshot);
}

async function loadGridlyCountyBoundaryOverlay() {
  if (gridlyCountyBoundaryOverlayGeoJsonById.__standardTexasLoaded) return renderGridlyCountyBoundaryOverlay("county-boundary-overlay-load");
  try {
    const packageLoader = typeof window !== "undefined" ? window.gridlyLp0361cRuntimeCountyGeometryPackageLoader : null;
    if (!packageLoader?.load) throw new Error("Authoritative production county geometry loader is unavailable.");
    const geometryPackage = await packageLoader.load();
    const packagedCounties = Array.isArray(geometryPackage?.counties) ? geometryPackage.counties : [];
    const supportedCountyIds = new Set(getGridlyCountyBoundaryOverlaySupportedCountyIds());
    gridlyCountyBoundaryOverlayGeoJsonById = { __standardTexasLoaded: true };
    gridlyCountyBoundaryOverlaySourceMetadataById = {};
    for (const county of packagedCounties) {
      const countyId = String(county?.countyId || "").trim().toLowerCase();
      if (!supportedCountyIds.has(countyId) || !county?.geometry) continue;
      const feature = { type: "Feature", properties: { geoid: county.countyFips, name: GRIDLY_COUNTY_REGISTRY[countyId]?.name, countyId }, geometry: county.geometry };
      gridlyCountyBoundaryOverlayGeoJsonById[countyId] = { type: "FeatureCollection", features: [feature] };
      gridlyCountyBoundaryOverlaySourceMetadataById[countyId] = { sourceType: "authoritative_production_package", sourcePath: GRIDLY_AUTHORITATIVE_PRODUCTION_COUNTY_GEOMETRY_PATH, payloadScope: "governed_operational_counties" };
    }

    const activeCountyId = gridlyGetActiveCountyId();
    if (!gridlyCountyBoundaryOverlayGeoJsonById[activeCountyId]) {
      const countyBoundaryPath = gridlyGetCountyRuntimeSources(activeCountyId)?.boundarySource || null;
      if (countyBoundaryPath && countyBoundaryPath !== GRIDLY_AUTHORITATIVE_PRODUCTION_COUNTY_GEOMETRY_PATH) {
        try {
          const countyResponse = await fetch(countyBoundaryPath, { cache: "no-store" });
          if (!countyResponse.ok) throw new Error(`County-specific boundary returned ${countyResponse.status}`);
          const countyGeojson = await countyResponse.json();
          const expectedGeoid = getGridlyCountyBoundaryOverlayCountyGeoid(activeCountyId);
          const countyFeatures = (Array.isArray(countyGeojson?.features) ? countyGeojson.features : [])
            .filter((feature) => !expectedGeoid || getGridlyCountyBoundaryOverlayFeatureGeoid(feature) === expectedGeoid);
          if (!countyFeatures.length) throw new Error("County-specific boundary GeoJSON has no active county features.");
          gridlyCountyBoundaryOverlayGeoJsonById[activeCountyId] = { ...countyGeojson, type: "FeatureCollection", features: countyFeatures };
          gridlyCountyBoundaryOverlaySourceMetadataById[activeCountyId] = { sourceType: "county_specific_active", sourcePath: countyBoundaryPath, payloadScope: GRIDLY_ACTIVE_COUNTY_BOUNDARY_PAYLOAD_SCOPE };
        } catch (countyError) {
          console.warn(`[Gridly] County-specific boundary fallback failed for ${activeCountyId}`, countyError);
        }
      }
    }
    gridlyCountyBoundaryGeoJson = gridlyCountyBoundaryOverlayGeoJsonById[gridlyGetActiveCountyId()] || null;
  } catch (error) {
    console.warn("[Gridly] County boundary overlay load failed", error);
  }
  return renderGridlyCountyBoundaryOverlay("county-boundary-overlay-load");
}

function gridlyGetStaleRuntimeBoundaryAssetPaths(countyId = gridlyGetActiveCountyId()) {
  const normalizedCountyId = gridlyNormalizeCountyId(countyId);
  const countyConfig = GRIDLY_COUNTY_REGISTRY[normalizedCountyId] || {};
  const runtimeSources = gridlyGetCountyRuntimeSources(normalizedCountyId) || {};
  return [countyConfig.boundaryPath, runtimeSources.boundarySource]
    .filter((path, index, paths) => Boolean(path) && paths.indexOf(path) === index)
    .filter((path) => /\/runtime-assets\//i.test(path) && /boundary[^/]*\.geojson(?:$|[?#])/i.test(path));
}


