    structuredMetadataOwnership: structuredMetadataObserved ? "canonicalRoadContext" : "not_observed", normalizedOwnership: normalizedReportObserved ? "normalizedReport.canonicalRoadContext" : "not_observed", canonicalOwnership: canonicalIncidentObserved ? "canonicalRoadContext" : "not_observed", alertOwnership: renderedConsumerObserved ? "LP023 consumerLocation" : "not_observed", popupOwnership: renderedConsumerObserved ? "LP023 popup adapters" : "not_observed",
