function findNearestRoadwaySegment(lat, lng, maxDistanceMiles = 1.2) {
  if (!gridlyCountyRuntimeSourceAvailable("roads") || !roadwayDatasetLoaded || !Array.isArray(roadwaySegmentFeatures) || !roadwaySegmentFeatures.length) return null;
  let best = null;
  for (const feature of roadwaySegmentFeatures) {
    if (typeof gridlySelectedAwarenessAreaResolutionCache !== "undefined") gridlySelectedAwarenessAreaResolutionCache.roadCandidateCount = Number(gridlySelectedAwarenessAreaResolutionCache.roadCandidateCount || 0) + 1;
    const segments = flattenRoadGeometrySegments(feature?.geometry);
    for (const segment of segments) {
      const distance = distancePointToSegmentMiles(lat, lng, segment.startLat, segment.startLng, segment.endLat, segment.endLng);
      if (!Number.isFinite(distance)) continue;
      if (!best || distance < best.distanceMiles) {
        best = {
          feature,
          distanceMiles: distance
        };
      }
    }
  }
  if (!best || !Number.isFinite(best.distanceMiles) || best.distanceMiles > maxDistanceMiles) return null;
  return best;
}

function flattenRoadGeometrySegments(geometry) {
  if (!geometry || !geometry.type) return [];
  if (geometry.type === "LineString") return lineCoordinatesToSegments(geometry.coordinates);
  if (geometry.type === "MultiLineString") {
    return geometry.coordinates.flatMap((line) => lineCoordinatesToSegments(line));
  }
  return [];
}

function lineCoordinatesToSegments(lineCoordinates) {
  if (!Array.isArray(lineCoordinates) || lineCoordinates.length < 2) return [];
  const segments = [];
  for (let i = 1; i < lineCoordinates.length; i += 1) {
    const start = lineCoordinates[i - 1];
    const end = lineCoordinates[i];
    const startLng = Number(start?.[0]);
    const startLat = Number(start?.[1]);
    const endLng = Number(end?.[0]);
    const endLat = Number(end?.[1]);
    if (![startLat, startLng, endLat, endLng].every(Number.isFinite)) continue;
    segments.push({ startLat, startLng, endLat, endLng });
  }
  return segments;
}

function projectPointToRoadSegment(lat, lng, startLat, startLng, endLat, endLng) {
  const scale = Math.cos(toRad((startLat + endLat + lat) / 3));
  const pointX = lng * scale;
  const startX = startLng * scale;
  const endX = endLng * scale;
  const pointY = lat;
  const startY = startLat;
  const endY = endLat;
  const dx = endX - startX;
  const dy = endY - startY;
  const lengthSquared = dx * dx + dy * dy;
  if (lengthSquared <= 0) {
    return {
      distanceMiles: haversineDistance(lat, lng, startLat, startLng),
      coordinate: { lat: startLat, lng: startLng },
      segmentBearing: gridlyRoadBearingDegrees(startLat, startLng, endLat, endLng),
      segmentStart: { lat: startLat, lng: startLng },
      segmentEnd: { lat: endLat, lng: endLng }
    };
  }
  let t = ((pointX - startX) * dx + (pointY - startY) * dy) / lengthSquared;
  t = Math.max(0, Math.min(1, t));
  const projX = startX + t * dx;
  const projY = startY + t * dy;
  const projLng = scale === 0 ? startLng : projX / scale;
  const projLat = projY;
  return {
    distanceMiles: haversineDistance(lat, lng, projLat, projLng),
    coordinate: { lat: projLat, lng: projLng },
    segmentBearing: gridlyRoadBearingDegrees(startLat, startLng, endLat, endLng),
    segmentStart: { lat: startLat, lng: startLng },
    segmentEnd: { lat: endLat, lng: endLng }
  };
}

function distancePointToSegmentMiles(lat, lng, startLat, startLng, endLat, endLng) {
  return projectPointToRoadSegment(lat, lng, startLat, startLng, endLat, endLng).distanceMiles;
}

function gridlyRoadBearingDegrees(startLat, startLng, endLat, endLng) {
  const lat1 = toRad(Number(startLat));
  const lat2 = toRad(Number(endLat));
  const deltaLng = toRad(Number(endLng) - Number(startLng));
  if (![lat1, lat2, deltaLng].every(Number.isFinite)) return null;
  const y = Math.sin(deltaLng) * Math.cos(lat2);
  const x = Math.cos(lat1) * Math.sin(lat2) - Math.sin(lat1) * Math.cos(lat2) * Math.cos(deltaLng);
  const degrees = (Math.atan2(y, x) * 180 / Math.PI + 360) % 360;
  return Number.isFinite(degrees) ? Math.round(degrees * 10) / 10 : null;
}

async function fetchFraCrossingsWithRetry(countyId = gridlyGetActiveCountyId()) {
  const normalizedCountyId = gridlyNormalizeCountyId(countyId);
  const countyConfig = GRIDLY_COUNTY_REGISTRY[normalizedCountyId];
  const governedResolver = window.gridlyRuntimeSourceRegistryBridge?.resolveGovernedCrossingSource;
  if (typeof governedResolver !== "function") throw new Error("Governed statewide Crossing resolver unavailable");
  const governedSource = await governedResolver({
    county: String(countyConfig?.name || "").replace(/\s+County$/i, ""),
    countyFips: countyConfig?.countyFips
  });
  gridlyRecordCrossingHydrationTrace("GOVERNED_SOURCE_RESOLVED", { countyId: normalizedCountyId, sourcePath: governedSource.packageFile || null, recordCount: governedSource.governedCount });
  if (governedSource.state === "ACTIVE_EMPTY") {
    return new Response(JSON.stringify({ type: "FeatureCollection", features: [] }), {
      status: 200,
      headers: { "Content-Type": "application/json" }
    });
  }

  const activeSources = Object.assign({}, gridlyGetCountyRuntimeSources(normalizedCountyId), {
    crossingSource: governedSource.packageFile,
    remoteCrossingSource: null
  });

  if (typeof window !== "undefined" && typeof window.gridlyGetActiveCountyCrossings === "function") {
    try {
      gridlyRecordCrossingHydrationTrace("PACKAGE_FETCH_STARTED", { countyId: normalizedCountyId, sourcePath: governedSource.packageFile });
      const providerGeojson = await window.gridlyGetActiveCountyCrossings({
        countyId: normalizedCountyId,
        sourcePath: governedSource.packageFile
      });
      gridlyRecordCrossingHydrationTrace("PACKAGE_FETCH_SUCCEEDED", { countyId: normalizedCountyId, sourcePath: governedSource.packageFile, recordCount: Array.isArray(providerGeojson?.features) ? providerGeojson.features.length : 0 });

      const providerFeatureCount = Array.isArray(providerGeojson?.features) ? providerGeojson.features.length : 0;
      if (providerFeatureCount !== governedSource.governedCount) {
        throw new Error(`Governed Crossing count mismatch for ${governedSource.county}: expected ${governedSource.governedCount}, loaded ${providerFeatureCount}`);
      }
      const providerCrossingIds = providerGeojson.features.map((feature, index) => {
        const properties = feature?.properties && typeof feature.properties === "object" ? feature.properties : {};
        const identity = properties.CROSSING || properties.crossing || properties.crossing_id || properties.crossingId || properties.id || feature?.id;
        return identity !== undefined && identity !== null && String(identity).trim() ? String(identity).trim() : `index:${index}`;
      });
      if (new Set(providerCrossingIds).size !== providerCrossingIds.length) {
        throw new Error(`Governed Crossing duplicate identity for ${governedSource.county}`);
      }
      // LP202.1's governed registry entry, county manifest, production record,
      // package path, and exact count jointly own package assignment. Individual
      // FRA rows are not a package ownership guard: governed metro packages can
      // intentionally retain crossings whose source-reported FIPS differs from
      // the package county (Dallas has nine such rows among its governed 789).

      // A full provider audit loads its historical Liberty fixtures and then
      // performs a second, optionless active-county load. That diagnostic path
      // still consults legacy runtimeSourceAvailability and rejects governed
      // statewide counties such as Dallas after their requested package has
      // already loaded successfully. Keep diagnostics out of the commit path;
      // the completed provider trace is the authority for this load's mode.
      const providerMode = window.gridlyCrossingProvider?.getLastLoadTrace?.()?.mode || "unknown";

      const providerResponse = new Response(
        JSON.stringify(providerGeojson || { type: "FeatureCollection", features: [] }),
        {
          status: 200,
          headers: { "Content-Type": "application/json" }
        }
      );

      providerResponse.gridlyCrossingSource = `crossing_provider_${providerMode}`;
      providerResponse.gridlyCrossingSourcePath = governedSource.packageFile;

      recordGridlyCrossingFallbackAudit("crossingProviderRuntimeSourceUsed", {
        providerRuntimeIntegrationActive: true,
        providerMode,
        sourceUsed: `crossing_provider_${providerMode}`,
        lastFetchSource: `crossing_provider_${providerMode}`,
        providerFeatureCount: Array.isArray(providerGeojson?.features) ? providerGeojson.features.length : 0,
        remoteAttempted: false,
        remoteFetchSucceeded: false,
        fallbackUsed: false,
        localCrossingFallbackUsed: false
      });

      return providerResponse;
    } catch (providerError) {
      recordGridlyCrossingFallbackAudit("crossingProviderRuntimeSourceFailed", {
        providerRuntimeIntegrationActive: true,
        providerFailureReason: String(providerError?.message || providerError || "unknown_error"),
        providerFallbackToExistingPath: false
      });
      throw providerError;
    }
  }

  const remoteCrossingUrl = activeSources?.remoteCrossingSource || null;
  const localCrossingUrl = activeSources?.crossingSource || null;
  let lastError = null;

  if (remoteCrossingUrl) for (let attempt = 1; attempt <= CROSSING_FETCH_RETRY_ATTEMPTS; attempt += 1) {
    try {
      recordGridlyCrossingFallbackAudit("remoteFraFetchAttempt", {
        remoteUrlUsed: remoteCrossingUrl,
        remoteAttempted: true,
        remoteFetchSucceeded: false,
        remoteFetchFailedReason: null,
        fetchMode: "cors-default",
        cacheMode: "default",
        sourceUsed: null
      });

      const response = await fetch(remoteCrossingUrl, GRIDLY_REMOTE_CROSSING_FETCH_OPTIONS);

      if (!response.ok) {
        throw new Error(`FRA feed returned ${response.status}`);
      }

      response.gridlyCrossingSource = "remote_fra";
      recordGridlyCrossingFallbackAudit("remoteFraFetchSucceeded", {
        remoteUrlUsed: remoteCrossingUrl,
        remoteAttempted: true,
        remoteFetchSucceeded: true,
        remoteFetchFailedReason: null,
        fallbackUsed: false,
        localCrossingFallbackUsed: false,
        sourceUsed: "remote_fra",
        lastFetchSource: "remote_fra",
        fetchMode: "cors-default",
        cacheMode: "default"
      });

      return response;
    } catch (error) {
      lastError = error;
      if (attempt < CROSSING_FETCH_RETRY_ATTEMPTS) {
        if (isGridlyExplicitDebugModeEnabled()) {
          console.info(`FRA crossing fetch attempt ${attempt} failed. Retrying...`, error);
        }
        await wait(CROSSING_FETCH_RETRY_DELAY_MS * attempt);
      }
    }
  }

  if (localCrossingUrl) {
    try {
      if (remoteCrossingUrl) {
        recordGridlyCrossingFallbackAudit("remoteFraFetchFailed", {
          remoteFraFetchFailed: true,
          remoteFraFetchFailureReason: String(lastError?.message || lastError || "unknown_error"),
          remoteFetchFailedReason: String(lastError?.message || lastError || "unknown_error"),
          remoteFetchSucceeded: false
        });
      }

      if (isGridlyExplicitDebugModeEnabled()) {
        console.info(
          remoteCrossingUrl
            ? "FRA crossing fetch failed. Loading local crossing fallback..."
            : "Loading active county crossing runtime source...",
          lastError
        );
      }

      const fallbackResponse = await fetch(localCrossingUrl, GRIDLY_LOCAL_CROSSING_FETCH_OPTIONS);

      if (!fallbackResponse.ok) {
        throw new Error(`Local crossing fallback returned ${fallbackResponse.status}`);
      }

      fallbackResponse.gridlyCrossingSource = remoteCrossingUrl ? "local_fallback" : "county_runtime_source";

      recordGridlyCrossingFallbackAudit("localCrossingFallbackUsed", {
        localCrossingFallbackUsed: Boolean(remoteCrossingUrl),
        localCrossingFallbackReachable: true,
        fallbackUsed: Boolean(remoteCrossingUrl),
        sourceUsed: remoteCrossingUrl ? "local_fallback" : "county_runtime_source",
        lastFetchSource: remoteCrossingUrl ? "local_fallback" : "county_runtime_source",
        cacheMode: "no-store",
        fetchMode: "cors-default"
      });

      return fallbackResponse;
    } catch (fallbackError) {
      throw new Error(`FRA crossing fetch failed and local fallback failed: ${fallbackError?.message || fallbackError}`);
    }
  }

  throw lastError || new Error("No active county crossing source is available");
}

function ensureGridlyActiveCountyCrossingInventory(reason = "unspecified") {
  const activeCountyId = gridlyGetActiveCountyId();
  if (typeof gridlyRecordCommunityTransitionStage === "function") gridlyRecordCommunityTransitionStage("crossing_source_resolution", { subsystem: "crossing", subsystemCounty: activeCountyId, authoritativeCounty: activeCountyId, previousValue: gridlyCrossingInventoryCountyId, newValue: activeCountyId, staleState: gridlyCrossingInventoryCountyId && gridlyCrossingInventoryCountyId !== activeCountyId ? "cleared_or_reloaded_by_lp202.2" : "retained_if_current", reason });
  gridlyRecordCrossingHydrationTrace("HYDRATION_ENSURE_ENTER", { countyId: activeCountyId, reason });
  // An empty governed inventory is loaded state, not a cache miss.
  if (gridlyCrossingInventoryCountyId === activeCountyId && Array.isArray(crossings)) {
    gridlyRecordCrossingHydrationTrace("HYDRATION_ALREADY_HEALTHY", { countyId: activeCountyId });
    return false;
  }
  if (gridlyCrossingInventoryReloadPromise && gridlyCrossingInventoryReloadPromise.gridlyTargetCountyId === activeCountyId) {
    gridlyRecordCrossingHydrationTrace("HYDRATION_INFLIGHT_REUSED", { countyId: activeCountyId });
    return true;
  }
  gridlyCrossingInventoryHydrationState = { countyId: activeCountyId, attempted: true, completed: false, failureReason: null, reason };
  if (Array.isArray(crossings) && crossings.length && gridlyCrossingInventoryCountyId !== activeCountyId) {
    crossings = [];
    if (crossingMarkers instanceof Map) {
      crossingMarkers.forEach((marker) => { try { crossingLayer?.removeLayer?.(marker); } catch (_error) {} });
      crossingMarkers.clear();
    }
    safeText("crossingCount", "Loading");
  }
  const reload = loadCrossings().finally(() => {
    if (gridlyCrossingInventoryReloadPromise === reload) gridlyCrossingInventoryReloadPromise = null;
  });
  reload.gridlyTargetCountyId = activeCountyId;
  reload.gridlyReason = reason;
  gridlyCrossingInventoryReloadPromise = reload;
  return true;
}

function wait(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

function inferCrossingCity(crossingName, props = {}) {
  const localityValues = [props.city, props.cityname, props.CITYNAME, props.community, props.place, props.inc_city, props.nearcity, props.municipality]
    .filter((value) => value && !/^unassigned$/i.test(String(value).trim()));
  const valuePool = [
    crossingName,
    ...localityValues
  ]
    .filter(Boolean)
    .map((value) => String(value).toLowerCase());

  for (const rule of LIBERTY_COUNTY_CITY_RULES) {
    if (rule.patterns.some((pattern) => valuePool.some((value) => value.includes(pattern)))) {
      return rule.city;
    }
  }

  if (localityValues.length) {
    return String(localityValues[0]).trim().toLowerCase().replace(/\b[a-z]/g, (letter) => letter.toUpperCase());
  }
  return "Unassigned";
}

function buildRegionKey({ country, state, county, city }) {
  return [country, state, county, city].map(toRegionSlug).join(".");
}

function toRegionSlug(value) {
  return String(value || "")
    .trim()
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "");
}

async function loadCrossingReviewOverrides() {
  try {
    const activeCrossingReviewOverridesUrl = gridlyGetActiveCountyRuntimeSources()?.crossingOverridesSource || null;
    if (!activeCrossingReviewOverridesUrl) return {};
    const response = await fetch(activeCrossingReviewOverridesUrl, {
      cache: "no-store"
    });

    if (!response.ok) {
      if (isGridlyExplicitDebugModeEnabled()) console.warn("Crossing review override file not found. Falling back to raw FRA data.");
      return {};
    }

    return await response.json();
  } catch (error) {
    if (isGridlyExplicitDebugModeEnabled()) console.warn("Unable to load crossing review overrides:", error);
    return {};
  }
}

function shouldShowCrossingInLaunchMode(crossing) {
  const review = crossing.review || {};
  const visibility = review.visibility || "unreviewed";
  const localName = String(review.localName || "").trim();

  if (visibility === "hide") return false;

  if (visibility === "keep") return true;

  if (["local_fallback", "county_runtime_source", "crossing_provider_legacy", "crossing_provider_package", "crossing_provider_fra-review", "crossing_provider_production"].includes(String(crossing.source || "").trim())) return true;

  if (localName.length > 0) return true;

  return false;
}
function refreshReportHazardViews(source = "unspecified") {
  const endRefreshHazardTrace = timeGridlyReflowTrace("refreshReportHazardViews", source);
  gridlyRefreshAuditState.totalRefreshCount += 1;
  gridlyRefreshAuditState.refreshSourceCounts[source] = (gridlyRefreshAuditState.refreshSourceCounts[source] || 0) + 1;
  gridlyRefreshAuditState.lastRefreshAt = Date.now();
  crossingRenderReportsVersion += 1;
  gridlyRefreshCycleCache = createGridlyRefreshCycleCache();
  try {
    const childDurations = {};
    const timeRefreshChild = (name, fn) => {
      const start = performance.now();
      fn();
      childDurations[name] = Number((performance.now() - start).toFixed(2));
    };
    const refreshLayoutModeIsDesktop = evaluateLayoutMode() === "desktop";
    // Build the authoritative active model before the Portrait writer consumes
    // it.  Previously desktop performed this in the opposite order, allowing a
    // cached quiet/coverage model to become the final visible writer.
    timeRefreshChild("refreshGridlyCommunityPulseSharedModel", () => refreshGridlyCommunityPulseSharedModel({ reason: source, topAwarenessMicrolineReadOnly: true }));
    timeRefreshChild("refreshPortraitV2LocalizedIntelligence", () => refreshPortraitV2LocalizedIntelligence());
    gridlyRefreshAuditState.renderCounts.renderUnifiedIncidents += 1;
    timeRefreshChild("renderUnifiedIncidents", () => renderUnifiedIncidents());
    timeRefreshChild("renderDriveTexasOfficialMarkers", () => renderGridlyDriveTexasOfficialMarkers(source));
    gridlyRefreshAuditState.renderCounts.scheduleRenderCrossings += 1;
    timeRefreshChild("scheduleRenderCrossings", () => scheduleRenderCrossings("state-change"));
    // Alerts owns a real DOM collection in portrait and desktop layouts.
    // Creating generic items cannot be conditional on desktop layout.
    gridlyRefreshAuditState.renderCounts.renderAlerts += 1;
    timeRefreshChild("renderAlerts", () => renderAlerts());
    if (refreshLayoutModeIsDesktop) {
      gridlyRefreshAuditState.renderCounts.renderRoadHazards += 1;
      timeRefreshChild("renderRoadHazards", () => renderRoadHazards());
      gridlyRefreshAuditState.renderCounts.renderTrendingCrossings += 1;
      timeRefreshChild("renderTrendingCrossings", () => renderTrendingCrossings());
      gridlyRefreshAuditState.renderCounts.updateRouteIntelligence += 1;
      timeRefreshChild("updateRouteIntelligence", () => updateRouteIntelligence());
      timeRefreshChild("updateTrustStats", () => updateTrustStats());
      timeRefreshChild("updateGrowthWidgets", () => updateGrowthWidgets());
      timeRefreshChild("renderGridlyCommunityPulse", () => renderGridlyCommunityPulse({ reason: source }));
      timeRefreshChild("renderGridlyIntelligencePreviewCard", () => renderGridlyIntelligencePreviewCard({ reason: source }));
    }
    timeRefreshChild("updateDailyHabitStatus", () => updateDailyHabitStatus());
    timeRefreshChild("updateMobileAlertsMirror", () => updateMobileAlertsMirror());
    timeRefreshChild("evaluateSmartAlertsBanner", () => evaluateSmartAlertsBanner());
    timeRefreshChild("updateLastUpdated", () => updateLastUpdated());
    timeRefreshChild("recomputeMovementIntelligence", () => recomputeMovementIntelligence());
    timeRefreshChild("updateCorridorSummaryCards", () => updateCorridorSummaryCards());
    const childDurationTotal = Object.values(childDurations).reduce((total, duration) => total + (Number.isFinite(duration) ? duration : 0), 0);
    const refreshDuration = Number(childDurationTotal.toFixed(2));
    gridlyRefreshAuditState.lastRefreshDuration = refreshDuration;
    gridlyRefreshAuditState.lastChildDurations = childDurations;
    const unifiedIncidents = getUnifiedIncidents();
    const safeHazardMarkerCount = (typeof hazardMarkers !== "undefined" && Array.isArray(hazardMarkers))
      ? hazardMarkers.length
      : null;
    const safeRoadHazardMarkerCount = (typeof roadHazardMarkers !== "undefined" && Array.isArray(roadHazardMarkers))
      ? roadHazardMarkers.length
      : null;
    const safeCrossingMarkerCount = (typeof crossingMarkers !== "undefined" && crossingMarkers && typeof crossingMarkers.size === "number")
      ? crossingMarkers.size
      : null;
    const renderedMarkerCount = [safeHazardMarkerCount, safeRoadHazardMarkerCount, safeCrossingMarkerCount].every((count) => typeof count === "number")
      ? (safeHazardMarkerCount + safeRoadHazardMarkerCount + safeCrossingMarkerCount)
      : "unknown";
    const refreshSummary = {
      at: gridlyRefreshAuditState.lastRefreshAt,
      iso: new Date(gridlyRefreshAuditState.lastRefreshAt).toISOString(),
      source,
      durationMs: refreshDuration,
      childDurations: { ...childDurations },
      itemCounts: {
        alertCount: Array.isArray(activeReports) ? activeReports.length : 0,
        unifiedIncidentCount: Array.isArray(unifiedIncidents) ? unifiedIncidents.length : 0,
        roadHazardCount: Array.isArray(activeHazards) ? activeHazards.length : 0,
        crossingCount: Array.isArray(crossings) ? crossings.length : 0,
        renderedMarkerCount,
        routeIntelligenceState: routeWatchActivated ? "active" : "idle"
      }
    };
    gridlyRefreshAuditState.recentRefreshes.push(refreshSummary);
    recordGridlyActiveLocationLifecycleEvent("refreshReportHazardViews", {
      source,
      durationMs: refreshDuration,
      childDurations: { ...childDurations },
      itemCounts: { ...refreshSummary.itemCounts }
    });
    if (gridlyRefreshAuditState.recentRefreshes.length > GRIDLY_REFRESH_BREAKDOWN_LOG_LIMIT) {
      gridlyRefreshAuditState.recentRefreshes.splice(0, gridlyRefreshAuditState.recentRefreshes.length - GRIDLY_REFRESH_BREAKDOWN_LOG_LIMIT);
    }
  } finally {
    gridlyIntelligenceCacheAuditState.active = false;
    gridlyRefreshCycleCache = null;
    endRefreshHazardTrace();
  }
}

const GRIDLY_TEST_DATA_CLEAR_CONFIRMATION = "CLEAR_TEST_DATA";

const GRIDLY_TEST_DATA_SHARED_SUPPRESSION_MS = 10 * 60 * 1000;
const gridlyDevCleanupSharedSuppressionState = {
  active: false,
  suppressUntil: 0,
  startedAt: 0,
  reason: "",
  reportIds: new Set(),
  reportKeys: new Set(),
  deviceIds: new Set(),
  suppressedCount: 0,
  lastSuppressedCount: 0,
  lastReloadSource: "",
  reloadSources: [],
  samples: []
};

function gridlyBuildSharedReportSuppressionKey(report = {}) {
  const kind = String(report?.reportKind || (report?.crossingId || report?.crossing_id ? "crossing" : "hazard")).toLowerCase();
  const type = String(report?.type || report?.report_type || "other").toLowerCase();
  const crossingId = String(report?.crossingId || report?.crossing_id || "").trim();
  const latNum = Number(report?.lat ?? report?.latitude ?? report?.rawLat);
  const lngNum = Number(report?.lng ?? report?.lon ?? report?.longitude ?? report?.rawLng);
  const lat = Number.isFinite(latNum) ? latNum.toFixed(4) : "na";
  const lng = Number.isFinite(lngNum) ? lngNum.toFixed(4) : "na";
  return `${kind}|${type}|${crossingId || "no-crossing"}|${lat}|${lng}`;
}

function gridlyArmDevCleanupSharedSuppression(records = [], options = {}) {
  const now = Date.now();
  const suppressMs = Math.max(60 * 1000, Number(options?.suppressMs) || GRIDLY_TEST_DATA_SHARED_SUPPRESSION_MS);
  gridlyDevCleanupSharedSuppressionState.active = true;
  gridlyDevCleanupSharedSuppressionState.suppressUntil = now + suppressMs;
  gridlyDevCleanupSharedSuppressionState.startedAt = now;
  gridlyDevCleanupSharedSuppressionState.reason = options?.reason || "gridlyClearTestData";
  gridlyDevCleanupSharedSuppressionState.reportIds = new Set();
  gridlyDevCleanupSharedSuppressionState.reportKeys = new Set();
  gridlyDevCleanupSharedSuppressionState.deviceIds = new Set([String(deviceId || "").trim()].filter(Boolean));
  gridlyDevCleanupSharedSuppressionState.suppressedCount = 0;
  gridlyDevCleanupSharedSuppressionState.lastSuppressedCount = 0;
  gridlyDevCleanupSharedSuppressionState.lastReloadSource = "";
  gridlyDevCleanupSharedSuppressionState.reloadSources = [];
  gridlyDevCleanupSharedSuppressionState.samples = [];

  (Array.isArray(records) ? records : []).forEach((record) => {
    const id = String(record?.id || "").trim();
    if (id) gridlyDevCleanupSharedSuppressionState.reportIds.add(id);
    const key = gridlyBuildSharedReportSuppressionKey(record);
    if (key) gridlyDevCleanupSharedSuppressionState.reportKeys.add(key);
    const recordDeviceId = String(record?.deviceId || record?.device_id || "").trim();
    if (recordDeviceId) gridlyDevCleanupSharedSuppressionState.deviceIds.add(recordDeviceId);
  });

  return {
    active: true,
    suppressUntil: gridlyDevCleanupSharedSuppressionState.suppressUntil,
    suppressUntilIso: new Date(gridlyDevCleanupSharedSuppressionState.suppressUntil).toISOString(),
    reportIdCount: gridlyDevCleanupSharedSuppressionState.reportIds.size,
    reportKeyCount: gridlyDevCleanupSharedSuppressionState.reportKeys.size,
    deviceIdCount: gridlyDevCleanupSharedSuppressionState.deviceIds.size
  };
}

function gridlyShouldSuppressSharedReportDuringDevCleanup(report = {}, reason = "") {
  const state = gridlyDevCleanupSharedSuppressionState;
  const now = Date.now();
  if (!state.active || now > state.suppressUntil) {
    state.active = false;
    return false;
  }
  const id = String(report?.id || "").trim();
  const reportDeviceId = String(report?.deviceId || report?.device_id || "").trim();
  const submittedAtMs = new Date(report?.submittedAt || report?.created_at || 0).getTime();
  const isCleanupCandidateWindow = Number.isFinite(submittedAtMs)
    && submittedAtMs > 0
    && submittedAtMs >= state.startedAt - (24 * 60 * 60 * 1000)
    && submittedAtMs <= state.startedAt;
  const suppressed = Boolean(
    (id && state.reportIds.has(id)) ||
    state.reportKeys.has(gridlyBuildSharedReportSuppressionKey(report)) ||
    (reportDeviceId && state.deviceIds.has(reportDeviceId) && isCleanupCandidateWindow)
  );
  if (suppressed) {
    state.suppressedCount += 1;
    state.lastSuppressedCount += 1;
    state.lastReloadSource = reason;
    if (!state.reloadSources.includes(reason)) state.reloadSources.push(reason);
    if (state.samples.length < 5) {
      state.samples.push({ id: id || null, type: report?.type || report?.report_type || null, reportKind: report?.reportKind || null, source: report?.source || null, deviceId: reportDeviceId || null });
    }
  }
  return suppressed;
}

function gridlyGetDevCleanupSuppressionAudit() {
  const state = gridlyDevCleanupSharedSuppressionState;
  return {
    active: Boolean(state.active && Date.now() <= state.suppressUntil),
    suppressUntilIso: state.suppressUntil ? new Date(state.suppressUntil).toISOString() : null,
    suppressedSharedReportsCount: state.suppressedCount,
    lastSuppressedSharedReportsCount: state.lastSuppressedCount,
    reloadSource: state.lastReloadSource || (state.reloadSources.length ? state.reloadSources[state.reloadSources.length - 1] : (state.active && Date.now() <= state.suppressUntil ? "suppression_armed_waiting_for_shared_reload" : "none")),
    reloadSources: [...state.reloadSources],
    reportIdCount: state.reportIds.size,
    reportKeyCount: state.reportKeys.size,
    deviceIdCount: state.deviceIds.size,
    samples: [...state.samples]
  };
}

function gridlyGetProtectedCleanupStorageKeys() {
  return [
    SAVED_PLACES_STORAGE_KEY,
    SELECTED_PLACE_STORAGE_KEY,
    GRIDLY_SETTINGS_STORAGE_KEY,
    MAP_STYLE_STORAGE_KEY,
    GRIDLY_PROFILE_STORAGE_KEY,
    SMART_ALERTS_STORAGE_KEY,
    SMART_ALERTS_DRAWER_SEEN_KEY,
    MAP_FIRST_HINT_SEEN_KEY,
    MOVEMENT_INTELLIGENCE_STORAGE_KEY,
    COMMUTE_BASELINE_SAMPLES_STORAGE_KEY,
    "gridlyHome",
    "gridlyWork"
  ].filter(Boolean);
}

function gridlyIsProtectedCleanupStorageKey(key = "") {
  const protectedKeys = new Set(gridlyGetProtectedCleanupStorageKeys());
  return protectedKeys.has(String(key || ""));
}

function gridlyGetTestArtifactStorageKeys() {
  if (typeof localStorage === "undefined") return [];
  const artifactMatcher = /^gridly(?:Local)?(?:Test|Dev).*(?:Report|Reports|Hazard|Hazards|Artifact|Artifacts|Cache|Telemetry|Event|Events|History)$/i;
  const staleSavedReportMatcher = /^gridly.*(?:Test|Dev|Local).*(?:Saved)?Report.*(?:Artifact|Draft|Cache|History)?$/i;
  const keys = [];
  try {
    for (let i = 0; i < localStorage.length; i += 1) {
      const key = localStorage.key(i);
      if (!key || gridlyIsProtectedCleanupStorageKey(key)) continue;
      if (artifactMatcher.test(key) || staleSavedReportMatcher.test(key)) keys.push(key);
    }
  } catch (_error) {
    return [];
  }
  return keys.sort();
}

function gridlyReadCleanupEventHistoryCounts() {
  const raw = gridlySafeLocalStorageGet(GRIDLY_EVENT_HISTORY_STORAGE_KEY);
  if (!raw) return { crossingEvents: 0, hazardEvents: 0, telemetryFields: 0, parseError: false };
  try {
    const parsed = JSON.parse(raw);
    const crossingEvents = Array.isArray(parsed?.crossingEvents) ? parsed.crossingEvents.length : 0;
    const hazardEvents = Array.isArray(parsed?.hazardEvents) ? parsed.hazardEvents.length : 0;
    const telemetry = parsed?.operationalTelemetry && typeof parsed.operationalTelemetry === "object" ? parsed.operationalTelemetry : {};
    const telemetryFields = Object.values(telemetry).filter((value) => {
      if (typeof value === "number") return value > 0;
      return Boolean(value);
    }).length;
    return { crossingEvents, hazardEvents, telemetryFields, parseError: false };
  } catch (_error) {
    return { crossingEvents: 0, hazardEvents: 0, telemetryFields: 1, parseError: true };
  }
}

function gridlyBuildTestDataCleanupAudit(options = {}) {
  const historyCounts = gridlyReadCleanupEventHistoryCounts();
  const artifactKeys = gridlyGetTestArtifactStorageKeys();
  const reportCount = Array.isArray(activeReports) ? activeReports.length : 0;
  const hazardCount = Array.isArray(activeHazards) ? activeHazards.length : 0;
  const telemetryQualityCount = Number(gridlyCrossingEventQualityTelemetry?.duplicateCrossingEventsSuppressed || 0) > 0 ? 1 : 0;
  const localEventHistoryFound = historyCounts.crossingEvents + historyCounts.hazardEvents + (historyCounts.parseError ? 1 : 0);
  const telemetryFound = historyCounts.telemetryFields + telemetryQualityCount;
  const protectedDataSkipped = gridlyGetProtectedCleanupStorageKeys().filter((key) => gridlySafeLocalStorageHas(key));
  const supabaseCleanupAvailable = typeof gridlyDevPurgeRecentRoadHazards === "function";
  const audit = {
    dryRun: options?.dryRun !== false,
    roadHazardsFound: hazardCount,
    crossingReportsFound: reportCount,
    localEventHistoryFound,
    telemetryFound,
    wouldDelete: {
      inMemoryRoadHazards: hazardCount,
      inMemoryCrossingReports: reportCount,
      localStorageKeys: [
        ...(localEventHistoryFound || telemetryFound ? [GRIDLY_EVENT_HISTORY_STORAGE_KEY] : []),
        ...artifactKeys
      ],
      localStorageArtifactKeys: artifactKeys,
      localEventHistory: {
        key: GRIDLY_EVENT_HISTORY_STORAGE_KEY,
        crossingEvents: historyCounts.crossingEvents,
        hazardEvents: historyCounts.hazardEvents,
        parseError: historyCounts.parseError
      },
      localTelemetry: {
        key: GRIDLY_EVENT_HISTORY_STORAGE_KEY,
        operationalTelemetryFields: historyCounts.telemetryFields,
        crossingEventQualityTelemetryFields: telemetryQualityCount
      },
      duplicateAlerts: {
        source: "derived from local event history and active report arrays",
        safelyRemovableThroughLocalCleanup: true
      },
      supabase: supabaseCleanupAvailable
        ? { available: true, helper: "gridlyDevPurgeRecentRoadHazards", scope: "recent road hazards only; crossing report purge is audit-only because no safe dev purge helper exists" }
        : { available: false, reason: "Supabase cleanup helper is not available yet; audit only" }
    },
    protectedDataSkipped
  };
  console.info("gridlyTestDataCleanupAudit", audit);
  return audit;
}


function gridlyClearVisibleDevCleanupSurfaces(reason = "gridlyClearTestData") {
  activeReports = [];
  activeHazards = [];
  recentlyClearedRoadHazards = [];
  if (unifiedIncidentLayer && typeof unifiedIncidentLayer.clearLayers === "function") {
    unifiedIncidentLayer.clearLayers();
  }
  if (typeof renderUnifiedIncidents === "function") renderUnifiedIncidents(`${reason}:render-empty`);
  if (typeof renderAlerts === "function") renderAlerts();
  refreshReportHazardViews(reason);
  if (typeof renderUnifiedIncidents === "function") renderUnifiedIncidents(`${reason}:post-refresh`);
  if (unifiedIncidentLayer && typeof unifiedIncidentLayer.clearLayers === "function" && !activeReports.length && !activeHazards.length) {
    unifiedIncidentLayer.clearLayers();
  }
}

function gridlyGetVisibleDevCleanupCounts() {
  const alertsSnapshot = typeof window !== "undefined" && typeof window.getAlertsSurfaceSnapshot === "function" ? window.getAlertsSurfaceSnapshot() : null;
  const markerCount = typeof unifiedIncidentLayer?.getLayers === "function" ? unifiedIncidentLayer.getLayers().length : 0;
  return {
    activeHazardsAfterCleanup: Array.isArray(activeHazards) ? activeHazards.length : 0,
    activeReportsAfterCleanup: Array.isArray(activeReports) ? activeReports.length : 0,
    visibleMarkersAfterCleanup: markerCount,
    activeAlertsAfterCleanup: Number(alertsSnapshot?.activeIncidentCount ?? alertsSnapshot?.count ?? 0)
  };
}

function gridlyRemoveLocalStorageKeys(keys = []) {
  const removed = [];
  const skipped = [];
  if (typeof localStorage === "undefined") return { removed, skipped: keys };
  keys.forEach((key) => {
    if (!key || gridlyIsProtectedCleanupStorageKey(key)) {
      skipped.push(key);
      return;
    }
    try {
      localStorage.removeItem(key);
      removed.push(key);
    } catch (_error) {
      skipped.push(key);
    }
  });
  return { removed: removed.sort(), skipped: skipped.filter(Boolean).sort() };
}

window.gridlyClearLocalTestReports = function gridlyClearLocalTestReports(options = {}) {
  if (options?.confirm !== GRIDLY_TEST_DATA_CLEAR_CONFIRMATION) {
    const blocked = {
      ok: false,
      reason: "confirm_CLEAR_TEST_DATA_required",
      clearedLocalActiveReports: 0,
      clearedLocalActiveHazards: 0,
      removedLocalStorageKeys: [],
      protectedDataSkipped: gridlyGetProtectedCleanupStorageKeys().filter((key) => gridlySafeLocalStorageHas(key))
    };
    console.warn("gridlyClearLocalTestReports blocked", blocked);
    return blocked;
  }

  const reportCountBefore = Array.isArray(activeReports) ? activeReports.length : 0;
  const hazardCountBefore = Array.isArray(activeHazards) ? activeHazards.length : 0;

  activeReports = [];
  activeHazards = [];
  recentlyClearedRoadHazards = [];

  const removed = gridlyRemoveLocalStorageKeys(gridlyGetTestArtifactStorageKeys());

  gridlyClearVisibleDevCleanupSurfaces("gridlyClearLocalTestReports");

  const summary = {
    ok: true,
    clearedLocalActiveReports: reportCountBefore,
    clearedLocalActiveHazards: hazardCountBefore,
    removedLocalStorageKeys: removed.removed,
    skippedLocalStorageKeys: removed.skipped,
    supabaseRowsDeleted: 0,
    note: "Local in-memory report/hazard state cleared. Supabase production data was not deleted."
  };

  console.info("gridlyClearLocalTestReports summary", summary);
  return summary;
};

window.gridlyTestDataCleanupAudit = function gridlyTestDataCleanupAudit(options = {}) {
  return gridlyBuildTestDataCleanupAudit({ ...options, dryRun: options?.dryRun !== false });
};

window.gridlyClearTestData = async function gridlyClearTestData(options = {}) {
  const before = gridlyBuildTestDataCleanupAudit({ dryRun: true });
  if (options?.confirm !== GRIDLY_TEST_DATA_CLEAR_CONFIRMATION) {
    const blocked = {
      ok: false,
      dryRun: false,
      reason: "confirm_CLEAR_TEST_DATA_required",
      deleted: { localEventHistory: false, localTelemetry: false, localReports: false, supabaseRowsDeleted: 0 },
      protectedDataSkipped: before.protectedDataSkipped,
      audit: before
    };
    console.warn("gridlyClearTestData blocked", blocked);
    return blocked;
  }

  console.warn("gridlyClearTestData confirmed cleanup plan", before.wouldDelete);

  const suppressionSeedRecords = [
    ...(Array.isArray(activeHazards) ? activeHazards : []),
    ...(Array.isArray(activeReports) ? activeReports : [])
  ];
  const suppression = gridlyArmDevCleanupSharedSuppression(suppressionSeedRecords, { reason: "gridlyClearTestData" });

  const localReportCleanup = window.gridlyClearLocalTestReports({ confirm: GRIDLY_TEST_DATA_CLEAR_CONFIRMATION });
  const historyWrite = gridlyWriteEventHistoryState(gridlyCreateEmptyEventHistoryState());
  gridlyCrossingEventQualityTelemetry = {
    duplicateCrossingEventsSuppressed: 0,
    lastSuppressedDuplicate: null
  };

  let supabaseCleanup = {
    available: false,
    deleted: 0,
    reason: "Supabase cleanup helper is not available yet; audit only."
  };
  if (typeof gridlyDevPurgeRecentRoadHazards === "function") {
    supabaseCleanup = await gridlyDevPurgeRecentRoadHazards({
      hours: 24,
      radiusMiles: DEFAULT_NEARBY_RADIUS_MILES,
      sourceFilter: ["user"],
      deviceIdFilter: [deviceId],
      limit: 100,
      ...(options?.supabaseOptions && typeof options.supabaseOptions === "object" ? options.supabaseOptions : {}),
      dryRun: false,
      confirm: true
    });
  }

  let supabaseCrossingCleanup = { available: false, deleted: 0, reason: "Crossing report Supabase cleanup helper is not available." };
  if (typeof gridlyDevPurgeRecentCrossingReports === "function") {
    supabaseCrossingCleanup = await gridlyDevPurgeRecentCrossingReports({
      hours: 24,
      radiusMiles: DEFAULT_NEARBY_RADIUS_MILES,
      sourceFilter: ["user"],
      deviceIdFilter: [deviceId],
      limit: 100,
      ...(options?.crossingSupabaseOptions && typeof options.crossingSupabaseOptions === "object" ? options.crossingSupabaseOptions : {}),
      dryRun: false,
      confirm: true
    });
  }

  gridlyWriteEventHistoryState(gridlyCreateEmptyEventHistoryState());
  gridlyClearVisibleDevCleanupSurfaces("gridlyClearTestData:finalize");

  const after = gridlyBuildTestDataCleanupAudit({ dryRun: true });
  const result = {
    ok: true,
    dryRun: false,
    deleted: {
      localEventHistory: Boolean(historyWrite?.written),
      localTelemetry: Boolean(historyWrite?.written),
      localReports: Boolean(localReportCleanup?.ok),
      localRoadHazards: Number(localReportCleanup?.clearedLocalActiveHazards || 0),
      localCrossingReports: Number(localReportCleanup?.clearedLocalActiveReports || 0),
      localStorageKeys: localReportCleanup?.removedLocalStorageKeys || [],
      supabaseRowsDeleted: Number(supabaseCleanup?.deleted || 0) + Number(supabaseCrossingCleanup?.deleted || 0)
    },
    suppression,
    repopulationDetected: Boolean((after?.roadHazardsFound || 0) > 0 || (after?.crossingReportsFound || 0) > 0),
    reloadSource: gridlyGetDevCleanupSuppressionAudit().reloadSource,
    suppressedSharedReportsCount: gridlyGetDevCleanupSuppressionAudit().suppressedSharedReportsCount,
    purgedSupabaseRoadHazardsCount: Number(supabaseCleanup?.deleted || 0),
    purgedSupabaseCrossingReportsCount: Number(supabaseCrossingCleanup?.deleted || 0),
    ...gridlyGetVisibleDevCleanupCounts(),
    supabaseCleanup,
    supabaseCrossingCleanup,
    protectedDataSkipped: before.protectedDataSkipped,
    before,
    after
  };
  console.info("gridlyClearTestData completed", result);
  return result;
};

window.gridlyUnifiedHazardSourceAudit = async function gridlyUnifiedHazardSourceAudit(options = {}) {
  if (!supabaseClient) {
    const missing = { ok: false, reason: "Supabase client not initialized." };
    console.warn("gridlyUnifiedHazardSourceAudit unavailable", missing);
    return missing;
  }

  const ROAD_HAZARD_TYPES = gridlyGetSharedRoadHazardReportTypes();
  const hours = Math.max(1, Number(options?.hours) || 24);
  const cutoffIso = new Date(Date.now() - (hours * 60 * 60 * 1000)).toISOString();
  const rawSourceFilter = options?.sourceFilter;
  const sourceFilter = Array.isArray(rawSourceFilter)
    ? rawSourceFilter.map((value) => String(value || "").trim().toLowerCase()).filter(Boolean)
    : null;

  const { data, error } = await supabaseClient
    .from("reports")
    .select("id,report_type,source,created_at,expires_at,crossing_id")
    .gte("created_at", cutoffIso)
    .in("report_type", ROAD_HAZARD_TYPES)
    .order("created_at", { ascending: false })
    .limit(1000);

  if (error) {
    console.error("gridlyUnifiedHazardSourceAudit query failed", error);
    return { ok: false, reason: error.message || "query_failed" };
  }

  const rows = Array.isArray(data) ? data : [];
  const normalizedRows = normalizeReports(rows);
  const activeNormalizedHazards = gridlyFilterRoadHazardsByLatestLifecycle(normalizedRows.filter((report) => report.reportKind === "hazard"), Date.now());
  const effectiveSourceRows = rows.filter((row) => {
    if (!sourceFilter?.length) return true;
    const effectiveSource = String(row?.source || "user").toLowerCase();
    return sourceFilter.includes(effectiveSource);
  });
  const recentUserRoadHazards = effectiveSourceRows.filter((row) => {
    const type = String(row?.report_type || "").toLowerCase();
    const normalizedType = type === "wreck" ? "crash" : type;
    return normalizedType !== "hazard_cleared" && String(row?.crossing_id || "").trim().length === 0 && String(row?.source || "user").toLowerCase() === "user";
  });

  const summary = {
    ok: true,
    cutoffIso,
    sourceOwner: "supabase.reports -> normalizeReports(...) -> activeHazards -> getLiveHazardIncidents()",
    sourceCount: activeNormalizedHazards.length,
    generatedIncidentCount: getLiveHazardIncidents().length,
    recentUserRoadHazardCount: recentUserRoadHazards.length,
    sourceBreakdown: rows.reduce((acc, row) => {
      const key = String(row?.source || "user").toLowerCase() || "user";
      acc[key] = (acc[key] || 0) + 1;
      return acc;
    }, {})
  };

  console.info("gridlyUnifiedHazardSourceAudit", summary);
  return summary;
};


const gridlyActiveIncidentAudit = function gridlyActiveIncidentAudit() {
  const now = new Date();
  const liveHazardIncidents = getLiveHazardIncidents();

  const lifecycleStateTotals = {};
  const reportTypeTotals = {};

  const generatedRoadIncidents = liveHazardIncidents.map((incident) => {
    const reports = Array.isArray(incident?.reports)
      ? incident.reports
      : activeHazards.filter((hazard) => getHazardClusterKey(hazard) === incident.key && !hazard.expired && hazard.type !== "hazard_cleared");

    const latestReport = incident.latestReport || reports[0] || null;
    const lifecycleState = latestReport ? getIncidentLifecycleState(latestReport, now) : "unknown";

    lifecycleStateTotals[lifecycleState] = (lifecycleStateTotals[lifecycleState] || 0) + 1;

    reports.forEach((report) => {
      const type = String(report?.type || "unknown").toLowerCase();
      reportTypeTotals[type] = (reportTypeTotals[type] || 0) + 1;
    });

    const routeImpactStatus = latestReport?.routeImpactStatus
      || latestReport?.route_impact_status
      || latestReport?.routeImpact
      || latestReport?.route_impact
      || latestReport?.route_relevance
      || null;

    return {
      roadIncidentId: `road-${incident.key}`,
      clusterKey: incident.key,
      sourceReportIds: reports.map((report) => report.id).filter(Boolean),
      sourceReportTypes: reports.map((report) => String(report?.type || "unknown").toLowerCase()),
      source: latestReport?.source || "user",
      created_at: latestReport?.submittedAt || null,
      expires_at: latestReport?.expires_at || latestReport?.expiresAt || null,
      lifecycleState,
      expired: Boolean(latestReport?.expired),
      coordinates: {
        lat: Number(latestReport?.lat),
        lng: Number(latestReport?.lng)
      },
      routeImpactStatus,
      inclusionReason: {
        includedByGetLiveHazardIncidents: true,
        rules: [
          "source row is in activeHazards[]",
          "active hazards require hazard.expired === false",
          "recent hazard_cleared rows are retained for Recently Cleared visibility",
          "newer hazard_cleared rows suppress active road hazards at the same rounded coordinates",
          "clustered by getHazardClusterKey(type + lat/lng rounded to 4 decimals), with cleared rows keyed by cleared location"
        ],
        filterSnapshot: {
          reportKind: latestReport?.reportKind || null,
          expired: Boolean(latestReport?.expired),
          type: String(latestReport?.type || "")
        }
      }
    };
  });

  const activeHazardsCount = activeHazards.filter((hazard) => !hazard.expired && hazard.type !== "hazard_cleared").length;
  const activeReportsCount = activeReports.filter((report) => getIncidentLifecycleState(report, now) === "active").length;

  const summary = {
    generatedRoadIncidentCount: generatedRoadIncidents.length,
    activeHazardsCount,
    activeReportsCount,
    lifecycleStateTotals,
    reportTypeTotals
  };

  const audit = { generatedRoadIncidents, summary };
  console.info("gridlyActiveIncidentAudit", audit);
  return audit;
};


function gridlyCountArrayItems(value) {
  return Array.isArray(value) ? value.length : 0;
}

function gridlyIncidentAuditSampleReport(report = {}) {
  return {
    id: report?.id || null,
    crossingId: report?.crossingId || report?.crossing_id || null,
    reportKind: report?.reportKind || null,
    type: report?.type || report?.report_type || null,
    source: report?.source || null,
    submittedAt: report?.submittedAt || report?.created_at || null,
    expiresAt: report?.expiresAt || report?.expires_at || null,
    expired: Boolean(report?.expired),
    lat: Number.isFinite(Number(report?.lat ?? report?.latitude ?? report?.rawLat)) ? Number(report?.lat ?? report?.latitude ?? report?.rawLat) : null,
    lng: Number.isFinite(Number(report?.lng ?? report?.lon ?? report?.longitude ?? report?.rawLng)) ? Number(report?.lng ?? report?.lon ?? report?.longitude ?? report?.rawLng) : null,
    clusterKey: typeof getHazardClusterKey === "function" ? getHazardClusterKey(report) : null,
    title: report?.title || null
  };
}

function gridlyBuildIncidentSourceTrace(options = {}) {
  const now = new Date();
  const liveHazardIncidents = typeof getLiveHazardIncidents === "function" ? getLiveHazardIncidents() : [];
  const safeActiveReports = Array.isArray(activeReports) ? activeReports : [];
  const safeActiveHazards = Array.isArray(activeHazards) ? activeHazards : [];
  const safeRecentlyClearedRoadHazards = Array.isArray(recentlyClearedRoadHazards) ? recentlyClearedRoadHazards : [];
  const safeUnifiedIncidents = typeof getUnifiedIncidents === "function" ? getUnifiedIncidents() : [];
  const safeActiveUnifiedIncidents = typeof getActiveUnifiedIncidents === "function" ? getActiveUnifiedIncidents() : [];
  const txdotFutureIncidents = typeof futureTxdotIncidents === "function" ? futureTxdotIncidents() : [];
  const txdotFutureConstruction = typeof futureTxdotConstruction === "function" ? futureTxdotConstruction() : [];
  const txdotServiceItems = Array.isArray(window?.gridlyTxdot?.getRoadConditions?.()) ? window.gridlyTxdot.getRoadConditions() : [];
  const historicalState = typeof gridlyReadEventHistoryState === "function" ? gridlyReadEventHistoryState() : gridlyCreateEmptyEventHistoryState();
  const historicalHazardEvents = Array.isArray(historicalState?.hazardEvents) ? historicalState.hazardEvents : [];
  const historicalCrossingEvents = Array.isArray(historicalState?.crossingEvents) ? historicalState.crossingEvents : [];
  const alertsSnapshot = typeof window !== "undefined" && typeof window.getAlertsSurfaceSnapshot === "function" ? window.getAlertsSurfaceSnapshot() : null;
  const latestAlerts = Array.isArray(window?.__gridlyLatestAlertsForRender) ? window.__gridlyLatestAlertsForRender : [];
  const alertItems = Array.isArray(alertsSnapshot?.alerts) ? alertsSnapshot.alerts : latestAlerts;
  const sourceBreakdown = {};
  const sourceIncidentBreakdown = {};
  const liveActiveHazards = gridlyFilterRoadHazardsByLatestLifecycle(safeActiveHazards, Date.now());

  liveHazardIncidents.forEach((incident) => {
    const reports = Array.isArray(incident?.reports)
      ? incident.reports
      : liveActiveHazards.filter((hazard) => getHazardClusterKey(hazard) === incident.key);
    const incidentSources = new Set();
    reports.forEach((report) => {
      const source = String(report?.source || "unknown").toLowerCase() || "unknown";
      sourceBreakdown[source] = (sourceBreakdown[source] || 0) + 1;
      incidentSources.add(source);
    });
    incidentSources.forEach((source) => {
      sourceIncidentBreakdown[source] = (sourceIncidentBreakdown[source] || 0) + 1;
    });
  });

  const roadUnifiedIncidents = (Array.isArray(safeUnifiedIncidents) ? safeUnifiedIncidents : [])
    .filter((incident) => String(incident?.id || "").startsWith("road-"));
  const roadActiveUnifiedIncidents = (Array.isArray(safeActiveUnifiedIncidents) ? safeActiveUnifiedIncidents : [])
    .filter((incident) => String(incident?.id || "").startsWith("road-"));
  const txdotUnifiedIncidents = gridlyFindTxdotRowsInCollection(safeUnifiedIncidents);
  if (txdotUnifiedIncidents.length > 0) {
    sourceIncidentBreakdown.txdot = (sourceIncidentBreakdown.txdot || 0) + txdotUnifiedIncidents.length;
  }
  const activeReportHazardMatches = safeActiveReports.filter((report) => String(report?.reportKind || "").toLowerCase() === "hazard" || Object.prototype.hasOwnProperty.call(HAZARD_TYPES, String(report?.type || report?.report_type || "").toLowerCase()));
  const historicalOpenHazards = historicalHazardEvents.filter((event) => !event?.clearedAt);
  const cachedRoadAlerts = latestAlerts.filter((alert) => {
    const id = String(alert?.id || alert?.incidentId || alert?.reportId || "");
    const rawId = String(alert?.raw?.id || alert?.raw?.incidentId || alert?.raw?.reportId || "");
    const kind = String(alert?.reportKind || alert?.raw?.reportKind || "").toLowerCase();
    return id.startsWith("road-") || rawId.startsWith("road-") || kind === "hazard" || kind === "road";
  });
  const alertRoadItems = alertItems.filter((alert) => {
    const id = String(alert?.id || alert?.incidentId || alert?.reportId || "");
    const rawId = String(alert?.raw?.id || alert?.raw?.incidentId || alert?.raw?.reportId || "");
    const kind = String(alert?.reportKind || alert?.raw?.reportKind || "").toLowerCase();
    return id.startsWith("road-") || rawId.startsWith("road-") || kind === "hazard" || kind === "road";
  });
  const incidentSamples = liveHazardIncidents.slice(0, Math.max(1, Math.min(10, Number(options?.sampleLimit) || 10))).map((incident) => {
    const reports = Array.isArray(incident?.reports)
      ? incident.reports
      : liveActiveHazards.filter((hazard) => getHazardClusterKey(hazard) === incident.key);
    const latestReport = incident?.latestReport || reports[0] || null;
    const roadIncidentId = `road-${incident?.key || "unknown"}`;
    const matchingUnified = roadUnifiedIncidents.find((item) => String(item?.id || "") === roadIncidentId) || null;
    const matchingAlerts = alertItems.filter((alert) => String(alert?.id || alert?.raw?.id || alert?.incidentId || "") === roadIncidentId).slice(0, 3);
    const matchingHistory = historicalHazardEvents.filter((event) => {
      const eventId = String(event?.incidentId || "");
      return reports.some((report) => eventId === String(report?.id || report?.crossingId || report?.crossing_id || ""));
    }).slice(0, 3);
    return {
      roadIncidentId,
      clusterKey: incident?.key || null,
      reportCount: reports.length,
      sourceReportIds: reports.map((report) => report?.id).filter(Boolean),
      sourceReportTypes: reports.map((report) => String(report?.type || report?.report_type || "unknown").toLowerCase()),
      sourceReportSources: [...new Set(reports.map((report) => String(report?.source || "unknown").toLowerCase()))],
      lifecycleState: latestReport ? getIncidentLifecycleState(latestReport, now) : "unknown",
      fromActiveHazards: reports.length,
      fromActiveReports: activeReportHazardMatches.filter((report) => reports.some((hazard) => String(hazard?.id || "") === String(report?.id || ""))).length,
      fromUnifiedIncidents: Boolean(matchingUnified),
      fromRenderedAlerts: matchingAlerts.length,
      fromHistoricalEvents: matchingHistory.length,
      latestReport: gridlyIncidentAuditSampleReport(latestReport),
      alertSamples: matchingAlerts.map((alert) => ({
        id: alert?.id || null,
        title: alert?.resolvedHeadline || alert?.title || alert?.localizedSummary || null,
        reportKind: alert?.reportKind || alert?.raw?.reportKind || null,
        rawId: alert?.raw?.id || null,
        source: alert?.source || alert?.raw?.source || null
      })),
      historicalEventSamples: matchingHistory.map((event) => ({
        incidentId: event?.incidentId || null,
        hazardType: event?.hazardType || null,
        createdAt: event?.createdAt || null,
        clearedAt: event?.clearedAt || null,
        roadName: event?.roadName || null
      }))
    };
  });

  const audit = {
    generatedRoadIncidents: liveHazardIncidents.length,
    sourceBreakdown: {
      sourceRowsBySource: sourceBreakdown,
      generatedIncidentsBySource: sourceIncidentBreakdown,
      pipeline: "activeHazards[] -> getLiveHazardIncidents() -> getUnifiedIncidents() road-* -> buildCommuteConsequenceIntelligence()/getAlertsSurfaceSnapshot() -> Alerts"
    },
    fromActiveReports: {
      sourceRows: activeReportHazardMatches.length,
      activeReportsTotal: safeActiveReports.length,
      generatedRoadIncidents: 0,
      note: "getLiveHazardIncidents() reads activeHazards[], not activeReports[]."
    },
    fromActiveHazards: {
      sourceRows: liveActiveHazards.length,
      activeHazardsTotal: safeActiveHazards.length,
      recentlyClearedRoadHazardsTotal: safeRecentlyClearedRoadHazards.length,
      generatedRoadIncidents: liveHazardIncidents.length,
      clusterKeys: liveHazardIncidents.map((incident) => incident?.key).filter(Boolean)
    },
    fromSharedReports: {
      sourceRows: safeActiveHazards.length + safeRecentlyClearedRoadHazards.length,
      activeSourceRows: liveActiveHazards.length,
      recentlyClearedSourceRows: safeRecentlyClearedRoadHazards.length,
      generatedRoadIncidents: liveHazardIncidents.length,
      lastLoadSharedReportsSuccessAt: gridlyNetworkAuditState?.loadSharedReports?.lastSuccessAt || null,
      lastLoadSharedReportsSuccessIso: gridlyNetworkAuditState?.loadSharedReports?.lastSuccessAt ? new Date(gridlyNetworkAuditState.loadSharedReports.lastSuccessAt).toISOString() : null,
      sourceOwner: "loadSharedReports() selects live road hazard rows into activeHazards and keeps recent hazard_cleared rows in recentlyClearedRoadHazards for cleared-only visibility."
    },
    fromTxDot: {
      futureTxdotIncidents: gridlyCountArrayItems(txdotFutureIncidents),
      futureTxdotConstruction: gridlyCountArrayItems(txdotFutureConstruction),
      txdotUnifiedIncidents: txdotUnifiedIncidents.length,
      txdotMapEligibleCount: txdotServiceItems.filter((row) => typeof gridlyTxdotRowHasFiniteCoordinates === "function" ? gridlyTxdotRowHasFiniteCoordinates(row) : gridlyHasFiniteTxdotCoordinates(row)).length,
      txdotRowsSkippedNoCoordinates: txdotServiceItems.filter((row) => !(typeof gridlyTxdotRowHasFiniteCoordinates === "function" ? gridlyTxdotRowHasFiniteCoordinates(row) : gridlyHasFiniteTxdotCoordinates(row))).length,
      serviceRoadConditions: gridlyCountArrayItems(txdotServiceItems),
      sampleTxdotUnifiedRows: txdotUnifiedIncidents.slice(0, 5),
      generatedRoadIncidents: 0,
      note: "futureTxdotIncidents() and futureTxdotConstruction() are separate getUnifiedIncidents() sources and do not create road-* generated incidents."
    },
    fromHistoricalEvents: {
      hazardEvents: historicalHazardEvents.length,
      openHazardEvents: historicalOpenHazards.length,
      crossingEvents: historicalCrossingEvents.length,
      generatedRoadIncidents: 0,
      note: "Event history is analytics/history storage; getLiveHazardIncidents() does not read it."
    },
    fromDerivedIntelligence: {
      unifiedIncidents: gridlyCountArrayItems(safeUnifiedIncidents),
      roadUnifiedIncidents: roadUnifiedIncidents.length,
      activeUnifiedIncidents: gridlyCountArrayItems(safeActiveUnifiedIncidents),
      activeRoadUnifiedIncidents: roadActiveUnifiedIncidents.length,
      alertsSnapshotCount: gridlyCountArrayItems(alertItems),
      roadAlertsSnapshotCount: alertRoadItems.length,
      generatedRoadIncidents: roadActiveUnifiedIncidents.length,
      recentlyClearedRoadUnifiedIncidents: roadUnifiedIncidents.length - roadActiveUnifiedIncidents.length,
      note: "Derived intelligence consumes active road-* unified incidents for alert surfaces; cleared road-* incidents are informational Recently Cleared rows, not generated active incidents."
    },
    fromCachedState: {
      latestAlertsForRender: latestAlerts.length,
      latestRoadAlertsForRender: cachedRoadAlerts.length,
      alertsForRenderSample: gridlyCountArrayItems(window?.__gridlyAlertsForRenderSample),
      refreshCycleCacheActive: Boolean(gridlyRefreshCycleCache),
      refreshAuditLastRefreshAt: gridlyRefreshAuditState?.lastRefreshAt || null,
      generatedRoadIncidents: 0,
      note: "Cached alert arrays/DOM can keep an alert surface visible until rerender, but generatedRoadIncidents are recomputed from activeHazards."
    },
    incidentSamples
  };
  console.info("gridlyIncidentSourceAudit", audit);
  return audit;
}

function gridlyIncidentSourceAudit(options = {}) {
  return gridlyBuildIncidentSourceTrace(options);
}

window.gridlyIncidentSourceAudit = gridlyIncidentSourceAudit;
exposeGridlyAuditHelper("gridlyIncidentSourceAudit", gridlyIncidentSourceAudit);


const GRIDLY_CLEARED_HAZARD_PERSISTENCE_AUDIT_VERSION = "V239-audit-only";

function gridlyClearedHazardPersistenceSafeArray(value) {
  return Array.isArray(value) ? value : [];
}

function gridlyClearedHazardPersistenceIso(value) {
  if (!value) return null;
  const ms = new Date(value).getTime();
  return Number.isFinite(ms) ? new Date(ms).toISOString() : null;
}

function gridlyClearedHazardPersistenceCoord(record = {}) {
  const coord = typeof gridlyCoordinateFromRecord === "function" ? gridlyCoordinateFromRecord(record) : null;
  const lat = Number(coord?.lat ?? record?.lat ?? record?.latitude ?? record?.rawLat ?? record?.raw?.lat ?? record?.raw?.latitude);
  const lng = Number(coord?.lng ?? record?.lng ?? record?.lon ?? record?.longitude ?? record?.rawLng ?? record?.raw?.lng ?? record?.raw?.longitude);
  return Number.isFinite(lat) && Number.isFinite(lng) ? { lat, lng } : null;
}

function gridlyClearedHazardPersistenceId(record = {}) {
  const value = record?.id ?? record?.report_id ?? record?.reportId ?? record?.incidentId ?? record?.incident_id ?? record?.key ?? record?.raw?.id ?? record?.raw?.report_id ?? record?.latestReport?.id;
  return value === undefined || value === null || !String(value).trim() ? "" : String(value).trim();
}

function gridlyClearedHazardPersistenceType(record = {}) {
  const type = record?.type || record?.report_type || record?.category || record?.hazardType || record?.raw?.type || record?.raw?.report_type || record?.latestReport?.type || record?.latestReport?.report_type || "unknown";
  return String(type || "unknown").toLowerCase();
}

function gridlyClearedHazardPersistenceSourceReportId(record = {}) {
  const value = record?.sourceReportId || record?.source_report_id || record?.reportId || record?.report_id || record?.raw?.id || record?.raw?.report_id || record?.latestReport?.id || record?.reports?.[0]?.id || record?.id;
  return value === undefined || value === null || !String(value).trim() ? "" : String(value).trim();
}

function gridlyClearedHazardPersistenceTimestamp(record = {}) {
  return record?.updatedAt || record?.updated_at || record?.createdAt || record?.created_at || record?.submittedAt || record?.timestamp || record?.raw?.updated_at || record?.raw?.created_at || record?.latestReport?.submittedAt || record?.latestReport?.created_at || null;
}

function gridlyClearedHazardPersistenceClearTime(record = {}) {
  return record?.clearedAt || record?.cleared_at || record?.closedAt || record?.closed_at || (gridlyClearedHazardPersistenceType(record) === "hazard_cleared" ? gridlyClearedHazardPersistenceTimestamp(record) : null) || record?.raw?.clearedAt || record?.raw?.cleared_at || null;
}

function gridlyClearedHazardPersistenceLifecycle(record = {}, nowMs = Date.now(), allHazards = activeHazards) {
  const explicit = String(record?.lifecycleState || record?.lifecycle_state || record?.lifecycle || record?.state || record?.status || record?.raw?.lifecycleState || record?.raw?.status || "").trim().toLowerCase();
  if (explicit) return explicit;
  if (gridlyClearedHazardPersistenceType(record) === "hazard_cleared") return "cleared";
  try {
    if (typeof getIncidentLifecycleState === "function") return String(getIncidentLifecycleState(record, nowMs) || "unknown").toLowerCase();
  } catch (_error) {}
  try {
    if (typeof gridlyRoadHazardLatestLifecycleState === "function") return String(gridlyRoadHazardLatestLifecycleState(record, allHazards) || "unknown").toLowerCase();
  } catch (_error) {}
  return "unknown";
}

function gridlyClearedHazardPersistenceStatus(record = {}, nowMs = Date.now(), allHazards = activeHazards) {
  const explicit = String(record?.status || record?.state || record?.raw?.status || "").trim().toLowerCase();
  if (explicit) return explicit;
  const lifecycle = gridlyClearedHazardPersistenceLifecycle(record, nowMs, allHazards);
  if (["cleared", "recently_cleared", "hazard_cleared", "inactive", "expired", "stale", "historical"].includes(lifecycle)) return "cleared";
  return "active";
}

function gridlyClearedHazardPersistenceRoadName(record = {}) {
  return String(record?.roadName || record?.road_name || record?.selectedRoadName || record?.location_name || record?.area || record?.city || record?.crossingName || record?.title || record?.raw?.roadName || record?.raw?.road_name || record?.latestReport?.roadName || "").trim();
}

function gridlyClearedHazardPersistenceDuplicateKey(record = {}) {
  const type = gridlyClearedHazardPersistenceType(record) === "hazard_cleared" ? (record?.clearedHazardType || record?.hazardType || "hazard_cleared") : gridlyClearedHazardPersistenceType(record);
  const sourceReportId = gridlyClearedHazardPersistenceSourceReportId(record);
  if (sourceReportId) return `source:${sourceReportId}`;
  if (typeof getHazardClusterKey === "function") {
    try { return `cluster:${getHazardClusterKey({ ...record, type })}`; } catch (_error) {}
  }
  const coord = gridlyClearedHazardPersistenceCoord(record);
  return coord ? `coord:${type}:${coord.lat.toFixed(4)}:${coord.lng.toFixed(4)}` : `title:${type}:${gridlyClearedHazardPersistenceRoadName(record).toLowerCase()}`;
}

function gridlyClearedHazardPersistenceRecordsFromStorageArea(storage, storageName) {
  const records = [];
  const breakdown = { available: false, keyCount: 0, hazardKeyCount: 0, parsedHazardRecords: 0, keys: [] };
  if (!storage) return { records, breakdown };
  try {
    breakdown.available = true;
    breakdown.keyCount = Number(storage.length || 0);
    const visit = (value, key, path, depth = 0) => {
      if (depth > 4 || value == null) return;
      if (Array.isArray(value)) {
        value.forEach((entry, index) => visit(entry, key, `${path}[${index}]`, depth + 1));
        return;
      }
      if (typeof value === "object") {
        const text = `${value.type || ""} ${value.report_type || ""} ${value.reportKind || ""} ${value.title || ""} ${value.detail || ""}`.toLowerCase();
        const hazardLike = /hazard|flood|crash|wreck|debris|construction|closed|disabled/.test(text) || Object.prototype.hasOwnProperty.call(value, "clearedAt") || Object.prototype.hasOwnProperty.call(value, "cleared_at");
        if (hazardLike) records.push({ ...value, __gridlyStorageSource: storageName, __gridlyStorageKey: key, __gridlyStoragePath: path });
        Object.entries(value).slice(0, 40).forEach(([childKey, childValue]) => visit(childValue, key, `${path}.${childKey}`, depth + 1));
      }
    };
    for (let index = 0; index < storage.length; index += 1) {
      const key = storage.key(index);
      if (!key) continue;
      const isHazardKey = /hazard|incident|report|alert|clear|gridly/i.test(key);
      if (isHazardKey) {
        breakdown.hazardKeyCount += 1;
        breakdown.keys.push(key);
      }
      if (!isHazardKey) continue;
      const raw = storage.getItem(key);
      try { visit(JSON.parse(raw), key, key, 0); }
      catch (_error) {
        if (/hazard|cleared|incident|report/i.test(String(raw || ""))) records.push({ id: `${storageName}:${key}`, title: String(raw || "").slice(0, 120), __gridlyStorageSource: storageName, __gridlyStorageKey: key, __gridlyStoragePath: key });
      }
    }
    breakdown.parsedHazardRecords = records.length;
  } catch (error) {
    breakdown.error = error?.message || "storage_read_failed";
  }
  return { records, breakdown };
}

function gridlyClearedHazardPersistenceRenderedAlertRows() {
  const cacheRows = gridlyClearedHazardPersistenceSafeArray(typeof window !== "undefined" ? window.__gridlyLatestAlertsForRender : [])
    .map((record) => ({ ...record, renderedSurface: record?.renderedSurface || "alert_cache" }));
  const domRows = [];
  if (typeof document !== "undefined") {
    const cacheById = new Map(cacheRows.map((record) => [String(gridlyClearedHazardPersistenceId(record) || "").trim(), record]).filter(([id]) => Boolean(id)));
    const cacheByTitle = new Map(cacheRows.map((record) => [String(record?.title || record?.headline || record?.resolvedHeadline || "").trim().toLowerCase(), record]).filter(([title]) => Boolean(title)));
    document.querySelectorAll("[data-gridly-alert-row='true'], [data-incident-id]").forEach((node, index) => {
      const dataset = node?.dataset || {};
      const text = String(node?.innerText || node?.textContent || "").trim();
      const rawId = dataset.gridlyAlertId || dataset.incidentId || dataset.id || "";
      const rawTitle = dataset.gridlyAlertTitle || dataset.gridlyTitle || text.slice(0, 120);
      const titleKey = String(rawTitle || "").trim().toLowerCase();
      const matchedCache = (rawId ? cacheById.get(String(rawId).trim()) : null) || (titleKey ? cacheByTitle.get(titleKey) : null) || null;
      if (!rawId && !matchedCache && !dataset.gridlyAlertTitle && !dataset.gridlyAlertSummary) return;
      const lat = Number(dataset.gridlyAlertLat);
      const lng = Number(dataset.gridlyAlertLng);
      const rects = typeof node?.getClientRects === "function" ? node.getClientRects() : [];
      const computedStyle = typeof window !== "undefined" && typeof window.getComputedStyle === "function" ? window.getComputedStyle(node) : null;
      const visibleInDom = Boolean(
        node?.isConnected !== false
        && !node?.hidden
        && dataset.gridlyAuditHidden !== "true"
        && computedStyle?.display !== "none"
        && computedStyle?.visibility !== "hidden"
        && computedStyle?.opacity !== "0"
        && (!rects || rects.length > 0 || Number(node?.offsetHeight || 0) > 0 || Number(node?.offsetWidth || 0) > 0)
      );
      domRows.push({
        ...(matchedCache || {}),
        id: rawId || gridlyClearedHazardPersistenceId(matchedCache) || `dom-alert-${index}`,
        title: rawTitle || matchedCache?.title || "",
        detail: text,
        status: dataset.state || dataset.status || matchedCache?.status || "rendered",
        source: "rendered_alert_dom",
        renderedSurface: "alert_panel_dom",
        awarenessArea: dataset.gridlyAlertAwarenessArea || matchedCache?.awarenessArea || matchedCache?.area || "",
        area: dataset.gridlyAlertAwarenessArea || matchedCache?.area || matchedCache?.city || matchedCache?.town || "",
        locationName: dataset.gridlyAlertLocation || matchedCache?.locationName || matchedCache?.knownLocation || "",
        lat: Number.isFinite(lat) ? lat : matchedCache?.lat,
        lng: Number.isFinite(lng) ? lng : (matchedCache?.lng ?? matchedCache?.lon),
        crossingId: dataset.gridlyAlertCrossingId || matchedCache?.crossingId || matchedCache?.crossing_id || "",
        hazardType: dataset.gridlyAlertHazardType || matchedCache?.hazardType || matchedCache?.type || matchedCache?.category || "",
        visibleInAlertPanelDom: visibleInDom,
        domAuditIndex: index
      });
    });
  }
  return { cacheRows, domRows };
}

function gridlyClearedHazardPersistenceRenderedMarkers() {
  const markerRows = [];
  const layers = typeof unifiedIncidentLayer?.getLayers === "function" ? unifiedIncidentLayer.getLayers() : [];
  layers.forEach((layer, index) => {
    const latLng = layer?.getLatLng?.();
    const options = layer?.options || {};
    const audit = options.gridlyPlacementAudit || {};
    markerRows.push({
      id: options.incidentId || audit.incidentId || `marker-${index}`,
      incidentId: options.incidentId || audit.incidentId || "",
      source: options.incidentSource || "unifiedIncidentLayer",
      lat: latLng?.lat,
      lng: latLng?.lng,
      status: "rendered",
      gridlyPlacementAudit: audit
    });
  });
  return markerRows;
}

function gridlyExplainAlertAwarenessSurvival(record = {}, currentArea = null) {
  const selectedLabel = currentArea?.label || currentArea?.storageValue || GRIDLY_COUNTY_WIDE_AWARENESS_LABEL;
  const coord = typeof getGridlyAwarenessIntelligenceRecordCoordinate === "function" ? getGridlyAwarenessIntelligenceRecordCoordinate(record) : gridlyClearedHazardPersistenceCoord(record);
  const textArea = record?.awarenessArea || record?.awareness_area || record?.area || record?.city || record?.town || record?.raw?.awarenessArea || record?.raw?.city || "";
  const renderedSurface = record?.renderedSurface || (record?.source === "rendered_alert_dom" ? "alert_panel_dom" : "alert_cache");
  if (!currentArea || currentArea.countyWide || currentArea.fallback) {
    return {
      renderedSurface,
      whyItSurvivedFiltering: "County mode does not apply town awareness filtering."
    };
  }
  if (!coord && !textArea && !(record?.crossingId || record?.crossing_id || record?.crossingName || record?.crossing_name)) {
    return {
      renderedSurface,
      whyItSurvivedFiltering: `Rendered ${renderedSurface} row had no recoverable coordinates, crossing, city, or awarenessArea metadata for ${selectedLabel}; it should be linked to its filtered cache record or removed from mismatch auditing.`
    };
  }
  return {
    renderedSurface,
    whyItSurvivedFiltering: `Rendered ${renderedSurface} row did not match selected awareness area ${selectedLabel}; source filtering failed or the DOM/cache row was stale.`
  };
}

function gridlyClearedHazardPersistenceRecordAuditKey(record = {}) {
  const id = String(gridlyClearedHazardPersistenceId(record) || "").trim();
  if (id) return `id:${id}`;
  const sourceReportId = String(gridlyClearedHazardPersistenceSourceReportId(record) || "").trim();
  if (sourceReportId) return `sourceReportId:${sourceReportId}`;
  const coord = gridlyClearedHazardPersistenceCoord(record);
  if (coord) return `coord:${coord.lat.toFixed(5)}:${coord.lng.toFixed(5)}`;
  const title = String(record?.title || record?.headline || record?.resolvedHeadline || record?.detail || "").trim().toLowerCase();
  return title ? `title:${title}` : "";
}

function gridlyClearedHazardPersistenceRecordsMatch(left = {}, right = {}) {
  const leftKey = gridlyClearedHazardPersistenceRecordAuditKey(left);
  const rightKey = gridlyClearedHazardPersistenceRecordAuditKey(right);
  if (leftKey && rightKey && leftKey === rightKey) return true;
  const leftTitle = String(left?.title || left?.headline || left?.resolvedHeadline || "").trim().toLowerCase();
  const rightTitle = String(right?.title || right?.headline || right?.resolvedHeadline || "").trim().toLowerCase();
  if (leftTitle && rightTitle && leftTitle === rightTitle) return true;
  const leftCoord = gridlyClearedHazardPersistenceCoord(left);
  const rightCoord = gridlyClearedHazardPersistenceCoord(right);
  return Boolean(leftCoord && rightCoord && Math.abs(leftCoord.lat - rightCoord.lat) <= 0.00015 && Math.abs(leftCoord.lng - rightCoord.lng) <= 0.00015);
}

function gridlyClearedHazardPersistenceVisibleDomAlertRows(renderedAlerts = {}) {
  return gridlyClearedHazardPersistenceSafeArray(renderedAlerts.domRows).filter((record) => record?.visibleInAlertPanelDom !== false);
}

function gridlyClassifyAwarenessAreaMismatchRecord(record = {}, renderedAlerts = {}, membership = {}) {
  const visibleDomRows = gridlyClearedHazardPersistenceVisibleDomAlertRows(renderedAlerts);
  const source = record?.source || "renderedAlerts";
  const renderedSurface = record?.renderedSurface || (source === "rendered_alert_dom" ? "alert_panel_dom" : "alert_cache");
  const currentlyVisibleInAlertPanelDom = renderedSurface === "alert_panel_dom"
    ? record?.visibleInAlertPanelDom !== false
    : visibleDomRows.some((domRecord) => gridlyClearedHazardPersistenceRecordsMatch(record, domRecord));
  const presentInUnifiedIncidents = Boolean(membership.appearsInUnifiedIncidents);
  const presentInActiveHazards = Boolean(membership.appearsInActiveHazards);
  const presentOnMap = Boolean(membership.appearsOnMap);
  const presentOnlyInStaleCache = renderedSurface === "alert_cache" && !currentlyVisibleInAlertPanelDom && !presentInUnifiedIncidents && !presentInActiveHazards && !presentOnMap;
  const presentOnlyInDiagnosticSourceInventory = !currentlyVisibleInAlertPanelDom && !presentInUnifiedIncidents && !presentInActiveHazards && !presentOnMap && (Boolean(membership.appearsInStorage) || Boolean(membership.appearsInSupabaseInventory));
  const presentInUnifiedIncidentsButFilteredBeforeRendering = presentInUnifiedIncidents && !currentlyVisibleInAlertPanelDom && !presentOnMap;
  let auditClassification = "visible_mismatch";
  if (presentOnlyInStaleCache) auditClassification = "stale_cache";
  else if (presentOnlyInDiagnosticSourceInventory) auditClassification = "diagnostic_source_inventory";
  else if (presentInUnifiedIncidentsButFilteredBeforeRendering) auditClassification = "unified_incident_filtered_before_rendering";
  else if (!currentlyVisibleInAlertPanelDom) auditClassification = "stale_diagnostic";
  return {
    currentlyVisibleInAlertPanelDom,
    presentOnlyInStaleCache,
    presentOnlyInDiagnosticSourceInventory,
    presentInUnifiedIncidentsButFilteredBeforeRendering,
    contributesToCurrentSelectedAreaAlertUi: currentlyVisibleInAlertPanelDom,
    auditClassification
  };
}

function gridlyClearedHazardPersistenceRecordSummary(record = {}, source = "unknown", membership = {}, nowMs = Date.now(), currentArea = null) {
  const coord = gridlyClearedHazardPersistenceCoord(record);
  const createdAt = gridlyClearedHazardPersistenceIso(record?.createdAt || record?.created_at || record?.submittedAt || record?.raw?.created_at || record?.latestReport?.submittedAt);
  const updatedAt = gridlyClearedHazardPersistenceIso(record?.updatedAt || record?.updated_at || record?.raw?.updated_at || record?.latestReport?.updated_at || createdAt);
  const clearedAt = gridlyClearedHazardPersistenceIso(gridlyClearedHazardPersistenceClearTime(record));
  const ageMs = new Date(updatedAt || createdAt || 0).getTime();
  const awarenessArea = (() => {
    const explicit = record?.awarenessArea || record?.awareness_area || record?.area || record?.city || record?.town || record?.raw?.awarenessArea || "";
    if (explicit) return String(explicit);
    if (currentArea && typeof isGridlyRecordInAwarenessArea === "function") {
      try { return isGridlyRecordInAwarenessArea(record, currentArea) ? (currentArea.label || currentArea.storageValue || "current") : "outside_current_awareness_area"; } catch (_error) {}
    }
    return "";
  })();
  return {
    id: gridlyClearedHazardPersistenceId(record),
    hazardType: gridlyClearedHazardPersistenceType(record),
    subtype: record?.subtype || record?.hazardSubtype || record?.otherHazardSubtype || record?.raw?.subtype || null,
    title: record?.title || record?.headline || record?.resolvedHeadline || record?.localizedSummary || record?.raw?.title || "",
    roadName: gridlyClearedHazardPersistenceRoadName(record),
    lat: coord ? coord.lat : null,
    lng: coord ? coord.lng : null,
    status: gridlyClearedHazardPersistenceStatus(record, nowMs),
    lifecycleState: gridlyClearedHazardPersistenceLifecycle(record, nowMs),
    source,
    sourceReportId: gridlyClearedHazardPersistenceSourceReportId(record),
    createdAt,
    updatedAt,
    clearedAt,
    ageMinutes: Number.isFinite(ageMs) && ageMs > 0 ? Math.max(0, Math.floor((nowMs - ageMs) / 60000)) : null,
    awarenessArea,
    appearsInActiveHazards: Boolean(membership.appearsInActiveHazards),
    appearsInUnifiedIncidents: Boolean(membership.appearsInUnifiedIncidents),
    appearsInAlerts: Boolean(membership.appearsInAlerts),
    appearsOnMap: Boolean(membership.appearsOnMap),
    appearsInStorage: Boolean(membership.appearsInStorage),
    appearsInSupabaseInventory: Boolean(membership.appearsInSupabaseInventory)
  };
}

async function gridlyReadClearedHazardPersistenceSupabaseInventory(hours = 72) {
  const result = { available: false, rows: [], normalizedRows: [], error: null, queriedHours: hours };
  if (!supabaseClient) {
    result.error = "Supabase client not initialized";
    return result;
  }
  try {
    const hazardTypes = typeof gridlyGetSharedRoadHazardReportTypes === "function" ? gridlyGetSharedRoadHazardReportTypes() : Object.keys(HAZARD_TYPES || {});
    const cutoffIso = new Date(Date.now() - (Math.max(1, Number(hours) || 72) * 60 * 60 * 1000)).toISOString();
    const { data, error } = await supabaseClient
      .from("reports")
      .select("*")
      .gte("created_at", cutoffIso)
      .in("report_type", [...new Set([...hazardTypes, "hazard_cleared"])])
      .order("created_at", { ascending: false })
      .limit(1000);
    if (error) throw error;
    result.available = true;
    result.rows = Array.isArray(data) ? data : [];
    result.normalizedRows = typeof normalizeReports === "function" ? normalizeReports(result.rows) : result.rows;
  } catch (error) {
    result.error = error?.message || "supabase_inventory_failed";
  }
  return result;
}

function gridlyClearedHazardPersistenceLikelyCause(findings = [], sourceBreakdown = {}) {
  if (findings.some((finding) => finding.code === "supabase_active_after_local_clear")) return "A cleared hazard still has an active Supabase source row newer than, or not matched by, the local clear record; reload/area switch can rehydrate it into activeHazards.";
  if (findings.some((finding) => finding.code === "active_after_clear")) return "activeHazards contains a record whose latest lifecycle appears cleared, so local activeHazards is the reintroduction source.";
  if (findings.some((finding) => finding.code === "duplicate_hazard_ids")) return "The same hazard appears under multiple IDs or sourceReportIds, so clearing one record may leave a duplicate active record alive.";
  if (findings.some((finding) => finding.code === "storage_revive_risk")) return "A hazard-like record remains in browser storage/cache and may be merged back into rendered state after reload.";
  if (findings.some((finding) => finding.code === "awareness_mismatch")) return "The selected awareness area filter is admitting active records outside the current area.";
  if (Number(sourceBreakdown?.activeHazards?.count || 0) > 0) return "No definitive cleared-record mismatch was found; active hazards currently originate from activeHazards populated by loadSharedReports().";
  return "No active reintroduction source detected in the audited surfaces.";
}

async function gridlyClearedHazardPersistenceAudit(options = {}) {
  const nowMs = Date.now();
  const currentAwarenessAreaRaw = typeof getGridlySelectedAwarenessArea === "function" ? getGridlySelectedAwarenessArea() : null;
  const currentAwarenessArea = currentAwarenessAreaRaw && typeof getGridlyAwarenessAreaDebugOption === "function" ? getGridlyAwarenessAreaDebugOption(currentAwarenessAreaRaw) : currentAwarenessAreaRaw;
  const safeActiveHazards = gridlyClearedHazardPersistenceSafeArray(activeHazards);
  const safeActiveReports = gridlyClearedHazardPersistenceSafeArray(activeReports);
  const safeRecentlyCleared = gridlyClearedHazardPersistenceSafeArray(recentlyClearedRoadHazards);
  const unifiedIncidents = typeof getUnifiedIncidents === "function" ? gridlyClearedHazardPersistenceSafeArray(getUnifiedIncidents()) : [];
  const renderedAlerts = gridlyClearedHazardPersistenceRenderedAlertRows();
  const renderedMarkers = gridlyClearedHazardPersistenceRenderedMarkers();
  const localStorageAudit = gridlyClearedHazardPersistenceRecordsFromStorageArea(typeof localStorage !== "undefined" ? localStorage : null, "localStorage");
  const sessionStorageAudit = gridlyClearedHazardPersistenceRecordsFromStorageArea(typeof sessionStorage !== "undefined" ? sessionStorage : null, "sessionStorage");
  const storageRecords = [...localStorageAudit.records, ...sessionStorageAudit.records];
  const supabaseInventory = await gridlyReadClearedHazardPersistenceSupabaseInventory(options?.hours || 72);
  const supabaseRecords = gridlyClearedHazardPersistenceSafeArray(supabaseInventory.normalizedRows);
  const alertRecords = [...renderedAlerts.cacheRows, ...renderedAlerts.domRows];

  const idSets = {
    activeHazards: new Set(safeActiveHazards.map(gridlyClearedHazardPersistenceId).filter(Boolean)),
    unifiedIncidents: new Set(unifiedIncidents.map(gridlyClearedHazardPersistenceId).filter(Boolean)),
    alerts: new Set(alertRecords.map(gridlyClearedHazardPersistenceId).filter(Boolean)),
    markers: new Set(renderedMarkers.map(gridlyClearedHazardPersistenceId).filter(Boolean)),
    storage: new Set(storageRecords.map(gridlyClearedHazardPersistenceId).filter(Boolean)),
    supabase: new Set(supabaseRecords.map(gridlyClearedHazardPersistenceId).filter(Boolean))
  };
  const coordinateMatch = (record, rows) => {
    const coord = gridlyClearedHazardPersistenceCoord(record);
    if (!coord) return false;
    return rows.some((row) => {
      const rowCoord = gridlyClearedHazardPersistenceCoord(row);
      return rowCoord && Math.abs(rowCoord.lat - coord.lat) <= 0.00015 && Math.abs(rowCoord.lng - coord.lng) <= 0.00015;
    });
  };
  const appears = (record, setName, rows) => {
    const id = gridlyClearedHazardPersistenceId(record);
    return Boolean((id && idSets[setName]?.has(id)) || coordinateMatch(record, rows));
  };

  const allEntries = [
    ...safeActiveHazards.map((record) => ({ record, source: "activeHazards" })),
    ...safeActiveReports.map((record) => ({ record, source: "activeReports" })),
    ...safeRecentlyCleared.map((record) => ({ record, source: "recentlyClearedRoadHazards" })),
    ...unifiedIncidents.map((record) => ({ record, source: "unifiedIncidents" })),
    ...alertRecords.map((record) => ({ record, source: record?.source === "rendered_alert_dom" ? "renderedAlertDom" : "renderedAlertCache" })),
    ...renderedMarkers.map((record) => ({ record, source: "renderedMapMarkers" })),
    ...storageRecords.map((record) => ({ record, source: record.__gridlyStorageSource || "storage" })),
    ...supabaseRecords.map((record) => ({ record, source: "supabaseInventory" }))
  ];

  const canonical = new Map();
  allEntries.forEach(({ record, source }) => {
    const key = gridlyClearedHazardPersistenceDuplicateKey(record);
    const existing = canonical.get(key) || { key, records: [], sources: new Set() };
    existing.records.push(record);
    existing.sources.add(source);
    canonical.set(key, existing);
  });

  const sourceBreakdown = {
    activeHazards: { count: safeActiveHazards.length, clearedLike: safeActiveHazards.filter((record) => gridlyClearedHazardPersistenceStatus(record, nowMs) === "cleared").length },
    activeReports: { count: safeActiveReports.length },
    unifiedIncidents: { count: unifiedIncidents.length, active: unifiedIncidents.filter((record) => String(record?.status || "").toLowerCase() === "active").length, cleared: unifiedIncidents.filter((record) => String(record?.status || "").toLowerCase() === "cleared").length },
    renderedAlerts: { cacheCount: renderedAlerts.cacheRows.length, domCount: renderedAlerts.domRows.length, total: alertRecords.length },
    renderedMapMarkers: { count: renderedMarkers.length },
    recentlyClearedRoadHazards: { count: safeRecentlyCleared.length },
    supabaseInventory: { available: supabaseInventory.available, count: supabaseRecords.length, error: supabaseInventory.error },
    storage: { localStorage: localStorageAudit.breakdown, sessionStorage: sessionStorageAudit.breakdown }
  };

  const lifecycleBreakdown = allEntries.reduce((acc, { record, source }) => {
    const state = gridlyClearedHazardPersistenceLifecycle(record, nowMs);
    acc[state] = acc[state] || { total: 0, sources: {} };
    acc[state].total += 1;
    acc[state].sources[source] = (acc[state].sources[source] || 0) + 1;
    return acc;
  }, {});

  const suspicious = [];
  const addSuspicious = (record, source, reasonCode, reason) => {
    const summary = gridlyClearedHazardPersistenceRecordSummary(record, source, {
      appearsInActiveHazards: appears(record, "activeHazards", safeActiveHazards),
      appearsInUnifiedIncidents: appears(record, "unifiedIncidents", unifiedIncidents),
      appearsInAlerts: appears(record, "alerts", alertRecords),
      appearsOnMap: appears(record, "markers", renderedMarkers),
      appearsInStorage: appears(record, "storage", storageRecords),
      appearsInSupabaseInventory: appears(record, "supabase", supabaseRecords)
    }, nowMs, currentAwarenessAreaRaw);
    suspicious.push({ ...summary, reasonCode, reason });
  };

  safeActiveHazards.forEach((hazard) => {
    const latestState = typeof gridlyRoadHazardLatestLifecycleState === "function" ? gridlyRoadHazardLatestLifecycleState(hazard, [...safeActiveHazards, ...safeRecentlyCleared, ...supabaseRecords]) : gridlyClearedHazardPersistenceLifecycle(hazard, nowMs);
    if (["cleared", "recently_cleared", "hazard_cleared"].includes(String(latestState || "").toLowerCase()) || gridlyClearedHazardPersistenceType(hazard) === "hazard_cleared") {
      addSuspicious(hazard, "activeHazards", "active_after_clear", "Record is present in activeHazards even though latest lifecycle resolves to cleared/recently cleared.");
    }
  });

  safeRecentlyCleared.forEach((clear) => {
    if (appears(clear, "activeHazards", safeActiveHazards)) addSuspicious(clear, "recentlyClearedRoadHazards", "cleared_but_active", "Recently cleared record matches an activeHazards record by ID or coordinate.");
    if (appears(clear, "markers", renderedMarkers)) addSuspicious(clear, "recentlyClearedRoadHazards", "cleared_marker", "Recently cleared record still has a rendered map marker.");
    if (appears(clear, "alerts", alertRecords)) addSuspicious(clear, "recentlyClearedRoadHazards", "cleared_alert", "Recently cleared record still has a rendered alert row/cache entry.");
    if (supabaseInventory.available && !appears(clear, "supabase", supabaseRecords)) addSuspicious(clear, "recentlyClearedRoadHazards", "local_clear_missing_supabase", "Local recently cleared record was not found in the Supabase hazard inventory window.");
  });

  supabaseRecords.forEach((record) => {
    const status = gridlyClearedHazardPersistenceStatus(record, nowMs, supabaseRecords);
    if (status === "cleared" && appears(record, "activeHazards", safeActiveHazards)) addSuspicious(record, "supabaseInventory", "supabase_cleared_local_active", "Supabase inventory has a cleared record that still matches local activeHazards.");
    if (status !== "cleared" && coordinateMatch(record, safeRecentlyCleared)) addSuspicious(record, "supabaseInventory", "supabase_active_after_local_clear", "Supabase inventory has an active record matching a locally recently cleared hazard.");
  });

  const coordinateGroups = new Map();
  allEntries.forEach(({ record, source }) => {
    const coord = gridlyClearedHazardPersistenceCoord(record);
    if (!coord) return;
    const key = `coord:${gridlyClearedHazardPersistenceType(record)}:${coord.lat.toFixed(4)}:${coord.lng.toFixed(4)}`;
    const existing = coordinateGroups.get(key) || { key, records: [], sources: new Set() };
    existing.records.push(record);
    existing.sources.add(source);
    coordinateGroups.set(key, existing);
  });
  const sourceReportGroups = new Map();
  allEntries.forEach(({ record, source }) => {
    const sourceReportId = gridlyClearedHazardPersistenceSourceReportId(record);
    if (!sourceReportId) return;
    const key = `sourceReportId:${sourceReportId}`;
    const existing = sourceReportGroups.get(key) || { key, records: [], sources: new Set() };
    existing.records.push(record);
    existing.sources.add(source);
    sourceReportGroups.set(key, existing);
  });
  const duplicateHazardGroups = [...canonical.values(), ...coordinateGroups.values(), ...sourceReportGroups.values()]
    .map((group) => {
      const ids = [...new Set(group.records.map(gridlyClearedHazardPersistenceId).filter(Boolean))];
      const sourceReportIds = [...new Set(group.records.map(gridlyClearedHazardPersistenceSourceReportId).filter(Boolean))];
      return { key: group.key, count: group.records.length, ids, sourceReportIds, sources: [...group.sources] };
    })
    .filter((group, index, groups) => {
      const duplicateSignature = `${group.key}|${group.ids.join(",")}|${group.sourceReportIds.join(",")}|${group.sources.join(",")}`;
      const firstIndex = groups.findIndex((candidate) => `${candidate.key}|${candidate.ids.join(",")}|${candidate.sourceReportIds.join(",")}|${candidate.sources.join(",")}` === duplicateSignature);
      return index === firstIndex && group.count > 1 && (group.ids.length > 1 || group.sourceReportIds.length > 1 || group.sources.length > 1);
    });

  duplicateHazardGroups.forEach((group) => {
    const firstRecord = canonical.get(group.key)?.records?.[0];
    if (firstRecord) addSuspicious(firstRecord, "duplicateHazardGroups", "duplicate_hazard_ids", "Same hazard cluster/source appears under multiple IDs, source IDs, or surfaces.");
  });

  const awarenessAreaMismatchRecords = alertRecords.filter((record) => {
    if (!currentAwarenessAreaRaw || currentAwarenessAreaRaw.countyWide || currentAwarenessAreaRaw.fallback) return false;
    try { return !isGridlyRecordInAwarenessArea(record, currentAwarenessAreaRaw); } catch (_error) { return false; }
  }).map((record) => {
    const source = record?.source === "rendered_alert_dom" ? "renderedAlertDom" : "renderedAlertCache";
    const membership = {
      appearsInActiveHazards: appears(record, "activeHazards", safeActiveHazards),
      appearsInUnifiedIncidents: appears(record, "unifiedIncidents", unifiedIncidents),
      appearsInAlerts: true,
      appearsOnMap: appears(record, "markers", renderedMarkers),
      appearsInStorage: appears(record, "storage", storageRecords),
      appearsInSupabaseInventory: appears(record, "supabase", supabaseRecords)
    };
    return {
      ...gridlyClearedHazardPersistenceRecordSummary(record, source, membership, nowMs, currentAwarenessAreaRaw),
      crossingId: record?.crossingId || record?.crossing_id || record?.raw?.crossingId || record?.raw?.crossing_id || null,
      ...gridlyExplainAlertAwarenessSurvival(record, currentAwarenessAreaRaw),
      ...gridlyClassifyAwarenessAreaMismatchRecord(record, renderedAlerts, membership)
    };
  });
  const visibleMismatchRecords = awarenessAreaMismatchRecords.filter((record) => record.contributesToCurrentSelectedAreaAlertUi);
  const staleDiagnosticRecords = awarenessAreaMismatchRecords.filter((record) => !record.contributesToCurrentSelectedAreaAlertUi);
  visibleMismatchRecords.forEach((record) => addSuspicious(record, record.source || "renderedAlerts", "awareness_mismatch", "Visible alert is outside the selected awareness area."));

  storageRecords.filter((record) => gridlyClearedHazardPersistenceStatus(record, nowMs) !== "cleared" && coordinateMatch(record, safeRecentlyCleared)).forEach((record) => {
    addSuspicious(record, record.__gridlyStorageSource || "storage", "storage_revive_risk", "Browser storage contains an active-looking hazard matching a recently cleared hazard.");
  });

  const findingsMap = suspicious.reduce((acc, record) => {
    const item = acc.get(record.reasonCode) || { code: record.reasonCode, count: 0, summary: record.reason, affectedSources: new Set() };
    item.count += 1;
    item.affectedSources.add(record.source);
    acc.set(record.reasonCode, item);
    return acc;
  }, new Map());
  const findings = [...findingsMap.values()].map((item) => ({ ...item, affectedSources: [...item.affectedSources] }));
  if (!findings.length) findings.push({ code: "no_persistence_mismatch_detected", count: 0, summary: "No cleared hazard persistence mismatch was detected in the audited sources.", affectedSources: [] });

  const clearedButStillActive = suspicious.filter((record) => ["active_after_clear", "cleared_but_active", "supabase_cleared_local_active"].includes(record.reasonCode));
  const staleActiveRecords = suspicious.filter((record) => ["supabase_active_after_local_clear", "storage_revive_risk"].includes(record.reasonCode) || (record.status === "active" && Number(record.ageMinutes) > (RECENTLY_CLEARED_WINDOW_MINUTES || 90)));
  const storageBreakdown = {
    localStorage: localStorageAudit.breakdown,
    sessionStorage: sessionStorageAudit.breakdown,
    suspiciousStorageRecords: suspicious.filter((record) => record.appearsInStorage).length
  };
  const recentClearIndex = typeof gridlyBuildRecentRoadClearIndex === "function" ? gridlyBuildRecentRoadClearIndex([...safeActiveHazards, ...safeRecentlyCleared, ...supabaseRecords], nowMs) : new Map();
  const runtimeSuppressedRecords = gridlyDiagnosticArray(gridlyClearedHazardRehydrationGuardState?.suppressedRecords);
  const rehydrationSuppressedRecords = runtimeSuppressedRecords.length
    ? runtimeSuppressedRecords
    : safeActiveHazards.map((hazard) => {
      const clear = gridlyFindRecentClearForRoadHazard(hazard, [...safeActiveHazards, ...safeRecentlyCleared, ...supabaseRecords], recentClearIndex, nowMs);
      return clear ? gridlySummarizeRehydrationSuppression(hazard, clear, "audit", nowMs) : null;
    }).filter(Boolean);
  const suppressedButStillStoredRecords = rehydrationSuppressedRecords.map((record) => {
    const appearsInAlertCache = renderedAlerts.cacheRows.some((row) => gridlyClearedHazardPersistenceRecordsMatch(record, row));
    const appearsInVisibleAlertPanelDom = gridlyClearedHazardPersistenceVisibleDomAlertRows(renderedAlerts).some((row) => gridlyClearedHazardPersistenceRecordsMatch(record, row));
    const appearsOnMap = appears(record, "markers", renderedMarkers);
    return {
      ...record,
      appearsInStorage: appears(record, "storage", storageRecords),
      appearsInSupabaseInventory: appears(record, "supabase", supabaseRecords),
      appearsInAlertCache,
      appearsInVisibleAlertPanelDom,
      appearsOnMap,
      rendersAsActiveAlertOrMarker: Boolean(appearsInVisibleAlertPanelDom || appearsOnMap)
    };
  }).filter((record) => record.appearsInStorage || record.appearsInSupabaseInventory || record.appearsInAlertCache || record.appearsInVisibleAlertPanelDom || record.appearsOnMap);
  const alertAreaFilterApplied = true;
  const alertAreaFilteredOutRecords = gridlyDiagnosticArray(gridlyAlertAreaFilterState?.filteredOutRecords);
  const selectedAwarenessAreaMode = gridlyAlertAreaFilterState?.selectedMode || (currentAwarenessAreaRaw?.countyWide || currentAwarenessAreaRaw?.fallback ? "county" : "town");
  const selectedAwarenessAreaLabel = gridlyAlertAreaFilterState?.selectedLabel || currentAwarenessAreaRaw?.label || GRIDLY_COUNTY_WIDE_AWARENESS_LABEL;
  const activeCrossingReportRecords = safeActiveReports.filter((record) => isGridlyCrossingReportRecord(record) && (typeof getIncidentLifecycleState !== "function" || getIncidentLifecycleState(record) === "active"));
  const crossingAreaFilter = typeof gridlyGetCrossingReportAreaFilter === "function"
    ? gridlyGetCrossingReportAreaFilter(activeCrossingReportRecords, "clearedHazardPersistenceAudit.activeReports")
    : { applied: false, inSelectedArea: activeCrossingReportRecords, outsideSelectedArea: [], filteredOutRecords: [], filteredOutCount: 0 };
  const crossingOutsideContributionRecords = gridlyDiagnosticArray(crossingAreaFilter.outsideSelectedArea).map((record) => gridlyCrossingAreaFilterRecordSummary(record, "activeReportsOutsideSelectedArea")).map((summary, index) => {
    const record = crossingAreaFilter.outsideSelectedArea[index];
    return {
      ...summary,
      appearsInUnifiedIncidents: appears(record, "unifiedIncidents", unifiedIncidents),
      appearsInAlerts: appears(record, "alerts", alertRecords),
      appearsOnMap: appears(record, "markers", renderedMarkers),
      contributesToTopAwareness: Boolean(gridlyCommunityPulseAuditState?.activeAwareness?.activeAwarenessSamples?.some?.((sample) => sample?.sourceKind === "activeReport" && (sample?.resolvedLocationLabel === summary.area || sample?.reusedAlertText === summary.title))),
      contributesToAwarenessCard: Boolean(gridlyCommunityPulseAuditState?.communityAwarenessSummary?.activeReportsInArea?.some?.((item) => gridlyClearedHazardPersistenceId(item) === gridlyClearedHazardPersistenceId(record)))
    };
  });
  const crossingAreaFilteredOutRecords = crossingOutsideContributionRecords.length ? crossingOutsideContributionRecords : gridlyDiagnosticArray(crossingAreaFilter.filteredOutRecords);
  const crossingAreaFilterApplied = Boolean(crossingAreaFilter.applied);
  const crossingAreaFilterPass = crossingAreaFilterApplied && crossingOutsideContributionRecords.every((record) => !record.appearsInUnifiedIncidents && !record.appearsInAlerts && !record.appearsOnMap && !record.contributesToTopAwareness && !record.contributesToAwarenessCard);
  const clearedRehydrationGuardPass = clearedButStillActive.length === 0 && suppressedButStillStoredRecords.every((record) => !record.rendersAsActiveAlertOrMarker);
  const alertAreaFilterPass = alertAreaFilterApplied && visibleMismatchRecords.length === 0;

  const audit = {
    version: GRIDLY_CLEARED_HAZARD_PERSISTENCE_AUDIT_VERSION,
    generatedAt: new Date(nowMs).toISOString(),
    currentAwarenessArea,
    activeHazardCount: safeActiveHazards.length,
    activeReportCount: safeActiveReports.length,
    unifiedIncidentCount: unifiedIncidents.length,
    renderedAlertCount: alertRecords.length,
    renderedMarkerCount: renderedMarkers.length,
    recentlyClearedCount: safeRecentlyCleared.length,
    clearedButStillActive,
    duplicateHazardGroups,
    staleActiveRecords,
    sourceBreakdown,
    lifecycleBreakdown,
    storageBreakdown,
    awarenessAreaMismatchRecords,
    visibleMismatchRecords,
    staleDiagnosticRecords,
    rehydrationSuppressedCount: rehydrationSuppressedRecords.length,
    rehydrationSuppressedRecords,
    suppressedButStillStoredRecords,
    alertAreaFilterApplied,
    alertAreaFilteredOutCount: alertAreaFilteredOutRecords.length,
    alertAreaFilteredOutRecords,
    crossingAreaFilterApplied,
    crossingAreaFilterPass,
    crossingAreaFilteredOutCount: crossingAreaFilteredOutRecords.length,
    crossingAreaFilteredOutRecords,
    activeCrossingReportsInSelectedArea: gridlyDiagnosticArray(crossingAreaFilter.inSelectedArea).map((record) => gridlyCrossingAreaFilterRecordSummary(record, "activeReportsInSelectedArea")),
    activeCrossingReportsOutsideSelectedArea: crossingAreaFilteredOutRecords,
    selectedAwarenessAreaMode,
    selectedAwarenessAreaLabel,
    clearedRehydrationGuardPass,
    alertAreaFilterPass,
    recentlyClearedIndex: {
      count: recentClearIndex?.size || 0,
      keys: recentClearIndex?.size ? [...recentClearIndex.keys()].slice(0, 40) : []
    },
    findings,
    likelyCause: gridlyClearedHazardPersistenceLikelyCause(findings, sourceBreakdown),
    safeToPatch: findings.some((finding) => finding.code !== "no_persistence_mismatch_detected"),
    suspiciousRecords: suspicious
  };
  console.info("gridlyClearedHazardPersistenceAudit", audit);
  return audit;
}

if (typeof window !== "undefined") {
  window.gridlyClearedHazardPersistenceAudit = gridlyClearedHazardPersistenceAudit;
}
exposeGridlyAuditHelper("gridlyClearedHazardPersistenceAudit", gridlyClearedHazardPersistenceAudit);

function gridlyReadTxdotDiagnostics() {
  if (typeof window === "undefined") return {};
  if (typeof window.gridlyTxdot?.getDiagnostics === "function") return window.gridlyTxdot.getDiagnostics() || {};
  const normalizedRows = Array.isArray(window.gridlyTxdot?.getRoadConditions?.()) ? window.gridlyTxdot.getRoadConditions() : [];
  const rawRows = Array.isArray(window.gridlyTxdot?.getRawRoadConditions?.())
    ? window.gridlyTxdot.getRawRoadConditions()
    : (Array.isArray(window.gridlyTxdotRawRoadConditions) ? window.gridlyTxdotRawRoadConditions : []);
  return {
    rawCount: rawRows.length,
    normalizedCount: normalizedRows.length,
    rawIncidentCount: rawRows.length,
    rawConstructionCount: rawRows.filter((row) => /construct|maintenance|lane closure|work zone/i.test(`${row?.condition || ""} ${row?.type || ""} ${row?.description || ""}`)).length,
    rawConditionCount: rawRows.length,
    sampleRawRows: rawRows.slice(0, 3),
    sampleNormalizedRows: normalizedRows.slice(0, 3)
  };
}

function gridlyHasFiniteTxdotCoordinates(item = {}) {
  const lat = item?.lat ?? item?.latitude ?? item?.rawLat;
  const lng = item?.lng ?? item?.lon ?? item?.longitude ?? item?.rawLng;
  return Number.isFinite(Number(lat)) && Number.isFinite(Number(lng));
}

function gridlyIsTxdotActiveByDate(item = {}, now = new Date()) {
  const status = String(item?.status || item?.state || "active").toLowerCase();
  if (["cleared", "closed", "expired", "inactive"].includes(status)) return false;
  const startRaw = item?.startTime || item?.start_time || item?.created_at || item?.updated_at;
  const endRaw = item?.endTime || item?.end_time || item?.expires_at;
  const startMs = startRaw ? Date.parse(startRaw) : NaN;
  const endMs = endRaw ? Date.parse(endRaw) : NaN;
  const nowMs = now.getTime();
  if (Number.isFinite(startMs) && startMs > nowMs) return false;
  if (Number.isFinite(endMs) && endMs < nowMs) return false;
  return true;
}

function gridlyFindTxdotRowsInCollection(collection = []) {
  return (Array.isArray(collection) ? collection : []).filter((item) => {
    const source = String(item?.source || item?.provider || item?.agency || "").toLowerCase();
    const id = String(item?.id || item?.incidentId || item?.reportId || item?.raw?.id || "").toLowerCase();
    const title = String(item?.title || item?.headline || item?.description || item?.raw?.title || "").toLowerCase();
    return source.includes("txdot") || source.includes("drive texas") || id.includes("txdot") || title.includes("txdot") || title.includes("drive texas");
  });
}

function gridlyBuildTxdotSourceBlockers(details = {}) {
  const blockers = [];
  const configured = Boolean(details.txdotFetchConfigured);
  const hasFetched = Boolean(details.txdotLastFetchAttempt);
  const rawCount = Number(details.txdotRawConditionCount || 0);
  const normalizedCount = Number(details.txdotNormalizedCount || 0);
  const unifiedCount = Number(details.txdotUnifiedIncidentCount || 0);
  const renderedCount = Number(details.txdotRenderedMarkerCount || 0);
  const alertCount = Number(details.txdotRenderedAlertCount || 0);

  if (!configured) {
    blockers.push("no TxDOT fetch configured: gridlyTxdot service/config is present only when an endpoint, fetch helper, and API key are available.");
  } else if (!hasFetched) {
    blockers.push("fetch configured but not called: gridlyTxdot.fetchRoadConditions exists, but no runtime fetch attempt has been recorded.");
  } else if (details.txdotLastFetchSuccess === false) {
    blockers.push(`fetch called but failed: ${details.txdotLastFetchError || "unknown TxDOT fetch error"}.`);
  } else if (rawCount === 0) {
    blockers.push("fetch called but returns 0: no raw TxDOT condition rows are currently cached.");
  }

  if (rawCount > 0 && normalizedCount === 0) {
    blockers.push("data exists but not normalized: raw TxDOT rows are cached, but gridlyTxdot normalized road conditions are empty.");
  }

  if (normalizedCount > 0 && unifiedCount === 0) {
    blockers.push("normalized but not added to activeHazards/unified incidents: TxDOT service rows remain in gridlyExternalRoadConditions and are not emitted by futureTxdotIncidents(), futureTxdotConstruction(), or activeHazards.");
  }

  if (unifiedCount > 0 && renderedCount === 0) {
    blockers.push("incidents exist but not rendered as markers: TxDOT rows are present in unified incidents but no TxDOT marker DOM/layer entries were detected.");
  }

  if (unifiedCount > 0 && alertCount === 0) {
    blockers.push("incidents exist but not rendered on the alert surface: TxDOT unified incidents were found, but the current alerts snapshot/cache contains no TxDOT rows.");
  }

  if (normalizedCount > 0 && details.txdotDateFilteredCount > 0) {
    blockers.push(`incidents exist but filtered out by date/status: ${details.txdotDateFilteredCount} normalized TxDOT row(s) are outside the active status/time window.`);
  }

  if (normalizedCount > 0 && details.txdotSourceFilteredCount > 0) {
    blockers.push(`incidents exist but filtered out by source: ${details.txdotSourceFilteredCount} normalized TxDOT row(s) do not carry a txdot source label.`);
  }

  if (normalizedCount > 0 && details.txdotMissingCoordinateCount > 0) {
    blockers.push(`incidents exist but filtered out by bounds/marker eligibility: ${details.txdotMissingCoordinateCount} normalized TxDOT row(s) lack finite latitude/longitude for map marker rendering.`);
  }

  if (!blockers.length) blockers.push("no TxDOT source blocker detected in the current cached runtime state.");
  return blockers;
}

function gridlyTxDotSourceAudit() {
  const txdotService = window.gridlyTxdot || null;
  const txdotConfig = window.GRIDLY_CONFIG?.txdot || null;
  const txdotState = window.gridlyTxdotState || {};
  const diagnostics = gridlyReadTxdotDiagnostics();
  const normalizedRows = Array.isArray(txdotService?.getRoadConditions?.()) ? txdotService.getRoadConditions() : (Array.isArray(window.gridlyExternalRoadConditions) ? window.gridlyExternalRoadConditions : []);
  const rawRows = Array.isArray(txdotService?.getRawRoadConditions?.()) ? txdotService.getRawRoadConditions() : (Array.isArray(window.gridlyTxdotRawRoadConditions) ? window.gridlyTxdotRawRoadConditions : []);
  const now = new Date();
  const txdotFutureIncidents = typeof futureTxdotIncidents === "function" ? futureTxdotIncidents() : [];
  const txdotFutureConstruction = typeof futureTxdotConstruction === "function" ? futureTxdotConstruction() : [];
  const unifiedIncidents = typeof getUnifiedIncidents === "function" ? getUnifiedIncidents() : [];
  const alertsSnapshot = typeof window.getAlertsSurfaceSnapshot === "function" ? window.getAlertsSurfaceSnapshot() : null;
  const alertItems = Array.isArray(alertsSnapshot?.alerts) ? alertsSnapshot.alerts : (Array.isArray(window.__gridlyLatestAlertsForRender) ? window.__gridlyLatestAlertsForRender : []);
  const txdotUnifiedRows = gridlyFindTxdotRowsInCollection(unifiedIncidents);
  const txdotAlertRows = gridlyFindTxdotRowsInCollection(alertItems);
  const renderedTxdotMarkerCount = typeof document !== "undefined"
    ? document.querySelectorAll("#map .gridly-marker-txdot-single, #map .gridly-marker-txdot-corridor, #map .gridly-marker-txdot-route-impact, #map [data-visual-style^='txdot'], #map [data-incident-id*='txdot' i]").length
    : 0;
  const mapEligibleRows = normalizedRows.filter((row) => gridlyHasFiniteTxdotCoordinates(row) && gridlyIsTxdotActiveByDate(row, now));
  const alertEligibleRows = normalizedRows.filter((row) => gridlyIsTxdotActiveByDate(row, now) && (row?.title || row?.description || row?.roadName || row?.routeNameDisplay));
  const dateFilteredCount = normalizedRows.filter((row) => !gridlyIsTxdotActiveByDate(row, now)).length;
  const sourceFilteredCount = normalizedRows.filter((row) => !String(row?.source || "").toLowerCase().includes("txdot")).length;
  const missingCoordinateCount = normalizedRows.filter((row) => !gridlyHasFiniteTxdotCoordinates(row)).length;
  const helpersFound = {
    gridlyTxdot: Boolean(txdotService),
    fetchRoadConditions: typeof txdotService?.fetchRoadConditions === "function",
    normalizeIncident: typeof txdotService?.normalizeIncident === "function",
    getRoadConditions: typeof txdotService?.getRoadConditions === "function",
    getRawRoadConditions: typeof txdotService?.getRawRoadConditions === "function",
    getDiagnostics: typeof txdotService?.getDiagnostics === "function",
    futureTxdotIncidents: typeof futureTxdotIncidents === "function",
    futureTxdotConstruction: typeof futureTxdotConstruction === "function"
  };
  const configFound = {
    hasConfigObject: Boolean(txdotConfig && typeof txdotConfig === "object"),
    hasApiKey: Boolean(String(txdotConfig?.apiKey || "").trim()),
    hasEndpointTemplate: Boolean(String(txdotConfig?.endpointTemplate || "").trim()),
    refreshIntervalMs: Number.isFinite(Number(txdotConfig?.refreshIntervalMs)) ? Number(txdotConfig.refreshIntervalMs) : null
  };
  const txdotFetchConfigured = Boolean(helpersFound.fetchRoadConditions && configFound.hasEndpointTemplate && configFound.hasApiKey);
  const auditDetails = {
    txdotFetchConfigured,
    txdotLastFetchAttempt: txdotState.lastFetchTime || diagnostics.lastFetchTime || null,
    txdotLastFetchSuccess: txdotState.lastFetchOk ?? diagnostics.lastFetchOk ?? null,
    txdotLastFetchError: txdotState.lastError || diagnostics.lastError || null,
    txdotRawConditionCount: Number(diagnostics.rawConditionCount ?? diagnostics.rawCount ?? rawRows.length) || 0,
    txdotNormalizedCount: normalizedRows.length,
    txdotUnifiedIncidentCount: txdotUnifiedRows.length,
    txdotUnifiedIncidents: txdotUnifiedRows.length,
    txdotRenderedMarkerCount: renderedTxdotMarkerCount,
    txdotRenderedAlertCount: txdotAlertRows.length,
    txdotDateFilteredCount: dateFilteredCount,
    txdotSourceFilteredCount: sourceFilteredCount,
    txdotMissingCoordinateCount: missingCoordinateCount,
    txdotRowsSkippedNoCoordinates: missingCoordinateCount
  };
  return {
    txdotHelpersFound: helpersFound,
    txdotConfigFound: configFound,
    txdotFetchConfigured,
    txdotLastFetchAttempt: auditDetails.txdotLastFetchAttempt,
    txdotLastFetchSuccess: auditDetails.txdotLastFetchSuccess,
    txdotRawIncidentCount: Number(diagnostics.rawIncidentCount ?? rawRows.length) || 0,
    txdotRawConstructionCount: Number(diagnostics.rawConstructionCount ?? 0) || 0,
    txdotRawConditionCount: auditDetails.txdotRawConditionCount,
    txdotNormalizedCount: normalizedRows.length,
    futureTxdotIncidents: txdotFutureIncidents.length,
    futureTxdotConstruction: txdotFutureConstruction.length,
    txdotUnifiedIncidents: txdotUnifiedRows.length,
    txdotMapEligibleCount: mapEligibleRows.length,
    txdotAlertEligibleCount: alertEligibleRows.length,
    txdotRowsSkippedNoCoordinates: missingCoordinateCount,
    sampleTxdotUnifiedRows: txdotUnifiedRows.slice(0, 5),
    sampleRawRows: Array.isArray(diagnostics.sampleRawRows) ? diagnostics.sampleRawRows : rawRows.slice(0, 3),
    sampleNormalizedRows: Array.isArray(diagnostics.sampleNormalizedRows) ? diagnostics.sampleNormalizedRows : normalizedRows.slice(0, 3),
    blockers: gridlyBuildTxdotSourceBlockers(auditDetails),
    trace: {
      fetchConfig: configFound,
      rawRows: auditDetails.txdotRawConditionCount,
      normalizedRows: normalizedRows.length,
      activeHazardCandidates: normalizedRows.filter((row) => String(row?.source || "").toLowerCase().includes("txdot")).length,
      activeHazardsRows: gridlyFindTxdotRowsInCollection(Array.isArray(activeHazards) ? activeHazards : []).length,
      futureTxdotIncidents: txdotFutureIncidents.length,
      futureTxdotConstruction: txdotFutureConstruction.length,
      txdotUnifiedIncidents: txdotUnifiedRows.length,
      unifiedIncidents: txdotUnifiedRows.length,
      txdotMapEligibleCount: mapEligibleRows.length,
      txdotRowsSkippedNoCoordinates: missingCoordinateCount,
      sampleTxdotUnifiedRows: txdotUnifiedRows.slice(0, 3),
      alertSurfaceRows: txdotAlertRows.length,
      mapMarkers: renderedTxdotMarkerCount
    },
    nextPatchRecommendation: txdotUnifiedRows.length > 0
      ? "TxDOT cached normalized rows are wired through futureTxdotIncidents()/futureTxdotConstruction(); if startup automation is needed, add a cache-respecting one-time fetch in a later patch."
      : "After a manual await window.gridlyTxdot?.fetchRoadConditions?.(), verify cached rows have finite coordinates and flow through futureTxdotIncidents()/futureTxdotConstruction(); keep Supabase activeHazards/user hazard ownership unchanged."
  };
}

window.gridlyTxDotSourceAudit = gridlyTxDotSourceAudit;
exposeGridlyAuditHelper("gridlyTxDotSourceAudit", gridlyTxDotSourceAudit);


let gridlyTxdotStartupFetchPromise = null;
let gridlyTxdotStartupFetchAttempted = false;

if (typeof window !== "undefined" && window.GRIDLY_ENABLE_TXDOT_STARTUP_FETCH === undefined) {
  window.GRIDLY_ENABLE_TXDOT_STARTUP_FETCH = false;
}

function gridlyIsTxdotStartupFetchEnabled() {
  return typeof window !== "undefined" && window.GRIDLY_ENABLE_TXDOT_STARTUP_FETCH === true;
}

function gridlyIsTxdotFetchAvailable() {
  const txdotService = window.gridlyTxdot || null;
  const txdotConfig = window.GRIDLY_CONFIG?.txdot || null;
  return Boolean(
    typeof txdotService?.fetchRoadConditions === "function"
    && String(txdotConfig?.endpointTemplate || "").trim()
    && String(txdotConfig?.apiKey || "").trim()
  );
}

function gridlyTxdotPickFirstPresent(record = {}, keys = []) {
  if (!record || typeof record !== "object") return undefined;
  for (const key of keys) {
    if (record[key] !== undefined && record[key] !== null && String(record[key]).trim() !== "") return record[key];
  }
  return undefined;
}

function gridlyTxdotDirectionalFieldExample(rows = [], aliases = []) {
  const safeRows = Array.isArray(rows) ? rows : [];
  for (const row of safeRows) {
    const value = gridlyTxdotPickFirstPresent(row, aliases);
    if (value !== undefined) return value;
  }
  return null;
}

function gridlyTxdotFieldInventoryRow(config = {}, rawRows = [], normalizedRows = [], unifiedRows = []) {
  const rawAliases = Array.isArray(config.rawAliases) ? config.rawAliases : [];
  const normalizedAliases = Array.isArray(config.normalizedAliases) ? config.normalizedAliases : [];
  const storedAliases = Array.isArray(config.storedAliases) ? config.storedAliases : [];
  const rawExample = gridlyTxdotDirectionalFieldExample(rawRows, rawAliases);
  const normalizedExample = gridlyTxdotDirectionalFieldExample(normalizedRows, normalizedAliases);
  const storedExample = gridlyTxdotDirectionalFieldExample(unifiedRows, storedAliases);
  const observedRaw = rawExample !== null;
  const observedNormalized = normalizedExample !== null;
  const observedStored = storedExample !== null;
  const normalizedField = normalizedAliases[0] || null;
  const storedField = storedAliases[0] || null;
  const preserved = Boolean(config.preserved || observedStored || (config.storage === "memory_normalized_cache" && observedNormalized));
  return {
    rawField: rawAliases[0] || null,
    rawAliases,
    normalizedField,
    normalizedAliases,
    storedField,
    storedAliases,
    storage: config.storage || (storedField ? "unified_incident_memory" : (normalizedField ? "normalized_cache_only" : "not_stored")),
    usedByGridly: config.usedByGridly || "not_used_for_directional_labeling",
    ignoredByGridly: config.ignoredByGridly || "not promoted beyond current TxDOT cache/unified incident path",
    directionalUse: config.directionalUse || "LOW VALUE",
    helps: config.helps || [],
    preserved,
    discarded: Boolean(config.discarded || (!preserved && (rawAliases.length || normalizedAliases.length))),
    observed: { raw: observedRaw, normalized: observedNormalized, stored: observedStored },
    examples: { raw: rawExample, normalized: normalizedExample, stored: storedExample },
    note: config.note || ""
  };
}

function gridlyTxdotDirectionalReadinessAudit(options = {}) {
  const includeConnectedAudits = gridlyShouldRunConnectedAuditSnapshots(options);
  const target = typeof window !== "undefined" ? window : globalThis;
  const txdotService = target?.gridlyTxdot || null;
  const rawRows = typeof txdotService?.getRawRoadConditions === "function"
    ? txdotService.getRawRoadConditions()
    : (Array.isArray(target?.gridlyTxdotRawRoadConditions) ? target.gridlyTxdotRawRoadConditions : []);
  const normalizedRows = typeof txdotService?.getRoadConditions === "function"
    ? txdotService.getRoadConditions()
    : (Array.isArray(target?.gridlyExternalRoadConditions) ? target.gridlyExternalRoadConditions : []);
  const unifiedRows = typeof getUnifiedIncidents === "function"
    ? gridlyFindTxdotRowsInCollection(getUnifiedIncidents())
    : [];
  const sourceAudit = includeConnectedAudits && typeof gridlyTxDotSourceAudit === "function" ? gridlyTxDotSourceAudit() : null;
  const directionalRoadAudit = includeConnectedAudits && typeof gridlyDirectionalRoadAudit === "function" ? gridlyDirectionalRoadAudit({ maxDistanceMeters: 75, includeConnectedAudits: false }) : null;
  const rawObservedFields = Array.from(new Set(rawRows.flatMap((row) => row && typeof row === "object" ? Object.keys(row) : []))).sort();
  const normalizedObservedFields = Array.from(new Set(normalizedRows.flatMap((row) => row && typeof row === "object" ? Object.keys(row) : []))).sort();
  const unifiedObservedFields = Array.from(new Set(unifiedRows.flatMap((row) => row && typeof row === "object" ? Object.keys(row) : []))).sort();
  const inventoryConfig = [
    {
      rawAliases: ["travel_direction", "direction", "route_direction"],
      normalizedAliases: ["direction"],
      storedAliases: ["direction"],
      storage: "normalized_cache_and_unified_incident_memory",
      usedByGridly: "preserved on TxDOT normalized/unified objects but not used for marker placement, side-of-road selection, or alert labels",
      ignoredByGridly: "not used by gridlyDirectionalRoadAudit and not displayed as NB/SB/EB/WB in current reporting output",
      directionalUse: "HIGH VALUE",
      helps: ["road direction", "hazard direction"],
      preserved: true,
      note: "normalizeDirection() maps N/S/E/W and NB/SB/EB/WB into cardinal labels; unknown or missing values remain unknown."
    },
    {
      rawAliases: ["route_name", "route", "highway"],
      normalizedAliases: ["routeName", "routeNameRaw", "routeNameDisplay"],
      storedAliases: ["routeName", "routeNameDisplay"],
      storage: "normalized_cache_and_unified_incident_memory",
      usedByGridly: "used for TxDOT titles, roadName fallback, local focus matching, and unified incident road/area labels",
      ignoredByGridly: "not joined to local roadway geometry or OSRM candidates for carriageway-aware placement",
      directionalUse: "HIGH VALUE",
      helps: ["corridor identity", "road direction when combined with travel_direction"],
      preserved: true
    },
    {
      rawAliases: ["roadway", "road_name"],
      normalizedAliases: ["roadName"],
      storedAliases: ["roadName", "area"],
      storage: "normalized_cache_and_unified_incident_memory",
      usedByGridly: "used as display road label and area fallback",
      ignoredByGridly: "not authoritative enough by itself for EB/WB/NB/SB labeling",
      directionalUse: "MEDIUM VALUE",
      helps: ["corridor identity"],
      preserved: true
    },
    {
      rawAliases: ["from_limit", "fromLimit"],
      normalizedAliases: ["fromLimit", "fromLimitRaw", "fromLimitDisplay"],
      storedAliases: [],
      storage: "normalized_cache_only",
      usedByGridly: "available to TxDOT analytics/local summaries but not copied into unified incidents",
      ignoredByGridly: "discarded at gridlyBuildTxdotUnifiedIncident(), so alerts/markers cannot use from-limit context",
      directionalUse: "HIGH VALUE",
      helps: ["corridor identity", "hazard direction", "reference limits"],
      preserved: true,
      note: "Retain in a future unified payload if directional labels need official limits."
    },
    {
      rawAliases: ["to_limit", "toLimit"],
      normalizedAliases: ["toLimit", "toLimitRaw", "toLimitDisplay"],
      storedAliases: [],
      storage: "normalized_cache_only",
      usedByGridly: "available to TxDOT analytics/local summaries but not copied into unified incidents",
      ignoredByGridly: "discarded at gridlyBuildTxdotUnifiedIncident(), so alerts/markers cannot use to-limit context",
      directionalUse: "HIGH VALUE",
      helps: ["corridor identity", "hazard direction", "reference limits"],
      preserved: true
    },
    {
      rawAliases: ["__geometry", "geometry"],
      normalizedAliases: ["latitude", "longitude"],
      storedAliases: ["lat", "lng", "latitude", "longitude"],
      storage: "midpoint_only_in_normalized_and_unified_memory",
      usedByGridly: "LineString midpoint becomes latitude/longitude for TxDOT marker eligibility",
      ignoredByGridly: "full route geometry is not retained, so segment bearing and carriageway shape are unavailable after normalization",
      directionalUse: "HIGH VALUE",
      helps: ["bearing if retained", "corridor identity", "side of divided roadway if combined with carriageway metadata"],
      preserved: true,
      note: "Current code keeps only a midpoint from LineString geometry and discards the coordinate array."
    },
    {
      rawAliases: ["condition", "type", "event_type", "category"],
      normalizedAliases: ["type"],
      storedAliases: ["type", "category", "report_type"],
      storage: "normalized_cache_and_unified_incident_memory",
      usedByGridly: "used for construction/incident split, severity, marker style, and alert category eligibility",
      ignoredByGridly: "does not identify side or route direction by itself",
      directionalUse: "LOW VALUE",
      helps: ["lane impact only when condition text contains lane closure/work zone wording"],
      preserved: true
    },
    {
      rawAliases: ["description", "summary", "detail"],
      normalizedAliases: ["description"],
      storedAliases: ["description", "summary"],
      storage: "normalized_cache_and_unified_incident_memory",
      usedByGridly: "used as unified description/summary fallback",
      ignoredByGridly: "not parsed for embedded EB/WB/NB/SB, lanes closed, or side-of-road semantics",
      directionalUse: "MEDIUM VALUE",
      helps: ["hazard direction", "lane impact", "corridor identity"],
      preserved: true
    },
    {
      rawAliases: ["delay_flag"],
      normalizedAliases: ["delayFlag"],
      storedAliases: [],
      storage: "normalized_cache_only",
      usedByGridly: "used by TxDOT local summary recommendation text",
      ignoredByGridly: "not copied into unified incidents and not used for lane-level placement",
      directionalUse: "LOW VALUE",
      helps: ["lane impact"],
      preserved: true
    },
    {
      rawAliases: ["detour_flag"],
      normalizedAliases: ["detourFlag"],
      storedAliases: [],
      storage: "normalized_cache_only",
      usedByGridly: "used by TxDOT local summary recommendation text",
      ignoredByGridly: "not copied into unified incidents and not used for directional placement",
      directionalUse: "LOW VALUE",
      helps: ["lane impact", "corridor identity"],
      preserved: true
    },
    {
      rawAliases: ["county_num"],
      normalizedAliases: ["countyNum"],
      storedAliases: [],
      storage: "normalized_cache_only",
      usedByGridly: "used by TxDOT local focus filtering for Liberty County",
      ignoredByGridly: "not copied into unified incidents",
      directionalUse: "LOW VALUE",
      helps: ["corridor identity"],
      preserved: true
    },
    {
      rawAliases: ["start_time"],
      normalizedAliases: ["startTime"],
      storedAliases: ["createdAt", "created_at"],
      storage: "normalized_cache_and_unified_incident_memory",
      usedByGridly: "used for active-date filtering and incident timestamps",
      ignoredByGridly: "not relevant to carriageway side",
      directionalUse: "LOW VALUE",
      helps: [],
      preserved: true
    },
    {
      rawAliases: ["end_time"],
      normalizedAliases: ["endTime"],
      storedAliases: ["endTime", "expiresAt", "expires_at"],
      storage: "normalized_cache_and_unified_incident_memory",
      usedByGridly: "used for active-date filtering and expiration",
      ignoredByGridly: "not relevant to carriageway side",
      directionalUse: "LOW VALUE",
      helps: [],
      preserved: true
    },
    {
      rawAliases: ["GLOBALID", "id"],
      normalizedAliases: ["id"],
      storedAliases: ["rawTxdotId", "id"],
      storage: "normalized_cache_and_unified_incident_memory",
      usedByGridly: "used for TxDOT identity and duplicate tracing",
      ignoredByGridly: "not directional",
      directionalUse: "LOW VALUE",
      helps: [],
      preserved: true
    },
    {
      rawAliases: ["reference_marker", "ref_marker", "mile_marker", "begin_milepoint", "end_milepoint"],
      normalizedAliases: [],
      storedAliases: [],
      storage: "not_currently_normalized",
      usedByGridly: "not fetched/recognized by current normalizer unless present only inside description/from/to text",
      ignoredByGridly: "no dedicated field inventory or unified incident field exists today",
      directionalUse: "HIGH VALUE",
      helps: ["reference markers", "mile markers", "corridor identity"],
      discarded: true,
      note: "No dedicated marker fields are mapped in current Gridly TxDOT normalization."
    },
    {
      rawAliases: ["lane_closure", "lanes_closed", "lane_count", "closed_lanes", "lane_impacts"],
      normalizedAliases: [],
      storedAliases: [],
      storage: "not_currently_normalized",
      usedByGridly: "not fetched/recognized as structured lane data; condition/description text may mention lane closures",
      ignoredByGridly: "no lane-level object is retained",
      directionalUse: "HIGH VALUE",
      helps: ["lane impact", "side of divided roadway"],
      discarded: true,
      note: "Current endpoint may expose lane context only as condition/description text in this integration."
    },
    {
      rawAliases: ["carriageway", "roadbed", "side_of_road", "roadway_side"],
      normalizedAliases: [],
      storedAliases: [],
      storage: "not_currently_normalized",
      usedByGridly: "not available in the current mapped fields",
      ignoredByGridly: "no current field exists to determine divided-road side with confidence",
      directionalUse: "HIGH VALUE",
      helps: ["side of divided roadway", "carriageway awareness"],
      discarded: true,
      note: "This remains the major missing geometry/metadata class for divided roads."
    }
  ];
  const fullInventory = inventoryConfig.map((config) => gridlyTxdotFieldInventoryRow(config, rawRows, normalizedRows, unifiedRows));
  const preservedFields = fullInventory.filter((field) => field.preserved).map((field) => ({ rawField: field.rawField, normalizedField: field.normalizedField, storedField: field.storedField, storage: field.storage, directionalUse: field.directionalUse }));
  const discardedFields = fullInventory.filter((field) => field.discarded || field.storage === "not_currently_normalized" || field.storage === "not_stored").map((field) => ({ rawField: field.rawField, normalizedField: field.normalizedField, reason: field.ignoredByGridly, directionalUse: field.directionalUse }));
  const directionalFields = fullInventory.filter((field) => field.helps.includes("road direction") || field.helps.includes("hazard direction") || /direction|limit|geometry|carriageway|lane/i.test(field.rawField || ""));
  const corridorFields = fullInventory.filter((field) => field.helps.includes("corridor identity") || /route|roadway|limit|county|marker/i.test(field.rawField || ""));
  const roadwayFields = fullInventory.filter((field) => /route|roadway|geometry|limit|marker|carriageway/i.test([field.rawField, field.normalizedField, field.storedField].filter(Boolean).join(" ")));
  const laneFields = fullInventory.filter((field) => field.helps.includes("lane impact") || /lane|delay|detour|condition|description/i.test([field.rawField, field.normalizedField].filter(Boolean).join(" ")));
  const hasDirectionField = fullInventory.some((field) => field.rawField === "travel_direction" && (field.observed.raw || field.observed.normalized || field.observed.stored || field.preserved));
  const hasRouteField = fullInventory.some((field) => field.rawField === "route_name" && (field.observed.raw || field.observed.normalized || field.observed.stored || field.preserved));
  const hasLimits = fullInventory.some((field) => field.rawField === "from_limit" && field.preserved) && fullInventory.some((field) => field.rawField === "to_limit" && field.preserved);
  const hasFullGeometryObserved = rawRows.some((row) => row?.__geometry?.type === "LineString" && Array.isArray(row?.__geometry?.coordinates) && row.__geometry.coordinates.length > 1);
  const hasFullGeometryPreserved = false;
  const hasLaneStructured = laneFields.some((field) => field.storage !== "not_currently_normalized" && field.observed.raw && /lane/i.test(field.rawField || ""));
  const hasCarriagewayStructured = fullInventory.some((field) => field.rawField === "carriageway" && (field.observed.raw || field.observed.normalized || field.observed.stored));
  const scoreParts = {
    officialRouteIdentity: hasRouteField ? 20 : 0,
    explicitTravelDirection: hasDirectionField ? 25 : 0,
    fromToLimits: hasLimits ? 15 : 0,
    fullGeometryRetained: hasFullGeometryPreserved ? 20 : (hasFullGeometryObserved ? 8 : 0),
    structuredLaneOrCarriageway: (hasLaneStructured || hasCarriagewayStructured) ? 20 : 0
  };
  const directionalReadinessScore = Object.values(scoreParts).reduce((sum, value) => sum + value, 0);
  const readinessLabel = directionalReadinessScore >= 80 ? "HIGH" : directionalReadinessScore >= 50 ? "MEDIUM" : "LOW";
  const buildCorridorAssessment = (displayName, rawPattern, directions) => {
    const matchingNormalized = normalizedRows.filter((row) => {
      const text = [row?.routeNameDisplay, row?.routeName, row?.roadName, row?.title, row?.description, row?.fromLimitDisplay, row?.toLimitDisplay].join(" ").toUpperCase();
      return rawPattern.test(text);
    });
    const matchingUnified = unifiedRows.filter((row) => {
      const text = [row?.routeNameDisplay, row?.routeName, row?.roadName, row?.title, row?.description, row?.area, row?.direction].join(" ").toUpperCase();
      return rawPattern.test(text);
    });
    const directionsPreserved = Array.from(new Set([...matchingNormalized, ...matchingUnified].map((row) => String(row?.direction || "").toUpperCase()).filter(Boolean)));
    return {
      corridor: displayName,
      testedDirections: directions,
      currentRowsInNormalizedCache: matchingNormalized.length,
      currentRowsInUnifiedIncidents: matchingUnified.length,
      directionValuesObserved: directionsPreserved,
      preservesIfTravelDirectionProvided: hasRouteField && hasDirectionField,
      currentlyDisplayedAsDirectionalLabel: false,
      wherePreserved: "route_name -> routeName/routeNameDisplay; travel_direction -> direction; gridlyBuildTxdotUnifiedIncident copies routeName/routeNameDisplay/direction into in-memory unified incidents",
      whereLost: [
        "full TxDOT LineString geometry is reduced to midpoint latitude/longitude during normalizeIncident()",
        "fromLimit/toLimit remain in normalized cache but are not copied by gridlyBuildTxdotUnifiedIncident()",
        "structured reference-marker, lane, and carriageway fields have no dedicated current mapping",
        "direction is not consumed by marker placement, side-of-road confidence, Route Watch, routing, or alert label generation"
      ],
      retentionPoint: "Future work can retain full __geometry, from/to limits, and any lane/carriageway/reference-marker fields in the TxDOT normalized object and unified incident payload without re-enabling startup fetch."
    };
  };
  const localSegmentsAssessment = {
    available: Boolean(roadwayDatasetLoaded && Array.isArray(roadwaySegmentFeatures) && roadwaySegmentFeatures.length),
    support: {
      direction: "MEDIUM when a nearby segment is selected because bearing can be computed; LOW for divided-road side without carriageway metadata",
      bearing: "STRONGEST current source when loaded; gridlyBuildLocalDirectionalRoadCandidates computes segmentBearing",
      carriagewayAwareness: "LOW; OSM one-way/tags may exist but are not sufficient for every divided road",
      sideOfRoadConfidence: "LOW to MEDIUM; based on nearest same-name candidate gap, not official carriageway IDs"
    }
  };
  const osrmAssessment = {
    available: Boolean(lastRoadSnapDebug?.nearestRoadCandidates?.length),
    support: {
      direction: "LOW; current normalized OSRM nearest candidates expose snapped point/name/distance but not bearing here",
      bearing: "LOW in this app path",
      carriagewayAwareness: "LOW",
      sideOfRoadConfidence: "LOW"
    }
  };
  const txdotAssessment = {
    available: Boolean(txdotService && typeof txdotService.normalizeIncident === "function"),
    cachedRows: normalizedRows.length,
    support: {
      direction: hasDirectionField ? "STRONG when travel_direction is present; currently preserved but unused for placement" : "LOW until travel_direction is present in fetched rows",
      bearing: hasFullGeometryObserved ? "POTENTIALLY STRONG from raw LineString, but current normalizer discards full shape" : "LOW; midpoint only in current cache",
      carriagewayAwareness: hasCarriagewayStructured ? "STRONG if observed raw carriageway fields are retained" : "LOW; no current mapped carriageway field",
      sideOfRoadConfidence: "LOW until full geometry plus carriageway/lane/reference-marker fields are retained"
    }
  };
  const recommendations = [
    "Keep TxDOT startup fetch disabled; this audit reads only cached service rows and static mapping knowledge.",
    "For future US 90 EB/WB and TX 146 NB/SB support, preserve travel_direction as the official direction candidate and join it with routeNameDisplay.",
    "Retain full raw __geometry LineString coordinates in the normalized TxDOT object before attempting bearing or divided-road placement from TxDOT.",
    "Promote fromLimit/toLimit into future unified TxDOT incidents because they provide official corridor/reference context that is currently lost after normalization.",
    "Add dedicated retention for any future reference-marker, mile-marker, lane, closure-direction, or carriageway fields if the endpoint returns them; do not infer side-of-road from midpoint alone.",
    "Compare TxDOT official direction with local roadway segment bearing before displaying NB/SB/EB/WB; if they conflict or carriageway side is ambiguous, keep safeDirectionalLabelAnswer as insufficient_geometry."
  ];
  const audit = {
    auditVersion: "V206.11-txdot-directional-roadway-readiness-audit",
    auditOnly: true,
    txdotAvailable: Boolean(txdotService && typeof txdotService.normalizeIncident === "function"),
    startupFetchEnabled: typeof gridlyIsTxdotStartupFetchEnabled === "function" ? gridlyIsTxdotStartupFetchEnabled() : false,
    rawFieldInventory: {
      endpointTemplate: target?.GRIDLY_CONFIG?.txdot?.endpointTemplate || null,
      observedFields: rawObservedFields,
      mappedFields: fullInventory.map((field) => ({ rawField: field.rawField, rawAliases: field.rawAliases, normalizedField: field.normalizedField, storedField: field.storedField, directionalUse: field.directionalUse, examples: field.examples }))
    },
    normalizedFieldInventory: {
      observedFields: normalizedObservedFields,
      mappedFields: fullInventory.map((field) => ({ normalizedField: field.normalizedField, normalizedAliases: field.normalizedAliases, storedField: field.storedField, storage: field.storage, usedByGridly: field.usedByGridly, ignoredByGridly: field.ignoredByGridly }))
    },
    preservedFields,
    discardedFields,
    directionalFields,
    corridorFields,
    roadwayFields,
    laneFields,
    directionalReadiness: {
      label: readinessLabel,
      scoreParts,
      canDetermineRoadDirection: hasRouteField && hasDirectionField ? "yes_when_travel_direction_is_present" : "not_from_current_cache_alone",
      canDetermineSideOfDividedRoadway: hasFullGeometryPreserved && hasCarriagewayStructured ? "potentially" : "no_full_geometry_and_carriageway_metadata_missing",
      canDetermineCorridorIdentity: hasRouteField ? "yes_route_name_routeNameDisplay_preserved" : "limited",
      canDetermineHazardDirection: hasDirectionField ? "yes_as_official_event_direction_but_not_geometry_validated" : "no_explicit_direction_observed",
      canDetermineLaneImpact: hasLaneStructured ? "yes_if_structured_lane_fields_are_observed" : "only_from_condition_description_text_today"
    },
    directionalReadinessScore,
    usableForEBWB: hasRouteField && hasDirectionField ? "conditionally_yes_for_official_event_label_not_side_of_road" : "no_explicit_EB_WB_field_not_available_in_current_rows",
    usableForNBSB: hasRouteField && hasDirectionField ? "conditionally_yes_for_official_event_label_not_side_of_road" : "no_explicit_NB_SB_field_not_available_in_current_rows",
    usableForDividedRoads: hasFullGeometryPreserved && hasCarriagewayStructured ? "potentially" : "no_current_full_geometry_or_carriageway_side_confidence",
    usableForCorridorIntelligence: hasRouteField || hasLimits ? "yes_for_official_corridor_context" : "limited",
    fieldValueExamples: {
      travelDirection: gridlyTxdotDirectionalFieldExample([...rawRows, ...normalizedRows, ...unifiedRows], ["travel_direction", "direction"]),
      routeName: gridlyTxdotDirectionalFieldExample([...rawRows, ...normalizedRows, ...unifiedRows], ["route_name", "routeNameDisplay", "routeName", "roadName"]),
      fromLimit: gridlyTxdotDirectionalFieldExample([...rawRows, ...normalizedRows], ["from_limit", "fromLimitDisplay", "fromLimit"]),
      toLimit: gridlyTxdotDirectionalFieldExample([...rawRows, ...normalizedRows], ["to_limit", "toLimitDisplay", "toLimit"]),
      geometryType: rawRows.find((row) => row?.__geometry)?.__geometry?.type || null,
      laneText: gridlyTxdotDirectionalFieldExample([...rawRows, ...normalizedRows], ["lane_closure", "lanes_closed", "description", "condition", "type"])
    },
    us90Assessment: buildCorridorAssessment("US 90", /\b(US\s*90|US0*90)\b/, ["EB", "WB"]),
    tx146Assessment: buildCorridorAssessment("TX 146", /\b(TX\s*146|SH0*146|SH\s*146)\b/, ["NB", "SB"]),
    dataSourceComparison: {
      localRoadwaySegments: localSegmentsAssessment,
      osrmNearestCandidates: osrmAssessment,
      txdotRoadwayData: txdotAssessment,
      strongestCurrentSupport: {
        direction: "TxDOT when travel_direction is present; otherwise local segment bearing only gives inferred cardinal direction",
        bearing: "Current local roadway segments",
        carriagewayAwareness: "None strong today; TxDOT could become strongest if full geometry plus carriageway/lane fields are retained",
        sideOfRoadConfidence: "Current local roadway same-name candidate distance gap is best available but still insufficient for high-confidence divided roads"
      },
      linkedDirectionalRoadAuditSkippedByDefault: !includeConnectedAudits,
      linkedDirectionalRoadAudit: directionalRoadAudit ? {
        safeDirectionalLabelAnswer: directionalRoadAudit.safeDirectionalLabelAnswer,
        roadGeometryAvailable: directionalRoadAudit.roadGeometryAvailable,
        selectedSideConfidence: directionalRoadAudit.selectedSideConfidence,
        missingData: directionalRoadAudit.missingData
      } : null
    },
    recommendations,
    sourceAuditSkippedByDefault: !includeConnectedAudits,
    sourceAuditSummary: sourceAudit ? {
      txdotFetchConfigured: sourceAudit.txdotFetchConfigured,
      txdotLastFetchAttempt: sourceAudit.txdotLastFetchAttempt,
      txdotLastFetchSuccess: sourceAudit.txdotLastFetchSuccess,
      txdotRawConditionCount: sourceAudit.txdotRawConditionCount,
      txdotNormalizedCount: sourceAudit.txdotNormalizedCount,
      txdotUnifiedIncidents: sourceAudit.txdotUnifiedIncidents,
      blockers: sourceAudit.blockers
    } : null,
    trace: [
      "No fetch is started by this audit; it reads cached gridlyTxdot raw/normalized rows only.",
      "Current TxDOT service endpoint is DriveTexas conditions.geojson; normalizeIncident maps route_name, roadway, condition, travel_direction, from/to limits, times, flags, county, and midpoint coordinates.",
      "gridlyBuildTxdotUnifiedIncident preserves routeName, routeNameDisplay, direction, roadName, type/category, timestamps, coordinates, and rawTxdotId.",
      "The full raw LineString is not preserved after normalization, and no structured carriageway/lane/reference-marker fields are currently mapped.",
      "This audit does not change reporting, routing, Route Watch, rail, alerts, Portrait V2, Supabase schema, marker placement, clustering, schedules, or startup fetch behavior."
    ],
    observedRuntime: {
      rawRowCount: rawRows.length,
      normalizedRowCount: normalizedRows.length,
      unifiedTxdotRowCount: unifiedRows.length,
      rawObservedFields,
      normalizedObservedFields,
      unifiedObservedFields
    }
  };
  target.gridlyLastTxdotDirectionalReadinessAudit = audit;
  console.info("gridlyTxdotDirectionalReadinessAudit", audit);
  return audit;
}

if (typeof window !== "undefined") {
  window.gridlyTxdotDirectionalReadinessAudit = gridlyTxdotDirectionalReadinessAudit;
  window.gridlyLastTxdotDirectionalReadinessAudit = window.gridlyLastTxdotDirectionalReadinessAudit || null;
}
exposeGridlyAuditHelper("gridlyTxdotDirectionalReadinessAudit", gridlyTxdotDirectionalReadinessAudit);

function gridlyRefreshAfterTxdotFetch(reason = "txdot-fetch") {
  if (typeof refreshReportHazardViews === "function") {
    refreshReportHazardViews(reason);
    return "refreshReportHazardViews";
  }
  if (typeof renderUnifiedIncidents === "function") {
    renderUnifiedIncidents(reason);
    return "renderUnifiedIncidents";
  }
  if (typeof renderUnifiedIncidentMarkers === "function") {
    renderUnifiedIncidentMarkers(reason);
    return "renderUnifiedIncidentMarkers";
  }
  return "none";
}

async function gridlyRunTxdotFetchAndRefresh(options = {}) {
  const force = Boolean(options.force);
  const reason = String(options.reason || (force ? "txdot-manual-validation" : "txdot-startup"));
  const txdotService = window.gridlyTxdot || null;
  const txdotState = window.gridlyTxdotState || {};
  const cachedRows = typeof txdotService?.getRoadConditions === "function" ? txdotService.getRoadConditions() : gridlyReadCachedTxdotRows();
  const cachedRowCount = Array.isArray(cachedRows) ? cachedRows.length : 0;

  if (!force && !gridlyIsTxdotStartupFetchEnabled()) {
    return {
      attempted: false,
      skipped: true,
      skipReason: "txdot_startup_fetch_disabled",
      refreshMethod: "none",
      fetchedRows: cachedRowCount
    };
  }

  if (!gridlyIsTxdotFetchAvailable()) {
    return {
      attempted: false,
      skipped: true,
      skipReason: "txdot_fetch_not_configured",
      refreshMethod: "none",
      fetchedRows: 0
    };
  }

  if (!force && cachedRowCount > 0) {
    const refreshMethod = gridlyRefreshAfterTxdotFetch(`${reason}:cached`);
    return {
      attempted: false,
      skipped: true,
      skipReason: "cached_rows_available",
      refreshMethod,
      fetchedRows: cachedRowCount
    };
  }

  if (!force && (txdotState.hasFetched || txdotState.lastFetchTime)) {
    return {
      attempted: false,
      skipped: true,
      skipReason: "startup_fetch_already_attempted",
      refreshMethod: "none",
      fetchedRows: cachedRowCount
    };
  }

  if (!force && gridlyTxdotStartupFetchPromise) {
    return gridlyTxdotStartupFetchPromise;
  }

  const runFetch = (async () => {
    let rows = [];
    let fetchError = "";
    let refreshMethod = "none";
    try {
      rows = await txdotService.fetchRoadConditions();
    } catch (error) {
      fetchError = error instanceof Error ? error.message : String(error);
    }
    try {
      refreshMethod = gridlyRefreshAfterTxdotFetch(reason);
    } catch (error) {
      fetchError = [fetchError, error instanceof Error ? error.message : String(error)].filter(Boolean).join("; ");
    }
    const fetchedRows = Array.isArray(rows) ? rows.length : 0;
    return {
      attempted: true,
      skipped: false,
      skipReason: "",
      refreshMethod,
      fetchedRows,
      error: fetchError
    };
  })();

  if (!force) {
    gridlyTxdotStartupFetchPromise = runFetch;
    runFetch.then(
      () => { gridlyTxdotStartupFetchPromise = null; },
      () => { gridlyTxdotStartupFetchPromise = null; }
    );
  }

  return runFetch;
}

function gridlyBuildTxdotValidationResult(fetchSummary = {}) {
  const txdotAudit = typeof gridlyTxDotSourceAudit === "function" ? gridlyTxDotSourceAudit() : {};
  const incidentAudit = typeof gridlyIncidentSourceAudit === "function" ? gridlyIncidentSourceAudit({ sampleLimit: 5 }) : {};
  const normalizedRows = Number(txdotAudit.txdotNormalizedCount || 0);
  const rawRows = Number(txdotAudit.txdotRawConditionCount || 0);
  const txdotUnifiedIncidents = Number(txdotAudit.txdotUnifiedIncidents || 0);
  const txdotMapEligibleCount = Number(txdotAudit.txdotMapEligibleCount || 0);
  const txdotAlertEligibleCount = Number(txdotAudit.txdotAlertEligibleCount || 0);
  const txdotRenderedMarkerCount = Number(txdotAudit.trace?.mapMarkers || 0);
  const checks = {
    txdotFetchSuccess: txdotAudit.txdotLastFetchSuccess === true,
    rawRows: rawRows > 0,
    normalizedRows: normalizedRows > 0,
    futureTxdotIncidents: Number(txdotAudit.futureTxdotIncidents || 0) > 0,
    futureTxdotConstruction: Number(txdotAudit.futureTxdotConstruction || 0) > 0,
    txdotUnifiedIncidents: txdotUnifiedIncidents > 0,
    txdotMapEligibleCount: txdotMapEligibleCount > 0,
    txdotMarkersOrAlertsEligible: (txdotMapEligibleCount + txdotAlertEligibleCount + txdotRenderedMarkerCount) > 0
  };
  const failedChecks = Object.entries(checks)
    .filter(([, passed]) => !passed)
    .map(([name]) => name);

  return {
    result: failedChecks.length ? "FAIL" : "PASS",
    txdotFetchSuccess: checks.txdotFetchSuccess,
    rawRows,
    normalizedRows,
    futureTxdotIncidents: Number(txdotAudit.futureTxdotIncidents || 0),
    futureTxdotConstruction: Number(txdotAudit.futureTxdotConstruction || 0),
    txdotUnifiedIncidents,
    txdotMapEligibleCount,
    txdotAlertEligibleCount,
    txdotRenderedMarkerCount,
    txdotRowsSkippedNoCoordinates: Number(txdotAudit.txdotRowsSkippedNoCoordinates || 0),
    fetchSummary,
    refreshMethod: fetchSummary.refreshMethod || "none",
    checks,
    failedChecks,
    blockers: Array.isArray(txdotAudit.blockers) ? txdotAudit.blockers : [],
    txdotSourceAudit: txdotAudit,
    incidentSourceAudit: incidentAudit
  };
}

async function gridlyTxdotFullValidation() {
  const fetchSummary = await gridlyRunTxdotFetchAndRefresh({ force: true, reason: "txdot-full-validation" });
  const result = gridlyBuildTxdotValidationResult(fetchSummary);
  console.info("gridlyTxdotFullValidation", result);
  return result;
}

function gridlyScheduleStartupTxdotFetch() {
  if (gridlyTxdotStartupFetchAttempted) return;
  if (!gridlyIsTxdotStartupFetchEnabled()) return;
  gridlyTxdotStartupFetchAttempted = true;
  const start = () => {
    gridlyRunTxdotFetchAndRefresh({ force: false, reason: "txdot-startup-once" })
      .then((summary) => {
        if (summary?.attempted) console.info("gridlyTxdotStartupFetch", summary);
      })
      .catch((error) => {
        console.warn("gridlyTxdotStartupFetch failed", error);
      });
  };

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", start, { once: true });
  } else {
    setTimeout(start, 0);
  }
}

window.gridlyTxdotFullValidation = gridlyTxdotFullValidation;
exposeGridlyAuditHelper("gridlyTxdotFullValidation", gridlyTxdotFullValidation);
gridlyScheduleStartupTxdotFetch();

function gridlyAuditHelperExposureAudit() {
  const target = typeof window !== "undefined" ? window : globalThis;
  const helperNames = Object.keys(target || {}).filter((name) => typeof name === "string");
  const helperNamesContainingTxdot = helperNames
    .filter((name) => name.toLowerCase().includes("txdot"))
    .sort();
  const helperNamesContainingIncident = helperNames
    .filter((name) => name.toLowerCase().includes("incident"))
    .sort();
  const appVersionParts = [
    typeof GRIDLY_APP_VERSION_LABEL === "string" ? GRIDLY_APP_VERSION_LABEL : null,
    typeof GRIDLY_APP_BUILD_LABEL === "string" ? GRIDLY_APP_BUILD_LABEL : null,
    typeof APP_BUILD === "string" ? `APP_BUILD ${APP_BUILD}` : null,
    "V203.4B"
  ].filter(Boolean);

  return {
    gridlyTxDotSourceAudit: typeof target?.gridlyTxDotSourceAudit,
    gridlyTxdotLayerAudit: typeof target?.gridlyTxdotLayerAudit,
    gridlyRunTxdotLayerAudit: typeof target?.gridlyRunTxdotLayerAudit,
    gridlyLastTxdotLayerAudit: target?.gridlyLastTxdotLayerAudit || null,
    gridlyIncidentSourceAudit: typeof target?.gridlyIncidentSourceAudit,
    gridlyTxdotFetch: typeof target?.gridlyTxdot?.fetchRoadConditions,
    helperNamesContainingTxdot,
    helperNamesContainingIncident,
    appVersionTag: appVersionParts.join(" / ")
  };
}

window.gridlyAuditHelperExposureAudit = gridlyAuditHelperExposureAudit;
exposeGridlyAuditHelper("gridlyAuditHelperExposureAudit", gridlyAuditHelperExposureAudit);


const GRIDLY_CORE_ROAD_HAZARD_CLEANUP_TYPES = Object.freeze(["flooding", "ice", "debris", "crash", "construction", "road_closed", "disabled_vehicle", "traffic_backup", "other_hazard"]);
const GRIDLY_SHARED_ROAD_HAZARD_REPORT_TYPES = Object.freeze([...GRIDLY_CORE_ROAD_HAZARD_CLEANUP_TYPES, "hazard_cleared", "wreck"]);
const GRIDLY_SUPABASE_TEST_HAZARD_CONFIRMATION = "CLEAR_SUPABASE_TEST_HAZARDS";

function gridlyGetSharedRoadHazardReportTypes() {
  return [...GRIDLY_SHARED_ROAD_HAZARD_REPORT_TYPES];
}

function gridlyNormalizeSharedRoadHazardType(type = "") {
  const normalized = String(type || "").trim().toLowerCase();
  return normalized === "wreck" ? "crash" : normalized;
}

function gridlyIsHazardDeviceCrossingId(crossingId = "") {
  return String(crossingId || "").trim().toLowerCase().startsWith("hazard-device-");
}

function gridlyIsSharedRoadHazardReportRow(row = {}) {
  const rawType = String(row?.report_type || row?.type || "").trim().toLowerCase();
  return GRIDLY_SHARED_ROAD_HAZARD_REPORT_TYPES.includes(rawType);
}

function gridlyIsTxDotReportSource(row = {}) {
  const sourceText = [row?.source, row?.provider, row?.external_source]
    .map((value) => String(value || "").toLowerCase())
    .join(" ");
  return /\btx\s*dot\b|\btxdot\b|texas department of transportation/.test(sourceText);
}

function gridlySupabaseHazardRoadName(row = {}) {
  return gridlyNormalizeAnalyticsRoadLabel(
    row?.road_name
      || row?.roadName
      || row?.primary_road
      || row?.primaryRoad
      || row?.nearest_road
      || row?.nearestRoad
      || row?.location_name
      || row?.locationName
      || row?.crossing_name
      || row?.crossingName
      || ""
  ) || "Unknown road";
}

async function gridlyFetchActiveSupabaseRoadHazardRows(limit = 1000) {
  if (!supabaseClient) {
    return { ok: false, rows: [], error: "Supabase client not initialized." };
  }

  const nowIso = new Date().toISOString();
  const maxRows = Math.max(1, Math.min(1000, Number(limit) || 1000));
  const { data, error } = await supabaseClient
    .from("reports")
    .select("id,report_type,source,created_at,expires_at,crossing_id,crossing_name,railroad,detail,lat,lng")
    .gt("expires_at", nowIso)
    .in("report_type", gridlyGetSharedRoadHazardReportTypes())
    .order("created_at", { ascending: true })
    .limit(maxRows);

  if (error) {
    return { ok: false, rows: [], error: error.message || "query_failed" };
  }

  return { ok: true, rows: (Array.isArray(data) ? data : []).filter(gridlyIsSharedRoadHazardReportRow), error: "" };
}

function gridlyBuildSupabaseHazardInventory(rows = []) {
  const activeRows = Array.isArray(rows) ? rows.filter(gridlyIsSharedRoadHazardReportRow) : [];
  const byType = activeRows.reduce((acc, row) => {
    const type = gridlyNormalizeSharedRoadHazardType(row?.report_type || row?.type || "unknown") || "unknown";
    acc[type] = (acc[type] || 0) + 1;
    return acc;
  }, {});
  const createdTimes = activeRows
    .map((row) => ({ iso: row?.created_at || row?.createdAt || null, time: new Date(row?.created_at || row?.createdAt || 0).getTime() }))
    .filter((entry) => entry.iso && Number.isFinite(entry.time));

  return {
    activeHazardRows: activeRows.length,
    byType,
    cleanupTypeCoverage: {
      requiredTypes: [...GRIDLY_CORE_ROAD_HAZARD_CLEANUP_TYPES],
      sharedReportTypes: gridlyGetSharedRoadHazardReportTypes(),
      includesIce: GRIDLY_SHARED_ROAD_HAZARD_REPORT_TYPES.includes("ice")
    },
    oldestCreatedAt: createdTimes.length ? createdTimes.reduce((oldest, entry) => entry.time < oldest.time ? entry : oldest).iso : null,
    newestCreatedAt: createdTimes.length ? createdTimes.reduce((newest, entry) => entry.time > newest.time ? entry : newest).iso : null,
    sampleRows: activeRows.slice(0, 10).map((row) => ({
      id: row?.id || null,
      type: gridlyNormalizeSharedRoadHazardType(row?.report_type || row?.type || "unknown") || "unknown",
      source: row?.source || "user",
      createdAt: row?.created_at || row?.createdAt || null,
      roadName: gridlySupabaseHazardRoadName(row)
    }))
  };
}

window.gridlySupabaseHazardInventoryAudit = async function gridlySupabaseHazardInventoryAudit(options = {}) {
  const fetchResult = await gridlyFetchActiveSupabaseRoadHazardRows(options?.limit || 1000);
  if (!fetchResult.ok) {
    const failed = { activeHazardRows: 0, byType: {}, oldestCreatedAt: null, newestCreatedAt: null, sampleRows: [], ok: false, error: fetchResult.error };
    console.warn("gridlySupabaseHazardInventoryAudit failed", failed);
    return failed;
  }
  const audit = gridlyBuildSupabaseHazardInventory(fetchResult.rows);
  console.info("gridlySupabaseHazardInventoryAudit", audit);
  return audit;
};

window.gridlySupabaseHazardPurgeAudit = async function gridlySupabaseHazardPurgeAudit(options = {}) {
  const fetchResult = await gridlyFetchActiveSupabaseRoadHazardRows(options?.limit || 1000);
  if (!fetchResult.ok) {
    const failed = { supabaseActiveHazardsFound: 0, supabaseActiveHazardsWouldDelete: 0, purgeScope: "shared road hazard reports only", preservedRailReports: true, preservedTxDot: true, ok: false, error: fetchResult.error };
    console.warn("gridlySupabaseHazardPurgeAudit failed", failed);
    return failed;
  }

  const rows = fetchResult.rows;
  const deleteCandidates = rows.filter((row) => gridlyIsSharedRoadHazardReportRow(row) && !gridlyIsTxDotReportSource(row));
  const txdotRows = rows.filter(gridlyIsTxDotReportSource);
  const audit = {
    supabaseActiveHazardsFound: rows.length,
    supabaseActiveHazardsWouldDelete: deleteCandidates.length,
    purgeScope: "active Supabase reports where report_type is a shared road hazard type; excludes TxDOT-tagged rows and never targets rail crossing report types or other storage",
    cleanupTypeCoverage: {
      requiredTypes: [...GRIDLY_CORE_ROAD_HAZARD_CLEANUP_TYPES],
      sharedReportTypes: gridlyGetSharedRoadHazardReportTypes(),
      includesIce: GRIDLY_SHARED_ROAD_HAZARD_REPORT_TYPES.includes("ice")
    },
    preservedRailReports: true,
    preservedTxDot: txdotRows.length
  };
  console.info("gridlySupabaseHazardPurgeAudit", audit);
  return audit;
};

function gridlyNormalizeSupabaseMutationError(error = null) {
  if (!error) return null;
  return {
    message: error.message || "",
    code: error.code || "",
    details: error.details || "",
    hint: error.hint || "",
    name: error.name || ""
  };
}

function gridlyLooksLikeSupabaseRlsError(error = null) {
  const normalized = gridlyNormalizeSupabaseMutationError(error);
  if (!normalized) return false;
  const text = [normalized.message, normalized.code, normalized.details, normalized.hint, normalized.name].join(" ").toLowerCase();
  return text.includes("row-level security")
    || text.includes("rls")
    || text.includes("policy")
    || text.includes("permission denied")
    || text.includes("42501")
    || text.includes("insufficient privilege");
}

function gridlyBuildNonMatchingIdProbeValue(candidateIds = []) {
  const sample = candidateIds.find((id) => id !== null && typeof id !== "undefined");
  const sampleText = String(sample || "").trim();
  if (/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(sampleText)) {
    return "00000000-0000-0000-0000-000000000000";
  }
  if (typeof sample === "number" || (/^-?\d+$/.test(sampleText) && sampleText !== "")) return -1;
  return "gridly-dev-purge-failure-audit-non-matching-id";
}

window.gridlyClearSupabaseTestHazards = async function gridlyClearSupabaseTestHazards(options = {}) {
  if (options?.confirm !== GRIDLY_SUPABASE_TEST_HAZARD_CONFIRMATION) {
    const blocked = { deleted: 0, failed: 0, ok: false, reason: "confirm_CLEAR_SUPABASE_TEST_HAZARDS_required" };
    console.warn("gridlyClearSupabaseTestHazards blocked", blocked);
    return blocked;
  }
  if (!supabaseClient) {
    const missing = { deleted: 0, failed: 0, ok: false, reason: "Supabase client not initialized." };
    console.warn("gridlyClearSupabaseTestHazards unavailable", missing);
    return missing;
  }

  const fetchResult = await gridlyFetchActiveSupabaseRoadHazardRows(options?.limit || 1000);
  if (!fetchResult.ok) {
    const failed = { deleted: 0, failed: 0, ok: false, error: fetchResult.error };
    console.warn("gridlyClearSupabaseTestHazards query failed", failed);
    return failed;
  }
  const idsToDelete = fetchResult.rows
    .filter((row) => gridlyIsSharedRoadHazardReportRow(row) && !gridlyIsTxDotReportSource(row))
    .map((row) => row.id)
    .filter(Boolean);
  if (!idsToDelete.length) {
    await loadSharedReports("clear_supabase_test_hazards_noop_validation");
    const trace = typeof gridlyBuildIncidentSourceTrace === "function" ? gridlyBuildIncidentSourceTrace({ sampleLimit: 5 }) : null;
    return { deleted: 0, failed: 0, ok: true, validation: trace };
  }

  const { error } = await supabaseClient.from("reports").delete().in("id", idsToDelete);
  if (error) {
    const failed = { deleted: 0, failed: idsToDelete.length, ok: false, error: error.message || "delete_failed" };
    console.error("gridlyClearSupabaseTestHazards delete failed", failed);
    return failed;
  }

  await loadSharedReports("clear_supabase_test_hazards_validation");
  const validation = typeof gridlyBuildIncidentSourceTrace === "function" ? gridlyBuildIncidentSourceTrace({ sampleLimit: 5 }) : null;
  const result = { deleted: idsToDelete.length, failed: 0, ok: true, validation };
  console.info("gridlyClearSupabaseTestHazards completed", result);
  return result;
};

window.gridlyDevPurgeFailureAudit = async function gridlyDevPurgeFailureAudit(options = {}) {
  const deleteTargetTable = "reports";
  const emptyAudit = {
    deleteAttempted: false,
    deleteCandidateCount: 0,
    deleteTargetTable,
    deleteError: null,
    deleteResponse: null,
    rlsSuspected: false,
    candidateIdsSample: [],
    dryRunCount: 0,
    actualDeleteCount: 0
  };

  if (!supabaseClient) {
    const missing = { ...emptyAudit, deleteError: { message: "Supabase client not initialized." }, deleteResponse: { ok: false, reason: "supabase_client_missing" } };
    console.warn("gridlyDevPurgeFailureAudit unavailable", missing);
    return missing;
  }

  const ROAD_HAZARD_TYPES = gridlyGetSharedRoadHazardReportTypes();
  const {
    hours = 24,
    radiusMiles = DEFAULT_NEARBY_RADIUS_MILES,
    nearLocation = null,
    sourceFilter = ["user"],
    typeFilter = [],
    deviceIdFilter = [deviceId],
    limit = 50
  } = options || {};

  const normalizedTypeFilter = Array.isArray(typeFilter)
    ? typeFilter.map((v) => String(v || "").trim().toLowerCase()).filter(Boolean)
    : [];
  const normalizedSourceFilter = Array.isArray(sourceFilter)
    ? sourceFilter.map((v) => String(v || "").trim().toLowerCase()).filter(Boolean)
    : [];
  const normalizedDeviceIdFilter = Array.isArray(deviceIdFilter)
    ? deviceIdFilter.map((v) => String(v || "").trim()).filter(Boolean)
    : [];
  const explicitTypeFilter = normalizedTypeFilter.length > 0;
  const maxRows = Math.max(1, Math.min(500, Number(limit) || 50));
  const radius = Number(radiusMiles) > 0 ? Number(radiusMiles) : 0;
  const cutoffIso = new Date(Date.now() - (Math.max(1, Number(hours) || 24) * 60 * 60 * 1000)).toISOString();
  const centerCandidate = nearLocation && Number.isFinite(Number(nearLocation.lat)) && Number.isFinite(Number(nearLocation.lng))
    ? { lat: Number(nearLocation.lat), lng: Number(nearLocation.lng), source: "nearLocation" }
    : userLocation && Number.isFinite(Number(userLocation.lat)) && Number.isFinite(Number(userLocation.lng))
    ? { lat: Number(userLocation.lat), lng: Number(userLocation.lng), source: "userLocation" }
    : map?.getCenter
    ? { lat: Number(map.getCenter().lat), lng: Number(map.getCenter().lng), source: "mapCenter" }
    : null;

  const { data, error } = await supabaseClient
    .from(deleteTargetTable)
    .select("id,report_type,source,created_at,lat,lng,crossing_id,crossing_name,detail,device_id")
    .gte("created_at", cutoffIso)
    .in("report_type", ROAD_HAZARD_TYPES)
    .order("created_at", { ascending: false })
    .limit(1000);

  if (error) {
    const queryError = gridlyNormalizeSupabaseMutationError(error) || { message: error.message || "query_failed" };
    const failed = {
      ...emptyAudit,
      deleteError: queryError,
      deleteResponse: { ok: false, stage: "candidate_query", error: queryError },
      rlsSuspected: gridlyLooksLikeSupabaseRlsError(error)
    };
    console.warn("gridlyDevPurgeFailureAudit query failed", failed);
    return failed;
  }

  const matches = (Array.isArray(data) ? data : []).filter((row) => {
    const type = String(row?.report_type || "").toLowerCase();
    const effectiveSource = String(row?.source || "user").toLowerCase();
    const crossingId = String(row?.crossing_id || "").trim();
    const isRail = crossingId.length > 0 && !gridlyIsHazardDeviceCrossingId(crossingId);

    if (!ROAD_HAZARD_TYPES.includes(type)) return false;
    if (!explicitTypeFilter && type === "hazard_cleared") return false;
    if (!explicitTypeFilter && isRail) return false;
    if (explicitTypeFilter && !normalizedTypeFilter.includes(type)) return false;
    if (normalizedSourceFilter.length && !normalizedSourceFilter.includes(effectiveSource)) return false;
    if (normalizedDeviceIdFilter.length && !normalizedDeviceIdFilter.includes(String(row?.device_id || "").trim())) return false;
    if (!radius || !centerCandidate) return true;

    return getDistanceMiles(centerCandidate.lat, centerCandidate.lng, Number(row?.lat), Number(row?.lng)) <= radius;
  }).slice(0, maxRows);

  const candidateIds = matches.map((row) => row?.id).filter(Boolean);
  const impossibleId = gridlyBuildNonMatchingIdProbeValue(candidateIds);
  const deleteProbe = candidateIds.length
    ? await supabaseClient
      .from(deleteTargetTable)
      .delete({ count: "exact" })
      .eq("id", impossibleId)
      .select("id")
    : { data: null, error: null, count: 0, status: null, statusText: "Skipped: no delete candidates." };
  const normalizedDeleteError = gridlyNormalizeSupabaseMutationError(deleteProbe?.error);
  const deleteResponse = {
    ok: !deleteProbe?.error,
    nonMutatingProbe: Boolean(candidateIds.length),
    probeFilter: candidateIds.length ? { id: impossibleId } : null,
    data: Array.isArray(deleteProbe?.data) ? deleteProbe.data : deleteProbe?.data ?? null,
    count: Number.isFinite(Number(deleteProbe?.count)) ? Number(deleteProbe.count) : null,
    status: deleteProbe?.status ?? null,
    statusText: deleteProbe?.statusText ?? null,
    error: normalizedDeleteError,
    filterComparison: {
      dryRunFilters: {
        table: deleteTargetTable,
        createdAtGte: cutoffIso,
        reportTypeIn: ROAD_HAZARD_TYPES,
        sourceFilter: normalizedSourceFilter,
        typeFilter: normalizedTypeFilter,
        deviceIdFilter: normalizedDeviceIdFilter,
        excludesHazardClearedUnlessExplicit: !explicitTypeFilter,
        excludesRailUnlessExplicit: !explicitTypeFilter,
        radiusMiles: radius,
        center: centerCandidate,
        limit: maxRows
      },
      actualDeleteFiltersInPurgeHelper: {
        table: deleteTargetTable,
        idInCandidateIdsOnly: true
      },
      filtersDiffer: true,
      note: "gridlyDevPurgeRecentRoadHazards builds candidates with the dry-run filters, then deletes by candidate id only; this audit probes delete permissions with an impossible id and does not delete candidate rows."
    }
  };
  const audit = {
    deleteAttempted: Boolean(candidateIds.length),
    deleteCandidateCount: candidateIds.length,
    deleteTargetTable,
    deleteError: normalizedDeleteError,
    deleteResponse,
    rlsSuspected: gridlyLooksLikeSupabaseRlsError(deleteProbe?.error),
    candidateIdsSample: candidateIds.slice(0, 10),
    dryRunCount: matches.length,
    actualDeleteCount: Number.isFinite(Number(deleteProbe?.count)) ? Number(deleteProbe.count) : 0
  };

  console.info("gridlyDevPurgeFailureAudit", audit);
  return audit;
};

const gridlyDevPurgeRecentRoadHazards = async function gridlyDevPurgeRecentRoadHazards(options = {}) {
  const host = String(window?.location?.hostname || "").toLowerCase();
  const isDevHost = host === "localhost" || host === "127.0.0.1" || host.endsWith(".local") || host === "";
  if (!isDevHost) {
    const blocked = { ok: false, deleted: 0, reason: `Blocked outside dev host (${host || "unknown"}).` };
    console.warn("gridlyDevPurgeRecentRoadHazards blocked", blocked);
    return blocked;
  }
  if (!supabaseClient) {
    const missing = { ok: false, deleted: 0, reason: "Supabase client not initialized." };
    console.warn("gridlyDevPurgeRecentRoadHazards unavailable", missing);
    return missing;
  }

  const ROAD_HAZARD_TYPES = gridlyGetSharedRoadHazardReportTypes();
  const {
    dryRun = true,
    hours = 24,
    radiusMiles = DEFAULT_NEARBY_RADIUS_MILES,
    nearLocation = null,
    sourceFilter = ["user"],
    typeFilter = [],
    deviceIdFilter = [deviceId],
    limit = 50,
    confirm = false
  } = options || {};

  const normalizedTypeFilter = Array.isArray(typeFilter)
    ? typeFilter.map((v) => String(v || "").trim().toLowerCase()).filter(Boolean)
    : [];
  const normalizedSourceFilter = Array.isArray(sourceFilter)
    ? sourceFilter.map((v) => String(v || "").trim().toLowerCase()).filter(Boolean)
    : [];
  const normalizedDeviceIdFilter = Array.isArray(deviceIdFilter)
    ? deviceIdFilter.map((v) => String(v || "").trim()).filter(Boolean)
    : [];
  const explicitTypeFilter = normalizedTypeFilter.length > 0;
  const maxRows = Math.max(1, Math.min(500, Number(limit) || 50));
  const radius = Number(radiusMiles) > 0 ? Number(radiusMiles) : 0;
  const cutoffIso = new Date(Date.now() - (Math.max(1, Number(hours) || 24) * 60 * 60 * 1000)).toISOString();
  const centerCandidate = nearLocation && Number.isFinite(Number(nearLocation.lat)) && Number.isFinite(Number(nearLocation.lng))
    ? { lat: Number(nearLocation.lat), lng: Number(nearLocation.lng), source: "nearLocation" }
    : userLocation && Number.isFinite(Number(userLocation.lat)) && Number.isFinite(Number(userLocation.lng))
    ? { lat: Number(userLocation.lat), lng: Number(userLocation.lng), source: "userLocation" }
    : map?.getCenter
    ? { lat: Number(map.getCenter().lat), lng: Number(map.getCenter().lng), source: "mapCenter" }
    : null;

  console.warn("⚠️ gridlyDevPurgeRecentRoadHazards: This helper targets Supabase report SOURCE rows. Generated road-* incidents are derived output and are not directly persisted. Always review dryRun output before running confirm delete.");

  const classifyCleanupCandidate = (row = {}) => {
    const type = String(row?.report_type || "").trim().toLowerCase();
    const effectiveSource = String(row?.source || "user").trim().toLowerCase();
    const rowDeviceId = String(row?.device_id || "").trim();
    const crossingId = String(row?.crossing_id || "").trim();
    const isHazardDeviceId = gridlyIsHazardDeviceCrossingId(crossingId);
    const isRail = crossingId.length > 0 && !isHazardDeviceId;
    const createdTime = new Date(row?.created_at || 0).getTime();
    const expiresTime = new Date(row?.expires_at || 0).getTime();
    const cutoffTime = new Date(cutoffIso).getTime();
    const reasons = [];
    const distanceMiles = radius && centerCandidate
      ? getDistanceMiles(centerCandidate.lat, centerCandidate.lng, Number(row?.lat), Number(row?.lng))
      : null;

    if (!ROAD_HAZARD_TYPES.includes(type)) reasons.push("report_type_not_shared_road_hazard");
    if (!Number.isFinite(expiresTime) || expiresTime <= Date.now()) reasons.push("not_active_or_missing_expires_at");
    if (!Number.isFinite(createdTime) || createdTime < cutoffTime) reasons.push("created_at_before_cutoff");
    if (!explicitTypeFilter && type === "hazard_cleared") reasons.push("hazard_cleared_excluded_without_explicit_type_filter");
    if (!explicitTypeFilter && isRail) reasons.push("crossing_id_present_rail_report_excluded_without_explicit_type_filter");
    if (explicitTypeFilter && !normalizedTypeFilter.includes(type)) reasons.push("type_filter_mismatch");
    if (normalizedSourceFilter.length && !normalizedSourceFilter.includes(effectiveSource)) reasons.push("source_filter_mismatch");
    if (normalizedDeviceIdFilter.length && !normalizedDeviceIdFilter.includes(rowDeviceId)) reasons.push("device_id_filter_mismatch");
    if (radius && centerCandidate && !(Number.isFinite(distanceMiles) && distanceMiles <= radius)) reasons.push("outside_radius");

    return {
      eligible: reasons.length === 0,
      reasons,
      checks: {
        reportType: type,
        reportTypeAllowed: ROAD_HAZARD_TYPES.includes(type),
        activeByExpiresAt: Number.isFinite(expiresTime) && expiresTime > Date.now(),
        createdAtWithinWindow: Number.isFinite(createdTime) && createdTime >= cutoffTime,
        source: effectiveSource,
        sourceFilterPasses: !normalizedSourceFilter.length || normalizedSourceFilter.includes(effectiveSource),
        deviceId: rowDeviceId,
        deviceIdFilterPasses: !normalizedDeviceIdFilter.length || normalizedDeviceIdFilter.includes(rowDeviceId),
        crossingId,
        hasCrossingId: crossingId.length > 0,
        crossingIdRepresentsHazardDevice: isHazardDeviceId,
        classifiedAsRailReport: isRail,
        classifiedAsRoadHazard: ROAD_HAZARD_TYPES.includes(type) && (!isRail || explicitTypeFilter),
        distanceMiles,
        radiusPasses: !radius || !centerCandidate || (Number.isFinite(distanceMiles) && distanceMiles <= radius),
        devTestMarkerRequired: false,
        devTestMarkerPasses: true
      }
    };
  };

  const { data, error } = await supabaseClient
    .from("reports")
    .select("id,report_type,source,created_at,expires_at,lat,lng,crossing_id,crossing_name,detail,device_id")
    .gte("created_at", cutoffIso)
    .in("report_type", ROAD_HAZARD_TYPES)
    .order("created_at", { ascending: false })
    .limit(1000);

  if (error) {
    console.error("gridlyDevPurgeRecentRoadHazards query failed", error);
    return { ok: false, deleted: 0, error: error.message || "query_failed" };
  }

  const nowIso = new Date().toISOString();
  const { data: activeInventoryData, error: activeInventoryError } = await supabaseClient
    .from("reports")
    .select("id,report_type,source,created_at,expires_at,lat,lng,crossing_id,crossing_name,detail,device_id")
    .gt("expires_at", nowIso)
    .in("report_type", ROAD_HAZARD_TYPES)
    .order("created_at", { ascending: false })
    .limit(1000);

  const matches = (Array.isArray(data) ? data : []).filter((row) => classifyCleanupCandidate(row).eligible).slice(0, maxRows);

  const groupedClusterKeys = [...new Set(matches.map((row) => getHazardClusterKey({ type: row.report_type, lat: row.lat, lng: row.lng })))];
  const predictedRoadIncidentIds = groupedClusterKeys.map((clusterKey) => `road-${clusterKey}`);
  const candidates = matches.map((row) => ({
    id: row.id,
    type: row.report_type,
    source: row.source || "user",
    created_at: row.created_at,
    expires_at: row.expires_at || "",
    lat: row.lat,
    lng: row.lng,
    crossing_id: row.crossing_id || "",
    crossing_name: row.crossing_name || "",
    detail: row.detail || "",
    device_id: row.device_id || ""
  }));

  const activeInventoryRows = (Array.isArray(activeInventoryData) ? activeInventoryData : []).filter(gridlyIsSharedRoadHazardReportRow);
  const inventoryEligibility = activeInventoryRows.map((row) => {
    const classification = classifyCleanupCandidate(row);
    return {
      id: row.id,
      type: row.report_type,
      source: row.source || "user",
      created_at: row.created_at || "",
      expires_at: row.expires_at || "",
      crossing_id: row.crossing_id || "",
      device_id: row.device_id || "",
      eligible: classification.eligible,
      exclusionReasons: classification.reasons,
      checks: classification.checks
    };
  });
  const inventoryExclusionReasonCounts = inventoryEligibility.reduce((acc, row) => {
    (row.exclusionReasons.length ? row.exclusionReasons : ["eligible_candidate"]).forEach((reason) => {
      acc[reason] = (acc[reason] || 0) + 1;
    });
    return acc;
  }, {});

  if (candidates.length) console.table(candidates);
  if (inventoryEligibility.length) console.table(inventoryEligibility);

  const summary = {
    ok: true,
    dryRun: Boolean(dryRun),
    cutoffIso,
    radiusMiles: radius,
    hours: Math.max(1, Number(hours) || 24),
    limit: maxRows,
    sourceFilter: normalizedSourceFilter,
    typeFilter: normalizedTypeFilter,
    deviceIdFilter: normalizedDeviceIdFilter,
    safeDeleteScope: "dev host only; report rows must be recent, user-sourced by default, from the current device by default, road hazard types, not actual rail/crossing reports, and within the dev radius when a center is available",
    center: centerCandidate,
    candidateCount: candidates.length,
    candidates,
    activeInventoryComparison: {
      ok: !activeInventoryError,
      error: activeInventoryError?.message || "",
      activeInventoryRows: activeInventoryRows.length,
      activeInventoryRowsEligibleUnderCleanupFilters: inventoryEligibility.filter((row) => row.eligible).length,
      activeInventoryRowsExcludedUnderCleanupFilters: inventoryEligibility.filter((row) => !row.eligible).length,
      exclusionReasonCounts: inventoryExclusionReasonCounts,
      note: "Inventory uses expires_at > now() active shared road-hazard rows. Cleanup candidates additionally require created_at within the recent-hours window, source/device/radius filters, and protection for actual rail/crossing reports. crossing_id values with the hazard-device-* prefix are treated as road-hazard identifiers, not rail reports.",
      rows: inventoryEligibility
    },
    groupedClusterKeys,
    predictedRoadIncidentIds,
    currentLiveHazardIncidentCount: getLiveHazardIncidents().length,
    currentGeneratedRoadIncidentCount: getUnifiedIncidents().filter((item) => String(item?.id || "").startsWith("road-")).length,
    deleted: 0
  };

  if (dryRun !== false) {
    console.info("gridlyDevPurgeRecentRoadHazards dry run", summary);
    return summary;
  }

  if (confirm !== true) {
    return { ...summary, ok: false, reason: "confirm_true_required_for_delete" };
  }

  const idsToDelete = candidates.map((row) => row.id).filter(Boolean);
  if (!idsToDelete.length) {
    console.info("gridlyDevPurgeRecentRoadHazards no matches to delete", summary);
    return summary;
  }

  const { error: deleteError } = await supabaseClient.from("reports").delete().in("id", idsToDelete);
  if (deleteError) {
    console.error("gridlyDevPurgeRecentRoadHazards delete failed", deleteError);
    return { ...summary, ok: false, error: deleteError.message || "delete_failed" };
  }

  await loadSharedReports("dev_purge_recent_road_hazards");

  summary.deleted = idsToDelete.length;
  console.info("gridlyDevPurgeRecentRoadHazards completed", summary);
  return summary;
};



const gridlyDevPurgeRecentCrossingReports = async function gridlyDevPurgeRecentCrossingReports(options = {}) {
  const host = String(window?.location?.hostname || "").toLowerCase();
  const isDevHost = host === "localhost" || host === "127.0.0.1" || host.endsWith(".local") || host === "";
  if (!isDevHost) {
    const blocked = { ok: false, deleted: 0, reason: `Blocked outside dev host (${host || "unknown"}).` };
    console.warn("gridlyDevPurgeRecentCrossingReports blocked", blocked);
    return blocked;
  }
  if (!supabaseClient) {
    const missing = { ok: false, deleted: 0, reason: "Supabase client not initialized." };
    console.warn("gridlyDevPurgeRecentCrossingReports unavailable", missing);
    return missing;
  }

  const {
    dryRun = true,
    hours = 24,
    radiusMiles = DEFAULT_NEARBY_RADIUS_MILES,
    nearLocation = null,
    sourceFilter = ["user"],
    deviceIdFilter = [deviceId],
    limit = 50,
    confirm = false
  } = options || {};

  const roadHazardTypes = gridlyGetSharedRoadHazardReportTypes();
  const normalizedSourceFilter = Array.isArray(sourceFilter)
    ? sourceFilter.map((v) => String(v || "").trim().toLowerCase()).filter(Boolean)
    : [];
  const normalizedDeviceIdFilter = Array.isArray(deviceIdFilter)
    ? deviceIdFilter.map((v) => String(v || "").trim()).filter(Boolean)
    : [];
  const maxRows = Math.max(1, Math.min(500, Number(limit) || 50));
  const radius = Number(radiusMiles) > 0 ? Number(radiusMiles) : 0;
  const cutoffIso = new Date(Date.now() - (Math.max(1, Number(hours) || 24) * 60 * 60 * 1000)).toISOString();
  const centerCandidate = nearLocation && Number.isFinite(Number(nearLocation.lat)) && Number.isFinite(Number(nearLocation.lng))
    ? { lat: Number(nearLocation.lat), lng: Number(nearLocation.lng), source: "nearLocation" }
    : userLocation && Number.isFinite(Number(userLocation.lat)) && Number.isFinite(Number(userLocation.lng))
    ? { lat: Number(userLocation.lat), lng: Number(userLocation.lng), source: "userLocation" }
    : map?.getCenter
    ? { lat: Number(map.getCenter().lat), lng: Number(map.getCenter().lng), source: "mapCenter" }
    : null;

  const { data, error } = await supabaseClient
    .from("reports")
    .select("id,report_type,source,created_at,lat,lng,crossing_id,crossing_name,detail,device_id")
    .gte("created_at", cutoffIso)
    .order("created_at", { ascending: false })
    .limit(1000);

  if (error) {
    console.error("gridlyDevPurgeRecentCrossingReports query failed", error);
    return { ok: false, deleted: 0, error: error.message || "query_failed" };
  }

  const matches = (Array.isArray(data) ? data : []).filter((row) => {
    const type = String(row?.report_type || "").toLowerCase();
    const effectiveSource = String(row?.source || "user").toLowerCase();
    const crossingId = String(row?.crossing_id || "").trim();
    if (roadHazardTypes.includes(type)) return false;
    if (!crossingId || crossingId.startsWith("hazard-")) return false;
    if (normalizedSourceFilter.length && !normalizedSourceFilter.includes(effectiveSource)) return false;
    if (normalizedDeviceIdFilter.length && !normalizedDeviceIdFilter.includes(String(row?.device_id || "").trim())) return false;
    if (!radius || !centerCandidate) return true;
    return getDistanceMiles(centerCandidate.lat, centerCandidate.lng, Number(row?.lat), Number(row?.lng)) <= radius;
  }).slice(0, maxRows);

  const candidates = matches.map((row) => ({
    id: row.id,
    type: row.report_type,
    source: row.source || "user",
    created_at: row.created_at,
    lat: row.lat,
    lng: row.lng,
    crossing_id: row.crossing_id || "",
    crossing_name: row.crossing_name || "",
    detail: row.detail || "",
    device_id: row.device_id || ""
  }));

  const summary = {
    ok: true,
    dryRun: Boolean(dryRun),
    cutoffIso,
    radiusMiles: radius,
    hours: Math.max(1, Number(hours) || 24),
    limit: maxRows,
    sourceFilter: normalizedSourceFilter,
    deviceIdFilter: normalizedDeviceIdFilter,
    safeDeleteScope: "dev host only; recent crossing rows from the current device by default, user-sourced by default, non-road-hazard report types, and within the dev radius when a center is available",
    center: centerCandidate,
    candidateCount: candidates.length,
    candidates,
    deleted: 0
  };

  if (dryRun !== false) {
    console.info("gridlyDevPurgeRecentCrossingReports dry run", summary);
    return summary;
  }
  if (confirm !== true) return { ...summary, ok: false, reason: "confirm_true_required_for_delete" };

  const idsToDelete = candidates.map((row) => row.id).filter(Boolean);
  if (!idsToDelete.length) {
    console.info("gridlyDevPurgeRecentCrossingReports no matches to delete", summary);
    return summary;
  }

  const { error: deleteError } = await supabaseClient.from("reports").delete().in("id", idsToDelete);
  if (deleteError) {
    console.error("gridlyDevPurgeRecentCrossingReports delete failed", deleteError);
    return { ...summary, ok: false, error: deleteError.message || "delete_failed" };
  }

  summary.deleted = idsToDelete.length;
  console.info("gridlyDevPurgeRecentCrossingReports completed", summary);
  return summary;
};


