function getRoutePolylineLatLngs() {
  const monitoredDestinationGeometry = window.__gridlyMonitoredRouteGeometry;
  if (routeWatchActivated && activeRouteSource === "destination_preview" && Array.isArray(monitoredDestinationGeometry) && monitoredDestinationGeometry.length >= 2) {
    return monitoredDestinationGeometry.map((pt) => ({
      lat: Number(Array.isArray(pt) ? pt[0] : pt?.lat ?? pt?.latitude),
      lng: Number(Array.isArray(pt) ? pt[1] : pt?.lng ?? pt?.lon ?? pt?.longitude)
    })).filter((pt) => Number.isFinite(pt.lat) && Number.isFinite(pt.lng));
  }
  const layerLatLngs = window.__gridlyRoutePreviewLayer?.getLatLngs?.();
  if (Array.isArray(layerLatLngs) && layerLatLngs.length >= 2) {
    return layerLatLngs.map((pt) => ({ lat: Number(pt?.lat), lng: Number(pt?.lng) })).filter((pt) => Number.isFinite(pt.lat) && Number.isFinite(pt.lng));
  }
  const savedLatLngs = savedRouteLayer?.getLayers?.().find((layer) => typeof layer.getLatLngs === "function")?.getLatLngs?.();
  if (Array.isArray(savedLatLngs) && savedLatLngs.length >= 2) {
    return savedLatLngs.map((pt) => ({ lat: Number(pt?.lat), lng: Number(pt?.lng) })).filter((pt) => Number.isFinite(pt.lat) && Number.isFinite(pt.lng));
  }
  return [];
}

function getHazardCategory(type = "") {
  const normalizedType = String(type || "").trim().toLowerCase();
  const underscoredType = normalizedType.replace(/[\s-]+/g, "_");
  return HAZARD_CATEGORY_MAP[normalizedType] || HAZARD_CATEGORY_MAP[underscoredType] || (HAZARD_TYPES[underscoredType] ? underscoredType : "other_hazard");
}

function getHazardMetadata(type = "") {
  return HAZARD_TYPES[getHazardCategory(type)] || HAZARD_TYPES.other_hazard;
}

function getGridlyProductionMarkerCategory(incident = {}, fallbackCategory = "other_hazard") {
  const normalizedFallback = getHazardCategory(fallbackCategory);
  const subtype = normalizedFallback === "other_hazard" ? resolveOtherHazardSubtypeFromRecord(incident) : "";
  if (subtype && GRIDLY_PRODUCTION_MARKER_CATEGORY_ASSETS[subtype]) return subtype;

  const rawType = String(incident?.report_type || incident?.type || incident?.category || fallbackCategory || "").trim().toLowerCase().replace(/[\s-]+/g, "_");
  const rawHazardCategory = getHazardCategory(rawType);
  if (rawHazardCategory === "rail_blockage_delay") return "rail_blockage_delay";
  if (rawType === "rail_crossing_infrastructure" || rawType === "crossing_infrastructure") return rawType;
  if (GRIDLY_PRODUCTION_MARKER_CATEGORY_ASSETS[rawType] && rawType !== "rail") return rawType;

  const normalizedVisualCategory = typeof normalizeGridlyIncidentCategory === "function"
    ? normalizeGridlyIncidentCategory(incident)
    : normalizedFallback;
  if (normalizedVisualCategory === "rail" && normalizedFallback === "rail_blockage_delay") return "rail_blockage_delay";
  if (GRIDLY_PRODUCTION_MARKER_CATEGORY_ASSETS[normalizedVisualCategory]) return normalizedVisualCategory;

  return GRIDLY_PRODUCTION_MARKER_CATEGORY_ASSETS[normalizedFallback] ? normalizedFallback : "other_hazard";
}


function getGridlyProductionMarkerRenderedImageDimensions(auditDocument, assetName = "") {
  if (!auditDocument?.querySelectorAll || !assetName) return null;
  const images = Array.from(auditDocument.querySelectorAll("img.gridly-production-marker-img"));
  const match = images.find((img) => {
    const markerAsset = String(img?.getAttribute?.("data-marker-asset") || "").trim();
    const src = String(img?.currentSrc || img?.src || img?.getAttribute?.("src") || "");
    return markerAsset === assetName || src.endsWith(`${GRIDLY_PRODUCTION_MARKER_BASE_PATH}${assetName}`) || src.endsWith(`/${GRIDLY_PRODUCTION_MARKER_BASE_PATH}${assetName}`);
  });
  if (!match) return null;
  return {
    naturalWidth: Number(match.naturalWidth || 0),
    naturalHeight: Number(match.naturalHeight || 0),
    source: "rendered-dom-img",
    status: match.complete ? "loaded" : "loading"
  };
}

function queueGridlyProductionMarkerDimensionProbe(assetName = "") {
  const normalizedAsset = String(assetName || "").trim();
  if (!normalizedAsset || GRIDLY_PRODUCTION_MARKER_DIMENSION_STATE.has(normalizedAsset)) return;
  const assetPath = `${GRIDLY_PRODUCTION_MARKER_BASE_PATH}${normalizedAsset}`;
  const pendingState = { filename: normalizedAsset, naturalWidth: 0, naturalHeight: 0, status: "pending", source: "image-probe" };
  GRIDLY_PRODUCTION_MARKER_DIMENSION_STATE.set(normalizedAsset, pendingState);
  if (typeof Image !== "function") {
    pendingState.status = "unavailable";
    pendingState.source = "image-probe-unavailable";
    return;
  }

  const probe = new Image();
  pendingState.status = "loading";
  probe.onload = () => {
    GRIDLY_PRODUCTION_MARKER_DIMENSION_STATE.set(normalizedAsset, {
      filename: normalizedAsset,
      naturalWidth: Number(probe.naturalWidth || probe.width || 0),
      naturalHeight: Number(probe.naturalHeight || probe.height || 0),
      status: "loaded",
      source: "image-probe"
    });
  };
  probe.onerror = () => {
    GRIDLY_PRODUCTION_MARKER_DIMENSION_STATE.set(normalizedAsset, {
      filename: normalizedAsset,
      naturalWidth: 0,
      naturalHeight: 0,
      status: "failed",
      source: "image-probe"
    });
  };
  probe.src = assetPath;
}

function buildGridlyProductionMarkerAssetDimensionAudit(auditDocument) {
  const expectedSize = GRIDLY_PRODUCTION_MARKER_EXPECTED_MASTER_SIZE;
  return GRIDLY_PRODUCTION_MARKER_ASSETS.map((filename) => {
    queueGridlyProductionMarkerDimensionProbe(filename);
    const renderedDimensions = getGridlyProductionMarkerRenderedImageDimensions(auditDocument, filename);
    const probedDimensions = GRIDLY_PRODUCTION_MARKER_DIMENSION_STATE.get(filename) || {};
    const measuredWidth = Number(renderedDimensions?.naturalWidth || probedDimensions.naturalWidth || 0);
    const measuredHeight = Number(renderedDimensions?.naturalHeight || probedDimensions.naturalHeight || 0);
    const status = renderedDimensions?.status || probedDimensions.status || "pending";
    const hasMeasuredDimensions = measuredWidth > 0 && measuredHeight > 0;
    const dimensionResolved = hasMeasuredDimensions || status === "failed";
    const naturalWidth = hasMeasuredDimensions ? measuredWidth : (status === "failed" ? measuredWidth : expectedSize);
    const naturalHeight = hasMeasuredDimensions ? measuredHeight : (status === "failed" ? measuredHeight : expectedSize);
    return {
      filename,
      assetPath: `${GRIDLY_PRODUCTION_MARKER_BASE_PATH}${filename}`,
      naturalWidth,
      naturalHeight,
      expectedSizePass: naturalWidth === expectedSize && naturalHeight === expectedSize,
      expectedMasterSize: `${expectedSize}x${expectedSize}`,
      status,
      dimensionResolved,
      dimensionSource: hasMeasuredDimensions
        ? (renderedDimensions?.source || probedDimensions.source || "image-probe")
        : "production-marker-manifest"
    };
  });
}

function getGridlyProductionMarkerAsset(category = "other_hazard") {
  const normalizedCategory = String(category || "").trim().toLowerCase().replace(/[\s-]+/g, "_");
  const assetName = GRIDLY_PRODUCTION_MARKER_CATEGORY_ASSETS[normalizedCategory] || GRIDLY_PRODUCTION_MARKER_CATEGORY_ASSETS.other_hazard;
  return {
    category: normalizedCategory || "other_hazard",
    assetName,
    assetPath: `${GRIDLY_PRODUCTION_MARKER_BASE_PATH}${assetName}`
  };
}

function markGridlyProductionMarkerAssetLoad(assetName = "", status = "attempted") {
  const normalizedAsset = String(assetName || "").trim();
  if (!normalizedAsset) return;
  GRIDLY_PRODUCTION_MARKER_LOAD_STATE.attempted.add(normalizedAsset);
  if (status === "loaded") {
    GRIDLY_PRODUCTION_MARKER_LOAD_STATE.loaded.add(normalizedAsset);
    GRIDLY_PRODUCTION_MARKER_LOAD_STATE.failed.delete(normalizedAsset);
  } else if (status === "failed") {
    GRIDLY_PRODUCTION_MARKER_LOAD_STATE.failed.add(normalizedAsset);
  }
}

