function buildGridlyOwnershipStateAudit(options = {}) {
  const auditVersion = "V226.4";
  const safeNow = () => {
    try {
      return new Date().toISOString();
    } catch (error) {
      return "";
    }
  };
  const safeTextById = (id) => {
    try {
      if (typeof document === "undefined") return null;
      const element = document.getElementById(id);
      if (!element) return null;
      return String(element.textContent || "").replace(/\s+/g, " ").trim();
    } catch (error) {
      return null;
    }
  };
  const safeCall = (fn, fallback = null) => {
    try {
      return typeof fn === "function" ? fn() : fallback;
    } catch (error) {
      return fallback;
    }
  };
  const safeBoolean = (fn) => {
    try {
      return Boolean(fn());
    } catch (error) {
      return false;
    }
  };
  const safeClassPresent = (element, className) => {
    try {
      return Boolean(element?.classList?.contains?.(className));
    } catch (error) {
      return false;
    }
  };
  const routeLatLngs = safeCall(() => (typeof getRoutePolylineLatLngs === "function" ? getRoutePolylineLatLngs() : null), null);
  const activeRouteCoordinateCount = Array.isArray(routeLatLngs)
    ? routeLatLngs.filter((pt) => Number.isFinite(Number(pt?.lat)) && Number.isFinite(Number(pt?.lng))).length
    : 0;
  const activeRoutePresent = activeRouteCoordinateCount > 1;
  const selectedDestinationLabel = safeCall(() => (typeof getSelectedDestinationLabel === "function" ? getSelectedDestinationLabel() : null), null);
  const selectedLabel = String(selectedDestinationLabel || "").trim();
  const routeIsMonitoring = safeBoolean(() => routeWatchActivated || window.__gridlyRouteWatchActive);
  const commandVisibilityState = safeCall(() => (typeof getGridlyMobileCommandCardVisibilityState === "function" ? getGridlyMobileCommandCardVisibilityState() : null), null);
  const popupInteractionActive = safeBoolean(() => commandVisibilityState?.popupInteractionActive || (typeof isGridlyLeafletPopupInteractionActive === "function" && isGridlyLeafletPopupInteractionActive()) || (typeof isGridlyCrossingPopupInteractionActive === "function" && isGridlyCrossingPopupInteractionActive()));
  const awarenessPanelMode = false;

  let commandCardOwner = commandVisibilityState?.visible ? (commandVisibilityState?.owner || "unknown") : "none";
  if (commandCardOwner === "none" && routeIsMonitoring) commandCardOwner = "route";
  else if (commandCardOwner === "none" && selectedLabel) commandCardOwner = "destination";

  const selectedAwarenessArea = safeCall(() => {
    if (typeof getSelectedGridlyAwarenessArea === "function") return getSelectedGridlyAwarenessArea();
    if (typeof getGridlySelectedAwarenessArea === "function") return getGridlySelectedAwarenessArea();
    return null;
  }, null);
  const awarenessStorageValue = safeCall(() => {
    if (typeof gridlySafeLocalStorageGet === "function") return gridlySafeLocalStorageGet("gridlyHomeTown");
    if (typeof window !== "undefined" && window.localStorage) return window.localStorage.getItem("gridlyHomeTown");
    return null;
  }, null);

  const awarenessDiagnostics = safeCall(() => (
    typeof getGridlyAwarenessModeDiagnostics === "function"
      ? getGridlyAwarenessModeDiagnostics({ ...options, ownershipAuditReadOnly: true, routeLatLngs: Array.isArray(routeLatLngs) ? routeLatLngs : [] })
      : null
  ), null);
  const pulseModel = options?.includeFreshPulseModel === true
    ? safeCall(() => (typeof buildGridlyCommunityPulseModel === "function" ? buildGridlyCommunityPulseModel({ ...options, ownershipAuditReadOnly: true, routeLatLngs: Array.isArray(routeLatLngs) ? routeLatLngs : [] }) : null), null)
    : null;
  const pulseState = pulseModel || (typeof gridlyCommunityPulseAuditState === "object" && gridlyCommunityPulseAuditState ? gridlyCommunityPulseAuditState : null);
  const pulseSurface = safeCall(() => (typeof document !== "undefined" ? document.getElementById("gridlyCommunityPulseSurface") : null), null);
  const pulseVisible = safeBoolean(() => {
    if (pulseSurface) return !pulseSurface.hidden;
    return pulseState?.pulseVisible;
  });
  const pulseSuppressedReason = String(pulseState?.pulseSuppressedReason || (awarenessDiagnostics?.awarenessMode === "route" ? "route-priority suppression: active route intelligence is primary" : "") || "");

  const commandCard = safeCall(() => (typeof document !== "undefined" ? document.getElementById("mobileDestinationCommandTitle")?.closest?.(".mobile-destination-command") || document.querySelector(".mobile-destination-command") : null), null);
  const crossingsElement = safeCall(() => (typeof document !== "undefined" ? document.getElementById("mobileAwarenessPanelCrossings") : null), null);
  const issuesElement = safeCall(() => (typeof document !== "undefined" ? document.getElementById("mobileAwarenessPanelIssues") : null), null);
  const destinationPreview = safeCall(() => (typeof window !== "undefined" && window.GridlyDestinationRoutePreview ? window.GridlyDestinationRoutePreview : null), null);
  const selectedDestination = safeCall(() => {
    if (typeof ensureGridlySearchState !== "function" || typeof normalizeGridlySearchResult !== "function") return null;
    return normalizeGridlySearchResult(ensureGridlySearchState()?.selectedDestination);
  }, null);

  const routeTakingCommandCardOwnership = commandCardOwner === "route" || Boolean(routeIsMonitoring && !awarenessPanelMode);
  const destinationTakingCommandCardOwnership = commandCardOwner === "destination";
  const routeSuppressingCommunityPulse = Boolean(activeRoutePresent && (awarenessDiagnostics?.awarenessMode === "route" || /route-priority suppression/i.test(pulseSuppressedReason)) && !pulseVisible);
  const awarenessLanguagePattern = /awareness|community|county|area|crossing|hazard|quiet|nearby/i;
  const commandCardTextForConflict = [
    safeTextById("mobileAwarenessPanelKicker"),
    safeTextById("mobileDestinationCommandTitle"),
    safeTextById("mobileDestinationCommandMeta"),
    safeTextById("mobileAwarenessPanelCrossings"),
    safeTextById("mobileAwarenessPanelIssues")
  ].filter(Boolean).join(" ");
  const awarenessLanguageStillShowing = awarenessLanguagePattern.test(commandCardTextForConflict);
  const conflictingOwners = Boolean(
    ((commandCardOwner === "route" || commandCardOwner === "destination") && awarenessLanguageStillShowing)
    || (commandCardOwner === "awareness" && routeSuppressingCommunityPulse)
  );
  const awarenessPrimary = Boolean(
    commandCardOwner === "awareness"
    && (pulseVisible || !routeSuppressingCommunityPulse)
    && !routeTakingCommandCardOwnership
    && !destinationTakingCommandCardOwnership
  );
  let summary = "Awareness is primary; no route or destination is taking command-card ownership.";
  if (conflictingOwners) summary = "Potential ownership conflict detected between command card language and route/community pulse state.";
  else if (destinationTakingCommandCardOwnership) summary = "Destination state is taking command-card ownership under current behavior.";
  else if (routeTakingCommandCardOwnership || routeSuppressingCommunityPulse) summary = "Route state is taking priority under current behavior.";
  else if (!awarenessPrimary) summary = "Ownership is indeterminate from the current runtime state.";

  return {
    available: true,
    version: auditVersion,
    generatedAt: safeNow(),
    awarenessArea: {
      selectedName: selectedAwarenessArea?.label || selectedAwarenessArea?.storageValue || null,
      selectedKey: selectedAwarenessArea?.key || null,
      storageValue: selectedAwarenessArea?.storageValue || awarenessStorageValue || null
    },
    commandCard: {
      selectedLabel: selectedLabel || null,
      routeIsMonitoring,
      awarenessPanelMode,
      popupInteractionActive,
      visible: Boolean(commandVisibilityState?.visible),
      visibilityRule: commandVisibilityState?.rule || null,
      owner: commandCardOwner,
      kickerText: safeTextById("mobileAwarenessPanelKicker"),
      titleText: safeTextById("mobileDestinationCommandTitle"),
      metaText: safeTextById("mobileDestinationCommandMeta"),
      crossingsText: safeTextById("mobileAwarenessPanelCrossings"),
      issuesText: safeTextById("mobileAwarenessPanelIssues"),
      impactText: safeTextById("mobileDestinationCommandImpact"),
      buttonText: safeTextById("mobileDestinationCommandBtn"),
      awarenessLinesVisible: Boolean((crossingsElement && !crossingsElement.hidden) || (issuesElement && !issuesElement.hidden)),
      destinationPanelClassPresent: safeClassPresent(commandCard, "is-destination-panel") || safeClassPresent(commandCard, "destination-panel"),
      bodyDestinationPanelClassPresent: safeBoolean(() => document.body?.classList?.contains?.("is-destination-panel") || document.body?.classList?.contains?.("destination-panel"))
    },
    communityPulse: {
      awarenessMode: awarenessDiagnostics?.awarenessMode || pulseState?.awarenessMode || null,
      pulseVisible,
      pulseSuppressedReason: pulseSuppressedReason || null,
      activeRouteCoordinateCount,
      activeRoutePresent,
      headlineText: safeTextById("gridlyCommunityPulseHeadline") || pulseState?.renderedPulseHeadline || null,
      sublineText: safeTextById("gridlyCommunityPulseSubline") || pulseState?.renderedPulseSubline || null
    },
    routeState: {
      routeWatchActivated: safeBoolean(() => routeWatchActivated),
      windowRouteWatchActive: safeBoolean(() => window.__gridlyRouteWatchActive),
      activeRouteCoordinateCount,
      savedRouteLayerPresent: safeBoolean(() => savedRouteLayer && typeof savedRouteLayer.getLayers === "function" && savedRouteLayer.getLayers().length > 0),
      routePreviewLayerPresent: safeBoolean(() => window.__gridlyRoutePreviewLayer && typeof window.__gridlyRoutePreviewLayer.getLatLngs === "function" && window.__gridlyRoutePreviewLayer.getLatLngs().length > 0)
    },
    destinationState: {
      selectedDestinationPresent: Boolean(selectedDestination || selectedLabel),
      selectedDestinationLabel: selectedLabel || null,
      routePreviewActive: Boolean(destinationPreview?.active),
      routePreviewStatus: destinationPreview?.status || null
    },
    ownershipAssessment: {
      awarenessPrimary,
      routeTakingCommandCardOwnership,
      destinationTakingCommandCardOwnership,
      routeSuppressingCommunityPulse,
      conflictingOwners,
      summary
    }
  };
}

window.gridlyOwnershipStateAudit = function gridlyOwnershipStateAudit(options = {}) {
  try {
    return buildGridlyOwnershipStateAudit(options || {});
  } catch (error) {
    return {
      available: true,
      version: "V226.4",
      generatedAt: (() => {
        try { return new Date().toISOString(); } catch (dateError) { return ""; }
      })(),
      error: error?.message || "ownership audit unavailable",
      awarenessArea: { selectedName: null, selectedKey: null, storageValue: null },
      commandCard: {
        selectedLabel: null,
        routeIsMonitoring: null,
        awarenessPanelMode: null,
        owner: "unknown",
        kickerText: null,
        titleText: null,
        metaText: null,
        crossingsText: null,
        issuesText: null,
        impactText: null,
        buttonText: null,
        awarenessLinesVisible: false,
        destinationPanelClassPresent: false,
        bodyDestinationPanelClassPresent: false
      },
      communityPulse: {
        awarenessMode: null,
        pulseVisible: false,
        pulseSuppressedReason: null,
        activeRouteCoordinateCount: 0,
        activeRoutePresent: false,
        headlineText: null,
        sublineText: null
      },
      routeState: {
        routeWatchActivated: null,
        windowRouteWatchActive: null,
        activeRouteCoordinateCount: 0,
        savedRouteLayerPresent: false,
        routePreviewLayerPresent: false
      },
      destinationState: {
        selectedDestinationPresent: false,
        selectedDestinationLabel: null,
        routePreviewActive: false,
        routePreviewStatus: null
      },
      ownershipAssessment: {
        awarenessPrimary: false,
        routeTakingCommandCardOwnership: false,
        destinationTakingCommandCardOwnership: false,
        routeSuppressingCommunityPulse: false,
        conflictingOwners: false,
        summary: "Ownership audit caught an error and returned a safe fallback."
      }
    };
  }
};



function gridlyHistoricalIntelligenceTitleCaseLocation(value = "") {
  const preservedAbbreviations = new Set(["US", "TX", "FM", "SH", "IH", "I", "CR", "RR"]);
  return String(value || "")
    .trim()
    .toLowerCase()
    .replace(/\b[a-z0-9]+\b/g, (word, offset) => {
      const upper = word.toUpperCase();
      if (preservedAbbreviations.has(upper) || /^\d+[a-z]?$/.test(word)) return upper;
      if (offset > 0 && /^(?:at|and)$/.test(word)) return word;
      return word.charAt(0).toUpperCase() + word.slice(1);
    })
    .replace(/\b(Mc)([a-z])/g, (_, prefix, letter) => `${prefix}${letter.toUpperCase()}`);
}

const GRIDLY_HISTORICAL_LOCATION_FALLBACK_LABEL = "Location not specified";
const GRIDLY_HISTORICAL_SOURCE_ROAD_LOCATION_PATHS = Object.freeze([
  "roadName", "road_name", "roadLabel", "road_label", "roadTitle", "road_title",
  "primaryRoad", "primary_road", "referenceRoad", "reference_road", "nearestRoad", "nearest_road",
  "nearestRoadName", "nearest_road_name", "nearbyRoad", "nearby_road", "resolvedRoadName", "resolved_road_name",
  "displayRoad", "display_road", "displayRoadName", "display_road_name",
  "routeName", "route_name", "routeLabel", "route_label", "corridorName", "corridor_name",
  "location", "locationLabel", "location_label", "locationName", "location_name", "locationTitle", "location_title",
  "locationText", "location_text", "displayLocation", "display_location", "resolvedLocation", "resolved_location", "resolvedLocationLabel", "resolved_location_label",
  "localizedLocation", "localized_location", "localizedSpot", "localized_spot", "knownLocation", "known_location",
  "crossingName", "crossing_name", "crossingLabel", "crossing_label",
  "intersection", "street", "streetName", "street_name", "address"
]);
const GRIDLY_HISTORICAL_SOURCE_ROAD_LOCATION_NESTS = Object.freeze(["", "raw", "source", "original", "metadata", "properties"]);
const GRIDLY_HISTORICAL_TEXT_FALLBACK_LOCATION_PATHS = Object.freeze(["title", "description", "summary", "headline", "detail"]);
const GRIDLY_HISTORICAL_WEAK_LOCATION_TITLE_PATTERN = /^(?:flooding(?:\s+cleared)?|livestock\s+on\s+road|other\s+hazard(?:\s+cleared)?|road\s+hazard(?:\s+cleared)?|hazard(?:\s+cleared)?|road\s+pattern|road\s+issue|recurring\s+road\s+issue|community-reported\s+road\s+issue|drivers\s+previously\s+reported\s+this\s+road\s+issue|this\s+area|local\s+area|nearby\s+area|area|unknown\s+road|roadway|local\s+roadway|location\s+(?:details\s+)?unavailable|location\s+unknown|location\s+not\s+specified)$/i;

function gridlyHistoricalIntelligenceIsWeakLocationTitle(value = "") {
  return GRIDLY_HISTORICAL_WEAK_LOCATION_TITLE_PATTERN.test(String(value || "").replace(/\s+/g, " ").trim());
}

function gridlyHistoricalIntelligenceCleanLocationCandidate(value = "") {
  const text = safeDisplayText(value, "").replace(/\s+/g, " ").trim();
  if (!text) return "";
  if (gridlyHistoricalIntelligenceIsGenericOtherHazardLabel(text)) return "";
  if (gridlyHistoricalIntelligenceIsWeakLocationTitle(text)) return "";
  return text;
}

function gridlyHistoricalIntelligenceReadPath(source = {}, path = "") {
  if (!source || typeof source !== "object" || !path) return undefined;
  return path.split(".").reduce((current, key) => {
    if (current == null || typeof current !== "object") return undefined;
    return current[key];
  }, source);
}

function gridlyHistoricalIntelligenceLocationFromPaths(source = {}, paths = [], specificity = "specific") {
  for (const path of paths) {
    const cleaned = gridlyHistoricalIntelligenceCleanLocationCandidate(gridlyHistoricalIntelligenceReadPath(source, path));
    if (cleaned) return { label: cleaned, sourceField: path, specificity };
  }
  return null;
}

function gridlyHistoricalIntelligenceBuildNestedPaths(paths = []) {
  const output = [];
  GRIDLY_HISTORICAL_SOURCE_ROAD_LOCATION_NESTS.forEach((nest) => {
    paths.forEach((path) => output.push(nest ? `${nest}.${path}` : path));
  });
  return output;
}

function gridlyHistoricalIntelligenceExtractLocationFromText(value = "") {
  const text = safeDisplayText(value, "").replace(/\s+/g, " ").trim();
  if (!text) return "";
  const patterns = [
    /\b((?:US|FM|CR|SH|TX|IH|I)\s*[-#]?\s*\d+[A-Za-z]?(?:\s+(?:at|&|and)\s+[A-Z][A-Za-z0-9.' -]+(?:Street|St|Road|Rd|Avenue|Ave|Drive|Dr|Lane|Ln|Boulevard|Blvd|Way|Court|Ct))?)/i,
    /\b([A-Z][A-Za-z0-9.' -]+(?:Street|St|Road|Rd|Avenue|Ave|Drive|Dr|Lane|Ln|Boulevard|Blvd|Way|Court|Ct)\s+(?:&|and|at)\s+[A-Z][A-Za-z0-9.' -]+(?:Street|St|Road|Rd|Avenue|Ave|Drive|Dr|Lane|Ln|Boulevard|Blvd|Way|Court|Ct))\b/i,
    /\b(?:near|on|at)\s+([A-Z0-9][A-Za-z0-9.' -]+(?:Street|St|Road|Rd|Avenue|Ave|Drive|Dr|Lane|Ln|Boulevard|Blvd|Way|Court|Ct|FM\s*\d+|CR\s*\d+|US\s*\d+))\b/i
  ];
  for (const pattern of patterns) {
    const match = text.match(pattern);
    const cleaned = gridlyHistoricalIntelligenceCleanLocationCandidate(match?.[1] || "");
    if (cleaned) return cleaned;
  }
  return "";
}

function gridlyHistoricalIntelligenceSourceReportLocationCandidates(record = {}) {
  const directPaths = gridlyHistoricalIntelligenceBuildNestedPaths(GRIDLY_HISTORICAL_SOURCE_ROAD_LOCATION_PATHS);
  const candidates = [];
  directPaths.forEach((path) => {
    const label = gridlyHistoricalIntelligenceCleanLocationCandidate(gridlyHistoricalIntelligenceReadPath(record, path));
    if (label) candidates.push({ label, sourceField: path, specificity: "specific", sourceType: "source_report_field" });
  });
  const fallbackPaths = gridlyHistoricalIntelligenceBuildNestedPaths(GRIDLY_HISTORICAL_TEXT_FALLBACK_LOCATION_PATHS);
  fallbackPaths.forEach((path) => {
    const label = gridlyHistoricalIntelligenceExtractLocationFromText(gridlyHistoricalIntelligenceReadPath(record, path));
    if (label) candidates.push({ label, sourceField: path, specificity: "specific", sourceType: "text_fallback_extraction" });
  });
  return candidates;
}

function gridlyHistoricalIntelligenceMostCommonSourceLocationContext(records = []) {
  const counts = new Map();
  (Array.isArray(records) ? records : []).forEach((record, recordIndex) => {
    gridlyHistoricalIntelligenceSourceReportLocationCandidates(record).forEach((candidate) => {
      const normalized = gridlyHistoricalIntelligenceNormalizeLocationToken(candidate.label);
      if (!normalized) return;
      if (!counts.has(normalized)) {
        counts.set(normalized, {
          label: candidate.label,
          sourceField: candidate.sourceField,
          specificity: candidate.specificity || "specific",
          sourceType: candidate.sourceType || "source_report_field",
          count: 0,
          recordIndexes: []
        });
      }
      const entry = counts.get(normalized);
      entry.count += 1;
      entry.recordIndexes.push(recordIndex);
      if (String(candidate.sourceType) === "source_report_field" && String(entry.sourceType) !== "source_report_field") {
        entry.label = candidate.label;
        entry.sourceField = candidate.sourceField;
        entry.sourceType = candidate.sourceType;
      }
    });
  });
  return Array.from(counts.values()).sort((a, b) => {
    const sourcePriority = Number(b.sourceType === "source_report_field") - Number(a.sourceType === "source_report_field");
    return Number(b.count) - Number(a.count) || sourcePriority || String(a.label).localeCompare(String(b.label));
  })[0] || null;
}


function gridlyHistoricalIntelligencePrimitiveAuditValue(value) {
  if (value == null) return "";
  if (typeof value === "string" || typeof value === "number" || typeof value === "boolean") return safeDisplayText(value, "");
  return "";
}

function gridlyHistoricalIntelligenceAuditPathsWithNests(paths = []) {
  return gridlyHistoricalIntelligenceBuildNestedPaths(paths);
}

function gridlyHistoricalIntelligenceSourceReportKeySample(records = [], limit = 3) {
  return (Array.isArray(records) ? records : []).slice(0, limit).map((record, index) => ({
    recordIndex: index,
    keys: record && typeof record === "object" ? Object.keys(record).slice(0, 32) : []
  }));
}

function gridlyHistoricalIntelligenceSourceReportRoadFieldSample(records = [], limit = 3) {
  const paths = gridlyHistoricalIntelligenceAuditPathsWithNests(GRIDLY_HISTORICAL_SOURCE_ROAD_LOCATION_PATHS);
  const output = [];
  (Array.isArray(records) ? records : []).slice(0, limit).forEach((record, recordIndex) => {
    const fields = paths.map((path) => {
      const value = gridlyHistoricalIntelligencePrimitiveAuditValue(gridlyHistoricalIntelligenceReadPath(record, path));
      return value ? { field: path, value, recoveredByPresentationResolver: Boolean(gridlyHistoricalIntelligenceCleanLocationCandidate(value)) } : null;
    }).filter(Boolean).slice(0, 18);
    output.push({ recordIndex, fields });
  });
  return output;
}

function gridlyHistoricalIntelligenceSourceNestedKeySample(records = [], limit = 3) {
  const nestedKeys = ["raw", "source", "original", "metadata", "properties"];
  return (Array.isArray(records) ? records : []).slice(0, limit).map((record, recordIndex) => ({
    recordIndex,
    nested: nestedKeys.reduce((acc, key) => {
      const value = record?.[key];
      if (value && typeof value === "object" && !Array.isArray(value)) acc[key] = Object.keys(value).slice(0, 32);
      return acc;
    }, {})
  }));
}

function gridlyHistoricalIntelligenceRecordHasCoordinates(record = {}) {
  const coordinatePairs = [
    ["lat", "lng"], ["lat", "lon"], ["latitude", "longitude"], ["y", "x"],
    ["raw.lat", "raw.lng"], ["raw.lat", "raw.lon"], ["raw.latitude", "raw.longitude"],
    ["source.lat", "source.lng"], ["source.lat", "source.lon"], ["source.latitude", "source.longitude"],
    ["original.lat", "original.lng"], ["original.lat", "original.lon"], ["original.latitude", "original.longitude"],
    ["metadata.lat", "metadata.lng"], ["metadata.latitude", "metadata.longitude"],
    ["properties.lat", "properties.lng"], ["properties.latitude", "properties.longitude"]
  ];
  const hasNumericPair = coordinatePairs.some(([latPath, lngPath]) => {
    const lat = Number(gridlyHistoricalIntelligenceReadPath(record, latPath));
    const lng = Number(gridlyHistoricalIntelligenceReadPath(record, lngPath));
    return Number.isFinite(lat) && Number.isFinite(lng);
  });
  if (hasNumericPair) return true;
  const arrayPaths = ["coordinates", "coords", "location.coordinates", "raw.coordinates", "raw.coords", "raw.location.coordinates", "source.coordinates", "source.coords", "source.location.coordinates", "original.coordinates", "original.coords", "original.location.coordinates", "geometry.coordinates"];
  return arrayPaths.some((path) => {
    const value = gridlyHistoricalIntelligenceReadPath(record, path);
    return Array.isArray(value) && value.length >= 2 && Number.isFinite(Number(value[0])) && Number.isFinite(Number(value[1]));
  });
}

function gridlyHistoricalIntelligenceRecordsHaveCoordinates(records = []) {
  return (Array.isArray(records) ? records : []).some((record) => gridlyHistoricalIntelligenceRecordHasCoordinates(record));
}

function gridlyHistoricalIntelligenceSeedDemoLegacyAssessment(records = [], finding = {}) {
  const seedPattern = /seed|demo|fake|sample|test|mock|simulated|fixture/i;
  const legacyPattern = /legacy|migrated|old_schema|old-schema|schema[_ -]?v?1\b|historical[_ -]?v?1\b/i;
  const sourceText = [
    finding?.source,
    finding?.groupingKey,
    ...(Array.isArray(records) ? records : []).flatMap((record) => [
      record?.source, record?.sourceType, record?.source_type, record?.id, record?.reportId, record?.report_id,
      record?.incidentId, record?.incident_id, record?.historicalRecordId, record?.historical_record_id,
      record?.metadata?.source, record?.metadata?.seedSource, record?.metadata?.schemaVersion, record?.schemaVersion, record?.schema_version
    ])
  ].map((value) => String(value || "")).join(" ");
  const missingCurrentIds = (Array.isArray(records) ? records : []).some((record) => !(record?.reportId || record?.report_id || record?.incidentId || record?.incident_id || record?.id || record?.uuid));
  const hasRawSourceOriginal = (Array.isArray(records) ? records : []).some((record) => record?.raw || record?.source || record?.original);
  return {
    appearsSeededDemoLegacy: Boolean(seedPattern.test(sourceText) || legacyPattern.test(sourceText) || (missingCurrentIds && hasRawSourceOriginal)),
    seededOrDemo: seedPattern.test(sourceText),
    legacyLike: legacyPattern.test(sourceText) || (missingCurrentIds && hasRawSourceOriginal),
    evidence: [
      seedPattern.test(sourceText) ? "seed/demo/test marker found in source/id/metadata" : "",
      legacyPattern.test(sourceText) ? "legacy/schema marker found in source/id/metadata" : "",
      missingCurrentIds && hasRawSourceOriginal ? "raw/source/original nested payload without current report id" : ""
    ].filter(Boolean)
  };
}

function gridlyHistoricalIntelligenceWeakTitleReasons({ title = "", context = null, coordinatesExist = false, locationAvailableOnlyAsCoordinates = false, seededAssessment = null } = {}) {
  const normalized = safeDisplayText(title, "").replace(/\s+/g, " ").trim();
  const reasons = [];
  if (!normalized) reasons.push("final title is empty after rendering");
  if (normalized === GRIDLY_HISTORICAL_LOCATION_FALLBACK_LABEL) reasons.push("rendered fallback because no usable road/location text field was found");
  if (normalized && gridlyHistoricalIntelligenceIsWeakLocationTitle(normalized)) reasons.push("final title matches the generic/weak location-title pattern");
  if (!context) reasons.push("presentation resolver found no recognized source road/location alias");
  if (locationAvailableOnlyAsCoordinates) reasons.push("source report has coordinates but no road/location text; reverse geocoding is intentionally not attempted");
  else if (coordinatesExist) reasons.push("source report includes coordinates, but a text location was still unavailable or weak");
  if (seededAssessment?.appearsSeededDemoLegacy) reasons.push("row appears seeded/demo/legacy based on source/id/metadata shape");
  return Array.from(new Set(reasons));
}

function gridlyHistoricalIntelligenceBuildDataCleanupRecommendations({ weakRows = [], seededDataDetected = false, rowCount = 0 } = {}) {
  const coordinateOnlyCount = weakRows.filter((row) => row.locationAvailableOnlyAsCoordinates).length;
  const seededWeakCount = weakRows.filter((row) => row.appearsSeededDemoLegacy).length;
  const noTextLocationCount = weakRows.filter((row) => !row.sourceReportLocationResolved).length;
  return {
    clearTestSeedDataBeforeBeta: Boolean(seededDataDetected || seededWeakCount),
    shouldClearTestSeedDataBeforeBeta: Boolean(seededDataDetected || seededWeakCount),
    recommendation: (seededDataDetected || seededWeakCount)
      ? "Clear or quarantine test/seed/demo historical records before beta so weak historical rows do not look like product defects."
      : "No seed/demo marker was detected by this audit; keep monitoring weak rows and quarantine any non-production history before beta.",
    presentationScopeOnly: true,
    noStorageMutationPerformed: true,
    noReverseGeocodingRecommended: coordinateOnlyCount > 0,
    counts: {
      rowCount,
      weakRowCount: weakRows.length,
      coordinateOnlyWeakRowCount: coordinateOnlyCount,
      seededDemoLegacyWeakRowCount: seededWeakCount,
      weakRowsWithoutRecognizedTextLocationCount: noTextLocationCount
    },
    actions: [
      seededDataDetected || seededWeakCount ? "Delete or quarantine historical seed/demo/test records before beta validation." : "Keep production historical records; no seed/demo cleanup is currently proven by this audit.",
      coordinateOnlyCount ? "For coordinate-only legacy rows, collect a road/location label at report capture or run an offline data-cleanup job outside this presentation resolver; do not invent names in UI." : "No coordinate-only weak rows were detected in this render audit.",
      noTextLocationCount ? "Backfill missing road/location text from trusted original reports where available; leave Location not specified when no actual text field exists." : "Recognized source road/location text exists for all rendered rows."
    ]
  };
}

function gridlyHistoricalIntelligenceRecordLocationContext(record = {}) {
  const exactPaths = [
    "presentationLocationLabel", "locationLabel", "displayLocation", "resolvedLocationLabel", "localizedLocation", "localizedSpot", "locationName", "locationPhrase", "knownLocation",
    "raw.presentationLocationLabel", "raw.locationLabel", "raw.displayLocation", "raw.resolvedLocationLabel", "raw.localizedLocation", "raw.localizedSpot", "raw.locationName", "raw.locationPhrase", "raw.knownLocation",
    "source.presentationLocationLabel", "source.locationLabel", "source.displayLocation", "source.resolvedLocationLabel", "source.localizedLocation", "source.localizedSpot", "source.locationName", "source.locationPhrase", "source.knownLocation",
    "original.presentationLocationLabel", "original.locationLabel", "original.displayLocation", "original.resolvedLocationLabel", "original.localizedLocation", "original.localizedSpot", "original.locationName", "original.locationPhrase", "original.knownLocation"
  ];
  const roadPaths = [
    "referenceRoad", "reference_road", "roadName", "road", "resolvedRoadName", "primaryRoad", "routeName", "crossingName", "crossingLabel", "crossing", "intersection", "crossStreet", "cross_street", "nearestRoad", "nearestRoadName", "nearest_road", "street", "address",
    "raw.referenceRoad", "raw.reference_road", "raw.roadName", "raw.road", "raw.resolvedRoadName", "raw.primaryRoad", "raw.routeName", "raw.crossingName", "raw.crossingLabel", "raw.crossing", "raw.intersection", "raw.crossStreet", "raw.cross_street", "raw.nearestRoad", "raw.nearestRoadName", "raw.nearest_road", "raw.street", "raw.address",
    "source.referenceRoad", "source.reference_road", "source.roadName", "source.road", "source.resolvedRoadName", "source.primaryRoad", "source.routeName", "source.crossingName", "source.crossingLabel", "source.crossing", "source.intersection", "source.crossStreet", "source.cross_street", "source.nearestRoad", "source.nearestRoadName", "source.nearest_road", "source.street", "source.address",
    "original.referenceRoad", "original.reference_road", "original.roadName", "original.road", "original.resolvedRoadName", "original.primaryRoad", "original.routeName", "original.crossingName", "original.crossingLabel", "original.crossing", "original.intersection", "original.crossStreet", "original.cross_street", "original.nearestRoad", "original.nearestRoadName", "original.nearest_road", "original.street", "original.address"
  ];
  const localityPaths = [
    "locality", "town", "city", "place", "area",
    "raw.locality", "raw.town", "raw.city", "raw.place", "raw.area",
    "source.locality", "source.town", "source.city", "source.place", "source.area",
    "original.locality", "original.town", "original.city", "original.place", "original.area"
  ];
  return gridlyHistoricalIntelligenceLocationFromPaths(record, exactPaths, "specific")
    || gridlyHistoricalIntelligenceLocationFromPaths(record, roadPaths, "specific")
    || gridlyHistoricalIntelligenceLocationFromPaths(record, localityPaths, "locality")
    || null;
}

function gridlyHistoricalIntelligenceBestLocationContext(finding = {}) {
  const sourceReportContext = gridlyHistoricalIntelligenceMostCommonSourceLocationContext(finding.sourceRecords);
  if (sourceReportContext) return sourceReportContext;
  const findingContext = gridlyHistoricalIntelligenceRecordLocationContext(finding);
  if (findingContext) return findingContext;
  const recordContexts = (Array.isArray(finding.sourceRecords) ? finding.sourceRecords : [])
    .map((record) => gridlyHistoricalIntelligenceRecordLocationContext(record))
    .filter(Boolean);
  return recordContexts.find((context) => context.specificity === "specific") || recordContexts[0] || null;
}

function gridlyHistoricalIntelligenceFormatLocationLine(locationContext = null, hazardLabel = "") {
  const cleanedLocation = gridlyHistoricalIntelligenceCleanLocationCandidate(locationContext?.label || "");
  const cleanedHazard = safeDisplayText(hazardLabel, "");
  if (!cleanedLocation) return GRIDLY_HISTORICAL_LOCATION_FALLBACK_LABEL;
  const alreadyFormattedPresentation = locationContext?.sourceField === "presentationLocationLabel" && (
    /\b(?:near|on|at|between)\b/i.test(cleanedLocation)
    || (cleanedHazard && cleanedLocation.toLowerCase().includes(cleanedHazard.toLowerCase()))
  );
  if (alreadyFormattedPresentation) return cleanedLocation;
  const titledLocation = gridlyHistoricalIntelligenceTitleCaseLocation(cleanedLocation);
  const hasLeadingPreposition = /^(?:near|on|at|between)\b/i.test(titledLocation);
  const alreadyContextual = hasLeadingPreposition || (!cleanedHazard && /\s&\s|\sand\s/i.test(titledLocation));
  const locationPhrase = alreadyContextual ? titledLocation : `Near ${titledLocation}`;
  const hazardLocationPhrase = /^(?:near|on|at|between)\b/i.test(locationPhrase) ? `${locationPhrase.charAt(0).toLowerCase()}${locationPhrase.slice(1)}` : locationPhrase;
  return cleanedHazard ? `${cleanedHazard} ${hazardLocationPhrase}` : locationPhrase;
}

function gridlyHistoricalIntelligenceDisplayLocation(finding = {}) {
  return gridlyHistoricalIntelligenceFormatLocationLine(
    gridlyHistoricalIntelligenceBestLocationContext(finding),
    finding.hazardLabel
  );
}

function gridlyHistoricalIntelligenceCleanRowLocationTitle(value = "") {
  const cleaned = gridlyHistoricalIntelligenceCleanLocationCandidate(value);
  if (!cleaned) return "";
  const withoutLocationPrefix = cleaned.replace(/^(?:near|on|at)\s+/i, "").trim();
  return gridlyHistoricalIntelligenceCleanLocationCandidate(withoutLocationPrefix || cleaned) || cleaned;
}

function gridlyHistoricalIntelligenceRowLocationTitle(finding = {}) {
  const context = gridlyHistoricalIntelligenceBestLocationContext(finding);
  const directLocation = gridlyHistoricalIntelligenceCleanRowLocationTitle(context?.label || "");
  if (directLocation) return gridlyHistoricalIntelligenceTitleCaseLocation(directLocation);
  const displayLocation = gridlyHistoricalIntelligenceCleanRowLocationTitle(gridlyHistoricalIntelligenceFormatLocationLine(context, ""));
  return displayLocation ? gridlyHistoricalIntelligenceTitleCaseLocation(displayLocation) : GRIDLY_HISTORICAL_LOCATION_FALLBACK_LABEL;
}

function gridlyHistoricalIntelligencePatternSubtitle(finding = {}) {
  const hazard = safeDisplayText(finding.hazardLabel, "").toLowerCase();
  if (finding.category === "most_blocked_crossing") return "Frequently blocked crossing";
  if (finding.category === "recurring_flooding_location") return "Recurring flooding reported here";
  if (finding.category === "repeat_construction_zone") return "Recurring construction zone";
  if (finding.category === "high_delay_corridor") return "Common delay area";
  if (finding.category === "community_confirmed_hotspot") return "Community-confirmed hotspot";
  if (finding.category === "recurring_hazard") {
    if (hazard && !gridlyHistoricalIntelligenceIsGenericOtherHazardLabel(hazard)) return `Recurring ${hazard} reported here`;
    return "Recurring road issue reported here";
  }
  const language = getGridlyIntelligencePreviewLanguage(finding.category);
  return safeDisplayText(language.title || finding.title || "Historical pattern", "Historical pattern");
}


function gridlyHistoricalIntelligenceRecordTimestampMs(record = {}) {
  const value = typeof gridlyHistoricalAuditTimestamp === "function"
    ? gridlyHistoricalAuditTimestamp(record)
    : (record?.createdAt || record?.created_at || record?.timestamp || record?.reportedAt || record?.reported_at || null);
  const ms = new Date(value || 0).getTime();
  return Number.isFinite(ms) && ms > 0 ? ms : null;
}

function gridlyHistoricalIntelligenceHourLabel(hour) {
  const value = Number(hour);
  if (!Number.isFinite(value)) return "";
  const normalized = ((Math.round(value) % 24) + 24) % 24;
  if (normalized === 0) return "12 AM";
  if (normalized === 12) return "12 PM";
  return `${normalized % 12} ${normalized < 12 ? "AM" : "PM"}`;
}

function gridlyHistoricalIntelligencePeakWindowLabel(records = []) {
  const buckets = new Map();
  (Array.isArray(records) ? records : []).forEach((record) => {
    const ms = gridlyHistoricalIntelligenceRecordTimestampMs(record);
    if (!ms) return;
    const hour = new Date(ms).getHours();
    buckets.set(hour, (buckets.get(hour) || 0) + 1);
  });
  if (!buckets.size) return "";
  const [peakHour] = Array.from(buckets.entries()).sort((a, b) => b[1] - a[1] || a[0] - b[0])[0] || [];
  if (!Number.isFinite(Number(peakHour))) return "";
  const endHour = (Number(peakHour) + 2) % 24;
  return `${gridlyHistoricalIntelligenceHourLabel(peakHour)} – ${gridlyHistoricalIntelligenceHourLabel(endHour)}`;
}

function gridlyHistoricalIntelligenceCommunityMemberEstimate(records = []) {
  const contributorIds = new Set();
  let explicitMax = 0;
  (Array.isArray(records) ? records : []).forEach((record) => {
    [record?.userId, record?.user_id, record?.reporterId, record?.reporter_id, record?.contributorId, record?.contributor_id, record?.deviceId, record?.device_id]
      .filter(Boolean)
      .forEach((id) => contributorIds.add(String(id)));
    const explicit = Number(record?.uniqueContributorCount ?? record?.contributorCount ?? record?.contributors ?? record?.reporterCount ?? record?.reporter_count ?? record?.distinctReporters);
    if (Number.isFinite(explicit) && explicit > explicitMax) explicitMax = explicit;
  });
  return Math.max(contributorIds.size, Math.round(explicitMax));
}

function gridlyHistoricalIntelligenceDurationNoun(category = "") {
  return category === "most_blocked_crossing" || category === "high_delay_corridor" ? "delay" : "clear time";
}

function gridlyHistoricalIntelligenceImpactLabel(category = "", minutes = null) {
  const duration = formatGridlyHistoricalIntelligenceDuration(minutes);
  if (!duration) return "";
  return gridlyHistoricalIntelligenceDurationNoun(category) === "delay" ? `Typical delay ${duration}` : `Usually clears in ${duration}`;
}

function gridlyHistoricalIntelligenceSummaryLine(finding = {}) {
  const pieces = [];
  if (finding.peakWindowLabel) pieces.push(`Most reported ${finding.peakWindowLabel}`);
  const impact = gridlyHistoricalIntelligenceImpactLabel(finding.category, finding.averageDurationMinutes);
  if (impact) pieces.push(impact);
  if (!pieces.length && Number(finding.count || 0) > 0) pieces.push(`${Number(finding.count || 0)} community ${Number(finding.count || 0) === 1 ? "report" : "reports"}`);
  if (pieces.length < 2 && Number(finding.confirmationCount || 0) > 0) pieces.push("Reported by community members");
  return pieces.slice(0, 2).join(" · ");
}

function gridlyHistoricalIntelligenceSupportingCopy(finding = {}) {
  const language = getGridlyIntelligencePreviewLanguage(finding.category);
  if (finding.category === "most_blocked_crossing") return "Drivers have repeatedly reported train delays at this crossing.";
  if (finding.category === "recurring_flooding_location") return "Drivers have repeatedly reported flooding at this recurring location.";
  if (finding.category === "community_confirmed_hotspot") return "Community activity has been reported here more than once.";
  if (finding.category === "recurring_hazard" && finding.genericClearedHazard) return "Drivers previously reported this road issue.";
  if (finding.category === "recurring_hazard" && finding.genericRoadIssue) return "Community-reported road issue.";
  return typeof language.description === "function" ? language.description(finding) : "Drivers have repeatedly reported activity here.";
}

