function gridlyLp0543ExtractDurationFromPatternNode(root) {
  const node = root?.querySelector?.('[data-gridly-history-pattern-statement="duration"]');
  const text = safeDisplayText(node?.textContent || "", "");
  const match = text.match(/^It usually clears within ((?:about )?(?:\d+ minute|\d+ minutes|\d+ hour|\d+ hours)(?: \d+ minutes?|))\.$/i);
  if (!match) return { text: "", minutes: null, nodeFound: Boolean(node) };
  const durationText = safeDisplayText(match[1], "");
  let minutes = null;
  const hourMatch = durationText.match(/(?:about )?(\d+) hours?/i);
  const minuteMatch = durationText.match(/(?:^| )(\d+) minutes?$/i);
  if (hourMatch) minutes = Number(hourMatch[1]) * 60 + (minuteMatch ? Number(minuteMatch[1]) : 0);
  else if (minuteMatch) minutes = Number(minuteMatch[1]);
  if (/\b1 minutes\b/i.test(durationText)) minutes = null;
  return { text: durationText, minutes: Number.isFinite(minutes) ? minutes : null, nodeFound: true };
}

