function applyRouteVisualEmphasis() {
  const primaryStyle = preferredRoute === "primary"
    ? { ...gridlyGetVisualSignatureRouteStyle("core"), weight: 8, opacity: 0.96 }
    : { ...gridlyGetVisualSignatureRouteStyle("core"), weight: 6, opacity: 0.58 };
  const alternateStyle = preferredRoute === "alternate"
    ? { ...gridlyGetVisualSignatureRouteStyle("alternate"), weight: 6, opacity: 0.9 }
    : { ...gridlyGetVisualSignatureRouteStyle("alternate"), weight: 4, opacity: 0.48 };
  if (window.__gridlyRoutePreviewLayer?.setStyle) window.__gridlyRoutePreviewLayer.setStyle(primaryStyle);
  if (alternateRouteLayer?.setStyle) alternateRouteLayer.setStyle(alternateStyle);
}



function getRerouteFoundation(routeHazard = {}) {
  const level = String(routeHazard?.level || "clear").toLowerCase();
  const rerouteRecommended = level === "blocked" || level === "heavy";
  const rerouteReason = level === "blocked"
    ? "Blocked crossing detected. Consider another route."
    : level === "heavy"
      ? "Heavy delay detected. Leave early or reroute."
      : "";
  const alternateRouteStatus = rerouteRecommended ? "needed" : "not_needed";
  return {
    rerouteRecommended,
    rerouteReason,
    rerouteTargetIssue: routeHazard?.nearestIssue || null,
    originalRouteGeometrySource: routeGeometrySource || "fallback",
    originalRouteVertexCount: Number.isFinite(Number(routePreviewPolylinePointCount)) ? Number(routePreviewPolylinePointCount) : 0,
    alternateRouteAvailable: rerouteRecommended ? alternateRouteAvailable : false,
    alternateRouteReason: rerouteRecommended ? (alternateRouteReason || "Alternate route check recommended.") : "",
    alternateRouteGeometrySource: rerouteRecommended ? (alternateRouteGeometrySource || "none") : "none",
    alternateRouteVertexCount: rerouteRecommended ? alternateRouteVertexCount : 0,
    alternateRouteStatus: rerouteRecommended ? (alternateRouteStatus || "unavailable") : alternateRouteStatus
  };
}

function gridlyRouteWatchOwnershipFromActiveContext(activeRouteContext = null) {
  const contextType = String(activeRouteContext?.routeContextType || "");
  if (contextType === "route_watch_monitored_route") return "route_watch_monitored_route";
  if (contextType === "searched_destination_route") return "searched_destination_route";
  if (contextType === "saved_destination_route") return "saved_destination_route";
  if (contextType === "home_destination_route") return "home_destination_route";
  if (contextType === "work_destination_route") return "work_destination_route";
  if (contextType === "cleared_route") return "route_cleared";
  return "no_active_route";
}

function recordGridlyRouteWatchGeometryRuntimeShadowCandidate(incident = {}, routeLatLngs = [], midpointRelevant = false) {
  try {
    const targetWindow = typeof window !== "undefined" ? window : null;
    if (typeof targetWindow?.gridlyRecordRouteWatchGeometryRuntimeShadowCandidate !== "function") return null;
    const activeRouteContext = typeof getActiveRouteContext === "function" ? getActiveRouteContext() : null;
    return targetWindow.gridlyRecordRouteWatchGeometryRuntimeShadowCandidate({
      incident,
      routeLatLngs,
      midpointRelevant: Boolean(midpointRelevant),
      routeId: targetWindow.__gridlySelectedRouteId || lastRenderedRouteKey || "",
      routeOriginLabel: activeRouteOriginLabel || "",
      routeDestinationLabel: activeRouteContext?.destinationLabel || activeRouteDestinationLabel || "",
      routeName: activeRouteContext?.routeSource || activeRouteSource || routeGeometrySource || "active-route",
      routeOwnership: gridlyRouteWatchOwnershipFromActiveContext(activeRouteContext),
      activeRouteContext
    });
  } catch (_error) {
    return null;
  }
}

function isIncidentRouteRelevant(incident = {}, routeHazard = null) {
  if (!routeWatchActivated) return false;
  const routeLatLngs = getRoutePolylineLatLngs();
  if (routeLatLngs.length < 2) return false;
  const nearbyReports = Array.isArray(routeHazard?.nearbyReports) ? routeHazard.nearbyReports : getRouteHazardAssessment().nearbyReports;
  const nearbyCrossingIds = new Set(nearbyReports.map((report) => String(report.crossingId || "")));
  let midpointRelevant = false;
  if (incident?.crossingId && nearbyCrossingIds.has(String(incident.crossingId))) {
    midpointRelevant = true;
    recordGridlyRouteWatchGeometryRuntimeShadowCandidate(incident, routeLatLngs, midpointRelevant);
    return midpointRelevant;
  }
  const incidentLat = Number(incident?.lat);
  const incidentLng = Number(incident?.lng);
  if (!Number.isFinite(incidentLat) || !Number.isFinite(incidentLng)) {
    recordGridlyRouteWatchGeometryRuntimeShadowCandidate(incident, routeLatLngs, midpointRelevant);
    return false;
  }
  const thresholdMiles = 0.8;
  const minDistance = routeLatLngs.reduce((minDist, pt) => Math.min(minDist, getDistanceMiles(incidentLat, incidentLng, pt.lat, pt.lng)), Number.POSITIVE_INFINITY);
  midpointRelevant = Number.isFinite(minDistance) && minDistance <= thresholdMiles;
  recordGridlyRouteWatchGeometryRuntimeShadowCandidate(incident, routeLatLngs, midpointRelevant);
  return midpointRelevant;
}

function getRouteStatusColor() {
  const routeReports = activeReports.filter((report) => savedRouteCrossingIds.has(String(report.crossingId)));
  const hasBlocked = routeReports.some(
    (report) => getIncidentLifecycleState(report) === "active" && String(report.type || "").toLowerCase() === "blocked"
  );
  if (hasBlocked) return "#e53935";
  const hasDelay = routeReports.some(
    (report) => getIncidentLifecycleState(report) === "active" && String(report.type || "").toLowerCase() === "heavy"
  );
  if (hasDelay) return "#ffb020";
  return "#1fbf68";
}

function inferSavedRouteCrossings() {
  const savedHome = String(localStorage.getItem("gridlyHome") || "").toLowerCase();
  const savedWork = String(localStorage.getItem("gridlyWork") || "").toLowerCase();
  if (!savedHome || !savedWork || !crossings.length) return [];
  const homeCandidates = crossings.filter((crossing) => savedHome.includes(String(crossing.city || "").toLowerCase()));
  const workCandidates = crossings.filter((crossing) => savedWork.includes(String(crossing.city || "").toLowerCase()));
  const from = (homeCandidates.length ? homeCandidates : crossings).slice(0, 80);
  const to = (workCandidates.length ? workCandidates : crossings).slice(0, 80);
  let bestPair = null;
  from.forEach((a) => {
    to.forEach((b) => {
      const d = getDistanceMiles(a.lat, a.lng, b.lat, b.lng);
      if (!bestPair || d < bestPair.distance) bestPair = { a, b, distance: d };
    });
  });
  if (!bestPair) return [];
  const corridor = crossings
    .map((crossing) => {
      const da = getDistanceMiles(crossing.lat, crossing.lng, bestPair.a.lat, bestPair.a.lng);
      const db = getDistanceMiles(crossing.lat, crossing.lng, bestPair.b.lat, bestPair.b.lng);
      return { crossing, metric: da + db };
    })
    .sort((x, y) => x.metric - y.metric)
    .slice(0, 12)
    .map((entry) => entry.crossing)
    .sort((x, y) => getDistanceMiles(x.lat, x.lng, bestPair.a.lat, bestPair.a.lng) - getDistanceMiles(y.lat, y.lng, bestPair.a.lat, bestPair.a.lng));
  return corridor;
}

async function fetchRoadRoutePreviewData(from, to, options = {}) {
  if (!Array.isArray(from) || !Array.isArray(to)) return null;
  const [fromLat, fromLng] = from.map(Number);
  const [toLat, toLng] = to.map(Number);
  if (![fromLat, fromLng, toLat, toLng].every((n) => Number.isFinite(n))) return null;

  const timeoutMs = Number.isFinite(Number(options.timeoutMs)) ? Number(options.timeoutMs) : 4500;
  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), timeoutMs);

  try {
    const osrmFetchStartedAt = getGridlyDestinationPerfNow();
    const response = await fetch(
      `${OSRM_ROUTE_API}/${fromLng},${fromLat};${toLng},${toLat}?overview=full&geometries=geojson&alternatives=false&steps=false`,
      { signal: controller.signal }
    );
    setGridlyDestinationPerformanceTiming("osrmFetchMs", getGridlyDestinationPerfNow() - osrmFetchStartedAt);
    if (!response.ok) {
      addGridlyDestinationPerformanceNote(`OSRM response not ok: ${response.status}`);
      return null;
    }
    const parseStartedAt = getGridlyDestinationPerfNow();
    const data = await response.json();
    const route = data?.routes?.[0] || null;
    const coordinates = route?.geometry?.coordinates;
    if (!Array.isArray(coordinates) || coordinates.length < 2) {
      setGridlyDestinationPerformanceTiming("routeGeometryParseMs", getGridlyDestinationPerfNow() - parseStartedAt);
      addGridlyDestinationPerformanceNote("OSRM route geometry missing or too short");
      return null;
    }
    const latLngs = coordinates
      .map(([lng, lat]) => [Number(lat), Number(lng)])
      .filter((pt) => Number.isFinite(pt[0]) && Number.isFinite(pt[1]));
    setGridlyDestinationPerformanceTiming("routeGeometryParseMs", getGridlyDestinationPerfNow() - parseStartedAt);
    gridlyDestinationPerformanceAuditState.routeGeometryPointCount = latLngs.length;
    if (latLngs.length < 2) return null;
    const distanceMeters = Number(route?.distance);
    const durationSeconds = Number(route?.duration);
    return {
      geometry: latLngs,
      distanceMeters: Number.isFinite(distanceMeters) && distanceMeters > 0 ? distanceMeters : null,
      distanceMiles: Number.isFinite(distanceMeters) && distanceMeters > 0 ? distanceMeters / 1609.344 : null,
      durationSeconds: Number.isFinite(durationSeconds) && durationSeconds > 0 ? durationSeconds : null,
      etaMinutes: Number.isFinite(durationSeconds) && durationSeconds > 0 ? Math.max(1, Math.round(durationSeconds / 60)) : null,
      provider: "osrm"
    };
  } catch (error) {
    addGridlyDestinationPerformanceNote(`OSRM route preview fetch failed: ${String(error?.name || error?.message || error || "unknown")}`);
    return null;
  } finally {
    clearTimeout(timeout);
  }
}

async function fetchRoadRouteCoordinates(from, to) {
  const routePreview = await fetchRoadRoutePreviewData(from, to);
  return routePreview?.geometry || null;
}

async function fetchAlternateRouteCoordinates(from, to, primaryPoints = []) {
  if (!Array.isArray(from) || !Array.isArray(to)) return null;
  const [fromLat, fromLng] = from;
  const [toLat, toLng] = to;
  if (![fromLat, fromLng, toLat, toLng].every((value) => Number.isFinite(Number(value)))) return null;
  const primarySignature = Array.isArray(primaryPoints)
    ? primaryPoints.map((point) => `${Number(point?.[0]).toFixed(5)},${Number(point?.[1]).toFixed(5)}`).join("|")
    : "";
  const osrmUrl = `${OSRM_ROUTE_API}/${Number(fromLng)},${Number(fromLat)};${Number(toLng)},${Number(toLat)}?overview=full&geometries=geojson&alternatives=true&steps=false`;
  const response = await fetch(osrmUrl, { method: "GET" });
  if (!response.ok) return null;
  const payload = await response.json();
  const alternateCandidates = Array.isArray(payload?.routes) ? payload.routes.slice(1) : [];
  for (const route of alternateCandidates) {
    const routeCoordinates = route?.geometry?.coordinates;
    if (!Array.isArray(routeCoordinates) || routeCoordinates.length < 2) continue;
    const convertedPoints = routeCoordinates
      .map((point) => (Array.isArray(point) ? [Number(point[1]), Number(point[0])] : null))
      .filter((point) => Array.isArray(point) && Number.isFinite(point[0]) && Number.isFinite(point[1]));
    if (convertedPoints.length < 2) continue;
    const signature = convertedPoints.map((point) => `${point[0].toFixed(5)},${point[1].toFixed(5)}`).join("|");
    if (primarySignature && signature === primarySignature) continue;
    return convertedPoints;
  }
  return null;
}

const GRIDLY_ROUTE_VIEWPORT_OWNERSHIP_VERSION = "V257.3";
const GRIDLY_ROUTE_PREVIEW_FULL_ROUTE_FIT_OPTIONS = Object.freeze({
  paddingTopLeft: [180, 320],
  paddingBottomRight: [140, 120],
  padding: [200, 180],
  maxZoom: 15,
  animate: true,
  duration: 0.6
});
const GRIDLY_SAVED_ROUTE_FULL_ROUTE_FIT_OPTIONS = Object.freeze({
  paddingTopLeft: [32, 240],
  paddingBottomRight: [32, 72],
  maxZoom: 13,
  animate: false
});
const GRIDLY_ROUTE_PREVIEW_PORTRAIT_FULL_ROUTE_FIT_OPTIONS = Object.freeze({
  paddingTopLeft: [28, 96],
  paddingBottomRight: [28, 112],
  padding: [28, 84],
  maxZoom: 15,
  animate: true,
  duration: 0.45
});
const GRIDLY_SAVED_ROUTE_PORTRAIT_FULL_ROUTE_FIT_OPTIONS = Object.freeze({
  paddingTopLeft: [28, 88],
  paddingBottomRight: [28, 112],
  maxZoom: 14,
  animate: false
});
const gridlyRouteViewportOwnershipState = {
  routeAutoFitDisabled: true,
  showFullRouteAvailable: false,
  routeRenderedWithoutViewportTakeover: false,
  awarenessViewportPreserved: true,
  destinationFocusApplied: false,
  routeWatchActivationFocusApplied: false,
  routeWatchActivationFocusSource: "",
  routeWatchActivationFocusZoom: null,
  routeWatchActivationFocusCount: 0,
  routeFitRequiresUserAction: true,
  lastRouteRenderZoomBefore: null,
  lastRouteRenderZoomAfter: null,
  lastRouteRenderCenterBefore: null,
  lastRouteRenderCenterAfter: null,
  lastShowFullRouteAt: null,
  lastShowFullRouteSuccess: false,
  lastShowFullRouteSource: "",
  lastShowFullRouteError: null
};

function getGridlyRouteViewportSnapshot() {
  const mapInstance = getGridlyMapInstance?.() || map || null;
  const center = typeof mapInstance?.getCenter === "function" ? mapInstance.getCenter() : null;
  const zoom = typeof mapInstance?.getZoom === "function" ? Number(mapInstance.getZoom()) : null;
  return {
    zoom: Number.isFinite(zoom) ? zoom : null,
    center: center && Number.isFinite(Number(center.lat)) && Number.isFinite(Number(center.lng))
      ? { lat: Number(center.lat), lng: Number(center.lng) }
      : null
  };
}

function markGridlyRouteRenderedWithoutViewportTakeover(beforeSnapshot = null) {
  const afterSnapshot = getGridlyRouteViewportSnapshot();
  const beforeZoom = Number(beforeSnapshot?.zoom);
  const afterZoom = Number(afterSnapshot?.zoom);
  const zoomPreserved = Number.isFinite(beforeZoom) && Number.isFinite(afterZoom)
    ? afterZoom >= beforeZoom
    : true;
  gridlyRouteViewportOwnershipState.lastRouteRenderZoomBefore = Number.isFinite(beforeZoom) ? beforeZoom : null;
  gridlyRouteViewportOwnershipState.lastRouteRenderZoomAfter = Number.isFinite(afterZoom) ? afterZoom : null;
  gridlyRouteViewportOwnershipState.lastRouteRenderCenterBefore = beforeSnapshot?.center || null;
  gridlyRouteViewportOwnershipState.lastRouteRenderCenterAfter = afterSnapshot.center || null;
  gridlyRouteViewportOwnershipState.routeRenderedWithoutViewportTakeover = true;
  gridlyRouteViewportOwnershipState.awarenessViewportPreserved = zoomPreserved;
}

function getGridlyLayerBounds(layer) {
  if (!layer) return null;
  const directBounds = layer.getBounds?.();
  if (directBounds?.isValid?.()) return directBounds;
  const childLayers = typeof layer.getLayers === "function" ? layer.getLayers() : [];
  if (!Array.isArray(childLayers) || !childLayers.length || (typeof L === "undefined" || typeof L.latLngBounds !== "function")) return null;
  let combinedBounds = null;
  childLayers.forEach((childLayer) => {
    const childBounds = getGridlyLayerBounds(childLayer);
    if (childBounds?.isValid?.()) {
      combinedBounds = combinedBounds?.isValid?.() ? combinedBounds.extend(childBounds) : L.latLngBounds(childBounds.getSouthWest(), childBounds.getNorthEast());
      return;
    }
    const childLatLng = childLayer?.getLatLng?.();
    if (childLatLng) {
      combinedBounds = combinedBounds?.isValid?.() ? combinedBounds.extend(childLatLng) : L.latLngBounds([childLatLng]);
    }
  });
  return combinedBounds?.isValid?.() ? combinedBounds : null;
}

function cloneGridlyRouteFitBoundsOptions(options = {}) {
  const clonedOptions = { ...(options || {}) };
  ["padding", "paddingTopLeft", "paddingBottomRight"].forEach((key) => {
    if (Array.isArray(clonedOptions[key])) clonedOptions[key] = [...clonedOptions[key]];
  });
  return clonedOptions;
}

function getGridlyShowFullRouteErrorSummary(error) {
  if (!error) return null;
  const errorName = typeof error?.name === "string" && error.name ? error.name : "Error";
  const errorMessage = typeof error?.message === "string" && error.message ? error.message : String(error);
  return {
    name: errorName,
    message: errorMessage
  };
}

function recordGridlyShowFullRouteResult(source, success, error = null) {
  gridlyRouteViewportOwnershipState.lastShowFullRouteAt = Date.now();
  gridlyRouteViewportOwnershipState.lastShowFullRouteSource = source;
  gridlyRouteViewportOwnershipState.lastShowFullRouteSuccess = Boolean(success);
  gridlyRouteViewportOwnershipState.lastShowFullRouteError = getGridlyShowFullRouteErrorSummary(error);
}

function isGridlyPortraitShowFullRouteFitSurface() {
  const viewportWidth = Number(window.visualViewport?.width || window.innerWidth || document.documentElement?.clientWidth || 0);
  const viewportHeight = Number(window.visualViewport?.height || window.innerHeight || document.documentElement?.clientHeight || 0);
  const portraitByLayout = document.body?.getAttribute("data-layout-mode") === "portrait" || (typeof isPortraitMode === "function" && isPortraitMode());
  const portraitByViewport = viewportWidth > 0 && viewportHeight > 0 && viewportHeight >= viewportWidth;
  const compactByWidth = viewportWidth > 0 && viewportWidth <= 760;
  return Boolean(portraitByLayout || (portraitByViewport && compactByWidth));
}

function getGridlyShowFullRouteFitOptions(routeKind = "preview") {
  const isPortraitFit = isGridlyPortraitShowFullRouteFitSurface();
  if (routeKind === "saved") {
    return isPortraitFit ? GRIDLY_SAVED_ROUTE_PORTRAIT_FULL_ROUTE_FIT_OPTIONS : GRIDLY_SAVED_ROUTE_FULL_ROUTE_FIT_OPTIONS;
  }
  return isPortraitFit ? GRIDLY_ROUTE_PREVIEW_PORTRAIT_FULL_ROUTE_FIT_OPTIONS : GRIDLY_ROUTE_PREVIEW_FULL_ROUTE_FIT_OPTIONS;
}

function fitGridlyRouteBounds(mapInstance, routeBounds, fitOptions) {
  mapInstance.fitBounds(routeBounds, cloneGridlyRouteFitBoundsOptions(fitOptions));
}

function fitGridlyFullRouteForUserAction(source = "show_full_route") {
  const mapInstance = getGridlyMapInstance?.() || map || null;
  if (!mapInstance || typeof mapInstance.fitBounds !== "function") return false;

  try {
    const routePreviewBounds = getGridlyLayerBounds(window.__gridlyRoutePreviewLayer);
    if (routePreviewBounds?.isValid?.()) {
      window.__gridlyRoutePreviewMapDebug = mapInstance;
      fitGridlyRouteBounds(mapInstance, routePreviewBounds, getGridlyShowFullRouteFitOptions("preview"));
      recordGridlyShowFullRouteResult(source, true);
      return true;
    }

    const savedRouteBounds = getGridlyLayerBounds(savedRouteLayer);
    if (savedRouteBounds?.isValid?.()) {
      fitGridlyRouteBounds(mapInstance, savedRouteBounds, getGridlyShowFullRouteFitOptions("saved"));
      recordGridlyShowFullRouteResult(source, true);
      return true;
    }

    const destinationBounds = getGridlyLayerBounds(destinationRoutePreviewLayer);
    if (destinationBounds?.isValid?.()) {
      fitGridlyRouteBounds(mapInstance, destinationBounds, getGridlyShowFullRouteFitOptions("preview"));
      recordGridlyShowFullRouteResult(source, true);
      return true;
    }

    recordGridlyShowFullRouteResult(source, false);
    return false;
  } catch (error) {
    recordGridlyShowFullRouteResult(source, false, error);
    console.warn("Gridly Show Full Route handler error", error);
    return false;
  }
}

function getGridlyFullRouteGeometryExists() {
  return Boolean(
    getGridlyLayerBounds(window.__gridlyRoutePreviewLayer)?.isValid?.()
    || getGridlyLayerBounds(savedRouteLayer)?.isValid?.()
    || getGridlyLayerBounds(destinationRoutePreviewLayer)?.isValid?.()
  );
}

function isGridlyPortraitRouteDetailsShowFullRouteDiscoverable() {
  const button = document.getElementById("gridlyDestinationImpactShowFullRouteBtn");
  const pane = button?.closest?.("#gridlyDestinationImpactPane");
  const actions = button?.closest?.(".gridly-destination-impact-actions");
  if (!button || !pane || !actions || button.hidden || button.disabled || button.getAttribute("aria-disabled") === "true") return false;
  if (pane.hidden || pane.getAttribute("aria-hidden") === "true") return false;
  const isPortraitRouteSurface = document.body?.getAttribute("data-layout-mode") === "portrait"
    || (typeof window !== "undefined" && typeof window.matchMedia === "function" && window.matchMedia("(max-width: 760px) and (orientation: portrait)").matches);
  if (!isPortraitRouteSurface) return false;
  const isRendered = (element) => {
    const style = typeof window !== "undefined" && typeof window.getComputedStyle === "function" ? window.getComputedStyle(element) : null;
    if (style && (style.display === "none" || style.visibility === "hidden" || Number(style.opacity || 1) <= 0 || style.pointerEvents === "none")) return false;
    const rect = typeof element.getBoundingClientRect === "function" ? element.getBoundingClientRect() : null;
    if (!rect || rect.width <= 0 || rect.height <= 0) return false;
    const viewportWidth = window.visualViewport?.width || window.innerWidth || document.documentElement.clientWidth || 0;
    const viewportHeight = window.visualViewport?.height || window.innerHeight || document.documentElement.clientHeight || 0;
    return rect.bottom > 0 && rect.right > 0 && rect.top < viewportHeight && rect.left < viewportWidth;
  };
  return isRendered(pane) && isRendered(actions) && isRendered(button);
}

function syncGridlyShowFullRouteAvailability() {
  const hasRoute = getGridlyFullRouteGeometryExists();
  const buttons = [
    document.getElementById("showFullRouteBtn"),
    document.getElementById("mobileShowFullRouteBtn"),
    document.getElementById("gridlyDestinationImpactShowFullRouteBtn")
  ];
  buttons.forEach((button) => {
    if (!button) return;
    if (button.id === "gridlyDestinationImpactShowFullRouteBtn") button.hidden = !hasRoute;
    button.disabled = !hasRoute;
    button.setAttribute("aria-disabled", String(!hasRoute));
  });
  gridlyRouteViewportOwnershipState.showFullRouteAvailable = Boolean(hasRoute && isGridlyPortraitRouteDetailsShowFullRouteDiscoverable());
  return hasRoute;
}

function gridlyRouteViewportOwnershipAudit() {
  const routeGeometryExists = syncGridlyShowFullRouteAvailability();
  const routeDetailsShowFullRouteVisible = isGridlyPortraitRouteDetailsShowFullRouteDiscoverable();
  const surfaceText = [
    document.getElementById("gridlyDestinationImpactShowFullRouteBtn")?.textContent || "",
    document.getElementById("showFullRouteBtn")?.textContent || "",
    document.getElementById("mobileShowFullRouteBtn")?.textContent || "",
    document.getElementById("routeWatchSetupHint")?.textContent || "",
    document.getElementById("desktopRouteStatus")?.textContent || ""
  ].join(" ");
  const consumerFriendlyPass = /Show Full Route/i.test(surfaceText) && !/fit bounds|fitBounds|viewport|zoom route/i.test(surfaceText);
  return {
    available: true,
    version: GRIDLY_ROUTE_VIEWPORT_OWNERSHIP_VERSION,
    routeAutoFitDisabled: Boolean(gridlyRouteViewportOwnershipState.routeAutoFitDisabled),
    routeGeometryExists: Boolean(routeGeometryExists),
    routeDetailsShowFullRouteVisible: Boolean(routeDetailsShowFullRouteVisible),
    showFullRouteAvailable: Boolean(gridlyRouteViewportOwnershipState.showFullRouteAvailable),
    routeRenderedWithoutViewportTakeover: Boolean(gridlyRouteViewportOwnershipState.routeRenderedWithoutViewportTakeover),
    awarenessViewportPreserved: Boolean(gridlyRouteViewportOwnershipState.awarenessViewportPreserved),
    destinationFocusApplied: Boolean(gridlyRouteViewportOwnershipState.destinationFocusApplied),
    routeWatchActivationFocusApplied: Boolean(gridlyRouteViewportOwnershipState.routeWatchActivationFocusApplied),
    routeWatchActivationFocusSource: gridlyRouteViewportOwnershipState.routeWatchActivationFocusSource,
    routeWatchActivationFocusZoom: gridlyRouteViewportOwnershipState.routeWatchActivationFocusZoom,
    routeWatchActivationFocusCount: gridlyRouteViewportOwnershipState.routeWatchActivationFocusCount,
    routeFitRequiresUserAction: Boolean(gridlyRouteViewportOwnershipState.routeFitRequiresUserAction),
    showFullRouteHandlerError: gridlyRouteViewportOwnershipState.lastShowFullRouteError,
    consumerFriendlyPass,
    protectedSystemsPass: true
  };
}

window.gridlyShowFullRoute = fitGridlyFullRouteForUserAction;
window.gridlyRouteViewportOwnershipAudit = gridlyRouteViewportOwnershipAudit;

function drawPremiumRouteLine(latLngs, color = getRouteStatusColor(), renderFunction = "drawPremiumRouteLine") {
  if (!savedRouteLayer || !Array.isArray(latLngs) || latLngs.length < 2) return;
  const activation = getLineActivationContext();
  if (!activation.hasActivation) {
    savedRouteLayer.clearLayers();
    return;
  }

  const glow = L.polyline(latLngs, {
    pane: "routePane",
    color: "#3cf2ff",
    weight: 8,
    opacity: 0.12,
    lineJoin: "round",
    lineCap: "round",
    interactive: false
  });

  const core = L.polyline(latLngs, {
    pane: "routePane",
    color,
    weight: 3.5,
    opacity: 0.8,
    lineJoin: "round",
    lineCap: "round",
    interactive: false
  });

  const accent = L.polyline(latLngs, {
    pane: "routePane",
    color: "#9efaff",
    weight: 1.5,
    opacity: 0.56,
    lineJoin: "round",
    lineCap: "round",
    interactive: false
  });

  savedRouteLayer.addLayer(glow);
  savedRouteLayer.addLayer(core);
  savedRouteLayer.addLayer(accent);
  logGridlyMapLineRendered({
    renderFunction,
    routeId: activation.selectedRouteId,
    activationReason: activation.selectedRouteId ? "selected-route-id" : activation.routeWatchActive ? "route-watch-active" : "selected-corridor-id",
    coordinates: latLngs
  });

  if (map && routeFocusArmed) {
    // V257.3: route rendering no longer takes viewport ownership automatically.
    // The existing saved-route fit behavior is preserved behind Show Full Route.
    routeFocusArmed = false;
  }
  markGridlyRouteRenderedWithoutViewportTakeover(getGridlyRouteViewportSnapshot());
  syncGridlyShowFullRouteAvailability?.();
}

async function renderSavedRouteLine() {
  if (!savedRouteLayer) return;
  const activation = getLineActivationContext();
  if (!activation.hasActivation) {
    savedRouteLayer.clearLayers();
    lastRenderedRouteKey = "";
    return;
  }
  const routeCrossings = inferSavedRouteCrossings();
  savedRouteCrossingIds = new Set(routeCrossings.map((c) => String(c.id)));
  if (routeCrossings.length < 2) {
    lastRenderedRouteKey = "";
    routeFocusArmed = false;
    savedRouteLayer.clearLayers();
    return;
  }

  const from = [routeCrossings[0].lat, routeCrossings[0].lng];
  const to = [routeCrossings[routeCrossings.length - 1].lat, routeCrossings[routeCrossings.length - 1].lng];
  const routeKey = `${from.join(",")}|${to.join(",")}|${getRouteStatusColor()}`;
  if (routeKey === lastRenderedRouteKey) return;
  lastRenderedRouteKey = routeKey;

  savedRouteLayer.clearLayers();
  const osrmPath = await fetchRoadRouteCoordinates(from, to);
  const fallbackPath = routeCrossings.map((crossing) => [crossing.lat, crossing.lng]);
  drawPremiumRouteLine(osrmPath?.length > 1 ? osrmPath : fallbackPath, getRouteStatusColor(), "renderSavedRouteLine");
  recordGridlyActiveLocationLifecycleEvent("renderSavedRouteLine:complete", {
    routeKey,
    routeWatchActivated: Boolean(routeWatchActivated),
    pointCount: (osrmPath?.length > 1 ? osrmPath : fallbackPath).length,
    geometrySource: osrmPath?.length > 1 ? "osrm" : "fallback"
  });
}

function getMarkerLabel(report, markerStateClass, lifecycleState) {
  if (lifecycleState === "recently_cleared" || markerStateClass === "state-cleared") return "✓";
  if (markerStateClass === "state-blocked") return "🛑";
  if (markerStateClass === "state-delay") return "⏱";
  return "◦";
}

function buildSmartIncidentClusters(visibleCrossings = []) {
  const candidates = visibleCrossings
    .map((crossing) => {
      const report = getLatestReportForCrossing(crossing.id);
      const lifecycleState = getIncidentLifecycleState(report);
      if (!report || lifecycleState !== "active") return null;
      const reportType = String(report?.type || "").toLowerCase();
      const severity = reportType === "blocked" ? 2 : reportType === "heavy" ? 1 : 0;
      const candidate = { crossing, report, severity };
      return candidate;
    })
    .filter(Boolean);

  const hiddenIds = new Set();
  const leadCounts = new Map();
  const groupedIds = new Set();

  candidates.forEach((seed) => {
    const seedId = String(seed.crossing.id);
    if (groupedIds.has(seedId)) return;
    const group = candidates.filter((candidate) => {
      if (groupedIds.has(String(candidate.crossing.id))) return false;
      return getDistanceMiles(seed.crossing.lat, seed.crossing.lng, candidate.crossing.lat, candidate.crossing.lng) <= 0.34;
    });
    group.forEach((entry) => groupedIds.add(String(entry.crossing.id)));
    if (group.length <= 2) return;

    const leader = group.sort((a, b) => b.severity - a.severity || a.report.minutesAgo - b.report.minutesAgo)[0];
    leadCounts.set(String(leader.crossing.id), group.length);
    group.forEach((entry) => {
      const id = String(entry.crossing.id);
      if (id !== String(leader.crossing.id)) hiddenIds.add(id);
    });
  });

  return { leadCounts, hiddenIds };
}




function highlightNearestCrossingOnFirstLoad() {
  if (!map || !crossings.length) return;
  if (localStorage.getItem(MAP_FIRST_HINT_SEEN_KEY)) return;

  const center = getGridlyAwarenessAnchor();
  const nearest = findNearestCrossings(center.lat, center.lng, 1)[0];
  if (!nearest) return;

  const marker = crossingMarkers.get(String(nearest.id));
  if (!marker) return;

  const markerEl = marker.getElement?.();
  markerEl?.classList.add("pulse-nearest");

  marker.bindTooltip("Tap marker to report status", {
    direction: "top",
    offset: [0, -12],
    className: "gridly-map-hint",
    opacity: 0.96
  });

  marker.openTooltip();
  localStorage.setItem(MAP_FIRST_HINT_SEEN_KEY, "1");

  setTimeout(() => {
    marker.closeTooltip();
    markerEl?.classList.remove("pulse-nearest");
  }, 4200);
}

function getFilterFitPadding() {
  if (typeof getGridlyAwarenessFitPadding === "function") return getGridlyAwarenessFitPadding();
  const isMobile = window.matchMedia && window.matchMedia("(max-width: 768px)").matches;
  return isMobile ? { paddingTopLeft: [20, 112], paddingBottomRight: [20, 148] } : { paddingTopLeft: [24, 48], paddingBottomRight: [24, 96] };
}

function getGridlyFilterViewportMaxZoom(filterKey = activeGeoFilter) {
  const isMobile = window.matchMedia && window.matchMedia("(max-width: 768px)").matches;
  if (filterKey === "county") return GRIDLY_COUNTY_STARTUP_ZOOM;
  if (filterKey === "town") return GRIDLY_TOWN_STARTUP_ZOOM;
  if (filterKey === "active-delays") return isMobile ? 14 : 13;
  if (filterKey === "all") return isMobile ? 12 : 11;
  return isMobile ? 16 : 15;
}

function getActiveDelayCrossingsForViewport() {
  if (!Array.isArray(crossings) || !crossings.length) return [];
  return crossings.filter((crossing) => {
    const report = getLatestReportForCrossing(crossing.id);
    return getIncidentLifecycleState(report) === "active";
  });
}

function gridlyReissueActiveAreaPresentation(source = "geo-filter-empty") {
  const currentPresentation = gridlyActiveGeographicPresentation;
  if (currentPresentation && currentPresentation.semanticLevel !== "COUNTYWIDE" && [currentPresentation.lat, currentPresentation.lng].every((value) => Number.isFinite(Number(value)))) {
    const zoom = gridlyCommittedSemanticCamera?.zoom || GRIDLY_TOWN_STARTUP_ZOOM;
    if (typeof gridlyRecordSemanticCameraOperation === "function") {
      gridlyRecordSemanticCameraOperation("setView", [[Number(currentPresentation.lat), Number(currentPresentation.lng)], Number(zoom), { animate: true }], "FILTER_PRESENTATION", source);
    }
    return setGridlyAwarenessView({ lat: Number(currentPresentation.lat), lng: Number(currentPresentation.lng) }, Number(zoom), { animate: true, compensateForChrome: false });
  }
  const area = typeof getGridlyHomeTownAwarenessAnchor === "function" ? getGridlyHomeTownAwarenessAnchor() : null;
  if (!area || !map || area.countyWide === true || area.fallback === true) return false;

  // Filter changes are presentation actions, not semantic-selection actions.
  // Resolve the already-governed camera, then issue the real Leaflet movement
  // directly without opening a transaction, changing identity, or persisting.
  const placeGeoid = typeof gridlyResolveCanonicalPlaceGeoid === "function" ? gridlyResolveCanonicalPlaceGeoid(area) : null;
  const consumerCamera = placeGeoid && typeof gridlyGetGovernedPlaceConsumerPresentationCamera === "function"
    ? gridlyGetGovernedPlaceConsumerPresentationCamera(placeGeoid)
    : null;
  const canonicalTarget = placeGeoid ? gridlyPlacePresentationTargets?.[placeGeoid] : null;
  const target = consumerCamera || canonicalTarget || area;
  const lng = consumerCamera ? target?.lng : (canonicalTarget ? target?.lon : target?.lng);
  const zoom = consumerCamera ? target?.zoom : (canonicalTarget ? GRIDLY_TOWN_STARTUP_ZOOM : (target?.startupZoom || GRIDLY_TOWN_STARTUP_ZOOM));
  if (![target?.lat, lng, zoom].every((value) => Number.isFinite(Number(value)))) return false;
  if (typeof gridlyRecordSemanticCameraOperation === "function") {
    gridlyRecordSemanticCameraOperation("setView", [[Number(target.lat), Number(lng)], Number(zoom), { animate: true }], "FILTER_PRESENTATION", source);
  }
  return setGridlyAwarenessView({ lat: Number(target.lat), lng: Number(lng) }, Number(zoom), { animate: true, compensateForChrome: false });
}

function gridlyApplyZeroCrossingViewportContract(filterKey = activeGeoFilter, reason = "unknown") {
  if (filterKey === "active-delays" || filterKey === "county") return false;
  if (!["nearby", "town", "all"].includes(filterKey)) return false;
  return gridlyReissueActiveAreaPresentation(`geo-filter-empty:${filterKey}:${reason}`);
}

function fitMapToCrossingsForActiveFilter(visibleCrossings = []) {
  if (!map) return;

  let targetBounds = null;
  let targetCrossings = Array.isArray(visibleCrossings) ? visibleCrossings : [];

  if (activeGeoFilter === "county") {
    // Fit the same governed polygon that the user can see, not a parallel
    // bounds table (and never a rectangular substitute).
    if (typeof renderGridlyCountyBoundaryOverlay === "function") renderGridlyCountyBoundaryOverlay("county-filter-fit");
    const polygonLayer = typeof gridlyCountyBoundaryOverlayLayersById !== "undefined"
      ? gridlyCountyBoundaryOverlayLayersById[gridlyGetActiveCountyId()] || null
      : null;
    targetBounds = polygonLayer?.getBounds?.() || (typeof renderGridlyCountyBoundaryOverlay !== "function" && typeof gridlyGetCountyBounds === "function" ? gridlyGetCountyBounds(gridlyGetActiveCountyId()) : null);
  } else if (activeGeoFilter === "active-delays") {
    targetCrossings = getActiveDelayCrossingsForViewport();
    if (!targetCrossings.length) return;
  }

  if (!targetBounds) {
    if (!targetCrossings.length) {
      gridlyApplyZeroCrossingViewportContract(activeGeoFilter, "fit-map");
      return;
    }

    const latLngs = targetCrossings
      .map((crossing) => [Number(crossing.lat), Number(crossing.lng)])
      .filter(([lat, lng]) => Number.isFinite(lat) && Number.isFinite(lng));

    if (!latLngs.length) return;

    targetBounds = L.latLngBounds(latLngs);
  }

  if (!targetBounds?.isValid?.()) return;

  map.fitBounds(targetBounds, {
    ...getFilterFitPadding(),
    animate: true,
    duration: 0.55,
    maxZoom: getGridlyFilterViewportMaxZoom(activeGeoFilter)
  });

  highlightNearestCrossingOnFirstLoad();
}

function updateGeoFilterStatus(visibleCrossings = []) {
  const count = visibleCrossings.length;
  const crossingCoverageUnavailable = count === 0 && typeof gridlyGetActiveCountyCrossingInventory === "function" && gridlyGetActiveCountyCrossingInventory().length === 0;
  const publish = (message) => {
    if (els.geoFilterStatus) els.geoFilterStatus.textContent = message;
  };
  if (crossingCoverageUnavailable) {
    publish("Crossing data isn't available for this area yet.");
    return;
  }
  if (activeGeoFilter === "nearby" && userLocation) {
    updateNearestContext();
    return;
  }

  const crossingLabel = count === 1 ? "crossing" : "crossings";
  let message = "All crossings visible: tap markers to confirm route status.";

  if (activeGeoFilter === "nearby") {
    message = count ? `Act now: review ${count} nearby ${crossingLabel} before departure.` : "Action needed: switch filters or zoom to find crossings.";
  } else if (activeGeoFilter === "town") {
    message = count ? `Route focus: check ${count} likely commute ${crossingLabel}.` : "No route crossings in view. Try My Town or Delays.";
  } else if (activeGeoFilter === "county") {
    message = count ? "Awareness area: scan crossings and tap any issue marker." : "No awareness area crossings visible. Reset map view.";
  } else if (activeGeoFilter === "active-delays") {
    const delayLabel = count === 1 ? "delay" : "delays";
    message = count ? `Priority: resolve ${count} active ${delayLabel} affecting routes.` : "Good news: no active delays in this view.";
  } else if (activeGeoFilter === "all") {
    message = count ? "All crossings visible: tap markers to confirm route status." : "Crossing data isn't available for this area yet.";
  }

  publish(message);
}

function getVisibleCrossingsForFilter(reason = "unknown") {
  const fallbackToAll = () => {
    debugGeoFilter(activeGeoFilter, crossings.length, reason);
    return crossings;
  };

  if (activeGeoFilter === "all") {
    const relevant = getDefaultRelevantCrossings();
    const activeCountyInventory = gridlyGetActiveCountyCrossingInventory();
    const visible = relevant.length ? relevant : activeCountyInventory;
    debugGeoFilter("All", visible.length, reason);
    return visible;
  }

  if (activeGeoFilter === "active-delays") {
    const filtered = crossings.filter((crossing) => {
      const report = getLatestReportForCrossing(crossing.id);
      return getIncidentLifecycleState(report) === "active";
    });
    debugGeoFilter("Active Delays", filtered.length, reason);
    return filtered;
  }

  if (activeGeoFilter === "county") {
    const activeCountyId = gridlyGetActiveCountyId();
    const countyArea = gridlyBuildCountywideAwarenessFallbackOption(activeCountyId, GRIDLY_COUNTY_REGISTRY[activeCountyId] || {});
    const filtered = gridlySelectConsumerVisibleCrossings({ ...countyArea, countyId: activeCountyId, countyWide: true }, { countyId: activeCountyId });
    debugGeoFilter("My County", filtered.length, reason);
    return filtered;
  }

  if (activeGeoFilter === "town") {
    const presentation = gridlyActiveGeographicPresentation;
    const awarenessAnchor = presentation && presentation.semanticLevel !== "COUNTYWIDE" && [presentation.lat, presentation.lng].every((value) => Number.isFinite(Number(value)))
      ? { lat: Number(presentation.lat), lng: Number(presentation.lng), radiusMiles: 10 }
      : (typeof getGridlyHomeTownAwarenessAnchor === "function" ? getGridlyHomeTownAwarenessAnchor() : null);
    const filtered = awarenessAnchor ? getGridlyHomeTownCrossings(awarenessAnchor) : crossings.filter(
      (crossing) => String(crossing.city || "").toLowerCase() === getMyTownKey()
    );

    if (!filtered.length) {
      const center = awarenessAnchor || getGridlyAwarenessAnchor({ preferUserLocation: false });
      const nearest = center ? findNearestCrossings(center.lat, center.lng, 10) : crossings;
      debugGeoFilter("Awareness Area", nearest.length, reason);
      return nearest;
    }

    debugGeoFilter("Awareness Area", filtered.length, reason);
    return filtered;
  }

  if (activeGeoFilter === "nearby") {
    const center = getGridlyAwarenessAnchor();
    const nearest = findNearestCrossings(center.lat, center.lng, 10);
    debugGeoFilter("Nearby", nearest.length, reason);
    return nearest;
  }

  return fallbackToAll();
}

function debugGeoFilter(label, visibleCount, reason = "unknown") {
  gridlyCrossingRenderAuditState.filterApplyCallCount += 1;
  const signature = `${activeGeoFilter}|${label}|${visibleCount}`;
  const now = pushCrossingAuditCall("filter-apply", reason, { label, visibleCount, activeGeoFilter, signature });
  const lastApply = gridlyCrossingRenderAuditState.lastFilterApply;
  if (signature === lastApply.signature && now - lastApply.at <= GRIDLY_GEO_FILTER_DEDUPE_MS) return;
  gridlyCrossingRenderAuditState.lastFilterApply = { key: activeGeoFilter, visibleCount, signature, at: now };
  if (GRIDLY_CROSSING_RENDER_DEBUG) {
    console.debug(`Filter applied: ${label}`);
    console.debug(`Visible crossings: ${visibleCount}`);
  }
}

function ensureUnifiedIncidentLayerOnMap() {
  if (!map || typeof L === "undefined" || !L?.layerGroup) return false;
  if (!unifiedIncidentLayer) {
    unifiedIncidentLayer = L.layerGroup();
  }
  if (typeof map.hasLayer === "function" && !map.hasLayer(unifiedIncidentLayer)) {
    unifiedIncidentLayer.addTo(map);
  }
  return Boolean(unifiedIncidentLayer && typeof map.hasLayer === "function" ? map.hasLayer(unifiedIncidentLayer) : unifiedIncidentLayer);
}

function gridlyIncidentEligibleForMapMarker(incident = {}) {
  const type = String(incident?.report_type || incident?.type || "").trim().toLowerCase();
  const status = String(incident?.status || incident?.state || "").trim().toLowerCase();
  const lifecycleState = String(incident?.lifecycleState || incident?.lifecycle || incident?.lifecycle_state || "").trim().toLowerCase();
  if (type === "hazard_cleared") return false;
  if (status === "cleared" || status === "hazard_cleared") return false;
  if (["recently_cleared", "cleared", "hazard_cleared"].includes(lifecycleState)) return false;
  return true;
}

function gridlyGetBlockedCrossingMarkerOwnershipKey(record = {}) {
  const crossingId = record?.crossingId ?? record?.crossing_id;
  if (crossingId === undefined || crossingId === null || !String(crossingId).trim()) return null;
  const normalizedCrossingId = String(crossingId).trim();
  const reportId = record?.reportId ?? record?.report_id ?? record?.id;
  if (reportId !== undefined && reportId !== null && String(reportId).trim()) {
    return `crossing:${normalizedCrossingId}:report:${String(reportId).trim()}`;
  }
  const type = String(record?.report_type || record?.type || "rail_blockage_delay").trim().toLowerCase() || "rail_blockage_delay";
  return `crossing:${normalizedCrossingId}:type:${type}`;
}

function gridlyIsUnifiedRailCrossingIncident(incident = {}) {
  const id = String(incident?.id || "").trim().toLowerCase();
  const type = String(incident?.report_type || incident?.type || "").trim().toLowerCase();
  const category = typeof getHazardCategory === "function" ? getHazardCategory(incident?.report_type || incident?.type || "") : "";
  return id.startsWith("rail-") || category === "rail_blockage_delay" || ["blocked", "heavy", "delayed", "delay", "rail_delay", "rail_blocked"].includes(type);
}

function gridlyGetCrossingLayerBlockedMarkerOwnershipKeys() {
  const keys = new Set();
  if (!(crossingMarkers instanceof Map)) return keys;
  crossingMarkers.forEach((marker, crossingId) => {
    if (!marker) return;
    const report = typeof getLatestReportForCrossing === "function" ? getLatestReportForCrossing(crossingId) : null;
    const state = typeof getIncidentLifecycleState === "function" ? getIncidentLifecycleState(report) : "";
    if (state !== "active") return;
    const exactKey = gridlyGetBlockedCrossingMarkerOwnershipKey({
      crossingId,
      reportId: report?.id || report?.report_id || "",
      report_type: report?.type || "rail_blockage_delay"
    });
    if (exactKey) keys.add(exactKey);
    const fallbackKey = gridlyGetBlockedCrossingMarkerOwnershipKey({ crossingId, report_type: report?.type || "rail_blockage_delay" });
    if (fallbackKey) keys.add(fallbackKey);
  });
  return keys;
}

function gridlyGetUnifiedBlockedCrossingMarkerSuppression(incident = {}, crossingLayerOwnershipKeys = new Set()) {
  if (!gridlyIsUnifiedRailCrossingIncident(incident)) return { suppress: false, reason: "not_rail_crossing_incident" };
  const exactKey = gridlyGetBlockedCrossingMarkerOwnershipKey(incident);
  const crossingId = incident?.crossingId ?? incident?.crossing_id;
  const fallbackKey = crossingId !== undefined && crossingId !== null
    ? gridlyGetBlockedCrossingMarkerOwnershipKey({ crossingId, report_type: incident?.report_type || incident?.type || "rail_blockage_delay" })
    : null;
  if ((exactKey && crossingLayerOwnershipKeys.has(exactKey)) || (fallbackKey && crossingLayerOwnershipKeys.has(fallbackKey))) {
    return {
      suppress: true,
      reason: "crossingLayer_owns_blocked_crossing_marker",
      visualOwner: "crossingLayer",
      dataStillAvailableInUnifiedIncidents: true,
      ownershipKey: exactKey || fallbackKey
    };
  }
  return { suppress: false, reason: "no_crossingLayer_marker_for_report", ownershipKey: exactKey || fallbackKey };
}


let lastGridlyPopupGenerationAudit = {
  available: false,
  popupCount: 0,
  totalPopupGenerationMs: 0,
  averagePopupGenerationMs: 0,
  slowestPopupGenerationMs: 0,
  slowestPopupIncident: null,
  popupRows: [],
  recommendations: ["renderUnifiedIncidents has not generated popups in this session yet."]
};

function gridlyAddPopupAuditDuration(row, key, startAt) {
  if (!row || !key) return;
  row[key] = (Number(row[key]) || 0) + (gridlyNowMs() - startAt);
}

function gridlyGetPopupBuilderFunctionName(incident = {}) {
  const id = String(incident?.id || "");
  return id.startsWith("rail-") ? "buildGridlyCrossingPopupConsumerModel" : "buildGridlyHazardPopupConsumerModel";
}

function gridlyBuildPopupGenerationRecommendations(audit = {}) {
  if (!audit.available || !audit.popupCount) return ["Run Gridly once more after startup to capture popup-generation timings."];
  const slowest = audit.slowestPopupIncident || {};
  const builder = slowest.popupBuilderFunction || "unknown popup builder";
  const dominantBreakdown = [
    ["road lookup", slowest.roadLookupDurationMs],
    ["location resolution", slowest.locationResolutionDurationMs],
    ["narrative generation", slowest.narrativeDurationMs],
    ["HTML generation", slowest.htmlGenerationDurationMs]
  ].sort((a, b) => (Number(b[1]) || 0) - (Number(a[1]) || 0))[0];
  return [
    `${builder} produced the slowest popup at ${gridlyRoundDurationMs(slowest.popupBuildDurationMs)}ms for ${slowest.incidentId || "unknown incident"}.`,
    `${dominantBreakdown?.[0] || "Unknown work"} is the largest measured sub-step for the slowest popup at ${gridlyRoundDurationMs(dominantBreakdown?.[1])}ms.`,
    "Audit-only instrumentation; popup content, marker rendering, and Leaflet binding behavior are unchanged."
  ];
}

function gridlyRecordPopupGenerationAudit(popupRows = []) {
  const rows = Array.isArray(popupRows) ? popupRows.map((row) => ({
    incidentId: row.incidentId || null,
    incidentType: row.incidentType || null,
    popupBuildDurationMs: gridlyRoundDurationMs(row.popupBuildDurationMs),
    popupBuilderFunction: row.popupBuilderFunction || null,
    roadLookupDurationMs: gridlyRoundDurationMs(row.roadLookupDurationMs),
    locationResolutionDurationMs: gridlyRoundDurationMs(row.locationResolutionDurationMs),
    narrativeDurationMs: gridlyRoundDurationMs(row.narrativeDurationMs),
    htmlGenerationDurationMs: gridlyRoundDurationMs(row.htmlGenerationDurationMs)
  })) : [];
  const total = rows.reduce((sum, row) => sum + (Number(row.popupBuildDurationMs) || 0), 0);
  const slowestPopupIncident = rows.reduce((slowest, row) => (Number(row.popupBuildDurationMs) || 0) > (Number(slowest?.popupBuildDurationMs) || 0) ? row : slowest, null);
  lastGridlyPopupGenerationAudit = {
    available: rows.length > 0,
    popupCount: rows.length,
    totalPopupGenerationMs: gridlyRoundDurationMs(total),
    averagePopupGenerationMs: rows.length ? gridlyRoundDurationMs(total / rows.length) : 0,
    slowestPopupGenerationMs: gridlyRoundDurationMs(slowestPopupIncident?.popupBuildDurationMs),
    slowestPopupIncident,
    popupRows: rows,
    recommendations: []
  };
  lastGridlyPopupGenerationAudit.recommendations = gridlyBuildPopupGenerationRecommendations(lastGridlyPopupGenerationAudit);
  return lastGridlyPopupGenerationAudit;
}

function gridlyPopupGenerationAudit() {
  return {
    ...lastGridlyPopupGenerationAudit,
    slowestPopupIncident: lastGridlyPopupGenerationAudit.slowestPopupIncident ? { ...lastGridlyPopupGenerationAudit.slowestPopupIncident } : null,
    popupRows: [...(lastGridlyPopupGenerationAudit.popupRows || [])],
    recommendations: [...(lastGridlyPopupGenerationAudit.recommendations || [])]
  };
}

let lastUnifiedIncidentRenderAudit = {
  available: false,
  totalDurationMs: 0,
  incidentCount: 0,
  roadHazardCount: 0,
  crossingCount: 0,
  renderedMarkerCount: 0,
  phaseDurations: {},
  slowestPhase: null,
  slowestPhaseDurationMs: 0,
  recommendations: ["renderUnifiedIncidents has not completed in this session yet."]
};

function gridlyRoundDurationMs(value) {
  return Number((Number(value) || 0).toFixed(2));
}

function gridlyBuildUnifiedIncidentRenderRecommendations(audit = {}) {
  const slowestPhase = audit.slowestPhase || "unknown";
  const slowestDuration = Number(audit.slowestPhaseDurationMs) || 0;
  const totalDuration = Number(audit.totalDurationMs) || 0;
  const share = totalDuration > 0 ? Math.round((slowestDuration / totalDuration) * 100) : 0;
  const prefix = slowestPhase === "unknown"
    ? "Run Gridly once more after startup to capture a complete renderUnifiedIncidents phase breakdown."
    : `${slowestPhase} is the slowest measured phase at ${gridlyRoundDurationMs(slowestDuration)}ms (${share}% of renderUnifiedIncidents).`;
  const phaseGuidance = {
    "build incidents": "Audit getUnifiedIncidents(), source consolidation, and fallback hazard coordinate scans before changing marker rendering.",
    "filter incidents": "Audit render-key dedupe, lifecycle eligibility checks, and preferred-candidate selection.",
    "sort incidents": "No explicit sort was observed inside renderUnifiedIncidents; if this grows, inspect upstream incident builders.",
    "road hazard processing": "Audit getLiveHazardIncidents() clustering and road hazard aggregation used by marker debug metadata.",
    "crossing processing": "Audit crossing marker ownership-key collection and duplicate blocked-crossing suppression.",
    "marker creation": "Audit Leaflet divIcon/L.marker construction and marker visual-state helpers.",
    "marker updates": "Audit marker addTo(unifiedIncidentLayer) calls and Leaflet marker insertion costs.",
    "marker removal": "Audit unifiedIncidentLayer.clearLayers() and the previous marker count before render.",
    "popup generation": "Audit buildUnifiedIncidentPopup() and popup HTML generation.",
    "DOM updates": "Audit updateHazardCounter() and desktop community pulse rendering.",
    "layer updates": "Audit ensureUnifiedIncidentLayerOnMap() and Leaflet layer operations.",
    "alert synchronization": "No alert synchronization work is expected in renderUnifiedIncidents; non-zero time indicates a future coupling to inspect.",
    "awareness synchronization": "Audit desktop renderGridlyCommunityPulse() if this phase is slow."
  };
  return [prefix, phaseGuidance[slowestPhase] || "Inspect the slowest measured phase before making behavior changes."];
}

function gridlyRecordUnifiedIncidentRenderAudit(audit) {
  const entries = Object.entries(audit.phaseDurations || {});
  const [slowestPhase, slowestPhaseDurationMs] = entries.reduce((slowest, entry) => entry[1] > slowest[1] ? entry : slowest, [null, 0]);
  lastUnifiedIncidentRenderAudit = {
    available: audit.available !== false,
    totalDurationMs: gridlyRoundDurationMs(audit.totalDurationMs),
    incidentCount: audit.incidentCount || 0,
    roadHazardCount: audit.roadHazardCount || 0,
    crossingCount: audit.crossingCount || 0,
    renderedMarkerCount: audit.renderedMarkerCount || 0,
    phaseDurations: Object.fromEntries(entries.map(([key, value]) => [key, gridlyRoundDurationMs(value)])),
    slowestPhase,
    slowestPhaseDurationMs: gridlyRoundDurationMs(slowestPhaseDurationMs),
    recommendations: []
  };
  lastUnifiedIncidentRenderAudit.recommendations = gridlyBuildUnifiedIncidentRenderRecommendations(lastUnifiedIncidentRenderAudit);
  return lastUnifiedIncidentRenderAudit;
}

function renderUnifiedIncidents(reason = "auto") {
  const endRenderUnifiedTrace = timeGridlyReflowTrace("renderUnifiedIncidents");
  const renderAuditStart = gridlyNowMs();
  const phaseDurations = {
    "build incidents": 0,
    "filter incidents": 0,
    "sort incidents": 0,
    "road hazard processing": 0,
    "crossing processing": 0,
    "marker creation": 0,
    "marker updates": 0,
    "marker removal": 0,
    "popup generation": 0,
    "DOM updates": 0,
    "layer updates": 0,
    "alert synchronization": 0,
    "awareness synchronization": 0
  };
  const addPhaseDuration = (phase, startAt) => {
    phaseDurations[phase] = (phaseDurations[phase] || 0) + (gridlyNowMs() - startAt);
  };
  const popupAuditRows = [];
  const finalizeRenderAudit = (extra = {}) => {
    gridlyRecordPopupGenerationAudit(popupAuditRows);
    endRenderUnifiedTrace();
    return gridlyRecordUnifiedIncidentRenderAudit({
      totalDurationMs: gridlyNowMs() - renderAuditStart,
      phaseDurations,
      ...extra
    });
  };
  let phaseStart = gridlyNowMs();
  const layerAvailable = ensureUnifiedIncidentLayerOnMap();
  addPhaseDuration("layer updates", phaseStart);
  if (!layerAvailable) {
    finalizeRenderAudit({ available: false });
    return;
  }

  const renderSelectedAwarenessArea = typeof getGridlySelectedAwarenessArea === "function" ? getGridlySelectedAwarenessArea() : null;
  const renderActiveCounty = typeof window !== "undefined" && window.GRIDLY_ACTIVE_COUNTY_ID
    ? gridlyNormalizeCountyId(window.GRIDLY_ACTIVE_COUNTY_ID)
    : gridlyNormalizeCountyId(renderSelectedAwarenessArea?.countyId || GRIDLY_DEFAULT_COUNTY_ID);
  const renderAwarenessArea = renderSelectedAwarenessArea
    ? [renderSelectedAwarenessArea.countyId || "", renderSelectedAwarenessArea.label || "", renderSelectedAwarenessArea.storageValue || ""].join(":")
    : "";
  const renderCanonicalState = typeof gridlyGetCanonicalActiveCommunityState === "function" ? gridlyGetCanonicalActiveCommunityState() : null;
  const renderSignature = gridlyV734BuildRefreshReuseSignature({
    reasonScope: "renderUnifiedIncidents",
    canonicalActiveCommunityRevision: renderCanonicalState?.revision || "canonical_unavailable",
    canonicalActiveCommunityCount: renderCanonicalState?.activeCount ?? "unknown",
    mapZoom: typeof map !== "undefined" && typeof map?.getZoom === "function" ? map.getZoom() : "",
    layerReady: Boolean(unifiedIncidentLayer),
    routeWatchActivated: Boolean(typeof routeWatchActivated !== "undefined" && routeWatchActivated)
  }, { activeCounty: renderActiveCounty, awarenessArea: renderAwarenessArea });
  const existingLayerCount = typeof unifiedIncidentLayer?.getLayers === "function" ? unifiedIncidentLayer.getLayers().length : 0;
  const previousRenderedActiveCount = Number(gridlyV734RefreshReuseState.renderUnifiedActiveCommunityCount ?? existingLayerCount);
  const activeCountDecreased = renderCanonicalState && Number(renderCanonicalState.activeCount) < previousRenderedActiveCount;
  if (gridlyV734RefreshReuseState.renderUnifiedSignature === renderSignature && existingLayerCount > 0 && !activeCountDecreased) {
    gridlyV734RefreshReuseState.renderUnifiedReuseCount += 1;
    finalizeRenderAudit({
      incidentCount: existingLayerCount,
      renderedMarkerCount: existingLayerCount,
      v734RenderReuseApplied: true,
      v734RenderReuseCount: gridlyV734RefreshReuseState.renderUnifiedReuseCount
    });
    return;
  }
  gridlyV734RefreshReuseState.renderUnifiedSignature = renderSignature;
  gridlyV734RefreshReuseState.renderUnifiedActiveCommunityRevision = renderCanonicalState?.revision || "";
  gridlyV734RefreshReuseState.renderUnifiedActiveCommunityCount = renderCanonicalState?.activeCount ?? 0;

  phaseStart = gridlyNowMs();
  unifiedIncidentLayer.clearLayers();
  addPhaseDuration("marker removal", phaseStart);

  phaseStart = gridlyNowMs();
  const unifiedIncidents = getUnifiedIncidents();
  // The canonical community projection is presentation data, not the map's
  // source authority.  In particular, legacy generic rows can be active before
  // that projection classifies them as reportKind=hazard.  Always union the
  // coordinate-owned activeHazards collection into the production render path.
  const canonicalHazards = Array.isArray(renderCanonicalState?.activeRoadHazardRecords)
    ? renderCanonicalState.activeRoadHazardRecords
    : [];
  const authoritativeActiveHazards = Array.isArray(activeHazards) ? activeHazards : [];
  const fallbackHazardsById = new Map();
  [...canonicalHazards, ...authoritativeActiveHazards].forEach((hazard, index) => {
    const identity = String(hazard?.reportId || hazard?.report_id || hazard?.id || `anonymous:${index}`);
    fallbackHazardsById.set(identity, hazard);
  });
  const fallbackHazards = [...fallbackHazardsById.values()];
  const getIncidentCoordinate = (incident) => {
    const lat = incident?.lat ?? incident?.latitude ?? incident?.rawLat;
    const lng = incident?.lng ?? incident?.lon ?? incident?.longitude ?? incident?.rawLng;
    return { lat, lng };
  };
  const hasFiniteCoordinates = (incident) => {
    const { lat, lng } = getIncidentCoordinate(incident);
    return Number.isFinite(Number(lat)) && Number.isFinite(Number(lng));
  };
  const primaryIncidents = typeof getGridlyActiveCountSurfaceRows === "function"
    ? getGridlyActiveCountSurfaceRows(unifiedIncidents)
    : (Array.isArray(unifiedIncidents) ? unifiedIncidents : []).filter((incident) => String(incident?.status || "").toLowerCase() === "active");
  const activeFallbackHazards = typeof getGridlyActiveCountSurfaceRows === "function"
    ? getGridlyActiveCountSurfaceRows(fallbackHazards)
    : fallbackHazards.filter((hazard) => hazard && !hazard.expired && String(hazard.type || hazard.report_type || "").toLowerCase() !== "hazard_cleared");
  const primaryCoordinateCount = primaryIncidents.filter(hasFiniteCoordinates).length;
  const fallbackCoordinateCount = activeFallbackHazards.filter(hasFiniteCoordinates).length;
  // Generic reports own their coordinates and must be merged, not treated as an
  // all-or-nothing fallback behind crossing/official unified incidents.
  const shouldUseFallbackHazards = fallbackCoordinateCount > 0;
  const primaryKeys = new Set(primaryIncidents.map((incident) => String(incident?.reportId || incident?.report_id || incident?.id || "")));
  const genericHazardsMissingFromPrimary = activeFallbackHazards.filter((hazard) => {
    const id = String(hazard?.reportId || hazard?.report_id || hazard?.id || "");
    return !id || !primaryKeys.has(id);
  });
  const incidents = [...primaryIncidents, ...genericHazardsMissingFromPrimary];
  const reportIdentity = (record) => String(record?.reportId || record?.report_id || record?.id || "");
  gridlyHazardMarkerLoopTrace = new Map(authoritativeActiveHazards.map((hazard) => {
    const id = reportIdentity(hazard);
    return [id, {
      presentInActiveHazards: true,
      presentInUnifiedIncidents: primaryIncidents.some((incident) => reportIdentity(incident) === id),
      presentInMergedRenderSource: incidents.some((incident) => reportIdentity(incident) === id),
      presentAfterDeduplication: false, presentInMarkerLoop: false,
      coordinateAccepted: false, typeAccepted: false, identityAccepted: Boolean(id),
      iconResolved: false, markerConstructorReached: false, markerCreated: false,
      markerAddedToMap: false, markerCurrentlyOnMap: false, firstFailedStage: null
    }];
  }));
  const markerRenderSkipReasons = { missing_lat_lng: 0, invalid_lat_lng: 0, filtered_out: 0, cleared_or_recently_cleared: 0, duplicate_unified_blocked_crossing_marker: 0, missing_marker_layer: 0, render_exception: 0 };
  const markerSourceUsed = genericHazardsMissingFromPrimary.length ? "unifiedIncidents+activeHazards" : "unifiedIncidents";
  const sourceCounts = {
    primaryCount: primaryIncidents.length,
    primaryValidCount: primaryCoordinateCount,
    activeHazardsCount: activeFallbackHazards.length,
    activeHazardsValidCount: fallbackCoordinateCount,
    selectedSourceName: markerSourceUsed,
    selectedSourceCount: incidents.length
  };
  addPhaseDuration("build incidents", phaseStart);
  phaseStart = gridlyNowMs();
  const routeHazard = routeWatchActivated ? getRouteHazardAssessment() : null;
  const dedupedMap = new Map();
  const duplicateCounts = new Map();

  incidents.forEach((incident) => {
    const renderKey = getUnifiedIncidentRenderKey(incident);
    incident._gridlyRenderKey = renderKey;
    if (!dedupedMap.has(renderKey)) {
      dedupedMap.set(renderKey, incident);
      duplicateCounts.set(renderKey, 1);
      return;
    }
    duplicateCounts.set(renderKey, (duplicateCounts.get(renderKey) || 1) + 1);
    dedupedMap.set(renderKey, choosePreferredIncidentCandidate(dedupedMap.get(renderKey), incident, routeHazard));
  });
  const dedupedIncidents = [...dedupedMap.values()];
  dedupedIncidents.forEach((incident) => {
    const trace = gridlyHazardMarkerLoopTrace.get(reportIdentity(incident));
    if (trace) trace.presentAfterDeduplication = true;
  });
  addPhaseDuration("filter incidents", phaseStart);
  phaseStart = gridlyNowMs();
  const crossingLayerOwnershipKeys = gridlyGetCrossingLayerBlockedMarkerOwnershipKeys();
  const suppressedUnifiedIncidentMarkers = [];
  const markerEligibleIncidents = dedupedIncidents.filter((incident) => {
    const eligible = gridlyIncidentEligibleForMapMarker(incident);
    if (!eligible) {
      markerRenderSkipReasons.cleared_or_recently_cleared += 1;
      return false;
    }
    const suppression = gridlyGetUnifiedBlockedCrossingMarkerSuppression(incident, crossingLayerOwnershipKeys);
    if (suppression.suppress) {
      markerRenderSkipReasons.duplicate_unified_blocked_crossing_marker += 1;
      suppressedUnifiedIncidentMarkers.push({
        incidentId: incident?.id || incident?.report_id || incident?.key || null,
        crossingId: incident?.crossingId || incident?.crossing_id || null,
        reportId: incident?.reportId || incident?.report_id || null,
        ownershipKey: suppression.ownershipKey || null,
        suppressionReason: suppression.reason,
        visualOwner: suppression.visualOwner,
        dataStillAvailableInUnifiedIncidents: suppression.dataStillAvailableInUnifiedIncidents
      });
      return false;
    }
    return true;
  });

  addPhaseDuration("crossing processing", phaseStart);

  const markersByCategory = {};
  const markerTypesRendered = new Set();
  const activeVisualStates = new Set();
  let markersAffectingRoute = 0;
  let routeHighlightedMarkers = 0;

  markerEligibleIncidents.forEach((incident) => {
    const markerTrace = gridlyHazardMarkerLoopTrace.get(reportIdentity(incident));
    if (markerTrace) {
      markerTrace.presentInMarkerLoop = true;
      markerTrace.typeAccepted = true;
    }
    let markerPhaseStart = gridlyNowMs();
    if (!unifiedIncidentLayer) { markerRenderSkipReasons.missing_marker_layer += 1; return; }
    const { lat: rawLat, lng: rawLng } = getIncidentCoordinate(incident);
    if (rawLat == null || rawLng == null) { markerRenderSkipReasons.missing_lat_lng += 1; return; }
    const lat = Number(rawLat);
    const lng = Number(rawLng);
    if (!Number.isFinite(lat) || !Number.isFinite(lng)) { markerRenderSkipReasons.invalid_lat_lng += 1; return; }
    if (markerTrace) markerTrace.coordinateAccepted = true;

    const distanceFromUser = userLocation
      ? getDistanceMiles(userLocation.lat, userLocation.lng, lat, lng)
      : null;
    const isNearbyPriority = Number.isFinite(distanceFromUser) && distanceFromUser <= PRIORITY_NEARBY_MILES;
    const ageClass =
      incident.age_minutes <= 15 ? "fresh" : incident.age_minutes <= 60 ? "aging" : "old";
    const proximityClass = isNearbyPriority ? "nearby-priority" : "far-faded";
    const routeRelevanceClass = routeWatchActivated
      ? (isIncidentRouteRelevant(incident, routeHazard) ? "route-relevant" : "route-deemphasized")
      : "";
    const canonicalMarkerPresentation = gridlyBuildCanonicalLiveIncidentPresentation(incident);
    const visualState = getGridlyIncidentVisualState({ ...incident, type: canonicalMarkerPresentation.hazardType, report_type: canonicalMarkerPresentation.hazardType });
    const markerVisual = getGridlyMarkerVisualConfig(visualState.markerStyle);
    const hierarchyConfig = getGridlyMarkerHierarchyConfig(visualState.markerStyle);
    const markerVisualClass = markerVisual.className;
    const markerVisualClassSafe = sanitizeText(markerVisualClass);
    const hazardVisualClassSegment = markerVisualClassSafe ? ` ${markerVisualClassSafe}` : "";
    const priorityClassMap = {
      "route-impact": "gridly-marker-priority-route-impact",
      critical: "gridly-marker-priority-critical",
      high: "gridly-marker-priority-high",
      moderate: "gridly-marker-priority-moderate",
      low: "gridly-marker-priority-low",
      passive: "gridly-marker-priority-passive"
    };
    const hierarchyPriorityClass = priorityClassMap[hierarchyConfig.emphasisLevel] || "gridly-marker-priority-passive";
    const consequenceLevel = String(visualState?.consequenceLevel || "low").toLowerCase();
    const consequenceClass = `gridly-consequence-${consequenceLevel}`;
    const freshnessLevel = String(visualState?.freshnessLevel || evaluateGridlyIncidentFreshness(incident)?.freshnessLevel || "recent").toLowerCase();
    const freshnessClass = `gridly-freshness-${freshnessLevel}`;
    const confidenceEval = evaluateGridlyIncidentConfidence(incident, { visualState, freshnessOptions: { nowMs: Date.now() } });
    const confidenceLevel = String(confidenceEval?.confidenceLevel || "low").toLowerCase();
    const confidenceVisualClass = `gridly-confidence-${confidenceLevel.replace(/_/g, "-")}`;
    const hazardVisualOwner = gridlyResolveVisualHierarchyOwner({ visualStyle: visualState.markerStyle, markerNode: null, config: hierarchyConfig, incident });
    const markerState = incident?.status === "cleared" || incident?.report_type === "hazard_cleared" ? "cleared" : "active";
    const hazardVisualMetadata = gridlyBuildVisualPriorityMetadata({
      owner: hazardVisualOwner,
      visualState: markerState === "cleared" ? "recently_cleared" : (routeRelevanceClass === "route-relevant" ? "route_impact" : "active"),
      routeRelevant: routeRelevanceClass === "route-relevant",
      selected: false,
      impactLevel: hierarchyConfig.emphasisLevel,
      priorityRank: hierarchyConfig.priorityRank
    });
    const intelligence = generateGridlyIntelligencePhrase(incident, visualState);
    const communityPresence = typeof scoreCommunityPresenceIncident === "function"
      ? scoreCommunityPresenceIncident(incident, { allCandidates: dedupedIncidents })
      : null;
    const hazardVisualMetadataAttributes = `
          data-visual-style="${sanitizeText(visualState.markerStyle)}"
          data-visual-priority="${sanitizeText(String(markerVisual.priority))}"
          data-gridly-marker-priority="${sanitizeText(String(hierarchyConfig.priorityRank))}"
          data-gridly-marker-weight="${sanitizeText(String(hierarchyConfig.visualWeight))}"
          ${hazardVisualMetadata.attributes}
          data-gridly-consequence="${sanitizeText(consequenceLevel)}"
          data-gridly-freshness="${sanitizeText(freshnessLevel)}"
          data-gridly-confidence="${sanitizeText(confidenceLevel)}"
          data-gridly-intelligence="${sanitizeText(intelligence.shortPhrase)}"
          data-gridly-confidence-label="${sanitizeText(intelligence.confidencePhrase)}"
          data-incident-id="${sanitizeText(canonicalMarkerPresentation.incidentId || getGridlyCommunityIncidentId(incident))}"
          data-gridly-canonical-incident-id="${sanitizeText(canonicalMarkerPresentation.incidentId || "")}"
          data-gridly-canonical-report-id="${sanitizeText(canonicalMarkerPresentation.reportId || "")}"
          data-gridly-canonical-hazard-type="${sanitizeText(canonicalMarkerPresentation.hazardType || "")}"
          data-gridly-canonical-condition-family="${sanitizeText(canonicalMarkerPresentation.conditionFamily || "")}"
          data-lat="${sanitizeText(String(lat))}"
          data-lng="${sanitizeText(String(lng))}"
          data-gridly-community-awareness="${communityPresence ? "true" : "false"}"
          data-gridly-community-score="${sanitizeText(String(communityPresence?.communityPresenceScore || 0))}"
          data-gridly-community-corridor="${sanitizeText(communityPresence?.corridor || "Local corridors")}"
          data-gridly-community-severity="${sanitizeText(String(communityPresence?.severity || "low"))}"
          data-gridly-community-freshness="${sanitizeText(String(communityPresence?.freshnessLevel || "unknown"))}"
          data-gridly-community-bridge-source="${sanitizeText(GRIDLY_COMMUNITY_AWARENESS_BRIDGE_SOURCE)}"
        `;
    const category = getHazardCategory(incident.report_type || incident.type || "other_hazard");
    const productionMarkerCategory = getGridlyProductionMarkerCategory(incident, category);
    const productionMarkerAsset = getGridlyProductionMarkerAsset(productionMarkerCategory);
    const productionMarkerAnchor = getGridlyProductionMarkerAnchor(productionMarkerCategory, GRIDLY_PRODUCTION_MARKER_DISPLAY_SIZE);
    const productionMarkerPopupAnchor = getGridlyProductionMarkerPopupAnchor(productionMarkerCategory, GRIDLY_PRODUCTION_MARKER_DISPLAY_SIZE);
    const markerVariantClass = `marker-${category}`;
    const productionMarkerClass = `marker-asset-${productionMarkerCategory}`;
    const confidenceClass = String(incident.confidence || "").toLowerCase().includes("community") ? "confidence-community" : "confidence-high";
    markersByCategory[category] = (markersByCategory[category] || 0) + 1;
    markerTypesRendered.add(markerVariantClass);
    markerTypesRendered.add(productionMarkerClass);
    markerTypesRendered.add(getMapSeverityClass(incident));
    markerTypesRendered.add(confidenceClass);
    markerTypesRendered.add(markerVisualClass);
    activeVisualStates.add(ageClass);
    if (routeRelevanceClass) activeVisualStates.add(routeRelevanceClass);
    if (routeRelevanceClass === "route-relevant") {
      markersAffectingRoute += 1;
      routeHighlightedMarkers += 1;
    }

    const icon = L.divIcon({
      className: `gridly-production-marker-icon ${markerVisualClassSafe} ${sanitizeText(hazardVisualMetadata.className)}`,
      html: `
        <div class="gridly-hazard-marker has-production-marker ${sanitizeText(getMapSeverityClass(incident))} ${ageClass} ${proximityClass} ${routeRelevanceClass} ${sanitizeText(markerVariantClass)} ${sanitizeText(productionMarkerClass)} ${sanitizeText(confidenceClass)} ${sanitizeText(hierarchyPriorityClass)} ${sanitizeText(consequenceClass)} ${sanitizeText(freshnessClass)} ${sanitizeText(confidenceVisualClass)} ${sanitizeText(hazardVisualMetadata.className)}${hazardVisualClassSegment}"
          style="--gridly-production-marker-anchor-x:${sanitizeText(String(productionMarkerAnchor[0]))}px; --gridly-production-marker-anchor-y:${sanitizeText(String(productionMarkerAnchor[1]))}px;"
          data-category="${sanitizeText(category)}"
          data-marker-category="${sanitizeText(productionMarkerCategory)}"
          data-marker-asset="${sanitizeText(productionMarkerAsset.assetPath)}"
          ${hazardVisualMetadataAttributes}
          data-freshness="${sanitizeText(ageClass)}"
          data-confidence="${sanitizeText(confidenceClass.replace("confidence-", ""))}"
          data-route-relevance="${sanitizeText(routeRelevanceClass || "unscored")}"
          data-state="${sanitizeText(markerState)}">
          <img class="gridly-production-marker-img" src="${sanitizeText(productionMarkerAsset.assetPath)}" alt="" aria-hidden="true" data-marker-asset="${sanitizeText(productionMarkerAsset.assetName)}" onload="window.gridlyMarkProductionMarkerAssetLoad && window.gridlyMarkProductionMarkerAssetLoad(this.dataset.markerAsset, 'loaded')" onerror="window.gridlyMarkProductionMarkerAssetLoad && window.gridlyMarkProductionMarkerAssetLoad(this.dataset.markerAsset, 'failed')" />
          <small>${incident.age_minutes}m</small>
          ${incident.reports_count > 1 ? `<b>${incident.reports_count}</b>` : ""}
        </div>
      `,
      iconSize: [GRIDLY_PRODUCTION_MARKER_DISPLAY_SIZE, GRIDLY_PRODUCTION_MARKER_DISPLAY_SIZE],
      iconAnchor: productionMarkerAnchor,
      popupAnchor: productionMarkerPopupAnchor
    });
    if (markerTrace) markerTrace.iconResolved = Boolean(icon);
    markGridlyProductionMarkerAssetLoad(productionMarkerAsset.assetName, "attempted");
    addPhaseDuration("marker creation", markerPhaseStart);

    try {
      markerPhaseStart = gridlyNowMs();
      if (markerTrace) markerTrace.markerConstructorReached = true;
      const marker = L.marker([lat, lng], {
        icon,
        incidentId: String(incident?.id || incident?.report_id || incident?.key || ""),
        incidentSource: String(incident?.source || ""),
        gridlyCommunityStatus: markerState,
        status: markerState,
        gridlyCanonicalActiveCommunityRevision: renderCanonicalState?.revision || "",
        incident, sourceIncident: incident, report: incident,
        gridlyPlacementAudit: {
          incidentId: String(incident?.id || incident?.report_id || incident?.key || ""),
          coordinateSourceUsed: incident?.coordinateSourceUsed || "unified_incident_lat_lng",
          rawTapCoordinate: incident?.rawTapCoordinate || incident?.reportCaptureCoordinate || null,
          snappedRoadCoordinate: incident?.snappedRoadCoordinate || null,
          finalPlacementCoordinate: incident?.finalPlacementCoordinate || { lat, lng },
          renderedMarkerCoordinate: { lat, lng },
          reportCaptureCoordinate: incident?.reportCaptureCoordinate || null,
          storedReportCoordinate: incident?.storedReportCoordinate || null,
          activeHazardCoordinate: incident?.activeHazardCoordinate || null,
          unifiedIncidentCoordinate: { lat, lng },
          tapToSnapDeltaMeters: incident?.tapToSnapDeltaMeters ?? null,
          tapToFinalDeltaMeters: incident?.tapToFinalDeltaMeters ?? null,
          snapToFinalDeltaMeters: incident?.snapToFinalDeltaMeters ?? null,
          placementMode: incident?.placementMode || null,
          placementRiskLevel: incident?.placementRiskLevel || null,
          roadCandidateCount: incident?.roadCandidateCount ?? null,
          nearestCandidateDistanceMeters: incident?.nearestCandidateDistanceMeters ?? null,
          representativeCoordinateReason: incident?.representativeCoordinateReason || null
        }
      });
      if (markerTrace) markerTrace.markerCreated = Boolean(marker);
      addPhaseDuration("marker creation", markerPhaseStart);
      markerPhaseStart = gridlyNowMs();
      // Layer insertion is the generic incident presentation boundary.  Popup
      // enrichment (which historically assumed a crossing/corridor) must not
      // prevent a valid coordinate-owned marker from existing on the map.
      marker.addTo(unifiedIncidentLayer);
      if (markerTrace) {
        markerTrace.markerAddedToMap = true;
        markerTrace.markerCurrentlyOnMap = Boolean(map?.hasLayer?.(unifiedIncidentLayer));
      }
      addPhaseDuration("marker updates", markerPhaseStart);
      markerPhaseStart = gridlyNowMs();
      const popupContent = buildUnifiedIncidentPopup(incident, { popupAuditRows });
      addPhaseDuration("popup generation", markerPhaseStart);
      markerPhaseStart = gridlyNowMs();
      marker.bindPopup(popupContent, { maxWidth: 340 });
      marker.on("click", () => gridlyLp0546BindIncidentSelection?.(incident, /official|drivetexas|txdot/i.test(String(incident.providerId || incident.source || "")) ? "official_marker" : "community_marker"));
      marker.on("popupopen", () => { if (gridlyHistoricalSelectionStateV1?.incidentId === String(incident?.id || incident?.report_id || incident?.key || "") || gridlyHistoricalSelectionStateV1?.officialIncidentId === String(incident?.id || incident?.report_id || incident?.key || "")) gridlyLp0546BindIncidentSelection?.(incident, /official|drivetexas|txdot/i.test(String(incident.providerId || incident.source || "")) ? "official_popup" : "community_popup"); });
      addPhaseDuration("marker updates", markerPhaseStart);
    } catch (error) {
      markerRenderSkipReasons.render_exception += 1;
      if (markerTrace && !markerTrace.firstFailedStage) markerTrace.firstFailedStage = markerTrace.markerConstructorReached ? "marker_construction_or_insertion" : "icon_resolution";
    }
  });

  gridlyHazardMarkerLoopTrace.forEach((trace) => {
    if (trace.firstFailedStage) return;
    const stages = [
      ["active_hazards", trace.presentInActiveHazards], ["generic_merge", trace.presentInMergedRenderSource],
      ["deduplication", trace.presentAfterDeduplication], ["marker_loop", trace.presentInMarkerLoop],
      ["identity", trace.identityAccepted], ["type", trace.typeAccepted], ["coordinates", trace.coordinateAccepted],
      ["icon", trace.iconResolved], ["marker_constructor", trace.markerConstructorReached],
      ["marker_created", trace.markerCreated], ["layer_insertion", trace.markerAddedToMap],
      ["layer_visibility", trace.markerCurrentlyOnMap]
    ];
    trace.firstFailedStage = stages.find(([, passed]) => !passed)?.[0] || null;
  });

  const duplicateEntries = [...duplicateCounts.entries()].filter(([, count]) => count > 1);
  const duplicateIncidentCount = duplicateEntries.reduce((sum, [, count]) => sum + (count - 1), 0);

  phaseStart = gridlyNowMs();
  updateHazardCounter(markerEligibleIncidents);
  addPhaseDuration("DOM updates", phaseStart);

  phaseStart = gridlyNowMs();
  const liveHazardIncidentCount = getLiveHazardIncidents().length;
  addPhaseDuration("road hazard processing", phaseStart);
  lastMarkerAuditDebug = {
    activeMarkerCount: markerEligibleIncidents.length,
    totalIncidentsInput: incidents.length,
    uniqueIncidentRenderCount: markerEligibleIncidents.length,
    markerEligibleIncidentCount: markerEligibleIncidents.length,
    markerSuppressedClearedOrRecentlyClearedCount: markerRenderSkipReasons.cleared_or_recently_cleared,
    suppressedUnifiedIncidentMarkerCount: suppressedUnifiedIncidentMarkers.length,
    suppressedUnifiedIncidentMarkers,
    blockedCrossingMarkerOwnership: {
      visualOwner: "crossingLayer",
      suppressionReason: "crossingLayer_owns_blocked_crossing_marker",
      dataStillAvailableInUnifiedIncidents: true,
      crossingLayerOwnershipKeyCount: crossingLayerOwnershipKeys.size
    },
    duplicateIncidentCount,
    duplicateKeysPreview: duplicateEntries.slice(0, 8).map(([key, count]) => `${key}×${count}`),
    activeRenderedCount: markerEligibleIncidents.filter((item) => String(item?.status || "").toLowerCase() !== "cleared").length,
    clearedRenderedCount: markerEligibleIncidents.filter((item) => String(item?.status || "").toLowerCase() === "cleared").length,
    routeRelevantRenderedCount: markerEligibleIncidents.filter((item) => isIncidentRouteRelevant(item, routeHazard)).length,
    lastRenderAt: new Date().toISOString(),
    markerLayerCount: typeof unifiedIncidentLayer?.getLayers === "function" ? unifiedIncidentLayer.getLayers().length : null,
    markersByCategory,
    markersAffectingRoute,
    clusteredMarkerCount: liveHazardIncidentCount,
    markerTypesRendered: [...markerTypesRendered],
    routeHighlightedMarkers,
    activeVisualStates: [...activeVisualStates],
    markerRenderFunctionFound: typeof renderUnifiedIncidentMarkers === "function" || typeof renderUnifiedIncidents === "function",
    markerSourceCount: Array.isArray(incidents) ? incidents.length : 0,
    markerSourceSample: (Array.isArray(incidents) ? incidents : []).slice(0, 3).map((item) => ({
      id: item?.id || item?.report_id || item?.key || null,
      type: item?.report_type || item?.type || null,
      lat: getIncidentCoordinate(item).lat ?? null,
      lng: getIncidentCoordinate(item).lng ?? null
    })),
    markerRenderSkipReasons,
    markerSourceUsed,
    lastMarkerRenderAt: new Date().toISOString(),
    lastMarkerRenderSourceCounts: sourceCounts,
    lastMarkerRenderResult: {
      reason,
      selectedSourceName: markerSourceUsed,
      selectedSourceCount: incidents.length,
      renderedMarkerCount: typeof unifiedIncidentLayer?.getLayers === "function" ? unifiedIncidentLayer.getLayers().length : 0
    }
  };
  phaseStart = gridlyNowMs();
  const renderLayoutMode = evaluateLayoutMode();
  addPhaseDuration("DOM updates", phaseStart);
  if (renderLayoutMode === "desktop") {
    phaseStart = gridlyNowMs();
    renderGridlyCommunityPulse({ reason: `renderUnifiedIncidents:${reason}` });
    addPhaseDuration("awareness synchronization", phaseStart);
  }

  finalizeRenderAudit({
    incidentCount: Array.isArray(incidents) ? incidents.length : 0,
    roadHazardCount: liveHazardIncidentCount,
    crossingCount: markerEligibleIncidents.filter((item) => gridlyIsUnifiedRailCrossingIncident(item)).length + suppressedUnifiedIncidentMarkers.length,
    renderedMarkerCount: typeof unifiedIncidentLayer?.getLayers === "function" ? unifiedIncidentLayer.getLayers().length : markerEligibleIncidents.length
  });
}

function renderUnifiedIncidentMarkers() {
  return renderUnifiedIncidents();
}

function gridlyBuildBlockedCrossingMarkerAudit() {
  const markerRecords = [];
  const addRecord = (record = {}) => {
    markerRecords.push({
      markerType: record.markerType || "unknown",
      owningLayer: record.owningLayer || "unknown",
      creationPath: record.creationPath || "unknown",
      crossingId: String(record.crossingId || ""),
      reportId: String(record.reportId || ""),
      sourceRecord: record.sourceRecord || "unknown",
      leafletId: record.leafletId || null,
      lat: record.lat ?? null,
      lng: record.lng ?? null,
      category: record.category || "",
      visualStyle: record.visualStyle || "",
      interactive: record.interactive !== false
    });
  };

  if (crossingMarkers instanceof Map) {
    crossingMarkers.forEach((marker, crossingId) => {
      const report = typeof getLatestReportForCrossing === "function" ? getLatestReportForCrossing(crossingId) : null;
      const state = typeof getIncidentLifecycleState === "function" ? getIncidentLifecycleState(report) : "";
      const latLng = typeof marker?.getLatLng === "function" ? marker.getLatLng() : {};
      if (state === "active") {
        addRecord({
          markerType: "blocked_crossing",
          owningLayer: "crossingLayer",
          creationPath: "renderCrossings → crossingMarkers → crossingLayer",
          crossingId,
          reportId: report?.id || report?.report_id || "",
          sourceRecord: "activeReports crossing report",
          leafletId: marker?._leaflet_id || null,
          lat: latLng?.lat,
          lng: latLng?.lng,
          category: "rail_blockage_delay",
          visualStyle: "rail_blocked",
          interactive: true
        });
      }
    });
  }

  const unifiedMarkers = typeof unifiedIncidentLayer?.getLayers === "function" ? unifiedIncidentLayer.getLayers() : [];
  unifiedMarkers.forEach((marker) => {
    const options = marker?.options || {};
    const incidentId = String(options.incidentId || "");
    if (!/^rail-/.test(incidentId)) return;
    const crossingId = incidentId.replace(/^rail-/, "");
    const report = typeof getLatestReportForCrossing === "function" ? getLatestReportForCrossing(crossingId) : null;
    const latLng = typeof marker?.getLatLng === "function" ? marker.getLatLng() : {};
    addRecord({
      markerType: "blocked_crossing",
      owningLayer: "unifiedIncidentLayer",
      creationPath: "getConsolidatedIncidents → getUnifiedIncidents → renderUnifiedIncidents → unifiedIncidentLayer",
      crossingId,
      reportId: report?.id || report?.report_id || "",
      sourceRecord: "unified rail incident from activeReports crossing report",
      leafletId: marker?._leaflet_id || null,
      lat: latLng?.lat,
      lng: latLng?.lng,
      category: "rail_blockage_delay",
      visualStyle: "rail_blocked",
      interactive: true
    });
  });

  const recordsByCrossing = markerRecords.reduce((acc, record) => {
    const key = record.crossingId || "unknown";
    if (!acc[key]) acc[key] = [];
    acc[key].push(record);
    return acc;
  }, {});
  const suppressedUnifiedIncidentMarkers = Array.isArray(lastMarkerAuditDebug?.suppressedUnifiedIncidentMarkers)
    ? lastMarkerAuditDebug.suppressedUnifiedIncidentMarkers
    : [];
  const suppressedUnifiedIncidentMarkerCount = suppressedUnifiedIncidentMarkers.length;
  const hasCrossingLayerMarker = markerRecords.some((record) => record.owningLayer === "crossingLayer");
  const hasUnifiedIncidentLayerMarker = markerRecords.some((record) => record.owningLayer === "unifiedIncidentLayer");

  return {
    version: "V310.4",
    generatedAt: new Date().toISOString(),
    classification: hasCrossingLayerMarker && hasUnifiedIncidentLayerMarker
      ? "two_marker_systems_rendering_simultaneously"
      : (suppressedUnifiedIncidentMarkerCount > 0 ? "ownership_arbitrated_to_crossingLayer" : "single_or_unconfirmed_marker_system"),
    markerCount: markerRecords.length,
    suppressedUnifiedIncidentMarkerCount,
    suppressionReason: suppressedUnifiedIncidentMarkerCount > 0 ? "crossingLayer_owns_blocked_crossing_marker" : null,
    visualOwner: hasCrossingLayerMarker ? "crossingLayer" : null,
    dataStillAvailableInUnifiedIncidents: typeof getUnifiedIncidents === "function"
      ? getUnifiedIncidents().some((incident) => gridlyIsUnifiedRailCrossingIncident(incident))
      : null,
    suppressedUnifiedIncidentMarkers,
    recordsByCrossing,
    markerRecords,
    notes: [
      "Audit-only helper; does not mutate Leaflet layers or marker render conditions.",
      "crossingLayer records come from renderCrossings and crossingMarkers.",
      "unified rail/crossing data remains in getUnifiedIncidents; renderUnifiedIncidents suppresses only duplicate Leaflet markers already owned by crossingLayer."
    ]
  };
}


if (typeof window !== "undefined") {
  window.gridlyRenderUnifiedIncidentsNow = () => renderUnifiedIncidents("manual-debug");
  window.gridlyBlockedCrossingMarkerAudit = gridlyBuildBlockedCrossingMarkerAudit;
  window.gridlyUnifiedIncidentRenderAudit = () => ({ ...lastUnifiedIncidentRenderAudit, phaseDurations: { ...(lastUnifiedIncidentRenderAudit.phaseDurations || {}) }, recommendations: [...(lastUnifiedIncidentRenderAudit.recommendations || [])] });
  window.gridlyPopupGenerationAudit = gridlyPopupGenerationAudit;
}

function scheduleHazardMarkerAutoRender(source = "unspecified") {
  const renderFn = typeof renderUnifiedIncidents === "function"
    ? renderUnifiedIncidents
    : (typeof renderUnifiedIncidentMarkers === "function" ? renderUnifiedIncidentMarkers : null);
  if (typeof renderFn !== "function") return;
  renderFn();
  setTimeout(() => {
    if (typeof renderFn === "function") renderFn();
  }, 500);
  setTimeout(() => {
    if (typeof renderFn === "function") renderFn();
  }, 1500);
}

function getCategoryMarkerGlyph(category, incident) {
  if (incident?.status === "cleared" || incident?.report_type === "hazard_cleared") return "✓";
  const glyphMap = {
    rail_blockage_delay: "⟂",
    delay: "◔",
    flooding: "≈",
    crash: "✶",
    construction: "▧",
    road_closed: "⛔",
    disabled_vehicle: "◌",
    traffic_backup: "◍",
    other_hazard: "•"
  };
  return glyphMap[category] || "•";
}

function buildHazardPopup(incident) {
  const hazard = incident.latestReport;
  const isFresh = hazard.minutesAgo <= REPORT_EXPIRATION_MINUTES;
  const reportedAgo = humanizeMinutesAgo(hazard.minutesAgo);
  const driverLabel = `${incident.count} driver${incident.count === 1 ? "" : "s"}`;
  const reportStateLabel = isFresh ? "Live community report" : "Needs new confirmation";
  const reportedLabel = isFresh
    ? `Reported ${reportedAgo} by ${driverLabel}.`
    : `Last reported ${reportedAgo} by ${driverLabel}.`;
  const stateNote = isFresh
    ? "Drivers can confirm if this hazard is still active."
    : "This may no longer be active.";
  const actionButtons = isFresh
    ? `
        <button class="popup-report-btn warning" data-action="confirm-hazard" data-hazard-type="${sanitizeText(hazard.type)}" data-lat="${hazard.lat}" data-lng="${hazard.lng}">Still There</button>
        <button class="popup-report-btn blue" data-action="clear-hazard" data-hazard-type="${sanitizeText(hazard.type)}" data-lat="${hazard.lat}" data-lng="${hazard.lng}">Cleared</button>
      `
    : `
        <button class="popup-report-btn warning" data-action="confirm-hazard" data-hazard-type="${sanitizeText(hazard.type)}" data-lat="${hazard.lat}" data-lng="${hazard.lng}">Confirm Now</button>
      `
    ;

  return `
    <div class="gridly-popup">
      <strong>${sanitizeText(isFresh ? hazard.title : "Crash Report")}</strong>
      <span>${sanitizeText(reportStateLabel)}</span><br />
      <span>${sanitizeText(reportedLabel)}</span><br />
      <span>${sanitizeText(stateNote)}</span><br />

      <div class="popup-report-grid">
        ${actionButtons}
        <button class="popup-report-btn neutral" data-action="zoom-hazard" data-lat="${hazard.lat}" data-lng="${hazard.lng}">View Area</button>
      </div>
    </div>
  `;
}

function humanizeMinutesAgo(totalMinutes) {
  const minutes = Math.max(0, Number(totalMinutes) || 0);

  if (minutes <= 1) return "just now";
  if (minutes < 60) return `${minutes}m ago`;

  const roundedHours = Math.round(minutes / 60);
  if (roundedHours < 24) return `${roundedHours}h ago`;

  const roundedDays = Math.round(roundedHours / 24);
  return `${roundedDays}d ago`;
}
function gridlyRoadClearedCoordinateKey(hazard = {}) {
  const lat = Number(hazard?.lat ?? hazard?.latitude ?? hazard?.rawLat);
  const lng = Number(hazard?.lng ?? hazard?.lon ?? hazard?.longitude ?? hazard?.rawLng);
  if (!Number.isFinite(lat) || !Number.isFinite(lng)) return null;
  return `${lat.toFixed(3)}-${lng.toFixed(3)}`;
}

function gridlyIsRoadClearedHazardRecord(hazard = {}) {
  return String(hazard?.type || hazard?.report_type || "").toLowerCase() === "hazard_cleared";
}

function gridlyInferRoadClearedHazardType(hazard = {}) {
  const explicitType = String(hazard?.clearedHazardType || hazard?.originalHazardType || hazard?.hazardType || hazard?.hazard_type || "").trim().toLowerCase();
  if (explicitType && explicitType !== "hazard_cleared") return gridlyNormalizeHazardType({ type: explicitType });

  const recordType = String(hazard?.type || hazard?.report_type || "").trim().toLowerCase();
  if (recordType && recordType !== "hazard_cleared") return gridlyNormalizeHazardType({ type: recordType });

  const text = [hazard?.detail, hazard?.title, hazard?.crossingName, hazard?.crossing_name, hazard?.label]
    .map((value) => String(value || "").toLowerCase())
    .join(" ");
  const normalizedText = text.replace(/[^a-z0-9]+/g, " ").trim();
  for (const [type, copy] of Object.entries(HAZARD_TYPES || {})) {
    if (type === "rail_blockage_delay" || type === "rail_issue") continue;
    const typeText = String(type || "").replace(/_/g, " ");
    const labelText = String(copy?.label || "").toLowerCase().replace(/[^a-z0-9]+/g, " ").trim();
    const labelLead = labelText.split(" ")[0] || "";
    if ((typeText && normalizedText.includes(typeText)) || (labelText && normalizedText.includes(labelText)) || (labelLead && labelLead.length >= 4 && normalizedText.includes(labelLead))) {
      return gridlyNormalizeHazardType({ type });
    }
  }
  return "other_hazard";
}

function gridlyRoadHazardLifecycleMatchType(hazard = {}) {
  return gridlyIsRoadClearedHazardRecord(hazard) ? gridlyInferRoadClearedHazardType(hazard) : gridlyNormalizeHazardType(hazard);
}

function gridlyRoadHazardIncidentKey(hazard = {}) {
  const value = hazard?.incidentKey || hazard?.incident_key || hazard?.incidentId || hazard?.incident_id || hazard?.groupKey || hazard?.group_key || hazard?.clusterId || hazard?.cluster_id;
  const text = String(value || "").trim();
  return text ? `incident:${text.toLowerCase()}` : "";
}

function gridlyRoadHazardRoundedCoordinateKey(hazard = {}, decimals = GRIDLY_ROAD_CLUSTER_ROUNDING_DECIMALS) {
  const coordinate = gridlyRoadClusterCoordinateFromRecord(hazard);
  const lat = Number(coordinate?.lat ?? hazard?.lat ?? hazard?.latitude ?? hazard?.rawLat);
  const lng = Number(coordinate?.lng ?? hazard?.lng ?? hazard?.lon ?? hazard?.longitude ?? hazard?.rawLng);
  if (!Number.isFinite(lat) || !Number.isFinite(lng)) return "";
  const safeDecimals = Number.isFinite(Number(decimals)) ? Number(decimals) : GRIDLY_ROAD_CLUSTER_ROUNDING_DECIMALS;
  return `${lat.toFixed(safeDecimals)}-${lng.toFixed(safeDecimals)}`;
}

function gridlyRoadHazardLifecycleMatchKeys(hazard = {}) {
  const keys = new Set();
  const incidentKey = gridlyRoadHazardIncidentKey(hazard);
  if (incidentKey) keys.add(incidentKey);

  const sourceReportId = String(hazard?.sourceReportId || hazard?.source_report_id || hazard?.reportId || hazard?.report_id || hazard?.raw?.id || hazard?.raw?.report_id || hazard?.latestReport?.id || "").trim();
  if (sourceReportId) keys.add(`sourcereport:${sourceReportId.toLowerCase()}`);

  const id = String(hazard?.id || hazard?.raw?.id || "").trim();
  if (id) keys.add(`id:${id.toLowerCase()}`);

  const hazardType = gridlyRoadHazardLifecycleMatchType(hazard);
  const explicitRoadCluster = String(hazard?.roadClusterKey || hazard?.road_cluster_key || hazard?.clusterKey || hazard?.cluster_key || "").trim();
  if (explicitRoadCluster) keys.add(`roadcluster:${explicitRoadCluster.toLowerCase()}`);

  const coordinateKey = gridlyRoadHazardRoundedCoordinateKey(hazard, GRIDLY_ROAD_CLUSTER_ROUNDING_DECIMALS);
  if (coordinateKey) {
    keys.add(`roadcluster:${hazardType}-${coordinateKey}`);
    keys.add(`coordtype:${hazardType}-${coordinateKey}`);
  }

  const previousCoordinateKey = gridlyRoadHazardRoundedCoordinateKey(hazard, GRIDLY_ROAD_CLUSTER_PREVIOUS_ROUNDING_DECIMALS);
  if (previousCoordinateKey) keys.add(`coordtype:${hazardType}-${previousCoordinateKey}`);

  return [...keys];
}

function gridlyBuildRoadHazardLifecycleIndex(hazards = activeHazards) {
  const index = new Map();
  gridlyDiagnosticArray(hazards).forEach((hazard) => {
    if (!hazard || hazard?.expired) return;
    const type = String(hazard?.type || hazard?.report_type || "").toLowerCase();
    const isRoadHazard = hazard?.reportKind === "hazard" || type === "hazard_cleared" || Object.prototype.hasOwnProperty.call(HAZARD_TYPES, type);
    if (!isRoadHazard) return;
    const eventTime = gridlyRoadClusterReportTimeMs(hazard);
    if (!Number.isFinite(eventTime) || eventTime <= 0) return;
    const state = gridlyIsRoadClearedHazardRecord(hazard) ? "cleared" : "active";
    gridlyRoadHazardLifecycleMatchKeys(hazard).forEach((key) => {
      const previous = index.get(key);
      const previousTime = Number(previous?.eventTime) || 0;
      if (!previous || eventTime > previousTime || (eventTime === previousTime && state === "cleared")) {
        index.set(key, { hazard, state, eventTime, key });
      }
    });
  });
  return index;
}

function gridlyFindNewestMatchingRoadHazardLifecycleEntry(hazard = {}, hazards = activeHazards, stateFilter = null) {
  const keys = gridlyRoadHazardLifecycleMatchKeys(hazard);
  if (!keys.length) return null;
  const lifecycleIndex = gridlyBuildRoadHazardLifecycleIndex(hazards);
  const states = Array.isArray(stateFilter)
    ? new Set(stateFilter.map((state) => String(state || "").toLowerCase()))
    : (stateFilter ? new Set([String(stateFilter).toLowerCase()]) : null);
  return keys
    .map((key) => lifecycleIndex.get(key))
    .filter((entry) => entry && (!states || states.has(String(entry.state || "").toLowerCase())))
    .sort((a, b) => Number(b.eventTime || 0) - Number(a.eventTime || 0))[0] || null;
}

function gridlyRoadHazardLatestLifecycleState(hazard = {}, hazards = activeHazards) {
  const eventTime = gridlyRoadClusterReportTimeMs(hazard);
  const isClear = gridlyIsRoadClearedHazardRecord(hazard);
  const latest = gridlyFindNewestMatchingRoadHazardLifecycleEntry(hazard, hazards);
  if (!latest) return isClear ? "cleared" : "active";
  if (isClear) {
    const newerActive = gridlyFindNewestMatchingRoadHazardLifecycleEntry(hazard, hazards, "active");
    const activeTime = Number(newerActive?.eventTime || 0);
    return Number.isFinite(eventTime) && eventTime > 0 && Number.isFinite(activeTime) && activeTime > eventTime ? "active" : "cleared";
  }
  const latestClear = gridlyFindNewestMatchingRoadHazardLifecycleEntry(hazard, hazards, "cleared");
  const clearTime = Number(latestClear?.eventTime || 0);
  return Number.isFinite(eventTime) && eventTime > 0 && Number.isFinite(clearTime) && clearTime > eventTime ? "cleared" : "active";
}

function gridlyRoadClearSupersededByNewerActive(hazard = {}, hazards = activeHazards) {
  if (!gridlyIsRoadClearedHazardRecord(hazard)) return false;
  const clearTime = gridlyRoadClusterReportTimeMs(hazard);
  const newerActive = gridlyFindNewestMatchingRoadHazardLifecycleEntry(hazard, hazards, "active");
  const activeTime = Number(newerActive?.eventTime || 0);
  return Number.isFinite(clearTime) && clearTime > 0 && Number.isFinite(activeTime) && activeTime > clearTime;
}

function gridlyRoadClearedAgeMinutes(hazard = {}, nowMs = Date.now()) {
  const submittedAtMs = new Date(hazard?.submittedAt || hazard?.created_at || hazard?.createdAt || hazard?.updated_at || 0).getTime();
  if (!Number.isFinite(submittedAtMs) || submittedAtMs <= 0 || submittedAtMs > nowMs) return null;
  return Math.max(0, Math.floor((nowMs - submittedAtMs) / 60000));
}

function gridlyIsRecentlyClearedRoadHazardRecord(hazard = {}, nowMs = Date.now()) {
  if (!gridlyIsRoadClearedHazardRecord(hazard)) return false;
  const ageMinutes = gridlyRoadClearedAgeMinutes(hazard, nowMs);
  return Number.isFinite(Number(ageMinutes)) && Number(ageMinutes) <= RECENTLY_CLEARED_WINDOW_MINUTES;
}

function gridlyBuildRecentRoadClearIndex(hazards = activeHazards, nowMs = Date.now()) {
  return gridlyDiagnosticArray(hazards).reduce((acc, hazard) => {
    if (!gridlyIsRecentlyClearedRoadHazardRecord(hazard, nowMs)) return acc;
    const hazardTime = gridlyRoadClusterReportTimeMs(hazard);
    gridlyRoadHazardLifecycleMatchKeys(hazard).forEach((key) => {
      const previous = acc.get(key);
      const previousTime = gridlyRoadClusterReportTimeMs(previous);
      if (!previous || hazardTime >= previousTime) acc.set(key, hazard);
    });
    return acc;
  }, new Map());
}

function gridlyRoadHazardClearMatchReason(hazard = {}, clear = {}) {
  const hazardKeys = new Set(gridlyRoadHazardLifecycleMatchKeys(hazard));
  const matchedKey = gridlyRoadHazardLifecycleMatchKeys(clear).find((key) => hazardKeys.has(key));
  if (matchedKey) return matchedKey;
  const hazardType = gridlyRoadHazardLifecycleMatchType(hazard);
  const clearType = gridlyRoadHazardLifecycleMatchType(clear);
  const hazardRoad = normalizeGridlyAwarenessAreaLookupText(gridlyRoadClusterRoadName(hazard));
  const clearRoad = normalizeGridlyAwarenessAreaLookupText(gridlyRoadClusterRoadName(clear));
  const hazardTime = gridlyRoadClusterReportTimeMs(hazard);
  const clearTime = gridlyRoadClusterReportTimeMs(clear);
  const proximityMs = Math.abs(Number(clearTime || 0) - Number(hazardTime || 0));
  if (hazardType === clearType && hazardRoad && clearRoad && hazardRoad === clearRoad && Number.isFinite(proximityMs) && proximityMs <= 12 * 60 * 60 * 1000) {
    return `roadtypeproximity:${hazardType}:${hazardRoad}`;
  }
  return "";
}

function gridlyRecentClearIsNewerThanRoadHazard(hazard = {}, clear = {}) {
  const hazardTime = gridlyRoadClusterReportTimeMs(hazard);
  const clearTime = gridlyRoadClusterReportTimeMs(clear);
  return Number.isFinite(hazardTime) && hazardTime > 0 && Number.isFinite(clearTime) && clearTime > hazardTime;
}

function gridlyFindRecentClearForRoadHazard(hazard = {}, hazards = activeHazards, recentClearIndex = gridlyBuildRecentRoadClearIndex(hazards), nowMs = Date.now()) {
  if (!hazard || gridlyIsRoadClearedHazardRecord(hazard)) return null;
  const directClear = gridlyRoadHazardLifecycleMatchKeys(hazard)
    .map((key) => recentClearIndex.get(key))
    .filter((clear) => clear
      && gridlyIsRecentlyClearedRoadHazardRecord(clear, nowMs)
      && gridlyRecentClearIsNewerThanRoadHazard(hazard, clear))
    .sort((a, b) => gridlyRoadClusterReportTimeMs(b) - gridlyRoadClusterReportTimeMs(a))[0] || null;
  if (directClear) return directClear;
  return gridlyDiagnosticArray(hazards)
    .filter((clear) => gridlyIsRecentlyClearedRoadHazardRecord(clear, nowMs)
      && gridlyRecentClearIsNewerThanRoadHazard(hazard, clear)
      && gridlyRoadHazardClearMatchReason(hazard, clear))
    .sort((a, b) => gridlyRoadClusterReportTimeMs(b) - gridlyRoadClusterReportTimeMs(a))[0] || null;
}

function gridlyBuildClearedDuplicateRoadHazardSuppressionSources(sourceHazards = activeHazards) {
  const hazardRows = gridlyDiagnosticArray(sourceHazards);
  const reportRows = typeof activeReports !== "undefined" ? gridlyDiagnosticArray(activeReports) : [];
  const recentlyClearedRows = typeof recentlyClearedRoadHazards !== "undefined" ? gridlyDiagnosticArray(recentlyClearedRoadHazards) : [];
  return [...hazardRows, ...reportRows, ...recentlyClearedRows].filter((row) => row && typeof row === "object");
}

function gridlySuppressClearedDuplicateRoadHazardAwarenessCandidates(hazards = activeHazards, options = {}) {
  const nowMs = Number.isFinite(Number(options?.nowMs)) ? Number(options.nowMs) : Date.now();
  const sourceHazards = gridlyDiagnosticArray(options?.sourceHazards || hazards);
  const candidates = gridlyDiagnosticArray(hazards);
  const suppressionSources = gridlyBuildClearedDuplicateRoadHazardSuppressionSources(sourceHazards);
  const recentClearIndex = gridlyBuildRecentRoadClearIndex(suppressionSources, nowMs);
  return candidates.filter((hazard) => {
    if (!hazard || gridlyIsRoadClearedHazardRecord(hazard) || gridlyIsClearedHazardAwarenessRecord(hazard)) return false;
    const matchingClear = gridlyFindRecentClearForRoadHazard(hazard, suppressionSources, recentClearIndex, nowMs);
    return !matchingClear;
  });
}

function gridlyBuildClearedDuplicateRoadHazardSuppressionAudit(hazards = activeHazards, options = {}) {
  const nowMs = Number.isFinite(Number(options?.nowMs)) ? Number(options.nowMs) : Date.now();
  const sourceHazards = gridlyDiagnosticArray(hazards);
  const suppressionSources = gridlyBuildClearedDuplicateRoadHazardSuppressionSources(sourceHazards);
  const recentClearIndex = gridlyBuildRecentRoadClearIndex(suppressionSources, nowMs);
  const duplicateActiveHazardKeys = [];
  const suppressedRecords = [];
  sourceHazards.forEach((hazard) => {
    if (!hazard || gridlyIsRoadClearedHazardRecord(hazard) || gridlyIsClearedHazardAwarenessRecord(hazard)) return;
    const matchingClear = gridlyFindRecentClearForRoadHazard(hazard, suppressionSources, recentClearIndex, nowMs);
    if (!matchingClear) return;
    const keys = gridlyRoadHazardLifecycleMatchKeys(hazard);
    duplicateActiveHazardKeys.push(...keys);
    suppressedRecords.push(gridlySummarizeRehydrationSuppression(hazard, matchingClear, "clearedDuplicateRoadHazardSuppression", nowMs));
  });
  return {
    duplicateActiveHazardKeys: Array.from(new Set(duplicateActiveHazardKeys)),
    clearedDuplicateSuppressedCount: suppressedRecords.length,
    duplicateSuppressionReason: suppressedRecords.length
      ? "cleared_duplicate_hazard_suppressed_by_newer_matching_clear_across_ids_or_source_report_ids"
      : "",
    suppressedRecords
  };
}

function gridlySummarizeRehydrationSuppression(hazard = {}, clear = {}, source = "activeHazards", nowMs = Date.now()) {
  const hazardCoord = gridlyCoordinateFromRecord(hazard);
  const clearCoord = gridlyCoordinateFromRecord(clear);
  return {
    source,
    id: hazard?.id || hazard?.report_id || hazard?.reportId || null,
    sourceReportId: hazard?.sourceReportId || hazard?.source_report_id || hazard?.reportId || hazard?.report_id || hazard?.raw?.id || null,
    type: hazard?.type || hazard?.report_type || null,
    matchedClearId: clear?.id || clear?.report_id || clear?.reportId || null,
    matchedClearType: clear?.clearedHazardType || clear?.hazardType || clear?.type || clear?.report_type || null,
    matchReason: gridlyRoadHazardClearMatchReason(hazard, clear),
    hazardCreatedAt: hazard?.submittedAt || hazard?.created_at || hazard?.createdAt || null,
    clearCreatedAt: clear?.submittedAt || clear?.created_at || clear?.createdAt || null,
    hazardEventTimeMs: gridlyRoadClusterReportTimeMs(hazard) || null,
    clearEventTimeMs: gridlyRoadClusterReportTimeMs(clear) || null,
    clearIsNewerThanHazard: gridlyRecentClearIsNewerThanRoadHazard(hazard, clear),
    hazardAgeMinutes: gridlyRoadClusterReportAgeMinutes(hazard, nowMs),
    clearAgeMinutes: gridlyRoadClusterReportAgeMinutes(clear, nowMs),
    hazardCoordinate: hazardCoord ? { lat: Number(hazardCoord.lat), lng: Number(hazardCoord.lng) } : null,
    clearCoordinate: clearCoord ? { lat: Number(clearCoord.lat), lng: Number(clearCoord.lng) } : null,
    roadName: gridlyRoadClusterRoadName(hazard)
  };
}

function gridlyRoadHazardSuppressedByRecentClear(hazard = {}, recentClearIndex = gridlyBuildRecentRoadClearIndex(), nowMs = Date.now(), sourceHazards = activeHazards) {
  return Boolean(gridlyFindRecentClearForRoadHazard(hazard, sourceHazards, recentClearIndex, nowMs));
}

function gridlyHasRecentlyClearedLifecycleState(hazard = {}, nowMs = Date.now()) {
  const explicitState = String(hazard?.lifecycleState || hazard?.lifecycle || hazard?.status || hazard?.state || "").trim().toLowerCase();
  if (["recently_cleared", "cleared", "expired", "inactive", "historical", "stale"].includes(explicitState)) return true;
  return gridlyIsRecentlyClearedRoadHazardRecord(hazard, nowMs);
}

function gridlyIsActiveRoadHazardIncidentSource(hazard = {}, sourceHazards = activeHazards, recentClearIndex = gridlyBuildRecentRoadClearIndex(sourceHazards), nowMs = Date.now()) {
  if (!hazard || hazard?.expired) return false;
  if (gridlyIsRoadClearedHazardRecord(hazard) || gridlyHasRecentlyClearedLifecycleState(hazard, nowMs)) return false;
  if (getIncidentLifecycleState(hazard, nowMs) !== "active") return false;
  if (typeof gridlyClassifyHazardLifecycle === "function") {
    const resolved = gridlyClassifyHazardLifecycle(hazard, { nowMs });
    if (resolved?.lifecycleState && !["ACTIVE", "NEEDS_CONFIRMATION", "CONFIRMED"].includes(resolved.lifecycleState)) return false;
  }
  if (typeof gridlyRoadHazardLatestLifecycleState === "function" && gridlyRoadHazardLatestLifecycleState(hazard, sourceHazards) === "cleared") return false;
  return !gridlyRoadHazardSuppressedByRecentClear(hazard, recentClearIndex, nowMs, sourceHazards);
}

function gridlyFilterRecentlyClearedRoadHazardsForVisibility(hazards = activeHazards, nowMs = Date.now()) {
  const sourceHazards = gridlyDiagnosticArray(hazards);
  return sourceHazards.filter((hazard) => gridlyIsRecentlyClearedRoadHazardRecord(hazard, nowMs));
}

function gridlyFilterRoadHazardsByLatestLifecycle(hazards = activeHazards, nowMs = Date.now()) {
  const sourceHazards = gridlyDiagnosticArray(hazards);
  const recentClearIndex = gridlyBuildRecentRoadClearIndex(sourceHazards, nowMs);
  const suppressedRecords = [];
  const active = sourceHazards.filter((hazard) => {
    const matchingClear = gridlyFindRecentClearForRoadHazard(hazard, sourceHazards, recentClearIndex, nowMs);
    if (matchingClear && !gridlyIsRoadClearedHazardRecord(hazard)) {
      suppressedRecords.push(gridlySummarizeRehydrationSuppression(hazard, matchingClear, "gridlyFilterRoadHazardsByLatestLifecycle", nowMs));
      return false;
    }
    return gridlyIsActiveRoadHazardIncidentSource(hazard, sourceHazards, recentClearIndex, nowMs);
  });
  gridlyClearedHazardRehydrationGuardState = {
    suppressedRecords,
    lastUpdatedAt: new Date(nowMs).toISOString()
  };
  return active;
}

function gridlyBuildRoadHazardIncidentsFromReports(hazards = activeHazards, options = {}) {
  const grouped = new Map();
  const cleared = options?.cleared === true;
  const nowMs = Number.isFinite(Number(options?.nowMs)) ? Number(options.nowMs) : Date.now();
  const sourceHazards = gridlyDiagnosticArray(hazards);
  const recentClearIndex = gridlyBuildRecentRoadClearIndex(sourceHazards, nowMs);

  sourceHazards
    .filter((hazard) => cleared
      ? gridlyIsRecentlyClearedRoadHazardRecord(hazard, nowMs) && !gridlyRoadClearSupersededByNewerActive(hazard, sourceHazards)
      : gridlyIsActiveRoadHazardIncidentSource(hazard, sourceHazards, recentClearIndex, nowMs))
    .forEach((hazard) => {
      const key = cleared
        ? `hazard_cleared-${gridlyRoadHazardLifecycleMatchType(hazard)}-${gridlyRoadClearedCoordinateKey(hazard) || gridlyRoadHazardRoundedCoordinateKey(hazard) || getHazardClusterKey(hazard)}`
        : getHazardClusterKey(hazard);

      if (!grouped.has(key)) {
        grouped.set(key, {
          key,
          reports: []
        });
      }

      grouped.get(key).reports.push(hazard);
    });

  return [...grouped.values()]
    .map((incident) => {
      const sorted = incident.reports.sort(
        (a, b) => new Date(b.submittedAt) - new Date(a.submittedAt)
      );

      return {
        key: incident.key,
        count: sorted.length,
        latestReport: sorted[0],
        reports: sorted,
        representativeCoordinateReason: sorted.length > 1
          ? "latest_report_coordinate_within_tight_0.0001_degree_hazard_cluster"
          : "single_report_coordinate",
        oldestMinutes: Math.max(...sorted.map((r) => r.minutesAgo)),
        newestMinutes: Math.min(...sorted.map((r) => r.minutesAgo))
      };
    })
    .sort((a, b) => b.count - a.count || a.newestMinutes - b.newestMinutes);
}

function getRecentlyClearedRoadHazardIncidents() {
  return gridlyBuildRoadHazardIncidentsFromReports(recentlyClearedRoadHazards, { cleared: true });
}

function getLiveHazardIncidents() {
  return gridlyBuildRoadHazardIncidentsFromReports([...gridlyDiagnosticArray(activeHazards), ...gridlyDiagnosticArray(recentlyClearedRoadHazards)]);
}

function getRouteWatchCommunitySourceIncidents() {
  if (!routeWatchActivated) return [];
  return gridlyBuildRoadHazardIncidentsFromReports(routeWatchSourceHazards).map((incident) => {
    const latest = incident.latestReport || {};
    return normalizeUnifiedIncident({
      id: `road-route-${latest.id || incident.key}`,
      type: latest.type || latest.report_type || "road_hazard",
      source: "community",
      status: "active",
      severity: latest.severity || "medium",
      title: latest.title || latest.detail || "Community road report",
      description: latest.detail || "",
      raw: latest,
      lat: latest.lat ?? latest.latitude ?? latest.rawLat,
      lng: latest.lng ?? latest.lon ?? latest.longitude ?? latest.rawLng,
      area: latest.location_name || latest.area || latest.city || "",
      created_at: latest.submittedAt,
      reports_count: incident.count,
      age_minutes: latest.minutesAgo,
      report_type: latest.type
    });
  });
}

function getRouteIntelligenceSourceIncidents() {
  const localAndOfficial = getUnifiedIncidents();
  if (!routeWatchActivated) return localAndOfficial;
  const localSourceIds = new Set(localAndOfficial.map((incident) => String(incident?.raw?.id || "")).filter(Boolean));
  const remoteCommunity = getRouteWatchCommunitySourceIncidents().filter((incident) => !localSourceIds.has(String(incident?.raw?.id || "")));
  return [...localAndOfficial, ...remoteCommunity];
}

function getLiveProximityRouteIntelligenceIncidents(options = {}) {
  if (!routeWatchActivated) return [];
  const userAnchor = getGridlyActiveAwarenessUserLocationAnchor(options);
  if (!userAnchor) return [];
  const routeHazard = options.routeHazard || getRouteHazardAssessment();
  return getRouteIntelligenceSourceIncidents()
    .filter((incident) => String(incident?.status || "").toLowerCase() === "active")
    .filter((incident) => isIncidentRouteRelevant(incident, routeHazard))
    .map((incident) => ({
      ...incident,
      gridlyLiveProximity: buildGridlyActiveAwarenessProximityModel(incident, userAnchor)
    }))
    .filter((incident) => Number(incident.gridlyLiveProximity?.score || 0) > 0);
}

const GRIDLY_ROAD_CLUSTER_PREVIOUS_ROUNDING_DECIMALS = 3;
const GRIDLY_ROAD_CLUSTER_PREVIOUS_PRECISION_DEGREES = 0.001;
const GRIDLY_ROAD_CLUSTER_ROUNDING_DECIMALS = 4;
const GRIDLY_ROAD_CLUSTER_ROUNDING_PRECISION_DEGREES = 0.0001;
const GRIDLY_ROAD_CLUSTER_METHOD = "type_plus_tight_0.0001_degree_coordinate_bucket";

function getHazardClusterKey(hazard) {
  const rawLat = hazard?.lat ?? hazard?.latitude ?? hazard?.rawLat;
  const rawLng = hazard?.lng ?? hazard?.lon ?? hazard?.longitude ?? hazard?.rawLng;
  const latNum = Number(rawLat);
  const lngNum = Number(rawLng);
  const lat = Number.isFinite(latNum) ? latNum.toFixed(GRIDLY_ROAD_CLUSTER_ROUNDING_DECIMALS) : "na";
  const lng = Number.isFinite(lngNum) ? lngNum.toFixed(GRIDLY_ROAD_CLUSTER_ROUNDING_DECIMALS) : "na";
  return `${hazard?.type || "hazard"}-${lat}-${lng}`;
}

function gridlyRoadClusterCoordinateFromRecord(record = {}) {
  return gridlyCoordinateFromRecord(record)
    || gridlyCoordinateFromRecord(record?.finalPlacementCoordinate)
    || gridlyCoordinateFromRecord(record?.storedReportCoordinate)
    || gridlyCoordinateFromRecord(record?.activeHazardCoordinate)
    || null;
}

function gridlyRoadClusterRoundedCoordinateFromKey(clusterKey = "") {
  const match = String(clusterKey || "").match(/(-?\d+\.\d+)-(-?\d+\.\d+)$/);
  if (!match) return null;
  const lat = Number(match[1]);
  const lng = Number(match[2]);
  if (!Number.isFinite(lat) || !Number.isFinite(lng)) return null;
  return { lat, lng };
}

function gridlyEstimateRoadClusterRadiusMeters(latitude = LOCATION_DEFAULTS?.center?.[0] || 30, precisionDegrees = GRIDLY_ROAD_CLUSTER_ROUNDING_PRECISION_DEGREES) {
  const lat = Number.isFinite(Number(latitude)) ? Number(latitude) : 30;
  const precision = Number.isFinite(Number(precisionDegrees)) ? Number(precisionDegrees) : GRIDLY_ROAD_CLUSTER_ROUNDING_PRECISION_DEGREES;
  const latMeters = precision * 111320;
  const lngMeters = precision * 111320 * Math.cos(lat * Math.PI / 180);
  return Math.round(Math.sqrt((latMeters ** 2) + (lngMeters ** 2)) * 10) / 10;
}

function gridlyRoadClusterReportId(record = {}) {
  return String(record?.id || record?.report_id || record?.reportId || record?.incidentId || "").trim();
}

function gridlyRoadClusterReportTimeMs(record = {}) {
  const value = record?.submittedAt || record?.created_at || record?.createdAt || record?.updated_at || record?.updatedAt || 0;
  const ms = new Date(value).getTime();
  return Number.isFinite(ms) ? ms : 0;
}

function gridlyRoadClusterReportAgeMinutes(record = {}, nowMs = Date.now()) {
  const ms = gridlyRoadClusterReportTimeMs(record);
  if (!ms || ms > nowMs) return null;
  return Math.max(0, Math.round((nowMs - ms) / 60000));
}

function gridlyRoadClusterRoadName(record = {}) {
  return String(record?.roadName || record?.road_name || record?.street || record?.nearest_road || record?.location_name || record?.area || "Unknown road").trim() || "Unknown road";
}

function gridlyRoadClusterRoadSide(record = {}) {
  const text = [
    record?.roadSide,
    record?.road_side,
    record?.direction,
    record?.bearing,
    record?.laneDirection,
    record?.lane_direction,
    record?.description,
    record?.detail,
    record?.title,
    record?.roadName,
    record?.road_name
  ].map((value) => String(value || "").toLowerCase()).join(" ");
  if (/\b(northbound|north bound|nb)\b/.test(text)) return "northbound";
  if (/\b(southbound|south bound|sb)\b/.test(text)) return "southbound";
  if (/\b(eastbound|east bound|eb)\b/.test(text)) return "eastbound";
  if (/\b(westbound|west bound|wb)\b/.test(text)) return "westbound";
  if (/\b(left shoulder|inside shoulder|median)\b/.test(text)) return "inside_or_median";
  if (/\b(right shoulder|outside shoulder)\b/.test(text)) return "outside_shoulder";
  return "unknown";
}

function gridlyRoadClusterConfidenceRank(record = {}) {
  const text = String(record?.confidence || record?.source || "").toLowerCase();
  if (/official|txdot|moderator|trusted|system/.test(text)) return 3;
  if (/community|verified|confirm/.test(text)) return 2;
  return 1;
}

function gridlyClassifyRoadClusterHighZoomRisk(details = {}) {
  const maxDistance = Number(details.maxClusterDistanceMeters || 0);
  if (details.containsClearedReports || details.containsMultipleRoadSides || details.containsDividedRoadName || maxDistance >= 75) return "high";
  if (details.containsMultipleRoadNames || details.containsMultipleReportTypes || maxDistance >= 25 || Number(details.clusterMemberCount || 0) > 1) return "medium";
  return "low";
}

function gridlyBuildRoadClusterAudit(options = {}) {
  const nowMs = Number.isFinite(Number(options?.nowMs)) ? Number(options.nowMs) : Date.now();
  const sampleLimit = Math.max(1, Math.min(50, Number(options?.sampleLimit) || 12));
  const sourceHazards = Array.isArray(options?.hazards) ? options.hazards : [...gridlyDiagnosticArray(activeHazards), ...gridlyDiagnosticArray(recentlyClearedRoadHazards)];
  const sourceReports = Array.isArray(options?.reports) ? options.reports : gridlyDiagnosticArray(activeReports);
  const unifiedIncidents = Array.isArray(options?.unifiedIncidents)
    ? options.unifiedIncidents
    : (typeof getUnifiedIncidents === "function" ? getUnifiedIncidents() : []);
  const liveHazardIncidents = Array.isArray(options?.liveHazardIncidents)
    ? options.liveHazardIncidents
    : (typeof getLiveHazardIncidents === "function" ? getLiveHazardIncidents() : []);
  const renderedAudits = typeof unifiedIncidentLayer?.getLayers === "function"
    ? unifiedIncidentLayer.getLayers().map((layer) => {
      const audit = layer?.options?.gridlyPlacementAudit || {};
      const latLng = typeof layer?.getLatLng === "function" ? layer.getLatLng() : null;
      return { ...audit, incidentId: audit?.incidentId || layer?.options?.incidentId || "", renderedMarkerCoordinate: gridlyCoordinateFromRecord(latLng) || audit?.renderedMarkerCoordinate || null };
    })
    : [];
  const reportById = new Map(sourceReports.map((report) => [gridlyRoadClusterReportId(report), report]).filter(([id]) => id));
  const latitudeForEstimate = sourceHazards.map((hazard) => Number(gridlyRoadClusterCoordinateFromRecord(hazard)?.lat)).find(Number.isFinite) || LOCATION_DEFAULTS?.center?.[0] || 30;
  const estimatedClusterRadiusMeters = gridlyEstimateRoadClusterRadiusMeters(latitudeForEstimate);
  const previousEstimatedClusterRadiusMeters = gridlyEstimateRoadClusterRadiusMeters(latitudeForEstimate, GRIDLY_ROAD_CLUSTER_PREVIOUS_PRECISION_DEGREES);

  const sampleClusters = liveHazardIncidents.slice(0, sampleLimit).map((incident) => {
    const reports = Array.isArray(incident?.reports) ? incident.reports : sourceHazards.filter((hazard) => getHazardClusterKey(hazard) === incident?.key);
    const sortedReports = [...reports].sort((a, b) => gridlyRoadClusterReportTimeMs(b) - gridlyRoadClusterReportTimeMs(a));
    const representative = incident?.latestReport || sortedReports[0] || null;
    const representativeCoordinate = gridlyRoadClusterCoordinateFromRecord(representative);
    const clusterCoordinate = gridlyRoadClusterRoundedCoordinateFromKey(incident?.key);
    const roadIncidentId = `road-${incident?.key || "unknown"}`;
    const unified = unifiedIncidents.find((item) => String(item?.id || "") === roadIncidentId) || null;
    const rendered = renderedAudits.find((audit) => String(audit?.incidentId || "") === roadIncidentId) || gridlyFindRenderedMarkerPlacementAudit(roadIncidentId);
    const reportTypes = [...new Set(reports.map((report) => String(report?.type || report?.report_type || "unknown").toLowerCase()))];
    const roadNames = [...new Set(reports.map(gridlyRoadClusterRoadName).filter(Boolean))];
    const roadSides = [...new Set(reports.map(gridlyRoadClusterRoadSide).filter((side) => side && side !== "unknown"))];
    const containsClearedReports = reports.some(gridlyIsRoadClearedHazardRecord);
    const containsMultipleRoadNames = roadNames.length > 1;
    const containsMultipleRoadSides = roadSides.length > 1;
    const containsMultipleReportTypes = reportTypes.length > 1;
    const containsDividedRoadName = roadNames.some((name) => /\b(us\s*90|u\.?s\.?\s*90|tx\s*146|sh\s*146|state\s*highway\s*146|highway\s*146)\b/i.test(name));
    const distancesToRepresentative = reports.map((report) => gridlyCoordinateDeltaMeters(gridlyRoadClusterCoordinateFromRecord(report), representativeCoordinate)).filter((distance) => Number.isFinite(Number(distance)));
    const maxClusterDistanceMeters = distancesToRepresentative.length ? Math.max(...distancesToRepresentative) : 0;
    const highestConfidenceRank = Math.max(...reports.map(gridlyRoadClusterConfidenceRank), 0);
    const representativeRank = gridlyRoadClusterConfidenceRank(representative);
    const newestReport = sortedReports[0] || null;
    const representativeReportId = gridlyRoadClusterReportId(representative);
    const highZoomPlacementRisk = gridlyClassifyRoadClusterHighZoomRisk({
      clusterMemberCount: reports.length,
      maxClusterDistanceMeters,
      maxMemberDistanceMeters: maxClusterDistanceMeters,
      dividedRoadRisk: containsDividedRoadName || containsMultipleRoadSides || maxClusterDistanceMeters >= previousEstimatedClusterRadiusMeters * 0.25 ? "elevated" : "reduced",
      carriagewayRisk: containsMultipleRoadSides || maxClusterDistanceMeters >= 25 ? "elevated" : "reduced",
      containsClearedReports,
      containsMultipleRoadSides,
      containsMultipleRoadNames,
      containsMultipleReportTypes,
      containsDividedRoadName
    });

    const clusterMembers = reports.map((report) => {
      const reportId = gridlyRoadClusterReportId(report);
      const originalReport = reportById.get(reportId) || null;
      const originalReportCoordinate = gridlyRoadClusterCoordinateFromRecord(originalReport) || gridlyCoordinateFromRecord(report?.rawTapCoordinate || report?.reportCaptureCoordinate) || gridlyRoadClusterCoordinateFromRecord(report);
      const activeHazardCoordinate = gridlyRoadClusterCoordinateFromRecord(report);
      const distanceToRepresentativeMeters = gridlyCoordinateDeltaMeters(activeHazardCoordinate, representativeCoordinate);
      return {
        reportId: reportId || null,
        reportType: report?.type || report?.report_type || null,
        source: report?.source || null,
        confidence: report?.confidence || null,
        ageMinutes: gridlyRoadClusterReportAgeMinutes(report, nowMs),
        isCleared: gridlyIsRoadClearedHazardRecord(report),
        roadName: gridlyRoadClusterRoadName(report),
        roadSide: gridlyRoadClusterRoadSide(report),
        originalReportCoordinate,
        activeHazardCoordinate,
        clusterCoordinate,
        representativeCoordinate,
        unifiedIncidentCoordinate: gridlyRoadClusterCoordinateFromRecord(unified),
        renderedCoordinate: gridlyRoadClusterCoordinateFromRecord(rendered?.renderedMarkerCoordinate),
        distanceToRepresentativeMeters,
        clusterKey: incident?.key || null,
        trace: {
          report: originalReportCoordinate,
          activeHazards: activeHazardCoordinate,
          roadClustering: clusterCoordinate,
          representativeSelection: representativeCoordinate,
          unifiedIncidents: gridlyRoadClusterCoordinateFromRecord(unified),
          renderedMarker: gridlyRoadClusterCoordinateFromRecord(rendered?.renderedMarkerCoordinate)
        }
      };
    });

    return {
      clusterKey: incident?.key || null,
      clusterMemberCount: reports.length,
      clusterCoordinate,
      clusterMembers,
      representativeCoordinate,
      representativeCoordinateReason: incident?.representativeCoordinateReason || (reports.length > 1 ? "latest_report_coordinate_within_tight_0.0001_degree_hazard_cluster" : "single_report_coordinate"),
      representativeReportId: representativeReportId || null,
      representativeReportAge: gridlyRoadClusterReportAgeMinutes(representative, nowMs),
      representativeReportType: representative?.type || representative?.report_type || null,
      representativeIsNewestReport: representativeReportId && newestReport ? representativeReportId === gridlyRoadClusterReportId(newestReport) : null,
      representativeIsHighestConfidenceReport: representative ? representativeRank >= highestConfidenceRank : null,
      distanceToRepresentativeMeters: clusterMembers.map((member) => ({ reportId: member.reportId, meters: member.distanceToRepresentativeMeters })),
      maxClusterDistanceMeters,
      maxMemberDistanceMeters: maxClusterDistanceMeters,
      dividedRoadRisk: containsDividedRoadName || containsMultipleRoadSides || maxClusterDistanceMeters >= previousEstimatedClusterRadiusMeters * 0.25 ? "elevated" : "reduced",
      carriagewayRisk: containsMultipleRoadSides || maxClusterDistanceMeters >= 25 ? "elevated" : "reduced",
      containsClearedReports,
      containsMultipleRoadSides,
      containsMultipleRoadNames,
      containsMultipleReportTypes,
      containsDividedRoadName,
      roadNames,
      roadSides,
      reportTypes,
      unifiedIncidentCoordinate: gridlyRoadClusterCoordinateFromRecord(unified),
      renderedCoordinate: gridlyRoadClusterCoordinateFromRecord(rendered?.renderedMarkerCoordinate),
      highZoomPlacementRisk,
      highZoomPlacementRiskReasons: [
        containsDividedRoadName ? "known_divided_highway_name" : "",
        containsMultipleRoadSides ? "multiple_detected_road_sides" : "",
        containsClearedReports ? "cleared_report_in_cluster" : "",
        maxClusterDistanceMeters >= 75 ? "representative_far_from_member" : "",
        containsMultipleRoadNames ? "multiple_road_names" : "",
        containsMultipleReportTypes ? "multiple_report_types" : ""
      ].filter(Boolean)
    };
  });

  const highRiskClusters = sampleClusters.filter((cluster) => cluster.highZoomPlacementRisk === "high").length;
  const mediumRiskClusters = sampleClusters.filter((cluster) => cluster.highZoomPlacementRisk === "medium").length;
  const clusteredSamples = sampleClusters.filter((cluster) => cluster.clusterMemberCount > 1);
  const largestClusterMemberCount = sampleClusters.reduce((max, cluster) => Math.max(max, Number(cluster.clusterMemberCount || 0)), 0);
  const largestMaxMemberDistanceMeters = sampleClusters.reduce((max, cluster) => Math.max(max, Number(cluster.maxMemberDistanceMeters || cluster.maxClusterDistanceMeters || 0)), 0);
  const dividedRoadRisk = sampleClusters.some((cluster) => cluster.dividedRoadRisk === "elevated") ? "elevated_in_sample" : "reduced_by_tight_coordinate_bucket";
  const carriagewayRisk = sampleClusters.some((cluster) => cluster.carriagewayRisk === "elevated") ? "elevated_in_sample" : "reduced_by_tight_coordinate_bucket";

  return {
    clusteringEnabled: true,
    clusterPrecision: GRIDLY_ROAD_CLUSTER_ROUNDING_PRECISION_DEGREES,
    clusterMethod: GRIDLY_ROAD_CLUSTER_METHOD,
    clusterRoundingPrecision: GRIDLY_ROAD_CLUSTER_ROUNDING_PRECISION_DEGREES,
    clusterRoundingDecimals: GRIDLY_ROAD_CLUSTER_ROUNDING_DECIMALS,
    estimatedClusterRadiusMeters,
    previousClusterPrecision: GRIDLY_ROAD_CLUSTER_PREVIOUS_PRECISION_DEGREES,
    previousEstimatedClusterRadiusMeters,
    preChangeClusterRisk: "high: the former 0.001-degree bucket could span roughly " + previousEstimatedClusterRadiusMeters + "m diagonally near the sampled latitude, so opposite sides of divided roads or separate carriageways could share one key.",
    postChangeClusterRisk: "lower: active road hazards now use a 0.0001-degree bucket with an estimated diagonal of roughly " + estimatedClusterRadiusMeters + "m; duplicate reports at the same spot can still merge, while broad cross-road merges are less likely.",
    clusterMemberCount: largestClusterMemberCount,
    maxMemberDistanceMeters: largestMaxMemberDistanceMeters,
    representativeCoordinateReason: clusteredSamples.length ? "latest_report_coordinate_within_tight_0.0001_degree_hazard_cluster" : "single_report_coordinate_or_no_clustered_samples",
    dividedRoadRisk,
    carriagewayRisk,
    clusterKeyGeneration: "`${type}-${lat.toFixed(4)}-${lng.toFixed(4)}` for active road hazards; recently cleared rows continue to use `hazard_cleared-${coordinateKey}` and remain separated from active clusters.",
    distanceGrouping: "Option A selected for beta: a tighter 0.0001-degree coordinate bucket. It avoids broad 0.001-degree merges without adding a new road-geometry dependency or changing rail behavior.",
    representativeSelectionRules: "Each tight cluster sorts reports by submittedAt descending; the latest report remains the representative because the tighter bucket bounds representative drift to a small duplicate-report area.",
    suppressionRules: "Expired hazards and non-recent hazard_cleared rows are excluded. Active hazards sharing a cleared coordinate key are suppressed only when a recent clear is actually newer than the hazard.",
    dedupeRules: "renderUnifiedIncidents dedupes by unified incident id first; road clusters normally render one marker per road-${clusterKey} incident.",
    clearedHazardInteraction: "Recently cleared road rows are included as separate cleared clusters keyed by cleared coordinate; they do not become representatives for active clusters unless their type/key is explicitly the cleared cluster.",
    reviewedOptions: {
      optionA: "Selected: 0.0001 precision is the smallest beta-ready change and directly fixes broad rounded-cell clustering.",
      optionB: "Deferred: distance-based clustering would improve bucket-boundary behavior but adds more membership logic and tuning risk.",
      optionC: "Deferred: road-aware clustering needs reliable carriageway/side geometry that is not currently part of the report payload.",
      optionD: "Deferred: hybrid road/distance logic is likely best long term, but it is more complex than needed for this precision fix."
    },
    primaryQuestions: {
      whenRoadClusteringOccurs: "getLiveHazardIncidents groups filtered activeHazards before getUnifiedIncidents creates road unified incidents and before renderUnifiedIncidents renders markers.",
      coordinateRoundingUsed: GRIDLY_ROAD_CLUSTER_ROUNDING_PRECISION_DEGREES,
      effectiveClusteringRadiusMeters: estimatedClusterRadiusMeters,
      oppositeSidesCanEnterSameCluster: "Less likely; active road hazards now need matching type and matching 0.0001-degree rounded lat/lng instead of the former broad 0.001-degree cell.",
      separateCarriagewaysCanEnterSameCluster: "Less likely for typical divided carriageway separation; exact same-location duplicates still merge.",
      newerReportCanMoveRepresentativeCoordinate: "Only within the tighter active road hazard bucket; newest remains the representative to preserve existing dedupe behavior.",
      clearedReportCanBecomeRepresentativeCoordinate: "Only for the separate recently-cleared cluster; active hazard clusters filter cleared rows out or suppress matching active rows.",
      representativeAlwaysNewestReport: clusteredSamples.length ? clusteredSamples.every((cluster) => cluster.representativeIsNewestReport === true) : null,
      representativeAlwaysHighestConfidenceReport: clusteredSamples.length ? clusteredSamples.every((cluster) => cluster.representativeIsHighestConfidenceReport === true) : null,
      shouldClusteringDetermineHighZoomPlacement: highRiskClusters > 0 || mediumRiskClusters > 0 ? "Review recommended for sampled elevated-risk clusters, but the active road hazard bucket is now much tighter than the pre-change 0.001-degree key." : "Current samples are low risk under the tighter key."
    },
    dividedRoadReview: {
      routesChecked: ["US 90", "TX 146", "other divided highways inferred from road-side/direction text"],
      sampleMatches: sampleClusters.filter((cluster) => cluster.containsDividedRoadName || cluster.containsMultipleRoadSides),
      conclusion: "The tighter active-road key reduces accidental divided-road and carriageway merges without changing rail clustering, reporting payloads, or historical record validity."
    },
    sampleClusters,
    highZoomRiskSummary: { low: sampleClusters.filter((cluster) => cluster.highZoomPlacementRisk === "low").length, medium: mediumRiskClusters, high: highRiskClusters },
    recommendations: [
      "Use this audit at high zoom on suspected divided roads to compare each member's originalReportCoordinate with the representativeCoordinate and renderedCoordinate.",
      "Expect same-location duplicate reports to merge, but reports on opposite sides of divided roads to split unless their final coordinates are extremely close.",
      "If a sampled cluster still shows elevated dividedRoadRisk or carriagewayRisk, review the report finalPlacementCoordinate values before considering a future distance-based or road-aware clustering pass.",
      "Keep rail reporting, rail markers, TxDOT, and Supabase payload shape out of this road-cluster precision path."
    ]
  };
}

function gridlyRoadClusterAudit(options = {}) {
  const audit = gridlyBuildRoadClusterAudit(options);
  console.info("gridlyRoadClusterAudit", audit);
  return audit;
}

if (typeof window !== "undefined") {
  window.gridlyRoadClusterAudit = gridlyRoadClusterAudit;
}
exposeGridlyAuditHelper("gridlyRoadClusterAudit", gridlyRoadClusterAudit);

function gridlyBuildRoadClearedLifecycleTrace(options = {}) {
  const nowMs = Number.isFinite(Number(options?.nowMs)) ? Number(options.nowMs) : Date.now();
  const sourceHazards = Array.isArray(options?.hazards) ? options.hazards : [...gridlyDiagnosticArray(activeHazards), ...gridlyDiagnosticArray(recentlyClearedRoadHazards)];
  const sourceReports = Array.isArray(options?.reports) ? options.reports : gridlyDiagnosticArray(activeReports);
  const unifiedIncidents = Array.isArray(options?.unifiedIncidents)
    ? options.unifiedIncidents
    : (typeof getUnifiedIncidents === "function" ? getUnifiedIncidents() : []);
  const liveHazardIncidents = Array.isArray(options?.liveHazardIncidents)
    ? options.liveHazardIncidents
    : (typeof getLiveHazardIncidents === "function" ? getLiveHazardIncidents() : []);
  const roadClearedRows = sourceHazards.filter(gridlyIsRoadClearedHazardRecord);
  const recentlyClearedRows = roadClearedRows.filter((row) => gridlyIsRecentlyClearedRoadHazardRecord(row, nowMs));
  const clearedUnifiedIncidents = unifiedIncidents.filter((incident) => {
    const status = String(incident?.status || "").toLowerCase();
    const type = String(incident?.report_type || incident?.type || "").toLowerCase();
    return status === "cleared" || type === "hazard_cleared";
  });
  const roadClearedUnifiedIncidents = clearedUnifiedIncidents.filter((incident) => {
    const id = String(incident?.id || "").toLowerCase();
    const source = String(incident?.source || "").toLowerCase();
    const reportType = String(incident?.report_type || "").toLowerCase();
    return reportType === "hazard_cleared" || (id.startsWith("road-") && !/rail|txdot/.test(source));
  });
  const alertEligibleRows = roadClearedUnifiedIncidents.filter((incident) => String(incident?.status || "").toLowerCase() === "active");
  const historicalEligibleRows = roadClearedRows.filter((row, index) => gridlyClassifyHazardLifecycleFrameworkRecord({
    record: row,
    sourceKind: "activeHazards",
    index,
    sourceHazards,
    sourceReports,
    nowMs
  }).historicalEligible);
  const recentClearIndex = gridlyBuildRecentRoadClearIndex(sourceHazards, nowMs);
  const suppressedActiveHazards = sourceHazards.filter((row) => gridlyRoadHazardSuppressedByRecentClear(row, recentClearIndex, nowMs));
  const scenarioTypes = ["flooding", "road_closed", "crash", "debris", "disabled_vehicle", "traffic_backup"];
  return {
    roadClearedLifecycleTrace: {
      sourcePath: [
        "recentlyClearedRoadHazards receives normalized hazard_cleared rows from loadSharedReports() recent-clear read",
        "getLiveHazardIncidents() excludes hazard_cleared and recently_cleared rows from active generated road incidents",
        "getUnifiedIncidents() emits cleared-only road incidents from recentlyClearedRoadHazards when the clear is the latest credible lifecycle event",
        "Alerts keep cleared unified incidents out of active eligibility; Recently Cleared may still read cleared rows by age_minutes",
        "gridlyHazardLifecycleFramework/gridlyHistoricalIntelligenceAudit mark cleared road rows historical-eligible without active treatment"
      ],
      sourceCounts: {
        activeHazards: sourceHazards.length,
        activeReports: sourceReports.length,
        roadClearedRows: roadClearedRows.length,
        recentlyClearedRows: recentlyClearedRows.length,
        liveHazardIncidents: liveHazardIncidents.length,
        roadClearedUnifiedIncidents: roadClearedUnifiedIncidents.length,
        suppressedActiveHazardsAtClearedLocations: suppressedActiveHazards.length
      },
      sampleTraces: scenarioTypes.map((type) => ({
        hazardType: type,
        lifecycle: ["Reported", "Cleared", `Recently Cleared <= ${RECENTLY_CLEARED_WINDOW_MINUTES} minutes`, "Historical Intelligence eligible"],
        activeHazardTreatment: "stops after a newer hazard_cleared row at the same rounded road location",
        routeImpactTreatment: "cleared unified incident is informational, not active route-impacting"
      })),
      detectedRows: roadClearedRows.slice(0, 6).map((row) => ({
        id: row?.id || null,
        type: row?.type || row?.report_type || null,
        ageMinutes: gridlyRoadClearedAgeMinutes(row, nowMs),
        recentlyCleared: gridlyIsRecentlyClearedRoadHazardRecord(row, nowMs),
        coordinateKey: gridlyRoadClearedCoordinateKey(row),
        historicalEligible: gridlyClassifyHazardLifecycleFrameworkRecord({ record: row, sourceKind: "activeHazards", sourceHazards, sourceReports, nowMs }).historicalEligible
      }))
    },
    roadClearedWriteDetected: roadClearedRows.length > 0,
    roadClearedUnifiedIncidentDetected: roadClearedUnifiedIncidents.length > 0,
    roadClearedAlertEligible: alertEligibleRows.length > 0,
    roadClearedHistoricalEligible: historicalEligibleRows.length > 0,
    recentlyClearedVisibilityWindow: RECENTLY_CLEARED_WINDOW_MINUTES,
    roadClearedFilteringFindings: [
      "Previous active-alert eligibility could count cleared unified road incidents inside the recent-clear window.",
      "Current getLiveHazardIncidents() only returns active lifecycle rows; latest recently cleared road rows are kept separately for Recently Cleared and suppress older active rows by incident key, road cluster, or rounded coordinate plus hazard type.",
      "Expired hazard_cleared rows can still be loaded by the recent-clear read path for the visibility window, without changing Supabase writes.",
      "Rail cleared paths are not modified by this road-only lifecycle trace."
    ],
    recommendedLifecyclePath: "Reported road hazard -> hazard_cleared row -> cleared unified road incident -> Recently Cleared for 90 minutes -> Historical Intelligence eligible; never active once cleared."
  };
}



function gridlyReadCachedTxdotRows() {
  if (typeof window === "undefined") return [];
  const serviceRows = typeof window.gridlyTxdot?.getRoadConditions === "function"
    ? window.gridlyTxdot.getRoadConditions()
    : null;
  if (Array.isArray(serviceRows)) return serviceRows;
  return Array.isArray(window.gridlyExternalRoadConditions) ? window.gridlyExternalRoadConditions : [];
}

function gridlyTxdotRowHasFiniteCoordinates(row = {}) {
  const lat = Number(row?.lat ?? row?.latitude ?? row?.rawLat);
  const lng = Number(row?.lng ?? row?.lon ?? row?.longitude ?? row?.rawLng);
  return Number.isFinite(lat) && Number.isFinite(lng);
}

function gridlyTxdotIsConstructionRow(row = {}) {
  const text = [
    row?.source,
    row?.sourceType,
    row?.type,
    row?.category,
    row?.condition,
    row?.title,
    row?.headline,
    row?.description,
    row?.summary
  ].map((value) => String(value || "").toLowerCase()).join(" ");
  return /construct|maintenance|lane closure|work zone|road work|utility work/.test(text);
}

function gridlyBuildTxdotUnifiedIncident(row = {}, options = {}) {
  const lat = Number(row?.lat ?? row?.latitude ?? row?.rawLat);
  const lng = Number(row?.lng ?? row?.lon ?? row?.longitude ?? row?.rawLng);
  if (!Number.isFinite(lat) || !Number.isFinite(lng)) return null;

  const isConstruction = Boolean(options.construction);
  const rawId = String(row?.id || row?.incidentId || row?.reportId || row?.GLOBALID || `${lat.toFixed(5)}-${lng.toFixed(5)}`).trim();
  const idPrefix = isConstruction ? "txdot-construction" : "txdot";
  const safeRawId = rawId.replace(/^txdot-construction-/i, "").replace(/^txdot-/i, "") || `${lat.toFixed(5)}-${lng.toFixed(5)}`;
  const roadName = safeDisplayText(row?.roadName || row?.routeNameDisplay || row?.routeName || row?.roadway, "Roadway");
  const rowTitle = safeDisplayText(row?.title || row?.headline, "");
  const condition = safeDisplayText(row?.type || row?.category || row?.condition, isConstruction ? "construction" : "incident");
  const category = isConstruction ? "construction" : normalizeGridlyTxdotVisualCategory(condition, { ...row, source: "txdot" });
  const title = rowTitle || `TxDOT ${condition} on ${roadName}`;
  const description = safeDisplayText(row?.description || row?.summary || row?.detail, title);
  const createdAt = row?.createdAt || row?.created_at || row?.startTime || row?.start_time || row?.reportedAt || null;
  const updatedAt = row?.updatedAt || row?.updated_at || row?.lastUpdated || row?.last_updated || createdAt || new Date(0).toISOString();
  const expiresAt = row?.expiresAt || row?.expires_at || row?.endTime || row?.end_time || null;

  return normalizeUnifiedIncident({
    id: `${idPrefix}-${safeRawId}`,
    source: "txdot",
    sourceType: "txdot",
    externalSource: "txdot",
    provider: "TxDOT",
    type: category,
    category,
    severity: getGridlyIncidentSeverity({ ...row, source: "txdot", description, title }, category),
    status: "active",
    title,
    headline: title,
    description,
    summary: description,
    lat,
    lng,
    latitude: lat,
    longitude: lng,
    roadName,
    area: roadName,
    routeName: row?.routeName || null,
    routeNameDisplay: row?.routeNameDisplay || null,
    direction: row?.direction || null,
    createdAt,
    updatedAt,
    expiresAt,
    endTime: row?.endTime || row?.end_time || expiresAt,
    created_at: createdAt || updatedAt,
    updated_at: updatedAt,
    expires_at: expiresAt,
    confidence: row?.confidence || "official",
    reports_count: 1,
    report_type: category,
    isExternal: true,
    isTxdot: true,
    rawTxdotId: row?.id || null
  });
}

function gridlyBuildTxdotUnifiedRows(options = {}) {
  const wantConstruction = Boolean(options.construction);
  return gridlyReadCachedTxdotRows()
    .filter((row) => row && String(row?.source || "").toLowerCase().includes("txdot"))
    .filter((row) => gridlyTxdotRowHasFiniteCoordinates(row))
    .filter((row) => gridlyTxdotIsConstructionRow(row) === wantConstruction)
    .map((row) => gridlyBuildTxdotUnifiedIncident(row, { construction: wantConstruction }))
    .filter(Boolean);
}

function futureTxdotIncidents() { return gridlyBuildTxdotUnifiedRows({ construction: false }); }
function futureTxdotConstruction() { return gridlyBuildTxdotUnifiedRows({ construction: true }); }
function futureFloodAlerts() { return []; }


function gridlyTxdotLayerAudit() {
  const toArray = (value) => Array.isArray(value) ? value : [];
  const toText = (value) => String(value || "").trim();
  const toLowerText = (value) => toText(value).toLowerCase();
  const numberOrNull = (value) => {
    const parsed = Number(value);
    return Number.isFinite(parsed) ? parsed : null;
  };
  const getLatLng = (item = {}) => {
    const lat = numberOrNull(item?.lat ?? item?.latitude ?? item?.rawLat);
    const lng = numberOrNull(item?.lng ?? item?.lon ?? item?.longitude ?? item?.rawLng);
    return { lat, lng, hasCoordinates: Number.isFinite(lat) && Number.isFinite(lng) };
  };
  const getTxdotId = (item = {}) => toText(item?.rawTxdotId || item?.id || item?.incidentId || item?.reportId || item?.GLOBALID);
  const isTxdotLike = (item = {}) => {
    const haystack = [item?.source, item?.sourceType, item?.externalSource, item?.provider, item?.id, item?.rawTxdotId, item?.title, item?.headline]
      .map(toLowerText)
      .join(" ");
    return /txdot|drive texas|drivetexas/.test(haystack);
  };
  const getTypeText = (item = {}) => [item?.type, item?.category, item?.condition, item?.report_type, item?.title, item?.description]
    .map(toLowerText)
    .join(" ");
  const isConstruction = (item = {}) => gridlyTxdotIsConstructionRow(item) || /txdot_construction|\bconstruction\b|maintenance|lane closure|work zone|road work|utility work/.test(getTypeText(item));
  const getTimestampMs = (item = {}) => {
    const candidate = item?.updated_at || item?.updatedAt || item?.created_at || item?.createdAt || item?.startTime || item?.start_time || item?.reportedAt;
    const parsed = candidate ? new Date(candidate).getTime() : Number.NaN;
    return Number.isFinite(parsed) ? parsed : null;
  };
  const getEndTimestampMs = (item = {}) => {
    const candidate = item?.expires_at || item?.expiresAt || item?.endTime || item?.end_time;
    const parsed = candidate ? new Date(candidate).getTime() : Number.NaN;
    return Number.isFinite(parsed) ? parsed : null;
  };
  const isDateFiltered = (item = {}) => {
    const endMs = getEndTimestampMs(item);
    if (!Number.isFinite(endMs)) return false;
    return endMs < Date.now();
  };
  const mapBounds = map && typeof map.getBounds === "function" ? map.getBounds() : null;
  const isInBounds = (item = {}) => {
    const { lat, lng, hasCoordinates } = getLatLng(item);
    if (!hasCoordinates || !mapBounds || typeof mapBounds.contains !== "function") return null;
    return Boolean(mapBounds.contains([lat, lng]));
  };
  const getVisibleDomTxdotMarkers = () => {
    if (typeof document === "undefined") return [];
    const markerNodes = Array.from(document.querySelectorAll([
      "#map .leaflet-marker-pane .gridly-hazard-marker",
      "#map .leaflet-marker-pane [data-visual-style^='txdot_']",
      "#map .gridly-marker-txdot-single",
      "#map .gridly-marker-txdot-corridor",
      "#map .gridly-marker-txdot-route-impact"
    ].join(", ")));
    const seen = new Set();
    return markerNodes.filter((node) => {
      if (!node || seen.has(node)) return false;
      seen.add(node);
      const style = toLowerText(node.dataset?.visualStyle);
      const className = toLowerText(node.className);
      const source = toLowerText(node.dataset?.incidentSource || node.closest?.(".leaflet-marker-icon")?.dataset?.incidentSource);
      const id = toLowerText(node.dataset?.incidentId || node.dataset?.id || node.closest?.(".leaflet-marker-icon")?.dataset?.incidentId);
      return style.startsWith("txdot_") || className.includes("txdot") || source.includes("txdot") || id.includes("txdot");
    }).filter((node) => {
      const iconNode = node.closest?.(".leaflet-marker-icon") || node;
      const style = typeof window !== "undefined" && window.getComputedStyle ? window.getComputedStyle(iconNode) : null;
      const rect = iconNode.getBoundingClientRect?.();
      return !style || (style.display !== "none" && style.visibility !== "hidden" && Number(style.opacity || 1) !== 0 && (!rect || (rect.width > 0 && rect.height > 0)));
    });
  };
  const rawRows = typeof window !== "undefined" && typeof window.gridlyTxdot?.getRawRoadConditions === "function"
    ? window.gridlyTxdot.getRawRoadConditions()
    : toArray(window?.gridlyTxdotRawRoadConditions);
  const normalizedRows = gridlyReadCachedTxdotRows().filter(isTxdotLike);
  const unifiedRows = (typeof getUnifiedIncidents === "function" ? getUnifiedIncidents() : []).filter(isTxdotLike);
  const activeUnifiedRows = unifiedRows.filter((incident) => toLowerText(incident?.status || "active") === "active");
  const normalizedIds = new Set(normalizedRows.map(getTxdotId).filter(Boolean));
  const unifiedIds = new Set(unifiedRows.map(getTxdotId).filter(Boolean));
  const normalizedWithoutCoordinates = normalizedRows.filter((row) => !getLatLng(row).hasCoordinates);
  const normalizedOutsideBounds = normalizedRows.filter((row) => getLatLng(row).hasCoordinates && isInBounds(row) === false);
  const normalizedSourceFiltered = gridlyReadCachedTxdotRows().filter((row) => row && !isTxdotLike(row));
  const unifiedStatusFiltered = unifiedRows.filter((row) => toLowerText(row?.status || "active") !== "active");
  const unifiedDateFiltered = unifiedRows.filter(isDateFiltered);
  const unifiedVisualStates = unifiedRows.map((incident) => ({ incident, visualState: getGridlyIncidentVisualState(incident) }));
  const markerCandidates = unifiedVisualStates.filter(({ incident, visualState }) => {
    const { hasCoordinates } = getLatLng(incident);
    return hasCoordinates && toLowerText(incident?.status || "active") === "active" && !isDateFiltered(incident) && visualState?.shouldRender !== false;
  });
  const markerFilteredByVisualState = unifiedVisualStates.filter(({ incident, visualState }) => getLatLng(incident).hasCoordinates && visualState?.shouldRender === false);
  const renderedLayerMarkers = (unifiedIncidentLayer && typeof unifiedIncidentLayer.getLayers === "function")
    ? unifiedIncidentLayer.getLayers().filter((layer) => isTxdotLike({
        source: layer?.options?.incidentSource,
        id: layer?.options?.incidentId,
        rawTxdotId: layer?.options?.incidentId
      }))
    : [];
  const visibleDomTxdotMarkers = getVisibleDomTxdotMarkers();
  const latestAlerts = toArray(window?.__gridlyLatestAlertsForRender);
  const alertCandidates = activeUnifiedRows.filter((incident) => {
    const { hasCoordinates } = getLatLng(incident);
    return hasCoordinates && !isDateFiltered(incident);
  });
  const alertRendered = latestAlerts.filter(isTxdotLike);
  const skippedByFilterBreakdown = {
    source: normalizedSourceFiltered.length,
    type: normalizedRows.filter((row) => !GRIDLY_NORMALIZED_INCIDENT_CATEGORIES.has(normalizeGridlyIncidentCategory({ ...row, source: "txdot" }))).length,
    status: unifiedStatusFiltered.length,
    date: unifiedDateFiltered.length,
    visualShouldRenderFalse: markerFilteredByVisualState.length,
    notInUnified: normalizedRows.filter((row) => {
      const id = getTxdotId(row);
      return id && !unifiedIds.has(id) && !unifiedIds.has(`txdot-${id}`) && !unifiedIds.has(`txdot-construction-${id}`);
    }).length
  };
  const blockers = [];
  if (!rawRows.length) blockers.push("No TxDOT raw rows are cached. Run await window.gridlyTxdot?.fetchRoadConditions?.() first and confirm the API key/fetch succeeds.");
  if (rawRows.length && !normalizedRows.length) blockers.push("TxDOT rows were fetched but no cached normalized rows were found.");
  if (normalizedRows.length && !unifiedRows.length) blockers.push("TxDOT rows are normalized but are not present in getUnifiedIncidents().");
  if (normalizedWithoutCoordinates.length) blockers.push(`${normalizedWithoutCoordinates.length} normalized TxDOT row(s) have no finite coordinates.`);
  if (normalizedOutsideBounds.length) blockers.push(`${normalizedOutsideBounds.length} normalized TxDOT row(s) are outside the current map bounds.`);
  if (unifiedRows.length && !markerCandidates.length) blockers.push("TxDOT rows are unified, but current visual-state eligibility marks every TxDOT marker as non-renderable.");
  if (markerFilteredByVisualState.length) blockers.push(`${markerFilteredByVisualState.length} unified TxDOT row(s) have visualState.shouldRender === false.`);
  if (markerCandidates.length && !renderedLayerMarkers.length && !visibleDomTxdotMarkers.length) blockers.push("TxDOT marker candidates exist, but no TxDOT markers are currently rendered in the Leaflet layer/DOM. Manual fetch does not trigger marker rerender.");
  if (renderedLayerMarkers.length && !visibleDomTxdotMarkers.length) blockers.push("TxDOT markers exist in the Leaflet layer but are not visible in the marker DOM.");
  if (alertCandidates.length && !alertRendered.length) blockers.push("TxDOT alert candidates exist, but no TxDOT rows are present in __gridlyLatestAlertsForRender.");
  const nextPatchRecommendation = !rawRows.length
    ? "Run the manual TxDOT fetch, then rerun this audit."
    : (!normalizedRows.length
      ? "Patch TxDOT normalization/cache handoff before touching rendering."
      : (!unifiedRows.length
        ? "Patch getUnifiedIncidents()/futureTxdotIncidents handoff so cached TxDOT rows become unified incidents."
        : (!markerCandidates.length
          ? "Patch TxDOT marker eligibility deliberately; current visual-state policy sets TxDOT shouldRender=false."
          : (!renderedLayerMarkers.length && !visibleDomTxdotMarkers.length
            ? "Patch a manual, non-startup rerender path after explicit TxDOT fetch; do not add startup fetches, polling, or activeHazards forcing."
            : (alertCandidates.length && !alertRendered.length
              ? "Patch the alert candidate-to-render pipeline for TxDOT without changing startup fetch behavior."
              : "TxDOT reaches the current rendered marker path; inspect visibility, styling, and alert surface separately.")))));

  return {
    txdotFetchedRows: rawRows.length,
    txdotNormalizedRows: normalizedRows.length,
    txdotUnifiedIncidents: unifiedRows.length,
    txdotIncidentCount: unifiedRows.filter((row) => !isConstruction(row)).length,
    txdotConstructionCount: unifiedRows.filter(isConstruction).length,
    markerCandidates: markerCandidates.length,
    markerRenderedCount: Math.max(renderedLayerMarkers.length, visibleDomTxdotMarkers.length),
    alertCandidates: alertCandidates.length,
    alertRenderedCount: alertRendered.length,
    skippedNoCoordinates: normalizedWithoutCoordinates.length,
    skippedByBounds: normalizedOutsideBounds.length,
    skippedByFilters: skippedByFilterBreakdown.source + skippedByFilterBreakdown.type + skippedByFilterBreakdown.status + skippedByFilterBreakdown.date + skippedByFilterBreakdown.visualShouldRenderFalse + skippedByFilterBreakdown.notInUnified,
    visibleTxdotMarkerSamples: visibleDomTxdotMarkers.slice(0, 5).map((node) => ({
      incidentId: node.dataset?.incidentId || node.closest?.(".leaflet-marker-icon")?.dataset?.incidentId || "",
      visualStyle: node.dataset?.visualStyle || "",
      lat: numberOrNull(node.dataset?.lat),
      lng: numberOrNull(node.dataset?.lng),
      className: toText(node.className).slice(0, 160)
    })),
    unifiedTxdotSamples: unifiedRows.slice(0, 5).map((incident) => {
      const { lat, lng, hasCoordinates } = getLatLng(incident);
      const visualState = getGridlyIncidentVisualState(incident);
      return {
        id: incident?.id || null,
        rawTxdotId: incident?.rawTxdotId || null,
        type: incident?.type || incident?.category || null,
        status: incident?.status || null,
        lat,
        lng,
        hasCoordinates,
        inBounds: isInBounds(incident),
        shouldRender: visualState?.shouldRender,
        markerStyle: visualState?.markerStyle,
        updatedAt: incident?.updated_at || incident?.updatedAt || null,
        expiresAt: incident?.expires_at || incident?.expiresAt || incident?.endTime || null
      };
    }),
    blockers,
    nextPatchRecommendation,
    details: {
      skippedByFilterBreakdown,
      activeUnifiedTxdotCount: activeUnifiedRows.length,
      markerLayerTxdotCount: renderedLayerMarkers.length,
      visibleDomTxdotCount: visibleDomTxdotMarkers.length,
      mapBoundsAvailable: Boolean(mapBounds),
      normalizedTxdotIdsMissingFromUnified: normalizedRows.filter((row) => {
        const id = getTxdotId(row);
        return id && !unifiedIds.has(id) && !unifiedIds.has(`txdot-${id}`) && !unifiedIds.has(`txdot-construction-${id}`);
      }).slice(0, 10).map(getTxdotId),
      normalizedTxdotIdsPresent: normalizedRows.filter((row) => normalizedIds.has(getTxdotId(row))).slice(0, 10).map(getTxdotId)
    }
  };
}

function gridlyRunTxdotLayerAudit() {
  const target = typeof window !== "undefined" ? window : globalThis;
  console.log("Gridly TxDOT layer audit started");

  const auditPromise = Promise.resolve()
    .then(async () => {
      const txdotService = target?.gridlyTxdot || null;
      if (!txdotService || typeof txdotService.fetchRoadConditions !== "function") {
        throw new Error("Gridly TxDOT layer audit cannot run because window.gridlyTxdot.fetchRoadConditions is unavailable.");
      }

      await txdotService.fetchRoadConditions();

      const auditFn = typeof target?.gridlyTxdotLayerAudit === "function"
        ? target.gridlyTxdotLayerAudit
        : (typeof gridlyTxdotLayerAudit === "function" ? gridlyTxdotLayerAudit : null);
      if (typeof auditFn !== "function") {
        throw new Error("Gridly TxDOT layer audit cannot run because window.gridlyTxdotLayerAudit is unavailable.");
      }

      const auditResult = auditFn();
      target.gridlyLastTxdotLayerAudit = auditResult;
      console.log(auditResult);
      return auditResult;
    })
    .catch((error) => {
      const auditError = {
        error: true,
        message: error instanceof Error ? error.message : String(error),
        timestamp: new Date().toISOString()
      };
      target.gridlyLastTxdotLayerAudit = auditError;
      console.error("Gridly TxDOT layer audit failed", error);
      console.log(auditError);
      return auditError;
    });

  return auditPromise;
}

if (typeof window !== "undefined") {
  window.gridlyTxdotLayerAudit = gridlyTxdotLayerAudit;
  window.gridlyLastTxdotLayerAudit = window.gridlyLastTxdotLayerAudit || null;
  window.gridlyRunTxdotLayerAudit = gridlyRunTxdotLayerAudit;
}

exposeGridlyAuditHelper("gridlyTxdotLayerAudit", gridlyTxdotLayerAudit);
exposeGridlyAuditHelper("gridlyRunTxdotLayerAudit", gridlyRunTxdotLayerAudit);

function mapRailReportType(type) {
  if (type === "blocked") return "rail_blocked";
  if (type === "heavy") return "rail_delay";
  if (type === "cleared") return "rail_cleared";
  return "rail_delay";
}

function mapRoadHazardType(type) {
  const map = { crash: "wreck", flooding: "flooding",
  ice: "ice", construction: "construction", debris: "debris", road_closed: "closure", disabled_vehicle: "disabled_vehicle", traffic_backup: "traffic_backup", other_hazard: "other_hazard", hazard_cleared: "cleared" };
  return map[type] || "debris";
}

function normalizeUnifiedIncident(base) {
  return { ...base, updated_at: base.updated_at || base.created_at, confidence: base.confidence || "community", reports_count: Number(base.reports_count || 1) };
}


function gridlyCoordinateFromRecord(record = {}) {
  const lat = Number(record?.lat ?? record?.latitude ?? record?.rawLat);
  const lng = Number(record?.lng ?? record?.lon ?? record?.longitude ?? record?.rawLng);
  if (!Number.isFinite(lat) || !Number.isFinite(lng)) return null;
  return { lat, lng };
}

function gridlyCoordinateDeltaMeters(a, b) {
  if (!a || !b) return null;
  const lat1 = Number(a.lat);
  const lng1 = Number(a.lng);
  const lat2 = Number(b.lat);
  const lng2 = Number(b.lng);
  if (![lat1, lng1, lat2, lng2].every(Number.isFinite)) return null;
  const earthRadiusMeters = 6371000;
  const toRad = (value) => value * Math.PI / 180;
  const dLat = toRad(lat2 - lat1);
  const dLng = toRad(lng2 - lng1);
  const h = Math.sin(dLat / 2) ** 2
    + Math.cos(toRad(lat1)) * Math.cos(toRad(lat2)) * Math.sin(dLng / 2) ** 2;
  return Math.round(earthRadiusMeters * 2 * Math.atan2(Math.sqrt(h), Math.sqrt(1 - h)) * 10) / 10;
}

function gridlyCoordinatesWithinMeters(a, b, toleranceMeters = 0.5) {
  const deltaMeters = gridlyCoordinateDeltaMeters(a, b);
  return Number.isFinite(Number(deltaMeters)) && Number(deltaMeters) <= toleranceMeters;
}

function gridlyLatestRoadIncidentForPlacementTrace() {
  const roadIncidents = typeof getUnifiedIncidents === "function"
    ? getUnifiedIncidents().filter((incident) => String(incident?.id || "").startsWith("road-"))
    : [];
  return roadIncidents
    .slice()
    .sort((a, b) => new Date(b?.created_at || b?.updated_at || 0).getTime() - new Date(a?.created_at || a?.updated_at || 0).getTime())[0] || null;
}

function gridlyClassifyPlacementSource({ tapCoordinate, projectionCoordinate, snappedCoordinate, finalPlacementCoordinate, placementMode }) {
  if (projectionCoordinate && gridlyCoordinatesWithinMeters(finalPlacementCoordinate, projectionCoordinate)) return "projected_point";
  if (snappedCoordinate && gridlyCoordinatesWithinMeters(finalPlacementCoordinate, snappedCoordinate)) return "snapped_point";
  if (tapCoordinate && gridlyCoordinatesWithinMeters(finalPlacementCoordinate, tapCoordinate)) return "raw_tap";
  if (["raw_tap", "raw_tap_preserved_user_intent", "tap_preserved_near_road", "snap_rejected_divided_road_risk", "snap_rejected_too_far", "raw_tap_no_candidate", "raw_tap_projection_missing", "raw_tap_snap_too_far", "raw_tap_divided_road_ambiguous"].includes(placementMode)) return "raw_tap";
  if (placementMode === "projected_point_used") return "projected_point";
  if (placementMode === "road_snapped") return projectionCoordinate ? "projected_point" : "snapped_point";
  return "unknown";
}

function gridlyFindRenderedMarkerPlacementAudit(incidentId) {
  const layers = typeof unifiedIncidentLayer?.getLayers === "function" ? unifiedIncidentLayer.getLayers() : [];
  const targetId = String(incidentId || "");
  for (const layer of layers) {
    const audit = layer?.options?.gridlyPlacementAudit || null;
    const layerIncidentId = String(audit?.incidentId || layer?.options?.incidentId || "");
    if (targetId && layerIncidentId && layerIncidentId !== targetId) continue;
    const latLng = typeof layer?.getLatLng === "function" ? layer.getLatLng() : null;
    const renderedMarkerCoordinate = gridlyCoordinateFromRecord(latLng) || audit?.renderedMarkerCoordinate || null;
    return { ...(audit || {}), renderedMarkerCoordinate };
  }
  return null;
}


function gridlyRoadwayAuditNormalizeText(value) {
  return String(value ?? "").trim();
}

function gridlyRoadwayAuditLower(value) {
  return gridlyRoadwayAuditNormalizeText(value).toLowerCase();
}

function gridlyRoadwayAuditFeatureNameValues(feature) {
  const props = feature?.properties || {};
  return [
    props.name,
    props.ref,
    props.highway,
    props.route,
    props.route_name,
    props.routeName,
    props.alt_name,
    props.official_name,
    props["tiger:name_base"],
    props["tiger:name_base_1"],
    props["tiger:name_base_2"],
    props["tiger:name_base_3"]
  ].map(gridlyRoadwayAuditNormalizeText).filter(Boolean);
}

function gridlyRoadwayAuditFeatureText(feature) {
  const props = feature?.properties || {};
  return gridlyRoadwayAuditLower([...gridlyRoadwayAuditFeatureNameValues(feature), props["@id"]].join(" | "));
}

function gridlyRoadwayAuditMatchesCorridor(feature, corridorKey) {
  const text = gridlyRoadwayAuditFeatureText(feature);
  if (corridorKey === "us90") return /\b(us\s*90|us-90|u\.?s\.?\s*highway\s*90|united\s+states\s+highway\s+90|highway\s+90)\b/.test(text);
  if (corridorKey === "tx146") return /\b(tx\s*146|tx-146|sh\s*146|state\s+highway\s+146|highway\s+146)\b/.test(text);
  return false;
}

function gridlyRoadwayAuditToArray(value) {
  if (Array.isArray(value)) return value;
  if (value == null) return [];
  if (value?.type === "FeatureCollection" && Array.isArray(value.features)) return value.features;
  if (value && typeof value === "object" && value.type !== "Feature" && !value.geometry) {
    const values = Object.values(value);
    if (values.length && values.every((entry) => entry && typeof entry === "object")) return values;
  }
  return [];
}

function gridlyRoadwayAuditCountValues(values) {
  return values.reduce((counts, value) => {
    const key = gridlyRoadwayAuditNormalizeText(value);
    if (key) counts[key] = (counts[key] || 0) + 1;
    return counts;
  }, {});
}

function gridlyRoadwayAuditRound(value, digits = 3) {
  const number = Number(value);
  if (!Number.isFinite(number)) return null;
  const factor = 10 ** digits;
  return Math.round(number * factor) / factor;
}

function gridlyRoadwayAuditMilesToMeters(value) {
  const number = Number(value);
  return Number.isFinite(number) ? gridlyRoadwayAuditRound(number * 1609.344, 1) : null;
}

function gridlyRoadwayAuditFeatureCenter(feature) {
  const segments = flattenRoadGeometrySegments(feature?.geometry);
  if (!segments.length) return null;
  const points = [];
  segments.forEach((segment) => {
    points.push([segment.startLat, segment.startLng], [segment.endLat, segment.endLng]);
  });
  const totals = points.reduce((acc, point) => ({ lat: acc.lat + point[0], lng: acc.lng + point[1] }), { lat: 0, lng: 0 });
  return { lat: totals.lat / points.length, lng: totals.lng / points.length };
}

function gridlyRoadwayAuditFeatureBearing(feature) {
  const segments = flattenRoadGeometrySegments(feature?.geometry).filter((segment) => {
    return haversineDistance(segment.startLat, segment.startLng, segment.endLat, segment.endLng) > 0.0005;
  });
  if (!segments.length) return null;
  const middle = segments[Math.floor(segments.length / 2)];
  return gridlyRoadBearingDegrees(middle.startLat, middle.startLng, middle.endLat, middle.endLng);
}

function gridlyRoadwayAuditSampleFeature(feature) {
  const props = feature?.properties || {};
  const bearing = gridlyRoadwayAuditFeatureBearing(feature);
  const center = gridlyRoadwayAuditFeatureCenter(feature);
  return {
    id: props["@id"] || props.id || null,
    geometryType: feature?.geometry?.type || null,
    name: props.name || null,
    ref: props.ref || null,
    highway: props.highway || null,
    oneway: props.oneway || null,
    lanes: props.lanes || null,
    lanesForward: props["lanes:forward"] || null,
    lanesBackward: props["lanes:backward"] || null,
    tigerSeparated: props["tiger:separated"] || null,
    placement: props.placement || null,
    bearing,
    inferredDirection: gridlyInferCardinalRoadDirection(bearing),
    center: center ? { lat: gridlyRoadwayAuditRound(center.lat, 6), lng: gridlyRoadwayAuditRound(center.lng, 6) } : null
  };
}

function gridlyRoadwayAuditFieldCandidates(features, patterns) {
  const counts = {};
  features.forEach((feature) => {
    Object.keys(feature?.properties || {}).forEach((field) => {
      if (patterns.some((pattern) => pattern.test(field))) counts[field] = (counts[field] || 0) + 1;
    });
  });
  return Object.entries(counts)
    .sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]))
    .map(([field, count]) => ({ field, count }));
}

function gridlyRoadwayAuditFindParallelCandidates(features, maxPairs = 8) {
  const candidates = [];
  const sampled = features.slice(0, 220);
  for (let i = 0; i < sampled.length; i += 1) {
    const a = sampled[i];
    const centerA = gridlyRoadwayAuditFeatureCenter(a);
    const bearingA = gridlyRoadwayAuditFeatureBearing(a);
    const namesA = new Set(gridlyRoadwayAuditFeatureNameValues(a).map(gridlyRoadwayAuditLower));
    if (!centerA || !Number.isFinite(Number(bearingA)) || !namesA.size) continue;
    for (let j = i + 1; j < sampled.length; j += 1) {
      const b = sampled[j];
      const centerB = gridlyRoadwayAuditFeatureCenter(b);
      const bearingB = gridlyRoadwayAuditFeatureBearing(b);
      if (!centerB || !Number.isFinite(Number(bearingB))) continue;
      const sharedName = gridlyRoadwayAuditFeatureNameValues(b).map(gridlyRoadwayAuditLower).find((name) => namesA.has(name));
      if (!sharedName) continue;
      const distanceMeters = haversineDistance(centerA.lat, centerA.lng, centerB.lat, centerB.lng) * 1609.344;
      const bearingDifference = gridlyBearingDifferenceDegrees(bearingA, bearingB);
      if (distanceMeters >= 8 && distanceMeters <= 90 && Number.isFinite(bearingDifference) && bearingDifference <= 25) {
        candidates.push({
          sharedName,
          distanceMeters: gridlyRoadwayAuditRound(distanceMeters, 1),
          bearingDifferenceDegrees: gridlyRoadwayAuditRound(bearingDifference, 1),
          first: gridlyRoadwayAuditSampleFeature(a),
          second: gridlyRoadwayAuditSampleFeature(b)
        });
      }
    }
  }
  return candidates.sort((a, b) => a.distanceMeters - b.distanceMeters).slice(0, maxPairs);
}

function gridlyRoadwayAuditAssessCorridor(label, corridorKey) {
  const features = Array.isArray(roadwaySegmentFeatures) ? roadwaySegmentFeatures.filter((feature) => gridlyRoadwayAuditMatchesCorridor(feature, corridorKey)) : [];
  const geometryTypeCount = gridlyRoadwayAuditCountValues(features.map((feature) => feature?.geometry?.type));
  const roadNameVariants = gridlyRoadwayAuditCountValues(features.flatMap(gridlyRoadwayAuditFeatureNameValues));
  const bearingSamples = features.map(gridlyRoadwayAuditSampleFeature).filter((sample) => Number.isFinite(Number(sample.bearing))).slice(0, 12);
  const duplicateParallelSegmentCandidates = gridlyRoadwayAuditFindParallelCandidates(features, 8);
  const hasOneWayPairs = features.filter((feature) => gridlyRoadwayAuditLower(feature?.properties?.oneway) === "yes").length >= 2;
  const hasMultiLaneBidirectionalCenterline = features.some((feature) => {
    const props = feature?.properties || {};
    return gridlyRoadwayAuditLower(props.oneway) !== "yes" && (Number(props.lanes) >= 3 || props["lanes:forward"] || props["lanes:backward"] || props["lanes:both_ways"]);
  });
  const separateCarriagewaysAppearPresent = hasOneWayPairs || duplicateParallelSegmentCandidates.length > 0;
  const appearsCenterlineOnly = features.length > 0 && !separateCarriagewaysAppearPresent && hasMultiLaneBidirectionalCenterline;
  const bearingComputable = bearingSamples.length > 0;
  const confidenceLevel = !features.length ? "none" : (separateCarriagewaysAppearPresent && bearingComputable ? "medium" : (bearingComputable ? "low" : "none"));
  const directionalLabelsCanBeInferredSafely = Boolean(separateCarriagewaysAppearPresent && bearingComputable && confidenceLevel !== "low");
  const readiness = !features.length
    ? "no_geometry_loaded"
    : (directionalLabelsCanBeInferredSafely ? "usable_with_caution" : "insufficient_geometry");
  return {
    road: label,
    directionalReadiness: readiness,
    segmentCount: features.length,
    geometryTypeCount,
    roadNameVariants,
    bearingSamples,
    parallelCandidateDistanceMeters: duplicateParallelSegmentCandidates.map((candidate) => candidate.distanceMeters),
    duplicateParallelSegmentCandidates,
    appearsCenterlineOnly,
    separateCarriagewaysAppearPresent,
    directionalLabelsCanBeInferredSafely,
    confidenceLevel,
    assessment: !features.length
      ? "No matching local roadway geometry is loaded for this corridor."
      : (directionalLabelsCanBeInferredSafely
        ? "Local geometry includes computable bearings and probable separate carriageway/parallel candidates, but this remains audit-only without authoritative carriageway direction metadata."
        : "Local geometry can identify the corridor and usually compute bearings, but it is not sufficient to safely publish directional/carriageway labels by itself.")
  };
}

function gridlyRoadwayGeometryCapabilityAudit() {
  const features = Array.isArray(roadwaySegmentFeatures) ? roadwaySegmentFeatures : [];
  const loadedFeatures = roadwayDatasetLoaded ? features : [];
  const geometryTypes = gridlyRoadwayAuditCountValues(loadedFeatures.map((feature) => feature?.geometry?.type));
  const roadNameFieldCandidates = gridlyRoadwayAuditFieldCandidates(loadedFeatures, [/name/i, /^ref$/i, /route/i, /highway/i]);
  const directionFieldCandidates = gridlyRoadwayAuditFieldCandidates(loadedFeatures, [/direction/i, /bearing/i, /heading/i, /forward/i, /backward/i, /prefix/i, /suffix/i]);
  const oneWayFieldCandidates = gridlyRoadwayAuditFieldCandidates(loadedFeatures, [/oneway/i, /one_way/i]);
  const bearingFieldCandidates = gridlyRoadwayAuditFieldCandidates(loadedFeatures, [/bearing/i, /heading/i, /azimuth/i]);
  const carriagewayFieldCandidates = gridlyRoadwayAuditFieldCandidates(loadedFeatures, [/carriage/i, /separat/i, /divider/i, /median/i, /placement/i, /^lanes/i, /turn:lanes/i]);
  const bearingAvailable = bearingFieldCandidates.length > 0;
  const bearingComputable = loadedFeatures.some((feature) => Number.isFinite(Number(gridlyRoadwayAuditFeatureBearing(feature))));
  const carriagewayMetadataAvailable = carriagewayFieldCandidates.some((entry) => /carriage|separat|divider|median|placement/i.test(entry.field));
  const dividedRoadRepresentationAvailable = loadedFeatures.some((feature) => gridlyRoadwayAuditLower(feature?.properties?.oneway) === "yes") || carriagewayMetadataAvailable;
  const sampleRoadSegments = loadedFeatures.slice(0, 10).map(gridlyRoadwayAuditSampleFeature);
  const sampleUs90Segments = loadedFeatures.filter((feature) => gridlyRoadwayAuditMatchesCorridor(feature, "us90")).slice(0, 10).map(gridlyRoadwayAuditSampleFeature);
  const sampleTx146Segments = loadedFeatures.filter((feature) => gridlyRoadwayAuditMatchesCorridor(feature, "tx146")).slice(0, 10).map(gridlyRoadwayAuditSampleFeature);
  const estimatedBearingSamples = loadedFeatures.map(gridlyRoadwayAuditSampleFeature).filter((sample) => Number.isFinite(Number(sample.bearing))).slice(0, 20);
  const us90GeometryAssessment = gridlyRoadwayAuditAssessCorridor("US 90", "us90");
  const tx146GeometryAssessment = gridlyRoadwayAuditAssessCorridor("TX 146", "tx146");
  const duplicateParallelSegmentCandidates = gridlyRoadwayAuditFindParallelCandidates(loadedFeatures, 12);
  const target = typeof window !== "undefined" ? window : globalThis;
  const rawTxdotRows = typeof target?.gridlyTxdot?.getRawRoadConditions === "function" ? target.gridlyTxdot.getRawRoadConditions() : gridlyRoadwayAuditToArray(target?.gridlyTxdotRawRoadConditions);
  const normalizedTxdotRows = typeof gridlyReadCachedTxdotRows === "function" ? gridlyReadCachedTxdotRows() : [];
  const txdotRows = [...gridlyRoadwayAuditToArray(rawTxdotRows), ...gridlyRoadwayAuditToArray(normalizedTxdotRows)];
  const txdotHasGeometry = txdotRows.some((row) => row?.__geometry?.type || row?.geometry?.type);
  const txdotHasLineGeometry = txdotRows.some((row) => [row?.__geometry?.type, row?.geometry?.type].includes("LineString") || [row?.__geometry?.type, row?.geometry?.type].includes("MultiLineString"));
  const txdotHasDirection = txdotRows.some((row) => row?.travel_direction || row?.travelDirection || row?.direction);
  const routeLatLngs = typeof savedRouteLayer?.getLatLngs === "function" ? (savedRouteLayer.getLatLngs() || []) : [];
  const routeGeometryAvailable = Array.isArray(routeLatLngs) && routeLatLngs.length >= 2;
  const localLoaded = Boolean(roadwayDatasetLoaded && loadedFeatures.length);
  const missingData = [];
  if (!localLoaded) missingData.push("local roadway segment geometry not loaded");
  if (!bearingAvailable) missingData.push("authoritative bearing fields on local roadway segments");
  if (!carriagewayMetadataAvailable) missingData.push("explicit carriageway/side-of-road metadata");
  if (!directionFieldCandidates.some((entry) => /direction/i.test(entry.field))) missingData.push("explicit EB/WB/NB/SB direction metadata on local roadway segments");
  if (!txdotHasLineGeometry) missingData.push("retained TxDOT LineString/MultiLineString geometry in normalized incident cache");
  if (!txdotHasDirection) missingData.push("observed/current TxDOT travel_direction values for geometry validation");
  const sourceComparison = {
    localRoadwaySegments: {
      loaded: localLoaded,
      source: ROADWAY_SEGMENTS_URL,
      roadNameSupport: roadNameFieldCandidates.length ? "yes_name_ref_highway_fields" : "missing",
      bearingSupport: bearingComputable ? "computable_from_linestring_coordinates" : "missing",
      directionSupport: directionFieldCandidates.some((entry) => /direction/i.test(entry.field)) ? "limited_name_direction_fields" : "no_explicit_direction",
      carriagewaySupport: dividedRoadRepresentationAvailable ? "partial_oneway_or_separation_tags" : "missing",
      sideOfRoadSupport: carriagewayMetadataAvailable ? "partial_metadata_not_validated" : "insufficient",
      betaUsability: localLoaded && bearingComputable ? "usable_with_caution_for_audit_only" : "insufficient"
    },
    osrmNearestCandidates: {
      loaded: Boolean(lastRoadSnapDebug?.nearestCandidates?.length || lastRoadSnapDebug?.osrmNearestCandidates?.length),
      roadNameSupport: "yes_when_nearest_response_has_name",
      bearingSupport: "not_retained_in_current_nearest_debug_path",
      directionSupport: "missing",
      carriagewaySupport: "missing",
      sideOfRoadSupport: "insufficient_point_snap_only",
      betaUsability: "insufficient_for_directional_labels"
    },
    txdotCachedCurrentGeometry: {
      loaded: txdotRows.length > 0,
      roadNameSupport: txdotRows.some((row) => row?.roadway || row?.roadName || row?.routeName || row?.route_name) ? "yes_when_rows_present" : "unknown_or_missing",
      bearingSupport: txdotHasLineGeometry ? "potential_if_full_geometry_retained" : "discarded_or_midpoint_only_today",
      directionSupport: txdotHasDirection ? "official_direction_present_in_some_rows" : "not_observed_in_current_cache",
      carriagewaySupport: "not_structured_in_current_normalized_cache",
      sideOfRoadSupport: "insufficient_without_retained_line_and_carriageway_metadata",
      betaUsability: txdotHasDirection ? "usable_with_caution_for_official_event_direction_only" : "insufficient"
    },
    routeGeometry: {
      loaded: routeGeometryAvailable,
      roadNameSupport: "missing_route_polyline_has_shape_not_road_names",
      bearingSupport: routeGeometryAvailable ? "computable_for_active_route_path" : "missing_when_no_active_route",
      directionSupport: "route_travel_direction_only_not_road_carriageway_direction",
      carriagewaySupport: "missing",
      sideOfRoadSupport: "insufficient",
      betaUsability: "not_suitable_for_roadway_intelligence_labels"
    }
  };
  const scoreParts = {
    localGeometryLoaded: localLoaded ? 20 : 0,
    lineGeometryPresent: Object.keys(geometryTypes).some((type) => /LineString/.test(type)) ? 20 : 0,
    roadNamesPresent: roadNameFieldCandidates.length ? 15 : 0,
    bearingComputable: bearingComputable ? 20 : 0,
    dividedRepresentationPartial: dividedRoadRepresentationAvailable ? 10 : 0,
    explicitDirectionMetadata: directionFieldCandidates.some((entry) => /direction/i.test(entry.field)) ? 5 : 0,
    carriagewayMetadata: carriagewayMetadataAvailable ? 5 : 0,
    txdotRetainedGeometry: txdotHasLineGeometry ? 5 : 0
  };
  const directionalReadinessScore = Object.values(scoreParts).reduce((sum, value) => sum + value, 0);
  const directionalReadiness = !localLoaded
    ? "no_geometry_loaded"
    : (directionalReadinessScore >= 85 && us90GeometryAssessment.directionalReadiness !== "insufficient_geometry" && tx146GeometryAssessment.directionalReadiness !== "insufficient_geometry"
      ? "ready_high_confidence"
      : (directionalReadinessScore >= 55 ? "usable_with_caution" : "insufficient_geometry"));
  const recommendation = directionalReadiness === "ready_high_confidence"
    ? "Use local roadway geometry only behind conservative validation against explicit direction/carriageway metadata; keep audit-only until live incident labeling is designed."
    : "Do not claim US 90 EB/WB or TX 146 NB/SB production support yet. Next required data is authoritative carriageway-aware roadway geometry with explicit direction/one-way semantics, plus retained TxDOT LineString geometry and travel_direction for validation.";
  const audit = {
    auditVersion: "V206.12-roadway-geometry-capability-audit",
    auditOnly: true,
    destructiveActionsTaken: false,
    geometrySourcesFound: [
      { source: "localRoadwaySegments", url: ROADWAY_SEGMENTS_URL, found: true },
      { source: "osrmNearestCandidates", url: OSRM_NEAREST_API, found: true },
      { source: "txdotCachedCurrentGeometry", found: txdotRows.length > 0 || Boolean(target?.gridlyTxdot) },
      { source: "routeGeometry", found: true }
    ],
    geometrySourcesLoaded: {
      localRoadwaySegments: localLoaded,
      osrmNearestCandidates: Boolean(sourceComparison.osrmNearestCandidates.loaded),
      txdotCachedCurrentGeometry: txdotRows.length > 0,
      routeGeometry: routeGeometryAvailable
    },
    roadSegmentFeatureCount: loadedFeatures.length,
    roadSegmentGeometryTypes: geometryTypes,
    roadNameFieldCandidates,
    directionFieldCandidates,
    oneWayFieldCandidates,
    bearingAvailable,
    bearingComputable,
    carriagewayMetadataAvailable,
    dividedRoadRepresentationAvailable,
    us90GeometryAssessment,
    tx146GeometryAssessment,
    sampleRoadSegments,
    sampleUs90Segments,
    sampleTx146Segments,
    estimatedBearingSamples,
    duplicateParallelSegmentCandidates,
    missingData,
    directionalReadiness,
    directionalReadinessScore,
    scoreParts,
    dataSourceComparison: sourceComparison,
    recommendation,
    guardrailConclusion: "Current local geometry can support audit bearing calculations and corridor identification. It should not be treated as high-confidence directional/carriageway reporting unless explicit direction, selected-segment reliability, and separated same-name carriageway candidates are all validated."
  };
  console.info("gridlyRoadwayGeometryCapabilityAudit", audit);
  return audit;
}

if (typeof window !== "undefined") {
  window.gridlyRoadwayGeometryCapabilityAudit = gridlyRoadwayGeometryCapabilityAudit;
}
exposeGridlyAuditHelper("gridlyRoadwayGeometryCapabilityAudit", gridlyRoadwayGeometryCapabilityAudit);

function gridlyInferCardinalRoadDirection(bearing) {
  const value = Number(bearing);
  if (!Number.isFinite(value)) return null;
  const normalized = ((value % 360) + 360) % 360;
  if (normalized >= 315 || normalized < 45) return "NB";
  if (normalized >= 45 && normalized < 135) return "EB";
  if (normalized >= 135 && normalized < 225) return "SB";
  if (normalized >= 225 && normalized < 315) return "WB";
  return null;
}

const GRIDLY_DIRECTIONAL_PROVENANCE_AUDIT_VERSION = "V253";
const GRIDLY_DIRECTIONAL_PROVENANCE_READINESS_VALIDATION_VERSION = "V253.1";
const GRIDLY_DIRECTIONAL_PROVENANCE_CORRIDOR_PURITY_AUDIT_VERSION = "V253.2";
const GRIDLY_DIRECTIONAL_PROVENANCE_COUNTY_GEOMETRY_CONTAINMENT_AUDIT_VERSION = "V253.4";
const GRIDLY_DIRECTIONAL_PROVENANCE_PRIORITY_CORRIDOR_AUDIT_VERSION = "V253.5";
const GRIDLY_DIRECTIONAL_PROVENANCE_CORRIDORS = ["US 90", "TX 146", "TX 321", "FM 1960", "FM 1409"];
const GRIDLY_DIRECTIONAL_PROVENANCE_COUNTYWIDE_PRIORITY_CORRIDORS = ["US 90", "TX 146", "TX 321", "FM 1960", "FM 1409"];
const GRIDLY_DIRECTIONAL_PROVENANCE_COMMUNITY_CRITICAL_CORRIDORS = ["FM 1008", "FM 1011", "FM 563", "TX 105", "US 59", "I-69", "FM 2025", "FM 787"];
const GRIDLY_DIRECTIONAL_PROVENANCE_PRIORITY_CORRIDOR_COMMUNITIES = {
  "US 90": ["Liberty County countywide"],
  "TX 146": ["Liberty County countywide"],
  "TX 321": ["Liberty County countywide"],
  "FM 1960": ["Liberty County countywide"],
  "FM 1409": ["Liberty County countywide"],
  "FM 1008": ["Kenefick"],
  "FM 1011": ["Liberty County communities"],
  "FM 563": ["Liberty County communities"],
  "TX 105": ["Liberty County communities"],
  "US 59": ["Cleveland area", "Liberty County communities"],
  "I-69": ["Cleveland area", "Liberty County communities"],
  "FM 2025": ["Cleveland area", "Liberty County communities"],
  "FM 787": ["Liberty County communities"]
};

const GRIDLY_DIRECTIONAL_PROVENANCE_CORRIDOR_PATTERNS = {
  "US 90": /\b(us\s*90|us-90|u\.?s\.?\s*highway\s*90|united\s+states\s+highway\s+90|highway\s+90)\b/i,
  "TX 146": /\b(tx\s*146|tx-146|sh\s*146|state\s+highway\s+146|highway\s+146)\b/i,
  "TX 321": /\b(tx\s*321|tx-321|sh\s*321|state\s+highway\s+321|highway\s+321)\b/i,
  "FM 1960": /\b(fm\s*1960|fm-1960|farm\s*-?\s*to\s*-?\s*market(?:\s+road)?\s*1960|farm-to-market\s+road\s*1960)\b/i,
  "FM 1409": /\b(fm\s*1409|fm-1409|farm\s*-?\s*to\s*-?\s*market(?:\s+road)?\s*1409|farm-to-market\s+road\s*1409)\b/i,
  "FM 1008": /\b(fm\s*1008|fm-1008|farm\s*-?\s*to\s*-?\s*market(?:\s+road)?\s*1008|farm-to-market\s+road\s*1008)\b/i,
  "FM 1011": /\b(fm\s*1011|fm-1011|farm\s*-?\s*to\s*-?\s*market(?:\s+road)?\s*1011|farm-to-market\s+road\s*1011)\b/i,
  "FM 563": /\b(fm\s*563|fm-563|farm\s*-?\s*to\s*-?\s*market(?:\s+road)?\s*563|farm-to-market\s+road\s*563)\b/i,
  "TX 105": /\b(tx\s*105|tx-105|sh\s*105|state\s+highway\s+105|highway\s+105)\b/i,
  "US 59": /\b(us\s*59|us-59|u\.?s\.?\s*highway\s*59|united\s+states\s+highway\s+59|highway\s+59|eastex\s+freeway)\b/i,
  "I-69": /\b(i\s*-?\s*69|ih\s*-?\s*69|interstate\s+69|eastex\s+freeway)\b/i,
  "FM 2025": /\b(fm\s*2025|fm-2025|farm\s*-?\s*to\s*-?\s*market(?:\s+road)?\s*2025|farm-to-market\s+road\s*2025)\b/i,
  "FM 787": /\b(fm\s*787|fm-787|farm\s*-?\s*to\s*-?\s*market(?:\s+road)?\s*787|farm-to-market\s+road\s*787)\b/i
};
const GRIDLY_DIRECTIONAL_PROVENANCE_CORRIDOR_DEFAULTS = {
  "US 90": { orientation: "east-west", directions: ["EB", "WB"], authoritative: true },
  "TX 146": { orientation: "north-south", directions: ["NB", "SB"], authoritative: false },
  "TX 321": { orientation: "north-south", directions: ["NB", "SB"], authoritative: false },
  "FM 1960": { orientation: "east-west", directions: ["EB", "WB"], authoritative: true },
  "FM 1409": { orientation: "north-south", directions: ["NB", "SB"], authoritative: true }
};

function gridlyCreateEmptyDirectionalProvenance(overrides = {}) {
  return {
    directionSource: "none",
    cardinalDirection: null,
    bearing: null,
    confidence: "low",
    corridor: null,
    corridorDefaultUsed: false,
    dividedRoadRisk: false,
    fallbackReason: "insufficient_confidence",
    suppressed: true,
    ...overrides
  };
}

function gridlyNormalizeDirectionalConfidence(value) {
  const normalized = String(value || "").toLowerCase();
  if (normalized === "high" || normalized === "medium") return normalized;
  return "low";
}

function gridlyDirectionalProvenanceRoundBearing(value) {
  const bearing = Number(value);
  return Number.isFinite(bearing) ? gridlyRoadwayAuditRound(((bearing % 360) + 360) % 360, 1) : null;
}

function gridlyDirectionalProvenanceOfficialDirection(record = {}) {
  const candidates = [
    record?.direction,
    record?.travelDirection,
    record?.travel_direction,
    record?.officialDirection,
    record?.official_direction,
    record?.laneDirection,
    record?.lane_direction,
    record?.routeImpact,
    record?.route_impact,
    record?.raw?.direction,
    record?.raw?.travelDirection,
    record?.raw?.travel_direction,
    record?.raw?.officialDirection,
    record?.raw?.official_direction,
    record?.source?.direction,
    record?.source?.travelDirection,
    record?.source?.travel_direction,
    record?.latestReport?.direction,
    record?.latestReport?.travelDirection,
    record?.latestReport?.travel_direction
  ];
  const joined = candidates.map((value) => String(value || "").trim()).filter(Boolean).join(" ").toLowerCase();
  if (!joined || /\b(both|all directions|bidirectional|two-way|all lanes)\b/.test(joined)) return null;
  if (/\b(northbound|north bound|nb)\b/.test(joined)) return "NB";
  if (/\b(southbound|south bound|sb)\b/.test(joined)) return "SB";
  if (/\b(eastbound|east bound|eb)\b/.test(joined)) return "EB";
  if (/\b(westbound|west bound|wb)\b/.test(joined)) return "WB";
  return null;
}

function gridlyDirectionalProvenanceCorridorFromValue(value = "") {
  const normalized = normalizeCorridorBaseLabel(String(value || "").replace(/\s+Corridor$/i, ""));
  if (!normalized) return null;
  return GRIDLY_DIRECTIONAL_PROVENANCE_CORRIDORS.find((corridor) => {
    const corridorPattern = corridor.replace(/\s+/, "\\s*");
    return normalized === corridor || new RegExp(`\\b${corridorPattern}\\b`, "i").test(normalized);
  }) || null;
}

function gridlyDirectionalProvenanceCorridor(record = {}, selectedSegment = null) {
  const candidates = [
    selectedSegment?.roadName,
    record?.selectedRoadName,
    record?.roadName,
    record?.road_name,
    record?.primaryRoad,
    record?.parsedPrimaryRoad,
    record?.routeNameDisplay,
    record?.routeName,
    record?.nearestRoad,
    record?.nearestRoadName,
    record?.corridor,
    record?.raw?.roadName,
    record?.raw?.primaryRoad,
    record?.raw?.routeNameDisplay,
    record?.source?.roadName,
    record?.latestReport?.roadName,
    typeof inferCorridorLabel === "function" ? inferCorridorLabel(record) : ""
  ];
  for (const value of candidates) {
    const corridor = gridlyDirectionalProvenanceCorridorFromValue(value);
    if (corridor) return corridor;
  }
  return null;
}

function gridlyDirectionalProvenanceFallbackReason({ hasGeometry, selectedSegment, dividedRoadRisk, ambiguousParallelSegments, confidence, cardinalDirection, corridor, corridorDefaultUsed, officialDirection }) {
  if (dividedRoadRisk) return "divided_road_risk";
  if (ambiguousParallelSegments) return "ambiguous_parallel_segments";
  if (!hasGeometry && !selectedSegment) return "no_geometry";
  if (hasGeometry && !selectedSegment) return "no_valid_segment";
  if (corridorDefaultUsed && corridor && !officialDirection && (corridor === "TX 146" || corridor === "TX 321")) return "mixed_orientation_corridor";
  if (!cardinalDirection || confidence === "low") return "insufficient_confidence";
  return null;
}

function gridlyBuildDirectionalProvenance(record = {}, options = {}) {
  const coordinate = gridlyCoordinateFromRecord(options.coordinate)
    || gridlyCoordinateFromRecord(record?.finalPlacementCoordinate)
    || gridlyCoordinateFromRecord(record?.representativeCoordinate)
    || gridlyCoordinateFromRecord(record?.rawTapCoordinate || record?.reportCaptureCoordinate)
    || gridlyCoordinateFromRecord(record);
  const geometryDecision = options.geometryDecision || (coordinate && typeof gridlyGeometryAwarePlacementDecision === "function"
    ? gridlyGeometryAwarePlacementDecision(coordinate, { maxDistanceMeters: options.maxDistanceMeters || 75, limit: options.limit || 16 })
    : null);
  const selectedSegment = options.selectedSegment
    || geometryDecision?.selectedSegment
    || record?.geometryAwarePlacement?.selectedSegment
    || record?.selectedRoadwaySegment
    || null;
  const corridor = gridlyDirectionalProvenanceCorridor(record, selectedSegment);
  const corridorDefault = corridor ? GRIDLY_DIRECTIONAL_PROVENANCE_CORRIDOR_DEFAULTS[corridor] || null : null;
  const bearing = gridlyDirectionalProvenanceRoundBearing(
    selectedSegment?.bearing
    ?? record?.selectedSegmentBearing
    ?? record?.segmentBearing
    ?? record?.segment_bearing
    ?? record?.bearing
    ?? record?.geometry?.bearing
    ?? null
  );
  const segmentDirection = gridlyInferCardinalRoadDirection(bearing);
  const officialDirection = gridlyDirectionalProvenanceOfficialDirection(record);
  const sameRoadParallelCount = Number(geometryDecision?.oppositeSideCandidateCount ?? geometryDecision?.sameRoadParallelCandidates?.length ?? record?.oppositeSideCandidateCount ?? 0);
  const candidateGap = Number(geometryDecision?.candidateDistanceGapMeters ?? record?.candidateDistanceGapMeters);
  const dividedRoadRisk = Boolean(options.dividedRoadRisk || geometryDecision?.dividedRoadRisk || record?.dividedRoadRisk || record?.geometryAwarePlacement?.dividedRoadRisk);
  const ambiguousParallelSegments = Boolean(
    sameRoadParallelCount > 0
    && (!Number.isFinite(candidateGap) || candidateGap <= 5 || dividedRoadRisk)
  );
  const hasGeometry = Boolean(geometryDecision?.candidateCount || selectedSegment || bearing !== null || roadwayDatasetLoaded);
  const selectedSideConfidence = gridlyNormalizeDirectionalConfidence(geometryDecision?.selectedSideConfidence || record?.selectedSideConfidence || record?.directionConfidence);
  let confidence = "low";
  let directionSource = "none";
  let cardinalDirection = null;
  let corridorDefaultUsed = false;

  if (bearing !== null && segmentDirection) {
    directionSource = "segment_bearing";
    cardinalDirection = segmentDirection;
    confidence = dividedRoadRisk || ambiguousParallelSegments
      ? "low"
      : (selectedSideConfidence === "high" ? "high" : selectedSideConfidence === "medium" ? "medium" : "medium");
  } else if (officialDirection) {
    directionSource = "official_direction";
    cardinalDirection = officialDirection;
    confidence = dividedRoadRisk || ambiguousParallelSegments ? "low" : "medium";
    if (corridorDefault) corridorDefaultUsed = true;
  } else if (corridorDefault) {
    directionSource = "corridor_default";
    corridorDefaultUsed = true;
    confidence = "low";
    cardinalDirection = null;
  }

  if (corridorDefault && directionSource !== "corridor_default") corridorDefaultUsed = true;
  if ((corridor === "TX 146" || corridor === "TX 321") && directionSource === "corridor_default") {
    confidence = "low";
    cardinalDirection = null;
  }
  if (confidence === "low" || dividedRoadRisk || ambiguousParallelSegments) cardinalDirection = null;

  const fallbackReason = gridlyDirectionalProvenanceFallbackReason({
    hasGeometry,
    selectedSegment,
    dividedRoadRisk,
    ambiguousParallelSegments,
    confidence,
    cardinalDirection,
    corridor,
    corridorDefaultUsed,
    officialDirection
  });

  return gridlyCreateEmptyDirectionalProvenance({
    directionSource,
    cardinalDirection,
    bearing,
    confidence,
    corridor,
    corridorDefaultUsed,
    dividedRoadRisk,
    fallbackReason,
    suppressed: confidence === "low" || !cardinalDirection,
    selectedSegmentId: selectedSegment?.segmentId || null,
    selectedSegmentDistanceMeters: selectedSegment?.distanceFromTapMeters ?? record?.selectedSegmentDistanceMeters ?? null,
    selectedSideConfidence,
    ambiguousParallelSegments,
    evaluatedCoordinate: coordinate
  });
}

function gridlyDirectionalProvenanceRecords(options = {}) {
  const supplied = Array.isArray(options.records) ? options.records : null;
  const unified = supplied || (typeof getUnifiedIncidents === "function" ? getUnifiedIncidents() : []);
  const fallback = !supplied && (!Array.isArray(unified) || !unified.length) && Array.isArray(activeHazards) ? activeHazards : [];
  const records = Array.isArray(unified) && unified.length ? unified : fallback;
  return (Array.isArray(records) ? records : []).filter((record) => {
    const text = `${record?.id || ""} ${record?.type || ""} ${record?.report_type || ""} ${record?.category || ""} ${record?.roadName || ""} ${record?.primaryRoad || ""}`.toLowerCase();
    return /road|hazard|crash|closure|flood|traffic|debris|disabled|txdot/.test(text) || gridlyCoordinateFromRecord(record);
  });
}

function gridlyDirectionalProvenanceIncrement(counts, key) {
  const normalized = key == null || key === "" ? "none" : String(key);
  counts[normalized] = (counts[normalized] || 0) + 1;
}

function gridlyDirectionalProvenanceFeatureText(feature = {}) {
  if (typeof gridlyRoadwayAuditFeatureText === "function") return gridlyRoadwayAuditFeatureText(feature);
  const props = feature?.properties || {};
  return [
    props.name,
    props.ref,
    props.highway,
    props.route,
    props.route_name,
    props.routeName,
    props.alt_name,
    props.official_name,
    props["tiger:name_base"],
    props["tiger:name_base_1"],
    props["tiger:name_base_2"],
    props["tiger:name_base_3"],
    props["@id"]
  ].map((value) => String(value || "").trim()).filter(Boolean).join(" | ").toLowerCase();
}

function gridlyDirectionalProvenanceFeatureMatchesCorridor(feature = {}, corridor = "") {
  if (typeof gridlyRoadwayAuditMatchesCorridor === "function") {
    if (corridor === "US 90" && gridlyRoadwayAuditMatchesCorridor(feature, "us90")) return true;
    if (corridor === "TX 146" && gridlyRoadwayAuditMatchesCorridor(feature, "tx146")) return true;
  }
  const pattern = GRIDLY_DIRECTIONAL_PROVENANCE_CORRIDOR_PATTERNS[corridor];
  return Boolean(pattern && pattern.test(gridlyDirectionalProvenanceFeatureText(feature)));
}

function gridlyDirectionalProvenanceAxisFromBearing(bearing) {
  const value = Number(bearing);
  if (!Number.isFinite(value)) return null;
  const normalized = ((value % 360) + 360) % 360;
  return (normalized >= 45 && normalized < 135) || (normalized >= 225 && normalized < 315) ? "EW" : "NS";
}

function gridlyDirectionalProvenancePredominantAxis(axisCounts = {}) {
  const ew = Number(axisCounts.EW || 0);
  const ns = Number(axisCounts.NS || 0);
  const total = ew + ns;
  if (!total) return "mixed";
  const minorityShare = Math.min(ew, ns) / total;
  if (minorityShare >= 0.25) return "mixed";
  return ew > ns ? "EW" : "NS";
}

const GRIDLY_DIRECTIONAL_PROVENANCE_MAJOR_HIGHWAY_CLASSES = new Set(["motorway", "trunk", "primary", "secondary"]);

function gridlyDirectionalProvenanceCanonicalCorridorsFromText(value = "") {
  const text = String(value || "");
  if (!text.trim()) return [];
  const found = new Set();
  const addMatches = (pattern, formatter) => {
    let match;
    const regex = new RegExp(pattern.source, pattern.flags.includes("g") ? pattern.flags : `${pattern.flags}g`);
    while ((match = regex.exec(text)) !== null) {
      const number = Number(match[1]);
      if (Number.isFinite(number)) found.add(formatter(number));
    }
  };
  addMatches(/\b(?:i|ih|interstate)\s*-?\s*(\d{1,3})\b/gi, (number) => `I-${number}`);
  addMatches(/\b(?:us|u\.?s\.?|united\s+states(?:\s+highway)?)\s*-?\s*(\d{1,3})\b/gi, (number) => `US ${number}`);
  addMatches(/\b(?:tx|sh|state\s+(?:hwy|highway)|highway)\s*-?\s*(\d{1,4})\b/gi, (number) => `TX ${number}`);
  addMatches(/\b(?:fm|farm\s*-?\s*to\s*-?\s*market(?:\s+road)?)\s*-?\s*(\d{1,4})\b/gi, (number) => `FM ${number}`);
  Array.from(found).forEach((corridor) => {
    const match = corridor.match(/^(?:US |I-)(\d+)$/);
    if (match) found.delete(`TX ${match[1]}`);
  });
  return Array.from(found);
}

function gridlyDirectionalProvenanceFeatureHighwayClass(feature = {}) {
  const props = feature?.properties || {};
  return String(props.highway || props.road_class || props.class || "").toLowerCase().trim();
}

function gridlyDirectionalProvenanceFallbackMajorRoadLabel(feature = {}) {
  const props = feature?.properties || {};
  const highwayClass = gridlyDirectionalProvenanceFeatureHighwayClass(feature);
  if (!GRIDLY_DIRECTIONAL_PROVENANCE_MAJOR_HIGHWAY_CLASSES.has(highwayClass)) return null;
  const label = normalizeCorridorBaseLabel(props.name || props.official_name || props.alt_name || props.route_name || props.routeName || "");
  if (!label || /^(road|unnamed road|unknown)$/i.test(label)) return null;
  return label;
}

function gridlyDirectionalProvenanceCorridorsFromFeature(feature = {}) {
  const props = feature?.properties || {};
  const text = [
    props.ref,
    props.name,
    props.official_name,
    props.alt_name,
    props.route,
    props.route_name,
    props.routeName,
    props["tiger:name_base"],
    props["tiger:name_base_1"],
    props["tiger:name_base_2"],
    props["tiger:name_base_3"]
  ].map((value) => String(value || "").trim()).filter(Boolean).join(" | ");
  const corridors = gridlyDirectionalProvenanceCanonicalCorridorsFromText(text);
  const fallback = corridors.length ? null : gridlyDirectionalProvenanceFallbackMajorRoadLabel(feature);
  if (fallback) corridors.push(fallback);
  return corridors;
}

function gridlyDirectionalProvenanceCorridorFromRecordAuditText(record = {}) {
  const candidates = [
    record?.selectedRoadName,
    record?.roadName,
    record?.road_name,
    record?.primaryRoad,
    record?.parsedPrimaryRoad,
    record?.routeNameDisplay,
    record?.routeName,
    record?.nearestRoad,
    record?.nearestRoadName,
    record?.corridor,
    record?.highway,
    record?.raw?.roadName,
    record?.raw?.primaryRoad,
    record?.raw?.routeNameDisplay,
    record?.raw?.routeName,
    record?.raw?.highway,
    record?.source?.roadName,
    record?.source?.primaryRoad,
    record?.source?.routeName,
    record?.source?.highway,
    record?.latestReport?.roadName,
    record?.latestReport?.primaryRoad,
    record?.latestReport?.routeName,
    record?.latestReport?.highway,
    typeof inferCorridorLabel === "function" ? inferCorridorLabel(record) : ""
  ];
  for (const value of candidates) {
    const knownCorridor = gridlyDirectionalProvenanceCorridorFromValue(value);
    if (knownCorridor) return knownCorridor;
    const [detectedCorridor] = gridlyDirectionalProvenanceCanonicalCorridorsFromText(value);
    if (detectedCorridor) return detectedCorridor;
  }
  return null;
}

function gridlyDirectionalProvenanceAreaInventoryKey(area = {}) {
  if (area?.key === "liberty-county") return "county";
  return area?.key || normalizeGridlyAwarenessAreaLookupText(area?.label || area?.storageValue || "").replace(/\s+/g, "-") || "unknown";
}

function gridlyDirectionalProvenanceSegmentInAwarenessArea(segment = {}, area = {}) {
  if (!area) return false;
  const midpoint = {
    lat: (Number(segment.startLat) + Number(segment.endLat)) / 2,
    lng: (Number(segment.startLng) + Number(segment.endLng)) / 2
  };
  if (![segment.startLat, segment.startLng, segment.endLat, segment.endLng, midpoint.lat, midpoint.lng].every(Number.isFinite)) return false;
  if (area.countyWide || area.fallback) {
    return isGridlyCoordinateInsideLibertyCountyBounds({ lat: segment.startLat, lng: segment.startLng })
      || isGridlyCoordinateInsideLibertyCountyBounds({ lat: segment.endLat, lng: segment.endLng })
      || isGridlyCoordinateInsideLibertyCountyBounds(midpoint);
  }
  if (!Number.isFinite(Number(area.lat)) || !Number.isFinite(Number(area.lng))) return false;
  const radiusMiles = Number(area.radiusMiles) || DEFAULT_NEARBY_RADIUS_MILES;
  const distanceMiles = typeof distancePointToSegmentMiles === "function"
    ? distancePointToSegmentMiles(area.lat, area.lng, segment.startLat, segment.startLng, segment.endLat, segment.endLng)
    : Math.min(
      getDistanceMiles(area.lat, area.lng, segment.startLat, segment.startLng),
      getDistanceMiles(area.lat, area.lng, segment.endLat, segment.endLng),
      getDistanceMiles(area.lat, area.lng, midpoint.lat, midpoint.lng)
    );
  return Number.isFinite(distanceMiles) && distanceMiles <= radiusMiles;
}

function gridlyDirectionalProvenanceAreaRuntimeCoverage(area = {}, records = [], currentScopedRecords = []) {
  const areaRecords = area?.countyWide || area?.fallback
    ? records.filter((record) => gridlyDirectionalProvenanceRecordInAwarenessScope(record, { isCountyMode: true }))
    : records.filter((record) => {
      try { return typeof isGridlyRecordInAwarenessArea === "function" ? isGridlyRecordInAwarenessArea(record, area) : false; } catch (_error) { return false; }
    });
  const currentScopeRecords = area?.countyWide || area?.fallback
    ? currentScopedRecords
    : currentScopedRecords.filter((record) => {
      try { return typeof isGridlyRecordInAwarenessArea === "function" ? isGridlyRecordInAwarenessArea(record, area) : false; } catch (_error) { return false; }
    });
  const corridorCoverageCounts = {};
  areaRecords.forEach((record) => {
    const corridor = gridlyDirectionalProvenanceCorridorFromRecordAuditText(record) || "out_of_scope_or_unknown";
    gridlyDirectionalProvenanceIncrement(corridorCoverageCounts, corridor);
  });
  return {
    runtimeEvaluatedRecords: records.length,
    scopedEvaluatedRecords: areaRecords.length,
    selectedScopedEvaluatedRecords: currentScopeRecords.length,
    corridorCoverageCounts
  };
}


function gridlyDirectionalProvenanceCorridorTier(corridor = "", stats = {}) {
  const label = normalizeCorridorBaseLabel(String(corridor || ""));
  const lower = label.toLowerCase();
  if (!label) return "local";
  if (/\bfrontage\b/.test(lower)) return "local";
  if (/\b(?:cr|county\s+road)\s*-?\s*\d+[a-z]?\b/i.test(label)) return "local";
  if (/^i-\d+\b/i.test(label) || /^interstate\s+\d+\b/i.test(label)) return "primary";
  if (/^(?:us|u\.s\.|united\s+states(?:\s+highway)?)\s*-?\s*\d+\b/i.test(label)) return "primary";
  if (/^(?:tx|sh|state\s+(?:hwy|highway))\s*-?\s*\d+\b/i.test(label)) return "primary";
  if (/^highway\s*\d+\b/i.test(label)) return "primary";
  if (/\bgrand\s+parkway\b/i.test(label)) return "primary";
  if (/^(?:fm|farm\s*-?\s*to\s*-?\s*market(?:\s+road)?)\s*-?\s*\d+\b/i.test(label)) return "secondary";
  if (/\b(?:main\s+street|washington\s+avenue|majnik\s+avenue|san\s+marcos\s+drive|santa\s+fe\s+parkway|town\s+center\s+drive)\b/i.test(label)) return "local";
  const geometrySegments = Number(stats.geometrySegments || 0);
  const roadwayFeatures = Number(stats.roadwayFeatures || 0);
  if (geometrySegments >= 50 && roadwayFeatures >= 10 && !/\b(?:street|st|avenue|ave|drive|dr|lane|ln|court|ct|circle|cir|way|trail|trl|place|pl|boulevard|blvd|parkway|pkwy)\b/i.test(label)) {
    return "secondary";
  }
  return "local";
}

function gridlyDirectionalProvenanceEmptyTierBreakdown() {
  return { primary: 0, secondary: 0, local: 0 };
}

function gridlyDirectionalProvenanceTierBreakdown(corridors = []) {
  return corridors.reduce((breakdown, entry) => {
    const tier = entry?.tier === "primary" || entry?.tier === "secondary" || entry?.tier === "local"
      ? entry.tier
      : gridlyDirectionalProvenanceCorridorTier(entry?.corridor, entry);
    breakdown[tier] += 1;
    return breakdown;
  }, gridlyDirectionalProvenanceEmptyTierBreakdown());
}

function gridlyDirectionalProvenanceFeaturesForCorridor(corridor = "", options = {}) {
  const label = normalizeCorridorBaseLabel(String(corridor || ""));
  const loadedFeatures = roadwayDatasetLoaded && Array.isArray(roadwaySegmentFeatures) ? roadwaySegmentFeatures : [];
  if (!label || !loadedFeatures.length) return [];
  const countyContained = Boolean(options?.countyContained);
  return loadedFeatures.filter((feature) => {
    if (countyContained && !gridlyDirectionalProvenanceFeatureInsideCounty(feature)) return false;
    if (gridlyDirectionalProvenanceFeatureMatchesCorridor(feature, label)) return true;
    return gridlyDirectionalProvenanceCorridorsFromFeature(feature).some((candidate) => normalizeCorridorBaseLabel(candidate) === label);
  });
}

function gridlyDirectionalProvenanceCountyContainedFeatures() {
  const loadedFeatures = roadwayDatasetLoaded && Array.isArray(roadwaySegmentFeatures) ? roadwaySegmentFeatures : [];
  return loadedFeatures.filter((feature) => gridlyDirectionalProvenanceFeatureInsideCounty(feature));
}

function gridlyDirectionalProvenanceCountyContainedCorridors() {
  return gridlyDirectionalProvenanceBuildStatsFromFeatures(
    gridlyDirectionalProvenanceCountyContainedFeatures(),
    { source: "county_geometry_containment_guard" }
  );
}

function gridlyDirectionalProvenanceReadinessBucket(score = 0, tier = "local") {
  const value = Number(score) || 0;
  if (tier === "local") {
    if (value >= 80) return "conditional";
    return value >= 55 ? "conditional" : "notReady";
  }
  if (value >= 80) return "ready";
  if (value >= 55) return "conditional";
  return "notReady";
}

function gridlyDirectionalProvenanceReadinessSummary(entries = []) {
  return entries.reduce((summary, entry) => {
    const status = entry?.readinessStatus === "ready" || entry?.readinessStatus === "conditional" || entry?.readinessStatus === "notReady"
      ? entry.readinessStatus
      : gridlyDirectionalProvenanceReadinessBucket(entry?.readinessScore, entry?.tier);
    summary[status] += 1;
    return summary;
  }, { ready: 0, conditional: 0, notReady: 0 });
}

function gridlyDirectionalProvenanceReadinessGeometryQuality(stats = {}) {
  const segments = Number(stats.geometrySegments || 0);
  const features = Number(stats.roadwayFeatures || 0);
  if (segments >= 120 && features >= 8) return { label: "high", score: 30 };
  if (segments >= 50 && features >= 4) return { label: "medium", score: 23 };
  if (segments >= 12 && features >= 2) return { label: "limited", score: 15 };
  if (segments > 0) return { label: "sparse", score: 8 };
  return { label: "none", score: 0 };
}

function gridlyDirectionalProvenanceReadinessBearingStability(axisCounts = {}, geometrySegments = 0) {
  const ew = Number(axisCounts.EW || 0);
  const ns = Number(axisCounts.NS || 0);
  const total = ew + ns;
  if (!total) return { label: "none", dominantShare: 0, score: 0 };
  const dominantShare = Math.max(ew, ns) / total;
  const usableSegments = Number(geometrySegments || 0);
  if (dominantShare >= 0.88 && usableSegments >= 20) return { label: "high", dominantShare, score: 24 };
  if (dominantShare >= 0.72 && usableSegments >= 10) return { label: "medium", dominantShare, score: 18 };
  if (dominantShare >= 0.6) return { label: "mixed", dominantShare, score: 10 };
  return { label: "highly_variable", dominantShare, score: 4 };
}

function gridlyDirectionalProvenanceReadinessCorridorConsistency(stats = {}, bearingAssessment = {}) {
  const segments = Number(stats.geometrySegments || 0);
  const features = Math.max(1, Number(stats.roadwayFeatures || 0));
  const segmentsPerFeature = segments / features;
  const axis = stats.predominantAxis || "mixed";
  const dominantShare = Number(bearingAssessment.dominantShare || 0);
  if (axis !== "mixed" && dominantShare >= 0.85 && segmentsPerFeature >= 4) return { label: "high", score: 20 };
  if (axis !== "mixed" && dominantShare >= 0.7) return { label: "medium", score: 15 };
  if (segments > 0 && dominantShare >= 0.55) return { label: "mixed", score: 8 };
  return { label: "low", score: 2 };
}

function gridlyDirectionalProvenanceReadinessDividedRoadRisk(corridor = "", tier = "local", features = [], stats = {}, bearingAssessment = {}) {
  let onewayFeatures = 0;
  let separatedFeatures = 0;
  let multilaneFeatures = 0;
  features.forEach((feature) => {
    const props = feature?.properties || {};
    const oneway = String(props.oneway || "").toLowerCase().trim();
    if (oneway === "yes" || oneway === "1" || oneway === "true") onewayFeatures += 1;
    if (String(props["tiger:separated"] || props.separated || props.divided || "").toLowerCase().trim() === "yes") separatedFeatures += 1;
    if (Number(props.lanes) >= 4 || props["lanes:forward"] || props["lanes:backward"]) multilaneFeatures += 1;
  });
  const segments = Number(stats.geometrySegments || 0);
  const dominantShare = Number(bearingAssessment.dominantShare || 0);
  const knownAmbiguousCorridor = /^(TX 146|TX 321)$/i.test(String(corridor || ""));
  const dividedSignals = onewayFeatures + separatedFeatures + multilaneFeatures;
  if (knownAmbiguousCorridor || (tier === "primary" && dividedSignals >= 4 && dominantShare < 0.86)) {
    return { label: "high", score: 0, onewayFeatures, separatedFeatures, multilaneFeatures };
  }
  if ((tier === "primary" && dividedSignals > 0) || (segments >= 180 && dominantShare < 0.78)) {
    return { label: "medium", score: 8, onewayFeatures, separatedFeatures, multilaneFeatures };
  }
  return { label: "low", score: 12, onewayFeatures, separatedFeatures, multilaneFeatures };
}

function gridlyDirectionalProvenanceReadinessRuntimeCoverage(corridor = "", runtimeCoverage = {}) {
  const samples = Number(runtimeCoverage?.[corridor] || 0);
  if (samples >= 5) return { label: "sufficient", samples, score: 14 };
  if (samples > 0) return { label: "limited", samples, score: 8 };
  return { label: "none", samples, score: 2 };
}

function gridlyDirectionalProvenanceReadinessConfidence(score = 0, geometryQuality = "none", bearingStability = "none", runtimeCoverage = "none") {
  const value = Number(score) || 0;
  if (value >= 80 && geometryQuality === "high" && bearingStability === "high") return "high";
  if (value >= 55 && geometryQuality !== "none") return "medium";
  return "low";
}

function gridlyDirectionalProvenanceDirectionalReadiness(detectedMajorCorridors = [], runtimeCoverage = {}, options = {}) {
  const countywide = detectedMajorCorridors.map((stats) => {
    const tier = gridlyDirectionalProvenanceCorridorTier(stats.corridor, stats);
    const features = gridlyDirectionalProvenanceFeaturesForCorridor(stats.corridor, { countyContained: Boolean(options?.countyContained) });
    const geometry = gridlyDirectionalProvenanceReadinessGeometryQuality(stats);
    const bearing = gridlyDirectionalProvenanceReadinessBearingStability(stats.axisSegmentBreakdown, stats.geometrySegments);
    const consistency = gridlyDirectionalProvenanceReadinessCorridorConsistency(stats, bearing);
    const dividedRisk = gridlyDirectionalProvenanceReadinessDividedRoadRisk(stats.corridor, tier, features, stats, bearing);
    const runtime = gridlyDirectionalProvenanceReadinessRuntimeCoverage(stats.corridor, runtimeCoverage);
    const tierPriorityScore = tier === "local" ? -8 : 0;
    const readinessScore = Math.max(0, Math.min(100, Math.round(geometry.score + bearing.score + consistency.score + dividedRisk.score + runtime.score + tierPriorityScore)));
    const readinessConfidence = gridlyDirectionalProvenanceReadinessConfidence(readinessScore, geometry.label, bearing.label, runtime.label);
    const readinessStatus = gridlyDirectionalProvenanceReadinessBucket(readinessScore, tier);
    return {
      corridor: stats.corridor,
      tier,
      readinessScore,
      readinessConfidence,
      readinessStatus,
      recommendedForDirectionalAwareness: tier !== "local" && readinessStatus === "ready" && readinessConfidence === "high" && dividedRisk.label !== "high",
      geometryQuality: geometry.label,
      bearingStability: bearing.label,
      corridorConsistency: consistency.label,
      dividedRoadRisk: dividedRisk.label,
      runtimeCoverage: runtime.label,
      runtimeSamples: runtime.samples,
      predominantAxis: stats.predominantAxis || "mixed",
      axisSegmentBreakdown: stats.axisSegmentBreakdown || { EW: 0, NS: 0 },
      roadwayFeatures: Number(stats.roadwayFeatures || 0),
      geometrySegments: Number(stats.geometrySegments || 0),
      auditOnly: true
    };
  }).sort((a, b) => {
    const tierRank = { primary: 0, secondary: 1, local: 2 };
    return (tierRank[a.tier] ?? 3) - (tierRank[b.tier] ?? 3) || b.readinessScore - a.readinessScore || a.corridor.localeCompare(b.corridor);
  });
  return {
    countywide,
    readinessSummary: gridlyDirectionalProvenanceReadinessSummary(countywide)
  };
}

function gridlyDirectionalProvenanceFeatureAuditId(feature = {}, featureIndex = 0) {
  const props = feature?.properties || {};
  return String(props["@id"] || props.id || props.osm_id || props.way_id || props.gid || `feature_${featureIndex}`);
}

function gridlyDirectionalProvenanceFeatureInsideCounty(feature = {}) {
  const segments = typeof flattenRoadGeometrySegments === "function" ? flattenRoadGeometrySegments(feature?.geometry) : [];
  if (!segments.length) return false;
  return segments.some((segment) => {
    const midpoint = {
      lat: (Number(segment.startLat) + Number(segment.endLat)) / 2,
      lng: (Number(segment.startLng) + Number(segment.endLng)) / 2
    };
    return isGridlyCoordinateInsideLibertyCountyBounds({ lat: segment.startLat, lng: segment.startLng })
      || isGridlyCoordinateInsideLibertyCountyBounds({ lat: segment.endLat, lng: segment.endLng })
      || isGridlyCoordinateInsideLibertyCountyBounds(midpoint);
  });
}

function gridlyDirectionalProvenanceReadinessAliasGroup(corridor = "") {
  const label = normalizeCorridorBaseLabel(String(corridor || ""));
  const lower = label.toLowerCase();
  if (/^(?:us 59|i-69)\b/i.test(label) || /\beastex\s+freeway\b/i.test(label)) return "us59_i69_eastex";
  if (/^us 90\b/i.test(label) || /\bcrosby\s+freeway\b/i.test(lower)) return "us90";
  return label || "unknown";
}

function gridlyDirectionalProvenanceExpectedLibertyCorridor(corridor = "") {
  const label = normalizeCorridorBaseLabel(String(corridor || ""));
  if (!label) return false;
  if (GRIDLY_DIRECTIONAL_PROVENANCE_CORRIDORS.includes(label)) return true;
  if (/^(?:US 59|I-69|TX 99|TX 105|FM 1008|FM 1010|FM 1409|FM 1410|FM 1413|FM 160|FM 163|FM 1725|FM 1909|FM 1960|FM 2025|FM 2090|FM 223|FM 2518|FM 2610|FM 2684|FM 2797|FM 2830|FM 3361|FM 563|FM 686|FM 770|FM 787|FM 834)\b/i.test(label)) return true;
  if (/\beastex\s+freeway\b/i.test(label)) return true;
  return false;
}

function gridlyDirectionalProvenanceValidationFeatureProfile(corridor = "", options = {}) {
  const loadedFeatures = roadwayDatasetLoaded && Array.isArray(roadwaySegmentFeatures) ? roadwaySegmentFeatures : [];
  const features = gridlyDirectionalProvenanceFeaturesForCorridor(corridor, { countyContained: Boolean(options?.countyContained) });
  const featureIds = new Set();
  let insideCountyFeatures = 0;
  let outsideCountyFeatures = 0;
  let frontageFeatures = 0;
  let multiRefFeatures = 0;
  let nonTexasRefFeatures = 0;
  const textSamples = [];
  features.forEach((feature) => {
    const featureIndex = loadedFeatures.indexOf(feature);
    featureIds.add(gridlyDirectionalProvenanceFeatureAuditId(feature, featureIndex >= 0 ? featureIndex : featureIds.size));
    if (gridlyDirectionalProvenanceFeatureInsideCounty(feature)) insideCountyFeatures += 1;
    else outsideCountyFeatures += 1;
    const text = gridlyDirectionalProvenanceFeatureText(feature);
    if (/\bfrontage\b/i.test(text)) frontageFeatures += 1;
    if (/;|\|/.test(text) && /\b(?:i|us|u\.?s\.?|tx|sh|state\s+(?:hwy|highway)|fm)\s*-?\s*\d+/i.test(text)) multiRefFeatures += 1;
    if (/\b(?:ga|la|ok|ar)\s*-?\s*\d+\b/i.test(text)) nonTexasRefFeatures += 1;
    if (textSamples.length < 3 && text) textSamples.push(text.slice(0, 160));
  });
  return {
    featureCount: features.length,
    featureIds,
    insideCountyFeatures,
    outsideCountyFeatures,
    insideCountyShare: features.length ? insideCountyFeatures / features.length : 0,
    frontageFeatures,
    multiRefFeatures,
    nonTexasRefFeatures,
    textSamples
  };
}

function gridlyDirectionalProvenanceReadinessValidation(directionalReadiness = {}, detectedMajorCorridors = [], options = {}) {
  const readinessEntries = Array.isArray(directionalReadiness?.countywide) ? directionalReadiness.countywide : [];
  const duplicateCorridors = [];
  const aliasCandidates = [];
  const suspiciousCorridors = [];
  const normalizationIssues = [];
  const entryCounts = new Map();
  const profiles = new Map();
  const getProfile = (corridor) => {
    const key = String(corridor || "");
    if (!profiles.has(key)) profiles.set(key, gridlyDirectionalProvenanceValidationFeatureProfile(key, { countyContained: Boolean(options?.countyContained) }));
    return profiles.get(key);
  };

  readinessEntries.forEach((entry, index) => {
    const key = normalizeCorridorBaseLabel(entry?.corridor || "");
    if (!key) return;
    if (!entryCounts.has(key)) entryCounts.set(key, []);
    entryCounts.get(key).push(index);
  });
  entryCounts.forEach((indexes, corridor) => {
    if (indexes.length > 1) {
      duplicateCorridors.push({
        corridor,
        duplicateCount: indexes.length,
        readinessIndexes: indexes,
        reason: "same_normalized_corridor_has_multiple_readiness_records"
      });
    }
  });

  const aliasGroups = new Map();
  readinessEntries.forEach((entry) => {
    const group = gridlyDirectionalProvenanceReadinessAliasGroup(entry?.corridor || "");
    if (!aliasGroups.has(group)) aliasGroups.set(group, []);
    aliasGroups.get(group).push(entry);
  });
  aliasGroups.forEach((entries, group) => {
    const uniqueCorridors = Array.from(new Set(entries.map((entry) => entry?.corridor).filter(Boolean)));
    if (uniqueCorridors.length > 1) {
      aliasCandidates.push({
        aliasGroup: group,
        corridors: uniqueCorridors,
        relationship: "known_or_likely_alias_family",
        reason: "multiple_readiness_candidates_share_a_known_corridor_alias_family"
      });
    }
  });

  for (let i = 0; i < readinessEntries.length; i += 1) {
    for (let j = i + 1; j < readinessEntries.length; j += 1) {
      const a = readinessEntries[i];
      const b = readinessEntries[j];
      const aProfile = getProfile(a?.corridor);
      const bProfile = getProfile(b?.corridor);
      const smaller = Math.min(aProfile.featureIds.size, bProfile.featureIds.size);
      if (!smaller) continue;
      let overlap = 0;
      aProfile.featureIds.forEach((id) => { if (bProfile.featureIds.has(id)) overlap += 1; });
      const overlapShare = overlap / smaller;
      if (overlapShare >= 0.5 && normalizeCorridorBaseLabel(a?.corridor) !== normalizeCorridorBaseLabel(b?.corridor)) {
        aliasCandidates.push({
          corridors: [a.corridor, b.corridor],
          relationship: "shared_geometry_overlap",
          overlapFeatureCount: overlap,
          overlapShare: Number(overlapShare.toFixed(3)),
          reason: "readiness_candidates_share_a_majority_of_the_smaller_feature_set"
        });
      }
    }
  }

  readinessEntries.forEach((entry) => {
    const corridor = entry?.corridor || "";
    const profile = getProfile(corridor);
    const expected = gridlyDirectionalProvenanceExpectedLibertyCorridor(corridor);
    const malformed = !/^(?:I-\d+|US \d+|TX \d+|FM \d+|[A-Z0-9][A-Za-z0-9 .'-]+)$/i.test(String(corridor || ""));
    const reasons = [];
    if (!expected && profile.featureCount > 0 && profile.insideCountyFeatures === 0) reasons.push("outside_expected_liberty_county_inventory_and_no_in_county_geometry_support");
    if (profile.featureCount > 0 && profile.insideCountyShare < 0.2 && !expected) reasons.push("extremely_low_liberty_county_geometry_support");
    if (malformed) reasons.push("malformed_corridor_label");
    if (profile.nonTexasRefFeatures > 0 && profile.insideCountyFeatures === 0) reasons.push("non_texas_route_reference_detected_in_supporting_geometry");
    if (reasons.length) {
      suspiciousCorridors.push({
        corridor,
        readinessScore: entry.readinessScore,
        readinessConfidence: entry.readinessConfidence,
        readinessStatus: entry.readinessStatus,
        tier: entry.tier,
        geometrySegments: Number(entry.geometrySegments || 0),
        roadwayFeatures: Number(entry.roadwayFeatures || 0),
        insideCountyFeatures: profile.insideCountyFeatures,
        outsideCountyFeatures: profile.outsideCountyFeatures,
        reasons,
        sampleEvidence: profile.textSamples
      });
    }
    if (/^(?:US|TX|FM)\s*-?\d+/i.test(String(corridor || "")) && normalizeCorridorBaseLabel(corridor) !== corridor) {
      normalizationIssues.push({
        corridor,
        normalized: normalizeCorridorBaseLabel(corridor),
        issue: "readiness_corridor_label_not_in_canonical_spacing_or_case"
      });
    }
    if (profile.nonTexasRefFeatures > 0) {
      normalizationIssues.push({
        corridor,
        issue: "supporting_geometry_contains_non_texas_route_references",
        affectedFeatureCount: profile.nonTexasRefFeatures,
        sampleEvidence: profile.textSamples
      });
    }
    if (profile.frontageFeatures > 0 && !/\bfrontage\b/i.test(corridor)) {
      normalizationIssues.push({
        corridor,
        issue: "frontage_road_features_contribute_to_non_frontage_corridor_candidate",
        affectedFeatureCount: profile.frontageFeatures
      });
    }
    if (profile.multiRefFeatures > 0 && /^(?:US 59|I-69)$/i.test(corridor)) {
      normalizationIssues.push({
        corridor,
        issue: "multi_ref_us59_i69_features_require_alias_review_not_score_inflation",
        affectedFeatureCount: profile.multiRefFeatures
      });
    }
  });

  const suspiciousSet = new Set(suspiciousCorridors.map((item) => item.corridor));
  const duplicateSet = new Set(duplicateCorridors.map((item) => item.corridor));
  const aliasCorridorSet = new Set();
  aliasCandidates.forEach((candidate) => (candidate.corridors || []).forEach((corridor) => aliasCorridorSet.add(corridor)));
  const topReadinessCandidates = readinessEntries
    .slice()
    .sort((a, b) => Number(b.readinessScore || 0) - Number(a.readinessScore || 0) || String(a.corridor || "").localeCompare(String(b.corridor || "")))
    .slice(0, 12)
    .map((entry) => ({
      corridor: entry.corridor,
      readinessScore: entry.readinessScore,
      readinessConfidence: entry.readinessConfidence,
      readinessStatus: entry.readinessStatus,
      validationStatus: duplicateSet.has(normalizeCorridorBaseLabel(entry.corridor))
        ? "duplicate"
        : (suspiciousSet.has(entry.corridor) ? "suspicious" : (aliasCorridorSet.has(entry.corridor) ? "aliasReview" : "validated"))
    }));
  const warningCount = aliasCandidates.length + suspiciousCorridors.length + normalizationIssues.length;
  const errorCount = duplicateCorridors.length;
  return {
    available: true,
    version: GRIDLY_DIRECTIONAL_PROVENANCE_READINESS_VALIDATION_VERSION,
    auditOnly: true,
    evaluatedReadinessCandidates: readinessEntries.length,
    detectedCorridorCount: Array.isArray(detectedMajorCorridors) ? detectedMajorCorridors.length : 0,
    topReadinessCandidates,
    duplicateCorridors,
    aliasCandidates,
    suspiciousCorridors,
    normalizationIssues,
    validationSummary: {
      passed: warningCount === 0 && errorCount === 0,
      warnings: warningCount,
      errors: errorCount
    }
  };
}


function gridlyDirectionalProvenancePropertyValues(feature = {}, fields = []) {
  const props = feature?.properties || {};
  return fields
    .map((field) => props[field])
    .flatMap((value) => Array.isArray(value) ? value : String(value == null ? "" : value).split(/\s*;\s*/))
    .map((value) => String(value || "").trim())
    .filter(Boolean);
}

function gridlyDirectionalProvenanceUniqueValues(values = [], limit = 12) {
  return Array.from(new Set(values.map((value) => String(value || "").trim()).filter(Boolean))).slice(0, limit);
}

function gridlyDirectionalProvenanceRouteRefsFromText(value = "") {
  const text = String(value || "");
  const found = new Set();
  const addMatches = (pattern, formatter) => {
    let match;
    const regex = new RegExp(pattern.source, pattern.flags.includes("g") ? pattern.flags : `${pattern.flags}g`);
    while ((match = regex.exec(text)) !== null) {
      const number = Number(match[1]);
      if (Number.isFinite(number)) found.add(formatter(number));
    }
  };
  addMatches(/\b(?:i|ih|interstate)\s*-?\s*(\d{1,3})\b/gi, (number) => `I-${number}`);
  addMatches(/\b(?:us|u\.?s\.?|united\s+states(?:\s+highway)?)\s*-?\s*(\d{1,3})\b/gi, (number) => `US ${number}`);
  addMatches(/\b(?:tx|sh|state\s+(?:hwy|highway)|highway)\s*-?\s*(\d{1,4})\b/gi, (number) => `TX ${number}`);
  addMatches(/\b(?:fm|farm\s*-?\s*to\s*-?\s*market(?:\s+road)?)\s*-?\s*(\d{1,4})\b/gi, (number) => `FM ${number}`);
  addMatches(/\b(?:ga|georgia)\s*(?:hwy|highway)?\s*-?\s*(\d{1,4})\b/gi, (number) => `GA Hwy ${number}`);
  addMatches(/\b(?:mt|montana)\s*(?:hwy|highway)?\s*-?\s*(\d{1,4})\b/gi, (number) => `MT ${number}`);
  addMatches(/\b(?:fl|florida)\s*(?:hwy|highway)?\s*-?\s*(\d{1,4})\b/gi, (number) => `FL Hwy ${number}`);
  addMatches(/\b(?:la|louisiana)\s*(?:hwy|highway)?\s*-?\s*(\d{1,4})\b/gi, (number) => `LA Hwy ${number}`);
  addMatches(/\b(?:ok|oklahoma)\s*(?:hwy|highway)?\s*-?\s*(\d{1,4})\b/gi, (number) => `OK Hwy ${number}`);
  addMatches(/\b(?:ar|arkansas)\s*(?:hwy|highway)?\s*-?\s*(\d{1,4})\b/gi, (number) => `AR Hwy ${number}`);
  return Array.from(found);
}

function gridlyDirectionalProvenanceFeatureOrigin(feature = {}, corridor = "", featureIndex = 0) {
  const props = feature?.properties || {};
  const nameFields = ["name", "official_name", "route_name", "routeName", "tiger:name_base"];
  const refFields = ["ref", "route", "highway"];
  const aliasFields = ["alt_name", "tiger:name_base_1", "tiger:name_base_2", "tiger:name_base_3"];
  const sourceNames = gridlyDirectionalProvenancePropertyValues(feature, nameFields);
  const sourceRefs = gridlyDirectionalProvenancePropertyValues(feature, refFields);
  const sourceAliases = gridlyDirectionalProvenancePropertyValues(feature, aliasFields);
  const text = [sourceRefs, sourceNames, sourceAliases].flat().join(" | ");
  const canonicalCorridors = gridlyDirectionalProvenanceCanonicalCorridorsFromText(text);
  const routeReferences = gridlyDirectionalProvenanceRouteRefsFromText(text);
  const fallbackLabel = gridlyDirectionalProvenanceFallbackMajorRoadLabel(feature);
  const normalizedCorridor = normalizeCorridorBaseLabel(corridor);
  const normalizedFallback = normalizeCorridorBaseLabel(fallbackLabel);
  const matchedBy = [];
  if (canonicalCorridors.some((candidate) => normalizeCorridorBaseLabel(candidate) === normalizedCorridor)) matchedBy.push("canonical_route_reference_or_name");
  if (routeReferences.some((candidate) => normalizeCorridorBaseLabel(candidate) === normalizedCorridor)) matchedBy.push("state_route_reference_or_name");
  if (normalizedFallback && normalizedFallback === normalizedCorridor) matchedBy.push("fallback_major_road_label");
  if (gridlyDirectionalProvenanceFeatureMatchesCorridor(feature, corridor)) matchedBy.push("legacy_seed_corridor_pattern");
  const segments = typeof flattenRoadGeometrySegments === "function" ? flattenRoadGeometrySegments(feature?.geometry) : [];
  return {
    featureId: gridlyDirectionalProvenanceFeatureAuditId(feature, featureIndex),
    sourceNames: gridlyDirectionalProvenanceUniqueValues(sourceNames, 8),
    sourceRefs: gridlyDirectionalProvenanceUniqueValues(sourceRefs, 8),
    sourceAliases: gridlyDirectionalProvenanceUniqueValues(sourceAliases, 8),
    routeReferences: gridlyDirectionalProvenanceUniqueValues(routeReferences, 12),
    matchedBy: gridlyDirectionalProvenanceUniqueValues(matchedBy, 8),
    insideCounty: gridlyDirectionalProvenanceFeatureInsideCounty(feature),
    geometrySegments: segments.length,
    highwayClass: gridlyDirectionalProvenanceFeatureHighwayClass(feature) || null,
    sampleText: gridlyDirectionalProvenanceFeatureText(feature).slice(0, 220)
  };
}

function gridlyDirectionalProvenanceCorridorOriginProfile(corridor = "", corridorFeatureMap = null, options = {}) {
  const loadedFeatures = roadwayDatasetLoaded && Array.isArray(roadwaySegmentFeatures) ? roadwaySegmentFeatures : [];
  const features = gridlyDirectionalProvenanceFeaturesForCorridor(corridor, { countyContained: Boolean(options?.countyContained) });
  const sourceFeatures = features.map((feature) => {
    const index = loadedFeatures.indexOf(feature);
    return gridlyDirectionalProvenanceFeatureOrigin(feature, corridor, index >= 0 ? index : 0);
  });
  const featureIds = new Set(sourceFeatures.map((feature) => feature.featureId));
  const sourceRefs = gridlyDirectionalProvenanceUniqueValues(sourceFeatures.flatMap((feature) => feature.sourceRefs), 20);
  const sourceNames = gridlyDirectionalProvenanceUniqueValues(sourceFeatures.flatMap((feature) => feature.sourceNames), 20);
  const sourceAliases = gridlyDirectionalProvenanceUniqueValues(sourceFeatures.flatMap((feature) => feature.sourceAliases), 20);
  const sourceRoadwayReferences = gridlyDirectionalProvenanceUniqueValues(sourceFeatures.flatMap((feature) => feature.routeReferences), 20);
  const normalizationPath = gridlyDirectionalProvenanceUniqueValues(sourceFeatures.flatMap((feature) => feature.matchedBy), 10);
  const insideCountyFeatures = sourceFeatures.filter((feature) => feature.insideCounty).length;
  const outsideCountyFeatures = sourceFeatures.length - insideCountyFeatures;
  const overlapRelationships = [];
  if (corridorFeatureMap instanceof Map && featureIds.size) {
    corridorFeatureMap.forEach((otherIds, otherCorridor) => {
      if (!otherCorridor || normalizeCorridorBaseLabel(otherCorridor) === normalizeCorridorBaseLabel(corridor)) return;
      let overlapFeatureCount = 0;
      featureIds.forEach((id) => { if (otherIds.has(id)) overlapFeatureCount += 1; });
      if (!overlapFeatureCount) return;
      const smaller = Math.min(featureIds.size, otherIds.size) || 1;
      overlapRelationships.push({
        corridor: otherCorridor,
        overlapFeatureCount,
        overlapShareOfSmallerSet: Number((overlapFeatureCount / smaller).toFixed(3))
      });
    });
  }
  overlapRelationships.sort((a, b) => b.overlapFeatureCount - a.overlapFeatureCount || String(a.corridor).localeCompare(String(b.corridor)));
  return {
    corridor,
    sourceFeatures: sourceFeatures.length,
    geometryCount: sourceFeatures.length,
    geometrySegments: sourceFeatures.reduce((sum, feature) => sum + Number(feature.geometrySegments || 0), 0),
    insideCountyFeatures,
    outsideCountyFeatures,
    sourceRefs,
    sourceNames,
    sourceAliases,
    sourceRoadwayReferences,
    normalizationPath,
    overlapRelationships: overlapRelationships.slice(0, 10),
    sampleFeatures: sourceFeatures.slice(0, 6)
  };
}

function gridlyDirectionalProvenanceLikelyNonTexasCorridor(corridor = "", origin = {}) {
  const label = normalizeCorridorBaseLabel(corridor);
  const refs = [label, ...(origin.sourceRoadwayReferences || []), ...(origin.sourceRefs || []), ...(origin.sourceNames || []), ...(origin.sourceAliases || [])].join(" | ");
  if (/\b(?:GA|MT|FL|LA|OK|AR)\s*(?:Hwy|Highway)?\s*\d+\b/i.test(refs)) return true;
  if (/^I-95$/i.test(label) || /^US 17$/i.test(label)) return true;
  if (/^(?:I-|US )\d+$/i.test(label) && !gridlyDirectionalProvenanceExpectedLibertyCorridor(label) && origin.insideCountyFeatures === 0) return true;
  return false;
}

function gridlyDirectionalProvenancePurityOriginClassification(corridor = "", origin = {}, readinessEntry = null, readinessValidation = {}) {
  const expected = gridlyDirectionalProvenanceExpectedLibertyCorridor(corridor);
  const hasGeometry = Number(origin.sourceFeatures || 0) > 0;
  const hasInsideGeometry = Number(origin.insideCountyFeatures || 0) > 0;
  const nonTexas = gridlyDirectionalProvenanceLikelyNonTexasCorridor(corridor, origin);
  const normalizationArtifact = (origin.normalizationPath || []).includes("canonical_route_reference_or_name") && !expected && !hasInsideGeometry;
  const aliasArtifact = Array.isArray(readinessValidation?.aliasCandidates) && readinessValidation.aliasCandidates.some((candidate) => (candidate.corridors || []).includes(corridor));
  if (nonTexas) return "potential_non_texas_reference_contamination";
  if (!hasGeometry && readinessEntry) return "readiness_scoring_without_matching_geometry";
  if (normalizationArtifact) return "route_reference_normalization_artifact";
  if (aliasArtifact) return "alias_or_shared_geometry_artifact";
  if ((origin.normalizationPath || []).includes("fallback_major_road_label") && !expected) return "major_road_name_fallback_artifact";
  if (hasGeometry && !hasInsideGeometry && !expected) return "outside_county_geometry_artifact";
  if (hasGeometry && hasInsideGeometry && !expected) return "unexpected_local_geometry_requires_review";
  return expected ? "expected_liberty_county_corridor" : "unclassified_suspicious_corridor";
}

function gridlyDirectionalProvenanceCorridorPurityAudit(directionalReadiness = {}, detectedMajorCorridors = [], readinessValidation = {}, options = {}) {
  const readinessEntries = Array.isArray(directionalReadiness?.countywide) ? directionalReadiness.countywide : [];
  const loadedFeatures = roadwayDatasetLoaded && Array.isArray(roadwaySegmentFeatures) ? roadwaySegmentFeatures : [];
  const countyContained = Boolean(options?.countyContained);
  const candidateCorridors = new Set();
  const suspiciousLabels = [
    "US 17",
    "I-95",
    "GA Hwy 196",
    "MT 223",
    "Leroy Coffer Highway",
    "General Screven Way",
    "Blountstown Highway",
    "Veterans Parkway"
  ];
  detectedMajorCorridors.forEach((entry) => { if (entry?.corridor) candidateCorridors.add(entry.corridor); });
  readinessEntries.forEach((entry) => { if (entry?.corridor) candidateCorridors.add(entry.corridor); });
  (readinessValidation?.suspiciousCorridors || []).forEach((entry) => { if (entry?.corridor) candidateCorridors.add(entry.corridor); });
  if (!countyContained) suspiciousLabels.forEach((corridor) => candidateCorridors.add(corridor));

  const corridorFeatureMap = new Map();
  candidateCorridors.forEach((corridor) => {
    const ids = new Set();
    gridlyDirectionalProvenanceFeaturesForCorridor(corridor, { countyContained }).forEach((feature) => {
      const index = loadedFeatures.indexOf(feature);
      ids.add(gridlyDirectionalProvenanceFeatureAuditId(feature, index >= 0 ? index : ids.size));
    });
    corridorFeatureMap.set(corridor, ids);
  });

  const readinessByCorridor = new Map(readinessEntries.map((entry) => [entry.corridor, entry]));
  const origins = Array.from(candidateCorridors).map((corridor) => {
    const origin = gridlyDirectionalProvenanceCorridorOriginProfile(corridor, corridorFeatureMap, { countyContained });
    const readinessEntry = readinessByCorridor.get(corridor) || null;
    const originClassification = gridlyDirectionalProvenancePurityOriginClassification(corridor, origin, readinessEntry, readinessValidation);
    return {
      ...origin,
      readinessScore: readinessEntry?.readinessScore ?? null,
      readinessConfidence: readinessEntry?.readinessConfidence ?? null,
      readinessStatus: readinessEntry?.readinessStatus ?? null,
      originClassification,
      readinessIntegrity: {
        receivedReadinessScore: Boolean(readinessEntry),
        duplicateGeometry: (origin.overlapRelationships || []).some((relationship) => Number(relationship.overlapShareOfSmallerSet || 0) >= 0.5),
        aliasContamination: Array.isArray(readinessValidation?.aliasCandidates) && readinessValidation.aliasCandidates.some((candidate) => (candidate.corridors || []).includes(corridor)),
        normalizationContamination: /normalization|non_texas|contamination/i.test(originClassification)
      }
    };
  });

  const suspiciousCorridorOrigins = origins.filter((origin) => {
    if (gridlyDirectionalProvenanceExpectedLibertyCorridor(origin.corridor)) return false;
    if (gridlyDirectionalProvenanceLikelyNonTexasCorridor(origin.corridor, origin)) return true;
    if (/artifact|contamination|suspicious|unexpected|unclassified/i.test(origin.originClassification)) return true;
    return false;
  }).sort((a, b) => Number(b.readinessScore || 0) - Number(a.readinessScore || 0) || Number(b.sourceFeatures || 0) - Number(a.sourceFeatures || 0) || String(a.corridor).localeCompare(String(b.corridor)));

  const nonTexasCorridors = suspiciousCorridorOrigins.filter((origin) => gridlyDirectionalProvenanceLikelyNonTexasCorridor(origin.corridor, origin)).map((origin) => ({
    corridor: origin.corridor,
    sourceFeatures: origin.sourceFeatures,
    insideCountyFeatures: origin.insideCountyFeatures,
    sourceRoadwayReferences: origin.sourceRoadwayReferences,
    sourceRefs: origin.sourceRefs,
    sourceNames: origin.sourceNames,
    sourceAliases: origin.sourceAliases,
    readinessScore: origin.readinessScore,
    reason: origin.originClassification
  }));
  const likelyNormalizationArtifacts = suspiciousCorridorOrigins.filter((origin) => origin.readinessIntegrity.normalizationContamination || (origin.normalizationPath || []).includes("canonical_route_reference_or_name")).map((origin) => ({
    corridor: origin.corridor,
    normalizationPath: origin.normalizationPath,
    sourceFeatures: origin.sourceFeatures,
    sourceRoadwayReferences: origin.sourceRoadwayReferences,
    readinessScore: origin.readinessScore,
    reason: origin.originClassification
  }));
  const likelyAliasArtifacts = suspiciousCorridorOrigins.filter((origin) => origin.readinessIntegrity.aliasContamination || (origin.overlapRelationships || []).some((relationship) => Number(relationship.overlapShareOfSmallerSet || 0) >= 0.5)).map((origin) => ({
    corridor: origin.corridor,
    sourceFeatures: origin.sourceFeatures,
    overlapRelationships: origin.overlapRelationships,
    readinessScore: origin.readinessScore,
    reason: origin.originClassification
  }));
  const likelyGeometryArtifacts = suspiciousCorridorOrigins.filter((origin) => origin.sourceFeatures > 0 && origin.insideCountyFeatures === 0).map((origin) => ({
    corridor: origin.corridor,
    sourceFeatures: origin.sourceFeatures,
    geometrySegments: origin.geometrySegments,
    insideCountyFeatures: origin.insideCountyFeatures,
    outsideCountyFeatures: origin.outsideCountyFeatures,
    sampleFeatures: origin.sampleFeatures,
    reason: origin.originClassification
  }));
  return {
    available: true,
    version: GRIDLY_DIRECTIONAL_PROVENANCE_CORRIDOR_PURITY_AUDIT_VERSION,
    auditOnly: true,
    rendersDirectionalUi: false,
    topSuspiciousCorridors: suspiciousCorridorOrigins.slice(0, 12).map((origin) => ({
      corridor: origin.corridor,
      readinessScore: origin.readinessScore,
      sourceFeatures: origin.sourceFeatures,
      insideCountyFeatures: origin.insideCountyFeatures,
      originClassification: origin.originClassification
    })),
    suspiciousCorridorOrigins,
    nonTexasCorridors,
    likelyNormalizationArtifacts,
    likelyAliasArtifacts,
    likelyGeometryArtifacts,
    puritySummary: {
      passed: suspiciousCorridorOrigins.length === 0,
      suspiciousCount: suspiciousCorridorOrigins.length,
      nonTexasCount: nonTexasCorridors.length,
      normalizationArtifactCount: likelyNormalizationArtifacts.length,
      aliasArtifactCount: likelyAliasArtifacts.length,
      geometryArtifactCount: likelyGeometryArtifacts.length
    }
  };
}


const GRIDLY_DIRECTIONAL_PROVENANCE_CONTAINMENT_SUSPICIOUS_CORRIDORS = [
  "US 17",
  "I-95",
  "GA Hwy 196",
  "MT 223",
  "Veterans Parkway",
  "Leroy Coffer Highway"
];
const GRIDLY_DIRECTIONAL_PROVENANCE_CONTAINMENT_TRUSTED_CORRIDORS = ["US 90", "FM 1409", "FM 1960", "FM 1011"];

function gridlyDirectionalProvenanceFeatureInsideCountyByBounds(feature = {}) {
  return gridlyDirectionalProvenanceFeatureInsideCounty(feature);
}

function gridlyDirectionalProvenanceFeatureSourceName(feature = {}) {
  const props = feature?.properties || {};
  return String(props.source || props.sourceName || props.dataset || props.dataSource || ROADWAY_SEGMENTS_URL || "local_roadway_dataset_geometry");
}

function gridlyDirectionalProvenanceBuildStatsFromFeatures(features = [], options = {}) {
  const source = String(options.source || "audit_feature_subset");
  const corridorStats = new Map();
  (Array.isArray(features) ? features : []).forEach((feature) => {
    const corridors = gridlyDirectionalProvenanceCorridorsFromFeature(feature);
    if (!corridors.length) return;
    const segments = typeof flattenRoadGeometrySegments === "function" ? flattenRoadGeometrySegments(feature?.geometry) : [];
    corridors.forEach((corridor) => {
      if (!corridorStats.has(corridor)) {
        corridorStats.set(corridor, {
          corridor,
          source,
          tier: gridlyDirectionalProvenanceCorridorTier(corridor),
          roadwayFeatures: 0,
          geometrySegments: 0,
          predominantAxis: "mixed",
          geometryCapable: false,
          axisSegmentBreakdown: { EW: 0, NS: 0 }
        });
      }
      const stats = corridorStats.get(corridor);
      stats.roadwayFeatures += 1;
      stats.geometrySegments += segments.length;
      segments.forEach((segment) => {
        const bearing = typeof gridlyRoadBearingDegrees === "function"
          ? gridlyRoadBearingDegrees(segment.startLat, segment.startLng, segment.endLat, segment.endLng)
          : null;
        const axis = gridlyDirectionalProvenanceAxisFromBearing(bearing);
        if (axis) stats.axisSegmentBreakdown[axis] += 1;
      });
    });
  });
  return Array.from(corridorStats.values())
    .map((stats) => ({
      ...stats,
      tier: gridlyDirectionalProvenanceCorridorTier(stats.corridor, stats),
      geometryCapable: stats.geometrySegments > 0,
      predominantAxis: gridlyDirectionalProvenancePredominantAxis(stats.axisSegmentBreakdown)
    }))
    .sort((a, b) => b.geometrySegments - a.geometrySegments || b.roadwayFeatures - a.roadwayFeatures || a.corridor.localeCompare(b.corridor));
}

function gridlyDirectionalProvenanceReadinessEntryForAudit(stats = {}, runtimeCoverage = {}, features = []) {
  const tier = gridlyDirectionalProvenanceCorridorTier(stats.corridor, stats);
  const geometry = gridlyDirectionalProvenanceReadinessGeometryQuality(stats);
  const bearing = gridlyDirectionalProvenanceReadinessBearingStability(stats.axisSegmentBreakdown, stats.geometrySegments);
  const consistency = gridlyDirectionalProvenanceReadinessCorridorConsistency(stats, bearing);
  const dividedRisk = gridlyDirectionalProvenanceReadinessDividedRoadRisk(stats.corridor, tier, features, stats, bearing);
  const runtime = gridlyDirectionalProvenanceReadinessRuntimeCoverage(stats.corridor, runtimeCoverage);
  const tierPriorityScore = tier === "local" ? -8 : 0;
  const readinessScore = Math.max(0, Math.min(100, Math.round(geometry.score + bearing.score + consistency.score + dividedRisk.score + runtime.score + tierPriorityScore)));
  return {
    corridor: stats.corridor,
    tier,
    readinessScore,
    readinessConfidence: gridlyDirectionalProvenanceReadinessConfidence(readinessScore, geometry.label, bearing.label, runtime.label),
    readinessStatus: gridlyDirectionalProvenanceReadinessBucket(readinessScore, tier),
    geometryQuality: geometry.label,
    bearingStability: bearing.label,
    corridorConsistency: consistency.label,
    dividedRoadRisk: dividedRisk.label,
    runtimeCoverage: runtime.label,
    runtimeSamples: runtime.samples,
    roadwayFeatures: Number(stats.roadwayFeatures || 0),
    geometrySegments: Number(stats.geometrySegments || 0),
    predominantAxis: stats.predominantAxis || "mixed",
    axisSegmentBreakdown: stats.axisSegmentBreakdown || { EW: 0, NS: 0 },
    auditOnly: true
  };
}

function gridlyDirectionalProvenanceContainedReadinessAudit(detectedMajorCorridors = [], directionalReadiness = {}, runtimeCoverage = {}) {
  const loadedFeatures = roadwayDatasetLoaded && Array.isArray(roadwaySegmentFeatures) ? roadwaySegmentFeatures : [];
  const insideFeatures = loadedFeatures.filter((feature) => gridlyDirectionalProvenanceFeatureInsideCountyByBounds(feature));
  const containedStats = gridlyDirectionalProvenanceBuildStatsFromFeatures(insideFeatures, { source: "local_roadway_dataset_geometry_inside_county_only" });
  const currentByCorridor = new Map((Array.isArray(directionalReadiness?.countywide) ? directionalReadiness.countywide : []).map((entry) => [entry.corridor, entry]));
  const containedStatsByCorridor = new Map(containedStats.map((stats) => [stats.corridor, stats]));
  const loadedInsideByCorridor = new Map();
  GRIDLY_DIRECTIONAL_PROVENANCE_CONTAINMENT_TRUSTED_CORRIDORS.forEach((corridor) => {
    const corridorFeatures = new Set(gridlyDirectionalProvenanceFeaturesForCorridor(corridor));
    loadedInsideByCorridor.set(corridor, insideFeatures.filter((feature) => corridorFeatures.has(feature)));
  });
  const trustedComparisons = GRIDLY_DIRECTIONAL_PROVENANCE_CONTAINMENT_TRUSTED_CORRIDORS.map((corridor) => {
    const current = currentByCorridor.get(corridor) || null;
    const containedStatsEntry = containedStatsByCorridor.get(corridor) || {
      corridor,
      tier: gridlyDirectionalProvenanceCorridorTier(corridor),
      roadwayFeatures: 0,
      geometrySegments: 0,
      predominantAxis: "mixed",
      geometryCapable: false,
      axisSegmentBreakdown: { EW: 0, NS: 0 }
    };
    const contained = gridlyDirectionalProvenanceReadinessEntryForAudit(containedStatsEntry, runtimeCoverage, loadedInsideByCorridor.get(corridor) || []);
    const scoreDelta = (current ? Number(current.readinessScore || 0) : 0) - Number(contained.readinessScore || 0);
    return {
      corridor,
      currentReadinessScore: current?.readinessScore ?? null,
      containedReadinessScore: contained.readinessScore,
      scoreDelta,
      currentGeometrySegments: current?.geometrySegments ?? null,
      containedGeometrySegments: contained.geometrySegments,
      currentRoadwayFeatures: current?.roadwayFeatures ?? null,
      containedRoadwayFeatures: contained.roadwayFeatures,
      materialChangeExpected: Math.abs(scoreDelta) >= 5 || (current?.readinessStatus || null) !== contained.readinessStatus,
      note: current ? "compared_current_readiness_to_inside_county_only_geometry_audit_projection" : "no_current_readiness_entry_for_corridor"
    };
  });
  const material = trustedComparisons.filter((entry) => entry.materialChangeExpected);
  return {
    trustedCorridorComparisons: trustedComparisons,
    readinessImpactIfContained: material.length
      ? `Potential material readiness change for ${material.map((entry) => entry.corridor).join(", ")} if outside-county geometry is removed from scoring.`
      : "No material readiness score/status change projected for US 90, FM 1409, FM 1960, or FM 1011 when scoring is recomputed with inside-county roadway geometry only."
  };
}

function gridlyDirectionalProvenanceCountyGeometryContainmentAudit(detectedMajorCorridors = [], directionalReadiness = {}, readinessValidation = {}, runtimeCoverage = {}) {
  const loadedFeatures = roadwayDatasetLoaded && Array.isArray(roadwaySegmentFeatures) ? roadwaySegmentFeatures : [];
  const featureContainment = loadedFeatures.map((feature, index) => ({
    feature,
    featureId: gridlyDirectionalProvenanceFeatureAuditId(feature, index),
    sourceName: gridlyDirectionalProvenanceFeatureSourceName(feature),
    insideCounty: gridlyDirectionalProvenanceFeatureInsideCountyByBounds(feature),
    corridors: gridlyDirectionalProvenanceCorridorsFromFeature(feature),
    segments: typeof flattenRoadGeometrySegments === "function" ? flattenRoadGeometrySegments(feature?.geometry).length : 0,
    sampleText: gridlyDirectionalProvenanceFeatureText(feature).slice(0, 220)
  }));
  const sourceStats = new Map();
  featureContainment.forEach((entry) => {
    if (!sourceStats.has(entry.sourceName)) {
      sourceStats.set(entry.sourceName, {
        sourceName: entry.sourceName,
        sourceType: entry.sourceName === ROADWAY_SEGMENTS_URL ? "local_geojson" : "runtime_or_embedded_geometry",
        participatesIn: ["corridor_inventory", "readiness_scoring", "alias_analysis", "overlap_analysis", "normalization_review"],
        featureCount: 0,
        insideCountyCount: 0,
        outsideCountyCount: 0
      });
    }
    const stats = sourceStats.get(entry.sourceName);
    stats.featureCount += 1;
    if (entry.insideCounty) stats.insideCountyCount += 1;
    else stats.outsideCountyCount += 1;
  });
  const localSourceName = ROADWAY_SEGMENTS_URL || "local_roadway_dataset_geometry";
  if (!sourceStats.has(localSourceName)) {
    sourceStats.set(localSourceName, {
      sourceName: localSourceName,
      sourceType: "local_geojson",
      participatesIn: ["corridor_inventory", "readiness_scoring", "alias_analysis", "overlap_analysis", "normalization_review"],
      featureCount: 0,
      insideCountyCount: 0,
      outsideCountyCount: 0
    });
  }

  const suspiciousCorridorLineage = GRIDLY_DIRECTIONAL_PROVENANCE_CONTAINMENT_SUSPICIOUS_CORRIDORS.map((corridor) => {
    const origin = gridlyDirectionalProvenanceCorridorOriginProfile(corridor);
    const corridorFeatures = new Set(gridlyDirectionalProvenanceFeaturesForCorridor(corridor));
    const normalizedCorridor = normalizeCorridorBaseLabel(corridor);
    const sources = gridlyDirectionalProvenanceUniqueValues(
      featureContainment
        .filter((entry) => entry.corridors.some((candidate) => normalizeCorridorBaseLabel(candidate) === normalizedCorridor)
          || corridorFeatures.has(entry.feature))
        .map((entry) => entry.sourceName),
      8
    );
    const sourceStageIntroduced = origin.sourceFeatures > 0 ? "source_loading" : "not_observed_in_loaded_geometry";
    const firstStageWhereContaminationAppears = origin.sourceFeatures > 0 && origin.insideCountyFeatures === 0
      ? "source_loading"
      : origin.sourceFeatures > 0 && origin.outsideCountyFeatures > 0
        ? "corridor_extraction"
        : "not_detected";
    return {
      corridor,
      sourceDataset: sources[0] || localSourceName,
      sourceDatasets: sources.length ? sources : [localSourceName],
      sourceGeometryCount: origin.sourceFeatures,
      sourceStageIntroduced,
      firstStageWhereContaminationAppears,
      insideCountyFeatures: origin.insideCountyFeatures,
      outsideCountyFeatures: origin.outsideCountyFeatures,
      geometrySegments: origin.geometrySegments,
      normalizationPath: origin.normalizationPath,
      overlapRelationships: origin.overlapRelationships,
      sampleFeatures: origin.sampleFeatures
    };
  });

  const detectedOutsideOnly = (Array.isArray(detectedMajorCorridors) ? detectedMajorCorridors : []).filter((entry) => {
    const profile = gridlyDirectionalProvenanceCorridorOriginProfile(entry?.corridor || "");
    return profile.sourceFeatures > 0 && profile.insideCountyFeatures === 0;
  }).map((entry) => ({
    corridor: entry.corridor,
    roadwayFeatures: entry.roadwayFeatures,
    geometrySegments: entry.geometrySegments,
    tier: entry.tier,
    firstStageWhereContaminationAppears: "corridor_extraction"
  }));

  const outsideFeatures = featureContainment.filter((entry) => !entry.insideCounty);
  const outsideCorridorCounts = {};
  outsideFeatures.forEach((entry) => {
    (entry.corridors.length ? entry.corridors : ["unclassified"]).forEach((corridor) => gridlyDirectionalProvenanceIncrement(outsideCorridorCounts, corridor));
  });

  const containmentFailures = [];
  if (outsideFeatures.length) {
    containmentFailures.push({
      stage: "source_loading",
      failureType: "outside_county_geometry_loaded",
      sourceName: localSourceName,
      featureCount: outsideFeatures.length,
      explanation: "loadRoadwayDataset validates line geometry but does not apply Liberty County containment before storing roadwaySegmentFeatures."
    });
  }
  if (detectedOutsideOnly.length) {
    containmentFailures.push({
      stage: "corridor_extraction",
      failureType: "outside_county_geometry_survives_into_corridor_inventory",
      corridorCount: detectedOutsideOnly.length,
      sampleCorridors: detectedOutsideOnly.slice(0, 12)
    });
  }
  const aliasUnrestricted = Array.isArray(readinessValidation?.aliasCandidates) && readinessValidation.aliasCandidates.some((candidate) => (candidate.corridors || []).some((corridor) => {
    const profile = gridlyDirectionalProvenanceCorridorOriginProfile(corridor);
    return profile.outsideCountyFeatures > 0;
  }));
  if (aliasUnrestricted) {
    containmentFailures.push({
      stage: "alias_detection",
      failureType: "alias_analysis_uses_unrestricted_geometry",
      aliasCandidateCount: readinessValidation.aliasCandidates.length
    });
  }
  const readinessOutside = (Array.isArray(directionalReadiness?.countywide) ? directionalReadiness.countywide : []).filter((entry) => {
    const profile = gridlyDirectionalProvenanceCorridorOriginProfile(entry?.corridor || "");
    return profile.outsideCountyFeatures > 0 && profile.insideCountyFeatures === 0;
  });
  if (readinessOutside.length) {
    containmentFailures.push({
      stage: "readiness_scoring",
      failureType: "readiness_scoring_consumes_unrestricted_geometry",
      corridorCount: readinessOutside.length,
      sampleCorridors: readinessOutside.slice(0, 12).map((entry) => ({
        corridor: entry.corridor,
        readinessScore: entry.readinessScore,
        geometrySegments: entry.geometrySegments,
        roadwayFeatures: entry.roadwayFeatures
      }))
    });
  }

  const readinessImpact = gridlyDirectionalProvenanceContainedReadinessAudit(detectedMajorCorridors, directionalReadiness, runtimeCoverage);
  const suspiciousGeometrySources = Array.from(sourceStats.values()).filter((source) => source.outsideCountyCount > 0).map((source) => ({
    ...source,
    reason: "source_contains_geometry_that_does_not_intersect_liberty_county_bounds"
  }));
  const containmentStages = [
    {
      stage: "source_loading",
      geometrySource: localSourceName,
      countyContainmentApplied: false,
      evidence: "loadRoadwayDataset stores all valid LineString/MultiLineString features from the local GeoJSON without a Liberty County bounds check."
    },
    {
      stage: "normalization",
      countyContainmentApplied: false,
      evidence: "gridlyDirectionalProvenanceCorridorsFromFeature normalizes route/name/ref text from any loaded feature."
    },
    {
      stage: "corridor_extraction",
      countyContainmentApplied: false,
      evidence: "gridlyDirectionalProvenanceCountywideDetectedCorridors iterates every roadwaySegmentFeatures entry without filtering by gridlyDirectionalProvenanceFeatureInsideCounty."
    },
    {
      stage: "alias_detection",
      countyContainmentApplied: false,
      evidence: "readiness validation compares feature-id overlap using gridlyDirectionalProvenanceFeaturesForCorridor, which is sourced from unrestricted roadwaySegmentFeatures."
    },
    {
      stage: "readiness_scoring",
      countyContainmentApplied: false,
      evidence: "directional readiness consumes detectedMajorCorridors built from unrestricted countywide extraction."
    }
  ];
  return {
    available: true,
    version: GRIDLY_DIRECTIONAL_PROVENANCE_COUNTY_GEOMETRY_CONTAINMENT_AUDIT_VERSION,
    auditOnly: true,
    rendersDirectionalUi: false,
    geometrySources: Array.from(sourceStats.values()),
    containmentStages,
    containmentFailures,
    outsideCountyGeometrySummary: {
      loadedFeatureCount: featureContainment.length,
      insideCountyFeatureCount: featureContainment.filter((entry) => entry.insideCounty).length,
      outsideCountyFeatureCount: outsideFeatures.length,
      outsideCountyShare: featureContainment.length ? Number((outsideFeatures.length / featureContainment.length).toFixed(4)) : 0,
      outsideCorridorCounts,
      outsideOnlyDetectedCorridors: detectedOutsideOnly,
      sampleOutsideFeatures: outsideFeatures.slice(0, 10).map((entry) => ({
        featureId: entry.featureId,
        sourceName: entry.sourceName,
        corridors: entry.corridors,
        geometrySegments: entry.segments,
        sampleText: entry.sampleText
      }))
    },
    suspiciousGeometrySources,
    suspiciousCorridorLineage,
    readinessImpactIfContained: readinessImpact.readinessImpactIfContained,
    readinessImpactDetails: readinessImpact.trustedCorridorComparisons,
    containmentSummary: {
      passed: containmentFailures.length === 0,
      failures: containmentFailures.length,
      firstFailureStage: containmentFailures[0]?.stage || null,
      likelyOutcome: containmentFailures.some((failure) => failure.stage === "readiness_scoring")
        ? "B_containment_failure_exists_in_broader_corridor_extraction_stage"
        : containmentFailures.length
          ? "A_containment_failure_isolated_to_audit_or_source_inventory_stage"
          : "no_containment_failures_detected"
    }
  };
}

function gridlyDirectionalProvenanceBuildCountyGeometryContainmentGuard(uncontainedDetectedMajorCorridors = [], containedDetectedMajorCorridors = [], uncontainedDirectionalReadiness = {}, containedDirectionalReadiness = {}) {
  const loadedFeatures = roadwayDatasetLoaded && Array.isArray(roadwaySegmentFeatures) ? roadwaySegmentFeatures : [];
  const insideFeatures = gridlyDirectionalProvenanceCountyContainedFeatures();
  const containedCorridorSet = new Set((Array.isArray(containedDetectedMajorCorridors) ? containedDetectedMajorCorridors : []).map((entry) => entry?.corridor).filter(Boolean));
  const excludedOutsideCountyCorridors = (Array.isArray(uncontainedDetectedMajorCorridors) ? uncontainedDetectedMajorCorridors : [])
    .filter((entry) => entry?.corridor && !containedCorridorSet.has(entry.corridor))
    .map((entry) => ({
      corridor: entry.corridor,
      tier: entry.tier,
      roadwayFeatures: Number(entry.roadwayFeatures || 0),
      geometrySegments: Number(entry.geometrySegments || 0)
    }))
    .sort((a, b) => b.geometrySegments - a.geometrySegments || String(a.corridor).localeCompare(String(b.corridor)));
  const excludedOutsideCountyFeatures = loadedFeatures.length - insideFeatures.length;
  const containedReadinessByCorridor = new Map((Array.isArray(containedDirectionalReadiness?.countywide) ? containedDirectionalReadiness.countywide : []).map((entry) => [entry.corridor, entry]));
  const uncontainedReadinessByCorridor = new Map((Array.isArray(uncontainedDirectionalReadiness?.countywide) ? uncontainedDirectionalReadiness.countywide : []).map((entry) => [entry.corridor, entry]));
  const trustedComparisons = GRIDLY_DIRECTIONAL_PROVENANCE_CONTAINMENT_TRUSTED_CORRIDORS.map((corridor) => {
    const before = uncontainedReadinessByCorridor.get(corridor) || null;
    const after = containedReadinessByCorridor.get(corridor) || null;
    const scoreDelta = before && after ? Number(after.readinessScore || 0) - Number(before.readinessScore || 0) : null;
    return {
      corridor,
      beforeScore: before?.readinessScore ?? null,
      afterScore: after?.readinessScore ?? null,
      scoreDelta,
      beforeStatus: before?.readinessStatus ?? null,
      afterStatus: after?.readinessStatus ?? null,
      statusStable: Boolean(before && after && before.readinessStatus === after.readinessStatus),
      materiallyUnchanged: Boolean(before && after && Math.abs(scoreDelta) <= 5 && before.readinessStatus === after.readinessStatus)
    };
  });
  const passed = trustedComparisons.every((entry) => entry.materiallyUnchanged || (entry.beforeScore === null && entry.afterScore === null));
  return {
    available: true,
    version: GRIDLY_DIRECTIONAL_PROVENANCE_COUNTY_GEOMETRY_CONTAINMENT_AUDIT_VERSION,
    containmentApplied: true,
    excludedOutsideCountyCorridors,
    excludedOutsideCountyFeatures,
    trustedCorridorValidation: {
      passed,
      corridors: trustedComparisons
    }
  };
}

function gridlyDirectionalProvenanceAreaCorridorInventory(records = [], scopedRecords = []) {
  const loadedFeatures = roadwayDatasetLoaded && Array.isArray(roadwaySegmentFeatures) ? roadwaySegmentFeatures : [];
  const areas = Array.isArray(GRIDLY_AWARENESS_AREA_DEFINITIONS)
    ? GRIDLY_AWARENESS_AREA_DEFINITIONS.filter((area) => area && area.key !== "other")
    : [];
  return areas.reduce((inventory, area) => {
    const corridorStats = new Map();
    loadedFeatures.forEach((feature) => {
      const corridors = gridlyDirectionalProvenanceCorridorsFromFeature(feature);
      if (!corridors.length) return;
      const segments = typeof flattenRoadGeometrySegments === "function" ? flattenRoadGeometrySegments(feature?.geometry) : [];
      const areaSegments = segments.filter((segment) => gridlyDirectionalProvenanceSegmentInAwarenessArea(segment, area));
      if (!areaSegments.length) return;
      corridors.forEach((corridor) => {
        if (!corridorStats.has(corridor)) {
          corridorStats.set(corridor, {
            corridor,
            tier: gridlyDirectionalProvenanceCorridorTier(corridor),
            roadwayFeatures: 0,
            geometrySegments: 0,
            predominantAxis: "mixed",
            geometryCapable: false,
            axisSegmentBreakdown: { EW: 0, NS: 0 }
          });
        }
        const stats = corridorStats.get(corridor);
        stats.roadwayFeatures += 1;
        stats.geometrySegments += areaSegments.length;
        areaSegments.forEach((segment) => {
          const bearing = typeof gridlyRoadBearingDegrees === "function"
            ? gridlyRoadBearingDegrees(segment.startLat, segment.startLng, segment.endLat, segment.endLng)
            : null;
          const axis = gridlyDirectionalProvenanceAxisFromBearing(bearing);
          if (axis) stats.axisSegmentBreakdown[axis] += 1;
        });
      });
    });
    const runtimeCoverage = gridlyDirectionalProvenanceAreaRuntimeCoverage(area, records, scopedRecords);
    const detectedMajorCorridors = Array.from(corridorStats.values())
      .map((stats) => ({
        ...stats,
        tier: gridlyDirectionalProvenanceCorridorTier(stats.corridor, stats),
        geometryCapable: stats.geometrySegments > 0,
        predominantAxis: gridlyDirectionalProvenancePredominantAxis(stats.axisSegmentBreakdown)
      }))
      .sort((a, b) => b.geometrySegments - a.geometrySegments || b.roadwayFeatures - a.roadwayFeatures || a.corridor.localeCompare(b.corridor));
    runtimeCoverage.corridorsWithoutRuntimeSamples = detectedMajorCorridors
      .map((entry) => entry.corridor)
      .filter((corridor) => !runtimeCoverage.corridorCoverageCounts[corridor]);
    inventory[gridlyDirectionalProvenanceAreaInventoryKey(area)] = {
      areaKey: area.key || null,
      label: area.label || area.storageValue || "Awareness Area",
      source: area.source || "",
      detectedMajorCorridors,
      geometryCapableCorridors: detectedMajorCorridors.filter((entry) => entry.geometryCapable),
      tierBreakdown: gridlyDirectionalProvenanceTierBreakdown(detectedMajorCorridors),
      runtimeCoverage,
      corridorCount: detectedMajorCorridors.length
    };
    return inventory;
  }, {});
}

function gridlyDirectionalProvenanceGeometryInventory() {
  const loadedFeatures = roadwayDatasetLoaded && Array.isArray(roadwaySegmentFeatures) ? roadwaySegmentFeatures : [];
  return GRIDLY_DIRECTIONAL_PROVENANCE_CORRIDORS.reduce((inventory, corridor) => {
    const corridorFeatures = loadedFeatures.filter((feature) => gridlyDirectionalProvenanceFeatureMatchesCorridor(feature, corridor));
    const axisCounts = { EW: 0, NS: 0 };
    let geometrySegments = 0;
    corridorFeatures.forEach((feature) => {
      const segments = typeof flattenRoadGeometrySegments === "function" ? flattenRoadGeometrySegments(feature?.geometry) : [];
      geometrySegments += segments.length;
      segments.forEach((segment) => {
        const bearing = typeof gridlyRoadBearingDegrees === "function"
          ? gridlyRoadBearingDegrees(segment.startLat, segment.startLng, segment.endLat, segment.endLng)
          : null;
        const axis = gridlyDirectionalProvenanceAxisFromBearing(bearing);
        if (axis) axisCounts[axis] += 1;
      });
    });
    inventory[corridor] = {
      corridor,
      tier: gridlyDirectionalProvenanceCorridorTier(corridor, { roadwayFeatures: corridorFeatures.length, geometrySegments }),
      found: corridorFeatures.length > 0,
      geometryCapable: geometrySegments > 0,
      roadwayFeatures: corridorFeatures.length,
      geometrySegments,
      predominantAxis: gridlyDirectionalProvenancePredominantAxis(axisCounts),
      axisSegmentBreakdown: axisCounts
    };
    return inventory;
  }, {});
}

function gridlyDirectionalProvenanceCountywideDetectedCorridors() {
  const loadedFeatures = roadwayDatasetLoaded && Array.isArray(roadwaySegmentFeatures) ? roadwaySegmentFeatures : [];
  const corridorStats = new Map();
  loadedFeatures.forEach((feature) => {
    const corridors = gridlyDirectionalProvenanceCorridorsFromFeature(feature);
    if (!corridors.length) return;
    const segments = typeof flattenRoadGeometrySegments === "function" ? flattenRoadGeometrySegments(feature?.geometry) : [];
    corridors.forEach((corridor) => {
      if (!corridorStats.has(corridor)) {
        corridorStats.set(corridor, {
          corridor,
          tier: gridlyDirectionalProvenanceCorridorTier(corridor),
          roadwayFeatures: 0,
          geometrySegments: 0,
          predominantAxis: "mixed",
          geometryCapable: false,
          axisSegmentBreakdown: { EW: 0, NS: 0 }
        });
      }
      const stats = corridorStats.get(corridor);
      stats.roadwayFeatures += 1;
      stats.geometrySegments += segments.length;
      segments.forEach((segment) => {
        const bearing = typeof gridlyRoadBearingDegrees === "function"
          ? gridlyRoadBearingDegrees(segment.startLat, segment.startLng, segment.endLat, segment.endLng)
          : null;
        const axis = gridlyDirectionalProvenanceAxisFromBearing(bearing);
        if (axis) stats.axisSegmentBreakdown[axis] += 1;
      });
    });
  });
  return Array.from(corridorStats.values())
    .map((stats) => ({
      ...stats,
      tier: gridlyDirectionalProvenanceCorridorTier(stats.corridor, stats),
      geometryCapable: stats.geometrySegments > 0,
      predominantAxis: gridlyDirectionalProvenancePredominantAxis(stats.axisSegmentBreakdown)
    }))
    .sort((a, b) => b.geometrySegments - a.geometrySegments || b.roadwayFeatures - a.roadwayFeatures || a.corridor.localeCompare(b.corridor));
}

function gridlyDirectionalProvenanceTierBreakdownValidation(tierBreakdown = {}, corridorCount = 0) {
  const tierTotal = Number(tierBreakdown.primary || 0) + Number(tierBreakdown.secondary || 0) + Number(tierBreakdown.local || 0);
  const expectedCount = Number(corridorCount || 0);
  if (tierTotal === expectedCount) {
    return {
      passed: true,
      reason: "tier_breakdown_total_matches_countywide_corridor_count"
    };
  }
  return {
    passed: false,
    reason: `tier_breakdown_total_${tierTotal}_does_not_match_countywide_corridor_count_${expectedCount}`
  };
}

function gridlyDirectionalProvenanceAwarenessContext() {
  const selectedFilter = typeof activeGeoFilter !== "undefined" && activeGeoFilter ? activeGeoFilter : null;
  let filter = null;
  try {
    filter = typeof gridlyGetSelectedAlertAreaFilter === "function" ? gridlyGetSelectedAlertAreaFilter() : null;
  } catch (_error) {
    filter = null;
  }
  let selectedArea = filter?.area || null;
  if (!selectedArea) {
    try {
      selectedArea = typeof getGridlySelectedAwarenessArea === "function" ? getGridlySelectedAwarenessArea() : null;
    } catch (_error) {
      selectedArea = null;
    }
  }
  const debugArea = selectedArea && typeof getGridlyAwarenessAreaDebugOption === "function"
    ? getGridlyAwarenessAreaDebugOption(selectedArea)
    : (selectedArea ? {
      key: selectedArea.key || null,
      label: selectedArea.label || selectedArea.storageValue || "",
      storageValue: selectedArea.storageValue || selectedArea.label || "",
      radiusMiles: selectedArea.radiusMiles ?? null,
      countyWide: selectedArea.countyWide === true,
      fallback: selectedArea.fallback === true,
      source: selectedArea.source || ""
    } : null);
  const isCountyMode = Boolean(
    filter?.mode === "county"
    || !selectedArea
    || selectedArea?.countyWide === true
    || selectedArea?.fallback === true
  );
  return {
    selectedAwarenessArea: debugArea,
    selectedAwarenessAreaKey: selectedArea?.key || debugArea?.key || null,
    selectedFilter: selectedFilter || filter?.mode || null,
    isCountyMode,
    source: filter ? "gridlyGetSelectedAlertAreaFilter" : (selectedArea ? "getGridlySelectedAwarenessArea" : "unavailable")
  };
}

function gridlyDirectionalProvenanceRecordInAwarenessScope(record = {}, awarenessContext = {}) {
  if (awarenessContext.isCountyMode) return true;
  const key = awarenessContext.selectedAwarenessAreaKey;
  const area = key && GRIDLY_AWARENESS_AREA_BY_KEY ? GRIDLY_AWARENESS_AREA_BY_KEY[key] : null;
  if (!area) return false;
  try {
    return typeof isGridlyRecordInAwarenessArea === "function" ? isGridlyRecordInAwarenessArea(record, area) : true;
  } catch (_error) {
    return false;
  }
}

function gridlyDirectionalProvenanceEmptyCorridorCoverage() {
  return GRIDLY_DIRECTIONAL_PROVENANCE_CORRIDORS.reduce((coverage, corridor) => {
    coverage[corridor] = 0;
    return coverage;
  }, {});
}

function gridlyDirectionalProvenanceEvaluateAuditRecords(records = [], options = {}, sampleLimit = 8) {
  const corridorBreakdown = {};
  const corridorRuntimeCoverage = gridlyDirectionalProvenanceEmptyCorridorCoverage();
  const directionSourceBreakdown = {};
  const fallbackReasonBreakdown = {};
  const sampleRecords = [];
  let highConfidence = 0;
  let mediumConfidence = 0;
  let lowConfidence = 0;
  let suppressed = 0;

  records.forEach((record, index) => {
    const provenance = gridlyBuildDirectionalProvenance(record, options);
    if (provenance.confidence === "high") highConfidence += 1;
    else if (provenance.confidence === "medium") mediumConfidence += 1;
    else lowConfidence += 1;
    if (provenance.suppressed) suppressed += 1;
    gridlyDirectionalProvenanceIncrement(corridorBreakdown, provenance.corridor || "out_of_scope_or_unknown");
    if (provenance.corridor && Object.prototype.hasOwnProperty.call(corridorRuntimeCoverage, provenance.corridor)) {
      corridorRuntimeCoverage[provenance.corridor] += 1;
    }
    gridlyDirectionalProvenanceIncrement(directionSourceBreakdown, provenance.directionSource);
    gridlyDirectionalProvenanceIncrement(fallbackReasonBreakdown, provenance.fallbackReason || "none");
    if (sampleRecords.length < sampleLimit) {
      sampleRecords.push({
        recordId: String(record?.id || record?.report_id || record?.reportId || `record_${index}`),
        provenance
      });
    }
  });

  return {
    runtimeEvaluated: records.length,
    highConfidence,
    mediumConfidence,
    lowConfidence,
    suppressed,
    corridorRuntimeCoverage,
    corridorsWithoutRuntimeCoverage: GRIDLY_DIRECTIONAL_PROVENANCE_CORRIDORS.filter((corridor) => !corridorRuntimeCoverage[corridor]),
    corridorBreakdown,
    directionSourceBreakdown,
    fallbackReasonBreakdown,
    sampleRecords
  };
}


function gridlyDirectionalProvenancePriorityCorridorStats(corridor = "", detectedMajorCorridors = []) {
  const label = normalizeCorridorBaseLabel(String(corridor || ""));
  const detected = (Array.isArray(detectedMajorCorridors) ? detectedMajorCorridors : [])
    .find((entry) => normalizeCorridorBaseLabel(entry?.corridor || "") === label);
  if (detected) return detected;
  const features = gridlyDirectionalProvenanceFeaturesForCorridor(label, { countyContained: true });
  const [derived] = gridlyDirectionalProvenanceBuildStatsFromFeatures(features, { source: "priority_corridor_safelist_audit" })
    .filter((entry) => normalizeCorridorBaseLabel(entry?.corridor || "") === label);
  return derived || {
    corridor: label,
    source: "priority_corridor_safelist_audit_missing_geometry",
    tier: gridlyDirectionalProvenanceCorridorTier(label),
    roadwayFeatures: 0,
    geometrySegments: 0,
    predominantAxis: "mixed",
    geometryCapable: false,
    axisSegmentBreakdown: { EW: 0, NS: 0 }
  };
}

function gridlyDirectionalProvenancePriorityCorridorAudit(directionalReadiness = {}, detectedMajorCorridors = [], runtimeCoverage = {}) {
  const readinessByCorridor = new Map((Array.isArray(directionalReadiness?.countywide) ? directionalReadiness.countywide : [])
    .map((entry) => [normalizeCorridorBaseLabel(entry?.corridor || ""), entry]));
  const detectedSet = new Set((Array.isArray(detectedMajorCorridors) ? detectedMajorCorridors : [])
    .map((entry) => normalizeCorridorBaseLabel(entry?.corridor || ""))
    .filter(Boolean));
  const priorityLabels = Array.from(new Set([
    ...GRIDLY_DIRECTIONAL_PROVENANCE_COUNTYWIDE_PRIORITY_CORRIDORS,
    ...GRIDLY_DIRECTIONAL_PROVENANCE_COMMUNITY_CRITICAL_CORRIDORS
  ].map((corridor) => normalizeCorridorBaseLabel(corridor)).filter(Boolean)));
  const categoryForCorridor = (corridor) => GRIDLY_DIRECTIONAL_PROVENANCE_COUNTYWIDE_PRIORITY_CORRIDORS.includes(corridor)
    ? "countywide"
    : "communityCritical";
  const buildEntry = (corridor) => {
    const current = readinessByCorridor.get(corridor) || null;
    const stats = gridlyDirectionalProvenancePriorityCorridorStats(corridor, detectedMajorCorridors);
    const features = gridlyDirectionalProvenanceFeaturesForCorridor(corridor, { countyContained: true });
    const readinessEntry = current || gridlyDirectionalProvenanceReadinessEntryForAudit(stats, runtimeCoverage, features);
    const category = categoryForCorridor(corridor);
    return {
      corridor,
      tier: readinessEntry.tier || gridlyDirectionalProvenanceCorridorTier(corridor, stats),
      readinessScore: Number(readinessEntry.readinessScore || 0),
      readinessStatus: readinessEntry.readinessStatus || gridlyDirectionalProvenanceReadinessBucket(readinessEntry.readinessScore, readinessEntry.tier),
      priorityCorridor: true,
      category,
      countywidePriority: category === "countywide",
      communityCritical: category === "communityCritical",
      communities: GRIDLY_DIRECTIONAL_PROVENANCE_PRIORITY_CORRIDOR_COMMUNITIES[corridor] || [],
      directionalDisplayAllowed: false,
      includedInReadinessEvaluation: true,
      currentlyInDirectionalReadiness: Boolean(current),
      currentlyInCountyContainedInventory: detectedSet.has(corridor),
      underEvaluation: true,
      auditOnly: true,
      governanceOnly: true
    };
  };
  const priorityCorridors = priorityLabels.map(buildEntry);
  const missingPriorityCorridors = priorityCorridors
    .filter((entry) => !entry.currentlyInDirectionalReadiness || !entry.currentlyInCountyContainedInventory)
    .map((entry) => ({
      corridor: entry.corridor,
      category: entry.category,
      communities: entry.communities,
      currentlyInDirectionalReadiness: entry.currentlyInDirectionalReadiness,
      currentlyInCountyContainedInventory: entry.currentlyInCountyContainedInventory,
      includedInReadinessEvaluation: entry.includedInReadinessEvaluation,
      directionalDisplayAllowed: false,
      reason: entry.currentlyInDirectionalReadiness
        ? "priority_corridor_missing_from_county_contained_inventory"
        : "priority_corridor_missing_from_current_directional_readiness_output"
    }));
  const summary = {
    totalPriorityCorridors: priorityCorridors.length,
    countywidePriorityCorridors: priorityCorridors.filter((entry) => entry.category === "countywide").length,
    communityCriticalCorridors: priorityCorridors.filter((entry) => entry.category === "communityCritical").length,
    readinessProtectedCorridors: priorityCorridors.filter((entry) => entry.includedInReadinessEvaluation).length,
    ready: priorityCorridors.filter((entry) => entry.readinessStatus === "ready").length,
    conditional: priorityCorridors.filter((entry) => entry.readinessStatus === "conditional").length,
    notReady: priorityCorridors.filter((entry) => entry.readinessStatus === "notReady").length,
    missingPriorityCorridors: missingPriorityCorridors.length,
    directionalDisplayAllowed: 0,
    auditOnly: true,
    governanceOnly: true
  };
  return {
    available: true,
    version: GRIDLY_DIRECTIONAL_PROVENANCE_PRIORITY_CORRIDOR_AUDIT_VERSION,
    priorityCorridors,
    countywidePriorityCorridors: priorityCorridors.filter((entry) => entry.category === "countywide"),
    communityCriticalCorridors: priorityCorridors.filter((entry) => entry.category === "communityCritical"),
    readinessProtectedCorridors: priorityCorridors.filter((entry) => entry.includedInReadinessEvaluation),
    missingPriorityCorridors,
    summary
  };
}

function gridlyDirectionalProvenanceAudit(options = {}) {
  const records = gridlyDirectionalProvenanceRecords(options);
  const maxRecords = Number.isFinite(Number(options.maxRecords)) ? Math.max(0, Number(options.maxRecords)) : records.length;
  const evaluatedRecords = records.slice(0, maxRecords);
  const sampleLimit = Number.isFinite(Number(options.sampleLimit)) ? Math.max(0, Number(options.sampleLimit)) : 8;
  const awarenessContext = gridlyDirectionalProvenanceAwarenessContext();
  const scopedEvaluatedRecords = evaluatedRecords.filter((record) => gridlyDirectionalProvenanceRecordInAwarenessScope(record, awarenessContext));
  const globalEvaluation = gridlyDirectionalProvenanceEvaluateAuditRecords(evaluatedRecords, options, sampleLimit);
  const scopedEvaluation = gridlyDirectionalProvenanceEvaluateAuditRecords(scopedEvaluatedRecords, options, sampleLimit);
  const geometryInventory = gridlyDirectionalProvenanceGeometryInventory();
  const uncontainedDetectedMajorCorridors = gridlyDirectionalProvenanceCountywideDetectedCorridors();
  const detectedMajorCorridors = gridlyDirectionalProvenanceCountyContainedCorridors();
  const countywideTierBreakdown = gridlyDirectionalProvenanceTierBreakdown(uncontainedDetectedMajorCorridors);
  const containedTierBreakdown = gridlyDirectionalProvenanceTierBreakdown(detectedMajorCorridors);
  const countywideGeometryInventory = {
    scope: "countywide",
    corridorCount: uncontainedDetectedMajorCorridors.length,
    tierBreakdown: countywideTierBreakdown,
    tierBreakdownValidation: gridlyDirectionalProvenanceTierBreakdownValidation(countywideTierBreakdown, uncontainedDetectedMajorCorridors.length),
    detectedMajorCorridors: uncontainedDetectedMajorCorridors,
    countyContainedDetectedMajorCorridors: detectedMajorCorridors,
    countyContainedCorridorCount: detectedMajorCorridors.length,
    countyContainedTierBreakdown: containedTierBreakdown,
    countyContainedTierBreakdownValidation: gridlyDirectionalProvenanceTierBreakdownValidation(containedTierBreakdown, detectedMajorCorridors.length),
    corridors: geometryInventory,
    directionalSeedGeometryInventory: geometryInventory,
    directionalSeedTierBreakdown: gridlyDirectionalProvenanceTierBreakdown(Object.values(geometryInventory))
  };
  const areaCorridorInventory = gridlyDirectionalProvenanceAreaCorridorInventory(evaluatedRecords, scopedEvaluatedRecords);
  const uncontainedDirectionalReadiness = gridlyDirectionalProvenanceDirectionalReadiness(uncontainedDetectedMajorCorridors, globalEvaluation.corridorRuntimeCoverage);
  const directionalReadiness = gridlyDirectionalProvenanceDirectionalReadiness(detectedMajorCorridors, globalEvaluation.corridorRuntimeCoverage, { countyContained: true });
  const readinessValidation = gridlyDirectionalProvenanceReadinessValidation(directionalReadiness, detectedMajorCorridors, { countyContained: true });
  const countyGeometryContainmentGuard = gridlyDirectionalProvenanceBuildCountyGeometryContainmentGuard(
    uncontainedDetectedMajorCorridors,
    detectedMajorCorridors,
    uncontainedDirectionalReadiness,
    directionalReadiness
  );
  const countyGeometryContainmentAudit = gridlyDirectionalProvenanceCountyGeometryContainmentAudit(
    detectedMajorCorridors,
    directionalReadiness,
    readinessValidation,
    globalEvaluation.corridorRuntimeCoverage
  );
  const priorityCorridorAudit = gridlyDirectionalProvenancePriorityCorridorAudit(
    directionalReadiness,
    detectedMajorCorridors,
    globalEvaluation.corridorRuntimeCoverage
  );

  return {
    available: true,
    version: GRIDLY_DIRECTIONAL_PROVENANCE_AUDIT_VERSION,
    auditOnly: true,
    rendersDirectionalUi: false,
    awarenessContext,
    globalRuntimeEvaluated: globalEvaluation.runtimeEvaluated,
    scopedRuntimeEvaluated: scopedEvaluation.runtimeEvaluated,
    totalEvaluated: globalEvaluation.runtimeEvaluated,
    runtimeEvaluated: globalEvaluation.runtimeEvaluated,
    globalHighConfidence: globalEvaluation.highConfidence,
    globalMediumConfidence: globalEvaluation.mediumConfidence,
    globalLowConfidence: globalEvaluation.lowConfidence,
    globalSuppressed: globalEvaluation.suppressed,
    scopedHighConfidence: scopedEvaluation.highConfidence,
    scopedMediumConfidence: scopedEvaluation.mediumConfidence,
    scopedLowConfidence: scopedEvaluation.lowConfidence,
    scopedSuppressed: scopedEvaluation.suppressed,
    highConfidence: globalEvaluation.highConfidence,
    mediumConfidence: globalEvaluation.mediumConfidence,
    lowConfidence: globalEvaluation.lowConfidence,
    suppressed: globalEvaluation.suppressed,
    countywideGeometryInventory,
    areaCorridorInventory,
    directionalReadiness,
    readinessValidation,
    corridorPurityAudit: gridlyDirectionalProvenanceCorridorPurityAudit(directionalReadiness, detectedMajorCorridors, readinessValidation, { countyContained: true }),
    priorityCorridorAudit,
    countyGeometryContainmentGuard,
    countyGeometryContainmentAudit,
    readinessSummary: directionalReadiness.readinessSummary,
    geometryInventory: countywideGeometryInventory,
    globalCorridorRuntimeCoverage: globalEvaluation.corridorRuntimeCoverage,
    scopedCorridorRuntimeCoverage: scopedEvaluation.corridorRuntimeCoverage,
    corridorRuntimeCoverage: globalEvaluation.corridorRuntimeCoverage,
    corridorsWithoutRuntimeCoverage: globalEvaluation.corridorsWithoutRuntimeCoverage,
    corridorsWithoutScopedRuntimeCoverage: scopedEvaluation.corridorsWithoutRuntimeCoverage,
    globalCorridorBreakdown: globalEvaluation.corridorBreakdown,
    scopedCorridorBreakdown: scopedEvaluation.corridorBreakdown,
    corridorBreakdown: globalEvaluation.corridorBreakdown,
    globalDirectionSourceBreakdown: globalEvaluation.directionSourceBreakdown,
    scopedDirectionSourceBreakdown: scopedEvaluation.directionSourceBreakdown,
    directionSourceBreakdown: globalEvaluation.directionSourceBreakdown,
    globalFallbackReasonBreakdown: globalEvaluation.fallbackReasonBreakdown,
    scopedFallbackReasonBreakdown: scopedEvaluation.fallbackReasonBreakdown,
    fallbackReasonBreakdown: globalEvaluation.fallbackReasonBreakdown,
    globalSampleRecords: globalEvaluation.sampleRecords,
    scopedSampleRecords: scopedEvaluation.sampleRecords,
    sampleRecords: globalEvaluation.sampleRecords
  };
}

if (typeof window !== "undefined") {
  window.gridlyBuildDirectionalProvenance = gridlyBuildDirectionalProvenance;
  window.gridlyDirectionalProvenanceAudit = gridlyDirectionalProvenanceAudit;
}
exposeGridlyAuditHelper("gridlyDirectionalProvenanceAudit", gridlyDirectionalProvenanceAudit);

function gridlyDirectionalRoadNameFromFeature(feature = {}, roadEvaluationContext = null) {
  const evaluationContext = roadEvaluationContext || buildGridlyRoadEvaluationContext();
  const props = feature?.properties || {};
  const candidates = [props.name, props.ref, props.highway]
    .map((value) => typeof evaluateRoadNameCandidate === "function" ? evaluateRoadNameCandidate(value, evaluationContext) : { valid: Boolean(value), normalized: String(value || "").trim() });
  return candidates.find((entry) => entry.valid)?.normalized || "Unknown road";
}

function gridlyBuildLocalDirectionalRoadCandidates(tapCoordinate, options = {}) {
  const tap = gridlyCoordinateFromRecord(tapCoordinate);
  if (!tap || !roadwayDatasetLoaded || !Array.isArray(roadwaySegmentFeatures) || !roadwaySegmentFeatures.length) return [];
  const roadEvaluationContext = options.roadEvaluationContext || buildGridlyRoadEvaluationOperationContext();
  const maxDistanceMeters = Number.isFinite(Number(options.maxDistanceMeters)) ? Number(options.maxDistanceMeters) : 75;
  const maxDistanceMiles = maxDistanceMeters / 1609.344;
  const bestByFeature = new Map();
  roadwaySegmentFeatures.forEach((feature, featureIndex) => {
    const segments = flattenRoadGeometrySegments(feature?.geometry);
    for (const segment of segments) {
      const projection = projectPointToRoadSegment(tap.lat, tap.lng, segment.startLat, segment.startLng, segment.endLat, segment.endLng);
      if (!projection || !Number.isFinite(projection.distanceMiles) || projection.distanceMiles > maxDistanceMiles) continue;
      const current = bestByFeature.get(featureIndex);
      if (!current || projection.distanceMiles < current.distanceMiles) bestByFeature.set(featureIndex, { feature, featureIndex, projection });
    }
  });
  return Array.from(bestByFeature.values())
    .map((entry) => {
      const distanceMeters = entry.projection.distanceMiles * 1609.344;
      const roadName = gridlyDirectionalRoadNameFromFeature(entry.feature, roadEvaluationContext);
      const bearing = entry.projection.segmentBearing;
      const inferredDirection = gridlyInferCardinalRoadDirection(bearing);
      const props = entry.feature?.properties || {};
      return {
        source: "local_roadway_dataset_geometry",
        roadName,
        candidateCoordinate: entry.projection.coordinate,
        distanceFromTapMeters: Number(distanceMeters.toFixed(1)),
        bearing,
        inferredDirection,
        directionConfidence: Number.isFinite(Number(bearing)) ? "medium" : "low",
        featureId: props["@id"] || props.id || null,
        oneWay: props.oneway || null,
        highway: props.highway || null,
        segmentStart: entry.projection.segmentStart,
        segmentEnd: entry.projection.segmentEnd,
        geometryAvailable: true,
        rank: 0,
        selected: false,
        selectionReason: "pending_rank"
      };
    })
    .sort((a, b) => Number(a.distanceFromTapMeters || Infinity) - Number(b.distanceFromTapMeters || Infinity))
    .slice(0, 12)
    .map((candidate, index) => ({ ...candidate, rank: index + 1 }));
}


function gridlyRoadwaySegmentId(feature, featureIndex, segmentIndex) {
  const props = feature?.properties || {};
  const baseId = props["@id"] || props.id || props.osm_id || props.way_id || props.gid || `feature_${featureIndex}`;
  return `${baseId}::segment_${segmentIndex}`;
}

function gridlyRoadwayGeometryLengthMeters(startLat, startLng, endLat, endLng) {
  const miles = haversineDistance(startLat, startLng, endLat, endLng);
  return Number.isFinite(miles) ? gridlyRoadwayAuditRound(miles * 1609.344, 1) : null;
}

function gridlyRoadNameKey(value) {
  return gridlyRoadwayAuditNormalizeText(value).toLowerCase();
}

function gridlyBuildGeometryAwareRoadCandidates(tapCoordinate, options = {}) {
  const tap = gridlyCoordinateFromRecord(tapCoordinate);
  if (!tap || !roadwayDatasetLoaded || !Array.isArray(roadwaySegmentFeatures) || !roadwaySegmentFeatures.length) return [];
  const maxDistanceMeters = Number.isFinite(Number(options.maxDistanceMeters)) ? Number(options.maxDistanceMeters) : 75;
  const limit = Number.isFinite(Number(options.limit)) ? Math.max(1, Number(options.limit)) : 16;
  const maxDistanceMiles = maxDistanceMeters / 1609.344;
  const candidates = [];
  roadwaySegmentFeatures.forEach((feature, featureIndex) => {
    const segments = flattenRoadGeometrySegments(feature?.geometry);
    segments.forEach((segment, segmentIndex) => {
      const projection = projectPointToRoadSegment(tap.lat, tap.lng, segment.startLat, segment.startLng, segment.endLat, segment.endLng);
      if (!projection || !Number.isFinite(projection.distanceMiles) || projection.distanceMiles > maxDistanceMiles) return;
      const distanceMeters = projection.distanceMiles * 1609.344;
      const roadName = gridlyDirectionalRoadNameFromFeature(feature);
      const bearing = projection.segmentBearing;
      const segmentLengthMeters = gridlyRoadwayGeometryLengthMeters(segment.startLat, segment.startLng, segment.endLat, segment.endLng);
      const props = feature?.properties || {};
      candidates.push({
        source: "local_roadway_dataset_geometry",
        segmentId: gridlyRoadwaySegmentId(feature, featureIndex, segmentIndex),
        featureIndex,
        segmentIndex,
        featureId: props["@id"] || props.id || props.osm_id || props.way_id || props.gid || null,
        roadName,
        roadNameKey: gridlyRoadNameKey(roadName),
        distanceFromTapMeters: gridlyRoadwayAuditRound(distanceMeters, 1),
        candidateCoordinate: {
          lat: gridlyRoadwayAuditRound(projection.coordinate.lat, 7),
          lng: gridlyRoadwayAuditRound(projection.coordinate.lng, 7)
        },
        segmentStart: {
          lat: gridlyRoadwayAuditRound(segment.startLat, 7),
          lng: gridlyRoadwayAuditRound(segment.startLng, 7)
        },
        segmentEnd: {
          lat: gridlyRoadwayAuditRound(segment.endLat, 7),
          lng: gridlyRoadwayAuditRound(segment.endLng, 7)
        },
        segmentCenter: {
          lat: gridlyRoadwayAuditRound((segment.startLat + segment.endLat) / 2, 7),
          lng: gridlyRoadwayAuditRound((segment.startLng + segment.endLng) / 2, 7)
        },
        bearing: Number.isFinite(Number(bearing)) ? gridlyRoadwayAuditRound(bearing, 1) : null,
        geometryLengthMeters: segmentLengthMeters,
        oneWay: props.oneway || null,
        highway: props.highway || null,
        ref: props.ref || null,
        placement: props.placement || null,
        lanes: props.lanes || null,
        inferredDirection: gridlyInferCardinalRoadDirection(bearing),
        directionConfidence: Number.isFinite(Number(bearing)) ? "medium" : "low",
        rank: 0,
        selected: false,
        selectionReason: "pending_geometry_aware_rank"
      });
    });
  });
  return candidates
    .sort((a, b) => Number(a.distanceFromTapMeters || Infinity) - Number(b.distanceFromTapMeters || Infinity)
      || String(a.roadName || "").localeCompare(String(b.roadName || ""))
      || String(a.segmentId || "").localeCompare(String(b.segmentId || "")))
    .slice(0, limit)
    .map((candidate, index) => ({ ...candidate, rank: index + 1 }));
}

function gridlySelectGeometryAwareRoadSegment(candidates = []) {
  const sorted = (Array.isArray(candidates) ? candidates : [])
    .filter((candidate) => Number.isFinite(Number(candidate?.distanceFromTapMeters)))
    .sort((a, b) => Number(a.distanceFromTapMeters) - Number(b.distanceFromTapMeters));
  if (!sorted.length) {
    return {
      selectedSegment: null,
      selectedSegmentReason: "no_local_roadway_geometry_candidate_within_radius",
      sameRoadCandidateCount: 0,
      oppositeSideCandidateCount: 0,
      dividedRoadRisk: false,
      selectedSideConfidence: "low",
      canSupportFutureDirectionalLabels: false,
      recommendedDirection: null,
      directionConfidence: "low"
    };
  }
  const selected = sorted[0];
  const sameRoadCandidates = selected.roadNameKey
    ? sorted.filter((candidate) => candidate.roadNameKey === selected.roadNameKey)
    : [];
  const sameRoadParallelCandidates = sameRoadCandidates.filter((candidate) => {
    if (candidate.segmentId === selected.segmentId) return false;
    const bearingDifference = gridlyBearingDifferenceDegrees(selected.bearing, candidate.bearing);
    return Number(candidate.distanceFromTapMeters) <= 90
      && (bearingDifference === null || bearingDifference <= 30 || bearingDifference >= 150);
  });
  const nearestOpposite = sameRoadParallelCandidates[0] || null;
  const distanceGap = nearestOpposite && Number.isFinite(Number(nearestOpposite.distanceFromTapMeters))
    ? gridlyRoadwayAuditRound(Number(nearestOpposite.distanceFromTapMeters) - Number(selected.distanceFromTapMeters), 1)
    : null;
  const bearingDifferences = sameRoadParallelCandidates
    .map((candidate) => gridlyBearingDifferenceDegrees(selected.bearing, candidate.bearing))
    .filter(Number.isFinite);
  const bearingConsistent = !bearingDifferences.length || bearingDifferences.some((difference) => difference <= 30 || difference >= 150);
  const dividedRoadRisk = sameRoadParallelCandidates.length > 0 && Number.isFinite(Number(nearestOpposite?.distanceFromTapMeters)) && Number(nearestOpposite.distanceFromTapMeters) <= 35;
  const selectedDistance = Number(selected.distanceFromTapMeters);
  const selectedSideConfidence = !Number.isFinite(selectedDistance) ? "low"
    : (dividedRoadRisk && Number.isFinite(distanceGap) && distanceGap >= 10 && selectedDistance <= 12 && bearingConsistent) ? "high"
      : (dividedRoadRisk && Number.isFinite(distanceGap) && distanceGap >= 5 && selectedDistance <= 20) ? "medium"
        : dividedRoadRisk ? "low"
          : selectedDistance <= 12 ? "high"
            : selectedDistance <= 25 ? "medium" : "low";
  const directionConfidence = Number.isFinite(Number(selected.bearing))
    ? (selectedSideConfidence === "high" ? "medium" : selectedSideConfidence === "medium" ? "low" : "low")
    : "low";
  const canSupportFutureDirectionalLabels = Boolean(
    Number.isFinite(Number(selected.bearing))
    && selectedSideConfidence !== "low"
    && sameRoadCandidates.length > 0
  );
  return {
    selectedSegment: {
      ...selected,
      selected: true,
      selectionReason: "nearest_geometry_segment_selected; same-road continuity and divided-road separation checked before directional confidence is assigned"
    },
    selectedSegmentReason: "nearest_geometry_segment_selected_with_same_road_and_parallel_carriageway_diagnostics",
    sameRoadCandidateCount: sameRoadCandidates.length,
    oppositeSideCandidateCount: sameRoadParallelCandidates.length,
    dividedRoadRisk,
    selectedSideConfidence,
    canSupportFutureDirectionalLabels,
    recommendedDirection: gridlyInferCardinalRoadDirection(selected.bearing),
    directionConfidence,
    sameRoadParallelCandidates: sameRoadParallelCandidates.slice(0, 6).map((candidate) => ({
      segmentId: candidate.segmentId,
      roadName: candidate.roadName,
      distanceFromTapMeters: candidate.distanceFromTapMeters,
      bearing: candidate.bearing,
      bearingDifferenceFromSelected: gridlyBearingDifferenceDegrees(selected.bearing, candidate.bearing),
      segmentCenter: candidate.segmentCenter
    })),
    candidateDistanceGapMeters: distanceGap
  };
}

function gridlyGeometryAwarePlacementDecision(tapCoordinate, options = {}) {
  const tap = gridlyCoordinateFromRecord(tapCoordinate);
  const candidateSegments = gridlyBuildGeometryAwareRoadCandidates(tap, options);
  const selection = gridlySelectGeometryAwareRoadSegment(candidateSegments);
  const decoratedCandidates = candidateSegments.map((candidate) => ({
    ...candidate,
    selected: candidate.segmentId === selection.selectedSegment?.segmentId,
    selectionReason: candidate.segmentId === selection.selectedSegment?.segmentId
      ? selection.selectedSegmentReason
      : `rejected_by_geometry_distance_rank_${candidate.rank}`,
    bearingDifferenceFromSelected: candidate.segmentId === selection.selectedSegment?.segmentId ? 0 : gridlyBearingDifferenceDegrees(selection.selectedSegment?.bearing, candidate.bearing)
  }));
  return {
    tapCoordinate: tap,
    candidateSegments: decoratedCandidates,
    candidateCount: decoratedCandidates.length,
    ...selection
  };
}

function gridlyNormalizeOsrmDirectionalCandidates(candidates = []) {
  return (Array.isArray(candidates) ? candidates : [])
    .map((candidate, index) => {
      const coordinate = gridlyCoordinateFromRecord(candidate?.candidateCoordinate || candidate?.location || candidate);
      return {
        source: candidate?.source || "osrm_nearest_v1_driving",
        roadName: String(candidate?.roadName || candidate?.name || "unknown").trim() || "unknown",
        candidateCoordinate: coordinate,
        distanceFromTapMeters: Number.isFinite(Number(candidate?.distanceFromTapMeters ?? candidate?.distance)) ? Math.round(Number(candidate?.distanceFromTapMeters ?? candidate?.distance) * 10) / 10 : null,
        bearing: null,
        inferredDirection: null,
        directionConfidence: "low",
        rank: index + 1,
        selected: false,
        selectionReason: "OSRM nearest exposes snapped point/name/distance here, but not local segment geometry or carriageway bearing."
      };
    });
}

function gridlyBearingDifferenceDegrees(a, b) {
  const first = Number(a);
  const second = Number(b);
  if (!Number.isFinite(first) || !Number.isFinite(second)) return null;
  const diff = Math.abs(first - second) % 360;
  return Math.round(Math.min(diff, 360 - diff) * 10) / 10;
}

function gridlyLatestDirectionalTapCoordinate(options = {}) {
  return gridlyCoordinateFromRecord(options.tapCoordinate)
    || gridlyCoordinateFromRecord(lastMobileReportSubmitDebug.rawTapCoordinate || lastMobileReportSubmitDebug.originalTapCoords)
    || gridlyCoordinateFromRecord(lastRoadSnapDebug.rawTapCoordinate || lastRoadSnapDebug.originalTapCoords)
    || gridlyCoordinateFromRecord(lastMobileReportSubmitDebug.finalPlacementCoordinate)
    || gridlyCoordinateFromRecord(lastRoadSnapDebug.finalPlacementCoordinate);
}

function gridlyDirectionalSampleIncidents(limit = 6) {
  const unifiedIncidents = typeof getUnifiedIncidents === "function" ? getUnifiedIncidents() : [];
  return unifiedIncidents
    .filter((incident) => String(incident?.id || "").startsWith("road-"))
    .slice(0, limit)
    .map((incident) => ({
      id: incident.id,
      roadName: incident.roadName || incident.road_name || incident.nearestRoad || "Unknown road",
      coordinate: gridlyCoordinateFromRecord(incident),
      rawTapCoordinate: gridlyCoordinateFromRecord(incident.rawTapCoordinate || incident.reportCaptureCoordinate),
      finalPlacementCoordinate: gridlyCoordinateFromRecord(incident.finalPlacementCoordinate) || gridlyCoordinateFromRecord(incident),
      roadCandidateCount: incident.roadCandidateCount ?? null,
      nearestCandidateDistanceMeters: incident.nearestCandidateDistanceMeters ?? null,
      placementMode: incident.placementMode || "unknown"
    }));
}

function gridlyDirectionalRoadAudit(options = {}) {
  const includeConnectedAudits = gridlyShouldRunConnectedAuditSnapshots(options);
  const lastTapCoordinate = gridlyLatestDirectionalTapCoordinate(options);
  const localCandidates = gridlyBuildLocalDirectionalRoadCandidates(lastTapCoordinate, options);
  const osrmCandidates = gridlyNormalizeOsrmDirectionalCandidates(lastRoadSnapDebug?.nearestRoadCandidates || []);
  const nearestRoadCandidates = localCandidates.length ? localCandidates : osrmCandidates;
  const selectedRoadCandidate = nearestRoadCandidates[0] || null;
  const nearestDistance = Number(selectedRoadCandidate?.distanceFromTapMeters);
  const secondCandidate = nearestRoadCandidates[1] || null;
  const secondDistance = Number(secondCandidate?.distanceFromTapMeters);
  const candidateDistanceGapMeters = Number.isFinite(nearestDistance) && Number.isFinite(secondDistance)
    ? Math.round(Math.abs(secondDistance - nearestDistance) * 10) / 10
    : null;
  const selectedRoadNameKey = String(selectedRoadCandidate?.roadName || "").toLowerCase();
  const sameRoadNameCandidates = selectedRoadNameKey
    ? nearestRoadCandidates.filter((candidate) => String(candidate.roadName || "").toLowerCase() === selectedRoadNameKey)
    : [];
  const bearingDifferences = sameRoadNameCandidates.slice(1).map((candidate) => gridlyBearingDifferenceDegrees(selectedRoadCandidate?.bearing, candidate?.bearing)).filter(Number.isFinite);
  const parallelCandidateRisk = sameRoadNameCandidates.length > 1 && Number.isFinite(secondDistance) && secondDistance <= 35 && (candidateDistanceGapMeters === null || candidateDistanceGapMeters <= 12);
  const dividedRoadRisk = Boolean(lastRoadSnapDebug?.dividedRoadRisk) || parallelCandidateRisk;
  const selectedSideConfidence = !selectedRoadCandidate ? "low"
    : dividedRoadRisk ? "low"
      : Number.isFinite(candidateDistanceGapMeters) && candidateDistanceGapMeters >= 12 ? "high"
        : Number.isFinite(candidateDistanceGapMeters) && candidateDistanceGapMeters >= 5 ? "medium"
          : nearestRoadCandidates.length <= 1 ? "medium" : "low";
  const roadGeometryAvailable = localCandidates.length > 0;
  const roadBearing = Number.isFinite(Number(selectedRoadCandidate?.bearing)) ? Number(selectedRoadCandidate.bearing) : null;
  const inferredDirection = gridlyInferCardinalRoadDirection(roadBearing);
  const directionConfidence = roadGeometryAvailable && inferredDirection
    ? (selectedSideConfidence === "high" ? "high" : selectedSideConfidence === "medium" ? "medium" : "low")
    : "low";
  const roadName = selectedRoadCandidate?.roadName || (typeof resolveNearestRoadName === "function" && lastTapCoordinate ? resolveNearestRoadName(lastTapCoordinate.lat, lastTapCoordinate.lng) : "Unknown road") || "Unknown road";
  const directionLabel = inferredDirection ? `${roadName} ${inferredDirection}` : roadName;
  const safeDirectionalLabelAnswer = !roadGeometryAvailable ? "insufficient_geometry"
    : directionConfidence === "high" ? "yes_high_confidence"
      : directionConfidence === "medium" ? "yes_medium_confidence" : "no_low_confidence";
  const missingData = [];
  if (!lastTapCoordinate) missingData.push("last tap/report coordinate");
  if (!osrmCandidates.length) missingData.push("latest OSRM nearest candidate list (run tap-map report flow first)");
  if (!roadGeometryAvailable) missingData.push("nearby local roadway LineString/MultiLineString geometry within audit radius");
  if (!Number.isFinite(roadBearing)) missingData.push("candidate segment bearing");
  if (!selectedRoadCandidate?.oneWay) missingData.push("explicit one-way/carriageway direction metadata for high-confidence EB/WB/NB/SB labeling");
  if (parallelCandidateRisk) missingData.push("lane/carriageway-side disambiguation because multiple same-name candidates are similarly close");
  const recommendations = [
    "Use local roadway segment geometry for bearing diagnostics; OSRM nearest candidates alone expose point distance but not enough segment geometry for reliable directional labels.",
    "Treat EB/WB/NB/SB labels as audit-only until the selected candidate has both a stable bearing and enough separation from same-name parallel candidates.",
    "For divided roads such as US 90 and TX 146, compare nearest vs second-nearest same-name candidates and do not promote a directional label when the distance gap is small.",
    "Persist no new payload fields from this audit; keep Supabase, routing, Route Watch, rail markers, and rail reporting untouched."
  ];
  const decoratedCandidates = nearestRoadCandidates.map((candidate, index) => ({
    ...candidate,
    rank: index + 1,
    selected: index === 0,
    reasonSelectedRejected: index === 0
      ? (roadGeometryAvailable ? "nearest local geometry candidate selected for directional audit" : "nearest OSRM point candidate selected, but bearing is unavailable")
      : `rejected_by_rank_distance_${candidate.distanceFromTapMeters ?? "unknown"}m`,
    bearingDifferenceFromSelected: index === 0 ? 0 : gridlyBearingDifferenceDegrees(selectedRoadCandidate?.bearing, candidate?.bearing)
  }));
  const placementAuditSnapshot = includeConnectedAudits && typeof gridlyHazardPlacementAccuracyAudit === "function" ? gridlyHazardPlacementAccuracyAudit() : null;
  const roadClusterAuditSnapshot = includeConnectedAudits && typeof gridlyBuildRoadClusterAudit === "function" ? gridlyBuildRoadClusterAudit({ sampleLimit: 4 }) : null;
  const audit = {
    auditVersion: "V206.10.4-directional-road-placement-bearing-audit",
    auditOnly: true,
    destructiveActionsTaken: false,
    lastTapCoordinate,
    nearestRoadCandidates: decoratedCandidates,
    selectedRoadCandidate: decoratedCandidates[0] || null,
    roadName,
    roadBearing,
    inferredDirection,
    directionLabel,
    directionConfidence,
    safeDirectionalLabelAnswer,
    canSafelyLabelExamplesRightNow: safeDirectionalLabelAnswer,
    dividedRoadRisk,
    parallelCandidateRisk,
    candidateCount: decoratedCandidates.length,
    nearestCandidateDistanceMeters: Number.isFinite(nearestDistance) ? Math.round(nearestDistance * 10) / 10 : null,
    secondNearestCandidateDistanceMeters: Number.isFinite(secondDistance) ? Math.round(secondDistance * 10) / 10 : null,
    candidateDistanceGapMeters,
    sameRoadNameCandidateCount: sameRoadNameCandidates.length,
    bearingDifferences,
    selectedSideConfidence,
    roadGeometryAvailable,
    dataSourceAssessment: {
      localRoadwaySegments: roadGeometryAvailable ? "has nearby segment geometry and can provide audit bearing" : "unavailable_or_no_nearby_geometry",
      osrmNearestCandidates: osrmCandidates.length ? "has nearby point candidates, names, and distances; no bearing/shape in current snap response" : "not_available_in_latest_debug_state",
      leafletTapCoordinate: lastTapCoordinate ? "available" : "missing",
      routeGeometry: typeof savedRouteLayer?.getLatLngs === "function" && (savedRouteLayer.getLatLngs() || []).length ? "available_for_route_context_not_carriageway_selection" : "not_available_or_not_used",
      mapLayerGeometry: "not used for permanent UI; audit relies on loaded roadway dataset geometry when available"
    },
    missingData,
    recommendations,
    sampleIncidents: gridlyDirectionalSampleIncidents(),
    connectedAudits: {
      hazardPlacementAccuracyAuditAvailable: typeof gridlyHazardPlacementAccuracyAudit === "function",
      roadClusterAuditAvailable: typeof gridlyRoadClusterAudit === "function",
      nestedSnapshotsSkippedByDefault: !includeConnectedAudits,
      placementCoordinate: placementAuditSnapshot?.finalPlacementCoordinate || placementAuditSnapshot?.renderedMarkerCoordinate || null,
      placementMode: placementAuditSnapshot?.placementMode || null,
      clusteringApplied: placementAuditSnapshot?.clusteringApplied ?? null,
      clusterSampleCount: Array.isArray(roadClusterAuditSnapshot?.sampleClusters) ? roadClusterAuditSnapshot.sampleClusters.length : null
    },
    trace: [
      "Tap coordinate: last tap/report debug coordinate from lastMobileReportSubmitDebug or lastRoadSnapDebug.",
      "Nearest road candidates: local roadway geometry candidates are preferred for bearing; latest OSRM nearest debug candidates are used as a no-bearing fallback.",
      "Road name: selected candidate name, falling back to resolveNearestRoadName when needed.",
      "Candidate geometry: local LineString/MultiLineString projected segment when available; OSRM fallback has point only.",
      "Bearing: computed from selected local segment start/end when available.",
      "Inferred direction: NB/EB/SB/WB ranges are applied only when bearing is numeric.",
      "Selected candidate: nearest candidate by tap distance for this diagnostic-only audit.",
      "Marker coordinate and alert label: linked through gridlyHazardPlacementAccuracyAudit without changing reporting output."
    ],
    lastRoadSnapDebug: { ...lastRoadSnapDebug },
    lastMobileReportSubmitDebug: { ...lastMobileReportSubmitDebug }
  };
  console.info("gridlyDirectionalRoadAudit", audit);
  return audit;
}

if (typeof window !== "undefined") {
  window.gridlyDirectionalRoadAudit = gridlyDirectionalRoadAudit;
}
exposeGridlyAuditHelper("gridlyDirectionalRoadAudit", gridlyDirectionalRoadAudit);


function gridlyGeometryAwarePlacementSampleIncidents(limit = 8) {
  const unifiedIncidents = typeof getUnifiedIncidents === "function" ? getUnifiedIncidents() : [];
  return unifiedIncidents
    .filter((incident) => String(incident?.id || "").startsWith("road-"))
    .slice(0, limit)
    .map((incident) => ({
      id: incident.id,
      type: incident.report_type || incident.type,
      rawTapCoordinate: gridlyCoordinateFromRecord(incident.rawTapCoordinate || incident.reportCaptureCoordinate),
      finalPlacementCoordinate: gridlyCoordinateFromRecord(incident.finalPlacementCoordinate) || gridlyCoordinateFromRecord(incident),
      selectedRoadwaySegment: incident.selectedRoadwaySegment || null,
      selectedRoadName: incident.selectedRoadName || incident.roadName || incident.nearestRoad || "Unknown road",
      selectedSegmentDistanceMeters: incident.selectedSegmentDistanceMeters ?? null,
      selectedSideConfidence: incident.selectedSideConfidence || "unknown",
      placementMode: incident.placementMode || "unknown"
    }));
}

function gridlyGeometryAwarePlacementAudit(options = {}) {
  const includeConnectedAudits = gridlyShouldRunConnectedAuditSnapshots(options);
  const tapCoordinate = gridlyLatestDirectionalTapCoordinate(options);
  const geometryDecision = gridlyGeometryAwarePlacementDecision(tapCoordinate, { maxDistanceMeters: options.maxDistanceMeters || 75, limit: options.limit || 16 });
  const selectedSegment = geometryDecision.selectedSegment || lastRoadSnapDebug?.selectedRoadwaySegment || lastRoadSnapDebug?.geometryAwarePlacement?.selectedSegment || null;
  const selectedRoadName = selectedSegment?.roadName || lastRoadSnapDebug?.selectedRoadName || null;
  const placementAuditSnapshot = includeConnectedAudits && typeof gridlyHazardPlacementAccuracyAudit === "function" ? gridlyHazardPlacementAccuracyAudit() : null;
  const roadClusterAuditSnapshot = includeConnectedAudits && typeof gridlyBuildRoadClusterAudit === "function" ? gridlyBuildRoadClusterAudit({ sampleLimit: 4 }) : null;
  const directionalAuditSnapshot = includeConnectedAudits && typeof gridlyDirectionalRoadAudit === "function" ? gridlyDirectionalRoadAudit({ maxDistanceMeters: options.maxDistanceMeters || 75, includeConnectedAudits: false }) : null;
  const geometryCapabilitySnapshot = includeConnectedAudits && typeof gridlyRoadwayGeometryCapabilityAudit === "function" ? gridlyRoadwayGeometryCapabilityAudit() : null;
  const candidateCount = geometryDecision.candidateCount || 0;
  const selectedSegmentDistanceMeters = selectedSegment?.distanceFromTapMeters ?? lastRoadSnapDebug?.selectedSegmentDistanceMeters ?? null;
  const selectedSegmentBearing = selectedSegment?.bearing ?? lastRoadSnapDebug?.selectedSegmentBearing ?? null;
  const geometryAwarePlacementAvailable = Boolean(candidateCount && selectedSegment);
  const dividedRoadRisk = Boolean(geometryDecision.dividedRoadRisk || lastRoadSnapDebug?.dividedRoadRisk);
  const selectedSideConfidence = geometryDecision.selectedSideConfidence || lastRoadSnapDebug?.selectedSideConfidence || "low";
  const recommendedDirection = geometryDecision.recommendedDirection || lastRoadSnapDebug?.recommendedDirection || null;
  const directionConfidence = geometryDecision.directionConfidence || lastRoadSnapDebug?.directionConfidence || "low";
  const canSupportFutureDirectionalLabels = Boolean(geometryDecision.canSupportFutureDirectionalLabels || lastRoadSnapDebug?.canSupportFutureDirectionalLabels);
  const recommendations = [
    "Use the selected local roadway segment as the internal road-hazard attachment point before considering any future EB/WB/NB/SB display labels.",
    "Keep directional labels audit-only; require stable segment selection, sufficient same-road carriageway separation, and explicit metadata review before exposing labels to users.",
    "For US 90 and TX 146 validation, run two real taps on opposite carriageways and compare selectedSegment.segmentId plus selectedSegmentDistanceMeters in this audit.",
    "Do not alter rail reporting, crossing workflows, TxDOT startup fetch, Supabase schema, Route Watch, Alerts, or Historical Intelligence from this prototype."
  ];
  const audit = {
    auditVersion: "V206.13-geometry-aware-road-hazard-placement-prototype",
    auditOnly: true,
    destructiveActionsTaken: false,
    tapCoordinate,
    candidateCount,
    candidateSegments: geometryDecision.candidateSegments || [],
    selectedSegment,
    selectedRoadName,
    selectedSegmentDistanceMeters,
    selectedSegmentBearing,
    selectedSegmentReason: geometryDecision.selectedSegmentReason || lastRoadSnapDebug?.selectedSegmentReason || "no_geometry_aware_selection_available",
    sameRoadCandidateCount: geometryDecision.sameRoadCandidateCount || 0,
    oppositeSideCandidateCount: geometryDecision.oppositeSideCandidateCount || 0,
    dividedRoadRisk,
    selectedSideConfidence,
    geometryAwarePlacementAvailable,
    canSupportFutureDirectionalLabels,
    recommendedDirection,
    directionConfidence,
    sameRoadParallelCandidates: geometryDecision.sameRoadParallelCandidates || [],
    candidateDistanceGapMeters: geometryDecision.candidateDistanceGapMeters ?? null,
    sampleIncidents: gridlyGeometryAwarePlacementSampleIncidents(),
    recommendations,
    connectedAudits: {
      hazardPlacementAccuracyAuditAvailable: typeof gridlyHazardPlacementAccuracyAudit === "function",
      roadClusterAuditAvailable: typeof gridlyRoadClusterAudit === "function",
      directionalRoadAuditAvailable: typeof gridlyDirectionalRoadAudit === "function",
      roadwayGeometryCapabilityAuditAvailable: typeof gridlyRoadwayGeometryCapabilityAudit === "function",
      nestedSnapshotsSkippedByDefault: !includeConnectedAudits,
      placementMode: placementAuditSnapshot?.placementMode || null,
      finalPlacementCoordinate: placementAuditSnapshot?.finalPlacementCoordinate || null,
      renderedMarkerCoordinate: placementAuditSnapshot?.renderedMarkerCoordinate || null,
      clusterSampleCount: Array.isArray(roadClusterAuditSnapshot?.sampleClusters) ? roadClusterAuditSnapshot.sampleClusters.length : null,
      directionalSelectedRoadCandidate: directionalAuditSnapshot?.selectedRoadCandidate || null,
      directionalReadiness: geometryCapabilitySnapshot?.directionalReadiness || null,
      localRoadwayFeatureCount: geometryCapabilitySnapshot?.roadSegmentFeatureCount ?? null
    },
    validationGuide: {
      us90: "Zoom to US 90, tap one carriageway, record selectedSegment.segmentId, then tap the opposite carriageway and confirm the segmentId changes while selectedSegmentDistanceMeters stays small.",
      tx146: "Repeat the same opposite-carriageway check on TX 146 before promoting any future NB/SB diagnostic label confidence.",
      success: "Selected segments differ, selected distances remain small, and the rendered/final marker coordinate remains visually consistent with the user's tap."
    },
    trace: [
      "Tap Coordinate -> local LineString/MultiLineString segment candidates from the loaded roadway dataset.",
      "Each candidate records segment id, road name, projected tap distance, start/end, center, bearing, and geometry length.",
      "Selection is nearest-first, with same-road continuity, divided-road separation, and bearing consistency diagnostics layered on top.",
      "Selected segment is internal diagnostic state only; no EB/WB/NB/SB label is exposed to users."
    ],
    lastRoadSnapDebug: { ...lastRoadSnapDebug },
    lastMobileReportSubmitDebug: { ...lastMobileReportSubmitDebug }
  };
  console.info("gridlyGeometryAwarePlacementAudit", audit);
  return audit;
}

if (typeof window !== "undefined") {
  window.gridlyGeometryAwarePlacementAudit = gridlyGeometryAwarePlacementAudit;
}
exposeGridlyAuditHelper("gridlyGeometryAwarePlacementAudit", gridlyGeometryAwarePlacementAudit);

function gridlyPlacementPipelineTraceAudit(options = {}) {
  const tapCoordinate = gridlyCoordinateFromRecord(options.tapCoordinate) || gridlyLatestDirectionalTapCoordinate(options);
  const geometryDecision = tapCoordinate
    ? gridlyGeometryAwarePlacementDecision(tapCoordinate, { maxDistanceMeters: options.maxDistanceMeters || 75, limit: options.limit || 16 })
    : null;
  const latestRoadIncident = gridlyLatestRoadIncidentForPlacementTrace();
  const selectedSegment = geometryDecision?.selectedSegment
    || lastRoadSnapDebug?.geometryAwarePlacement?.selectedSegment
    || lastRoadSnapDebug?.selectedRoadwaySegment
    || latestRoadIncident?.geometryAwarePlacement?.selectedSegment
    || latestRoadIncident?.selectedRoadwaySegment
    || null;
  const projectionCoordinate = gridlyCoordinateFromRecord(selectedSegment?.candidateCoordinate)
    || gridlyCoordinateFromRecord(lastRoadSnapDebug?.geometryAwarePlacement?.selectedSegment?.candidateCoordinate)
    || gridlyCoordinateFromRecord(latestRoadIncident?.geometryAwarePlacement?.selectedSegment?.candidateCoordinate);
  const snappedCoordinate = gridlyCoordinateFromRecord(lastMobileReportSubmitDebug.snappedRoadCoordinate)
    || gridlyCoordinateFromRecord(latestRoadIncident?.snappedRoadCoordinate)
    || gridlyCoordinateFromRecord(lastRoadSnapDebug.snappedRoadCoordinate);
  const osrmNearestCoordinate = gridlyCoordinateFromRecord(lastRoadSnapDebug.snappedRoadCoordinate);
  const finalPlacementCoordinate = gridlyCoordinateFromRecord(options.finalPlacementCoordinate)
    || gridlyCoordinateFromRecord(lastMobileReportSubmitDebug.finalPlacementCoordinate)
    || gridlyCoordinateFromRecord(lastRoadSnapDebug.finalPlacementCoordinate)
    || gridlyCoordinateFromRecord(latestRoadIncident?.finalPlacementCoordinate)
    || gridlyCoordinateFromRecord(latestRoadIncident);
  const hazardCoordinate = gridlyCoordinateFromRecord(lastMobileReportSubmitDebug.activeSubmitCoords)
    || gridlyCoordinateFromRecord(lastMobileReportSubmitDebug.insertPayloadPreview)
    || gridlyCoordinateFromRecord(latestRoadIncident?.storedReportCoordinate)
    || gridlyCoordinateFromRecord(latestRoadIncident);
  const renderedAudit = latestRoadIncident?.id ? gridlyFindRenderedMarkerPlacementAudit(latestRoadIncident.id) : gridlyFindRenderedMarkerPlacementAudit();
  const markerCoordinate = gridlyCoordinateFromRecord(renderedAudit?.renderedMarkerCoordinate)
    || gridlyCoordinateFromRecord(lastMobileReportSubmitDebug.renderedMarkerCoordinate)
    || gridlyCoordinateFromRecord(latestRoadIncident?.renderedMarkerCoordinate)
    || gridlyCoordinateFromRecord(latestRoadIncident);
  const placementMode = lastMobileReportSubmitDebug.placementMode || latestRoadIncident?.placementMode || lastRoadSnapDebug?.placementMode || null;
  const placementSource = gridlyClassifyPlacementSource({
    tapCoordinate,
    projectionCoordinate,
    snappedCoordinate,
    finalPlacementCoordinate,
    placementMode
  });
  const projectionComputed = Boolean(projectionCoordinate);
  const projectionStored = Boolean(
    projectionCoordinate
    && (selectedSegment?.candidateCoordinate
      || lastRoadSnapDebug?.geometryAwarePlacement?.selectedSegment?.candidateCoordinate
      || latestRoadIncident?.geometryAwarePlacement?.selectedSegment?.candidateCoordinate
      || lastMobileReportSubmitDebug?.snappedRoadCoordinate
      || latestRoadIncident?.snappedRoadCoordinate)
  );
  const projectionUsed = Boolean(projectionCoordinate && gridlyCoordinatesWithinMeters(finalPlacementCoordinate, projectionCoordinate));
  const projectionDiscarded = Boolean(projectionComputed && !projectionUsed);
  const hazardCoordinateSource = gridlyCoordinatesWithinMeters(hazardCoordinate, projectionCoordinate) ? "projected_point"
    : gridlyCoordinatesWithinMeters(hazardCoordinate, osrmNearestCoordinate) ? "snapped_point"
      : gridlyCoordinatesWithinMeters(hazardCoordinate, tapCoordinate) ? "raw_tap"
        : hazardCoordinate ? "unknown" : "none";
  const markerCoordinateSource = gridlyCoordinatesWithinMeters(markerCoordinate, projectionCoordinate) ? "projected_point"
    : gridlyCoordinatesWithinMeters(markerCoordinate, osrmNearestCoordinate) ? "snapped_point"
      : gridlyCoordinatesWithinMeters(markerCoordinate, tapCoordinate) ? "raw_tap"
        : markerCoordinate ? "unknown" : "none";
  const audit = {
    auditVersion: "V206.14-geometry-projection-placement-trace",
    auditOnly: true,
    destructiveActionsTaken: false,
    tapCoordinate,
    projectionCoordinate,
    finalPlacementCoordinate,
    placementSource,
    projectionComputed,
    projectionStored,
    projectionUsed,
    projectionUseDecision: placementMode === "projected_point_used" ? "projection_used_by_gridlyBuildRoadAwareHazardPlacement" : projectionDiscarded ? "projection_not_used_by_gridlyBuildRoadAwareHazardPlacement" : "projection_status_unknown",
    projectionDiscarded,
    markerCoordinateSource,
    hazardCoordinateSource,
    markerCoordinate,
    hazardCoordinate,
    snappedCoordinate,
    osrmNearestCoordinate,
    placementMode,
    tapToProjectionDeltaMeters: gridlyCoordinateDeltaMeters(tapCoordinate, projectionCoordinate),
    tapToFinalDeltaMeters: gridlyCoordinateDeltaMeters(tapCoordinate, finalPlacementCoordinate),
    projectionToFinalDeltaMeters: gridlyCoordinateDeltaMeters(projectionCoordinate, finalPlacementCoordinate),
    selectedRoadName: selectedSegment?.roadName || latestRoadIncident?.selectedRoadName || null,
    selectedSegmentDistanceMeters: selectedSegment?.distanceFromTapMeters ?? latestRoadIncident?.selectedSegmentDistanceMeters ?? null,
    selectedSegmentBearing: selectedSegment?.bearing ?? latestRoadIncident?.selectedSegmentBearing ?? null,
    selectedSideConfidence: geometryDecision?.selectedSideConfidence || lastRoadSnapDebug?.selectedSideConfidence || latestRoadIncident?.selectedSideConfidence || "low",
    recommendedDirection: geometryDecision?.recommendedDirection || lastRoadSnapDebug?.recommendedDirection || latestRoadIncident?.recommendedDirection || null,
    pipelineStages: [
      {
        stage: "user_tap",
        coordinate: tapCoordinate,
        storedAt: ["lastMobileReportSubmitDebug.rawTapCoordinate", "lastRoadSnapDebug.rawTapCoordinate", "rawTapCoordinate/reportCaptureCoordinate on local hazard when available"],
        note: "Original click/GPS coordinate captured before road validation."
      },
      {
        stage: "nearest_road_selection",
        coordinate: osrmNearestCoordinate,
        storedAt: ["lastRoadSnapDebug.snappedRoadCoordinate", "OSRM diagnostic candidates"],
        note: "OSRM nearest validates that a road exists and provides a snapped waypoint, but local geometry may replace this as the candidate supplied to placement selection."
      },
      {
        stage: "segment_selection",
        coordinate: projectionCoordinate,
        storedAt: ["geometryAwarePlacement.selectedSegment.candidateCoordinate", "selectedRoadwaySegment.candidateCoordinate"],
        note: "Local LineString/MultiLineString geometry candidates are ranked and the selected segment retains the projection coordinate."
      },
      {
        stage: "projection_calculation",
        coordinate: projectionCoordinate,
        storedAt: ["candidateSegments[].candidateCoordinate", "selectedSegment.candidateCoordinate"],
        note: "projectPointToRoadSegment calculates the closest point on each segment; gridlyBuildGeometryAwareRoadCandidates copies it into candidateCoordinate."
      },
      {
        stage: "road_aware_final_choice",
        coordinate: finalPlacementCoordinate,
        source: placementSource,
        storedAt: ["placementDecision.finalPlacementCoordinate", "lastMobileReportSubmitDebug.finalPlacementCoordinate"],
        note: "gridlyBuildRoadAwareHazardPlacement decides whether to preserve the raw tap or use the candidate supplied as snappedCoordinate. This audit only observes that decision."
      },
      {
        stage: "hazard_object_creation",
        coordinate: hazardCoordinate,
        source: hazardCoordinateSource,
        storedAt: ["reports row lat/lng", "localHazardEntry.finalPlacementCoordinate"],
        note: "createSharedHazardReport receives the chosen final coordinate as lat/lng and stores those values on the hazard row/local hazard object."
      },
      {
        stage: "marker_placement",
        coordinate: markerCoordinate,
        source: markerCoordinateSource,
        storedAt: ["unified incident lat/lng", "Leaflet marker [lat,lng]", "layer.options.gridlyPlacementAudit.renderedMarkerCoordinate"],
        note: "renderUnifiedIncidents renders Leaflet markers from unified incident lat/lng, which are derived from stored hazard lat/lng."
      }
    ],
    ownershipFinding: projectionUsed
      ? "The geometry-derived projection point currently survives into final hazard/marker placement for the inspected event."
      : projectionComputed
        ? "The geometry projection is computed and stored for diagnostics, but final hazard/marker placement for the inspected event resolves to a different coordinate; the loss occurs at gridlyBuildRoadAwareHazardPlacement when it chooses raw tap for the current placement conditions."
        : "No projection coordinate was available for the inspected event; load roadway geometry and run a tap-map hazard flow before using this trace.",
    latestRoadIncidentId: latestRoadIncident?.id || null,
    renderedPlacementAudit: renderedAudit || null,
    lastRoadSnapDebug: { ...lastRoadSnapDebug },
    lastMobileReportSubmitDebug: { ...lastMobileReportSubmitDebug }
  };
  console.info("gridlyPlacementPipelineTraceAudit", audit);
  return audit;
}

