function syncHazardPickerUiState() {
  const picker = document.getElementById("gridlyHazardPanel");
  if (!picker) return;
  const selectedType = reportingState.selectedHazardType || selectedQuickHazardType || pendingHazardPlacement || null;
  const requiresOtherSubtype = selectedType === "other_hazard";
  const selectedSubtype = normalizeOtherHazardSubtype(selectedOtherHazardSubtype);
  const subtypePanel = picker.querySelector("[data-other-hazard-subtype-panel]");
  if (subtypePanel) subtypePanel.hidden = !requiresOtherSubtype;
  picker.querySelectorAll("[data-other-hazard-subtype]").forEach((btn) => {
    const isSelected = selectedSubtype && btn.dataset.otherHazardSubtype === selectedSubtype;
    btn.classList.toggle("selected", Boolean(isSelected));
    btn.setAttribute("aria-pressed", String(Boolean(isSelected)));
  });
  const disablePlacementActions = Boolean(reportingState.submissionInProgress || reportingState.locationLookupInProgress);
  picker.querySelectorAll('[data-action="submit-hazard"], [data-action="start-map-placement"]').forEach((btn) => {
    btn.disabled = disablePlacementActions || (requiresOtherSubtype && !selectedSubtype);
    btn.setAttribute("aria-busy", reportingState.locationLookupInProgress ? "true" : "false");
  });
  const cancelBtn = picker.querySelector('[data-action="cancel-hazard-placement"]');
  if (cancelBtn) cancelBtn.disabled = Boolean(reportingState.submissionInProgress);
}

const tapMapTraceLog = [];
let lastHazardPlacementEvent = null;
let lastRoadHazardPlacementSource = null;
let lastRoadHazardPlacementStep = null;
let lastRoadHazardPlacementError = null;
function pushTapMapTrace(event, detail = {}) {
  const entry = { at: new Date().toISOString(), event, detail };
  tapMapTraceLog.push(entry);
  if (tapMapTraceLog.length > 80) tapMapTraceLog.shift();
  lastHazardPlacementEvent = entry;
  lastRoadHazardPlacementStep = event;
  if (event.includes("failed") || event.includes("error") || event.includes("cancel")) {
    lastRoadHazardPlacementError = detail?.reason || detail?.message || event;
  }
}

function getRoadHazardBlockingOverlays() {
  return Array.from(document.querySelectorAll("body *")).filter((node) => {
    if (!(node instanceof HTMLElement)) return false;
    const style = getComputedStyle(node);
    if (style.display === "none" || style.visibility === "hidden" || style.pointerEvents === "none") return false;
    const rect = node.getBoundingClientRect();
    if (rect.width < window.innerWidth * 0.6 || rect.height < window.innerHeight * 0.35) return false;
    return true;
  }).slice(0, 20).map((node) => {
    const style = getComputedStyle(node);
    return { tag: node.tagName, id: node.id || "", className: node.className || "", pointerEvents: style.pointerEvents, zIndex: style.zIndex };
  });
}

function syncMapPlacementCursorState() {
  const mapEl = map?.getContainer?.() || document.getElementById("map");
  if (!mapEl) return;
  mapEl.style.cursor = reportingState.placementModeActive ? "crosshair" : "";
}

function openHazardPanel(entryPoint = reportingState.activeReportEntryPoint || "report_near_me") {
  gridlyRecordHazardPropagationStage("report_flow_opened", { entryPoint });
  reportLifecycleDiag("openHazardPanel", { entryPoint });
  injectHazardReportUI();
  updateReportingState({ reportModeActive: true, activeReportEntryPoint: entryPoint });
  const picker = document.getElementById("gridlyHazardPanel");
  picker?.classList.add("visible");
  document.getElementById("gridlyMobileRouteQuickPanel")?.classList.remove("visible");
  syncHazardPickerUiState();
  const computed = picker ? window.getComputedStyle(picker) : null;
  reportDebugLog("[Gridly][Report] picker open path called", {
    entryPoint,
    pickerSelector: "#gridlyHazardPanel",
    pickerExists: Boolean(picker),
    className: picker?.className || null,
    display: computed?.display || null,
    visibility: computed?.visibility || null,
    opacity: computed?.opacity || null,
    zIndex: computed?.zIndex || null,
    rect: picker ? picker.getBoundingClientRect() : null
  });
}

window.closeHazardPanel = function (options = {}) {
  const { preserveLastReportMessage = true } = options;
  if (reportingState.placementModeActive && !options.forceCloseDuringPlacement) {
    return;
  }
  setTacticalReportHelperVisibility(false);
  const updates = {
    reportModeActive: false,
    placementModeActive: false,
    selectedHazardType: null
  };
  if (!preserveLastReportMessage) updates.lastReportMessage = "";
  updateReportingState(updates);
  document.getElementById("gridlyHazardPanel")?.classList.remove("visible");
  returnMobileToLiveMode("close_hazard_panel");
};

