function gridlyPickRowKeys(row, allowedKeys = []) {
  const safeRow = row && typeof row === "object" ? row : {};
  return allowedKeys.reduce((clean, key) => {
    if (Object.prototype.hasOwnProperty.call(safeRow, key)) clean[key] = safeRow[key];
    return clean;
  }, {});
}

function gridlyGetUnsupportedReportInsertKeys(row) {
  if (!row || typeof row !== "object") return [];
  const allowed = new Set(GRIDLY_REPORTS_ALLOWED_INSERT_KEYS);
  return Object.keys(row).filter((key) => !allowed.has(key));
}

function isGridlySupabaseMissingColumnSchemaError(error) {
  const message = String(error?.message || error?.details || error?.hint || "").toLowerCase();
  const code = String(error?.code || "").toLowerCase();
  return code === "pgrst204"
    || (message.includes("column") && (message.includes("schema cache") || message.includes("could not find") || message.includes("does not exist")));
}

function gridlyBuildRoadHazardSubmitShapeAudit(row, legacyRow, error = null, fallbackUsed = false) {
  const detail = row?.detail;
  const unsupportedTopLevelKeys = gridlyGetUnsupportedReportInsertKeys(row);
  const legacyKeys = Object.keys(legacyRow || gridlyPickRowKeys(row, GRIDLY_REPORTS_BASE_INSERT_KEYS));
  const legacyShapePass = legacyKeys.length > 0 && legacyKeys.every((key) => GRIDLY_REPORTS_BASE_INSERT_KEYS.includes(key));
  return {
    supabaseInsertKeys: Object.keys(row || {}),
    legacyRetryInsertKeys: legacyKeys,
    unsupportedTopLevelKeys,
    detailType: typeof detail,
    detailPreview: String(detail || "").slice(0, 240),
    submitWouldUseLegacyRetry: Boolean(fallbackUsed || unsupportedTopLevelKeys.length || (error && isGridlySupabaseMissingColumnSchemaError(error))),
    fallbackRetryAttempted: Boolean(fallbackUsed),
    fallbackRetrySucceeded: Boolean(fallbackUsed && !error),
    lastSubmitError: error ? String(error?.message || error?.details || error || "") : "",
    submitShapePass: Boolean(
      row
      && typeof detail === "string"
      && (fallbackUsed ? legacyShapePass : !unsupportedTopLevelKeys.length)
      && Object.keys(row).every((key) => GRIDLY_REPORTS_ALLOWED_INSERT_KEYS.includes(key))
    )
  };
}

function gridlyPickRoadHazardLocationIdentityFields(source = {}) {
  const keys = [
    "roadName",
    "primaryRoad",
    "locationName",
    "knownLocation",
    "locationLabel",
    "authoritativeLocationLabel",
    "strongestLocationLabel",
    "displayLocation"
  ];
  return keys.reduce((fields, key) => {
    if (Object.prototype.hasOwnProperty.call(source, key) && source[key] !== undefined && source[key] !== null && source[key] !== "") {
      fields[key] = source[key];
    }
    return fields;
  }, {});
}


function buildGridlyCanonicalRoadHazardDisplayLocation(record = {}, options = {}) {
  const coords = gridlyCoordinateFromRecord(options.submittedCoordinate || record?.submittedCoordinate || record);
  const clean = (value) => safeDisplayText(value, "").replace(/^Near\s+/i, "").trim();
  const road = clean(
    record?.authoritativeLocationLabel
    || record?.displayLocation
    || record?.strongestLocationLabel
    || record?.roadName
    || record?.primaryRoad
    || record?.selectedRoadName
    || record?.road_name
    || record?.nearest_road
  );
  const prebuilt = clean(record?.canonicalDisplayLocation || record?.canonicalLocationPhrase || record?.nearbyLocationPhrase);
  if (prebuilt && (!road || prebuilt.toLowerCase().includes(road.toLowerCase()))) return prebuilt;
  const community = coords && typeof resolveGridlyV313RoadHazardCommunityDistance === "function"
    ? resolveGridlyV313RoadHazardCommunityDistance(coords)
    : { text: "" };
  const relative = clean(record?.relativeLocationText || record?.relativeDistanceText || community.text);
  if (road && relative) return `${road} ${relative}`;
  if (road) return road;
  if (relative) return relative;
  return clean(record?.locationLabel || record?.knownLocation || record?.locationName || record?.area || record?.city);
}

function applyGridlyCanonicalRoadHazardDisplayLocation(record = {}, options = {}) {
  if (!record || typeof record !== "object") return record;
  const canonicalDisplayLocation = buildGridlyCanonicalRoadHazardDisplayLocation(record, options);
  if (!canonicalDisplayLocation) return record;
  record.canonicalDisplayLocation = canonicalDisplayLocation;
  record.canonicalLocationPhrase = canonicalDisplayLocation;
  record.displayLocation = canonicalDisplayLocation;
  record.locationLabel = canonicalDisplayLocation;
  record.knownLocation = canonicalDisplayLocation;
  record.locationName = canonicalDisplayLocation;
  record.resolvedLocationLabel = canonicalDisplayLocation;
  record.nearbyLocationPhrase = canonicalDisplayLocation;
  record.authoritativeLocationLabel = canonicalDisplayLocation;
  record.strongestLocationLabel = canonicalDisplayLocation;
  return record;
}

function scheduleGridlyPostSubmitLocalSurfaceRefresh(source = "post_submit_local") {
  const runner = () => {
    gridlyReportSubmissionRecoveryState.renderWorkTriggered.push({ source, work: "refreshReportHazardViews", at: Date.now() });
    refreshReportHazardViews(source);
    if (typeof renderUnifiedIncidents === "function") renderUnifiedIncidents(`${source}:unified`);
    scheduleHazardMarkerAutoRender(`${source}:markers`);
  };
  if (typeof requestAnimationFrame === "function") {
    requestAnimationFrame(() => setTimeout(runner, 0));
  } else {
    setTimeout(runner, 0);
  }
}

function gridlyBuildRoadHazardSubmissionLocationPayload(options = {}) {
  const cleanRoad = (value) => {
    const text = safeDisplayText(value, "");
    return text && !/^(unknown|unknown road)$/i.test(text) ? text : "";
  };
  const submittedCoordinate = gridlyCoordinateFromRecord(options.submittedCoordinate);
  const cachedCoordinate = gridlyCoordinateFromRecord(options.cachedCoordinate);
  const cachedDistanceMeters = submittedCoordinate && cachedCoordinate ? gridlyCoordinateDeltaMeters(submittedCoordinate, cachedCoordinate) : null;
  const explicitRoad = cleanRoad(options.roadName) || cleanRoad(options.primaryRoad) || cleanRoad(options.selectedRoadName);
  const cachedRoad = cleanRoad(options.cachedRoadName || options.cachedPrimaryRoad || options.cachedSelectedRoadName);
  const cachedCoordinateMatchesSubmitted = Number.isFinite(cachedDistanceMeters) && cachedDistanceMeters <= 0.5;
  const cachedRoadAccepted = Boolean(!explicitRoad && cachedRoad && cachedCoordinateMatchesSubmitted);
  const resolvedRoad = cleanRoad(options.resolvedRoadName || options.resolverRoadName);
  const selectedPrimaryRoad = explicitRoad || (cachedRoadAccepted ? cachedRoad : "") || resolvedRoad;
  const fallbackText = cleanRoad(options.nearbyPairFallbackText || options.crossingFallbackText || options.locationName || options.knownLocation || options.locationLabel);
  const nearbyPairFallbackSuppressed = Boolean(selectedPrimaryRoad && fallbackText && fallbackText !== selectedPrimaryRoad && /\b(?:at|&)\b/i.test(fallbackText));
  const staleCachedRoadStateRejected = Boolean(!explicitRoad && cachedRoad && !cachedRoadAccepted);
  const payload = selectedPrimaryRoad ? {
    roadName: selectedPrimaryRoad,
    primaryRoad: selectedPrimaryRoad,
    locationName: selectedPrimaryRoad,
    knownLocation: selectedPrimaryRoad,
    locationLabel: selectedPrimaryRoad,
    authoritativeLocationLabel: selectedPrimaryRoad,
    strongestLocationLabel: selectedPrimaryRoad
  } : {};
  return {
    payload,
    audit: {
      payloadPass: Boolean(selectedPrimaryRoad && payload.roadName === selectedPrimaryRoad && payload.authoritativeLocationLabel === selectedPrimaryRoad),
      us90WacoFallbackUsed: /us\s*90\s+at\s+waco/i.test(selectedPrimaryRoad),
      nearbyPairFallbackSuppressed,
      staleCachedRoadStateRejected,
      savedPayloadLocationFields: gridlyPickRoadHazardLocationIdentityFields(payload),
      cachedCoordinateMatchesSubmitted,
      cachedDistanceMeters: Number.isFinite(cachedDistanceMeters) ? cachedDistanceMeters : null,
      identitySource: explicitRoad ? "current_submit" : (cachedRoadAccepted ? "coordinate_matched_cache" : (resolvedRoad ? "resolver" : "none"))
    }
  };
}

function gridlyBuildRoadHazardDetailLocationMetadata(locationPayload = {}, options = {}) {
  const submittedCoordinate = gridlyCoordinateFromRecord(options.submittedCoordinate);
  const authoritativeLocationLabel = safeDisplayText(locationPayload.authoritativeLocationLabel || locationPayload.roadName || locationPayload.primaryRoad || locationPayload.locationName || "", "");
  const strongestLocationLabel = safeDisplayText(locationPayload.strongestLocationLabel || authoritativeLocationLabel, "");
  const baseDisplayLocation = safeDisplayText(locationPayload.displayLocation || strongestLocationLabel || authoritativeLocationLabel, "");
  const canonicalDisplayLocation = buildGridlyCanonicalRoadHazardDisplayLocation({
    ...locationPayload,
    displayLocation: baseDisplayLocation,
    lat: submittedCoordinate?.lat,
    lng: submittedCoordinate?.lng
  }, { submittedCoordinate });
  const displayLocation = safeDisplayText(canonicalDisplayLocation || baseDisplayLocation, "");
  const knownLocation = safeDisplayText(locationPayload.knownLocation || displayLocation, "");
  const locationLabel = safeDisplayText(locationPayload.locationLabel || displayLocation, "");
  return {
    ...locationPayload,
    canonicalDisplayLocation: displayLocation,
    canonicalLocationPhrase: displayLocation,
    authoritativeLocationLabel: displayLocation || authoritativeLocationLabel,
    strongestLocationLabel: displayLocation || strongestLocationLabel,
    displayLocation,
    knownLocation,
    locationLabel,
    resolvedLocationLabel: displayLocation,
    nearbyLocationPhrase: displayLocation,
    submittedCoordinate: submittedCoordinate ? { ...submittedCoordinate } : null
  };
}

async function gridlyInsertWithCountyMetadataFallback(client, tableName, row) {
  const insertRow = tableName === "reports" ? gridlyPickRowKeys(row, GRIDLY_REPORTS_BASE_INSERT_KEYS) : row;
  const isHazardReport = tableName === "reports" && String(row?.crossing_id || "").startsWith("hazard-");
  if (isHazardReport) gridlyLastHazardPersistenceDiagnostic = Object.freeze({
    status: "ATTEMPTING", attemptedAt: new Date().toISOString(), reportType: row?.report_type || null,
    countyId: row?.county_id || gridlyExtractStructuredMetadata(row)?.county_id || gridlyExtractStructuredMetadata(row)?.countyId || null,
    deviceId: insertRow?.device_id || null, crossingId: insertRow?.crossing_id || null,
    lat: Number.isFinite(Number(insertRow?.lat)) ? Number(insertRow.lat) : null,
    lng: Number.isFinite(Number(insertRow?.lng)) ? Number(insertRow.lng) : null,
    expiresAt: insertRow?.expires_at || null, insertedRowId: null,
    firstAttemptMode: "DEPLOYED_BASE_COLUMNS", firstAttemptError: null,
    fallbackAttempted: false, fallbackMode: null, fallbackError: null, finalStatus: "PENDING"
  });
  let first;
  try {
    first = await client.from(tableName).insert(insertRow);
  } catch (error) {
    first = { error };
  }
  const error = first?.error || null;
  if (!error) {
    const returnedRow = Array.isArray(first?.data) ? first.data[0] : first?.data;
    if (isHazardReport) gridlyLastHazardPersistenceDiagnostic = Object.freeze({ ...gridlyLastHazardPersistenceDiagnostic, status: "SUCCEEDED", finalStatus: "PERSISTED", insertedRowId: returnedRow?.id || null });
    return { data: first?.data || null, error: null, metadataPersisted: tableName !== "reports", insertedRow: insertRow, attemptedRow: insertRow, fallbackRow: null, metadataFallbackUsed: false };
  }
  if (isHazardReport) gridlyLastHazardPersistenceDiagnostic = Object.freeze({ ...gridlyLastHazardPersistenceDiagnostic, firstAttemptError: gridlyPersistenceErrorDiagnostic(error) });
  if (!isGridlySupabaseCountyMetadataSchemaError(error) && !isGridlySupabaseMissingColumnSchemaError(error)) {
    if (isHazardReport) gridlyLastHazardPersistenceDiagnostic = Object.freeze({ ...gridlyLastHazardPersistenceDiagnostic, status: "FAILED", finalStatus: "NOT_PERSISTED" });
    return { error, metadataPersisted: false, insertedRow: null, attemptedRow: insertRow, fallbackRow: null, metadataFallbackUsed: false };
  }
  const fallbackRow = tableName === "reports"
    ? insertRow
    : gridlyStripCountyMetadataFromRow(insertRow);
  console.warn(`[Gridly] ${tableName} insert shape was rejected by Supabase schema cache; retrying legacy insert shape.`, error);
  if (isHazardReport) gridlyLastHazardPersistenceDiagnostic = Object.freeze({ ...gridlyLastHazardPersistenceDiagnostic, fallbackAttempted: true, fallbackMode: "DEPLOYED_BASE_COLUMNS_RETRY" });
  let retry;
  try {
    retry = await client.from(tableName).insert(fallbackRow);
  } catch (retryError) {
    retry = { error: retryError };
  }
  if (isHazardReport) gridlyLastHazardPersistenceDiagnostic = Object.freeze({
    ...gridlyLastHazardPersistenceDiagnostic,
    status: retry?.error ? "FAILED" : "SUCCEEDED",
    fallbackError: gridlyPersistenceErrorDiagnostic(retry?.error),
    finalStatus: retry?.error ? "NOT_PERSISTED" : "PERSISTED",
    insertedRowId: (Array.isArray(retry?.data) ? retry.data[0]?.id : retry?.data?.id) || null
  });
  return {
    data: retry?.data || null,
    error: retry.error,
    metadataPersisted: false,
    insertedRow: retry.error ? null : fallbackRow,
    attemptedRow: insertRow,
    fallbackRow,
    metadataFallbackUsed: true,
    originalError: error
  };
}


