async function gridlyRunSearchCertificationAudit(queries = GRIDLY_SEARCH_DISCOVERY_CERTIFICATION_QUERIES) {
  const queryList = Array.isArray(queries) && queries.length ? queries : GRIDLY_SEARCH_DISCOVERY_CERTIFICATION_QUERIES;
  const rows = [];
  for (const entry of queryList) {
    const query = typeof entry === "string" ? entry : entry.query;
    const category = typeof entry === "string" ? "Uncategorized" : entry.category;
    const results = await gridlySearchAddress(query, { limit: GRIDLY_SEARCH_RENDER_LIMIT });
    const diagnostics = results?.gridlyProviderDiagnostics || gridlyDestinationProviderState.lastDiagnostics || {};
    const topResult = summarizeGridlyDestinationSearchResult(results[0]);
    const providerUsed = topResult?.provider || (diagnostics.providerAttempted ? "nominatim" : (diagnostics.localSeedCount ? "local_poi_seed" : "none"));
    const localSeedFound = results.some((result) => result?.provider === "local_poi_seed" || result?.localPoiSeed);
    rows.push({
      county: typeof entry === "string" ? "" : (entry.county || ""),
      category,
      query,
      found: results.length > 0,
      topResult: topResult?.title || null,
      resultCount: results.length,
      providerUsed,
      providerSource: providerUsed,
      missingResults: results.length > 0 ? [] : [query],
      rankingObservation: topResult ? `${topResult.title} ranked first from ${providerUsed}${localSeedFound ? " with Gridly local knowledge present" : ""}` : "No result returned",
      localSeedFound,
      normalizedQuery: normalizeGridlyBrandSearchText(query),
      notes: diagnostics.providerError || diagnostics.providerSkippedReason || (diagnostics.visibleQualityFiltered ? "quality filtered" : ""),
      diagnostics: {
        intent: diagnostics.intent || classifyGridlyDestinationSearchIntent(query).type,
        providerStatus: diagnostics.providerStatus || "unknown",
        providerResultCount: diagnostics.providerResultCount ?? null,
        cacheHit: Boolean(diagnostics.cacheHit),
        suppressedFarAwayCount: Number(diagnostics.suppressedFarAwayCount) || 0
      }
    });
  }
  const categories = [...new Set(rows.map((row) => row.category))];
  const counties = [...new Set(rows.map((row) => row.county).filter(Boolean))];
  const coverageSummary = categories.reduce((summary, category) => {
    const categoryRows = rows.filter((row) => row.category === category);
    const foundCount = categoryRows.filter((row) => row.found).length;
    summary[category] = {
      total: categoryRows.length,
      found: foundCount,
      coveragePercentage: categoryRows.length ? Math.round((foundCount / categoryRows.length) * 100) : 0,
      missingResults: categoryRows.filter((row) => !row.found).map((row) => row.query),
      providerSources: [...new Set(categoryRows.map((row) => row.providerSource).filter(Boolean))]
    };
    return summary;
  }, {});
  const foundTotal = rows.filter((row) => row.found).length;
  return {
    audit: "V886 Regional Search Certification Audit",
    generatedAt: new Date().toISOString(),
    regionalCoverageEnabled: true,
    regionalCountyCount: counties.length,
    countiesCovered: counties,
    totalQueries: rows.length,
    passed: foundTotal,
    failed: rows.length - foundTotal,
    passRate: rows.length ? Math.round((foundTotal / rows.length) * 100) : 0,
    coveragePercentage: rows.length ? Math.round((foundTotal / rows.length) * 100) : 0,
    coverageSummary,
    rows,
    rankingObservations: rows.map((row) => ({ query: row.query, observation: row.rankingObservation })),
    missingResults: rows.filter((row) => !row.found).map((row) => row.query),
    providerContribution: buildGridlySearchDiscoveryAudit().providerContribution
  };
}


function summarizeGridlyDestinationSearchResult(result) {
  const normalized = normalizeGridlySearchResult(result);
  if (!normalized) return null;
  const display = buildGridlySearchDisplayLines(normalized);
  const subtitle = buildGridlyLocationContext(normalized) || normalized.subtitle || "";
  return {
    title: display.title,
    subtitle,
    provider: normalized.provider || normalized.source || "unknown",
    source: normalized.provider || normalized.source || "unknown",
    intent: normalized.searchIntent || "",
    bucket: normalized.searchRank?.bucket || "",
    distanceMiles: Number.isFinite(normalized.searchRank?.anchorDistanceMiles)
      ? Number(normalized.searchRank.anchorDistanceMiles.toFixed(1))
      : (Number.isFinite(normalized.searchRank?.distanceMiles) ? Number(normalized.searchRank.distanceMiles.toFixed(1)) : null),
    lat: Number.isFinite(normalized.lat) ? Number(normalized.lat.toFixed(6)) : null,
    lng: Number.isFinite(normalized.lng) ? Number(normalized.lng.toFixed(6)) : null
  };
}

async function gridlyDestinationSearchBatchTest(queries = GRIDLY_DESTINATION_SEARCH_BATCH_DEFAULT_QUERIES) {
  const queryList = Array.isArray(queries) && queries.length ? queries : GRIDLY_DESTINATION_SEARCH_BATCH_DEFAULT_QUERIES;
  const rows = [];
  for (const query of queryList) {
    const queryText = String(query || "").trim();
    if (!queryText) continue;
    const results = await gridlySearchAddress(queryText, { limit: 5 });
    const diagnostics = results?.gridlyProviderDiagnostics || gridlyDestinationProviderState.lastDiagnostics || {};
    const top5 = results.map((result) => summarizeGridlyDestinationSearchResult(result)).filter(Boolean).slice(0, 5);
    rows.push({
      query: queryText,
      count: results.length,
      suppressedFarAwayCount: Number(diagnostics.suppressedFarAwayCount) || 0,
      visibleQualityFiltered: Boolean(diagnostics.visibleQualityFiltered),
      localQualityResultCount: Number(diagnostics.localQualityResultCount) || 0,
      genericLocalProviderFillerSuppressed: Boolean(diagnostics.genericLocalProviderFillerSuppressed),
      firstTitle: top5[0]?.title || "",
      firstSubtitle: top5[0]?.subtitle || "",
      provider: top5[0]?.provider || "",
      source: top5[0]?.source || "",
      intent: top5[0]?.intent || classifyGridlyDestinationSearchIntent(queryText).type,
      bucket: top5[0]?.bucket || "",
      distanceMiles: top5[0]?.distanceMiles ?? null,
      top5
    });
  }
  return rows;
}

