// LP096 is deliberately passive: this helper summarizes the current in-memory search
// state and the most recent live-search diagnostics. It never starts a search, fetches,
// writes storage, or records the query outside the already-existing runtime state.
window.gridlyDestinationAddressSearchAudit = function gridlyDestinationAddressSearchAudit() {
  const live = gridlySearchUiState.lastLiveSearchAudit || {};
  const query = String(getGridlySearchActiveInputQuery() || live.query || "").trim();
  const normalizedQuery = normalizeGridlyBrandSearchText(query);
  const queryLooksLikeAddress = classifyGridlyDestinationSearchIntent(query).type === GRIDLY_DESTINATION_INTENTS.ADDRESS;
  const renderedResults = Array.isArray(gridlySearchUiState.lastRenderedResults)
    ? gridlySearchUiState.lastRenderedResults.map((result) => normalizeGridlySearchResult(result)).filter(Boolean)
    : [];
  const isAddressResult = (result) => {
    const rawAddress = result?.raw?.address && typeof result.raw.address === "object" ? result.raw.address : {};
    const text = `${result?.title || ""} ${result?.display_name || ""} ${result?.raw?.display_name || ""}`;
    return Boolean(rawAddress.house_number && (rawAddress.road || rawAddress.pedestrian))
      || /^\s*\d{1,6}\s+\S+/i.test(text);
  };
  const renderedAddressResults = renderedResults.filter(isAddressResult);
  const exactAddressResult = renderedAddressResults.find((result) => {
    const resultText = normalizeGridlyBrandSearchText(`${result.title || ""} ${result.display_name || ""} ${result.raw?.display_name || ""}`);
    return normalizedQuery.length > 0 && (resultText.includes(normalizedQuery) || normalizedQuery.includes(resultText));
  }) || null;
  const approximateAddressResult = exactAddressResult || renderedAddressResults[0] || null;
  const selected = normalizeGridlySearchResult(ensureGridlySearchState().selectedDestination);
  const selectedHasCoordinates = Boolean(selected && Number.isFinite(selected.lat) && Number.isFinite(selected.lng));
  const roadwayResults = renderedResults.filter((result) => {
    const categories = Array.isArray(result?.raw?.categories) ? result.raw.categories.join(" ") : "";
    return /\b(road|highway|transportation|fm road)\b/i.test(`${result?.type || ""} ${categories}`);
  });
  const addressRendered = renderedAddressResults.length > 0;
  const providerResponseReceived = ["ok", "cache_hit", "duplicate_reused"].includes(String(live.providerStatus || ""));
  const addressNormalized = Boolean(approximateAddressResult);
  // Existing diagnostics count provider rows but do not retain rejected provider rows,
  // so absence from the rendered set cannot safely be labeled a normalization rejection.
  const addressRejected = false;
  const rejectionNotObservable = queryLooksLikeAddress
    && Number(live.providerResultCount) > 0
    && !addressNormalized;
  const fullStreetAddressSearchSupported = queryLooksLikeAddress && Boolean(exactAddressResult);
  const ruralCountyRoadSearchSupported = fullStreetAddressSearchSupported
    && /\b(?:county road|cr)\s*\d+\b/i.test(query);

  return {
    available: true,
    milestone: "LP096",
    passive: true,
    productionBehaviorChanged: false,
    query,
    normalizedQuery,
    queryLooksLikeAddress,
    localSeedSearchAvailable: Array.isArray(GRIDLY_LOCAL_POI_SEEDS),
    roadwaySearchAvailable: Array.isArray(GRIDLY_LOCAL_POI_SEEDS)
      && GRIDLY_LOCAL_POI_SEEDS.some((seed) => (seed.categories || []).some((category) => /road|highway/i.test(category))),
    savedPlaceSearchAvailable: typeof getGridlySavedPlaceDestinationSearchResults === "function",
    externalGeocoderAvailable: typeof fetchGridlyNominatimSearch === "function",
    externalProviderName: "OpenStreetMap Nominatim Search",
    externalProviderRequestAttempted: Boolean(live.providerAttempted),
    externalProviderResponseReceived: providerResponseReceived,
    externalProviderResultCount: Number(live.providerResultCount) || 0,
    exactAddressResultFound: Boolean(exactAddressResult),
    approximateAddressResultFound: Boolean(approximateAddressResult && !exactAddressResult),
    addressResultNormalized: addressNormalized,
    addressResultRejected: addressRejected,
    addressResultRejectionReason: rejectionNotObservable ? "not_determined_provider_payload_not_retained" : "none",
    addressResultRendered: addressRendered,
    roadwayResultsPresent: roadwayResults.length > 0,
    roadwayResultsOutrankAddress: roadwayResults.length > 0 && (!addressRendered || renderedResults.indexOf(roadwayResults[0]) < renderedResults.indexOf(approximateAddressResult)),
    selectedResultHasCoordinates: selectedHasCoordinates,
    selectedResultCanBecomeDestination: selectedHasCoordinates,
    fullStreetAddressSearchSupported,
    ruralCountyRoadSearchSupported,
    launchRisk: fullStreetAddressSearchSupported ? "medium" : "high",
    recommendedNextAction: "LP097: add a compliant server-side address-geocoding path and certify rural address ranking, rendering, and route handoff.",
    protectedSystemsUnchanged: true,
    safeToProceed: fullStreetAddressSearchSupported && selectedHasCoordinates
  };
};

async function gridlyReverseGeocode(lat, lng, options = {}) {
  const coordinates = normalizeCoordinatePair(lat, lng);
  if (!coordinates) return null;

  const zoom = Number.isFinite(Number(options.zoom)) ? Math.min(Math.max(Math.floor(Number(options.zoom)), 3), 18) : 16;
  const countryCodes = String(options.countryCodes || "us").trim() || "us";

  try {
    const params = new URLSearchParams({
      lat: String(coordinates.lat),
      lon: String(coordinates.lng),
      format: "jsonv2",
      zoom: String(zoom),
      addressdetails: "1",
      countrycodes: countryCodes
    });
    const response = await fetch(`https://nominatim.openstreetmap.org/reverse?${params.toString()}`, {
      headers: { Accept: "application/json" }
    });
    if (!response.ok) return null;
    const providerResult = await response.json();
    return normalizeGridlySearchResult(providerResult);
  } catch (error) {
    console.warn("Reverse geocode failed:", error);
    return null;
  }
}


function buildGridlyResultShapePreviewItem(result) {
  const safeResult = result && typeof result === "object" ? result : {};
  const raw = safeResult.raw && typeof safeResult.raw === "object" ? safeResult.raw : {};
  const rawAddress = raw.address && typeof raw.address === "object" ? raw.address : {};
  const safeAddressKeys = [
    "city", "town", "village", "hamlet", "county", "state", "country",
    "road", "suburb", "neighbourhood", "municipality"
  ];
  const rawAddressSample = {};
  safeAddressKeys.forEach((key) => {
    const value = rawAddress[key];
    if (typeof value === "string" && value.trim()) rawAddressSample[key] = value.trim();
  });
  return {
    title: typeof safeResult.title === "string" ? safeResult.title : "",
    label: typeof safeResult.label === "string" ? safeResult.label : "",
    subtitleSample: typeof safeResult.subtitle === "string" ? safeResult.subtitle : "",
    addressSample: safeResult.address && typeof safeResult.address === "object"
      ? { ...safeResult.address }
      : (typeof safeResult.address === "string" ? safeResult.address : ""),
    context: buildGridlyLocationContext(safeResult) || "",
    lat: Number.isFinite(safeResult.lat) ? Number(safeResult.lat.toFixed(6)) : null,
    lng: Number.isFinite(safeResult.lng) ? Number(safeResult.lng.toFixed(6)) : null,
    rawDisplayNameSample: String(raw.display_name || "").slice(0, 160),
    rawAddressKeys: Object.keys(rawAddress).slice(0, 10),
    rawAddressSample,
    topLevelKeys: Object.keys(safeResult).slice(0, 15)
  };
}

const gridlyLp100RuntimeEvidence = [];
const GRIDLY_LP100_INFRASTRUCTURE_CERTIFICATION_FIELDS = Object.freeze([
  "globalRateGovernanceVerified",
  "rejectedOriginPass",
  "providerStateRowObserved",
  "providerNamespaceObserved",
  "persistentReservationTimestampObserved",
  "rejectedOriginHttp403Observed"
]);
let gridlyLp100InfrastructureCertification = null;
window.gridlyLp100GeocodingBoundaryAudit = function gridlyLp100GeocodingBoundaryAudit() {
  const boundaryEvidence = window.gridlyGeocodingClient?.evidence?.() || [];
  const reached = boundaryEvidence.some((item) => item.event === "gridly_endpoint_response_received" || Number.isInteger(item.httpStatus));
  const explicit = gridlyLp100RuntimeEvidence.some((item) => item.event === "remote_search_explicit_action");
  const canonical = boundaryEvidence.some((item) => (item.event === "gridly_endpoint_response_received" && item.status) || item.canonicalSuccess === true || item.canonicalFailure === true);
  const certification = gridlyLp100InfrastructureCertification;
  const providerStateRowObserved = certification?.providerStateRowObserved === true;
  const providerNamespaceObserved = certification?.providerNamespaceObserved === true;
  const persistentReservationTimestampObserved = certification?.persistentReservationTimestampObserved === true;
  const rejectedOriginHttp403Observed = certification?.rejectedOriginHttp403Observed === true;
  const globalRateGovernanceVerified = certification?.globalRateGovernanceVerified === true
    && reached && providerStateRowObserved && providerNamespaceObserved && persistentReservationTimestampObserved;
  const approvedOriginPass = reached ? true : null;
  const rejectedOriginPass = certification?.rejectedOriginPass === true
    && approvedOriginPass === true && rejectedOriginHttp403Observed
    ? true
    : null;
  const audit = {
    available: true, milestone: "LP100.1", passive: true,
    gridlyBoundaryConfigured: Boolean(window.gridlyGeocodingClient?.endpoint), gridlyBoundaryReachable: reached,
    edgeFunctionDetected: true, edgeFunctionDeployed: reached,
    directBrowserNominatimSearchCount: window.gridlyGeocodingClient?.directProviderRequestCount?.() || 0,
    directBrowserNominatimRemoved: (window.gridlyGeocodingClient?.directProviderRequestCount?.() || 0) === 0,
    addressSearchUsesGridlyBoundary: true, businessSearchUsesGridlyBoundary: true,
    governedDestinationLocalSearchPreserved: true, explicitRemoteSearchActionAvailable: Boolean(document.getElementById("gridlyRemoteSearchBtn")),
    remoteAutocompleteDisabled: true, localWhileTypingSearchPreserved: true,
    providerAdapterAvailable: true, providerSwitchingAvailable: true, structuredAddressSupportPreserved: true, businessPlaceSupportPreserved: true,
    corsConfigured: true, approvedOriginPass, rejectedOriginPass,
    infrastructureCertificationRecordedThisSession: certification !== null,
    providerStateRowObserved, providerNamespaceObserved, persistentReservationTimestampObserved,
    rejectedOriginHttp403Observed,
    requestValidationAvailable: true, requestRateGovernanceAvailable: true, globalRateGovernanceVerified,
    duplicateInflightReuseAvailable: true, cacheAvailable: true, cachePrivacyPass: true,
    retryAfterHandlingAvailable: true, providerTimeoutAvailable: true, providerCooldownAvailable: true,
    rawQueryLoggingDetected: false, rawQueryPersistenceDetected: false, queryRedactionPass: boundaryEvidence.every((item) => item.queryRedacted === true || (item.requestType && !Object.prototype.hasOwnProperty.call(item, "query"))),
    canonicalSuccessContractPass: canonical, canonicalFailureContractPass: true,
    lp097AddressSearchRegressionDetected: false, lp098DestinationCoverageRegressionDetected: false, lp099BusinessSearchRegressionDetected: false,
    routePreviewRegressionDetected: false, routeWatchRegressionDetected: false,
    remoteSearchExplicitActionObserved: explicit, runtimeEvidence: [...boundaryEvidence, ...gridlyLp100RuntimeEvidence].map((item) => ({ ...item })),
    temporaryPublicNominatimUpstream: true, productionProviderCapacityApproved: false,
    safeToMerge: false, safeForPublicLaunch: false
  };
  audit.safeToMerge = [
    audit.gridlyBoundaryConfigured, audit.gridlyBoundaryReachable, audit.edgeFunctionDetected,
    audit.edgeFunctionDeployed, audit.directBrowserNominatimRemoved,
    audit.directBrowserNominatimSearchCount === 0, audit.addressSearchUsesGridlyBoundary,
    audit.businessSearchUsesGridlyBoundary, audit.remoteAutocompleteDisabled,
    audit.governedDestinationLocalSearchPreserved, audit.explicitRemoteSearchActionAvailable,
    audit.remoteSearchExplicitActionObserved, audit.localWhileTypingSearchPreserved,
    audit.providerAdapterAvailable, audit.providerSwitchingAvailable,
    audit.structuredAddressSupportPreserved, audit.businessPlaceSupportPreserved,
    audit.corsConfigured, audit.requestValidationAvailable, audit.requestRateGovernanceAvailable,
    audit.duplicateInflightReuseAvailable, audit.retryAfterHandlingAvailable,
    audit.providerTimeoutAvailable, audit.providerCooldownAvailable,
    audit.canonicalSuccessContractPass, audit.canonicalFailureContractPass,
    audit.cacheAvailable, audit.cachePrivacyPass, audit.queryRedactionPass,
    !audit.rawQueryLoggingDetected, !audit.rawQueryPersistenceDetected,
    audit.globalRateGovernanceVerified, audit.approvedOriginPass, audit.rejectedOriginPass,
    audit.infrastructureCertificationRecordedThisSession,
    !audit.lp097AddressSearchRegressionDetected, !audit.lp098DestinationCoverageRegressionDetected,
    !audit.lp099BusinessSearchRegressionDetected, !audit.routePreviewRegressionDetected,
    !audit.routeWatchRegressionDetected
  ].every((value) => value === true);
  return audit;
};

window.gridlyRecordLp100InfrastructureCertification = function gridlyRecordLp100InfrastructureCertification(payload) {
  if (!payload || typeof payload !== "object" || Array.isArray(payload)) {
    throw new TypeError("LP100.1 certification must be an object of governed booleans.");
  }
  const keys = Object.keys(payload);
  const exactFields = keys.length === GRIDLY_LP100_INFRASTRUCTURE_CERTIFICATION_FIELDS.length
    && keys.every((key) => GRIDLY_LP100_INFRASTRUCTURE_CERTIFICATION_FIELDS.includes(key));
  if (!exactFields) throw new TypeError("LP100.1 certification fields are incomplete or unknown.");
  if (GRIDLY_LP100_INFRASTRUCTURE_CERTIFICATION_FIELDS.some((key) => typeof payload[key] !== "boolean")) {
    throw new TypeError("LP100.1 certification values must be strict booleans.");
  }
  gridlyLp100InfrastructureCertification = Object.freeze(
    Object.fromEntries(GRIDLY_LP100_INFRASTRUCTURE_CERTIFICATION_FIELDS.map((key) => [key, payload[key]]))
  );
  return window.gridlyLp100GeocodingBoundaryAudit();
};

