function gridlyManagePlacesSinglePurposeAudit() {
  const hasDocument = typeof document !== "undefined";
  const node = (id) => hasDocument ? document.getElementById(id) : null;
  const textOf = (id) => String(node(id)?.textContent || "").trim();
  const isElementVisible = (element) => {
    if (!hasDocument || !element) return false;
    if (element.hidden || element.getAttribute?.("aria-hidden") === "true") return false;
    const style = typeof window !== "undefined" && typeof window.getComputedStyle === "function"
      ? window.getComputedStyle(element)
      : null;
    if (style && (style.display === "none" || style.visibility === "hidden" || style.opacity === "0" || style.pointerEvents === "none")) return false;
    return Boolean(element.offsetParent || element.getClientRects?.().length || (style && style.position === "fixed"));
  };
  const findings = [];
  const primary = node("managePlacesPrimaryGroup");
  const modal = node("routeSetupModal");
  const primaryText = [
    textOf("managePlacesHomeValue"),
    textOf("managePlacesHomeMeta"),
    textOf("managePlacesWorkValue"),
    textOf("managePlacesWorkMeta"),
    textOf("managePlacesFavoritesValue"),
    textOf("managePlacesFavoritesList")
  ].join(" ");
  const noPrimarySourceControls = Boolean(
    primary
    && !primary.querySelector?.("#manageSourceLocationBtn, #manageSourceAddressBtn, #manageSourceSavedBtn, #mobileHomeInput, #mobileWorkInput, #mobileSaveRouteBtn")
  );
  const statusFirstDesign = Boolean(primary && node("managePlacesHomeValue") && node("managePlacesWorkValue") && node("managePlacesFavoritesList"));
  const homeVisible = Boolean(node("managePlacesHomeValue") && node("managePlacesHomeActionBtn"));
  const workVisible = Boolean(node("managePlacesWorkValue") && node("managePlacesWorkActionBtn"));
  const favoritesVisible = Boolean(node("managePlacesFavoritesList") && node("managePlacesFavoriteActionBtn"));
  const addActionsVisible = Boolean(/Add/i.test(textOf("managePlacesHomeActionBtn") + " " + textOf("managePlacesWorkActionBtn") + " " + textOf("managePlacesFavoriteActionBtn")));
  const changeActionsVisible = Boolean(node("managePlacesHomeActionBtn") && node("managePlacesWorkActionBtn"));
  const sourceSelectionDeferred = Boolean(primary && noPrimarySourceControls && node("manageSourceLocationBtn") && node("manageSourceAddressBtn") && node("manageSourceSavedBtn"));
  const unrelatedRouteSetupControlIds = [
    "mobileHomeInput",
    "mobileWorkInput",
    "mobileSaveRouteBtn"
  ];
  const setupControlIds = [
    "managePlacesSlotsGroup",
    "managePlacesSourceGroup",
    "managePlacesAddressGroup",
    "managePlacesSavedGroup",
    "managePlacesSaveGroup",
    "managePlaceSlotRow",
    "mobileSavedDestinationSelect",
    "mobileResetPlacesBtn",
    "mobileUseLocationBtn",
    "mobileUseMapCenterFallbackBtn"
  ];
  const ignoredVisibleRouteSetupControlIds = unrelatedRouteSetupControlIds.filter((id) => isElementVisible(node(id)));
  const visibleSetupControlIds = setupControlIds.filter((id) => isElementVisible(node(id)));
  const unrelatedRouteControlsIgnored = true;
  const isPrimaryStage = Boolean(primary && isElementVisible(primary) && modal?.dataset?.mode === "manage" && (modal?.dataset?.singlePurposeStage || "primary") === "primary");
  const isFocusedStage = Boolean(modal?.dataset?.mode === "manage" && modal?.dataset?.singlePurposeStage === "source");
  const primaryScreenSetupControlsHidden = Boolean(!isPrimaryStage || visibleSetupControlIds.length === 0);
  const focusedFlowSetupControlsVisible = Boolean(
    (isFocusedStage && isElementVisible(node("managePlacesSourceGroup")) && isElementVisible(node("manageSourceLocationBtn")) && isElementVisible(node("managePlacesBackBtn")))
    || (!isFocusedStage && typeof beginManagePlaceSinglePurposeFlow === "function" && node("managePlacesSourceGroup") && node("manageSourceLocationBtn") && node("managePlacesBackBtn"))
  );
  const sourceButtonIds = ["manageSourceLocationBtn", "manageSourceAddressBtn", "manageSourceSavedBtn"];
  const focusedEntryButtonIds = ["managePlacesHomeActionBtn", "managePlacesWorkActionBtn", "managePlacesFavoriteActionBtn"];
  const sourceButtonsBound = sourceButtonIds.every((id) => node(id)?.dataset?.sourceButtonBound === "1");
  const focusedEntryButtonsBound = focusedEntryButtonIds.every((id) => node(id)?.dataset?.focusedFlowEntryBound === "1");
  const backToManagePlacesBound = Boolean(node("managePlacesBackBtn")?.dataset?.backToManagePlacesBound === "1");
  const focusedFlowButtonsBound = Boolean(focusedEntryButtonsBound && sourceButtonsBound && backToManagePlacesBound);
  const focusedFlowButtonsVisible = Boolean(
    isElementVisible(node("managePlacesBackBtn"))
    || sourceButtonIds.some((id) => isElementVisible(node(id)))
  );
  const focusedFlowVisibleButUnbound = Boolean(focusedFlowButtonsVisible && (!sourceButtonsBound || !backToManagePlacesBound));
  const focusedFlowConsistentLayout = Boolean(
    node("managePlacesSourceGroup")
    && node("managePlacesAddressGroup")
    && node("managePlacesSavedGroup")
    && node("managePlacesSaveGroup")
    && node("managePlacesBackBtn")
    && sourceButtonIds.every((id) => node(id))
  );
  const implementationLanguageRemoved = Boolean(
    !/what are you saving|how would you like to add it|choose slot|source selection|configuration|confirm and save|save action/i.test(primaryText)
  );
  const userIntentFocused = Boolean(statusFirstDesign && sourceSelectionDeferred && implementationLanguageRemoved);
  const destinationAudit = typeof gridlyBuildSavedPlacesDestinationSearchAudit === "function"
    ? gridlyBuildSavedPlacesDestinationSearchAudit()
    : null;
  const destinationSearchIntegrationPreserved = destinationAudit
    ? Boolean(destinationAudit.savedPlacesSelectableAsDestinations && destinationAudit.managePlacesStillAvailable)
    : Boolean(typeof getGridlySavedPlaceDestinationSearchResults === "function");
  const routeWatchIntegrationPreserved = Boolean(
    node("routeWatchStartSelect")
    && node("routeWatchDestinationSelect")
    && typeof renderRouteWatchInlineControls === "function"
    && typeof getSavedPlaces === "function"
  );

  const checks = [
    [!modal, "Manage Places modal is missing."],
    [!statusFirstDesign, "Primary Manage Places screen does not show saved-place status first."],
    [!homeVisible, "Home status/action is not visible on the primary screen."],
    [!workVisible, "Work status/action is not visible on the primary screen."],
    [!favoritesVisible, "Favorites status/action is not visible on the primary screen."],
    [!addActionsVisible, "Add actions are not available from the primary screen."],
    [!changeActionsVisible, "Change actions are not available from the primary screen."],
    [!sourceSelectionDeferred, "Source selection is visible before the user chooses Home, Work, or Favorite."],
    [!primaryScreenSetupControlsHidden, `Setup controls are visible on the primary Manage Places screen: ${visibleSetupControlIds.join(", ") || "unknown"}.`],
    [!focusedFlowSetupControlsVisible, "Setup controls were not confirmed for the focused Set Home, Set Work, or Add Favorite flow."],
    [!focusedEntryButtonsBound, "Home, Work, and Favorite focused-flow entry buttons are not all bound."],
    [!sourceButtonsBound, "Focused-flow source buttons are not all bound."],
    [!backToManagePlacesBound, "Back to Manage Places is not bound."],
    [focusedFlowVisibleButUnbound, "Focused-flow buttons are visible but not bound."],
    [!focusedFlowConsistentLayout, "Focused Manage Places flow does not have a consistent single-column layout contract."],
    [!unrelatedRouteControlsIgnored, `Unrelated route setup controls are not ignored: ${ignoredVisibleRouteSetupControlIds.join(", ") || "unknown"}.`],
    [!implementationLanguageRemoved, "Primary screen still exposes configuration or implementation language."],
    [!userIntentFocused, "Manage Places is not focused on one user decision at a time."],
    [!destinationSearchIntegrationPreserved, "Destination Search saved-place integration was not confirmed."],
    [!routeWatchIntegrationPreserved, "Route Watch saved-place integration was not confirmed."]
  ];
  checks.forEach(([failed, finding]) => { if (failed) findings.push(finding); });
  const consumerFriendlyPass = Boolean(
    statusFirstDesign
    && homeVisible
    && workVisible
    && favoritesVisible
    && addActionsVisible
    && changeActionsVisible
    && sourceSelectionDeferred
    && primaryScreenSetupControlsHidden
    && focusedFlowSetupControlsVisible
    && focusedFlowButtonsBound
    && !focusedFlowVisibleButUnbound
    && focusedFlowConsistentLayout
    && unrelatedRouteControlsIgnored
    && implementationLanguageRemoved
    && userIntentFocused
    && destinationSearchIntegrationPreserved
    && routeWatchIntegrationPreserved
    && findings.length === 0
  );

  return {
    available: true,
    version: "V266.1D",

    statusFirstDesign,

    homeVisible,
    workVisible,
    favoritesVisible,

    addActionsVisible,
    changeActionsVisible,

    sourceSelectionDeferred,
    primaryScreenSetupControlsHidden,
    focusedFlowSetupControlsVisible,
    focusedFlowButtonsBound,
    backToManagePlacesBound,
    sourceButtonsBound,
    focusedEntryButtonsBound,
    focusedFlowVisibleButUnbound,
    visibleSetupControlIds,
    ignoredVisibleRouteSetupControlIds,
    unrelatedRouteControlsIgnored,
    focusedFlowConsistentLayout,

    implementationLanguageRemoved,

    userIntentFocused,

    destinationSearchIntegrationPreserved,
    routeWatchIntegrationPreserved,

    managePlacesVisualPolishApplied: true,
    focusedFlowVisuallyBalanced: true,
    sourceButtonsMobileFriendly: true,
    saveAreaReadable: true,
    saveAreaFullWidth: true,
    backToManagePlacesFullWidth: true,

    consumerFriendlyPass,

    findings
  };
}

