exposeGridlyAuditHelper("gridlyManagePlacesSinglePurposeAudit", gridlyManagePlacesSinglePurposeAudit);


function gridlyBuildSavedPlacesDestinationSearchAudit() {
  const findings = [];
  const state = typeof getSavedPlacesState === "function" ? getSavedPlacesState() : normalizeSavedPlaces();
  const homeSaved = isConfiguredPlace(state.home);
  const workSaved = isConfiguredPlace(state.work);
  const favoritePlaces = [
    ...(Array.isArray(state.custom) ? state.custom : []),
    ...(Array.isArray(state.favorites) ? state.favorites : [])
  ].filter((place) => isConfiguredPlace(place));
  const favoriteCount = favoritePlaces.length;
  const homeResults = getGridlySavedPlaceDestinationSearchResults("home");
  const workResults = getGridlySavedPlaceDestinationSearchResults("work");
  const favoriteResults = getGridlySavedPlaceDestinationSearchResults("favorites");
  const allSavedResults = getGridlySavedPlaceDestinationSearchResults("", { includeAll: true });
  const selected = normalizeGridlySearchResult(ensureGridlySearchState()?.selectedDestination);
  const selectedIsSavedPlace = Boolean(selected && (selected.provider === "saved_place" || selected.raw?.savedPlace === true));
  const preview = typeof getGridlyDestinationRoutePreviewState === "function" ? getGridlyDestinationRoutePreviewState() : (window.GridlyDestinationRoutePreview || {});
  const routeOriginAudit = typeof gridlyRouteOriginAudit === "function" ? gridlyRouteOriginAudit() : null;
  const routeViewportAudit = typeof gridlyRouteViewportOwnershipAudit === "function" ? gridlyRouteViewportOwnershipAudit() : null;
  const routePreviewForSavedPlace = Boolean(selectedIsSavedPlace && preview?.destination && normalizeCoordinatePair(preview.destination.lat, preview.destination.lng));
  const savedPlacesDetected = Boolean(homeSaved || workSaved || favoriteCount > 0);
  const homeSearchable = !homeSaved || homeResults.some((result) => result.savedPlaceType === "home" || result.raw?.savedPlaceType === "home");
  const workSearchable = !workSaved || workResults.some((result) => result.savedPlaceType === "work" || result.raw?.savedPlaceType === "work");
  const favoritesSearchable = favoriteCount === 0 || favoriteResults.filter((result) => result.savedPlaceType === "favorite" || result.raw?.savedPlaceType === "favorite").length >= Math.min(favoriteCount, favoriteResults.length || favoriteCount);
  const savedPlacesSelectableAsDestinations = allSavedResults.every((result) => Number.isFinite(result.lat) && Number.isFinite(result.lng) && result.provider === "saved_place");
  const savedPlaceRowsConsumerFriendly = allSavedResults.every((result) => buildGridlyLocationContext(result) === "Saved place" && !/configure|setup|manage|settings/i.test(`${result.title} ${result.subtitle}`));
  const managePlacesStillAvailable = Boolean(document.getElementById("desktopManageRouteBtn") || document.getElementById("routeSetupModal") || typeof openRouteSetupModal === "function");
  const savedPlaceSelectionPreservesRouteOriginOwnership = routeOriginAudit ? routeOriginAudit.version === "V257.4" && routeOriginAudit.protectedSystemsPass === true : true;
  const savedPlaceSelectionPreservesViewportOwnership = routeViewportAudit ? routeViewportAudit.version === "V257.3" && routeViewportAudit.protectedSystemsPass === true : true;

  if (homeSaved && !homeSearchable) findings.push("Home is saved but not searchable as a destination.");
  if (workSaved && !workSearchable) findings.push("Work is saved but not searchable as a destination.");
  if (favoriteCount > 0 && !favoritesSearchable) findings.push("One or more Favorites are saved but not searchable as destinations.");
  if (!savedPlacesSelectableAsDestinations) findings.push("Saved-place search results are missing destination coordinates.");
  if (!savedPlaceRowsConsumerFriendly) findings.push("Saved-place search rows look like configuration rows instead of destination choices.");
  if (!managePlacesStillAvailable) findings.push("Manage Places entry point was not detected.");
  if (!savedPlaceSelectionPreservesRouteOriginOwnership) findings.push("Route origin ownership audit did not report the V257.4 protected state.");
  if (!savedPlaceSelectionPreservesViewportOwnership) findings.push("Route viewport ownership audit did not report the V257.3 protected state.");

  const consumerFriendlyPass = Boolean(savedPlaceRowsConsumerFriendly && !findings.some((finding) => /configure|setup|settings|technical|directional|trust/i.test(finding)));
  return {
    available: true,
    version: "V257.5",
    savedPlacesDetected,
    homeSaved,
    workSaved,
    favoriteCount,
    homeSearchable,
    workSearchable,
    favoritesSearchable,
    savedPlacesSelectableAsDestinations,
    savedPlaceSelectionCreatesRoutePreview: selectedIsSavedPlace ? routePreviewForSavedPlace : savedPlacesSelectableAsDestinations,
    savedPlaceSelectionPreservesRouteOriginOwnership,
    savedPlaceSelectionPreservesViewportOwnership,
    managePlacesStillAvailable,
    consumerFriendlyPass,
    canProceedToPatch: true,
    findings
  };
}

window.gridlySavedPlacesDestinationSearchAudit = function gridlySavedPlacesDestinationSearchAudit() {
  return gridlyBuildSavedPlacesDestinationSearchAudit();
};

function gridlySavedPlacesEmptyStateElementVisible(el) {
  if (!(el instanceof HTMLElement) || el.hidden) return false;
  const text = String(el.textContent || "").trim();
  if (!text) return false;
  const style = typeof getComputedStyle === "function" ? getComputedStyle(el) : null;
  return !(style && (style.visibility === "hidden" || Number(style.opacity || "1") === 0));
}

function gridlyBuildSavedPlacesEmptyStateAudit() {
  const findings = [];
  const state = typeof getSavedPlacesState === "function" ? getSavedPlacesState() : normalizeSavedPlaces();
  const homeSaved = isConfiguredPlace(state.home);
  const workSaved = isConfiguredPlace(state.work);
  const favoritesCount = [
    ...(Array.isArray(state.custom) ? state.custom : []),
    ...(Array.isArray(state.favorites) ? state.favorites : [])
  ].filter((place) => isConfiguredPlace(place)).length;
  const note = document.getElementById("destinationEmptyNote");
  const homeBtn = document.getElementById("destinationHomeBtn");
  const workBtn = document.getElementById("destinationWorkBtn");
  const visibleText = [
    note && gridlySavedPlacesEmptyStateElementVisible(note) ? note.textContent : "",
    homeBtn && gridlySavedPlacesEmptyStateElementVisible(homeBtn) ? homeBtn.textContent : "",
    workBtn && gridlySavedPlacesEmptyStateElementVisible(workBtn) ? workBtn.textContent : ""
  ].join(" ");
  const needsHomeGuidance = !homeSaved;
  const needsWorkGuidance = !workSaved;
  const homeGuidanceVisible = !needsHomeGuidance || /home not saved yet/i.test(visibleText);
  const workGuidanceVisible = !needsWorkGuidance || /work not saved yet/i.test(visibleText);
  const emptyStateGuidanceVisible = Boolean((needsHomeGuidance || needsWorkGuidance) ? (homeGuidanceVisible && workGuidanceVisible) : true);
  const managePlacesAvailable = Boolean(
    document.getElementById("desktopManageRouteBtn")
    || document.getElementById("routeSetupModal")
    || document.getElementById("destinationAddBtn")
    || typeof openRouteSetupModal === "function"
  );
  const homeResults = typeof getGridlySavedPlaceDestinationSearchResults === "function" ? getGridlySavedPlaceDestinationSearchResults("home") : [];
  const workResults = typeof getGridlySavedPlaceDestinationSearchResults === "function" ? getGridlySavedPlaceDestinationSearchResults("work") : [];
  const unsavedHomeShownAsDestination = Boolean(!homeSaved && homeResults.some((result) => (result.savedPlaceType || result.raw?.savedPlaceType) === "home"));
  const unsavedWorkShownAsDestination = Boolean(!workSaved && workResults.some((result) => (result.savedPlaceType || result.raw?.savedPlaceType) === "work"));

  if (!emptyStateGuidanceVisible) findings.push("Missing Home/Work empty-state guidance in Destination Search.");
  if (!managePlacesAvailable) findings.push("Manage Places entry point was not detected.");
  if (unsavedHomeShownAsDestination) findings.push("Unsaved Home is appearing as a selectable destination.");
  if (unsavedWorkShownAsDestination) findings.push("Unsaved Work is appearing as a selectable destination.");

  const consumerFriendlyPass = Boolean(emptyStateGuidanceVisible && managePlacesAvailable && !unsavedHomeShownAsDestination && !unsavedWorkShownAsDestination && findings.length === 0);
  return {
    available: true,
    version: "V258",
    homeSaved,
    workSaved,
    favoritesCount,
    emptyStateGuidanceVisible,
    managePlacesAvailable,
    unsavedHomeShownAsDestination,
    unsavedWorkShownAsDestination,
    consumerFriendlyPass,
    findings
  };
}

window.gridlySavedPlacesEmptyStateAudit = function gridlySavedPlacesEmptyStateAudit() {
  return gridlyBuildSavedPlacesEmptyStateAudit();
};

function gridlyBuildSavedPlaceRouteClarityAudit() {
  const findings = [];
  const searchState = typeof ensureGridlySearchState === "function" ? ensureGridlySearchState() : null;
  const selected = typeof normalizeGridlySearchResult === "function"
    ? normalizeGridlySearchResult(searchState?.selectedDestination)
    : searchState?.selectedDestination;
  const preview = typeof getGridlyDestinationRoutePreviewState === "function"
    ? getGridlyDestinationRoutePreviewState()
    : (window.GridlyDestinationRoutePreview || {});
  const ownership = typeof updateGridlyRouteOwnershipSurface === "function"
    ? updateGridlyRouteOwnershipSurface()
    : (typeof resolveGridlyRouteOwnershipSurface === "function" ? resolveGridlyRouteOwnershipSurface() : {});
  const routeOriginLabel = gridlyFriendlyPlaceLabel(preview?.source?.label || ownership?.originLabel || "", "");
  const routeDestinationLabel = gridlyFriendlyPlaceLabel(preview?.destination?.label || selected?.title || selected?.label || ownership?.destinationLabel || "", "");
  const selectedDestinationIsSavedPlace = isGridlySavedPlaceDestination(selected);
  const relationLineText = preview?.routeRelationLineText || (routeOriginLabel && routeDestinationLabel ? getGridlyRouteRelationLineText(routeOriginLabel, routeDestinationLabel) : "");
  const surfaceText = [
    document.getElementById("mobileDestinationCommandMeta")?.textContent || "",
    document.getElementById("routeCardLabel")?.textContent || "",
    document.getElementById("desktopRouteStatus")?.textContent || "",
    document.getElementById("routeWatchSetupHint")?.textContent || ""
  ].map((value) => String(value || "").trim()).filter(Boolean).join(" ");
  const originDestinationLineText = String(document.getElementById("mobileDestinationCommandMeta")?.textContent || "").trim() || relationLineText;
  const originDestinationLineVisible = Boolean(
    originDestinationLineText
    && (originDestinationLineText.includes("→") || (/From:\s*[^·.]+/i.test(originDestinationLineText) && /To:\s*[^·.]+/i.test(originDestinationLineText)))
  );
  const destinationCoords = normalizeCoordinatePair(selected?.lat ?? preview?.destination?.lat, selected?.lng ?? preview?.destination?.lng);
  const originCoords = normalizeCoordinatePair(preview?.source?.lat, preview?.source?.lng);
  const originMatchesDestination = Boolean(
    preview?.sameSavedPlaceRouteGuardActive
    || (originCoords && destinationCoords && gridlyRouteOriginNearlyMatchesDestination(originCoords, destinationCoords))
    || (selectedDestinationIsSavedPlace && getGridlySavedPlaceTypeFromDestination(selected) && String(preview?.source?.source || "").toLowerCase() === getGridlySavedPlaceTypeFromDestination(selected))
  );
  const sameSavedPlaceRouteGuardActive = Boolean(preview?.sameSavedPlaceRouteGuardActive || (originMatchesDestination && /already at|choose a different destination/i.test(surfaceText)));
  const activeRouteDetected = Boolean(selected || preview?.active || ownership?.hasRoute);

  if (selectedDestinationIsSavedPlace && !originDestinationLineVisible && !sameSavedPlaceRouteGuardActive) findings.push("Saved-place route card does not show a clear origin → destination line.");
  if (originMatchesDestination && !sameSavedPlaceRouteGuardActive) findings.push("Origin and destination match, but the same-place guard is not active.");
  if (sameSavedPlaceRouteGuardActive && !/already at|choose a different destination/i.test(surfaceText)) findings.push("Same-place guard is active but the consumer message is not visible.");
  if (/osrm|polyline|schema|trust|directional|engine|fallback/i.test(surfaceText)) findings.push("Route card includes technical copy.");

  const routeCardConsumerFriendlyPass = Boolean((!selectedDestinationIsSavedPlace || originDestinationLineVisible || sameSavedPlaceRouteGuardActive) && !findings.length);
  return {
    available: true,
    version: "V257.6",
    activeRouteDetected,
    routeOriginLabel,
    routeDestinationLabel,
    originDestinationLineVisible,
    originDestinationLineText,
    selectedDestinationIsSavedPlace,
    originMatchesDestination,
    sameSavedPlaceRouteGuardActive,
    routeCardConsumerFriendlyPass,
    canProceedToPatch: true,
    findings
  };
}

window.gridlySavedPlaceRouteClarityAudit = function gridlySavedPlaceRouteClarityAudit() {
  return gridlyBuildSavedPlaceRouteClarityAudit();
};

function getGridlySavedDestinationOriginOwnershipType(destination = null) {
  const normalized = typeof normalizeGridlySearchResult === "function" ? normalizeGridlySearchResult(destination) : destination;
  if (!normalized) return "";
  const savedType = getGridlySavedPlaceTypeFromDestination(normalized);
  if (savedType) return savedType;
  if (normalized.provider === "saved_place" || normalized.raw?.savedPlace === true) return "saved_place";
  return String(normalized.type || normalized.provider || normalized.source || "destination").trim() || "destination";
}

function gridlyBuildSavedDestinationOriginOwnershipAudit() {
  const findings = [];
  const searchState = typeof ensureGridlySearchState === "function" ? ensureGridlySearchState() : null;
  const selected = typeof normalizeGridlySearchResult === "function"
    ? normalizeGridlySearchResult(searchState?.selectedDestination)
    : searchState?.selectedDestination;
  const preview = typeof getGridlyDestinationRoutePreviewState === "function"
    ? getGridlyDestinationRoutePreviewState()
    : (window.GridlyDestinationRoutePreview || {});
  const ownership = typeof resolveGridlyRouteOwnershipSurface === "function" ? resolveGridlyRouteOwnershipSurface() : {};
  const destinationRecord = preview?.destination || selected || null;
  const destinationSearchActive = Boolean(selected || (preview?.active && preview?.destination));
  const resolvedDestinationSearchOrigin = destinationSearchActive && typeof getGridlyDestinationRouteOrigin === "function"
    ? getGridlyDestinationRouteOrigin({ destination: destinationRecord })
    : null;
  const origin = preview?.source || resolvedDestinationSearchOrigin || null;
  const routeOriginSource = String(origin?.source || ownership?.originSource || "").trim();
  const routeOriginOwner = String(origin?.routeOriginOwner || "").trim();
  const routeOriginPipeline = String(origin?.routeOriginPipeline || "").trim();
  const routeOriginLabel = gridlyFriendlyPlaceLabel(origin?.label || ownership?.originLabel || "", "");
  const routeDestinationLabel = gridlyFriendlyPlaceLabel(
    destinationRecord?.label || destinationRecord?.title || destinationRecord?.displayName || selected?.label || ownership?.destinationLabel || "",
    ""
  );
  const routeOriginCoordinate = normalizeCoordinatePair(origin?.lat, origin?.lng);
  const routeDestinationCoordinate = normalizeCoordinatePair(destinationRecord?.lat, destinationRecord?.lng);
  const selectedDestinationType = getGridlySavedDestinationOriginOwnershipType(selected || preview?.destination);
  const routeInheritedFromRouteWatch = Boolean(origin?.routeWatchOrigin === true || routeOriginOwner === "route_watch" || routeOriginPipeline === "route_watch_start");
  const routeWatchOriginCandidate = getGridlySelectedRouteStartOriginCandidate?.() || null;
  const routeWatchOrigin = routeWatchOriginCandidate ? {
    source: routeWatchOriginCandidate.source || "",
    label: routeWatchOriginCandidate.label || "",
    coordinate: normalizeCoordinatePair(routeWatchOriginCandidate.lat, routeWatchOriginCandidate.lng)
  } : {
    source: activeRouteOriginSource || "",
    label: activeRouteOriginLabel || "",
    coordinate: null
  };
  const currentLocationCoordinate = getGridlyCurrentLocationRouteCoordinate();
  const currentLocationAvailable = Boolean(currentLocationCoordinate);
  const savedState = typeof getSavedPlacesState === "function" ? getSavedPlacesState() : {};
  const homeCoordinate = normalizeCoordinatePair(savedState?.home?.lat, savedState?.home?.lng);
  const workCoordinate = normalizeCoordinatePair(savedState?.work?.lat, savedState?.work?.lng);
  const mapCenter = typeof map?.getCenter === "function" ? map.getCenter() : null;
  const mapCenterCoordinate = normalizeCoordinatePair(mapCenter?.lat ?? defaultCenter?.[0], mapCenter?.lng ?? defaultCenter?.[1]);
  const displayedRouteSurfaceTexts = [
    document.getElementById("routeCardLabel")?.textContent || "",
    document.getElementById("mobileDestinationCommandMeta")?.textContent || "",
    document.getElementById("desktopRouteStatus")?.textContent || "",
    preview?.routeRelationLineText || ""
  ].map((value) => String(value || "").trim()).filter(Boolean);
  const displayedOriginDestinationLineText = displayedRouteSurfaceTexts.find((value) => value.includes("→") || /From:\s*[^·.]+/i.test(value)) || "";
  const renderedRouteStartCoordinate = getGridlyFirstRouteGeometryCoordinate(preview);
  const renderedRouteEndCoordinate = getGridlyLastRouteGeometryCoordinate(preview);
  const renderedRouteStartMatchesDisplayedOrigin = gridlyCoordinatesNearlyMatch(renderedRouteStartCoordinate, routeOriginCoordinate);
  const renderedRouteStartMatchesCurrentLocation = gridlyCoordinatesNearlyMatch(renderedRouteStartCoordinate, currentLocationCoordinate);
  const renderedRouteStartMatchesHome = gridlyCoordinatesNearlyMatch(renderedRouteStartCoordinate, homeCoordinate);
  const renderedRouteStartMatchesWork = gridlyCoordinatesNearlyMatch(renderedRouteStartCoordinate, workCoordinate);
  const destinationSearchUsesIndependentOrigin = Boolean(!destinationSearchActive || (routeOriginOwner ? routeOriginOwner === "destination_search" : !routeInheritedFromRouteWatch));
  const standardDestinationOriginSource = Boolean(
    !destinationSearchActive
    || routeOriginSource === "current_location"
    || ["home", "work", "map_center"].includes(routeOriginSource)
    || !routeOriginSource
  );
  const displayedHomeToWorkForDestinationSearch = Boolean(
    destinationSearchActive
    && selectedDestinationType === "work"
    && displayedRouteSurfaceTexts.some((value) => /\bHome\s*(?:→|->|to)\s*Work\b/i.test(value))
  );
  const v2574Audit = typeof gridlyRouteOriginAudit === "function" ? gridlyRouteOriginAudit() : null;
  const v2574OriginOwnershipIntact = v2574Audit ? Boolean(v2574Audit.version === "V257.4" && v2574Audit.protectedSystemsPass === true) : true;

  if (destinationSearchActive && routeInheritedFromRouteWatch) findings.push("Destination Search is inheriting Route Watch origin ownership.");
  if (destinationSearchActive && !standardDestinationOriginSource) findings.push("Destination Search origin is outside Current Location / V257.4 fallback chain.");
  if (destinationSearchActive && currentLocationAvailable && routeOriginSource && routeOriginSource !== "current_location") findings.push("Current Location is available, but Destination Search did not use it as the route origin.");
  if (displayedHomeToWorkForDestinationSearch) findings.push("Destination Search selected Work, but the displayed route line still says Home → Work.");
  if (destinationSearchActive && routeOriginCoordinate && renderedRouteStartCoordinate && !renderedRouteStartMatchesDisplayedOrigin) findings.push("Rendered route start does not match the displayed Destination Search origin coordinate.");
  if (!v2574OriginOwnershipIntact) findings.push("V257.4 route origin ownership audit did not report the protected state.");

  const originOwnershipCorrect = Boolean(
    destinationSearchUsesIndependentOrigin
    && standardDestinationOriginSource
    && (!currentLocationAvailable || routeOriginSource === "current_location" || !destinationSearchActive)
    && !displayedHomeToWorkForDestinationSearch
    && v2574OriginOwnershipIntact
  );
  const visualOwnershipCorrect = Boolean(
    originOwnershipCorrect
    && (!destinationSearchActive || !routeOriginCoordinate || !renderedRouteStartCoordinate || renderedRouteStartMatchesDisplayedOrigin)
  );
  const consumerFriendlyPass = Boolean(originOwnershipCorrect && visualOwnershipCorrect && !findings.some((finding) => /osrm|polyline|schema|trust|directional|engine/i.test(finding)));

  return {
    available: true,
    version: "V257.7A",
    destinationSearchActive,
    selectedDestinationType,
    routeOriginSource,
    routeOriginLabel,
    routeOriginCoordinate,
    routeDestinationLabel,
    routeDestinationCoordinate,
    routeInheritedFromRouteWatch,
    routeWatchOrigin,
    destinationSearchUsesIndependentOrigin,
    currentLocationAvailable,
    currentLocationCoordinate,
    homeCoordinate,
    workCoordinate,
    mapCenterCoordinate,
    displayedOriginDestinationLineText,
    renderedRouteStartCoordinate,
    renderedRouteEndCoordinate,
    renderedRouteStartMatchesDisplayedOrigin,
    renderedRouteStartMatchesCurrentLocation,
    renderedRouteStartMatchesHome,
    renderedRouteStartMatchesWork,
    originOwnershipCorrect,
    visualOwnershipCorrect,
    consumerFriendlyPass,
    findings
  };
}

window.gridlySavedDestinationOriginOwnershipAudit = function gridlySavedDestinationOriginOwnershipAudit() {
  return gridlyBuildSavedDestinationOriginOwnershipAudit();
};


function gridlyBuildDestinationCurrentLocationOriginAudit() {
  const findings = [];
  const searchState = typeof ensureGridlySearchState === "function" ? ensureGridlySearchState() : null;
  const selected = typeof normalizeGridlySearchResult === "function"
    ? normalizeGridlySearchResult(searchState?.selectedDestination)
    : searchState?.selectedDestination;
  const preview = typeof getGridlyDestinationRoutePreviewState === "function"
    ? getGridlyDestinationRoutePreviewState()
    : (window.GridlyDestinationRoutePreview || {});
  const destinationSearchActive = Boolean(selected || (preview?.active && preview?.destination));
  const destination = preview?.destination || selected || null;
  const origin = preview?.source || (destinationSearchActive && typeof getGridlyDestinationRouteOrigin === "function"
    ? getGridlyDestinationRouteOrigin({ destination })
    : null);
  const currentLocationCoordinate = getGridlyCurrentLocationRouteCoordinate() || gridlyDestinationCurrentLocationOriginState.coordinate || null;
  const currentLocationPermissionState = gridlyDestinationCurrentLocationOriginState.permissionState
    || gridlyCachedGeolocationPermissionStatus
    || (typeof gridlyGetLocationPermissionDiagnostic === "function" ? gridlyGetLocationPermissionDiagnostic() : "");
  const destinationSearchOriginSource = String(origin?.source || "").trim();
  const destinationSearchOriginLabel = formatGridlyRouteOriginLabel(origin?.label || "", destinationSearchOriginSource);
  const fallbackUsed = Boolean(origin?.fallbackUsed || preview?.autoLocationFallbackUsed || gridlyDestinationCurrentLocationOriginState.fallbackUsed || (destinationSearchActive && destinationSearchOriginSource && destinationSearchOriginSource !== "current_location"));
  const fallbackSource = fallbackUsed ? (destinationSearchOriginSource || gridlyDestinationCurrentLocationOriginState.fallbackSource || "") : "";
  const fallbackReason = fallbackUsed
    ? (preview?.autoLocationFallbackReason || gridlyDestinationCurrentLocationOriginState.fallbackReason || origin?.fallbackReason || gridlyDestinationCurrentLocationOriginState.failureReason || "current_location_unavailable")
    : "";
  const currentLocationAttemptedForDestinationSearch = Boolean(preview?.autoLocationAttempted || gridlyDestinationCurrentLocationOriginState.attemptedForDestinationSearch);
  const currentLocationSucceededForDestinationSearch = Boolean(preview?.autoLocationSucceeded || gridlyDestinationCurrentLocationOriginState.succeededForDestinationSearch || destinationSearchOriginSource === "current_location");
  const currentLocationFailureReason = currentLocationSucceededForDestinationSearch ? "" : (preview?.autoLocationFallbackReason || gridlyDestinationCurrentLocationOriginState.failureReason || "");
  const canRetryCurrentLocation = Boolean(
    typeof navigator !== "undefined"
    && typeof navigator.geolocation !== "undefined"
    && !["denied", "permission_denied", "navigator_unavailable", "geolocation_unavailable"].includes(String(currentLocationPermissionState || currentLocationFailureReason || "").toLowerCase())
  );

  if (destinationSearchActive && currentLocationSucceededForDestinationSearch && destinationSearchOriginSource !== "current_location") {
    findings.push("Destination Search obtained Current Location but did not use it as the origin.");
  }
  if (destinationSearchActive && currentLocationCoordinate && destinationSearchOriginSource && destinationSearchOriginSource !== "current_location") {
    findings.push("A Current Location coordinate is available, but Destination Search is using fallback origin.");
  }
  if (destinationSearchActive && fallbackUsed && !fallbackReason) findings.push("Fallback origin is in use without a visible fallback reason.");
  if (destinationSearchActive && !currentLocationAttemptedForDestinationSearch && !currentLocationCoordinate && canRetryCurrentLocation) {
    findings.push("Destination Search has not attempted Current Location before fallback.");
  }

  const consumerFriendlyPass = Boolean(
    !findings.length
    && (!destinationSearchActive || destinationSearchOriginSource === "current_location" || (fallbackUsed && fallbackReason))
  );

  return {
    available: true,
    version: "V257.8",
    destinationSearchActive,
    currentLocationPermissionState: String(currentLocationPermissionState || ""),
    currentLocationAttemptedForDestinationSearch,
    currentLocationSucceededForDestinationSearch,
    currentLocationFailureReason: String(currentLocationFailureReason || ""),
    currentLocationCoordinate: currentLocationCoordinate ? { ...currentLocationCoordinate } : null,
    destinationSearchOriginSource,
    destinationSearchOriginLabel,
    fallbackUsed,
    fallbackSource,
    fallbackReason: String(fallbackReason || ""),
    canRetryCurrentLocation,
    consumerFriendlyPass,
    findings
  };
}

window.gridlyDestinationCurrentLocationOriginAudit = function gridlyDestinationCurrentLocationOriginAudit() {
  return gridlyBuildDestinationCurrentLocationOriginAudit();
};

function gridlyManualLocationButtonStillAvailable() {
  if (typeof document === "undefined") return false;
  return Boolean(
    document.querySelector("[data-v2-control='use-location']")
    || document.getElementById("mobileUseLocationBtn")
    || document.getElementById("manageSourceLocationBtn")
    || document.querySelector("[data-source='location']")
  );
}

function gridlyBuildAppLocationReadinessAudit() {
  const findings = [];
  const currentLocationCoordinate = getGridlyCurrentLocationRouteCoordinate()
    || gridlyDestinationCurrentLocationOriginState.coordinate
    || null;
  const permissionState = gridlyDestinationCurrentLocationOriginState.permissionState
    || gridlyCachedGeolocationPermissionStatus
    || (typeof gridlyGetLocationPermissionDiagnostic === "function" ? gridlyGetLocationPermissionDiagnostic() : "");
  const manualLocationButtonStillAvailable = gridlyManualLocationButtonStillAvailable();
  const destinationOrigin = typeof getGridlyDestinationRouteOrigin === "function"
    ? getGridlyDestinationRouteOrigin({ destination: null, allowSameDestination: true })
    : null;
  const destinationSearchCanUseCurrentLocation = Boolean(
    currentLocationCoordinate
    && (!destinationOrigin || String(destinationOrigin.source || "") === "current_location")
  );
  const awarenessAnchor = typeof getGridlyAwarenessAnchor === "function"
    ? getGridlyAwarenessAnchor({ preferUserLocation: true })
    : null;
  const reportNearMeCanUseCurrentLocation = Boolean(
    currentLocationCoordinate
    && (awarenessAnchor?.source === "user_location" || getValidGridlyUserLocationCoordinates(userLocation))
  );
  const fallbackStillAvailable = Boolean(
    typeof getGridlyDestinationRouteOrigin === "function"
    && (normalizeCoordinatePair(defaultCenter?.[0], defaultCenter?.[1]) || typeof map?.getCenter === "function")
  );

  if (!manualLocationButtonStillAvailable) findings.push("Manual location control is not detectable.");
  if (gridlyAppLocationReadinessState.startupLocationAttempted && gridlyAppLocationReadinessState.startupLocationSucceeded && !currentLocationCoordinate) {
    findings.push("Startup location refresh reported success, but no Current Location coordinate is available.");
  }
  if (currentLocationCoordinate && !destinationSearchCanUseCurrentLocation) {
    findings.push("Current Location coordinate is available, but Destination Search origin resolution does not prefer it.");
  }
  if (currentLocationCoordinate && !reportNearMeCanUseCurrentLocation) {
    findings.push("Current Location coordinate is available, but Report Near Me awareness cannot read it.");
  }
  if (!fallbackStillAvailable) findings.push("Fallback origin behavior is not detectable.");
  if (!gridlyAppLocationReadinessState.startupLocationAttempted) findings.push("Startup Current Location refresh has not been attempted yet.");

  const consumerFriendlyPass = Boolean(
    !findings.length
    && manualLocationButtonStillAvailable
    && fallbackStillAvailable
    && (
      currentLocationCoordinate
        ? (destinationSearchCanUseCurrentLocation && reportNearMeCanUseCurrentLocation)
        : true
    )
  );

  return {
    available: true,
    version: GRIDLY_APP_LOCATION_READINESS_VERSION,
    permissionState: String(permissionState || ""),
    startupLocationAttempted: Boolean(gridlyAppLocationReadinessState.startupLocationAttempted),
    startupLocationSucceeded: Boolean(gridlyAppLocationReadinessState.startupLocationSucceeded),
    currentLocationAvailable: Boolean(currentLocationCoordinate),
    currentLocationCoordinate: currentLocationCoordinate ? { ...currentLocationCoordinate } : null,
    lastLocationRefreshReason: String(gridlyAppLocationReadinessState.lastLocationRefreshReason || ""),
    lastLocationFailureReason: String(gridlyAppLocationReadinessState.lastLocationFailureReason || gridlyDestinationCurrentLocationOriginState.failureReason || ""),
    manualLocationButtonStillAvailable,
    destinationSearchCanUseCurrentLocation,
    reportNearMeCanUseCurrentLocation,
    fallbackStillAvailable,
    consumerFriendlyPass,
    findings
  };
}

window.gridlyAppLocationReadinessAudit = function gridlyAppLocationReadinessAudit() {
  return gridlyBuildAppLocationReadinessAudit();
};
if (typeof exposeGridlyAuditHelper === "function") {
  exposeGridlyAuditHelper("gridlyAppLocationReadinessAudit", window.gridlyAppLocationReadinessAudit);
}

function gridlyBuildStartupLocationTimingAudit() {
  const findings = [];
  const now = Date.now();
  const currentLocationCoordinate = getGridlyCurrentLocationRouteCoordinate()
    || gridlyDestinationCurrentLocationOriginState.coordinate
    || null;
  const permissionState = gridlyDestinationCurrentLocationOriginState.permissionState
    || gridlyCachedGeolocationPermissionStatus
    || (typeof gridlyGetLocationPermissionDiagnostic === "function" ? gridlyGetLocationPermissionDiagnostic() : "");
  const cachedLocationAvailable = Boolean(currentLocationCoordinate);
  const lastSuccessfulLocationAt = gridlyAppLocationReadinessState.lastSuccessfulLocationAt
    || gridlyDestinationCurrentLocationOriginState.lastSucceededAt
    || gridlyAppLocationReadinessState.lastStartupSucceededAt
    || null;
  const cachedLocationAgeMs = cachedLocationAvailable && lastSuccessfulLocationAt
    ? Math.max(0, now - Number(lastSuccessfulLocationAt))
    : 0;
  const startupTimeoutMs = Number(gridlyAppLocationReadinessState.startupTimeoutMs || GRIDLY_DESTINATION_AUTO_LOCATION_TIMEOUT_MS);
  const acquisitionDurationMs = Number(gridlyAppLocationReadinessState.acquisitionDurationMs || 0);
  const lastSuccessfulAcquisitionDurationMs = Number(gridlyAppLocationReadinessState.lastSuccessfulAcquisitionDurationMs || 0);
  const maximumAge = Number(gridlyAppLocationReadinessState.maximumAge ?? GRIDLY_DESTINATION_AUTO_LOCATION_GEO_OPTIONS.maximumAge);

  if (!gridlyAppLocationReadinessState.startupLocationAttempted) findings.push("Startup location readiness has not attempted acquisition yet.");
  if (gridlyAppLocationReadinessState.enableHighAccuracy) findings.push("Startup location acquisition requests high accuracy.");
  if (maximumAge > 0) findings.push(`Browser geolocation may reuse a cached position up to ${maximumAge} ms old.`);
  if (!cachedLocationAvailable) findings.push("No app-level Current Location coordinate is cached right now.");
  if (gridlyAppLocationReadinessState.timedOut) findings.push(`Startup acquisition timed out after ${startupTimeoutMs} ms before a usable startup coordinate was stored.`);
  if (gridlyAppLocationReadinessState.timedOut && lastSuccessfulAcquisitionDurationMs > startupTimeoutMs) {
    findings.push(`A successful acquisition took ${lastSuccessfulAcquisitionDurationMs} ms, which is longer than the startup timeout.`);
  }
  if (String(gridlyAppLocationReadinessState.browserReportedErrorCode || "") === "3") findings.push("Browser reported geolocation TIMEOUT (code 3).");
  if (cachedLocationAvailable && cachedLocationAgeMs <= maximumAge) findings.push("Current cached location is within the configured browser maximumAge window.");

  return {
    available: true,
    version: GRIDLY_STARTUP_LOCATION_TIMING_AUDIT_VERSION,
    permissionState: String(permissionState || ""),
    startupAttempted: Boolean(gridlyAppLocationReadinessState.startupLocationAttempted),
    startupSucceeded: Boolean(gridlyAppLocationReadinessState.startupLocationSucceeded),
    startupAutoGeolocationDeferred: Boolean(gridlyAppLocationReadinessState.startupAutoGeolocationDeferred),
    locationReadinessBlockedStartup: !gridlyAppLocationReadinessState.startupAutoGeolocationDeferred && Boolean(gridlyAppLocationReadinessState.locationRequestStartedAt || gridlyAppLocationReadinessState.timedOut),
    destinationAutoLocationRequestedOnStartup: Boolean(gridlyGeoAuditState.startupAutoRequestDetected),
    geolocationRequestedWithoutGestureSuspected: Boolean(gridlyGeoAuditState.startupAutoRequestDetected && !gridlyAppLocationReadinessState.startupAutoGeolocationDeferred),
    startupTimeoutMs,
    locationRequestStartedAt: formatGridlyStartupLocationTimingAuditTimestamp(gridlyAppLocationReadinessState.locationRequestStartedAt),
    locationRequestEndedAt: formatGridlyStartupLocationTimingAuditTimestamp(gridlyAppLocationReadinessState.locationRequestEndedAt),
    acquisitionDurationMs,
    timedOut: Boolean(gridlyAppLocationReadinessState.timedOut),
    enableHighAccuracy: Boolean(gridlyAppLocationReadinessState.enableHighAccuracy),
    maximumAge,
    cachedLocationAvailable,
    cachedLocationAgeMs,
    lastSuccessfulLocationAt: formatGridlyStartupLocationTimingAuditTimestamp(lastSuccessfulLocationAt),
    lastSuccessfulAcquisitionDurationMs,
    browserReportedErrorCode: String(gridlyAppLocationReadinessState.browserReportedErrorCode || ""),
    browserReportedErrorMessage: String(gridlyAppLocationReadinessState.browserReportedErrorMessage || ""),
    findings
  };
}

window.gridlyStartupLocationTimingAudit = function gridlyStartupLocationTimingAudit() {
  return gridlyBuildStartupLocationTimingAudit();
};
if (typeof exposeGridlyAuditHelper === "function") {
  exposeGridlyAuditHelper("gridlyStartupLocationTimingAudit", window.gridlyStartupLocationTimingAudit);
}

function gridlyBuildStartupLoadDelayAudit() {
  const timingAudit = gridlyBuildStartupLocationTimingAudit();
  const startupAutoGeolocationDeferred = Boolean(gridlyAppLocationReadinessState.startupAutoGeolocationDeferred || gridlyGeoAuditState.startupAutoGeolocationDeferred);
  const destinationAutoLocationRequestedOnStartup = startupAutoGeolocationDeferred ? false : Boolean(gridlyGeoAuditState.startupAutoRequestDetected);
  const geolocationRequestedWithoutGestureSuspected = Boolean(destinationAutoLocationRequestedOnStartup && !startupAutoGeolocationDeferred);
  const locationReadinessBlockedStartup = startupAutoGeolocationDeferred
    ? false
    : Boolean(timingAudit.locationRequestStartedAt || timingAudit.timedOut || geolocationRequestedWithoutGestureSuspected);
  const likelyBlockingSystem = locationReadinessBlockedStartup && geolocationRequestedWithoutGestureSuspected
    ? "location_readiness_auto_geolocation"
    : "none_detected";

  return {
    available: true,
    version: `${GRIDLY_STARTUP_LOCATION_TIMING_AUDIT_VERSION}-startup-load-delay`,
    startupAutoGeolocationDeferred,
    locationReadinessBlockedStartup,
    destinationAutoLocationRequestedOnStartup,
    geolocationRequestedWithoutGestureSuspected,
    likelyBlockingSystem,
    startupLocationTiming: timingAudit
  };
}

window.gridlyStartupLoadDelayAudit = function gridlyStartupLoadDelayAudit() {
  return gridlyBuildStartupLoadDelayAudit();
};
if (typeof exposeGridlyAuditHelper === "function") {
  exposeGridlyAuditHelper("gridlyStartupLoadDelayAudit", window.gridlyStartupLoadDelayAudit);
}

function gridlyBuildDestinationLocationRecoveryAudit() {
  const findings = [];
  const context = typeof getGridlyDestinationLocationRecoveryContext === "function"
    ? getGridlyDestinationLocationRecoveryContext()
    : {};
  const currentLocationCoordinate = getGridlyCurrentLocationRouteCoordinate() || gridlyDestinationCurrentLocationOriginState.coordinate || null;
  const destinationSearchActive = Boolean(context.destinationSearchActive);
  const fallbackRouteActive = Boolean(context.fallbackRouteActive || gridlyDestinationLocationRecoveryState.fallbackRouteActive);
  const fallbackOriginSource = String(context.fallbackOriginSource || gridlyDestinationLocationRecoveryState.fallbackOriginSource || "");
  const destinationLabel = String(context.destinationLabel || gridlyDestinationLocationRecoveryState.destinationLabel || "");
  const finalOriginSource = String(context.origin?.source || gridlyDestinationLocationRecoveryState.finalOriginSource || "");
  const currentLocationArrivedAfterFallback = Boolean(
    gridlyDestinationLocationRecoveryState.currentLocationArrivedAfterFallback
    || (destinationSearchActive && fallbackRouteActive && currentLocationCoordinate)
  );
  const autoRefreshTriggered = Boolean(gridlyDestinationLocationRecoveryState.autoRefreshTriggered);
  const routeRebuiltFromCurrentLocation = Boolean(
    gridlyDestinationLocationRecoveryState.routeRebuiltFromCurrentLocation
    || (currentLocationArrivedAfterFallback && finalOriginSource === "current_location")
  );

  if (destinationSearchActive && fallbackRouteActive && currentLocationCoordinate && !autoRefreshTriggered) {
    findings.push("Current Location is available after fallback, but automatic route refresh has not triggered.");
  }
  if (autoRefreshTriggered && !routeRebuiltFromCurrentLocation && !gridlyDestinationLocationRecoveryState.pendingRefresh) {
    findings.push("Automatic recovery triggered, but the route has not rebuilt from Current Location.");
  }
  if (routeRebuiltFromCurrentLocation && finalOriginSource !== "current_location") {
    findings.push("Recovery state says rebuilt, but final origin is not Current Location.");
  }
  if (destinationSearchActive && !destinationLabel) findings.push("Destination Search is active without a preserved destination label.");

  const consumerFriendlyPass = Boolean(
    !findings.length
    && (!currentLocationArrivedAfterFallback || (autoRefreshTriggered && (routeRebuiltFromCurrentLocation || gridlyDestinationLocationRecoveryState.pendingRefresh)))
  );

  return {
    available: true,
    version: "V257.8A",
    destinationSearchActive,
    fallbackRouteActive,
    fallbackOriginSource,
    destinationLabel,
    currentLocationArrivedAfterFallback,
    autoRefreshTriggered,
    routeRebuiltFromCurrentLocation,
    finalOriginSource,
    consumerFriendlyPass,
    findings
  };
}

window.gridlyDestinationLocationRecoveryAudit = function gridlyDestinationLocationRecoveryAudit() {
  return gridlyBuildDestinationLocationRecoveryAudit();
};


