function setRoutePreviewState(rendered, reason, options = {}) {
  // Route preview is only considered successful when a real global preview layer has at least 2 points.
  routePreviewPolylinePointCount = Number.isFinite(Number(options.pointCount)) ? Number(options.pointCount) : 0;
  const hasUsableGlobalLayer = Boolean(window.__gridlyRoutePreviewLayer)
    && typeof window.__gridlyRoutePreviewLayer.getLatLngs === "function"
    && Array.isArray(window.__gridlyRoutePreviewLayer.getLatLngs())
    && window.__gridlyRoutePreviewLayer.getLatLngs().length >= 2;

  routePreviewLayerExists = hasUsableGlobalLayer;
  mapHasRoutePreviewLayer = hasUsableGlobalLayer
    && Boolean(map && savedRouteLayer && typeof map.hasLayer === "function" && map.hasLayer(savedRouteLayer));
  routePreviewRendered = hasUsableGlobalLayer;
  routePreviewReason = hasUsableGlobalLayer
    ? "Route created · Previewing route. Start Route Watch to monitor it."
    : String(reason || (Boolean(rendered) ? "Route preview reported but layer is unavailable." : "Route preview not rendered."));
  lastRoutePreviewError = routePreviewRendered ? null : routePreviewReason;
}

async function renderRoutePreviewLine(startCoordinates, destinationCoordinates) {
  routeRequestTriggered = false;
  osrmRequestStarted = false;
  osrmResponseReceived = false;
  routeRenderAttempted = false;
  routeRenderSucceeded = false;
  lastOsrmRequestUrl = null;
  lastOsrmResponseStatus = null;
  markRouteRenderAuditState({ rendered: false, source: "pending", pointCount: 0, osrmRouteSuccess: false, renderedAt: null });
  // Render from saved Home/Work (or other saved place) coordinates only after coordinate validation succeeds.
  if (!map) return false;
  const routeViewportBeforeRender = getGridlyRouteViewportSnapshot();

  try {
  const fallbackPoints = [
    [Number(startCoordinates?.lat), Number(startCoordinates?.lng)],
    [Number(destinationCoordinates?.lat), Number(destinationCoordinates?.lng)]
  ];
  const hasValidPoints = fallbackPoints.length >= 2 && fallbackPoints.every((point) => (
    Array.isArray(point)
    && point.length >= 2
    && Number.isFinite(point[0])
    && Number.isFinite(point[1])
  ));
  if (!hasValidPoints) return false;

  const requestKey = `${fallbackPoints[0][0].toFixed(6)},${fallbackPoints[0][1].toFixed(6)}->${fallbackPoints[1][0].toFixed(6)},${fallbackPoints[1][1].toFixed(6)}`;
  const nowMs = Date.now();
  if (routeRequestInFlight && requestKey === lastRouteRequestKey && (nowMs - lastRouteRequestAt) < 1500) {
    duplicateRouteRequestBlockedCount += 1;
    console.info("Gridly duplicate route request blocked", { requestKey, duplicateRouteRequestBlockedCount });
    return false;
  }
  routeRequestInFlight = true;
  lastRouteRequestKey = requestKey;
  lastRouteRequestAt = nowMs;

  if (window.__gridlyRoutePreviewLayer && typeof map.removeLayer === "function" && map.hasLayer(window.__gridlyRoutePreviewLayer)) {
    map.removeLayer(window.__gridlyRoutePreviewLayer);
  }
  if (routePreviewCorridorLayer && typeof map.removeLayer === "function" && map.hasLayer(routePreviewCorridorLayer)) {
    map.removeLayer(routePreviewCorridorLayer);
  }
  if (alternateRouteLayer && typeof map.removeLayer === "function" && map.hasLayer(alternateRouteLayer)) {
    map.removeLayer(alternateRouteLayer);
  }
  routePreviewCorridorLayer = null;
  alternateRouteLayer = null;
  alternateRouteVertexCount = 0;
  alternateRouteGeometrySource = "none";
  alternateRouteStatus = "not_needed";
  alternateRouteReason = "";
  alternateRouteAvailable = false;
  primaryRouteHazardCount = 0;
  alternateRouteHazardCount = 0;
  hazardsAvoidedCount = 0;
  routeComparisonStatus = "alternate_unavailable";
  routeComparisonSummary = "";
  activeRouteSource = "primary";

  let previewPoints = fallbackPoints;
  routeGeometrySource = "fallback";
  osrmRouteSuccess = false;
  monitoredRouteEtaMinutes = null;
  monitoredRouteDelayMinutes = null;
  monitoredRouteDurationSeconds = null;
  monitoredRouteDistanceMiles = null;

  try {
    const startLat = Number(startCoordinates?.lat);
    const startLng = Number(startCoordinates?.lng);
    const destinationLat = Number(destinationCoordinates?.lat);
    const destinationLng = Number(destinationCoordinates?.lng);
    const osrmUrl = `${OSRM_ROUTE_API}/${startLng},${startLat};${destinationLng},${destinationLat}?overview=full&geometries=geojson&alternatives=false&steps=false`;
    lastOsrmRequestUrl = osrmUrl;
    routeRequestTriggered = true;
    lastRouteRequest = {
      engine: "osrm",
      url: osrmUrl,
      start: { lat: startLat, lng: startLng },
      destination: { lat: destinationLat, lng: destinationLng },
      requestedAt: new Date().toISOString()
    };
    console.info("Gridly route request payload", lastRouteRequest);
    const controller = typeof AbortController === "function" ? new AbortController() : null;
    osrmRequestStarted = true;
    console.info("Gridly OSRM request start", { url: osrmUrl });
    const timeoutId = controller ? setTimeout(() => controller.abort(), 7000) : null;
    const response = await fetch(osrmUrl, {
      method: "GET",
      signal: controller?.signal
    });
    lastOsrmResponseStatus = Number(response?.status || 0) || null;
    if (timeoutId) clearTimeout(timeoutId);
    if (!response.ok) {
      throw new Error(`OSRM response failed (${response.status})`);
    }
    const payload = await response.json();
    osrmResponseReceived = true;
    console.info("Gridly OSRM response received", { hasRoutes: Array.isArray(payload?.routes), routeCount: Array.isArray(payload?.routes) ? payload.routes.length : 0 });
    const primaryRoute = payload?.routes?.[0] || null;
    const routeCoordinates = primaryRoute?.geometry?.coordinates;
    if (!Array.isArray(routeCoordinates) || routeCoordinates.length < 2) {
      throw new Error("OSRM route geometry was invalid.");
    }
    const convertedPoints = routeCoordinates
      .map((point) => (Array.isArray(point) ? [Number(point[1]), Number(point[0])] : null))
      .filter((point) => Array.isArray(point) && Number.isFinite(point[0]) && Number.isFinite(point[1]));
    if (convertedPoints.length < 2) {
      throw new Error("OSRM route geometry could not be converted.");
    }
    previewPoints = convertedPoints;
    lastRouteGeometryPointCount = convertedPoints.length;
    lastRouteError = null;
    console.info("Gridly route geometry point count", { pointCount: convertedPoints.length, source: "osrm" });
    routeGeometrySource = "osrm";
    osrmRouteSuccess = true;
    markRouteRenderAuditState({
      rendered: false,
      source: "osrm",
      pointCount: convertedPoints.length,
      osrmRouteSuccess: true,
      renderedAt: null
    });
    const osrmDistanceMeters = Number(primaryRoute?.distance);
    if (Number.isFinite(osrmDistanceMeters) && osrmDistanceMeters > 0) {
      monitoredRouteDistanceMiles = Number((osrmDistanceMeters / 1609.344).toFixed(2));
    }
    const osrmDurationSeconds = Number(primaryRoute?.duration);
    if (Number.isFinite(osrmDurationSeconds) && osrmDurationSeconds > 0) {
      monitoredRouteDurationSeconds = Math.round(osrmDurationSeconds);
      monitoredRouteEtaMinutes = Math.max(1, Math.round(osrmDurationSeconds / 60));
    }
  } catch (error) {
    // A straight line is not a route. Preserve the selected destination and
    // report provider failure instead of presenting interpolation as a route.
    routeGeometrySource = "unavailable";
    osrmRouteSuccess = false;
    lastRouteError = String(error?.message || error || "OSRM route failed");
    lastRouteGeometryPointCount = 0;
    monitoredRouteDistanceMiles = null;
    monitoredRouteDurationSeconds = null;
    monitoredRouteEtaMinutes = null;
    console.info("Gridly route geometry unavailable", { pointCount: 0, source: "unavailable" });
    markRouteRenderAuditState({
      rendered: false,
      source: "unavailable",
      pointCount: 0,
      osrmRouteSuccess: false,
      renderedAt: null
    });
    captureRouteAttempt({ osrmCallSucceeded: false, finalFailureReason: lastRouteError });
    return false;
  }

  const corridorUnderlay = L.polyline(previewPoints, gridlyGetVisualSignatureRouteStyle("halo"));

  const corridorBase = L.polyline(previewPoints, gridlyGetVisualSignatureRouteStyle("shoulder"));

  const routePreviewLayer = L.polyline(previewPoints, gridlyGetVisualSignatureRouteStyle("core"));

  const routeStartEndpoint = gridlyCreateRouteEndpointMarker(previewPoints[0], "origin");
  const routeDestinationEndpoint = gridlyCreateRouteEndpointMarker(previewPoints[previewPoints.length - 1], "destination");
  const routeSignatureLayers = [corridorUnderlay, corridorBase, routePreviewLayer, routeStartEndpoint, routeDestinationEndpoint].filter(Boolean);

  routeRenderAttempted = true;
  routePreviewCorridorLayer = L.layerGroup(routeSignatureLayers).addTo(map);
  console.info("Gridly route layer render result", {
    routeLayerExists: Boolean(routePreviewLayer),
    routeLayerOnMap: Boolean(map && routePreviewLayer && map.hasLayer(routePreviewLayer)),
    routePaneZIndex: map?.getPane?.("routePane")?.style?.zIndex || null
  });
  window.__gridlyRoutePreviewLayer = routePreviewLayer;

  const rerouteFoundation = getRerouteFoundation(getRouteHazardAssessment());
  if (rerouteFoundation.rerouteRecommended) {
    alternateRouteStatus = "unavailable";
    alternateRouteReason = "Alternate route check recommended.";
    try {
      const alternatePoints = await fetchAlternateRouteCoordinates(
        [Number(startCoordinates?.lat), Number(startCoordinates?.lng)],
        [Number(destinationCoordinates?.lat), Number(destinationCoordinates?.lng)],
        previewPoints
      );
      if (Array.isArray(alternatePoints) && alternatePoints.length >= 2) {
        alternateRouteLayer = L.polyline(alternatePoints, {
          ...gridlyGetVisualSignatureRouteStyle("alternate"),
          weight: 5,
          opacity: 0.72
        }).addTo(map);
        alternateRouteVertexCount = alternatePoints.length;
        alternateRouteGeometrySource = "osrm_alternative";
        alternateRouteStatus = "available";
        alternateRouteReason = "Alternate route available.";
        alternateRouteAvailable = true;
      }
    } catch (error) {
      alternateRouteStatus = "unavailable";
      alternateRouteReason = "Alternate route check recommended.";
    }
  }
  updateRouteComparisonState(getRouteHazardAssessment());

  const actualLatLngs = routePreviewLayer.getLatLngs();
  routePreviewPolylinePointCount = Array.isArray(actualLatLngs) ? actualLatLngs.length : 0;
  const hasUsablePreviewLayer = Boolean(window.__gridlyRoutePreviewLayer)
    && typeof window.__gridlyRoutePreviewLayer.getLatLngs === "function"
    && Array.isArray(window.__gridlyRoutePreviewLayer.getLatLngs())
    && window.__gridlyRoutePreviewLayer.getLatLngs().length >= 2;
  routePreviewRendered = hasUsablePreviewLayer;
  routePreviewLayerExists = hasUsablePreviewLayer;
  mapHasRoutePreviewLayer = hasUsablePreviewLayer && Boolean(map && typeof map.hasLayer === "function" && map.hasLayer(routePreviewLayer));
  if (!routePreviewRendered) {
    markRouteRenderAuditState({
      rendered: false,
      source: routeGeometrySource || "fallback",
      pointCount: routePreviewPolylinePointCount,
      osrmRouteSuccess: Boolean(osrmRouteSuccess)
    });
    console.info("Gridly route render failure", { routePreviewRendered, pointCount: routePreviewPolylinePointCount });
    return false;
  }
  routeRenderSucceeded = true;
  markRouteRenderAuditState({
    rendered: true,
    source: routeGeometrySource || "fallback",
    pointCount: routePreviewPolylinePointCount,
    osrmRouteSuccess: Boolean(osrmRouteSuccess),
    renderedAt: Date.now()
  });
  persistGridlyRouteMetrics({
    routePointCount: routePreviewPolylinePointCount,
    routeDistanceMiles: monitoredRouteDistanceMiles,
    routeDurationMinutes: Number.isFinite(Number(monitoredRouteDurationSeconds)) && Number(monitoredRouteDurationSeconds) > 0
      ? Math.max(1, Math.round(Number(monitoredRouteDurationSeconds) / 60))
      : null
  });
  recordGridlyActiveLocationLifecycleEvent("routePreviewRender:complete", {
    routeWatchActivated: Boolean(routeWatchActivated),
    routePreviewRendered: Boolean(routePreviewRendered),
    routePreviewLayerExists: Boolean(routePreviewLayerExists),
    pointCount: routePreviewPolylinePointCount,
    routeGeometrySource,
    activeRouteSource
  });
  console.info("Gridly route render success", { pointCount: routePreviewPolylinePointCount });
  if (typeof safeApplyRouteIntelligenceAfterRouteRender === "function") {
    safeApplyRouteIntelligenceAfterRouteRender("route_render_success");
  }
  try {
    const captureBaselineSample = () => {
      try {
        window.gridlyCaptureCommuteBaselineSample?.();
      } catch (error) {
        // Silent by design: baseline storage must never block route rendering.
      }
    };
    if (typeof queueMicrotask === "function") queueMicrotask(captureBaselineSample);
    else setTimeout(captureBaselineSample, 0);
  } catch (error) {
    // Silent by design: baseline storage must never block route rendering.
  }

  markGridlyRouteRenderedWithoutViewportTakeover(routeViewportBeforeRender);
  syncGridlyShowFullRouteAvailability?.();

  return true;
  } finally {
    routeRequestInFlight = false;
  }
}




function ensureAlternateRouteButton() {
  if (!els) return null;
  if (els.useAlternateRouteBtn && document.body.contains(els.useAlternateRouteBtn)) return els.useAlternateRouteBtn;

  const actionHost = els.routeWatchStartBtn?.parentElement;
  if (!actionHost) return null;

  const button = document.createElement("button");
  button.type = "button";
  button.id = "useAlternateRouteBtn";
  button.className = "secondary-btn compact-btn route-watch-alt-btn";
  button.textContent = "Use Alternate Route";
  button.hidden = true;
  button.setAttribute("aria-disabled", "true");
  button.title = "Alternate route unavailable";

  const startButton = els.routeWatchStartBtn;
  if (startButton?.nextSibling) actionHost.insertBefore(button, startButton.nextSibling);
  else actionHost.appendChild(button);

  button.addEventListener("click", (event) => {
    event.preventDefault();
    if (button.disabled) return;
    useAlternateRoute();
  });

  els.useAlternateRouteBtn = button;
  return button;
}

function getRouteRecommendationState(routeHazard) {
  const transitionActive = routeTransitionUntil > Date.now();
  if (transitionActive && activeRouteSource === "alternate") {
    routeUxState = "alternate_promoted_after_switch";
    routeRecommendationTone = "affirming";
    return {
      state: routeUxState,
      tone: routeRecommendationTone,
      message: lastRouteSwitchMessage || "Now monitoring alternate route."
    };
  }
  if (routeHazard?.level === "clear" && primaryRouteHazardCount === 0) {
    routeUxState = "primary_route_clear";
    routeRecommendationTone = "calm";
    return { state: routeUxState, tone: routeRecommendationTone, message: "Primary route is clear. Route Watch is actively monitoring for changes." };
  }
  if ((routeHazard?.level === "blocked" || routeHazard?.level === "heavy" || routeHazard?.level === "caution") && !alternateRouteAvailable) {
    routeUxState = "primary_hazard_no_alternate";
    routeRecommendationTone = "urgent";
    return { state: routeUxState, tone: routeRecommendationTone, message: "Delay risk detected on primary route. No safer alternate is available right now." };
  }
  if (routeComparisonStatus === "both_delayed") {
    routeUxState = "both_routes_active_delays";
    routeRecommendationTone = "balanced";
    return { state: routeUxState, tone: routeRecommendationTone, message: "Both primary and alternate routes have active delays. Keep monitoring live reports before departure." };
  }
  if (routeComparisonStatus === "alternate_safer") {
    routeUxState = "alternate_safer";
    routeRecommendationTone = "advisory";
    return { state: routeUxState, tone: routeRecommendationTone, message: "A safer alternate route is available now. Switching may reduce delay exposure." };
  }
  if (routeComparisonStatus === "alternate_available") {
    routeUxState = "alternate_not_better";
    routeRecommendationTone = "neutral";
    return { state: routeUxState, tone: routeRecommendationTone, message: "An alternate route is available, but the primary route is still the better option." };
  }
  routeUxState = "primary_clear";
  routeRecommendationTone = "calm";
  return { state: routeUxState, tone: routeRecommendationTone, message: "Primary route remains your recommended option." };
}

function updateAlternateRouteActionState() {
  const switchEl = els?.alternateRoute;
  const switchBtn = ensureAlternateRouteButton();
  const switchAvailable = Boolean(alternateRouteAvailable && alternateRouteLayer && window.__gridlyRoutePreviewLayer && routeWatchActivated);
  const monitoringAlternate = activeRouteSource === "alternate";

  if (switchEl) {
    switchEl.classList.toggle("disabled", !switchAvailable);
    switchEl.setAttribute("aria-disabled", switchAvailable ? "false" : "true");
    switchEl.title = monitoringAlternate ? "Monitoring Alternate" : (switchAvailable ? "Use Alternate Route" : "Alternate route unavailable");
  }

  if (switchBtn) {
    switchBtn.hidden = !routeWatchActivated;
    switchBtn.disabled = monitoringAlternate ? true : !switchAvailable;
    switchBtn.classList.toggle("disabled", !switchAvailable);
    switchBtn.setAttribute("aria-disabled", (switchAvailable && !monitoringAlternate) ? "false" : "true");
    switchBtn.title = monitoringAlternate ? "Monitoring Alternate" : (switchAvailable ? "Use Alternate Route" : "Alternate route unavailable");
    switchBtn.textContent = monitoringAlternate ? "Monitoring Alternate" : (switchAvailable ? "Use Alternate Route" : "Alternate Route Unavailable");
  }
}

async function useAlternateRoute() {
  if (!(alternateRouteAvailable && alternateRouteLayer && window.__gridlyRoutePreviewLayer && routeWatchActivated)) {
    setConfirmation("Alternate route is not available yet.", "error");
    updateAlternateRouteActionState();
    return false;
  }
  try {
    const alternateLatLngs = alternateRouteLayer.getLatLngs?.() || [];
    if (!Array.isArray(alternateLatLngs) || alternateLatLngs.length < 2) throw new Error("invalid alternate geometry");
    const promotedPoints = alternateLatLngs.map((point) => [Number(point.lat), Number(point.lng)]).filter((point) => Number.isFinite(point[0]) && Number.isFinite(point[1]));
    if (promotedPoints.length < 2) throw new Error("alternate geometry conversion failed");

    window.__gridlyRoutePreviewLayer.setLatLngs(promotedPoints);
    routePreviewPolylinePointCount = promotedPoints.length;
    routeGeometrySource = "alternate_promoted";
    activeRouteSource = "alternate";
    routeWatchActivated = true;
    routePreviewRendered = true;
    routePreviewLayerExists = true;
    mapHasRoutePreviewLayer = true;
    lastRouteSwitchAt = new Date().toISOString();
    routeSwitchCount += 1;
    lastRouteSwitchMessage = "Now monitoring alternate route.";
    routeTransitionUntil = Date.now() + 9000;

    let nextAlternate = null;
    const places = Array.isArray(getSavedPlaces?.()) ? getSavedPlaces() : [];
    const start = places.find((place) => place.id === (els?.routeWatchStartSelect?.value || ""));
    const destination = places.find((place) => place.id === (els?.routeWatchDestinationSelect?.value || ""));
    const startCoordinates = normalizeCoordinatePair(start?.lat, start?.lng);
    const destinationCoordinates = normalizeCoordinatePair(destination?.lat, destination?.lng);
    if (startCoordinates && destinationCoordinates) {
      nextAlternate = await fetchAlternateRouteCoordinates([startCoordinates.lat, startCoordinates.lng], [destinationCoordinates.lat, destinationCoordinates.lng], promotedPoints);
    }

    if (alternateRouteLayer && map?.hasLayer?.(alternateRouteLayer)) map.removeLayer(alternateRouteLayer);
    alternateRouteLayer = null;
    alternateRouteAvailable = false;
    alternateRouteStatus = "unavailable";
    alternateRouteReason = "Alternate route refresh in progress.";
    alternateRouteVertexCount = 0;
    alternateRouteGeometrySource = "none";

    if (Array.isArray(nextAlternate) && nextAlternate.length >= 2) {
      alternateRouteLayer = L.polyline(nextAlternate, { ...gridlyGetVisualSignatureRouteStyle("alternate"), weight: 5, opacity: 0.72 }).addTo(map);
      alternateRouteVertexCount = nextAlternate.length;
      alternateRouteGeometrySource = "osrm_alternative";
      alternateRouteStatus = "available";
      alternateRouteReason = "Alternate route available.";
      alternateRouteAvailable = true;
    } else {
      alternateRouteReason = "Alternate route unavailable after switching.";
    }

    updateRouteComparisonState(getRouteHazardAssessment());
    updateRouteIntelligence();
    updateRouteWatchPill();
    updateAlternateRouteActionState();
    setConfirmation("Now monitoring alternate route.", "success");
    return true;
  } catch (error) {
    setConfirmation("Could not switch routes right now. Keeping current monitored route.", "error");
    updateAlternateRouteActionState();
    return false;
  }
}


function gridlyFriendlyPlaceLabel(placeOrLabel = null, fallback = "Not selected") {
  if (placeOrLabel && typeof placeOrLabel === "object") {
    const id = String(placeOrLabel.id || placeOrLabel.type || "").toLowerCase();
    if (id === "home") return "Home";
    if (id === "work") return "Work";
    return String(placeOrLabel.label || placeOrLabel.name || fallback || "Not selected").trim() || fallback;
  }
  const text = String(placeOrLabel || "").trim();
  if (!text) return fallback;
  const normalized = text.toLowerCase();
  if (normalized === "home") return "Home";
  if (normalized === "work") return "Work";
  if (normalized === "current location") return "Current Location";
  if (normalized === "map center") return "Map Center";
  return text;
}

function resolveGridlyRouteOwnershipSurface() {
  const places = typeof getSavedPlaces === "function" ? getSavedPlaces() : [];
  const startId = els?.routeWatchStartSelect?.value || "";
  const destinationId = els?.routeWatchDestinationSelect?.value || "";
  const startPlace = places.find((place) => place.id === startId) || null;
  const destinationPlace = places.find((place) => place.id === destinationId) || null;
  const searchState = typeof ensureGridlySearchState === "function" ? ensureGridlySearchState() : null;
  const selectedDestination = typeof normalizeGridlySearchResult === "function"
    ? normalizeGridlySearchResult(searchState?.selectedDestination)
    : searchState?.selectedDestination;
  const destinationPreview = typeof getGridlyDestinationRoutePreviewState === "function"
    ? getGridlyDestinationRoutePreviewState()
    : (window.GridlyDestinationRoutePreview || {});
  const previewSource = destinationPreview?.source || null;
  const previewDestination = destinationPreview?.destination || selectedDestination || null;
  const destinationPreviewActive = Boolean(destinationPreview?.active || selectedDestination);
  const fallbackOrigin = destinationPreviewActive && typeof getGridlyDestinationRouteOrigin === "function"
    ? getGridlyDestinationRouteOrigin({ destination: previewDestination })
    : null;
  const routeWatchHasStarted = Boolean(routeWatchActivated || window.__gridlyRouteWatchActive);
  const hasRoute = Boolean(
    destinationPreviewActive
    || routePreviewRendered
    || routePreviewLayerExists
    || window.__gridlyRoutePreviewLayer
    || savedRouteLayer?.getLayers?.().length
    || activeDestinationPlace
    || window.__gridlySelectedRouteId
  );
  const destinationSearchOrigin = previewSource || fallbackOrigin || null;
  const originLabel = hasRoute
    ? destinationPreviewActive
      ? formatGridlyRouteOriginLabel(destinationSearchOrigin?.label || "Map Center", destinationSearchOrigin?.source || "map_center")
      : formatGridlyRouteOriginLabel(
          activeRouteOriginLabel || gridlyFriendlyPlaceLabel(startPlace, "Map Center"),
          activeRouteOriginSource || startPlace?.id || ""
        )
    : "Not selected";
  const destinationLabel = hasRoute
    ? gridlyFriendlyPlaceLabel(
        previewDestination?.label
          || previewDestination?.title
          || previewDestination?.displayName
          || (!destinationPreviewActive ? activeRouteDestinationLabel : "")
          || (!destinationPreviewActive ? activeDestinationPlace : null)
          || (!destinationPreviewActive ? destinationPlace : null),
        "Destination"
      )
    : "Not selected";
  const monitoringLabel = routeWatchHasStarted && !destinationPreviewActive ? "Monitoring Active" : "Preview Only";
  return {
    hasRoute,
    originLabel,
    destinationLabel,
    monitoringLabel,
    originSource: destinationPreviewActive ? (destinationSearchOrigin?.source || "map_center") : (activeRouteOriginSource || startPlace?.id || ""),
    fallbackUsed: Boolean((destinationSearchOrigin || (!destinationPreviewActive ? { fallbackUsed: false } : null))?.fallbackUsed),
    fallbackReason: String((destinationSearchOrigin || {})?.fallbackReason || ""),
    destinationPreviewActive,
    routeWatchHasStarted
  };
}

function updateGridlyRouteOwnershipSurface() {
  const ownership = resolveGridlyRouteOwnershipSurface();
  safeText("routeOwnershipOrigin", ownership.originLabel);
  safeText("routeOwnershipDestination", ownership.destinationLabel);
  safeText("routeOwnershipMonitoring", ownership.monitoringLabel);
  const desktopStatus = document.getElementById("desktopRouteStatus");
  if (desktopStatus && ownership.hasRoute) {
    desktopStatus.dataset.routeOwnership = `${ownership.originLabel} to ${ownership.destinationLabel} · ${ownership.monitoringLabel}`;
  }
  return ownership;
}

function gridlyBuildRouteButtonContextAudit() {
  const findings = [];
  const routePanel = document.getElementById("gridlyMobileRouteQuickPanel");
  const routeQuickPanelInjected = Boolean(routePanel);
  const routeQuickPanelVisible = Boolean(routePanel?.classList?.contains("visible"));
  const routeQuickStartSelect = document.getElementById("mobileRouteQuickStart");
  const routeQuickDestinationSelect = document.getElementById("mobileRouteQuickDestination");
  const routeQuickStartWatchButton = routePanel?.querySelector?.('[data-action="start-route-watch-quick"]') || null;
  const routeQuickViewRouteButton = routePanel?.querySelector?.('[data-action="view-route-quick"]') || null;
  const routeQuickShowFullRouteButton = document.getElementById("mobileShowFullRouteBtn") || routePanel?.querySelector?.('[data-action="show-full-route-quick"]') || null;
  const routeQuickClearButton = routePanel?.querySelector?.('[data-action="clear-route-quick"]') || null;
  const routeQuickStopButton = routePanel?.querySelector?.('[data-action="stop-route-watch-quick"]') || null;
  const routeDetailsPane = document.getElementById("gridlyDestinationImpactPane");
  const routeDetailsVisible = Boolean(routeDetailsPane && !routeDetailsPane.hidden && routeDetailsPane.getAttribute("aria-hidden") !== "true");
  const destinationPreview = typeof getGridlyDestinationRoutePreviewState === "function"
    ? getGridlyDestinationRoutePreviewState()
    : (window.GridlyDestinationRoutePreview || {});
  const ownership = typeof resolveGridlyRouteOwnershipSurface === "function" ? resolveGridlyRouteOwnershipSurface() : {};
  const routeGeometryAudit = typeof getGridlyActiveRouteCoordinatesForAudit === "function" ? getGridlyActiveRouteCoordinatesForAudit() : null;
  const savedRouteLayerCount = Number(savedRouteLayer?.getLayers?.().length || 0);
  const destinationPreviewLayerCount = Number(destinationRoutePreviewLayer?.getLayers?.().length || 0);
  const routeWatchMonitoring = Boolean(routeWatchActivated || window.__gridlyRouteWatchActive);
  const destinationRoutePreviewAvailable = Boolean(
    destinationPreview?.active
    || ["loading", "ready"].includes(String(destinationPreview?.status || ""))
    || destinationPreviewLayerCount > 0
    || (Array.isArray(destinationPreview?.geometry) && destinationPreview.geometry.length >= 2)
  );
  const routeWatchRouteAvailable = Boolean(
    routeWatchMonitoring
    || savedRouteLayerCount > 0
    || routePreviewRendered
    || routePreviewLayerExists
    || window.__gridlyRoutePreviewLayer
    || activeDestinationPlace
    || window.__gridlySelectedRouteId
  );
  const activeRouteExists = Boolean(
    ownership?.hasRoute
    || destinationRoutePreviewAvailable
    || routeWatchRouteAvailable
    || routeGeometryAudit?.activeRoutePresent
  );
  const activeRouteType = destinationRoutePreviewAvailable
    ? (routeWatchMonitoring ? "destination_route_preview_over_route_watch" : "destination_route_preview")
    : routeWatchMonitoring
      ? "route_watch_monitoring"
      : routeWatchRouteAvailable
        ? "route_watch_preview"
        : "";
  const routeWatchSetupAvailable = Boolean(
    document.getElementById("routeWatchStartBtn")
    || document.getElementById("setupCard")
    || document.getElementById("routeSetupModal")
    || (routeQuickStartSelect && routeQuickDestinationSelect && routeQuickStartWatchButton)
    || typeof openMobileRouteQuickPanel === "function"
    || typeof openRouteSetupModal === "function"
  );
  const activeRouteDetailsAvailable = Boolean(
    routeDetailsPane
    && document.getElementById("gridlyCurrentRouteLine")
    && document.getElementById("gridlyCurrentRouteMeta")
    && typeof openGridlyDestinationImpactPane === "function"
  );
  const routeButtonOpensCurrentRouteWhenActive = Boolean(destinationRoutePreviewAvailable && activeRouteDetailsAvailable && typeof openGridlyCurrentRouteDetailsFromRouteButton === "function");
  const routeButtonOpensSetupWhenNoRoute = Boolean(!activeRouteExists && typeof openGridlyContextAwareRouteButtonSurface === "function" && (routeWatchSetupAvailable || routeQuickPanelInjected));
  const routeWatchStillAvailable = Boolean(routeWatchSetupAvailable && (document.getElementById("gridlyDestinationImpactManageRouteBtn") || routeQuickStartWatchButton || typeof openMobileRouteQuickPanel === "function"));
  const clearRouteAvailable = Boolean(document.getElementById("gridlyDestinationImpactClearRouteBtn") || routeQuickClearButton || typeof window.gridlyClearRoute === "function" || typeof clearGridlyRoute === "function");
  const showFullRouteAvailable = Boolean(document.getElementById("gridlyDestinationImpactShowFullRouteBtn") || routeQuickShowFullRouteButton || routeQuickViewRouteButton || typeof fitGridlyFullRouteForUserAction === "function");
  const routeButtonOpensSetupSurface = Boolean(!destinationRoutePreviewAvailable && ((routeQuickPanelInjected && routeQuickStartSelect && routeQuickDestinationSelect && routeQuickStartWatchButton) || typeof openMobileRouteQuickPanel === "function"));
  const routeButtonIncludesDetailsActions = Boolean(routeQuickViewRouteButton || routeQuickClearButton || routeQuickStopButton || routeQuickShowFullRouteButton);
  const ownershipConflictDetected = Boolean(destinationRoutePreviewAvailable && !routeButtonOpensCurrentRouteWhenActive);

  findings.push(destinationRoutePreviewAvailable
    ? "Route button is context-aware for active destination route previews and opens Current Route Details before setup."
    : "No active destination route preview detected; Route button keeps the Route Watch setup path first.");
  findings.push("Route Watch setup remains available from the Current Route Details secondary manage action and the existing quick panel.");
  if (routeQuickPanelVisible) findings.push("Route Quick Panel is currently visible.");
  if (routeButtonIncludesDetailsActions) findings.push("Route Quick Panel still includes route utility actions for setup/manage flows.");
  if (!activeRouteDetailsAvailable) findings.push("Current Route Details pane is unavailable or missing route summary fields.");
  if (ownershipConflictDetected) findings.push("Ownership conflict: an active destination route exists but the Route button is not configured to show Current Route Details first.");

  const consumerFriendlyPass = Boolean(
    routeWatchStillAvailable
    && clearRouteAvailable
    && showFullRouteAvailable
    && (!destinationRoutePreviewAvailable || routeButtonOpensCurrentRouteWhenActive)
    && (!activeRouteExists || activeRouteDetailsAvailable)
  );
  return {
    available: true,
    version: "V262.1",
    activeRouteExists,
    activeRouteType,
    routeButtonOpensCurrentRouteWhenActive,
    routeButtonOpensSetupWhenNoRoute,
    currentRouteDetailsVisible: routeDetailsVisible,
    routeWatchStillAvailable,
    clearRouteAvailable,
    showFullRouteAvailable,
    consumerFriendlyPass,
    findings,
    routeButtonCurrentOwner: destinationRoutePreviewAvailable
      ? "Route button opens Current Route Details first for active destination routes, with Start Route Watch available directly when applicable."
      : "Route button opens the existing Route Watch setup surface when no active destination route is present.",
    routeButtonConsumerExpectation: activeRouteExists
      ? "With an active Current Location → destination route visible, Route opens current route details before setup controls."
      : "With no active route, Route opens setup so the user can choose start/destination and start Route Watch.",
    routeWatchSetupAvailable,
    destinationRoutePreviewAvailable,
    activeRouteDetailsAvailable,
    ownershipConflictDetected
  };
}

