window.gridlyRouteWatchNamingEntryPointAudit = gridlyRouteWatchNamingEntryPointAudit;

function gridlyGetAuditText(selector) {
  const node = document.querySelector(selector);
  return String(node?.textContent || "").replace(/\s+/g, " ").trim();
}

function gridlyBuildRouteWatchNamingEntryPointAudit() {
  const currentRouteWatchName = gridlyGetAuditText(".desktop-route-watch-strip .route-watch-heading-row .eyebrow")
    || gridlyGetAuditText("#setupCard .eyebrow")
    || gridlyGetAuditText("#routeWatchStartBtn")
    || "Route Watch";
  const currentEntryPointLabel = gridlyGetAuditText('[data-v2-sheet="route"] em')
    || gridlyGetAuditText("#mobileDockRouteBtn")
    || gridlyGetAuditText('[data-section="routes"]')
    || "Route";
  const routeWatchNameLower = currentRouteWatchName.toLowerCase();
  const entryPointLabelLower = currentEntryPointLabel.toLowerCase();
  const routeWordInName = /\broute\b/.test(routeWatchNameLower);
  const watchWordInName = /\bwatch\b|monitor/.test(routeWatchNameLower);
  const routeWordInEntryPoint = /\b(routes?|routing)\b/.test(entryPointLabelLower);
  const watchWordInEntryPoint = /\bwatch\b|monitor/.test(entryPointLabelLower);
  const namingSupportsMonitoring = watchWordInName;
  const namingSuggestsRouting = routeWordInName;
  const entryPointSupportsMonitoring = watchWordInEntryPoint;
  const entryPointSuggestsRouting = routeWordInEntryPoint;
  const routingExpectationScore = Math.min(100, (routeWordInName ? 35 : 0) + (routeWordInEntryPoint ? 40 : 0) + (/manage|choose|start/.test(entryPointLabelLower) ? 10 : 0) + (watchWordInEntryPoint ? -15 : 0));
  const monitoringExpectationScore = Math.min(100, (watchWordInName ? 45 : 0) + (watchWordInEntryPoint ? 35 : 0) + (/monitor/.test(routeWatchNameLower) ? 15 : 0) + (routeWordInEntryPoint && !watchWordInEntryPoint ? -20 : 0) + (routeWordInName ? 5 : 0));
  const ownershipAlignmentScore = Math.max(0, Math.min(100, 55 + (namingSupportsMonitoring ? 15 : 0) + (entryPointSupportsMonitoring ? 20 : 0) - (entryPointSuggestsRouting && !entryPointSupportsMonitoring ? 25 : 0) - (namingSuggestsRouting ? 10 : 0)));
  const consumerFriendlyPass = Boolean(
    monitoringExpectationScore >= 75
    && routingExpectationScore <= 35
    && ownershipAlignmentScore >= 80
    && namingSupportsMonitoring
    && entryPointSupportsMonitoring
    && !entryPointSuggestsRouting
  );
  const findings = [
    {
      question: "If a user sees Route Watch, do they think create a route or monitor a route?",
      answer: watchWordInName ? "Mostly monitor a route, but the word Route still carries some create/manage-route expectation." : "Create or manage a route is more likely than monitoring.",
      recommendation: "Keep Route Watch framed as a monitoring product and pair it with monitoring-specific support copy before future UI changes."
    },
    {
      question: "With Current Location → Walmart active, would Route Watch manage that route or monitor future trips?",
      answer: "A first-time tester is likely to expect Route Watch to manage or attach to the active route unless Current Route Details clearly owns the active route and Route Watch is described as monitoring.",
      recommendation: "Preserve Destination Search as the active current-route owner; treat Route Watch as a secondary monitoring path for saved or recurring trips."
    },
    {
      question: "Does the current entry point communicate monitoring or routing?",
      answer: entryPointSupportsMonitoring ? "The entry point includes monitoring language." : "The current entry point reads as routing because the primary dock/route entry says Route.",
      recommendation: "Future label/copy decisions should make the entry point promise watch/monitoring rather than route creation."
    },
    {
      question: "Does the current naming reinforce Know Before You Go or Navigation?",
      answer: "Route Watch partially reinforces Know Before You Go through Watch, but Route and Route/Routes entry points still lean toward navigation.",
      recommendation: "Use monitoring, readiness, delay, and before-you-go language around Route Watch in a future UI-specific version."
    },
    {
      question: "Would a first-time tester immediately understand Destination Search versus Route Watch?",
      answer: consumerFriendlyPass ? "Yes, the current labels are clear enough without explanation." : "No. The current naming is directionally correct, but the entry point and route-management copy leave too much overlap with Destination Search.",
      recommendation: "Do not mark consumer-friendly until Destination Search = Routing and Route Watch = Monitoring are understandable from labels alone."
    }
  ];

  return {
    available: true,
    version: "V262.4",
    auditOnly: true,
    currentRouteWatchName,
    currentEntryPointLabel,
    routingExpectationScore,
    monitoringExpectationScore,
    firstTimeTesterInterpretation: "A first-time tester would read Route Watch as a feature that watches a route, but the surrounding Route/Routes entry points and manage-route language make it easy to expect route creation or active-route management too.",
    likelyUserQuestion: "Do I use Route Watch to create or manage my Current Location → Walmart route, or is it only for monitoring saved trips before I leave?",
    currentMentalModel: "Route Watch is visible as a route-related surface that can feel like setup, saved places, current-route management, and monitoring at the same time.",
    recommendedMentalModel: "Destination Search routes me somewhere now; Route Watch monitors a saved or recurring trip so I know before I go.",
    namingSupportsMonitoring,
    namingSuggestsRouting,
    entryPointSupportsMonitoring,
    entryPointSuggestsRouting,
    ownershipAlignmentScore,
    consumerFriendlyPass,
    findings
  };
}

function gridlyRouteWatchNamingEntryPointAudit() {
  return gridlyBuildRouteWatchNamingEntryPointAudit();
}

function gridlyBuildRouteRemovalImpactInventory() {
  const capability = (name, owner, routeSurface, alternativePath, risk = "low", notes = "") => ({
    capability: name,
    owner,
    currentlyAccessibleFromRoute: true,
    routeSurface,
    alternativeAccessExists: Boolean(alternativePath),
    alternativeAccessPath: alternativePath,
    inaccessibleIfRouteRemoved: !alternativePath,
    risk,
    notes
  });

  const destinationSearchPath = "Destination Search → choose/search Home, Work, Favorite, or destination → destination route preview / Current Route Details";
  const routeDetailsPath = "Route Details / Destination Impact pane → current route summary and active-route actions";
  const settingsPlacesPath = "Settings → My Routes → Edit Home / Edit Work / Manage Saved Places";
  const routeWatchPath = "Route Watch owner surfaces: dashboard Start Route Watch, desktop Route Watch strip, Route Details → Start Route Watch, and Settings route/place access";

  const capabilities = [
    capability(
      "Create Route",
      "Destination Search",
      "Route button can open Route Quick Panel with Start/Destination selectors and View Route.",
      destinationSearchPath,
      "low",
      "Current product direction places one-off route creation with Destination Search; Route is a duplicate setup shortcut."
    ),
    capability(
      "Home routing",
      "Destination Search",
      "Route Quick Panel can select saved Home as a start or destination when saved.",
      "Destination Search → Home chip/result; Dashboard Daily Destination → Home; saved Home remains editable in Settings.",
      "low"
    ),
    capability(
      "Work routing",
      "Destination Search",
      "Route Quick Panel can select saved Work as a start or destination when saved.",
      "Destination Search → Work chip/result; Dashboard Daily Destination → Work; saved Work remains editable in Settings.",
      "low"
    ),
    capability(
      "Favorite routing",
      "Destination Search",
      "Route Quick Panel can select saved favorite destinations.",
      "Destination Search → Favorite/saved-place result; Dashboard Daily Destination → Favorite; Settings → Manage Saved Places.",
      "low"
    ),
    capability(
      "Destination routing",
      "Destination Search",
      "Route button can expose a route setup panel, but arbitrary searched destinations are owned by destination search.",
      destinationSearchPath,
      "none"
    ),
    capability(
      "Route Details",
      "Route Details",
      "When a destination route is active, the context-aware Route button opens Current Route Details first.",
      routeDetailsPath + "; destination command impact line opens the same details pane.",
      "low",
      "Removal mostly affects a shortcut because active-route details have their own pane and destination-card entry."
    ),
    capability(
      "Active Route management",
      "Route Details / Active Route Experience",
      "Route Quick Panel and active Route Details expose Show Full Route, Clear Route, and Stop Watch controls.",
      routeDetailsPath,
      "low"
    ),
    capability(
      "Route Watch",
      "Route Watch",
      "Route button can open the Route Quick Panel and start monitoring from selected start/destination values.",
      routeWatchPath,
      "medium",
      "Functional access remains duplicated, but removing the dock shortcut could reduce discoverability of monitoring until Settings/Route Details/Dashboard links are validated in a UI pass."
    ),
    capability(
      "Stop Route Watch",
      "Route Details / Route Watch",
      "Route Quick Panel includes Stop Route Watch when monitoring is active.",
      "Route Details → Stop Watch; desktop Route Watch strip → Stop Route Watch.",
      "low"
    ),
    capability(
      "Manage Places",
      "Settings",
      "Route Quick Panel includes a Manage Places link.",
      settingsPlacesPath,
      "low"
    ),
    capability(
      "Saved Places",
      "Settings / Destination Search",
      "Route Quick Panel consumes saved places as start/destination options.",
      "Settings → My Routes → Manage Saved Places; Destination Search exposes saved Home, Work, and Favorites as route destinations.",
      "low"
    ),
    capability(
      "Route setup",
      "Route Watch",
      "Route Quick Panel provides Start and Destination selectors plus View Route / Start Route Watch.",
      "Dashboard Start Route Watch; desktop Route Watch strip; Route Details → Start Route Watch; Settings place management for prerequisites.",
      "medium",
      "This is a duplicated setup surface, not a unique capability; risk is mainly that a familiar shortcut disappears."
    ),
    capability(
      "Route intelligence",
      "Active Route Experience / Route Watch",
      "Route surfaces show readiness, reports, recommendation, freshness, and monitoring state.",
      "Awareness Brief, Route Watch strip, destination route preview card, and Route Details context summary.",
      "low"
    ),
    capability(
      "Route awareness",
      "Active Route Experience / Route Details",
      "Route button can lead to details that explain current route context.",
      "Destination command impact line → Route Details; Awareness Brief and map surfaces expose route-relevant report context.",
      "low"
    ),
    capability(
      "Show Full Route",
      "Route Details / Active Route Experience",
      "Route Quick Panel includes Show Full Route.",
      "Route Details → Show Full Route; desktop Route Watch strip → Show Full Route.",
      "low"
    ),
    capability(
      "Clear Route",
      "Route Details / Active Route Experience",
      "Route Quick Panel includes Clear Route.",
      "Route Details → Clear Route; desktop Route Watch strip → Clear Route.",
      "low"
    )
  ];

  const uniqueCapabilities = capabilities.filter((item) => item.inaccessibleIfRouteRemoved);
  const duplicateCapabilities = capabilities.filter((item) => item.alternativeAccessExists);
  const inaccessibleAfterRemoval = capabilities.filter((item) => item.inaccessibleIfRouteRemoved);
  const lowRiskCapabilities = capabilities.filter((item) => item.risk === "none" || item.risk === "low");
  const mediumRiskCapabilities = capabilities.filter((item) => item.risk === "medium");
  const highRiskCapabilities = capabilities.filter((item) => item.risk === "high");
  const removalRiskScore = Math.min(100, (mediumRiskCapabilities.length * 8) + (highRiskCapabilities.length * 25) + (inaccessibleAfterRemoval.length * 35));
  const routeButtonOwnsUniqueCapability = uniqueCapabilities.length > 0;
  const consumerFriendlyPass = Boolean(capabilities.length >= 16 && !routeButtonOwnsUniqueCapability && inaccessibleAfterRemoval.length === 0);

  return {
    available: true,
    version: "V262.5",
    auditOnly: true,
    routeButtonOwnsUniqueCapability,
    totalCapabilitiesReviewed: capabilities.length,
    capabilities,
    uniqueCapabilities,
    duplicateCapabilities,
    inaccessibleAfterRemoval,
    lowRiskCapabilities,
    mediumRiskCapabilities,
    highRiskCapabilities,
    removalRiskScore,
    consumerFriendlyPass,
    findings: [
      "1. Capabilities that would become inaccessible if Route disappeared: none detected in this inventory; every reviewed Route-reachable capability has an alternate owner/path.",
      "2. Route does not own a unique user job in the current product direction; Destination Search owns current route creation, Route Details owns active-route management, Route Watch owns monitoring, and Settings owns saved-place management.",
      "3. Route is primarily duplicating access to capabilities owned elsewhere, especially current route details, route setup, saved-place selection, Route Watch monitoring, and active-route exit controls.",
      `4. Overall removal risk is low-to-medium discoverability risk, not functional loss risk; score ${removalRiskScore}/100 because Route Watch and route setup lose a prominent shortcut even though alternate paths remain.`
    ],
    recommendation: "No Unique Capability Ownership Detected"
  };
}

