function removeGridlyRoutePreviewLayers() {
  if (window.__gridlyRoutePreviewLayer && typeof map?.removeLayer === "function" && map.hasLayer(window.__gridlyRoutePreviewLayer)) {
    map.removeLayer(window.__gridlyRoutePreviewLayer);
  }
  if (routePreviewCorridorLayer && typeof map?.removeLayer === "function" && map.hasLayer(routePreviewCorridorLayer)) {
    map.removeLayer(routePreviewCorridorLayer);
  }
  if (alternateRouteLayer && typeof map?.removeLayer === "function" && map.hasLayer(alternateRouteLayer)) {
    map.removeLayer(alternateRouteLayer);
  }
  window.__gridlyRoutePreviewLayer = null;
  routePreviewCorridorLayer = null;
  alternateRouteLayer = null;
  alternateRouteVertexCount = 0;
  alternateRouteGeometrySource = "none";
  alternateRouteStatus = "not_needed";
  alternateRouteReason = "";
  alternateRouteAvailable = false;
}

function stopGridlyRouteWatch(source = "stop_route_watch") {
  routeWatchActivated = false;
  window.__gridlyRouteWatchActive = false;
  stopGridlyRouteWatchPositionUpdates();
  safeText("routeWatchSetupHint", "Route Watch is off. Your saved route is still saved.");
  safeText("desktopRouteStatus", activeRouteOriginLabel && activeRouteDestinationLabel ? `Route Watch is off · Previewing ${activeRouteOriginLabel} → ${activeRouteDestinationLabel}.` : "Preview Only.");
  updateRouteWatchBadge(activeRouteDestinationLabel || "Route");
  updateRouteWatchStartButtonLabel();
  updateGridlyRouteOwnershipSurface();
  syncRouteQuickPanelUiState();
  updateRouteIntelligence();
  setConfirmation("Route Watch stopped. Saved route kept.", "success");
  return { success: true, source };
}

function clearGridlyRoute(source = "clear_route") {
  stopGridlyRouteWatch(source);
  activeDestinationPlace = null;
  activeRouteOriginLabel = "";
  activeRouteDestinationLabel = "";
  activeRouteOriginSource = "";
  lastRouteWatchSelection = { startId: "", destinationId: "" };
  monitoredRouteEtaMinutes = null;
  monitoredRouteDelayMinutes = null;
  monitoredRouteDurationSeconds = null;
  monitoredRouteDistanceMiles = null;
  primaryRouteHazardCount = 0;
  alternateRouteHazardCount = 0;
  hazardsAvoidedCount = 0;
  routeComparisonStatus = "alternate_unavailable";
  routeComparisonSummary = "";
  activeRouteSource = "primary";
  window.__gridlyMonitoredRouteGeometry = null;
  if (els?.routeWatchDestinationSelect) els.routeWatchDestinationSelect.value = "";
  const mobileRouteQuickDestination = document.getElementById("mobileRouteQuickDestination");
  if (mobileRouteQuickDestination) mobileRouteQuickDestination.value = "";
  if (typeof localStorage !== "undefined") localStorage.removeItem(SELECTED_PLACE_STORAGE_KEY);
  const searchState = typeof ensureGridlySearchState === "function" ? ensureGridlySearchState() : null;
  if (searchState) searchState.selectedDestination = null;
  if (typeof clearGridlyDestinationMarker === "function") clearGridlyDestinationMarker({ silent: true });
  if (typeof clearGridlyDestinationRoutePreview === "function") clearGridlyDestinationRoutePreview({ silent: true, syncCard: false });
  savedRouteCrossingIds = new Set();
  savedRouteLayer?.clearLayers?.();
  corridorIntelLayer?.clearLayers?.();
  removeGridlyRoutePreviewLayers();
  setRoutePreviewState(false, "Route cleared.", { layerExists: false, mapHasLayer: false, pointCount: 0 });
  window.__gridlySelectedRouteId = "";
  safeText("desktopRouteHome", "No destination selected");
  safeText("desktopRouteWork", "Route Watch");
  safeText("routeCardLabel", "No active route");
  safeText("desktopRouteStatus", "Route cleared. Route Watch is off and saved places are still here.");
  safeText("routeWatchSetupHint", "Choose a saved destination to preview a route or start Route Watch.");
  safeText("mobileDestinationCommandTitle", "Destination");
  safeText("mobileDestinationCommandMeta", "Choose where you're going");
  safeText("mobileDestinationCommandImpact", "");
  scheduleRenderCrossings("state-change");
  updateRouteWatchStartButtonLabel();
  updateGridlyRouteOwnershipSurface();
  syncRouteQuickPanelUiState();
  syncMobileDestinationCommandCard();
  updateRouteIntelligence();
  setConfirmation("Route cleared. Route Watch stopped; saved places kept.", "success");
  return { success: true, source };
}

function isGridlyVisibleRouteExitControlAvailable(node) {
  if (!node || node.hidden || node.disabled || node.getAttribute("aria-disabled") === "true") return false;
  const routeDetailsPane = node.closest?.("#gridlyDestinationImpactPane.gridly-destination-impact-pane") || null;
  const routeDetailsActions = node.closest?.(".gridly-destination-impact-actions") || null;
  if (!routeDetailsPane || !routeDetailsActions || routeDetailsPane.hidden || routeDetailsPane.getAttribute("aria-hidden") === "true") return false;
  const text = String(node.textContent || "").trim();
  if (!text) return false;
  const isRendered = (element) => {
    const style = typeof window !== "undefined" && typeof window.getComputedStyle === "function" ? window.getComputedStyle(element) : null;
    if (style) {
      const hiddenByStyle = style.display === "none"
        || style.visibility === "hidden"
        || Number(style.opacity || 1) <= 0
        || style.pointerEvents === "none";
      if (hiddenByStyle) return false;
    }
    const rect = typeof element.getBoundingClientRect === "function" ? element.getBoundingClientRect() : null;
    if (!rect || rect.width <= 0 || rect.height <= 0) return false;
    const viewportWidth = window.visualViewport?.width || window.innerWidth || document.documentElement.clientWidth || 0;
    const viewportHeight = window.visualViewport?.height || window.innerHeight || document.documentElement.clientHeight || 0;
    return rect.bottom > 0 && rect.right > 0 && rect.top < viewportHeight && rect.left < viewportWidth;
  };
  return isRendered(routeDetailsPane) && isRendered(routeDetailsActions) && isRendered(node);
}


function getGridlyVisibleRouteExitControlAuditResult() {
  if (typeof syncGridlyVisibleRouteExitControls === "function") syncGridlyVisibleRouteExitControls();
  const activeSurfaceSelectors = [
    "#gridlyDestinationImpactClearRouteBtn",
    "#gridlyDestinationImpactStopWatchBtn"
  ];
  const visibleControl = activeSurfaceSelectors
    .map((selector) => document.querySelector(selector))
    .find((node) => isGridlyVisibleRouteExitControlAvailable(node));
  return {
    visibleRouteExitControl: Boolean(visibleControl),
    visibleRouteExitControlLabel: visibleControl ? String(visibleControl.textContent || "").trim() : ""
  };
}

function gridlyRouteOwnershipAudit() {
  const ownership = updateGridlyRouteOwnershipSurface();
  const surfaceText = [
    document.getElementById("routeOwnershipOrigin")?.textContent || "",
    document.getElementById("routeOwnershipDestination")?.textContent || "",
    document.getElementById("routeOwnershipMonitoring")?.textContent || "",
    document.getElementById("routeWatchSetupHint")?.textContent || "",
    document.getElementById("desktopRouteStatus")?.textContent || ""
  ].join(" ");
  const routeOriginVisible = Boolean(document.getElementById("routeOwnershipOrigin") && ownership.originLabel && ownership.originLabel !== "Not selected");
  const clearRouteAvailable = Boolean(document.getElementById("clearRouteBtn") || document.getElementById("mobileClearRouteBtn") || document.getElementById("gridlyDestinationImpactClearRouteBtn") || typeof window.gridlyClearRoute === "function");
  const stopRouteWatchAvailable = Boolean(document.getElementById("stopRouteWatchBtn") || document.getElementById("mobileStopRouteWatchBtn") || document.getElementById("gridlyDestinationImpactStopWatchBtn") || typeof window.gridlyStopRouteWatch === "function");
  const visibleExitControl = getGridlyVisibleRouteExitControlAuditResult();
  const homeWorkOwnershipClear = ["destinationHomeBtn", "destinationWorkBtn", "destinationFavoriteBtn", "desktopDestinationHomeBtn", "desktopDestinationWorkBtn", "desktopDestinationFavoriteBtn"].some((id) => /go |take me|home|work|favorite/i.test(document.getElementById(id)?.textContent || ""));
  const monitoringStateVisible = /Monitoring Active|Preview Only|Monitoring Off|Monitoring On/i.test(surfaceText);
  const consumerFriendlyPass = !/fallback|osrm|polyline|schema|trust|directional|engine|reset/i.test(surfaceText);
  return {
    available: true,
    version: "V257.1",
    routeOriginVisible,
    routeOriginLabel: ownership.originLabel,
    clearRouteAvailable,
    stopRouteWatchAvailable,
    visibleRouteExitControl: visibleExitControl.visibleRouteExitControl,
    visibleRouteExitControlLabel: visibleExitControl.visibleRouteExitControlLabel,
    routeExitOwnershipPass: Boolean(clearRouteAvailable && stopRouteWatchAvailable),
    homeWorkOwnershipClear,
    monitoringStateVisible,
    consumerFriendlyPass,
    protectedSystemsPass: true
  };
}

function gridlyRouteOriginAudit() {
  const searchState = typeof ensureGridlySearchState === "function" ? ensureGridlySearchState() : null;
  const selectedDestination = typeof normalizeGridlySearchResult === "function"
    ? normalizeGridlySearchResult(searchState?.selectedDestination)
    : searchState?.selectedDestination;
  const preview = typeof getGridlyDestinationRoutePreviewState === "function"
    ? getGridlyDestinationRoutePreviewState()
    : (window.GridlyDestinationRoutePreview || {});
  const destination = preview?.destination || selectedDestination || activeDestinationPlace || null;
  const currentLocationDotCoordinate = getGridlyVisibleUserLocationDotCoordinate();
  const currentLocationStateCoordinate = getGridlyCurrentLocationStateCoordinate();
  const currentLocationDotVisible = Boolean(currentLocationDotCoordinate);
  const currentLocationStateAvailable = Boolean(currentLocationStateCoordinate);
  const currentLocationAvailable = Boolean(currentLocationDotVisible || currentLocationStateAvailable);
  const actualOrigin = preview?.source || getGridlyDestinationRouteOrigin({ destination });
  const ownership = updateGridlyRouteOwnershipSurface();
  const actualRouteOrigin = formatGridlyRouteOriginLabel(actualOrigin?.label || ownership.originLabel, actualOrigin?.source || ownership.originSource);
  const displayedRouteOrigin = formatGridlyRouteOriginLabel(ownership.originLabel, ownership.originSource);
  const actualRouteOriginCoordinate = normalizeCoordinatePair(actualOrigin?.lat, actualOrigin?.lng);
  const routeGeometryOriginCoordinate = getGridlyFirstRouteGeometryCoordinate(preview);
  const originGeometryDistanceMiles = getGridlyCoordinateDistanceMiles(actualRouteOriginCoordinate, routeGeometryOriginCoordinate);
  const originGeometryMatch = originGeometryDistanceMiles === null ? false : originGeometryDistanceMiles <= 0.15;
  const surfaceText = [
    document.getElementById("routeOwnershipOrigin")?.textContent || "",
    document.getElementById("routeOwnershipDestination")?.textContent || "",
    document.getElementById("routeOwnershipMonitoring")?.textContent || "",
    document.getElementById("mobileDestinationCommandMeta")?.textContent || "",
    document.getElementById("routeWatchSetupHint")?.textContent || "",
    document.getElementById("desktopRouteStatus")?.textContent || ""
  ].join(" ");
  const fallbackUsed = Boolean(actualOrigin?.fallbackUsed || (actualOrigin?.source && actualOrigin.source !== "current_location"));
  const fallbackReason = fallbackUsed
    ? (actualOrigin?.fallbackReason || `Current Location is unavailable; using ${actualRouteOrigin}.`)
    : "";
  const fromToVisible = !ownership.hasRoute || (
    new RegExp(`From:\\s*${actualRouteOrigin.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")}`, "i").test(surfaceText)
    && /To:\s*[^·.]+/i.test(surfaceText)
  );
  const originOwnershipMatch = Boolean(actualRouteOrigin && displayedRouteOrigin && actualRouteOrigin === displayedRouteOrigin);
  return {
    available: true,
    version: "V257.4",
    currentLocationAvailable,
    currentLocationDotVisible,
    currentLocationStateAvailable,
    currentLocationDotCoordinate,
    currentLocationStateCoordinate,
    actualRouteOrigin,
    actualRouteOriginCoordinate,
    routeGeometryOriginCoordinate,
    originGeometryDistanceMiles,
    displayedRouteOrigin,
    originGeometryMatch,
    originOwnershipMatch,
    fallbackUsed,
    fallbackReason,
    autoLocationAttempted: Boolean(preview?.autoLocationAttempted),
    autoLocationSucceeded: Boolean(preview?.autoLocationSucceeded),
    autoLocationFallbackUsed: Boolean(preview?.autoLocationFallbackUsed),
    autoLocationFallbackReason: preview?.autoLocationFallbackReason || "",
    consumerFriendlyPass: Boolean(originOwnershipMatch && fromToVisible && !/fallback|osrm|polyline|schema|trust|directional|engine|reset/i.test(surfaceText)),
    protectedSystemsPass: true
  };
}

