  const buttonClass = v2 ? "gridly-v2-tile settings-pwa-install-button" : "primary-btn compact-btn settings-pwa-install-button";
  const buttonAttrs = v2 ? ' data-v2-action="settings-pwa-install"' : ' id="settingsPwaInstallBtn"';
