function getRouteEtaMetricsFromState({
  routeHazardLevel = "clear",
  fallbackExtraMinutes = 0
} = {}) {
  const etaMinutes = Number.isFinite(Number(monitoredRouteEtaMinutes))
    ? Number(monitoredRouteEtaMinutes)
    : null;
  const delayMinutes = Number.isFinite(Number(monitoredRouteDelayMinutes))
    ? Number(monitoredRouteDelayMinutes)
    : null;
  return {
    routeEtaValue: etaMinutes && etaMinutes > 0 ? `${etaMinutes} min` : "",
    routeDelayValue: delayMinutes && delayMinutes > 0 ? `+${delayMinutes} min` : ""
  };
}

function getRoutePressureBand(score = 0) {
  const normalized = Math.max(0, Math.min(100, Number(score) || 0));
  if (normalized < 20) return "Clear";
  if (normalized < 45) return "Moderate";
  if (normalized < 70) return "Heavy";
  return "Severe";
}

function computeRoutePressureModel({ routeHazard = null, routeRelevantHazards = [], freshnessTier = "Unknown" } = {}) {
  const relevant = Array.isArray(routeRelevantHazards) ? routeRelevantHazards : [];
  const activeRelevant = relevant.filter((incident) => String(incident?.status || "").toLowerCase() === "active");
  const highSeverityCount = activeRelevant.filter((incident) => String(incident?.severity || "").toLowerCase() === "high").length;
  const mediumSeverityCount = activeRelevant.filter((incident) => ["medium","moderate"].includes(String(incident?.severity || "").toLowerCase())).length;
  const densityScore = Math.min(28, activeRelevant.length * 7);
  const recentActivityScore = Math.min(18, activeRelevant.filter((incident) => Number(incident?.age_minutes) <= 20).length * 6);
  const blockageScore = Math.min(28, (Array.isArray(routeHazard?.nearbyReports) ? routeHazard.nearbyReports : []).filter((report) => report.lifecycleState === "active" && report.reportType === "blocked").length * 14);
  const delayAccumulationScore = Math.min(18, highSeverityCount * 6 + mediumSeverityCount * 3 + Math.max(0, Number(monitoredRouteDelayMinutes) || 0));
  const freshnessMultiplier = freshnessTier === "Fresh" ? 1 : freshnessTier === "Aging" ? 0.82 : 0.66;
  const raw = densityScore + recentActivityScore + blockageScore + delayAccumulationScore;
  const score = Math.round(Math.min(100, raw * freshnessMultiplier));
  return { score, band: getRoutePressureBand(score) };
}

function buildRouteRecommendationMessage({ routeIsMonitoring = false, pressureBand = "Clear", hazardsAvoided = 0, routeRelevantCount = 0, blockedNearRoute = 0, alternateAvailable = false } = {}) {
  const normalizedBand = String(pressureBand || "Clear").toLowerCase();
  if (!routeIsMonitoring) return "Checking active route conditions";
  if (alternateAvailable && hazardsAvoided > 0) return `Alternate route avoids ${hazardsAvoided} active hazard${hazardsAvoided === 1 ? "" : "s"}`;
  if (normalizedBand === "severe") return blockedNearRoute > 0 ? "Route heavily impacted by active incidents" : "Major corridor disruption detected";
  if (normalizedBand === "heavy") return routeRelevantCount > 2 ? "Multiple active hazards affecting route" : "Heavy congestion risk detected ahead";
  if (normalizedBand === "moderate") return blockedNearRoute > 0 ? "Monitor conditions near active crossings" : "Delay pressure building near your route";
  if (routeRelevantCount === 0) return "No active reports near your route";
  return "Primary corridor currently stable";
}

function computeRouteConfidenceModel({ routeRelevantHazards = [], routeHazard = null, freshnessTier = "Unknown", routeIsMonitoring = false } = {}) {
  if (!routeIsMonitoring) return { band: "Low", score: 0, inputs: { routeIsMonitoring: false }, reasoning: "Route Watch inactive; confidence held low until monitoring is enabled." };
  const relevant = Array.isArray(routeRelevantHazards) ? routeRelevantHazards : [];
  const hazardReports = Array.isArray(routeHazard?.nearbyReports) ? routeHazard.nearbyReports : [];
  const freshReports = relevant.filter((incident) => Number(incident?.age_minutes) <= 30).length;
  const staleReports = relevant.filter((incident) => Number(incident?.age_minutes) > 120).length;
  const confirmations = relevant.reduce((sum, incident) => sum + Math.max(0, Number(incident?.reports_count) || 0), 0);
  const repeatedIncidents = relevant.filter((incident) => Number(incident?.reports_count) >= 2).length;
  const activeCoverage = hazardReports.filter((report) => report.lifecycleState === "active").length;
  const consistency = hazardReports.length > 0 ? Math.round((activeCoverage / hazardReports.length) * 100) : 0;
  const freshnessScore = freshnessTier === "Fresh" ? 35 : freshnessTier === "Aging" ? 24 : 12;
  const confirmationScore = Math.min(25, confirmations * 2);
  const repeatScore = Math.min(15, repeatedIncidents * 4);
  const coverageScore = Math.min(15, activeCoverage * 3);
  const consistencyScore = Math.min(10, Math.round(consistency / 10));
  const stalePenalty = Math.min(12, staleReports * 2);
  const score = Math.max(0, Math.min(100, freshnessScore + confirmationScore + repeatScore + coverageScore + consistencyScore - stalePenalty));
  const band = score >= 70 ? "High" : score >= 40 ? "Moderate" : "Low";
  const reasoning = band === "High"
    ? "Multiple confirmations with fresh and consistent route coverage."
    : band === "Moderate"
      ? "Some confirmations and fresh activity; continue active monitoring."
      : "Sparse or aging incident signal; confidence remains limited.";
  return { band, score, inputs: { freshReports, staleReports, confirmations, repeatedIncidents, activeCoverage, consistency, freshnessTier }, reasoning };
}

function updateRouteIntelligence(nearest = []) {
  if (routeWatchActivated) startGridlyRouteWatchPositionUpdates();
  const routeLabelParts = buildRouteWatchLabelParts();

  const unifiedActive = getRouteIntelligenceSourceIncidents().filter((incident) => incident.status === "active");
  const activeIssues = routeWatchActivated
    ? getLiveProximityRouteIntelligenceIncidents()
    : unifiedActive.filter((incident) => incident.type.startsWith("rail_"));

  const consumerActive = routeWatchActivated ? activeIssues : unifiedActive;
  const highAlerts = consumerActive.filter((report) => report.severity === "high").length;
  const moderateAlerts = consumerActive.filter((report) => report.severity === "medium").length;
  const confirmedIncidents = getConsolidatedIncidents().filter((incident) => {
    const reports = Array.isArray(incident?.reports) ? incident.reports : [];
    const latest = reports[0] || [...reports].sort(compareReportsByRecency)[0];
    return latest && getIncidentLifecycleState(latest) === "active" && reports.length >= 2;
  }).length;
  const desktopRouteSummary = `${unifiedActive.length} live incidents · ${confirmedIncidents} confirmed`;

  const crossingRisk = nearest.length
    ? Math.round(nearest.reduce((sum, c) => sum + c.risk, 0) / nearest.length)
    : 28;

  const impact = Math.min(
    100,
    activeIssues.length * 10 + highAlerts * 22 + moderateAlerts * 8 + Math.round(crossingRisk * 0.35)
  );

  const routeIsConfigured = routeLabelParts.configured;
  const routeIsMonitoring = routeWatchActivated && routeIsConfigured;
  const extraMinutes = Math.max(0, Math.round(impact / 7));
  const routeIntel = getRouteWatchIntelligence(activeIssues);
  const routeHazard = getRouteHazardAssessment();
  const systemConfidence = getSystemConfidence(routeIsMonitoring);
  const recommendationConfidence = getRecommendationConfidence({
    alternateAvailable: Boolean(alternateRouteAvailable),
    hazardsAvoided: Number(hazardsAvoidedCount || 0),
    primaryScore: Number(primaryRouteScore || 0),
    alternateScore: Number(alternateRouteScore || 0),
    routeIsMonitoring
  });
  const corridorHealth = getCorridorHealthFromScore(routeHazard?.score || 0);
  const estimatedDelayImpact = getEstimatedDelayImpact(corridorHealth, routeHazard?.level || "");
  const activeUnifiedHazards = consumerActive.filter((incident) => !String(incident.type || "").startsWith("rail_"));
  const routeRelevantHazards = routeIsMonitoring
    ? activeUnifiedHazards.filter((incident) => isIncidentRouteRelevant(incident, routeHazard))
    : [];
  const routeRelevantBlockedCrossings = routeIsMonitoring
    ? routeHazard.nearbyReports.filter((report) => report.reportType === "blocked" && report.lifecycleState === "active").length
    : 0;
  const routeContextSummary = !routeIsMonitoring
    ? "Route Watch is off. Select Home and a destination to choose what Gridly should watch."
    : routeRelevantBlockedCrossings > 0
      ? "Active report near route: blocked crossing detected along the watched corridor."
      : routeRelevantHazards.length > 0
        ? `${routeRelevantHazards.length} active issue${routeRelevantHazards.length === 1 ? "" : "s"} affecting this route.`
        : "No active reports near this route right now.";
  const newestMinutes = activeIssues.length
    ? Math.min(...activeIssues.map((issue) => Number(issue.minutesAgo)).filter((value) => Number.isFinite(value)))
    : null;
  const freshnessTier = getFreshnessTier(newestMinutes);
  const pressureModel = computeRoutePressureModel({ routeHazard, routeRelevantHazards, freshnessTier });
  routePressureScore = pressureModel.score;
  routePressureBand = pressureModel.band;
  calibratedRecommendationBand = routePressureBand;
  const confidenceModel = computeRouteConfidenceModel({ routeRelevantHazards, routeHazard, freshnessTier, routeIsMonitoring });
  routeConfidence = confidenceModel.band;
  confidenceInputs = confidenceModel.inputs;
  confidenceReasoning = confidenceModel.reasoning;
  activeMonitoringState = routeIsMonitoring ? "active" : "standby";
  const alternateRouteAdvantageLabel = hazardsAvoidedCount > 0 ? `${hazardsAvoidedCount} avoided` : "None";
  const recommendationMessage = buildRouteRecommendationMessage({
    routeIsMonitoring,
    pressureBand: calibratedRecommendationBand,
    hazardsAvoided: hazardsAvoidedCount,
    routeRelevantCount: routeRelevantHazards.length,
    blockedNearRoute: routeRelevantBlockedCrossings,
    alternateAvailable: Boolean(alternateRouteAvailable)
  });
  lastRouteRecommendationMessage = recommendationMessage;
  const etaMetrics = getRouteEtaMetricsFromState({
    routeHazardLevel: routeHazard.level,
    fallbackExtraMinutes: extraMinutes
  });
  const freshReportCount = activeIssues.filter((issue) => Number(issue.minutesAgo) <= 30).length;

  safeText("nearbyAlertCount", `${activeIssues.length} active now`);

  safeText(
    "activeAlertText",
    activeIssues.length === 1
      ? "One active shared report currently affecting the area."
      : "Live shared reports near your saved or current location."
  );

  if (els.impactFill) els.impactFill.style.width = `${impact}%`;
  safeText("impactScore", `${impact} / 100`);

  els.routeStatusCard?.classList.remove("clear", "delayed", "high");

  if (!routeIsMonitoring) {
    safeText("routeStatus", "Choose a route to start");
    safeText("routeEta", routeLabelParts.hasHome ? "Choose destination" : "Set Home");
    safeText("desktopRouteStatus", routeLabelParts.hasHome ? "Choose a saved destination to start Route Watch." : "Set Home and one destination to start Route Watch.");
    safeText("routeFreshness", "Unknown");
    safeText("routeConfidence", `Monitoring: ${getRouteWatchMonitoringSignalCopy(systemConfidence)} · Guidance: ${getRouteWatchGuidanceSignalCopy(recommendationConfidence)}`);
    safeText("routeReports", "0 active");
    safeText("routeRecommendation", recommendationMessage);
    safeText("sideRouteWatchHint", routeLabelParts.hasHome ? "Choose a saved destination to start Route Watch." : "Set Home and one destination to start Route Watch.");
    safeText("departureTime", "Set destination first");
    renderRouteWatchIntelligenceFields({
      systemConfidence,
      recommendationConfidence,
      corridorHealth: "Awaiting route",
      estimatedDelayImpact: "Awaiting route",
      routePressureBand: "Clear",
      routeRelevantHazardCount: 0,
      alternateRouteAdvantageLabel: "None",
      routeConfidence
    });
    els.routeStatusCard?.classList.add("delayed");
  } else if (routeHazard.level === "blocked") {
    safeText("routeStatus", "ALTERNATE ROUTE RECOMMENDED");
    safeText("routeEta", `ETA 32 min (+${extraMinutes})`);
    safeText("departureTime", "LEAVE NOW");
    renderRouteWatchIntelligenceFields({ systemConfidence, recommendationConfidence, corridorHealth, estimatedDelayImpact, routePressureBand, routeRelevantHazardCount: routeRelevantHazards.length, alternateRouteAdvantageLabel, routeConfidence, ...getRouteEtaMetricsFromState({ routeHazardLevel: routeHazard.level, fallbackExtraMinutes: extraMinutes }) });
    safeText("desktopRouteStatus", "Route conditions checked: major active report near this watched route.");
    safeText("routeFreshness", freshnessTier);
    safeText("routeConfidence", `Monitoring: ${getRouteWatchMonitoringSignalCopy(systemConfidence)} · Guidance: ${getRouteWatchGuidanceSignalCopy(recommendationConfidence)}`);
    safeText("routeReports", `${routeHazard.nearbyReports.length} near route`);
    safeText("routeRecommendation", recommendationMessage);
    safeText("sideRouteWatchHint", routeContextSummary);
    els.routeStatusCard?.classList.add("high");
  } else if (routeHazard.level === "heavy") {
    safeText("routeStatus", "Heavy blockage ahead");
    safeText("routeEta", `ETA 26 min (+${extraMinutes})`);
    safeText("departureTime", "LEAVE 8 MIN EARLY");
    renderRouteWatchIntelligenceFields({ systemConfidence, recommendationConfidence, corridorHealth, estimatedDelayImpact, routePressureBand, routeRelevantHazardCount: routeRelevantHazards.length, alternateRouteAdvantageLabel, routeConfidence, ...getRouteEtaMetricsFromState({ routeHazardLevel: routeHazard.level, fallbackExtraMinutes: extraMinutes }) });
    safeText("desktopRouteStatus", "Route conditions checked: active reports near this watched route.");
    safeText("routeFreshness", freshnessTier);
    safeText("routeConfidence", `Monitoring: ${getRouteWatchMonitoringSignalCopy(systemConfidence)} · Guidance: ${getRouteWatchGuidanceSignalCopy(recommendationConfidence)}`);
    safeText("routeReports", `${routeHazard.nearbyReports.length} near route`);
    safeText("routeRecommendation", recommendationMessage);
    safeText("sideRouteWatchHint", routeContextSummary);
    els.routeStatusCard?.classList.add("delayed");
  } else if (routeHazard.level === "caution") {
    safeText("routeStatus", "Monitoring crossings nearby");
    safeText("routeEta", `ETA 24 min (+${Math.max(extraMinutes, 3)})`);
    safeText("departureTime", "LEAVE SLIGHTLY EARLY");
    renderRouteWatchIntelligenceFields({ systemConfidence, recommendationConfidence, corridorHealth, estimatedDelayImpact, routePressureBand, routeRelevantHazardCount: routeRelevantHazards.length, alternateRouteAdvantageLabel, routeConfidence, ...getRouteEtaMetricsFromState({ routeHazardLevel: routeHazard.level, fallbackExtraMinutes: extraMinutes }) });
    safeText("desktopRouteStatus", "Route conditions checked: active report near this watched route.");
    safeText("routeFreshness", freshnessTier);
    safeText("routeConfidence", `Monitoring: ${getRouteWatchMonitoringSignalCopy(systemConfidence)} · Guidance: ${getRouteWatchGuidanceSignalCopy(recommendationConfidence)}`);
    safeText("routeReports", `${routeHazard.nearbyReports.length} near route`);
    safeText("routeRecommendation", recommendationMessage);
    safeText("sideRouteWatchHint", routeContextSummary);
    els.routeStatusCard?.classList.add("delayed");
  } else {
    safeText("routeStatus", "Corridor clear");
    safeText("routeEta", "ETA 21 min");
    safeText("departureTime", "ON-SCHEDULE DEPARTURE");
    renderRouteWatchIntelligenceFields({ systemConfidence, recommendationConfidence, corridorHealth, estimatedDelayImpact, routePressureBand, routeRelevantHazardCount: routeRelevantHazards.length, alternateRouteAdvantageLabel, routeConfidence, ...getRouteEtaMetricsFromState({ routeHazardLevel: routeHazard.level, fallbackExtraMinutes: extraMinutes }) });
    safeText("desktopRouteStatus", "Route conditions checked: no active reports near this route. Route Watch is still on.");
    safeText("routeFreshness", freshnessTier);
    safeText("routeConfidence", `Monitoring: ${getRouteWatchMonitoringSignalCopy(systemConfidence)} · Guidance: ${getRouteWatchGuidanceSignalCopy(recommendationConfidence)}`);
    safeText("routeReports", `${routeHazard.nearbyReports.length} near route`);
    safeText("routeRecommendation", recommendationMessage);
    safeText("sideRouteWatchHint", routeContextSummary);
    els.routeStatusCard?.classList.add("clear");
  }

  if (els.routeRecommendation) {
    els.routeRecommendation.classList.add("route-watch-recommendation-emphasis");
  }
  const mobileLiveCommand = document.querySelector(".mobile-live-command");
  if (mobileLiveCommand) mobileLiveCommand.removeAttribute("data-delay-state");
  syncMobileDestinationCommandCard();
  safeText("mobileLiveRouteStatus", `${els.routeStatus?.textContent || "Corridor clear"} • ${els.routeEta?.textContent || "ETA pending"}`);
  safeText("mobileLiveRouteMeta", getLiveCommuteSignalLine({ impact, urgentBlockedCount: routeIntel.urgentBlockedCount, recommendation: els.routeRecommendation?.textContent || "" }));
  renderDesktopRouteWatchMetrics({
    freshness: routeIsMonitoring ? freshnessTier : "Unknown",
    reportsNearRoute: routeIsMonitoring ? `${routeHazard.nearbyReports.length} near route` : "0 near route",
    systemConfidence,
    recommendationConfidence,
    corridorHealth: routeIsMonitoring ? corridorHealth : "Awaiting route",
    estimatedDelayImpact: routeIsMonitoring ? estimatedDelayImpact : "Awaiting route",
    routeEtaValue: routeIsMonitoring ? etaMetrics.routeEtaValue : "",
    routeDelayValue: routeIsMonitoring ? etaMetrics.routeDelayValue : ""
  });

  const liveStatusCard = document.querySelector(".mobile-live-hero");
  liveStatusCard?.classList.remove("clear-status", "delay-status", "blocked-status");

  if (impact >= 70) {
    const routeIssueTitle = routeHazard?.nearestIssue?.incident?.title || "";
    if (mobileLiveCommand) mobileLiveCommand.dataset.delayState = "blocked";
    safeText("mobileLiveStatusPill", alternateRouteAvailable ? "ALT ROUTE READY" : "BLOCKED");
    safeText("delayRisk", routeIntel.urgentBlockedCount > 0 ? (routeIssueTitle || "Heavy blockage risk nearby") : "Alternate route recommended");
    safeText("delayReason", routeIntel.urgentBlockedCount > 0 ? `${routeIntel.urgentBlockedCount} active signal${routeIntel.urgentBlockedCount === 1 ? "" : "s"} in the last 10 min · alternate route recommended.` : "Live corridor unstable · severe crossing pressure detected.");
    safeText("alternateRoute", "Use alternate");
    safeText("alternateReason", "Avoid highest-impact crossing if possible.");
    safeText("impactText", "High route impact. Use alternate now.");
    safeText("mobileLiveRouteActionBtn", alternateRouteAvailable ? "Use alternate" : "Review route");
    liveStatusCard?.classList.add("blocked-status");
  } else if (impact >= 40) {
    const routeIssueTitle = routeHazard?.nearestIssue?.incident?.title || "";
    if (mobileLiveCommand) mobileLiveCommand.dataset.delayState = "delayed";
    safeText("mobileLiveStatusPill", routeIssueTitle ? "Delay risk detected" : "Route watch active");
    safeText("delayRisk", routeIssueTitle || "Delay risk building nearby");
    safeText("delayReason", routeIssueTitle ? `${routeIssueTitle} · prepare backup route if conditions worsen.` : "Active live signals detected · prepare backup route.");
    safeText("alternateRoute", "Have backup");
    safeText("alternateReason", "Alternate route may help if reports increase.");
    safeText("impactText", "Moderate route impact. Wait 10 min or leave early.");
    safeText("mobileLiveRouteActionBtn", "Wait 10 min");
    liveStatusCard?.classList.add("delay-status");
  } else {
    if (mobileLiveCommand) mobileLiveCommand.dataset.delayState = "clear";
    safeText("mobileLiveStatusPill", "CLEAR");
    safeText("delayRisk", "Route clear • Leave now");
    safeText("delayReason", "No active crossing pressure nearby · live monitoring active.");
    safeText("alternateRoute", "Not needed");
    safeText("alternateReason", "Current route appears clear.");
    safeText("impactText", "Low route impact. Normal travel expected.");
    safeText("mobileLiveRouteActionBtn", "View route");
    liveStatusCard?.classList.add("clear-status");
  }
  if (!routeIsMonitoring) {
    safeText("mobileLiveRouteActionBtn", "Choose route");
  }
  setRouteActiveBodyState(routeIsMonitoring);
  updateAlternateRouteActionState();

  updateMobileTopCommuteCta({ impact, routeIsMonitoring, alternateRouteAvailable });
  updateMobileWatchHeader();
  updateRouteWatchBadge();
  renderGridlyCommunityPulse({ reason: "updateRouteIntelligence" });
}

function updateMobileTopCommuteCta({ routeIsMonitoring = false } = {}) {
  const cta = document.getElementById("mobileCommuteRouteBtn");
  if (!cta) return;
  cta.textContent = routeIsMonitoring ? "View Route" : "Choose Route";
  cta.dataset.sectionJump = "routes";
  cta.dataset.topCtaAction = "open-route-panel";
}

function getMobileWatchAreaLabel() {
  const selectedRouteLabel = [
    window.__gridlySelectedRouteLabel,
    window.__gridlyActiveRouteLabel,
    window.__gridlyWatchedRouteLabel
  ].find((value) => typeof value === "string" && value.trim());
  if (selectedRouteLabel) return selectedRouteLabel.trim();

  const selectedAreaLabel = [
    window.__gridlySelectedAreaLabel,
    window.__gridlySelectedCountyLabel,
    window.__gridlySelectedWatchAreaLabel
  ].find((value) => typeof value === "string" && value.trim());
  if (selectedAreaLabel) return selectedAreaLabel.trim();

  return gridlyGetActiveCountyConfig()?.name || LOCATION_DEFAULTS.county || "Liberty County";
}

function updateCountyOwnedStaticRuntimeLabels() {
  const countyName = gridlyGetActiveCountyConfig()?.name || getMobileWatchAreaLabel();
  const activeFeedLabel = `${countyName} · Active Feed`;
  document.querySelectorAll?.(".beta-pill").forEach((node) => {
    if (/County Beta/i.test(String(node.textContent || ""))) node.textContent = `${countyName} Beta`;
  });
  document.querySelectorAll?.(".hero-floating-badge.county-chip").forEach((node) => {
    node.textContent = activeFeedLabel;
  });
  document.querySelectorAll?.("#crossingsSection p, #dashboardSection p, #crossingInventoryCountyText").forEach((node) => {
    if (/Public crossing inventory currently loaded for/i.test(String(node.textContent || ""))) {
      node.textContent = `Public crossing inventory currently loaded for ${countyName}.`;
    }
  });
  const selectedArea = typeof getGridlySelectedAwarenessArea === "function" ? getGridlySelectedAwarenessArea() : null;
  const awarenessLabel = String(selectedArea?.label || selectedArea?.name || "").trim() || countyName;
  if (typeof safeText === "function") {
    safeText("mobileAwarenessPanelKicker", getGridlyLocationAwarenessCardKicker(awarenessLabel));
    safeText("mobileDestinationCommandTitle", awarenessLabel);
    safeText("gridlyWelcomePreviewPlace", `Watching ${awarenessLabel}`);
  }
  const portraitPanel = document.getElementById?.("gridlyPortraitLocationAwarenessPanel");
  if (portraitPanel) {
    const setPortraitPanelText = (selector, value) => {
      const node = portraitPanel.querySelector?.(selector);
      if (node) node.textContent = value;
    };
    setPortraitPanelText('[data-v2-location-awareness="kicker"]', getGridlyLocationAwarenessCardKicker(awarenessLabel));
    setPortraitPanelText('[data-v2-location-awareness="title"]', awarenessLabel);
    portraitPanel.dataset.awarenessAreaName = awarenessLabel;
  }
  const footer = document.querySelector?.("footer");
  if (footer && /Gridly Beta/i.test(String(footer.textContent || ""))) footer.textContent = `Gridly Beta • ${countyName}`;
  gridlyMarkCountyOwnedRuntimeLabels?.("updateCountyOwnedStaticRuntimeLabels");
}

function gridlyMarkCountyOwnedRuntimeLabels(reason = "county-context-sync") {
  if (typeof document === "undefined") return;
  [
    "mobileWatchArea",
    "mobileLocalContextValue",
    "mobileAwarenessPanelKicker",
    "mobileDestinationCommandTitle",
    "gridlyWelcomePreviewPlace",
    "gridlyWelcomeTownStatus",
    "crossingInventoryCountyText"
  ].forEach((id) => {
    const node = document.getElementById?.(id);
    if (!node) return;
    node.setAttribute("data-gridly-county-owned", id);
    node.setAttribute("data-gridly-county-owned-sync", reason);
  });
  document.querySelectorAll?.(".beta-pill, .hero-floating-badge.county-chip, footer, [data-v2-location-awareness='kicker'], [data-v2-location-awareness='title']").forEach((node) => {
    node.setAttribute("data-gridly-county-owned", node.getAttribute("data-gridly-county-owned") || "county-context-label");
    node.setAttribute("data-gridly-county-owned-sync", reason);
  });
}

function updateMobileWatchHeader() {
  const watchArea = getMobileWatchAreaLabel();
  safeText("mobileWatchLabel", "WATCHING");
  safeText("mobileWatchArea", watchArea);
  safeText("mobileLocalContextLabel", "Current Area");
  safeText("mobileLocalContextValue", watchArea);
  updateCountyOwnedStaticRuntimeLabels();
}


function getLiveCommuteSignalLine({ impact = 0, urgentBlockedCount = 0, recommendation = "" } = {}) {
  if (impact >= 75) return urgentBlockedCount > 0 ? "Heavy blockage risk on US 90" : "Alternate route recommended";
  if (impact >= 45) return "Delay building near Dayton crossing";
  if (impact >= 20) return "Route pressure rising • monitor closely";
  return recommendation || "Route clear • Leave now";
}

const GRIDLY_HEADER_OWNERSHIP_AUDIT_VERSION = "V179.6";
const gridlyHeaderOwnershipTraceState = {
  writes: [],
  lastWriteByTarget: {}
};
const GRIDLY_HEADER_OWNERSHIP_TARGETS = new Set([
  "gridlyV2TopStatusPrimary",
  "gridlyV2TopStatusSecondary",
  "#gridlyV2TopStatusPrimary",
  "#gridlyV2TopStatusSecondary"
]);

function normalizeGridlyHeaderOwnershipTarget(targetElement = "") {
  const target = String(targetElement || "").trim();
  if (target === "#gridlyV2TopStatusPrimary") return "gridlyV2TopStatusPrimary";
  if (target === "#gridlyV2TopStatusSecondary") return "gridlyV2TopStatusSecondary";
  return target;
}

function recordGridlyHeaderOwnershipWrite(sourceFunction, targetElement, value, metadata = {}) {
  const normalizedTarget = normalizeGridlyHeaderOwnershipTarget(targetElement);
  if (!GRIDLY_HEADER_OWNERSHIP_TARGETS.has(normalizedTarget)) return;
  const entry = {
    at: Date.now(),
    sourceFunction: String(sourceFunction || "unknown"),
    targetElement: normalizedTarget,
    value: typeof value === "string" ? value : (value == null ? "" : String(value)),
    metadata: metadata && typeof metadata === "object" ? { ...metadata } : {}
  };
  gridlyHeaderOwnershipTraceState.writes.push(entry);
  if (gridlyHeaderOwnershipTraceState.writes.length > 20) gridlyHeaderOwnershipTraceState.writes.shift();
  gridlyHeaderOwnershipTraceState.lastWriteByTarget[normalizedTarget] = entry;
}

function recordGridlyTopPanelWriteApplied(sourceFunction, targetElement, value) {
  const serializedValue = normalizeGridlyUserFacingRoadText(typeof value === "string" ? value : (value == null ? "" : String(value)));
  const normalizedTarget = normalizeGridlyHeaderOwnershipTarget(targetElement);
  gridlyBackgroundLoopAuditState.topPanelWriteCount += 1;
  gridlyBackgroundLoopAuditState.topPanelWrites.push({
    at: Date.now(),
    sourceFunction: String(sourceFunction || "unknown"),
    targetElement: normalizedTarget,
    value: serializedValue
  });
  trimGridlyBackgroundAuditList(gridlyBackgroundLoopAuditState.topPanelWrites);
  recordGridlyHeaderOwnershipWrite(sourceFunction, normalizedTarget, serializedValue, { trace: "setGridlyTopPanelTextIfChanged" });
  recordGridlyActiveLocationLifecycleEvent("headerTopStatusWrite", {
    sourceFunction: String(sourceFunction || "unknown"),
    targetElement: normalizedTarget,
    value: serializedValue
  });
  if (isGridlyTopPanelDebugEnabled()) {
    console.debug("[V159.2 TOP PANEL WRITE]", {
      sourceFunction,
      targetElement: normalizedTarget,
      value: serializedValue
    });
  }
}

function logTopPanelWrite(sourceFunction, targetElement, value) {
  recordGridlyTopPanelWriteApplied(sourceFunction, targetElement, value);
}


function logTopStripOwnershipDiagnostic(sourceFunction) {
  gridlyBackgroundLoopAuditState.topPanelOwnerCheckCount += 1;
  const selectors = [
    "#habitStatusHeadline",
    "#habitStatusDetail",
    "#gridlyV2TopStatusPrimary",
    "#gridlyV2TopStatusSecondary"
  ];
  const candidates = selectors.map((selector) => {
    const element = document.querySelector(selector);
    return {
      selector,
      id: element?.id || null,
      classList: element ? Array.from(element.classList) : [],
      innerText: element?.innerText || "",
      sourceFunction
    };
  });
  const visibleOwner = candidates.find((entry) => {
    const text = String(entry.innerText || "");
    return /Train blocking US 90|No major disruptions nearby/.test(text);
  }) || null;
  gridlyBackgroundLoopAuditState.topPanelOwnerChecks.push({
    at: Date.now(),
    sourceFunction: String(sourceFunction || "unknown"),
    visibleOwnerSelector: visibleOwner?.selector || null
  });
  trimGridlyBackgroundAuditList(gridlyBackgroundLoopAuditState.topPanelOwnerChecks);
  if (isGridlyTopPanelDebugEnabled()) {
    console.debug("[V159.3 TOP STRIP OWNER]", {
      visibleOwner,
      candidates
    });
  }
}

function getGridlyUpdateDailyHabitStatusActiveItemCount(items = []) {
  return (Array.isArray(items) ? items : []).filter((item) => {
    if (!item) return false;
    if (item.expired === true) return false;
    const status = String(item.status || item.lifecycleState || item.type || item.report_type || "").toLowerCase();
    return status !== "cleared" && status !== "hazard_cleared" && status !== "inactive" && status !== "expired";
  }).length;
}

function getGridlyUpdateDailyHabitStatusTopAwarenessText() {
  const readText = (id) => safeDisplayText(document.getElementById(id)?.textContent, "");
  return {
    primary: readText("gridlyV2TopStatusPrimary"),
    secondary: readText("gridlyV2TopStatusSecondary")
  };
}

function buildGridlyUpdateDailyHabitStatusPortraitSignature(unifiedIncidents = []) {
  const activeUnifiedIncidents = typeof getGridlyActiveCountSurfaceRows === "function"
    ? getGridlyActiveCountSurfaceRows(unifiedIncidents)
    : (Array.isArray(unifiedIncidents) ? unifiedIncidents : []).filter((incident) => String(incident?.status || "").toLowerCase() === "active");
  const activeUnifiedState = activeUnifiedIncidents
    .map((incident) => [
      String(incident?.id || incident?.incident_id || incident?.crossingId || incident?.crossing_id || ""),
      String(incident?.status || ""),
      String(incident?.severity || incident?.priority || incident?.impact || "")
    ].join(":"))
    .sort()
    .join("|");
  const awarenessArea = typeof getGridlySelectedAwarenessArea === "function" ? getGridlySelectedAwarenessArea() : null;
  const topAwarenessText = getGridlyUpdateDailyHabitStatusTopAwarenessText();
  const topAwarenessModel = typeof window !== "undefined" && window.gridlyTopAwarenessMicrolineState
    ? window.gridlyTopAwarenessMicrolineState
    : {};
  const signatureParts = {
    unifiedIncidentCount: (Array.isArray(unifiedIncidents) ? unifiedIncidents : []).length,
    activeUnifiedIncidentCount: activeUnifiedIncidents.length,
    activeUnifiedState,
    activeHazardCount: getGridlyUpdateDailyHabitStatusActiveItemCount(typeof activeHazards !== "undefined" ? activeHazards : []),
    activeReportCount: getGridlyUpdateDailyHabitStatusActiveItemCount(typeof activeReports !== "undefined" ? activeReports : []),
    routeWatchActive: Boolean((typeof routeWatchActivated !== "undefined" && routeWatchActivated) || (typeof window !== "undefined" && window.__gridlyRouteWatchActive)),
    awarenessAreaKey: safeDisplayText(awarenessArea?.key || awarenessArea?.storageValue, ""),
    awarenessAreaName: safeDisplayText(awarenessArea?.label || awarenessArea?.name || awarenessArea?.storageValue, ""),
    topPrimaryText: topAwarenessText.primary,
    topSecondaryText: topAwarenessText.secondary,
    topModelText: safeDisplayText(topAwarenessModel?.text, ""),
    topModelVisible: Boolean(topAwarenessModel?.visible),
    topModelSelectedHeadline: safeDisplayText(topAwarenessModel?.selectedHeadline || topAwarenessModel?.pulseHeadline, "")
  };
  return JSON.stringify(signatureParts);
}

function shouldUseGridlyUpdateDailyHabitStatusPortraitFastPath(signature = "") {
  return Boolean(
    typeof isPortraitMode === "function"
    && isPortraitMode()
    && signature
    && gridlyUpdateDailyHabitStatusFastPathState.lastPortraitSignature === signature
  );
}

function updateDailyHabitStatus() {
  recordGridlyBackgroundFunctionCall("updateDailyHabitStatus");
  const functionStartedAt = performance.now();
  const sections = {};
  const timeSection = makeGridlySectionTimer(sections);
  const portraitModeActive = typeof isPortraitMode === "function" && isPortraitMode();
  let unifiedIncidentsSnapshot = null;
  let portraitFastPathSignature = "";
  if (portraitModeActive) {
    unifiedIncidentsSnapshot = getUnifiedIncidents();
    portraitFastPathSignature = buildGridlyUpdateDailyHabitStatusPortraitSignature(unifiedIncidentsSnapshot);
    if (shouldUseGridlyUpdateDailyHabitStatusPortraitFastPath(portraitFastPathSignature)) {
      gridlyUpdateDailyHabitStatusFastPathState.lastSkippedAt = Date.now();
      recordPortraitIntelligenceBreakdown("updateDailyHabitStatus", functionStartedAt, sections, {
        portraitUnchangedFastPathSkipped: true
      });
      return;
    }
  }

  const localizedIntel = timeSection("intelligence_calculations", () => buildUnifiedLocalizedCommuteIntelligence({ limit: 6 }));
  const { unifiedActive, railActive, activeIssues, highIssues, moderateIssues, activeCount, confirmationCount } = timeSection("array_filtering_sorting", () => {
    unifiedIncidentsSnapshot = unifiedIncidentsSnapshot || getUnifiedIncidents();
    const unifiedActiveItems = typeof getGridlyActiveCountSurfaceRows === "function"
      ? getGridlyActiveCountSurfaceRows(unifiedIncidentsSnapshot)
      : unifiedIncidentsSnapshot.filter((incident) => incident.status === "active");
    const railActiveItems = unifiedActiveItems.filter((incident) => incident.type.startsWith("rail_"));
    const activeIssueItems = railActiveItems;
    const highIssueItems = activeIssueItems.filter((report) => report.severity === "high");
    const moderateIssueItems = activeIssueItems.filter((report) => report.severity === "moderate");
    return {
      unifiedActive: unifiedActiveItems,
      railActive: railActiveItems,
      activeIssues: activeIssueItems,
      highIssues: highIssueItems,
      moderateIssues: moderateIssueItems,
      activeCount: activeIssueItems.length,
      confirmationCount: unifiedIncidentsSnapshot.reduce((sum, i) => sum + i.reports_count, 0)
    };
  });

  const activeAlertCount = Math.max(0, Number(localizedIntel?.activeLocalizedAlertCount || 0));
  const hasActiveAlertIntel = Boolean(localizedIntel?.hasActiveAlerts) || activeAlertCount > 0 || activeIssues.length > 0;

  const awarenessPulseModel = timeSection("shared_community_pulse_model_reuse", () => {
    const expectedPulseSignature = typeof gridlyV734BuildRefreshReuseSignature === "function"
      ? gridlyV734BuildRefreshReuseSignature({ topAwarenessMicrolineReadOnly: true, communityAwarenessSummaryArea: "" })
      : "";
    if (expectedPulseSignature && gridlyCommunityPulseAuditState?.v734SharedModelSignature === expectedPulseSignature) {
      return gridlyCommunityPulseAuditState;
    }
    return typeof refreshGridlyCommunityPulseSharedModel === "function"
      ? refreshGridlyCommunityPulseSharedModel({ reason: "update-daily-habit-status-reuse", topAwarenessMicrolineReadOnly: true })
      : {};
  });
  const awarenessBrief = buildGridlyAwarenessBriefCopy({
    intel: localizedIntel,
    existingAlertWording: hasActiveAlertIntel && typeof resolveGridlyExistingAlertWording === "function" ? resolveGridlyExistingAlertWording({ limit: 6 }) : {},
    pulseModel: awarenessPulseModel
  });
  let pill = awarenessBrief.state === "quiet" ? "Community quiet" : awarenessBrief.state === "high" ? "High community activity" : "Community report";
  let headline = awarenessBrief.primary;
  const visibleAwarenessMicroline = awarenessBrief.microlineVisible ? safeDisplayText(awarenessBrief.microline, "") : "";
  let detail = visibleAwarenessMicroline
    ? `${awarenessBrief.secondary} • ${visibleAwarenessMicroline}`
    : awarenessBrief.secondary;
  let cardClass = awarenessBrief.state === "high" ? "high" : awarenessBrief.state === "moderate" ? "delayed" : "clear";

  const topStatus = headline;
  const topDetail = detail;

  if (isGridlyTopPanelDebugEnabled()) {
    console.debug("[V159.1 TOP PANEL BINDING]", {
      activeAlertCount,
      topStatus,
      topDetail,
      renderedTitle: headline,
      renderedSubtitle: detail
    });
  }

  timeSection("text_content_updates", () => {
    safeTopPanelText("habitStatusPill", pill, "updateDailyHabitStatus");
    safeTopPanelText("habitStatusHeadline", headline, "updateDailyHabitStatus");
    safeTopPanelText("habitStatusDetail", detail, "updateDailyHabitStatus");
    logTopStripOwnershipDiagnostic("updateDailyHabitStatus");
  });

  timeSection("class_style_updates", () => {
    els.habitStatusStrip?.classList.remove("clear", "delayed", "high");
    els.habitStatusStrip?.classList.add(cardClass);
  });

  void unifiedActive;
  void railActive;
  void activeCount;
  if (portraitModeActive) {
    gridlyUpdateDailyHabitStatusFastPathState.lastPortraitSignature = portraitFastPathSignature;
  }
  recordPortraitIntelligenceBreakdown("updateDailyHabitStatus", functionStartedAt, sections);
}

function updateGrowthWidgets() {
  const unifiedActive = getUnifiedIncidents().filter((incident) => incident.status === "active");
  const railActive = unifiedActive.filter((incident) => incident.type.startsWith("rail_"));
  const activeIssues = railActive;
  const highCount = activeIssues.filter((report) => report.severity === "high").length;
  const lastReport = activeReports[0];

  if (highCount > 0) {
    safeText("routeRecommendation", "LEAVE NOW OR REROUTE");
    safeText(
      "routeRecommendationReason",
      `${highCount} high-impact shared report${highCount === 1 ? "" : "s"} active right now.`
    );
  } else if (activeIssues.length > 0) {
    safeText("routeRecommendation", "Heavy blockage ahead");
    safeText(
      "routeRecommendationReason",
      `${activeIssues.length} active shared report${activeIssues.length === 1 ? "" : "s"} may affect travel.`
    );
  } else {
    safeText("routeRecommendation", "Corridor clear");
    safeText("routeRecommendationReason", "No major active shared delays detected right now.");
  }

  const confirmationCount = getUnifiedIncidents().reduce((sum,i)=>sum+i.reports_count,0);
  const routeLabelParts = buildRouteWatchLabelParts();
  const routeIsMonitoring = Boolean(routeWatchActivated && routeLabelParts?.configured);
  const routeHazard = routeIsMonitoring ? getRouteHazardAssessment() : { nearbyReports: [], level: "clear", score: 0 };
  const activeUnifiedHazards = unifiedActive.filter((incident) => !String(incident.type || "").startsWith("rail_"));
  const routeRelevantHazards = routeIsMonitoring
    ? activeUnifiedHazards.filter((incident) => isIncidentRouteRelevant(incident, routeHazard))
    : [];
  const routeRelevantBlockedCrossings = routeIsMonitoring
    ? (Array.isArray(routeHazard?.nearbyReports) ? routeHazard.nearbyReports : []).filter((report) => report.reportType === "blocked" && report.lifecycleState === "active").length
    : 0;

  const newestMinutes = typeof lastReport?.minutesAgo === "number" ? lastReport.minutesAgo : null;
  const freshnessTier = getFreshnessTier(newestMinutes);
  const pressureModel = computeRoutePressureModel({ routeHazard, routeRelevantHazards, freshnessTier });
  routePressureScore = pressureModel.score;
  routePressureBand = pressureModel.band;
  calibratedRecommendationBand = routePressureBand;
  const confidenceModel = computeRouteConfidenceModel({ routeRelevantHazards, routeHazard, freshnessTier, routeIsMonitoring });
  routeConfidence = confidenceModel.band;
  confidenceInputs = confidenceModel.inputs;
  confidenceReasoning = confidenceModel.reasoning;
  activeMonitoringState = routeIsMonitoring ? "active" : "standby";
  const alternateRouteAdvantageLabel = hazardsAvoidedCount > 0 ? `${hazardsAvoidedCount} avoided` : "None";
  const recommendationMessage = buildRouteRecommendationMessage({
    routeIsMonitoring,
    pressureBand: calibratedRecommendationBand,
    hazardsAvoided: hazardsAvoidedCount,
    routeRelevantCount: routeRelevantHazards.length,
    blockedNearRoute: routeRelevantBlockedCrossings,
    alternateAvailable: Boolean(alternateRouteAvailable)
  });
  lastRouteRecommendationMessage = recommendationMessage;
  if (confirmationCount >= 2) {
    safeText("communityTrust", `${freshnessTier} · Community confirmed`);
    safeText("communityTrustReason", `${confirmationCount} active reports live. Multiple drivers are reporting.`);
  } else if (confirmationCount > 0) {
    safeText("communityTrust", `${freshnessTier} · Awaiting additional reports`);
    safeText("communityTrustReason", "Reported by a community member. Conditions may change quickly.");
  } else {
    safeText("communityTrust", "Fresh · Awaiting reports");
    safeText("communityTrustReason", "No active reports yet. Community updates will appear as drivers report.");
  }

  if (lastReport) {
    safeText("freshestReport", `${lastReport.minutesAgo} min ago`);
    safeText(
      "freshestReportReason",
      `${lastReport.crossingName} was marked ${getReportCopy(lastReport.type).label}.`
    );
  } else {
    safeText("freshestReport", "None yet");
    safeText("freshestReportReason", "Reports appear here as soon as drivers submit them.");
  }
}


function updateCorridorSummaryCards() {
  const normalized = getMovementIntelligence();
  const corridorStats = normalized.corridors.map((corridor) => ({ corridor, status: computeCorridorStatus(corridor) }));
  const ranked = corridorStats.sort((a, b) => (b.status.delayScore || 0) - (a.status.delayScore || 0));
  const lead = ranked[0];
  if (!lead) return;

  const state = lead.status;
  const summaryLine = `${lead.corridor.label || "Unnamed Corridor"}`;
  const guidanceLine = getCorridorGuidanceMessage(state.severityLabel);
  const reportCountLabel = `${state.stackedReportCount || 0} active report${state.stackedReportCount === 1 ? "" : "s"}`;
  const freshnessLabel = state.freshness >= 70 ? "Fresh" : state.freshness >= 40 ? "Recent" : "Stale";
  const communitySupportLabel = state.confidence >= 70 ? "Community confirmed" : state.confidence >= 55 ? "Multiple drivers reporting" : "Awaiting additional reports";
  const detailLine = `${state.severityLabel} · ${guidanceLine} · ~${Math.round(state.delayMinutes || 0)} min delay · ${communitySupportLabel} · ${freshnessLabel} · ${reportCountLabel}`;
  safeText("corridorSummaryHeadline", summaryLine);
  safeText("corridorSummaryDetail", detailLine);
  safeText("mobileCorridorSummaryHeadline", summaryLine);
  safeText("mobileCorridorSummaryDetail", detailLine);
  safeText("liveOpsStatus", `${state.severityLabel} · ~${Math.round(state.delayMinutes || 0)} min`);
  safeText("liveOpsDetail", `${guidanceLine} · ${communitySupportLabel} · ${reportCountLabel}`);

  const badges = [
    "LIVE",
    state.freshness < 35 ? "STALE" : null,
    state.confidence >= 70 ? "COMMUNITY CONFIRMED" : null,
    state.confidence >= 55 && state.freshness >= 45 ? "MULTIPLE DRIVERS REPORTING" : null
  ].filter(Boolean);

  [els.corridorSummaryBadges, els.mobileCorridorBadges].forEach((node) => {
    if (!node) return;
    node.innerHTML = badges.map((badge) => `<span class="trust-pill">${sanitizeText(badge)}</span>`).join("");
  });

  const theme = getCorridorSeverityTheme(state.severityLabel);
  [document.querySelector('.corridor-intel-card'), document.querySelector('.mobile-corridor-intel-card')].forEach((card) => {
    if (!card) return;
    card.style.borderColor = theme.border;
    card.style.boxShadow = `0 0 0 1px ${theme.border} inset, 0 16px 28px ${theme.glow}`;
  });
  [els.corridorSummaryHeadline, els.mobileCorridorSummaryHeadline, els.liveOpsStatus].forEach((node) => {
    if (!node) return;
    node.style.color = theme.text;
  });
  [els.corridorSummaryBadges, els.mobileCorridorBadges].forEach((node) => {
    if (!node) return;
    node.querySelectorAll('.trust-pill').forEach((pill) => {
      pill.style.background = theme.badge;
      pill.style.borderColor = theme.border;
    });
  });

  const focusCorridor = selectFocusedCorridor(corridorStats);
  drawCorridorIntelLines(focusCorridor ? [focusCorridor] : []);
}

function getCorridorSeverityRank(severityLabel = "Clear") {
  if (severityLabel === "Blocked") return 3;
  if (severityLabel === "Heavy Delay") return 2;
  if (severityLabel === "Minor Delay") return 1;
  return 0;
}

function getSelectedCorridorId() {
  const candidates = [
    window.__gridlySelectedCorridorId,
    window.__gridlyActiveCorridorId,
    window.__gridlyMovementSelectedCorridorId
  ];
  const selected = candidates.find((value) => value !== undefined && value !== null && String(value).trim());
  return selected ? String(selected).trim() : "";
}

function getSelectedRouteId() {
  const selected = window.__gridlySelectedRouteId;
  if (selected === undefined || selected === null) return "";
  return String(selected).trim();
}

function getRouteWatchActivationState() {
  return window.__gridlyRouteWatchActive === true;
}

function getLineActivationContext() {
  const selectedCorridorId = getSelectedCorridorId();
  const selectedRouteId = getSelectedRouteId();
  const routeWatchActive = getRouteWatchActivationState();
  return { selectedCorridorId, selectedRouteId, routeWatchActive, hasActivation: Boolean(selectedCorridorId || selectedRouteId || routeWatchActive) };
}

function logGridlyMapLineRendered({ renderFunction = "unknown", corridorId = "", routeId = "", activationReason = "", coordinates = [] } = {}) {
  console.info("Gridly map line rendered", { renderFunction, corridorId, routeId, activationReason, coordinates });
}

function selectFocusedCorridor(corridorStats = []) {
  const valid = (Array.isArray(corridorStats) ? corridorStats : []).filter((item) => {
    const corridor = item?.corridor || {};
    const severityRank = getCorridorSeverityRank(item?.status?.severityLabel || "Clear");
    return hasValidCorridorCoordinates(corridor) && severityRank > 0;
  });
  if (!valid.length) return null;

  const selectedCorridorId = getSelectedCorridorId();
  if (selectedCorridorId) {
    const selected = valid.find((item) => String(item?.corridor?.id || "") === selectedCorridorId);
    if (selected) return selected;
  }

  const ranked = valid.sort((a, b) => {
    const severityDiff = getCorridorSeverityRank(b?.status?.severityLabel || "Clear") - getCorridorSeverityRank(a?.status?.severityLabel || "Clear");
    if (severityDiff !== 0) return severityDiff;
    return (b?.status?.delayScore || 0) - (a?.status?.delayScore || 0);
  });

  return ranked[0] || null;
}

function getCorridorGuidanceMessage(severityLabel = "Clear") {
  if (severityLabel === "Blocked") return "Avoid this corridor";
  if (severityLabel === "Heavy Delay") return "Consider alternate route";
  if (severityLabel === "Minor Delay") return "Expect a small delay";
  return "You can drive now";
}

function hasValidCorridorCoordinates(corridor = {}) {
  const values = [corridor.startLat, corridor.startLng, corridor.endLat, corridor.endLng];
  const allFinite = values.every((n) => Number.isFinite(Number(n)));
  if (!allFinite) return false;
  const startLat = Number(corridor.startLat);
  const startLng = Number(corridor.startLng);
  const endLat = Number(corridor.endLat);
  const endLng = Number(corridor.endLng);
  if (Math.abs(startLat) > 90 || Math.abs(endLat) > 90 || Math.abs(startLng) > 180 || Math.abs(endLng) > 180) return false;
  const spanKm = calculateDistanceKm(startLat, startLng, endLat, endLng);
  return Number.isFinite(spanKm) && spanKm > 0.05 && spanKm <= 60;
}

function shouldRenderCorridorLine() {
  return getLineActivationContext().hasActivation;
}

function drawCorridorIntelLines(corridorStats = []) {
  if (!corridorIntelLayer) return;
  corridorIntelLayer.clearLayers();
  const item = Array.isArray(corridorStats) ? corridorStats[0] : null;
  const corridor = item?.corridor || {};
  const state = item?.status || {};
  const severityLabel = state.severityLabel || "Clear";
  if (!hasValidCorridorCoordinates(corridor)) return;
  if (!shouldRenderCorridorLine()) return;

  const latLngs = [
    [Number(corridor.startLat), Number(corridor.startLng)],
    [Number(corridor.endLat), Number(corridor.endLng)]
  ];
  const theme = getCorridorSeverityTheme(severityLabel);

  const glow = L.polyline(latLngs, {
    pane: "routePane",
    color: theme.glow,
    weight: 6,
    opacity: 0.18,
    lineCap: "round",
    interactive: false
  });
  glow.addTo(corridorIntelLayer);

  const core = L.polyline(latLngs, {
    pane: "routePane",
    color: theme.border,
    weight: 3,
    opacity: 0.62,
    lineCap: "round",
    interactive: false
  });
  core.addTo(corridorIntelLayer);
  const activation = getLineActivationContext();
  logGridlyMapLineRendered({
    renderFunction: "drawCorridorIntelLines",
    corridorId: String(corridor.id || ""),
    routeId: activation.selectedRouteId,
    activationReason: activation.selectedCorridorId ? "selected-corridor-id" : activation.selectedRouteId ? "selected-route-id" : "route-watch-active",
    coordinates: latLngs
  });

  const from = corridor.startLabel || "Start";
  const to = corridor.endLabel || "End";
  const label = `${from} — ${to} · ${severityLabel}`;
  core.bindTooltip(sanitizeText(label), {
    permanent: false,
    sticky: true,
    direction: "top",
    opacity: 0.92,
    className: "corridor-intel-tooltip"
  });
}

function getCorridorSeverityTheme(severityLabel = "Clear") {
  if (severityLabel === "Blocked") return { border: "rgba(249, 115, 22, 0.75)", glow: "rgba(239, 68, 68, 0.22)", badge: "rgba(239, 68, 68, 0.2)", text: "#fdba74" };
  if (severityLabel === "Heavy Delay") return { border: "rgba(245, 158, 11, 0.75)", glow: "rgba(245, 158, 11, 0.2)", badge: "rgba(251, 191, 36, 0.22)", text: "#fbbf24" };
  if (severityLabel === "Minor Delay") return { border: "rgba(59, 130, 246, 0.75)", glow: "rgba(234, 179, 8, 0.18)", badge: "rgba(59, 130, 246, 0.2)", text: "#93c5fd" };
  return { border: "rgba(34, 197, 94, 0.65)", glow: "rgba(34, 197, 94, 0.14)", badge: "rgba(34, 197, 94, 0.2)", text: "#86efac" };
}

const ROAD_HAZARD_DISPLAY_CATEGORIES = new Set(["road_closed", "flooding", "crash", "construction", "disabled_vehicle", "debris", "traffic_backup", "other_hazard"]);

function formatRoadHazardCategoryLabel(category) {
  const labels = {
    road_closed: "Road Closed",
    flooding: "Flooding",
    crash: "Crash / Wreck",
    construction: "Construction",
    disabled_vehicle: "Disabled Vehicle",
    debris: "Debris in Road",
    traffic_backup: "Traffic Backup",
    other_hazard: "Other Hazard"
  };
  return labels[category] || "Other Hazard";
}

function extractRoadHintFromText(text = "") {
  const candidate = String(text || "");
  if (!candidate) return "";
  const between = candidate.match(/\bbetween\s+([A-Z0-9][A-Za-z0-9 .\/-]{2,})\s+and\s+([A-Z0-9][A-Za-z0-9 .\/-]{2,})/i);
  if (between?.[1] && between?.[2]) return `${between[1].trim()} / ${between[2].trim()}`;
  const near = candidate.match(/\b(?:on|near|at)\s+([A-Z0-9][A-Za-z0-9 .\/-]{2,})/i);
  return near?.[1] ? near[1].trim() : "";
}

const INVALID_ROAD_NAME_TOKENS = new Set([
  "private",
  "unnamed",
  "unknown",
  "null",
  "none",
  "road",
  "crossing",
  "railroad",
  "railroad crossing",
  "street",
  "n/a",
  "na",
  "test",
  "temp",
  "etc",
  "local road impact",
  "local road impact into liberty",
  "local road impact in liberty",
  "impact into liberty",
  "impact in liberty"
]);

function normalizeRoadNameCandidate(value = "") {
  return String(value || "")
    .trim()
    .replace(/\s+/g, " ");
}

function normalizeRoadwayReference(value = "") {
  const normalized = normalizeRoadNameCandidate(value);
  if (!normalized) return "";

  const compact = normalized
    .replace(/\bwestbound\b|\beastbound\b|\bnorthbound\b|\bsouthbound\b/gi, "")
    .replace(/\bwest\b|\beast\b|\bnorth\b|\bsouth\b/gi, "")
    .replace(/\s+/g, " ")
    .trim();

  const patterns = [
    { re: /^(?:united\s+states\s+highway|u\.?s\.?\s*highway|us\s*highway|us)\s*[- ]?(\d+[a-z]?)$/i, format: (n) => `US ${n.toUpperCase()}` },
    { re: /^(?:farm\s+to\s+market(?:\s+road)?|fm)\s*[- ]?(\d+[a-z]?)$/i, format: (n) => `FM ${n.toUpperCase()}` },
    { re: /^(?:texas\s+state\s+highway|texas\s+highway|tx)\s*[- ]?(\d+[a-z]?)$/i, format: (n) => `TX ${n.toUpperCase()}` },
    { re: /^(?:state\s+highway|sh)\s*[- ]?(\d+[a-z]?)$/i, format: (n) => `SH ${n.toUpperCase()}` },
    { re: /^(?:interstate|ih|i)\s*[- ]?(\d+[a-z]?)$/i, format: (n) => `I-${n.toUpperCase()}` },
    { re: /^(?:loop)\s*[- ]?(\d+[a-z]?)$/i, format: (n) => `Loop ${n.toUpperCase()}` },
    { re: /^(?:spur)\s*[- ]?(\d+[a-z]?)$/i, format: (n) => `Spur ${n.toUpperCase()}` },
    { re: /^(?:county\s+road|cr)\s*[- ]?(\d+[a-z]?)$/i, format: (n) => `CR ${n.toUpperCase()}` }
  ];

  for (const pattern of patterns) {
    const match = compact.match(pattern.re);
    if (match?.[1]) return pattern.format(match[1]);
  }
  return compact;
}

function evaluateRoadNameCandidate(value = "", roadEvaluationContext = null) {
  if (roadEvaluationContext && typeof gridlySelectedAwarenessAreaResolutionCache !== "undefined") gridlySelectedAwarenessAreaResolutionCache.roadEvaluationOptimizedContextReuseCount = Number(gridlySelectedAwarenessAreaResolutionCache.roadEvaluationOptimizedContextReuseCount || 0) + 1;
  const normalized = normalizeRoadwayReference(normalizeRoadNameCandidate(value));
  if (!normalized) return { normalized, valid: false, reason: "empty" };
  if (/^[-,.\s]+$/.test(normalized)) return { normalized, valid: false, reason: "punctuation_only" };
  if (normalized.length < 3) return { normalized, valid: false, reason: "too_short" };
  const lowered = normalized.toLowerCase();
  if (INVALID_ROAD_NAME_TOKENS.has(lowered) || (typeof gridlyIsInvalidCountyAwareRoadLabel === "function" && gridlyIsInvalidCountyAwareRoadLabel(normalized, roadEvaluationContext))) return { normalized, valid: false, reason: "generic_placeholder" };
  if (/^[A-Z0-9\s\-/.&]+$/.test(normalized) && INVALID_ROAD_NAME_TOKENS.has(lowered.replace(/\s+/g, " "))) {
    return { normalized, valid: false, reason: "all_caps_placeholder" };
  }
  return { normalized, valid: true, reason: "ok" };
}

function getRoadwayFeatureNameCandidates(feature, roadEvaluationContext = null) {
  const properties = feature?.properties || {};
  return [properties.name, properties.ref, properties.highway, properties.FULLNAME]
    .map((value) => evaluateRoadNameCandidate(value, roadEvaluationContext));
}


function normalizeRoadDisplayCase(value = "") {
  const text = normalizeRoadNameCandidate(value);
  if (!text) return "";
  const normalizedReference = normalizeRoadwayReference(text);
  if (/^(?:US|FM|SH|TX|I-\d+[A-Z]?|CR|Loop|Spur)\b/.test(normalizedReference)) return normalizedReference;

  return text
    .split(/(\s+|[-\/])/)
    .map((segment) => {
      if (!segment || /^\s+$/.test(segment) || segment === "-" || segment === "/") return segment;
      if (/^\d+[A-Z]?$/.test(segment)) return segment.toUpperCase();
      return segment.charAt(0).toUpperCase() + segment.slice(1).toLowerCase();
    })
    .join("");
}

function titleCaseRoadText(value = "") {
  return normalizeRoadDisplayCase(value);
}

function normalizeRoadComparison(value = "") {
  return String(value || "").toLowerCase().replace(/[^a-z0-9]/g, "");
}

const GRIDLY_VALIDATED_PRIMARY_CORRIDORS = ["US 90", "TX 321", "TX 146", "FM 1960", "FM 1409", "FM 1008", "US 59"];
const GRIDLY_VALIDATED_PRIMARY_CORRIDOR_KEYS = new Set(GRIDLY_VALIDATED_PRIMARY_CORRIDORS.map((name) => normalizeRoadComparison(name)));
let gridlyValidatedPrimaryCorridorInventoryCache = null;

function isGridlyValidatedPrimaryCorridor(value = "") {
  const normalized = normalizeGridlyRoadHazardRoadComponent(value) || normalizeRoadDisplayCase(value);
  const key = normalizeRoadComparison(normalized);
  if (!key) return false;
  return GRIDLY_VALIDATED_PRIMARY_CORRIDOR_KEYS.has(key) || GRIDLY_VALIDATED_PRIMARY_CORRIDORS.some((name) => {
    const allowedKey = normalizeRoadComparison(name);
    return key === allowedKey || key.includes(allowedKey) || allowedKey.includes(key);
  });
}

function canonicalGridlyValidatedPrimaryCorridor(value = "") {
  const normalized = normalizeGridlyRoadHazardRoadComponent(value) || normalizeRoadDisplayCase(value);
  const key = normalizeRoadComparison(normalized);
  return GRIDLY_VALIDATED_PRIMARY_CORRIDORS.find((name) => {
    const allowedKey = normalizeRoadComparison(name);
    return key === allowedKey || key.includes(allowedKey) || allowedKey.includes(key);
  }) || normalized;
}

function getGridlyValidatedPrimaryCorridorInventory() {
  const sourceLength = Array.isArray(roadwaySegmentFeatures) ? roadwaySegmentFeatures.length : 0;
  if (gridlyValidatedPrimaryCorridorInventoryCache?.sourceLength === sourceLength) return gridlyValidatedPrimaryCorridorInventoryCache.inventory;
  const byKey = new Map();
  if (roadwayDatasetLoaded && sourceLength) {
    roadwaySegmentFeatures.forEach((feature) => {
      const props = feature?.properties || {};
      const names = [props?.name, props?.ref, props?.highway]
        .map((value) => normalizeGridlyRoadHazardRoadComponent(value) || normalizeRoadDisplayCase(value))
        .filter(Boolean);
      const canonical = names.map(canonicalGridlyValidatedPrimaryCorridor).find(isGridlyValidatedPrimaryCorridor);
      if (!canonical) return;
      const segments = flattenRoadGeometrySegments(feature?.geometry);
      if (!segments.length) return;
      const key = normalizeRoadComparison(canonical);
      if (!byKey.has(key)) byKey.set(key, { roadName: canonical, segments: [] });
      byKey.get(key).segments.push(...segments);
    });
  }
  const inventory = Array.from(byKey.values()).filter((entry) => entry.segments.length);
  gridlyValidatedPrimaryCorridorInventoryCache = { sourceLength, inventory };
  return inventory;
}

function collectGridlyValidatedPrimaryCorridorCandidates(lat, lng, options = {}) {
  const coords = normalizeCoordinatePair(lat, lng);
  const maxDistanceMiles = Number.isFinite(Number(options?.maxDistanceMiles)) ? Number(options.maxDistanceMiles) : 3;
  const stats = options?.perfStats && typeof options.perfStats === "object" ? options.perfStats : null;
  const inventory = getGridlyValidatedPrimaryCorridorInventory();
  if (stats) stats.corridorCandidateCount = Math.max(Number(stats.corridorCandidateCount || 0), inventory.length);
  if (!coords || !inventory.length) return [];
  return inventory.map((candidate) => {
    let best = null;
    for (const segment of candidate.segments) {
      if (stats) stats.distanceComputationCount = Number(stats.distanceComputationCount || 0) + 1;
      const distance = distancePointToSegmentMiles(coords.lat, coords.lng, segment.startLat, segment.startLng, segment.endLat, segment.endLng);
      if (!Number.isFinite(distance)) continue;
      if (best === null || distance < best) best = distance;
    }
    return {
      roadName: candidate.roadName,
      distanceMiles: best,
      source: "validated_primary_corridor_inventory"
    };
  }).filter((entry) => Number.isFinite(entry.distanceMiles) && entry.distanceMiles <= maxDistanceMiles)
    .sort((a, b) => a.distanceMiles - b.distanceMiles);
}

function buildGridlyRoadEvaluationOperationContext() {
  if (typeof gridlySelectedAwarenessAreaResolutionCache !== "undefined") {
    gridlySelectedAwarenessAreaResolutionCache.roadEvaluationOperationCount = Number(gridlySelectedAwarenessAreaResolutionCache.roadEvaluationOperationCount || 0) + 1;
    gridlySelectedAwarenessAreaResolutionCache.selectedAreaLookupWithinRoadContextCount = Number(gridlySelectedAwarenessAreaResolutionCache.selectedAreaLookupWithinRoadContextCount || 0) + 1;
    gridlySelectedAwarenessAreaResolutionCache.activeCountyLookupWithinRoadContextCount = Number(gridlySelectedAwarenessAreaResolutionCache.activeCountyLookupWithinRoadContextCount || 0) + 1;
    gridlySelectedAwarenessAreaResolutionCache.countyDisplayLookupWithinRoadContextCount = Number(gridlySelectedAwarenessAreaResolutionCache.countyDisplayLookupWithinRoadContextCount || 0) + 1;
  }
  const selectedAwarenessArea = typeof getGridlySelectedAwarenessArea === "function" ? getGridlySelectedAwarenessArea() : null;
  const activeCountyId = typeof gridlyGetActiveCountyId === "function" ? gridlyGetActiveCountyId(selectedAwarenessArea) : gridlyNormalizeCountyId(selectedAwarenessArea?.countyId || GRIDLY_DEFAULT_COUNTY_ID);
  const countyDisplayContext = typeof gridlyGetCountyDisplayContext === "function" ? gridlyGetCountyDisplayContext({}, { selectedAwarenessArea, activeCountyId, countyId: activeCountyId }) : null;
  return buildGridlyRoadEvaluationContext({ selectedAwarenessArea, activeCountyId, countyDisplayContext, operationScoped: true });
}

function collectNearbyRoadCandidates(lat, lng, maxDistanceMiles = 0.45, maxCandidates = 6, roadEvaluationContext = null) {
  if (!roadwayDatasetLoaded || !Array.isArray(roadwaySegmentFeatures) || !roadwaySegmentFeatures.length) return [];
  const evaluationContext = roadEvaluationContext || buildGridlyRoadEvaluationContext();
  const bestByRoadKey = new Map();
  for (const feature of roadwaySegmentFeatures) {
    const candidates = getRoadwayFeatureNameCandidates(feature, evaluationContext);
    const selected = candidates.find((entry) => entry.valid);
    if (!selected?.normalized) continue;
    const roadName = selected.normalized;
    const roadKey = normalizeRoadComparison(roadName);
    if (!roadKey) continue;
    const segments = flattenRoadGeometrySegments(feature?.geometry);
    for (const segment of segments) {
      const distance = distancePointToSegmentMiles(lat, lng, segment.startLat, segment.startLng, segment.endLat, segment.endLng);
      if (!Number.isFinite(distance) || distance > maxDistanceMiles) continue;
      const existing = bestByRoadKey.get(roadKey);
      if (!existing || distance < existing.distanceMiles) {
        bestByRoadKey.set(roadKey, { roadName, roadKey, distanceMiles: distance });
      }
    }
  }
  return Array.from(bestByRoadKey.values())
    .sort((a, b) => a.distanceMiles - b.distanceMiles)
    .slice(0, Math.max(2, maxCandidates));
}

function gridlyRoadHazardPrimaryCorridorEvidence(lat, lng, options = {}) {
  const coords = normalizeCoordinatePair(lat, lng);
  const maxDistanceMiles = Number.isFinite(Number(options?.maxDistanceMiles)) ? Number(options.maxDistanceMiles) : 3;
  const perfStats = options?.perfStats && typeof options.perfStats === "object" ? options.perfStats : null;
  if (!coords) {
    return { selectedPrimaryCorridor: "", selectedPrimaryCorridorDistance: null, candidates: [], source: "missing_coordinates", broadGeometryFallbackUsed: false };
  }
  const candidates = collectGridlyValidatedPrimaryCorridorCandidates(coords.lat, coords.lng, { maxDistanceMiles, perfStats })
    .map((entry) => ({
      road: canonicalGridlyValidatedPrimaryCorridor(entry?.roadName),
      distanceMiles: Number(entry?.distanceMiles),
      distanceMeters: Number.isFinite(Number(entry?.distanceMiles)) ? Number((Number(entry.distanceMiles) * 1609.344).toFixed(1)) : null,
      source: entry?.source || "validated_primary_corridor_inventory"
    }))
    .filter((entry) => entry.road && isGridlyValidatedPrimaryCorridor(entry.road) && Number.isFinite(entry.distanceMiles) && entry.distanceMiles <= maxDistanceMiles)
    .sort((a, b) => a.distanceMiles - b.distanceMiles);
  const selected = candidates[0] || null;
  return {
    selectedPrimaryCorridor: selected?.road || "",
    selectedPrimaryCorridorDistance: selected?.distanceMeters ?? null,
    selectedPrimaryCorridorDistanceMiles: selected ? Number(selected.distanceMiles.toFixed(4)) : null,
    candidates,
    source: selected ? "closest_validated_primary_corridor" : (roadwayDatasetLoaded ? "no_validated_primary_corridor_within_radius_v313_safe_fallback" : "roadway_dataset_unavailable"),
    broadGeometryFallbackUsed: false
  };
}

function buildNearbyPairResolutionIndexKey(lat, lng, primaryRoad = "", roadEvaluationContext = null) {
  const coords = normalizeCoordinatePair(lat, lng);
  if (!coords) return "";
  const primaryKey = normalizeRoadComparison(evaluateRoadNameCandidate(primaryRoad, roadEvaluationContext).normalized || "");
  return `${coords.lat.toFixed(4)},${coords.lng.toFixed(4)}::${primaryKey || "none"}`;
}

function resolveNearbyRoadPair(lat, lng, primaryRoad = "", roadEvaluationContext = null) {
  const evaluationContext = roadEvaluationContext || buildGridlyRoadEvaluationContext();
  const primaryNormalized = evaluateRoadNameCandidate(primaryRoad, evaluationContext);
  const indexActive = Boolean(gridlyRoadNameLookupCache?.nearbyPairResolutionIndex instanceof Map);
  const indexKey = buildNearbyPairResolutionIndexKey(lat, lng, primaryRoad, evaluationContext);
  if (indexActive && indexKey && gridlyRoadNameLookupCache.nearbyPairResolutionIndex.has(indexKey)) {
    gridlyRoadNameLookupCache.nearbyPairResolutionIndexHits = Number(gridlyRoadNameLookupCache.nearbyPairResolutionIndexHits || 0) + 1;
    return { ...(gridlyRoadNameLookupCache.nearbyPairResolutionIndex.get(indexKey) || {}) };
  }
  if (indexActive && indexKey) gridlyRoadNameLookupCache.nearbyPairResolutionIndexMisses = Number(gridlyRoadNameLookupCache.nearbyPairResolutionIndexMisses || 0) + 1;
  const stageTimings = {};
  const withStageTiming = (stageName, fn) => {
    const startedAt = performance.now();
    const value = fn();
    stageTimings[stageName] = Number((Number(stageTimings[stageName] || 0) + (performance.now() - startedAt)).toFixed(4));
    return value;
  };
  const finalizeNearbyPairResult = (state) => {
    if (indexActive && indexKey) gridlySetBoundedRoadNameResolverCacheEntry(gridlyRoadNameLookupCache.nearbyPairResolutionIndex, indexKey, { ...state });
    if (indexActive) {
      const slowestStage = Object.entries(stageTimings).sort((a, b) => Number(b[1]) - Number(a[1]))[0] || null;
      const currentSlowest = gridlyRoadNameLookupCache.nearbyPairResolutionSlowestStage;
      if (slowestStage && (!currentSlowest || Number(slowestStage[1]) > Number(currentSlowest.ms || 0))) {
        gridlyRoadNameLookupCache.nearbyPairResolutionSlowestStage = { stage: slowestStage[0], ms: Number(slowestStage[1]) };
      }
    }
    return state;
  };
  const result = {
    roadA: primaryNormalized.valid ? primaryNormalized.normalized : "",
    roadB: "",
    used: false,
    distanceMiles: null,
    rejectedReason: "",
    samples: []
  };
  const coords = normalizeCoordinatePair(lat, lng);
  if (!coords) {
    result.rejectedReason = "invalid_coordinates";
    return finalizeNearbyPairResult(result);
  }
  const candidates = withStageTiming("nearby_candidate_scan", () => collectNearbyRoadCandidates(coords.lat, coords.lng, 0.45, 8, evaluationContext));
  if (indexActive) gridlyRoadNameLookupCache.nearbyPairResolutionCandidateCount = Number(gridlyRoadNameLookupCache.nearbyPairResolutionCandidateCount || 0) + Number(candidates.length || 0);
  result.samples = candidates.slice(0, 6).map((entry) => `${entry.roadName} (${entry.distanceMiles.toFixed(3)} mi)`);
  if (!candidates.length) {
    result.rejectedReason = roadwayDatasetLoaded ? "no_nearby_roads_in_radius" : "roadway_dataset_unavailable";
    return finalizeNearbyPairResult(result);
  }
  if (!result.roadA) result.roadA = candidates[0]?.roadName || "";
  const primaryKey = normalizeRoadComparison(result.roadA);
  const secondary = candidates.find((entry) => {
    const candidateKey = normalizeRoadComparison(entry.roadName);
    if (!candidateKey || !primaryKey) return false;
    if (candidateKey === primaryKey) return false;
    if (candidateKey.includes(primaryKey) || primaryKey.includes(candidateKey)) return false;
    if (entry.distanceMiles > 0.35) return false;
    return true;
  });
  if (!secondary) {
    result.rejectedReason = "no_meaningful_secondary_road";
    return finalizeNearbyPairResult(result);
  }
  result.roadB = secondary.roadName;
  result.distanceMiles = Number(secondary.distanceMiles.toFixed(4));
  result.used = true;
  return finalizeNearbyPairResult(result);
}

function buildHumanLocationContext({ primaryRoad = "", crossingRoad = "", intersectingRoad = "", roadwayRef = "", nearbyArea = "" } = {}) {
  const ordered = [primaryRoad, crossingRoad, intersectingRoad, roadwayRef]
    .map((value) => titleCaseRoadText(normalizeRoadNameCandidate(value)))
    .filter(Boolean);
  const uniqueRoads = [];
  const seen = new Set();
  ordered.forEach((road) => {
    const key = normalizeRoadComparison(road);
    if (!key || seen.has(key)) return;
    seen.add(key);
    uniqueRoads.push(road);
  });
  const area = String(nearbyArea || "").trim();
  const primary = uniqueRoads[0] || "";
  const secondary = uniqueRoads[1] || "";
  let phrasing = "";
  if (primary && secondary) phrasing = `${primary} & ${secondary}`;
  else if (primary) phrasing = primary;
  else if (area) phrasing = area;
  return {
    primary,
    secondary,
    phrasing,
    usedFallback: !primary,
    source: primary ? "roadway_candidates" : area ? "area_fallback" : "none",
    samples: uniqueRoads.slice(0, 4)
  };
}

// Rank point-hazard roadway evidence by the distance to the actual segment, not
// by the order in which a nearby crossing happened to be returned.  Keeping
// this small and data-shaped also lets county roadway loaders attach their
// candidate segments without creating a second consumer resolver.
function gridlyResolvePointIncidentRoadCandidates(incidentCoordinate, roadCandidates = [], options = {}) {
  const coords = normalizeCoordinatePair(incidentCoordinate?.lat, incidentCoordinate?.lng);
  const trustworthyMeters = Number.isFinite(Number(options?.trustworthyMeters)) ? Number(options.trustworthyMeters) : 45;
  if (!coords) return { incidentCoordinate: null, roadCandidates: [], primaryRoadCandidate: null, secondaryRoadCandidate: null, distanceMeters: null, selectionReason: "invalid_incident_coordinate", locationContext: buildHumanLocationContext({ nearbyArea: options?.nearbyArea || "" }) };
  const ranked = (Array.isArray(roadCandidates) ? roadCandidates : []).map((candidate, index) => {
    const coordinates = Array.isArray(candidate?.coordinates) ? candidate.coordinates : [];
    let distanceMiles = Infinity;
    let closestSegment = null;
    for (let pointIndex = 1; pointIndex < coordinates.length; pointIndex += 1) {
      const a = coordinates[pointIndex - 1];
      const b = coordinates[pointIndex];
      const distance = distancePointToSegmentMiles(coords.lat, coords.lng, Number(a?.[1]), Number(a?.[0]), Number(b?.[1]), Number(b?.[0]));
      if (Number.isFinite(distance) && distance < distanceMiles) { distanceMiles = distance; closestSegment = [a, b]; }
    }
    return { name: titleCaseRoadText(normalizeRoadNameCandidate(candidate?.name || candidate?.roadName || "")), coordinates, closestSegment, distanceMeters: Number.isFinite(distanceMiles) ? Number((distanceMiles * 1609.344).toFixed(2)) : null, classification: candidate?.classification || "road", sourceIndex: index };
  }).filter(candidate => candidate.name && candidate.distanceMeters !== null)
    .sort((a, b) => a.distanceMeters - b.distanceMeters || a.name.localeCompare(b.name) || a.sourceIndex - b.sourceIndex);
  const primary = ranked[0] && ranked[0].distanceMeters <= trustworthyMeters ? ranked[0] : null;
  const secondary = primary ? ranked.find(candidate => normalizeRoadComparison(candidate.name) !== normalizeRoadComparison(primary.name)) || null : null;
  const locationContext = buildHumanLocationContext({ primaryRoad: primary?.name || "", crossingRoad: secondary?.name || "", nearbyArea: options?.nearbyArea || "" });
  return { incidentCoordinate: coords, roadCandidates: ranked, primaryRoadCandidate: primary, secondaryRoadCandidate: secondary, distanceMeters: primary?.distanceMeters ?? null, selectionReason: primary ? (primary.distanceMeters <= 2 ? "point_on_nearest_road_segment" : "nearest_trustworthy_road_segment") : "no_trustworthy_road_geometry", locationContext };
}

function resolveNearbyKnownLocation(lat, lng, options = {}) {
  const __lp012StartedAt = gridlyLP012Now();
  try {
  const coords = normalizeCoordinatePair(lat, lng);
  if (!coords) return "";
  const radiusMiles = Number.isFinite(Number(options?.radiusMiles)) ? Number(options.radiusMiles) : 1.8;
  const nearest = runNestedLookupOperation({
    functionName: "resolveNearbyKnownLocation",
    collectionName: "crossings",
    collectionLength: Array.isArray(crossings) ? crossings.length : 0,
    lookupType: "scan"
  }, () => findNearestCrossings(coords.lat, coords.lng, 1))[0];
  if (!nearest || !Number.isFinite(Number(nearest.distance)) || Number(nearest.distance) > radiusMiles) return "";
  const roadEvaluationContext = options?.roadEvaluationContext || options?.evaluationContext || null;
  const evaluation = evaluateRoadNameCandidate(nearest?.name || "", roadEvaluationContext);
  return evaluation.valid ? evaluation.normalized : "";
  } finally {
    gridlyLP012RecordResolver("resolveNearbyKnownLocation", __lp012StartedAt);
  }
}

function isResolvableRoadNameCandidate(value = "", roadEvaluationContext = null) {
  return evaluateRoadNameCandidate(value, roadEvaluationContext).valid;
}

function buildResolveNearestRoadNameIndexKey(lat, lng, options = {}) {
  const latNum = Number(lat);
  const lngNum = Number(lng);
  if (!Number.isFinite(latNum) || !Number.isFinite(lngNum)) return "";
  const stableId = String(options?.id || options?.incidentId || options?.reportId || "").trim();
  const rounded = `${latNum.toFixed(6)},${lngNum.toFixed(6)}`;
  const revisionKey = gridlyBuildRoadNameResolverRevisionKey();
  return stableId ? `${revisionKey}::id::${stableId}::${rounded}` : `${revisionKey}::geo::${rounded}`;
}

function resolveNearestRoadName(lat, lng) {
  const __lp012StartedAt = gridlyLP012Now();
  try {
  const resolverCache = gridlyEnsureRoadNameResolverRuntimeCache();
  const indexActive = Boolean(resolverCache?.resolveNearestRoadNameIndex instanceof Map);
  const indexKey = buildResolveNearestRoadNameIndexKey(lat, lng);
  if (indexActive && indexKey && resolverCache.resolveNearestRoadNameIndex.has(indexKey)) {
    resolverCache.resolveNearestRoadNameIndexHits = Number(resolverCache.resolveNearestRoadNameIndexHits || 0) + 1;
    const cachedResult = resolverCache.resolveNearestRoadNameIndex.get(indexKey);
    resolveNearestRoadName.lastDebug = cachedResult?.debugState || null;
    return cachedResult?.value ?? null;
  }
  if (indexActive && indexKey) {
    resolverCache.resolveNearestRoadNameIndexMisses = Number(resolverCache.resolveNearestRoadNameIndexMisses || 0) + 1;
  }
  const roadEvaluationContext = buildGridlyRoadEvaluationOperationContext();
  const stageTimings = {};
  const withStageTiming = (stageName, fn) => {
    const startedAt = performance.now();
    const value = fn();
    stageTimings[stageName] = Number((Number(stageTimings[stageName] || 0) + (performance.now() - startedAt)).toFixed(4));
    return value;
  };
  const finalizeResolveNearestRoadNameResult = (value, state) => {
    if (indexActive && indexKey) gridlySetBoundedRoadNameResolverCacheEntry(resolverCache.resolveNearestRoadNameIndex, indexKey, { value, debugState: state });
    if (indexActive) {
      const slowestStage = Object.entries(stageTimings).sort((a, b) => Number(b[1]) - Number(a[1]))[0] || null;
      const currentSlowest = resolverCache.resolveNearestRoadNameSlowestStage;
      if (slowestStage && (!currentSlowest || Number(slowestStage[1]) > Number(currentSlowest.ms || 0))) {
        resolverCache.resolveNearestRoadNameSlowestStage = { stage: slowestStage[0], ms: Number(slowestStage[1]) };
      }
    }
    return value;
  };
  const coords = normalizeCoordinatePair(lat, lng);
  const debugState = {
    resolverExists: true,
    roadwayDatasetLoaded,
    roadwayFeatureCount: Array.isArray(roadwaySegmentFeatures) ? roadwaySegmentFeatures.length : 0,
    crossingCount: Array.isArray(crossings) ? crossings.length : 0,
    roadwayLookupSource: "none",
    nearestSegmentDistance: null,
    fallbackReason: "",
    candidateSource: "none",
    rejectedCandidates: [],
    rejectionReasons: [],
    normalizedCandidateSamples: [],
    pairedRoadSamples: [],
    nearbyRoadPairingUsed: false,
    nearbyRoadDistance: null,
    pairingRejectedReason: "",
    sampleLookup: null,
    fallbackBehavior: "returns null when no local roadway source is available",
    coords
  };
  if (!coords) {
    debugState.fallbackBehavior = "returns null when coordinates are invalid";
    debugState.fallbackReason = "invalid_coordinates";
    resolveNearestRoadName.lastDebug = debugState;
    return finalizeResolveNearestRoadNameResult(null, debugState);
  }
  if (indexActive) resolverCache.resolveNearestRoadNameCandidateCollectionSize = Array.isArray(roadwaySegmentFeatures) ? roadwaySegmentFeatures.length : 0;
  const nearestSegmentMatch = withStageTiming("roadway_segment_scan", () => runNestedLookupOperation({
    functionName: "resolveNearestRoadName",
    collectionName: "roadwaySegmentFeatures",
    collectionLength: Array.isArray(roadwaySegmentFeatures) ? roadwaySegmentFeatures.length : 0,
    lookupType: "scan"
  }, () => findNearestRoadwaySegment(coords.lat, coords.lng, 1.2)));
  if (indexActive) {
    resolverCache.resolveNearestRoadNameCandidatesEvaluated += Array.isArray(roadwaySegmentFeatures) ? roadwaySegmentFeatures.length : 0;
    resolverCache.resolveNearestRoadNameMaxCandidateScanDurationMs = Math.max(Number(resolverCache.resolveNearestRoadNameMaxCandidateScanDurationMs || 0), Number(stageTimings.roadway_segment_scan || 0));
  }
  if (nearestSegmentMatch?.feature) {
    const segmentCandidates = getRoadwayFeatureNameCandidates(nearestSegmentMatch.feature, roadEvaluationContext);
    const selectedSegment = runNestedLookupOperation({ functionName: "resolveNearestRoadName", collectionName: "segmentCandidates", collectionLength: segmentCandidates.length, lookupType: "find" }, () => segmentCandidates.find((entry) => entry.valid));
    const rejectedSegments = runNestedLookupOperation({ functionName: "resolveNearestRoadName", collectionName: "segmentCandidates", collectionLength: segmentCandidates.length, lookupType: "filter" }, () => segmentCandidates.filter((entry) => entry.normalized && !entry.valid));
    debugState.rejectedCandidates.push(...rejectedSegments.map((entry) => entry.normalized));
    debugState.rejectionReasons.push(...rejectedSegments.map((entry) => entry.reason));
    debugState.normalizedCandidateSamples.push(...segmentCandidates.map((entry) => entry.normalized).filter(Boolean).slice(0, 4));
    debugState.nearestSegmentDistance = Number(nearestSegmentMatch.distanceMiles.toFixed(4));
    if (selectedSegment?.normalized) {
      debugState.candidateSource = "roadway_dataset";
      debugState.roadwayLookupSource = "roadway_dataset";
      debugState.fallbackBehavior = "returns nearest roadway segment label when valid";
      const pair = withStageTiming("nearby_pair_resolution", () => resolveNearbyRoadPair(coords.lat, coords.lng, selectedSegment.normalized, roadEvaluationContext));
      debugState.pairedRoadSamples = pair.samples;
      debugState.nearbyRoadPairingUsed = pair.used;
      debugState.nearbyRoadDistance = pair.distanceMiles;
      debugState.pairingRejectedReason = pair.rejectedReason;
      resolveNearestRoadName.lastDebug = debugState;
      const resolvedValue = pair.used ? `${pair.roadA} & ${pair.roadB}` : selectedSegment.normalized;
      return finalizeResolveNearestRoadNameResult(resolvedValue, debugState);
    }
    debugState.fallbackReason = "nearest_segment_unnamed_or_generic";
  } else {
    debugState.fallbackReason = roadwayDatasetLoaded ? "no_segment_within_radius" : "roadway_dataset_unavailable";
  }

  const nearest = withStageTiming("crossing_scan", () => runNestedLookupOperation({
    functionName: "resolveNearestRoadName",
    collectionName: "crossings",
    collectionLength: Array.isArray(crossings) ? crossings.length : 0,
    lookupType: "scan"
  }, () => findNearestCrossings(coords.lat, coords.lng, 1))[0]);
  if (nearest && Number.isFinite(Number(nearest.distance)) && Number(nearest.distance) <= 0.8) {
    const tempCandidate = [nearest?.roadwayName, nearest?.road_name, nearest?.street_name, nearest?.crossing_street, nearest?.cross_street, nearest?.name]
      .map((value) => evaluateRoadNameCandidate(value, roadEvaluationContext));
    const selected = runNestedLookupOperation({ functionName: "resolveNearestRoadName", collectionName: "crossingCandidates", collectionLength: tempCandidate.length, lookupType: "find" }, () => tempCandidate.find((entry) => entry.valid));
    const rejected = runNestedLookupOperation({ functionName: "resolveNearestRoadName", collectionName: "crossingCandidates", collectionLength: tempCandidate.length, lookupType: "filter" }, () => tempCandidate.filter((entry) => entry.normalized && !entry.valid));
    debugState.rejectedCandidates = rejected.map((entry) => entry.normalized);
    debugState.rejectionReasons = rejected.map((entry) => entry.reason);
    debugState.normalizedCandidateSamples = tempCandidate.map((entry) => entry.normalized).filter(Boolean).slice(0, 8).concat(debugState.normalizedCandidateSamples).slice(0, 8);
    debugState.sampleLookup = nearest?.name || null;
    if (selected?.normalized) {
      debugState.candidateSource = "crossing_fallback";
      debugState.roadwayLookupSource = "crossing_fallback";
      debugState.fallbackBehavior = "returns nearest crossing-linked road label when valid";
      const pair = withStageTiming("crossing_pair_resolution", () => resolveNearbyRoadPair(coords.lat, coords.lng, selected.normalized, roadEvaluationContext));
      debugState.pairedRoadSamples = pair.samples;
      debugState.nearbyRoadPairingUsed = pair.used;
      debugState.nearbyRoadDistance = pair.distanceMiles;
      debugState.pairingRejectedReason = pair.rejectedReason;
      resolveNearestRoadName.lastDebug = debugState;
      const resolvedValue = pair.used ? `${pair.roadA} & ${pair.roadB}` : selected.normalized;
      return finalizeResolveNearestRoadNameResult(resolvedValue, debugState);
    }
    debugState.fallbackReason = debugState.fallbackReason || "crossing_candidate_invalid";
  }

  debugState.roadwayLookupSource = debugState.roadwayLookupSource || "none";
  debugState.fallbackReason = debugState.fallbackReason || "no_valid_candidate_found";
  resolveNearestRoadName.lastDebug = debugState;
  return finalizeResolveNearestRoadNameResult(null, debugState);
  } finally {
    gridlyLP012RecordResolver("resolveNearestRoadName", __lp012StartedAt);
  }
}

