function standardizeGridlyAlertHeadline(value = "") {
  const raw = normalizeGridlyUserFacingRoadText(String(value ?? "").replace(/[\s_]+/g, " ").trim());
  if (!raw) return "";
  const protectedRefs = [];
  let working = raw
    .replace(/\b(?:U\.?S\.?|US)\s*-?\s*(\d+[A-Z]?)\b/gi, (_, number) => ` __GRIDLY_ROAD_REF_${protectedRefs.push(`US ${String(number).toUpperCase()}`) - 1}__ `)
    .replace(/\b(?:T\.?X\.?|TX)\s*-?\s*(\d+[A-Z]?)\b/gi, (_, number) => ` __GRIDLY_ROAD_REF_${protectedRefs.push(`TX ${String(number).toUpperCase()}`) - 1}__ `)
    .replace(/\b(?:F\.?M\.?|FM)\s*-?\s*(\d+[A-Z]?)\b/gi, (_, number) => ` __GRIDLY_ROAD_REF_${protectedRefs.push(`FM ${String(number).toUpperCase()}`) - 1}__ `)
    .replace(/\b(?:C\.?R\.?|CR)\s*-?\s*(\d+[A-Z]?)\b/gi, (_, number) => ` __GRIDLY_ROAD_REF_${protectedRefs.push(`CR ${String(number).toUpperCase()}`) - 1}__ `)
    .replace(/\b(?:S\.?H\.?|SH)\s*-?\s*(\d+[A-Z]?)\b/gi, (_, number) => ` __GRIDLY_ROAD_REF_${protectedRefs.push(`SH ${String(number).toUpperCase()}`) - 1}__ `)
    .replace(/\b(?:I|IH)\s*-\s*(\d+[A-Z]?)\b/gi, (_, number) => ` __GRIDLY_ROAD_REF_${protectedRefs.push(`I-${String(number).toUpperCase()}`) - 1}__ `);

  const lowerWords = new Set(["a", "an", "and", "at", "by", "for", "from", "in", "near", "of", "on", "or", "the", "to", "with", "between"]);
  const keepUpper = new Set(["US", "TX", "FM", "CR", "SH", "IH", "ID"]);
  const formatWord = (word, index) => {
    if (!word || /^__GRIDLY_ROAD_REF_\d+__$/.test(word)) return word;
    if (/^\d+[A-Za-z]?$/.test(word)) return word.toUpperCase();
    const normalized = word.replace(/[’]/g, "'");
    if (/^[A-Za-z]{1,3}$/.test(normalized) && keepUpper.has(normalized.toUpperCase())) return normalized.toUpperCase();
    const lowered = normalized.toLowerCase();
    if (index > 0 && lowerWords.has(lowered)) return lowered;
    return normalized
      .split(/([\-/])/).map((part) => {
        if (part === "-" || part === "/") return part;
        if (!part) return part;
        if (/^\d+[a-z]?$/.test(part)) return part.toUpperCase();
        return part.charAt(0).toUpperCase() + part.slice(1).toLowerCase();
      }).join("");
  };

  working = working
    .replace(/\s*([/–—-])\s*/g, " $1 ")
    .replace(/\s+/g, " ")
    .trim()
    .split(" ")
    .map(formatWord)
    .join(" ")
    .replace(/\s+([,.;:!?])/g, "$1")
    .replace(/\s*([/–—-])\s*/g, " $1 ")
    .replace(/\s+/g, " ")
    .trim();

  protectedRefs.forEach((label, index) => {
    working = working.replace(new RegExp(`__GRIDLY_ROAD_REF_${index}__`, "g"), label);
  });
  working = normalizeGridlyEditorialConsumerPresentationText(working);
  return working;
}

function normalizeGridlyEditorialConsumerPresentationText(value = "") {
  return normalizeGridlyUserFacingRoadText(value)
    .replace(/\b(\d+(?:\.\d+)?)\s+Miles?\b/g, (_, distance) => `${distance} ${Number(distance) === 1 ? "mile" : "miles"}`)
    .replace(/\b(\d+(?:\.\d+)?)\s+(mile|miles)\s+(North|South|East|West)\s+of\b/g, (_, distance, unit, direction) => `${distance} ${unit.toLowerCase()} ${direction.toLowerCase()} of`)
    .replace(/\b(Near|At|On|Between)\b/g, (match, word, offset, fullText) => {
      const before = String(fullText || "").slice(0, offset).trim();
      return before ? word.toLowerCase() : word;
    })
    .replace(/\s+/g, " ")
    .trim();
}

function buildGridlyCanonicalEventPresentationModel(event = {}, options = {}) {
  const fallbackTitle = options?.fallbackTitle || event?.resolvedHeadline || event?.headline || event?.title || event?.localizedSummary || "";
  const cardModel = typeof buildGridlyAlertCardConsumerModel === "function"
    ? buildGridlyAlertCardConsumerModel(event, { fallbackTitle })
    : null;
  const title = normalizeGridlyEditorialConsumerPresentationText(cardModel?.title || standardizeGridlyAlertHeadline(fallbackTitle) || "Road hazard");
  const authoritativeHazardLocation = typeof resolveGridlyRoadHazardAuthoritativeLocationLabel === "function"
    ? resolveGridlyRoadHazardAuthoritativeLocationLabel(event)
    : "";
  const hazardLocationLine = authoritativeHazardLocation || "";
  const locationLine = normalizeGridlyEditorialConsumerPresentationText(hazardLocationLine || cardModel?.locationLine || event?.locationLine || event?.location || "");
  const locationLabel = normalizeGridlyEditorialConsumerPresentationText(authoritativeHazardLocation || cardModel?.locationLabel || event?.locationLabel || event?.roadName || event?.corridor || "");
  const freshnessCountLine = normalizeGridlyEditorialConsumerPresentationText(cardModel?.freshnessCountLine || event?.freshnessCountLine || event?.minutesText || "");
  const evidenceLine = normalizeGridlyEditorialConsumerPresentationText(cardModel?.freshnessCountLine || event?.evidenceLine || event?.freshnessCountLine || event?.minutesText || "");
  const primaryEvent = title;
  const locationContext = locationLine;
  const evidence = evidenceLine;
  const supportingDetails = Array.isArray(options?.supportingDetails) ? options.supportingDetails : [];
  return {
    title: primaryEvent,
    locationLine: locationContext,
    locationLabel,
    freshnessCountLine: evidence,
    primaryEvent,
    locationContext,
    evidence,
    supportingDetails,
    hierarchy: [
      { layer: 1, name: "Primary Event", key: "primaryEvent", value: primaryEvent, strongestVisualElement: true },
      { layer: 2, name: "Location Context", key: "locationContext", value: locationContext, supportsPrimaryEvent: true },
      { layer: 3, name: "Evidence", key: "evidence", value: evidence, trustModelPreserved: true },
      { layer: 4, name: "Supporting Details", key: "supportingDetails", value: supportingDetails, actionsMetadataAndAdditionalContext: true }
    ],
    compositionContract: "what-happened -> where -> evidence -> details",
    consumerModelSource: cardModel ? "buildGridlyAlertCardConsumerModel" : "headline-fallback",
    editorialStandard: "GRIDLY EDITORIAL STANDARD V1",
    canonicalPresentationStandard: "GRIDLY CANONICAL EVENT PRESENTATION V1",
    normalized: true
  };
}

