function gridlyLocationTruthAudit(options = {}) {
  const canonicalContext = typeof getGridlyCanonicalAwarenessPresentationContext === "function"
    ? getGridlyCanonicalAwarenessPresentationContext()
    : null;
  const canonicalAudit = typeof window !== "undefined" && typeof window.gridlyCanonicalAwarenessPresentationAudit === "function"
    ? window.gridlyCanonicalAwarenessPresentationAudit()
    : null;
  const controlRailAudit = typeof window !== "undefined" && typeof window.gridlyPortraitSpatialOwnershipAudit === "function"
    ? window.gridlyPortraitSpatialOwnershipAudit()
    : null;
  const briefAudit = typeof window !== "undefined" && typeof window.gridlyBriefSimplificationAudit === "function"
    ? window.gridlyBriefSimplificationAudit()
    : null;
  const alerts = Array.isArray(options?.alerts)
    ? options.alerts
    : (typeof window !== "undefined" && typeof window.getAlertsSurfaceSnapshot === "function" && Array.isArray(window.getAlertsSurfaceSnapshot()?.alerts)
      ? window.getAlertsSurfaceSnapshot().alerts
      : []);
  const sampleHazard = options?.sampleHazard || alerts.find((alert) => !isGridlyAlertRailOrCrossingRelated(alert)) || {
    id: "v869-location-truth-sample",
    title: "Flooding on TX 321",
    headline: "Flooding reported from Cleveland",
    roadName: "TX 321",
    locationName: "Cleveland",
    awarenessArea: canonicalContext?.displayName || "Dayton",
    reportLocationLabel: "Submitted nearby",
    minutesText: "Reported just now",
    type: "flooding"
  };
  const canonical = buildGridlyCanonicalEventPresentationModel(sampleHazard, { fallbackTitle: sampleHazard.title || sampleHazard.headline });
  const hazardLocation = resolveGridlyRoadHazardAuthoritativeLocationLabel(sampleHazard);
  const awarenessArea = canonicalContext?.displayName || sampleHazard.awarenessArea || "";
  const reportLocation = safeDisplayText(sampleHazard.reportLocationLabel || sampleHazard.submissionLocation || sampleHazard.reportLocation || "Submitted nearby", "Submitted nearby");
  const surfaceInventory = [
    { surface: "Awareness headline", presents: "Hazard location", source: "buildGridlyCanonicalEventPresentationModel.primaryEvent", text: canonical.primaryEvent },
    { surface: "Expanded Brief", presents: "Hazard location plus Awareness Area header", source: "gridlyBriefInteractionBuildModel + canonical event model", text: `${canonical.primaryEvent} ${canonical.locationContext}`.trim() },
    { surface: "Alert cards", presents: "Hazard location", source: "buildAlertsSurfaceHtml canonical model", text: `${canonical.primaryEvent} ${canonical.locationContext}`.trim() },
    { surface: "Alert sheet", presents: "Hazard location", source: "alerts panel heading/card canonical model", text: `${canonical.primaryEvent} ${canonical.locationContext}`.trim() },
    { surface: "Hazard popup", presents: "Hazard location", source: "buildGridlyHazardPopupConsumerModel", text: hazardLocation ? `Reported on ${hazardLocation}` : canonical.locationContext },
    { surface: "Marker popup", presents: "Hazard location", source: "popup consumer model; marker placement unchanged", text: hazardLocation ? `Reported on ${hazardLocation}` : canonical.locationContext },
    { surface: "Location Context card", presents: "Awareness Area", source: "getGridlyCanonicalAwarenessPresentationContext", text: awarenessArea },
    { surface: "Community report wording", presents: "Report location", source: "report metadata only", text: reportLocation },
    { surface: "Route impact", presents: "Route context with canonical hazard summary", source: "route surfaces consume alert summaries only", text: canonical.locationContext },
    { surface: "Community confirmation wording", presents: "Report/evidence count", source: "community trust model", text: canonical.evidence }
  ];
  const hazardTexts = surfaceInventory.filter((entry) => /Hazard location/.test(entry.presents)).map((entry) => entry.text).join(" ");
  const reportLocationSeparated = !reportLocation || !hazardLocation || !new RegExp(`\\b${reportLocation.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")}\\b`, "i").test(hazardTexts);
  const hazardLocationPresent = Boolean(hazardLocation && new RegExp(`\\b${hazardLocation.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")}\\b`, "i").test(hazardTexts));
  const locationContextUsesAwarenessArea = Boolean(awarenessArea && surfaceInventory.find((entry) => entry.surface === "Location Context card")?.presents === "Awareness Area");
  const mixedLocationDetected = !reportLocationSeparated || (awarenessArea && hazardLocation && awarenessArea !== hazardLocation && /reported in|submitted in|submitted nearby/i.test(canonical.locationContext));
  const result = {
    audit: "V869 Location Truth Audit",
    available: true,
    sourceInventory: surfaceInventory,
    canonicalHazardLocation: hazardLocation,
    awarenessArea,
    reportLocation,
    headlineUsesHazardLocation: hazardLocationPresent && /on|at|between|near/i.test(canonical.primaryEvent),
    briefUsesHazardLocation: hazardLocationPresent,
    popupUsesHazardLocation: hazardLocationPresent,
    alertUsesHazardLocation: hazardLocationPresent,
    locationContextUsesAwarenessArea,
    reportLocationSeparated,
    mixedLocationDetected,
    canonicalContextPass: Boolean(canonicalAudit?.pass !== false && locationContextUsesAwarenessArea),
    protectedAudits: {
      v865CanonicalAwarenessPass: Boolean(canonicalAudit?.pass !== false),
      v867ControlRailPass: Boolean(!controlRailAudit || controlRailAudit.pass || controlRailAudit.portraitSpatialOwnershipPass),
      v868BriefPass: Boolean(!briefAudit || briefAudit.pass)
    }
  };
  result.pass = Boolean(result.headlineUsesHazardLocation && result.briefUsesHazardLocation && result.popupUsesHazardLocation && result.alertUsesHazardLocation && result.locationContextUsesAwarenessArea && result.reportLocationSeparated && !result.mixedLocationDetected && result.canonicalContextPass && result.protectedAudits.v865CanonicalAwarenessPass && result.protectedAudits.v867ControlRailPass && result.protectedAudits.v868BriefPass);
  return result;
}

