  const registryCounty = gridlyLp022ResolveRegistryIdentifierLabel(rawCountyId);
  const county = gridlyLp022NormalizeLocationText(record?.county || record?.countyName || record?.county_name || raw?.county || raw?.countyName || source?.county || source?.countyName || registryCounty || options?.fallbackCounty || "");
  if (gridlyLp022IsValidLocationCandidate(road, "roadway") && gridlyLp022IsValidLocationCandidate(cross, "crossing") && !gridlyLp022SameRoad(road, cross)) return { label: `${road} at ${cross}`, locationLine: `${road} at ${cross}`, locationSource: "trustedRoadwayIntersection", authoritativeLocationUsed: false, strongestLocationConsumed: !gridlyLp022LocationFieldValue(record, "strongestLocationLabel"), fallbackLevel: "trusted roadway/intersection information" };
  if (gridlyLp022IsValidLocationCandidate(road, "roadway") && gridlyLp022IsValidLocationCandidate(community, "community") && !gridlyLp022SameRoad(road, community)) return { label: `${road} near ${community}`, locationLine: `${road} near ${community}`, locationSource: "roadwayCommunity", authoritativeLocationUsed: false, strongestLocationConsumed: !gridlyLp022LocationFieldValue(record, "strongestLocationLabel"), fallbackLevel: "roadway + trusted community" };
