function gridlyLp019UsableViewportVisibility(mapRef, coords, options = {}) {
  const container = mapRef?.getContainer?.();
  const point = coords && typeof mapRef?.latLngToContainerPoint === "function" ? mapRef.latLngToContainerPoint([coords.lat, coords.lng]) : null;
  const fallbackWidth = Number(mapRef?.getSize?.()?.x) || 0;
  const fallbackHeight = Number(mapRef?.getSize?.()?.y) || 0;
  const mapRect = container instanceof HTMLElement
    ? container.getBoundingClientRect()
    : { left: 0, top: 0, right: fallbackWidth, bottom: fallbackHeight, width: fallbackWidth, height: fallbackHeight };
  const safetyMargin = Math.max(12, Math.min(28, Math.round(Math.min(mapRect.width || fallbackWidth, mapRect.height || fallbackHeight) * 0.035) || 16));
  const popupAllowance = options.popupRequested ? Math.max(36, Math.min(84, Math.round((mapRect.height || fallbackHeight) * 0.11) || 48)) : 0;
  const visibleOverlap = (selector, edge) => Array.from(document.querySelectorAll(selector)).reduce((total, el) => {
    if (!(el instanceof HTMLElement)) return total;
    const style = getComputedStyle(el);
    if (el.hidden || el.getAttribute("aria-hidden") === "true" || style.display === "none" || style.visibility === "hidden" || Number(style.opacity) === 0) return total;
    const rect = el.getBoundingClientRect();
    const horizontalOverlap = Math.max(0, Math.min(mapRect.right, rect.right) - Math.max(mapRect.left, rect.left));
    if (horizontalOverlap <= Math.min(mapRect.width || 0, 24)) return total;
    if (edge === "top" && rect.top <= mapRect.top + (mapRect.height * 0.5)) return Math.max(total, Math.max(0, Math.min(rect.bottom, mapRect.bottom) - mapRect.top));
    if (edge === "bottom" && rect.bottom >= mapRect.bottom - (mapRect.height * 0.5)) return Math.max(total, Math.max(0, mapRect.bottom - Math.max(rect.top, mapRect.top)));
    return total;
  }, 0);
  const topObstruction = visibleOverlap("#gridlyCurrentConditionsPanel, #gridlyPortraitV2CurrentConditions, .gridly-current-conditions, .gridly-filter-surface, .leaflet-top", "top");
  const bottomObstruction = visibleOverlap("#gridlyLocationContextCard, .gridly-location-context-card, .gridly-bottom-context, .leaflet-bottom", "bottom");
  const usableViewportRect = {
    left: safetyMargin,
    top: topObstruction + safetyMargin + popupAllowance,
    right: Math.max(safetyMargin, (mapRect.width || fallbackWidth) - safetyMargin),
    bottom: Math.max(topObstruction + safetyMargin + popupAllowance, (mapRect.height || fallbackHeight) - bottomObstruction - safetyMargin),
  };
  usableViewportRect.width = Math.max(0, usableViewportRect.right - usableViewportRect.left);
  usableViewportRect.height = Math.max(0, usableViewportRect.bottom - usableViewportRect.top);
  const insideMap = Boolean(point && point.x >= 0 && point.y >= 0 && point.x <= (mapRect.width || fallbackWidth) && point.y <= (mapRect.height || fallbackHeight));
  const horizontalVisibilityPass = Boolean(point && point.x >= usableViewportRect.left && point.x <= usableViewportRect.right);
  const verticalVisibilityPass = Boolean(point && point.y >= usableViewportRect.top && point.y <= usableViewportRect.bottom);
  const targetClearOfTopObstruction = Boolean(point && point.y >= topObstruction + safetyMargin + popupAllowance);
  const targetClearOfBottomObstruction = Boolean(point && point.y <= (mapRect.height || fallbackHeight) - bottomObstruction - safetyMargin);
  const targetInsideUsableViewport = Boolean(insideMap && horizontalVisibilityPass && verticalVisibilityPass);
  const popupEl = options.popupRequested ? document.querySelector("#map .leaflet-popup") : null;
  const popupRect = popupEl?.getBoundingClientRect?.();
  const popupInsideUsableViewport = !options.popupRequested || !popupRect || (popupRect.left >= mapRect.left + safetyMargin && popupRect.right <= mapRect.right - safetyMargin && popupRect.top >= mapRect.top + safetyMargin && popupRect.bottom <= mapRect.bottom - safetyMargin);
  let visibilityFailureReason = "";
  if (options.popupRequested && !popupInsideUsableViewport) visibilityFailureReason = "popup_outside_map_viewport";
  if (!point) visibilityFailureReason = "target_container_point_unavailable";
  else if (!insideMap) visibilityFailureReason = "target_outside_map_container";
  else if (!horizontalVisibilityPass) visibilityFailureReason = "target_too_close_to_horizontal_edge";
  else if (!targetClearOfTopObstruction) visibilityFailureReason = "target_obscured_by_top_surface";
  else if (!targetClearOfBottomObstruction) visibilityFailureReason = "target_obscured_by_bottom_surface";
  else if (!verticalVisibilityPass) visibilityFailureReason = "target_outside_vertical_usable_viewport";
  return {
    mapContainerRect: gridlyLp019RectAudit(mapRect),
    usableViewportRect: gridlyLp019RectAudit(usableViewportRect),
    targetContainerPoint: gridlyLp019PointAudit(point),
    targetInsideUsableViewport,
    markerInsideUsableViewport: targetInsideUsableViewport,
    popupInsideUsableViewport,
    finalPopupInsideUsableViewport: popupInsideUsableViewport,
    targetClearOfTopObstruction,
    targetClearOfBottomObstruction,
    horizontalVisibilityPass,
    verticalVisibilityPass,
    usableViewportVisibilityCompleted: Boolean(targetInsideUsableViewport && targetClearOfTopObstruction && targetClearOfBottomObstruction && popupInsideUsableViewport),
    visibilityFailureReason
  };
}

function gridlyLp019IntendedViewportTargetPoint(mapRef, offset = null) {
  const size = mapRef?.getSize?.();
  if (!size) return null;
  return { x: Number(size.x) / 2 - Number(offset?.x || 0), y: Number(size.y) / 2 - Number(offset?.y || 0) };
}

