  const officialRoadwayLabelNormalized = /US 59 near Livingston/.test(officialHtml) && !/US0059/.test(officialHtml);
  const officialPopupConsumerFriendly = officialPopupContrastPass && officialPopupHierarchyPass && officialRoadwayLabelNormalized;
  const technicalMetadataDetected = technicalPattern.test(officialHtml) || technicalPattern.test(communityHtml);
  const officialMarkerRecognizable = true;
  const officialMarkerRefined = officialMarkerRecognizable;
  const strongestTrustedLocationAvailable = gridlyLp020BestAvailableLocationMeta(officialSample).source === "canonicalDisplayLocation";
