function gridlyNormalizeOfficialConsumerLanguage(value = "", context = {}) {
  let text = gridlyOfficialConsumerCleanText(value);
  if (!text) return "";
  const route = gridlyOfficialConsumerRouteName(context.record || context, text);
  const routePattern = route ? route.replace(/[.*+?^${}()|[\]\\]/g, "\\$&") : "";
  text = text
    .replace(/\b(construction of safety improvements? projects? consisting of install(?:ing)? )cale( median barrier)\b/gi, "$1cable$2")
    .replace(/\bconstruction of safety improvements? projects? consisting of install(?:ing)? cable median barrier\b/gi, "Crews are installing a cable median barrier")
    .replace(/\bconstruction of safety improvements? consisting of install(?:ing)? cable median barrier\b/gi, "Crews are installing a cable median barrier")
    .replace(/\bconstruction of ([^.]+?) consisting of installing ([^.]+?)\.?$/i, "Construction crews are installing $2.")
    .replace(/\bconsisting of install(?:ing)? cable median barrier\b/gi, "while crews install a cable median barrier")
    .replace(/\bconsisting of installing\b/gi, "installing")
    .replace(/\bnot affected\b/gi, "remain open")
    .replace(/\bmain lanes remain open\b/gi, "Main lanes remain open")
    .replace(/\balternating lanes closed\b/gi, "Alternating lane closures")
    .replace(/\ball lanes closed\b/gi, "All lanes closed")
    .replace(/\blanes closed\b/gi, "lane closures")
    .replace(/\bexpect delays\s*\.\s*Crews are installing a cable median barrier\b/gi, "Expect delays while crews install a cable median barrier");
  text = gridlyOfficialConsumerSentenceCase(text);
  if (routePattern) {
    text = text
      .replace(new RegExp(`^${routePattern}\\s+Main lanes remain open\\.\\s*`, "i"), `${route} main lanes remain open. `)
      .replace(new RegExp(`^${routePattern}\\s*,?\\s*Alternating lane closures\\.\\s*`, "i"), `Alternating lane closures on ${route}. `)
      .replace(new RegExp(`^${routePattern}\\s+All lanes closed\\.\\s*`, "i"), `All lanes closed on ${route}. `);
  }
  if (route && /\bconstruction\b/i.test(text) && !new RegExp(`\\bon\\s+${route.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")}\\b`, "i").test(text) && !new RegExp(route.replace(/[.*+?^${}()|[\]\\]/g, "\\$&"), "i").test(text)) {
    text = `Construction underway on ${route}. ${text}`;
  }
  text = text
    .replace(/\bConstruction of safety improvement projects installing cable median barrier\b/gi, "Crews are installing a cable median barrier")
    .replace(/\bConstruction underway on ([^.]+)\.\s+Alternating lane closures on \1\.\s*/gi, "Alternating lane closures on $1. ")
    .replace(/\bConstruction underway on ([^.]+)\.\s+Crews are installing a cable median barrier\./gi, "Crews are installing a cable median barrier.")
    .replace(/\bExpect delays\.\s+Crews are installing a cable median barrier\./gi, "Expect delays while crews install a cable median barrier.")
    .replace(/\b(US|SH|FM|IH|TX|I|Loop)\s+(\d+)\s+\1\s+\2\b/gi, "$1 $2");
  text = text.replace(/\s+([.,;:!?])/g, "$1").replace(/(?:\s*\.\s*){2,}/g, ". ").replace(/\s+/g, " ").trim();
  if (text && !/[.!?]$/.test(text)) text += ".";
  return text;
}



const GRIDLY_LP047_OFFICIAL_CATEGORY_PRESENTATION = Object.freeze({
  crash: Object.freeze({ title: "Crash reported", happening: (road) => `A crash has been reported${road ? ` on ${road}` : " on the roadway"}.`, impact: "Expect slower traffic and use caution near the scene." }),
  flooding: Object.freeze({ title: "Flooding reported", happening: (road) => `Flooding has been reported${road ? ` on ${road}` : " on the roadway"}.`, impact: "Water on the road can change quickly; do not drive through flooded areas." }),
  high_water: Object.freeze({ title: "High water reported", happening: (road) => `High water has been reported${road ? ` on ${road}` : " on the roadway"}.`, impact: "Use caution and avoid driving through water-covered roads." }),
  construction: Object.freeze({ title: "Road work reported", happening: (road) => `Road work is reported${road ? ` on ${road}` : " in this area"}.`, impact: "Expect crews, lane changes, or slower traffic where work is active." }),
  lane_closure: Object.freeze({ title: "Lane closure reported", happening: (road) => `One or more lanes are closed${road ? ` on ${road}` : " on the roadway"}.`, impact: "Expect reduced capacity and possible delays." }),
  road_closed: Object.freeze({ title: "Road closed", happening: (road) => `The road is closed${road ? ` on ${road}` : " in this area"}.`, impact: "Plan for delays and use an alternate route if needed." }),
  bridge_restriction: Object.freeze({ title: "Bridge restriction reported", happening: (road) => `A bridge restriction is reported${road ? ` on ${road}` : " in this area"}.`, impact: "Some vehicles may need to slow down, use another crossing, or follow posted restrictions." }),
  bridge_closure: Object.freeze({ title: "Bridge closed", happening: (road) => `A bridge is closed${road ? ` on ${road}` : " in this area"}.`, impact: "Use another crossing and expect extra travel time." }),
  travel_advisory: Object.freeze({ title: "Travel advisory", happening: (road) => `An official travel advisory is active${road ? ` for ${road}` : " in this area"}.`, impact: "Use extra caution and check conditions before you go." }),
  disabled_vehicle: Object.freeze({ title: "Disabled vehicle reported", happening: (road) => `A disabled vehicle has been reported${road ? ` on ${road}` : " on the roadway"}.`, impact: "Use caution near the shoulder or affected lane." }),
  debris: Object.freeze({ title: "Debris reported", happening: (road) => `Debris has been reported${road ? ` on ${road}` : " on the roadway"}.`, impact: "Watch for objects in or near the travel lanes." }),
  weather: Object.freeze({ title: "Weather advisory", happening: (road) => `Weather may affect travel${road ? ` near ${road}` : " in this area"}.`, impact: "Conditions may include heavy rain, reduced visibility, wind, or severe weather." }),
  other_official: Object.freeze({ title: "Official roadway notice", happening: (road) => `An official roadway notice is active${road ? ` for ${road}` : " in this area"}.`, impact: "Use caution and check conditions before you go." })
});

function gridlyLp047OfficialPresentationKey(record = {}, sourceType = "official-roadways") {
  const text = [record?.normalizedGridlyType, record?.category, record?.type, record?.title, record?.description, record?.raw?.category, record?.raw?.title].map((value) => String(value || "")).join(" ").toLowerCase();
  if (sourceType === "weather" || /weather|rain|visibility|wind|tornado|storm|ice|snow|fog/.test(text)) return "weather";
  if (/disabled\s*vehicle|stalled\s*vehicle/.test(text)) return "disabled_vehicle";
  if (/debris|object|obstruction/.test(text)) return "debris";
  if (/bridge.*clos|clos.*bridge/.test(text)) return "bridge_closure";
  if (/bridge|weight limit|height limit|restriction/.test(text)) return "bridge_restriction";
  if (/road\s*clos|road closed|full\s*closure|closed road|all lanes closed/.test(text)) return "road_closed";
  if (/flood|high water|water over|standing water/.test(text)) return /high water/.test(text) ? "high_water" : "flooding";
  if (/lane\s*clos|lanes? closed|lane blocked|shoulder/.test(text)) return "lane_closure";
  if (/construct|maintenance|work zone|road work|repair/.test(text)) return "construction";
  if (/crash|accident|collision|wreck/.test(text)) return "crash";
  if (/advisory|alert|delay|detour|condition|incident/.test(text)) return "travel_advisory";
  return "other_official";
}

function gridlyLp047OfficialCategoryPresentation(record = {}, sourceType = "official-roadways") {
  const key = gridlyLp047OfficialPresentationKey(record, sourceType);
  const entry = GRIDLY_LP047_OFFICIAL_CATEGORY_PRESENTATION[key] || GRIDLY_LP047_OFFICIAL_CATEGORY_PRESENTATION.other_official;
  const road = gridlyOfficialConsumerRouteName(record, [record?.routeName, record?.roadName, record?.roadway, record?.location, record?.description].join(" "));
  return Object.freeze({ key, title: entry.title, firstSentence: entry.happening(road), impactSentence: entry.impact, combinedDescription: `${entry.happening(road)} ${entry.impact}`.trim(), attribution: "Official Source · DriveTexas" });
}

function gridlyLp047OfficialPresentationPlanAudit(records = []) {
  const sourceRecords = Array.isArray(records) && records.length ? records : (typeof getGridlyOfficialSituationNormalizedRecords === "function" ? getGridlyOfficialSituationNormalizedRecords() : []);
  const categories = {};
  sourceRecords.forEach((record) => {
    const presentation = gridlyLp047OfficialCategoryPresentation(record, record?.providerId === "weather" ? "weather" : "official-roadways");
    categories[presentation.key] = categories[presentation.key] || { count: 0, title: presentation.title, firstSentenceExample: presentation.firstSentence, impactSentence: presentation.impactSentence, attribution: presentation.attribution };
    categories[presentation.key].count += 1;
  });
  return Object.freeze({ available: true, milestone: "LP047", investigationFirst: true, productionChangeScope: "presentation_refinement_only", protectedSystemsPreserved: ["LP039 authority ownership", "Shared Geometry Authority", "DriveTexas ingestion", "provider adapters", "category assignment", "hazard lifecycle", "Supabase", "community reports", "marker rendering", "alert focus", "Travel Brief ownership", "refresh logic", "runtime contracts"], auditedCategoryKeys: Object.keys(GRIDLY_LP047_OFFICIAL_CATEGORY_PRESENTATION), observedCategoryPresentation: categories, recommendedPresentationPlan: "Use one Gridly voice for official categories: understandable title, what-is-happening first sentence, practical impact second sentence, preserved roadway name, and Official Source · DriveTexas attribution." });
}

