function gridlyLp0455ParseOfficialFreshnessValue(value, nowMs = Date.now()) {
  if (value === null || value === undefined || value === "") return { parsedEpochMs: NaN, unit: "missing" };
  if (typeof value === "number" || /^\d+(?:\.\d+)?$/.test(String(value).trim())) {
    const numeric = Number(value);
    if (!Number.isFinite(numeric) || numeric <= 0) return { parsedEpochMs: NaN, unit: "invalid_numeric" };
    if (numeric >= 100000000000) return { parsedEpochMs: numeric, unit: "epoch_milliseconds" };
    if (numeric >= 1000000000) return { parsedEpochMs: numeric * 1000, unit: "epoch_seconds" };
    return { parsedEpochMs: NaN, unit: "non_date_numeric_rejected" };
  }
  const parsed = new Date(value).getTime();
  return Number.isFinite(parsed) ? { parsedEpochMs: parsed, unit: "iso_string" } : { parsedEpochMs: NaN, unit: "invalid_string" };
}

function gridlyLp0455OfficialFreshnessResult(situation = {}, nowMs = Date.now()) {
  const names = ["updatedAt", "updated_at", "lastUpdated", "last_updated", "modified", "modifiedAt", "published", "eventUpdateTime", "sourceUpdatedAt", "timestamp", "reportedAt", "observedAt", "freshnessTimestamp", "lastUpdatedAt", "startTime", "endTime"];
  const freshnessCandidateFields = names.map((name) => ({ name, value: situation?.[name] })).filter((item) => item.value !== undefined && item.value !== null && item.value !== "");
  let selected = null;
  for (const candidate of freshnessCandidateFields) {
    const parsed = gridlyLp0455ParseOfficialFreshnessValue(candidate.value, nowMs);
    const calculatedAgeMs = parsed.parsedEpochMs - nowMs > 0 ? NaN : nowMs - parsed.parsedEpochMs;
    const calculatedAgeMinutes = Math.round(calculatedAgeMs / 60000);
    const reasonable = Number.isFinite(calculatedAgeMinutes) && calculatedAgeMinutes >= 0 && calculatedAgeMinutes <= GRIDLY_OFFICIAL_FRESHNESS_REASONABLE_MAX_MINUTES;
    selected = { ...candidate, ...parsed, calculatedAgeMs, calculatedAgeMinutes, reasonable };
    if (reasonable) break;
  }
  const unavailable = "Update time unavailable";
  const renderedFreshnessLine = selected?.reasonable && typeof formatGridlyAlertsFreshnessLine === "function"
    ? formatGridlyAlertsFreshnessLine(selected.calculatedAgeMinutes, unavailable)
    : unavailable;
  const fallbackReason = selected?.reasonable
    ? null
    : (!freshnessCandidateFields.length
      ? "missing_or_unknown"
      : (Number.isFinite(selected?.calculatedAgeMinutes) && selected.calculatedAgeMinutes > GRIDLY_OFFICIAL_FRESHNESS_REASONABLE_MAX_MINUTES ? "implausibly_old" : "invalid_or_unknown"));
  const safeLine = /754673 minutes ago|updated recently|nan|negative|invalid date|undefined|^updated\s+\d{10,}|^updated\s+\d{4}-\d{2}-\d{2}/i.test(String(renderedFreshnessLine)) ? unavailable : renderedFreshnessLine;
  return {
    freshnessCandidateFields,
    selectedFreshnessField: selected?.name || null,
    selectedFreshnessRawValue: selected?.value ?? null,
    selectedFreshnessType: selected?.value === undefined || selected?.value === null ? "missing" : typeof selected.value,
    selectedFreshnessParsedEpochMs: Number.isFinite(selected?.parsedEpochMs) ? selected.parsedEpochMs : null,
    currentEpochMs: nowMs,
    calculatedAgeMs: Number.isFinite(selected?.calculatedAgeMs) ? selected.calculatedAgeMs : null,
    calculatedAgeMinutes: Number.isFinite(selected?.calculatedAgeMinutes) ? selected.calculatedAgeMinutes : null,
    freshnessUnitClassification: selected?.unit || "missing",
    freshnessReasonable: Boolean(selected?.reasonable),
    renderedFreshnessLine: safeLine,
    freshnessFallbackUsed: !selected?.reasonable || safeLine === unavailable,
    freshnessFallbackReason: fallbackReason,
    freshnessLineOmitted: false,
    freshnessRenderedAsUnavailable: safeLine === unavailable,
    firstFreshnessFailureStage: selected?.reasonable || !freshnessCandidateFields.length ? null : "freshness_unreasonable_or_invalid"
  };
}

