function formatPortraitTopStripImpactLabel(tier = "") {
  const normalizedTier = String(tier || "").toLowerCase();
  if (normalizedTier === "severe" || normalizedTier === "heavy") return "High impact";
  if (normalizedTier === "moderate") return "Moderate impact";
  return "Low impact";
}


function getGridlyAwarenessBriefTownLabel() {
  return getGridlyCanonicalAwarenessPresentationContext().displayName;
}

function getGridlyAwarenessTimeOfDayGreetingPart(date = new Date()) {
  const hour = Number(date instanceof Date ? date.getHours() : new Date(date).getHours());
  if (hour >= 5 && hour < 12) return "Good Morning";
  if (hour >= 12 && hour < 17) return "Good Afternoon";
  return "Good Evening";
}

function getGridlyAwarenessGreetingText(options = {}) {
  const profile = typeof getGridlyUserProfile === "function" ? getGridlyUserProfile() : (gridlyUserProfile || {});
  const preferredName = typeof getGridlyPreferredNamePreference === "function" ? getGridlyPreferredNamePreference() : "";
  const name = safeDisplayText(preferredName || profile?.preferredName || profile?.name, "");
  const part = getGridlyAwarenessTimeOfDayGreetingPart(options.date || options.now || new Date());
  return name ? `${part} ${name}` : part;
}

function pluralizeGridlyCommunityReports(count = 0, singular = "community report", plural = "community reports") {
  const safeCount = Math.max(0, Number(count) || 0);
  return `${safeCount} ${safeCount === 1 ? singular : plural}`;
}

function pluralizeGridlyMobilityReports(count = 0) {
  return pluralizeGridlyCommunityReports(count, "active community report", "active community reports");
}

function getGridlyAwarenessCommunityCount(intel = {}, activeAwareness = {}) {
  const dedupedMobilityCount = Number(activeAwareness?.topAwarenessDedupedMobilityCount ?? activeAwareness?.topAwarenessDisplayedCount);
  if (Number.isFinite(dedupedMobilityCount)) return Math.max(0, dedupedMobilityCount);
  const candidates = [
    activeAwareness?.activeReportCount,
    activeAwareness?.activeAwarenessCount,
    activeAwareness?.activeHazardCount,
    intel?.activeLocalizedAlertCount,
    Array.isArray(window.__gridlyLatestAlertsForRender) ? window.__gridlyLatestAlertsForRender.length : null,
    Array.isArray(typeof activeReports !== "undefined" ? activeReports : null) ? getGridlyAwarenessLifecycleActiveReports(activeReports).length : null
  ];
  return Math.max(0, ...candidates.map((value) => Number(value)).filter((value) => Number.isFinite(value)));
}

function isGridlyAlertsSurfaceUserFacingClear(snapshot = null) {
  if (!snapshot || typeof snapshot !== "object") return false;
  const alerts = Array.isArray(snapshot.alerts) ? snapshot.alerts : [];
  return Math.max(0, Number(snapshot.activeIncidentCount || 0)) === 0
    && alerts.length === 0
    && snapshot.hasActiveAlerts === false;
}

function getGridlyAlertsSurfaceVisibleActiveIncidentCount(snapshot = null) {
  if (!snapshot || typeof snapshot !== "object") return null;
  const alerts = Array.isArray(snapshot.alerts) ? snapshot.alerts : [];
  const visibleAlertCount = Math.max(0, alerts.length);
  const activeIncidentCount = Math.max(0, Number(snapshot.activeIncidentCount ?? snapshot.count ?? 0) || 0);
  if (visibleAlertCount > 0 && activeIncidentCount > 0) return Math.min(visibleAlertCount, activeIncidentCount);
  if (visibleAlertCount > 0) return visibleAlertCount;
  if (activeIncidentCount > 0 && snapshot.hasActiveAlerts === true) return activeIncidentCount;
  return null;
}

function getGridlyAwarenessBriefActiveState({ intel = {}, pulseModel = {} } = {}) {
  const snapshot = typeof window !== "undefined" && typeof window.getAlertsSurfaceSnapshot === "function"
    ? window.getAlertsSurfaceSnapshot()
    : null;
  const alertsSurfaceUserFacingClear = isGridlyAlertsSurfaceUserFacingClear(snapshot);
  const latestAlerts = typeof window !== "undefined" && Array.isArray(window.__gridlyLatestAlertsForRender)
    ? window.__gridlyLatestAlertsForRender
    : [];
  const alerts = alertsSurfaceUserFacingClear ? [] : (Array.isArray(snapshot?.alerts) ? snapshot.alerts : latestAlerts);
  const activeLocalizedAlertCount = alertsSurfaceUserFacingClear ? 0 : Math.max(0, Number(intel?.activeLocalizedAlertCount || 0));
  const activeIncidentCount = alertsSurfaceUserFacingClear ? 0 : Math.max(0, Number(
    snapshot?.activeIncidentCount
    ?? snapshot?.count
    ?? activeLocalizedAlertCount
  ) || 0);
  const alertVisibleActiveIncidentCount = alertsSurfaceUserFacingClear ? 0 : getGridlyAlertsSurfaceVisibleActiveIncidentCount(snapshot);
  const activeHazardSourceCount = alertsSurfaceUserFacingClear ? 0 : Math.max(0, Number(
    snapshot?.activeHazardSourceCount
    ?? pulseModel?.activeAwareness?.activeHazardCount
    ?? 0
  ) || 0);
  const activeAlertLength = alerts.length;
  const activeCountsAreClear = activeIncidentCount === 0
    && activeLocalizedAlertCount === 0
    && activeAlertLength === 0
    && activeHazardSourceCount === 0;
  return {
    activeCountsAreClear,
    activeIncidentCount,
    activeLocalizedAlertCount,
    activeAlertLength,
    activeHazardSourceCount,
    alertVisibleActiveIncidentCount,
    alertsSurfaceUserFacingClear
  };
}

function gridlyIsSanJacintoActiveRoadHazardWordingContext({ activeAwareness = {}, activeCount = 0, primary = "" } = {}) {
  const activeCountyId = typeof gridlyGetActiveCountyId === "function" ? gridlyGetActiveCountyId() : "";
  if (activeCountyId !== "san-jacinto-tx" || Number(activeCount || 0) <= 0) return false;
  const categoryText = [
    primary,
    activeAwareness?.resolvedCategory,
    activeAwareness?.topCategory,
    activeAwareness?.activeAwarenessSamples?.[0]?.resolvedCategory,
    activeAwareness?.activeAwarenessSamples?.[0]?.type,
    activeAwareness?.activeAwarenessSamples?.[0]?.report_type
  ].map((value) => String(value || "")).join(" ");
  return /\broad\s*(?:closed|closure)\b/i.test(categoryText);
}

function gridlySanJacintoActiveRoadHazardTopAwarenessText({ activeAwareness = {}, activeCount = 0, primary = "" } = {}) {
  if (!gridlyIsSanJacintoActiveRoadHazardWordingContext({ activeAwareness, activeCount, primary })) return "";
  const sampleRecord = activeAwareness?.activeAwarenessSamples?.[0] || activeAwareness?.topAwarenessSelectedLocationIntelligence?.item || activeAwareness || {};
  if (gridlyHasAcceptedSpecificRoadLabel(sampleRecord)) return safeDisplayText(primary, "");
  const text = safeDisplayText(primary, "");
  if (/^Road Closed\s+(?:near\s+Coldspring|on\s+San Jacinto County)\b/i.test(text)) return text.replace(/^Road Closed\s+(?:near\s+Coldspring|on\s+San Jacinto County)\b/i, "Road Closed reported nearby");
  return text || "Road Closed reported nearby";
}


function getGridlyQuietTopAwarenessFastPathStatus(intel = null) {
  const safeIntel = intel && typeof intel === "object" ? intel : null;
  const latestAlerts = typeof window !== "undefined" && Array.isArray(window.__gridlyLatestAlertsForRender)
    ? window.__gridlyLatestAlertsForRender
    : [];
  const activeReportCount = Array.isArray(activeReports)
    ? getGridlyAwarenessLifecycleActiveReports(activeReports).length
    : 0;
  const activeHazardCount = Array.isArray(activeHazards)
    ? getGridlyAwarenessLifecycleActiveHazards(activeHazards).length
    : 0;
  const activeLocalizedAlertCount = Math.max(0, Number(safeIntel?.activeLocalizedAlertCount || 0));
  const localizedSummaryCount = Array.isArray(safeIntel?.items) ? safeIntel.items.length : 0;
  const corridorClusterCount = Math.max(
    Array.isArray(safeIntel?.corridorClusters) ? safeIntel.corridorClusters.length : 0,
    Array.isArray(safeIntel?.sourceCorridorClusters) ? safeIntel.sourceCorridorClusters.length : 0
  );
  const activeAlertCount = Math.max(0, activeLocalizedAlertCount, latestAlerts.length, activeReportCount);
  const blockers = [];
  if (activeAlertCount > 0) blockers.push("active_alerts_present");
  if (activeHazardCount > 0) blockers.push("active_hazards_present");
  if (localizedSummaryCount > 0) blockers.push("localized_summaries_present");
  if (corridorClusterCount > 0) blockers.push("corridor_clusters_present");
  if (safeIntel?.hasActiveAlerts) blockers.push("intel_has_active_alerts");
  return {
    eligible: blockers.length === 0,
    blockers,
    activeAlertCount,
    activeHazardCount,
    activeReportCount,
    latestAlertCount: latestAlerts.length,
    activeLocalizedAlertCount,
    localizedSummaryCount,
    corridorClusterCount,
    expensiveSnapshotSkipped: true,
    unifiedIncidentScanSkipped: true
  };
}

function isGridlyQuietTopAwarenessFastPathEligible(intel = {}) {
  return getGridlyQuietTopAwarenessFastPathStatus(intel).eligible;
}

