function renderTrendingCrossings() {
  if (!els.trendingList) return;

  const incidents = getConsolidatedIncidents().slice(0, 3);

  if (!incidents.length) {
    els.trendingList.innerHTML = `<div class="trend-item muted">Nearby crossings look clear right now.</div>`;
    return;
  }

  els.trendingList.innerHTML = incidents
    .map((incident) => {
      const latest = incident.latestReport;
      const confidenceLabel = getCrossingConfidenceLabel(latest, incident.count);
      const freshnessLabel = getFreshnessLabel(latest);
      const confirmationLabel = getDriverConfirmationLabel(incident.count);

      const className =
        latest.type === "cleared"
          ? "clear"
          : latest.severity === "high"
          ? "hot"
          : "";

      return `
        <button class="trend-item ${className}" type="button" data-action="zoom-crossing" data-crossing-id="${sanitizeText(incident.crossingId)}">
          <strong>${sanitizeText(incident.crossingName)}</strong>
          <p>${sanitizeText(freshnessLabel)} · ${sanitizeText(confidenceLabel)} · ${sanitizeText(confirmationLabel)}</p>
        </button>
      `;
    })
    .join("");
}

function updateMobileAlertsMirror() {
  if (!els.mobileAlertsMirror) return;

  const incidents = getConsolidatedIncidents();

  if (!incidents.length) {
    els.mobileAlertsMirror.textContent =
      "Route conditions currently appear calm.";
    gridlyEnforceCanonicalPresentationOnVisibleAlertCards("updateMobileAlertsMirror");
    return;
  }

  const top = incidents[0];
  const latest = top.latestReport;

  els.mobileAlertsMirror.textContent =
    `${top.crossingName}: ${getReportCopy(latest.type).label} · ${top.count} confirmation${top.count === 1 ? "" : "s"} · newest ${top.newestMinutes} min ago.`;
  gridlyEnforceCanonicalPresentationOnVisibleAlertCards("updateMobileAlertsMirror");
}

function updateTrustStats() {
  const latestReports = getLatestReportsByCrossing();
  const active = latestReports.filter((report) => !report.expired);

  const lastReport = [...activeReports].sort((a, b) => {
    return new Date(b.submittedAt || 0) - new Date(a.submittedAt || 0);
  })[0];

  safeText("reportDecayStatus", `${REPORT_EXPIRATION_MINUTES} min expiry`);
  safeText("lastReportTime", lastReport ? `${lastReport.minutesAgo} min ago` : "None yet");
  safeText("nearbyAlertCount", active.filter((report) => getIncidentLifecycleState(report) === "active").length);
}

function compareReportsByRecency(a, b) {
  const timeDiff = new Date(b.submittedAt || 0).getTime() - new Date(a.submittedAt || 0).getTime();
  if (timeDiff !== 0) return timeDiff;
  if (a.type === "cleared" && b.type !== "cleared") return -1;
  if (b.type === "cleared" && a.type !== "cleared") return 1;
  return String(b.id || "").localeCompare(String(a.id || ""));
}

function normalizeCrossingName(value) {
  return String(value || "")
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, " ")
    .trim();
}

function getReportLocationKey(report) {
  if (!report || typeof report !== "object") return "";

  if (report.crossingId != null && String(report.crossingId).trim()) {
    return `id:${String(report.crossingId).trim()}`;
  }

  const normalizedName = normalizeCrossingName(report.crossingName || report.crossing || report.locationName);
  if (normalizedName) return `name:${normalizedName}`;

  const lat = Number(report.lat);
  const lng = Number(report.lng);
  if (Number.isFinite(lat) && Number.isFinite(lng)) {
    return `ll:${lat.toFixed(4)},${lng.toFixed(4)}`;
  }

  return "";
}

function getLatestReportStateByLocation(reports = activeReports) {
  const latestByLocation = new Map();

  (Array.isArray(reports) ? reports : [])
    .filter((report) => report && !report.expired)
    .sort(compareReportsByRecency)
    .forEach((report) => {
      const key = getReportLocationKey(report);
      if (!key || latestByLocation.has(key)) return;
      latestByLocation.set(key, report);
    });

  return latestByLocation;
}

function getLatestReportForCrossing(crossingId) {
  const locationKey = getReportLocationKey({ crossingId });
  return getLatestReportStateByLocation().get(locationKey);
}

function getLatestReportsByCrossing() {
  return [...getLatestReportStateByLocation().values()];
}

function getConsolidatedIncidents() {
  const grouped = new Map();
  let warnedMalformedReport = false;
  const latestByLocation = getLatestReportStateByLocation();

  activeReports
    .filter((report) => !report.expired)
    .forEach((report) => {
      const key = getReportLocationKey(report);
      if (!key) {
        if (!warnedMalformedReport) {
          console.warn("Consolidated incidents received malformed report data (missing grouping key).", report);
          warnedMalformedReport = true;
        }
        return;
      }

      if (!grouped.has(key)) {
        grouped.set(key, {
          key,
          crossingId: report.crossingId != null ? String(report.crossingId) : key,
          crossingName: report.crossingName || "Unknown Crossing",
          reports: []
        });
      }

      grouped.get(key).reports.push(report);
    });

  return [...grouped.values()]
    .map((incident) => {
      const reports = Array.isArray(incident.reports) ? incident.reports : [];
      const sorted = [...reports].sort(compareReportsByRecency);
      const latestReport = latestByLocation.get(incident.key) || sorted[0];

      return {
        crossingId: incident.crossingId,
        crossingName: incident.crossingName,
        reports: sorted,
        count: sorted.length,
        latestReport,
        newestMinutes: sorted.length ? Math.min(...sorted.map((r) => r.minutesAgo)) : 0,
        oldestMinutes: sorted.length ? Math.max(...sorted.map((r) => r.minutesAgo)) : 0
      };
    })
    .sort((a, b) => {
      const severityScore = (incident) => {
        const report = incident.latestReport;
        if (getIncidentLifecycleState(report) !== "active") return 0;
        if (report.severity === "high") return 3;
        if (report.severity === "moderate") return 2;
        return 1;
      };

      return severityScore(b) - severityScore(a) || b.count - a.count || a.newestMinutes - b.newestMinutes;
    });

  highlightNearestCrossingOnFirstLoad();
}

function getReportCountForCrossing(crossingId) {
  const locationKey = getReportLocationKey({ crossingId });
  return activeReports.filter(
    (report) => !report.expired && getReportLocationKey(report) === locationKey
  ).length;
}

function getDriverConfirmationLabel(count) {
  if (count <= 0) return "Needs confirmation";
  if (count === 1) return "1 driver confirmation";
  return `${count} driver confirmations`;
}

function getCrossingConfidenceLabel(report, count) {
  if (!report) return "Awaiting additional reports";
  if (isClearedReportType(report.type)) return "Recently cleared";
  if (count >= 2 && report.minutesAgo <= 60) return "Community confirmed";
  if (report.minutesAgo > REPORT_EXPIRATION_MINUTES) return "Conditions may have changed";
  return "Awaiting additional reports";
}

function getFreshnessLabel(report) {
  if (!report) return "Needs confirmation";
  if (report.minutesAgo <= 1) return "Last confirmed just now";
  return `Last confirmed ${report.minutesAgo} min ago`;
}


function formatGridlyAlertsFreshnessLine(value, fallback = "") {
  const minutes = Number(value?.minutesAgo ?? value?.newestMinutes ?? value?.age_minutes ?? value);
  if (!Number.isFinite(minutes)) return String(fallback || "Updated just now").split("•")[0].trim().replace(/^Last confirmed/i, "Updated").replace(/^Reported/i, "Updated");
  if (minutes <= 1) return "Updated just now";
  const rounded = Math.max(0, Math.round(minutes));
  return `Updated ${rounded} minute${rounded === 1 ? "" : "s"} ago`;
}

function formatGridlyAlertsTrustLine({ report = null, count = 0, fallback = "" } = {}) {
  const normalizedFallback = String(fallback || "").trim();
  if (report && isClearedReportType(report.type)) return "Recently cleared";
  if (Number(count) >= 2) return "Community confirmed";
  if (report && Number(report.minutesAgo) > REPORT_EXPIRATION_MINUTES) return "Most recent report indicates conditions may have changed";
  return (normalizedFallback.split("•").map((part) => part.trim()).find((part) => /awaiting|confirmed|cleared|changed/i.test(part)) || "Awaiting additional reports").replace(/^Reported/i, "Updated");
}

function getReportStateLabel(report) {
  if (!report) return "Needs confirmation";
  if (report.expired) return "Expired report";
  const lifecycleState = getIncidentLifecycleState(report);
  if (lifecycleState === "recently_cleared" || lifecycleState === "cleared") return "Cleared by drivers";
  return "Active shared report";
}

function isActiveReportType(type) {
  const normalized = String(type || "").trim().toLowerCase();
  return ["blocked", "heavy", "other", "delayed", "delay", "rail_delay", "rail_blocked"].includes(normalized) || Object.prototype.hasOwnProperty.call(HAZARD_TYPES, normalized);
}

function isClearedReportType(type) {
  const normalized = String(type || "").trim().toLowerCase();
  return normalized === "cleared" || normalized === "hazard_cleared";
}

function isRecentlyCleared(report, now = Date.now()) {
  if (!report) return false;
  const reportType = report.type || report.report_type || report.reportType || report.raw?.type || report.raw?.report_type || report.status || report.lifecycleState || report.lifecycle;
  if (!isClearedReportType(reportType)) return false;
  const submittedAtMs = new Date(report.submittedAt || report.submitted_at || report.updated_at || report.updatedAt || report.created_at || report.createdAt || 0).getTime();
  if (!Number.isFinite(submittedAtMs) || submittedAtMs <= 0) return false;
  return now - submittedAtMs <= RECENTLY_CLEARED_WINDOW_MINUTES * 60000;
}

function getIncidentLifecycleState(report, now = Date.now()) {
  if (!report) return "inactive";
  const explicitState = String(report.status || report.lifecycleState || report.lifecycle || report.state || report.raw?.status || report.raw?.lifecycleState || report.raw?.lifecycle || report.raw?.state || "").trim().toLowerCase();
  const reportType = report.type || report.report_type || report.reportType || report.raw?.type || report.raw?.report_type || report.raw?.reportType || explicitState;
  if (isClearedReportType(reportType) || isClearedReportType(explicitState) || ["cleared", "recently_cleared", "historical", "stale"].includes(explicitState)) {
    return isRecentlyCleared({ ...report, type: reportType }, now) ? "recently_cleared" : "cleared";
  }
  if (report.expired || explicitState === "expired" || explicitState === "inactive") return "inactive";
  if (explicitState === "active") return "active";
  if (isActiveReportType(reportType)) return "active";
  return "inactive";
}


function gridlyCommunityTrustAudit(options = {}) {
  const nowMs = Number.isFinite(Number(options?.nowMs)) ? Number(options.nowMs) : Date.now();
  const generatedAt = new Date(nowMs).toISOString();
  const safeActiveReports = Array.isArray(activeReports) ? activeReports : [];
  const safeActiveHazards = Array.isArray(activeHazards) ? activeHazards : [];
  const safeRecentlyClearedRoadHazards = Array.isArray(recentlyClearedRoadHazards) ? recentlyClearedRoadHazards : [];
  const lifecycleStates = new Set([
    ...Object.keys(GRIDLY_HAZARD_TRUST_LABELS || {}),
    ...Object.values(GRIDLY_HAZARD_TRUST_LABELS || {}),
    ...GRIDLY_HAZARD_LIFECYCLE_FRAMEWORK_STATES,
    "active",
    "inactive",
    "recently_cleared",
    "cleared",
    "expired",
    "stale"
  ]);
  const visibleTrustStates = [
    "Needs confirmation",
    "Recently reported",
    "Confirmed by drivers",
    "Active shared report",
    "Cleared by drivers",
    "Cleared",
    "Low",
    "Medium",
    "High",
    "Stale",
    "Recently Cleared",
    "Expired report"
  ];
  const dormantTrustStates = [
    "Community confirmed",
    "Awaiting additional reports",
    "Recently cleared trust weighting",
    "Conflicting reports surfaced",
    "Clear confirmation required",
    "Historical event"
  ];
  const activeReportSamples = safeActiveReports.slice(0, 12).map((report) => {
    const count = gridlyCountCrossingConfirmations(report?.crossingId || report?.crossing_id, safeActiveReports);
    return {
      id: report?.id || null,
      type: report?.type || report?.report_type || null,
      crossingId: report?.crossingId || report?.crossing_id || null,
      lifecycleState: getIncidentLifecycleState(report, nowMs),
      confirmationCount: count,
      confidenceLabel: getCrossingConfidenceLabel(report, count),
      latestStateWins: true
    };
  });
  const activeHazardSamples = safeActiveHazards.slice(0, 12).map((hazard, index) => {
    const lifecycle = typeof gridlyClassifyHazardLifecycleFrameworkRecord === "function"
      ? gridlyClassifyHazardLifecycleFrameworkRecord({ record: hazard, sourceKind: "activeHazards", index, sourceHazards: safeActiveHazards, sourceReports: safeActiveReports, nowMs })
      : null;
    const matchingClear = typeof gridlyFindRecentClearForRoadHazard === "function"
      ? gridlyFindRecentClearForRoadHazard(hazard, [...safeActiveHazards, ...safeRecentlyClearedRoadHazards], gridlyBuildRecentRoadClearIndex([...safeActiveHazards, ...safeRecentlyClearedRoadHazards], nowMs), nowMs)
      : null;
    return {
      id: hazard?.id || hazard?.report_id || hazard?.reportId || null,
      type: hazard?.type || hazard?.report_type || null,
      clusterKey: typeof getHazardClusterKey === "function" ? getHazardClusterKey(hazard) : null,
      lifecycleState: lifecycle?.lifecycleState || (typeof gridlyClassifyHazardLifecycle === "function" ? gridlyClassifyHazardLifecycle(hazard, { nowMs })?.lifecycleState : null),
      trustLabel: lifecycle?.trustLabel || null,
      confirmationCount: lifecycle?.confirmationCount ?? gridlyHazardLifecycleConfirmationCount(hazard, "activeHazards", safeActiveHazards, safeActiveReports),
      suppressedByRecentClear: Boolean(matchingClear),
      matchedClearId: matchingClear?.id || matchingClear?.report_id || matchingClear?.reportId || null
    };
  });
  const roadClearSuppressionTrace = typeof gridlyBuildRoadClearedLifecycleTrace === "function"
    ? gridlyBuildRoadClearedLifecycleTrace({ reports: safeActiveReports, hazards: [...safeActiveHazards, ...safeRecentlyClearedRoadHazards], nowMs })
    : null;
  const lifecycleAudit = typeof gridlyHazardLifecycleAudit === "function"
    ? gridlyHazardLifecycleAudit({ auditOnly: true, nowMs })
    : null;
  return {
    available: true,
    auditVersion: "V247.0",
    generatedAt,

    confirmationModelDetected: true,
    clearModelDetected: true,
    conflictResolutionDetected: true,

    activeConfirmationThreshold: {
      roadHazardConfirmed: 2,
      roadHazardConfidenceScoreBoosts: { oneReport: 1, twoReports: 2, threeReports: 3 },
      crossingMediumConfidence: 2,
      crossingHighConfidence: 3,
      crossingHighFreshnessMinutes: 30,
      crossingMediumFreshnessMinutes: 60,
      explicitConfirmedFieldsAlsoConfirm: ["confirmed", "verified", "isVerified", "status/lifecycleState/verificationStatus/confidence contains confirmed or verified", "official/system/FRA/TxDOT source"]
    },
    clearConfirmationThreshold: {
      roadHazardClearReportsRequired: 1,
      crossingClearReportsRequired: 1,
      requiresAdditionalConfirmation: false,
      roadHazardClearWindowMinutes: RECENTLY_CLEARED_WINDOW_MINUTES,
      crossingRecentlyClearedWindowMinutes: RECENTLY_CLEARED_WINDOW_MINUTES
    },

    visibleTrustStates,
    dormantTrustStates,

    activeVsClearBehavior: {
      roadHazards: {
        grouping: "hazard type plus tight 0.0001-degree coordinate bucket, with incident/source id and same-road/type proximity matching for clear suppression",
        activeConfirmation: "same active hazard cluster count is used as confirmation count; framework treats two or more matching reports as CONFIRMED",
        clearHandling: "a hazard_cleared row is a clearing signal; one recent matching clear suppresses matching active road hazards",
        latestStateRule: "newest matching lifecycle state wins; if a newer active report follows a clear, active can supersede the clear",
        conflictSurfacedToUsers: false,
        samples: activeHazardSamples
      },
      crossings: {
        grouping: "crossing id, normalized crossing name, then 0.0001-degree coordinate fallback",
        activeConfirmation: "all non-cleared reports at the same crossing are counted; two reports within 60 minutes produce Medium, three within 30 minutes produce High",
        clearHandling: "a cleared report is a clearing signal; latest report per crossing controls visible state, with cleared winning same-timestamp tie-breaks",
        latestStateRule: "latest non-expired report by submittedAt wins for state; one newer clear can make a crossing incident cleared even if older active reports remain grouped",
        conflictSurfacedToUsers: false,
        samples: activeReportSamples
      },
      examples: {
        "1 active + 1 newer clear": "clear wins for matching crossing/road hazard; active road hazard suppressed if the clear is recent and matching",
        "2 active + 1 newer clear": "clear still wins; active count does not require multiple clears",
        "3 active + 2 clear": "newest matching lifecycle event wins; multiple clears are not separately weighted",
        "clear older than active": "newer active can supersede older clear",
        "crossing blocked + crossing clear": "latest report at crossing determines active versus cleared",
        "road closed + road clear": "matching newer hazard_cleared suppresses active road_closed at the same matched location/type"
      }
    },

    lifecycleInteractions: {
      active: "Active reports remain active while unexpired and classified ACTIVE, NEEDS_CONFIRMATION, or CONFIRMED.",
      confirmed: "Hazard lifecycle framework upgrades active/non-stale/non-historical hazards to CONFIRMED at two or more confirmations or recent reconfirmation; crossing confidence labels use Medium/High rather than a lifecycle state.",
      recentlyCleared: "Cleared rows within the recently-cleared window are retained for Recently Cleared visibility and can suppress matching active road hazards.",
      cleared: "Clear reports are classified cleared after the recent window; they are not active incident sources.",
      stale: "Lifecycle classifiers mark stale by age, and active incident filtering excludes STALE hazard lifecycle records.",
      expired: "Expired reports are excluded from latest state, consolidated incident grouping, and active hazard incident generation.",
      currentLifecycleStatesDetected: [...lifecycleStates],
      hazardLifecycleAudit: lifecycleAudit,
      roadClearSuppressionTrace
    },

    risks: [
      "One newer matching clear report can suppress multiple older active road hazard reports; no multi-user clear threshold is enforced.",
      "One newer crossing clear report can make a crossing appear cleared even when older active reports remain in the same incident group.",
      "Conflicting active-versus-clear reports are resolved internally by recency and are not surfaced as a user-facing conflict state.",
      "Hazard confirmation can be inferred from two matching reports, but clear reports are not weighted against active report counts.",
      "Crossing confidence uses report count and freshness labels, but the latest clear state can override prior active confidence language.",
      "A stale active report can remain visible until lifecycle age rules, expiration, or a newer clear suppresses it; construction does not auto-expire in the lifecycle rules.",
      "Road clear matching includes same-road/type proximity within 12 hours, which may suppress nearby but distinct hazards on the same road if location text is broad."
    ],

    findings: [
      "Confirmation is category-specific for road hazards because the hazard cluster key includes hazard type; crossing confirmation is crossing-location-specific.",
      "Road hazard confirmation is location-based using tight coordinate buckets and matching keys, not an explicit vote ledger.",
      "Crossing confirmation is report-count based at a crossing and uses freshness thresholds for Low/Medium/High labels.",
      "Clear handling is asymmetric: one clear report can change/suppress active state, while active confirmation can require two or three reports for stronger trust labels.",
      "The product has visible labels for Needs confirmation, Confirmed by drivers, Recently Cleared, Cleared, Active shared report, Low/Medium/High, Stale, and Expired report; Community confirmed is not the detected literal label.",
      "The audit helper is read-only and does not create reports, delete reports, alter Supabase, alter route logic, or change lifecycle thresholds."
    ],

    recommendations: [
      "For V247.1, add an explicit conflict state when active and clear reports coexist inside the same matching window.",
      "Consider separate clear-confirmation thresholds or source weighting for high-impact categories such as road_closed, flooding, and blocked crossings.",
      "Expose active count versus clear count and newest timestamps in trust copy before claiming an incident is cleared.",
      "Avoid high-certainty language unless the state is official, multi-user confirmed, or recently reconfirmed.",
      "Review same-road/type clear proximity suppression to reduce false clearing of distinct nearby hazards.",
      "Document category-specific lifecycle thresholds and user-facing confidence labels in a product trust contract before changing logic."
    ],

    protectedSystemsModified: false,
    routeLogicModified: false,
    awarenessFilteringModified: false,
    supabaseModified: false,

    canProceedToV247_1: true
  };
}

if (typeof window !== "undefined") {
  window.gridlyCommunityTrustAudit = gridlyCommunityTrustAudit;
}

function calculateBaseRisk(props, index) {
  let score = 18;

  const traffic = Number(props.aadt || props.avgdailytraffic || props.traffic || 0);
  const trains = Number(props.daythrutrain || props.totaltrains || props.trains || 0);

  if (traffic > 5000) score += 20;
  if (traffic > 10000) score += 12;
  if (trains > 5) score += 14;
  if (trains > 15) score += 14;

  score += index % 7;

  return Math.min(score, 82);
}

function handleCrossingSearch() {
  if (!els.crossingSearch || !els.searchResults) return;

  const query = els.crossingSearch.value.trim().toLowerCase();

  if (!query) {
    els.searchResults.innerHTML = "";
    return;
  }

  const matches = crossings
    .filter((crossing) => `${crossing.name} ${crossing.railroad}`.toLowerCase().includes(query))
    .slice(0, 6);

  if (!matches.length) {
    els.searchResults.innerHTML = `
      <button class="search-result-btn" type="button">
        No matching crossing found
        <span>Try a street name, crossing name, or railroad.</span>
      </button>
    `;
    return;
  }

  els.searchResults.innerHTML = matches
    .map(
      (crossing) => `
        <button class="search-result-btn" type="button" data-action="zoom-crossing" data-crossing-id="${sanitizeText(crossing.id)}">
          ${sanitizeText(crossing.name)}
          <span>${sanitizeText(crossing.railroad)} · Click to zoom and report from map</span>
        </button>
      `
    )
    .join("");
}

function findNearestCrossings(lat, lng, count = 5) {
  return crossings
    .filter(isGridlyReportableCrossing)
    .map((crossing) => ({
      ...crossing,
      distance: haversineDistance(lat, lng, crossing.lat, crossing.lng)
    }))
    .sort((a, b) => a.distance - b.distance)
    .slice(0, count);
}

function getDistanceMiles(lat1, lng1, lat2, lng2) {
  return haversineDistance(lat1, lng1, lat2, lng2);
}

function haversineDistance(lat1, lng1, lat2, lng2) {
  const r = 3958.8;
  const dLat = toRad(lat2 - lat1);
  const dLng = toRad(lng2 - lng1);

  const a =
    Math.sin(dLat / 2) ** 2 +
    Math.cos(toRad(lat1)) * Math.cos(toRad(lat2)) * Math.sin(dLng / 2) ** 2;

  return 2 * r * Math.asin(Math.sqrt(a));
}

function calculateDistanceKm(lat1, lng1, lat2, lng2) {
  return haversineDistance(lat1, lng1, lat2, lng2) * 1.60934;
}

function isPointNearCorridor(lat, lng, startLat, startLng, endLat, endLng, thresholdKm = 2) {
  const samples = 12;
  let minDistanceKm = Infinity;
  for (let i = 0; i <= samples; i += 1) {
    const t = i / samples;
    const sampleLat = startLat + (endLat - startLat) * t;
    const sampleLng = startLng + (endLng - startLng) * t;
    const distanceKm = calculateDistanceKm(lat, lng, sampleLat, sampleLng);
    if (distanceKm < minDistanceKm) minDistanceKm = distanceKm;
  }
  return minDistanceKm <= thresholdKm;
}

function toRad(value) {
  return (value * Math.PI) / 180;
}

function flashButton(button, message) {
  if (!button) return;

  const original = button.textContent;
  button.textContent = message;

  setTimeout(() => {
    button.textContent = original;
  }, 1300);
}

function getParticipationAcknowledgementCopy(kind, contextLabel = "") {
  const label = String(contextLabel || "").trim();
  const contextSuffix = label ? ` ${label}.` : "";
  const acknowledgementKind = String(kind || "report").trim().toLowerCase();

  if (acknowledgementKind === "confirm") {
    return `Thanks for confirming. Your update helps nearby drivers know what to expect.${contextSuffix}`;
  }

  if (acknowledgementKind === "clear") {
    return `Thanks for the update. Drivers nearby can see this may be moving again.${contextSuffix}`;
  }

  return `Thanks for helping your community. Your report is now part of local awareness.${contextSuffix}`;
}

function getParticipationAcknowledgementKind(reportType = "", confidence = "") {
  const normalizedType = String(reportType || "").trim().toLowerCase();
  const normalizedConfidence = String(confidence || "").trim().toLowerCase();

  if (normalizedType === "cleared" || normalizedType === "hazard_cleared" || normalizedConfidence.includes("cleared") || normalizedConfidence.includes("clear")) {
    return "clear";
  }

  if (normalizedConfidence.includes("confirm") || normalizedConfidence.includes("still active") || normalizedConfidence.includes("still there")) {
    return "confirm";
  }

  return "report";
}

function runUnifiedReportSuccessLifecycle({
  flow = "crossing",
  successType = "",
  successMessage = getParticipationAcknowledgementCopy("report"),
  buttonEl = null,
  originalButtonText = "",
  onButtonReset = null,
  popupClose = null
} = {}) {
  if (reportSuccessLifecycleTimer) clearTimeout(reportSuccessLifecycleTimer);
  if (reportButtonResetTimer) clearTimeout(reportButtonResetTimer);

  lastReportSuccessStartedAt = Date.now();
  lastPopupReportingStartedAt = flow === "crossing" ? lastReportSuccessStartedAt : lastPopupReportingStartedAt;
  lastReportSuccessCompletedAt = 0;
  lastReportSuccessType = successType || "";
  lastReportSuccessFlow = flow || "";
  const popupFlowActive = flow === "crossing";
  popupReportingLifecycleActive = popupFlowActive;
  liveReportingTemporarilySuppressed = popupFlowActive;
  if (popupFlowActive && els.reportSection?.open) els.reportSection.open = false;
  setLiveReportingDrawerSuppression(popupFlowActive);
  document.body?.classList.toggle("popup-reporting-lifecycle-active", popupFlowActive);
  document.body?.classList.toggle("popup-reporting-suppress-live-panel", popupFlowActive);
  lastSuccessSurfaceOwner = popupFlowActive ? "crossing_popup" : "live_reporting_panel";

  if (buttonEl) {
    buttonEl.classList.remove("is-submitting");
    buttonEl.classList.add("is-success");
    buttonEl.textContent = "Shared ✓";
  }

  setConfirmation(successMessage, "success", { durationMs: REPORT_SUCCESS_HOLD_MS });

  reportSuccessLifecycleTimer = setTimeout(() => {
    if (typeof popupClose === "function") {
      popupClose();
      lastPopupClosedAt = Date.now();
    }
    if (popupFlowActive) {
      popupReportingLifecycleActive = false;
      liveReportingTemporarilySuppressed = false;
      lastPopupReportingCompletedAt = Date.now();
      setLiveReportingDrawerSuppression(false);
      document.body?.classList.remove("popup-reporting-lifecycle-active");
      document.body?.classList.remove("popup-reporting-suppress-live-panel");
    }
  }, REPORT_POPUP_CLOSE_DELAY_MS);

  reportButtonResetTimer = setTimeout(() => {
    if (buttonEl) {
      buttonEl.classList.remove("is-success");
      if (typeof onButtonReset === "function") {
        onButtonReset();
      } else {
        buttonEl.textContent = originalButtonText;
      }
    }
    lastReportSuccessCompletedAt = Date.now();
    lastReportingResetAt = lastReportSuccessCompletedAt;
  }, REPORT_BUTTON_SUCCESS_MS);
}

function setConfirmation(message, type = "success", options = {}) {
  const { persist = false, durationMs = REPORT_CONFIRMATION_READ_MS } = options || {};
  updateReportingState({
    lastReportMessage: message || "",
    lastReportError: type === "error" ? message || "" : ""
  });
  if (popupReportingLifecycleActive && reportingState.submissionInProgress && type === "success") return;
  mirrorReportConfirmationToPortraitV2(message, type, { durationMs, persist });
  if (!els.reportConfirmation) return;

  if (reportConfirmationDismissTimer) clearTimeout(reportConfirmationDismissTimer);
  if (reportConfirmationFadeTimer) clearTimeout(reportConfirmationFadeTimer);
  els.reportConfirmation.classList.remove("is-fading");

  els.reportConfirmation.classList.remove("success", "error", "info");
  if (type) els.reportConfirmation.classList.add(type);
  els.reportConfirmation.textContent = message || "";

  if (persist || !message || type === "error") return;

  reportConfirmationFadeTimer = setTimeout(() => {
    els.reportConfirmation?.classList.add("is-fading");
  }, Math.max(800, durationMs - REPORT_CONFIRMATION_FADE_MS));

  reportConfirmationDismissTimer = setTimeout(() => {
    if (!els.reportConfirmation) return;
    els.reportConfirmation.classList.remove("is-fading");
    els.reportConfirmation.classList.remove("success");
    els.reportConfirmation.textContent = "";
    updateReportingState({ lastReportMessage: "" });
  }, durationMs);
}

function showShareCard() {
  els.shareCard?.classList.add("visible");
}

async function shareGridly() {
  const shareData = {
    title: "Gridly",
    text: "Check live railroad crossing reports before you go.",
    url: "https://dbmaps.github.io/liberty-county-map/"
  };

  if (navigator.share) {
    try {
      await navigator.share(shareData);
      setConfirmation("Thanks for sharing Gridly.", "success");
      return;
    } catch {
      return;
    }
  }

  try {
    await navigator.clipboard.writeText(shareData.url);
    setConfirmation("Gridly link copied to clipboard.", "success");
  } catch {
    setConfirmation("Share link: https://dbmaps.github.io/liberty-county-map/", "success");
  }
}

function setSync(value) {
  safeText("syncStatus", value);
}

function safeText(id, value) {
  if (shouldSuppressGridlyDashboardSectionPassiveTextUpdate(id)) return;
  const displayValue = normalizeGridlyUserFacingRoadText(value);
  if (!els[id]) els[id] = document.getElementById(id);
  if (els[id]) els[id].textContent = displayValue;
  document.querySelectorAll(`[data-bind-text="${id}"]`).forEach((node) => {
    node.textContent = displayValue;
  });
}

function gridlyHealthCheck() {
  const ids = [...document.querySelectorAll("[id]")].map((node) => node.id);
  const dupes = ids.filter((id, index) => ids.indexOf(id) !== index);
  if (isGridlyExplicitDebugModeEnabled()) {
    if (dupes.length) console.warn("[Gridly health] Duplicate IDs:", [...new Set(dupes)]);
    ["map", "dashboardSection", "reportSection", "alertsSection"].forEach((id) => {
      if (!document.getElementById(id)) console.warn(`[Gridly health] Missing required element #${id}`);
    });
  }
}
window.gridlyHealthCheck = gridlyHealthCheck;

function sanitizeText(value) {
  return cleanupGridlyDisplayEncodingArtifacts(value)
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#039;");
}
/* =========================================================
   GRIDLY V12.3.1 — SMART CROSSING REVIEW MODE
   Multi-decision review tool
   Activate with: ?review=1
========================================================= */

const REVIEW_MODE_ACTIVE = new URLSearchParams(window.location.search).get("review") === "1";
const REVIEW_STORAGE_KEY = "gridlyCrossingReviewDecisionsV1231";

let crossingReviewDecisions = JSON.parse(localStorage.getItem(REVIEW_STORAGE_KEY) || "{}");

const originalLoadCrossingsV1231 = loadCrossings;

loadCrossings = async function () {
  await originalLoadCrossingsV1231();

  if (REVIEW_MODE_ACTIVE) {
    initCrossingReviewMode();
  }
};

function initCrossingReviewMode() {
  injectCrossingReviewStyles();
  buildCrossingReviewPanel();
  safeText("mapTrustNote", "Crossing Review Mode is active. Normal users do not see this.");
}

function getReviewDecision(crossingId) {
  return crossingReviewDecisions[String(crossingId)] || {
    visibility: "unreviewed",
    renameNeeded: false,
    needsCheck: false,
    localName: "",
    notes: ""
  };
}

function saveReviewDecision(crossingId, updates) {
  crossingReviewDecisions[String(crossingId)] = {
    ...getReviewDecision(crossingId),
    ...updates,
    reviewedAt: new Date().toISOString()
  };

  localStorage.setItem(REVIEW_STORAGE_KEY, JSON.stringify(crossingReviewDecisions, null, 2));
  buildCrossingReviewPanel();
}

function buildCrossingReviewPanel() {
  const existing = document.getElementById("crossingReviewPanel");
  if (existing) existing.remove();

  const reviewed = Object.values(crossingReviewDecisions);
  const keepCount = reviewed.filter((d) => d.visibility === "keep").length;
  const hideCount = reviewed.filter((d) => d.visibility === "hide").length;
  const renameCount = reviewed.filter((d) => d.renameNeeded).length;
  const checkCount = reviewed.filter((d) => d.needsCheck).length;

  const panel = document.createElement("div");
  panel.id = "crossingReviewPanel";
  panel.className = "crossing-review-panel";

  panel.innerHTML = `
    <div class="review-header">
      <div>
        <strong>Gridly V12.3.1 Review Mode</strong>
        <span>${crossings.length} FRA crossings loaded</span>
      </div>
      <button type="button" onclick="exportCrossingReviewDecisions()">Export JSON</button>
    </div>

    <div class="review-counts">
      <span>Keep: ${keepCount}</span>
      <span>Hide: ${hideCount}</span>
      <span>Rename: ${renameCount}</span>
      <span>Check: ${checkCount}</span>
    </div>

    <div class="review-help">
      Visibility and rename are now separate. You can mark a crossing as Hidden + Rename, Kept + Rename, or Needs Check.
    </div>

    <div class="review-list">
      ${crossings
        .slice()
        .sort((a, b) => a.name.localeCompare(b.name))
        .map((crossing) => renderReviewCrossingItem(crossing))
        .join("")}
    </div>
  `;

  document.body.appendChild(panel);
}

function renderReviewCrossingItem(crossing) {
  const decision = getReviewDecision(crossing.id);

  const statusParts = [];

  if (decision.visibility === "keep") statusParts.push("Kept");
  if (decision.visibility === "hide") statusParts.push("Hidden");
  if (decision.visibility === "unreviewed") statusParts.push("Unreviewed");
  if (decision.renameNeeded) statusParts.push("Rename");
  if (decision.needsCheck) statusParts.push("Needs Check");
  if (decision.localName) statusParts.push("Local Name Added");

  const statusText = statusParts.join(" + ");

  return `
    <div class="review-item ${sanitizeText(decision.visibility)} ${decision.renameNeeded ? "rename" : ""} ${decision.needsCheck ? "needs_check" : ""}" id="review-${sanitizeText(crossing.id)}">
      <div class="review-title">
        <strong>${sanitizeText(crossing.name)}</strong>
        <span>${sanitizeText(crossing.railroad)}</span>
      </div>

      <div class="review-meta">
        ID: ${sanitizeText(crossing.id)}<br>
        ${crossing.lat.toFixed(6)}, ${crossing.lng.toFixed(6)}
      </div>

      <input
        type="text"
        placeholder="Local nickname / better public name"
        value="${sanitizeText(decision.localName || "")}"
        onchange="setCrossingNickname('${sanitizeText(crossing.id)}', this.value)"
      />

      <textarea
        placeholder="Notes, reason, local context"
        onchange="setCrossingNotes('${sanitizeText(crossing.id)}', this.value)"
      >${sanitizeText(decision.notes || "")}</textarea>

      <div class="review-actions">
        <button onclick="setCrossingVisibility('${sanitizeText(crossing.id)}', 'keep')">Keep</button>
        <button onclick="setCrossingVisibility('${sanitizeText(crossing.id)}', 'hide')">Hide</button>
        <button onclick="toggleCrossingRename('${sanitizeText(crossing.id)}')">Rename</button>
        <button onclick="toggleNeedsCheck('${sanitizeText(crossing.id)}')">Needs Check</button>
        <button onclick="zoomToCrossing('${sanitizeText(crossing.id)}')">Zoom</button>
      </div>

      <div class="review-status">Status: ${sanitizeText(statusText)}</div>
    </div>
  `;
}

window.setCrossingVisibility = function (crossingId, visibility) {
  saveReviewDecision(crossingId, { visibility });
};

window.toggleCrossingRename = function (crossingId) {
  const decision = getReviewDecision(crossingId);
  saveReviewDecision(crossingId, { renameNeeded: !decision.renameNeeded });
};

window.toggleNeedsCheck = function (crossingId) {
  const decision = getReviewDecision(crossingId);
  saveReviewDecision(crossingId, { needsCheck: !decision.needsCheck });
};

window.setCrossingNickname = function (crossingId, value) {
  const trimmed = value.trim();

  saveReviewDecision(crossingId, {
    localName: trimmed,
    renameNeeded: trimmed.length > 0 ? true : getReviewDecision(crossingId).renameNeeded
  });

  highlightNearestCrossingOnFirstLoad();
};

window.setCrossingNotes = function (crossingId, value) {
  saveReviewDecision(crossingId, {
    notes: value.trim()
  });

  highlightNearestCrossingOnFirstLoad();
};

window.exportCrossingReviewDecisions = function () {
  const output = JSON.stringify(crossingReviewDecisions, null, 2);

  navigator.clipboard
    .writeText(output)
    .then(() => setConfirmation("Crossing review JSON copied to clipboard.", "success"))
    .catch(() => {
      console.log("Gridly Crossing Review Export:", output);
      setConfirmation("Export printed to console. Open DevTools to copy it.", "success");
    });

  highlightNearestCrossingOnFirstLoad();
};

