  const gridlyReflowAudit = function gridlyReflowAudit() {
    const layoutReads = [
      { pattern: 'getBoundingClientRect', notes: 'Frequently used in sheet visibility checks, popup placement, map/control diagnostics, and route/report UI probes.' },
      { pattern: 'getComputedStyle', notes: 'Used heavily in visibility gating and state diagnostics across portrait v2, modals, route setup, and alerts surfaces.' },
      { pattern: 'clientWidth/clientHeight/scrollWidth/scrollHeight', notes: 'Used in layout mode selection and overflow detection paths.' },
      { pattern: 'getClientRects', notes: 'Used in visibility helpers attached to portrait/v2 diagnostics.' }
    ];

    const layoutWrites = [
      { pattern: 'classList.add/remove/toggle', notes: 'Common across modal, sheet, dock, and route/report state transitions.' },
      { pattern: 'style.*', notes: 'Inline style writes in portrait v2 sheet/backdrop open-close flows and map/report overlays.' },
      { pattern: 'setAttribute/removeAttribute', notes: 'Used to update aria/hidden/inert and mode data attributes.' },
      { pattern: 'innerHTML/appendChild', notes: 'Dynamic surface creation and content updates for sheets, modals, and panels.' }
    ];

    const suspectedReadAfterWrite = [
      { area: 'Portrait V2 sheet lifecycle', evidence: 'Sheet/backdrop class/style writes during open/close are followed by visibility and geometry reads in nearby diagnostic/state helpers.' },
      { area: 'Route/hazard quick panels', evidence: 'Panel visibility class toggles and attribute writes are followed by computed style / rect checks in debug and readiness flows.' },
      { area: 'Popup + map sizing flows', evidence: 'UI writes and panel transitions occur around requestAnimationFrame + map.invalidateSize + bounding rect measurements.' },
      { area: 'Dock/filter button state updates', evidence: 'Bulk class toggles can precede element visibility and width reads in verifier/debug paths.' }
    ];

    const hotspotFunctions = [
      'applyPortraitV2SurfaceContainment',
      'renderAlerts',
      'renderUnifiedIncidents',
      'refreshReportHazardViews',
      'installGridlyMobileLayerMenu',
      'scheduleMapResize',
      'gridlyPortraitV2SheetState',
      'gridlyPortraitV2LayerAudit'
    ];

    const repeatedTriggers = [
      'window resize listeners (multiple registrations)',
      'visualViewport resize/scroll listeners',
      'requestAnimationFrame map resize/invalidate chains',
      'setTimeout-driven UI staging/open-close timers',
      'setInterval live refresh loop for shared reports'
    ];

    const recommendedTargets = [
      'Batch DOM writes before any geometry/computed-style reads per frame.',
      'Isolate heavy visibility/debug probes from hot interaction paths.',
      'Throttle/de-duplicate resize-triggered measurement paths.',
      'Guard map.invalidateSize calls to only run when container dimensions actually changed.',
      'Centralize sheet/panel measurement to one read phase per transition.'
    ];

    const mapResizeGuard = window.__gridlyMapResizeGuard || null;
    return {
      layoutReads,
      layoutWrites,
      suspectedReadAfterWrite,
      hotspotFunctions,
      repeatedTriggers,
      recommendedTargets,
      mapResizeGuardActive: Boolean(mapResizeGuard?.active),
      lastMapSize: mapResizeGuard?.getLastSize?.() || null,
      skippedMapInvalidates: mapResizeGuard?.getSkippedCount?.() || 0,
      forcedMapInvalidates: mapResizeGuard?.getForcedCount?.() || 0,
      portraitMeasurementCacheActive: Boolean(portraitV2MeasurementCache.active),
      cachedReadHits: portraitV2MeasurementCache.hits,
      cachedReadMisses: portraitV2MeasurementCache.misses,
      portraitBatchingActive: Boolean(portraitV2BatchingState.active),
      passiveAuditOnlyConfirmed: true
    };
  };

  function getGridlyTopHeaderBleedAuditSnapshot() {
    const body = document.body;
    const shell = document.getElementById("gridlyPortraitV2");
    const headerSelectors = [".gridly-v2-topbar", ".gridly-v2-status-pill", ".gridly-v2-segments"];
    const headerElements = headerSelectors
      .map((selector) => ({ selector, element: shell?.querySelector?.(selector) || null }))
      .filter((entry) => entry.element);
    const rectToJson = (rect) => rect ? {
      top: Math.round(rect.top),
      right: Math.round(rect.right),
      bottom: Math.round(rect.bottom),
      left: Math.round(rect.left),
      width: Math.round(rect.width),
      height: Math.round(rect.height)
    } : null;
    const rectsOverlap = (a, b) => Boolean(a && b && a.width > 0 && a.height > 0 && b.width > 0 && b.height > 0 && a.left < b.right && a.right > b.left && a.top < b.bottom && a.bottom > b.top);
    const parseAlpha = (color = "") => {
      const rgba = String(color || "").match(/rgba?\(([^)]+)\)/i);
      if (!rgba) return color && color !== "transparent" ? 1 : 0;
      const parts = rgba[1].split(",").map((part) => part.trim());
      return parts.length >= 4 ? Number.parseFloat(parts[3]) : 1;
    };
    const headerRegionRect = headerElements.reduce((acc, entry) => {
      const rect = entry.element.getBoundingClientRect();
      if (!rect || rect.width <= 0 || rect.height <= 0) return acc;
      if (!acc) return { top: rect.top, right: rect.right, bottom: rect.bottom, left: rect.left, width: rect.width, height: rect.height };
      const top = Math.min(acc.top, rect.top);
      const left = Math.min(acc.left, rect.left);
      const right = Math.max(acc.right, rect.right);
      const bottom = Math.max(acc.bottom, rect.bottom);
      return { top, right, bottom, left, width: right - left, height: bottom - top };
    }, null);
    const headerSurfaces = headerElements.map(({ selector, element }) => {
      const style = getComputedStyle(element);
      const backgroundImageApplied = Boolean(style.backgroundImage && style.backgroundImage !== "none");
      const backgroundAlpha = parseAlpha(style.backgroundColor);
      return {
        selector,
        rect: rectToJson(element.getBoundingClientRect()),
        zIndex: style.zIndex,
        isolation: style.isolation,
        contain: style.contain,
        backgroundColor: style.backgroundColor,
        backgroundImageApplied,
        backgroundAlpha,
        opaqueOrIsolated: Boolean((backgroundImageApplied || backgroundAlpha >= 0.96) && style.isolation === "isolate" && String(style.contain || "").includes("paint"))
      };
    });
    const overlapCandidates = [
      { name: "gridlyCommunityPulseSurface", selector: "#gridlyCommunityPulseSurface" },
      { name: "map-card", selector: ".map-card" },
      { name: "map", selector: "#map" }
    ];
    const overlappingTopRegionElements = overlapCandidates.map((candidate) => {
      const element = document.querySelector(candidate.selector);
      const style = element ? getComputedStyle(element) : null;
      const rect = element ? element.getBoundingClientRect() : null;
      return {
        ...candidate,
        exists: Boolean(element),
        hidden: Boolean(element?.hidden),
        display: style?.display || null,
        visibility: style?.visibility || null,
        opacity: style?.opacity || null,
        rect: rectToJson(rect),
        overlapsTopRegion: rectsOverlap(headerRegionRect, rect)
      };
    });
    const communityPulseOverlap = overlappingTopRegionElements.find((entry) => entry.name === "gridlyCommunityPulseSurface");
    const headerBackgroundIsolationApplied = headerSurfaces.length === headerSelectors.length && headerSurfaces.every((surface) => surface.opaqueOrIsolated);
    const portraitShieldApplied = Boolean(body?.dataset?.layoutMode === "portrait" && shell && body.classList.contains("gridly-v2-surface-containment"));
    const communityPulseVisuallyContained = Boolean(!communityPulseOverlap?.overlapsTopRegion || (portraitShieldApplied && headerBackgroundIsolationApplied));
    const topHeaderBleedCheck = {
      checked: true,
      status: headerBackgroundIsolationApplied && communityPulseVisuallyContained ? "ok" : "needs_attention",
      portraitShieldApplied,
      headerRegionRect: rectToJson(headerRegionRect),
      checkedSelectors: headerSelectors
    };
    return {
      topHeaderBleedCheck,
      overlappingTopRegionElements,
      communityPulseVisuallyContained,
      headerBackgroundIsolationApplied,
      headerSurfaces
    };
  }

  const gridlyPortraitV2LayerAudit = function gridlyPortraitV2LayerAudit() {
    return new Promise((resolve) => requestAnimationFrame(() => {
    const backdrop = document.getElementById("gridlyPortraitV2SheetBackdrop");
    const sheet = document.getElementById("gridlyPortraitV2Sheet");
    const routeButtons = Array.from(document.querySelectorAll('#gridlyPortraitV2SheetBody button')).filter((button) => {
      const label = (button.textContent || "").toLowerCase();
      return label.includes("manage places") || label.includes("open route watch") || label.includes("view route");
    });
    const getMetrics = (el) => {
      if (!el) return null;
      const style = getComputedStyle(el);
      return {
        zIndex: style.zIndex,
        pointerEvents: style.pointerEvents,
        hidden: Boolean(el.hidden),
        display: style.display,
      };
    };
    const centerTarget = (() => {
      if (!sheet) return null;
      const rect = sheet.getBoundingClientRect();
      if (rect.width <= 0 || rect.height <= 0) return null;
      const x = Math.round(rect.left + (rect.width / 2));
      const y = Math.round(rect.top + (rect.height / 2));
      const hit = document.elementFromPoint(x, y);
      return {
        x,
        y,
        element: hit ? `${hit.tagName.toLowerCase()}${hit.id ? `#${hit.id}` : ""}${hit.className ? `.${String(hit.className).trim().replace(/\s+/g, ".")}` : ""}` : null,
        isInsideSheet: Boolean(hit && sheet.contains(hit))
      };
    })();
    const routeButtonHits = routeButtons.map((button) => {
      const rect = button.getBoundingClientRect();
      const x = Math.round(rect.left + (rect.width / 2));
      const y = Math.round(rect.top + (rect.height / 2));
      const hit = document.elementFromPoint(x, y);
      return {
        text: (button.textContent || "").trim(),
        x,
        y,
        topElement: hit ? `${hit.tagName.toLowerCase()}${hit.id ? `#${hit.id}` : ""}${hit.className ? `.${String(hit.className).trim().replace(/\s+/g, ".")}` : ""}` : null,
        hitButtonOrChild: Boolean(hit && (hit === button || button.contains(hit)))
      };
    });
    const backdropCoveringSheet = Boolean(centerTarget && !centerTarget.isInsideSheet);
    resolve({
      backdrop: getMetrics(backdrop),
      activeSheet: getMetrics(sheet),
      elementFromPointAtSheetCenter: centerTarget,
      elementFromPointAtRouteButtons: routeButtonHits,
      backdropCoveringSheet,
      ...getGridlyTopHeaderBleedAuditSnapshot(),
      recommendedStatus: backdropCoveringSheet ? "needs-fix" : "ok"
    });
    }));
  };

  window.gridlyPortraitV2SheetState = function gridlyPortraitV2SheetState() {
    pushGridlyReflowTrace("gridlyPortraitV2SheetState", "read");
    return runPortraitV2BatchedRead(null, (frameId) => {
    const shell = document.getElementById("gridlyPortraitV2");
    const sheet = document.getElementById("gridlyPortraitV2Sheet");
    const sheetBody = document.getElementById("gridlyPortraitV2SheetBody");
    const isOnscreen = (el) => {
      if (!el) return false;
      const style = getCachedPortraitMeasurement(el, "computed-style", () => getComputedStyle(el), frameId);
      if (el.hidden || style.display === "none" || style.visibility === "hidden" || Number(style.opacity || "1") === 0) return false;
      const rect = getCachedPortraitMeasurement(el, "rect", () => el.getBoundingClientRect(), frameId);
      return rect.width > 0 && rect.height > 0 && rect.bottom > 0 && rect.right > 0 && rect.top < window.innerHeight && rect.left < window.innerWidth;
    };
    const getState = (el) => {
      if (!el) return null;
      const style = getCachedPortraitMeasurement(el, "computed-style", () => getComputedStyle(el), frameId);
      return {
        hidden: Boolean(el.hidden),
        display: style.display,
        pointerEvents: style.pointerEvents,
        transform: style.transform,
        translate: style.translate,
        classes: Array.from(el.classList),
        visuallyOnscreen: isOnscreen(el)
      };
    };
    const portraitModeActive = (document.body?.dataset?.layoutMode || "") === "portrait-v2";
    const reportRenderLoopActive = activeSheet === "report";
    const reportSurfaceReopenConditions = {
      activeSheetIsReport: activeSheet === "report",
      gridlyActiveSurfaceIsReport: gridlyActiveSurface === "report",
      mobileModeIsReport: mobileUiMode === "report",
      reportModeActiveFlag: Boolean(reportingState?.reportModeActive)
    };
    const backdrop = document.getElementById("gridlyPortraitV2SheetBackdrop");
    resolve({
      activeSheet,
      shellHidden: Boolean(shell?.hidden),
      shellDisplay: shell ? getCachedPortraitMeasurement(shell, "computed-style", () => getComputedStyle(shell), frameId)?.display : null,
      shellPointerEvents: shell ? getCachedPortraitMeasurement(shell, "computed-style", () => getComputedStyle(shell), frameId)?.pointerEvents : null,
      sheetHidden: Boolean(sheet?.hidden),
      sheetDisplay: sheet ? getCachedPortraitMeasurement(sheet, "computed-style", () => getComputedStyle(sheet), frameId)?.display : null,
      sheetPointerEvents: sheet ? getCachedPortraitMeasurement(sheet, "computed-style", () => getComputedStyle(sheet), frameId)?.pointerEvents : null,
      sheetTransform: sheet ? getCachedPortraitMeasurement(sheet, "computed-style", () => getComputedStyle(sheet), frameId)?.transform : null,
      sheetClasses: sheet ? Array.from(sheet.classList) : [],
      sheetVisible: isOnscreen(sheet),
      backdropHidden: Boolean(backdrop?.hidden),
      backdropDisplay: backdrop ? getCachedPortraitMeasurement(backdrop, "computed-style", () => getComputedStyle(backdrop), frameId)?.display : null,
      bodyClasses: Array.from(document.body?.classList || []),
      shell: getState(shell),
      sheet: getState(sheet),
      sheetBody: getState(sheetBody),
      rawActiveSheetSource: {
        portraitV2ActiveSheet: activeSheet,
        gridlyActiveSurface,
        mobileUiMode,
        reportingStateReportModeActive: Boolean(reportingState?.reportModeActive)
      },
      reportRenderLoopActive,
      reportSurfaceReopenConditions,
      reportSurfaceReopenEligible: Object.values(reportSurfaceReopenConditions).some(Boolean),
      bodyModalOpen: document.body.classList.contains("modal-open"),
      attachedToActivePortraitMode: portraitModeActive && Boolean(shell && !shell.hidden)
    });
    });
  };


window.gridlyDirectionConfidenceAudit = function gridlyDirectionConfidenceAudit() {
  const pathHelperFromGlobal = (typeof window !== "undefined" && typeof window.getValueByPath === "function")
    ? window.getValueByPath
    : (typeof globalThis !== "undefined" && typeof globalThis.getValueByPath === "function")
      ? globalThis.getValueByPath
      : (typeof getValueByPath === "function" ? getValueByPath : null);
  const safeGetValueByPath = (obj, path) => {
    if (pathHelperFromGlobal) {
      try {
        return pathHelperFromGlobal(obj, path);
      } catch (_error) {
        return undefined;
      }
    }
    if (!obj || typeof path !== "string" || !path.trim()) return undefined;
    return path.split(".").reduce((acc, key) => {
      if (acc === null || acc === undefined) return undefined;
      return acc[key];
    }, obj);
  };
  const activeIncidents = typeof getActiveUnifiedIncidents === "function" ? getActiveUnifiedIncidents() : [];
  const alertSnapshot = typeof getAlertsSurfaceSnapshot === "function" ? getAlertsSurfaceSnapshot() : null;
  const alertItems = Array.isArray(alertSnapshot?.alerts) ? alertSnapshot.alerts : [];
  const enrichedById = new Map();
  alertItems.forEach((alert) => {
    const alertId = String(alert?.id || alert?.incidentId || alert?.reportId || "").trim();
    if (!alertId) return;
    const rawCandidate =
      alert?.raw && typeof alert.raw === "object" ? alert.raw : null;
    const alertCandidate =
      alert && typeof alert === "object" ? alert : null;
    const enrichedCandidate = rawCandidate
      ? { ...rawCandidate, ...alertCandidate }
      : alertCandidate;
    if (enrichedCandidate) {
      enrichedById.set(alertId, enrichedCandidate);
    }
  });
  return (Array.isArray(activeIncidents) ? activeIncidents : []).map((incident) => {
    const incidentId = String(incident?.id || incident?.incidentId || incident?.reportId || "").trim();
    const enrichedIncident = incidentId ? (enrichedById.get(incidentId) || null) : null;
    const directionOwnerIncident = enrichedIncident || incident;
    const incidentTypeToken = String(directionOwnerIncident?.type || directionOwnerIncident?.hazardType || directionOwnerIncident?.category || directionOwnerIncident?.label || "").toLowerCase();
    const incidentIdToken = String(directionOwnerIncident?.id || directionOwnerIncident?.incidentId || "").toLowerCase();
    const isRoadHazardIncident = incidentIdToken.startsWith("road-")
      || incidentTypeToken.includes("hazard")
      || incidentTypeToken.includes("crash")
      || incidentTypeToken.includes("debris")
      || incidentTypeToken.includes("flood")
      || incidentTypeToken.includes("closure")
      || incidentTypeToken.includes("construct");
    if (isRoadHazardIncident) {
      return {
        incidentId: String(directionOwnerIncident?.id || directionOwnerIncident?.incidentId || directionOwnerIncident?.reportId || "").trim(),
        titleOrHeadline: String(incident?.title || incident?.headline || ""),
        roadName: "",
        inferredOrientation: "unknown",
        directionPair: [],
        confidence: "LOW",
        source: "road-hazard-deferred",
        reason: "Road hazard direction confidence deferred; location text remains authoritative."
      };
    }
    const directionAuditOwner = directionOwnerIncident;
    const confidence = resolveIncidentDirectionConfidence(directionAuditOwner);
    const availableRoadFields = [
      "primaryRoad", "roadName", "resolvedRoadName", "corridor", "route", "road", "nearestRoad", "knownLocation",
      "raw.primaryRoad", "raw.roadName", "source.primaryRoad", "source.roadName"
    ].filter((path) => {
      const value = safeGetValueByPath(directionAuditOwner, path);
      return typeof value === "string" ? Boolean(value.trim()) : value !== undefined && value !== null;
    });
    return {
      incidentId: confidence.incidentId,
      titleOrHeadline: String(incident?.title || incident?.headline || ""),
      roadName: confidence.roadName,
      inferredOrientation: confidence.inferredOrientation,
      directionPair: confidence.directionPair,
      confidence: confidence.confidence,
      source: confidence.source,
      reason: confidence.reason
    };
  });
};


window.gridlyUiSmokeTest = function gridlyUiSmokeTest() {
  bindBottomDockRealButtons();
  const dockButtons = getBottomDockButtons();
  const classified = dockButtons.map((btn) => ({ btn, intent: classifyBottomDockIntent(btn) }));
  const byIntent = (intent) => classified.some((entry) => entry.intent === intent && entry.btn.dataset.gridlyDockBound === "true");
  const settingsButtonBound = classified.some((entry) => (
    entry.intent === "settings"
    && (
      entry.btn.dataset.gridlyDockBound === "true"
      || entry.btn.dataset.gridlyV2SheetBound === "true"
      || gridlyGlobalDockEventTrace.settingsButtonBindings.nodeBound
    )
  ));
  const alertsPanel = document.querySelector("#alertsSection:not([hidden]), .gridly-tactical-dock-sheet:not([hidden])[data-action='alerts']");
  const markerAudit = window.gridlyMarkerAuditDebug?.() || {};
  const markerRendererPresent = (
    typeof window.gridlyRenderHazardMarkersDebug === "function" ||
    typeof renderUnifiedIncidents === "function" ||
    typeof renderUnifiedIncidentMarkers === "function"
  );
  const isVisible = (el) => {
    if (!el || el.hidden) return false;
    const style = window.getComputedStyle(el);
    const rect = el.getBoundingClientRect();
    return style.display !== "none" && style.visibility !== "hidden" && style.opacity !== "0" && rect.width > 0 && rect.height > 0;
  };

  const settingsSurfaceSelectorCandidates = [
    "#settingsModal",
    ".gridly-tactical-dock-sheet[data-action='settings']",
    "#gridlyPortraitV2Sheet",
    "#gridlyPortraitV2Sheet.is-open",
    "#gridlyPortraitV2Sheet[data-active-sheet='settings']",
    ".gridly-portrait-v2-sheet",
    ".gridly-settings-sheet",
    "[data-gridly-surface='settings']",
    "[data-action='settings']"
  ];

  const settingsSurfaceSelectorsFound = [];
  const visibleSettingsSurfaceSelectorsFound = [];
  settingsSurfaceSelectorCandidates.forEach((selector) => {
    const matches = document.querySelectorAll(selector);
    if (!matches.length) return;
    settingsSurfaceSelectorsFound.push(selector);
    if ([...matches].some((node) => isVisible(node))) {
      visibleSettingsSurfaceSelectorsFound.push(selector);
    }
  });

  const settingsPanelFound = visibleSettingsSurfaceSelectorsFound.length > 0 || (activeSheet === "settings" && !document.getElementById("gridlyPortraitV2Sheet")?.hidden);

  const activeSheetValue = activeSheet || document.getElementById("gridlyPortraitV2Sheet")?.dataset?.activeSheet || "";

  const alertsSurfaceSelectorCandidates = [
    "#alertsSection",
    "#gridlyPortraitV2Sheet[data-active-sheet='alerts']",
    ".gridly-tactical-dock-sheet[data-action='alerts']",
    "#smartAlertsModal"
  ];
  const alertsSurfaceSelectorsFound = [];
  const visibleAlertsSurfaceSelectorsFound = [];
  alertsSurfaceSelectorCandidates.forEach((selector) => {
    const matches = document.querySelectorAll(selector);
    if (!matches.length) return;
    alertsSurfaceSelectorsFound.push(selector);
    if ([...matches].some((node) => isVisible(node))) visibleAlertsSurfaceSelectorsFound.push(selector);
  });
  const alertsOpenActionFound = typeof openAlertsSurfaceFromDock === "function";
  const layersOpenActionFound = typeof openPortraitLayersSurface === "function" || typeof openPortraitV2Sheet === "function";

  const layer = unifiedIncidentLayer;
  const layerMarkers = typeof layer?.getLayers === "function" ? layer.getLayers() : [];
  const hazardMarkerDomSelectors = [
    "#map .gridly-hazard-marker",
    "#map .leaflet-marker-icon .gridly-hazard-marker",
    "#map .leaflet-marker-pane .gridly-hazard-marker",
    "#map .leaflet-marker-icon[data-state]"
  ];
  const hazardMarkerDomSelectorsFound = hazardMarkerDomSelectors.filter((selector) => document.querySelector(selector));

  const layersSurfaceSelectorCandidates = ["#gridlyPortraitV2Sheet[data-active-sheet='layers']", "#map .leaflet-control-layers-expanded", "#mobileNativeSurfaceLayer:not([hidden])"];
  const visibleLayersSurfaceSelectorsFound = layersSurfaceSelectorCandidates.filter((selector) => {
    const matches = Array.from(document.querySelectorAll(selector));
    return matches.some((node) => isVisible(node));
  });
  const visibleHazardMarkerCount = document.querySelectorAll("#map .leaflet-marker-icon .gridly-hazard-marker").length || document.querySelectorAll("#map .gridly-hazard-marker").length;

  const activeHazardCoordinateSample = (Array.isArray(activeHazards) ? activeHazards : []).slice(0, 3).map((hazard) => {
    const rawLat = hazard?.lat ?? hazard?.latitude ?? hazard?.rawLat ?? null;
    const rawLng = hazard?.lng ?? hazard?.lon ?? hazard?.longitude ?? hazard?.rawLng ?? null;
    const lat = Number(rawLat);
    const lng = Number(rawLng);
    return {
      lat: Number.isFinite(lat) ? lat : null,
      lng: Number.isFinite(lng) ? lng : null,
      rawLat,
      rawLng,
      finite: Number.isFinite(lat) && Number.isFinite(lng)
    };
  });

  return {
    bottomDockButtonsFound: dockButtons.length,
    reportButtonBound: byIntent("report"),
    routeButtonBound: byIntent("route"),
    alertsButtonBound: byIntent("alerts"),
    settingsButtonBound,
    layersButtonBound: byIntent("layers"),
    alertsPanelFound: Boolean(alertsPanel),
    alertsSurfaceSelectorsFound,
    visibleAlertsSurfaceSelectorsFound,
    alertsOpenActionFound,
    reportUsesBottomSheet: Boolean((activeSheetValue === "report" || document.getElementById("gridlyPortraitV2Sheet")?.dataset?.activeSheet === "report") && isVisible(document.getElementById("gridlyPortraitV2Sheet"))),
    activeSheet: activeSheetValue || null,
    settingsPanelFound,
    settingsSurfaceSelectorsFound,
    visibleSettingsSurfaceSelectorsFound,
    layersOpenActionFound,
    visibleLayersSurfaceSelectorsFound,
    hazardLayerFound: Boolean(layer && map && map.hasLayer?.(layer)),
    unifiedIncidentLayerOnMap: Boolean(layer && map && map.hasLayer?.(layer)),
    hazardLayerChildCount: layerMarkers.length,
    hazardMarkerDomSelectorsFound,
    activeHazardCount: Array.isArray(activeHazards) ? activeHazards.length : 0,
    activeHazardCoordinateSample,
    visibleHazardMarkerCount,
    markerRenderFunctionFound: Boolean(markerAudit?.markerRenderFunctionFound) || markerRendererPresent,
    markerSourceCount: Number(markerAudit?.markerSourceCount || 0),
    markerSourceSample: Array.isArray(markerAudit?.markerSourceSample) ? markerAudit.markerSourceSample : [],
    markerSourceUsed: markerAudit?.markerSourceUsed || "",
    lastMarkerRenderAt: markerAudit?.lastMarkerRenderAt || null,
    lastMarkerRenderSourceCounts: markerAudit?.lastMarkerRenderSourceCounts || null,
    lastMarkerRenderResult: markerAudit?.lastMarkerRenderResult || null,
    markerRenderSkipReasons: markerAudit?.markerRenderSkipReasons || null,
    currentFilter: activeGeoFilter || null
  };
};


function getGridlyAuditRouteRenderSnapshot() {
  const safeRouteSnapshot = {
    routeLayerLatLngs: null,
    renderedRoutePointCount: 0,
    routeRenderAudit: null,
    currentRoutePointCount: 0,
    currentRouteGeometrySource: null,
    routeUsesOsrmGeometry: false,
    routeRenderedAsStraightLine: false,
    routeGeometryPointCount: 0
  };
  try {
    const countLatLngs = (value) => {
      if (!Array.isArray(value)) return 0;
      return value.reduce((count, item) => {
        if (Array.isArray(item)) return count + countLatLngs(item);
        const lat = Number(item?.lat ?? item?.[0]);
        const lng = Number(item?.lng ?? item?.[1]);
        return count + (Number.isFinite(lat) && Number.isFinite(lng) ? 1 : 0);
      }, 0);
    };
    const readFiniteNumber = (value, fallback = 0) => {
      const number = Number(value);
      return Number.isFinite(number) ? number : fallback;
    };
    const readBoolean = (value) => Boolean(value);
    const routeLayer = window.__gridlyRoutePreviewLayer || null;
    let routeLayerLatLngs = null;
    try {
      routeLayerLatLngs = routeLayer && typeof routeLayer.getLatLngs === "function"
        ? routeLayer.getLatLngs()
        : null;
    } catch (error) {
      routeLayerLatLngs = null;
    }
    const renderedRoutePointCount = countLatLngs(routeLayerLatLngs);
    const routeRenderAuditCandidates = [
      window.__gridlyRouteRenderAuditState,
      window.gridlyLastRouteRenderAuditState,
      typeof lastRouteRenderAuditState !== "undefined" ? lastRouteRenderAuditState : null
    ].filter((candidate) => candidate && typeof candidate === "object");
    const routeRenderAudit = routeRenderAuditCandidates.find((candidate) => String(candidate.source || "").toLowerCase() === "osrm" && readFiniteNumber(candidate.pointCount, 0) > 2)
      || routeRenderAuditCandidates[0]
      || null;
    const auditPointCount = readFiniteNumber(routeRenderAudit?.pointCount, 0);
    const previewPointCount = typeof routePreviewPolylinePointCount !== "undefined" ? readFiniteNumber(routePreviewPolylinePointCount, 0) : 0;
    const geometryPointCount = typeof lastRouteGeometryPointCount !== "undefined" ? readFiniteNumber(lastRouteGeometryPointCount, 0) : 0;
    const currentRoutePointCount = Math.max(auditPointCount, previewPointCount, renderedRoutePointCount, geometryPointCount, 0);
    const routeGeometrySourceCandidates = [
      routeRenderAudit?.source,
      window.__gridlyRouteRenderAuditState?.source,
      window.gridlyLastRouteRenderAuditState?.source,
      typeof routeGeometrySource !== "undefined" ? routeGeometrySource : null
    ].map((source) => String(source || "").toLowerCase()).filter(Boolean);
    const currentRouteGeometrySource = routeGeometrySourceCandidates[0] || null;
    const previewRendered = typeof routePreviewRendered !== "undefined" ? readBoolean(routePreviewRendered) : false;
    const latestRouteWasRendered = Boolean(routeRenderAudit?.rendered || previewRendered || renderedRoutePointCount >= 2);
    const osrmSucceeded = typeof osrmRouteSuccess !== "undefined" ? readBoolean(osrmRouteSuccess) : false;
    const osrmGeometryEvidence = routeGeometrySourceCandidates.includes("osrm")
      || Boolean(routeRenderAudit?.osrmRouteSuccess || osrmSucceeded);
    const routeUsesOsrmGeometry = Boolean(osrmGeometryEvidence && currentRoutePointCount > 2);
    const routeRenderedAsStraightLine = Boolean(
      latestRouteWasRendered
      && currentRouteGeometrySource !== "osrm"
      && currentRoutePointCount > 0
      && currentRoutePointCount <= 2
    );
    return {
      routeLayerLatLngs,
      renderedRoutePointCount,
      routeRenderAudit: routeRenderAudit || {},
      currentRoutePointCount,
      currentRouteGeometrySource,
      routeUsesOsrmGeometry,
      routeRenderedAsStraightLine,
      routeGeometryPointCount: currentRoutePointCount
    };
  } catch (error) {
    return safeRouteSnapshot;
  }
}

function getGridlyAuditAlertCardNodes(isAuditVisible) {
  const activeAlertsSheet = document.querySelector("#gridlyPortraitV2Sheet[data-active-sheet='alerts']:not([hidden])");
  const activeAlertsSurface = activeAlertsSheet?.querySelector?.("#gridlyPortraitV2SheetBody .gridly-alerts-active, .gridly-alerts-active")
    || document.querySelector(".gridly-alerts-active");
  const cardSelector = [
    "[data-gridly-alert-row='true']",
    "[data-gridly-alert-id]",
    ".gridly-alert-row.gridly-alert-intel-card",
    ".gridly-alerts-active > .gridly-alert-row",
    ".gridly-alerts-active > .gridly-alert-intel-card",
    ".alert-item",
    "#alertsList > *",
    "#roadHazardsList > *"
  ].join(",");
  const scopedCards = activeAlertsSurface
    ? Array.from(activeAlertsSurface.querySelectorAll(cardSelector))
    : [];
  const fallbackCards = Array.from(document.querySelectorAll(cardSelector));
  const uniqueCards = Array.from(new Set([...scopedCards, ...fallbackCards]));
  const hasVisibleComputedChain = (node) => {
    if (!(node instanceof Element)) return false;
    if (node.hidden || node.getAttribute("aria-hidden") === "true") return false;
    let current = node;
    while (current && current instanceof Element) {
      const style = window.getComputedStyle(current);
      if (style.display === "none" || style.visibility === "hidden" || style.opacity === "0") return false;
      current = current.parentElement;
    }
    return true;
  };
  const hasRenderedBoxOrContent = (node) => {
    if (!(node instanceof Element)) return false;
    const rects = typeof node.getClientRects === "function" ? node.getClientRects() : [];
    if (rects && rects.length > 0) return true;
    const rect = typeof node.getBoundingClientRect === "function" ? node.getBoundingClientRect() : null;
    if (rect && rect.width > 0 && rect.height > 0) return true;
    return String(node.textContent || "").trim().length > 0 && hasVisibleComputedChain(node);
  };
  const visibleCards = uniqueCards.filter((node) => {
    if (node?.getAttribute?.("data-gridly-alert-hidden") === "true") return false;
    if (node?.hasAttribute?.("data-gridly-alert-expand")) return false;
    const belongsToVisibleAlertsSheet = Boolean(activeAlertsSheet && activeAlertsSheet.contains(node));
    const belongsToVisibleAlertsSurface = Boolean(activeAlertsSurface && activeAlertsSurface.contains(node));
    if (!belongsToVisibleAlertsSheet && !belongsToVisibleAlertsSurface && node.closest?.("#gridlyPortraitV2Sheet") && !node.closest?.("#gridlyPortraitV2Sheet[data-active-sheet='alerts']:not([hidden])")) return false;
    if (!hasVisibleComputedChain(node) || !hasRenderedBoxOrContent(node)) return false;
    return typeof isAuditVisible === "function" ? (isAuditVisible(node) || hasRenderedBoxOrContent(node)) : true;
  });
  return {
    activeAlertsSurface,
    alertCardNodes: uniqueCards,
    visibleAlertCards: visibleCards,
    cardSelector
  };
}


function gridlyAwarenessExperienceAudit() {
  const readText = (selector) => String(document.querySelector(selector)?.textContent || "").replace(/\s+/g, " ").trim();
  const visibleNode = (node) => {
    if (!node || typeof node.getBoundingClientRect !== "function") return false;
    const style = window.getComputedStyle(node);
    const rect = node.getBoundingClientRect();
    return !node.hidden && style.display !== "none" && style.visibility !== "hidden" && style.opacity !== "0" && rect.width > 0 && rect.height > 0;
  };
  const readFont = (selector) => {
    const node = document.querySelector(selector);
    if (!node) return { selector, found: false };
    const style = window.getComputedStyle(node);
    return {
      selector,
      found: true,
      text: String(node.textContent || "").replace(/\s+/g, " ").trim(),
      fontSize: style.fontSize,
      fontWeight: style.fontWeight,
      lineHeight: style.lineHeight,
      letterSpacing: style.letterSpacing
    };
  };
  const readBox = (selector) => {
    const node = document.querySelector(selector);
    if (!node) return { selector, found: false };
    const style = window.getComputedStyle(node);
    const rect = node.getBoundingClientRect();
    return {
      selector,
      found: true,
      visible: visibleNode(node),
      top: Math.round(rect.top),
      height: Math.round(rect.height),
      padding: style.padding,
      margin: style.margin,
      borderRadius: style.borderRadius
    };
  };
  const primaryHeadline = readText("#gridlyV2TopStatusPrimary") || "No major mobility issues reported in Dayton.";
  const secondaryHeadline = readText("#gridlyV2TopStatusSecondary") || "Community activity is quiet.";
  const microline = readText("#gridlyTopAwarenessMicroline, .gridly-v2-top-awareness-microline");
  const scopeFilters = Array.from(document.querySelectorAll("#gridlyPortraitV2 .gridly-v2-segments button")).map((button) => ({
    label: String(button.textContent || "").trim(),
    active: button.classList.contains("is-active"),
    filter: button.dataset.v2Filter || button.dataset.geoFilter || ""
  }));
  const pulseHeadline = readText("#gridlyCommunityPulseHeadline, .community-pulse-copy strong");
  const pulseCopy = readText("#gridlyCommunityPulseCopy, .community-pulse-copy p");
  const latestAlerts = Array.isArray(window.__gridlyLatestAlertsForRender) ? window.__gridlyLatestAlertsForRender : [];
  const activeAwareness = window.gridlyTopAwarenessMicrolineState || {};
  const activeReportCount = Number(activeAwareness.activeReportCount ?? activeAwareness.activeAwarenessCount ?? latestAlerts.length ?? 0) || 0;
  const hasActiveAlertLanguage = /(reported|blocked|flood|delay|disruption|hazard|train|crash|closure|slow|impact)/i.test(`${primaryHeadline} ${secondaryHeadline} ${microline}`);
  const hasCommunityLanguage = /(community|driver|neighbor|reported|report)/i.test(`${primaryHeadline} ${secondaryHeadline} ${microline} ${pulseHeadline} ${pulseCopy}`);
  const hasRouteLanguage = /(route|commute|movement|corridor|delays?|travel)/i.test(`${primaryHeadline} ${secondaryHeadline} ${microline}`);
  const { visibleAlertCards = [], alertCardNodes = [] } = typeof getGridlyAuditAlertCardNodes === "function"
    ? getGridlyAuditAlertCardNodes(visibleNode)
    : { visibleAlertCards: [], alertCardNodes: [] };
  const alertSamples = visibleAlertCards.slice(0, 3).map((card) => {
    const text = String(card.textContent || "").replace(/\s+/g, " ").trim();
    const title = String(card.querySelector?.("strong, .gridly-alert-title, .gridly-alert-headline, [data-gridly-alert-title]")?.textContent || "").replace(/\s+/g, " ").trim();
    const locationSpecific = /\b(?:at|near|between|on|tx|sh|us|fm|cr|road|rd|street|st|avenue|ave|crossing|county road)\b|\b\d{2,4}\b/i.test(text);
    const freshnessVisible = /\b(?:just now|\d+\s*(?:m|min|minute|h|hr|hour)s?\s*ago|latest|updated|now)\b/i.test(text);
    const whatVisible = /(blocked|flood|hazard|train|crash|closure|delay|slowing|impact|disruption|reported|stable)/i.test(text);
    return {
      title,
      textPreview: text.slice(0, 180),
      whatVisible,
      locationSpecific,
      freshnessVisible,
      twoSecondComprehension: Boolean(whatVisible && locationSpecific && freshnessVisible)
    };
  });
  const twoSecondPassCount = alertSamples.filter((sample) => sample.twoSecondComprehension).length;
  const typography = {
    topbar: readFont("#gridlyPortraitV2 .gridly-v2-watch"),
    primaryHeadline: readFont("#gridlyV2TopStatusPrimary"),
    secondaryHeadline: readFont("#gridlyV2TopStatusSecondary"),
    microline: readFont("#gridlyTopAwarenessMicroline, .gridly-v2-top-awareness-microline"),
    alertTitle: readFont(".gridly-alert-row strong, .alert-item strong"),
    dockLabel: readFont("#gridlyPortraitV2 .gridly-v2-bottom-dock em")
  };
  const spacing = {
    topbar: readBox("#gridlyPortraitV2 .gridly-v2-topbar"),
    statusPill: readBox("#gridlyPortraitV2 .gridly-v2-status-pill"),
    segments: readBox("#gridlyPortraitV2 .gridly-v2-segments"),
    bottomDock: readBox("#gridlyPortraitV2 .gridly-v2-bottom-dock"),
    visibleAlertCardCount: visibleAlertCards.length,
    alertCardSample: visibleAlertCards.slice(0, 2).map((card) => {
      const style = window.getComputedStyle(card);
      const rect = card.getBoundingClientRect();
      return { height: Math.round(rect.height), padding: style.padding, margin: style.margin, gap: style.gap || "" };
    })
  };
  const currentDominance = hasActiveAlertLanguage
    ? "An active incident or mobility consequence dominates the top panel."
    : "A generic route-clear status dominates the top panel.";
  const shouldDominate = "The user-first awareness answer should dominate: what changed locally, where it is, how recent it is, and whether the community is quiet or active.";
  const premiumScore = Math.max(1, Math.min(10,
    5
    + (hasActiveAlertLanguage ? 1 : 0)
    + (hasCommunityLanguage ? 1 : 0)
    + (microline ? 1 : 0)
    + (visibleAlertCards.length ? 1 : 0)
    - (primaryHeadline.length < 18 ? 1 : 0)
    - (twoSecondPassCount < Math.min(alertSamples.length, 1) ? 1 : 0)
  ));

  return {
    auditVersion: "V207-awareness-experience-audit",
    currentTopPanelAnalysis: {
      primaryHeadline,
      secondaryHeadline,
      awarenessMicroline: microline || "Not visible or not populated in the current state.",
      scopeFilters,
      communityPulseHeadline: pulseHeadline || "Not visible in the Portrait V2 top stack.",
      communityPulseCopy: pulseCopy || "Not visible in the Portrait V2 top stack.",
      activeReportCount,
      currentDominance,
      shouldDominate,
      findings: [
        "The status pill is compact and operational, but it reads more like route status than a daily awareness briefing.",
        "The secondary line is useful for impact/freshness when alerts exist; quiet states fall back to generic reassurance.",
        "The filter row consumes early visual attention even though filters are a secondary control after the awareness answer."
      ]
    },
    awarenessHierarchyAnalysis: {
      currentHierarchy: ["brand/watch label", "status pill headline", "status pill subline", "scope filters", "map"],
      recommendedHierarchy: ["personal/local greeting or awareness headline", "specific disruption or quiet-day summary", "where + freshness + community report count", "map", "filters/actions"],
      gap: "The current top panel answers whether routes are clear, but Gridly's product promise should first answer what neighbors have reported before the driver goes."
    },
    informationDensityAnalysis: {
      densityAssessment: "Medium-high in the top 150px because brand, status, microline, and five filters compete for attention.",
      usefulDensity: "The primary and secondary status lines carry the right data primitives but need clearer hierarchy and less generic quiet-state copy.",
      overloadRisks: ["Five scope chips appear before the user has read the core awareness summary.", "Microline text can become too small to carry important community context."],
      underusedAreas: ["The quiet-state headline has room to be warmer and more community-aware.", "Alert cards can expose location and freshness as structured metadata instead of secondary small text only."]
    },
    typographyAnalysis: {
      sampledTypography: typography,
      recommendations: [
        "Make the daily primary headline larger/stronger than the current compact status label when this becomes an implementation sprint.",
        "Keep freshness/community metadata lighter, but not below comfortable mobile scan size.",
        "Use title case or sentence case for premium awareness copy; reserve all-caps for short route/crossing identifiers only.",
        "Give alert titles a clear first line, then use smaller but legible metadata chips for where and how recent."
      ]
    },
    spacingAnalysis: {
      sampledSpacing: spacing,
      findings: [
        "The top stack is efficient, but efficiency currently wins over breathing room and premium briefing feel.",
        "Status-to-filter spacing is tight; filters feel coupled to the headline rather than secondary controls.",
        "Bottom dock spacing feels polished and should remain action-oriented, while the top panel can become more editorial."
      ],
      opportunities: ["Add more vertical breathing room inside the awareness card.", "Separate controls from the awareness summary with clearer spacing or lower emphasis.", "Allow alert cards enough vertical rhythm for title, location, and freshness to scan independently."]
    },
    alertCardAnalysis: {
      visibleAlertCardCount: visibleAlertCards.length,
      detectedAlertCardCount: alertCardNodes.length,
      samples: alertSamples,
      twoSecondComprehensionPassCount: twoSecondPassCount,
      twoSecondComprehensionSummary: alertSamples.length
        ? (twoSecondPassCount === alertSamples.length ? "Current visible sample passes the what/where/freshness scan." : "At least one visible sample does not make what/where/freshness obvious within a 2-second scan.")
        : "No visible alert cards are available in the current DOM state; evaluate with active report fixtures before implementation.",
      recommendations: [
        "Structure each card as: event title, exact location/corridor, freshness + community count.",
        "Avoid generic first lines such as 'Impacted Movement' unless the next line immediately states the specific place.",
        "Make freshness visible without opening details."
      ]
    },
    routeIntelligenceAnalysis: {
      currentSignal: hasRouteLanguage ? "Route/movement language is present in the top copy." : "Route language is minimal in the current top copy.",
      recommendation: "Route intelligence should support the awareness headline, not replace it. Prefer 'No major mobility issues reported near your route' or 'Flooding reported on TX 146' over generic route-clear copy.",
      guardrail: "No route logic changes are recommended for this sprint; this is copy and hierarchy strategy only."
    },
    communityAwarenessAnalysis: {
      currentFeel: hasCommunityLanguage ? "Emerging community-powered awareness network" : "Closer to a compact map/traffic status app than a community-powered awareness network",
      evidence: { hasCommunityLanguage, activeReportCount, pulseHeadline, pulseCopy, microline },
      recommendations: [
        "Use 'reported' and 'community activity' language in the daily top state so the source of awareness is obvious.",
        "Quiet days should still feel community-powered: 'No major issues reported' plus 'Community activity is quiet.'",
        "Moderate/high activity should make report count and freshness visible before filters."
      ]
    },
    premiumExperienceScore: {
      score: premiumScore,
      scale: "1-10",
      rationale: "The shell has polished glass styling and functional intelligence, but the daily-use hierarchy still feels utilitarian compared with onboarding because the first read lacks a warmer awareness brief and explicit community positioning."
    },
    strongestElements: [
      "Compact always-available Portrait V2 shell with strong dock affordances.",
      "Existing top-status data model already includes active alert, impact, freshness, and microline inputs.",
      "Alert rendering pipeline has location-resolution and freshness primitives available for clearer cards.",
      "Community Pulse model provides the right foundation for 'neighbors reporting for neighbors' positioning."
    ],
    weakestElements: [
      "Generic quiet-state copy under-expresses Gridly's 'Know Before You Go' promise.",
      "Scope filters compete too early with the awareness headline.",
      "Community report counts are not consistently dominant in the first screen.",
      "Alert cards can require too much reading to separate what happened, where, and how recent."
    ],
    topImprovementOpportunities: [
      { rank: 1, opportunity: "Replace generic route-clear top copy with a daily local awareness brief.", expectedImpact: "Higher premium feel and clearer product positioning." },
      { rank: 2, opportunity: "Promote what/where/freshness/community count as the top panel's canonical information order.", expectedImpact: "Faster comprehension and stronger trust." },
      { rank: 3, opportunity: "Demote filters visually until after the awareness answer.", expectedImpact: "Less clutter on first read without changing route/filter logic." },
      { rank: 4, opportunity: "Standardize alert card anatomy around title, location, age, and report count.", expectedImpact: "Better 2-second scanning." },
      { rank: 5, opportunity: "Introduce quiet/moderate/high state copy models that all feel community-powered.", expectedImpact: "Daily-use experience catches up to onboarding quality." }
    ],
    recommendedNextSprint: {
      name: "Portrait V2 Awareness Brief UI Refinement",
      scope: ["top panel copy hierarchy", "quiet/moderate/high state content models", "alert card visual hierarchy", "community report-count visibility", "spacing/typography polish"],
      explicitNonScope: ["onboarding", "settings", "lifecycle systems", "cleanup systems", "hazard placement", "route logic", "alert logic"],
      successCriteria: [
        "A user can identify what happened, where, and freshness in under 2 seconds.",
        "Quiet state still communicates community-powered local awareness.",
        "Top panel feels like Gridly, not a generic traffic/map status widget."
      ]
    },
    recommendedHeadlineModels: {
      quiet: "Good Morning Denise — No major mobility issues reported in Dayton.",
      moderate: "Good Morning Denise — Flooding reported on TX 146.",
      high: "Good Morning Denise — Multiple disruptions reported across Dayton."
    },
    recommendedQuietState: {
      headline: "Good Morning Denise",
      primary: "No major mobility issues reported in Dayton.",
      secondary: "Community activity is quiet.",
      metadata: "Last checked just now",
      designIntent: "Warm, calm, and community-powered without pretending nothing could change."
    },
    recommendedModerateState: {
      headline: "Good Morning Denise",
      primary: "Flooding reported on TX 146",
      secondary: "Between US 90 and Brown Road",
      metadata: "Latest community report 8 min ago",
      designIntent: "Specific event first, precise place second, freshness third."
    },
    recommendedHighActivityState: {
      headline: "Good Morning Denise",
      primary: "Multiple disruptions reported across Dayton.",
      secondary: "8 active community reports.",
      metadata: "Review before you go",
      designIntent: "Escalate urgency and community volume while avoiding panic language."
    }
  };
}

