const GRIDLY_BETA_STATUS = Object.freeze({
  pass: "PASS",
  partial: "PARTIAL",
  needsWork: "NEEDS WORK"
});

function gridlyBetaStatusFromSignals({ pass = false, partial = false } = {}) {
  if (pass) return GRIDLY_BETA_STATUS.pass;
  if (partial) return GRIDLY_BETA_STATUS.partial;
  return GRIDLY_BETA_STATUS.needsWork;
}

function gridlyBetaReadinessScore(statuses = []) {
  const weights = {
    [GRIDLY_BETA_STATUS.pass]: 1,
    [GRIDLY_BETA_STATUS.partial]: 0.5,
    [GRIDLY_BETA_STATUS.needsWork]: 0
  };
  const safeStatuses = statuses.filter((status) => Object.prototype.hasOwnProperty.call(weights, status));
  if (!safeStatuses.length) return 0;
  const score = safeStatuses.reduce((total, status) => total + weights[status], 0) / safeStatuses.length;
  return Math.round(score * 100);
}

function gridlyBetaReadinessAudit() {
  const target = typeof window !== "undefined" ? window : globalThis;
  const hasDocument = typeof document !== "undefined";
  const safeArrayLength = (value) => Array.isArray(value) ? value.length : 0;
  const helperAvailable = (name) => typeof target?.[name] === "function";
  const elementPresent = (id) => hasDocument && Boolean(document.getElementById(id));
  const selectorPresent = (selector) => hasDocument && Boolean(document.querySelector(selector));
  const runAuditSafely = (fn, ...args) => {
    if (typeof fn !== "function") return null;
    try {
      return fn(...args);
    } catch (_error) {
      return null;
    }
  };

  const travelTimeAudit = runAuditSafely(target?.gridlyTravelTimeAudit);
  const routeWatchDisplayAudit = runAuditSafely(target?.gridlyRouteWatchDisplayAudit);
  const portraitAudit = runAuditSafely(target?.gridlyPortraitStabilitySmokeAudit);
  const analyticsAudit = runAuditSafely(typeof gridlyAnalyticsAudit === "function" ? gridlyAnalyticsAudit : target?.gridlyAnalyticsAudit);
  const telemetryAudit = runAuditSafely(typeof gridlyOperationalTelemetryAudit === "function" ? gridlyOperationalTelemetryAudit : target?.gridlyOperationalTelemetryAudit);
  const hazardLifecycleAudit = runAuditSafely(target?.gridlyHazardLifecycleAudit, { auditOnly: true });

  const routeWatchStatus = gridlyBetaStatusFromSignals({
    pass: Boolean(travelTimeAudit?.baselineReady && travelTimeAudit?.routeImpactReady && routeWatchDisplayAudit?.displayApplied),
    partial: Boolean(helperAvailable("gridlyTravelTimeAudit") || helperAvailable("gridlyRouteWatchDisplayAudit") || routeWatchActivated || target?.__gridlyRouteWatchActive)
  });
  const portraitStatus = gridlyBetaStatusFromSignals({
    pass: Boolean(portraitAudit?.portraitReady || portraitAudit?.betaReady || portraitAudit?.smokeReady),
    partial: Boolean(helperAvailable("gridlyPortraitStabilitySmokeAudit") || helperAvailable("gridlyPortraitV2LayerAudit") || elementPresent("gridlyPortraitV2"))
  });
  const alertStatus = gridlyBetaStatusFromSignals({
    pass: Boolean(helperAvailable("gridlyVisualConsistencyAudit") && (safeArrayLength(target?.__gridlyLatestAlertsForRender) > 0 || selectorPresent(".alert-item, .gridly-alert-title, [data-gridly-alert-title]"))),
    partial: Boolean(typeof getAlertsSurfaceSnapshot === "function" || typeof renderUnifiedIncidents === "function" || elementPresent("alertsList") || selectorPresent("[data-section='alerts']"))
  });
  const reportingStatus = gridlyBetaStatusFromSignals({
    pass: Boolean(typeof createSharedHazardReport === "function" && typeof loadSharedReports === "function" && typeof normalizeReports === "function"),
    partial: Boolean(typeof loadSharedReports === "function" || elementPresent("manualReportBtn") || elementPresent("desktopReportNearMeBtnRail") || elementPresent("mobileCrossingReportBtn"))
  });
  const railCrossingStatus = gridlyBetaStatusFromSignals({
    pass: Boolean(safeArrayLength(crossings) > 0 && crossingMarkers instanceof Map && crossingMarkers.size > 0 && typeof loadCrossings === "function"),
    partial: Boolean(typeof loadCrossings === "function" || typeof fetchFraCrossings === "function" || helperAvailable("gridlyCrossingPipelineAudit") || safeArrayLength(crossings) > 0)
  });
  const hazardStatus = gridlyBetaStatusFromSignals({
    pass: Boolean(hazardLifecycleAudit?.lifecycleClassifierAvailable && hazardLifecycleAudit?.lifecycleAuditAvailable && safeArrayLength(activeHazards) > 0),
    partial: Boolean(typeof gridlyClassifyHazardLifecycle === "function" || helperAvailable("gridlyHazardLifecycleAudit") || safeArrayLength(activeHazards) > 0 || typeof getLiveHazardIncidents === "function")
  });
  const analyticsStatus = gridlyBetaStatusFromSignals({
    pass: Boolean(analyticsAudit?.betaReady && analyticsAudit?.eventHistoryReady && (Number(analyticsAudit?.crossingEventCount || 0) + Number(analyticsAudit?.hazardEventCount || 0) > 0)),
    partial: Boolean(analyticsAudit?.loaded || typeof gridlyAnalyticsAudit === "function" || helperAvailable("gridlyAnalyticsAudit"))
  });
  const telemetryStatus = gridlyBetaStatusFromSignals({
    pass: Boolean(telemetryAudit?.betaSafe && telemetryAudit?.telemetryReady && Number(telemetryAudit?.reportsCreated || 0) > 0),
    partial: Boolean(telemetryAudit?.telemetryReady || typeof gridlyOperationalTelemetryAudit === "function" || helperAvailable("gridlyOperationalTelemetryAudit"))
  });
  const notificationStatus = gridlyBetaStatusFromSignals({
    pass: false,
    partial: Boolean(gridlySafeLocalStorageHas(SMART_ALERTS_STORAGE_KEY) || elementPresent("settingsRouteAlertsToggle") || selectorPresent("[data-v2-settings-field^='notifications.']"))
  });

  const knownRisks = [
    {
      risk: "hazard aging",
      severity: "high",
      status: hazardStatus === GRIDLY_BETA_STATUS.pass ? "partially mitigated" : "beta blocker",
      rationale: "Hazard trust depends on age, confirmation count, and clear-state handling before stale reports can be trusted at beta scale."
    },
    {
      risk: "stale reports",
      severity: "high",
      status: reportingStatus === GRIDLY_BETA_STATUS.pass ? "watch" : "beta blocker",
      rationale: "Reports need visible freshness, validation, and lifecycle review so inactive road or rail reports do not remain prominent."
    },
    {
      risk: "location specificity",
      severity: "high",
      status: alertStatus === GRIDLY_BETA_STATUS.pass ? "watch" : "needs validation",
      rationale: "Alert trust improves only when road, crossing, corridor, and route-impact language points users to a specific location."
    },
    {
      risk: "notification logic",
      severity: "medium",
      status: "deferred architecture",
      rationale: "Notification preferences exist as storage/UI architecture, but delivery, targeting, throttling, and quiet-hour rules are not beta-ready."
    },
    {
      risk: "historical intelligence gaps",
      severity: "medium",
      status: analyticsStatus === GRIDLY_BETA_STATUS.pass ? "watch" : "needs work",
      rationale: "Historical confidence needs enough event history to support repeat-location patterns, typical duration, and commuter timing guidance."
    },
    {
      risk: "report validation",
      severity: "high",
      status: "needs work",
      rationale: "Community reports need confirmation, duplicate handling, and quality scoring before they should drive high-confidence beta decisions."
    },
    {
      risk: "TxDOT integration",
      severity: "low",
      status: "deferred / experimental",
      rationale: "TxDOT fetch is available but startup integration is disabled by default and is not beta-critical for mobile stability."
    }
  ];

  const recommendedNextPriorities = [
    {
      rank: 1,
      priority: "Hazard lifecycle framework",
      reasoning: "This is the highest trust dependency: aging, stale-report handling, confirmations, and clear/expire candidates determine whether beta users can rely on hazard state."
    },
    {
      rank: 2,
      priority: "Historical intelligence",
      reasoning: "Event history can turn repeated blocked crossings, recurring road hazards, and typical durations into useful beta guidance without adding new external systems."
    },
    {
      rank: 3,
      priority: "Alert quality/location specificity",
      reasoning: "Alerts should consistently identify the affected road, crossing, corridor, route relevance, age, and confidence so users understand why an alert matters."
    },
    {
      rank: 4,
      priority: "Beta user testing",
      reasoning: "User validation should test whether commuters understand alert phrasing, report flows, route-watch signals, and stale/clear states in real Liberty County conditions."
    },
    {
      rank: 5,
      priority: "Notification strategy",
      reasoning: "Notification delivery should remain behind beta readiness work until targeting, consent, throttle, location specificity, and quiet-hour policies are defined."
    }
  ];

  const statuses = [
    routeWatchStatus,
    portraitStatus,
    alertStatus,
    reportingStatus,
    railCrossingStatus,
    hazardStatus,
    analyticsStatus,
    telemetryStatus,
    notificationStatus
  ];

  return {
    routeWatchStatus,
    portraitStatus,
    alertStatus,
    reportingStatus,
    railCrossingStatus,
    hazardStatus,
    analyticsStatus,
    telemetryStatus,
    notificationStatus,
    knownRisks,
    betaReadinessScore: gridlyBetaReadinessScore(statuses),
    recommendedNextPriorities
  };
}

function gridlyBetaReadinessReviewAudit() {
  const target = typeof window !== "undefined" ? window : globalThis;
  const hasDocument = typeof document !== "undefined";
  const findings = [];
  const reviewedAreas = [
    "Feedback",
    "Route Watch",
    "Destination Search",
    "Saved Places",
    "Current Location",
    "Reporting",
    "Alerts",
    "Awareness Brief",
    "Community Pulse",
    "Settings",
    "Desktop",
    "Onboarding",
    "Safety Messaging"
  ];
  const runAuditSafely = (fn, ...args) => {
    if (typeof fn !== "function") return null;
    try {
      return fn(...args);
    } catch (error) {
      findings.push(`Audit helper ${fn.name || "anonymous"} failed during V261.1 review: ${String(error?.message || error || "unknown error")}`);
      return null;
    }
  };
  const text = (node) => String(node?.textContent || "").replace(/\s+/g, " ").trim();
  const visible = (node) => {
    if (!node || !hasDocument) return false;
    try {
      if (node.hidden || node.hasAttribute?.("hidden") || node.hasAttribute?.("inert")) return false;
      const style = typeof getComputedStyle === "function" ? getComputedStyle(node) : null;
      if (style && (style.display === "none" || style.visibility === "hidden" || style.opacity === "0")) return false;
      const rect = typeof node.getBoundingClientRect === "function" ? node.getBoundingClientRect() : null;
      if (rect && rect.width === 0 && rect.height === 0 && node.offsetParent === null) return false;
      return true;
    } catch (_error) {
      return true;
    }
  };
  const hiddenBecauseClosed = (node) => Boolean(node && !visible(node));
  const elementPresent = (id) => hasDocument && Boolean(document.getElementById(id));
  const selectorPresent = (selector) => hasDocument && Boolean(document.querySelector(selector));
  const visibleSelectorPresent = (selector) => hasDocument && Array.from(document.querySelectorAll(selector)).some(visible);
  const allVisible = (selector) => hasDocument ? Array.from(document.querySelectorAll(selector)).filter(visible) : [];
  const helperAvailable = (name) => typeof target?.[name] === "function";

  const feedbackSubmissionAudit = runAuditSafely(target?.gridlyFeedbackSubmissionAudit);
  const directFeedbackReadinessAudit = runAuditSafely(target?.gridlyDirectFeedbackReadinessAudit);
  const feedbackExperienceAudit = runAuditSafely(target?.gridlyFeedbackExperienceAudit);
  const routeAudit = runAuditSafely(target?.gridlyRouteWatchDisplayAudit);
  const destinationSearchAudit = runAuditSafely(target?.gridlyDestinationSearchShellAudit);
  const routeOwnershipAudit = runAuditSafely(target?.gridlyRouteOwnershipAudit);
  const routeOriginAudit = runAuditSafely(target?.gridlyRouteOriginAudit);
  const destinationOriginAudit = runAuditSafely(target?.gridlyDestinationCurrentLocationOriginAudit);
  const currentLocationAudit = runAuditSafely(target?.gridlyAppLocationReadinessAudit);
  const reportingAudit = runAuditSafely(target?.gridlyReportSubmissionAudit) || runAuditSafely(target?.gridlyReportingAudit);
  const legacyVisualConsistencyAudit = runAuditSafely(target?.gridlyVisualConsistencyAudit);
  const alertsVisualConsistencyBlockerAudit = runAuditSafely(target?.gridlyAlertsVisualConsistencyBlockerAudit);
  const alertsVisualConsistencyAuditAvailable = Boolean(alertsVisualConsistencyBlockerAudit?.available === true);
  const alertsVisualConsistencyBetaReady = Boolean(
    alertsVisualConsistencyAuditAvailable
    && alertsVisualConsistencyBlockerAudit?.blockerPresent === false
    && alertsVisualConsistencyBlockerAudit?.consumerFriendlyPass === true
  );
  const alertsVisualConsistencyBlocksBeta = Boolean(
    alertsVisualConsistencyAuditAvailable
    && (
      alertsVisualConsistencyBlockerAudit?.blockerPresent === true
      || (
        alertsVisualConsistencyBlockerAudit?.consumerFriendlyPass === false
        && alertsVisualConsistencyBlockerAudit?.userVisibleIssueDetected === true
      )
    )
  );
  const routeBlockerClassificationAudit = runAuditSafely(target?.gridlyBetaRouteBlockerClassificationAudit, { skipBetaReadiness: true });
  const routeBlockerClassificationAvailable = Boolean(routeBlockerClassificationAudit && routeBlockerClassificationAudit.available !== false);
  const routeClassificationRecommendedBetaBlockers = Array.isArray(routeBlockerClassificationAudit?.recommendedBetaBlockers)
    ? routeBlockerClassificationAudit.recommendedBetaBlockers
    : [];
  const routeStateClassifications = Array.isArray(routeBlockerClassificationAudit?.classifications)
    ? routeBlockerClassificationAudit.classifications
    : [];
  const actualUserVisibleRouteIssueDetected = Boolean(routeBlockerClassificationAudit?.actualUserVisibleRouteIssueDetected);
  const nonUserFacingRouteStatesIgnored = Boolean(
    routeBlockerClassificationAvailable
    && !actualUserVisibleRouteIssueDetected
    && routeClassificationRecommendedBetaBlockers.length === 0
  );

  const visibleDeadButtonCandidates = allVisible("button").filter((button) => {
    const label = text(button) || button.getAttribute("aria-label") || button.id || "button";
    const disabled = button.disabled || button.getAttribute("aria-disabled") === "true";
    const explicitlyPlaceholder = /coming soon|coming later|not available|placeholder/i.test(label) || /coming soon|coming later|not available|placeholder/i.test(button.title || "");
    if (explicitlyPlaceholder) return true;
    if (!disabled) return false;
    return !/route watch|alternate route|finish|current location/i.test(label);
  });
  const deadButtonCount = visibleDeadButtonCandidates.length;

  const placeholderExperienceNodes = allVisible(".settings-placeholder-note, .muted, [data-placeholder], .desktop-business-note, p, strong, h2, h3").filter((node) => {
    const copy = text(node);
    if (!copy) return false;
    if (/^No live corridor data yet$|^None yet$|^Loading$|^Checking$/i.test(copy)) return false;
    return /coming soon|coming later|placeholder|not available in Settings|No cleanup or test tools are available/i.test(copy);
  });
  const placeholderExperienceCount = placeholderExperienceNodes.length;

  const onboardingReady = Boolean(
    elementPresent("gridlyWelcomeOnboarding")
    && elementPresent("gridlyWelcomeNextBtn")
    && elementPresent("gridlyWelcomeFinishBtn")
    && hasDocument
    && document.querySelectorAll("[data-gridly-welcome-step]").length >= 5
    && typeof openGridlyWelcomeOnboarding === "function"
  );
  const onboardingTownChoicePresent = selectorPresent("[data-gridly-town='Dayton']");
  const safetyStatementPresent = Boolean(
    hasDocument
    && /do not use while driving|pull over|emergency|911|not for emergencies|drive safely|while driving/i.test(text(document.body))
  );
  const desktopGatePresent = Boolean(
    selectorPresent(".tactical-landscape-gate")
    && selectorPresent(".desktop-left-rail")
    && selectorPresent(".desktop-business-note[hidden]")
  );

  const feedbackFlowRoot = hasDocument ? document.querySelector("[data-gridly-feedback-flow]") : null;
  const feedbackAcknowledgementNode = feedbackFlowRoot?.parentElement?.querySelector?.("[data-gridly-feedback-acknowledgement]") || (hasDocument ? document.getElementById("settingsFeedbackStatus") : null);
  const directFeedbackSubmitButton = feedbackFlowRoot?.querySelector?.("[data-gridly-feedback-submit]") || (hasDocument ? document.getElementById("settingsSubmitFeedbackBtn") : null);
  const directFeedbackFallbackButton = feedbackFlowRoot?.querySelector?.("[data-gridly-feedback-prepare]") || (hasDocument ? document.getElementById("settingsPrepareFeedbackEmailBtn") : null);
  const feedbackFormHiddenBecauseClosed = Boolean(feedbackFlowRoot && !visible(feedbackFlowRoot));
  const directSubmissionImplemented = Boolean(
    typeof submitGridlyDirectFeedback === "function"
    && typeof buildGridlyDirectFeedbackPayload === "function"
    && directFeedbackSubmitButton
    && (directFeedbackReadinessAudit?.directSubmissionImplemented !== false)
  );
  const feedbackFallbackAvailable = Boolean(
    directFeedbackReadinessAudit?.emailFallbackPreserved
    || feedbackSubmissionAudit?.emailFallbackAvailable
    || (typeof prepareGridlyFeedbackEmail === "function" && typeof buildGridlyFeedbackMailtoUrl === "function" && directFeedbackFallbackButton && GRIDLY_FEEDBACK_EMAIL_RECIPIENT)
  );
  const privacySafeMetadataOnly = Boolean(
    directFeedbackReadinessAudit?.privacySafeMetadataOnly
    || (
      typeof buildGridlyDirectFeedbackPayload === "function"
      && !Object.prototype.hasOwnProperty.call(buildGridlyDirectFeedbackPayload("Bug", "Test"), "user_agent")
    )
  );
  const lastFeedbackInsertSucceeded = Boolean(directFeedbackReadinessAudit?.lastInsertSucceeded);
  const feedbackAcknowledgementVisible = Boolean(
    directFeedbackReadinessAudit?.acknowledgementVisible
    || feedbackSubmissionAudit?.acknowledgementVisible
    || visible(feedbackAcknowledgementNode)
  );
  const directFeedbackReady = Boolean(
    (feedbackSubmissionAudit?.betaReady || directFeedbackReadinessAudit?.betaReadyForImplementation || lastFeedbackInsertSucceeded)
    && directSubmissionImplemented
    && feedbackFallbackAvailable
    && privacySafeMetadataOnly
    && (!directFeedbackReadinessAudit?.insertAttempted || lastFeedbackInsertSucceeded || feedbackAcknowledgementVisible)
  );
  const oldFeedbackSystemReady = Boolean(
    feedbackSubmissionAudit?.betaReady
    && directSubmissionImplemented
    && feedbackFallbackAvailable
    && privacySafeMetadataOnly
    && feedbackExperienceAudit?.consumerFriendlyPass !== false
  );
  const feedbackReadinessFalseNegative = Boolean(
    !oldFeedbackSystemReady
    && directFeedbackReady
    && (feedbackFormHiddenBecauseClosed || lastFeedbackInsertSucceeded || feedbackAcknowledgementVisible)
  );
  const feedbackSystemReady = Boolean(
    directFeedbackReady
    && (feedbackExperienceAudit?.consumerFriendlyPass !== false || feedbackReadinessFalseNegative || feedbackFormHiddenBecauseClosed)
  );

  const savedPlacesReady = Boolean(
    elementPresent("settingsManageSavedPlacesBtn")
    && elementPresent("settingsSavedPlacesList")
    && elementPresent("routeWatchStartSelect")
    && elementPresent("routeWatchDestinationSelect")
  );
  const destinationSearchShell = hasDocument ? document.getElementById("gridlySearchShell") : null;
  const destinationSearchAvailable = Boolean(
    elementPresent("gridlySearchShell")
    && elementPresent("gridlyAddressSearchInput")
    && (helperAvailable("gridlyDestinationSearchShellAudit") || typeof openGridlyDestinationSearchSurface === "function" || typeof showGridlySearchShell === "function")
    && (!destinationSearchAudit || (destinationSearchAudit.shellExists !== false && destinationSearchAudit.inputExists !== false))
  );
  const destinationSearchHiddenBecauseClosed = Boolean(
    destinationSearchAvailable
    && destinationSearchShell
    && (destinationSearchAudit?.shellHidden || destinationSearchAudit?.shellHasHiddenAttribute || hiddenBecauseClosed(destinationSearchShell))
  );
  const routeOwnershipAuditPass = Boolean(
    routeOwnershipAudit
    && routeOwnershipAudit?.available !== false
    && (routeOwnershipAudit?.routeExitOwnershipPass !== false)
    && (routeOwnershipAudit?.consumerFriendlyPass !== false)
    && (routeOwnershipAudit?.protectedSystemsPass !== false)
  );
  const rawRouteOriginAuditPass = Boolean(
    routeOriginAudit
    && routeOriginAudit?.available !== false
    && (routeOriginAudit?.originOwnershipMatch !== false)
    && (routeOriginAudit?.consumerFriendlyPass !== false)
    && (routeOriginAudit?.protectedSystemsPass !== false)
  );
  const activeRoutePresent = Boolean(routeBlockerClassificationAudit?.activeRoutePresent);
  const routeOriginRequiredInCurrentState = Boolean(activeRoutePresent);
  const routeOriginNotRequiredInCurrentState = Boolean(!routeOriginRequiredInCurrentState);
  const routeOriginAuditPass = Boolean(rawRouteOriginAuditPass || routeOriginNotRequiredInCurrentState);
  const savedPlaceDestinationAuditPass = savedPlacesReady;
  const currentLocationReadinessPass = Boolean(
    currentLocationAudit
    && destinationOriginAudit
    && selectorPresent("[data-v2-control='use-location'], #mobileUseLocationBtn, #manageSourceLocationBtn")
    && (currentLocationAudit?.manualLocationButtonStillAvailable !== false)
    && (currentLocationAudit?.fallbackStillAvailable !== false)
    && (destinationOriginAudit?.consumerFriendlyPass !== false)
  );
  const oldDestinationSearchReady = Boolean(
    elementPresent("gridlySearchShell")
    && elementPresent("gridlyAddressSearchInput")
    && (helperAvailable("gridlyDestinationSearchShellAudit") || typeof openGridlyDestinationSearchSurface === "function")
    && (!destinationSearchAudit || destinationSearchAudit?.searchShellPresent !== false)
  );
  const oldCurrentLocationReady = Boolean(
    selectorPresent("[data-v2-control='use-location'], #mobileUseLocationBtn, #manageSourceLocationBtn")
    && (currentLocationAudit?.manualLocationButtonStillAvailable !== false)
    && (destinationOriginAudit?.consumerFriendlyPass !== false)
  );
  const oldRouteExperienceReady = Boolean(
    savedPlacesReady
    && oldDestinationSearchReady
    && oldCurrentLocationReady
    && elementPresent("routeWatchStartBtn")
    && elementPresent("showFullRouteBtn")
    && elementPresent("stopRouteWatchBtn")
    && (routeAudit?.displayApplied !== false)
  );
  const routeDisplayAppliedFalseDueToCommuteDeltaUnavailable = Boolean(
    routeAudit?.displayApplied === false
    && /commute_delta_unavailable/i.test(String(routeAudit?.displayReason || routeAudit?.reason || routeAudit?.fallbackReason || ""))
  );
  const routeCoreControlsAvailable = Boolean(
    savedPlaceDestinationAuditPass
    && destinationSearchAvailable
    && elementPresent("routeWatchStartBtn")
    && elementPresent("showFullRouteBtn")
    && elementPresent("stopRouteWatchBtn")
  );
  const routeAuditBackedReady = Boolean(
    routeCoreControlsAvailable
    && currentLocationReadinessPass
    && routeOwnershipAuditPass
    && routeOriginAuditPass
    && (routeAudit?.displayApplied !== false || routeDisplayAppliedFalseDueToCommuteDeltaUnavailable)
  );
  const routeClassificationReady = Boolean(
    routeCoreControlsAvailable
    && nonUserFacingRouteStatesIgnored
    && (routeBlockerClassificationAudit?.consumerFriendlyPass !== false)
  );
  const routeExperienceReady = Boolean(routeAuditBackedReady || routeClassificationReady);
  const routeReadinessFalseNegative = Boolean(
    !oldRouteExperienceReady
    && routeExperienceReady
    && (
      destinationSearchHiddenBecauseClosed
      || routeOwnershipAuditPass
      || routeOriginAuditPass
      || nonUserFacingRouteStatesIgnored
      || routeDisplayAppliedFalseDueToCommuteDeltaUnavailable
    )
  );

  const reportingExperienceReady = Boolean(
    elementPresent("manualReportBtn")
    && elementPresent("mobileCrossingReportBtn")
    && elementPresent("mobileHazardReportBtn")
    && typeof createSharedHazardReport === "function"
    && typeof loadSharedReports === "function"
    && (!reportingAudit || reportingAudit?.consumerFriendlyPass !== false)
  );

  const awarenessBriefNode = hasDocument ? document.querySelector("#gridlyV2TopStatusPrimary, #delayRisk, #habitStatusHeadline") : null;
  const alertsNode = hasDocument ? document.getElementById("alertsList") : null;
  const communityPulseNode = hasDocument ? document.getElementById("gridlyCommunityPulseSurface") : null;
  const awarenessBriefAvailable = Boolean(awarenessBriefNode);
  const awarenessBriefHiddenBecauseSheetState = Boolean(awarenessBriefAvailable && !visibleSelectorPresent("#gridlyV2TopStatusPrimary, #delayRisk, #habitStatusHeadline"));
  const alertsAvailable = Boolean(alertsNode && (typeof getAlertsSurfaceSnapshot === "function" || typeof renderUnifiedIncidents === "function" || alertsNode));
  const alertsHiddenBecauseClosed = Boolean(alertsAvailable && hiddenBecauseClosed(alertsNode));
  const communityPulseAvailable = Boolean(communityPulseNode);
  const oldAwarenessExperienceReady = Boolean(
    visibleSelectorPresent("#gridlyV2TopStatusPrimary, #delayRisk, #habitStatusHeadline")
    && selectorPresent("#alertsList")
    && selectorPresent("#gridlyCommunityPulseSurface")
    && selectorPresent(".geo-filter-pill[data-geo-filter='nearby']")
    && !alertsVisualConsistencyBlocksBeta
  );
  const awarenessExperienceReady = Boolean(
    awarenessBriefAvailable
    && alertsAvailable
    && communityPulseAvailable
    && selectorPresent(".geo-filter-pill[data-geo-filter='nearby']")
    && !alertsVisualConsistencyBlocksBeta
  );
  const awarenessReadinessFalseNegative = Boolean(
    !oldAwarenessExperienceReady
    && awarenessExperienceReady
    && (awarenessBriefHiddenBecauseSheetState || alertsHiddenBecauseClosed || hiddenBecauseClosed(communityPulseNode))
  );

  const addSpecificBlockers = (collection, checks) => {
    checks.forEach(([blocked, reason]) => {
      if (blocked) collection.push(reason);
    });
  };
  const feedbackBlockers = [];
  addSpecificBlockers(feedbackBlockers, [
    [!directSubmissionImplemented, "Direct feedback submit helper or bound submit button is missing."],
    [!feedbackFallbackAvailable, "Feedback email fallback is unavailable."],
    [!privacySafeMetadataOnly, "Feedback payload privacy boundary is not verified."],
    [Boolean(directFeedbackReadinessAudit?.insertAttempted && !lastFeedbackInsertSucceeded), "Direct feedback submit has not succeeded in this runtime."],
    [Boolean(directFeedbackReadinessAudit?.insertAttempted && !feedbackAcknowledgementVisible), "Feedback acknowledgement is not visible after a submit attempt."],
    [Boolean(feedbackExperienceAudit?.consumerFriendlyPass === false && !feedbackReadinessFalseNegative && !feedbackFormHiddenBecauseClosed), "Feedback consumer-facing copy or controls failed the experience audit."]
  ]);
  const routeBlockers = [];
  const routeOwnershipAuditBlocking = Boolean(
    !routeOwnershipAuditPass
    && (
      !routeBlockerClassificationAvailable
      || actualUserVisibleRouteIssueDetected
      || /ownership/i.test(routeClassificationRecommendedBetaBlockers.join(" "))
    )
  );
  const routeOriginAuditBlocking = Boolean(
    routeOriginRequiredInCurrentState
    && !routeOriginAuditPass
    && (
      !routeBlockerClassificationAvailable
      || Boolean(routeBlockerClassificationAudit?.routeOriginFailureBlocksBeta)
      || /origin/i.test(routeClassificationRecommendedBetaBlockers.join(" "))
    )
  );
  const currentLocationReadinessBlocking = Boolean(
    !currentLocationReadinessPass
    && (
      !routeBlockerClassificationAvailable
      || actualUserVisibleRouteIssueDetected
      || /Current Location/i.test(routeClassificationRecommendedBetaBlockers.join(" "))
    )
  );
  const routeWatchDisplayAuditBlocking = Boolean(
    routeAudit?.displayApplied === false
    && !routeDisplayAppliedFalseDueToCommuteDeltaUnavailable
    && (
      !routeBlockerClassificationAvailable
      || actualUserVisibleRouteIssueDetected
      || /display/i.test(routeClassificationRecommendedBetaBlockers.join(" "))
    )
  );
  addSpecificBlockers(routeBlockers, [
    [!destinationSearchAvailable, "Destination Search helper or shell/input is missing."],
    [routeOwnershipAuditBlocking, "Route ownership audit is failing."],
    [routeOriginAuditBlocking, "Route origin audit is failing."],
    [!savedPlaceDestinationAuditPass, "Saved Places destination controls are missing."],
    [currentLocationReadinessBlocking, "Current Location route origin controls are missing or failing."],
    [!elementPresent("routeWatchStartBtn"), "Route Watch start button is missing."],
    [!elementPresent("showFullRouteBtn"), "Full Route button is missing."],
    [!elementPresent("stopRouteWatchBtn"), "Stop Route Watch button is missing."],
    [routeWatchDisplayAuditBlocking, "Route Watch display has a user-visible functional issue."]
  ]);
  routeClassificationRecommendedBetaBlockers.forEach((blocker) => {
    if (blocker && !routeBlockers.includes(blocker)) routeBlockers.push(blocker);
  });
  const awarenessBlockers = [];
  addSpecificBlockers(awarenessBlockers, [
    [!awarenessBriefAvailable, "Awareness Brief surface is missing."],
    [!alertsAvailable, "Alerts surface or helper is missing."],
    [!communityPulseAvailable, "Community Pulse surface is missing."],
    [!selectorPresent(".geo-filter-pill[data-geo-filter='nearby']"), "Nearby map filter is missing."],
    [alertsVisualConsistencyBlocksBeta, "Alerts visual consistency audit reports beta polish is not ready."]
  ]);

  if (deadButtonCount) findings.push(`${deadButtonCount} visible dead button candidate(s) detected: ${visibleDeadButtonCandidates.map((button) => text(button) || button.id || "button").slice(0, 5).join(", ")}.`);
  else findings.push("No visible dead buttons were detected in the active DOM snapshot.");
  if (placeholderExperienceCount) findings.push(`${placeholderExperienceCount} visible placeholder experience candidate(s) detected: ${placeholderExperienceNodes.map((node) => text(node)).slice(0, 4).join(" | ")}.`);
  else findings.push("No visible placeholder experiences were detected in the active DOM snapshot.");
  findings.push(feedbackSystemReady ? "Send Feedback is wired for direct submission, preserves the fallback, and is not failed solely because the Settings feedback sheet is closed." : `Feedback readiness has specific blocker(s): ${feedbackBlockers.join(" ") || "review supporting feedback audits."}`);
  findings.push(onboardingReady ? `Onboarding is present with ${hasDocument ? document.querySelectorAll("[data-gridly-welcome-step]").length : 0} steps${onboardingTownChoicePresent ? " and a Dayton town choice" : ""}.` : "Onboarding is missing or not callable from the runtime.");
  findings.push(safetyStatementPresent ? "A visible safety statement was detected." : "No explicit driving/emergency safety statement was detected; add safety copy before a controlled beta.");
  findings.push(desktopGatePresent ? "Desktop surfaces are present and the future business portal is hidden/gated." : "Desktop gating could not be verified from the active DOM snapshot.");
  findings.push(routeExperienceReady ? "Route Watch, destination search, saved places, route ownership, route origin, and current-location readiness are present for beta testing." : `Route readiness has specific blocker(s): ${routeBlockers.join(" ") || "review supporting route audits."}`);
  if (nonUserFacingRouteStatesIgnored) findings.push(`V264.3 route classification ignored non-user-facing route states as blockers: ${(routeStateClassifications.length ? routeStateClassifications : ["none_detected"]).join(", ")}.`);
  if (!actualUserVisibleRouteIssueDetected) findings.push("V264.3 route classification detected no actual user-visible route issue; idle/no-route/closed/displayApplied false classification noise does not create a beta blocker.");
  if (routeDisplayAppliedFalseDueToCommuteDeltaUnavailable) findings.push("Route Watch displayApplied false was caused by commute_delta_unavailable and is not treated as a beta blocker by itself.");
  if (alertsVisualConsistencyBetaReady && legacyVisualConsistencyAudit?.betaPolishReady === false) findings.push("V265.2 alerts visual consistency classification uses the alert-specific V265.1 blocker audit as source of truth; unrelated legacy Settings or Route Watch visual-polish diagnostics are informational only.");
  findings.push(awarenessExperienceReady ? "Awareness Brief, alerts, map filters, and Community Pulse surfaces are present; closed sheets are classified separately from missing surfaces." : `Awareness readiness has specific blocker(s): ${awarenessBlockers.join(" ") || "review supporting awareness audits."}`);
  findings.push(reportingExperienceReady ? "Reporting surfaces and shared-report helpers are present." : "Reporting experience is not fully beta-ready in this runtime.");
  if (feedbackReadinessFalseNegative) findings.push("V261.1 corrected a feedback false negative caused by hidden Settings feedback state or already-successful direct submit evidence.");
  if (routeReadinessFalseNegative) findings.push("V261.1 corrected a route/destination false negative caused by closed destination search or supporting ownership/current-location audits being available.");
  if (awarenessReadinessFalseNegative) findings.push("V261.1 corrected an awareness false negative caused by closed or inactive sheet state rather than missing awareness surfaces.");
  findings.push("First-time Dayton tester path: onboarding can introduce Know Before You Go, choose Dayton as awareness area, optionally set Home/Work, then land on Awareness Brief with map, alerts, reporting, Route Watch, Settings, and Send Feedback available.");

  const betaBlockerCandidates = [];
  addSpecificBlockers(betaBlockerCandidates, [
    [!feedbackSystemReady, feedbackBlockers[0] || "Feedback readiness requires supporting audit review."],
    [!onboardingReady, "Onboarding is not ready."],
    [!safetyStatementPresent, "Explicit safety / emergency-use statement is missing."],
    [!desktopGatePresent, "Desktop gate is not verified."],
    [placeholderExperienceCount > 0, "Visible placeholder experiences remain."],
    [deadButtonCount > 0, "Visible dead buttons remain."],
    [!routeExperienceReady, routeBlockers[0] || "Route readiness requires supporting audit review."],
    [!awarenessExperienceReady, awarenessBlockers[0] || "Awareness readiness requires supporting audit review."],
    [!reportingExperienceReady, "Reporting experience is not fully beta-ready in this runtime."],
    [!directFeedbackReady, feedbackBlockers[0] || "Direct feedback readiness requires supporting audit review."]
  ]);
  const betaBlockers = Array.from(new Set(betaBlockerCandidates));
  const betaStrengths = [
    directFeedbackReady ? "Direct feedback submission has a Supabase path and email fallback." : "Feedback architecture has dedicated audit helpers and fallback visibility.",
    onboardingReady ? "First-run onboarding and Dayton awareness-area selection exist." : "Awareness-area onboarding copy exists in markup for review.",
    savedPlacesReady ? "Saved Places ownership is visible in Settings and Route Watch selectors." : "Saved Places surfaces are partially present.",
    reportingExperienceReady ? "Reporting supports crossing and road-hazard flows." : "Reporting entry points are present for review.",
    awarenessExperienceReady ? "Awareness-first surfaces are structurally present: brief, alerts, map filters, and Community Pulse." : "Awareness Brief and alerts need specific readiness review."
  ];
  const betaBlockerCount = betaBlockers.length;

  const feedbackDiagnostics = {
    directFeedbackReady,
    lastFeedbackInsertSucceeded,
    feedbackAcknowledgementVisible,
    feedbackFallbackAvailable,
    feedbackReadinessFalseNegative,
    feedbackFormHiddenBecauseClosed
  };
  const routeDiagnostics = {
    destinationSearchAvailable,
    destinationSearchHiddenBecauseClosed,
    routeOwnershipAuditPass,
    routeOriginAuditPass,
    rawRouteOriginAuditPass,
    activeRoutePresent,
    routeOriginRequiredInCurrentState,
    routeOriginNotRequiredInCurrentState,
    savedPlaceDestinationAuditPass,
    currentLocationReadinessPass,
    routeReadinessFalseNegative,
    routeClassificationAvailable: routeBlockerClassificationAvailable,
    routeStateClassifications,
    nonUserFacingRouteStatesIgnored,
    actualUserVisibleRouteIssueDetected,
    recommendedRouteBetaBlockers: routeClassificationRecommendedBetaBlockers,
    routeDisplayAppliedFalseDueToCommuteDeltaUnavailable,
    routeDisplayAppliedFalseIgnored: Boolean(routeDisplayAppliedFalseDueToCommuteDeltaUnavailable && !actualUserVisibleRouteIssueDetected),
    routeAuditBackedReady,
    routeClassificationReady
  };
  const awarenessDiagnostics = {
    awarenessBriefAvailable,
    awarenessBriefHiddenBecauseSheetState,
    alertsAvailable,
    alertsHiddenBecauseClosed,
    communityPulseAvailable,
    awarenessReadinessFalseNegative,
    alertsVisualConsistencyAuditAvailable,
    alertsVisualConsistencyBetaReady,
    alertsVisualConsistencyBlocksBeta,
    alertsVisualConsistencyBlockerAudit,
    legacyVisualConsistencyDiagnostics: legacyVisualConsistencyAudit
  };

  return {
    available: true,
    version: "V265.2",
    falseNegativeCleanupApplied: true,
    routeClassificationPatchApplied: true,
    routeOriginClassificationPatchApplied: true,
    alertsVisualConsistencyClassificationPatchApplied: true,
    feedbackSystemReady,
    onboardingReady,
    safetyStatementPresent,
    desktopGatePresent,
    placeholderExperienceCount,
    deadButtonCount,
    routeExperienceReady,
    awarenessExperienceReady,
    reportingExperienceReady,
    directFeedbackReady,
    lastFeedbackInsertSucceeded,
    feedbackAcknowledgementVisible,
    feedbackFallbackAvailable,
    feedbackReadinessFalseNegative,
    destinationSearchAvailable,
    destinationSearchHiddenBecauseClosed,
    routeOwnershipAuditPass,
    routeOriginAuditPass,
    rawRouteOriginAuditPass,
    activeRoutePresent,
    routeOriginRequiredInCurrentState,
    routeOriginNotRequiredInCurrentState,
    savedPlaceDestinationAuditPass,
    currentLocationReadinessPass,
    routeReadinessFalseNegative,
    routeStateClassifications: routeDiagnostics.routeStateClassifications,
    nonUserFacingRouteStatesIgnored,
    actualUserVisibleRouteIssueDetected,
    recommendedRouteBetaBlockers: routeClassificationRecommendedBetaBlockers,
    routeDisplayAppliedFalseDueToCommuteDeltaUnavailable,
    awarenessBriefAvailable,
    awarenessBriefHiddenBecauseSheetState,
    alertsAvailable,
    alertsHiddenBecauseClosed,
    communityPulseAvailable,
    awarenessReadinessFalseNegative,
    alertsVisualConsistencyAuditAvailable,
    alertsVisualConsistencyBetaReady,
    alertsVisualConsistencyBlocksBeta,
    alertsVisualConsistencyBlockerAudit,
    legacyVisualConsistencyDiagnostics: legacyVisualConsistencyAudit,
    feedbackDiagnostics,
    routeDiagnostics,
    awarenessDiagnostics,
    betaBlockerCount,
    betaReady: betaBlockerCount === 0,
    findings,
    reviewedAreas,
    betaBlockers,
    betaStrengths,
    firstTimeDaytonTesterExperience: "A first-time Dayton tester should see onboarding, choose Dayton as their awareness area, optionally save Home/Work, then use Awareness Brief first with Route Watch, reporting, alerts, map, Settings, and Send Feedback available.",
    recommendedNextMilestone: betaBlockerCount === 0 ? "V261.1 controlled beta launch checklist and tester script." : "V261.1 beta blocker closure: address only the specific actionable blockers returned by betaBlockers.",
    mergeRecommendation: "Merge the V261.1 audit-only false-negative cleanup after runtime findings are reviewed on real mobile and desktop devices; do not treat hidden closed sheets as missing systems.",
    protectedSystemsModified: false,
    directionalIntelligencePaused: true,
    trustResolutionDraftOnly: true
  };
}

window.gridlyBetaReadinessAudit = gridlyBetaReadinessAudit;
window.gridlyBetaReadinessReviewAudit = gridlyBetaReadinessReviewAudit;
exposeGridlyAuditHelper("gridlyBetaReadinessAudit", gridlyBetaReadinessAudit);
exposeGridlyAuditHelper("gridlyBetaReadinessReviewAudit", gridlyBetaReadinessReviewAudit);


function gridlyAlertsVisualConsistencyBlockerAudit() {
  const generatedAt = new Date().toISOString();
  const findings = [];
  const addFinding = (classification, severity, question, evidence, recommendedAction) => {
    findings.push({ classification, severity, question, evidence, recommendedAction });
  };
  const normalize = (value = "") => String(value ?? "").replace(/\s+/g, " ").trim();
  const safeArray = (value) => Array.isArray(value) ? value : [];
  const safeDocument = typeof document !== "undefined" ? document : null;
  const safeWindow = typeof window !== "undefined" ? window : globalThis;
  const readStyle = (node) => {
    if (!node || !safeWindow?.getComputedStyle) return null;
    try { return safeWindow.getComputedStyle(node); } catch (error) { return null; }
  };
  const isVisible = (node) => {
    if (!node || typeof node.getBoundingClientRect !== "function") return false;
    const style = readStyle(node);
    const rect = node.getBoundingClientRect();
    return !node.hidden
      && node.getAttribute?.("aria-hidden") !== "true"
      && (!style || (style.display !== "none" && style.visibility !== "hidden" && style.opacity !== "0"))
      && rect.width > 0
      && rect.height > 0;
  };
  const readTextFrom = (node, selector) => normalize(node?.querySelector?.(selector)?.textContent || "");
  const lineFingerprint = (text) => {
    const clean = normalize(text).toLowerCase();
    return {
      hasRoadCue: /\b(?:near|at|on|between|tx|sh|us|fm|cr|road|rd|street|st|avenue|ave|crossing|county road)\b|\b\d{2,4}\b/i.test(clean),
      hasFreshnessCue: /\b(?:just now|latest|updated|last checked|now|\d+\s*(?:m|min|minute|h|hr|hour)s?\s*ago|community reports?|active reports?)\b/i.test(clean),
      hasTrustCue: /\b(?:community|verified|confirmed|matched|approximate|reported|based on|confidence)\b/i.test(clean),
      hasTechnicalCue: /\b(?:risk_score|confidence_score|report_type|hazard_subtype|metadata|debug|raw|undefined|null|NaN)\b/i.test(clean)
    };
  };
  const styleSignature = (node) => {
    const style = readStyle(node);
    if (!style) return null;
    return {
      padding: style.padding,
      marginBottom: style.marginBottom,
      border: style.border,
      borderRadius: style.borderRadius,
      background: style.backgroundColor || style.background,
      display: style.display,
      gap: style.gap || ""
    };
  };
  const titleSignature = (node) => {
    const titleNode = node?.querySelector?.(".gridly-alert-title, strong, .gridly-alert-headline, [data-gridly-alert-title]");
    const style = readStyle(titleNode);
    return {
      text: normalize(titleNode?.textContent || node?.dataset?.gridlyAlertTitle || ""),
      fontSize: style?.fontSize || "",
      fontWeight: style?.fontWeight || "",
      lineHeight: style?.lineHeight || "",
      letterSpacing: style?.letterSpacing || ""
    };
  };
  const alertNodeSnapshot = (() => {
    if (!safeDocument || typeof getGridlyAuditAlertCardNodes !== "function") return { alertCardNodes: [], visibleAlertCards: [], activeAlertsSurface: null };
    try { return getGridlyAuditAlertCardNodes(isVisible); } catch (error) { return { alertCardNodes: [], visibleAlertCards: [], activeAlertsSurface: null, error: String(error?.message || error || "") }; }
  })();
  const visibleRows = safeArray(alertNodeSnapshot.visibleAlertCards).filter((node) => !node?.hasAttribute?.("data-gridly-alert-expand"));
  const alertCards = visibleRows.filter((node) => node?.getAttribute?.("data-gridly-alert-row") === "true" || node?.hasAttribute?.("data-gridly-alert-title"));
  const supplementalRows = visibleRows.filter((node) => !alertCards.includes(node));
  const cacheAlerts = safeArray(safeWindow?.__gridlyLatestAlertsForRender);
  const modelSamples = alertCards.length
    ? alertCards.map((node, index) => {
      const subtitles = Array.from(node.querySelectorAll?.(".gridly-alert-subtitle, small, [data-gridly-alert-location-line], [data-gridly-alert-freshness], [data-gridly-alert-count-line]") || []).map((child) => normalize(child.textContent)).filter(Boolean);
      return {
        index,
        source: "dom",
        title: normalize(node?.dataset?.gridlyAlertTitle || readTextFrom(node, ".gridly-alert-title, strong, .gridly-alert-headline, [data-gridly-alert-title]")),
        locationLine: normalize(node?.dataset?.gridlyAlertLocation || subtitles[0] || ""),
        freshnessCountLine: normalize(subtitles[1] || node?.dataset?.gridlyAlertSummary || ""),
        text: normalize(node.textContent || ""),
        style: styleSignature(node),
        titleStyle: titleSignature(node)
      };
    })
    : cacheAlerts.slice(0, 8).map((alert, index) => {
      const model = typeof buildGridlyAlertCardConsumerModel === "function" ? buildGridlyAlertCardConsumerModel(alert) : {};
      const title = normalize(model.title || alert?.resolvedHeadline || alert?.headline || alert?.title || "");
      const locationLine = normalize(model.locationLine || alert?.locationLine || alert?.location || alert?.roadName || alert?.corridor || "");
      const freshnessCountLine = normalize(model.freshnessCountLine || alert?.minutesText || alert?.timeText || "");
      return { index, source: "render-cache", title, locationLine, freshnessCountLine, text: normalize([title, locationLine, freshnessCountLine].join(" ")), style: null, titleStyle: null };
    });

  const cardsChecked = modelSamples.length;
  const comparableCardCount = Math.max(alertCards.length, modelSamples.length);
  const uniqueStyleCount = new Set(modelSamples.map((sample) => JSON.stringify(sample.style || {}))).size;
  const uniqueTitleStyleCount = new Set(modelSamples.map((sample) => JSON.stringify({
    fontSize: sample.titleStyle?.fontSize || "",
    fontWeight: sample.titleStyle?.fontWeight || "",
    lineHeight: sample.titleStyle?.lineHeight || ""
  }))).size;
  const inconsistentTitleSpacingOnly = new Set(modelSamples.map((sample) => sample.titleStyle?.letterSpacing || "")).size > 1;
  const fingerprints = modelSamples.map((sample) => ({ ...lineFingerprint([sample.title, sample.locationLine, sample.freshnessCountLine].join(" ")), sample }));
  const titlePatternPass = cardsChecked === 0 || modelSamples.every((sample) => sample.title && sample.title.length <= 72 && sample.title.split(/\s+/).length <= 10 && !lineFingerprint(sample.title).hasTechnicalCue);
  const locationPatternPass = cardsChecked === 0 || modelSamples.every((sample) => sample.locationLine && lineFingerprint(sample.locationLine).hasRoadCue && !lineFingerprint(sample.locationLine).hasTechnicalCue);
  const freshnessPatternPass = cardsChecked === 0 || modelSamples.every((sample) => sample.freshnessCountLine && lineFingerprint(sample.freshnessCountLine).hasFreshnessCue && !lineFingerprint(sample.freshnessCountLine).hasTechnicalCue);
  const trustPatternPass = cardsChecked === 0 || fingerprints.every((fingerprint) => fingerprint.hasTrustCue || fingerprint.hasFreshnessCue);
  const cardStylePass = comparableCardCount <= 1 || uniqueStyleCount <= 1;
  const titleStylePass = comparableCardCount <= 1 || uniqueTitleStyleCount <= 1;
  const spacingPass = comparableCardCount <= 1 || cardStylePass;
  const hierarchyPass = Boolean(titleStylePass && titlePatternPass && locationPatternPass && freshnessPatternPass);
  const interactionPass = supplementalRows.every((node) => {
    const text = normalize(node.textContent || "");
    const style = styleSignature(node) || {};
    const isMoreRow = /^\+\s*\d+\s+more/i.test(text);
    return !isMoreRow || (style.borderRadius || style.border || style.padding);
  });
  const technicalIssueDetected = fingerprints.some((fingerprint) => fingerprint.hasTechnicalCue);
  const visualIssueDetected = Boolean(
    cardsChecked > 0
    && (!cardStylePass || !titleStylePass || !titlePatternPass || !locationPatternPass || !freshnessPatternPass || !trustPatternPass || !spacingPass || !hierarchyPass || !interactionPass || technicalIssueDetected)
  );

  if (!cardStylePass) addFinding("spacing", "medium", "Do alert cards visually match one another?", `Detected ${uniqueStyleCount} card style signatures across ${comparableCardCount} alert cards.`, "Presentation Cleanup Needed");
  if (!titlePatternPass || !titleStylePass) addFinding("title_inconsistency", titleStylePass ? "medium" : "low", "Are titles using the same presentation model?", !titleStylePass ? `Title typography has ${uniqueTitleStyleCount} size/weight/line-height signatures.` : "One or more alert titles are missing, too long, or include technical copy.", "Presentation Cleanup Needed");
  if (inconsistentTitleSpacingOnly && titleStylePass) addFinding("title_inconsistency", "info", "Are titles using the same presentation model?", "Only alert title letter-spacing varies; size, weight, and line-height are aligned, so this is not treated as a beta blocker.", "No Patch Needed");
  if (!locationPatternPass) addFinding("location_inconsistency", "medium", "Are location lines using the same presentation model?", "One or more alert cards are missing a road/crossing/location cue in the location line.", "Copy Cleanup Needed");
  if (!freshnessPatternPass) addFinding("freshness_inconsistency", "medium", "Are freshness/count lines using the same presentation model?", "One or more alert cards are missing a freshness or active-report count line.", "Copy Cleanup Needed");
  if (!trustPatternPass) addFinding("trust_inconsistency", "low", "Are trust/confidence states presented consistently?", "Trust is conveyed through community/freshness wording rather than a separate confidence chip on every card.", "Presentation Cleanup Needed");
  if (!interactionPass) addFinding("interaction_inconsistency", "medium", "Do expanded and collapsed alerts follow the same visual language?", "One or more supplemental/expanded alert rows lacks the same card treatment as alert rows.", "Interaction Cleanup Needed");
  if (technicalIssueDetected) addFinding("copy_inconsistency", "high", "Would a beta tester notice visual inconsistency?", "Technical metadata was detected in alert-facing text.", "Copy Cleanup Needed");

  const blockerFindings = findings.filter((finding) => ["medium", "high"].includes(finding.severity));
  const blockerPresent = blockerFindings.length > 0;
  const primaryClassification = blockerFindings.length > 1
    ? "multiple"
    : (blockerFindings[0]?.classification || (findings[0]?.classification || "unknown"));
  const recommendedAction = blockerPresent
    ? (blockerFindings[0]?.recommendedAction || "Presentation Cleanup Needed")
    : "No Patch Needed";
  const oldAudit = typeof safeWindow?.gridlyVisualConsistencyAudit === "function"
    ? (() => { try { return safeWindow.gridlyVisualConsistencyAudit(); } catch (error) { return { auditError: String(error?.message || error || "") }; } })()
    : null;
  if (oldAudit?.betaPolishReady === false && !blockerPresent) {
    addFinding("unknown", "info", "Why did Beta Readiness report an alerts blocker?", "The legacy gridlyVisualConsistencyAudit betaPolishReady flag also depends on non-alert settings/route-watch polish checks, so the betaBlocker can be a false positive for alerts visual consistency.", "No Patch Needed");
  }
  const consumerFriendlyPass = Boolean(cardsChecked === 0 || (!blockerPresent && cardStylePass && titleStylePass && titlePatternPass && locationPatternPass && freshnessPatternPass && spacingPass && hierarchyPass && interactionPass && !technicalIssueDetected));

  return {
    available: true,
    version: "V265.1",
    generatedAt,
    blockerPresent,
    alertCardsConsistent: Boolean(cardStylePass),
    alertTitlesConsistent: Boolean(titleStylePass && titlePatternPass),
    alertLocationFormattingConsistent: Boolean(locationPatternPass),
    alertFreshnessFormattingConsistent: Boolean(freshnessPatternPass),
    alertTrustFormattingConsistent: Boolean(trustPatternPass),
    alertSpacingConsistent: Boolean(spacingPass),
    alertVisualHierarchyConsistent: Boolean(hierarchyPass),
    alertInteractionConsistent: Boolean(interactionPass),
    userVisibleIssueDetected: Boolean(visualIssueDetected),
    blockerReason: blockerPresent ? blockerFindings.map((finding) => finding.evidence).join(" ") : "",
    recommendedAction,
    consumerFriendlyPass,
    classification: primaryClassification,
    cardsChecked,
    visibleAlertCardCount: alertCards.length,
    supplementalAlertRowCount: supplementalRows.length,
    legacyVisualConsistencyBetaPolishReady: oldAudit?.betaPolishReady,
    findings
  };
}

