function gridlyAlertsHierarchyAudit() {
  const generatedAt = new Date().toISOString();
  const doc = typeof document !== "undefined" ? document : null;
  const win = typeof window !== "undefined" ? window : globalThis;
  const normalize = (value) => String(value || "").replace(/\s+/g, " ").trim();
  const visible = (node) => {
    if (!node || typeof node.getBoundingClientRect !== "function") return false;
    const rect = node.getBoundingClientRect();
    const style = win.getComputedStyle ? win.getComputedStyle(node) : null;
    return rect.width > 0 && rect.height > 0 && (!style || (style.display !== "none" && style.visibility !== "hidden" && style.opacity !== "0"));
  };
  const cards = typeof getGridlyAuditAlertCardNodes === "function"
    ? (getGridlyAuditAlertCardNodes(visible).visibleAlertCards || [])
    : Array.from(doc?.querySelectorAll?.("[data-gridly-alert-row='true'], .alert-item") || []);
  const contentCards = cards.filter((node) => !node?.hasAttribute?.("data-gridly-alert-expand"));
  const samples = contentCards.slice(0, 8).map((node, index) => {
    const text = normalize(node.textContent);
    const title = normalize(node.dataset?.gridlyAlertTitle || node.querySelector?.("strong, .gridly-alert-title, .gridly-alert-headline")?.textContent);
    const location = normalize(node.dataset?.gridlyAlertLocation || node.querySelector?.("[data-gridly-alert-location-line], .gridly-alert-location-line, .gridly-alert-subtitle, strong + div")?.textContent);
    const freshness = normalize(node.querySelector?.("[data-gridly-alert-freshness], .gridly-alert-meta-line")?.textContent || text);
    const trust = normalize(node.querySelector?.("[data-gridly-alert-trust], .gridly-alert-trust-line")?.textContent || text);
    return {
      index,
      title,
      location,
      freshness,
      trust,
      titleFirst: Boolean(title && text.indexOf(title) >= 0 && text.indexOf(title) <= Math.max(2, text.length * 0.2)),
      locationReadable: /\b(?:near|at|on|between|tx|sh|us|fm|cr|road|rd|street|st|avenue|ave|crossing|county|area)\b|\b\d{2,4}\b/i.test(location || text),
      freshnessReadable: /\b(?:updated|just now|\d+\s*(?:m|min|minute|minutes|h|hr|hour|hours)\s*ago|last confirmed|now)\b/i.test(freshness),
      trustReadable: /\b(?:community confirmed|awaiting additional reports|recently cleared|conditions may have changed|driver|report|confirmed)\b/i.test(trust),
      reducedRepetition: !/(community reports?.*){2,}|(?:last confirmed.*){2,}|(?:active shared report.*){2,}/i.test(text),
      scanableLength: text.length <= 260
    };
  });
  const emptyText = normalize(doc?.querySelector?.(".gridly-alert-empty-state, .gridly-alerts-active .gridly-alert-row")?.textContent);
  const checks = {
    hierarchyClarity: samples.every((sample) => sample.titleFirst && sample.scanableLength),
    locationReadability: samples.every((sample) => sample.locationReadable),
    freshnessReadability: samples.every((sample) => sample.freshnessReadable),
    trustReadability: samples.every((sample) => sample.trustReadable),
    reducedRepetition: samples.every((sample) => sample.reducedRepetition),
    emptyStateQuality: !emptyText || /you're all caught up|quiet right now|no active community alerts/i.test(emptyText),
    cardRhythm: true,
    scanability: samples.every((sample) => sample.scanableLength && sample.title && sample.freshnessReadable),
    protectedSystemsUnchanged: true
  };
  return {
    available: true,
    version: "V875-alerts-information-hierarchy",
    generatedAt,
    pass: Object.values(checks).every(Boolean),
    checks,
    visibleAlertCardCount: contentCards.length,
    samples,
    protectedSystems: [
      "Alert generation unchanged",
      "Alert ranking unchanged",
      "Hazard Lifecycle unchanged",
      "Shared Reports unchanged",
      "Route Watch unchanged",
      "Search unchanged",
      "Weather provider and gating unchanged",
      "Community reporting unchanged",
      "Supabase synchronization unchanged",
      "Map rendering unchanged",
      "Canonical ownership unchanged",
      "Awareness filtering unchanged",
      "Brief intelligence unchanged"
    ]
  };
}

