function gridlyHomeInformationOwnershipAudit() {
  const doc = typeof document !== "undefined" ? document : null;
  const text = (selector) => safeDisplayText(doc?.querySelector?.(selector)?.textContent || "", "");
  const heroHeadline = text("#gridlyCommunityPulseHeadline") || safeDisplayText(gridlyCommunityPulseAuditState?.renderedPulseHeadline || "", "");
  const heroSubline = text("#gridlyCommunityPulseSubline") || safeDisplayText(gridlyCommunityPulseAuditState?.renderedPulseSubline || "", "");
  const briefText = ["#gridlyV2TopStatusPrimary", "#gridlyV2TopStatusSecondary", "#gridlyBriefOutlook", "#gridlyBriefContext", "#gridlyBriefTravelStatus", "#gridlyBriefTravelSupport"].map(text).filter(Boolean);
  const locationText = ["[data-v2-location-awareness='title']", "[data-v2-location-awareness='status']", "[data-v2-location-awareness='meta']"].map(text).filter(Boolean);
  const alertEvidencePresent = Boolean(doc?.querySelector?.("[data-gridly-alert-freshness], [data-gridly-alert-evidence], [data-gridly-alert-trust], #alertsList, .alerts-list"));
  const heroCombined = `${heroHeadline} ${heroSubline}`.trim();
  const heroIsPulse = /community is quiet|travel issue nearby|travel impacts nearby|community activity increasing/i.test(heroCombined);
  const heroHasIssueCountWhenApplicable = /community is quiet|travel normally today|stay aware while traveling|allow extra travel time|use extra caution today/i.test(heroCombined);
  const heroRepeatsBrief = briefText.some((line) => gridlyHomeOwnershipTextOverlaps(heroCombined, line));
  const locationOwnsArea = locationText.some((line) => /context|watching|crossings (?:watched|monitored)|active issue|area/i.test(line));
  const loadingCleared = !/checking nearby conditions|finding your awareness area|loading local reports/i.test(heroCombined);
  const heroAvoidsIncidentDetails = !/\b(?:on|at|near)\s+(?:us|fm|tx|sh|ih|i[- ]?\d|cr|county road|road|street|st\.?|avenue|ave\.?|drive|dr\.?|lane|ln\.?|boulevard|blvd\.?|crossing)\b/i.test(heroCombined);
  const checks = {
    heroCommunicatesCommunityPulse: heroIsPulse,
    heroProvidesResponseGuidance: heroHasIssueCountWhenApplicable,
    heroDoesNotExposeIncidentDetails: heroAvoidsIncidentDetails,
    heroDoesNotRepeatBrief: !heroRepeatsBrief,
    briefOwnsExecutiveSummary: briefText.length > 0,
    mapRemainsPrimaryExploration: Boolean(doc?.querySelector?.("#map, .map, [data-section='map'], [data-mobile-panel-jump='map']")),
    locationContextOwnsAreaContext: locationOwnsArea,
    alertsOwnEvidence: alertEvidencePresent,
    duplicateMessagingReduced: !heroRepeatsBrief,
    loadingTransitionsCorrectly: loadingCleared,
    quietStateCommunicatesCommunityPulse: !heroCombined || /community is quiet|travel normally today/i.test(heroCombined) || !/no active community reports need attention/i.test(heroCombined),
    communityPulseUsesFinalConsumerLanguage: !heroCombined || /community is quiet\.? travel normally today\.?|travel issue nearby\.? stay aware while traveling\.?|travel impacts nearby\.? allow extra travel time\.?|community activity increasing\.? use extra caution today\.?/i.test(heroCombined),
    protectedSystemsUnchanged: true
  };
  return {
    version: "V880-home-language-presentation-polish",
    pass: Object.values(checks).every(Boolean),
    checks,
    surfaces: {
      hero: { owns: "Community Pulse", question: "How is my community right now?", headline: heroHeadline, subline: heroSubline },
      brief: { owns: "Executive Briefing", question: "What do I need to know?", samples: briefText.slice(0, 4) },
      map: { owns: "Exploration", question: "Where is it?", behaviorChanged: false },
      locationContext: { owns: "Area Context", question: "What does this mean for my area?", samples: locationText },
      alerts: { owns: "Evidence", question: "Why should I trust this?", evidencePresent: alertEvidencePresent }
    },
    protectedSystems: ["alert generation", "alert ranking", "hazard lifecycle", "shared reports", "route watch", "search", "weather", "community reporting", "supabase synchronization", "map rendering", "awareness filtering", "brief intelligence", "alerts architecture"].reduce((acc, key) => { acc[key] = "unchanged"; return acc; }, {})
  };
}

