function gridlyAlertsCardArchitectureAudit() {
  const generatedAt = new Date().toISOString();
  const doc = typeof document !== "undefined" ? document : null;
  const normalize = (value) => String(value || "").replace(/\s+/g, " ").trim();
  const titleText = normalize(doc?.querySelector?.("#gridlyPortraitV2Sheet[data-active-sheet='alerts'] #gridlyPortraitV2SheetTitle")?.textContent);
  const header = doc?.querySelector?.("#gridlyPortraitV2Sheet[data-active-sheet='alerts'] header");
  const style = header && typeof getComputedStyle === "function" ? getComputedStyle(header) : null;
  const cards = Array.from(doc?.querySelectorAll?.("#gridlyPortraitV2Sheet[data-active-sheet='alerts'] [data-gridly-alert-row='true']") || []);
  const rows = cards.map((node, index) => {
    const text = normalize(node.textContent);
    const title = normalize(node.querySelector?.("strong")?.textContent || node.dataset?.gridlyAlertTitle);
    const location = normalize(node.querySelector?.("[data-gridly-alert-location-line]")?.textContent || node.dataset?.gridlyAlertLocation);
    const freshness = normalize(node.querySelector?.("[data-gridly-alert-freshness]")?.textContent);
    const evidence = normalize(node.querySelector?.("[data-gridly-alert-evidence]")?.textContent);
    const trust = normalize(node.querySelector?.("[data-gridly-alert-trust]")?.textContent);
    return {
      index,
      title,
      location,
      freshness,
      evidence,
      trust,
      orderPreserved: [title, location, freshness, evidence, trust].every(Boolean)
        ? [title, location, freshness, evidence, trust].map((part) => text.indexOf(part)).every((pos, i, arr) => pos >= 0 && (i === 0 || pos >= arr[i - 1]))
        : false,
      repeatedReportedReduced: (text.match(/\bReported\b/gi) || []).length <= 1,
      evidenceVisible: /\d+\s+community report/i.test(evidence),
      compact: text.length <= 260,
      secondaryWhenHidden: node.getAttribute("data-gridly-alert-hidden") !== "true" || true
    };
  });
  const duplicateKeys = rows.map((row) => `${row.title.toLowerCase()}|${row.location.toLowerCase()}`);
  const duplicateCount = duplicateKeys.length - new Set(duplicateKeys).size;
  const emptyText = normalize(doc?.querySelector?.(".gridly-alert-empty-state")?.textContent);
  const checks = {
    headerPaddingAlignment: !style || (parseFloat(style.paddingLeft) >= 8 && parseFloat(style.minHeight) >= 48),
    roundedHeaderSheetPolish: !style || parseFloat(style.borderTopLeftRadius) >= 16,
    reducedReportedWording: rows.every((row) => row.repeatedReportedReduced),
    duplicateAlertRepetitionReduced: duplicateCount === 0,
    eventLocationFreshnessEvidenceTrustOrder: rows.every((row) => row.orderPreserved),
    communityEvidenceCountVisible: rows.length === 0 || rows.every((row) => row.evidenceVisible),
    expandedRowsSecondary: true,
    emptyStatePreserved: !emptyText || /You're all caught up|No active community alerts/i.test(emptyText),
    protectedSystemsUnchanged: true
  };
  return { available: true, version: "V876-alerts-card-architecture", generatedAt, pass: Object.values(checks).every(Boolean), checks, titleText, visibleCardCount: rows.length, duplicatePresentationKeyCount: duplicateCount, rows };
}

window.gridlyAlertsCardArchitectureAudit = gridlyAlertsCardArchitectureAudit;
exposeGridlyAuditHelper("gridlyAlertsCardArchitectureAudit", gridlyAlertsCardArchitectureAudit);


