function gridlyAwarenessClassificationAuditSafeArray(rows) {
  return Array.isArray(rows) ? rows.filter((row) => row && typeof row === "object") : [];
}

function gridlyAwarenessClassificationAuditText(record = {}) {
  return [
    record?.type, record?.category, record?.reportKind, record?.report_kind, record?.kind,
    record?.title, record?.headline, record?.summary, record?.description, record?.detail,
    record?.crossingName, record?.crossing_name, record?.crossingLabel, record?.locationLabel,
    record?.raw?.type, record?.raw?.category, record?.raw?.title, record?.raw?.headline,
    record?.raw?.summary, record?.raw?.description, record?.raw?.detail
  ].filter(Boolean).join(" ").toLowerCase();
}

function gridlyAwarenessClassificationAuditKey(record = {}, index = 0, sourcePath = "runtime") {
  const id = record?.id || record?.report_id || record?.reportId || record?.incidentId || record?.stableIncidentId || record?.crossingId || record?.crossing_id || record?.raw?.id || record?.raw?.report_id;
  if (id !== undefined && id !== null && String(id).trim()) return `id:${String(id).trim()}`;
  const crossingId = record?.crossingId || record?.crossing_id || record?.raw?.crossingId || record?.raw?.crossing_id;
  if (crossingId !== undefined && crossingId !== null && String(crossingId).trim()) return `crossing:${String(crossingId).trim()}`;
  const coords = gridlyCoordinateFromRecord(record);
  const type = String(record?.type || record?.report_type || record?.category || "unknown").toLowerCase();
  return `${sourcePath}:${coords ? `${coords.lat.toFixed(4)},${coords.lng.toFixed(4)}` : "no-coords"}:${type}:${index}`;
}

function gridlyAwarenessClassificationAuditIsCrossing(record = {}) {
  if (!record || typeof record !== "object") return false;
  if (record?.crossingId || record?.crossing_id || record?.crossing_id_text || record?.crossingName || record?.crossing_name || record?.crossingLabel) return true;
  if (typeof isGridlyCrossingReportRecord === "function" && isGridlyCrossingReportRecord(record)) return true;
  return /\b(?:rail|train|crossing|blocked crossing|blocking crossing)\b/i.test(gridlyAwarenessClassificationAuditText(record));
}

function gridlyAwarenessClassificationAuditIsRoadHazard(record = {}, sourcePath = "runtime") {
  if (gridlyIsClearedHazardAwarenessRecord(record)) return false;
  const id = String(record?.id || "").toLowerCase();
  const type = String(record?.type || record?.report_type || record?.reportType || record?.category || record?.raw?.type || record?.raw?.report_type || "").toLowerCase();
  const reportKind = String(record?.reportKind || record?.report_kind || record?.kind || "").toLowerCase();
  if (String(sourcePath || "").includes("activeHazards")) return true;
  if (String(sourcePath || "").includes("unifiedIncidents") && id.startsWith("road-")) return true;
  if (reportKind === "hazard" || reportKind === "road") return true;
  return /hazard|flood|debris|crash|closure|construction|disabled|other_hazard/.test(type);
}

function gridlyAwarenessClassificationAuditCandidate(record = {}, sourcePath = "runtime", index = 0) {
  const classifiedAsCrossingCondition = gridlyAwarenessClassificationAuditIsCrossing(record);
  const classifiedAsRoadHazard = gridlyAwarenessClassificationAuditIsRoadHazard(record, sourcePath);
  return {
    key: gridlyAwarenessClassificationAuditKey(record, index, sourcePath),
    id: record?.id || record?.report_id || record?.reportId || record?.incidentId || record?.raw?.id || null,
    type: record?.type || record?.report_type || record?.reportType || record?.raw?.type || "",
    category: record?.category || record?.reportCategory || record?.raw?.category || "",
    reportKind: record?.reportKind || record?.report_kind || record?.kind || "",
    crossingId: record?.crossingId || record?.crossing_id || record?.raw?.crossingId || record?.raw?.crossing_id || null,
    crossing_id: record?.crossing_id || record?.crossingId || record?.raw?.crossing_id || record?.raw?.crossingId || null,
    title: record?.title || "",
    headline: record?.headline || "",
    summary: record?.summary || record?.description || record?.detail || "",
    sourcePath,
    classifiedAsRoadHazard,
    classifiedAsCrossingCondition
  };
}

function gridlyBuildAwarenessClassificationAudit(options = {}) {
  const gridlyAwarenessClassificationAuditStateSnapshot = {
    gridlyAlertAreaFilterState: typeof gridlyAlertAreaFilterState !== "undefined" ? gridlyAlertAreaFilterState : undefined
  };
  try {
    const sourceActiveHazards = gridlyAwarenessClassificationAuditSafeArray(Array.isArray(options?.activeHazards) ? options.activeHazards : (typeof activeHazards !== "undefined" ? activeHazards : []));
    const sourceActiveReports = gridlyAwarenessClassificationAuditSafeArray(Array.isArray(options?.activeReports) ? options.activeReports : (typeof activeReports !== "undefined" ? activeReports : []));
    const sourceUnifiedIncidents = gridlyAwarenessClassificationAuditSafeArray(Array.isArray(options?.unifiedIncidents) ? options.unifiedIncidents : (typeof getUnifiedIncidents === "function" ? getUnifiedIncidents() : []));
    const sourceAlerts = gridlyAwarenessClassificationAuditSafeArray(Array.isArray(options?.alerts) ? options.alerts : (typeof getGridlyAlertsSurfaceActiveCommunityReportRows === "function" ? getGridlyAlertsSurfaceActiveCommunityReportRows({ limit: 20 }) : []));
    const awarenessModel = typeof buildGridlyLightweightActiveAwareness === "function"
      ? buildGridlyLightweightActiveAwareness({ activeHazards: sourceActiveHazards, activeReports: sourceActiveReports, alerts: sourceAlerts, lifecycleAuditReadOnly: true })
      : null;
    const candidateGroups = [
      ["activeHazards", sourceActiveHazards],
      ["activeReports", sourceActiveReports],
      ["unifiedIncidents", sourceUnifiedIncidents],
      ["alertCandidates", sourceAlerts]
    ];
    const allCandidates = candidateGroups.flatMap(([sourcePath, rows]) => rows.map((row, index) => gridlyAwarenessClassificationAuditCandidate(row, sourcePath, index)));
    const duplicateSuppressionAudit = typeof gridlyBuildClearedDuplicateRoadHazardSuppressionAudit === "function"
      ? gridlyBuildClearedDuplicateRoadHazardSuppressionAudit(sourceActiveHazards)
      : { duplicateActiveHazardKeys: [], clearedDuplicateSuppressedCount: 0, duplicateSuppressionReason: "" };
    const duplicateActiveHazardKeySet = new Set(duplicateSuppressionAudit.duplicateActiveHazardKeys || []);
    const awarenessCandidates = gridlyAwarenessClassificationAuditSafeArray(awarenessModel?.activeAwarenessSamples).map((row, index) => ({
      key: `awareness:${row.sourceKind || "unknown"}:${row.sourceIndex ?? index}`,
      id: null,
      type: row.resolvedCategory || "",
      category: row.resolvedCategory || "",
      reportKind: row.sourceKind || "",
      crossingId: null,
      crossing_id: null,
      title: "",
      headline: awarenessModel?.headline || "",
      summary: row.reusedAlertText || row.resolvedLocationLabel || "",
      sourcePath: "awarenessCandidates.activeAwarenessSamples",
      classifiedAsRoadHazard: row.sourceKind === "activeHazard" && !gridlyIsClearedHazardAwarenessRecord(row.item || row),
      classifiedAsCrossingCondition: /rail|train|crossing|blocked/i.test([row.resolvedCategory, row.reusedAlertText, row.resolvedLocationLabel].filter(Boolean).join(" "))
    }));
    const roadHazardCandidates = allCandidates.concat(awarenessCandidates).filter((candidate) => candidate.classifiedAsRoadHazard);
    const crossingCandidates = allCandidates.concat(awarenessCandidates).filter((candidate) => candidate.classifiedAsCrossingCondition);
    const roadKeys = new Set(roadHazardCandidates.map((candidate) => candidate.key));
    const overlappingCandidateKeys = crossingCandidates.map((candidate) => candidate.key).filter((key) => roadKeys.has(key));
    const roadHazardCandidatesAfterDuplicateSuppression = roadHazardCandidates.filter((candidate) => !duplicateActiveHazardKeySet.has(String(candidate.key || "").toLowerCase()));
    const roadKeysAfterDuplicateSuppression = new Set(roadHazardCandidatesAfterDuplicateSuppression.map((candidate) => candidate.key));
    const overlappingCandidateKeysAfterSuppression = crossingCandidates.map((candidate) => candidate.key).filter((key) => roadKeysAfterDuplicateSuppression.has(key));
    // V631 baseline before V634 suppression: const crossingCountedAsRoadHazard = overlappingCandidateKeys.length > 0;
    const crossingCountedAsRoadHazard = overlappingCandidateKeysAfterSuppression.length > 0;
    const selectedRawDetail = awarenessModel?.topAwarenessSelectedRawDetail || null;
    const selectedRawSummary = selectedRawDetail ? {
      sourceKind: selectedRawDetail.sourceKind || "activeItem",
      sourceIndex: Number(selectedRawDetail.sourceIndex || 0),
      resolvedCategory: selectedRawDetail.resolvedCategory || "unknown",
      rawCategoryValue: selectedRawDetail.rawCategoryValue || "",
      resolvedLocationLabel: safeDisplayText(selectedRawDetail.resolvedLocationLabel, ""),
      categorySource: selectedRawDetail.categorySource || "none",
      lightweightLocationSourceField: selectedRawDetail.lightweightLocationSourceField || "",
      reusedAlertText: safeDisplayText(selectedRawDetail.reusedAlertText, ""),
      lifecycleStage: selectedRawDetail.lifecycleClassification?.lifecycleStage || getGridlyTopAwarenessLifecycleStage(selectedRawDetail),
      isCleared: gridlyIsClearedHazardAwarenessRecord(selectedRawDetail.item || selectedRawDetail),
      isCrossing: gridlyAwarenessClassificationAuditIsCrossing(selectedRawDetail.item || selectedRawDetail)
    } : null;
    const activeReportAwarenessCandidates = awarenessCandidates.filter((candidate) => candidate.reportKind === "activeReport");
    const clearedAwarenessCandidates = gridlyAwarenessClassificationAuditSafeArray(awarenessModel?.activeAwarenessSamples).filter((row) => gridlyIsClearedHazardAwarenessRecord(row.item || row));
    const unknownActiveReportFallbackDetected = Boolean(selectedRawSummary
      && selectedRawSummary.sourceKind === "activeReport"
      && selectedRawSummary.resolvedCategory === "unknown"
      && /^Road Hazard on /i.test(String(awarenessModel?.headline || "")));
    return {
      available: true,
      activeRoadHazardCount: roadHazardCandidatesAfterDuplicateSuppression.length,
      activeRoadHazardCountBeforeDuplicateSuppression: roadHazardCandidates.length,
      activeRoadHazardCountAfterDuplicateSuppression: roadHazardCandidatesAfterDuplicateSuppression.length,
      activeCrossingConditionCount: crossingCandidates.length,
      activeAlertCount: sourceAlerts.length,
      roadHazardCandidates,
      crossingCandidates,
      alertCandidates: sourceAlerts.map((row, index) => gridlyAwarenessClassificationAuditCandidate(row, "alertCandidates", index)),
      awarenessCandidates,
      activeReportAwarenessCandidates,
      clearedAwarenessCandidates,
      duplicateActiveHazardKeys: duplicateSuppressionAudit.duplicateActiveHazardKeys || [],
      clearedDuplicateSuppressedCount: duplicateSuppressionAudit.clearedDuplicateSuppressedCount || 0,
      duplicateSuppressionReason: duplicateSuppressionAudit.duplicateSuppressionReason || "",
      unknownActiveReportFallbackDetected,
      selectedTopAwarenessRawDetail: selectedRawSummary,
      selectedTopAwarenessReason: awarenessModel?.topAwarenessSelectionReason || awarenessModel?.topAwarenessSelectionEligibilityReason || "",
      selectedTopAwarenessRejectedReasons: Array.isArray(awarenessModel?.topAwarenessRejectedReasons) ? awarenessModel.topAwarenessRejectedReasons : [],
      selectedTopAwarenessType: awarenessModel?.activeAwarenessSelectedIncidentType || awarenessModel?.resolvedCategory || null,
      selectedTopAwarenessSource: awarenessModel?.topAwarenessHeadlineSource || awarenessModel?.topAwarenessSelectionTruthSource || null,
      selectedTopAwarenessDetail: awarenessModel ? {
        headline: awarenessModel.headline || "",
        sourceKind: awarenessModel.activeAwarenessSamples?.[0]?.sourceKind || "",
        resolvedCategory: awarenessModel.resolvedCategory || "",
        source: awarenessModel.topAwarenessHeadlineSource || ""
      } : null,
      crossingCountedAsRoadHazard,
      overlappingCandidateKeys: Array.from(new Set(overlappingCandidateKeys)),
      overlappingCandidateKeysAfterSuppression: Array.from(new Set(overlappingCandidateKeysAfterSuppression)),
      safeForAwarenessClassification: !crossingCountedAsRoadHazard && !unknownActiveReportFallbackDetected
    };
  } finally {
    if (gridlyAwarenessClassificationAuditStateSnapshot.gridlyAlertAreaFilterState !== undefined) {
      gridlyAlertAreaFilterState = gridlyAwarenessClassificationAuditStateSnapshot.gridlyAlertAreaFilterState;
    }
  }
}

function suppressGridlyLowQualityCrossingLocationInCopy(value = "") {
  const text = safeDisplayText(value, "");
  if (!text) return "";
  const stripped = text
    .replace(/\s+\b(?:on|near|at)\s+(?:Private|Unknown|unnamed road|Local crossing impact|St\s+0{3,}|Street\s+0{3,})\b/gi, "")
    .replace(/\s+/g, " ")
    .trim();
  if (!stripped || (typeof isGridlyLowQualityCrossingLocationToken === "function" && isGridlyLowQualityCrossingLocationToken(stripped))) return "";
  return stripped;
}

function gridlyCrossingAwarenessPromotionAudit(options = {}) {
  const classification = gridlyBuildAwarenessClassificationAudit(options);
  const awarenessModel = typeof buildGridlyLightweightActiveAwareness === "function"
    ? buildGridlyLightweightActiveAwareness({
        activeHazards: Array.isArray(options?.activeHazards) ? options.activeHazards : undefined,
        activeReports: Array.isArray(options?.activeReports) ? options.activeReports : undefined,
        alerts: Array.isArray(options?.alerts) ? options.alerts : undefined,
        lifecycleAuditReadOnly: true
      })
    : null;
  const summary = typeof getGridlyMobileAwarenessPanelSummary === "function" ? getGridlyMobileAwarenessPanelSummary({ allowBuild: true, summaryOptions: options }) : {};
  const bottomPanelText = safeDisplayText(summary?.crossingsLine || (typeof document !== "undefined" ? document.getElementById?.("mobileAwarenessPanelCrossings")?.textContent : ""), "");
  const crossingCandidates = classification.crossingCandidates || [];
  const crossingNamingSample = crossingCandidates.map((candidate) => suppressGridlyLowQualityCrossingLocationInCopy(candidate.headline || candidate.title || candidate.summary || candidate.crossingId || "")).filter(Boolean).slice(0, 5);
  const selectedType = awarenessModel?.activeAwarenessSelectedIncidentType || awarenessModel?.resolvedCategory || classification.selectedTopAwarenessType || "";
  const selectedHeadline = suppressGridlyLowQualityCrossingLocationInCopy(awarenessModel?.headline || classification.selectedTopAwarenessDetail?.headline || "");
  const visibleCrossingCopyForQualityAudit = [
    ...crossingNamingSample,
    bottomPanelText,
    selectedHeadline
  ].filter(Boolean);
  const invalidCrossingRoadNameDetected = visibleCrossingCopyForQualityAudit.some((value) => typeof isGridlyLowQualityCrossingLocationToken === "function" && isGridlyLowQualityCrossingLocationToken(value))
    || /\b(?:on|near|at)\s+(?:Private|Unknown|unnamed road|Local crossing impact|St\s+0{3,}|Street\s+0{3,})\b/i.test(visibleCrossingCopyForQualityAudit.join(" "));
  const topAwarenessPromotesCrossing = /train blocking crossing|crossing blocked|rail/i.test(`${selectedType} ${selectedHeadline}`);
  const cacheValues = Array.from(gridlyRoadNameLookupCache?.formatterValues?.values?.() || []).slice(0, 5);
  return {
    activeCrossingConditionCount: Number(classification.activeCrossingConditionCount || 0),
    crossingAlertCandidates: classification.alertCandidates?.filter((candidate) => candidate.classifiedAsCrossingCondition) || [],
    crossingAwarenessCandidates: classification.awarenessCandidates?.filter((candidate) => candidate.classifiedAsCrossingCondition) || [],
    selectedTopAwarenessType: selectedType,
    selectedTopAwarenessSource: awarenessModel?.topAwarenessHeadlineSource || classification.selectedTopAwarenessSource || "",
    crossingRejectedReasons: (classification.selectedTopAwarenessRejectedReasons || []).filter((entry) => /crossing|rail/i.test(`${entry.reason} ${entry.resolvedCategory}`)),
    topAwarenessPromotesCrossing,
    bottomPanelText,
    bottomHazardCountSource: summary?.bottomHazardCountSource || "",
    bottomHazardCount: Number(summary?.bottomHazardCount || 0),
    classificationActiveRoadHazardCount: Number(classification.activeRoadHazardCount || 0),
    bottomCountMatchesClassification: Number(summary?.bottomHazardCount || 0) === Number(classification.activeRoadHazardCount || 0),
    crossingCountedAsHazard: Boolean(classification.crossingCountedAsRoadHazard),
    crossingNamingSample,
    invalidCrossingRoadNameDetected,
    roadNameLookupCacheActive: Boolean(gridlyCommuteIntelligenceAuditState.roadNameLookupCacheActive || gridlyRoadNameLookupCache?.formatterValues),
    roadNameLookupCacheHits: Number(gridlyCommuteIntelligenceAuditState.roadNameLookupCacheHits || gridlyRoadNameLookupCache?.formatterHits || 0),
    roadNameLookupCacheMisses: Number(gridlyCommuteIntelligenceAuditState.roadNameLookupCacheMisses || gridlyRoadNameLookupCache?.formatterMisses || 0),
    roadNameLookupCachedKeys: [...(gridlyCommuteIntelligenceAuditState.roadNameLookupCachedKeys || [])],
    roadNameLookupCachedValueSamples: cacheValues,
    lastSubmittedCrossingReportCounty: gridlyReportSubmissionOwnershipState.lastSubmittedCrossingReportCounty,
    lastSubmittedCrossingReportTown: gridlyReportSubmissionOwnershipState.lastSubmittedCrossingReportTown,
    lastSubmittedCrossingReportCrossingId: gridlyReportSubmissionOwnershipState.lastSubmittedCrossingReportCrossingId,
    lastSubmittedCrossingReportCoordinates: gridlyReportSubmissionOwnershipState.lastSubmittedCrossingReportCoordinates,
    postSaveRefreshTriggered: Boolean(gridlyReportSubmissionOwnershipState.postSaveRefreshTriggered),
    crossingReportVisibleAfterSave: Boolean(gridlyReportSubmissionOwnershipState.crossingReportVisibleAfterSave),
    crossingReportPromotedAfterSave: Boolean(gridlyReportSubmissionOwnershipState.crossingReportPromotedAfterSave),
    crossingReportAreaFilterPass: Boolean(classification.crossingCandidates?.length ? (gridlyCrossingAreaFilterState?.filteredOutRecords || []).length === 0 : gridlyReportSubmissionOwnershipState.crossingReportAreaFilterPass),
    crossingReportRenderCandidateCount: crossingCandidates.length,
    refreshedCrossingReportCandidateCount: Number(gridlyReportSubmissionOwnershipState.refreshedCrossingReportCandidateCount || 0),
    refreshedCrossingReportVisible: Boolean(gridlyReportSubmissionOwnershipState.refreshedCrossingReportVisible),
    refreshedCrossingReportCountyPass: Boolean(gridlyReportSubmissionOwnershipState.refreshedCrossingReportCountyPass),
    refreshedCrossingReportLifecyclePass: Boolean(gridlyReportSubmissionOwnershipState.refreshedCrossingReportLifecyclePass),
    refreshedCrossingReportAreaPass: Boolean(gridlyReportSubmissionOwnershipState.refreshedCrossingReportAreaPass),
    safeForCrossingAwarenessPromotion: Boolean(topAwarenessPromotesCrossing && !classification.crossingCountedAsRoadHazard && !invalidCrossingRoadNameDetected)
  };
}
